import { ICommandContext } from '@vs/vscode-command-framework';
import { CommunicationsManager } from '../CommunicationsManager';
import { TelemetryEventNames, ICommand, telemetryCommandDecorator } from '@vs/liveshare-core';

export function StartOrJoinCallCommandBuilder(): ICommand<void> {
    return new StartOrJoinCallCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.START_OR_JOIN_AUDIO, TelemetryEventNames.START_OR_JOIN_AUDIO_FAULT, 'StartOrJoinCall', 1)
class StartOrJoinCallCommand implements ICommand<void> {
    public async invoke(item: any, context: ICommandContext): Promise<void> {
        const callingServiceManager = CommunicationsManager.callingServiceManager;
        return await callingServiceManager?.commandStartOrJoinCall();
    }
}