import * as vscode from 'vscode';

import { PathManager } from '../PathManager';

export interface IRootFileSystemInfo {
    foundUnsupportedSchemes: boolean;
    isVirtualWorkspace: boolean;
    paths: string[];
}

export function getAllRootFileSystemPaths(): IRootFileSystemInfo {
    if (vscode.workspace.workspaceFolders == null || vscode.workspace.workspaceFolders.length === 0) {
        return {
            foundUnsupportedSchemes: false,
            isVirtualWorkspace: true,
            paths: [null],
        };
    }

    const fileSchemeWorkspaceFolders = vscode.workspace.workspaceFolders.filter(wf => wf.uri.scheme.toLowerCase() === PathManager.fileScheme);
    const containsFileSchemes = fileSchemeWorkspaceFolders.length > 0;
    const containsNonFileSchemes = fileSchemeWorkspaceFolders.length !== vscode.workspace.workspaceFolders.length;

    if (!containsFileSchemes) {
        return {
            foundUnsupportedSchemes: false,
            isVirtualWorkspace: true,
            paths: vscode.workspace.workspaceFolders.map(wf => wf.uri.path)
        };
    }

    return {
        foundUnsupportedSchemes: containsNonFileSchemes,
        isVirtualWorkspace: false,
        paths: fileSchemeWorkspaceFolders.map(wf => wf.uri.fsPath)
    };
}