export class EnumUtil {

    /**
     * Given a enum value the method tries to fetch corresponding enum key
     */
    public static getEnumKeyByEnumValue(myEnum: any, enumValue: number | string): string {
        return Object.keys(myEnum).find(x => myEnum[x] == enumValue);
    }
}