import { vsls } from '@vs/vsls-contracts';
import { LogLevel } from '@vs/vso-logging';
import { UserError } from '../abstractions/UserError';
import { CancellationError } from "@vs/vscs-utils";
import { IndeterminateError } from '../abstractions/IndeterminateError';
import { NonBlockingError } from '../abstractions/NonBlockingError';

import {
    FaultType,
    TelemetryResult
} from '@vs/vso-telemetry';
/**
 * Helper functions for sending telemetry events.
 */
export class TelemetryUtil {
    public static DeriveTelemetryResultFromErrorCode(error: any): TelemetryResult | void {
        switch (error.code) {
            case vsls.ErrorCodes.CollaborationSessionGuestRejected:
            case vsls.ErrorCodes.ForbiddenHttpStatusCode:
            case vsls.ErrorCodes.CollaborationSessionGuestCanceled:
            case vsls.ErrorCodes.CollaborationSessionRequestTimedOut:
            case vsls.ErrorCodes.CollaborationSessionNotFound:
            case vsls.ErrorCodes.CollaborationSessionUsersLimitReached:   
            case vsls.ErrorCodes.RelayConnectionHostFailure: 
                return TelemetryResult.UserFailure;

            default: {}
        }
    }

    public static DeriveTelemetryResultFromErrorType(error: any): TelemetryResult | void {
        if (error instanceof UserError) {
            return TelemetryResult.UserFailure;
        }
        if (error instanceof CancellationError) {
            return TelemetryResult.Cancel;
        }
        if (error instanceof IndeterminateError) {
            return TelemetryResult.IndeterminateFailure;
        }
        if (error instanceof NonBlockingError) {
            return TelemetryResult.NonBlockingFailure;
        }
    }

    public static DeriveTelemetryResult(error: Error): TelemetryResult {
        const resultByCode = TelemetryUtil.DeriveTelemetryResultFromErrorCode(error);
        if (typeof resultByCode !== 'undefined') {
            return resultByCode;
        }

        const resultByType = TelemetryUtil.DeriveTelemetryResultFromErrorType(error);
        if (typeof resultByType !== 'undefined') {
            return resultByType;
        }
        
        return TelemetryResult.Failure;
    }

    public static DeriveTelemetryTitle(command: string, result: TelemetryResult): string {
        // TODO: Could auto convert enum to friendly string.
        let category = 'Success';
        if (result === TelemetryResult.UserFailure) {
            category = 'User Failure';
        } else if (result === TelemetryResult.Cancel) {
            category = 'Cancelled';
        } else if (result === TelemetryResult.IndeterminateFailure) {
            category = 'Indeterminate Failure';
        } else if (result === TelemetryResult.Failure) {
            category = 'Failure';
        } else if (result === TelemetryResult.NonBlockingFailure) {
            category = 'Non Blocking Failure';
        }

        return `${command} ${category}`;
    }

    public static BuildTelemetryMessage(command: string, result: TelemetryResult, error?: string) {
        let errorPostfix = '';
        if (error !== undefined) {
            errorPostfix = `: ${error}`;
        }

        return `${this.DeriveTelemetryTitle(command, result)}${errorPostfix}`;
    }

    public static MapTelemetryResultToFaultType(result: TelemetryResult): FaultType {
        // TODO: Can we unify on one enum type.
        switch (result) {
            case TelemetryResult.UserFailure:
                return FaultType.User;
            case TelemetryResult.Cancel:
                return FaultType.UserCancelled;
            case TelemetryResult.Failure:
                return FaultType.Error;
            case TelemetryResult.NonBlockingFailure:
                return FaultType.NonBlockingFault;

            case TelemetryResult.IndeterminateFailure:
            default:
                return FaultType.Unknown;
        }
    }

    public static MapTelemetryResultToTraceEventType(result: TelemetryResult): LogLevel {
        return result === TelemetryResult.Success ? LogLevel.Info : LogLevel.Error;
    }
}