import * as vscode from 'vscode';

import { SessionAction, SessionState, SessionStateChangedEventArgs, SessionStatusChangedEventArgs } from './SessionTypes';
import { ISessionStateTracker } from './ISessionStateTracker';
import { sessionMachine } from './StateMachine';
import { ExtensionTelemetry } from './telemetry/ExtensionTelemetry';

class SessionStateTracker implements ISessionStateTracker {

    private readonly stateChangedEmitter = new vscode.EventEmitter<SessionStateChangedEventArgs>();
    public readonly onStateChanged = this.stateChangedEmitter.event;
    private readonly statusChangedEmitter = new vscode.EventEmitter<SessionStatusChangedEventArgs>();
    public readonly onStatusChanged = this.statusChangedEmitter.event;

    private currentState: SessionState = SessionState.Initializing; // initial state
    private currentHigherState: SessionState | undefined = undefined;
    private currentAction: SessionAction | undefined; // initial action
    private currentStatus: string | undefined; // initial state

    public get State(): SessionState {
        return this.currentState;
    }
    
    public get HigherState(): SessionState | undefined {
        return this.currentHigherState;
    }

    private transitionHigherState(nextState: SessionState, action: SessionAction) {
        if (nextState === SessionState.SharingInProgress 
            || nextState === SessionState.JoiningInProgress
            || nextState === SessionState.Shared 
            || nextState === SessionState.Joined) {
            this.currentHigherState = nextState;
        } else if (action === SessionAction.SharingError
            || action === SessionAction.JoiningError
            || action === SessionAction.EndSharing
            || action === SessionAction.Unjoin) {
            this.currentHigherState = undefined;
        }
    }

    public transition(action: SessionAction): SessionState | undefined {
        const currentStateConfig = sessionMachine[this.State];

        if (currentStateConfig) {
            let nextState = currentStateConfig[action];
            if (nextState !== undefined) {
                // Deal with next state being derived
                if (typeof nextState === 'function') {
                    nextState = nextState();
                }

                // Derive higher state
                this.transitionHigherState(nextState, action);

                // Record & send transition telemetry
                this.sendTransitionTelemetry(nextState, action);

                // Transition to the determined next state
                this.setState(nextState, action);

                return this.State;
            }

            // No transition exists for the given action
            return undefined;
        }

        // No config for the given state exists in the machine
        return undefined;
    }

    private sendTransitionTelemetry(nextState: SessionState, fromAction: SessionAction): void {
        ExtensionTelemetry.sendTransition(SessionState[this.State], SessionState[nextState], SessionAction[fromAction]);
    }

    public setState(newState: SessionState, actionTrigger: SessionAction) {
        const oldState = this.currentState;
        const oldAction = this.currentAction;

        this.currentState = newState;
        this.currentAction = actionTrigger;

        this.stateChangedEmitter.fire({ newState, oldState, newAction: actionTrigger, oldAction });
    }

    private setStatus(newStatus: string) {
        const oldStatus = this.currentStatus;
        this.currentStatus = newStatus;

        this.statusChangedEmitter.fire({ newStatus, oldStatus });
    }

    public point(action: string): void {
        if (action !== undefined) {
            this.setStatus(action);
        }
    }
}

export let sessionStateTracker = new SessionStateTracker();

// Used by unit tests.
export function setSessionStateTracker(tracker: SessionStateTracker) {
    sessionStateTracker = tracker;
}
