'use strict';

import * as vscode from 'vscode';

import {
    getNotebookCellData,
    IPathManager,
    ICoEditing,
    getCellId,
    sortCells,
    getNotebookHash,
    assert
} from '@vs/liveshare-core';
import { GuestCellChanges, OnDidChangeNotebookCellsArg } from './notebooksService';
import { CellManager } from './cellManager';

type HostNotebookCellData = vscode.NotebookCellData & { index: number };
type UnacknowledgedChanges = { deletes: string[], adds: string[] };

export class GuestCellManager extends CellManager {

    private hostNotebook: HostNotebookCellData[] = [];
    private unacknowledgedChanges: UnacknowledgedChanges = { deletes: [], adds: [] };

    constructor(notebookDocument: vscode.NotebookDocument, private readonly pathManager: IPathManager, private readonly coediting: ICoEditing) {
        super(notebookDocument);
        this.hostNotebook = notebookDocument.getCells().map(cell => ({ ...getNotebookCellData(cell), index: cell.index }));
        // hostNotebook is to remain sorted at all times - on creation, and after any update - add, delete, or move
        sortCells(this.hostNotebook);
        notebookDocument.getCells().forEach(cell => this.createFileClient(cell));
    }

    private createFileClient(cell: vscode.NotebookCell) {
        const fileName = this.pathManager.localPathToRelativePath(cell.document.uri);
        this.coediting.createSharedFileClient(fileName, cell.document.getText(), false);
    }

    public async onDidChangeNotebookCells(changeEvent: vscode.NotebookCellsChangeEvent): Promise<GuestCellChanges[]> {
        const changes = [];
        for (let change of changeEvent.changes) {
            const deletes = change.deletedItems.filter(cell => !this.isRemoteChange(cell)).map(cell => getCellId(cell));
            this.unacknowledgedChanges.deletes.push(...deletes);

            const adds = [];
            for (let cell of change.items) {
                if (!this.isRemoteChange(cell)) {
                    await this.addIdToCell(cell);
                    adds.push(getNotebookCellData(cell));
                    this.unacknowledgedChanges.adds.push(getCellId(cell));
                }
                this.createFileClient(cell);
            }

            if (deletes.length !== 0 || adds.length !== 0) {
                changes.push({
                    deletes,
                    adds: adds.length === 0
                            ? undefined
                            : {
                                insertAbove: change.start === 0 ? undefined : getCellId(changeEvent.document.getCells().find(c => c.index === (change.start - 1))),
                                cells: adds
                            }
                });
            }
        }
        return changes;
    }

    private deleteHostCell(id: string) {
        const idx = this.hostNotebook.findIndex(cell => getCellId(cell) === id);
        this.hostNotebook.splice(idx, 1);
        for (let i = idx; i < this.hostNotebook.length; i++) {
            this.hostNotebook[i].index--;
        }

        const unackedIdx = this.unacknowledgedChanges.deletes.findIndex(unackedId => unackedId === id);
        if (unackedIdx >= 0) {
            this.unacknowledgedChanges.deletes.splice(unackedIdx, 1);
        }
    }

    private addHostCell(index: number, cell: vscode.NotebookCellData) {
        this.hostNotebook.splice(index, 0, { ...cell, index });
        for (let i = index + 1; i < this.hostNotebook.length; i++) {
            this.hostNotebook[i].index++;
        }

        const id = getCellId(cell);
        const unackedIdx = this.unacknowledgedChanges.adds.findIndex(unackedId => unackedId === id);
        if (unackedIdx >= 0) {
            this.unacknowledgedChanges.adds.splice(unackedIdx, 1);
        }
    }

    public async onHostDidChangeNotebookCells(notebookCellsChange: OnDidChangeNotebookCellsArg) {
        for (let change of notebookCellsChange.changes) {
            for (let id of change.deletes) {
                this.deleteHostCell(id);
            }
            
            if (change.adds) {
                for (let i = 0; i < change.adds.cells.length; i++) {
                    this.addHostCell(change.adds.idx + i, change.adds.cells[i]);
                }
            }
        }

        const localContentHash = getNotebookHash(this.hostNotebook);
        assert(localContentHash === notebookCellsChange.contentHash, 'Guest representation of host notebook should match host notebook');

        if (this.unacknowledgedChanges.deletes.length === 0 && this.unacknowledgedChanges.adds.length === 0) {
            await this.sync();
        }
    }

    private async sync() {
        const guestCells = [];
        for (let guestCell of this.notebookDocument.getCells()) {
            const id = getCellId(guestCell);
            const hostCell = this.hostNotebook.find(hostCell => getCellId(hostCell) === id);
            if (hostCell) {
                guestCells.push(guestCell);
            } else {
                await this.deleteCell(guestCell);
            }
        }
        sortCells(guestCells);

        for (let guestIdx = 0, hostIdx = 0; hostIdx < this.hostNotebook.length; guestIdx++, hostIdx++) {
            const guestCell = guestIdx < guestCells.length ? guestCells[guestIdx] : undefined;
            const hostCell = this.hostNotebook[hostIdx];

            if (!guestCell) {
                await this.addCells(hostCell.index, [hostCell]);
                continue;
            }

            if (getCellId(guestCell) !== getCellId(hostCell)) {
                const movedCell = guestCells.find(c => getCellId(c) === getCellId(hostCell));
                if (movedCell) {
                    await this.moveCell(movedCell, hostCell.index);
                    guestCells.splice(guestCells.indexOf(movedCell), 1);
                    guestIdx--;
                } else {
                    await this.addCells(hostCell.index, [hostCell]);
                    guestIdx--;
                }
            }
        }

        this.checkSync();
    }

    private checkSync() {
        const cells = [...this.notebookDocument.getCells()];
        sortCells(cells);
        const localNotebookContents = getNotebookHash(cells);
        const hostNotebookContents = getNotebookHash(this.hostNotebook);
        assert(localNotebookContents === hostNotebookContents, 'Guest notebook should match host notebook after sync');
    }

}
