import * as vscode from 'vscode';

import { Signal } from '@vs/vscs-utils';
import * as cp from 'child_process';
import { ContactManager } from '../ContactManager';
import { ContactServiceManager } from '../ContactServiceManager';

import { 
    getExpService,
    SessionState, 
    SessionAction,
    sessionStateTracker,
    workspaceSessionInfoTracker,
    IContactModel
} from '@vs/liveshare-core';

export class ContactCommandUtilities {

    private static  ensureWorkspaceSharedInProgress = Promise.resolve();

    public static async inviteHelper(inviteContact: IContactModel): Promise<boolean> {
        
        const currentLink = await ContactCommandUtilities.getCurrentLink(inviteContact.contact.email);
        if (currentLink) {
            const serviceManager = ContactManager.getServiceManager(inviteContact.serviceId);
            if (!serviceManager || !serviceManager.capabilites.supportsInviteLink || ContactServiceManager.isOffline(inviteContact)) {
                await ContactCommandUtilities.inviteByEmailInternal(inviteContact.contact.email, inviteContact.contact.displayName, currentLink);
            } else {               
                await serviceManager.sendInviteLink(inviteContact.contact.id, currentLink);
                ContactManager.addInviteContact(inviteContact);
            }

            return true;
        }
        return false;
    }

    public static async inviteByEmail(email: string, name: string): Promise<boolean> {
        const currentLink = await ContactCommandUtilities.getCurrentLink(email);
        if (currentLink) {
            await ContactCommandUtilities.inviteByEmailInternal(email, name, currentLink);
            return true;
        }

        return false;
    }

    private static async getCurrentLink(email: string): Promise<string> {
        
        const joinState =
            sessionStateTracker.State === SessionState.JoiningInProgress ||
            sessionStateTracker.State === SessionState.Joined;
        
        if (!joinState) {
            await ContactCommandUtilities.ensureWorkspaceShared();

            const expService = getExpService();

            if (expService && await expService.isCachedFlightEnabled('invitationLink')) {

                return await vscode.commands.executeCommand<string>(
                    'liveshare.createInvitationLink', {
                        workspaceId: workspaceSessionInfoTracker.workspaceSessionInfo.id,
                        guestUsers: [email]
                    });
            }
        }

        if (joinState || sessionStateTracker.State === SessionState.Shared) {          
            return workspaceSessionInfoTracker.workspaceSessionInfo.joinUri;
        }

        return null;
    }

    private static async ensureWorkspaceSharedInternal(): Promise<void> {
        const state = sessionStateTracker.State;
        if (state === SessionState.SharingInProgress) {
            const sharedSignal = new Signal<void>();
            sessionStateTracker.onStateChanged((e) => {
                if (e.newAction === SessionAction.SharingError) {
                    sharedSignal.cancel();
                } else if (e.newAction === SessionAction.SharingSuccess) {
                    sharedSignal.resolve();
                }
            });
            await sharedSignal.promise;
        } else if (state !== SessionState.Shared) {
            const command = 'liveshare.start';
            await vscode.commands.executeCommand<vscode.Uri>(command, /* ShareOptions */ {
                suppressNotification: true
            });
        }
    }

    private static async ensureWorkspaceShared(): Promise<void> {
        await ContactCommandUtilities.ensureWorkspaceSharedInProgress;
        ContactCommandUtilities.ensureWorkspaceSharedInProgress  = ContactCommandUtilities.ensureWorkspaceSharedInternal();
        await ContactCommandUtilities.ensureWorkspaceSharedInProgress;
    }

    private static async inviteByEmailInternal(email: string, name: string, liveShareLink: string): Promise<void> {
        const subject = 'Join my Visual Studio Live Share session';
        const expService = getExpService();
        let mailContent = encodeURIComponent(`${liveShareLink}`);
        
        if (expService && await expService.isCachedFlightEnabled('invitationLink')) {
            mailContent = encodeURIComponent(`This Live Share session link is only accessible by ${name} (${email}) : ${liveShareLink}`);        
        }
        const encodedSubject = encodeURIComponent(subject);

        if (process.platform === 'win32') {
            const uri = `mailto:${email}?subject=${encodedSubject}^&body=${mailContent}`;
            cp.exec(`start ${uri}`);
        } else if (process.platform === 'darwin') {
            const uri = `mailto:${email}?subject=${encodedSubject}&body=${decodeURIComponent(mailContent)}`;
            cp.exec(`open '${uri}'`);
        } else {
            const uri = `mailto:${email}?subject=${encodedSubject}&body=${mailContent}`;
            vscode.commands.executeCommand('vscode.open', vscode.Uri.parse(uri));
        }
    }              
}