import { TraceSource, TraceFormat } from '@vs/vso-logging';
import { vsls } from '@vs/vsls-contracts';
import { MessageFactory } from './coauthoringService';
import { assert } from './coeditingUtils';

export interface ITransformManagerHost {
    /**
     * The trace to output to the logs.
     */
    readonly trace: TraceSource;
    /**
     * The file name.
     */
    readonly fileName: string;
}

export class TransformManager {
    private host: ITransformManagerHost;
    private serverVersionHistory: ServerVersion[] = new Array<ServerVersion>();

    public constructor(host: ITransformManagerHost) {
        this.host = host;
        this.serverVersionHistory.push(new ServerVersion(-1, null));
    }

    public AddToServersionHistory(serverVersion: number, message: vsls.TextChangeMessage, translatedMessage?: vsls.TextChangeMessage): void {
        let history: ServerVersion = new ServerVersion(serverVersion, message);
        if (translatedMessage && (message.changeServerVersion !== translatedMessage.changeServerVersion)) {
            history.AddMessage(translatedMessage);
        }

        this.serverVersionHistory.push(history);
    }

    public RemoveUnacknowledgedChangesFromServerVersionHistory(numberOfUnacknowledgedChanges: number): void {
        this.serverVersionHistory.splice(this.serverVersionHistory.length - numberOfUnacknowledgedChanges, numberOfUnacknowledgedChanges);
    }

    public RollbackTo(serverVersionNumber: number): void {
        for (let n: number = this.serverVersionHistory.length - 1; (n >= 0); --n) {
            if (this.serverVersionHistory[n].serverVersionNumber === serverVersionNumber) {
                this.serverVersionHistory.splice(n + 1);
                return;
            }
        }

        assert(false, 'Failed to find version number to remove');
    }

    public get CurrentServerVersionNumber(): number {
        return this.serverVersionHistory[this.serverVersionHistory.length - 1].serverVersionNumber;
    }

    public get CurrentHistory(): ServerVersion[] {
        return this.serverVersionHistory.map((serverVersion) => serverVersion.clone());
    }

    public setInitialHistory(serverVersions: ServerVersion[]): void {
        const newVersion = serverVersions[serverVersions.length - 1].serverVersionNumber;
        if (this.serverVersionHistory.length === 1 && this.serverVersionHistory[0].serverVersionNumber === -1) {
            this.serverVersionHistory = serverVersions;
            this.host.trace.info(`Setting initial history for ${TraceFormat.formatPath(this.host.fileName)} (server version: ${newVersion})`);
        } else {
            this.host.trace.warning(`Attempted to overwrite history for ${TraceFormat.formatPath(this.host.fileName)} with ${newVersion} (current: ${this.CurrentServerVersionNumber})`);
        }
    }

    public TransformMessageToCurrent(message: vsls.TextChangeMessage): vsls.TextChangeMessage {
        return this.TransformMessageToVersionWithMessageIndex(message, this.CurrentServerVersionNumber, this.serverVersionHistory.length);
    }

    public static TrackForwardAcrossChange(position: number, changes: vsls.TextChange[]): number {
        return TransformManager.TrackForwardAcrossChangeWithAdjustment(position, new PositionAdjustment(), changes);
    }

    public static TrackForwardAcrossChangeWithAdjustment(position: number, adjustment: PositionAdjustment, changes: vsls.TextChange[]): number {

        let accumulatedDelta: number = 0;
        for (let i: number = 0; (i < changes.length); ++i) {
            let change: vsls.TextChange = changes[i];
            if (change.start === undefined || change.length === undefined) {
                continue;
            }

            const newText = change.newText || '';

            if ((change.start + change.length >= position) && (i >= adjustment.nextChangeIndex)) {
                if (change.start < position) {
                    position = change.start + newText.length;
                }

                break;
            }

            accumulatedDelta += newText.length - change.length;
        }

        position += accumulatedDelta + adjustment.offset;
        return position;
    }

    public static TrackBackwardAcrossChange(position: number, changes: vsls.TextChange[]): number {
        return TransformManager.TrackBackwardAcrossChangeWithAdjustment(position, new PositionAdjustment(), changes);
    }

    public static TrackBackwardAcrossChangeWithAdjustment(position: number, adjustment: PositionAdjustment, changes: vsls.TextChange[]): number {
        adjustment.offset = 0;
        adjustment.nextChangeIndex = -1;
        while (++adjustment.nextChangeIndex < changes.length) {
            let change: vsls.TextChange = changes[adjustment.nextChangeIndex];
            if (change.start === undefined || change.length === undefined) {
                continue;
            }

            const newText = change.newText || '';

            if (change.start + newText.length >= position) {
                if (change.start < position) {
                    adjustment.offset = (position - change.start);
                    position = change.start;
                }

                break;
            }

            position -= (newText.length - change.length);
        }

        return position;
    }

    private TransformMessageIndexToVersion(targetVersion: number, messageIndex: number): vsls.TextChangeMessage {
        let message: vsls.TextChangeMessage = this.serverVersionHistory[messageIndex].GetBestMessage(targetVersion);
        if (message.changeServerVersion === targetVersion) {
            return message;
        }

        let newMessage: vsls.TextChangeMessage = this.TransformMessageToVersionWithMessageIndex(message, targetVersion, messageIndex);
        this.serverVersionHistory[messageIndex].AddMessage(newMessage);

        return newMessage;
    }

    private TransformMessageToVersionWithMessageIndex(message: vsls.TextChangeMessage, targetVersion: number, messageIndex: number): vsls.TextChangeMessage {
        assert(message.changeServerVersion !== undefined && targetVersion >= message.changeServerVersion, `Can\'t translate messages to prior to their creation. Target: ${targetVersion}, Message: ${message.changeServerVersion}`);
        if (message.changeServerVersion !== undefined && targetVersion < message.changeServerVersion) {
            return message;
        }

        // Take messages, whose changes are defined on message.ChangeServerVersion and roll those changes forward to the specified targetVersion
        // (where int.MaxValue corresponds to latest).
        //
        // The first step is to find the server versions that are relevant to transforming this message.
        // Note we're only interested in server versions after the server version of the message (the message does not need to be transformed
        // with respect to that) and the message before the target version (we don't need to transform for that message either).
        let serverVersionLastIndex: number = this.serverVersionHistory.length - 1;
        for (let serverVersionIndex: number = serverVersionLastIndex; (serverVersionIndex >= 0); --serverVersionIndex) {
            let serverVersion: ServerVersion = this.serverVersionHistory[serverVersionIndex];
            if (serverVersion.serverVersionNumber === targetVersion) {
                serverVersionLastIndex = serverVersionIndex;
                break;
            }
        }

        let anyRemoteChanges: boolean = false;
        let serverVersionStartIndex: number = serverVersionLastIndex + 1;
        for (let serverVersionIndex: number = serverVersionLastIndex; (serverVersionIndex >= 0); --serverVersionIndex) {
            let serverVersion: ServerVersion = this.serverVersionHistory[serverVersionIndex];
            if (serverVersion.serverVersionNumber === message.changeServerVersion) {
                // We only need to account for changes made after we match up the version numbers.
                serverVersionStartIndex = serverVersionIndex + 1;
                break;
            }

            anyRemoteChanges = anyRemoteChanges ||
                (serverVersion.Message && serverVersion.Message.clientId !== message.clientId) || false;
        }

        if (serverVersionStartIndex > serverVersionLastIndex) {
            // No need to transform anything
            return message;
        } else if (!anyRemoteChanges) {
            // All of the changes we'd translate across are from the sender of the message so
            // the message is, effectively, already translated to the desired version.
            return MessageFactory.TextChangeMessage(message.clientId, message.fileName, message.fileVersion, targetVersion, message.changes);
        }

        // Make a copy of the changes in the message so that we don't corrupt the original message.
        let copyOfChanges: vsls.TextChange[] = [];
        for (let messageChange of (message.changes || [])) {
            copyOfChanges.push(MessageFactory.TextChange(messageChange.start, messageChange.length, messageChange.newText));
        }

        let spanAdjustments: SpanAdjustment[][] | null = null;

        // Look for changes made by the same client in the interesting parts of the server history
        // and roll this change back across those changes (preserving the information in spanOffsets to
        // restore the positions later)
        let maxServerVersionIndex: number = (messageIndex > serverVersionLastIndex)
            ? (messageIndex - 1)
            : serverVersionLastIndex;

        for (let serverVersionIndex: number = maxServerVersionIndex; (serverVersionIndex >= serverVersionStartIndex); --serverVersionIndex) {
            let serverVersion: ServerVersion = this.serverVersionHistory[serverVersionIndex];
            if (serverVersion.Message && serverVersion.Message.clientId === message.clientId) {
                if (spanAdjustments === null) {
                    spanAdjustments = [];
                    for (let i: number = 0; (i < this.serverVersionHistory.length); ++i) {
                        spanAdjustments.push([]);

                        for (let j: number = 0; (j < copyOfChanges.length); ++j)
                            spanAdjustments[i][j] = new SpanAdjustment();
                    }
                }

                if (message.changeServerVersion === undefined) {
                    throw new Error('Message is missing change server version.');
                }

                let transformedMessage: vsls.TextChangeMessage = this.TransformMessageIndexToVersion(message.changeServerVersion, serverVersionIndex);
                if (transformedMessage.changes) {
                    for (let changeIndex: number = 0; (changeIndex < copyOfChanges.length); ++changeIndex) {
                        let change: vsls.TextChange = copyOfChanges[changeIndex];
                        if (change.start === undefined || change.length === undefined) {
                            assert(false, 'Text change has undefined start or length.');
                            continue;
                        }

                        let start: number = TransformManager.TrackBackwardAcrossChangeWithAdjustment(
                            change.start,
                            spanAdjustments[serverVersionIndex][changeIndex].start,
                            transformedMessage.changes || []);
                        let end: number = TransformManager.TrackBackwardAcrossChangeWithAdjustment(
                            change.start + change.length,
                            spanAdjustments[serverVersionIndex][changeIndex].end,
                            transformedMessage.changes || []);

                        assert(start >= 0, 'start must be positive');
                        assert(end >= start, 'end must not come before start');

                        change.start = start;
                        change.length = end - start;
                    }
                }
            }
        }

        let currentVersion = message.changeServerVersion;
        for (let serverVersionIndex: number = serverVersionStartIndex; (serverVersionIndex <= maxServerVersionIndex); ++serverVersionIndex) {
            let serverVersion: ServerVersion = this.serverVersionHistory[serverVersionIndex];
            if (currentVersion !== undefined &&
                ((serverVersionIndex <= serverVersionLastIndex) || (serverVersion.Message && serverVersion.Message.clientId === message.clientId))
            ) {
                let transformedMessage: vsls.TextChangeMessage = this.TransformMessageIndexToVersion(currentVersion, serverVersionIndex);
                if (!transformedMessage.changes) {
                    continue;
                }

                for (let changeIndex: number = 0; (changeIndex < copyOfChanges.length); ++changeIndex) {
                    let change: vsls.TextChange = copyOfChanges[changeIndex];
                    if (change.start === undefined || change.length === undefined) {
                        assert(false, 'Text change has undefined start or length.');
                        continue;
                    }

                    // Translate the change from the server version it is on to the current state.
                    // Track each each change as a distinct change rather that simply translating from the server version to now
                    // since there may be extraneous changes between here (see the unacknowledgedChanges handling above and below)
                    // that could confuse things.
                    let start: number = change.start;
                    let end: number = change.start + change.length;

                    if (spanAdjustments === null) {
                        start = TransformManager.TrackForwardAcrossChange(start, transformedMessage.changes);
                        end = TransformManager.TrackForwardAcrossChange(end, transformedMessage.changes);
                    } else {
                        start = TransformManager.TrackForwardAcrossChangeWithAdjustment(start, spanAdjustments[serverVersionIndex][changeIndex].start, transformedMessage.changes);
                        end = TransformManager.TrackForwardAcrossChangeWithAdjustment(end, spanAdjustments[serverVersionIndex][changeIndex].end, transformedMessage.changes);
                    }

                    assert(start >= 0, 'start must be positive');
                    assert(end >= start, 'end must not come before start');

                    change.start = start;
                    change.length = end - start;
                }

                if (serverVersionIndex <= serverVersionLastIndex) {
                    currentVersion = serverVersion.serverVersionNumber;
                }
            }
        }

        let m: vsls.TextChangeMessage = MessageFactory.TextChangeMessage(message.clientId, message.fileName, undefined, currentVersion, copyOfChanges);

        return m;
    }
}

class SpanAdjustment {
    public start: PositionAdjustment = new PositionAdjustment();
    public end: PositionAdjustment = new PositionAdjustment();
}

class PositionAdjustment {
    public offset: number = 0;
    public nextChangeIndex: number = 0;
}

export class ServerVersion {
    private readonly messages: (vsls.TextChangeMessage | null)[];

    constructor(
        public readonly serverVersionNumber: number,
        message: (vsls.TextChangeMessage | null) | (vsls.TextChangeMessage | null)[]
    ) {
        if (Array.isArray(message)) {
            this.messages = message;
        } else {
            this.messages = [message];
        }
    }

    public get Message(): vsls.TextChangeMessage | null {
        return this.messages[0];
    }

    public clone(): ServerVersion {
        const clonedMessages = this.messages.map((msg) => {
            if (!msg) {
                // Version -1 always has a null message
                return msg;
            }
            return MessageFactory.CoauthoringMessage(msg) as vsls.TextChangeMessage;
        });
        const result = new ServerVersion(this.serverVersionNumber, clonedMessages);
        return result;
    }

    public GetBestMessage(changeServerVersion: number): vsls.TextChangeMessage {
        for (let i: number = this.messages.length - 1; (i >= 0); --i) {
            let message: vsls.TextChangeMessage | null = this.messages[i];
            if (message && message.changeServerVersion !== undefined &&
                message.changeServerVersion <= changeServerVersion
            ) {
                return message;
            }
        }

        // Avoid returning the first (null) message, because callers expect a message object.
        throw new Error('Invalid message server version.');
    }

    public AddMessage(message: vsls.TextChangeMessage): void {
        for (let i: number = this.messages.length - 1; (i >= 0); --i) {
            let existingMessage: vsls.TextChangeMessage | null = this.messages[i];
            if (existingMessage && message.changeServerVersion !== undefined && existingMessage.changeServerVersion !== undefined &&
                message.changeServerVersion >= existingMessage.changeServerVersion
            ) {
                assert(message.changeServerVersion !== existingMessage.changeServerVersion, 'Should never try to insert a message we have');
                assert(message.clientId === existingMessage.clientId, 'Client IDs should never change');
                this.messages.splice(i + 1, 0, message);

                return;
            }
        }

        assert(false, 'Never should try to insert a new version before index 0');
    }
}
