import * as path from 'path';
import * as uuid from 'uuid';
import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { PathUtil } from './utils/PathUtil';
import { assert } from './utils/assert';
import { SessionState } from './SessionTypes';
import { IPathManager } from './IPathManager';
import * as sessionStateTracker from './SessionStateTracker';
import { Settings } from './Settings';
import { NotebookConstants } from './contracts/NotebookConstants';
import { findNotebookCell, findNotebookCellById, getCellId } from './utils/notebookUtils';
import { Lazy } from './Lazy';

/** Provides converters from vscode Uri to LSP protocol paths and back.
 *  Also manages paths for documents external to the shared workspace.
 */
export class PathManager implements IPathManager {
    public static readonly outputScheme = 'output';
    public static readonly vslsExternalScheme: string = 'vslsexternal';
    public static readonly githubDevScheme = 'vscode-vfs';
    public static readonly fileScheme = 'file';
    public static readonly gitScheme = 'git';
    public static readonly vslsSccScheme = 'vsls-scc';
    public static readonly externalPrefix: string = '/~external';
    public static readonly untitledPrefix: string = '/~untitled';
    public static readonly gitPrefix: string = '/~git';
    public static readonly untitledScheme: string = 'untitled';
    public static readonly notebookCellScheme: string = 'vscode-notebook-cell';
    public static readonly notebookCellPrefix: string = '/~notebook';

    private localPathsToVslsPaths: Map<string, string> = new Map<string, string>(); // { "c:/users/Caitlin/webapp/banana" : "/~external/a1b2c3/banana" }
    private vslsPathsToLocalPaths: Map<string, string> = new Map<string, string>(); // reverse ^

    private vslsExternalUriToIds: Map<string, string> = new Map<string, string>();
    private vslsExternalIdToUris: Map<string, vscode.Uri> = new Map<string, vscode.Uri>();

    public readonly scheme = `${Settings.scheme}:`;
    public static readonly rawScheme = Settings.scheme;

    constructor(
        private forcePrefixedRoot?: boolean,
        private fileService?: Lazy<vsls.FileService>
    ) { }

    public async init() {
        this.fileService().onExternalFilesChanged((e: vsls.ExternalFilesChangedEventArgs) => {
            if (e.changeType === vsls.CollectionChangeType.Add) {
                this.registerExternalFilesAsync(e.localPaths, e.vslsPaths);
            }
        });
    }

    /**
     * Given a local path string, generates a VSLS external path like
     * "/~external/guid/filename". Stores this mapping both locally and 
     * in the file service.
     * @param localPath Like "C:/Users/Caitlin/banana.txt"
     */
    private async registerExternalFilesAsync(localPaths: string[], vslsPaths: string[]): Promise<void> {
        if (localPaths == null) {
            // GUEST
            return;
        }
        // HOST
        for (let i = 0; i < localPaths.length; ++i) {
            let localPath = PathUtil.normalizePath(localPaths[i]);
            let vslsPath = PathUtil.normalizePath(vslsPaths[i]);
            this.localPathsToVslsPaths.set(localPath, vslsPath);
            this.vslsPathsToLocalPaths.set(vslsPath, localPath);
        }
    }

    /**
     * Given a generated external uri string get the original Uri
     */
    public getOriginalUri(externalUri: string): vscode.Uri {
        // The value we get may not be fully %-encoded. Since the values we have as keys are %-encoded
        // create a uri and get it's %-encoded value.
        let encodedValue = vscode.Uri.parse(externalUri).toString().toLowerCase();
        if (!this.vslsExternalIdToUris.has(encodedValue)) {
            throw new Error('Unknown document id');
        }

        return this.vslsExternalIdToUris.get(encodedValue);
    }

    /**
     * Convert from the host paths to a vsls URI which looks like (vsls:/<relative path from workspace root>) with forward slashes.
     */
    public code2ProtocolUriConverter(value: vscode.Uri): string {
        if (!value) {
            return undefined;
        }

        // If we have a http\https uri or a command (e.g. a markdown link), pass them through because operations on those should happen on the client side.
        if (value.scheme.toLowerCase() === 'http' || value.scheme.toLowerCase() === 'https' || value.scheme.toLowerCase() === 'command') {
            return value.toString();
        }

        const protocolWorkspacePath = this.code2protocolWorkspaceFilesOnly(value);
        if (protocolWorkspacePath !== null) {
            return protocolWorkspacePath.toString();
        }

        // This is an external URL, so we need to create & cache the URLs for
        // those URLs, and ensure they're correctly encoded.
        let uriString = value.toString();
        if (this.vslsExternalUriToIds.has(uriString)) {
            return this.vslsExternalUriToIds.get(uriString);
        }

        let fileName = path.basename(value.fsPath);
        let guid = uuid().replace(/-/g, '');
        // Create a URI and call toString so that it gets %-encoded. Other parts of the system will %-encode the string.
        let externalUri = vscode.Uri.parse(`${PathManager.vslsExternalScheme}:/${guid}/${fileName}`).toString().toLowerCase();
        this.vslsExternalUriToIds.set(uriString, externalUri);
        this.vslsExternalIdToUris.set(externalUri, value);
        return externalUri;
    }

    public code2protocolWorkspaceFilesOnly(uri: vscode.Uri): vscode.Uri {
        // If the given uri is outside of the workspace, workspaceFolder will be undefined.
        let workspaceFolder = vscode.workspace.getWorkspaceFolder(uri);
        if (!workspaceFolder) {
            return null;
        }

        // File is anchored under the workspace, so it's fine to just convert
        // this our vsls format for sharing on the wire
        const relativePath = vscode.workspace.asRelativePath(uri, false);
        const vslsPathAsString = PathUtil.convertToForwardSlashes(relativePath);
        let rootPrefix = '';
        if (workspaceFolder.index > 0 || this.forcePrefixedRoot) {
            rootPrefix = `~${workspaceFolder.index}/`;
        }

        return vscode.Uri.parse(`${this.scheme}/${rootPrefix}${vslsPathAsString}`);
    }

    /**
     * Convert from a protocol path which is a vsls uri to local paths.
     */
    public protocol2CodeUriConverter(value: string): vscode.Uri {
        if (!value) {
            return undefined;
        }

        return this.protocolUri2CodeUriConverter(vscode.Uri.parse(value));
    }

    public isExternalVslsPath(vslsPath: string): boolean {
        return vslsPath.startsWith(PathManager.externalPrefix) &&
            vslsPath.length > (PathManager.externalPrefix.length + 1);
    }

    public protocolUri2CodeUriConverter(value: vscode.Uri): vscode.Uri {
        const primaryPath = vscode.workspace.workspaceFolders ?
            vscode.workspace.workspaceFolders[0] :
            null;
        const scheme = value.scheme.toLowerCase();

        const isNotebookPath = value.path.startsWith(PathManager.notebookCellPrefix);

        // If we're handed a path that is for our scheme, and the root is also
        // our scheme then pass it through, since it's already in the correct
        // structure.
        // Note: all requests for vsls:/ files on the GUEST side will return here
        if ((scheme === PathManager.rawScheme && primaryPath && primaryPath.uri.scheme === PathManager.rawScheme)
            || scheme === 'http'
            || scheme === 'https') {

            if (value.path.startsWith(PathManager.gitPrefix)) {
                // vsls-scc:/ URIs on the guest
                return this.LiveShareSourceControlUriFromRelativeGitUri(value);
            } else if (isNotebookPath) {
                return this.NotebookCellUriFromRelativeNotebookCellUri(value);
            } else {
                // vsls:/ URIs on the guest 
                return value;
            }
        }

        if (scheme === PathManager.vslsExternalScheme) {
            return this.getOriginalUri(value.toString());
        }

        // Code assumes from here on that we are on the HOST side
        if (scheme !== PathManager.rawScheme) {
            throw new Error('Unknown path format from the client');
        }

        if (value.path.startsWith(PathManager.untitledPrefix)) {
            return vscode.Uri.parse(`${PathManager.untitledScheme}:${path.basename(value.path)}`);
        }

        if (value.path.startsWith(PathManager.gitPrefix)) {
            return this.GitUriFromRelativeGitUri(value);
        }

        if (isNotebookPath) {
            return this.NotebookCellUriFromRelativeNotebookCellUri(value);
        }

        if ((sessionStateTracker.sessionStateTracker.State === SessionState.Shared || sessionStateTracker.sessionStateTracker.State === SessionState.SharingInProgress)
                && this.isExternalVslsPath(value.path)) {
            let vslsPath = value.path;
            let localPath = this.vslsPathsToLocalPaths.get(vslsPath);
            if (localPath) {
                return vscode.Uri.parse(localPath);
            }
        }

        // Get the actual folder this is for.
        if (!primaryPath) {
            return value;
        }

        let { moniker, relativePath } = PathUtil.getMonikerFromUri(value);
        let rootIndex = parseInt(moniker, 10);

        // vscode.Uri.joinPath not available on older versions of VS Code
        if (vscode.Uri.joinPath === undefined) {
            let pathPrefix = primaryPath.uri.fsPath;
            if (moniker !== '') {
                const workspaceFolder = vscode.workspace.workspaceFolders[rootIndex];
                if (!workspaceFolder) {
                    return value;
                }

                pathPrefix = workspaceFolder.uri.fsPath;
            }

            if (pathPrefix.endsWith('/') || pathPrefix.endsWith('\\')) {
                pathPrefix = pathPrefix.substr(0, pathPrefix.length - 1);
            }

            if (relativePath.startsWith('/') || relativePath.startsWith('\\')) {
                relativePath = relativePath.substring(1);
            }

            return vscode.Uri.file(path.join(pathPrefix, relativePath));
        }

        let rootUri = primaryPath.uri;
        if (moniker !== '') {
            const workspaceFolder = vscode.workspace.workspaceFolders[rootIndex];
            if (!workspaceFolder) {
                return value;
            }

            rootUri = workspaceFolder.uri;
        }

        if (rootUri.path.length > 1 && (rootUri.path.endsWith('/') || rootUri.path.endsWith('\\'))) {
            rootUri = rootUri.with({ path: rootUri.path.substring(0, rootUri.path.length - 1) });
        }

        return vscode.Uri.joinPath(rootUri, relativePath);
    }

    /**
     * Converts a relative path to VSCode path.
     * This method is invoked by both HOST and GUEST, and results 
     * are different, depending on the side.
     * On the host, most times, we will return a file scheme URI. (file:/path/to/file.ext)
     * On the guest, most times we will return a vsls scheme URI. (vsls:/path/to/file.ext)
     * 
     * @param relativePath The relative path to convert.
     */
    public relativePathToLocalPath(relativePath: string): vscode.Uri {
        if (!relativePath) {
            return null;
        }

        if (relativePath.startsWith(this.scheme) || relativePath.startsWith('file:')) {
            throw new Error('Supplied path is not a relative path');
        }

        let protocolPrefixedPath: string = null;
        if (relativePath.startsWith('/')) {
            protocolPrefixedPath = `${this.scheme}${relativePath}`;
        } else {
            protocolPrefixedPath = `${this.scheme}/${relativePath}`;
        }

        return this.protocol2CodeUriConverter(protocolPrefixedPath);
    }

    public localPathToRelativePath(localPath: vscode.Uri): string | null {
        if (!localPath || localPath.scheme === PathManager.outputScheme) {
            return null;
        }

        if (localPath.scheme === PathManager.rawScheme) {
            return localPath.path;
        }

        if (localPath.scheme !== PathManager.gitScheme && localPath.scheme !== PathManager.vslsSccScheme
            && localPath.scheme !== PathManager.notebookCellScheme) {
            const isInWorkspace = !!vscode.workspace.getWorkspaceFolder(localPath);
            if (!isInWorkspace) {
                // The original path was unchanged, this means that it wasn't actually a file relative to a workspace
                if (sessionStateTracker.sessionStateTracker.State === SessionState.Shared || sessionStateTracker.sessionStateTracker.State === SessionState.SharingInProgress) {
                    // If the file is untitled, still format the path correctly
                    if (localPath.scheme === PathManager.untitledScheme) {
                        let localUntitledPath = this.localPathsToVslsPaths.get(localPath.fsPath);
                        if (!localUntitledPath) {
                            let guid = uuid().replace(/-/g, '');
                            const strippedPath = vscode.workspace.asRelativePath(localPath, false);
                            localUntitledPath = `${PathManager.untitledPrefix}/${guid}/${strippedPath}`;
                            this.localPathsToVslsPaths.set(localPath.fsPath, localUntitledPath);
                            this.vslsPathsToLocalPaths.set(localUntitledPath, localPath.fsPath);
                            return localUntitledPath;
                        }
                        return localUntitledPath;
                    }

                    // See if it's a registered external file
                    let localPathString = PathUtil.normalizePath(localPath.toString());
                    let vslsPath = this.localPathsToVslsPaths.get(localPathString);
                    if (vslsPath) {
                        return vslsPath;
                    }
                }

                return null;
            }
        }

        // case on the host, converting from git scheme to relative path
        if (localPath.scheme === PathManager.gitScheme) {
            let relativeWorkspacePath = vscode.workspace.asRelativePath(localPath.fsPath, false);
            return this.RelativeGitUriFromGitUri(localPath, relativeWorkspacePath);
        }

        // case on the guest, we need to convert from vsls-scc schema to relative path
        if (localPath.scheme === PathManager.vslsSccScheme) {
            return this.RelativeGitUriFromLiveShareSourceControlUri(localPath);
        }

        if (localPath.scheme === PathManager.notebookCellScheme) {
            return this.RelativeNotebookCellPathFromLocalNotebookCellUri(localPath);
        }

        const asProtocol = this.code2protocolWorkspaceFilesOnly(localPath);
        return asProtocol?.path;
    }

    public getFromVslsPathsToLocalPaths(vslsPath: string): string {
        return this.vslsPathsToLocalPaths.get(vslsPath);
    }

    public deleteFromVslsPathsToLocalPaths(vslsPath: string): boolean {
        return this.vslsPathsToLocalPaths.delete(vslsPath);
    }

    public getFromLocalPathsToVslsPaths(localPath: string): string {
        return this.localPathsToVslsPaths.get(localPath);
    }

    public deleteFromLocalPathsToVslsPaths(localPath: string): boolean {
        return this.localPathsToVslsPaths.delete(localPath);
    }

    public LiveShareSourceControlUriFromRelativeGitUri(relativeGitUri: vscode.Uri): vscode.Uri | null {
        var uriDetails = this.GetRelativeGitUriDetails(relativeGitUri.path);
        if (uriDetails) {
            let version = uriDetails.ref;

            let absolutePath = uriDetails.hostPath;
            if (absolutePath.startsWith('/')) {
                absolutePath = absolutePath.slice(1, absolutePath.length);
            }

            let vscodePath = vscode.Uri.file(absolutePath);   // c:/path/to/file.ts
            let resourceUri = uriDetails.guestPath;           // vsls:/to/file.ts

            let sccQuery: SccUriQuery = { path: vscodePath.fsPath, version: JSON.stringify({ ref: version }), sccId: 1, groupId: "workingTree", resourceUri: resourceUri };
            let gitUriString = `vsls-scc:${vscodePath.fsPath}?${JSON.stringify(sccQuery)}`;
            return vscode.Uri.parse(gitUriString);
        }

        return null;
    }

    public resourceUriFromLiveShareSourceControlUri(sccUri: vscode.Uri): vscode.Uri {
        let query = JSON.parse(sccUri.query) as SccUriQuery;
        let resourceUri = query.resourceUri;
        return vscode.Uri.parse(resourceUri);
    }

    public RelativeGitUriFromLiveShareSourceControlUri(sccUri: vscode.Uri): string {
        let query = JSON.parse(sccUri.query) as SccUriQuery;

        let version: string = undefined;

        let versionString = query?.version;
        if (versionString) {
            let versionObject: SccGitVersion = JSON.parse(versionString) as SccGitVersion;
            version = versionObject?.ref;
        }

        if (!version) {
            version = '~';
        }

        let forwardSlashesPath = PathUtil.convertToForwardSlashes(sccUri.path);

        // remove the extra leading slash
        if (forwardSlashesPath.startsWith('/')) {
            forwardSlashesPath = forwardSlashesPath.slice(1, forwardSlashesPath.length);
        }

        return `${PathManager.gitPrefix}/${version}/${forwardSlashesPath}::${query.resourceUri}`;
    }

    public RelativeGitUriFromGitUri(gitUri: vscode.Uri, relativeWorkspacePath: string): string {
        let localGitQuery = JSON.parse(gitUri.query) as GitUriQuery;
        return `${PathManager.gitPrefix}/${localGitQuery.ref}${gitUri.path}::${this.scheme}/${relativeWorkspacePath}`;
    }

    public GitUriFromRelativeGitUri(relativeGitUri: vscode.Uri): vscode.Uri {
        var uriDetails = this.GetRelativeGitUriDetails(relativeGitUri.path)
        if (uriDetails) {
            let vscodePath = vscode.Uri.file(uriDetails.hostPath);
            let localGitQuery: GitUriQuery = { path: vscodePath.fsPath, ref: uriDetails.ref };
            return vscode.Uri.parse(`${PathManager.gitScheme}:/${uriDetails.hostPath}?${JSON.stringify(localGitQuery)}`);
        }

        return null;
    }

    public GetRelativeGitUriDetails(path: string): SourceControlUriDetails {
        // path example: /~git/~/c:/path/to/file.ts::vsls:/to/file.ts
        let prefix: string = "/~git/";
        if (path.startsWith(prefix)) {
            let prefixLessPath = path.substr(prefix.length, path.length - prefix.length); // ~/c:/path/to/file.ts::vsls:/to/file.ts
            let versionEndIndex = prefixLessPath.indexOf('/');
            let version = prefixLessPath.substr(0, versionEndIndex); // ~
            let versionLessPath = prefixLessPath.substr(versionEndIndex + 1, prefixLessPath.length - versionEndIndex); // c:/path/to/file.ts::vsls:/to/file.ts
            let pathsArray = versionLessPath.split('::');
            if (pathsArray.length == 2) {
                return { ref: version, hostPath: pathsArray[0], guestPath: pathsArray[1] }
            }
        }

        return null;
    }

    private RelativeNotebookCellPathFromLocalNotebookCellUri(uri: vscode.Uri): string {
        const nbd = vscode.workspace.notebookDocuments?.find(nbd => nbd.uri.path === uri.path);
        if (!nbd) {
            return null;
        }
        const nbdRelativePath = this.localPathToRelativePath(nbd.uri);
        const notebookType = nbd.notebookType.startsWith(NotebookConstants.mirrorNotebookTypePrefix)
            ? nbd.notebookType.substring(NotebookConstants.mirrorNotebookTypePrefix.length)
            : nbd.notebookType;
        const cell = findNotebookCell(uri);
        if (!cell) {
            return null;
        }
        const id = getCellId(cell);
        return id ? `${PathManager.notebookCellPrefix}${nbdRelativePath}?${notebookType}#${id}` : null;
    }

    private getLocalNotebookUriFromRelativeNotebookCellUri(relativeCellUri: vscode.Uri): vscode.Uri {
        const relativeNotebookPath = relativeCellUri.path.substring(PathManager.notebookCellPrefix.length);
        return this.relativePathToLocalPath(relativeNotebookPath);
    }

    private NotebookCellUriFromRelativeNotebookCellUri(uri: vscode.Uri): vscode.Uri {
        const localNotebookPath = this.getLocalNotebookUriFromRelativeNotebookCellUri(uri);
        return findNotebookCellById(localNotebookPath, uri.fragment)?.document?.uri;
    }

    private async openNotebookCellDocument(relativeCellPath: string, show = false): Promise<vscode.TextDocument> {
        const relativeCellUri = vscode.Uri.parse(relativeCellPath);
        const localNotebookPath = this.getLocalNotebookUriFromRelativeNotebookCellUri(relativeCellUri);
        const nbd = await vscode.workspace.openNotebookDocument(localNotebookPath);
        if (nbd) {
            return this.openRelativePath(relativeCellPath, show, false);
        } else {
            throw new Error(`Could not open notebook ${relativeCellPath}`);
        }
    }

    public async openRelativePath(relativePath: string, show = false, openIfNotExists = true): Promise<vscode.TextDocument> {
        const localPath = this.relativePathToLocalPath(relativePath);
        if (localPath) {
            if (localPath.scheme === PathManager.notebookCellScheme) {
                const notebookCell = findNotebookCell(localPath);
                const result = notebookCell?.document;
                if (show && notebookCell) {
                    await vscode.window.showNotebookDocument(notebookCell?.notebook);
                }
                assert(result !== null, 'Notebook cell document should be non-null');
                return result;
            }

            const document = await vscode.workspace.openTextDocument(localPath);
            if (show) {
                await vscode.window.showTextDocument(document);
            }
            return document;
        }


        if (relativePath.startsWith(PathManager.notebookCellPrefix) && openIfNotExists) {
            return this.openNotebookCellDocument(relativePath, show);
        }

        throw new Error(`Could not open relative path ${relativePath}`);
    }

    public async dispose(): Promise<void> {
        this.vslsExternalIdToUris.clear();
        this.vslsExternalUriToIds.clear();
        this.localPathsToVslsPaths.clear();
        this.vslsPathsToLocalPaths.clear();
    }
}

/** Source Control Resource data serialized as JSON to vsls-scc:// URI query */
export interface SccUriQuery {
    path: string;
    version?: string | undefined;
    sccId?: number | undefined;
    groupId?: string | undefined;
    isWorkspace?: boolean | undefined;
    resourceUri?: string | undefined;
}

export interface UriParams {
    resource: vsls.SourceControlResource;
    sccId?: number | undefined;
    groupId?: string | undefined;
    resourceUri?: vscode.Uri | undefined;
}

interface GitUriQuery {
    path: string;
    ref: string;
}

interface SccGitVersion {
    ref: string;
}

interface SourceControlUriDetails {
    ref: string;
    hostPath: string;
    guestPath: string;
}

export const VSLS_SCHEME = PathManager.rawScheme;
export const FILE_SCHEME = PathManager.fileScheme;
export const GITHUB_DEV_SCHEME = PathManager.githubDevScheme;
export const VSLS_EXTERNAL_SCHEME = PathManager.vslsExternalScheme;
export const KNOWN_SCHEMES = ['http', 'https', VSLS_EXTERNAL_SCHEME, VSLS_SCHEME];