import * as vscode from 'vscode';
import { CancellationToken } from 'vscode';

import { CancellationError } from "@vs/vscs-utils";
import { ICommandContext, traceSource as trace } from '@vs/vscode-command-framework';
import { IAuthenticationProvider } from './IAuthenticationProvider';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { DEFAULT_ANONYMOUS_USER_NAME } from '../constants';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { NotificationUtil } from '@vs/vscode-command-framework';
import { sessionStateTracker } from '../SessionStateTracker';
import { TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { AuthenticationOptions } from './AuthenticationOptions';
import { IToken, IAuthStrategy } from '@vs/vscode-account';
import { SessionAction, SessionState } from '../SessionTypes';
import { auth } from './Authentication';
import { vsls } from '@vs/vsls-contracts';
import { TimeTracker } from '../utils/performance';

import {
    liveshareAnonymousStrategy,
    liveshareGithubStrategy,
} from './strategies';
import { SupportedAuthProviders, NativeAuthProvider } from './nativeAuth/NativeAuthProvider';
import { localize } from '../localize';

/** A subset of vsls.AuthenticationService sufficient for both LS desktop and web.
 */
export interface IAuthenticationProviderService extends vsls.AuthenticationCoreService {
    /**
     * Sets the authentication token for the RPC session(s).
     * @param loginTokenOrCode Token acquired from the Cascade authentication service,
     * or a short code that can be used to acquire a token.
     * @param options Login options.
     * @param cancellationToken A cancellation token.
     * @returns Information about the logged-in user, or null if the token is invalid
     * or expired.
     */
    loginAsync(
        loginTokenOrCode: vsls.AuthenticationToken,
        options: vsls.AuthenticationOptions,
        userInfo: vsls.UserInfo,
        cancellationToken?: CancellationToken)
            : Promise<vsls.UserInfo>;

    /**
     * Using the supplied credential, conduct and attempts to sets the authentication
     * token for the RPC session(s) with that cached token, if the token is still valid.
     * @param externalAccountInfo Details about the account used to find a
     * matching cached auth token.
     * @param options Login options.
     * @param cancellationToken A cancellation token.
     * @returns Information about the logged-in user, or null if a matching token
     * was not found or the token is invalid or expired.
     */
    loginWithExternalTokenAsync(
        externalAccountInfo: vsls.UserAccountInfo,
        externalToken: vsls.AuthenticationToken,
        options: vsls.AuthenticationOptions,
        userInfo: vsls.UserInfo,
        cancellationToken?: CancellationToken)
            : Promise<vsls.UserInfo>;

    /**
     * Clears the authentication token for the RPC session(s).
     * @param options Logout options.
     * @param cancellationToken A cancellation token.
     */
    logoutAsync(
            options: vsls.AuthenticationOptions,
            cancellationToken?: CancellationToken)
            : Promise<void>;
}

export class AuthenticationProvider implements IAuthenticationProvider {
    private readonly nativeAuth?: NativeAuthProvider;
    protected shouldClearCache: boolean = false;

    constructor(protected authService: IAuthenticationProviderService, isNativeAuthEnabled: boolean) {
        if (isNativeAuthEnabled) {
            this.nativeAuth = new NativeAuthProvider();
            this.nativeAuth.onSignOut(this.handleOnDidSignOut.bind(this));
        }
    }

    public isAuthenticated(): boolean {
        return userAuthStateTracker.IsSignedIn;
    }

    public async clearCache(cancellationToken?: CancellationToken): Promise<void> {
        userAuthStateTracker.userInfo = undefined;
        this.shouldClearCache = true;
        return undefined;
    }

    private async handleOnDidSignOut() {
        if (sessionStateTracker.State === SessionState.Shared) {
            // If this is the host end the collaboration session
            await vscode.commands.executeCommand<vscode.Uri>('liveshare.end');
        } else if (sessionStateTracker.State === SessionState.Joined) {
            // If this is the guest leave the collaboration session
            await vscode.commands.executeCommand<vscode.Uri>('liveshare.leave');
        }

        await this.signOut();
    }

    private async getUsernameFromInput() {
        const previousAnonymousName = Settings.get<string>(SettingKeys.anonymousUserName);

        let name = await NotificationUtil.showInputBox({
            prompt: 'Enter the name to display to other participants',
            ignoreFocusOut: true,
            value: previousAnonymousName || DEFAULT_ANONYMOUS_USER_NAME
        });

        const trimmedName = (name || '').trim();

        if (!trimmedName) {
            return DEFAULT_ANONYMOUS_USER_NAME;
        }

        return trimmedName.slice(0, 50);
    }

    public async askForUserName(): Promise<string> {
        const name = await this.getUsernameFromInput();

        if (name) {
            await Settings.save(SettingKeys.anonymousUserName, name);
        }

        return name;
    }

    public async attemptLoginVSCodeAccount(token: IToken, cancellationToken?: CancellationToken): Promise<boolean> {
        this.shouldClearCache = false;

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_LOGIN_STARTING);

        const logout = async () => {
            await auth.API.logOut([ token.strategy ]);
        };

        // try to authenticate with the token from the keytar
        try {

            let result = undefined;

            const providerName = token.strategy.publicName.toLowerCase();
            if (token.tokenType !== 'vsls') {
                // If token's type is not vsls then we're dealing with potnetially external token that has to
                // be exchanged prior to authentication
                result = await this.authService.loginWithExternalTokenAsync(
                    { providerName },
                    { token: token.accessToken },
                    {
                        cache: false,
                        cacheDefault: false
                    },
                    null,
                    cancellationToken
                );
            } else {
                // Live Share's authentication strategies exchange native tokens for a Cascade token.
                // Hence, we can jump straight to the login without running the exchange
                result = await this.authService.loginAsync(
                    { token: token.accessToken },
                    {
                        cache: false,
                        cacheDefault: false
                    },
                    null,
                    cancellationToken
                );
            }
            
            if (!result) {
                await logout();
            } else if (!result.providerName) {
                // Set the user info's provider name from the token's strategy.
                result.providerName = providerName;
            }

            userAuthStateTracker.userInfo = result;
        } catch (e) {
            // if token is not valid, remove it from the keytar
            await logout();
            throw e;
        }

        userAuthStateTracker.isCustomAccount = false;
        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_LOGIN_COMPLETE);

        return !!userAuthStateTracker.userInfo;
    }

    public async attemptSilentNativeLogin(options: AuthenticationOptions, context?: ICommandContext): Promise<boolean> {
        if (!this.nativeAuth) {
            trace.info(`Attempt to use silent native auth when it's turned off.`);
            return false;
        }

        sessionStateTracker.point(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_STARTING);

        let cancellationToken: CancellationToken;

        if (context) {
            const { cancellationTokenSource } = context;
            cancellationToken = cancellationTokenSource && cancellationTokenSource.token;
        }

        this.shouldClearCache = false;
        userAuthStateTracker.isCustomAccount = false;
        let result = false;

        await auth.API.waitForInitialLogin;

        const providerString = Settings.get<string>(SettingKeys.authenticationProvider);

        let provider: SupportedAuthProviders | undefined = (<any>SupportedAuthProviders)[providerString];
        if (!provider) {
            provider = SupportedAuthProviders.GitHub;
        }

        const token = await TimeTracker.timeIt('getCachedToken', async() => await this.nativeAuth.getCachedToken(provider));

        if (token) {
            trace.info(`Attempt to log in with ${provider} auth provider.`);
            result = await TimeTracker.timeIt('attemptLoginWithNativeToken', async() => await this.attemptLoginWithNativeToken(token, cancellationToken));

            if (result) {
                trace.info(`Authenticated with "${provider}" auth provider.`);
                sessionStateTracker.point(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_SIGNED_IN_WITH_NATIVE_PROVIDER);
                context?.telemetryEvent?.addProperty(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_AUTH_PROVIDER, provider);
            } else {
                this.nativeAuth.resetAccessTokenCache(provider);
            }
        }

        const anonymousAuthStrategy = this.anonymousAuthStrategy;
        if (!result &&
            options.isAllowAnonymous &&
            anonymousAuthStrategy) {
            sessionStateTracker.point(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_ATTEMPTING_ANONYMOUS_STRATEGY);
            const anonymousToken = await anonymousAuthStrategy.getAccessToken();

            context?.telemetryEvent?.addProperty(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_IS_ANONYMOUS_TOKEN_SET, !!anonymousToken);

            if (anonymousToken) {
                trace.info(`Attempt to log in as anonymous with previously acquired token.`);
                result = await this.attemptLoginWithNativeToken(anonymousToken.accessToken, cancellationToken);
            }

            if (result) {
                trace.info(`Authenticated as anonymous.`);
                context?.telemetryEvent?.addProperty(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_AUTH_PROVIDER, anonymousAuthStrategy.name);
                sessionStateTracker.point(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_SIGNED_IN_AS_ANONYMOUS);
            }
        }

        context?.telemetryEvent?.addProperty(TelemetryPropertyNames.SILENT_NATIVE_LOGIN_RESULT, result);
        return result;
    }

    public async attemptPromptedNativeLogin(context: ICommandContext): Promise<boolean> {
        if (!this.nativeAuth) {
            trace.info(`Attempt to use prompted native auth when it's turned off.`);
            return false;
        }

        sessionStateTracker.point(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_STARTING);
        let provider: SupportedAuthProviders | undefined;

        const signInOptions = Object.entries(SupportedAuthProviders).map(([key, value]) => {
            return {
                label: key,
                description: localize('authentication.SignInPrompt').replace('${key}', key),
                id: value,
            };
        });

        trace.info(`Present auth provider picker.`);
        const answer = await vscode.window.showQuickPick(signInOptions, {
            ignoreFocusOut: true,
            placeHolder: localize('authentication.SignInPromptPlaceholder')
        });

        if (!answer) {
            trace.info(`Auth provider picker has been cancelled by the user.`);
            throw new CancellationError();
        }

        provider = answer.id;
        Settings.save(SettingKeys.authenticationProvider, answer.label);

        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        if (cancellationToken && cancellationToken.isCancellationRequested) {
            trace.info(`Auth has been cancelled via cancellationToken before we've got an auth token.`);
            sessionStateTracker.point(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_CANCELED_VIA_CANCELLATION_TOKEN);
            throw new CancellationError();
        }

        if (provider) {
            context.telemetryEvent.addProperty(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_SELECTED_AUTH_PROVIDER, provider);
        } else {
            trace.info(`Auth has been cancelled by the user before we've got a token.`);
            sessionStateTracker.point(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_THE_USER_CANCELED_AUTH_PROVIDER_PICK);
            throw new CancellationError();
        }

        trace.info(`Attempt to log in with ${provider} auth provider.`);
        const token = await this.nativeAuth.getCachedTokenOrLogin(provider, context);

        if (cancellationToken && cancellationToken.isCancellationRequested) {
            trace.info(`Auth cancelled after we've got a token.`);
            sessionStateTracker.point(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_CANCELED_VIA_CANCELLATION_TOKEN);
            throw new CancellationError();
        }

        if (!token) {
            sessionStateTracker.point(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_FAILED_TO_ACQUIRE_AUTH_TOKEN);
            throw new Error(`Auth token returned by ${provider} provider is empty.`);
        }

        // Attempt to login with the returned user access token.
        const result = await this.attemptLoginWithNativeToken(token, cancellationToken);

        if (result) {
            trace.info(`Authenticated with "${provider}" auth provider.`);
        } else {
            this.nativeAuth.resetAccessTokenCache(provider);
        }

        context.telemetryEvent.addProperty(TelemetryPropertyNames.PROMPTED_NATIVE_LOGIN_RESULT, result);
        return result;
    }

    private async attemptLoginWithNativeToken(token: string, cancellationToken?: CancellationToken): Promise<boolean> {
        userAuthStateTracker.userInfo = await this.authService.loginAsync(
            { token },
            {
                cache: false,
                cacheDefault: false
            },
            null,
            cancellationToken);

        return !!userAuthStateTracker.userInfo;
    }

    public async attemptAnonymousLoginVSCodeAccount(options: AuthenticationOptions, cancellationToken?: CancellationToken): Promise<boolean> {
        this.shouldClearCache = false;

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_ANONYMOUS_LOGIN_STARTING);

        const anonymousAuthStrategy = this.anonymousAuthStrategy;
        if(!anonymousAuthStrategy) {
            throw new Error('Anonymous login not supported')
        }

        const tokens = await auth.API.getTokensOrAskToSignIn({
            shouldSkipQuestion: true,
            strategies: [ anonymousAuthStrategy ]
        });

        if (!tokens.length) {
            return false;
        }

        await this.attemptLoginVSCodeAccount(tokens[0], cancellationToken);

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_ANONYMOUS_LOGIN_COMPLETE);

        return !!userAuthStateTracker.userInfo;
    }

    public async attemptDefaultLoginVSCodeAccount(options: AuthenticationOptions, cancellationToken?: CancellationToken) {
        this.shouldClearCache = false;

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_DEFAULT_LOGIN_STARTING);

        userAuthStateTracker.isCustomAccount = false;

        const strategies = await this.getDefaultStrategies();

        const anonymousAuthStrategy = this.anonymousAuthStrategy;
        if (options.isAllowAnonymous && anonymousAuthStrategy) {
            strategies.push(anonymousAuthStrategy);
        }

        await auth.API.waitForInitialLogin;

        let tokens = await auth.API.getCachedTokens({ strategies });
        if (!tokens.length) {
            return false;
        }

        // we need agent alive to authenticate
        await this.waitForAuthenticateService();

        // attempt to log in using all cached tokens
        for (let i = 0; i < tokens.length; i++) {
            const tokensToTry = tokens.slice(i);
            const token = getDefaultTokenToUse(tokensToTry, anonymousAuthStrategy);
            if (!token) {
               return false;
            }

            const authResult = await this.attemptLoginVSCodeAccount(token, cancellationToken);
            if (authResult) {
               trace.info(`Authenticated with "${token.strategy.name}" strategy.`);
               break;
            }
        }

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_DEFAULT_LOGIN_COMPLETE);

        return !!userAuthStateTracker.userInfo;
    }

    public async attemptLogin(userCode: string, options: AuthenticationOptions, cancellationToken?: CancellationToken): Promise<boolean> {
        this.shouldClearCache = false;

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_LOGIN_STARTING);

        userAuthStateTracker.userInfo = await this.authService.loginAsync(
            { code: userCode },
            {
                cache: true,
                cacheDefault: true
            }, // TODO: pass options through once auth service refactored
            null,
            cancellationToken);

        // If the user had set default login account and provider information in vscode settings,
        // and we failed to do a login with that info, then set it up to use this custom account
        // for next default sign in attempt.
        let account = Settings.get<string>(SettingKeys.account);
        let providerName = Settings.get<string>(SettingKeys.accountProvider);
        if (account || providerName) {
            userAuthStateTracker.isCustomAccount = true;
        } else {
            userAuthStateTracker.isCustomAccount = false;
        }

        sessionStateTracker.point(TelemetryPropertyNames.ATTEMPT_LOGIN_COMPLETE);

        return !!userAuthStateTracker.userInfo;
    }

    public async signOut(): Promise<void> {
        if (!this.isAuthenticated()) {
            return;
        }

        const strategies = await this.getDefaultStrategies();
        // remove auth tokens from keytar for AAD and Github, keep the anonymous token in
        await auth.API.logOut(strategies);

        await this.authService.logoutAsync({ cache: true });
        userAuthStateTracker.userInfo = undefined;
        sessionStateTracker.transition(SessionAction.SignOut);
    }

    protected get anonymousAuthStrategy(): IAuthStrategy | undefined {
        return liveshareAnonymousStrategy;
    }

    protected async getDefaultStrategies(): Promise<IAuthStrategy[]> {
        const strategies: IAuthStrategy[] =
            [
                auth.API.defaultStrategy,
                liveshareGithubStrategy
            ];

        return strategies;
    }

    protected waitForAuthenticateService(): Promise<void> {
        return Promise.resolve();
    }

    /**
     * Wait for current user get authenticated and return its token.
     */
    public async waitForAuthenticatedUserToken(): Promise<string> {
        let currentUser = await this.authService.getCurrentAuthenticatedUserAsync();
        if (currentUser && currentUser.accessToken) {
            return currentUser.accessToken;
        }
    
        let disposable: vscode.Disposable;
        return await new Promise<string>(resolve => disposable = this.authService.onAuthenticationChanged((e) => {
            if (e.accessToken) {
                disposable.dispose();
                resolve(e.accessToken);
            }
        }));         
    }
}

/**
 * Method to find first non-anonymous token if possible.
 */
function getDefaultTokenToUse(tokens: IToken[], anonymousAuthStrategy: IAuthStrategy | undefined): IToken | undefined {
    if (tokens.length === 1) {
        return tokens[0];
    }

    // if we have more than 1 token, lets use the first non-anonymous one
    for (let token of tokens) {
        if (token.strategy !== anonymousAuthStrategy) {
            return token;
        }
    }
}