import * as vscode from 'vscode';

// This type is duplicated in the API. If changing, update there as well.
export class ActivityType {
    public static readonly session = 'session';
    public static readonly workspace = 'workspace';
    public static readonly debug = 'debug';
    public static readonly terminal = 'terminal';
}

// This type is duplicated in the API. If changing, update there as well.
export interface Activity {
    timestamp: Date;
    name: string;
    data?: any;
}

/**
 * Source for raising activities.
 */
export class ActivitySource {

    private readonly activityEmitter = new vscode.EventEmitter<Activity>();

    public get onActivity(): vscode.Event<Activity> {
        return this.activityEmitter.event;
    }

    public fire(activity: Activity): void {
        this.activityEmitter.fire(activity);
    }

}

export const activitySource = new ActivitySource();
