import { ICommandContext } from '@vs/vscode-command-framework';

import { ContactCommandUtilities } from './ContactCommandUtilities';
import { 
    TelemetryEventNames,
    TelemetryPropertyNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { ContactTreeExplorerItem } from '../ContactsProviderViewlet';

export function builder(): ICommand<boolean> {
    return new InviteContactCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.INVITE_CONTACT, TelemetryEventNames.INVITE_CONTACT_FAULT, 'InviteContact', 1)
class InviteContactCommand implements ICommand<boolean> {

    public async invoke(item: ContactTreeExplorerItem, context: ICommandContext): Promise<boolean> {
        // add type to the telemetry command
        context.telemetryEvent.addProperty(TelemetryPropertyNames.INVITE_CONTACT_TYPE, item.options.type);
        
        return ContactCommandUtilities.inviteHelper(item.contactModel);
    }
}