import * as vscode from 'vscode';
import { CommandBase, ICommandContext } from '@vs/vscode-command-framework';

import { sessionStateTransitionsCommandDecorator } from '../decorators/SessionStateTransitionsCommandDecorator';
import { authenticationCommandDecorator, IAuthenticationDecoratorOptions } from '../decorators/AuthenticationCommandDecorator';
import { validationCommandDecorator } from '../decorators/ValidationCommandDecorator';
import { errorNotificationCommandDecorator } from '../decorators/ErrorNotificationCommandDecorator';
import { telemetryCommandDecorator } from '../decorators/TelemetryCommandDecorator';
import { telemetryStatusCommandDecorator } from '../decorators/TelemetryStatusCommandDecorator';
import { cancellationDecorator } from '../decorators/CancellationDecorator';
import { progressCommandDecorator } from '../decorators/ProgressCommandDecorator';
import { TelemetryEventNames } from '../telemetry/TelemetryStrings';

import { IDependencies } from '../contracts/IDependencies';
import { IFileSystemManager } from '../file-system-provider/IFileSystemManager';
import { SessionAction } from '../SessionTypes';
import { ExtensionUtil } from '../utils/ExtensionUtil';

export function builder(deps: IDependencies): SignInAndReloadCommand {
    return new SignInAndReloadCommand(
        deps.fileSystemManager()
    );
}

export interface JoinPostreloadCommandOptions {
    workspaceId: string;
    isAllowAnonymous?: boolean;
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.AttemptJoining,
    authAttemptMax: 2
};

/**
 * Join reload `command` that triggers when we know what workspace we
 * are connecting to (typically happens from a blank/empty workspace or
 * a newly opened copy of VS Code).
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Signing in', TelemetryEventNames.JOIN_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.WORKSPACE_SIGNIN_RELOAD, TelemetryEventNames.JOIN_FAULT, 'SignInToElevate', 1)
@telemetryStatusCommandDecorator()
@validationCommandDecorator()
@progressCommandDecorator()
@sessionStateTransitionsCommandDecorator(null, SessionAction.JoiningSuccess, SessionAction.JoiningError)
@authenticationCommandDecorator(authOptions)
export class SignInAndReloadCommand extends CommandBase {
    constructor(
        private readonly fileSystemManager: IFileSystemManager
    ) {
        super();
    }

    public async invoke(options: JoinPostreloadCommandOptions, context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;

        if (cancellationTokenSource && cancellationTokenSource.token.isCancellationRequested) {
            return;
        }

        // Workaround for VSCode bug #53257 where saving files from read-only workspace fails.
        await this.fileSystemManager.registerFileSystemProvider(false /* isReadOnly */);
        this.fileSystemManager.disposeWorkspaceProvider();
        await vscode.workspace.saveAll(false);

        await ExtensionUtil.setTransientWorkspace(false);
        await vscode.commands.executeCommand('workbench.action.reloadWindow');
        
        return true;
    }
}
