import * as vscode from 'vscode';
import { TreeDataProviderContext } from './ExtensionTreeDataProvider';
import { TreeDataProviderBase } from './TreeDataProviderBase';
import { TreeViewItemOptions, TreeViewItem } from './TreeViewItem';
import { ISessionContext} from '../ISessionContext';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { vsls } from '@vs/vsls-contracts';
import {
    RpcErrorCodes,
} from '@vs/vso-rpc';
import {
    TraceSource,
} from '@vs/vso-logging';

interface TerminalSessionExplorerItemOptions extends TreeViewItemOptions {
    terminalId: number;
}

export class TerminalSessionExplorerItem extends TreeViewItem {
    public readonly terminalId: number;
    constructor(public readonly options: TerminalSessionExplorerItemOptions) {
        super(options);
        this.terminalId = options.terminalId;
    }
}

export enum TerminalsViewItem {
    Terminals = 'terminals',

    // terminals
    LocalTerminalReadOnly = 'terminals.local.readonly',
    LocalTerminalReadWrite = 'terminals.local.readwrite',
    RemoteTerminal = 'terminals.remote',

    // Other / unspecified item type
    Other = 'other',
}

const READ_ONLY_LABEL = 'Read-only';

export class TerminalsTreeDataProvider extends TreeDataProviderBase {
    private sharedTerminals: vsls.TerminalInfo[];
    private terminalService: vsls.TerminalService;

    constructor(
        private sessionContext: ISessionContext,
        private isSessionExplorer: boolean,
        private trace: TraceSource) {
            super(TerminalsViewItem.Terminals, TreeDataProviderContext.SharedOrJoined)
    }

    public refreshItems() {
        super.refreshItems();
        this.sharedTerminals = undefined;
    }

    public registerTerminalService(
        terminalService: vsls.TerminalService): vscode.Disposable {

        this.terminalService = terminalService;
        const disposables: vscode.Disposable[] = [];
        disposables.push(terminalService.onTerminalStarted(() => this.forceRefreshItems()));
        disposables.push(terminalService.onTerminalStopped(() => this.forceRefreshItems()));
        disposables.push(terminalService.onTerminalReadOnlyChanged(() => this.forceRefreshItems()));
        return vscode.Disposable.from(...disposables);
    }

    protected async getRootItem(): Promise<TreeViewItem> {
        await this.refreshSharedTerminals();

        return new TreeViewItem({
            type: TerminalsViewItem.Terminals,
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            label: `Shared Terminals (${this.sharedTerminals.length})`
        });
    }

    protected async getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]> {
        const result: TreeViewItem[] = [];

        if (!this.terminalService) {
            return result;
        }

        await this.refreshSharedTerminals();
        for (const terminal of this.sharedTerminals) {
            result.push(await this.getTerminalRow(terminal, this.sessionContext.coeditingClient.isHost));
        }

        return (result.length === 0)
            ? this.getDefaultTerminalsActions()
            : result;
    }

    private getDefaultTerminalsActions() {
        if (this.sessionContext.coeditingClient.isHost) {
            return [
                new TreeViewItem({
                    type: TerminalsViewItem.Other,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: 'Share terminal...',
                    command: {
                        title: 'Share terminal...',
                        command: (this.isSessionExplorer)
                            ? 'liveshare.fileTreeExplorer.shareTerminal'
                            : 'liveshare.activityBar.shareTerminal'
                    }
                })
            ];
        }

        return [
            new TreeViewItem({
                type: TerminalsViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: 'No terminals shared'
            })
        ];
    }

    private async refreshSharedTerminals(): Promise<void> {
        if (this.sharedTerminals) {
            return;
        }

        try {
            this.sharedTerminals = await this.terminalService.getRunningTerminalsAsync();
        } catch (e) {
            // If the guest is leaving, the service may become unavailable.
            if (e.code !== RpcErrorCodes.ServiceNotAvailable) {
                this.trace.error('Could not get running terminals', e);
            }

            this.sharedTerminals = [];
        }    
    }

    private async getTerminalRow(sharedTerminal: vsls.TerminalInfo, isLocalTerminal: boolean) {
        const readOnlyForGuests = sharedTerminal.options.readOnlyForGuests || workspaceSessionInfoTracker.isReadOnly;
        const clearName = (sharedTerminal.options.name || '').replace('[Shared]', '');

        const row = new TerminalSessionExplorerItem({
            label: `${clearName.trim()} (${readOnlyForGuests ? READ_ONLY_LABEL : 'Read/write'})`,
            terminalId: sharedTerminal.id,
            type: (isLocalTerminal)
                    ? (sharedTerminal.options.readOnlyForGuests ? TerminalsViewItem.LocalTerminalReadOnly : TerminalsViewItem.LocalTerminalReadWrite)
                    : TerminalsViewItem.RemoteTerminal,
            iconPath: TreeDataProviderBase.getThemeIconPath('terminal'),
            command: {
                title: 'Focus terminal',
                command: (this.isSessionExplorer)
                    ? 'liveshare.fileTreeExplorer.openTerminal'
                    : 'liveshare.activityBar.openTerminal',
                arguments: [{ terminalId: sharedTerminal.id }]
            }
        });

        return row;
    }
}