import * as vscode from 'vscode';

import { IWorkspacePromptsUtil } from '../abstractions/Interfaces';
import { ExtensionUtil } from '../../extensionUtil';
import { INotificationUtil } from '../abstractions/INotificationUtil';
import { IBrowserUtil } from './BrowserUtil';

/**
 * Helper functions for the various prompts we show for a workspace.
 */
export class WorkspacePromptsUtil implements IWorkspacePromptsUtil {
    constructor(
        private notificationUtil: INotificationUtil,
        private browserUtil: IBrowserUtil) {
    }

    public showSecurityInfo(): void {
        const securityInfoLink = 'https://aka.ms/vsls-security';
        this.browserUtil.openBrowser(securityInfoLink);
    }

    public async showFirewallInformationMessage(messageId: string, showCancelOption: boolean): Promise<boolean> {
        const getHelp = 'Help';
        const ok = 'OK';
        let result;
        if (showCancelOption) {
            result = await this.notificationUtil.showInformationMessage(
                messageId, false, { modal: ExtensionUtil.enableModalNotifications }, ok, getHelp);
        } else {
            let getHelpObject = { title: getHelp, isCloseAffordance: false };
            result = await this.notificationUtil.showInformationMessage<vscode.MessageItem>(
                messageId, false, { modal: ExtensionUtil.enableModalNotifications },
                { title: ok, isCloseAffordance: true }, getHelpObject);
            if (result === getHelpObject) {
                result = getHelp;
            } else {
                result = ok;
            }
        }

        if (result === getHelp) {
            this.showFirewallHelp();

            return await this.showFirewallInformationMessage(messageId, showCancelOption);
        } else {
            return result === ok;
        }

    }

    public showFirewallHelp(): void {
        const firewallHelpLink = 'https://go.microsoft.com/fwlink/?linkid=869620';
        this.browserUtil.openBrowser(firewallHelpLink);
    }
}
