'use strict';

import { TelemetryUtil } from './TelemetryUtil';
import {
    Telemetry,
} from '@vs/vso-telemetry';

export function decorate<T>(decorator: (fn: Function, key: string, target?: T) => Function): Function {
    return (target: T, key: string, descriptor: any) => {
        let fnKey: string | null = null;
        let fn: Function | null = null;

        if (typeof descriptor.value === 'function') {
            fnKey = 'value';
            fn = descriptor.value;
        } else if (typeof descriptor.get === 'function') {
            fnKey = 'get';
            fn = descriptor.get;
        }

        if (!fn || !fnKey) {
            throw new Error('not supported');
        }

        descriptor[fnKey] = decorator(fn, key, target);
    };
}

export function debounce(delay: number): Function {
    return decorate((fn, key) => {
        const timerKey = `$debounce$${key}`;

        return function (this: any, ...args: any[]) {
            clearTimeout(this[timerKey]);
            this[timerKey] = setTimeout(() => fn.apply(this, args), delay);
        };
    });
}

function _throttle<T>(fn: Function, key: string): Function {
    const currentKey = `$throttle$current$${key}`;
    const nextKey = `$throttle$next$${key}`;

    const trigger = function (this: any, ...args: any[]) {
        if (this[nextKey]) {
            return this[nextKey];
        }

        if (this[currentKey]) {
            this[nextKey] = done(this[currentKey]).then(() => {
                this[nextKey] = undefined;
                return trigger.apply(this, args);
            });

            return this[nextKey];
        }

        this[currentKey] = fn.apply(this, args) as Promise<T>;

        const clear: () => void = () => this[currentKey] = undefined;
        done(this[currentKey]).then(clear, clear);

        return this[currentKey];
    };

    return trigger;
}

export const throttle = decorate(_throttle);

export function done<T>(promise: Promise<T>): Promise<void> {
    return promise.then<void>(() => void 0);
}

function _memoize(fn: Function, key: string): Function {
    const memoizeKey = `$memoize$${key}`;

    return function (this: any, ...args: any[]) {
        if (!this.hasOwnProperty(memoizeKey)) {
            Object.defineProperty(this, memoizeKey, {
                configurable: false,
                enumerable: false,
                writable: false,
                value: fn.apply(this, args)
            });
        }

        return this[memoizeKey];
    };
}

export const memoize = decorate(_memoize);

export interface InstrumentationOptions {
    telemetryEventName: string;
    telemetryFaultEventName?: string;
    telemetryProperties?: ((result: any) => { [key: string]: string }) | { [key: string]: string };
    onError?: any | ((err?: any) => any);
}

/**
 * Wraps function body with try-catch, sends success telemetry if the function succeeds and fault telemetry if the function throws.
 * Chains to promise if the function returns one.
 * @param telemetryEventName - telemetry event name to send event if the function succeeds. Additional properties may be added to the event.
 * @param telemetryFaultEventName - telemetry fault event name to send if the function throws.
 * @param telemetryProperties - an object with properties or a function that returns an object with properties to add to the successful event.
 * @param onError - a function to call on throw or a value to return when the function throws. If not defined, the exception will bubble up.
 */
export function instrumented({ telemetryEventName, telemetryFaultEventName, telemetryProperties, onError }: InstrumentationOptions): Function {
    return decorate((fn, key, target: any) => {
        return function (this: any, ...args: any[]) {
            const sendFault = (e: any) => {
                const serviceName = target && target.constructor && target.constructor.name ? `${target.constructor.name}.${key}` : key;
                const telemetryResult = TelemetryUtil.DeriveTelemetryResult(e);
                const telemetryMessage = TelemetryUtil.BuildTelemetryMessage(serviceName, telemetryResult, e.message);

                Telemetry.sendFault(
                    telemetryFaultEventName || telemetryEventName + '-fault',
                    TelemetryUtil.MapTelemetryResultToFaultType(telemetryResult),
                    telemetryMessage,
                    e);

                if (this.trace && this.trace.traceEvent) {
                    this.trace.traceEvent(TelemetryUtil.MapTelemetryResultToTraceEventType(telemetryResult), 0, `[${serviceName}]: ${telemetryMessage}`);
                }

                if (typeof onError === 'function') {
                    return (<Function>onError).apply(this, e);
                } else if (typeof onError !== 'undefined') {
                    return onError;
                }

                throw e;
            };

            const sendSuccess = (result: any) => {
                const props = typeof telemetryProperties === 'undefined' ? undefined :
                    typeof telemetryProperties === 'function' ? (<Function>telemetryProperties).apply(this, result) :
                        telemetryProperties;

                Telemetry.sendTelemetryEvent(telemetryEventName, props);
                return result;
            };

            try {
                const result = fn.apply(this, args);
                if (result && typeof result.then === 'function') {
                    return result.then((r: any) => sendSuccess(r), (e: any) => sendFault(e));
                } else {
                    return sendSuccess(result);
                }
            } catch (e) {
                return sendFault(e);
            }
        };
    });
}
