import * as vscode from 'vscode';
import * as config from '../../config';
import { getExpService, TreatmentVariables, JoinCommandUtilities as JoinCommandUtilitiesCore } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { Uri } from 'vscode';
import { Key as ConfigKey } from '../../config';
import { IConfigUtil } from '../util/ConfigUtil';

import { IDependencies } from '../IDependencies';
import { ShareOptions } from '@vs/liveshare-api-contracts';
import { JoinCommandUtilities } from './JoinCommandUtilities';
import { ICommandContext } from '@vs/vscode-command-framework';
import { CancellationError } from '@vs/vscs-utils';
import { dependencies } from '../Dependencies';


import {
    SessionAction,
    TelemetryEventNames,
    TelemetryPropertyNames,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    sessionStateTransitionsCommandDecorator,
    authenticationCommandDecorator,
    IAuthenticationDecoratorOptions,
    IClipboardUtil,
    localize,
    LiveShareCommandBase,
    JoinCommandOptions
} from '@vs/liveshare-core';

export function builder(dep: IDependencies): JoinSessionCommand {
    return new JoinSessionCommand(
        dep.workspaceService(),
        dep.clipboardUtil(),
        dep.configUtil()
        );
}

export interface IShareDialogMeta {
    time: number;
    urisMap: { [key: string]: vscode.Uri; };
    commandText: string;
}

const askToSignIn = async (message: string, options: JoinCommandOptions | string | vscode.Uri) => {
    const notificationUtil = dependencies.notificationUtil();
    const signInItem = localize('Sign In');

    const questionResult = await notificationUtil.showInformationMessage(message, false, signInItem);

    // if user picked the `sign in` button
    if (questionResult === localize('Sign In')) {
        if (typeof options === 'string' || options instanceof vscode.Uri) {
            options = { link: options };
        } else if (!options) {
            options = {};
        }

        const joinCommandOptions: JoinCommandOptions = {
            ...options,
            isAllowAnonymous: false,
        };

        await vscode.commands.executeCommand(`${config.get<string>(config.Key.commandPrefix)}.join`, joinCommandOptions);
    }
    return;
};

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.AttemptJoining
};

/**
 * Join session `command` that invokes share or join based on host presence in the workspace.
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Joining collaboration session', TelemetryEventNames.JOIN_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.INITIATE_SESSION, TelemetryEventNames.JOIN_FAULT, 'Join', 1)
@telemetryStatusCommandDecorator()
@sessionStateTransitionsCommandDecorator(SessionAction.AttemptJoining, SessionAction.JoiningPendingReload, SessionAction.JoiningError)
@authenticationCommandDecorator(authOptions)
export class JoinSessionCommand extends LiveShareCommandBase {

    constructor(
        private workspaceService: vsls.WorkspaceService,
        private clipboardUtil: IClipboardUtil,
        private configUtil: IConfigUtil
    ) {
        super();
    }

    public async invoke(options: JoinCommandOptions, context: ICommandContext): Promise<Uri> {
        options = options || {};
        const { telemetryEvent } = context;
        let canUserShare: boolean;
        let workspaceId: string;
        const { cancellationTokenSource } = context;

        const expService = getExpService();
        // get reusable links  experiment status.
        let reusableLinksExperiment = true;
        await expService?.isCachedFlightEnabled('reusableLinks').then((result) => {
        if (result !== null) {
            reusableLinksExperiment = result;
        }});

        if (!reusableLinksExperiment) {
            (options as any).telemetryProperties = {
                ...(options as any).telemetryProperties,
                [TelemetryPropertyNames.JOIN_INVOKE_COMMAND]: context.commandText
            };
            return vscode.commands.executeCommand<vscode.Uri>(`${config.get<string>(config.Key.commandPrefix)}.joinSession`, options);
        }

        let clipboardValue = '';

        if (!options.link) {
            try {
                clipboardValue = await this.clipboardUtil.pasteFromClipboardAsync();
                clipboardValue = clipboardValue.trim();
            } catch (e) { }

            options.link = JoinCommandUtilitiesCore.extractLiveshareLink(clipboardValue);
        } 

        workspaceId = await this.getValidWorkspaceFromLink((options.link)?.toString().trim());

        if (workspaceId) {
            let workspaceInfo = this.createWorkspaceInfo(workspaceId);
            try {
                await this.workspaceService.beginJoinWorkspaceAsync(workspaceInfo, cancellationTokenSource && cancellationTokenSource.token);
            } catch (e) {
                // if host auto rejects anonymous users
                if (e.code === vsls.ErrorCodes.ForbiddenHttpStatusCode && e.message.includes('anonymous')) {
                    await askToSignIn(`${context.commandName}: ${localize(e.message)}`, options);
                    return;
                }
            }
            canUserShare = await this.workspaceService.canUserShareWorkspaceAsync(workspaceId, cancellationTokenSource && cancellationTokenSource.token);
        }

        // regular join prompt user for live share link
        if (options.inviteLinkJoining === undefined && !options.link && options.isPlannedSession === undefined) {
            const validateInput = (value: string): string => {
                return JoinCommandUtilitiesCore.extractLiveshareWorkspaceId(value.trim())
                    ? undefined
                    : 'Invalid collaboration session URL';
            };

            options.link = await vscode.window.showInputBox({
                prompt: 'Enter the URL of the collaboration session to join',
                ignoreFocusOut: true,
                value: JoinCommandUtilitiesCore.extractLiveshareLink(clipboardValue),
                validateInput
            });
        }

        if (!options.link) {
            // The user cancelled out of the input dialog.
            throw new CancellationError('Operation cancelled @ join collaboration session URL dialog.');
        }

        // planned sessions join - it doesn't prompt user for join link.
        if (canUserShare) {
            // TODO: Allow creating read only sessions
            const command = 'liveshare.start';
            vscode.commands.executeCommand<vscode.Uri>(command, <ShareOptions> {
                isPersistent: true,
                sessionId: workspaceId
            });
            telemetryEvent.addProperty(TelemetryPropertyNames.SHARED_AS_PLANNED_SESSION, 'true');
        } else {
            await JoinCommandUtilities.invokeJoinCommand(options, context);
        }
        return;
    }

    private async getValidWorkspaceFromLink(collaborationLink: string): Promise<string | undefined> {
        const liveshareLink = JoinCommandUtilitiesCore.extractLiveshareLink(collaborationLink);

        return JoinCommandUtilitiesCore.extractLiveshareWorkspaceId(liveshareLink);
    }

    private createWorkspaceInfo(workspaceId: string): vsls.WorkspaceJoinInfo {
        return {
            id: workspaceId,
            connectionMode: config.get<vsls.ConnectionMode>(config.Key.connectionMode),
            clientCapabilities: config.getClientCapabilties(),
            anonymousUserName: this.configUtil.get(ConfigKey.anonymousUserName)
        };
    }
}
