import * as vscode from 'vscode';

import { TreeViewItem}   from './TreeViewItem';
import { ExtensionTreeDataProvider,TreeDataProviderContext }   from './ExtensionTreeDataProvider';
import { TreeDataProviderBase }   from './TreeDataProviderBase';
import { ISessionContext}   from '../ISessionContext';
import {
    RpcConnectionShutdownError
} from '@vs/vso-rpc';

import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { sessionStateTracker } from '../SessionStateTracker';
import { SessionState } from '../SessionTypes';

export class SessionExplorerProvider implements vscode.TreeDataProvider<TreeViewItem> {
    private readonly extensionItemProviders = new Map<any, ExtensionTreeDataProvider>();
    private extensionProviders: ExtensionTreeDataProvider[] = [];

    private readonly changeEventEmitter = new vscode.EventEmitter<TreeViewItem | undefined>();
    public readonly onDidChangeTreeData = this.changeEventEmitter.event;

    constructor(
        private sessionContext: ISessionContext) {
        sessionStateTracker.onStateChanged((e) => this.forceRefreshState(e.oldState, e.newState));
        workspaceSessionInfoTracker.onReadOnlyChanged(() => this.forceRefresh());
        this.sessionContext.onAccessControlChanged(() => this.forceRefresh());
    }
    public getExtensionTreeDataProvider<T extends ExtensionTreeDataProvider>(id: string) : T | undefined {
        const provider = this.extensionProviders.find( e => e.id === id);
        if (provider) {
            return provider as T;
        }
    }

    public registerTreeDataProvider(treeDataProvider: ExtensionTreeDataProvider): vscode.Disposable | null {
        if (this.extensionProviders.indexOf(treeDataProvider) >= 0) {
            return null;
        }

        let changeRegistration: vscode.Disposable = undefined;
        if (treeDataProvider.onDidChangeTreeData) {
            changeRegistration = treeDataProvider.onDidChangeTreeData((element) => {
                this.refresh(element);
            });
        }

        this.extensionProviders.push(treeDataProvider);
        this.refresh();

        return new vscode.Disposable(() => {
            const index = this.extensionProviders.indexOf(treeDataProvider);
            if (index < 0) {
                // Already unregistered.
                return;
            }

            if (changeRegistration) {
                changeRegistration.dispose();
                changeRegistration = undefined;
            }

            this.extensionProviders.splice(index, 1);
            this.refresh();
        });
    }

    public refresh(element?: any) {
        this.changeEventEmitter.fire(element);
    }

    public getTreeItem(element: TreeViewItem): vscode.TreeItem | Thenable<vscode.TreeItem> {
        const extensionProvider = this.extensionItemProviders.get(element);
        if (extensionProvider) {
            return extensionProvider.getTreeItem(element);
        }

        return element;
    }

    public async getChildren(element?: TreeViewItem): Promise<TreeViewItem[]> {
        try {
            if (element) {
                return await this.getElementChildren(element);
            }
            return await this.getDefaultRootChildren();
        } catch (e) {
            // If the error is an RPC connection shutdown
            // resolve with an empty list of tree view items to avoid
            // displaying an error message to the user when leaving a
            // collaboration session.
            if (e instanceof RpcConnectionShutdownError) {
                return [];
            }
            throw e;
        }
    }

    private forceRefresh(): void {
        // force a refresh to all extension providers
        this.extensionProviders.forEach(p => {
            if (p.refreshItems) {
                p.refreshItems();
            }
        });

        this.refresh();
    }

    private forceRefreshState(oldState: SessionState, newState: SessionState): void {
        const oldStates = toSessionStates(oldState);
        const newStates = toSessionStates(newState);
        for (const provider of this.extensionProviders) {
            if (isExtensionProviderVisible(provider, oldStates) !== isExtensionProviderVisible(provider, newStates)) {
                this.forceRefresh();
                return;
            }
        }
    }

    private async getDefaultRootChildren(): Promise<TreeViewItem[]> {
        const state = sessionStateTracker.State;
        const sessionStates = toSessionStates(state);

        if (sessionStates.isSharingState || sessionStates.isJoiningState) {
            return [
                new TreeViewItem({
                    type: 'loading',
                    label: (sessionStates.isSharingState) ? 'Starting collaboration session...' : 'Joining collaboration session...',
                    iconPath: TreeDataProviderBase.getThemeIconPath('loading'),
                })
            ];
        }

        let children: TreeViewItem[] = [];

        this.extensionItemProviders.clear();
        for (const extensionProvider of this.extensionProviders) {
            if (isExtensionProviderVisible(extensionProvider, sessionStates)) {
                const providerChildren = await extensionProvider.getChildren();
                    if (providerChildren && providerChildren.length > 0) {
                    for (let providerChild of providerChildren) {
                        this.extensionItemProviders.set(providerChild, extensionProvider);
                    }
                    children = children.concat(providerChildren);
                }
            }
        }

        // Session state may have changed while we were querying for the details. If we're no longer in a collaboration session, reenter this method.
        if (sessionStateTracker.State !== state) {
            return await this.getDefaultRootChildren();
        }

        return children;
    }

    private async getElementChildren(element: TreeViewItem): Promise<TreeViewItem[]> {
        const extensionProvider = this.extensionItemProviders.get(element);
        if (extensionProvider) {
            const providerChildren = await extensionProvider.getChildren(element);
            for (let providerChild of providerChildren) {
                this.extensionItemProviders.set(providerChild, extensionProvider);
            }
            return providerChildren;
        }

        return [];
    }
}

interface SessionStates {
    readonly isSharedState: boolean;
    readonly isJoinedState: boolean;
    readonly isSharingState: boolean;
    readonly isJoiningState: boolean;
    readonly notSharedOrJoined: boolean;
}

function toSessionStates(state: SessionState): SessionStates {
    const isSharedState = (state === SessionState.Shared);
    const isJoinedState = (state === SessionState.Joined);

    return {
        isSharedState,
        isJoinedState,
        isSharingState: (state === SessionState.SharingInProgress),
        isJoiningState: (state === SessionState.JoiningInProgress),
        notSharedOrJoined: !isSharedState && !isJoinedState
    }
}

function isExtensionProviderVisible(provider: ExtensionTreeDataProvider, sessionStates: SessionStates): boolean {
    return (!provider.supportedContext && !sessionStates.notSharedOrJoined) ||
        (provider.supportedContext === TreeDataProviderContext.Joined && sessionStates.isJoinedState) ||
        (provider.supportedContext === TreeDataProviderContext.Sharing && sessionStates.isSharedState) ||
        (provider.supportedContext === TreeDataProviderContext.SharedOrJoined && !sessionStates.notSharedOrJoined) ||
        (provider.supportedContext === TreeDataProviderContext.NotSharedOrJoined && sessionStates.notSharedOrJoined);
}