import { ICommand } from '../types/ICommand';
import { ICommandConstructor } from '../types/ICommandConstructor';
import { ICommandContext } from '../types/ICommandContext';

/**
 * Type of the function returned by CommandDecoratorBase.setup(). The function
 * transforms the original command type into a decorated command type.
 */
export type CommandDecorator = <T extends ICommandConstructor<any>>(original: T) => T;

/**
 * Signature of the command invoke() function that is passed to decorators' invoke().
 */
export type CommandInvoke<T> = (options: any, context: ICommandContext) => Promise<T>;

/**
 * Base class for command decorators. Handles setting up decorator chaining (when multiple
 * decorators are applied to a command) and can optionally measuring timing of the decorator
 * invocation.
 */
export abstract class CommandDecoratorBase {
    /**
     * Initializes the command ecorator base.
     * @param enableProfiling `true` to enable measuring and tracing of the time taken
     * by the decorator (not including invocation of other decorators or the actual command).
     */
    public constructor(private readonly enableProfiling: boolean = true) {}

    /**
     * Constructs the decorator function. The returned function can be applied to
     * a command class using the @ decorator syntax.
     */
    public setup(): CommandDecorator {
        const decorator = this;
        const decoratorName = decorator.constructor.name.replace('CommandDecorator', '');

        if (!this.enableProfiling) {
            return function<T extends ICommandConstructor<any>>(original: T) {
                // Generate a new class that extends the original (decorated) command class and
                // overrides the invoke() method to call the decorator's decorate() method instead.
                // That method should then call back into the super (original) class's invoke().
                const decoratorClass = class extends original {
                    constructor(...args: any[]) {
                        super(...args);
                        if (decorator.decorate) decorator.decorate(this);
                    }
                    public invoke(options: any, context: ICommandContext): Promise<any> {
                        const originalInvoke = super.invoke.bind(this);
                        return decorator.invoke(originalInvoke, options, context);
                    }
                };
                // Copy the name of the original class to the decorator-generated class.
                Object.defineProperty(decoratorClass, 'name', {
                    writable: false,
                    value: original.name,
                });
                return decoratorClass;
            };
        } else {
            return function<T extends ICommandConstructor<any>>(original: T) {
                // Equivalent to the above, with added time measurement and tracing.
                const decoratorClass = class extends original {
                    constructor(...args: any[]) {
                        super(...args);
                        if (decorator.decorate) decorator.decorate(this);
                    }
                    public async invoke(options: any, context: ICommandContext): Promise<any> {
                        let preEnd: number | undefined;
                        let postStart: number | undefined;
                        context.trace.info(`Decorator starting: ${decoratorName}`);

                        const originalInvoke = super.invoke.bind(this);
                        const innerInvoke = async (
                            innerOtions: any,
                            innerContext: ICommandContext,
                        ) => {
                            preEnd = Date.now();
                            try {
                                return await originalInvoke(innerOtions, innerContext);
                            } finally {
                                postStart = Date.now();
                            }
                        };

                        const preStart = Date.now();
                        try {
                            const outerResult = await decorator.invoke(
                                innerInvoke,
                                options,
                                context,
                            );
                            return outerResult;
                        } finally {
                            const postEnd = Date.now();
                            const preTime = (preEnd || postEnd) - preStart;
                            const postTime = postEnd - (postStart || postEnd);
                            const totalTime = preTime + postTime;
                            context.trace.info(
                                `Decorator finishing: ${decoratorName}. ` +
                                    `Duration: ${totalTime}ms (${preTime} + ${postTime})`,
                            );
                        }
                    }
                };
                Object.defineProperty(decoratorClass, 'name', {
                    writable: false,
                    value: original.name,
                });
                return decoratorClass;
            };
        }
    }

    /**
     * Performs optional decorator-specific initialization on a command
     * immediately after the command is constructed (before any invocation).
     */
    protected decorate?(command: ICommand<any>): void;

    /**
     * Invokes the decorator. The invocation must include a call to invoke
     * the command (or chained decorator).
     */
    public abstract invoke<T>(
        commandInvoke: CommandInvoke<T>,
        options: any,
        context: ICommandContext,
    ): Promise<T>;

    public dispose?(): void;
}
