import { assertDefined, defer, Signal, raceAsync, NotImplementedError } from '@vs/vscs-utils';
import { Performance } from '@vs/vscs-performance';
import { vsls } from '@vs/vsls-contracts';
import { ServiceInfo } from '@vs/vso-rpc';
import { ILogger } from '@vs/vso-logging';

import { Connection } from './Connection';

import { IVSCodeConnectionOptions } from '../interfaces/IVSCodeConnectionOptions';
import { IVSCodeJointConnection } from '../interfaces/IVSCodeJointConnection';
import { TVSCodeConnectionHub } from '../interfaces/TVSCodeConnectionHub';
import { IVSCodeConnection } from '../interfaces/IVSCodeConnection';
import { IVSCodeServerHostService } from '../interfaces/IVSCodeServerHostService';

/**
 * Class to connect establish a VSCode connection through a main thread or service worker.
 * Currently the fastest to connect wins, but in the future, we can add different criteria on
 * what connection should be used - for instance connection with better throughput or latency
 * characteristics can win instead, and the connections might be upgraded/downgraded dynamically.
 */
export class VSCodeJointConnection<
    TOptions extends IVSCodeConnectionOptions = IVSCodeConnectionOptions
> extends Connection implements IVSCodeJointConnection<TOptions> {
    constructor(
        trace: ILogger,
        protected performance: Performance,
        public readonly options: TOptions,
        private readonly connectionHubs: [
            TVSCodeConnectionHub<TOptions>,
            TVSCodeConnectionHub<TOptions>
        ]
    ) {
        super(trace.createChild('vscode-joint'), performance);
    }
    public getSharedServers(): Promise<vsls.SharedServer[]> {
        throw new NotImplementedError('Method not implemented.');
    }

    public get vscodeServerHostClient(): IVSCodeServerHostService {
        assertDefined(this.connectionReference, 'No connection found.');

        return this.connectionReference.vscodeServerHostClient;
    }

    public get serverSharingService(): vsls.ServerSharingService {
        assertDefined(this.connectionReference, 'No connection found.');

        return this.connectionReference.serverSharingService;
    }

    public getRpcService<T>(rpcServiceContract: ServiceInfo<T>): T {
        throw new Error('Method not implemented.');
    }

    public get connection(): IVSCodeConnection<TOptions> {
        assertDefined(this.connectionReference, 'No connection found.');

        return this.connectionReference;
    }

    public get workspaceClient() {
        assertDefined(this.connectionReference, 'No connection found.');

        const { liveshareConnection } = this.connectionReference;

        assertDefined(liveshareConnection, 'No LiveShare connection found.');

        return liveshareConnection.workspaceClient;
    }

    public get liveshareConnection() {
        assertDefined(
            this.connectionReference?.liveshareConnection,
            'No LiveShare conneciton found.'
        );

        return this.connectionReference?.liveshareConnection;
    }

    public get sharedServer() {
        return this.connection.sharedServer;
    }

    public async openChannel(performance?: Performance) {
        const result = await this.connectionReference?.openChannel(performance);
        return result ?? null;
    }

    public get onVSCodeServerStarted() {
        return this.connection.onVSCodeServerStarted;
    }

    public get remotePort() {
        assertDefined(this.connectionReference, 'No connection found.');

        return this.connectionReference.remotePort;
    }
    public async startForwardingPort(port: number) {
        return await this.connection.startForwardingPort(port);
    }

    public async startForwardingPortWithVisibility(port: number, isPublic: boolean) {
        return await this.connection.startForwardingPortWithVisibility(port, isPublic);
    }

    public async updateForwardedPortVisibility(port: number, isPublic: boolean) {
        await this.connection.updateForwardedPortVisibility(port, isPublic);
        return this;
    }

    public async updateForwardedPortProtocol(port: number, isHttps: boolean) {
        await this.connection.updateForwardedPortProtocol(port, isHttps);
        return this;
    }

    public async updateForwardedPortPrivacy(port: number, privacy: vsls.PrivacyEnum) {
        await this.connection.updateForwardedPortPrivacy(port, privacy);
        return this;
    }

    public async stopForwardingPort(port: number) {
        await this.connection?.stopForwardingPort(port);

        return this;
    }

    public async sendHandshakeRequest(requestStr: string) {
        return await this.connection.sendHandshakeRequest(requestStr);
    }

    private connectionReference: IVSCodeConnection<TOptions> | null = null;

    /******************************************************
     * Implementation details.
     ******************************************************/

    protected async createConnectionMock(): Promise<this> {
        try {
            this.trace.info('creating connection');
            this.connectionSignal = new Signal();
            this.addToDisposables(this.connectionSignal);

            const [connectionHub, remoteConnectionHub] = this.connectionHubs;
            assertDefined(connectionHub, 'No VSCode ConnectionHub found.');
            assertDefined(remoteConnectionHub, 'No Remote VSCode ConnectionHub found.');

            this.onConnectionChangedHandler('connecting');

            const connection = await raceAsync([
                connectionHub.connectOnce(this.options, {
                    performance: this.performance.createGroup('main-thread'),
                }),
                remoteConnectionHub.connectOnce(this.options, {
                    performance: this.performance.createGroup('service-worker'),
                }),
            ]);

            assertDefined(this.connectionSignal, 'No connection signal found.');
            assertDefined(
                connection.liveshareConnection,
                'Connected but no LiveShare connection found.'
            );

            this.connectionReference = connection;

            this.addToDisposables(connection);
            this.addToDisposables(
                connection.onConnectionChanged(
                    this.onConnectionChangedEventEmitter.fire.bind(connection)
                )
            );

            this.connectionSignal.resolve(this);

            // fire the event after the connection completed
            defer(() => {
                this.onConnectionChangedHandler('connected');
            });

            return this;
        } catch (e) {
            this.handleConnectionError(e);

            throw e;
        }
    }
}
