import { dependencies } from '../_new_/Dependencies';
import {
     ISessionContext,
    SessionExplorerProvider,
    ParticipantsTreeDataProvider,
    TerminalsTreeDataProvider,
    ServerSharingTreeDataProvider,
    CollabActionTreeDataProvider
} from '@vs/liveshare-core';
import { TraceSource } from '@vs/vso-logging';
import { ContactManager } from '@vs/liveshare-contactservice';

import { CommentsTreeDataProvider } from '@vs/liveshare-reviews';
import { ChatTreeDataProvider } from '@vs/liveshare-communications';

export enum SessionExplorerType {
    ViewletInActivityBar = 'ActivityBar',
    ViewletInFileExplorer = 'SessionExplorer',
}

export async function createSessionExplorer(
    sessionContext: ISessionContext, 
    showCollabActions: boolean,
    initiator: SessionExplorerType, 
    trace: TraceSource): Promise<SessionExplorerProvider> {

    const isSessionExplorer = initiator === SessionExplorerType.ViewletInFileExplorer;
    const sessionExplorerProvider = new SessionExplorerProvider(sessionContext);

    // collab actions
    const collabActionTreeDataProvider = new CollabActionTreeDataProvider(isSessionExplorer);
    if (showCollabActions) {
        sessionExplorerProvider.registerTreeDataProvider(collabActionTreeDataProvider);
    }

    // participants
    const participantsTreeDataProvider = new ParticipantsTreeDataProvider(
        sessionContext,
        dependencies.clientAccessCheck,
        ContactManager,
        isSessionExplorer);
    sessionExplorerProvider.registerTreeDataProvider(participantsTreeDataProvider);
    
    // shared servers
    const serverSharingTreeDataProvider = new ServerSharingTreeDataProvider(
        sessionContext,
        isSessionExplorer,
        trace);
    sessionExplorerProvider.registerTreeDataProvider(serverSharingTreeDataProvider);

    // terminals
    const terminalsTreeDataProvider = new TerminalsTreeDataProvider(
        sessionContext,
        isSessionExplorer,
        trace);
    sessionExplorerProvider.registerTreeDataProvider(terminalsTreeDataProvider);
 
    // comments
    const commentsTreeDataProvider = new CommentsTreeDataProvider();
    sessionExplorerProvider.registerTreeDataProvider(commentsTreeDataProvider);

    // chat
    const chatTreeDataProvider = new ChatTreeDataProvider();
    sessionExplorerProvider.registerTreeDataProvider(chatTreeDataProvider);

    return sessionExplorerProvider;
}
