'use strict';

import * as vscode from 'vscode';

// Workaround for https://github.com/Microsoft/vscode-nls/issues/23
interface VSCodeNlsConfig {
    locale: string;
    _languagePackSupport?: boolean;
    _languagePackId?: string;
    _translationsConfigFile?: string;
    _cacheRoot?: string;
    _corruptedFile: string;
}

let nlsConfig = process.env.VSCODE_NLS_CONFIG;
if (nlsConfig) {
    let vscodeOptions: VSCodeNlsConfig = undefined;
    try {
        vscodeOptions = JSON.parse(nlsConfig);
    } catch {
    }

    if (vscodeOptions && vscodeOptions._languagePackSupport) {
        vscodeOptions._languagePackSupport = false;
        process.env.VSCODE_NLS_CONFIG = JSON.stringify(vscodeOptions);
    } else {
        nlsConfig = undefined;
    }
}

import * as nls from 'vscode-nls';

if (nlsConfig) {
    process.env.VSCODE_NLS_CONFIG = nlsConfig;
}

nls.config({ locale: vscode.env.language, messageFormat: nls.MessageFormat.both });
