'use strict';

import { Settings, SettingKeys } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import * as vscode from 'vscode';
import * as semver from 'semver';
import { Disposable, CancellationToken, Uri } from 'vscode';
import { ICommentManager, IHostCommentService } from './contracts';

import { IDependencies } from '../IDependencies';
import { IDependencies as ICoreDependencies } from '@vs/liveshare-core';

import { TraceSource } from '@vs/vso-logging';

import {
    IPathManager,
    PathManager,
    FILE_SCHEME,
    GITHUB_DEV_SCHEME,
    VSLS_SCHEME,
    SessionState,
    ISessionContext,
    TelemetryEventNames,
    sessionStateTracker,
    TrackedNamedPosition,
    ControllerHelper,
    commandBindingDecorator,
    ByDesignError,
    Lazy,
    localize
} from '@vs/liveshare-core';

/** Check if VSCode supports the new comment API and the comments feature is enabled */
export function commentsSupported(): boolean {
    return vscode.comments
        && vscode.comments.createCommentController
        && semver.gte(semver.coerce(vscode.version), '1.35.0')
        && Settings.get<boolean>(SettingKeys.comments);
}

interface ThreadInfo {
    vslsThread: vsls.CommentThread;
    vscodeThread: vscode.CommentThread;
    isTracked?: boolean | undefined;
}

const NAMED_POSITION_PREFIX = 'commentThread_';

export const commentManagerFactory = (coreDependencies: ICoreDependencies, dependencies: IDependencies) => {

    const {
        controllerDecorator,
        errorNotificationMethodDecorator,
        telemetryMethodDecorator
    } = coreDependencies.methodDecorators();

    @controllerDecorator
    class CommentManager implements ICommentManager, vscode.CommentingRangeProvider {
        private readonly service: Lazy<vsls.CommentService>;
        private readonly pathManager: Lazy<IPathManager>;
        private readonly session: ISessionContext;
        private readonly hostCommentService: Lazy<IHostCommentService>;
        private readonly fileService: Lazy<vsls.FileService>;
        private readonly trace: TraceSource;
        private readonly threads = new Map<number, ThreadInfo>();
        private readonly commentCountChanged = new vscode.EventEmitter<void>();
        private isActive: boolean;
        private commentController?: vscode.CommentController | undefined;
        private getThreadsPromise: Promise<void>;
        private disposables: Disposable[] = [];

        constructor(coreDependencies: ICoreDependencies, dependencies: IDependencies) {
            this.pathManager = coreDependencies.pathManager;
            this.service = dependencies.commentService;
            this.session = coreDependencies.sessionContext();
            this.hostCommentService = dependencies.hostCommentService;
            this.fileService = coreDependencies.fileService;
            this.trace = coreDependencies.trace().withName('CommentManager');
        }

        private get sessionId(): number {
            return this.session.coeditingClient.clientID;
        }

        private get participantId(): string {
            const result = this.session.collaboratorManager.getUserId(this.sessionId);
            if (!result) {
                throw new Error('Cannot get UserId for current Live Share user');
            }

            return result;
        }

        public get commentCount(): number {
            let result = 0;
            for (let [, { vscodeThread: { comments } }] of this.threads) {
                result += comments.length;
            }

            return result;
        }

        public get onCommentCountChanged(): vscode.Event<void> {
            return this.commentCountChanged.event;
        }

        public async init() {
            if (!commentsSupported()) {
                return;
            }

            // Register our VSCode command implementations
            ControllerHelper.register(this, this.disposables);

            this.isActive = true;
            this.service().onCommentThreadChanged(this.serviceCommentThreadChanged, this, this.disposables);
            // WARNING! We initialize all managers at once, so in some cases the `coeditingClient` might be not initialized yet due to a race condition,
            // please refer to the `ShareCommand` on how you can build a dependency tree for managers
            this.session.coeditingClient.positionTracker.onNamedPositionsChanged(positions => this.positionChanged(positions));
            this.getThreads().catch(e => this.trace.error('Error getting comment threads', e));
        }

        public async dispose() {
            if (!this.isActive) {
                return;
            }

            this.isActive = false;
            this.commentController = undefined;
            for (const disposable of this.disposables) {
                disposable.dispose();
            }

            this.disposables = [];
            this.getThreadsPromise = undefined;

            const firecommentThreadCountChangedEvent = this.threads.size > 0;
            this.threads.clear();
            if (firecommentThreadCountChangedEvent) {
                this.commentCountChanged.fire();
            }
        }

        //#region vscode.CommentingRangeProvider

        /**
         * Provide a list of ranges which allow new comment threads creation or null for a given document
         */
        public async provideCommentingRanges(document: vscode.TextDocument, token: CancellationToken): Promise<vscode.Range[]> {
            if (!this.isActive || !document) {
                return [];
            }

            // Not a Live Share document, or outside of collaboration session.
            const path = this.getDocumentPath(document);
            if (!path) {
                return [];
            }

            // Check if the file is excluded or hidden from the collaboration session and disable adding comments there if so.
            if (isSharing()) {
                const [file] = await this.fileService().listAsync([path], { includeExcluded: true, includeHidden: true });
                if (!file || !this.isActive) {
                    return [];
                }

                const { attributes } = file;
                if (attributes === vsls.FileAttributes.External ||
                    attributes === vsls.FileAttributes.Excluded ||
                    attributes === vsls.FileAttributes.Hidden) {
                    return [];
                }
            } else if (document.uri.path.startsWith(PathManager.externalPrefix)) {
                // Do not allow comments in external files on the guest side
                return [];
            }

            // Track thread positions for the document if not tracking
            this.trackThreadPositions(document, path);

            return [new vscode.Range(0, 0, document.lineCount - 1, 0)];
        }

        //#endregion

        @errorNotificationMethodDecorator(localize('commentManager.cannotCreateCommentThread'), TelemetryEventNames.CREATE_COMMENT_THREAD_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.CREATE_COMMENT_THREAD, TelemetryEventNames.CREATE_COMMENT_THREAD_FAULT, 'CommentManager.createThread')
        @commandBindingDecorator('liveshare.comments.createThread')
        public async createThread({ text, thread: vscodeThread }: vscode.CommentReply) {
            if (!vscodeThread) {
                // Command invoked without comment thread context, possibly from key binding. Ignore.
                return;
            }

            if (!this.isActive) {
                // Session has closed already. Do not create the comment thread then.
                vscodeThread.dispose();
                return;
            }

            try {
                const { resource, range } = vscodeThread;

                if (!resource) {
                    throw new Error('No resource provided on VSCode thread');
                }

                if (!this.isSupportedScheme(resource)) {
                    // The document scheme is not supported. We shouldn't get here because provideCommentingRanges() should have not allowed comments there.
                    throw new Error(`Unexpected scheme '${resource.scheme}' of VSCode thread.resource`);
                }

                const filePath = this.pathManager().localPathToRelativePath(resource);
                if (!filePath) {
                    // We shouldn't get here because provideCommentingRanges() should have not allowed comments there.
                    throw new Error(`Failed to get relative document path for VSCode document ${resource.toString()}`);
                }

                // Create the thread on the host comment service.
                const comment: vsls.Comment = this.createVslsComment(text);
                const threadContext: vsls.CommentThreadContext = {
                    documentVersion: 0,
                    filePath,
                    rightFileStart: { line: range.start.line, offset: range.start.character },
                    rightFileEnd: { line: range.end.line, offset: range.end.character }
                };

                const commentThread: vsls.CommentThread = {
                    threadContext,
                    lastUpdatedSessionId: this.sessionId,
                    rightSnapshotIndex: 1, // VS specific
                    comments: [comment]
                };

                // The document should already have been open and active. We need it to track comment posisitions in it later on.
                const document: vscode.TextDocument = await vscode.workspace.openTextDocument(resource);

                // This will fire serviceCommentThreadChanged event. It will be filtered out by lastUpdatedSessionId
                const vslsThread = this.cloneVslsThreadIfNeeded(await this.service().createCommentThreadAsync(commentThread));

                if (!this.isActive) {
                    // Collaboration session has ended while we were creating the comment thread.
                    vscodeThread.dispose();
                    return;
                }

                if (!vslsThread) {
                    throw new Error('CommentService.createCommentThreadAsync() returned null unexpectedly');
                }

                const threadId = vslsThread.threadId;
                if (typeof threadId !== 'number') {
                    throw new Error('CommentService.createCommentThreadAsync() returned a thread with missing or incorrect type threadId');
                }

                if (!vslsThread.comments || vslsThread.comments.length === 0) {
                    throw new Error('CommentService.createCommentThreadAsync() returned a thread without comments');
                }

                if (vslsThread.comments.length > 1) {
                    throw new Error('CommentService.createCommentThreadAsync() returned a thread with more than one comment');
                }

                this.addVSCodeComment(vslsThread, vscodeThread);
                if (isSharing()) {
                    vscodeThread.contextValue = 'deletable';
                }

                this.threads.set(threadId, { vslsThread, vscodeThread });
                this.trackThreadPosition(threadId, document);
                this.commentCountChanged.fire();

            } catch (err) {
                vscodeThread.dispose();
                throw err;
            }
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotDeleteThread'), TelemetryEventNames.DELETE_COMMENT_THREAD_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.DELETE_COMMENT_THREAD, TelemetryEventNames.DELETE_COMMENT_THREAD_FAULT, 'CommentManager.deleteThread')
        @commandBindingDecorator('liveshare.comments.deleteThread')
        public async deleteThread(vscodeThread?: vscode.CommentThread) {
            if (!vscodeThread) {
                // Command invoked without comment thread context, possibly from key binding. Ignore.
                return;
            }

            if (vscodeThread.comments.length) {
                const { threadId } = vscodeThread.comments[0] as VSCodeComment;

                // Delete the comments on the host from last to first
                for (let i = vscodeThread.comments.length - 1; i >= 0 && this.isActive; --i) {
                    const { commentId } = vscodeThread.comments[i] as VSCodeComment;
                    await this.service().deleteCommentAsync(threadId, commentId, this.sessionId);
                }

                this.threads.delete(threadId);
                this.commentCountChanged.fire();
            }

            vscodeThread.dispose();
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotReply'), TelemetryEventNames.REPLY_COMMENT_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.REPLY_COMMENT, TelemetryEventNames.REPLY_COMMENT_FAULT, 'CommentManager.reply')
        @commandBindingDecorator('liveshare.comments.reply')
        public async reply({ text, thread: vscodeThread }: vscode.CommentReply) {
            if (!this.isActive) {
                // Session has closed already. Do not create the comment thread then.
                return;
            }

            if (!vscodeThread) {
                // Command invoked without comment thread context, possibly from key binding. Ignore.
                return;
            }

            if (!vscodeThread.comments.length) {
                // Command invoked with a thread that has no comments on it, which means the thread has just been deleted.
                return;
            }

            const { vslsThread } = (vscodeThread.comments[0] as VSCodeComment);
            const parentId = vslsThread.comments.length ? vslsThread.comments[vslsThread.comments.length - 1].commentId : -1;
            const comment: vsls.Comment = this.createVslsComment(text, vslsThread.threadId, parentId);
            const vslsComment = await this.service().createCommentAsync(comment);

            if (!this.isActive) {
                // Collaboration session has ended while we were creating the comment thread.
                vscodeThread.dispose();
                return;
            }

            this.addVSCodeComment(vslsThread, vscodeThread, vslsComment);
            this.commentCountChanged.fire();
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotEditComment'), TelemetryEventNames.EDIT_COMMENT_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.EDIT_COMMENT, TelemetryEventNames.EDIT_COMMENT_FAULT, 'CommentManager.editComment')
        @commandBindingDecorator('liveshare.comments.editComment')
        public async editComment(vscodeComment?: VSCodeComment) {
            tryUpdateVSCodeComment(vscodeComment, true);
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotSaveComment'), TelemetryEventNames.SAVE_COMMENT_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.SAVE_COMMENT, TelemetryEventNames.SAVE_COMMENT_FAULT, 'CommentManager.saveComment')
        @commandBindingDecorator('liveshare.comments.saveComment')
        public async saveComment(vscodeComment?: VSCodeComment) {
            if (!tryUpdateVSCodeComment(vscodeComment, false)) {
                // Somebody invoked the command from the keybinding?
                return;
            }

            if (!this.isActive) {
                // Session has closed already. Do nothing then.
                return;
            }

            const { commentId, text, threadId, vslsThread, vscodeThread } = vscodeComment;

            const index = vslsThread.comments.findIndex(c => c.commentId === commentId);
            if (index === -1) {
                // The comment was deleted before we can update it.
                return;
            }

            const newComment: vsls.Comment = this.cloneVslsCommentIfNeeded(await this.service().updateCommentAsync(threadId, commentId, this.sessionId, text));
            if (newComment.commentId !== commentId) {
                throw new Error('Comment service updateCommentAsync() changed commentId unexpectedly');
            }

            vslsThread.comments[index] = newComment;
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotCancelEditComment'), TelemetryEventNames.CANCEL_EDIT_COMMENT_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.CANCEL_EDIT_COMMENT, TelemetryEventNames.CANCEL_EDIT_COMMENT_FAULT, 'CommentManager.cancelEditComment')
        @commandBindingDecorator('liveshare.comments.cancelEditComment')
        public async cancelEditComment(vscodeComment?: VSCodeComment) {
            if (!vscodeComment) {
                // Somebody invoked the command from the keybinding?
                return;
            }

            if (!this.isActive) {
                // Session has closed already. Do nothing then.
                return;
            }

            const { commentId, vslsThread, vscodeThread } = vscodeComment;
            const { text } = vslsThread.comments.find(c => c.commentId === commentId);
            if (!text) {
                // The comment was deleted before we can cancel saving the comment.
                return;
            }

            tryUpdateVSCodeComment(vscodeComment, false, text);
        }

        @errorNotificationMethodDecorator(localize('commentManager.cannotDeleteComment'), TelemetryEventNames.DELETE_COMMENT_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.DELETE_COMMENT, TelemetryEventNames.DELETE_COMMENT_FAULT, 'CommentManager.deleteComment')
        @commandBindingDecorator('liveshare.comments.deleteComment')
        public async deleteComment(vscodeComment?: VSCodeComment) {
            if (!vscodeComment) {
                // Somebody invoked the command from the keybinding?
                return;
            }

            if (!this.isActive) {
                // Session has closed already. Do nothing then.
                return;
            }

            const { commentId, vscodeThread, threadId, vslsThread } = vscodeComment;

            if (!vslsThread.comments.length) {
                // The thread has been already deleted.
                vscodeThread.dispose();
                return;
            }

            const index = vslsThread.comments.findIndex(c => c.commentId === commentId);
            if (index === -1) {
                // The comment has been already deleted.
                deleteVSCodeComment(vscodeThread, commentId);
                return;
            }

            if (vslsThread.comments.length > 1) {
                // Workaround for https://github.com/Microsoft/vscode/issues/73147
                // Deleting the very first comment screws up Comments panel if there other comments on the thread, so we disallow it here.
                if (index === 0) {
                    throw new ByDesignError(localize('commentManager.deleteOtherComments'));
                }

                vslsThread.comments.splice(index, 1);
            } else {
                // That was the last comment we deleted. Delete the thread.
                this.threads.delete(threadId);
            }

            deleteVSCodeComment(vscodeThread, commentId);

            // Delete the comment on the host
            await this.service().deleteCommentAsync(threadId, commentId, this.sessionId);
            this.commentCountChanged.fire();
        }

        private async getThreads() {
            if (!this.getThreadsPromise) {
                this.getThreadsPromise = this.getThreadsFromService();
            }

            await this.getThreadsPromise;
        }

        private async getThreadsFromService() {
            let threads: vsls.CommentThread[];
            try {
                threads = await this.service().getAllCommentThreadsAsync();
            } catch (err) {
                // Comments disabled or old host with no comments service.
                this.trace.info('Cannot get comment threads from the host. Comments may be disabled or not supported on the host.', err);
                await this.dispose();
                return;
            }

            // Session has closed while we were getting the comments.
            if (!this.isActive) {
                return;
            }

            // Register comment controller if it is not registered yet.
            if (!this.commentController) {
                const label = localize('commentManager.controllerLabel');
                this.commentController = vscode.comments.createCommentController('vsls-comments', label); // 'vsls-comments' is used in package.json 'commentController == vsls-comments' conditions.
                this.commentController.commentingRangeProvider = this;

                this.disposables.push(this.commentController);
            }

            for (const thread of threads) {
                this.createVscodeThread(thread);
            }

            if (threads.length) {
                this.commentCountChanged.fire();
            }
        }

        private createVscodeThread(vslsThread: vsls.CommentThread) {
            if (!this.isActive || !vslsThread || this.threads.has(vslsThread.threadId)) {
                return;
            }

            vslsThread = this.cloneVslsThreadIfNeeded(vslsThread);
            const { threadId, threadContext, comments } = vslsThread;
            if (!threadContext || !threadContext.rightFileStart) {
                return;
            }

            const resource = this.getResource(threadContext.filePath);
            if (!resource) {
                return;
            }

            const range = getRange(threadContext);
            const vscodeThread = this.commentController.createCommentThread(resource, range, []);
            vscodeThread.comments = (comments || []).map(c => this.createVscodeComment(c, vscodeThread, vslsThread));
            vscodeThread.label = getParticipants(vscodeThread);
            vscodeThread.collapsibleState = vscode.CommentThreadCollapsibleState.Collapsed;
            if (isSharing()) {
                vscodeThread.contextValue = 'deletable';
            }

            this.threads.set(threadId, { vslsThread, vscodeThread });
        }

        private cloneVslsThreadIfNeeded(thread?: vsls.CommentThread): vsls.CommentThread | undefined {
            if (!isSharing() || !thread) {
                // Joined guest already has a cloned object coming from JSON RPC
                return thread;
            }

            const threadContext = thread.threadContext ? Object.assign({}, thread.threadContext) : undefined;
            const comments = thread.comments ? thread.comments.map(c => this.cloneVslsCommentIfNeeded(c)) : undefined;
            return Object.assign({}, thread, { comments, threadContext });
        }

        private cloneVslsCommentIfNeeded(comment: vsls.Comment): vsls.Comment {
            if (!comment) {
                throw new Error('The comment is null or undefined');
            }

            if (!isSharing()) {
                // Joined guest already has a cloned object coming from JSON RPC
                return comment;
            }

            const likers = comment.likers ? comment.likers.slice() : undefined;
            return Object.assign({}, comment, { likers });
        }

        private getResource(path: string): Uri | undefined {
            return path && (isSharing() ? this.pathManager().relativePathToLocalPath(path) : Uri.parse(`${VSLS_SCHEME}:${path}`));
        }

        private async trackThreadPositions(document: vscode.TextDocument, path: string) {
            try {
                // Finish getting all comment threads
                await this.getThreads();

                // We may have left collaboration session when we were querying for all threads.
                if (!this.isActive) {
                    return;
                }

                if (isSharing()) {
                    for (const threadId of this.threads.keys()) {
                        this.trackThreadPosition(threadId, document);
                    }

                    return;
                }

                // Update threads latest positions and start tracking these positions.
                const vslsThreads = await this.service().getAllCommentThreadsAsync();

                // We may have left collaboration session when we were querying for all threads.
                if (!this.isActive) {
                    return;
                }

                for (const { threadId, threadContext } of vslsThreads) {
                    if (threadContext.filePath !== path) {
                        continue;
                    }

                    const { vslsThread: thread, vscodeThread, isTracked } = this.threads.get(threadId);
                    if (!vscodeThread || isTracked) {
                        continue;
                    }

                    // If host reported different thread location, update the local comment thread.
                    const range = getRange(threadContext);
                    if (range.start.line !== vscodeThread.range.start.line ||
                        range.start.character !== vscodeThread.range.start.character ||
                        range.end.line !== vscodeThread.range.end.line ||
                        range.end.character !== vscodeThread.range.end.character) {

                        thread.threadContext = threadContext;
                        vscodeThread.range = range;
                    }

                    this.trackThreadPosition(threadId, document);
                }
            } catch (err) {
                this.trace.error(`Error tracking document positions in ${path}`, err);
            }
        }

        private trackThreadPosition(threadId: number, document: vscode.TextDocument) {
            const threadInfo = this.threads.get(threadId);
            if (threadInfo && !threadInfo.isTracked && threadInfo.vscodeThread.resource.toString() === document.uri.toString() && this.isActive) {
                const fileName = this.pathManager().localPathToRelativePath(document.uri);
                const name = NAMED_POSITION_PREFIX + threadId.toString(10);
                this.session.coeditingClient.positionTracker.setNamedPosition(
                    name,
                    fileName,
                    document,
                    threadInfo.vscodeThread.range,
                    false);

                threadInfo.isTracked = true;
            }
        }

        private getDocumentPath(document: vscode.TextDocument): string | undefined {
            if (!document || !document.uri || !this.isSupportedScheme(document.uri)) {
                return;
            }

            return this.pathManager().localPathToRelativePath(document.uri);
        }

        private isSupportedScheme(uri: vscode.Uri) {
            const supportedSchemes = isSharing() ? [FILE_SCHEME, GITHUB_DEV_SCHEME] : [VSLS_SCHEME];
            return supportedSchemes.includes(uri.scheme)
        }

        private createVslsComment(text: string, threadId: number = 0, parentId: number = -1): vsls.Comment {
            const lastUpdatedSessionId = this.sessionId;
            const participantId = this.participantId;
            const participantLabel = this.session.collaboratorManager.getDisplayName(lastUpdatedSessionId);
            return {
                lastUpdatedSessionId,
                parentId,
                threadId,
                participantLabel,
                participantId,
                text
            };
        }

        private createVscodeComment(comment: vsls.Comment, vscodeThread: vscode.CommentThread, vslsThread: vsls.CommentThread): VSCodeComment {
            if (!comment) {
                throw new Error('The comment is null or undefined');
            }

            const { commentId, text, participantId, participantLabel } = comment;
            const body = new vscode.MarkdownString(text);
            const author = participantLabel || participantId;
            const isEditable = participantId === this.participantId;
            return new VSCodeComment(commentId, body, author, isEditable, vscodeThread, vslsThread);
        }

        private addVSCodeComment(vslsThread: vsls.CommentThread, vscodeThread: vscode.CommentThread, vslsComment?: vsls.Comment, index?: number) {
            if (vslsComment) {
                vslsComment = this.cloneVslsCommentIfNeeded(vslsComment);
                vslsThread.comments.push(vslsComment);
            } else {
                vslsComment = vslsThread.comments[vslsThread.comments.length - 1];
            }

            const vscodeComment = this.createVscodeComment(vslsComment, vscodeThread, vslsThread);
            vscodeThread.comments = [...vscodeThread.comments, vscodeComment];
            vscodeThread.label = getParticipants(vscodeThread);
        }

        private serviceCommentThreadChanged(e: vsls.CommentThreadChangedEventArgs) {
            if (!e) {
                return;
            }

            if (e.newThread) {
                if (e.newThread.lastUpdatedSessionId !== this.sessionId) {
                    this.createVscodeThread(e.newThread);
                    this.commentCountChanged.fire();
                }

                return;
            }

            if (!e.changedComment || e.changedComment.lastUpdatedSessionId === this.sessionId) {
                return;
            }

            const { commentId, threadId, isDeleted } = e.changedComment;
            const { vslsThread, vscodeThread } = this.threads.get(threadId);
            if (!vscodeThread) {
                return;
            }

            const index = vslsThread.comments.findIndex(c => c.commentId === commentId);
            if (isDeleted) {
                if (index === -1) {
                    return;
                }

                deleteVSCodeComment(vscodeThread, commentId);

                vslsThread.comments.splice(index, 1);
                if (!vslsThread.comments.length) {
                    this.threads.delete(threadId);
                }

                this.commentCountChanged.fire();
                return;
            }

            if (index === -1) {
                // Added
                this.addVSCodeComment(vslsThread, vscodeThread, e.changedComment);
                this.commentCountChanged.fire();
                return;
            }

            // Updated
            const vslsComment = this.cloneVslsCommentIfNeeded(e.changedComment);
            const vscodeComment = this.createVscodeComment(vslsComment, vscodeThread, vslsThread);
            vslsThread.comments[index] = vslsComment;
            vscodeThread.comments = vscodeThread.comments.map(c => (c as VSCodeComment).commentId === commentId ? vscodeComment : c);
        }

        private positionChanged(positions: TrackedNamedPosition[]) {
            for (const position of positions) {
                if (!position.name || !position.name.startsWith(NAMED_POSITION_PREFIX)) {
                    continue;
                }

                const threadId = Number.parseInt(position.name.substr(NAMED_POSITION_PREFIX.length), 10);
                if (isNaN(threadId)) {
                    continue;
                }

                const { vslsThread, vscodeThread } = this.threads.get(threadId);
                if (!vscodeThread || !vslsThread) {
                    continue;
                }

                const { rightFileStart, rightFileEnd } = vslsThread.threadContext;
                if (!rightFileStart || !rightFileEnd) {
                    continue;
                }

                const start: vsls.Position = { line: position.range.start.line, offset: position.range.start.character };
                const end: vsls.Position = { line: position.range.end.line, offset: position.range.end.character };
                if (rightFileStart.line === start.line && rightFileStart.offset === start.offset &&
                    rightFileEnd.line === end.line && rightFileEnd.offset === end.offset) {

                    continue;
                }

                vslsThread.threadContext.rightFileStart = start;
                vslsThread.threadContext.rightFileEnd = end;

                vscodeThread.range = position.range;

                if (isSharing()) {
                    this.hostCommentService().updateThreadPosition(threadId, start, end);
                }
            }
        }
    }

    return <any>new CommentManager(coreDependencies, dependencies);
};

class VSCodeComment implements vscode.Comment {
    public author: vscode.CommentAuthorInformation;
    public contextValue?: string;
    public mode: vscode.CommentMode = vscode.CommentMode.Preview;

    constructor(
        public readonly commentId: number,
        public body: string | vscode.MarkdownString,
        authorName: string,
        isEditable: boolean,
        public readonly vscodeThread: vscode.CommentThread,
        public readonly vslsThread: vsls.CommentThread,
    ) {
        this.author = { name: authorName };
        if (isEditable) {
            this.contextValue = 'editable_deletable';
        } else if (isSharing()) {
            this.contextValue = 'deletable';
        }
    }

    public get text(): string | undefined {
        if (typeof this.body === 'string') {
            return this.body;
        }

        return this.body ? this.body.value : undefined;
    }

    public get threadId(): number {
        return this.vslsThread.threadId;
    }
}

function getRange(t: vsls.CommentThreadContext): vscode.Range {
    const start = new vscode.Position(t.rightFileStart.line, t.rightFileStart.offset);
    const end = t.rightFileEnd ? new vscode.Position(t.rightFileEnd.line, t.rightFileEnd.offset) : start;
    return new vscode.Range(start, end);
}

function isSharing(): boolean {
    return sessionStateTracker.State === SessionState.Shared || sessionStateTracker.State === SessionState.SharingInProgress;
}

function tryUpdateVSCodeComment(vscodeComment: VSCodeComment | undefined, isEditing: boolean, text?: string): boolean {
    if (!vscodeComment) {
        return false;
    }

    const { vscodeThread, commentId } = vscodeComment;

    if (typeof commentId !== 'number' || isNaN(commentId)) {
        throw new Error('VSCode comment does not have id');
    }

    if (!vscodeThread) {
        throw new Error('VSCode comment does not have parent');
    }

    vscodeThread.comments = vscodeThread.comments.map(c => {
        if ((c as VSCodeComment).commentId === commentId) {
            c.mode = isEditing ? vscode.CommentMode.Editing : vscode.CommentMode.Preview;
            if (text) {
                c.body = new vscode.MarkdownString(text);
            }
        }

        return c;
    });

    // Updating comment state is local to the comment and should keep the comment thread expanded.
    vscodeThread.collapsibleState = vscode.CommentThreadCollapsibleState.Expanded;
    return true;
}

function deleteVSCodeComment(vscodeThread: vscode.CommentThread, commentId: number) {
    vscodeThread.comments = vscodeThread.comments.filter(c => (c as VSCodeComment).commentId !== commentId);
    if (vscodeThread.comments.length) {
        vscodeThread.label = getParticipants(vscodeThread);
    } else {
        vscodeThread.dispose();
    }
}

function getParticipants(vscodeThread: vscode.CommentThread): string {
    if (!vscodeThread) {
        throw new Error('vscodeThread is null or undefined');
    }

    const participants = new Set<string>(vscodeThread.comments.map(c => c.author.name));
    let result = '';
    for (const participant of participants) {
        if (participant) {
            result = result ? `${result}, ${participant}` : participant;
        }
    }

    const participantsPrefix = localize('commentManager.participants');
    return result ? `${participantsPrefix} ${result}` : undefined;
}
