
import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { getAllRootFileSystemPaths,IRootFileSystemInfo } from './getAllRootFileSystemPaths';
import { PathManager } from '../PathManager';
import { localize } from '../localize';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';

export class ShareCommandUtilities {

    public static buildShareInfo(): [vsls.WorkspaceShareInfo, IRootFileSystemInfo] {
        const anonymousGuestApprovalRequiredSetting = (Settings.get<string>(SettingKeys.anonymousGuestApproval) || '').toLowerCase();

        const workspaceRoots = getAllRootFileSystemPaths();
        const workspaceFolders =  workspaceRoots.foundUnsupportedSchemes
            ? vscode.workspace.workspaceFolders.filter(wf => wf?.uri.scheme.toLowerCase() === PathManager.fileScheme)
            : vscode.workspace.workspaceFolders;
        const name = workspaceFolders && workspaceFolders.length > 0 && workspaceFolders[0]
            ? workspaceFolders[0].name
            : localize('emptyWorkspace.liveShareWorkspace');

        return [{
                rootDirectories: workspaceRoots.paths,
                name,
                connectionMode: Settings.get<vsls.ConnectionMode>(SettingKeys.connectionMode),
                areAnonymousGuestsAllowed: (anonymousGuestApprovalRequiredSetting !== 'reject'),
            }, workspaceRoots];
    }
}
