import { IDependencies } from './IDependencies';
import { dependencies as coreDependencies, lazyLoad, sessionStateTracker, SessionState } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { guestSourceControlManagerFactory } from './sourceControl/guestSourceControlManager';
import { HostCommentService } from './comments/hostCommentService';
import { commentManagerFactory } from './comments/commentManager';

export const dependencies = (function (): IDependencies {
    const context: IDependencies = {
        sourceControlService: lazyLoad(() => coreDependencies.rpcFactory(vsls.SourceControlService, vsls.TraceSources.ClientSourceControl)),
        guestSourceControlManager: lazyLoad(() => guestSourceControlManagerFactory(coreDependencies, context)),
        hostCommentService: lazyLoad(() => new HostCommentService(coreDependencies)),
        commentService: lazyLoad(() =>
            sessionStateTracker.State === SessionState.Shared || sessionStateTracker.State === SessionState.SharingInProgress ?
                context.hostCommentService() : coreDependencies.rpcFactory(vsls.CommentService, vsls.TraceSources.ClientCommentService)),
        commentManager: lazyLoad(() => commentManagerFactory(coreDependencies, context)),

    };
    return context;
})();

