'use strict';

import { PackageInfo } from '../../contracts/packageInfo';
import { StackFrame } from '../../getStackFrames';
import { LiveShareExtensionApiBase, ExtensionContext } from '../../liveShareApiBase';
import getCallingPackage from './getCallingPackage';

export class LiveShareExtensionApi extends LiveShareExtensionApiBase {

    public constructor(extensionContext: ExtensionContext) {
        super(extensionContext);
    }

    protected async getCallingPackage(stackFrames: StackFrame[]): Promise<PackageInfo | null> {
        let callingPackage = getCallingPackage('LiveShareExtensionApi.getApi', stackFrames);
        if (!callingPackage) {
            // Check deprecated function name for back-compat.
            callingPackage = getCallingPackage('LiveShareExtensionApi.getApiAsync', stackFrames);
        }

        return callingPackage;
    }
}
