import { vsls } from '@vs/vsls-contracts';
// Note: SessionState is consumed by the Welcome Page's script file (welcomePageMain.ts)
// If states are changed/added please reflect these updates there as well.
export enum SessionState {
    Initializing,        // System
    SignedOut,           // Auth, System
    SigningIn,           // Auth
    ExternallySigningIn, // Auth
    SignedIn,            // Auth
    SharingInProgress,   // Share, Collab, CollabInProgress
    Shared,              // Share, Collab, CollabFinal
    JoiningInProgress,   // Join,  Collab, CollabInProgress
    Joined               // Join,  Collab, CollabFinal
}

export enum SessionAction {
    AttemptSharing,
    SharingError,
    SharingSuccess,
    EndSharing,
    Unjoin,
    AttemptJoining,
    JoiningError,
    JoiningPendingReload,
    JoiningSuccess,
    AttemptSignIn,
    AwaitExternalSignIn,
    SignInError,
    SignInSuccess,
    SignOut,
    Create
}

export enum SessionPromise {
    EnvironmentReadyForFileOperation, // Promise resolves to start file operations 
    JoiningCompleted 
}

export interface SessionStateChangedEventArgs {
    newState: SessionState;
    oldState: SessionState;
    newAction: SessionAction;
    oldAction: SessionAction | undefined;
}

export interface SessionStatusChangedEventArgs {
    newStatus: string;
    oldStatus: string | undefined;
}

export interface CollaboratorChangedEventArgs {
    previouslyJoined: boolean;
    isHost: boolean;
    collaboratorSessionHash: number;
    hasCollaborators: boolean;
    changeType: vsls.WorkspaceSessionChangeType;
    userProfile: vsls.WorkspaceUserProfile;
    sessionNumber: number;
    applicationName: string;
    disconnectedReason?: vsls.WorkspaceDisconnectedReason;
}