import * as signalr_proxy from '@vs/vso-signalr-client-proxy';
import { ILogger } from '@vs/vso-logging';
import * as rpc from 'vscode-jsonrpc';
import * as constants from './constants';

/**
 * Relay hub proxy server to accept connections coming from a joining participants
 * that send an 'ack' signal to start a channel session.
 */
export class RelayHubProxyServer {
    private readonly onHubJoinedEmitter = new rpc.Emitter<signalr_proxy.IRelayHubProxy | null>();

    private readonly onParticipantJoinedEmitter = new rpc.Emitter<{
        relayHubProxy: signalr_proxy.IRelayHubProxy;
        participant: signalr_proxy.IRelayHubParticipant;
    }>();

    constructor(
        private relayServiceProxy: signalr_proxy.IRelayServiceProxy,
        private hubId: string,
        private logger: ILogger,
        private hostProperties?: {
            [key: string]: any;
        }
    ) {}

    public readonly onHubJoined = this.onHubJoinedEmitter.event;

    public readonly onParticipantJoined = this.onParticipantJoinedEmitter.event;

    public async acceptConnections(cancellationToken?: rpc.CancellationToken): Promise<void> {
        const hubProxy = this.relayServiceProxy.hubProxy;

        const joinIfConnected = async () => {
            if (hubProxy.isConnected) {
                await this.joinHubAndAcceptConnections();
            } else {
                this.onHubJoinedEmitter.fire(null);
            }
        };
        const disposable = hubProxy.onConnectionStateChanged(async () => {
            try {
                await joinIfConnected();
            } catch (err) {
                this.logger.error(`Failed to join hub id:${this.hubId}`, err);
            }
        });

        if (cancellationToken) {
            cancellationToken.onCancellationRequested(() => disposable.dispose());
        }

        await joinIfConnected();
    }

    private async joinHubAndAcceptConnections(): Promise<signalr_proxy.IDisposable> {
        const hostProperties = this.hostProperties || {
            [constants.PARTICIPANT_PROPERTY_IS_HOST]: true,
            [constants.PARTICIPANT_PROPERTY_HOST_FLAGS]: constants.HostFlags.JoinReadAck,
        };

        const relayHubProxy = await this.relayServiceProxy.joinHub(this.hubId, hostProperties, {
            createIfNotExists: true,
        });
        this.logger.verbose(
            `accept connections for hub:${this.hubId} host id:${relayHubProxy.selfParticipant.id} on service:${relayHubProxy.serviceId} stamp:${relayHubProxy.stamp}`
        );

        this.onHubJoinedEmitter.fire(relayHubProxy);

        const onReceiveDataDisposable = relayHubProxy.onReceiveData(async (e) => {
            if (e.type === constants.DATA_TYPE_JOINED_READY) {
                this.logger.verbose(
                    `participant:${e.fromParticipant.id} joined for hub:${this.hubId}`
                );

                this.onParticipantJoinedEmitter.fire({
                    relayHubProxy,
                    participant: e.fromParticipant,
                });

                // send ack back
                await relayHubProxy.sendData(
                    signalr_proxy.SendOption.None,
                    [e.fromParticipant.id],
                    constants.DATA_TYPE_JOINED_READY_ACK,
                    null
                );
            }
        });

        const disposable = relayHubProxy.onDisconnected(() => {
            onReceiveDataDisposable.dispose();
            disposable.dispose();
            return Promise.resolve();
        });

        return disposable;
    }
}
