import * as vscode from 'vscode';
import { TreeViewItem } from './TreeViewItem';

export enum TreeDataProviderContext {
    None,
    Sharing,
    Joined,
    SharedOrJoined,
    NotSharedOrJoined
}

export interface ExtensionTreeDataProvider extends vscode.TreeDataProvider<TreeViewItem> {
    readonly id?: string;
    readonly supportedContext?: TreeDataProviderContext;
    refreshItems?(): void;
}
