import * as vscode from 'vscode';
import { HubConnectionService } from './HubConnectionService';
import { IHubConnectionService, IHubConnectionServiceFactory, IContactManager, constants, ContactServiceEvents } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { ILogger } from '@vs/vso-logging';
import { Mutex, once, Signal } from '@vs/vscs-utils';
import { HttpClient } from '@vs/vso-http-client';

export class HubConnectionServiceFactory implements IHubConnectionServiceFactory {

    private readonly defaultHubConnectionServiceFactory: () => Promise<IHubConnectionService>;
    private readonly defaultStampRequest: () => Promise<string>;
    private readonly serviceMap = new Map<string, IHubConnectionService>();


    public constructor(
        private readonly authCoreService: vsls.AuthenticationCoreService,
        private readonly signalRServiceUri: string,
        private readonly contactManager: IContactManager,
        private readonly logger: ILogger) {

        this.defaultHubConnectionServiceFactory = once(() => {
            this.logger.verbose(`Creating default hub connection using uri:${signalRServiceUri}`);
            return HubConnectionService.create(authCoreService, signalRServiceUri, logger.createChild('default'));
        });

        const uri = vscode.Uri.parse(signalRServiceUri);
        const statusUri = `${uri.scheme}://${uri.authority}${uri.path.substring(0, uri.path.lastIndexOf('/'))}/status`;

        this.defaultStampRequest = once(() => this.requestDefaultStamp ());
    }

    public async getOrCreate(stamp?: string): Promise<IHubConnectionService> {
        if (!stamp || await this.getDefaultStamp() === stamp) {
            return await this.defaultHubConnectionServiceFactory();
        }

        let service = this.serviceMap.get(stamp);
        if (!service) {
            this.logger.verbose(`Creating hub connection for stamp:${stamp}`);
            const uri = vscode.Uri.parse(this.signalRServiceUri);
            const stampUri = `${uri.scheme}://${stamp}-${uri.authority}${uri.path}`;
            service = await HubConnectionService.create(this.authCoreService, stampUri, this.logger.createChild(`${stamp}`));
            this.serviceMap.set(stamp, service);
        }

        return service;
    }

    private async requestDefaultStamp(): Promise<string> {
        const uri = vscode.Uri.parse(this.signalRServiceUri);
        const statusUri = `${uri.scheme}://${uri.authority}${uri.path.substring(0, uri.path.lastIndexOf('/'))}/status`;

        const start = new Date().getTime();
        const statusObj = await new HttpClient(this.logger.createChild('HttpClient')).get(statusUri).value<IStatus>();
        const defaultStamp = statusObj.AppSettings.Stamp;
        this.logger.verbose(`Request default stamp:${defaultStamp} t:${new Date().getTime() - start} ms`);
        return defaultStamp;
    }

    private async getDefaultStamp(): Promise<string> {
        const start = new Date().getTime();

        const presenceServiceManager = this.contactManager?.getServiceManager(constants.LIVESHARE_PRESENCE_PROVIDER_ID);
        const getSelfContactStamp = () => presenceServiceManager?.selfUser?.properties['stamp'];

        let selfContactStamp = getSelfContactStamp();
        const logSelfResolved = () => {
            this.logger.verbose(`Default stamp:${selfContactStamp} from self contact t:${new Date().getTime() - start} ms`);
        };
        
        if (selfContactStamp) {
            logSelfResolved();
            return selfContactStamp;
        }

        const userRegistration = new Signal<string>();
        if (presenceServiceManager) {
            presenceServiceManager.once(ContactServiceEvents.SelfContactChanged, () => {
                selfContactStamp = getSelfContactStamp();
                if (selfContactStamp) {
                    logSelfResolved();
                    userRegistration.resolve(selfContactStamp);
                }
            });
        }

        return await Promise.race([this.defaultStampRequest(), userRegistration.promise]);
    }
}

interface IStatus {
    AppSettings: {
        Stamp: string,
    }
}