import { EventEmitter } from 'events';

import { TraceListener } from './TraceListener';
import { LogLevel, ILogger } from './interfaces';

/**
 * Source for tracing events that associates a name with every event.
 */
export class TraceSource extends EventEmitter implements ILogger {
    public static readonly lineEventName = 'line';
    public static readonly eventEventName = 'event';
    public static readonly flushEventName = 'flush';

    public constructor(
        public readonly name: string
    ) {
        super();
    }

    /**
     * Creates a new TraceSource with listeners copied from the existing TraceSource.
     */
    public withName(name: string): TraceSource {
        const newTraceSource = new TraceSource(name);
        this.eventNames().forEach((eventName) => {
            this.listeners(eventName).forEach((listener) => {
                newTraceSource.on(eventName, <(...args: any[]) => void>listener);
            });
        });
        return newTraceSource;
    }

    /**
     * Same as `withName` but the child trace inherits the parent name
     * as the prefix of the it's name, e.g. `parent-name:name`.
     * Useful to define additional context when same component frequently
     * used in many places.
     * Another user-case is to define a package-wide main trace and use
     * the method to create loggers that are child of the main one.
     */
    public createChild(name: string): TraceSource {
        return this.withName(`${this.name}:${name}`);
    }

    public addTraceListener(listener: TraceListener): void {
        this.on(TraceSource.eventEventName, listener.traceEvent.bind(listener));
        this.on(TraceSource.lineEventName, listener.writeLine.bind(listener));
        if (listener.flushEvents) {
            this.on(TraceSource.flushEventName, listener.flushEvents.bind(listener));
        }
    }

    public async flushEvents(): Promise<void> {
        await Promise.all(this.listeners(TraceSource.flushEventName).map(f => Promise.resolve(f())));
    }

    public writeLine(line: string): void {
        this.emit(TraceSource.lineEventName, this.name, line);
    }

    public log(logLevel: LogLevel, message: string, ...args: any[]): this {
        this.traceEvent(logLevel, 0, message, ...args);
        return this;
    }

    public traceEvent(logLevel: LogLevel, id: number, message: string, ...args: any[]): void {
        this.emit(TraceSource.eventEventName, this.name, logLevel, id, message, ...args);
    }

    public errorEvent(id: number, message: string, ...args: any[]): void {
        this.traceEvent(LogLevel.Error, id, message, ...args);
    }
    public warningEvent(id: number, message: string, ...args: any[]): void {
        this.traceEvent(LogLevel.Warning, id, message,  ...args);
    }
    public infoEvent(id: number, message: string, ...args: any[]): void {
        this.traceEvent(LogLevel.Info, id, message, ...args);
    }

    public error(message: string, ...args: any[]): this {
        this.traceEvent(LogLevel.Error, 0, message, ...args);
        return this;
    }
    public warning(message: string, ...args: any[]): this {
        this.traceEvent(LogLevel.Warning, 0, message, ...args);
        return this;
    }
    public info(message: string, ...args: any[]): this {
        this.traceEvent(LogLevel.Info, 0, message, ...args);
        return this;
    }
    public verbose(message: string, ...args: any[]): this {
        this.traceEvent(LogLevel.Debug, 0, message, ...args);
        return this;
    }
}

