import * as uuid from 'uuid';

import { Privacy, errorToString } from '@vs/vso-logging';
import { ITimedEvent } from './ITimedEvent';
import { ITelemetryEvent } from './ITelemetryEvent';
import { FaultType } from './FaultType';
import { ITelemetryFilter } from './ITelemetryFilter';

import { TelemetryPropertyNames, TelemetryPropertyValues } from './TelemetryStrings';
import { ResponseError } from 'vscode-jsonrpc';
import { Result as TelemetryResult } from './Result';
import { ITelemetryReporter } from './ITelemetryReporter';
import { ITelemetry } from './ITelemetry';

let sequence: number = 0;

function setSequence(): number {
    sequence += 1;
    return sequence;
}

export class TelemetryClass implements ITelemetry {

    private contextProperties: Record<string, string>;
    private correlationEvent: ITelemetryEvent | undefined;

    private telemetryEvents: { [key: string]: ITimedEvent; } = {};

    private filters: ITelemetryFilter[] = [];
    private telemetryReporter: ITelemetryReporter;
    private canSendSensitiveFlag: boolean = false;

    public get reporter(): ITelemetryReporter {
        return this.telemetryReporter;
    }

    public get canSendSensitiveInformation(): boolean {
        return this.canSendSensitiveFlag;
    }

    public init(
        reporter: ITelemetryReporter,
        featureName?: string,
        canSendSensitiveInformation?: boolean,
        faultSendCallbackParam?: (fault: ITelemetryEvent) => Promise<string[]>) {
        this.telemetryReporter = reporter;
        this.canSendSensitiveFlag = canSendSensitiveInformation;
        TelemetryPropertyNames.FEATURE_NAME = featureName || '';
        if (faultSendCallbackParam) {
            faultSendCallback = faultSendCallbackParam;
        }
        this.contextProperties = {};

        this.addContextProperty(TelemetryPropertyNames.SESSION_ID, uuid());
    }

    public addFilter(filter: ITelemetryFilter): void {
        this.filters.push(filter);
    }

    public removeFilter(filter: ITelemetryFilter): void {
        const idx = this.filters.indexOf(filter);
        if (idx >= 0) {
            this.filters.splice(idx, 1);
        }
    }

    public addContextProperties(
        props: Record<string, any>,
        isPII = false,
    ): this {
        for (const [ key, value ] of Object.entries(props)) {
            this.addContextProperty(key, value, isPII);
        }

        return this;
    }

    public addContextProperty(property: string, value: any, isPII = false): this {
        // no need to set `undefined` values
        if (value === undefined) {
            return this;
        }

        const valueString = String(value);

        if (isPII && !this.canSendSensitiveInformation) {
            this.contextProperties[property] = Privacy.getShortHash(valueString);
        } else {
            this.contextProperties[property] = valueString;
        }

        return this;
    }

    public removeContextProperty(property: string): void {
        delete this.contextProperties[property];
    }

    public getContextProperty(property: string): string {
        return this.contextProperties[property];
    }

    private addContextPropertiesToObject(properties?: { [key: string]: string }) {
        return Object.assign({}, this.contextProperties, properties);
    }

    private filterAndSendTelemetryEvent(eventName: string, callback: (properties?: { [key: string]: string }, measures?: { [key: string]: number }) => void,
                                                    properties?: { [key: string]: string }, measures?: { [key: string]: number }) {
        if (!this.reporter) {
            // init not called
            return;
        }

        const augmentedMeasures = Object.assign({}, measures);
        const augmentedProperties = this.addContextPropertiesToObject(properties);
        for (const filter of this.filters) {
            if (!filter.shouldSend(eventName, augmentedProperties, augmentedMeasures)) {
                return;
            }
        }

        augmentedMeasures[TelemetryPropertyNames.SEQUENCE_NUMBER] = setSequence();
        callback(augmentedProperties, augmentedMeasures);
    }

    public sendTelemetryEvent(eventName: string, properties?: { [key: string]: string }, measures?: { [key: string]: number }): void {
        const cb = (augmentedProperties?: { [key: string]: string }, augmentedMeasures?: { [key: string]: number }) => this.reporter.sendTelemetryEvent(eventName, augmentedProperties, augmentedMeasures);
        this.filterAndSendTelemetryEvent(eventName, cb, properties, measures);
    }

    public sendTelemetryErrorEvent(eventName: string, properties?: { [key: string]: string }, measures?: { [key: string]: number }, errorProps?: string[]) {
        const cb = (augmentedProperties?: { [key: string]: string }, augmentedMeasures?: { [key: string]: number }) => this.reporter.sendTelemetryErrorEvent(eventName, augmentedProperties, augmentedMeasures, errorProps);
        this.filterAndSendTelemetryEvent(eventName, cb, properties, measures);
    }

    public sendFault(eventName: string, type: FaultType, details?: string, exception?: Error, correlatedEvent?: ITelemetryEvent) {
        (new Fault(eventName, type, details, exception, correlatedEvent)).send();
    }

    public startTimedEvent(eventName: string, correlate = false): ITimedEvent {
        const timedEvent = new TimedEvent(eventName, correlate);
        // save the event to telemetry events queue
        this.telemetryEvents[timedEvent.id] = timedEvent;
        return timedEvent;
    }

    public setCorrelationEvent(correlationEvent: ITelemetryEvent) {
        this.correlationEvent = correlationEvent;
    }

    public removeCorrelationEvent(correlationEvent: ITelemetryEvent) {
        if (this.correlationEvent === correlationEvent) {
            this.correlationEvent = undefined;
        }
    }

    public correlate(telemetryEvent: ITelemetryEvent): void {
        if (this.correlationEvent) {
            telemetryEvent.correlateWith(this.correlationEvent);
        }
    }

    public async endAllPendingEvents() {
        for (let eventId of Object.keys(this.telemetryEvents)) {
            const event = this.telemetryEvents[eventId];

            await event.endIfNotSent();
            delete this.telemetryEvents[eventId];
        }
    }

    public async dispose(): Promise<void> {
        await this.reporter.dispose();
    }
}

// tslint:disable-next-line: variable-name
const Telemetry = new TelemetryClass();
export { Telemetry };

let faultSendCallback: ((fault: ITelemetryEvent) => Promise<string[]>) | undefined;

export class TelemetryEvent implements ITelemetryEvent {

    private eventName: string;
    private properties: Record<string, string>;
    private measures: Record<string, number>;
    private correlationId: string;
    protected isSent: boolean = false;
    public id: string;

    constructor(eventName: string, correlate = false) {
        this.id = uuid();
        this.eventName = eventName;
        this.properties = {};
        this.measures = {};
        this.correlationId = uuid();
        if (correlate) {
            Telemetry.correlate(this);
        }
    }

    public static create(property: string, data: {
        properties?: Record<string, string>,
        measures?: Record<string, number>,
        correlate?: boolean
    }): TelemetryEvent {
        const correlate = data ? !!data.correlate : false;
        const telemetryEvent = new TelemetryEvent(property, correlate);

        if (data.properties) {
            Object.keys(data.properties)
                .forEach(key => telemetryEvent.addProperty(TelemetryPropertyNames.FEATURE_NAME + key, data.properties![key]));
        }

        if (data.measures) {
            Object.keys(data.measures)
                .forEach(key => telemetryEvent.addMeasure(TelemetryPropertyNames.FEATURE_NAME + key, data.measures![key]));
        }

        return telemetryEvent;
    }

    public addProperty(property: string, value: any, isPII = false, unkeyed = false): this {
        // no need to set `undefined` values
        if (value === undefined) {
            return this;
        }

        const valueString = String(value);

        if (isPII && !Telemetry.canSendSensitiveInformation) {
            this.properties[property] = Privacy.getHash(valueString, unkeyed);
        } else {
            this.properties[property] = valueString;
        }

        return this;
    }

    public addProperties(
        props: Record<string, any>,
        isPII = true,
    ): this {
        for (let [ key, value ] of Object.entries(props)) {
            this.addProperty(key, value, isPII);
        }

        return this;
    }

    public addPropertyIfNotExists(property: string, value: any, isPII = false, unkeyed = false): this {
        if (!this.propertyExists(property)) {
            this.addProperty(property, value, isPII, unkeyed);
        }

        return this;
    }

    public propertyExists(property: string) {
        return property in this.properties;
    }

    public addMeasure(measure: string, value: number): void {
        this.measures[measure] = value;
    }

    public addMeasureIfNotExists(measure: string, value: number): void {
        if (this.measures[measure] === undefined) {
            this.addMeasure(measure, value);
        }
    }

    public getCorrelationId(): string {
        return this.correlationId;
    }

    public correlateWith(otherEvent: ITelemetryEvent) {
        this.correlationId = otherEvent.getCorrelationId();
        return this;
    }

    public correlateWithId(correlationId: string) {
        this.correlationId = correlationId;
        return this;
    }

    private addCommonProperties() {
        this.addProperty(TelemetryPropertyNames.EVENT_ID, this.id);
        this.addProperty(TelemetryPropertyNames.CORRELATION_ID, this.correlationId);
    }

    public send() {
        this.addCommonProperties();
        Telemetry.sendTelemetryEvent(this.eventName, this.properties, this.measures);

        this.isSent = true;
    }

    public sendAsError(errorProps?: string[]) {
        this.addCommonProperties();
        Telemetry.sendTelemetryErrorEvent(this.eventName, this.properties, this.measures, errorProps);

        this.isSent = true;
    }
}

export class Fault extends TelemetryEvent {
    private exception: any;
    constructor(eventName: string, type: FaultType, details?: string, exception?: Error, correlatedEvent?: ITelemetryEvent) {
        super(eventName);
        this.exception = exception;
        this.addProperty(TelemetryPropertyNames.FAULT_TYPE, FaultType[type]);
        if (details) {
            this.addProperty(TelemetryPropertyNames.EVENT_MESSAGE, cleanSensitiveInformation(details));
        }
        let exceptionStack = '';
        if (exception && exception instanceof ResponseError) {
            if (exception.code && typeof exception.code === 'number') {
                this.addMeasure(TelemetryPropertyNames.EVENT_EXCEPTION_CODE, exception.code);
            }
            if (exception.data && typeof exception.data === 'string') {
                // RPC response errors have the remote stack trace in the data property.
                exceptionStack += cleanSensitiveInformation(exception.data) +
                    '\n   --- End of remote exception stack trace ---\n';
            }
        }
        if (exception && exception.stack && typeof exception.stack === 'string') {
            exceptionStack += cleanSensitiveInformation(errorToString(exception)!);
        }
        if (!exceptionStack) {
            exceptionStack = 'No Stack';
        }
        this.addProperty(TelemetryPropertyNames.EVENT_EXCEPTION_STACK, exceptionStack);
        if (correlatedEvent) {
            this.correlateWith(correlatedEvent);
        }
    }

    public async send() {
        let errorProps: string[] = [];
        if (faultSendCallback) {
            errorProps = await faultSendCallback(this);
        }
        return super.sendAsError([...errorProps, TelemetryPropertyNames.EVENT_MESSAGE, TelemetryPropertyNames.EVENT_EXCEPTION_STACK]);
    }
}

export class TimedEvent extends TelemetryEvent implements ITimedEvent {

    public static readonly scopeStack: ITimedEvent[] = [];
    private startTime: number;
    private lastMarkTime: number;

    constructor(eventName: string, correlate = false, sendStartEvent = false) {
        super(eventName, correlate);

        this.startTime = (new Date()).getTime();
        this.lastMarkTime = this.startTime;
        TimedEvent.scopeStack.push(this);

        this.addProperty(TelemetryPropertyNames.EVENT_CREATION_TIME, new Date().toISOString());
        this.addProperty(TelemetryPropertyNames.EVENT_TYPE, TelemetryPropertyValues.END);

        if (sendStartEvent) {
            const startEvent = new TelemetryEvent(eventName);
            startEvent.correlateWith(this);
            startEvent.addProperty(TelemetryPropertyNames.EVENT_TYPE, TelemetryPropertyValues.START);
            startEvent.send();
        }
    }

    public markTime(markName: string, fromStart = false): number {
        let currentTime = (new Date()).getTime();
        let duration = fromStart ? (currentTime - this.startTime) : (currentTime - this.lastMarkTime);
        this.lastMarkTime = currentTime;
        this.addMeasure(markName, duration);
        return duration;
    }

    public end(result: TelemetryResult, message?: string, sendNow = true): number {
        this.addProperty(TelemetryPropertyNames.EVENT_RESULT, TelemetryResult[result]);
        if (message) {
            this.addProperty(TelemetryPropertyNames.EVENT_MESSAGE, cleanSensitiveInformation(message));
        }
        const duration = this.markTime(TelemetryPropertyNames.EVENT_DURATION, true);
        Telemetry.removeCorrelationEvent(this);
        if (sendNow) {
            this.send();
        }
        for (let i = TimedEvent.scopeStack.length - 1; i >= 0; i--) {
            if (TimedEvent.scopeStack[i] === this) {
                TimedEvent.scopeStack.splice(i, 1);
            }
        }

        return duration;
    }

    public async endIfNotSent() {
        if (this.isSent) {
            return;
        }

        await this.end(TelemetryResult.Cancel, 'Completing pending telemetry events.');
    }
}

function removeEmailAddresses(str: string): string {
    return str.replace(/[\S]+@[\S]+/gi, '[EMAIL]');
}

export function cleanSensitiveInformation(str: string): string {
    return str ? removeEmailAddresses(removePath(str, '[PATH]/')) : str;
}

function removePath(filePath: string, replacementString = ''): string {
    return filePath.replace(/([A-Za-z]:)?(\S*[\\\/])+\S*/gi, (match: string, drive: string, directory: string, offset: number, whole: string) => {
        if (/^\d{1,4}\/\d{1,2}\/\d{1,4}$/.test(match)) { // This is a date. No need to scrub.
            return match;
        } else {
            const driveAndDirectoryLength = (drive ? drive.length : 0) + directory.length;
            const fileName = match.substr(driveAndDirectoryLength);
            return replacementString + fileName;
        }
    });
}

export const propagateOffsetMarkTime = (markName: string, markEvent: ITimedEvent): void => {
    for (let i = 0; i < TimedEvent.scopeStack.length; i++) {
        const targetEvent = TimedEvent.scopeStack[i];
        if (targetEvent !== markEvent) {
            targetEvent.markTime(markName);
        }
    }
};



