'use strict';

import * as vscode from 'vscode';

export class MemoryFile implements vscode.FileStat {
    public type: vscode.FileType;
    public ctime: number;
    public mtime: number;
    public size: number;
    public data?: Uint8Array;

    constructor(public uri: vscode.Uri, public name: string) {
        this.type = vscode.FileType.File;
        this.ctime = Date.now();
        this.mtime = Date.now();
        this.size = 0;
        this.name = name;
    }
}