import { ICommandContext } from '@vs/vscode-command-framework';

import { ContactCommandUtilities } from './ContactCommandUtilities';
import { 
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';

import { ContactTreeExplorerItem } from '../ContactsProviderViewlet';

export function builder(): ICommand<boolean> {
    return new InviteContactByEmailCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.INVITE_CONTACT_BY_EMAIL, TelemetryEventNames.INVITE_CONTACT_BY_EMAIL_FAULT, 'InviteContactByEmail', 1)
class InviteContactByEmailCommand implements ICommand<boolean> {

    public async invoke(item: ContactTreeExplorerItem, context: ICommandContext): Promise<boolean> {
        return ContactCommandUtilities.inviteByEmail(item.contactModel.contact.email, item.contactModel.contact.displayName);
    }
}