'use strict';

import { vsls } from '@vs/vsls-contracts';
import { Disposable } from 'vscode';
import { ServiceInfo } from '@vs/vso-rpc';
import { IDependencies } from './contracts/IDependencies';

/**
 * Helper class providing the API to manage RPC services.
 */
export class RpcServiceHelper {

    /**
     * Registers a host RPC service and returns a disposable registration object.
     * @param service Service instance. The class should implement the service interface.
     * @param serviceInfo Service metadata.
     * @param dependencies Dependencies container. 
     * @param disposables Collection of disposable objects where the registration object will be added to.
     */
    public static async registerHostRpcService<TService>(service: TService, serviceInfo: ServiceInfo<TService>, dependencies: IDependencies, disposables?: Disposable[]): Promise<Disposable> {
        if (!service) {
            throw new Error('service argument is missing or undefined');
        }

        if (!serviceInfo) {
            throw new Error('serviceInfo argument is missing or undefined');
        }

        if (!dependencies) {
            throw new Error('dependencies argument is missing or undefined');
        }

        const serviceName = serviceInfo.name;
        if (!serviceName) {
            throw new Error('serviceInfo.serviceName is empty or undefined');
        }

        const workspaceService = dependencies.workspaceService();
        const session = dependencies.sessionContext();
        const rpcServiceHandler = dependencies.rpcServiceHandler();
        const rpcServiceRegistration = rpcServiceHandler.registerRpcService(service, serviceInfo);

        try {
            await workspaceService.registerServicesAsync([serviceName], vsls.CollectionChangeType.Add);
        } catch (err) {
            rpcServiceRegistration.dispose();
            throw err;
        }

        const result = new Disposable(async () => {
            rpcServiceRegistration.dispose();
            if (session.isStartingCollaboration || session.isCollaborating) {
                try {
                    await workspaceService.registerServicesAsync([serviceName], vsls.CollectionChangeType.Remove);
                } catch {
                    // The session has ended already and we couldn't unregister the service.
                    // Ignore this and carry on.
                }
            }
        });

        if (disposables) {
            disposables.push(result);
        }

        return result;
    }


}