import * as net from 'net';
import * as url from 'url';
import { NodeStream, Stream } from '@vs/vs-ssh';
import { ILogger, LogLevel } from '@vs/vso-logging';
import { ConnectionMode } from '@vs/vso-workspace-core';

export async function openDirectConnection(connectLink: string, logger: ILogger): Promise<[Stream, ConnectionMode]> {
    if (typeof connectLink !== 'string' || !connectLink) {
        throw new Error('Cannot connect to workspace. Direct connect link is not a valid string.');
    }

    let connectUrl: url.UrlWithStringQuery;
    try {
        connectUrl = url.parse(connectLink);
    } catch (e) {
        throw new Error(`Workspace direct connect link is not a valid URL: ${e.message || e}`);
    }

    const { protocol, hostname, port, path, query } = connectUrl;
    if (!port || !hostname || path !== '/' || query || protocol !== 'net.tcp:') {
        throw new Error('Cannot connect to workspace. Unexpected format of direct connect link.');
    }

    const portNumber = parseInt(port, 10);
    if (isNaN(portNumber)) {
        throw new Error('Cannot connect to workspace. Cannot parse port number of direct connect link.'
        );
    }

    logger.log(LogLevel.Debug, `connecting to direct link '${connectUrl}'`);
    const socket = await new Promise<net.Socket>((resolve, reject) => {
        let connected = false;
        const result = net.createConnection(portNumber, hostname, () => {
            resolve(result);
            connected = true;
        });

        result.on('close', () => {
            if (!connected) {
                reject(new Error('connection closed.'));
            }
        });

        result.on('error', (error) => {
            if (!connected) {
                reject(error);
            }
        });
    });

    logger.log(LogLevel.Debug, `creating socket SSH...`);
    return [new NodeStream(socket), ConnectionMode.Direct];
}