import { IRpcClientProxy } from './IRpcClient';
import * as rpc from 'vscode-jsonrpc';
import { ILogger, LoggerSettings } from '@vs/vso-logging';
import { CancellationError, DisposableClass } from '@vs/vscs-utils';

export abstract class RpcClientProxyBase extends DisposableClass implements IRpcClientProxy {
    protected constructor(logger: ILogger) {
        super(logger);
    }

    public abstract ensureConnectionAsync(): Promise<rpc.MessageConnection>;

    public async sendNotification(
        logger: ILogger,
        serviceAndName: string,
        args: object | any[]
    ): Promise<void> {
        const connection = await this.ensureConnectionAsync();

        // Event args may contain sensitive data, so only trace when obfuscation is disabled.
        const argsString = LoggerSettings.disableObfuscation ? JSON.stringify(args) : '';

        logger.verbose(`sendNotification-> ${serviceAndName}: ${argsString}`);
        if (Array.isArray(args)) {
            // Method-style notification: 0 or more arguments.
            connection.sendNotification(serviceAndName, ...args);
        } else {
            // Event-style notification: a single EventArgs argument.
            connection.sendNotification(serviceAndName, args);
        }
    }

    public async sendRequest<T>(
        logger: ILogger,
        serviceAndMethodName: string,
        progress: { report: (value: any) => void } | null,
        cancellationToken: rpc.CancellationToken | null,
        ...args: any[]
    ): Promise<T> {
        const cancellationMessage = 'The request was cancelled.';
        let connectionCompleted = false;
        const connection = await Promise.race<rpc.MessageConnection>([
            this.ensureConnectionAsync(),
            new Promise<rpc.MessageConnection>((resolve, reject) => {
                if (cancellationToken) {
                    if (cancellationToken.isCancellationRequested) {
                        return reject(new CancellationError(cancellationMessage));
                    }
                    cancellationToken.onCancellationRequested(() => {
                        if (!connectionCompleted) {
                            reject(new CancellationError(cancellationMessage));
                        }
                    });
                }
            }),
        ]);
        connectionCompleted = true;

        let argsString = '';
        if (LoggerSettings.disableObfuscation) {
            // Arguments may contain sensitive data, so only trace when obfuscation is disabled.
            argsString = JSON.stringify(args);
            argsString = argsString.substr(1, argsString.length - 2);
        }
        logger.verbose(`< ${serviceAndMethodName}(${argsString})`);

        const start = Date.now();

        let result: T;
        try {
            if (progress) {
                // Attach the progress handler to the args; the write filter will detect and register it.
                // Also attach the cancellation token so progress notifications can be cancelled.
                (progress as any).cancellation = cancellationToken;
                (args as any).progress = progress;
            }

            // The vscode-jsonrpc sendRequest() method can only detect a cancellation token argument
            // if it is not null.
            let sendPromise: Thenable<T>;
            if (cancellationToken) {
                sendPromise = connection.sendRequest<T>(
                    serviceAndMethodName,
                    args,
                    cancellationToken
                );
            } else {
                sendPromise = connection.sendRequest<T>(serviceAndMethodName, args);
            }

            result = await sendPromise;
        } catch (err) {
            if (this.isDisposed) {
                // // This will either block (during deactivation) or throw a connection-closed error.
                // await this.initPromise;
            }

            // The error 'data' property should be the remote stack trace.
            logger.error(`> ${serviceAndMethodName}() error: ` + err.data);
            throw err;
        }

        const time = (Date.now() - start).toFixed(1);

        // Result may contain sensitive data, so only trace when obfuscation is disabled.
        if (LoggerSettings.disableObfuscation) {
            logger.verbose(`> ${serviceAndMethodName}() => ${JSON.stringify(result)} t:${time}`);
        } else {
            logger.verbose(`> ${serviceAndMethodName}() succeeded t:${time}`);
        }

        return result;
    }
}

export class RpcClientProxy extends RpcClientProxyBase {
    private constructor(
        private readonly promise: Promise<rpc.MessageConnection | any>,
        logger: ILogger
    ) {
        super(logger);
    }

    public static fromRpcConnection(connection: rpc.MessageConnection | any, logger: ILogger) {
        return new RpcClientProxy(Promise.resolve(connection), logger);
    }

    public static fromPromise(promise: Promise<rpc.MessageConnection | any>, logger: ILogger) {
        return new RpcClientProxy(promise, logger);
    }

    public ensureConnectionAsync(): Promise<rpc.MessageConnection> {
        return this.promise;
    }

    protected initPromise: Promise<void> = Promise.resolve();
}
