import * as vscode from 'vscode';
import { IDisposable } from '@vs/vscs-utils';
import { DecoratorUtils } from './decorators';

const defaultTextColor = new vscode.ThemeColor('statusBar.foreground');
const defaultBackgroundColor = new vscode.ThemeColor('statusBar.background');

function getTextEditorLabelDecoration(label: string, longestLine: number, backgroundColor?: string, textColor?: string) {
    const textCss = DecoratorUtils.stringifyCssProperties({
        '--scroll-signal': `calc(max(100%, ${longestLine+15}ch) - 100%)`, // 0 if no horizontal scroll bar. > 0 otherwise.
        '--amplified-scroll-signal': `calc(1000000000*var(--scroll-signal))`, // 0 if no horizontal scroll bar. >> 0 otherwise. 
        '--right-for-scroll': 'calc(100% - 50vw)', // The value of 'right' when there is a horizontal scroll bar.
        '--right': `min(var(--amplified-scroll-signal), var(--right-for-scroll))`, // 0 if no horizontal scroll bar. --right-for-scroll otherwise.
        position: 'absolute',
        padding: '0ch 4ch 0ch 4ch',
        'border-radius': '.5ch',
        top: '0ch',
        right: 'var(--right)',
        'pointer-events': 'none',
        'z-index': 1
    });

    const decorationOptions: vscode.DecorationRenderOptions = {
        rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
        after: {
            contentText: label,
            textDecoration: `none; ${textCss}`,
            backgroundColor: backgroundColor || defaultBackgroundColor,
            color: textColor || defaultTextColor,
        }
    };
    return vscode.window.createTextEditorDecorationType(decorationOptions);
}

export class TextEditorLabelDecorator {

    private decoration: vscode.TextEditorDecorationType;
    private longestLine: number;
    private disposables: IDisposable[] = [];

    public constructor(private readonly textEditor: vscode.TextEditor, private readonly label: string, private readonly backgroundColor?: string, private readonly textColor?: string) {
        this.setInitialLongestLine();
        this.createDecoration();
        this.render();

        this.disposables.push(vscode.window.onDidChangeTextEditorVisibleRanges((e) => {
            if (e.textEditor === this.textEditor) {
                this.render();
            }
        }));

        // NB if the former longest line got shorter, we don't update to reflect that,
        // as that would require going through all lines of the document again to find
        // the new longest line. Detecting when the longest line gets longer is more
        // important than detecting when it gets shorter, so we decided it wasn't worth 
        // the perf impact.
        this.disposables.push(vscode.workspace.onDidChangeTextDocument((e) => {
            if (e.document.uri.toString() !== this.textEditor.document.uri.toString()) {
                return;
            }

            const prevLongestLine = this.longestLine;
            e.contentChanges.forEach(c => {
                for (let l = c.range.start.line; l <= c.range.end.line; l++) {
                    this.updateLongestLine(l);
                }
            });

            if (this.longestLine !== prevLongestLine) {
                this.createDecoration();
                this.render();
            }
        }));
    }

    private createDecoration() {
        if (this.decoration) {
            this.decoration.dispose();
        }
        this.decoration = getTextEditorLabelDecoration(this.label, this.longestLine, this.backgroundColor, this.textColor);
        this.disposables.push(this.decoration);
    }

    private setInitialLongestLine() {
        this.longestLine = 0;
        for (let i = 0; i < this.textEditor.document.lineCount; i++) {
            this.updateLongestLine(i);
        }
    }

    private updateLongestLine(lineNumber: number) {
        this.longestLine = Math.max(this.longestLine, this.textEditor.document.lineAt(lineNumber).text.replace(/\t/g, '    ').length);
    }

    private render() {
        const topLine = Math.min(...this.textEditor.visibleRanges.map(vr => vr.start.line));
        const topLeft = new vscode.Position(topLine, 0);
        const topRange = new vscode.Range(topLeft, topLeft);
        this.textEditor.setDecorations(this.decoration, [topRange]);
    }

    public dispose(): void {
        this.disposables.forEach(d => d.dispose());
    }

}
