import * as vscode from 'vscode';

import { vsls } from '@vs/vsls-contracts';
import { activitySource, ActivityType } from '@vs/activity-log';

const disposables: vscode.Disposable[] = [];

export function recordTerminalActivities(terminalService: vsls.TerminalService) {
    disposables.push(terminalService.onTerminalStarted((e: vsls.TerminalEventArgs) => {
        activitySource.fire({
            timestamp: new Date(),
            name: `${ActivityType.terminal}/share`,
            data: {
                name: e.terminal.options.name,
                readOnly: e.terminal.options.readOnlyForGuests
            }
        });
    }));
    disposables.push(terminalService.onTerminalStopped((e: vsls.TerminalEventArgs) => {
        activitySource.fire({
            timestamp: new Date(),
            name: `${ActivityType.terminal}/unshare`,
            data: {
                name: e.terminal.options.name,
                readOnly: e.terminal.options.readOnlyForGuests
            }
        });
    }));
    disposables.push(terminalService.onTerminalReadOnlyChanged((e: vsls.TerminalEventArgs) => {
        activitySource.fire({
            timestamp: new Date(),
            name: `${ActivityType.terminal}/changeAccess`,
            data: {
                name: e.terminal.options.name,
                readOnly: e.terminal.options.readOnlyForGuests
            }
        });
    }));
}

export function disposeActivityListeners() {
    for (let d of disposables) {
        d.dispose();
    }
}
