import * as vscode from 'vscode';

import * as commandHandler from './commandHandler';
import * as codeConverter from 'vscode-languageclient/lib/codeConverter';
import * as protocolConverter from 'vscode-languageclient/lib/protocolConverter';
import * as vscodeLSP from 'vscode-languageserver-protocol';

import {
    Lazy,
    IPathManager,
    Settings,
    SettingKeys,
    RestrictedOperation,
    WellKnownRestrictedOperations,
    IClientAccessCheck,
    ISessionContext
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import {
    Telemetry,
    SendOnceFilter,
    FaultType
} from '@vs/vso-telemetry';

import { createConverterExtension as createCode2ProtocolConverterExtension } from './code2protocolExtension';
import { UniversalLanguageServerProvider } from './UniversalLanguageServerProvider';
import { LanguageServiceTelemetryEventNames } from './LanguageServiceTelemetry';
import { IRpcServiceHandler } from '@vs/vso-rpc';

export const REMOTE_COMMAND_NAME: string = '_liveshare.remotecommand';
export const CODE_ACTION_ITEM_RESOLVE_COUNT: number = Number.MAX_VALUE;

let universalProvider: UniversalLanguageServerProvider;
const telemetryFilter = new SendOnceFilter(LanguageServiceTelemetryEventNames.GET_DIAGNOSTICS_FAULT);

export async function activateAsync(
    workspaceService: vsls.WorkspaceService,
    pathManager: IPathManager,
    clientAccessCheck: Lazy<IClientAccessCheck>,
    sessionContext: ISessionContext,
    rpcServiceHandler: IRpcServiceHandler
): Promise<void> {
    Telemetry.addFilter(telemetryFilter);
    universalProvider = new UniversalLanguageServerProvider(
        workspaceService,
        sessionContext,
        pathManager,
        rpcServiceHandler
    );
    await universalProvider.initAsync();
    setupHandlers(universalProvider, pathManager, clientAccessCheck);
}

export async function dispose(): Promise<void> {
    telemetryFilter.reset();
    if (universalProvider) {
        await universalProvider.dispose();
    }
}

async function getExternalDocumentAsync(pathManager: IPathManager, uri: string, token: vscode.CancellationToken): Promise<string> {
    let originalUri: vscode.Uri = pathManager.getOriginalUri(uri);

    let document = await vscode.workspace.openTextDocument(originalUri);
    return document.getText();
}

async function tryRunCommand(command: vscodeLSP.Command, args: any[]): Promise<boolean> {
    if (Settings.get<boolean>(SettingKeys.allowGuestCommandControl) || commandHandler.isSafeCommand(command.command)) {
        await vscode.commands.executeCommand(command.command, ...args);
        return true;
    } else {
        // Typescript will return a CodeAction that contains both a WorkspaceEdit and a corresponding Command (that ostensibly does the same thing as the edit).
        // If '_typescript.applyCodeActionCommand' attempted to execute, then the guest would see the WorkspaceEdit applied when running the CodeAction,
        // but then get an error saying the host doesn't allow command execution when the corresponding command attempts to run. This avoids that confusing situation.
        return (command.command === '_typescript.applyCodeActionCommand');
    }
}

async function runCodeActionCommand(uri: vscode.Uri, range: vscode.Range, commandHash: string): Promise<boolean> {
    let commandsOrCodeActions = await vscode.commands.executeCommand<(vscode.Command | vscode.CodeAction)[]>('vscode.executeCodeActionProvider', uri, range, undefined, CODE_ACTION_ITEM_RESOLVE_COUNT);
    if (commandsOrCodeActions) {
        for (let commandOrCodeAction of commandsOrCodeActions) {
            const command = typeof commandOrCodeAction.command === 'string' ? (commandOrCodeAction as vscode.Command) : (commandOrCodeAction as vscode.CodeAction).command;
            if (command && commandHandler.hashCommand(command) === commandHash) {
                return await tryRunCommand(command, command.arguments);
            }
        }
    }
}

async function runCodeLensCommand(uri: vscode.Uri, commandHash: string): Promise<boolean> {
    try {
        let codeLenses = await vscode.commands.executeCommand<vscode.CodeLens[]>('vscode.executeCodeLensProvider', uri, Number.MAX_VALUE);
        if (codeLenses) {
            for (let cl of codeLenses) {
                if (cl.command && commandHandler.hashCommand(cl.command) === commandHash) {
                    return await tryRunCommand(cl.command, cl.command.arguments);
                }
            }
        }
    } catch (e) { /* executeCodeLensProvider is a new feature that may not be supported */ }
}

const codeActionOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.CodeAction };

export function setupHandlers(languageServerProvider: UniversalLanguageServerProvider, pathManager: IPathManager, clientAccessCheck?: Lazy<IClientAccessCheck>) {
    let connection = languageServerProvider.createProtocolConnection();

    let p2c = pathManager ?
        protocolConverter.createConverter((value) => {
            return pathManager.protocol2CodeUriConverter(value);
        }) :
        protocolConverter.createConverter((value) => { return pathManager.protocol2CodeUriConverter(value); });
    let c2p = pathManager ?
        codeConverter.createConverter((value) => { return pathManager.code2ProtocolUriConverter(value); }) :
        codeConverter.createConverter((value) => { return pathManager.code2ProtocolUriConverter(value); });
    let c2pExt = createCode2ProtocolConverterExtension(c2p);

    //Storing link support capability parameter from LSP Client in order to send correct response type to definition request
    let hasLinkSupport: boolean = false;

    try {
        // Setup diagnostics
        vscode.languages.onDidChangeDiagnostics((e: vscode.DiagnosticChangeEvent) => {
            for (let uri of e.uris) {
                try {
                    let diagnostics = vscode.languages.getDiagnostics(uri);
                    let params: vscodeLSP.PublishDiagnosticsParams = {
                        uri: c2p.asUri(uri),
                        diagnostics: c2p.asDiagnostics(diagnostics)
                    };
                    connection.sendNotification(vscodeLSP.PublishDiagnosticsNotification.type.method, params);
                } catch (e) {
                    // Even if we fail to get diagnostics for one URI, we should still continue with the rest
                    Telemetry.sendFault(LanguageServiceTelemetryEventNames.GET_DIAGNOSTICS_FAULT, FaultType.NonBlockingFault, 'Unable to get diagnostics', e);
                }
            }
        });
    } catch { /* vscode.languages.onDidChangeDiagnostics is a new API that may not be available */ }

    connection.onRequest(vscodeLSP.InitializeRequest.type, (params) => {
        let capabilities: vscodeLSP.ServerCapabilities = {
            hoverProvider: true,
            definitionProvider: true,
            typeDefinitionProvider: true,
            referencesProvider: true,
            implementationProvider: true,
            completionProvider: {
                triggerCharacters: ['.']
            },
            signatureHelpProvider: {
                triggerCharacters: ['(', ',']
            },
            //documentHighlightProvider: true, // Disabled due to https://github.com/Microsoft/vscode/issues/44848
            documentSymbolProvider: true,
            workspaceSymbolProvider: true,
            codeActionProvider: true,
            //codeLensProvider: {resolveProvider: false}, // Disabled due to https://github.com/Microsoft/vscode/issues/44846
            documentFormattingProvider: true,
            documentRangeFormattingProvider: true,
            documentOnTypeFormattingProvider: {
                firstTriggerCharacter: '}',
                moreTriggerCharacter: [';', '\n']
            },
            renameProvider: true,
            documentLinkProvider: {
                resolveProvider: false
            },
            colorProvider: true,
            executeCommandProvider: { commands: []},
            codeLensProvider: {
                resolveProvider: true
            }
        };
        if(params.capabilities){
            if(params.capabilities.textDocument.definition.linkSupport){
                hasLinkSupport = true;
            }
        }

        let result: vscodeLSP.InitializeResult = {
            capabilities
        };

        return result;
    });

    connection.onCustomRequest('liveshare/externalDocument', async (params: any, token: vscode.CancellationToken) => {
        const uri = params.textDocument.uri as string;
        return await getExternalDocumentAsync(pathManager, uri, token);
    });

    connection.onCustomRequest('liveshare/load', async (params: any) => {
        return null;
    });

    connection.onCustomRequest('liveshare/diagnosticsDocument', async (params: any) => {
        let uri = params.textDocument.uri as string;
        return c2p.asDiagnostics(vscode.languages.getDiagnostics(p2c.asUri(uri)));
    });

    connection.onRequest(vscodeLSP.HoverRequest.type, async (params): Promise<vscodeLSP.Hover> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let hovers = await vscode.commands.executeCommand<vscode.Hover[]>('vscode.executeHoverProvider', uri, position);
        if (!hovers || hovers.length === 0) {
            return null;
        }

        // LSP lets us return only one hover but we may have hovers from multiple providers. Merge them into one.
        let mergedContents = hovers.map((v) => v.contents).reduce((prev, curr, index, arr) => prev.concat(curr));
        let mergedHover = new vscode.Hover(mergedContents, hovers[0].range);

        return c2pExt.asHover(mergedHover);
    });

    connection.onRequest(vscodeLSP.DefinitionRequest.type, async (params): Promise<vscodeLSP.Definition | vscodeLSP.DefinitionLink[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let definition = await vscode.commands.executeCommand<vscode.Definition | vscode.DefinitionLink[]>('vscode.executeDefinitionProvider', uri, position);

        return asDefinitionResult(definition);
    });

    function asDefinitionResult(definition: vscode.Definition | vscode.DefinitionLink[]): vscodeLSP.Definition | vscodeLSP.DefinitionLink[] {
        if (Array.isArray(definition) && definition.length > 0 && (typeof (<any>definition[0]).targetUri !== 'undefined')) {
            if(hasLinkSupport){
                return c2pExt.asDefinitionLinkResult((<vscode.DefinitionLink[]>definition));
            }
            else{
                return c2pExt.asDefinitionResultAlternate((<vscode.DefinitionLink[]>definition));
            }
            //When we switch back to using locationLink, the locationLink specific tests in lspServer.test.ts should be reenabled          
        }
        return c2pExt.asDefinitionResult((<vscode.Definition>definition));
    }

    connection.onRequest(vscodeLSP.TypeDefinitionRequest.type, async (params): Promise<vscodeLSP.Location[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let typeDefinition: vscode.Location[];
        try {
            typeDefinition = await vscode.commands.executeCommand<vscode.Location[]>('vscode.executeTypeDefinitionProvider', uri, position);
        } catch (e) { /* go to type definition is a new feature that may not be supported */ }
        return typeDefinition ? typeDefinition.map(d => c2pExt.asLocation(d)) : null;
    });

    connection.onRequest(vscodeLSP.ReferencesRequest.type, async (params): Promise<vscodeLSP.Location[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let references = await vscode.commands.executeCommand<vscode.Location[]>('vscode.executeReferenceProvider', uri, position);
        return c2pExt.asReferences(references);
    });

    connection.onRequest(vscodeLSP.ImplementationRequest.type, async (params): Promise<vscodeLSP.Definition | vscodeLSP.DefinitionLink[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let definition = await vscode.commands.executeCommand<vscode.Definition | vscode.DefinitionLink[]>('vscode.executeImplementationProvider', uri, position);

        return asDefinitionResult(definition);
    });

    connection.onRequest(vscodeLSP.DocumentHighlightRequest.type, async (params): Promise<vscodeLSP.DocumentHighlight[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let highlights = await vscode.commands.executeCommand<vscode.DocumentHighlight[]>('vscode.executeDocumentHighlights', uri, position);
        return c2pExt.asDocumentHighlights(highlights);
    });

    connection.onRequest(vscodeLSP.CompletionRequest.type, async (params): Promise<vscodeLSP.CompletionItem[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let list = await vscode.commands.executeCommand<vscode.CompletionList>('vscode.executeCompletionItemProvider', uri, position,
                                                                               params.context ? params.context.triggerCharacter : undefined);
        if (!list) {
            return undefined;
        }

        return list.items.map(item => {
            // This is a temporary hack. See https://github.com/Microsoft/vscode-languageserver-node/issues/449
            (item as any).fromEdit = true;

            // VS Code supports the range on a completion item containing both a "inserting" and "replacing" range.
            // This isn't yet part of the LSP. See https://github.com/microsoft/vscode-languageserver-node/issues/586
            if (item.range && (item.range as any).replacing) {
                item.range = (item.range as any).replacing;
            }

            return c2p.asCompletionItem(item);
        });
    });

    connection.onRequest(vscodeLSP.SignatureHelpRequest.type, async (params): Promise<vscodeLSP.SignatureHelp> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let sigHelp = await vscode.commands.executeCommand<vscode.SignatureHelp>('vscode.executeSignatureHelpProvider', uri, position);
        return c2pExt.asSignatureHelp(sigHelp);
    });

    connection.onRequest(vscodeLSP.DocumentSymbolRequest.type, async (params): Promise<vscodeLSP.SymbolInformation[]> => {
        let uri = p2c.asUri(params.textDocument.uri);

        let symbols = await vscode.commands.executeCommand<vscode.SymbolInformation[]>('vscode.executeDocumentSymbolProvider', uri);
        return c2pExt.asSymbolInformations(symbols, uri);
    });

    connection.onRequest(vscodeLSP.WorkspaceSymbolRequest.type, async (params): Promise<vscodeLSP.SymbolInformation[]> => {
        let symbols = await vscode.commands.executeCommand<vscode.SymbolInformation[]>('vscode.executeWorkspaceSymbolProvider', params.query);
        return c2pExt.asSymbolInformations(symbols, undefined);
    });

    connection.onRequest(vscodeLSP.CodeActionRequest.type, async (params): Promise<(vscodeLSP.CodeAction | vscodeLSP.Command)[]> => {
        if (clientAccessCheck &&
            !await clientAccessCheck().canPerformOperation(<any>params, codeActionOperation)) {
            return undefined;
        }

        let uri = p2c.asUri(params.textDocument.uri);
        let range = p2c.asRange(params.range);

        let commandsOrCodeActions = await vscode.commands.executeCommand<(vscode.Command | vscode.CodeAction)[]>('vscode.executeCodeActionProvider', uri, range, undefined, CODE_ACTION_ITEM_RESOLVE_COUNT);
        
        if (!commandsOrCodeActions) {
            return undefined;
        }

        return commandsOrCodeActions.map((commandOrCodeAction) => {
            if (typeof commandOrCodeAction.command === 'string') {
                return commandHandler.wrapCodeActionCommand(commandOrCodeAction as vscode.Command, uri, range, c2p, c2pExt);
            } else {
                const codeAction = commandOrCodeAction as vscode.CodeAction;
                codeAction.command = codeAction.command ? commandHandler.wrapCodeActionCommand(codeAction.command, uri, range, c2p, c2pExt) : codeAction.command;
                return c2pExt.asCodeAction(codeAction);
            }
        });
    });


    connection.onRequest(vscodeLSP.ExecuteCommandRequest.type, async (params): Promise<boolean> => {
        if (clientAccessCheck &&
            !await clientAccessCheck().canPerformOperation(<any>params, codeActionOperation)) {
            return;
        }

        let command: vscodeLSP.Command;
        let args: any[] = params.arguments || [];
        if (params.command.startsWith(REMOTE_COMMAND_NAME)) {
            // Note: this will be typically from a another non-vscode guest that hasn't translated
            // the remote command wrapping
            command = <vscodeLSP.Command> args[0];
            args = command.arguments;
        } else {
            command = <vscodeLSP.Command> params;
        }

        if (args.length > 0 && args[0] === commandHandler.REMOTE_CODE_ACTION_NAME) {
            return await runCodeActionCommand(p2c.asUri(args[2]), p2c.asRange(args[3]), args[1]);
        } else if (args.length > 0 && args[0] === commandHandler.REMOTE_CODE_LENS_NAME) {
            return await runCodeLensCommand(p2c.asUri(args[2]), args[1]);
        } else {
            return await tryRunCommand(command, args);
        }
    });

    connection.onRequest(vscodeLSP.DocumentFormattingRequest.type, async (params): Promise<vscodeLSP.TextEdit[]> => {
        let uri = p2c.asUri(params.textDocument.uri);

        let edits = await vscode.commands.executeCommand<vscode.TextEdit[]>('vscode.executeFormatDocumentProvider', uri, params.options);
        if (!edits) {
            return undefined;
        }

        return edits.map(edit => c2p.asTextEdit(edit));
    });

    connection.onRequest(vscodeLSP.DocumentRangeFormattingRequest.type, async (params): Promise<vscodeLSP.TextEdit[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let range = p2c.asRange(params.range);

        let edits = await vscode.commands.executeCommand<vscode.TextEdit[]>('vscode.executeFormatRangeProvider', uri, range, params.options);
        if (!edits) {
            return undefined;
        }

        return edits.map(edit => c2p.asTextEdit(edit));
    });

    connection.onRequest(vscodeLSP.DocumentOnTypeFormattingRequest.type, async (params): Promise<vscodeLSP.TextEdit[]> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let edits = await vscode.commands.executeCommand<vscode.TextEdit[]>('vscode.executeFormatOnTypeProvider', uri, position, params.ch, params.options);
        if (!edits) {
            return undefined;
        }

        return edits.map(edit => c2p.asTextEdit(edit));
    });

    connection.onRequest(vscodeLSP.RenameRequest.type, async (params): Promise<vscodeLSP.WorkspaceEdit> => {
        let uri = p2c.asUri(params.textDocument.uri);
        let position = p2c.asPosition(params.position);

        let workspaceEdit = await vscode.commands.executeCommand<vscode.WorkspaceEdit>('vscode.executeDocumentRenameProvider', uri, position, params.newName);
        return c2pExt.asWorkspaceEdit(workspaceEdit);
    });

    connection.onRequest(vscodeLSP.DocumentLinkRequest.type, async (params): Promise<vscodeLSP.DocumentLink[]> => {
        let uri = p2c.asUri(params.textDocument.uri);

        let links = await vscode.commands.executeCommand<vscode.DocumentLink[]>('vscode.executeLinkProvider', uri);
        if (!links) {
            return undefined;
        }

        return links.map(link => c2p.asDocumentLink(link));
    });

    connection.onRequest(vscodeLSP.DocumentColorRequest.type, async (params): Promise<vscodeLSP.ColorInformation[]> => {
        let uri = p2c.asUri(params.textDocument.uri);

        let colors: vscode.ColorInformation[];
        try {
            colors = await vscode.commands.executeCommand<vscode.ColorInformation[]>('vscode.executeDocumentColorProvider', uri);
        } catch (e) { /* color providers is a new feature that may not be supported */ }
        return colors ? colors.map(c => c2pExt.asColorInformation(c)) : colors;
    });

    connection.onRequest(vscodeLSP.ColorPresentationRequest.type, async (params): Promise<vscodeLSP.ColorPresentation[]> => {
        let context = {
            uri: p2c.asUri(params.textDocument.uri),
            range: p2c.asRange(params.range)
        };
        let color = new vscode.Color(params.color.red, params.color.green, params.color.blue, params.color.alpha);

        let colorPresentations: vscode.ColorPresentation[];
        try {
            colorPresentations = await vscode.commands.executeCommand<vscode.ColorPresentation[]>('vscode.executeColorPresentationProvider', color, context);
        } catch (e) { /* color providers is a new feature that may not be supported */ }
        return colorPresentations ? colorPresentations.map(cp => c2pExt.asColorPresentation(cp)) : colorPresentations;
    });

    connection.onRequest(vscodeLSP.CodeLensRequest.type, async (params): Promise<vscodeLSP.CodeLens[]> => {
        let uri = p2c.asUri(params.textDocument.uri);

        let codeLenses: vscode.CodeLens[];
        try {
            codeLenses = await vscode.commands.executeCommand<vscode.CodeLens[]>('vscode.executeCodeLensProvider', uri, Number.MAX_VALUE);
        } catch (e) { /* executeCodeLensProvider is a new feature that may not be supported */ }
        return codeLenses ? codeLenses.map(cl => {
            if (cl.command) {
                cl.command = commandHandler.wrapCodeLensCommand(cl.command, uri, c2p, c2pExt);
            }
            return c2p.asCodeLens(cl);
        }) : codeLenses;
    });
}
