import * as fs from 'fs';
import * as util from 'util';
import * as fse from 'fs-extra';

const mkdirAsync = util.promisify(fs.mkdir);
const openAsync = util.promisify(fs.open);
const closeAsync = util.promisify(fs.close);
const writeAsync = util.promisify(fs.write);
const chmodAsync = util.promisify(fs.chmod);
const existsAsync = util.promisify(fs.exists);
const accessAsync = util.promisify(fs.access);
const readdirAsync = util.promisify(fs.readdir);
const unlinkAsync = util.promisify(fs.unlink);

class NodeFileAccess {
    public mkdirAsync(path: string): Promise<void> {
        return mkdirAsync(path);
    }

    public mkdirSync(path: string): void {
        fs.mkdirSync(path);
    }

    public openFileAsync(filePath: string, openMode: string): Promise<number> {
        return openAsync(filePath, openMode);
    }
    public openSync(filePath: string, flags: string | number): number {
        return fs.openSync(filePath, flags);
    }

    public openAsync(filePath: string, openMode: string): Promise<number> {
        return openAsync(filePath, openMode);
    }
    public closeSync(fileDescriptor: number): void {
        fs.closeSync(fileDescriptor);
    }

    public closeAsync(fileDescriptor: number): Promise<void> {
        return closeAsync(fileDescriptor);
    }

    public writeAsync(
        fileDescriptor: number,
        contents: string,
    ): Promise<{ bytesWritten: number; buffer: string }> {
        return writeAsync(fileDescriptor, contents);
    }

    public writeFile(filePath: string, data: string): Promise<void>;
    public writeFile(
        filePath: string,
        data: string,
        callback: (err: NodeJS.ErrnoException | null) => void,
    ): void;
    public writeFile(
        filePath: string,
        data: string,
        callback?: (err: NodeJS.ErrnoException | null) => void,
    ): any {
        if (typeof callback !== 'undefined') {
            fs.writeFile(filePath, data, callback);
        } else {
            return fse.writeFile(filePath, data);
        }
    }
    public writeFileAsync(filePath: string, data: string | Buffer): Promise<void> {
        return fse.writeFile(filePath, data);
    }

    public appendFileSync(fileDescriptor: number, data: any, options?: string): void {
        fs.appendFileSync(fileDescriptor, data, options);
    }

    public chmod(
        path: string,
        mode: string | number,
        callback: (err: NodeJS.ErrnoException | null) => void,
    ): void {
        fs.chmod(path, mode, callback);
    }

    public stat(
        path: string,
        callback: (err: NodeJS.ErrnoException | null, stats: fs.Stats) => void,
    ): void {
        fs.stat(path, callback);
    }

    public statSync(path: string): fs.Stats {
        return fs.statSync(path);
    }

    public lstatSync(path: string): fs.Stats {
        return fs.lstatSync(path);
    }
    public lstat(
        path: string,
        callback: (err: NodeJS.ErrnoException | null, stats: fs.Stats) => void,
    ): void {
        fs.lstat(path, callback);
    }

    public existsSync(filePath: string): boolean {
        return fs.existsSync(filePath);
    }
    public existsAsync = existsAsync;
    public chmodAsync = chmodAsync;
    public accessAsync = accessAsync;

    public readdirSync(path: string): string[] {
        return fs.readdirSync(path);
    }

    public readdirAsync(path: string): Promise<string[]> {
        return readdirAsync(path);
    }

    public readFileSync(path: string): Buffer;
    public readFileSync(path: string, options: string): string;
    public readFileSync(filePath: string, options?: string): any {
        if (typeof options !== 'undefined') {
            return fs.readFileSync(filePath, options as string);
        } else {
            return fs.readFileSync(filePath);
        }
    }

    public readFile(path: string): Promise<Buffer>;
    public readFile(
        filePath: string,
        options: string,
        callback: (err: NodeJS.ErrnoException | null, data: string) => void,
    ): void;
    public readFile(
        filePath: string,
        options?: string,
        callback?: (err: NodeJS.ErrnoException | null, data: string) => void,
    ): any {
        if (typeof callback !== 'undefined' && typeof options !== 'undefined') {
            fs.readFile(filePath, options, callback);
        } else {
            return fse.readFile(filePath);
        }
    }

    public unlink(path: string, callback: (err: NodeJS.ErrnoException | null) => void): void {
        fs.unlink(path, callback);
    }

    public unlinkSync(path: string): void {
        fs.unlinkSync(path);
    }

    public unlinkAsync(path: string): Promise<void> {
        return unlinkAsync(path);
    }

    // FSE

    public copySync(sourcePath: string, targetPath: string): void {
        fse.copySync(sourcePath, targetPath);
    }

    public readdir(path: string): Promise<string[]>;
    public readdir(
        path: string,
        callback: (err: NodeJS.ErrnoException, files: string[]) => void,
    ): void;
    public readdir(
        path: string,
        callback?: (err: NodeJS.ErrnoException, files: string[]) => void,
    ): any {
        if (typeof callback !== 'undefined') {
            fse.readdir(path, callback as (err: NodeJS.ErrnoException, files: string[]) => void);
        } else {
            return fse.readdir(path);
        }
    }

    public remove(dir: string): Promise<void> {
        return fse.remove(dir);
    }

    public renameSync(sourcePath: string, targetPath: string): void {
        fse.renameSync(sourcePath, targetPath);
    }

    public ensureDir(path: string): Promise<void> {
        return fse.ensureDir(path);
    }

    public ensureDirAsync(path: string): Promise<void> {
        return fse.ensureDir(path);
    }

    public writeFileSync(path: string, data: any): void {
        fse.writeFileSync(path, data);
    }

    public pathExistsSync(path: string): boolean {
        return fse.pathExistsSync(path);
    }

    public access(path: string): Promise<void> {
        return fse.access(path);
    }

    public copyFileSync(src: string, dest: string) {
        return fse.copyFileSync(src, dest);
    }

    public copyFile(src: string, dest: string) {
        return fse.copyFile(src, dest);
    }

    public readJson(file: string): Promise<any> {
        return fse.readJson(file);
    }

    public writeJson(file: string, data: any, options?: fse.WriteOptions): Promise<void> {
        return fse.writeJson(file, data, options);
    }

    public createReadStream(path: string): fs.ReadStream {
        return fse.createReadStream(path);
    }

    public createWriteStream(path: string): fse.WriteStream {
        return fse.createWriteStream(path);
    }

    public pathExists(path: string): Promise<boolean> {
        return fse.pathExists(path);
    }
}

export const fileAccess = new NodeFileAccess();
