import { vsls } from '@vs/vsls-contracts';

import { IBreakpointManager } from './IBreakpointManager';
import { BreakpointManager as BreakpointManagerClass } from '@vs/liveshare-debug';

import {
    IPathManager,
} from '@vs/liveshare-core';

export class BreakpointManager implements IBreakpointManager {
    private breakpointManager: BreakpointManagerClass;

    constructor (
        private pathManager: IPathManager,
        private sourceEventService: vsls.SourceEventService) {
    }

    public async init(isSharing: boolean): Promise<void> {
        if (BreakpointManagerClass.hasVSCodeSupport()) {
            this.breakpointManager = new BreakpointManagerClass(isSharing, this.sourceEventService, this.pathManager);
            await this.breakpointManager.init();
        }
    }

    public async dispose(): Promise<void> {
        if (this.breakpointManager) {
            await this.breakpointManager.dispose();
        }
    }
}