'use strict';

import * as vscode from 'vscode';

import { vsls } from '@vs/vsls-contracts';
import {
    IInittableDisposable,
    IDependencies,
    NotebookConstants,
    IPathManager,
    Lazy,
    WellKnownRestrictedOperations,
    RestrictedOperation,
    localize, 
    workspaceSessionInfoTracker,
    ISessionContext,
    getCellId,
    assert
} from '@vs/liveshare-core';
import { TraceSource } from '@vs/vso-logging';
import { CellLanguageChangeEvent, CellMetadataChangeEvent, CellExecutionStateChangeEvent, CellOutputsChangeEvent, ContentProvider, OnDidChangeNotebookCellsArg, NotebooksService } from './notebooksService';
import { GuestCellManager } from './guestCellManager';
import { NotebookContentProvider } from './notebookContentProvider';
import { notebooksServiceBase } from './notebooksServiceBase';
import { NotebookController } from './notebookController';

const executeCellOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.ExecuteNotebookCell };

export interface IGuestNotebooksService extends IInittableDisposable {}

export class GuestNotebooksService extends notebooksServiceBase implements IGuestNotebooksService {

    private readonly service: NotebooksService;
    private pathManager: IPathManager;
    private readonly session: ISessionContext;
    private readonly workspaceAccessControlService: Lazy<vsls.WorkspaceAccessControlService>;
    private readonly trace: TraceSource;
    private waitingForCellExecutionAccess = false;
    private hasRequestedCellExecutionAccess = false;
    private cellManagers: { [relativePath: string]: GuestCellManager } = {};
    private remoteChangesQueue: Promise<void> = Promise.resolve();
    private notebookController: NotebookController;

    constructor(dependencies: IDependencies, service: NotebooksService) {
        super();
        this.service = service;
        this.pathManager = dependencies.pathManager();
        this.session = dependencies.sessionContext();
        this.workspaceAccessControlService = dependencies.workspaceAccessControlService;
        this.trace = dependencies.trace().withName('Notebooks');
    }

    public async init() {

        super.init();

        // if running on a version of VS Code without notebooks support, don't init the guest notebooks service
        if (!(typeof vscode.notebooks?.onDidChangeCellOutputs === 'function')) {
            return;
        }
        try {
            vscode.workspace.notebookDocuments;
        } catch { /* Proposed API */ return; }

        await this.initContentProviders();

        this.disposables.push(vscode.workspace.onDidOpenNotebookDocument((document: vscode.NotebookDocument) => this.onDidOpenNotebookDocument(document)));
        this.disposables.push(vscode.notebooks?.onDidChangeNotebookCells(e => this._onDidChangeNotebookCells(e)));
        this.disposables.push(this.workspaceAccessControlService().onOperationRejected(async e => {
            if (e.operation.name === WellKnownRestrictedOperations.ExecuteNotebookCell && e.operation.sessionId === workspaceSessionInfoTracker.workspaceSessionInfo.sessionNumber) {
                this.executeNotebookCellRejected(e.access);
            }
        }));
        this.disposables.push(this.workspaceAccessControlService().onOperationAccessChanged(async e => {
            if (e.operation.name === WellKnownRestrictedOperations.ExecuteNotebookCell) {
                if ((e.access == vsls.RestrictedOperationAccess.Allowed && this.hasRequestedCellExecutionAccess) || this.waitingForCellExecutionAccess) {
                    this.waitingForCellExecutionAccess = false;
                    const allowed = e.access === vsls.RestrictedOperationAccess.Allowed;
                    const message = (allowed)
                                ? localize('notebooks.executeCellsAccessGranted')
                                : localize('notebooks.executeCellsAccessDenied');
                    vscode.window.showInformationMessage(message);
                    this.notebookController.handleExecutionRequests(allowed);  
                }
            }
        }));

        if (typeof vscode.notebooks?.createNotebookController === 'function') {
            this.notebookController = new NotebookController(this.pathManager, this.service);
            this.notebookController.createNotebookController();
            this.disposables.push(this.notebookController);
        }

        this.service.onDidChangeCellOutputs((e) => this.onDidChangeCellOutputs(e));
        this.service.onDidChangeCellMetadata((e) => this.onHostDidChangeCellMetadata(e));
        this.service.onDidChangeCellLanguage((e) => this.onHostDidChangeCellLanguage(e));
        this.service.onDidChangeNotebookCells((e) => this.onHostDidChangeNotebookCells(e));
        this.service.onDidChangeCellExecutionState((e) => this.onDidChangeCellExecutionState(e));
    }

    
    private onDidChangeCellOutputs(e: CellOutputsChangeEvent) { 
        const activeEditor = vscode.window.visibleNotebookEditors.find(editor => editor.document.uri.path === e.relativePath);
        if (!activeEditor) {
            return;
        }

        e.cells.forEach(remoteCell => {
            const localCell = this.getCellFromActiveEditor(activeEditor, remoteCell.id);
            if (localCell) { 
                this.notebookController.updateOutput(localCell, [...remoteCell.outputs]);
            }
        });
    }

    private onDidChangeCellExecutionState(e: CellExecutionStateChangeEvent) {
        const activeEditor = vscode.window.visibleNotebookEditors.find(editor => editor.document.uri.path === e.relativePath);
        if (!activeEditor) {
            return;
        }

        const localCell = this.getCellFromActiveEditor(activeEditor, e.cellId);
        if (localCell) {
            this.notebookController.updateExecutionState(localCell, e.relativePath, e.executionState, e.executionSummary.success);
        }

    }

    private getCellFromActiveEditor(editor: vscode.NotebookEditor, id: string): vscode.NotebookCell {
        return editor.document.getCells().find(cell => getCellId(cell) === id);
    }

    public handleLanguageChange(notebookUri: vscode.Uri, languageId: string, id: string) {
        const relativePath = this.pathManager.localPathToRelativePath(notebookUri);
        this.service.changeCellLanguageAsync(id, languageId, relativePath);
    }

    private onDidOpenNotebookDocument(document: vscode.NotebookDocument) {
        if (!document.notebookType.startsWith(NotebookConstants.mirrorNotebookTypePrefix)) {
            vscode.window.showWarningMessage(localize('notebooks.openedWithLocalContentProvider'));
        } else {
            const relativePath = this.pathManager.localPathToRelativePath(document.uri);
            if (!this.cellManagers[relativePath]) {
                this.cellManagers[relativePath] = new GuestCellManager(document, this.pathManager, this.session.coeditingClient);
            }
        }
    }

    private onHostDidChangeNotebookCells(e: OnDidChangeNotebookCellsArg) {
        if (this.cellManagers[e.relativePath]) {
            this.remoteChangesQueue = this.remoteChangesQueue.then(() => this.cellManagers[e.relativePath].onHostDidChangeNotebookCells(e));
        }
    }

    private async _onDidChangeNotebookCells(e: vscode.NotebookCellsChangeEvent) {
        const relativePath = this.pathManager.localPathToRelativePath(e.document.uri);
        assert(!!this.cellManagers[relativePath], 'Guest should have cell manager for notebook being changed');
        if (this.cellManagers[relativePath]) {
            const changes = await this.cellManagers[relativePath].onDidChangeNotebookCells(e);
            if (changes.length !== 0) {
                this.service.applyNotebookCellChangesAsync(relativePath, changes);
            }
        }
    }

    private async executeNotebookCellRejected(access: vsls.RestrictedOperationAccess): Promise<void> {
        if (access === vsls.RestrictedOperationAccess.RejectedInReadOnlySession) {
            vscode.window.showInformationMessage(localize('notebooks.executeCellsReadOnly'));
            return;
        }

        const requestAccess = localize('notebooks.executeCellsRequestAccess');
        const response = await vscode.window.showInformationMessage(localize('notebooks.executeCellsLackingPermission'), requestAccess);
        if (response === requestAccess) {
            this.hasRequestedCellExecutionAccess = true;
            this.waitingForCellExecutionAccess = true;
            this.workspaceAccessControlService().requestOperationAccessAsync(executeCellOperation);
        } else {    // if the user doesn't ask the host for permission, we need to end all cell executions
            this.notebookController.handleExecutionRequests(false);  
        }
    }

    private async initContentProviders() {
        let hostContentProviders: ContentProvider[] = [];
        try {
            hostContentProviders = await this.service.getContentProvidersAsync();
        } catch { /* in the case that the host doesn't offer the notebooks service */ }
        hostContentProviders.forEach((provider) => {
            const mirrorNotebookType = `${NotebookConstants.mirrorNotebookTypePrefix}${provider.viewType}`;
            const contentProvider = new NotebookContentProvider(provider.viewType, this.service);
			this.disposables.push(vscode.workspace.registerNotebookContentProvider(
				mirrorNotebookType,
				contentProvider,
				{
                    transientOutputs: false,
                    transientCellMetadata: {},
                    transientDocumentMetadata: {}
                },
                {			
                    displayName: `Live Share - ${provider.displayName}`,
                    filenamePattern: provider.selector.map(selector => selector.excludeFileNamePattern ? { include: selector.filenamePattern, exclude: selector.excludeFileNamePattern } : selector.filenamePattern ),
                    exclusive: true
                }
			));
        });
    }

    private onHostDidChangeCellMetadata(e: CellMetadataChangeEvent) {
        const activeEditor = vscode.window.visibleNotebookEditors.find(editor => editor.document.uri.path === e.relativePath);
        if (!activeEditor) {
            return;
        }

        const localCell = activeEditor.document.getCells().find(cell => getCellId(cell) === e.cell.id);
        if (localCell) {
            const edit = new vscode.WorkspaceEdit();
            edit.replaceNotebookCellMetadata(activeEditor.document.uri, localCell.index, e.cell.metadata);
            vscode.workspace.applyEdit(edit);
        }
    }

    private onHostDidChangeCellLanguage(e: CellLanguageChangeEvent) {
        const activeEditor = vscode.window.visibleNotebookEditors.find(editor => editor.document.uri.path === e.relativePath);
        if (!activeEditor) {
            return;
        }
        
        const localCell = activeEditor.document.getCells().find(cell => getCellId(cell) === e.cellId);
        if (localCell && localCell.document.languageId !== e.language) {
            vscode.languages.setTextDocumentLanguage(localCell.document, e.language);
        }
    }

}
