import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { terminalEndpointBufferFactoryType, ITerminalEndpointBuffer } from '@vs/liveshare-terminals';
import { RpcProxy } from '@vs/vso-rpc';
import { RPCClient } from '@abstractions/rpcClient';
import { traceSource } from '@vs/vscode-command-framework';
import { Url } from 'url';

export function createTerminalEndpointBufferFactory(): terminalEndpointBufferFactoryType {

    const factory = async (terminalInfo: vsls.TerminalInfo) => {
        const terminalEndpointRpcClient = new RPCClient((retryCount: number) => Promise.resolve(<Url>{
            protocol: 'net.pipe:',
            hostname: 'localhost',
            pathname: `/${terminalInfo.localPipeName}`,
        }));
        terminalEndpointRpcClient.connectionOwner = 'shared-terminal';
        const terminalEndpoint = RpcProxy.create(vsls.TerminalEndpoint, terminalEndpointRpcClient, traceSource.withName(vsls.TraceSources.ClientRpcTerminalEndpoint));

        const endpointBuffer: ITerminalEndpointBuffer = {
            isDisposed: () => (<RpcProxy><any>terminalEndpoint).client.isDisposed,
            readData: (cancellationToken: vscode.CancellationToken) => {
                return terminalEndpoint.readStringAsync(cancellationToken);
            },
            writeData: (data: string, cancellationToken: vscode.CancellationToken) => {
                return terminalEndpoint.writeStringAsync(data, cancellationToken);
            }
        };

        return endpointBuffer;
    };

    return factory;
}