import * as vscode from 'vscode';
import { TraceSource } from '@vs/vso-logging';
import { Settings } from '../../Settings';
import { SettingKeys } from  '../../SettingKeys';
import { userAuthStateTracker } from '../../UserAuthStateTracker';
import { IAuthenticationProviderService } from '../AuthenticationProvider';
import { EnumUtil } from '../../utils/EnumUtil';
import { ITokenExchangeService } from './ITokenExchangeService';
import { TokenExchangeService } from './TokenExchangeService';
import { SupportedAuthProviders } from './NativeAuthProvider';
import { vsls } from '@vs/vsls-contracts';
import axios, { AxiosRequestConfig } from 'axios';

/**
 * Our authentication service for both IAuthenticationProviderService and vsls.AuthenticationCoreService
 */
export class AuthenticationProviderService implements IAuthenticationProviderService {
    private loginToken: string | undefined;
    private userInfo: vsls.UserInfo | undefined;
    private readonly authenticationChanged = new vscode.EventEmitter<vsls.AuthenticationChangedEventArgs>();
    private readonly tokenExchangeService: ITokenExchangeService;

    public constructor(private trace: TraceSource) {
        userAuthStateTracker.onUserInfoChanged(() => this.fireAuthenticationChanged());
        this.tokenExchangeService = new TokenExchangeService(trace);
    }

//#region vsls.AuthenticationCoreService implementation

    public readonly onAuthenticationChanged = this.authenticationChanged.event;

    public getCurrentUserAsync(cancellationToken?: vscode.CancellationToken): Promise<vsls.UserInfo> {
        return Promise.resolve(this.userInfo as vsls.UserInfo);
    }

    public getCurrentAuthenticatedUserAsync(cancellationToken?: vscode.CancellationToken): Promise<vsls.AuthenticatedUserInfo> {
        const authenticatedUserInfo = new vsls.AuthenticatedUserInfo();
        authenticatedUserInfo.accessToken = this.loginToken;
        authenticatedUserInfo.userInfo = this.userInfo;
        return Promise.resolve(authenticatedUserInfo);
    }

    public removeRecentCollaboratorAsync(recentCollaboratorId: string, cancellationToken?: vscode.CancellationToken): Promise<void> {
        return Promise.resolve();
    }

    public removeAllRecentCollaboratorsAsync(cancellationToken?: vscode.CancellationToken): Promise<void> {
        return Promise.resolve();
    }

//#endregion

    private fireAuthenticationChanged(): void {
        this.trace.verbose('fireAuthenticationChanged');

        const authenticationChangedEventArgs = new vsls.AuthenticationChangedEventArgs();
        authenticationChangedEventArgs.accessToken = this.loginToken as string;
        authenticationChangedEventArgs.account = this.userInfo as vsls.UserInfo;

        this.authenticationChanged.fire(authenticationChangedEventArgs);
    }

    //#region IAuthenticationProviderService support

    public async loginAsync(
        loginTokenOrCode: vsls.AuthenticationToken,
        options: vsls.AuthenticationOptions,
        userInfo: vsls.UserInfo,
        cancellationToken?: vscode.CancellationToken): Promise<vsls.UserInfo> {

        this.trace.verbose('loginAsync');

        if (!loginTokenOrCode.token) {
            throw new Error('Empty token passed');
        }

        this.loginToken = loginTokenOrCode.token!;
        this.userInfo = await getUserAuthInfo(loginTokenOrCode.token!);

        return this.userInfo;
    }

    public async loginWithExternalTokenAsync(
        externalAccountInfo: vsls.UserAccountInfo,
        externalToken: vsls.AuthenticationToken,
        options: vsls.AuthenticationOptions,
        userInfo: vsls.UserInfo,
        cancellationToken?: vscode.CancellationToken): Promise<vsls.UserInfo> {

        this.trace.verbose('loginWithExternalTokenAsync');

        if (!externalAccountInfo.providerName) {
            throw new Error('Empty provider name passed');
        }

        if (!externalToken.token) {
            throw new Error('Empty native token passed');
        }

        const providerKey = EnumUtil.getEnumKeyByEnumValue(SupportedAuthProviders, externalAccountInfo.providerName);
        const provider = (<any>SupportedAuthProviders)[providerKey];

        if (!provider) {
            throw new Error(`Provider with id ${externalAccountInfo.providerName} is not supported`);
        }

        let cascadeToken = undefined;

        try {
            cascadeToken = await this.tokenExchangeService.exchange(provider, externalToken.token);
        } catch (e) {
            this.trace.error(`External token exchange failed with ${e}. Attempting legacy exchange.`);
            cascadeToken = await this.performLegacyTokenExchange(provider, externalToken.token);
        }

        return await this.loginAsync(
            { token: cascadeToken },
            options,
            userInfo,
            cancellationToken
        );
    }

    public logoutAsync(
            options: vsls.AuthenticationOptions,
            cancellationToken?: vscode.CancellationToken): Promise<void> {
        this.trace.verbose('logoutAsync');

        this.loginToken  = undefined;
        this.userInfo  = undefined;
        return Promise.resolve();
    }

    //#endregion

    private async performLegacyTokenExchange(providerName: string, externalToken: string) : Promise<string> {
        const defaultContentType = axios.defaults.headers['Content-Type'];
        try {
            axios.defaults.headers['Content-Type'] = 'application/json';
            const requestConfig: AxiosRequestConfig = {
                headers: {
                    'Cache-Control': 'no-cache'
                },
                proxy: false,
            };

            const endpointUri = getServiceUri()?.replace('prod', 'insiders');
            const response = await axios.post(
                endpointUri + "auth/exchange",
                {
                    provider: providerName,
                    token: externalToken
                },
                requestConfig
            );

            return response.data.access_token;
        } finally {
            axios.defaults.headers['Content-Type'] = defaultContentType;
        }
    }
}

function getServiceUri() {
    return Settings.get<string>(SettingKeys.serviceUri);
}

async function getUserAuthInfo(token: string): Promise<vsls.UserInfo> {
    const options: AxiosRequestConfig = {
        headers: {
            'Authorization': `Bearer ${token}`,
            'Cache-Control': 'no-cache',
            'Content-Type': 'application/json',
        },
        proxy: false, // Disabling axios proxy support allows VS Code proxy settings to take effect.
    };

    const response = await axios.get(getServiceUri() + "api/v1.2/profile", options);
    const responseUserProfile = response.data;
    const userProfile = responseUserProfile as vsls.WorkspaceUserProfile;

    return <vsls.UserInfo> {
        id: userProfile.id,
        emailAddress: userProfile.email,
        displayName: userProfile.name,
        userName: userProfile.userName,
        avatarUri: userProfile.avatarUri,
        recentCollaborators: responseUserProfile.recentCollaborators,
        isAnonymous: responseUserProfile.isAnonymous,
        programs: responseUserProfile.programs,
        accountStatus: responseUserProfile.status
    };
}