import * as path from 'path';

import { IFileSystemStats } from '../abstractions/IFileAccess';
import { fileAccess } from '@vscode-abstractions/fileAccess';

/**
 * Async function to get the immediate children of a directory.
 */
export const readdirAsync = (dir: string): Promise<string[]> => {
    return new Promise<string[]>((resolve, reject) => {
        fileAccess.readdir(dir, (err, children) => (err ? reject(err) : resolve(children)));
    });
};

/**
 * Async function to get file or directory stats.
 *
 * @param fileOrDir File or directory path to get stats for.
 * @returns File or directory stats.
 */
export const statAsync = (fileOrDir: string): Promise<IFileSystemStats> => {
    return new Promise<IFileSystemStats>((resolve, reject) => {
        fileAccess.stat(fileOrDir, (err, stats) => (err ? reject(err) : resolve(stats)));
    });
};

/**
 * Searches for files in a directory that pass a given filter.
 *
 * @param root Returned results are paths relative to this root.
 * @param dir Starting directory for the search.
 * @param filter Optional callback to filter the files.
 */
export const findFilesAsync = async (
    root: string,
    dir: string,
    filter?: (path: string) => boolean,
): Promise<string[]> => {
    let results: string[] = [];

    let children: string[] = [];
    try {
        children = await readdirAsync(dir);
    } catch (e) {
        // Skip a directory if it couldn't be read.
    }

    for (let child of children) {
        const childPath = path.join(dir, child);

        let childStat: IFileSystemStats;
        try {
            childStat = await statAsync(childPath);
        } catch (e) {
            // Skip a child if it couldn't be read.
            continue;
        }

        if (childStat.isDirectory()) {
            const childResults = await findFilesAsync(root, childPath, filter);
            results = results.concat(childResults);
        } else {
            const childRelativePath = path.relative(root, childPath);
            if (!filter || filter(childRelativePath)) {
                results.push(childRelativePath);
            }
        }
    }

    return results;
};
