'use strict';

import * as vscode from 'vscode';
import * as RemoteTaskProvider from './remoteTaskProvider';
import { Inittable, Disposable, NotificationUtil, traceSource } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import {
    ISessionContext,
    IAccessControlManager,
    WellKnownRestrictedOperations,
    askToSignInAndReload,
    IDependencies,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IChannel } from '@vs/vso-rpc';
import { StreamChannelTerminal } from './StreamChannelTerminal';

interface WorkspaceTaskCache {
    [taskUid: string]: {
        readonly taskOnHost: vsls.WorkspaceTask,
        hostTaskExecution?: vsls.TaskExecutionMoniker,
        monitorTaskExecution?: vscode.TaskExecution,
    };
}

interface SharedTaskOutput extends vscode.Disposable {
    readonly taskOutput: vsls.TaskOutputInfo;
    readonly terminal?: vscode.Terminal;
    readonly outputChannel?: vscode.OutputChannel;
}

export default class WorkspaceTaskClient extends Inittable(Disposable(Object)) {
    private readonly trace: TraceSource;
    private readonly accessControlManager: IAccessControlManager;
    private readonly workspaceTaskService: vsls.WorkspaceTaskService;
    private readonly taskOutputService: vsls.TaskOutputService;
    private readonly sessionContext: ISessionContext;

    private readonly subscriptions: vscode.Disposable[] = [];
    private deferredInit: Promise<void> = Promise.resolve();

    private readonly taskCache: WorkspaceTaskCache = {};
    private readonly hostTaskExecutions: vsls.TaskExecutionMoniker[] = [];
    private readonly pendingTaskMonitors: [vsls.WorkspaceTask, vsls.TaskExecutionMoniker][] = [];
    private readonly taskOutputCache: { [id: string]: SharedTaskOutput } = {};

    private taskManagerContext: RemoteTaskProvider.TaskManagerContext;
    private isAwaitingTaskRunPermission: boolean;
    private isUserAskedToSignIn: boolean;

    constructor(
        dependencies: IDependencies,
        accessControlManager: IAccessControlManager,
        private readonly streamFactory: (streamMoniker: vsls.RemoteStreamMoniker) => Promise<IChannel> ) {
        super();
        this.accessControlManager = accessControlManager;
        this.workspaceTaskService = dependencies.rpcFactory(vsls.WorkspaceTaskService, vsls.TraceSources.ClientRpc);   
        this.taskOutputService = dependencies.rpcFactory(vsls.TaskOutputService, vsls.TraceSources.ClientRpc);
        this.trace = traceSource.withName('WorkspaceTaskClient');
        this.sessionContext = dependencies.sessionContext();
    }

    public async init(): Promise<void> {
        await super.init();

        this.subscriptions.push(
            vscode.tasks.onDidStartTask(async e => this.handleWorkspaceTaskStarted(e.execution)),
            vscode.tasks.onDidEndTask(e => this.handleWorkspaceTaskEnded(e.execution)),
            vscode.tasks.onDidEndTaskProcess(e => this.handleWorkspaceTaskProcessEnded(e.execution, e.exitCode)),
            this.workspaceTaskService.onTaskStarted(e => this.handleHostTaskStarted(e.task, e.taskExecution)),
            this.workspaceTaskService.onTaskTerminated(e => this.handleHostTaskTerminated(e.taskExecution)),
            this.accessControlManager.onDidRejectOperation(async e => {
                if (e.operation.name === WellKnownRestrictedOperations.RunTask) {
                    const operation = <vsls.WorkspaceTaskRestrictedOperation>(e.operation);

                    if (e.isReadOnlySession) {
                        return;
                    }

                    if (e.isCurrentUserAnonymous) {
                        await this.requestTaskRunPermissionAnonymous(operation);
                    } else {
                        await this.requestTaskRunPermission(operation);
                    }
                }
            }),
            this.accessControlManager.onDidChangeOperationAccess(async e => {
                if (e.operation.name === WellKnownRestrictedOperations.RunTask) {
                    const operation = <vsls.WorkspaceTaskRestrictedOperation>(e.operation);
                    await this.handleTaskRunPermissionChange(operation, e.access);
                }
            }),
        );

        this.deferredInit = this.deferredInit.then(() => this.initializeContext()).catch(() => { });
    }

    private async initializeContext(): Promise<void> {

        this.taskManagerContext = RemoteTaskProvider.configure(
            () => this.workspaceTaskService.getSupportedTasksAsync().catch(e => []),
            () => this.pendingTaskMonitors
        );

        this.taskOutputService.onTaskOutputShared(e => this.createTaskOutput(e.taskOutput));

        const sharedTaskOutputs = await this.taskOutputService.getTaskOutputsAsync();
        for (const taskOutput of sharedTaskOutputs) {
            await this.createTaskOutput(taskOutput);
        }

        const [hostTasks, hostTaskExecutions]: [vsls.WorkspaceTask[], vsls.TaskExecutionMoniker[]] = await Promise
            .all([
                this.workspaceTaskService.getSupportedTasksAsync(),
                this.workspaceTaskService.getTaskExecutionsAsync()
            ]);

        this.hostTaskExecutions.push(...hostTaskExecutions);

        for (const taskOnHost of hostTasks) {
            this.taskCache[taskOnHost.uniqueId] = {
                taskOnHost: taskOnHost
            };
            const hostTaskExecution = hostTaskExecutions.filter(x => x.taskUid === taskOnHost.uniqueId)[0];
            if (hostTaskExecution) {
                // launch one (at most) monitor task on join
                await this.startMonitorTask(taskOnHost, hostTaskExecution);
            }
        }
    }

    public async dispose(): Promise<void> {
        await this.deferredInit;

        this.subscriptions.forEach(d => d.dispose());

        if (this.taskManagerContext) {
            this.taskManagerContext.dispose();
        }

        Object.keys(this.taskOutputCache)
            .map((x: string) => this.taskOutputCache[x])
            .forEach(d => d.dispose());

        await super.dispose();
    }

    private async requestTaskRunPermission(operation: vsls.WorkspaceTaskRestrictedOperation) {
        const requestPermission = 'Request permission';
        const response = await NotificationUtil.showErrorMessage(
            'The host doesn\'t allow guests to run tasks.',
            { modal: false },
            { title: requestPermission }
        );

        if (response.title === requestPermission) {
            this.isAwaitingTaskRunPermission = true;
            await this.accessControlManager.requestOperationAccess({
                name: WellKnownRestrictedOperations.RunTask,
                sessionId: this.sessionContext.coeditingClient.clientID
            });
        }
    }

    private async requestTaskRunPermissionAnonymous(operation: vsls.WorkspaceTaskRestrictedOperation) {
        if (this.isUserAskedToSignIn) {
            return;
        }

        this.isUserAskedToSignIn = true;

        await askToSignInAndReload('Cannot run tasks in read-only mode (anonymous). Sign in to proceed.');

        this.isUserAskedToSignIn = false;
    }

    private async handleTaskRunPermissionChange(operation: vsls.WorkspaceTaskRestrictedOperation, access: vsls.RestrictedOperationAccess) {
        if (this.isAwaitingTaskRunPermission && access === vsls.RestrictedOperationAccess.Allowed) {
            const runTask = 'Run task';
            const response = await NotificationUtil.showInformationMessage(
                'The host has allowed guests to run tasks.',
                /* isVerbose: */ false,
                { modal: false },
                { title: runTask }
            );

            if (response.title === runTask) {
                await vscode.commands.executeCommand('workbench.action.tasks.runTask');
            }
        }
    }

    private async createTaskOutput(taskOutput: vsls.TaskOutputInfo): Promise<void> {
        switch (taskOutput.options.contentType) {
            case vsls.TaskOutputContentType.TextWithAnsiEscapeCodes:
                await this.createTaskTerminal(taskOutput);
                break;
            case vsls.TaskOutputContentType.PlainText:
                await this.createOutputChannel(taskOutput);
                break;
            default:
            // unsupported
        }
    }

    private async handleWorkspaceTaskStarted(execution: vscode.TaskExecution): Promise<void> {
        const taskDef = WorkspaceTaskClient.getTaskDefinition(execution.task);
        const taskInfo = taskDef ? this.taskCache[taskDef.taskUid] : undefined;
        if (!taskInfo) {
            // unsupported non Live Share task
            return;
        }

        this.trace.verbose(`local task started taskUid:${taskDef.taskUid} executionId:${taskDef.executionId}`);

        if (!!taskDef.executionId) {
            // This is a monitor task, started by us earlier.
            // Record the task execution instance.
            taskInfo.monitorTaskExecution = execution;
            taskInfo.hostTaskExecution = { taskUid: taskDef.taskUid, id: taskDef.executionId };
        } else {
            // User has started the task execution manually.
            // Record the task execution for bookkeeping purposes
            taskInfo.monitorTaskExecution = execution;
            // The task execution ID is unknown at this moment.
            taskInfo.hostTaskExecution = undefined;

            this.trace.verbose(`Running remote uniqueId:${taskInfo.taskOnHost.uniqueId}`);
            await this.workspaceTaskService.runTaskAsync(taskInfo.taskOnHost.uniqueId);
        }
    }

    private handleWorkspaceTaskEnded(execution: vscode.TaskExecution): void {
        const taskDef = WorkspaceTaskClient.getTaskDefinition(execution.task);
        const taskInfo = taskDef ? this.taskCache[taskDef.taskUid] : undefined;
        if (!taskInfo) {
            // unsupported non Live Share task
            return;
        }

        this.trace.verbose(`local task ended taskUid:${taskDef.taskUid} executionId:${taskDef.executionId}`);
        if (taskInfo.monitorTaskExecution === execution) {
            // Switching to the Idle state, resetting monitor task execution values
            taskInfo.monitorTaskExecution = undefined;
            taskInfo.hostTaskExecution = undefined;

            // Restart the monitor task if there's a pending host task execution enqueued
            // and it's not the same as the current one (no retries allowed)
            const pendingHostExecution = this.hostTaskExecutions.filter(x => x.taskUid === taskDef.taskUid)[0];
            if (pendingHostExecution && pendingHostExecution.id !== taskDef.executionId) {
                // launch another monitor task.
                Promise.resolve().then(() => this.startMonitorTask(taskInfo.taskOnHost, pendingHostExecution));
            }
        }
    }

    private async handleWorkspaceTaskProcessEnded(execution: vscode.TaskExecution, exitCode: number): Promise<void> {
        const taskDef = WorkspaceTaskClient.getTaskDefinition(execution.task);
        const taskInfo = taskDef ? this.taskCache[taskDef.taskUid] : undefined;
        if (!taskInfo) {
            // unsupported non Live Share task
            return;
        }

        this.trace.verbose(`local task process ended taskUid:${taskDef.taskUid} exitCode:${exitCode}`);

        if (taskInfo.monitorTaskExecution !== execution) {
            // The condition is satisfied when another task has started before this monitor has stopped.
            // It means the current task state is overriden so we can ignore this event.
            return;
        }

        if (!taskInfo.hostTaskExecution) {
            // The monitor task seems to get stopped without actually starting a task execution on the host.
            return;
        }

        // check if monitored task execution finished running on the host.
        const completed = !this.hostTaskExecutions.some(x => x.id === taskInfo.hostTaskExecution.id);
        if (!completed && (!taskDef.executionId || exitCode === 0)) {
            // terminate! the host task execution only when the broker process exited with the success code (0)
            await this.workspaceTaskService.terminateTaskAsync(taskInfo.hostTaskExecution);
        }
    }

    private async handleHostTaskStarted(taskOnHost: vsls.WorkspaceTask, taskExecution: vsls.TaskExecutionMoniker): Promise<void> {

        this.trace.verbose(`host task started uniqueId:${taskOnHost.uniqueId} taskExecution:${JSON.stringify(taskExecution)}`);

        // register the host execution for further bookkeeping and decision making
        this.hostTaskExecutions.push(taskExecution);

        let taskInfo = this.getWorkspaceTaskInfo(taskOnHost);
        if (!taskInfo.monitorTaskExecution) {
            // If idle, then simply start monitoring this execution
            taskInfo.monitorTaskExecution = await this.startMonitorTask(taskOnHost, taskExecution);
        } else if (!taskInfo.hostTaskExecution) {
            // Update the host task execution once, when it's started by the broker
            taskInfo.hostTaskExecution = taskExecution;
        }
    }

    private async handleHostTaskTerminated(execution: vsls.TaskExecutionMoniker): Promise<void> {
        this.trace.verbose(`host task terminated execution:${JSON.stringify(execution)}`);

        const index = this.hostTaskExecutions.findIndex(x => x.id === execution.id);
        if (index !== -1) {
            this.hostTaskExecutions.splice(index, 1);
        }

        const taskInfo = this.taskCache[execution.taskUid];
        if (taskInfo && taskInfo.monitorTaskExecution) {
            taskInfo.monitorTaskExecution.terminate();
        }
    }

    private async startMonitorTask(taskOnHost: vsls.WorkspaceTask, taskExecution: vsls.TaskExecutionMoniker): Promise<vscode.TaskExecution | undefined> {
        // push the given task execution into the list of pending executions so that
        // the following fetch tasks API call will return monitor tasks only.
        this.pendingTaskMonitors.push([taskOnHost, taskExecution]);
        try {
            const fetched = await vscode.tasks.fetchTasks({ type: RemoteTaskProvider.liveShareTaskType });
            for (const workspaceTask of fetched.filter(x => WorkspaceTaskClient.getTaskUid(x) === taskOnHost.uniqueId)) {
                return await vscode.tasks.executeTask(workspaceTask);
            }
        } finally {
            // remove the task execution from the stack.
            this.pendingTaskMonitors.pop();
        }
        return undefined;
    }

    private async createTaskTerminal(info: vsls.TaskOutputInfo): Promise<void> {
        if (this.taskOutputCache[info.id]) {
            this.taskOutputCache[info.id].terminal.show();
            return;
        }

        this.trace.verbose(`creating task terminal info:${JSON.stringify(info)}`);

        const taskTerminalChannel = await this.streamFactory(info.feed.streamMoniker);
        const pty = new StreamChannelTerminal(taskTerminalChannel, true);

        const terminalOptions: vscode.ExtensionTerminalOptions = {
            name: info.name,
            pty,
        };

        const terminal: vscode.Terminal = vscode.window.createTerminal(terminalOptions);
        terminal.show();

        const subscriptions = [
            this.taskOutputService.onTaskOutputClosed(e => {
                if (e.taskOutput.id === info.id) {
                    disposeTaskOutput();
                    terminal.dispose();
                }
            }),
            vscode.window.onDidCloseTerminal(t => {
                if (t === terminal) {
                    disposeTaskOutput();
                }
            })
        ];

        const disposeTaskOutput = () => {
            this.trace.verbose(`dispose task terminal info:${JSON.stringify(info)}`);

            taskTerminalChannel.dispose();
            delete this.taskOutputCache[info.id];
            subscriptions.forEach(d => d.dispose());
        };

        this.taskOutputCache[info.id] = {
            taskOutput: info,
            terminal: terminal,
            dispose: () => { disposeTaskOutput(); terminal.dispose(); }
        };
    }

    private async createOutputChannel(info: vsls.TaskOutputInfo): Promise<void> {
        if (this.taskOutputCache[info.id]) {
            this.taskOutputCache[info.id].outputChannel.show();
            return;
        }

        this.trace.verbose(`create output channel info:${JSON.stringify(info)}`);

        const sharedName = `${info.name} [Shared]`;
        const outputChannel = vscode.window.createOutputChannel(sharedName);
        outputChannel.show(/*preserveFocus:*/true);

        const streamChannel = await this.streamFactory(info.feed.streamMoniker);
        streamChannel.onDataReceived(e => {
            const data = e.toString();
            outputChannel.append(data);
        });

        const subscription = this.taskOutputService.onTaskOutputClosed(e => {
            if (e.taskOutput.id === info.id) {
                disposeTaskOutput();
                outputChannel.dispose();
            }
        });

        const disposeTaskOutput = () => {
            this.trace.verbose(`dispose output channel info:${JSON.stringify(info)}`);

            delete this.taskOutputCache[info.id];
            streamChannel.dispose();
            subscription.dispose();
        };

        this.taskOutputCache[info.id] = {
            taskOutput: info,
            outputChannel: outputChannel,
            dispose: async () => { await disposeTaskOutput(); outputChannel.dispose(); }
        };
    }

    private getWorkspaceTaskInfo(taskOnHost: vsls.WorkspaceTask) {
        const taskUid = taskOnHost.uniqueId;
        let taskInfo = this.taskCache[taskUid];
        if (!taskInfo) {
            // register the new host task for the first time
            this.taskCache[taskUid] = {
                taskOnHost: taskOnHost
            };
            taskInfo = this.taskCache[taskUid];
        }
        return taskInfo;
    }

    private static getTaskDefinition(task: vscode.Task): RemoteTaskProvider.RemoteTaskDefinition | undefined {
        if (task.definition.type === RemoteTaskProvider.liveShareTaskType) {
            return task.definition as RemoteTaskProvider.RemoteTaskDefinition;
        }
        return undefined;
    }

    private static getTaskUid(task: vscode.Task): string | undefined {
        if (task.definition.type === RemoteTaskProvider.liveShareTaskType) {
            const taskDef = task.definition as RemoteTaskProvider.RemoteTaskDefinition;
            return taskDef.taskUid;
        }
        return undefined;
    }
}