import { TimeTelemetry } from '../../telemetry/CoauthoringTelemetry';

export function getTimedArray(telemetryPrefix: string): any[] {
    const timedArray = new TimedArray(telemetryPrefix);
    return new Proxy([], {
        set: function (target, property, value) {
            // @ts-ignore
            target[property] = value;
            timedArray.arrayUpdated(target);
            return true;
        }
    });
}

// Equivalent to oldArray = newArray, but preserves the original.
export function setArray(oldArray: any[], newArray: any[]) {
    if (oldArray.length > newArray.length) {
        oldArray.splice(newArray.length);
    }
    oldArray.splice(0, newArray.length, ...newArray);
}

class TimedArray {

    private wasZeroLength = true;
    private timeAtLastZeroLength = 0;
    private telemetry: TimeTelemetry;

    public constructor(telemetryPrefix: string) {
        this.telemetry = new TimeTelemetry(telemetryPrefix,  () => {
            // In the case that the array is stuck at non-0 length when the session ends,
            // we want to ensure we capture the time it spent at non-0 length.
            this.arrayUpdated([]);
        });
    }

    public arrayUpdated(target: any[]) {
        const isZeroLength = (target.length === 0);

        if (isZeroLength && !this.wasZeroLength) {
            const timeAtNonZeroLength = (new Date()).getTime() - this.timeAtLastZeroLength;
            this.telemetry.RecordTime(timeAtNonZeroLength);
        } else if (!isZeroLength && this.wasZeroLength) {
            this.timeAtLastZeroLength = (new Date()).getTime();
        }

        this.wasZeroLength = isZeroLength;
    }

}
