import * as vscode from 'vscode';
import {  Message, ExtensionMessage, UIMessage, WindowMessages, ChatWindow, Users, UIMessageDateGroup, UIMessageGroup } from './IChatViewController';
import { ExtensionUtil } from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
const SAME_GROUP_TIME = 5 * 60; // seconds

interface MessageWithUnread extends Message {
  isUnread: boolean;
}

export default class WebviewContainer {
  private panel: vscode.WebviewPanel;

  constructor(
    private onDidDispose?: () => void
  ) {
    let baseVuePath = ExtensionUtil.getExtensionUri('webview');
    const localResourceRoots = [baseVuePath];

    if (ExtensionUtil.isNode()) {
      baseVuePath = baseVuePath.with({
        scheme: 'vscode-resource'
      });
    }

    this.panel = vscode.window.createWebviewPanel(
      'chatPanel',
      'Chat',
      vscode.ViewColumn.Beside,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
        localResourceRoots: localResourceRoots
      });

    this.panel.webview.html = getWebviewContent(baseVuePath.toString());
   
    // Handle on did dispose for webview panel
    this.panel.onDidDispose(() => {
      this.panel = null;
      this.onDidDispose();
    });
  }

  public setMessageHandler(msgHandler: (message: ExtensionMessage) => void) {
    this.panel.webview.onDidReceiveMessage((message: ExtensionMessage) =>
      msgHandler(message)
    );
  }

  public update(uiMessage: UIMessage) {
    const { messages, users, window, currentUser } = uiMessage;
    const annotated = this.getAnnotatedMessages(messages, window, currentUser);
    const groups = this.getMessageGroups(annotated, users);
    this.panel.webview.postMessage({ ...uiMessage, messages: groups });
    this.panel.title = !!window ? window.name : '';
  }

  public reveal() {
    this.panel.reveal();
  }

  public isVisible() {
    return this.panel.visible;
  }

  private getAnnotatedMessages(
    messages: WindowMessages,
    window: ChatWindow,
    currentUser: contactProtocol.Contact
  ): WindowMessages {
    if (!!window) {
      // Annotates every message with isUnread (boolean)
      const { readTimestamp } = window;
      let result: { [ts: string]: MessageWithUnread } = {};

      Object.keys(messages).forEach(ts => {
        const message = messages[ts];
        const isDifferentUser = message.userId !== currentUser.id;
        const isUnread =
          !!readTimestamp && isDifferentUser && +ts > +readTimestamp;

        result[ts] = { ...message, isUnread };
      });
      return result;
    } else {
      return messages;
    }
  }

  private getMessageGroups(input: WindowMessages, users: Users): UIMessageDateGroup[] {
    let result: { [date: string]: WindowMessages } = {};

    Object.keys(input).forEach(ts => {
      const date = new Date(+ts * 1000);
      const dateStr = this.toDateString(date);
      if (!(dateStr in result)) {
        result[dateStr] = {};
      }
      result[dateStr][ts] = input[ts];
    });

    return Object.keys(result)
      .sort((a, b) => a.localeCompare(b))
      .map(date => {
        const messages = result[date];
        const groups = this.getMessageGroupsForDate(messages, users);
        return {
          groups,
          date
        };
      });
  }

  private toDateString(date: Date): string {
    // Returns ISO-format date string for a given date
    let month = (date.getMonth() + 1).toString();
    let day = date.getDate().toString();
  
    if (month.length === 1) {
      month = `0${month}`;
    }
  
    if (day.length === 1) {
      day = `0${day}`;
    }
  
    return `${date.getFullYear()}-${month}-${day}`;
  } 

  private getMessageGroupsForDate(
    input: WindowMessages,
    users: Users
  ): UIMessageGroup[] {
    const timestamps = Object.keys(input).sort((a, b) => +a - +b); // ascending

    const initial = {
      current: {},
      groups: [] as string[]
    };

    const result = timestamps.reduce((accumulator: any, ts) => {
      const { current, groups } = accumulator;
      const message = input[ts];
      const isSameUser = current.userId
        ? message.userId === current.userId
        : false;
      const isSameTime = current.ts
        ? +ts - +current.ts < SAME_GROUP_TIME
        : false;

      if (isSameUser && isSameTime) {
        return {
          groups,
          current: {
            ...current,
            ts,
            messages: [...current.messages, message]
          }
        };
      } else {
        const currentGroup = {
          messages: [message],
          userId: message.userId,
          user: users[message.userId],
          minTimestamp: ts,
          ts,
          key: ts
        };
        return {
          groups: current.ts ? [...groups, current] : [...groups],
          current: currentGroup
        };
      }
    }, initial);

    const currentResult = result.current;
    const groupsResult = result.groups;
    return currentResult.ts ? [...groupsResult, currentResult] : groupsResult;
  }
}

function getWebviewContent(staticPath: string) {
  return `<!DOCTYPE html>
  <html lang="en">
  <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>Chat</title>

      <link href="${staticPath}/css/app.css" rel="preload" as="style">
      <link href="${staticPath}/js/chunk-vendors.js" rel="preload" as="script">
      <link href="${staticPath}/js/app.js" rel="preload" as="script">
      <link href="${staticPath}/css/app.css" rel="stylesheet">
  </head>
  <body>
      <div id="app"> </div>
      <script src="${staticPath}/js/chunk-vendors.js"> </script>
      <script src="${staticPath}/js/app.js"> </script>
  </body>
  </html>`;
}