import * as path from 'path-browserify';

import { fileAccess } from '@vscode-abstractions/fileAccess';
import { loadJSON } from '../util/loadJSON';
import { TelemetryPropertyNames } from '../telemetry/telemetryStrings';
import { extensionContext } from './ExtentionContext';
import { getPackageJSON } from './getPackageJSON';
import { throwNotInitialized } from './throwIfNotInitialized';
import { Telemetry } from '@vs/vso-telemetry';

/**
 * Function to check if the folder is LiveShare extension directory.
 * @param pathComponents
 *      - @source - the path to the folder.
 *      - @name - folder name.
 * @returns Whether the folder is the LiveShare extension directory.
 */
const isCurrentExtensionDirectory = (
    extensionRoot: string,
    pathComponents: { source: string; name: string },
): boolean => {
    const { source, name } = pathComponents;
    const folderPath = path.join(source, name);
    const packageInfo = loadJSON(path.resolve(extensionRoot, './package.json'));

    const isDirectory = fileAccess.lstatSync(folderPath).isDirectory();

    if (isDirectory) {
        return new RegExp(`^${packageInfo.publisher}\\.${packageInfo.name}-[0-9]`).test(name);
    }

    return false;
};

/**
 * Function to get all liveshare directory names form the VSCode extensions directory.
 * @param source Path to the extensions directory.
 */
const getCurrentExtensionDirectories = async () => {
    throwNotInitialized(extensionContext);

    const source = extensionContext.extensionPath;
    return (await fileAccess.readdirAsync(source))
        .map((name: string) => {
            return { source, name };
        })
        .filter(isCurrentExtensionDirectory.bind(null, source));
};

/**
 * Function to check whether the current extension is the only LiveShare extension in the VSCode extensions folder.
 * @returns Whether the current extension is the only LiveShare extension in the VSCode extensions folder.
 */
export const isExtensionBeingUpdated = async (): Promise<boolean> => {
    try {
        const directories = await getCurrentExtensionDirectories();

        return directories.length > 1;
    } catch (e) {
        return false;
    }
};

export const isFirstActivation = async (packageJSON: any): Promise<boolean> => {
    throwNotInitialized(extensionContext);

    const { globalState } = extensionContext;

    const EXT_FIRST_ACTIVATION_VERSION_KEY = `${packageJSON.name}-first-activation-flag`;

    let wasActivatedBefore = false;
    if (!globalState.get(EXT_FIRST_ACTIVATION_VERSION_KEY)) {
        await globalState.update(EXT_FIRST_ACTIVATION_VERSION_KEY, <string>packageJSON.version);
        wasActivatedBefore = true;
    }
    Telemetry.addContextProperty(TelemetryPropertyNames.IS_FIRST_ACTIVATION, wasActivatedBefore);

    return wasActivatedBefore;
};
