import * as vscode from 'vscode';
import { VscodeSessionStatusProvider, VscodeSessionStatus } from '@vs/vscode-command-framework';
import {
    sessionStateTracker,
    SessionStateChangedEventArgs
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { ILogger } from '@vs/vso-logging';

import { IPresenceStatusProvider } from './IPresenceStatusProvider';

/**
 * This class will expose a mechanism to see if the liveshare extension has had any activity
 * work giving a timeout value
 */
export class IdlePresenceStatus extends VscodeSessionStatusProvider implements IPresenceStatusProvider {
    private readonly presenseStatusChangedEvent = new vscode.EventEmitter<contactProtocol.PresenceStatus>();

    public constructor(
        trace: ILogger,
        activityTimeout: number
    ) {
        super(trace.createChild('idle-status-provider'), activityTimeout);

        // any liveshare session state changed will reset
        sessionStateTracker.onStateChanged(async (e: SessionStateChangedEventArgs) => {
            this.reset();
        });

        // subscribe to status changes.
        this.onSessionStatusChanged((e: VscodeSessionStatus) => {
            if (e === VscodeSessionStatus.Active) {
                this.presenseStatusChangedEvent.fire(contactProtocol.PresenceStatus.Available);
            } else if (e === VscodeSessionStatus.Idle) {
                this.presenseStatusChangedEvent.fire(contactProtocol.PresenceStatus.Away);
            }
        });
    }

    public get id(): string {
        return 'idle';
    }

    public get status(): contactProtocol.PresenceStatus {
        const status = this.sessionStatus;
        switch (status) {
            case VscodeSessionStatus.Idle:
                return contactProtocol.PresenceStatus.Away;

            default:
                return contactProtocol.PresenceStatus.Available;
        }
    }

    public get priority(): number {
        return 10;
    }

    public get onStatusChanged(): vscode.Event<contactProtocol.PresenceStatus> {
        return this.presenseStatusChangedEvent.event;
    }

    public reset() {
        super.reset();
    }
}