import { Settings, SettingKeys } from '@vs/liveshare-core';

export const setLivesharePresenceEnabled = (enabled: boolean): Thenable<void> => {
    return Settings.save(SettingKeys.presence, enabled);
};


/**
 * Return true if presence settings is enabled
 */
 export const isLivesharePresenceEnabled = (): boolean => {
    return Settings.get<boolean>(SettingKeys.presence) === true;
};

/**
 * Return true if the signalR Uri was defined
 */
 export const isSignalRServiceEnabled = (): boolean =>  {
    return Settings.getUri(SettingKeys.signalRServiceUri) !== undefined;
};
