'use strict';

import * as vscode from 'vscode';

import {
    ISessionContext,
    IDependencies,
    IInittableDisposable,
    IPathManager,
    WellKnownRestrictedOperations,
    Lazy,
    IClientAccessCheck,
    RestrictedOperation,
    SessionContext,
    TelemetryEventNames,
    Settings,
    SettingKeys,
    localize,
    getNotebookCellData,
    getCellId,
    sortCells,
    getNotebookHash,
    assert
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IRpcClient, RpcProxy } from '@vs/vso-rpc';
import { TraceSource } from '@vs/vso-logging';
import { FaultType, Telemetry } from '@vs/vso-telemetry';
import { CellLanguageChangeEvent, CellMetadataChangeEvent, CellExecutionStateChangeEvent, CellOutputsChangeEvent, ContentProvider, GuestCellChanges, OnDidChangeNotebookCellsArg, NotebookDataWithNotebookType } from './notebooksService';
import { HostCellManager } from './hostCellManager';
import { notebooksServiceBase } from './notebooksServiceBase';

export interface IHostNotebooksService extends IInittableDisposable {}

export class HostNotebooksService extends notebooksServiceBase implements IHostNotebooksService {

    private readonly rpcClient: IRpcClient;
    private readonly workspaceService: vsls.WorkspaceService;
    private readonly pathManager: IPathManager;
    private readonly fileService: Lazy<vsls.FileService>;
    private readonly clientAccessCheck: Lazy<IClientAccessCheck>;
    private readonly workspaceAccessControlService: Lazy<vsls.WorkspaceAccessControlService>;
    private readonly session: ISessionContext;
    private readonly trace: TraceSource;

    private allowGuestExecuteCellsForSession = false;
    private executeCellOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.ExecuteNotebookCell, isEnabled: () => this.allowGuestExecuteCells() };

    private cellManagers: { [relativePath: string]: HostCellManager } = {};

    public constructor(dependencies: IDependencies, clientAccessCheck: Lazy<IClientAccessCheck>) {
        super();
        this.rpcClient = (<RpcProxy><any>dependencies.workspaceService()).client as IRpcClient;
        this.workspaceService = dependencies.workspaceService();
        this.pathManager = dependencies.pathManager();
        this.fileService = dependencies.fileService;
        this.clientAccessCheck = clientAccessCheck;
        this.workspaceAccessControlService = dependencies.workspaceAccessControlService;
        this.session = dependencies.sessionContext();
        this.trace = dependencies.trace().withName('Notebooks');
    }

    private allowGuestExecuteCells() {
        const settingValue = Settings.get<boolean>(SettingKeys.allowGuestExecuteCells);
        return settingValue || this.allowGuestExecuteCellsForSession;
    }

    public async init() {

        super.init();

        // if running on a version of VS Code without notebooks support, don't init the host notebooks service
        if (!(typeof vscode.notebooks?.onDidChangeCellOutputs === 'function')) {
            return;
        }
        try {
            this.disposables.push(vscode.notebooks.onDidChangeCellOutputs((e) => this.onDidChangeCellOutputs(e)));
            this.disposables.push(vscode.notebooks.onDidChangeCellMetadata((e) => this.onDidChangeCellMetadata(e)));
            this.disposables.push(vscode.notebooks.onDidChangeNotebookCellExecutionState((e) => this._onDidChangeNotebookCellExecutionState(e)));
            this.disposables.push(vscode.notebooks.onDidChangeNotebookCells(e => this._onDidChangeNotebookCells(e)));
            this.disposables.push(vscode.workspace.onDidOpenNotebookDocument(nbd => this._onDidOpenNotebookDocument(nbd)));
            vscode.workspace.notebookDocuments.forEach(nbd => this.createCellManager(nbd));
        } catch { /* Proposed API */ }

        this.allowGuestExecuteCellsForSession = false;
        this.disposables.push(this.workspaceAccessControlService().onOpeationAccessRequested(e => {
            if (SessionContext.isCollaborating && e.operation.name === WellKnownRestrictedOperations.ExecuteNotebookCell) {
                this.requestExecuteCellsAccess(e.operation, e.sessionId);
            }
        }));

        this.rpcClient.addRequestMethod(
            `notebooksService.getContentProviders`,
            (token) => this.getContentProviders(token));
        this.rpcClient.addRequestMethod(
            `notebooksService.openNotebook`,
            (relativePath, notebookType, token) => this.openNotebook(relativePath, notebookType, token));
        this.rpcClient.addRequestMethodWithContext(
            `notebooksService.executeCell`,
            (range, uri, notebookType, context, token) => this.executeCell(range, uri, notebookType, context, token));
        this.rpcClient.addRequestMethodWithContext(
            `notebooksService.executeNotebook`,
            (uri, notebookType, context, token) => this.executeNotebook(uri, notebookType, context, token));
        this.rpcClient.addRequestMethod(
            `notebooksService.cancelCellExecution`,
            (range, uri, notebookType, token) => this.cancelCellExecution(range, uri, notebookType, token));
        this.rpcClient.addRequestMethod(
            `notebooksService.cancelNotebookExecution`,
            (uri, notebookType, token) => this.cancelNotebookExecution(uri, notebookType, token));
        this.rpcClient.addRequestMethod(
            `notebooksService.changeCellLanguage`,
            (cellId, language, relativePath, token) => this.changeCellLanguage(cellId, language, relativePath, token));
        this.rpcClient.addRequestMethod(
            `notebooksService.applyNotebookCellChanges`,
            (relativePath, changes, token) => this.applyNotebookCellChanges(relativePath, changes, token));
        await this.workspaceService.registerServicesAsync([`notebooksService`], vsls.CollectionChangeType.Add);
    }

    private createCellManager(notebookDocument: vscode.NotebookDocument) {
        const relativePath = this.pathManager.localPathToRelativePath(notebookDocument.uri);
        if (!this.cellManagers[relativePath]) {
            this.cellManagers[relativePath] = new HostCellManager(notebookDocument, this.pathManager, this.fileService, this.session.coeditingClient);
        }
    }

    private _onDidOpenNotebookDocument(notebookDocument: vscode.NotebookDocument) {
        this.createCellManager(notebookDocument);
    }

    private async requestExecuteCellsAccess(operation: vsls.RestrictedOperation, sessionId: number): Promise<void> {
        try {
            const allow = localize('notebooks.executeCellsAllowForSession');
            const allowAlways = localize('notebooks.executeCellsAllowAlways');
            const reject = localize('notebooks.executeCellsReject');
            const response = await vscode.window.showInformationMessage(
                localize('notebooks.executeCellsRequested'),
                allow, allowAlways, reject);

            if (response === allow) {
                this.allowGuestExecuteCellsForSession = true;
            } else if (response === allowAlways) {
                Settings.save(SettingKeys.allowGuestExecuteCells, true);
            }

            const access = (response === allow || response === allowAlways)
                            ? vsls.RestrictedOperationAccess.Allowed
                            : vsls.RestrictedOperationAccess.ExplicitlyRejectedByHost;
            await this.workspaceAccessControlService().setOperationAccessAsync(operation, access);

        } catch (err) {
            const message = `Requesting access for '${operation ? operation.name : 'null'}' operation failed: ${err.message}`;
            this.trace.error(message);
            Telemetry.sendFault(TelemetryEventNames.REQUEST_OPERATION_ACCESS_FAULT, FaultType.NonBlockingFault, message, err);
        }
    }

    private async getContentProviders(cancellationToken?: vscode.CancellationToken): Promise<ContentProvider[]> {
        const notebookContentProviders: VSCodeNotebookContentProvider[] | undefined = await vscode.commands.executeCommand('_resolveNotebookContentProvider');

        let result: ContentProvider[] = [];
		if (notebookContentProviders) {
			result = notebookContentProviders.map(provider => ({
				viewType: provider.viewType,
				displayName: provider.displayName,
				priority: 'default',
				selector: provider.filenamePattern.map(pattern => 
                                typeof pattern === 'string'
                                        ? { filenamePattern: pattern }
                                        :  { filenamePattern: pattern.include, excludeFileNamePattern: pattern.exclude })
			}));
        }

        return result;
    }

    private async openNotebook(relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<NotebookDataWithNotebookType> {
        if (await this.fileService().isExcludedAsync(relativePath, {
            enableMultipleRoots: true
        })) {
            throw new Error('Notebook unavailable');
        }

        const localUri = this.pathManager.relativePathToLocalPath(relativePath);
        const notebookDocument = await vscode.workspace.openNotebookDocument(localUri);
        this.createCellManager(notebookDocument);
        await this.cellManagers[relativePath].init();
        const result = {
            usedNotebookType: notebookDocument.notebookType !== notebookType ? notebookDocument.notebookType : undefined,
            metadata: notebookDocument.metadata,
            cells: notebookDocument.getCells().map(cell => getNotebookCellData(cell))
        };
        // Bug in VS Code
        (result as any).languages = (notebookDocument as any).languages;
        return result;
    }

    private applyNotebookCellChanges(relativePath: string, changes: GuestCellChanges[], cancellationToken?: vscode.CancellationToken) {
        assert(!!this.cellManagers[relativePath], 'Host should have cell manager for notebook guest is trying to modify');
        if (this.cellManagers[relativePath]) {
            this.cellManagers[relativePath].applyChanges(changes);
        }
    }

    public handleLanguageChange(notebookUri: vscode.Uri, languageId: string, id: string) {
        const relativePath = this.pathManager.localPathToRelativePath(notebookUri);
        const language = languageId;
        const args: CellLanguageChangeEvent = {
            relativePath,
            cellId: id,
            language
        };
        this.rpcClient.sendNotification(this.trace, 'notebooksService.didChangeCellLanguage', args);
    }

    private async _onDidChangeNotebookCells(e: vscode.NotebookCellsChangeEvent) {
        const relativePath = this.pathManager.localPathToRelativePath(e.document.uri);
        assert(!!this.cellManagers[relativePath], 'Host should have cell manager for notebook being changed');
        if (this.cellManagers[relativePath]) { 
            const cells = [...e.document.getCells()];
            const changes = await this.cellManagers[relativePath].onDidChangeNotebookCells(e);
            sortCells(cells);
            const contentHash = getNotebookHash(cells);
            const arg: OnDidChangeNotebookCellsArg = {
                relativePath,
                changes,
                contentHash
            }
            this.rpcClient.sendNotification(this.trace, 'notebooksService.didChangeNotebookCells', arg);
        }
    }

    private async ensureNotebookEditor(uri: vscode.Uri, notebookType: string) {
        if (!vscode.window.visibleNotebookEditors.find(e => e.document.uri.toString() === uri.toString())) {
            const document = await vscode.workspace.openNotebookDocument(uri);
            await vscode.window.showNotebookDocument(document, { preserveFocus: true });
        }
    }

    private async executeCell(range: { start: number, end: number }, relativePath: string, notebookType: string, context: any, cancellationToken?: vscode.CancellationToken) {
        const canExecuteCells = await this.clientAccessCheck().canPerformOperation(context, this.executeCellOperation);
        if (!canExecuteCells) {
            const isReadOnly = await this.clientAccessCheck().isClientReadOnly(context);
            const access = isReadOnly
                                ? vsls.RestrictedOperationAccess.RejectedInReadOnlySession
                                : vsls.RestrictedOperationAccess.DisabledByHostConfiguration;
            this.workspaceAccessControlService().rejectOperationAsync({ name: WellKnownRestrictedOperations.ExecuteNotebookCell, sessionId: context.GuestSessionId }, access);
            return;
        }
        const uri = this.pathManager.relativePathToLocalPath(relativePath);
        await this.ensureNotebookEditor(uri, notebookType);
        vscode.commands.executeCommand('notebook.cell.execute', range, uri);
    }

    private async executeNotebook(relativePath: string, notebookType: string, context: any, cancellationToken?: vscode.CancellationToken) {
        const canExecuteNotebook = await this.clientAccessCheck().canPerformOperation(context, this.executeCellOperation);
        if (!canExecuteNotebook) {
            const isReadOnly = await this.clientAccessCheck().isClientReadOnly(context);
            const access = isReadOnly
                                ? vsls.RestrictedOperationAccess.RejectedInReadOnlySession
                                : vsls.RestrictedOperationAccess.DisabledByHostConfiguration;
            this.workspaceAccessControlService().rejectOperationAsync({ name: WellKnownRestrictedOperations.ExecuteNotebookCell, sessionId: context.GuestSessionId }, access);
            return;
        }
        const uri = this.pathManager.relativePathToLocalPath(relativePath);
        await this.ensureNotebookEditor(uri, notebookType);
        await vscode.commands.executeCommand('notebook.execute', uri);
    }

    private async cancelCellExecution(range: { start: number, end: number }, relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken) {
        const uri = this.pathManager.relativePathToLocalPath(relativePath);
        await this.ensureNotebookEditor(uri, notebookType);
        await vscode.commands.executeCommand('notebook.cell.cancelExecution', range, uri);
    }

    private async changeCellLanguage(cellId: string, language: string, relativePath: string, cancellationToken?: vscode.CancellationToken) {
        const uri = this.pathManager.relativePathToLocalPath(relativePath);
        const activeEditor = vscode.window.visibleNotebookEditors.find(editor => editor.document.uri.path === uri.path);
        if (!activeEditor) {
            return;
        }

        const localCell = activeEditor.document.getCells().find(cell => getCellId(cell) === cellId);
        if (localCell && localCell.document.languageId !== language) {
            vscode.languages.setTextDocumentLanguage(localCell.document, language);
        }
    }

    private async cancelNotebookExecution(relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken) {
        const uri = this.pathManager.relativePathToLocalPath(relativePath);
        await this.ensureNotebookEditor(uri, notebookType);
        await vscode.commands.executeCommand('notebook.cancelExecution', uri);
    }

    private onDidChangeCellOutputs(e: vscode.NotebookCellOutputsChangeEvent) {
        const relativePath = this.pathManager.localPathToRelativePath(e.document.uri);
        const args: CellOutputsChangeEvent = {
            relativePath,
            cells: e.cells.map(cell => ({
                id: getCellId(cell),
                outputs: [...cell.outputs]
            }))
        };
        this.rpcClient.sendNotification(this.trace, 'notebooksService.didChangeCellOutputs', args);
    }
    
    private _onDidChangeNotebookCellExecutionState(e: vscode.NotebookCellExecutionStateChangeEvent) {

        const cellId = getCellId(e.cell);

        if (!cellId) {
            assert(!!cellId, 'Host should have cell id for cell whose execution state is being changed');
            return;
        }
        const executionSummary = e.cell.executionSummary;
        const relativePath = this.pathManager.localPathToRelativePath(e.cell.notebook.uri);
        const executionState = e.state;
        const args: CellExecutionStateChangeEvent = {
            relativePath,
            cellId,
            executionState,
            executionSummary: {
                success: executionSummary?.success,
                timing: {
                    startTime: executionSummary?.timing?.startTime,
                    endTime: executionSummary?.timing?.endTime
                }
            }
        };
        this.rpcClient.sendNotification(this.trace, 'notebooksService.didChangeCellExecutionState', args);
    }


    private onDidChangeCellMetadata(e: vscode.NotebookCellMetadataChangeEvent) {
        const relativePath = this.pathManager.localPathToRelativePath(e.document.uri);
        const args: CellMetadataChangeEvent = {
            relativePath,
            cell: {
                id: getCellId(e.cell),
                metadata: e.cell.metadata
            }
        };
        this.rpcClient.sendNotification(this.trace, 'notebooksService.didChangeCellMetadata', args);
    }

    public async dispose() {
        super.dispose();
        if (this.session.isStartingCollaboration || this.session.isCollaborating) {
            try {
                await this.workspaceService.registerServicesAsync([`notebooksService`], vsls.CollectionChangeType.Remove);
            } catch {}
        }
    }

}

type VSCodeNotebookContentProvider = {
    viewType: string,
    displayName: string,
    filenamePattern: (string | { include: string; exclude: string; })[]
}
