import * as rpc from 'vscode-jsonrpc';
import { ILogger, LoggerSettings } from '@vs/vso-logging';

import { RpcServiceHandler, IRpcMessageStream } from './RpcServiceHandler';
import { IRpcNotifier } from './IRpcServiceHandler';
import { sendRpcRequest } from './sendRpcRequest';
import { notifyConnections } from './RpcUtils';

export type notifyEventProviderType = (serviceAndMethod: string, event: any) => void;

/**
 * An rpc request context.
 * Note: this context will be added at the end of the cancellation request for rpc request methods.
 */
export interface IRpcRequestContext {
    readonly connection: rpc.MessageConnection;
    readonly session: number;
}

/**
 * define a class capable to host multiple rpc services
 */
export class RpcServer extends RpcServiceHandler implements IRpcNotifier {
    private rpcSessionNumber: number = 0;
    public readonly rpcConnections: rpc.MessageConnection[] = [];
    private readonly notifyEventProvider: notifyEventProviderType;

    constructor(logger: ILogger, notifyEventProvider?: notifyEventProviderType) {
        super(logger);
        const defaultNotifyProvider = (serviceAndMethod: string, e: any) => {
            notifyConnections(this.rpcConnections, serviceAndMethod, e, logger);
        };

        this.notifyEventProvider = notifyEventProvider || defaultNotifyProvider;
    }

    public registerRemoteRpcService(
        serviceName: string,
        messageConnection: rpc.MessageConnection
    ): rpc.Disposable {
        this.trace.info(`adding remote rpc service:${serviceName}`);

        const serviceNamePrefix = serviceName + '.';
        messageConnection.onNotification((method: string, ...params: any[]): void => {
            if (method.startsWith(serviceNamePrefix)) {
                this.notifyEventProvider(method, params);
            }
        });

        const disposable = this.onHandleNoneRequest(async (rpcConnection, method, ...params) => {
            if (method.startsWith(serviceNamePrefix)) {
                return await sendRpcRequest(messageConnection, method, params, this.trace);
            }
        });

        messageConnection.onClose(() => disposable.dispose());
        messageConnection.onDispose(() => disposable.dispose());
        return disposable;
    }

    public sendNotification(
        logger: ILogger,
        serviceAndName: string,
        args: object | any[]
    ): Promise<void> {
        this.notifyEventProvider(serviceAndName, args);
        return Promise.resolve();
    }

    public acceptRpcMessageStream(
        rpcMessageStream: IRpcMessageStream
    ): [rpc.MessageConnection, number] {
        const messageConnection = this.createRpcConnection(rpcMessageStream, this.trace);
        const rpcSessionNumber = this.attachConnection(messageConnection);
        return [messageConnection, rpcSessionNumber];
    }

    private attachConnection(messageConnection: rpc.MessageConnection): number {
        this.rpcConnections.push(messageConnection);
        const rpcSessionNumber = ++this.rpcSessionNumber;
        this.trace.verbose(`Rpc #${rpcSessionNumber} created`);

        messageConnection.onRequest((method: string, ...params: any[]) => {
            return this.onRequest(
                async (
                    requestHandler: rpc.GenericRequestHandler<any, any>,
                    ...requestParams: any[]
                ) => {
                    // inject rpc request context on the last argument
                    const rpcRequestContext: IRpcRequestContext = {
                        connection: messageConnection,
                        session: rpcSessionNumber,
                    };

                    requestParams.push(rpcRequestContext);

                    const result = await Promise.resolve(requestHandler(...requestParams));
                    const loggerResult = LoggerSettings.disableObfuscation
                        ? ` => ${JSON.stringify(result)}`
                        : '';
                    this.trace.verbose(`> #${rpcSessionNumber} ${method}()${loggerResult}`);

                    return result;
                },
                messageConnection,
                method,
                ...params
            );
        });

        // Add progress and generic notification support.
        messageConnection.onNotification((method: string, ...params: any[]) => {
            this.onNotification(messageConnection, method, ...params);
        });

        const removeRpc = (event: string) => {
            const index = this.rpcConnections.indexOf(messageConnection);
            if (index !== -1) {
                this.trace.verbose(`Rpc #${rpcSessionNumber} removed event:${event}`);
                this.rpcConnections.splice(index, 1);
            }
        };

        messageConnection.onClose((e) => {
            removeRpc('closed');
        });

        messageConnection.onDispose((e) => {
            removeRpc('disposed');
        });

        return rpcSessionNumber;
    }
}
