'use strict';

import * as vscode from 'vscode';
import * as uuid from 'uuid';

import {
    NotebookConstants,
    getCellId,
    getNotebookCellData
} from '@vs/liveshare-core';

import { NotebookCellMetadata } from './notebooksService';

export class CellManager {

    private remoteChanges = new Set<string>();

    constructor (protected readonly notebookDocument: vscode.NotebookDocument) {}

    protected isRemoteChange(cell: { metadata: NotebookCellMetadata }) {
        const cellId = getCellId(cell);
        return cellId ? this.remoteChanges.has(cellId) : false;
    }

    protected async addIdToCell(cell: vscode.NotebookCell) {
        const existingId = getCellId(cell);
        let id = existingId;
        if (existingId) {
            const copiedCell = this.notebookDocument.getCells().find(c => (c !== cell && getCellId(c) === existingId));
            if (copiedCell) {
                id = uuid();
            }
        } else {
            id = uuid();
        }
        const edit = new vscode.WorkspaceEdit();
        const metadata = { ...cell.metadata };
        metadata[NotebookConstants.cellIdPropertyName] = id;
        edit.replaceNotebookCellMetadata(this.notebookDocument.uri, cell.index, metadata);
        await vscode.workspace.applyEdit(edit);
    }

    protected async deleteCell(cell: vscode.NotebookCell) {
        const cellId = getCellId(cell);
        const edit = new vscode.WorkspaceEdit();
        const range = new vscode.NotebookRange(cell.index, cell.index + 1);
        edit.replaceNotebookCells(this.notebookDocument.uri, range, []);
        this.remoteChanges.add(cellId);
        await vscode.workspace.applyEdit(edit);
        this.remoteChanges.delete(cellId);
    }

    protected async addCells(index: number, cells: vscode.NotebookCellData[]) {
        const edit = new vscode.WorkspaceEdit();
        cells.forEach(c => this.remoteChanges.add(getCellId(c)));
        const range = new vscode.NotebookRange(index, index);
        edit.replaceNotebookCells(this.notebookDocument.uri, range, cells);
        await vscode.workspace.applyEdit(edit);
        cells.forEach(c => this.remoteChanges.delete(getCellId(c)));
    }

    protected async moveCell(cell: vscode.NotebookCell, newIndex: number) { 
        const cellData = getNotebookCellData(cell);
        const cellId = getCellId(cell);
        const edit = new vscode.WorkspaceEdit();
        const newIndexRange = new vscode.NotebookRange(newIndex, newIndex);
        const cellIndexRange = new vscode.NotebookRange(cell.index, cell.index + 1);
        edit.replaceNotebookCells(this.notebookDocument.uri, newIndexRange, [cellData]);
        edit.replaceNotebookCells(this.notebookDocument.uri, cellIndexRange, []);
        this.remoteChanges.add(cellId);
        await vscode.workspace.applyEdit(edit);
        this.remoteChanges.delete(cellId);
    }

}
