import { CancellationToken, Progress } from 'vscode';
import { Signal, timeoutPromise, wait } from '@vs/vscs-utils';
import { TraceSource } from '@vs/vso-logging';
import { ErrorCodes } from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';

/**
 * Class to batch/cache the liveshare file service
 */
export class FileServiceCache {
    private readonly listServiceCache: QueryServiceCache<vsls.FileInfo, vsls.FileListOptions>;
    private readonly readTextCache: QueryServiceCache<vsls.FileTextInfo, vsls.FileReadOptions>;

    constructor(
        fileService: vsls.FileService,
        trace: TraceSource) {
        
        let totalBatches = 0;
        let totalCaches = 0;
        let currentCaches = 0;
        const onQueryCached = (path: string) => {
            ++totalCaches;
            ++currentCaches;
            if (currentCaches === 5) {
                trace.verbose(`totalCaches:${totalCaches} totalBatches:${totalBatches}`);
                currentCaches = 0;
            }
        };

        this.listServiceCache = new QueryServiceCache<vsls.FileInfo, vsls.FileListOptions>(
            (paths, options, ct) => {
                totalBatches += paths.length;
                return fileService.listAsync(paths, options, ct);
            },
            onQueryCached,
            trace.createChild('list'));

        let supportReadBatchCache = true;
        const nonReadBatchCallback = (paths: string[], options: vsls.FileReadOptions, ct?: CancellationToken) =>
            Promise.all(paths.map(path => fileService.readTextAsync(path, options, ct)));

        this.readTextCache = new QueryServiceCache<vsls.FileTextInfo, vsls.FileReadOptions>(
            async (paths, options, ct) => {
                totalBatches += paths.length;
                if (!supportReadBatchCache) {
                    return await nonReadBatchCallback(paths, options, ct);
                }

                try {
                    let progressResults: vsls.FileTextInfo[] = [];
                    const fileTextProgress: Progress<vsls.ReadTextResult> = {
                        report: (progress: vsls.ReadTextResult) => {
                            progressResults = progressResults.concat(progress.results);
                        }
                    };

                    let results = await fileService.readTextWithProgressAsync(paths, options, fileTextProgress);
                    results = results.concat(progressResults);
                    if (results.length !== paths.length) {
                        throw new Error('Invalid results -> readTextWithProgressAsync');
                    }
                    
                    return results;
                } catch (e) {
                    if (e.code === ErrorCodes.MethodNotFound) {
                        supportReadBatchCache = false;
                        return await nonReadBatchCallback(paths, options, ct);
                    }

                    throw e;
                }
            },
            onQueryCached,
            trace.createChild('readText'));
    
        fileService.onFilesChanged(e => {
            e.changes.forEach(change => {
                let changePath = change.path;
                if (!changePath.startsWith('/')) {
                    changePath = '/' + changePath;
                }

                this.invalidateCache(changePath);
            });
        });
    }

    public invalidateCache(path: string) {
        this.listServiceCache.invalidateCache(path);
        this.readTextCache.invalidateCache(path);
    }

    public listAsync(
        paths: string[],
        options: vsls.FileListOptions,
        lifeTime?: number,
        cancellationToken?: CancellationToken): Promise<vsls.FileInfo[]> {
        
        return this.listServiceCache.query(paths, options, lifeTime, cancellationToken);
    }

    public readTextAsync(
        paths: string[],
        options: vsls.FileReadOptions,
        lifeTime?: number,
        cancellationToken?: CancellationToken): Promise<vsls.FileTextInfo[]> {
            return this.readTextCache.query(paths, options, lifeTime, cancellationToken);
    }
}

/**
 * Definition of query batch in progress.
 */
interface QueryPathCache {
    queryPaths: string[];
    numberOfQueries: number;
}

/**
 * Definition a query info cache.
 */
interface QueryInfoCache<R> {
    // the promise result
    resultSignal: Signal<R>;
    // if this cache would expire
    expiredTime?: number;
    // if the cache is invalidated
    invalidated?: boolean;
}

/**
 * Class to help caching/batching a pattern of a service that allows
 * batching a method to receive multiple results.
 */
class QueryServiceCache<R, O> {
    private readonly cacheInfos = new Map<string, QueryInfoCache<R>>();
    private readonly queryCache = new Map<string, QueryPathCache>();

    constructor(
        private readonly serviceCallback: (paths: string[],options: O, cancellationToken?: CancellationToken) => Promise<R[]>,
        private readonly onQueryCached: (path: string) => void,
        private readonly trace: TraceSource) {
    }

    /**
     * Force to invalidate a set of paths.
     */
    public invalidateCache(path: string) {
        const affectedKeys = Array.from(this.cacheInfos.keys()).filter(key => key.startsWith(path));
        if (affectedKeys.length > 0) {
            this.trace.verbose(`invalidate cache for path:${path} count:${affectedKeys.length}`);
            affectedKeys.forEach(key => {
                const cacheInfo = this.cacheInfos.get(key);
                if (cacheInfo) {
                    if (cacheInfo.resultSignal.isFulfilled) {
                        this.cacheInfos.delete(key);
                    } else {
                        cacheInfo.invalidated = true;
                    }
                }            
            });
        }
    }

    public async query(
        paths: string[],
        options: O,
        lifeTime?: number,
        cancellationToken?: CancellationToken): Promise<R[]> {
        const queryPaths: string[] = [];

        const now = Date.now();
        const expiredTime: number | undefined = lifeTime ? now + lifeTime : undefined;

        let cacheInfos = paths.map(path => {
            const key = cacheKey(path, options);
            const cacheInfo = this.cacheInfos.get(key);
            if (!cacheInfo || (cacheInfo.expiredTime &&  now > cacheInfo.expiredTime)) {
                queryPaths.push(path);
            } else {
                this.onQueryCached(path);
                return cacheInfo;
            }
        });

        if (queryPaths.length > 0) {
            // we found at least one query path that we would need to be resolved remotely
            let index = 0;
            cacheInfos = cacheInfos.map(cacheInfo => {
                if (!cacheInfo) {
                    cacheInfo = {
                        resultSignal: new Signal<R>(),
                        expiredTime,
                    };

                    const key = cacheKey(queryPaths[index++], options);
                    this.cacheInfos.set(key, cacheInfo);
                }

                return cacheInfo;
            });

            const optionsKey = JSON.stringify(options);
            let queryPathsCache = this.queryCache.get(optionsKey);
            if (!queryPathsCache) {
                queryPathsCache = {
                    queryPaths,
                    numberOfQueries: 1
                };
                this.queryCache.set(optionsKey, queryPathsCache);
                // short sleep to allow other calls to batch more paths to query
                await wait(5);

                this.queryCache.delete(optionsKey);
                try {
                    this.trace.verbose(`flush query paths count:${queryPaths.length} numberOfQueries:${queryPathsCache.numberOfQueries}`);         
                    const queryResults = await this.serviceCallback(queryPaths, options, cancellationToken);
                    index = 0;
                    queryResults.forEach(result => {
                        const key = cacheKey(queryPaths[index++], options);
                        const cacheInfo = this.cacheInfos.get(key);
                        if (cacheInfo) {
                            cacheInfo.resultSignal.resolve(result);
                            if (cacheInfo.invalidated) {
                                this.cacheInfos.delete(key);
                            }
                        }
                    });
                }
                catch(err) {
                    queryPaths.forEach(queryPath => {
                        const key = cacheKey(queryPath, options);
                        const cacheInfo = this.cacheInfos.get(key);
                        if (cacheInfo) {
                            cacheInfo.resultSignal.reject(err);
                            this.cacheInfos.delete(key);
                        }                        
                    });
                }    
            } else {
                // another call will process this query request and so
                // the promise will be full filled later
                queryPathsCache.numberOfQueries++;
                queryPathsCache.queryPaths.push(...queryPaths);
            }
        }

        const results = await Promise.all(cacheInfos.map(i => i.resultSignal.promise));
        if (lifeTime) {
            wait(lifeTime).then(() => {
                this.removeExpiredCacheInfos();
            });
        }

        return results;
    }

    private removeExpiredCacheInfos() {
        const now = Date.now();
        const keysExpired = Array.from(this.cacheInfos.entries())
            .filter(entry => entry[1].expiredTime && now > entry[1].expiredTime && entry[1].resultSignal.isFulfilled)
            .map(entry => entry[0]);
        if (keysExpired.length > 0) {
            this.trace.verbose(`removing expired caches count:${keysExpired.length}`);
            for (const key of keysExpired) {
                this.cacheInfos.delete(key);
            }
        }
    }
}

function cacheKey<O>(path: string, options: O) {
    return `${path}-${JSON.stringify(options)}`;
}