import * as path from 'path';
import * as buffer from 'buffer';
import { LogLevel, TraceSource } from '@vs/vso-logging';
import { RpcErrorCodes } from '@vs/vso-rpc';

import { traceSource } from '@vs/vscode-command-framework';

import { vsls } from '@vs/vsls-contracts';
import * as url from 'url';
import { IWorkspaceProvider } from './IWorkspaceProvider';
import { IWorkspaceFileSystemProvider } from './IWorkspaceFileSystemProvider';

import { SessionPromise, SessionState } from '../SessionTypes';
import { ISessionContext } from '../ISessionContext';
import { sessionStateTracker } from '../SessionStateTracker';
import { Lazy } from '../Lazy';
import { Settings } from '../Settings';
import { PathUtil } from '../utils/PathUtil';
import { PathManager } from '../PathManager';
import { CoauthoringTelemetry, Event as CoauthoringTelemetryEvents } from '../telemetry/CoauthoringTelemetry';
