import { getExpService } from '../exp/ExperimentationService';
import { Mutex } from '@vs/vscs-utils';

/**
 * Amount of time the file cache will force to be expired.
 */
const fileCacheTimeExpired = 30000;

/**
 * Keys corresponding to both vscode.FileSystemError values and VSLS fileError strings.
 */
const enum FileError {
    FileNotFound = 'FileNotFound',
    FileExists = 'FileExists',
    NoPermissions = 'NoPermissions',
    FileNotADirectory = 'FileNotADirectory',
    FileIsADirectory = 'FileIsADirectory',
    FileTooLarge = 'FileTooLarge',
    FileNotAvailable = 'FileNotAvailable',
}

const enum FileOperation {
    Read,
    Stat
}

const binaryPreamble = [
    0x4D, 0x58, 0x90, 0x00, 0x03, 0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0x00, 0x00,
    0xB8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0x00, 0x00, 0x00,
    0x0E, 0x1F, 0xBA, 0x0E, 0x00, 0xB4, 0x09, 0xCD, 0x21, 0xB8, 0X01, 0x4C, 0xCD, 0x21, 0x54, 0x68
];

export function getBinaryPreamble(): Buffer {
    return buffer.Buffer.from(binaryPreamble);
}

export class WorkspaceProvider implements IWorkspaceFileSystemProvider {
    public _version: 8 = 8; // tslint:disable-line
    private currentConnectionStatus: vsls.WorkspaceConnectionStatus;
    private readonly trace: TraceSource;
    private onFilesChangedEmitter = new vscode.EventEmitter<vscode.FileChangeEvent[]>();
    private readonly eventRegistrations: vscode.Disposable[] = [];
    private readonly workspaceProviders: IWorkspaceProvider[] = [];
    private isDisposed: boolean = false;
    private multiRootWorkspaceEnabled: boolean = true;
    private readonly uriPrefix = Settings.scheme + ':';
    private generation = 0; // Each time this provider is re-registered with VSCode by fileSystemManager, we increase its generation.
    private workspaceFile: MemoryFile;
    private fileServiceCache: FileServiceCache;
    private enableFileServiceCache: boolean | undefined;
    private enableFileServiceCacheMutex = new Mutex();
    private fileOperationStartedOnce: Map<FileOperation, Boolean>; // Tracks if the operation has been started before

    /**
     * An event to signal that a resource has been created, changed, or deleted. This
     * event should fire for resources that are being [watched](#FileSystemProvider2.watch)
     * by clients of this provider.
     */
    public readonly onDidChangeFile: vscode.Event<vscode.FileChangeEvent[]> = this.onFilesChangedEmitter.event;

    public constructor(
        private workspaceService: vsls.WorkspaceService,
        private fileService: Lazy<vsls.FileService>,
        private sessionContext: ISessionContext) {
        this.trace = traceSource.withName(vsls.TraceSources.ClientFileProvider);
        this.workspaceService.onConnectionStatusChanged(
            this.onWorkspaceConnectionStatusChanged, this, this.eventRegistrations);
        this.fileOperationStartedOnce = new Map([
            [FileOperation.Stat, false],
            [FileOperation.Read, false]
        ])
    }

    public init() {
        this.fileService().onFilesChanged(this.onFilesChanged, this, this.eventRegistrations);
    }

    public registerWorkspaceProvider(workspaceProvider: IWorkspaceProvider) {
        this.workspaceProviders.push(workspaceProvider);
    }

    public fireFilesChanged(changes: vscode.FileChangeEvent[]) {
        this.onFilesChangedEmitter.fire(changes);
    }

    private onWorkspaceConnectionStatusChanged(e: vsls.WorkspaceConnectionStatusChangedEventArgs) {
        this.currentConnectionStatus = e.connectionStatus;
    }

    /*
     * For the first file, the promise we are waiting for is different than 
     * when the rest of the files are read. This accelerates loading of the first
     * file.
    */
    private async waitForSessionPromise(fileOperation: FileOperation) {
        if (this.fileOperationStartedOnce.get(fileOperation)) {
            await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);
        } else {
            this.fileOperationStartedOnce.set(fileOperation, true);
            await this.sessionContext.waitForSessionPromise(SessionPromise.EnvironmentReadyForFileOperation);
        }
    }

    public bumpGeneration() {
        this.generation++;
    }

    public createorUpdateWorkspaceFile(workspaceId: string, workspaceName: string) {
        const uri = vscode.Uri.parse(`vsls:/Live Share.code-workspace`);
        this.workspaceFile = new MemoryFile(uri, 'Live Share');
        const textEncoder = new TextEncoder();
        const content = textEncoder.encode(JSON.stringify({
            'folders': [
                {
                    'uri': `vsls:/?${workspaceId}`,
                    'name': workspaceName
                }
            ]
        }, undefined, '\t'));
        this.setWorkspaceFileInfo(uri, content);
    }

    private onFilesChanged(e: vsls.FilesChangedEventArgs) {
        let hasCreated = false;
        const changes = e.changes.map(change => {
            const changePath = PathUtil.getRelativePathFromPrefixedPath(change.fullPath);
            const changeUri = vscode.Uri.parse(`${this.uriPrefix}${changePath}`);

            const type = WorkspaceProvider.toFileChangeType(change.changeType);
            if (type === vscode.FileChangeType.Created) {
                hasCreated = true;
            }

            const fileChange: vscode.FileChangeEvent = {
                type,
                uri: changeUri
            };
            return fileChange;
        });

        this.onFilesChangedEmitter.fire(changes);

        // There is an issue in vscode (#117606) web where created events
        // are not refreshing the file explorer. Until this is fixed
        // explicitly refresh the file explorer on create.
        // The memory workspace file is only set for web.
        if (hasCreated && this.workspaceFile) {
            vscode.commands.executeCommand('workbench.files.action.refreshFilesExplorer');
        }
    }

    private static toFileChangeType(changeType: vsls.FileChangeType): vscode.FileChangeType {
        switch (changeType) {
            case vsls.FileChangeType.Added:
                return vscode.FileChangeType.Created;
            case vsls.FileChangeType.Deleted:
                return vscode.FileChangeType.Deleted;
            case vsls.FileChangeType.Updated:
                return vscode.FileChangeType.Changed;
            default: throw new Error('changeType not supported');
        }
    }

    public dispose() {
        this.isDisposed = true;
        this.eventRegistrations.forEach((r) => r.dispose());
    }

    /**
     * Subscribe to events in the file or folder denoted by `uri`.
     * @param uri
     * @param options
     */
    public watch(uri: vscode.Uri, options: { recursive?: boolean; excludes?: string[] }): vscode.Disposable {
        return {
            dispose() {
                /* TODO: @Daniel, implement proper file watching once we have support in the Agent */
                /* Right now we fire onDidChangeFile for every file change */
                /* empty */
            }
        };
    }

    /**
     * Retrieve metadata about a file.
     *
     * @param uri The uri of the file to retrieve meta data about.
     * @return The file metadata about the file.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `uri` doesn't exist.
     */
    public async stat(uri: vscode.Uri): Promise<vscode.FileStat> {
        if (uri.path === this.workspaceFile?.uri.path) {
            return this.workspaceFile;
        }

        if (uri.path === '/' || uri.path === '') {
            return { type: vscode.FileType.Directory, ctime: 0, mtime: 0, size: 0 };
        }

        const originalGeneration = this.generation;

        await this.waitForSessionPromise(FileOperation.Stat);

        if (originalGeneration !== this.generation) {
            // This file system provider was re-registered during the invocation of this stat().
            // Report the file as missing to make VSCode not load it.
            // Otherwise, VSCode may open it read/write in read-only session, or read-only in read/write session.
            throw this.fileError(FileError.FileNotFound, uri);
        }

        if (!this.isConnected) {
            return { type: vscode.FileType.Unknown, ctime: 0, mtime: 0, size: 0 };
        }

        const paths: string[] = [uri.path];
        let fileListOptions: vsls.FileListOptions = {
            recurseMode: vsls.FileRecurseMode.None,
            excludePatterns: undefined,
            includeDetails: true,
            enableMultipleRoots: this.multiRootWorkspaceEnabled
        };
        const fileInfos: vsls.FileInfo[] = await this.listAsync(paths, fileListOptions);

        if (fileInfos[0].path.startsWith(PathManager.untitledPrefix)) {
            try {
                return this.sessionContext.coeditingClient.openUntitledFiles.get(uri.path);
            } catch {
                throw this.fileError(FileError.FileNotFound, uri);
            }
        }

        // Invoke onStat method on providers
        for (const provider of this.workspaceProviders.filter(p => p.onStat)) {
            await provider.onStat(fileInfos);
        }

        if (fileInfos.length === 0 || fileInfos[0].exists === false) {
            throw this.fileError(FileError.FileNotFound, uri);
        }

        return this.getFileStat(fileInfos[0], uri.toString());
    }

    /**
     * Read the entire contents of a file.
     *
     * @param uri The uri of the file.
     * @return An array of bytes or a thenable that resolves to such.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `uri` doesn't exist.
     */
    public async readFile(uri: vscode.Uri): Promise<Uint8Array> {
        if (uri.path === this.workspaceFile?.uri.path) {
            return Promise.resolve(this.workspaceFile.data);
        }
        await this.waitForSessionPromise(FileOperation.Read);

        if (!uri.path.length || !this.isConnected) {
            throw this.fileError(FileError.FileNotFound, uri);
        }

        let fileTextInfo: vsls.FileTextInfo;

        try {
            if (uri.path.startsWith(PathManager.untitledPrefix)) {
                if (this.sessionContext.coeditingClient.openUntitledFiles.has(uri.path)) {
                    fileTextInfo = {
                        exists: true,
                        path: uri.path,
                        text: '',
                        isDirectory: false
                    };
                    new TelemetryEvent(CoauthoringTelemetryEvents.RECEIVE_UNTITLED_FILE).send();
                } else {
                    throw this.fileError(FileError.FileNotFound, uri);
                }
            } else {
                fileTextInfo = await this.readTextAsync(uri, {});
            }
        } catch (e) {
            this.trace.error('readFile error:', e);
            if (e.code === RpcErrorCodes.MessageTooLarge) {
                throw this.fileError(FileError.FileTooLarge, uri);
            } else if (e === FileError.FileNotFound) {
                throw this.fileError(FileError.FileNotFound, uri);
            } else {
                throw this.fileError(FileError.FileNotAvailable, uri);
            }
        }

        // Invoke onReadFile method on providers
        for (const provider of this.workspaceProviders.filter(p => p.onReadFile)) {
            await provider.onReadFile(fileTextInfo);
        }

        if (fileTextInfo.exists === false) {
            throw this.fileError(FileError.FileNotFound, uri, LogLevel.Debug);
        }

        // The file we received from the file service is not guaranteed to be completely synchronized with coauthoring.
        // Wait for the coauthoring client to fully synchronize it.
        let result: string | boolean = fileTextInfo.text;
        const coAuthoringFileName = this.sessionContext.coeditingClient.uriToFileName(uri);

        if (coAuthoringFileName && !(fileTextInfo.attributes === vsls.FileAttributes.Hidden)) {
            result = await this.sessionContext.coeditingClient.performFileOpenHandshake(coAuthoringFileName, result);
            if (typeof result === 'boolean' && result === false) {
                // Since we couldn't open the file, it likely (Although not
                // guarnetees) that the file is binary. Lets return some binary
                // pre-amble to the requester, so that (hopefully) they fall into
                // the 'binary file error handling' path.
                return Promise.resolve(getBinaryPreamble());
            }
        }

        let fileBuffer = buffer.Buffer.from(<string>result, 'utf8');
        return Promise.resolve(fileBuffer);
    }

    /**
     * Write data to a file, replacing its entire contents.
     *
     * @param uri The uri of the file.
     * @param content The new content of the file.
     * @param options Defines is missing files should or must be created.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `uri` doesn't exist and `create` is not set.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when the parent of `uri` doesn't exist and `create` is set.
     * @throws [`FileExists`](#FileSystemError.FileExists) when `uri` already exists and `overwrite` is set.
     * @throws [`NoPermissions`](#FileSystemError.NoPermissions) when permissions aren't sufficient.
     */
    public async writeFile(uri: vscode.Uri, content: Uint8Array, options: { create: boolean, overwrite: boolean }): Promise<void> {
        if (uri.path === this.workspaceFile?.uri.path) {
            this.setWorkspaceFileInfo(uri, content);
            return;
        }

        await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);

        if (!this.isSessionActive) {
            // When a session is terminated remotely, part of our clean up tries
            // to save the file. We need to report it as successful otherwise
            // an error is propogated to the save request in the UI, and we don't
            // completely clean up the session when we're a guest.
            // Thus, return a total lie: Yep, we saved it! *wink*.
            return;
        }

        try {
            if (uri.path.startsWith(PathManager.untitledPrefix)) {
                if (this.sessionContext.coeditingClient.openUntitledFiles.has(uri.path)) {
                    let file = this.sessionContext.coeditingClient.openUntitledFiles.get(uri.path);
                    file.mtime = new Date().getTime();
                    return;
                } else {
                    throw this.fileError(FileError.FileNotFound, uri);
                }
            }

            // First check if the file exists
            const exists: boolean = await this.fileExists(uri);

            if (exists && !(options && options.overwrite)) {
                throw this.fileError(FileError.FileExists, uri);
            } else if (!exists && !(options && options.create)) {
                throw this.fileError(FileError.FileNotFound, uri);
            } else if (exists) {
                // The co-editing client takes care of sending a save request to the host, so there is nothing to do here.
                return;
            }

            // The participant is creating a new file
            const stringContent = content.toString();
            const fileInfo = await this.fileService().writeTextAsync(
                uri.path, stringContent, { append: false, createIfNotExist: true });
            if (fileInfo.exists === false) {
                // The file service did not allow creating the file, possibly because it's in an excluded path.
                throw this.fileError(FileError.NoPermissions, uri);
            }
        } catch (e) {
            // To prevent dirty files and the "Save before closing?" dialog, report a save success.
            this.trace.error(e.message);
            return;
        }
    }

    /**
     * Rename a file or folder.
     *
     * @param oldUri The existing file or folder.
     * @param newUri The target location.
     * @param options Defines if existing files should be overwriten.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `oldUri` doesn't exist.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when parent of `newUri` doesn't exist
     * @throws [`FileExists`](#FileSystemError.FileExists) when `newUri` exists and when the `overwrite` option is not `true`.
     * @throws [`NoPermissions`](#FileSystemError.NoPermissions) when permissions aren't sufficient.
     */
    public async rename(oldUri: vscode.Uri, newUri: vscode.Uri, options: { overwrite: boolean }): Promise<void> {
        await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);

        if (!this.isSessionActive) {
            throw this.fileError(FileError.FileNotFound, oldUri);
        }

        const oldExists: boolean = await this.fileExists(oldUri);
        if (!oldExists) {
            throw this.fileError(FileError.FileNotFound, oldUri);
        }

        if (!(options && options.overwrite)) {
            const newExists: boolean = await this.fileExists(newUri);
            if (newExists) {
                throw this.fileError(FileError.FileExists, newUri);
            }
        }

        const fileInfo = await this.fileService().moveAsync(
            oldUri.path, url.parse(newUri.path).path, { overwrite: false });
        if (fileInfo.exists === false) {
            throw this.fileError(FileError.NoPermissions, newUri);
        }
    }

    /**
     * Create a new directory. *Note* that new files are created via `write`-calls.
     *
     * @param uri The uri of the new folder.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when the parent of `uri` doesn't exist.
     * @throws [`FileExists`](#FileSystemError.FileExists) when `uri` already exists.
     * @throws [`NoPermissions`](#FileSystemError.NoPermissions) when permissions aren't sufficient.
     */
    public async createDirectory(uri: vscode.Uri): Promise<void> {
        await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);

        if (!this.isSessionActive) {
            throw this.fileError(FileError.FileNotFound, uri);
        }

        // Prevents error on auto-save in external files
        if (uri.path.startsWith(PathManager.externalPrefix)) {
            return;
        }

        const dirInfo = await this.fileService().createDirectoryAsync(uri.path);
        if (dirInfo.exists === false) {
            throw this.fileError(FileError.NoPermissions, uri);
        }
    }

    /**
     * Retrieve the meta data of all entries of a [directory](#FileType.Directory)
     *
     * @param uri The uri of the folder.
     * @return An array of name/type-tuples or a thenable that resolves to such.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `uri` doesn't exist.
     */
    public async readDirectory(uri: vscode.Uri): Promise<[string, vscode.FileType][]> {
        await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);
        const result: [string, vscode.FileType][] = [];

        if (!this.isSessionActive) {
            return result;
        }

        let fileListOptions: vsls.FileListOptions = {
            recurseMode: vsls.FileRecurseMode.Children,
            excludePatterns: undefined,
            includeDetails: true,
            enableMultipleRoots: this.multiRootWorkspaceEnabled
        };

        let fileInfos: vsls.FileInfo[];
        fileInfos = await this.listAsync([uri.path], fileListOptions);

        // Invoke onReadDirectory method on providers
        for (const provider of this.workspaceProviders.filter(p => p.onReadDirectory)) {
            await provider.onReadDirectory(fileInfos);
        }

        if (fileInfos.length !== 1 || fileInfos[0].exists === false) {
            throw this.fileError(FileError.FileNotFound, uri);
        }

        fileInfos = fileInfos[0].children;

        checkForCaseSensitiveFileSystem(fileInfos);
        if (fileInfos) {
            fileInfos.forEach(fi => {
                let fileUri: vscode.Uri = uri.with({ path: fi.path });
                let fileStat: vscode.FileStat = this.getFileStat(fi, fileUri.toString());
                let fileName: string = path.basename(fi.path);
                result.push([fileName, fileStat.type]);
            });
        }

        return result;
    }

    /**
     * Delete a file.
     *
     * @param uri The resource that is to be deleted.
     * @param options Defines if deletion of folders is recursive.
     * @throws [`FileNotFound`](#FileSystemError.FileNotFound) when `uri` doesn't exist.
     * @throws [`NoPermissions`](#FileSystemError.NoPermissions) when permissions aren't sufficient.
     */
    public async delete(uri: vscode.Uri): Promise<void> {
        await this.sessionContext.waitForSessionPromise(SessionPromise.JoiningCompleted);

        if (!this.isSessionActive) {
            throw this.fileError(FileError.FileNotFound, uri);
        }

        return this.fileService().deleteAsync(uri.path, { useTrash: true });
    }

    private get isConnected(): boolean {
        return (this.currentConnectionStatus !== vsls.WorkspaceConnectionStatus.Disconnected) && !this.isDisposed;
    }

    private get isSessionActive(): boolean {
        const isJoined = (sessionStateTracker.State === SessionState.Joined);
        const isSessionActive = isJoined && this.isConnected;
        return isSessionActive;
    }

    private setWorkspaceFileInfo(uri: vscode.Uri, content: Uint8Array) {
        this.workspaceFile.mtime = Date.now();
        this.workspaceFile.size = content.byteLength;
        this.workspaceFile.data = content;
        this.onFilesChangedEmitter.fire([{
            type: vscode.FileChangeType.Changed,
            uri
        }]);
    }

    private getFileStat = (fileInfo: vsls.FileInfo, id: string) => {
        let fileStat: vscode.FileStat = {
            mtime: Date.parse(fileInfo.mtime as any as string),
            ctime: Date.parse(fileInfo.mtime as any as string),
            // avoid VSCode complaining about a conflict by not returning the file size
            size: undefined,
            type: fileInfo.isDirectory ? vscode.FileType.Directory : vscode.FileType.File
        };
        return fileStat;
    }

    private fileExists(resource: vscode.Uri): Promise<boolean> {
        let fileListOptions: vsls.FileListOptions = {
            recurseMode: vsls.FileRecurseMode.None,
            excludePatterns: undefined,
            includeDetails: true,
            enableMultipleRoots: this.multiRootWorkspaceEnabled
        };

        let paths: string[] = [];
        paths.push(resource.path);
        return this.listAsync(paths, fileListOptions)
            .then((fileInfo: vsls.FileInfo[]) => {
                // exits is only populated with false if the file does not exist
                return fileInfo[0].exists !== false;
            });
    }

    /**
     * Ensure we initialize the file service cache from the experimental service.
     */
    private async ensureStatusFileServiceCache() {
        // use a mutex to avoid multiple entry points to call this.
        await this.enableFileServiceCacheMutex.dispatch(async () => {
            if (this.enableFileServiceCache === undefined) {
                this.enableFileServiceCache = !!(await getExpService()?.getTreatmentVariableAsync('vscode', 'file-service-cache'));
                if (this.enableFileServiceCache) {
                    this.fileServiceCache = new FileServiceCache(this.fileService(), traceSource.withName('FileServiceCache'));
                    this.trace.info('File service cache is enabled');
                }
            }
        });
    }

    private async readTextAsync(
        uri: vscode.Uri,
        options: vsls.FileReadOptions,
        cancellationToken?: vscode.CancellationToken)
        : Promise<vsls.FileTextInfo> {

        if (this.enableFileServiceCache === undefined) {
            await this.ensureStatusFileServiceCache();
        }

        if (this.enableFileServiceCache) {
            const fileTextInfo = (await this.fileServiceCache.readTextAsync([uri.path], options, fileCacheTimeExpired, cancellationToken))[0];
            return fileTextInfo;
        } else {
            return await this.fileService().readTextAsync(uri.path, options, cancellationToken);
        }
    }

    private async listAsync(
        paths: string[],
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken)
        : Promise<vsls.FileInfo[]> {

        if (this.enableFileServiceCache === undefined) {
            await this.ensureStatusFileServiceCache();
        }

        if (this.enableFileServiceCache) {
            return await this.fileServiceCache.listAsync(paths, options, fileCacheTimeExpired, cancellationToken);
        }

        return await this.fileService().listAsync(paths, options, cancellationToken);
    }

    /**
     * Creates a vscode.FileSystemError object from the specified error name,
     * and file or directory URI.
     */
    private fileError(error: FileError, uri?: vscode.Uri, logLevel?: LogLevel) {
        this.trace.traceEvent(logLevel || LogLevel.Error, 0, `fileError: ${error} uri path:${uri?.path}`);

        let message;
        switch (error) {
            case FileError.FileNotFound:
                message = localize('fileError.FileNotFound');
                break;
            case FileError.FileExists:
                message = localize('fileError.FileExists');
                break;
            case FileError.NoPermissions:
                message = localize('fileError.NoPermissions');
                break;
            case FileError.FileTooLarge:
                message = localize('fileError.FileTooLarge');
                break;
            case FileError.FileNotAvailable:
                message = localize('fileError.FileNotAvailable');
                break;
            default:
                message = '';
        }

        message = message || `Error (${error}): ${uri.path}`;
        if (uri) {
            message = message.replace('$(path)', uri.path);
        }

        const errorFunction: (message: string) => vscode.FileSystemError =
            (vscode.FileSystemError as any)[error];
        return errorFunction ? errorFunction(message) : new Error(message);
    }

}

function checkForCaseSensitiveFileSystem(files: vsls.FileInfo[]) {
    const lowerCaseFileNames = new Set<string>();
    for (let f of files) {
        if (f.isDirectory) {
            continue;
        }
        const name = f.path.toLowerCase();
        if (lowerCaseFileNames.has(name)) {
            reportCaseSensitiveFileSystem();
            return;
        }
        lowerCaseFileNames.add(name);
    }
}

function reportCaseSensitiveFileSystem() {
    CoauthoringTelemetry.ReportCaseSensitiveFileSystem();
    vscode.window.showErrorMessage(localize('error.CaseSensitiveFileSystem'));
}
