import { ICommandDecoratorCallback } from '../types/ICommandDecoratorCallback';
import { CommandDecoratorBase, CommandInvoke, CommandDecorator } from './CommandDecoratorBase';
import { NotificationUtil } from '../util/NotificationUtil';
import { ICommandContext } from '../types/ICommandContext';
import { INotificationUtil } from '../types/INotificationUtil';
import { ByDesignError } from '../types/ByDesignErrors';
import { UserError } from '../types/UserError';
import { CancellationError } from '../types/CancellationError';
import { NonBlockingError } from '../types/NonBlockingError';

import { Telemetry, ITelemetry, FaultType as TelemetryFaultType } from '@vs/vso-telemetry';

export function errorNotificationCommandDecorator(
    title: string,
    telemetryFaultEventName: string,
    isModalError: boolean = false,
    onError?: ICommandDecoratorCallback,
): CommandDecorator {
    return new ErrorNotificationCommandDecorator(
        NotificationUtil,
        Telemetry,
        telemetryFaultEventName,
        title,
        isModalError,
        onError,
    ).setup();
}

/**
 * Error Notification `commandHandler` that converts exceptions into the correct
 * notification toast in the client.
 */
export class ErrorNotificationCommandDecorator extends CommandDecoratorBase {
    constructor(
        private notificationUtil: INotificationUtil,
        private telemetry: ITelemetry,
        private telemetryFaultEventName: string,
        private title: string,
        private isModalError: boolean,
        private onError?: ICommandDecoratorCallback,
    ) {
        super();
    }

    public async invoke<T>(
        commandInvoke: CommandInvoke<T>,
        options: any,
        context: ICommandContext,
    ): Promise<T> {
        const { cancellationTokenSource } = context;
        let result: T;

        // save the command name
        context.commandName = this.title;

        try {
            result = await commandInvoke(options, context);
        } catch (error) {
            try {
                const userMessage = error.userMessage || error.message;
                const fullMessage = userMessage ? `${this.title}: ${userMessage}` : this.title;
                // if `CancellationError` was throw, invalidate the cancellation token
                if (error instanceof CancellationError) {
                    // cancel the command cancellation token if not cancelled yet
                    if (
                        cancellationTokenSource &&
                        !cancellationTokenSource.token.isCancellationRequested
                    ) {
                        cancellationTokenSource.cancel();
                    }
                }

                const isCancellationOrUserError =
                    error instanceof UserError || error instanceof CancellationError;

                // Supress the notification if the error has the appropriate property
                // or if it's a cancellation error with no message.
                const suppressNotification =
                    error.isSuppressUserNotification ||
                    (error instanceof CancellationError && !userMessage);

                if (!suppressNotification) {
                    if (isCancellationOrUserError) {
                        this.notificationUtil.showInformationMessage(fullMessage, false);
                    } else if (error instanceof ByDesignError) {
                        await this.notificationUtil.showErrorMessage(fullMessage, {
                            modal: this.isModalError,
                        });
                    } else if (!(error instanceof NonBlockingError)) {
                        await this.notificationUtil.showErrorMessage(fullMessage, {
                            modal: this.isModalError,
                        });
                    }
                }
            } catch (e) {
                // if the above block triggered an error we want to know
                error = e;
            }

            // at this this point we will know about any errors that hasn't been
            // recorded - anything thats happened up stream of `TelemetryCommandMiddleware`
            if (error && !error.hasRecorded) {
                const errorMessage = `${this.title}: [unhandled exception (decorator)] ${error.message}`;
                context.trace.error(errorMessage);
                this.telemetry.sendFault(
                    this.telemetryFaultEventName,
                    TelemetryFaultType.Error,
                    errorMessage,
                    error,
                );
            }

            if (error && this.onError) {
                await this.onError(error, context, options);
            }
        }

        return result!;
    }
}
