export interface BufferManagerStatus {
    serverVersion: number;
    unacknowledgedCount: number;
    waitingForRemoteEditsToBeApplied: boolean;
    localChangesQueue: number;
    remoteMessagesQueue: number;
    collabBufferText: string;
}

/*
 * Provides abstraction for the environment that is hosting this manager. This
 * allowed the different places to hide the details of how those operations are
 * performed.
 */
export interface IVSCodeBufferManagerHost {
    /**
     * The id of the current OT host.
     */
    readonly clientID: number;
    /**
     * The total count of the number of parties in the OT system.
     */
    readonly clientCount: number;
    /**
     * The trace to output to the logs.
     */
    readonly trace: TraceSource;
    /**
     * Apply a workspace edit.
     */
    applyEdit(edits: vscode.TextEdit[], messageTrackingId?: string): Promise<ApplyEditResult>;
    /**
     * Updates the VS Code document contents to match the collab buffer contents.
     */
    resync(): Promise<void>;
    /**
     * Checks that the VS Code document contents match the collab buffer contents.
     */
    checkSync(bufferContents: string): void;
    /**
     * Check if the guest's buffer contents match the host's.
     */
    checkHostSync(serverVersionNumber: number, hashCode: number): void;
    /**
     * Send a message to the server.
     */
    postMessage(message: CoauthoringMessage): void;
    /**
     * Handle the client's new position.
     */
    updateClientPosition(message: vsls.SelectionChangeMessage): void;

    /**
     * Performs editor undo's until it matches the content expected.
     * @param contentToMatch The contents the buffer should match to consider a state as being reached
     */
    undoBufferToMatchContents(contentToMatch: string): Promise<string>;

    /**
     * Peform a single undo operation, and return the document edits that occured
     * from performing that undo, along with the now current document contents.
     */
    performSingleUndo(): Promise<{ edits: vscode.TextDocumentContentChangeEvent[]; contents: string }>;

    /**
     * Perform a single redo, and return the document contents after
     */
    performSingleRedo(): Promise<string>;

    /**
     * Perform editor redo's until there are no more redo's (that is, document
     * doesn't change after doing a redo)
     * @param handleChange Callback to be called for each document edit that is seen
     */
    redoUntilNoMoreToRedo(contentToMatch: string, handleChange: (e: vscode.TextDocumentChangeEvent) => void): Promise<void>;
}

export interface SaveSnapshot {
    serverVersionNumber: number;
    hashCode: number;
    changes: vsls.TextChange[][];
    hasUnacknowledgedChanges: boolean;
    fallbackText?: string;
}

export class MessageAndVersionNumber {
    public constructor(public readonly message: CoauthoringMessage, public readonly serverVersionNumber: number) {
        /* empty */
    }
}

export enum CoeditingIncomingMessageBehavior {
    None,
    Queue,
    QueueAndProcess
}

interface LocalRemoteTransitionInformation {
    beforeTransitionToLocal?: string | null;
    beforeTransitionToRemote: string | null;
    hadLocalEdits: boolean;
}

interface LocalRedoInformation {
    redoChanges: vsls.TextChange[];
    serverVersion: number;
}

enum PerformingUndoState {
    None = 0,
    ApplyingEdits = 1,
    CapturingEdits = 2,
}

class PendingEdit {
    constructor(
        public readonly algorithmState: OTAlgorithmState,
        public readonly pendingEdit: ITextChange[]
    ) {
    }
}

function acceptLocalChangeOnBuffer(e: vscode.TextDocumentChangeEvent, buffer: CollabBuffer, ot: OTAlgorithm) {
    // VS Code change events contain changes that are to be applied consecutively
    buffer.beginRecording();

    e.contentChanges.forEach(change => {
        const [start, end, text] = CollabBuffer.convertVsCodeContentChangeToCollabChange(change, buffer);

        buffer.applyLocalEdit(start, end, text);
    });

    const [changes, unexpandedChanges] = buffer.endRecording();

    ot.acceptLocalChange(changes, unexpandedChanges, (e as any as ITracked).trackingId);
}

function mapTextChangeToEditorEditForBuffer(change: ITextChange, buffer: CollabBuffer): vscode.TextEdit {
    let oldRange: vscode.Range;
    let newText = change.newText;
    const oldText = change.oldText;
    const oldStart = buffer.positionAt(change.oldPosition);
    const oldEnd = buffer.positionAt(change.oldEnd);

    const isReplacingSingleLF = (change.oldLength === 1) && (change.oldText.charCodeAt(0) === 10);
    const newTextEndsWithLF = (newText.length > 0) && (newText.charCodeAt(newText.length - 1) === 10);
    const newTextEndsWithCRLF = (newText.length > 1) && (newText.endsWith('\r\n'));
    const isReplacingWithSingleLF = (change.newLength === 1) && (change.newText.charCodeAt(0) === 10);
    const oldTextEndsWithLF = (oldText.length > 0) && (oldText.charCodeAt(oldText.length - 1) === 10);

    if (isReplacingSingleLF && newTextEndsWithLF && !newTextEndsWithCRLF) {
        // If we're only adding text, but the collab buffer has automatically included the adjacent LF into the
        // text we're replacing; ignore the added LF to prevent the cursor from teleporting to the next line.
        // But, if the new text ends CRLF (not just an LF), we should leave as it, and VSCode will "Fix up"
        // it's line endings to only insert the LF. If we strip it, it ends up with "cr", which is converted back
        // to LF, and now we have too many lines.
        oldRange = new vscode.Range(oldStart.line, oldStart.character, oldStart.line, oldStart.character);
        newText = newText.substr(0, newText.length - 1);
    } else if (isReplacingWithSingleLF && oldTextEndsWithLF) {
        // We're only deleting text, but the collab buffer has automatically included the adjacent LF into the
        // text we're adding; ignore the added LF to prevent the cursor from teleporting to the next line
        const truncatedOldEnd = buffer.positionAt(change.oldEnd - 1);
        oldRange = new vscode.Range(oldStart.line, oldStart.character, truncatedOldEnd.line, truncatedOldEnd.character);
        newText = '';
    } else {
        oldRange = new vscode.Range(oldStart.line, oldStart.character, oldEnd.line, oldEnd.character);
    }

    return new vscode.TextEdit(oldRange, newText);
}

enum LastChangeSource {
    Unknown,
    Local,
    Remote,
}

const SELECTION_SCROLLING_DEBOUNCE_TIMEOUT = 100;

export class VSCodeBufferManager {
    private readonly host: IVSCodeBufferManagerHost;
    private readonly diagnosticTrace: boolean;
    private readonly collabBuffer: CollabBuffer;
    private readonly otAlgorithm: OTAlgorithm;

    private saveSnapshots: IMap<SaveSnapshot> = {};
    private syncManager: SyncManager;
    private cachedHandshakes: SaveSnapshot[] = [];
    private pendingApplicationOfRemoteEdit: PendingEdit | null = null;
    private localChangesQueue: vscode.TextDocumentChangeEvent[] = getTimedArray('localchangesqueuetime');
    private remoteMessagesQueue: MessageAndVersionNumber[] = getTimedArray('remotemessagesqueuetime');
    private fileName: string;
    private highestQueuedEventId: number = -2;
    private localToRemoteTransitions: LocalRemoteTransitionInformation[] = [];
    private localRedoStack: LocalRedoInformation[] = [];
    private initialHistoryHighWaterMark: number = -1;
    private performingUndo: PerformingUndoState = PerformingUndoState.None;
    private lastChangeSource: LastChangeSource = LastChangeSource.Unknown;
    private hasEverHadALocalEdit = false;
    private redoWouldRedoLocalUndo = false;
    private localUndoCount: number = 0;
    private remoteUndoCount: number = 0;
    private selectionChangedDebounce: NodeJS.Timer | null = null;
    private scrollHappenedDebounce: NodeJS.Timer[] = [];

    // Note: diagnosticTrace should never be true for customers as it causes Customer Content (file names and edit contents) to be written to logs
    constructor(host: IVSCodeBufferManagerHost, fileName: string, initialText: string, private isHost: boolean, diagnosticTrace: boolean = false) {
        this.host = host;
        this.diagnosticTrace = diagnosticTrace;
        this.collabBuffer = new CollabBuffer(initialText, host.trace);
        this.fileName = fileName;
        this.syncManager = new SyncManager();

        let self = this;

        const algorithmHost = new class implements IOTAlgorithmHost {
            public get fileName(): string {
                return self.fileName;
            }
            public clientID = host.clientID;
            public clientCount = host.clientCount;
            public trace = host.trace;
            public postMessage(msg: vsls.TextChangeMessage): void {
                host.postMessage(msg);
            }
        };

        this.otAlgorithm = new OTAlgorithm(algorithmHost, this.diagnosticTrace);
        this.otAlgorithm.serverVersionChangedEvent.on(serverVersionChangedEventName, () => {
            this.onServerVersionChange();
        });
    }

    public get numberOfLocalUndos(): number {
        return this.localUndoCount;
    }

    public get numberOfRemoteUndos(): number {
        return this.remoteUndoCount;
    }

    public updateFileName(newFileName: string): void {
        this.fileName = newFileName;
    }

    private onServerVersionChange(): void {
        if (this.otAlgorithm.getOperationalTransformStatus().unacknowledgedCount === 0) {
            if (this.isHost) {
                this.postHandshake();
            } else {
                this.cachedHandshakes.push(this.makeSnapshot());
            }
        }
    }

    public clearLocalChangesQueue() {
        while (this.localChangesQueue.length > 0) {
            this.localChangesQueue.pop();
        }
    }

    public onDidChangeTextDocument(e: vscode.TextDocumentChangeEvent): void {
        if (this.performingUndo > PerformingUndoState.ApplyingEdits) {
            // If we're undoing, we're going to end up making lots of edits that
            // we don't want to propogate, or put into our operational transform
            // so just drop them on the floor.
            return;
        }

        this.localChangesQueue.push(e);
        this.processQueuedMessages();
    }

    private vscodeRangeToVslsRange(range: vscode.Range): vsls.Range {
        const start = this.toCollabOffset(range.start);
        const end = this.toCollabOffset(range.end);
        const length = end - start;
        return { start, length };
    }

    public onDidChangeTextEditorVisibleRanges(fileName: string, fileVersion: number, editorId: string, ranges: ReadonlyArray<vscode.Range>, trackingId?: string): void {
        if (ranges.length < 1) {
            return;
        }

        if (this.seenSelectionWithinDebouncePeriod()) {
            // We want to keep debouncing the selection (e.g. dropping other
            // scrolls) when we see a stream of scroll events. We only need short
            // period of idle before we pick them up again. This is a trade off;
            // if you're changing selection, and then scrolling the selection
            // out of view quickly, you'll drop the scroll events. But this is
            // an OK trade off to make sure the follower doesn't see flickering
            //
            // Note: By default, VS Code will do selection + one scroll event.
            // However, if the customer has smooth scrolling enabled, it will be
            // selection + N scroll events (however many needed to move the
            // viewport), which is why this resets the timer rather than clearing
            this.resetSelectionDebounce();
            return;
        }

        const bufferVisibleRanges: vsls.Range[] = ranges.map(range => this.vscodeRangeToVslsRange(range));
        const serverVersion = this.otAlgorithm.getOperationalTransformStatus().serverVersion;
        const layoutChangeMsg = MessageFactory.LayoutScrollMessage(
            this.host.clientID,
            fileName,
            fileVersion,
            serverVersion,
            bufferVisibleRanges[0].start,
            bufferVisibleRanges[0].length,
            editorId,
            bufferVisibleRanges);

        // Delay the handling of scroll messages by some time period. This is because
        // when the viewports are miss-matched between clients, a large viewport
        // will result being asked to bring lines 0-100 into view, but the client
        // can only display 0-20, so it only shows 0-20. This isn't normally a
        // problem until a there is a selection change in the same 'operation'
        // e.g. the user typed something at the bottom of the range of the
        // smaller viewport. E.g. 0-100 range on host, 0-20 on guest, edit happens
        // on line 21, we see: scroll, edit, selection events as discrete events
        // from VS Code (And receive them in the same way). This causes the smaller
        // viewport to flick up to the top of the 0-100 range, and then immediately
        // rescroll the line of the section which is where the cursor actually is.
        // This results in a lag of the scroll _starting_, but no delay during
        // the scroll.
        let scrollHappenedId = setTimeout(() => {
            const indexOfTimeoutId = this.scrollHappenedDebounce.indexOf(scrollHappenedId);
            if (indexOfTimeoutId > -1) {
                this.scrollHappenedDebounce.splice(indexOfTimeoutId, 1);
            }
            (layoutChangeMsg as any as ITracked).trackingId = trackingId;

            this.host.postMessage(layoutChangeMsg);
        }, SELECTION_SCROLLING_DEBOUNCE_TIMEOUT);

        this.scrollHappenedDebounce.push(scrollHappenedId);
    }

    public getEditorVisibleRanges(visibleRanges: ReadonlyArray<vscode.Range>): vsls.EditorVisibleRanges {
        const bufferVisibleRanges: vsls.Range[] = visibleRanges.map(range => this.vscodeRangeToVslsRange(range));
        return {
            fileName: this.fileName,
            serverVersionNumber: this.otAlgorithm.getOperationalTransformStatus().serverVersion,
            visibleRanges: bufferVisibleRanges
        };
    }

    private clearSelectionDebounce(): void {
        if (this.selectionChangedDebounce === null) {
            return;
        }

        clearTimeout(this.selectionChangedDebounce);
        this.selectionChangedDebounce = null;
    }

    private clearScrollHappenedDebounce(): void {
        this.scrollHappenedDebounce.forEach((id) => {
            clearTimeout(id);
        });

        this.scrollHappenedDebounce = [];
    }

    private seenSelectionWithinDebouncePeriod(): boolean {
        return this.selectionChangedDebounce !== null;
    }

    private havePendingScrolls(): boolean {
        return (this.scrollHappenedDebounce.length > 0);
    }

    private resetSelectionDebounce(): void {
        this.clearSelectionDebounce();
        this.clearScrollHappenedDebounce();
        this.selectionChangedDebounce = setTimeout(() => this.clearSelectionDebounce(), SELECTION_SCROLLING_DEBOUNCE_TIMEOUT);
    }

    public onDidChangeTextEditorSelection(selections: vscode.Selection[], fileName: string, kind?: vscode.TextEditorSelectionChangeKind, forceJumpForId?: number, trackingId?: string): void {
        if (this.pendingApplicationOfRemoteEdit) {
            // This event was caused by the remote edit being applied, which caused the selection to change. VS Code already deals with
            // repositioning the decorators, so drop this event.
            return;
        }

        // TODO: Support multiple selections (right now VS does a single big
        // selection combining all selections). For now just use the primary
        // selection which is at index 0.
        const primarySelection = selections[0];
        const offsetStart = this.toCollabOffset(primarySelection.start);
        const offsetEnd = this.toCollabOffset(primarySelection.end);
        const length = offsetEnd - offsetStart;
        const serverVersion = this.otAlgorithm.getOperationalTransformStatus().serverVersion;
        const selectionChangeMsg = MessageFactory.SelectionChangeMessage(this.host.clientID,
            fileName,
            undefined,
            serverVersion,
            offsetStart,
            length,
            primarySelection.isReversed,
            kind,
            forceJumpForId);
        (selectionChangeMsg as any as ITracked).trackingId = trackingId;
        this.host.postMessage(selectionChangeMsg);

        // We received a selection event, so if we need to reset the debounce
        // timeout, so that any scrolls that happen within a time period are
        // dropped, since selection gives the most specific focusing behaviour.
        this.resetSelectionDebounce();
    }

    public onIncomingMessage(message: CoauthoringMessage, serverVersionNumber: number, processingBehavior: CoeditingIncomingMessageBehavior = CoeditingIncomingMessageBehavior.QueueAndProcess): void {
        if (serverVersionNumber <= this.highestQueuedEventId) {
            return;
        }

        this.host.trace.verbose(`Queueing remote message for ${TraceFormat.formatPath(this.fileName)}`);
        this.highestQueuedEventId = serverVersionNumber;
        this.remoteMessagesQueue.push(new MessageAndVersionNumber(message, serverVersionNumber));

        if (processingBehavior === CoeditingIncomingMessageBehavior.Queue || this.performingUndo) {
            // If we're only being asked to queue, then don't process any items
            // in the queue. That will be handled at a later time.
            // Or...
            // We're in the middle of an update; since they're coming, we don't
            // want to loose them, but we also don't want to process them while
            // we're hoping for a predictable document content changes.
            return;
        }

        this.processQueuedMessages();
    }

    /**
     * Converts an offset in collaboration buffer coordinates to a VS Code position for the given document.
     */
    public toVSCodeDocumentPos(collabOffset: number): vscode.Position {
        const collabPos = this.collabBuffer.positionAt(collabOffset);
        const vsCodePos = new vscode.Position(collabPos.line, collabPos.character);
        return vsCodePos;
    }

    /**
     * Converts a VS Code position to an offset in collaboration buffer coordinates for this buffer.
     */
    public toCollabOffset(vsCodePos: vscode.Position): number {
        const collabPos = new CollabBufferPosition(vsCodePos.line, vsCodePos.character);
        const collabOffset = this.collabBuffer.offsetAt(collabPos);
        return collabOffset;
    }

    public getBufferManagerStatus(): BufferManagerStatus {
        let operationalTransformStatus = this.otAlgorithm.getOperationalTransformStatus();
        return {
            serverVersion: operationalTransformStatus.serverVersion,
            unacknowledgedCount: operationalTransformStatus.unacknowledgedCount,
            waitingForRemoteEditsToBeApplied: !!this.pendingApplicationOfRemoteEdit,
            localChangesQueue: this.localChangesQueue.length,
            remoteMessagesQueue: this.remoteMessagesQueue.length,
            collabBufferText: this.collabBuffer.getContent()
        };
    }

    public getCurrentHistory(): vsls.ServerVersionSnapshot[] {
        const history = this.otAlgorithm.getCurrentHistory();
        return history.map((serverVersion): vsls.ServerVersionSnapshot => {
            return {
                message: serverVersion.Message || undefined,
                serverVersionNumber: serverVersion.serverVersionNumber
            };
        });
    }

    public initializeHistory(fileOpenAcknowledgeMsg: vsls.FileOpenAcknowledgeMessage): void {
        const receivedHistory = fileOpenAcknowledgeMsg.history || [];
        const initialHistory: ServerVersion[] = [
            new ServerVersion(fileOpenAcknowledgeMsg.startServerVersionNumber || -1, null)
        ];

        // Use the received history to initialize our own OT state to be at the
        // same level. Note, there may be messages that happened after the remote
        // file was saved. We can't just splat those changes into the history, we
        // have to allow them to process through the normal mechanisms (e.g.
        // treat them like we got them as discrete messages from other clients)
        receivedHistory.forEach((serverVersion) => {
            const serverVersionNumber = serverVersion.serverVersionNumber!;
            if (serverVersionNumber <= (fileOpenAcknowledgeMsg.savedVersionNumber || 0)) {
                initialHistory.push(new ServerVersion(serverVersionNumber, serverVersion.message!));
                this.highestQueuedEventId = serverVersionNumber;
                return;
            }

            if (serverVersionNumber > this.initialHistoryHighWaterMark) {
                this.initialHistoryHighWaterMark = serverVersionNumber;
            }

            // Since these messages are after the saved revision, process them
            // like any other normal remotely received messages.
            const messageWithDefaults = MessageFactory.CoauthoringMessage(serverVersion.message!);
            this.onIncomingMessage(messageWithDefaults, serverVersionNumber, CoeditingIncomingMessageBehavior.Queue);
        });

        this.otAlgorithm.setInitialHistory(initialHistory);
    }

    public updateInitialHistoryHighWatermark(serverVersionNumber: number): void {
        if (this.initialHistoryHighWaterMark > serverVersionNumber) {
            return;
        }

        this.initialHistoryHighWaterMark = serverVersionNumber;
    }

    public undoLastLocalEdit(): boolean {
        this.host.trace.verbose(`Undo: Received Local Undo Request for ${TraceFormat.formatPath(this.fileName)}`);

        if (this.performingUndo) {
            // If we're already undoing a change, we should drop any other undo
            // requests that come. This means we're going to tell a fib saying
            // we 'handled it', when in reality, we're just droping the request
            // on the floor.
            this.host.trace.verbose('Undo: Already performing undo, not handling this undo');
            return true;
        }

        // If the last change was a local change, we don't need to explicitly
        // handle it -- the editor will undo it, and we'll see the changes, and
        // propogate. Additionally, if you share a session, and undo before making
        // any changes, we need to let VS handle that too
        if ((this.lastChangeSource === LastChangeSource.Local && this.localToRemoteTransitions.length < 1)
            || (this.lastChangeSource === LastChangeSource.Unknown && this.localToRemoteTransitions.length === 0)) {
            this.localUndoCount++;
            this.redoWouldRedoLocalUndo = true;
            this.host.trace.verbose(`Undo: Last change was local, let editor handle. Source: ${this.lastChangeSource}, Count: ${this.localToRemoteTransitions.length}`);
            return false;
        }

        // We have something we might be able to undo (E.g. we received some
        // remote edits). However, we've never seen any local edits, and we've
        // been monitoring all edits to this document, so we know there are none
        // from before time. This means nothing for the editor to actually undo
        if (!this.hasEverHadALocalEdit) {
            // Claim we've handled it, since theres nothing for us to undo before
            // the remote edits.
            this.host.trace.verbose('Undo: No local edits ever seen, with remote edits, nothing to undo');
            return true;
        }

        if (this.lastChangeSource === LastChangeSource.Local && this.localToRemoteTransitions.length > 0) {
            // When there is a local edit, and we have some transitions (e.g. we're
            // on the leading edge of local changes), we need to let the editor do
            // the undo locally, but check the buffer state after to see if we're
            // now back to the point in the buffer where we transitioned from remote
            // to local.
            this.host.trace.verbose('Undo: Last edit was local, performing undo to update transitions');
            this.performingUndo = PerformingUndoState.ApplyingEdits;
            this.redoWouldRedoLocalUndo = true;
            this.localUndoCount++;
            this.host.performSingleUndo().then(() => {
                this.performingUndo = PerformingUndoState.None;
                const transition = this.localToRemoteTransitions[this.localToRemoteTransitions.length - 1];
                if (this.collabBuffer.getContent() !== transition.beforeTransitionToLocal) {
                    this.host.trace.verbose('Undo: Editor undo complete, but still more that could be undo');
                    // we've got more local edits we might be able to undo so
                    // just leave us where we are.
                    return;
                }

                this.host.trace.verbose('Undo: Reached state of last remote edit. Updating status');
                // We reached the state where we transitioned to the state we had
                // before we saw any local updates, so update to having been remote
                transition.beforeTransitionToLocal = null;
                this.lastChangeSource = LastChangeSource.Remote;
                this.hasEverHadALocalEdit = transition.hadLocalEdits;
            });

            return true;
        }

        // We need to start undoing until this buffer reaches the point where it
        // has the state before any local updates

        assert(this.localToRemoteTransitions.length > 0, 'No local changes, but no transitions');
        let originalLocalToRemoteTransitions = this.localToRemoteTransitions.length;
        let targetBufferState = this.localToRemoteTransitions[this.localToRemoteTransitions.length - 1];

        if (!targetBufferState.beforeTransitionToRemote) {
            // We're at a state where there wasn't anything before we applied remote
            // edits. This is to handle the case of late join -- edits are already
            // applied relative to saved state on the host, and we join later, and
            // those deltas from the saved state are applied as edits. In that case
            // we consider the point those edits have completed applying as being
            // the back stop, so consider this case handled since there isn't
            // anything to undo.
            return true;
        }

        // We're now capturing the edits, so ensure that any changes we see are
        // ignored by our normal processing mechanisms.
        this.performingUndo = PerformingUndoState.CapturingEdits;

        this.remoteUndoCount++;
        this.collabBuffer.startCapturingEditsFromUndoing();
        this.host.trace.verbose('Undo: Rolling back buffer to before the last remote edit');

        let undoEdits: vscode.TextDocumentContentChangeEvent[];
        let realEdits: ITextChange[];
        let documentContents: string;
        let collabBuffer: CollabBuffer;
        let ot: OTAlgorithm;
        const changeMessages: vsls.TextChangeMessage[] = [];
        let rollbackChanges: vsls.TextChange[];
        let documentContentsToRedoTo: string;

        // 1. Revert the buffer to the original state after the edit we want to
        //    undo was completed.
        this.host.undoBufferToMatchContents(targetBufferState.beforeTransitionToRemote).then((documentBeforeUndos) => {
            documentContentsToRedoTo = documentBeforeUndos;
            // 2. Do 1 undo, which will give us the edits that undo would
            //    perform, as well as the resultant buffer content.
            return this.host.performSingleUndo();
        }).then((result) => {
            undoEdits = result.edits;
            documentContents = result.contents;

            // 3. Inspect our transitions, and update the information in them so
            //    that the next undo can do the right thing (e.g. roll the buffer
            //    back to the right state.
            assert(this.localToRemoteTransitions.length === originalLocalToRemoteTransitions, 'Didn\'t expect transitions while we were undoing');

            // We've got enough information to complete this transition now, so
            // remove it from the stack so we fallback to the _next_ undo when
            // the next undo is performed.
            this.localToRemoteTransitions.pop();
            let previousStateTransition = (this.localToRemoteTransitions.length > 0) ? this.localToRemoteTransitions[this.localToRemoteTransitions.length - 1] : null;

            // If the content before the undo matched the content after, that means
            // there are no more local undos, and we can stop trying them.
            const noMoreLocalUndos = (documentContents === documentContentsToRedoTo);

            // When we have a previous state, and it's content before the local
            // edit was applied now matches our current buffer state, it means
            // there basically isn't a state transition. If it doesn't match we're
            // still in a world where we're going to want to allow local undos to
            // keep undoing themselves when we attempt an undo
            if (previousStateTransition && previousStateTransition.beforeTransitionToLocal !== documentContents) {
                // Since the undo operation locally might undo one part of the
                // delta between the remote state, and the local state (E.g. the
                // IDE created an undo stop in during the customers edits), so if the
                // customer hits undo again, we'll perform undos of the remote
                // changes again to get to the state "before" the remote edits.
                // Which means we need to update the state we were aiming for.
                this.host.trace.verbose('Undo: Still more local undos; updating state');
                targetBufferState.beforeTransitionToRemote = documentContents;
                this.localToRemoteTransitions.push(targetBufferState);
            }

            if (this.localToRemoteTransitions.length < 1) {
                this.host.trace.verbose('Undo: No more local-remote states changes, cleaning up');
                // We need to fill in the 'back' stop state -- e.g. if someone does
                // undo again, we need to know when we've reverted back all the edits
                // so we need to implicitly push one back into the transition list
                // and assume our last edit was remote
                this.lastChangeSource = LastChangeSource.Remote;

                // Since there are no longer any transitions, but we were undoing
                // a remote edit, we need to consider that we might have reached
                // a point where there are no more local undos to undo. If undoing
                // didn't result in any local changes, we can consider us as having
                // no local edits.
                this.localToRemoteTransitions.push({ beforeTransitionToRemote: documentContents, hadLocalEdits: !noMoreLocalUndos });
                this.hasEverHadALocalEdit = !noMoreLocalUndos;
            }

            // 4. Redo the one change we just undid, so we can get a consistent
            //    buffer view we can operational-transform some changes through.
            //    This means our undo edits we captured above in (2) can be
            //    transformed into changes that we'll be able to apply to our
            //    original-nothing-undone state.
            return this.host.performSingleRedo();
        }).then((initialContent) => {
            // 5. Take the buffer state (with the edit we're going to attempt to
            //    undo), and create an OT + Buffer to generate isolated edits.
            //    Why not use the real buffer/OT? Because we've suspended it, and
            //    don't want the changes we're making for undoing to propogate
            //    to other clients, or fight against incoming changes.
            collabBuffer = new CollabBuffer(initialContent, this.host.trace);

            const self = this;
            const algorithmHost = new class implements IOTAlgorithmHost {
                public get fileName(): string {
                    return self.fileName;
                }

                // Changes from our redo will appear to be from client 1. We'll
                // use a different one later so that the OT actually transforms
                // the messages.
                public clientID = 1;
                public clientCount = self.host.clientCount;
                public trace = self.host.trace;
                public postMessage(msg: vsls.TextChangeMessage): void {
                    changeMessages.push(msg);
                }
            };

            ot = new OTAlgorithm(algorithmHost, this.diagnosticTrace);

            // 6. Convert the vscode text changes to TextChanges *now* because
            //    the state of the buffer determines the actual edits, and we want
            //    to replay them against a future snapshot _as they exist now_.
            realEdits = undoEdits.reduce((previous, edit) => {
                const [bufferStart, bufferEnd, bufferText] = CollabBuffer.convertVsCodeContentChangeToCollabChange(edit, collabBuffer);
                const textChange = collabBuffer.convertCollabufferChangeToITextChange(bufferStart, bufferEnd, bufferText);
                const compressed = compressConsecutiveTextChanges(previous, [textChange]);

                return compressed;
            }, [] as ITextChange[]);

            // 7. Redo everything till we have no more redos (E.g. we're in a
            //    state that matches our real OT/CollabBuffer), applying each
            //    edit that we see in the redo to our OT+CollabBuffer
            return this.host.redoUntilNoMoreToRedo(documentContentsToRedoTo, (e) => acceptLocalChangeOnBuffer(e, collabBuffer, ot));
        }).then(() => {
            // 8. Accept all the changes we saw, 'cause they're real.
            changeMessages.forEach((c, index) => {
                ot.acceptTextChangeAcknowledge(c, index);
            });

            const textChanges = realEdits.map((c) => MessageFactory.TextChange(c.oldPosition, c.oldLength, c.newText));

            // Pretend to be a different client so the message actually gets transformed
            let message = MessageFactory.TextChangeMessage(2, this.fileName, undefined, -1, textChanges);

            // 9. Transform the edits from the undo, on the original buffer state
            //    through to the redo edits to result on a message represents
            //    undoing the change against the 'current' state of the buffer.
            message = ot.TransformMessageToCurrent(message);

            // 10. Convert it into something we can ask vscode to apply against
            //     the document state.
            const edits = ot.transformMessageToEdits(collabBuffer.getMaximumOffset(), message);
            const changes = collabBuffer.transformEditsToTextChanges(edits);
            const workspaceEdits = changes.map(change => mapTextChangeToEditorEditForBuffer(change, collabBuffer));

            rollbackChanges = changes.map((change) => {
                return MessageFactory.TextChange(change.newPosition, change.newLength, change.oldText);
            });

            // 11. Apply them.
            this.performingUndo = PerformingUndoState.ApplyingEdits;
            return this.host.applyEdit(workspaceEdits);
        }).then(() => {
            const serverVersion = this.otAlgorithm.getOperationalTransformStatus().serverVersion;
            this.localRedoStack.push({
                redoChanges: rollbackChanges,
                serverVersion: serverVersion,
            });
            this.host.trace.verbose('Undo: Local undo complete');
            this.performingUndo = PerformingUndoState.None;
        }, (err) => {
            Telemetry.sendFault(TelemetryEventNames.UNDO_FAILURE, FaultType.Error, 'Failure to apply a local undo with remote edits', err);
            this.performingUndo = PerformingUndoState.None;
        });

        return true;
    }

    public redoLastLocalEdit(): boolean {
        if (this.lastChangeSource === LastChangeSource.Local || this.redoWouldRedoLocalUndo) {
            return false;
        }

        if (!featureFlags.localRedo) {
            // If the local redo feature is off, we dont want to let the editor
            // redo something while we have a remote edit. Returning true here
            // indiciates to the caller that we don't want VSCode to do anything
            return true;
        }

        // Last edit was remote, but we don't have anything to redo. We don't
        // want the editor to try a redo, so lets claim we handled it.
        if (this.localRedoStack.length < 1) {
            return true;
        }

        assert(this.localRedoStack.length > 0, 'We don\'t have any items to redo');

        // Get the edits to redo the buffer, and transform them from their original
        // OT version to our current state
        const redoToApply = this.localRedoStack.pop()!;
        let message = MessageFactory.TextChangeMessage(-1, this.fileName, undefined, redoToApply.serverVersion, redoToApply.redoChanges);
        message = this.otAlgorithm.TransformMessageToCurrent(message);

        // Convert the edits into something that we can actually apply to the buffer
        const edits = this.otAlgorithm.transformMessageToEdits(this.collabBuffer.getMaximumOffset(), message);
        const changes = this.collabBuffer.transformEditsToTextChanges(edits);
        const workspaceEdits = changes.map(change => mapTextChangeToEditorEditForBuffer(change, this.collabBuffer));

        // Actually apply the edits to the document.
        this.performingUndo = PerformingUndoState.ApplyingEdits;
        this.host.applyEdit(workspaceEdits).then(
            () => this.performingUndo = PerformingUndoState.None,
            (err) => {
                Telemetry.sendFault(TelemetryEventNames.REDO_FAILURE, FaultType.Error, 'Failure to apply a local redo with remote edits', err);
                this.performingUndo = PerformingUndoState.None;
            }
        );

        return true;
    }

    public clearUndoStateDueToDocumentClosing(): void {
        this.localRedoStack.length = 0;
        this.localToRemoteTransitions.length = 0;
        this.hasEverHadALocalEdit = false;

        // Since we're clearing it, it means we've had this open, and when (if)
        // it gets reopened, we'll assuming changes are remote (likley they'll
        // be replayed) -- even if we issued them locally.
        this.host.trace.verbose(`Undo: Clearing Local Undo State due to document close: ${TraceFormat.formatPath(this.fileName)}`);
        this.lastChangeSource = LastChangeSource.Remote;
        this.localToRemoteTransitions.push({
            hadLocalEdits: this.hasEverHadALocalEdit,
            beforeTransitionToRemote: this.collabBuffer.getContent(),
        });
    }

    public takeSnapshot(): void {
        const snapshot = this.makeSnapshot();
        this.saveSnapshots[snapshot.hashCode] = snapshot;
    }

    public getSavedSnapshotOrFallback(fileHashCode: number): SaveSnapshot {
        if (this.saveSnapshots[fileHashCode]) {
            return this.saveSnapshots[fileHashCode];
        }

        const snapshot = this.makeSnapshot();
        snapshot.fallbackText = this.collabBuffer.getContent();
        return snapshot;
    }

    private makeSnapshot(): SaveSnapshot {
        const currentContent = this.collabBuffer.getContent();
        const syncStatus = this.otAlgorithm.getOperationalTransformStatus();
        return {
            changes: syncStatus.unacknowledged.map((unack) => unack.rollbackEdits).reverse(),
            hasUnacknowledgedChanges: syncStatus.unacknowledgedCount > 0,
            hashCode: calculateFileHash(currentContent),
            serverVersionNumber: syncStatus.serverVersion
        };
    }

    private checkSync() {
        this.host.trace.verbose(`checkSync for ${TraceFormat.formatPath(this.fileName)}`);
        this.host.checkSync(this.collabBuffer.getContent());
    }

    private recordSyncedState() {
        const snapshot = this.makeSnapshot();
        if (this.isHost) {
            this.syncManager.recordSnapshot(snapshot);
            return;
        }

        if (!snapshot.hasUnacknowledgedChanges) {
            this.host.checkHostSync(snapshot.serverVersionNumber, snapshot.hashCode);
        }
    }

    public processQueuedMessages(): void {
        if (this.pendingApplicationOfRemoteEdit !== null) {
            // There is a pending edit we are waiting for, cannot advance now
            this.host.trace.verbose('Skipping step due to pending edit');
            return;
        }

        if (this.diagnosticTrace) {
            logger.logTrace(this.host.trace, 'step');
            logger.indent();
            logger.logTrace(this.host.trace, `before local changes - collabbuffer: ` + colorize.cyan(JSON.stringify(this.collabBuffer.getContent())));
        }

        const hadLocalChanges = this.localChangesQueue.length > 0;
        // First, we pump all the local changes
        while (this.localChangesQueue.length > 0) {
            let localChange = this.localChangesQueue.shift()!;
            this._acceptLocalChange(localChange);
        }

        // this.pendingApplicationOfRemoteEdit === null (because there's only been sync work since checking)
        // so we know there are no remote changes that aren't accounted for. All local changes have now been accounted for
        // (because there's only been sync work since this.localChangesQueue.length === 0). Therefore we should be in sync here.
        if (hadLocalChanges) {
            this.checkSync();
        }

        if (this.diagnosticTrace) {
            logger.logTrace(this.host.trace, `after localchanges - collabbuffer: ` + colorize.cyan(JSON.stringify(this.collabBuffer.getContent())));
        }

        let continueProcessing = true;
        // Then, we handle remote messages
        while (this.remoteMessagesQueue.length > 0 && continueProcessing) {
            const peekMsg = this.remoteMessagesQueue[0];
            const clientId = peekMsg.message.clientId;
            const msgType = peekMsg.message.messageType;

            if (clientId === undefined) {
                this.host.trace.error(`Message ${msgType} is missing client ID.`);
                continue;
            }

            switch (msgType) {
                case vsls.MessageType.TextChange:
                    // Certain messages mean we should stop processing the items
                    // until their completed. In that case, we'll signal the loop
                    // to break, and jump to the next interation
                    continueProcessing = this._handleTextChangeMessage(clientId, peekMsg);
                    continue;

                case vsls.MessageType.SelectionChange:
                    try {
                        this._handleSelectionChangeMessageIfMostRecent(clientId, peekMsg);
                    } catch (e) {
                        this.host.trace.error(`Error handling selection change in file: ${TraceFormat.formatPath(this.fileName)}`);
                        throw e;
                    }
                    break;

                default:
                    const errMsg = `Unexpected message type in buffer manager (${TraceFormat.formatPath(this.fileName)}): ${msgType}`;
                    this.host.trace.error(errMsg);
                    this.remoteMessagesQueue.shift();
                    assert(false, errMsg);
                    break;
            }
        }

        if (this.diagnosticTrace) {
            logger.unindent();
        }
    }

    private _handleTextChangeMessage(forClientId: number, withMessage: MessageAndVersionNumber): boolean {
        if (forClientId === this.host.clientID) {
            this.host.trace.verbose(`Received text change acknowledge for ${TraceFormat.formatPath(this.fileName)}`);
            // Becuause this is our own message, it can be processed synchronously
            // and the caller can keep processing any other messages still pending
            // in the remote message queue.
            this.remoteMessagesQueue.shift();
            this.otAlgorithm.acceptTextChangeAcknowledge(withMessage.message as vsls.TextChangeMessage, withMessage.serverVersionNumber);

            this.recordSyncedState();

            return true;
        }

        // For remote changes, we want to completely apply them one-at-a-time
        // So start applying the message, but inform the caller that they should
        // hold off processing any other changes.
        this._beginApplyingRemoteChange(withMessage.message as vsls.TextChangeMessage, withMessage.serverVersionNumber);
        return false;
    }

    private _handleSelectionChangeMessageIfMostRecent(forClientId: number, withMessage: MessageAndVersionNumber): void {
        // We only want to process the last selection change message for a given client ID before the next text
        // change message (or the queue end). Check if there are subsequent selection change messages in the
        // queue for this client ID, and if so, simply ignore this message.
        let foundSubsequentSelectionChange = false;
        for (let i = 1; i < this.remoteMessagesQueue.length; ++i) {
            const msg = this.remoteMessagesQueue[i].message;
            if (msg.clientId === forClientId) {
                foundSubsequentSelectionChange = msg.messageType === vsls.MessageType.SelectionChange;
                break;
            }
        }

        if (!foundSubsequentSelectionChange) {
            // No newer selection change messages found, handle this one.
            const transformedMessage = this.transformSelectionToCurrent(<vsls.SelectionChangeMessage>withMessage.message);
            this.host.updateClientPosition(transformedMessage);
        }

        this.remoteMessagesQueue.shift();
    }

    private _acceptLocalChange(e: vscode.TextDocumentChangeEvent): void {
        this.host.trace.verbose(`_acceptLocalChange for ${TraceFormat.formatPath(this.fileName)}`);

        if (this.lastChangeSource === LastChangeSource.Remote && !this.performingUndo) {
            this.host.trace.verbose(`Undo: Transitioning to local for ${TraceFormat.formatPath(this.fileName)}`);
            this.localToRemoteTransitions[this.localToRemoteTransitions.length - 1].beforeTransitionToLocal = this.collabBuffer.getContent();
        }

        // If we're not undoing changes, we'll change the last change type to
        // local. This is important because when we're undoing our changes, we're
        // going to see the undoing of the remote changes, and the re-application
        // of the remote changes as local (because we're applying them ourselves)
        if (!this.performingUndo) {
            this.hasEverHadALocalEdit = true;
            this.lastChangeSource = LastChangeSource.Local;
            this.redoWouldRedoLocalUndo = false;

            // We got a local change, so we need to clear our redo-stack since
            // we've pushed things forward, and thus we're not logically at the
            // first 'local' edit, rather than moving back through the edit stack
            this.localRedoStack.length = 0;
        }

        acceptLocalChangeOnBuffer(e, this.collabBuffer, this.otAlgorithm);
    }

    private _beginApplyingRemoteChange(message: vsls.TextChangeMessage, serverVersionNumber: number): void {
        this.host.trace.verbose(`_beginApplyingRemoteChange for ${TraceFormat.formatPath(this.fileName)}`);

        // Capture the state of the buffer immediately before we apply any remote edits
        // This is to enable us to be able to roll-back to this point, and then actually
        // peform a real undo.
        let insertedTransition = -1;
        if (this.lastChangeSource !== LastChangeSource.Remote) {
            assert(!this.performingUndo, 'Shouldn\'t see remote changes while undoing');
            this.host.trace.verbose(`Undo: Transitioning to Remote for ${TraceFormat.formatPath(this.fileName)}`);
            // When we're applying a remote change from the initial history, we
            // dont want to capture the content, because we think of that as part
            // of the initial document, and one can't go "undo" that, since you
            // couldn't have applied any local edits
            const currentBuffer = (serverVersionNumber > this.initialHistoryHighWaterMark) ? this.collabBuffer.getContent() : null;
            insertedTransition = this.localToRemoteTransitions.push({ beforeTransitionToRemote: currentBuffer, hadLocalEdits: this.hasEverHadALocalEdit });
        }

        let originalLastChangeSource = this.lastChangeSource;
        this.lastChangeSource = LastChangeSource.Remote;

        this.redoWouldRedoLocalUndo = false;

        let algoState = this.otAlgorithm.saveState();
        this.collabBuffer.beginRecording();

        this.otAlgorithm.acceptRemoteChange(this.collabBuffer, message, serverVersionNumber);
        let [edits, unexpandedEdits] = this.collabBuffer.endRecording();

        // Filter out the edits that aren't actually doing anything.
        edits = edits.filter(edit => !((edit.newLength === 0) && (edit.oldLength === 0)));

        // lucky us, the OT algorithm wants to ... do nothing on the buffer
        if (edits.length === 0) {
            // Remove the message now it's (effectively) been processed, and
            // get on with processing any more queued messages.
            this.remoteMessagesQueue.shift();
            this.processQueuedMessages();
            return;
        }

        this.host.trace.verbose(`Rolling back changes made by OT to the collab buffer for ${TraceFormat.formatPath(this.fileName)}`);
        // Undo the changes against the collab buffer, so we can subsequently
        // apply the clear edits against the local buffer.
        this.collabBuffer.applyRemoteEdits(edits.map((e) => {
            return {
                position: e.newPosition,
                length: e.newLength,
                text: e.oldText
            };
        }));

        // Map the raw edits we're processing into actual edits to apply to our
        // real editor, rather than our local buffer
        let vscodeEdits: vscode.TextEdit[] = edits.map((edit: ITextChange) => {
            return mapTextChangeToEditorEditForBuffer(edit, this.collabBuffer);
        });

        if (this.diagnosticTrace) {
            logger.logTrace(this.host.trace, `sending edit request to ext host: ` + JSON.stringify(edits));
            logger.logTrace(this.host.trace, `sending edit request to ext host: ` + JSON.stringify(vscodeEdits));
        }

        // Set a pending edit so any of our other events can merely queue events
        // until the pending edits are processed and we have a stable state again
        this.pendingApplicationOfRemoteEdit = new PendingEdit(algoState, edits);

        this.host.applyEdit(vscodeEdits, (message as any as ITracked).trackingId).then((applied) => {
            if (applied === ApplyEditResult.FAILED) {
                CoauthoringTelemetry.ReportCoeditingError('Failed to apply edits');
                this._finishApplyingRemoteChangeFail(originalLastChangeSource, insertedTransition);
                return;
            }

            this._finishApplyingRemoteChangeOK(applied);
        }, (err) => {
            this.host.trace.warning(`Error while applying edits`);
            CoauthoringTelemetry.ReportCoeditingError('Error while applying edits', err);
            this._finishApplyingRemoteChangeFail(originalLastChangeSource, insertedTransition);
        });
    }

    private async _finishApplyingRemoteChangeOK(applied: ApplyEditResult): Promise<void> {
        this.host.trace.verbose(`_finishApplyingRemoteChangeOK for ${TraceFormat.formatPath(this.fileName)}`);

        // Ignore the document changes caused by us. They should be in one giant
        // atomic change on this document, because thats how we're applying them
        // to the workspace via the host.
        // TODO: this assert is too strong. It should instead verify that the first
        // change on the local changes queue is the one we applied.
        assert(this.localChangesQueue.length === 1, `expected a single local change caused by my own edit, but got ${this.localChangesQueue.length}`);
        this.localChangesQueue.shift();

        // pop the remote change that caused this
        this.remoteMessagesQueue.shift();

        this.host.trace.verbose(`Applying remote edits to collab buffer for ${TraceFormat.formatPath(this.fileName)}`);
        // move the collab buffer forward
        this.collabBuffer.applyRemoteEdits(this.pendingApplicationOfRemoteEdit.pendingEdit.map((ed) => {
            return {
                position: ed.oldPosition,
                length: ed.oldLength,
                text: ed.newText
            };
        }));

        if (applied === ApplyEditResult.MODIFIED) {
            try {
                await this.host.resync();
            } catch (e) {
                // TODO alert the user and possibly terminate the Live Share session.
                assert(false, 'Resync should complete successfully');
            }
        }
        this.pendingApplicationOfRemoteEdit = null;

        // If this.localChangesQueue.length === 0, all local changes are accounted for,
        // and we just finished with the only remote change to account for. Therefore we should be in sync here.
        // If this.localChangesQueue.length !== 0, the call to this.processQueuedMessages below will go through
        // them, and we'll perform a sync check once we're done accounting for them.
        if (this.localChangesQueue.length === 0) {
            this.checkSync();
        }

        this.recordSyncedState();
        this.processQueuedMessages();
    }

    private _finishApplyingRemoteChangeFail(originalLastChangeSource: LastChangeSource, transitionIndex: number): void {
        this.host.trace.info(`Applying edits to main buffer failed for ${TraceFormat.formatPath(this.fileName)}`);
        let pendingEdit = this.pendingApplicationOfRemoteEdit!;
        this.pendingApplicationOfRemoteEdit = null;

        // We only want to actually pop local/remote transitions if we'd added
        // something to the list, and we're at the same point in the list -- if
        // we hadn't added to the to this list, the originally pushed state is
        // valid, and popping it will remove useful information.
        if ((transitionIndex > -1)
            && (transitionIndex === (this.localToRemoteTransitions.length - 1))
            && (this.lastChangeSource !== originalLastChangeSource)
        ) {
            // Something went wrong applying these updates, which means the buffer
            // state we captured isn't relevant; we need to remove it, and give up.
            this.localToRemoteTransitions.pop();
            this.lastChangeSource = originalLastChangeSource;
        }

        // Because we couldn't apply the edits, we need to roll back all the
        // changes we'd asked the OT state to apply so we can attempt them again
        // in the future.
        this.otAlgorithm.loadState(pendingEdit.algorithmState);

        this.processQueuedMessages();
    }

    private transformRangeToCurrent(clientId: number, fileName: string, fileVersion: number, serverVersionNumber: number, range: vsls.Range): vsls.Range & { changeServerVersion: number } {
        // Use a dummy text change message and run it through the transform manager to get the equivalent range
        // transform.
        const tc = MessageFactory.TextChange(range.start, range.length, '');
        const tcMsg = MessageFactory.TextChangeMessage(clientId, fileName, fileVersion, serverVersionNumber, [tc]);
        const transformedTcMessage = this.otAlgorithm.TransformMessageToCurrent(tcMsg);
        return {
            start: (transformedTcMessage.changes && transformedTcMessage.changes[0].start) || 0,
            length: (transformedTcMessage.changes && transformedTcMessage.changes[0].length) || 0,
            changeServerVersion: transformedTcMessage.changeServerVersion
        };
    }

    private transformSelectionToCurrent(scMsg: vsls.SelectionChangeMessage): vsls.SelectionChangeMessage {
        const transformedRange = this.transformRangeToCurrent(scMsg.clientId, scMsg.fileName, scMsg.fileVersion, scMsg.serverVersionNumber, { start: scMsg.start, length: scMsg.length });
        return MessageFactory.SelectionChangeMessage(scMsg.clientId,
            scMsg.fileName,
            scMsg.fileVersion,
            transformedRange.changeServerVersion,
            transformedRange.start,
            transformedRange.length,
            scMsg.isReversed,
            scMsg.kind,
            scMsg.forceJumpForClientId);
    }

    public transformVisibleRangesToCurrent(clientId: number, editorVisibleRanges: vsls.EditorVisibleRanges): vsls.EditorVisibleRanges {
        const visibleRanges: vsls.Range[] = editorVisibleRanges.visibleRanges.map(range => this.transformRangeToCurrent(clientId, editorVisibleRanges.fileName, undefined, editorVisibleRanges.serverVersionNumber, range));
        return {
            fileName: editorVisibleRanges.fileName,
            serverVersionNumber: editorVisibleRanges.serverVersionNumber,
            visibleRanges
        };
    }

    private remoteQueueContainsSelectionChange(): boolean {
        return this.remoteMessagesQueue.some((message) => {
            return (message.message.messageType === vsls.MessageType.SelectionChange);
        });
    }

    public transformScrollSelectionToCurrent(scMsg: vsls.LayoutScrollMessage): vsls.LayoutScrollMessage | null {
        if (this.remoteQueueContainsSelectionChange()) {
            return null;
        }

        const transformedPrimaryRange = this.transformRangeToCurrent(scMsg.clientId, scMsg.fileName, scMsg.fileVersion, scMsg.serverVersionNumber, { start: scMsg.start, length: scMsg.length });
        const transformedRanges = (scMsg.visibleRanges || []).map(range => this.transformRangeToCurrent(scMsg.clientId, scMsg.fileName, scMsg.fileVersion, scMsg.serverVersionNumber, range));

        return MessageFactory.LayoutScrollMessage(scMsg.clientId,
            scMsg.fileName,
            scMsg.fileVersion,
            transformedPrimaryRange.changeServerVersion,
            transformedPrimaryRange.start,
            transformedPrimaryRange.length,
            scMsg.editorId,
            transformedRanges);
    }

    // NB: "Handshake" is a misleading name for this message. This message is sent from the host
    // any time a new "official" OT state is reached.
    private postHandshake(): void {
        const snapshot = this.makeSnapshot();
        const handshakeMsg = MessageFactory.HandshakeMessage(this.host.clientID,
            this.fileName,
            snapshot.hashCode,
            snapshot.serverVersionNumber);
        this.host.postMessage(handshakeMsg);
    }

    public isFileSyncedForVersion(serverVersionNumber: number, fileHash: number): Promise<boolean> {
        return this.syncManager.isFileSyncedForVersion(serverVersionNumber, fileHash);
    }

    public onHandshake(handshake: vsls.HandshakeMessage) {
        for (let i = 0; i < this.cachedHandshakes.length; i++) {
            const cachedHandshake = this.cachedHandshakes[i];
            if (cachedHandshake.serverVersionNumber === handshake.serverVersionNumber) {
                // The handshake message refferred to this item in the cache. We remove it and everything earlier from the cache.
                this.cachedHandshakes.splice(0, i + 1);
                this.compareHandshake(handshake, cachedHandshake);
                break;
            } else if (handshake.serverVersionNumber !== undefined &&
                cachedHandshake.serverVersionNumber > handshake.serverVersionNumber
            ) {
                // The handshake message referred to something we didn't have in the cache
                // and we know any subsequent handshake message will have a higher server version number
                // so we can discard the earlier handshakes.
                this.cachedHandshakes.splice(0, i);
                break;
            }
        }
    }

    private async compareHandshake(handshake: vsls.HandshakeMessage, cachedHandshake: SaveSnapshot) {
        if (handshake.hashCode !== cachedHandshake.hashCode) {
            const fileNamePieces = this.fileName.split('.');
            const fileExtension = fileNamePieces.length > 1 ? fileNamePieces.pop() : 'NA';
            const moniker = PathUtil.getMonikerFromRelativePath(this.fileName).moniker || 'None';
            if (previousDesync) {
                CoauthoringTelemetry.ReportDesync(DesyncReason.Unknown, fileExtension, moniker, true);
                await vscode.window.showInformationMessage(`Live Share: The current document is out of sync with the host, and reconnecting did not resolve the issue. Please ask the host to end and reshare the session.`, { modal: true });
            } else {
                CoauthoringTelemetry.ReportDesync(DesyncReason.Unknown, fileExtension, moniker);
                const reconnect = { title: 'Reconnect' };
                const result = await vscode.window.showInformationMessage(`Live Share: The current document is out of sync with the host. Please try reconnecting to the session.`, { modal: true }, reconnect);
                if (result === reconnect) {
                    CoauthoringTelemetry.ReportDesyncReload();
                    await Settings.save(SettingKeys.desyncReload, true);
                    await ExtensionUtil.setTransientWorkspace(false);
                    vscode.commands.executeCommand('workbench.action.reloadWindow');
                }
            }
        }
    }

}

let previousDesync = false;
export function desyncReload() {
    previousDesync = true;
}
