import * as os from 'os';
import * as path from 'path-browserify';

import { setExtensionContext } from './util/ExtentionContext';
import { commandRegistry } from './commands/CommandRegistryProvider';
import { IVSLSCommandsAPI } from './types/IVSLSCommandsAPI';
import { IVSLSCommandsAPIOptions, ILoggingOptions } from './types/IVSLSCommandsAPIOptions';
import { LoggingUtil } from './tracing/loggingUtil';
import { ABTester } from './ab-tester/abTester';
import { isFirstActivation, isExtensionBeingUpdated } from './util/isFirstInitialization';
import { getPackageJSON } from './util/getPackageJSON';
import { throwNotInitialized } from './util/throwIfNotInitialized';
import { getLastFiles } from '@vscode-abstractions/fileUtils';
import { Telemetry } from '@vs/vso-telemetry';
import { telemetryReporterFactory } from '@vscode-abstractions/telemetryReporterFactory';
import { setLogLocation, getLogLocation } from '@vscode-abstractions/logFile';
import { LogLevel } from '@vs/vso-logging';

export let abTester: ABTester;
class VSLSCommandsAPI implements IVSLSCommandsAPI {
    private loggingUtil!: LoggingUtil;
    constructor(options: IVSLSCommandsAPIOptions) {
        // save extension context for further imports
        setExtensionContext(options.extensionContext);

        if (options.telemetry) {
            Telemetry.init(
                telemetryReporterFactory.create(options.extensionPackage),
                options.telemetry.featureName || 'vscode-vsls-command.',
                options.telemetry.canSendSensistiveInformation,
                options.telemetry.faultSendCallbackParam,
            );
        }
    }

    public async initLogging(extensionPackage: any, loggingOptions: ILoggingOptions) {
        // initialize tracing
        if (loggingOptions.logFileEnabled) {
            setLogLocation(
                loggingOptions.logFilePath ||
                    path.join(os.tmpdir(), `${extensionPackage.name}_logs`),
            );
        }

        this.loggingUtil = new LoggingUtil(<string>extensionPackage.displayName, loggingOptions);
        await this.loggingUtil.initLogging();
    }

    // tslint:disable-next-line: variable-name
    public registerCommand(commandText: string, CommandClass: any, commandOptions: any = {}) {
        commandRegistry.register(commandText, CommandClass, commandOptions);

        return this;
    }

    public get clientLogsLocation() {
        return getLogLocation();
    }

    public async getLastClientLogs(quantity: number): Promise<string[]> {
        if (getLogLocation() != null) {
            const folderPath = getLogLocation();
            return await getLastFiles(folderPath, quantity);
        }
        return [];
    }

    public getLogs(logLevel?: LogLevel) {
        return this.loggingUtil.getLogs(logLevel);
    }

    public setDiagnosticLogging(enableDiagnosticsLogging?: boolean, focus?: boolean) {
        this.loggingUtil.setDiagnosticLogging(enableDiagnosticsLogging, focus);
    }
}

let vslsCommandsAPIInternal: IVSLSCommandsAPI | undefined;
export const vslsCommands = {
    isFirstActivation,
    isExtensionBeingUpdated,
    get API() {
        return throwNotInitialized(vslsCommandsAPIInternal);
    },
    get abTester() {
        return throwNotInitialized(abTester);
    },
    get packageJSON() {
        return getPackageJSON();
    },
    async initialize(options: IVSLSCommandsAPIOptions) {
        if (vslsCommandsAPIInternal) {
            return vslsCommandsAPIInternal;
        }

        vslsCommandsAPIInternal = new VSLSCommandsAPI(options);
        // async initialize now.
        if (options.logging) {
            await (<VSLSCommandsAPI>vslsCommandsAPIInternal).initLogging(
                options.extensionPackage,
                options.logging,
            );
        }

        abTester = new ABTester(
            options.extensionContext.globalState,
            (await isFirstActivation(options.extensionPackage)) &&
                !(await isExtensionBeingUpdated()),
        );
    },
} as const;
