import * as ssh from '@vs/vs-ssh';
import { ILogger } from '@vs/vso-logging';
import { wait, timeoutPromise, TIME_SECOND_MS } from '@vs/vscs-utils';
import { SshHelpers } from './SshHelpers';
import { IWorkspaceSessionInfo } from '@vs/vso-workspace-core';
import { SshWorkspaceSession } from './SshWorkspaceSession';
import { streamFactoryType } from './streamFactoryType';
import debug from 'debug';

const defaultMaxTimeReconnect = 60 * TIME_SECOND_MS; // around 1 min
const defaultRetryTimeout = 5 * TIME_SECOND_MS; // 5 secs
const maxReconnectTimeout = 5 * TIME_SECOND_MS; // 5 secs

export interface SshReconnectOptions {
    enabled: boolean;
    maxTimeReconnect?: number;
    retryTimeout?: number;
}

export interface SshReconnectResult {
    retryCount: number;
    error?: Error;
}

export class SshWorkspaceSessionFactory {
    public static async createSshWorkspaceSession(
        sessionInfo: IWorkspaceSessionInfo,
        logger: ILogger,
        socketStreamFactory?: streamFactoryType,
        sshReconnectOptions?: SshReconnectOptions
    ): Promise<SshWorkspaceSession> {
        const streamFactory = socketStreamFactory || SshHelpers.openConnection;

        // Enable SSH protocol tracing and route it to the current logger. For now this
        // uses static properties on the `debug` package; currently that package is
        // instanced because this package references a different version than others.
        // If package versions are consolidated, the settings here could have broader impact.
        // TODO: Consider supporting a more flexible logging interface in the SSH lib.
        const sshTrace = logger.createChild('ssh');
        debug.enable(debug.disable() + ',vs-ssh');
        if (typeof (<any>debug).inspectOpts === 'object') {
            (<any>debug).inspectOpts.hideDate = true;
        }
        const defaultLog = debug.log;
        debug.log = function(this: ReturnType<typeof debug>, ...args: any[]) {
            if (this.namespace === 'vs-ssh') {
                sshTrace.info(args[0], ...args.slice(1));
            } else {
                defaultLog();
            }
        };

        const reconnectOptions = sshReconnectOptions || { enabled: true };

        let socketStream = await streamFactory(sessionInfo, logger);
        const sshSession = await SshHelpers.createSshClientSession();

        const reconnect = async (): Promise<SshReconnectResult> => {
            const maxTimeReconnect = reconnectOptions.maxTimeReconnect || defaultMaxTimeReconnect;
            const retryTimeout = reconnectOptions.retryTimeout || defaultRetryTimeout;

            logger.info(
                `reconnect started maxTimeReconnect:${maxTimeReconnect} retryTimeout:${retryTimeout}`
            );
            const start = Date.now();
            let retryCount = 1;
            let error: Error | undefined;

            while (Date.now() - start <= maxTimeReconnect && !sshSession.isClosed) {
                try {
                    socketStream = await streamFactory(sessionInfo, logger);
                    logger.info(`reconnecting ssh session retryCount:${retryCount}`);
                    await timeoutPromise(
                        sshSession.reconnect(socketStream),
                        maxReconnectTimeout,
                        new Error('timeout on ssh reconnection')
                    );

                    logger.info(
                        `ssh session successfully reconnected on retryCount:${retryCount} time:${(
                            Date.now() - start
                        ).toFixed(1)}`
                    );
                    error = undefined;
                    break;
                } catch (e) {
                    error = e;
                    if (e instanceof ssh.SshReconnectError) {
                        // Retry is not likely to succeed after an SshReconnectError
                        logger.error(`failed to reconnect ssh session: ${e.message}`);
                        break;
                    }

                    logger.verbose(
                        `failed to reconnect ssh session retryCount:${retryCount} error:${e}`
                    );
                    // wait for 5 secs to retry.
                    await wait(retryTimeout);
                }

                ++retryCount;
            }

            // if error log & dispose the ssh session.
            if (error) {
                logger.error(`unable to reconnect ssh session -> retryCount:${retryCount}`);
                sshSession.dispose();
            }

            return {
                retryCount,
                error,
            };
        };

        const clientAuthCompletion = new ssh.PromiseCompletionSource<void>();

        logger.verbose(`authenticating...`);
        await SshHelpers.authenticate(
            sshSession,
            sessionInfo,
            sessionInfo,
            socketStream,
            clientAuthCompletion
        );

        return new SshWorkspaceSession(
            sshSession,
            clientAuthCompletion.promise,
            logger.createChild('SshWorkspaceSession'),
            reconnectOptions.enabled ? reconnect : undefined
        );
    }
}
