import { Lazy, RpcServices as CoreRpcServices } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IRpcServiceHandler, ServiceInfo } from '@vs/vso-rpc';

export class RpcServices extends CoreRpcServices {
    constructor(
        public readonly rpcFactory: <T>(serviceInfo: ServiceInfo<T>, traceName: string) => T,
        public readonly rpcServiceHandler: Lazy<IRpcServiceHandler>,
        public fileService: Lazy<vsls.FileService>,
        public syncService: Lazy<vsls.SyncService>) { 
            super(rpcFactory, rpcServiceHandler); 
        }
}