import { fileAccess } from '@vs/vscode-command-framework';
import * as path from 'path';

import { SharedColors } from '../../coediting/client/decorators';
import { getExtensionUri } from '@vs/vscode-command-framework';
import { traceSource } from '@vs/vscode-command-framework';

const renderCircleIcon = (color: string, isFilled: boolean = false): string => {
    return `
        <svg xmlns="http://www.w3.org/2000/svg">
            <!--
                SVG inside SVG is because VSCode ignores the width / height on the root
                element. So nesting it lets us use the width/height to scale it. The
                x/y are to reposition it to be centered.
            -->
            <svg width="16px" height="16px" viewBox="0 0 16 16" version="1.1">
                <circle id="filled" fill="${color}" fill-rule="nonzero" cx="8" cy="8" r="${(isFilled) ? 6 : 0}"></circle>
                <path d="M8,14 C4.6862915,14 2,11.3137085 2,8 C2,4.6862915 4.6862915,2 8,2 C11.3137085,2 14,4.6862915 14,8 C14,11.3137085 11.3137085,14 8,14 Z M8,12 C10.209139,12 12,10.209139 12,8 C12,5.790861 10.209139,4 8,4 C5.790861,4 4,5.790861 4,8 C4,10.209139 5.790861,12 8,12 Z" id="stroke" fill="${color}" fill-rule="nonzero"></path>
            </svg>
        </svg>
    `;
};

interface ISessionExplorerIcon {
    normal: string;
    filled: string;
}

class IconsProvider {

    private trace = traceSource.withName('IconsProvider');   

    private icons: { [key: string]: ISessionExplorerIcon; } = {};
    private iconsRoot: string | undefined;

    public async getIcon(color: string): Promise<ISessionExplorerIcon | null> {
        const currentIcon = this.icons[color];

        if (currentIcon) {
            return currentIcon;
        }

        try {
            this.icons[color] = await this.createIconBundle(color);
        } catch (e) {
            this.trace.error('Creating icon bundle failed', e);
            return null;
        }

        return this.icons[color];
    }

    public async getIconByUserId(userId: number) {
        const color = SharedColors.requestColor(userId);
        const { backgroundColor, textColor } = color;
        const red = parseInt(`${255 * backgroundColor.red}`, 10);
        const green = parseInt(`${255 * backgroundColor.green}`, 10);
        const blue = parseInt(`${255 * backgroundColor.blue}`, 10);
        const colorString = `rgb(${red}, ${green}, ${blue})`;

        return await this.getIcon(colorString);
    }

    private createIconBundle = async (color: string): Promise<ISessionExplorerIcon> => {
        const cleanColorName = color.replace(/\,|\.|\(|\)|\s/gim, '_');

        if (!this.iconsRoot) {
            this.iconsRoot = getExtensionUri('images').fsPath;
        }

        const normalPath = path.join(this.iconsRoot, `./user-icon-${cleanColorName}-icon.svg`);
        const filledPath = path.join(this.iconsRoot, `./user-icon-${cleanColorName}-filled-icon.svg`);

        if ((await fileAccess.existsAsync(normalPath)) && (await fileAccess.existsAsync(filledPath))) {
            return {
                normal: normalPath,
                filled: filledPath
            };
        }

        await fileAccess.writeFileAsync(normalPath, renderCircleIcon(color, false));
        await fileAccess.writeFileAsync(filledPath, renderCircleIcon(color, true));

        return {
            normal: normalPath,
            filled: filledPath
        };
    }
}

const userIconProvider = new IconsProvider();
export async function getIconPathForUser(rowIndex: number, userId: number, isFollowing: boolean): Promise<any> {
    const iconBundle = await userIconProvider.getIconByUserId(userId);
    let iconPath;
    if (iconBundle) {
        const iconPathBundle = isFollowing ?
            iconBundle.filled
            : iconBundle.normal;
        iconPath = {
            dark: iconPathBundle,
            light: iconPathBundle
        };
    }

    return iconPath;
}