import { ShareDebugManagerBase as ShareDebugManagerClass } from '../../debugger/shareDebugManagerBase';

import { IShareDebugManager } from '../abstractions/Interfaces';

export class ShareDebugManager implements IShareDebugManager {
    constructor (
        private shareDebugManager: ShareDebugManagerClass) {
    }

    public init(): Promise<void> {
        return this.shareDebugManager.setShareState(true);
    }

    public dispose(): Promise<void> {
        return undefined;
    }

    public setShareState(isSharing: boolean): Promise<void> {
        return this.shareDebugManager.setShareState(isSharing);
    }
}