import { Emitter, Event } from 'vscode-jsonrpc';

import { createDisposable } from './createDisposable';

import { IDisposable } from '../interfaces';

/**
 * Function to connect 2 events, then the `event` fired,
 * fire the `event` also.
 */
export const connectEvents = <T extends any>(
    notify: Emitter<any>,
    ...events: ReadonlyArray<Event<any>>
): IDisposable => {
    const disposables: (IDisposable | undefined)[] = events.map((event) => {
        return event(notify.fire.bind(notify));
    });

    return createDisposable(() => {
        for (const disposable of disposables) {
            disposable?.dispose();
        }
    });
};
