import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { IUserAuthStateTracker } from './IUserAuthStateTracker';
import { Signal } from '@vs/vscs-utils';
class UserAuthStateTracker implements IUserAuthStateTracker {
    private userInfo_: vsls.UserInfo | null;

    private readonly userInfoChangedEmitter = new vscode.EventEmitter<void>();
    public readonly onUserInfoChanged = this.userInfoChangedEmitter.event;

    public get userInfo(): vsls.UserInfo | null {
        return this.userInfo_;
    }

    public set userInfo(value: vsls.UserInfo | null) {
        this.userInfo_ = value;
        this.userInfoChangedEmitter.fire();
    }

    public isCustomAccount: boolean = false;

    public isCurrentUserAnonymous(): boolean {
        return !!(this.userInfo && this.userInfo.isAnonymous);
    }

    public get IsSignedIn() {
        return !!this.userInfo;
    }

    public defaultAuthAttemptCompleteSignal = new Signal();

    public completeDefaultAuthAttempt() {
        this.defaultAuthAttemptCompleteSignal.resolve({});
    }
}

export const userAuthStateTracker = new UserAuthStateTracker();
