import {
    assert,
    assertDefined,
    DisposableClass,
    Signal,
    timeoutPromise,
    propertiesToString,
} from '@vs/vscs-utils';
import { Emitter } from 'vscode-jsonrpc';
import { Performance } from '@vs/vscs-performance';
import { ILogger } from '@vs/vso-logging';

import { IConnectionStatusChangeArg } from '../interfaces/IConnectionStatusChangeArg';
import { ConnectionCancellationError } from '../errors/ConnectionCancellationError';
import { errorToConnectionError } from '../utils/errorToConnectionError';
import { ConnectionStateError } from '../errors/ConnectionStateError';
import { TConnectionState } from '../interfaces/TConnectionState';
import { ConnectionError } from '../errors/ConnectionError';
import { IConnection } from '../interfaces/IConnection';
import { ConnectionTimeoutError } from '../errors/ConnectionTimeoutError';

export class Connection<TOptions extends any = any> extends DisposableClass
    implements IConnection<any> {
    private isDisconnectedFlag = false;

    private isDisposingRef = false;

    /**
     * If the connection was explicitly disconnected (vs disposed).
     */
    get isDisconnected() {
        return this.isDisconnectedFlag;
    }

    /**
     * Get connection `id` from the connection `options`.
     */
    public getId(options: any): string {
        throw new ConnectionError('Not implemented.');
    }

    /**
     * The `onConnectionChanged` callback is called every time the connection status changes.
     */
    protected readonly onConnectionChangedEventEmitter = new Emitter<IConnectionStatusChangeArg>();
    public get onConnectionChanged() {
        if (this.isDisposed) {
            throw new ConnectionStateError(
                'Cannot listen to `onConnectionChanged`, connection already disposed.'
            );
        }

        return this.onConnectionChangedEventEmitter.event;
    }

    constructor(
        protected readonly traceName: ILogger,
        protected performance: Performance,
        public readonly options: TOptions = {} as TOptions
    ) {
        super(traceName);

        this.addToDisposables(this.onConnectionChangedEventEmitter);
    }

    /**
     * If the connection is being disposed
     */
    public get isDisposing() {
        return this.isDisposingRef;
    }

    /**
     * Connection status.
     */
    public get status() {
        return this.connectionStatus;
    }

    /**
     * Previous connection status.
     */
    public get previousStatus() {
        return this.previousConnectionStatus;
    }

    /**
     * Method to connect to LiveShare Session and create basic RPC services.
     * Will reuse connection currently in progress if one already exists.
     */
    public async connect() {
        try {
            this.trace.info('asked to connect');

            /**
             * This will make sure we preserve the original rejection error versus
             * always returning the ConnectionStateError.
             */
            if (this.connectionSignal?.isCancelled || this.connectionSignal?.isRejected) {
                return await this.connectionSignal.promise;
            }

            assert(
                this.status !== 'disconnected',
                new ConnectionStateError(
                    'Connection already disconnected, please create a new one.'
                )
            );

            assert(
                !this.isDisposed,
                new ConnectionStateError('Connection is already disposed, please create a new one.')
            );

            if (this.connectionSignal) {
                this.trace.info(`return promise, resolved: ${this.connectionSignal.isResolved}`);

                return await this.connectionSignal.promise;
            }

            this.trace.info('creating new connection');

            return await this.createConnection();
        } catch (e) {
            this.handleConnectionError(e);
            throw errorToConnectionError(e);
        }
    }

    /**
     * Disconnect method is disposing the connection. Will cause the
     * `onConnectionChanged` and `onDispose` events to be fired.
     */
    public disconnect(reason?: string): Promise<this> {
        this.isDisconnectedFlag = true;

        return Promise.resolve(this.dispose(reason));
    }

    /**
     * Dispose the connection, same as `disconnect`. Will cause the
     * `onConnectionChanged` and `onDispose` events to be fired.
     */
    public dispose(reason?: string) {
        this.isDisposingRef = true;

        if (this.isDisposed) {
            return this;
        }

        this.onConnectionChangedHandler(
            'disconnected',
            new ConnectionCancellationError('Disposing the connection.')
        );
        super.dispose(reason);

        return this;
    }

    /**
     * Same as connect but with timeout.
     */
    public async connectWithTimeout(timeout: number): Promise<this> {
        try {
            this.trace.info(`asked to connect with timeout of ${timeout} ms`);

            if (!isFinite(timeout)) {
                return await this.connect();
            }

            return await timeoutPromise(
                this.connect(),
                timeout,
                new ConnectionTimeoutError(`Could not establish connection in ${timeout}ms.`)
            );
        } catch (e) {
            this.handleConnectionError(e);
            throw errorToConnectionError(e);
        }
    }

    /******************************************************
     * Implementation details.
     ******************************************************/
    protected connectionSignal?: Signal<this>;
    private connectionStatus: TConnectionState = 'none';
    private previousConnectionStatus: TConnectionState = 'none';

    protected onConnectionChangedHandler(connectionStatus: TConnectionState, error?: Error) {
        if (connectionStatus === this.connectionStatus) {
            return;
        }

        this.trace.info(
            `connection status changed: ${this.connectionStatus} -> ${connectionStatus}, error:`,
            error
        );

        this.previousConnectionStatus = this.connectionStatus;
        this.connectionStatus = connectionStatus;

        const event = {
            status: connectionStatus,
            previousStatus: this.previousConnectionStatus,
        };

        this.trace.info('firing change event: ', event);

        this.onConnectionChangedEventEmitter.fire(event);

        assertDefined(this.connectionSignal, 'No `connectionSignal` found.');

        if (this.connectionSignal.isFulfilled) {
            return;
        }

        if (connectionStatus === 'connected') {
            this.trace.info('🔌 connected');

            this.connectionSignal.resolve(this);
        }

        if (connectionStatus === 'disconnected') {
            this.trace.info('disconnected');

            this.connectionSignal.reject(
                errorToConnectionError(error ?? new ConnectionError('Connection failed.'))
            );
        }
    }

    protected initializeConnection(): this {
        this.trace.info('creating connection');
        this.connectionSignal = new Signal();
        this.connectionSignal.promise.catch((reason) => {
            this.trace.verbose(`signal rejected reason -> ${propertiesToString(reason)}`);
        });
        this.addToDisposables(this.connectionSignal);
        this.onConnectionChangedHandler('connecting');

        return this;
    }

    protected async createConnection(): Promise<this> {
        this.initializeConnection();

        assertDefined(this.connectionSignal, new ConnectionError('No `connectionSignal` found.'));

        await this.connectionSignal.promise;

        throw new ConnectionError('Not implemented.');
    }

    protected handleConnectionError(e: Error) {
        this.trace.error('connection failed: ', e);
        this.onConnectionChangedHandler('disconnected', e);

        this.connectionSignal?.reject(errorToConnectionError(e));

        this.dispose();
    }
}
