import * as vscode from 'vscode';
import { IExperimentationService, IExperimentationTelemetry, getExperimentationServiceAsync, TargetPopulation } from 'vscode-tas-client';
import { Telemetry, TelemetryEvent } from '@vs/vso-telemetry';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import * as constants from '../constants';
import { Settings } from '../Settings';

class ExperimentationTelemetry implements IExperimentationTelemetry {

    public setSharedProperty(name: string, value: string): void {
        Telemetry.addContextProperty(name, value);
    }

    public postEvent(eventName: string, props: Map<string, string>): void {
        const event = new TelemetryEvent(eventName);
        for (let [property, value] of props) {
            event.addProperty(property, value);
        }
        event.send();
    }

}

function getTargetPopulation() {
    if (Settings.isVSLSTeamMember) {
        return TargetPopulation.Team;
    } else if (Settings.isInternalFeatureSet) {
        return TargetPopulation.Internal;
    } else if (Settings.isInsidersFeatureSet) {
        return TargetPopulation.Insiders;
    } else {
        return TargetPopulation.Public;
    }
}

let expService: IExperimentationService;

export function getExpService() {
    return expService;
}

export async function initAsync(context: vscode.ExtensionContext, isWeb?: boolean) {
    const extensionName = `${constants.LIVESHARE_EXTENSION_ID}${isWeb ? '-web' : ''}`;
    const extensionVersion = ExtensionUtil.getExtensionVersion(constants.LIVESHARE_EXTENSION_ID);
    expService = await getExperimentationServiceAsync(
        extensionName,
        extensionVersion,
        getTargetPopulation(),
        new ExperimentationTelemetry(),
        context.globalState);
}
