import * as vscode from 'vscode';
import * as vscodeAccountAPI from '@vs/vscode-account';
import * as keytarType from 'keytar';
import { Telemetry } from '@vs/vso-telemetry';

declare const __webpack_require__: typeof require;
declare const __non_webpack_require__: typeof require;
function getNodeModule<T>(moduleName: string): T | undefined {
    const r = typeof __webpack_require__ === 'function' ? __non_webpack_require__ : require;

    try {
        return r(`${vscode.env.appRoot}/node_modules.asar/${moduleName}`);
    } catch (err) {
        // Not in ASAR.
    }

    try {
        return r(`${vscode.env.appRoot}/node_modules/${moduleName}`);
    } catch (err) {
        // Not available.
    }
    return undefined;
}

export const getKeytar = () => {
    return getNodeModule<typeof keytarType>('keytar');
};

export class Authentication {
    private authAPI?: vscodeAccountAPI.VSCodeAccount;

    public async init(
            context: vscode.ExtensionContext,
            extensionName: string,
            strategies: vscodeAccountAPI.IAuthStrategy[] = [],
            keytarIn?: typeof keytarType) {
        this.authAPI = await (vscodeAccountAPI as any).activateInternal(
            context,
            extensionName,
            Telemetry,
            [ ...strategies ],
            keytarIn || getKeytar()); // Keytar from Node Module needs to be passed explicitly
    }

    public get API(): vscodeAccountAPI.VSCodeAccount {
        if (!this.authAPI) {
            throw new Error('The auth API wasn\'t yet initialized. Please call the `init` function first');
        }

        return this.authAPI;
    }
}

export const auth = new Authentication();