
import * as vscode from 'vscode';
import * as nls from 'vscode-nls';

import { ICommentManager } from './contracts';
import { commentsSupported } from './commentManager';

import {
    TreeDataProviderBase,
    TreeDataProviderContext,
    TreeViewItem
} from '@vs/liveshare-core';

export const CommentsViewItem = 'comments';

const localize = nls.loadMessageBundle();

export class CommentsTreeDataProvider extends TreeDataProviderBase {
    private commentManager: ICommentManager;
    constructor() {
        super(CommentsViewItem, TreeDataProviderContext.SharedOrJoined);
    }

    public registerService(commentManager: ICommentManager): vscode.Disposable {

        this.commentManager = commentManager;
        return commentManager.onCommentCountChanged(() => this.forceRefreshItems());
    }

    protected getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]> {
        return Promise.resolve([]);
    }

    protected getRootItem(): Promise<TreeViewItem> {
        let item: TreeViewItem;

        if (commentsSupported()) {
            const label = localize('SessionExplorer.CommentsLabel', 'Comments ({0})', this.commentManager.commentCount);
            item = new TreeViewItem({
                type: CommentsViewItem,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label,
                command: {
                    title: 'Focus comment panel...',
                    command: 'workbench.action.focusCommentsPanel'
                }
            });
        }

        return Promise.resolve(item);
    }
}