
import { TraceSource } from '@vs/vso-logging';
import { ProviderBase } from './ProviderBase';

import  {
    SessionState,
    sessionStateTracker,
    SessionStateChangedEventArgs,
 } from '@vs/liveshare-core';
 import { vsls, contactProtocol } from '@vs/vsls-contracts';

export function registerSelfInviteProvider(authCoreService: vsls.AuthenticationCoreService, registerCallback: (id: string, provider: contactProtocol.ContactServiceProvider) => void, trace: TraceSource)  {
    registerCallback('selfInvite', new SelfInviteProvider(authCoreService, trace));
}

class SelfInviteProvider extends ProviderBase {

    constructor(authCoreService: vsls.AuthenticationCoreService, trace: TraceSource) {
        super();

        sessionStateTracker.onStateChanged(async (e: SessionStateChangedEventArgs) => {
            if (e.newState === SessionState.SignedOut || e.newState === SessionState.SignedIn) {
                this.notifySelfSuggestion(authCoreService, e.newState === SessionState.SignedIn, trace);
            }
        });

        // if during initialize we are already signed in
        if (sessionStateTracker.State === SessionState.SignedIn) {
            this.notifySelfSuggestion(authCoreService, true, trace);
        }
    }

    protected async requestInitialize(request: contactProtocol.InitializeRequest): Promise<contactProtocol.InitializeResponse> {
        return {
            description: 'Self invite provider',
            capabilities: {
                supportsDispose: false,
                supportsInviteLink: false,
                supportsPresence: false,
                supportsContactPresenceRequest: false,
                supportsPublishPresence: false
            }
        }; 
    }

    private async notifySelfSuggestion(authCoreService: vsls.AuthenticationCoreService, isAuthenticated: boolean, trace: TraceSource): Promise<void> {
        
        const contacts: contactProtocol.Contact[] = [];
        if (isAuthenticated) {
            const currentUser = await authCoreService.getCurrentUserAsync();
            if (currentUser) {
                contacts.push( <contactProtocol.Contact> {
                    id: currentUser.id,
                    displayName: currentUser.displayName,
                    email: currentUser.emailAddress
                });
            }
        }
        trace.verbose(`SelfInviteProvider-> status:${contacts.length > 0 ? true : false}`);
        this.notifySuggestedUsers(contacts);
    }
}