import * as vscode from 'vscode';
import { VSLS_CHAT_WINDOW } from '../constants';
import { TreeDataProviderBase, TreeDataProviderContext, TreeViewItem, localize, Settings, SettingKeys, ExtensionUtil } from '@vs/liveshare-core';
import { CommunicationsManager } from '../CommunicationsManager';
import { formatUnreadLabel } from '../utils';

export const chatViewItem = 'chat';

export class ChatTreeDataProvider extends TreeDataProviderBase {
    constructor() {
        super(chatViewItem, TreeDataProviderContext.SharedOrJoined);
        CommunicationsManager.onChatViewChanged(() => this.forceRefreshItems());
    }

    protected async getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]> {
        return;
    }

    protected async getRootItem(): Promise<TreeViewItem> {
        const chatWindowInfo = CommunicationsManager.chatViewController?.chatWindowInfo();
        if (!chatWindowInfo) {
            return;
        }

        let label = formatUnreadLabel(localize('chat.sessionChatLabel'), chatWindowInfo.unread);
        let item = new TreeViewItem({
            type: chatViewItem,
            label: label,
            tooltip: label,
            command: {
                title: localize('chat.openSessionChatWindow'),
                command: 'liveshare.openSessionChat',
                arguments: [ VSLS_CHAT_WINDOW ]
            }
        });

        return item;
    }
}