import { wrapCallSite } from 'source-map-support';

export type VSLSError = Error & { vslsStack?: NodeJS.CallSite[] };

/**
 * Converts an error object to a string, including stack trace with source map transformations.
 */

export function errorToString(e?: VSLSError): string | null {
    if (!e) {
        return null;
    }

    let s: string = e.message || 'Unknown error';

    const code = (<any>e).code;
    if (code) {
        s += ' code:' + code;
    }
    // Try to use source map information to map the stack frames back to original sources.
    let stack: string | null = null;
    if (e.vslsStack) {
        try {
            stack = e.vslsStack.map((frame) => '  at ' + wrapCallSite(frame)).join('\n');
        } catch (e) { }
    }
    if (!stack) {
        stack = e.stack || null;
    }
    if (stack) {
        s += '\n' + stack;
    }

    return s;
};
