import * as vscode from 'vscode';
import { IDisposableLike } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import * as jsonc from 'jsonc-parser';
import * as remotefile from 'remote-file';
import * as crypto from 'crypto';

export async function initRemoteFileSubscribe(
    context: vscode.ExtensionContext,
    url: string,
    callback: (result: any) => void,
    updatePeriodInMinutes?: number,
    logger?: ILogger): Promise<IDisposableLike> {

    const subscription = remotefile.subscribeOnFileUpdate(
        url,
        (buffer: Buffer | null) => {
            if (buffer) {
                try {
                    callback(jsonc.parse(buffer.toString()));
                } catch (e) {
                    // Failed to parse updated settings. Just keep the old settings.
                    logger?.warning('Failed to parse remote settings. ' + e);
                }
            } else {
                logger?.verbose('Remote settings not found.');
                callback(null);
            }
        },
        (updatePeriodInMinutes || 60) * 60 * 1000);

    const disposable = await subscription.init();
    return disposable;
}

export async function loadFilefromCache(url: string, logger?: ILogger): Promise<any | null> {
    // The `remote-file` package does not expose its internal cache.
    // But we need to retrieve a file from the cache without waiting for any HTTP request.
    const remoteFileCache = require('remote-file/internal/file-cache');
    const key = crypto.createHash('sha256').update(url).digest('hex');

    let buffer: Buffer;
    try {
        const remoteFile: any = await remoteFileCache.getCachedFile(key);
        buffer = remoteFile.getBuffer();
    } catch (e) {
        if (e.code === 'ENOENT') {
            logger?.verbose('Remote settings not found in local cache.');
        } else {
            logger?.warning('Failed to load remote settings from local cache. ' + e);
        }
        return null;
    }

    try {
        return jsonc.parse(buffer.toString());
    } catch (e) {
        logger?.warning('Failed to parse remote settings in local cache: ' + e);
        return null;
    }
}