import { TraceListener } from '@vs/vso-logging';
import { LogFileTraceListener, LogLocations } from '@vs/vso-logging-node';
import { traceSource } from '../../tracing/traceSource';

export function setLogLocation(logFilePath: string): void {
    LogLocations.clientLogFilePath = logFilePath;
}

export function getLogLocation(): string {
    return LogLocations.clientLogFilePath;
}

export async function createLogFileListener(): Promise<TraceListener | undefined> {
    const logFileTraceListener = new LogFileTraceListener('VSCode');
    const loggingFilePath = await logFileTraceListener.openAsync();
    if (!loggingFilePath) {
        return;
    }

    traceSource.info('Trace log: ' + logFileTraceListener.logFileName);
    return logFileTraceListener;
}
