import * as vscode from 'vscode';
import { IDisposable } from '@vs/vscs-utils';
import { TextEditorLabelDecorator } from './textEditorLabelDecorator';
import { DecoratorUtils, SharedColors } from './decorators';
import { ICoEditing } from '../ICoEditing';
import { ICollaboratorManager } from '../../ICollaborationManager';
import { getExpService } from '../../exp/ExperimentationService';
import { TreatmentVariables } from '../../exp/TreatmentVariables';

class FollowingLabelDecorator {

    private textEditorLabelDecorator?: TextEditorLabelDecorator;
    private followedClientId?: number;
    private disposables: IDisposable[] = [];

    public constructor(private readonly textEditor: vscode.TextEditor, private readonly coediting: ICoEditing, private readonly collaboratorManager: ICollaboratorManager) {
        this.updateDecorator();

        this.disposables.push(this.coediting.onPin(() => this.updateDecorator()));
        this.disposables.push(this.coediting.onUnpin(() => this.updateDecorator()));
    }

    private createTextEditorLabelDecorator() {
        const followedClientName = this.getClientName(this.followedClientId!);
        const followedClientColor = SharedColors.requestColor(this.followedClientId!);
        this.textEditorLabelDecorator = new TextEditorLabelDecorator(this.textEditor, `Following ${followedClientName}`, DecoratorUtils.toCssColor(followedClientColor.backgroundColor), DecoratorUtils.toCssColor(followedClientColor.textColor));
    }

    private updateDecorator() {
        const needsUpdate = this.updateFollowedClient();
        if (!needsUpdate) {
            return;
        }

        if (this.textEditorLabelDecorator) {
            this.removeTextEditorLabelDecorator();
        }

        if (this.followedClientId === undefined) {
            return;
        }

        if (!this.textEditorLabelDecorator) {
            if (getExpService()?.getTreatmentVariable<boolean>(TreatmentVariables.VSCodeConfig, TreatmentVariables.FollowIndicator)) {
                this.createTextEditorLabelDecorator();
            }
            return;
        }
    }

    private removeTextEditorLabelDecorator() {
        this.textEditorLabelDecorator?.dispose();
        this.textEditorLabelDecorator = undefined;
    }

    public dispose(): void {
        this.disposables.forEach(d => d.dispose());
        this.removeTextEditorLabelDecorator();
    }

    private updateFollowedClient() {
        const previous = this.followedClientId;

        this.followedClientId = this.coediting.getClientIdIfEditorIsPinned(this.textEditor);
        if (this.followedClientId < 0) {
            this.followedClientId = undefined;
        }

        return previous !== this.followedClientId;
    }

    private getClientName(clientId: number) {
        const profile = this.collaboratorManager.getCollaborators()[clientId];
        return profile?.name || profile?.userName || profile?.email;
    }

}

export class FollowingLabelDecoratorManager {

    private followingLabelDecorators = new Map<vscode.TextEditor, FollowingLabelDecorator>(); 
    private disposables: IDisposable[] = [];

    public constructor(private readonly coediting: ICoEditing, private readonly collaboratorManager: ICollaboratorManager) {
        this.updateFollowingLabelDecorators();
        this.disposables.push(vscode.window.onDidChangeVisibleTextEditors(() => this.updateFollowingLabelDecorators()));
    }

    private updateFollowingLabelDecorators() {
        const previousEditors = Array.from(this.followingLabelDecorators.keys());

        // Clean up decorators for deleted editors
        previousEditors.filter(editor => vscode.window.visibleTextEditors.indexOf(editor) < 0).forEach(editor => {
            const followingLabelDecorator = this.followingLabelDecorators.get(editor);
            this.followingLabelDecorators.delete(editor);
            followingLabelDecorator.dispose();
        });

        // Add decorators for new editors
        vscode.window.visibleTextEditors.filter(editor => previousEditors.indexOf(editor) < 0).forEach(editor => {
            this.followingLabelDecorators.set(editor, new FollowingLabelDecorator(editor, this.coediting, this.collaboratorManager));
        });
    }

    public dispose() {
        for (let followingLabelDecorator of this.followingLabelDecorators.values()) {
            followingLabelDecorator.dispose();
        }
        this.disposables.forEach(d => d.dispose());
    }

}
