'use strict';

import * as rpc from 'vscode-jsonrpc';

import { IRpcClientProxy } from './IRpcClient';
import { RpcClientProxy } from './RpcClientProxy';
import { ILogger, LogLevel, LoggerSettings } from '@vs/vso-logging';
import { ServiceInfo } from './ServiceInfo';
import { getEventPropertyName } from './RpcUtils';

/**
 * Defines error codes returned by the VSLS agent implemention of JSON-RPC,
 * which are a super-set of standard JSON-RPC error codes.
 */
export enum RpcErrorCodes {
    ParseError = rpc.ErrorCodes.ParseError,
    InvalidRequest = rpc.ErrorCodes.InvalidRequest,
    MethodNotFound = rpc.ErrorCodes.MethodNotFound,
    InvalidParams = rpc.ErrorCodes.InvalidParams,
    InternalError = rpc.ErrorCodes.InternalError,
    ServerNotInitialized = rpc.ErrorCodes.ServerNotInitialized,
    UnknownErrorCode = rpc.ErrorCodes.UnknownErrorCode,
    RequestCancelled = rpc.ErrorCodes.RequestCancelled,
    MessageWriteError = rpc.ErrorCodes.MessageWriteError,
    MessageReadError = rpc.ErrorCodes.MessageReadError,

    // VSLS extended RPC error codes
    ServiceNotAvailable = -32099,
    InvocationException = -32098,
    MessageTooLarge = -32097,
}

/**
 * Base class for RPC service proxies. Traces all messages
 * and emits events for incoming notifications.
 */
export class RpcProxy {
    private constructor(
        public readonly client: IRpcClientProxy,
        public readonly serviceName: string,
        private readonly logger: ILogger
    ) {}

    /**
     * Creates a proxy for an RPC service.
     *
     * @param serviceInfo Information about the service contract
     * @param client RPC client
     * @param logger logger to use
     */
    public static create<T>(
        serviceInfo: ServiceInfo<T>,
        client: IRpcClientProxy,
        logger: ILogger
    ): T {
        if (!(serviceInfo && serviceInfo.name)) {
            throw new Error('Missing RPC service name.');
        }

        const proxy = new RpcProxy(client, serviceInfo.name, logger);

        // Generate async methods for requests.
        for (const methodName of serviceInfo.methods) {
            const methodPropertyName = `${methodName}Async`;
            (proxy as any)[methodPropertyName] = function() {
                // Detect whether optional cancellation token was supplied, and if so strip from args.
                let args: any[];
                let cancellationToken: rpc.CancellationToken | null =
                    arguments[arguments.length - 1];
                if (
                    cancellationToken &&
                    typeof cancellationToken === 'object' &&
                    typeof cancellationToken.isCancellationRequested === 'boolean'
                ) {
                    args = Array.prototype.slice.call(arguments, 0, arguments.length - 1);
                } else {
                    args = Array.prototype.slice.call(arguments, 0, arguments.length);
                    cancellationToken = null;
                }

                // Detect whether optional progress was supplied, and if so strip from args.
                let progress: { report: (value: any) => void } | null = args[args.length - 1];
                if (
                    progress &&
                    typeof progress === 'object' &&
                    typeof progress.report === 'function'
                ) {
                    args.splice(args.length - 1, 1);
                } else {
                    progress = null;
                }

                const serviceAndMethodName = proxy.serviceName + '.' + methodName;
                return proxy.client.sendRequest<any>(
                    this.logger,
                    serviceAndMethodName,
                    progress,
                    cancellationToken,
                    ...args
                );
            };
        }

        // Generate methods for method-style notifications.
        for (const methodName of serviceInfo.voidMethods || []) {
            (proxy as any)[methodName] = function() {
                const args: any[] = Array.prototype.slice.call(arguments, 0, arguments.length);
                const serviceAndMethodName = proxy.serviceName + '.' + methodName;
                proxy.client
                    .sendNotification(this.logger, serviceAndMethodName, args)
                    .then()
                    .catch();
            };
        }

        // Generate events for event-style notifications.
        for (const eventName of serviceInfo.events) {
            const emitter = new rpc.Emitter<any>();
            const eventPropertyName = getEventPropertyName(eventName);
            (proxy as any)[eventPropertyName] = emitter.event;

            const serviceAndEventName = proxy.serviceName + '.' + eventName;
            proxy.client
                .ensureConnectionAsync()
                .then((connection) => {
                    connection.onNotification(serviceAndEventName, (...args: any[]) => {
                        const eventArgs = args[0];

                        // Event args may contain sensitive data, so only trace when obfuscation is disabled.
                        const argsString = LoggerSettings.disableObfuscation
                            ? JSON.stringify(eventArgs)
                            : '';

                        proxy.logger.log(LogLevel.Debug, `> ${serviceAndEventName}: ${argsString}`);
                        emitter.fire(eventArgs);
                    });
                })
                .catch((e) => {
                    // Failed to get the connection. There will already be errors traced elsewhere
                    // about the connection failure, so there's no need to trace anything more here.
                });
        }

        return (proxy as any) as T;
    }

    public static createWithConnection<T>(
        serviceInfo: ServiceInfo<T>,
        connection: rpc.MessageConnection,
        logger: ILogger
    ): T {
        return RpcProxy.create<T>(
            serviceInfo,
            RpcClientProxy.fromRpcConnection(connection, logger),
            logger
        );
    }

    public static createWithPromise<T>(
        serviceInfo: ServiceInfo<T>,
        promise: Promise<rpc.MessageConnection>,
        logger: ILogger
    ): T {
        return RpcProxy.create<T>(serviceInfo, RpcClientProxy.fromPromise(promise, logger), logger);
    }

    /**
     * Sends a notification (event) from this client to the service.
     *
     * (This is a static method because RPC contract interfaces do not define methods
     * for reverse notifications.)
     */
    public static notifyAsync(proxy: any, eventName: string, args: any): Promise<void> {
        const rpcProxy = proxy as RpcProxy;
        const serviceAndMethodName = rpcProxy.serviceName + '.' + eventName;
        return rpcProxy.client.sendNotification(rpcProxy.logger, serviceAndMethodName, args);
    }
}
