import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';

import { ICommand } from './abstractions/ICommand';
import { ICommandRegistryProvider } from './abstractions/ICommandRegistryProvider';
import { ICommandContextBuilder } from './abstractions/ICommandContextBuilder';

import {
    FaultType,
    ITelemetry
} from '@vs/vso-telemetry';
import {
    TelemetryEventNames
} from './telemetry/TelemetryStrings';
/**
 * Provider that ensures we register and execute commands safely
 * within VS Code.
 */
export class CommandRegistryProvider implements ICommandRegistryProvider {
    private readonly disposables: { [key: string]: vscode.Disposable } = {};

    constructor (
        private commandContextBuilder: ICommandContextBuilder,
        private telemetry: ITelemetry,
        private trace: TraceSource) {
    }

    public register(commandText: string, commandBuilder: () => ICommand<any>): void {
        this.disposables[commandText] = vscode.commands.registerCommand(
            commandText,
            async (options: any, context: ICommandContext) => {
                try {
                    options = options || {};
                    const command = commandBuilder();
                    context = context || this.commandContextBuilder.build(command, commandText);
                    return await command.invoke(options, context);
                } catch (error) {
                    if (error && !error.hasRecorded) {
                        const errorMessage = `Unhandled exception (command): ${error.message}`;
                        this.trace.error(errorMessage);
                        this.telemetry.sendFault(
                            TelemetryEventNames.UNHANDLED_COMMAND_ERROR_FAULT,
                            FaultType.Error,
                            errorMessage,
                            error);
                    }
                }
            }
        );
    }

    public dispose(commandString: string): void {
        const disposable = this.disposables[commandString];
        if (disposable) {
            disposable.dispose();
        }
    }

    public disposeAll(): void {
        for (const key in this.disposables) {
            if (key) {
                this.dispose(key);
            }
        }
    }
}
