import * as vscode from 'vscode';
import * as vscodeLSP from 'vscode-languageserver-protocol';
import { CancellationToken } from 'vscode';

import { summarizeLsRequests } from './LanguageServiceTelemetry';
import { RpcProxy, IRpcServiceHandler, RpcClient } from '@vs/vso-rpc';
import { TraceSource } from '@vs/vso-logging';

import { IPathManager, ISessionContext } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { traceSource } from '@vs/vscode-command-framework';

/**
 * A language service provider that provides language services in a language-agnostic way
 * by talking to the VSCode APIs.
 */
export class UniversalLanguageServerProvider implements vscode.Disposable {
    private readonly trace: TraceSource;
    private static readonly SERVICE_NAME = 'languageServerProvider-any';
    private notifyCookie: number;
    private requestHandlers = new Map<string, any>();
    private notificationHandlers = new Map<string, any>();

    // For telemetry purposes
    private servicedRequests = 0;
    private rejectedRequests = 0;
    private unacknowledgedHostChangesRejects = 0;
    private readonly rejectedRequestsDetails: { [method: string]: number } = {};

    // A list of LSP requests that don't require that the guest's buffer matches the host's to service.
    // E.g. there's no need to validate the 'initialize' request.
    private requestsThatDontNeedValidation = [
        vscodeLSP.InitializeRequest.type.method, vscodeLSP.ShutdownRequest.type.method,
        'liveshare/externalDocument', 'liveshare/load', 'liveshare/diagnosticsDocument'
    ];

    constructor(
        private workspaceService: vsls.WorkspaceService,
        private sessionContext: ISessionContext,
        private pathManager: IPathManager,
        private readonly rpcServiceHandler: IRpcServiceHandler
    ) {
        this.trace = traceSource.withName(vsls.TraceSources.ClientLSP);
    }

    public async initAsync(): Promise<void> {
        await this.workspaceService.registerServicesAsync([UniversalLanguageServerProvider.SERVICE_NAME], vsls.CollectionChangeType.Add);

        this.rpcServiceHandler.addRequestMethod(UniversalLanguageServerProvider.SERVICE_NAME + '.getMetadata', (token: CancellationToken) => {
            return <vsls.LanguageServerProviderMetadata>{ isLanguageClientProvider: true, contentTypes: ['any'] };
        });

        this.rpcServiceHandler.addRequestMethodWithContext(UniversalLanguageServerProvider.SERVICE_NAME + '.request', async (request: vsls.LspMessage, coeditingInfo: vsls.CoeditingInformation, context: any, token: CancellationToken) => {
            return await this.requestAsync(request, coeditingInfo, context, token);
        });

        this.notifyCookie = this.rpcServiceHandler.addNotificationHandler(UniversalLanguageServerProvider.SERVICE_NAME + '.notify', async (notification: vsls.LspMessage, token: CancellationToken) => {
            await this.notifyAsync(notification, token);
        });

        this.rpcServiceHandler.addRequestMethod(UniversalLanguageServerProvider.SERVICE_NAME + '.load', (token: CancellationToken) => {
            return Promise.resolve();
        });
    }

    public async dispose(): Promise<void> {
        summarizeLsRequests(this.servicedRequests, this.rejectedRequests, this.unacknowledgedHostChangesRejects, this.rejectedRequestsDetails);
        await this.workspaceService.registerServicesAsync([UniversalLanguageServerProvider.SERVICE_NAME], vsls.CollectionChangeType.Remove);

        this.rpcServiceHandler.removeRequestMethod(UniversalLanguageServerProvider.SERVICE_NAME + '.request');
        this.rpcServiceHandler.removeNotificationHandler(UniversalLanguageServerProvider.SERVICE_NAME + '.notify', this.notifyCookie);
        this.rpcServiceHandler.removeRequestMethod(UniversalLanguageServerProvider.SERVICE_NAME + '.load');
        this.pathManager.dispose();
    }

    public createProtocolConnection(): LSPProtocolConnection {
        return {
            onRequest: <P, R, E, RO>(type: vscodeLSP.RequestType<P, R, E, RO>, handler: vscodeLSP.RequestHandler<P, R, E>) => {
                this.requestHandlers.set(type.method, handler);
            },
            onCustomRequest: (method: string, handler: (params: any, token?: CancellationToken) => any) => {
                this.requestHandlers.set(method, handler);
            },
            onNotification: <P, R, E, RO>(type: vscodeLSP.NotificationType<P, RO>, handler: vscodeLSP.NotificationHandler<P>) => {
                this.notificationHandlers.set(type.method, handler);
            },
            sendNotification: (method: string, params?: any) => {
                const message: vsls.LspMessage = { method, params };
                this.rpcServiceHandler.sendNotification(this.trace, UniversalLanguageServerProvider.SERVICE_NAME + '.notified', { body: message });
            }
        };
    }

    public async requestAsync(request: vsls.LspMessage, coeditingInfo: vsls.CoeditingInformation, context: any, token: CancellationToken): Promise<any> {
        const method = request.method;
        // Workaround because VS LSP client doesn't properly handle a null value returned 
        // by a textDocument/documentSymbol request. 
        const nullValue: any = (method === 'textDocument/documentSymbol' ? [] : null);

        if (coeditingInfo && this.requestsThatDontNeedValidation.indexOf(method) < 0) {
            if (!this.canServiceRequest(coeditingInfo)) {
                this.trace.info(`Rejected ${request.method} request`);
                this.rejectedRequests++;
                this.rejectedRequestsDetails[method] = this.rejectedRequestsDetails[method]
                    ? this.rejectedRequestsDetails[method] + 1
                    : 1;
                return nullValue;
            }
            this.servicedRequests++;
        }

        let params = request.params;
        if (this.requestHandlers.has(method)) {
            if (context) {
                if (typeof params === 'undefined' || params === null) {
                    params = { context };
                } else if (typeof params === 'object') {
                    (<any>(params)).context = context;
                }
            }

            return await this.requestHandlers.get(method)(params, token);
        }

        return nullValue;
    }

    private canServiceRequest(guestCoeditingInformation: vsls.CoeditingInformation): boolean {
        // The host's buffer has unacknowledged changes
        if (this.sessionContext.coeditingClient.hasUnacknowledgedTextChanges) {
            this.unacknowledgedHostChangesRejects++;
            return false;
        }

        let textChangeHistory = this.sessionContext.coeditingClient.textChangeHistory;
        let historyIdx = textChangeHistory.length - 1;
        // No text changes so far
        if (historyIdx < 0) {
            return true;
        }

        // Requesting guest hasn't received any text edits
        // TODO: It's not 100% valid to return true here. It could be the case that another guest has
        // made edits that make it to the host before this request does
        if (guestCoeditingInformation.serverVersion === -1) {
            return true;
        } else {
            for (; historyIdx >= 0; historyIdx--) {
                if (textChangeHistory[historyIdx].changeServerVersion === guestCoeditingInformation.serverVersion) {
                    break;
                }
            }
            // Did not find the textChangeEventId from the guest on the host. Must have been too long ago
            if (historyIdx < 0) {
                return false;
            }
        }

        // We're interested in checking all changes that happen *after* the last one that the guest received
        historyIdx++;

        // Check if all changes to the host's buffers between these two were due to the guest issuing the request
        for (; historyIdx < textChangeHistory.length; historyIdx++) {
            if (textChangeHistory[historyIdx].clientId !== guestCoeditingInformation.clientId) {
                // Another guest has sent a change that the guest that made the request
                // hadn't received at the time the request was made
                return false;
            }
        }

        // All text changes have been due to the client that sent the request
        return true;
    }

    public async notifyAsync(notificationMessage: vsls.LspMessage, token: CancellationToken): Promise<void> {
        // No need to do a check with CoEditing here if we can service the notification or not.
        // Possible Client -> Server LSP notifications are: Initialized, Exit, DidChangeWorkspaceFolders, DidChangeConfiguration,
        // DidChangeWatchedFiles, DidOpenTextDocument, DidChangeTextDocument, WillSaveTextDocument, WillSaveWaitUntilTextDocument,
        // DidCloseTextDocument. These notifications should be sent from the host and not the guest.
        if (this.notificationHandlers.has(notificationMessage.method)) {
            await this.notificationHandlers.get(notificationMessage.method)(notificationMessage.params);
        }
    }
}

/**
 * The interface exposed to the LSP server to register callbacks for requests\notfications.
 */
export interface LSPProtocolConnection {
    onRequest<P, R, E, RO>(type: vscodeLSP.RequestType<P, R, E, RO>, handler: vscodeLSP.RequestHandler<P, R, E>): void;
    onCustomRequest(method: string, handler: (params: any, token?: CancellationToken) => any): void;
    onNotification<P, R, E, RO>(type: vscodeLSP.NotificationType<P, RO>, handler: vscodeLSP.NotificationHandler<P>): void;
    sendNotification(method: string, params?: any): void;
}