
import * as rpc from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';
import { assertDefined } from '@vs/vscs-utils';
import { IRpcRequestContext, IRpcServiceHandlerInfo } from '@vs/vso-rpc';
import { TelemetryEventNames, TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { TelemetryEvent } from '@vs/vso-telemetry';
import { RestrictedOperation,  } from '../accessControl/RestrictedOperation';
import { ClientAccessCheck } from '../accessControl/ClientAccessCheck';

const setWorkspaceAccessControl: RestrictedOperation = {
    name: 'setWorkspaceAccessControl',
    enabledInReadOnlySession: true,
    ownerOnly: true,
};

const rejectRestrictedOperation: RestrictedOperation = {
    name: 'rejectRestrictedOperation',
    enabledInReadOnlySession: true,
    ownerOnly: true,
};

const setRestrictedOperationAccess: RestrictedOperation = {
    name: 'setRestrictedOperationAccess',
    enabledInReadOnlySession: true,
    ownerOnly: true,
};

const rpcRequestContextErrorMessage = 'rpc request expected';
export class WorkspaceAccessControlService implements vsls.WorkspaceAccessControlService, IRpcServiceHandlerInfo {
    private userAccessControl: { [key: string]: vsls.AccessControl } = {};
    private defaultAccessControl: vsls.AccessControl = { isReadOnly: false };
    private operationAccessCheck: OperationAccessCheck;

    protected onAccessControlChangedEmitter = new rpc.Emitter<vsls.WorkspaceAccessControlEventArgs>();
    protected onOperationRejectedEmitter = new rpc.Emitter<vsls.RestrictedOperationAccessEventArgs>();
    protected onOperationAccessChangedEmitter = new rpc.Emitter<vsls.RestrictedOperationAccessEventArgs>();
    protected onOpeationAccessRequestedEmitter = new rpc.Emitter<vsls.RestrictedOperationAccessRequestedEventArgs>();

    public serviceInfo = vsls.WorkspaceAccessControlService;

    constructor(hostSessionId: number) {
        this.operationAccessCheck = new OperationAccessCheck(this, hostSessionId);
    }

    public async setAccessControlAsync(accessControl: vsls.WorkspaceAccessControl, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<void> {
        assertDefined(rpcRequestContext, rpcRequestContextErrorMessage);
        
        this.operationAccessCheck.verifyCanPerformOperation(rpcRequestContext.session, setWorkspaceAccessControl);
        this.userAccessControl = accessControl.userAccessControl;
        this.defaultAccessControl = accessControl.defaultAccessControl;
        this.onAccessControlChangedEmitter.fire({
            accessControl,
        });
    }

    public async requestOperationAccessAsync(operation: vsls.RestrictedOperation, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<void> {
        new TelemetryEvent(TelemetryEventNames.REQUEST_RESTRICTED_OPERATION)
            .addProperty(TelemetryPropertyNames.OPERATION_NAME, operation.name)
            .send();
        this.onOpeationAccessRequestedEmitter.fire({
            sessionId: rpcRequestContext!.session,
            operation
        });
    }

    public async setOperationAccessAsync(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<void> {
        assertDefined(rpcRequestContext, rpcRequestContextErrorMessage);   
        this.operationAccessCheck.verifyCanPerformOperation(rpcRequestContext.session, setRestrictedOperationAccess);
        new TelemetryEvent(TelemetryEventNames.SET_RESTRICTED_OPERATION_ACCESS)
            .addProperty(TelemetryPropertyNames.OPERATION_NAME, operation.name)
            .addProperty(TelemetryPropertyNames.OPERATION_ACCESS, access)
            .send();
        this.onOperationAccessChangedEmitter.fire({
            operation,
            access,
        });
    }

    public async rejectOperationAsync(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<void> {
        assertDefined(rpcRequestContext, rpcRequestContextErrorMessage);   
        this.operationAccessCheck.verifyCanPerformOperation(rpcRequestContext.session, rejectRestrictedOperation);

        this.onOperationRejectedEmitter.fire({
            operation,
            access,
        });
    }

    public onAccessControlChanged: rpc.Event<vsls.WorkspaceAccessControlEventArgs> = this.onAccessControlChangedEmitter.event;
    public onOperationRejected: rpc.Event<vsls.RestrictedOperationAccessEventArgs> = this.onOperationRejectedEmitter.event;
    public onOperationAccessChanged: rpc.Event<vsls.RestrictedOperationAccessEventArgs> = this.onOperationAccessChangedEmitter.event;
    public onOpeationAccessRequested: rpc.Event<vsls.RestrictedOperationAccessRequestedEventArgs> = this.onOpeationAccessRequestedEmitter.event;

    public get accessControl() {
        return {
            defaultAccessControl: this.defaultAccessControl,
            userAccessControl: this.userAccessControl
        };
    }

    public async getAccessControlAsync(cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceAccessControl> {
        return this.accessControl;
    }  
}

/**
 * Helper class to verify perform operations on the WorkspaceAccessControlService class.
 */
class OperationAccessCheck extends ClientAccessCheck {
    public get isReadOnly(): boolean {
        return false;
    }

    public logRejectedOperation(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess): Promise<void> {
        return Promise.resolve();
    }
}