import { vsls } from '@vs/vsls-contracts';
import * as rpc from 'vscode-jsonrpc';
import { ILogger } from '@vs/vso-logging';
import { SshRpcServer } from '@vs/vso-rpc-ssh';
import { SharedWorkspace } from '@vs/vso-workspace-core';
import { ServiceInfo, IRpcRequestContext } from '@vs/vso-rpc';
import { assertDefined, defer } from '@vs/vscs-utils';

export enum UserProfileChangeType {
    None = 0,
    Added = 1,
    Removed = 2,
    Closed = 3,
}

export interface UserProfileChanged {
    changeType: UserProfileChangeType;
    sessionNumber: number;
    userProfile: vsls.WorkspaceUserProfile;
}

export class WorkspaceServer extends SshRpcServer {
    public joinedProfiles: { [key: string]: vsls.WorkspaceUserProfile } = {};
    private joinedRpcSessions = new Map<rpc.MessageConnection, number>();
    private onUserProfileChangedEmitter = new rpc.Emitter<UserProfileChanged>();

    public constructor(
        public readonly sharedWorkspace: SharedWorkspace,
        logger: ILogger,
        ...rpcServiceInfos: [any, ServiceInfo<void>][]
    ) {
        super(sharedWorkspace.hostPrivateKeys, logger);
        this.onUserAuthenticate(async (userToken) => {
            let profile: any | null = null;
            try {
                profile = await sharedWorkspace.getWorkspaceUserProfile(userToken);
            } catch (e) {
                logger.error('Failed to get user profile', e);
            }
            return profile;
        });

        // hookup onSessionClosed
        this.onSessionClosed((rpcConnection) =>
            this.removeUserProfile(rpcConnection, UserProfileChangeType.Closed)
        );

        // register core services
        const workspaceInfo = sharedWorkspace.workspaceInfo;
        const workspaceService = <vsls.WorkspaceService>{
            joinWorkspaceAsync: async (
                joinInfo: vsls.WorkspaceJoinInfo,
                cancellationToken?: rpc.CancellationToken,
                rpcRequestContext?: IRpcRequestContext
            ) => {
                assertDefined(rpcRequestContext, 'rpc request expected');

                const joinerProfile = await sharedWorkspace.getWorkspaceUserProfile(
                    joinInfo.joiningUserSessionToken!
                );

                const sessionNumber = rpcRequestContext.session;
                this.addUserProfile(joinerProfile, rpcRequestContext);
                return {
                    sessionNumber,
                    id: workspaceInfo.id,
                    name: workspaceInfo.name,
                    conversationId: workspaceInfo.conversationId,
                    joinUri: workspaceInfo.joinLink,
                    connectionMode: vsls.ConnectionMode.Relay,
                    sessions: this.joinedProfiles,
                    accessControl: {
                        defaultAccessControl: { isReadOnly: false },
                        userAccessControl: {},
                    },
                };
            },
            unjoinWorkspaceAsync: (
                workspaceId: string,
                cancellationToken?: rpc.CancellationToken,
                rpcRequestContext?: IRpcRequestContext
            ) => {
                const rpcMessageConnection = rpcRequestContext!.connection;
                defer(async () => {
                    await this.closeSshSession(rpcMessageConnection!);
                }, 5);

                return Promise.resolve();
            },
        };

        this.registerRpcService(workspaceService, vsls.WorkspaceService, undefined, false);

        const configurationService: vsls.ConfigurationService = <vsls.ConfigurationService>{
            exchangeVersionsAsync: (
                agentVersion: vsls.AgentVersionInfo,
                clientVersion: vsls.ClientVersionInfo,
                cancellationToken?: rpc.CancellationToken
            ) => {
                return Promise.resolve({
                    version: '1.0',
                });
            },
        };
        this.registerRpcService(configurationService, vsls.ConfigurationService, undefined, false);

        // register rpc services to be available.
        rpcServiceInfos.forEach((item) => this.registerRpcService(item[0], item[1]));
    }

    public onUserProfileChanged = this.onUserProfileChangedEmitter.event;

    public get userProfiles() {
        return this.joinedProfiles;
    }

    public addUserProfile(
        userProfile: vsls.WorkspaceUserProfile,
        rpcRequestContext: IRpcRequestContext
    ) {
        const sessionNumber = rpcRequestContext.session;

        this.trace.info(
            `Adding user name:'${userProfile.userName}' with session number ${sessionNumber}`
        );

        this.joinedRpcSessions.set(rpcRequestContext.connection, sessionNumber);
        this.joinedProfiles[sessionNumber] = userProfile;
        this.onUserProfileChangedEmitter.fire({
            sessionNumber,
            changeType: UserProfileChangeType.Added,
            userProfile,
        });
    }

    public removeUserProfile(
        rpcMessageConnection: rpc.MessageConnection,
        changeType: UserProfileChangeType
    ): [number | undefined, vsls.WorkspaceUserProfile | undefined] | undefined {
        const sessionNumber = this.joinedRpcSessions.get(rpcMessageConnection);
        if (sessionNumber) {
            this.joinedRpcSessions.delete(rpcMessageConnection);
            return [sessionNumber, this.removeJoinedProfile(sessionNumber, changeType)];
        }
    }

    private removeJoinedProfile(
        sessionNumber: number,
        changeType: UserProfileChangeType
    ): vsls.WorkspaceUserProfile | undefined {
        const userProfile = this.joinedProfiles[sessionNumber];
        if (userProfile) {
            this.trace.info(
                `Removing user ${userProfile.name} with session number ${sessionNumber}`
            );
            delete this.joinedProfiles[sessionNumber];
            this.onUserProfileChangedEmitter.fire({
                sessionNumber,
                changeType,
                userProfile,
            });
            return userProfile;
        }
    }
}
