'use strict';

import * as vscode from 'vscode';
import { Activatable, Disposable } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import * as tt from './types';

import {
    Lazy,
    SessionContext,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { terminalEndpointBufferFactoryType, createJoinedTerminal  } from './createJoinedTerminal';

/**
 * Shared implementation for terminal controllers.
 */
export abstract class TerminalControllerBase extends Activatable(Disposable(Object)) {
    protected readonly terminalCache: tt.TerminalCache = new tt.TerminalCache();
    protected readonly sessionSubscriptions: vscode.Disposable[] = [];
    protected readonly globalSubscriptions: vscode.Disposable[] = [];
    protected deferredWork: Promise<void> = Promise.resolve();

    constructor(
        protected readonly lazyTerminalService: Lazy<vsls.TerminalService>,
        private readonly terminalEndpointBufferFactory: terminalEndpointBufferFactoryType,
        protected readonly trace: TraceSource) {
        super();

        vscode.window.onDidCloseTerminal(
            (terminal: vscode.Terminal) => {
                this.terminalCache.remove(terminal);
            },
            null /* this */,
            this.globalSubscriptions
        );
    }

    protected get terminalService() {
        return this.lazyTerminalService();
    }

    public async dispose(): Promise<void> {
        await this.deferredWork;
        await this.deactivate();

        const removed = this.globalSubscriptions.splice(0);
        removed.forEach(d => d.dispose());

        this.terminalCache.clean();

        SessionContext.hasSharedTerminals = false;

        await super.dispose();
    }

    public async deactivate(): Promise<void> {
        await this.deferredWork;

        const removed = this.sessionSubscriptions.splice(0);
        removed.forEach(d => d.dispose());

        this.terminalCache.clean(true /* sessionOnly */);

        await super.deactivate();
    }

    protected deferWork(work: () => Promise<any>): void {
        this.deferredWork = this.deferredWork
            .then(work)
            .catch(reason => {
                this.trace.error(reason.message);
            });
    }

    protected createTerminal(terminalInfo: vsls.TerminalInfo, renderer?: vscode.TerminalRenderer): Promise<vscode.Terminal> {
        return createJoinedTerminal({
            terminalService: this.terminalService,
            terminalCache: this.terminalCache,
            terminalEndpointBufferFactory: this.terminalEndpointBufferFactory,
            trace: this.trace
        }, terminalInfo, renderer);
    }
}