/** Lazy loaded and cached value */
export interface Lazy<T> {
    /** Get the cached value or call the loader if the value is falsy.
     * @returns the cached value if it's not falsy, or the result of the loader if it is a function; otherwise, undefined.
     */
    (createIfNotCreated?: boolean): T;
}

/** Mutable lazy load that its value can be changed on runtime. */
export interface MutableLazy<T> extends Lazy<T> {
    /** Current cached value, undefined if the value has not been loaded yet. */
    value?: T;

    /** The value loader. */
    loader?: () => T;
}

/**
 * Create a readonly lazy instance.
 * If createIfNotCreated = false, we return either the cached instance if it exists or undefined if it does not exist. 
 */
export function lazyLoad<T>(loader: () => T): Lazy<T> {
    let cache: any;

    return (createIfNotCreated = true) => {
        if (cache !== undefined) {
            return cache;
        } else if (createIfNotCreated) {
            return (cache = loader());
        }
        return undefined;
    };
}

/** Create a mutable lazy load wrapper.
 * @param loader - optional value loader. If not provided, value property must be set before the value function is called.
 */
export function lazyLoadMutable<T>(loader: () => T): MutableLazy<T> {
    const result: MutableLazy<T> = () => {
        if (result.value === undefined) {
            result.value = result.loader();
        }
        
        return result.value;
    }
    result.loader = loader;
    return result;
}

export function lazyLoadNotImplemented(): any {
    throw new Error('Dependencies: Instance not provided.');
}

export function delayedLoadMutable<T>(propertyName: string): MutableLazy<T> {
    return lazyLoadMutable<T>(() => { 
        throw Error(`Dependencies: ${propertyName} is not yet initialized`);
    });
}

/** Set a new loader (if it's defined) on the lazy object. Return the updated lazy object. */
export function setLazyLoadMutable<TLazy, T extends TLazy = TLazy>(orignal: MutableLazy<TLazy>, loader: (() => T) | undefined): MutableLazy<T> {
    if (typeof loader === 'function') {
        orignal.loader = loader;
    }

    return <MutableLazy<T>>orignal;
}