import { ExtensionSetupBase } from '../ExtensionSetupBase';
import { CommandId } from '../CommandConstants';

import { builder as SignInCommandBuilder } from './SignInCommand';
import { builder as SignOutCommandBuilder } from './SignOutCommand';
import { builder as SignInAndReloadCommandBuilder } from './SignInAndReloadCommand';
import { builder as FocusParticipantsBuilder } from './FocusParticipantsCommand';

export const registerCommands = (extensionSetup: ExtensionSetupBase): void => {
    extensionSetup.register(CommandId.signIn, SignInCommandBuilder);
    extensionSetup.register(CommandId.signOut, SignOutCommandBuilder);
    extensionSetup.register('signInAndReload', SignInAndReloadCommandBuilder);
    
    extensionSetup.register(CommandId.focusParticipants, FocusParticipantsBuilder);
    extensionSetup.register(CommandId.focusParticipantsActivityBar, FocusParticipantsBuilder);
    extensionSetup.register(CommandId.focusParticipantsFileTreeExplorer, FocusParticipantsBuilder);
};
