import { Uri } from 'vscode';
import { ICommandContext, NotificationUtil} from '@vs/vscode-command-framework';
import { ICommand } from '@vs/vscode-command-framework/src/types/ICommand';
import { PlannedSessionTreeViewItem } from '../PlannedSessionsProvider';
import { PlannedSessionsUtils } from '../plannedSessionUtils';

import { 
    SessionAction,
    TelemetryEventNames, 
    TelemetryPropertyNames,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    authenticationCommandDecorator,
    IAuthenticationDecoratorOptions, 
    IDependencies,
    localize,
    workspaceSessionInfoTracker
} from '@vs/liveshare-core';


export function builder(dependencies: IDependencies): ICommand<Uri> {
    return new CopyPlannedSessionLinkCommand(
    );
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.Create
};

/**
 * Copy planned session link `command` that copies a persistent link 
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Copy Planned Session link', TelemetryEventNames.COPY_PLANNED_SESSION_LINK_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.COPY_PLANNED_SESSION_LINK, TelemetryEventNames.COPY_PLANNED_SESSION_LINK_FAULT, 'Copy planned session link', 1)
@telemetryStatusCommandDecorator()
@authenticationCommandDecorator(authOptions)
export class CopyPlannedSessionLinkCommand implements ICommand<Uri> {

    constructor() { }

    public async invoke(item: PlannedSessionTreeViewItem, context: ICommandContext): Promise<Uri> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;
        try {
            let link;
            let workspaceList  = workspaceSessionInfoTracker.plannedWorkspaceList;
            if (item.workspaceInfo === undefined || item.workspaceInfo === null) {
               let workspaceInfo =  await PlannedSessionsUtils.selectPlannedSessionItemFromCommandPaletteAsync(workspaceList);
               link = workspaceInfo.joinUri;  
            } else  {
               link = item.workspaceInfo.joinUri;
            }

            if (link) {
                await PlannedSessionsUtils.copyToClipboardAsync(link);
                await NotificationUtil.showInformationMessage(localize('notification.CopyPlannedSessionLink'), false);  
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COPY_PLANNED_SESSION_LINK, true);
            } 
        } catch (e) {
            context.trace.error(`Failed to copy Planned Session link. ${e}`);
            throw new Error(localize('error.CannotCopyPlannedSessionLink'));
        }
        return;
    }
}