import { DebugSession } from 'vscode-debugadapter';
import { DebugProtocol } from 'vscode-debugprotocol';
import { InitializedEvent, StoppedEvent, TerminatedEvent } from 'vscode-debugadapter';
import * as vslsDebug from './DebugSessionHostService';
import { TraceSource } from '@vs/vso-logging';
import { ContinuedEvent } from 'vscode-debugadapter';
import { vsls } from '@vs/vsls-contracts';
import { 
    RpcErrorCodes,
} from '@vs/vso-rpc';
import { DebugAdapterCustomRequest } from './debugConstants';
import { DebugUtil } from './debugUtil';

interface LaunchRequestArguments extends DebugProtocol.LaunchRequestArguments {
}

export class JoinDebugSession extends DebugSession {

    private seq = 0;
    private stoppedEvent: vslsDebug.UIStoppedEvent | undefined = undefined;
    private continueReason?: vslsDebug.ContinueReason;
    private terminateOnDisconnect = false;

    constructor(
        private debugSessionHostService: vslsDebug.DebugSessionHostService,
        private debugSession: vsls.DebugSession,
        private trace: TraceSource) {
        super();
    }

    public forceTerminate(): void {
        this.sendEvent(new TerminatedEvent());
    }

    private get isStopped(): boolean {
        return this.stoppedEvent !== undefined;
    }

    /**
     * The 'initialize' request is the first request called by the frontend
     * to interrogate the features the debug adapter provides.
     */
    protected async initializeRequest(response: DebugProtocol.InitializeResponse, _args: DebugProtocol.InitializeRequestArguments): Promise<void> {
        response.body = this.debugSession.capabilities;
        this.sendResponse(response);

        // since this debug adapter can accept configuration requests like 'setBreakpoint' at any time,
        // we request them early by sending an 'initializeRequest' to the frontend.
        // The frontend will end the configuration sequence by calling 'configurationDone' request.
        this.sendEvent(new InitializedEvent());

        await this.initializeHostRequest();
    }

    protected async customRequest(command: string, response: DebugProtocol.Response, args: any, request?: DebugProtocol.Request): Promise<void> {
        switch (command) {
            case DebugAdapterCustomRequest.debugSessionId:
                response.body = { Id: this.debugSession.sessionId };
                break;
            case DebugAdapterCustomRequest.forceTerminate:
                this.forceTerminate();
                break;
            default:
                break;
        }

        this.sendResponse(response);
    }

    /**
     * Called at the end of the configuration sequence.
     * Indicates that all breakpoints etc. have been sent to the DA and that the 'launch' can start.
     */
    protected configurationDoneRequest(response: DebugProtocol.ConfigurationDoneResponse, args: DebugProtocol.ConfigurationDoneArguments): void {
        super.configurationDoneRequest(response, args);
    }

    protected launchRequest(response: DebugProtocol.LaunchResponse, args: DebugProtocol.LaunchRequestArguments, request?: DebugProtocol.Request): void {
        this.terminateOnDisconnect = true;
        this.attachToEvents();
        this.sendResponse(response);
    }

    protected attachRequest(response: DebugProtocol.AttachResponse, args: DebugProtocol.AttachRequestArguments, request?: DebugProtocol.Request): void {
        this.attachToEvents();
        this.sendResponse(response);
    }

    protected async stackTraceRequest(response: DebugProtocol.StackTraceResponse, _args: DebugProtocol.StackTraceArguments, _request?: DebugProtocol.Request): Promise<void> {
        
        if (this.isStopped) {
            let bodyResponse = DebugUtil.getStackTrace(_args, this.stoppedEvent, _request);

            if (bodyResponse) {
                response.body = bodyResponse;
            } else {
                response.body = await this.handleProtocolRequest(_request!.command, _args);
            }
        }

        this.sendResponse(response);
    }

    protected async scopesRequest(response: DebugProtocol.ScopesResponse, _args: DebugProtocol.ScopesArguments, _request?: DebugProtocol.Request): Promise<void> {
        if (this.isStopped) {
            const frameIdStr = _args.frameId.toString();
            if (this.stoppedEvent.scopes.hasOwnProperty(frameIdStr)) {
                response.body = {
                    scopes: this.stoppedEvent.scopes[frameIdStr]
                };
            } else {
                response.body = await this.handleProtocolRequest(_request!.command, _args);
            }
        }

        this.sendResponse(response);
    }

    protected async variablesRequest(response: DebugProtocol.VariablesResponse, _args: DebugProtocol.VariablesArguments, _request?: DebugProtocol.Request): Promise<void> {
        if (this.isStopped) {
            response.body = await this.handleProtocolRequest(_request!.command, _args);
        }

        this.sendResponse(response);
    }

    protected async sourceRequest(response: DebugProtocol.SourceResponse, _args: DebugProtocol.SourceArguments, _request?: DebugProtocol.Request): Promise<void> {
        if (this.isStopped) {
            let sourceRefStr =  _args.source.sourceReference ? _args.source.sourceReference.toString() : undefined;
            if (this.stoppedEvent.sourceReferenceContent &&
                sourceRefStr &&
                this.stoppedEvent.sourceReferenceContent.hasOwnProperty(sourceRefStr)) {
                response.body = this.stoppedEvent.sourceReferenceContent[sourceRefStr];
            } else {
                response.body = await this.handleProtocolRequest(_request!.command, _args);
            }
        }
        this.sendResponse(response);
    }

    protected async setBreakPointsRequest(response: DebugProtocol.SetBreakpointsResponse, _args: DebugProtocol.SetBreakpointsArguments, _request?: DebugProtocol.Request): Promise<void> {
        const originalSourcePath = _args.source.path;
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        response.body.breakpoints.forEach((b) => {
            if (b.source) {
                b.source.path = originalSourcePath;
            }
        });
        this.sendResponse(response);
    }

    protected async setVariableRequest(response: DebugProtocol.SetVariableResponse, _args: DebugProtocol.SetVariableArguments, _request?: DebugProtocol.Request): Promise<void> {
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    }

    protected async setExpressionRequest(response: DebugProtocol.SetExpressionResponse, _args: DebugProtocol.SetExpressionArguments, _request?: DebugProtocol.Request): Promise<void> {
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    }

    protected async evaluateRequest(response: DebugProtocol.EvaluateResponse, _args: DebugProtocol.EvaluateArguments, _request?: DebugProtocol.Request): Promise<void> {
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    }

    protected async threadsRequest(response: DebugProtocol.ThreadsResponse, _request?: DebugProtocol.Request): Promise<void> {
        if (this.isStopped) {
            response.body = {
                threads: this.stoppedEvent.threads
            };
        }

        this.sendResponse(response);
    }

    protected async disconnectRequest(response: DebugProtocol.DisconnectResponse, _args: DebugProtocol.DisconnectArguments, _request?: DebugProtocol.Request): Promise<void> {
        this.sendResponse(response);
        this.shutdown();
        if (this.terminateOnDisconnect) {
            await this.handleProtocolRequest('terminate');
        }
    }

    protected async continueRequest(response: DebugProtocol.ContinueResponse, _args: DebugProtocol.ContinueArguments, _request?: DebugProtocol.Request): Promise<void> {
        await this.continue(vslsDebug.ContinueReason.Go, _args.threadId);
        this.sendResponse(response);
    }

    protected async nextRequest(response: DebugProtocol.NextResponse, _args: DebugProtocol.NextArguments, _request?: DebugProtocol.Request): Promise<void> {
        await this.continue(vslsDebug.ContinueReason.StepOver, _args.threadId);
        this.sendResponse(response);
    }

    protected async stepInRequest(response: DebugProtocol.StepInResponse, _args: DebugProtocol.StepInArguments, _request?: DebugProtocol.Request): Promise<void> {
        await this.continue(vslsDebug.ContinueReason.StepIn, _args.threadId);
        this.sendResponse(response);
    }

    protected async stepOutRequest(response: DebugProtocol.StepOutResponse, _args: DebugProtocol.StepOutArguments, _request?: DebugProtocol.Request): Promise<void> {
        await this.continue(vslsDebug.ContinueReason.StepOut, _args.threadId);
        this.sendResponse(response);
    }

    protected async restartRequest(response: DebugProtocol.RestartResponse, _args: DebugProtocol.RestartArguments, _request?: DebugProtocol.Request): Promise<void>{
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    };

    protected async pauseRequest(response: DebugProtocol.PauseResponse, _args: DebugProtocol.PauseArguments, _request?: DebugProtocol.Request): Promise<void> {
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    }

    protected async loadedSourcesRequest(response: DebugProtocol.LoadedSourcesResponse, _args: DebugProtocol.LoadedSourcesArguments, _request?: DebugProtocol.Request): Promise<void> {
        response.body = await this.handleProtocolRequest(_request!.command, _args);
        this.sendResponse(response);
    }

    private attachToEvents() {
        this.debugSessionHostService.onDebugEvent(this.onDebugEvent, this);
        this.debugSessionHostService.onUIDebugEvent(this.onUIDebugEvent, this);
    }

    private onDebugEvent(e: any) {
        let event: DebugProtocol.Event = {
            seq: this.seq++,
            type: 'event',
            event: e.body.type,
            body: e.body
        };

        this.trace.verbose(`onDebugEvent event:${event.event}`);

        if (event.event === 'uiStopped') {
            const stoppedEvent = event as DebugProtocol.StoppedEvent;
            this.continueReason = undefined;
            const stoppedEventBody = stoppedEvent.body as any;
            const threads = stoppedEventBody.threads ? stoppedEventBody.threads : stoppedEventBody.Threads;
            const stackFrames = stoppedEventBody.stackFrames ? stoppedEventBody.stackFrames : stoppedEventBody.StackFrames;
            const scopes = stoppedEventBody.scopes ? stoppedEventBody.scopes : stoppedEventBody.Scopes;
            const sourceReferenceContent = stoppedEventBody.sourceReferenceContent ? stoppedEventBody.sourceReferenceContent : stoppedEventBody.SourceReferenceContent;

            this.stoppedEvent = {
                threads,
                stackFrames,
                scopes,
                sourceReferenceContent
            };

            this.trace.verbose(`onDebugEvent:stoppedEvent -> reason:${stoppedEvent.body.reason}`);
            event = new StoppedEvent(stoppedEvent.body.reason, stoppedEvent.body.threadId);
        }

        this.sendEvent(event);
    }

    private onUIDebugEvent(e: vslsDebug.UIDebugEventArgs) {
        this.trace.verbose(`onUIDebugEvent event:${e.body.type}`);
        if (e.body.type === 'enterRunMode' && this.continueReason === undefined) {
            const enterRunMode = e.body as vslsDebug.EnterRunMode;
            if (enterRunMode.Reason === 2 || enterRunMode.Reason === 8) {
                this.trace.verbose(`onUIDebugEvent::EnterRunMode threadId:${enterRunMode.ThreadId} reason:${enterRunMode.Reason}`);
                this.stoppedEvent = undefined;
                // Send Continued event to our host
                this.sendEvent(new ContinuedEvent(enterRunMode.ThreadId));
            }
        }
    }

    private async handleProtocolRequest(requestType: string, reqArguments?: any): Promise<any> {
        try {
            const response = await this.debugSessionHostService.handleProtocolRequestAsync(requestType, reqArguments);
            return response;
        } catch (e) {
            this.trace.error(`Failed to handleProtocolRequest for type:${requestType}. Error:${e}`);
            throw e;
        }
    }

    private async continue(reason: vslsDebug.ContinueReason, threadId: number) {
        // TODO:liveshare-web
        // var lastReason = this.continueReason;
        // var lastStoppedEvent = this.stoppedEvent;

        this.stoppedEvent = undefined;
        this.continueReason = reason;
        this.trace.verbose(`Continue->reason:${reason}`);

        try {
            await this.debugSessionHostService.continueAsync(reason, threadId);
            this.trace.verbose('Continue <---');
        } catch (e) {
            if (e.code === RpcErrorCodes.ServiceNotAvailable) {
                // The remote debug session service is no longer available.
                // The debug session must have ended while this request was queued.
                this.trace.verbose('Continue <---disconnected');
            }
        }
    }

    private async initializeHostRequest(): Promise<void> {
        const includeModules = (this.debugSession.capabilities.SupportsModulesRequest === true);

        let response: vslsDebug.InitializeDebugSessionResponse;
        try {
            const request = new vslsDebug.InitializeDebugSessionRequest();
            request.includeModules = includeModules;
            response = await this.debugSessionHostService.initializeRequestAsync(request);
        } catch (e) {
            if (e.code === RpcErrorCodes.MethodNotFound) {
                // If InitializeRequestAsync isn't supported by the host fall back
                // to making separate requests for the UIStoppedEvent & ModulesResponse
                const uiStoppedEvent = await this.debugSessionHostService.getCurrentStoppedEventAsync();
                //var modulesResponse = includeModules ? await handleProtocolRequest<ModulesResponse>(ModulesRequest.RequestType, new ModulesArguments()) : null;
                response = new vslsDebug.InitializeDebugSessionResponse();
                response.stoppedEvent = uiStoppedEvent;
                response.outputEvents = [];
                response.replayEvents = [];
            } else if (e.code === RpcErrorCodes.ServiceNotAvailable) {
                this.sendEvent(new TerminatedEvent());
                return;
            } else {
                throw e;
            }
        }

        // Sync up if remote session is on break state
        if (response.stoppedEvent != null) {
            const stoppedEvent: any = {
                body: response.stoppedEvent,
            };
            stoppedEvent.body.type = 'uiStopped';

            this.trace.verbose(`initializeHostRequest -> stoppedEvent reason:${stoppedEvent.body.reason}`);

            // Note: this event will be probably send from the VSCode side (VS does not) when an entry point is
            // hit. On VS side we should let the pass the reason since it will attempt to continue running the process since
            // launch flags are not set to 'stop on entry' option.
            if (stoppedEvent.body.reason === 'entry') {
                stoppedEvent.body.reason = 'breakpoint';
            }

            this.onDebugEvent(stoppedEvent);
        }

        // InitializeModules(response.ModulesResponse);

        // // Initialize console output events
        // Array.ForEach(response.OutputEvents, (debugEvent) => HandleDebugEvent(debugEvent));
    }
}