import { ICommandContext, NotificationUtil } from '@vs/vscode-command-framework';
import { ICommand } from '../abstractions/ICommand';
import { IDependencies } from '../contracts/IDependencies';
import { MessageFactory } from '../coediting/common/coauthoringService';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import {
    Telemetry,
} from '@vs/vso-telemetry';
import { TelemetryEventNames } from '../telemetry/TelemetryStrings';

export function builder(dependencies: IDependencies): FocusParticipantsCommand {
    return new FocusParticipantsCommand(dependencies);
}

export class FocusParticipantsCommand implements ICommand<boolean> {
    constructor(private readonly dependencies: IDependencies) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<boolean> {

        Telemetry.sendTelemetryEvent(TelemetryEventNames.FOCUS_PARTICIPANTS);

        if (!this.dependencies.sessionContext().coeditingClient) {
            return;
        }

        this.dependencies.sessionContext().coeditingClient.postMessage(MessageFactory.SummonMessage(this.dependencies.sessionContext().coeditingClient.clientID));
        const showVerboseNotifications = !!Settings.get<boolean>(SettingKeys.showVerboseNotifications);
        await NotificationUtil.showInformationMessage('Focus request sent.', showVerboseNotifications);
    }
}