'use strict';
import * as vscode from 'vscode';
import { Signal } from '@vs/vscs-utils';
import { vsls } from '@vs/vsls-contracts';
import { ISessionContext, CoauthoringInitializationParameters } from './ISessionContext';
import { ExtensionUtil } from './utils/ExtensionUtil';
import { CommandContext } from './CommandConstants';
import { ICoEditingCore, ICoEditing } from './coediting/ICoEditing';
import { CoEditing } from './coediting/CoEditing';
import { sessionStateTracker } from './SessionStateTracker';
import { IPathManager } from './IPathManager';
import { workspaceSessionInfoTracker } from './WorkspaceSessionInfoTracker';
import { userAuthStateTracker } from './UserAuthStateTracker';
import { CollaboratorManager } from './CollaboratorManager';
import { SessionTelemetry } from './telemetry/SessionTelemetry';
import { CollaboratorsTelemetry } from './telemetry/CollaboratorsTelemetry';
import {
    SessionState,
    CollaboratorChangedEventArgs,
    SessionStateChangedEventArgs,
    SessionAction,
    SessionPromise
} from './SessionTypes';
import { Settings } from './Settings';
import { SettingKeys } from './SettingKeys';
import {
    Telemetry,
    TelemetryResult,
} from '@vs/vso-telemetry';
import { TelemetryPropertyNames, TelemetryEventNames } from './telemetry/TelemetryStrings';

class SessionContext implements ISessionContext {
    private static singleton: SessionContext;
    private serversShared: boolean;
    private hasSharedTerminalsFlag: boolean;
    private hasCollaborators_: boolean;
    private isPlannedSessionsReadyFlag: boolean;
    private coeditingClientInstance: ICoEditing;

    public get coeditingClient(): ICoEditing {
        return this.coeditingClientInstance;
    }

    public serverSharingService: vsls.ServerSharingService;
    public collaboratorManager: CollaboratorManager;
    public extensionContext: vscode.ExtensionContext;
    private sessionPromiseMap: Map<SessionPromise, Signal<void>>;

    // For telemetry
    // The maximum number of guests this conversation had at a time
    private guestCountByIDE: { [ide: string]: number } = {};
    private distinctGuestCountByIDE: { [ide: string]: number } = {};

    // Events
    private readonly collaboratorChangedEmitter = new vscode.EventEmitter<CollaboratorChangedEventArgs>();
    public readonly onCollaboratorChanged = this.collaboratorChangedEmitter.event;
    private readonly hasCollaboratorsChangedEmitter = new vscode.EventEmitter<boolean>();
    public readonly onHasCollaboratorsChanged = this.hasCollaboratorsChangedEmitter.event;
    private readonly accessControlChangedEmitter = new vscode.EventEmitter<vsls.WorkspaceAccessControlEventArgs>();
    public readonly onAccessControlChanged = this.accessControlChangedEmitter.event;
    private readonly collaboratorsJoinedEmitter = new vscode.EventEmitter<void>();
    public readonly onCollaboratorsJoined = this.collaboratorsJoinedEmitter.event;
    private readonly coeditingClientChangedEmitter = new vscode.EventEmitter<ICoEditing>();
    public readonly onCoeditingClientChanged = this.coeditingClientChangedEmitter.event;

    constructor() {
        sessionStateTracker.onStateChanged(this.onSessionStateChanged.bind(this));
        this.sessionPromiseMap = new Map([
            [SessionPromise.EnvironmentReadyForFileOperation, new Signal<void>()],
            [SessionPromise.JoiningCompleted, new Signal<void>()]
        ])

        workspaceSessionInfoTracker.onReadOnlyChanged((isReadOnly: boolean) => {
            ExtensionUtil.setCommandContext(CommandContext.readOnlySession, isReadOnly);
        });
    }

    private updateTelemetryContext(e: SessionStateChangedEventArgs): void {
        let wasCollaborating = [SessionState.Shared, SessionState.Joined].indexOf(e.oldState) >= 0;
        if (this.isCollaborating) {
            if (workspaceSessionInfoTracker.workspaceSessionInfo) {
                let isHost = (e.newState === SessionState.Shared);
                const settings = vscode.workspace.getConfiguration(Settings.get<string>(SettingKeys.configName));
                SessionTelemetry.startSession(isHost, settings);
                if (isHost) {
                    this.resetTelemetry();
                }
            }
        } else if (wasCollaborating) {
            CollaboratorsTelemetry.endSession();
            SessionTelemetry.endSession(this.guestCountByIDE, this.distinctGuestCountByIDE);
        }
    }

    public onWorkspaceAccessControlChanged(e: vsls.WorkspaceAccessControlEventArgs) {
        this.accessControlChangedEmitter.fire(e);
    }

    /**
     * The last `sessionId` user have had in this session, if has been connected.
     */
    public getLatestPreviousSessionId(userId: string): number | undefined {
        if (!this.collaboratorManager) {
            return;
        }

        const { userIdBySessionIdHistory } = this.collaboratorManager;

        const previousUserSessionIds = [];
        for (let userSessionId of Object.keys(userIdBySessionIdHistory)) {
            const userSessionIdNumber = parseInt(userSessionId, 10);

            if (userId === userIdBySessionIdHistory[userSessionId]) {
                previousUserSessionIds.push(userSessionIdNumber);
            }
        }

        return Math.max(...previousUserSessionIds);
    }

    public initCoEditingContext(parameters: CoauthoringInitializationParameters): vscode.Disposable {
        if (!workspaceSessionInfoTracker.workspaceSessionInfo) {
            throw new Error('Failed to join a collaboration session. '
                + 'The host is offline. Ask them to start the session and rejoin.');
        }

        let initCoauthoringTelemetryEvent = Telemetry.startTimedEvent(TelemetryEventNames.INITIALIZE_COAUTHORING, true);
        initCoauthoringTelemetryEvent.addMeasure(TelemetryPropertyNames.NUM_OPEN_FILES, vscode.window.visibleTextEditors.length);

        userAuthStateTracker.userInfo = parameters.userInfo;
        this.collaboratorManager = new CollaboratorManager(this, workspaceSessionInfoTracker.workspaceSessionInfo.sessions);
        this.collaboratorManager.onCollaboratorsJoined(
            () => this.collaboratorsJoinedEmitter.fire());
        this.collaboratorManager.onCollaboratorChanged(
            (e: CollaboratorChangedEventArgs) => {
                this.collaboratorsChanged(e);
                CollaboratorsTelemetry.sendChangeCollaboratorsEvent(e);
            });

        const coEditing = new CoEditing({
            sourceEventService: parameters.sourceEventService,
            clientID: workspaceSessionInfoTracker.workspaceSessionInfo.sessionNumber,
            isGuest: parameters.isGuest,
            fileService: parameters.fileSystemService,
            pathManager: parameters.pathManager,
            clientAccessCheck: parameters.clientAccessCheck,
            collaboratorManager: this.collaboratorManager,
            joinCompleted: parameters.joinCompleted,
            fileSystemManager: parameters.fileSystemManager,
            syncService: parameters.syncService,
            presentationMode: workspaceSessionInfoTracker.workspaceSessionInfo.isPresentation
        });

        coEditing.init();
        this.coeditingClientInstance = coEditing;
        this.coeditingClientChangedEmitter.fire(coEditing);
        initCoauthoringTelemetryEvent.end(TelemetryResult.Success);
        return new vscode.Disposable(() => coEditing.dispose());
    }

    private collaboratorsChanged(e: CollaboratorChangedEventArgs): void {
        for (let ide of this.collaboratorManager.getIDEs()) {
            if (this.guestCountByIDE[ide] === undefined) {
                this.guestCountByIDE[ide] = 0;
            }
            if (this.distinctGuestCountByIDE[ide] === undefined) {
                this.distinctGuestCountByIDE[ide] = 0;
            }
            this.guestCountByIDE[ide] = Math.max(this.guestCountByIDE[ide], this.collaboratorManager.getCollaboratorCountByIDE(ide));
            this.distinctGuestCountByIDE[ide] = Math.max(this.distinctGuestCountByIDE[ide], this.collaboratorManager.getDistinctCollaboratorCountByIDE(ide));
        }

        this.collaboratorChangedEmitter.fire(e);
    }

    private disposeCoEditingContext(): void {
        workspaceSessionInfoTracker.workspaceSessionInfo = null;

        // Null checks in case there was an error while joining / sharing and the initialization did not fully complete
        if (this.collaboratorManager) {
            this.collaboratorManager.dispose();
            this.collaboratorManager = null;
        }

        if (this.coeditingClientInstance) {
            this.coeditingClientInstance.dispose();
            this.coeditingClientInstance = null;
            this.coeditingClientChangedEmitter.fire(null);
        }
    }

    public get hasServersShared(): boolean {
        return this.serversShared;
    }

    public set hasServersShared(serversShared: boolean) {
        this.serversShared = serversShared;
        ExtensionUtil.setCommandContext(CommandContext.isServerShared, serversShared);
    }

    public get hasSharedTerminals(): boolean {
        return this.hasSharedTerminalsFlag;
    }

    public set hasSharedTerminals(hasSharedTerminals: boolean) {
        this.hasSharedTerminalsFlag = hasSharedTerminals;
        ExtensionUtil.setCommandContext(CommandContext.hasSharedTerminals, hasSharedTerminals);
    }

    public get isPlannedSessionsReady(): boolean {
        return this.isPlannedSessionsReadyFlag;
    }

    public set isPlannedSessionsReady(isPlannedSessionsReady: boolean) {
        this.isPlannedSessionsReadyFlag = isPlannedSessionsReady;
        ExtensionUtil.setCommandContext(CommandContext.isPlannedSessionsReady, isPlannedSessionsReady);
    }

    public get isCollaborating() {
        return [SessionState.Shared,
        SessionState.Joined].indexOf(sessionStateTracker.State) >= 0;
    }

    public get isStartingCollaboration() {
        return [SessionState.JoiningInProgress,
        SessionState.SharingInProgress].indexOf(sessionStateTracker.State) >= 0;
    }

    private onSessionStateChanged(e: SessionStateChangedEventArgs) {
        if (this.isCollaborating) {
            Settings.save(SettingKeys.hasUsed, true);
        }
        this.updateTelemetryContext(e);

        const { newState } = e;

        ExtensionUtil.setCommandContext(CommandContext.state, SessionState[newState]);
        ExtensionUtil.setCommandContext(CommandContext.isCollaborating, (newState === SessionState.Shared) || (newState === SessionState.Joined));

        if (newState !== SessionState.Joined && newState !== SessionState.Shared) {
            // Disposal needs to happen synchronously, so we can't use the StateChanged event
            this.disposeCoEditingContext();

            this.hasServersShared = false;
            this.hasSharedTerminals = false;
            workspaceSessionInfoTracker.isReadOnly = false;
        }
    }

    public get hasCollaborators(): boolean {
        return this.hasCollaborators_;
    }

    public set hasCollaborators(hasCollaborators: boolean) {
        const previousHasCollaborators = this.hasCollaborators_;
        if (hasCollaborators !== previousHasCollaborators) {
            this.hasCollaborators_ = hasCollaborators;
            ExtensionUtil.setCommandContext(CommandContext.hasCollaborators, hasCollaborators);
            this.hasCollaboratorsChangedEmitter.fire(hasCollaborators);
        }
    }

    /**
     * Waits for the environment to be ready during the join process (successful, 
     * or otherwise). This is used to ensure that any operations that must be answered 
     * with certainty can wait until we know if we're joined or not (e.g. when we're
     *  joining, we don't know if we can answer the question, so must wait). Primarily,
     *  this is means any questions about files (E.g. does it exist? We dont know, we're not
     * joining!). This is useful on startup / opening of the workspace because we
     * might get file requests before we're in the session, and VS Code makes
     * decisions about files to read etc based on the responses we give.
     *
     * It is assumed that we are "joining" immediately on creation, and
     * will either end up reaching a terminal state when join/fail to join/decide
     * not to join.
     */
    public waitForSessionPromise(sessionPromise: SessionPromise): Promise<void> {
        return this.sessionPromiseMap.get(sessionPromise).promise
    }

    /**
     * Indicates that we have successfully joined the session
     */
    public joined(): void {
        // If session is joined, Environment is also ready for file operations
        if (!this.sessionPromiseMap.get(SessionPromise.EnvironmentReadyForFileOperation).isFulfilled) {
            this.environmentReadyForFileOperation();
        }
        sessionStateTracker.transition(SessionAction.JoiningSuccess);
        this.sessionPromiseMap.get(SessionPromise.JoiningCompleted).resolve();
    }

    /**
    * Indicates that we are ready to start file operations
    */
    public environmentReadyForFileOperation(): void {
        this.sessionPromiseMap.get(SessionPromise.EnvironmentReadyForFileOperation).resolve();
    }

    /**
     * Indicates that we are no longer attempting to join
     */
    public notJoining(): void {
        this.sessionPromiseMap.get(SessionPromise.JoiningCompleted).resolve(null);
    }

    public static get Instance(): SessionContext {
        if (!SessionContext.singleton) {
            SessionContext.singleton = new SessionContext();
        }

        return SessionContext.singleton;
    }

    private resetTelemetry() {
        CollaboratorsTelemetry.resetActiveEvent(false);
        if (!CollaboratorsTelemetry.listenerAdded) {
            CollaboratorsTelemetry.listenerAdded = true;
            this.onHasCollaboratorsChanged((hasCollaborators: boolean) => {
                CollaboratorsTelemetry.activeEvent.end(TelemetryResult.Success);
                CollaboratorsTelemetry.resetActiveEvent(hasCollaborators);
            });
        }
    }

    public dispose(): void {
        if (this.isCollaborating) {
            SessionTelemetry.endSession(this.guestCountByIDE, this.distinctGuestCountByIDE);
        }
    }
}

// Most importers only need the singleton instance.
const sessionContextInstance = SessionContext.Instance;
export {
    SessionContext as SessionContextClass,
    sessionContextInstance as SessionContext,
};

class CoEditingMock implements ICoEditingCore {

    public constructor(private pathManager: IPathManager) {
    }

    public clientID = 100;
    public openUntitledFiles = new Map<string, vscode.FileStat>();
    public uriToFileName(uri: vscode.Uri): string {
        return this.pathManager.localPathToRelativePath(uri);
    }

    public performFileOpenHandshake(fileName: string, receivedContent: string): Promise<string | boolean> {
        return Promise.resolve(receivedContent);
    }
}