import { ICommand } from '../abstractions/ICommand';
import { IDependencies } from '../contracts/IDependencies';
import { ErrorNotificationCommandDecorator } from './ErrorNotificationCommandDecoratorClass';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { ICommandDecoratorCallback } from '../abstractions/ICommandDecorator';

export const errorNotificationCommandDecoratorFactory = (command: ICommand<any>, dependencies: IDependencies, telemetryFaultEventName: string, title: string, isModalError: boolean = false, onError?: ICommandDecoratorCallback) => {
    return new ErrorNotificationCommandDecorator(
        DecoratorHelper.getCoreCommand(command),
        command,
        dependencies.telemetry(),
        telemetryFaultEventName,
        title,
        isModalError,
        onError
    );
};
