import { PolicyResolutionStrategy } from './policyResolutionStrategy';

export class ConnectionModeStrategy implements PolicyResolutionStrategy<string> {
    public readonly default: string = 'auto';

    public resolvePolicy(policyValues: string[]): string {
        if (!policyValues || policyValues.length === 0)
            return this.default;

        if (policyValues.includes('direct'))
            return 'direct';

        if (policyValues.includes('relay'))
            return 'relay';

        return this.default;
    }
}
