import { IConsoleLogger } from '../interfaces/IConsoleLogger';

import { LogLevel } from '../interfaces/LogLevel';
import { TraceFormat } from '../TraceFormat';
import { TraceListener } from '../TraceListener';

/**
 * A trace listener using the `console`.
 */
export class ConsoleTraceListener extends TraceListener {
    constructor(
        protected readonly consoleReference: IConsoleLogger = console,
    ) {
        super();
    }

    public writeTo(line: string): void {
        this.consoleReference.log(line)
    }

    protected writeEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void {
        const line = TraceFormat.formatEvent(null, source, logLevel, id, message, ...args);

        switch (logLevel) {
            case LogLevel.Critical:
            case LogLevel.Error: {
                return this.consoleReference.error(line);
            }

            case LogLevel.Warning: {
                return this.consoleReference.warn(line);
            }

            case LogLevel.Debug: {
                return (this.consoleReference.debug)
                    ? this.consoleReference.debug(line)
                    : this.consoleReference.log(line);
            }

            default: {
                return this.consoleReference.log(line);
            }
        }
    };
};
