import { ICommandContext } from '@vs/vscode-command-framework';

import { 
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { 
    ContactTreeExplorerItem
} from '../ContactsProviderViewlet';

export function builder(): ICommand<void> {
    return new ChangeSelfPresenceStatusCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.CHANGE_SELF_PRESENCE_STATUS, TelemetryEventNames.CHANGE_SELF_PRESENCE_STATUS_FAULT, 'ChangeSelfPresenceStatus', 1)
class ChangeSelfPresenceStatusCommand implements ICommand<void> {

    public async invoke(options: ContactTreeExplorerItem, context: ICommandContext): Promise<void> {
        let statusName = context.commandText.substr('liveshare.changePresence'.length);
        statusName = statusName.charAt(0).toLowerCase() + statusName.slice(1);
        const status: contactProtocol.PresenceStatus = <any>statusName;

        await options.contactServiceManager.publishPresence(status, {});
    }
}