import { ILogger } from '@vs/vso-logging';
import { createDuplexStreams } from './createDuplexStreams';
import { IMultiChannelRpcClient, createMultiChannelRpcClient } from './createMultiChannelRpcClient';
import { MultiChannelRpcServer } from './MultiChannelRpcServer';

export async function createDuplexMultiChannelRpcClient(
    rcpServer: MultiChannelRpcServer,
    logger: ILogger
): Promise<IMultiChannelRpcClient> {
    const [stream1, stream2] = createDuplexStreams();
    const serverPromise = rcpServer.acceptStream(stream1);

    const multiChannelRpcClientPromise = createMultiChannelRpcClient(stream2, logger);

    const [messageConnectionInfo, rpcClient] = await Promise.all([
        serverPromise,
        multiChannelRpcClientPromise,
    ]);
    messageConnectionInfo[0].listen();
    return rpcClient;
}
