import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { ICollaboratorManager } from './ICollaborationManager';
import { IMap } from './IMap';
import { CollaboratorChangedEventArgs } from './SessionTypes';
import { ISessionContext } from './ISessionContext';

import { DEFAULT_ANONYMOUS_USER_NAME, READ_ONLY_LABEL, READ_WRITE_LABEL } from './constants';
import { userAuthStateTracker } from './UserAuthStateTracker';
import { AnonymousAccessLevel, workspaceSessionInfoTracker } from './WorkspaceSessionInfoTracker';
import { getExpService } from './exp/ExperimentationService';

export class CollaboratorManager implements ICollaboratorManager {
    // all users that were in this session by `sessionId`
    public readonly userIdBySessionIdHistory: IMap<string> = {};
    
    private localUserInfo: vsls.UserInfo;
    private coEditorsHistory: IMap<boolean> = {}; // Hashset of all session numbers that were co-editors
    private coEditors: IMap<boolean> = {}; // Hashset of session numbers that are co-editors and currently connected
    private coEditorsIDE: IMap<string> = {}; // Hashset of session numbers and the IDE of these sessions
    private coEditorCount: number = 0;
    private profiles: IMap<vsls.WorkspaceUserProfile> = {};
    private profileByUserIdHistory: IMap<vsls.WorkspaceUserProfile> = {};
    private profileByUserId: IMap<vsls.WorkspaceUserProfile> = {};

    private readonly collaboratorChangedEmitter = new vscode.EventEmitter<CollaboratorChangedEventArgs>();
    public readonly onCollaboratorChanged = this.collaboratorChangedEmitter.event;
    private readonly collaboratorsJoinedEmitter = new vscode.EventEmitter<void>();
    public readonly onCollaboratorsJoined = this.collaboratorsJoinedEmitter.event;

    public constructor(
        private sessionContext: ISessionContext,
        collaboratorProfiles: IMap<vsls.WorkspaceUserProfile>
    ) {
        this.localUserInfo = userAuthStateTracker.userInfo;
        this.profiles = collaboratorProfiles || {};
        
        for (let key of Object.keys(collaboratorProfiles)) {
            const profile = collaboratorProfiles[key];
            
            this.userIdBySessionIdHistory[key] = profile.id;
        }
    }

    public onWorkspaceSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs) {
        const previouslyJoined = !!this.profileByUserIdHistory[e.userProfile.id];
        const isHost = this.localUserInfo.id === e.userProfile.id;
        const hasCollaborators = !!this.sessionContext.hasCollaborators;

        if (e.changeType === vsls.WorkspaceSessionChangeType.Joined) {
            this.profiles[e.sessionNumber] = e.userProfile;
            this.userIdBySessionIdHistory[e.sessionNumber] = e.userProfile.id;
            this.profileByUserIdHistory[e.userProfile.id] = e.userProfile;
            this.profileByUserId[e.userProfile.id] = e.userProfile;
            this.coEditorsIDE[e.sessionNumber] = e.applicationName;
        } else if (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined) {
            delete this.coEditors[e.sessionNumber];
            delete this.profiles[e.sessionNumber];
            delete this.profileByUserId[e.userProfile.id];
            if (this.coEditorCount > 0) {
                --this.coEditorCount;
            }
        }

        if (this.coEditorCount <= 0) {
            this.sessionContext.hasCollaborators = false;
        }

        this.collaboratorChangedEmitter.fire({
            userProfile: e.userProfile,
            changeType: e.changeType,
            applicationName: e.applicationName,
            disconnectedReason: e.disconnectedReason,
            sessionNumber: e.sessionNumber,
            collaboratorSessionHash: this.getProfileIndex(e.userProfile.id),
            previouslyJoined,
            isHost,
            hasCollaborators
        });
    }

    public getDisplayName(sessionId: number): string {
        const profile = this.profiles[sessionId];
        const isHostAllowedAnonyUserToBeRW = workspaceSessionInfoTracker.getAnonymousAccess(profile.id) === AnonymousAccessLevel.readWrite;

        if (profile) {
            if (profile.isAnonymous) {

                if (this.isReadWriteAnonymousEnabled() && isHostAllowedAnonyUserToBeRW) {
                    return `${profile.name} (${READ_WRITE_LABEL})`;
                }
                return `${profile.name} (${READ_ONLY_LABEL})`;
            }

            return profile.name || profile.userName || profile.email;
        }

        if (this.sessionContext.coeditingClient && sessionId === this.sessionContext.coeditingClient.clientID) {
            return this.localUserInfo.displayName || this.localUserInfo.emailAddress;
        }

        // Unknown user profile. Return default value.
        return `Collaborator ${sessionId}`;
    }

    public isReadWriteAnonymousEnabled(): boolean | undefined {
        return getExpService()?.getTreatmentVariable('vscode', 'readWriteAnonymous');
    }

    public getUserId(sessionId: number): string | undefined {
        const profile = this.profiles[sessionId];
        return profile && profile.id;
    }

    private getEmailOrUsername(sessionId: number): string {
        const profile = this.profiles[sessionId];
        if (profile) {
            return profile.email || profile.userName || '';
        }
    }

    private getProfileIndex(userId: string): number {
        return Object.keys(this.profileByUserIdHistory).findIndex((key) => key === userId);
    }

    /**
     * Returns all IDEs used by participants in this session
     */
    public getIDEs(): Set<string> {
        return new Set(this.getCollaboratorSessionIds().map(sessionId => this.coEditorsIDE[sessionId]));
    }

    /**
     * Returns the number of remote collaborators in this session (excludes the local user).
     */
    public getCollaboratorCount(): number {
        return this.coEditorCount;
    }

    public getCollaboratorCountByIDE(ide: string): number {
        return this.getCollaboratorEmailsOrUsernamesByIDE(ide).length;
    }

    /**
     * Returns the number of distinct remote collaborators in this session (excludes the local user).
     */
    public getDistinctCollaboratorCount(): number {
        return (new Set(this.getCollaboratorEmailsOrUsernames())).size;
    }

    // If the host is joined as a guest, this will not count them as a distinct guest
    public getDistinctCollaboratorCountByIDE(ide: string): number {
        return (new Set(
                    this.getCollaboratorEmailsOrUsernamesByIDE(ide)
                        .filter(emailOrUsername => emailOrUsername !== this.localUserInfo.emailAddress && emailOrUsername !== this.localUserInfo.userName)
            )).size;
    }

    /**
     * Returns the sessionId of all remote collaborators (excludes the local user).
     */
    public getCollaboratorSessionIds(): number[] {
        return Object.keys(this.coEditors)
            .map((id) => parseInt(id, 10));
    }

    /**
     * Returns the display names of all remote collaborators (excludes the local user).
     */
    private getCollaboratorEmailsOrUsernames(): string[] {
        return this.getCollaboratorSessionIds().map(sessionId => this.getEmailOrUsername(sessionId));
    }

    private getCollaboratorEmailsOrUsernamesByIDE(ide: string): string[] {
        return this.getCollaboratorSessionIds().filter(sessionId => (this.coEditorsIDE[sessionId] === ide)).map(sessionId => this.getEmailOrUsername(sessionId));
    }

    public coEditorsJoined(joinerIds: number[]): void {
        joinerIds.forEach((joinerId) => {
            if (joinerId !== this.sessionContext.coeditingClient.clientID) {
                this.coEditorsHistory[joinerId] = true;
                this.coEditors[joinerId] = true;
                ++this.coEditorCount;
            }
        });

        if (this.coEditorCount > 0) {
            this.sessionContext.hasCollaborators = true;
        }

        this.collaboratorsJoinedEmitter.fire();
    }

    public wasCoEditor(sessionNumber: number): boolean {
        return typeof this.coEditorsHistory[sessionNumber] !== 'undefined';
    }

    public getCollaborators() {
        return {
            ...this.profiles
        };
    }

    public dispose(): void {
        this.collaboratorChangedEmitter.dispose();
        this.collaboratorsJoinedEmitter.dispose();
        this.sessionContext.hasCollaborators = false;
    }
}

