import * as rpc from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';
import { IRpcRequestContext } from '@vs/vso-rpc';
import { UserProfileChangeType, WorkspaceServer } from '@vs/vso-workspace-server';
import { assertDefined, defer, notImplemented } from '@vs/vscs-utils';
import { WorkspaceUserService } from './WorkspaceUserService';
import { ILogger } from '@vs/vso-logging';
import { IRpcServiceHandlerInfo } from '@vs/vso-rpc';
import { WorkspaceAccessControlService } from './WorkspaceAccessControlService';
import { WorkspaceApi } from '@vs/vso-workspace-core';

/**
 * Implements the vsls Workspace Service for a host scenario.
 */
export class WorkspaceService implements vsls.WorkspaceService, IRpcServiceHandlerInfo {

    private readonly registerServiceNames = new Set<string>();

    private onServicesChangedEmitter = new rpc.Emitter<vsls.WorkspaceServicesChangedEventArgs>();
    private onConnectionStatusChangedEmitter = new rpc.Emitter<vsls.WorkspaceConnectionStatusChangedEventArgs>();
    private onProgressUpdatedEmitter = new rpc.Emitter<vsls.WorkspaceProgressEventArgs>();
    private onUserRemovedEmitter = new rpc.Emitter<vsls.EventArgs>();
    private onUserBlockedEmitter = new rpc.Emitter<vsls.EventArgs>();
    private onWorkspaceReadyForConnectionEmitter = new rpc.Emitter<vsls.WorkspaceReadyForConnectionEventArgs>();

    public serviceInfo = vsls.WorkspaceService;

    constructor(
        private readonly workspaceServer: WorkspaceServer,
        private readonly workspaceUserService: WorkspaceUserService,
        private readonly workspaceAccessControlService: WorkspaceAccessControlService,
        private readonly workspaceApi: WorkspaceApi,
        private readonly logger: ILogger) {

        workspaceServer.onUserProfileChanged(e => {
            if (e.changeType === UserProfileChangeType.Closed
                || e.changeType === UserProfileChangeType.Removed) {
                const disconnectedReason = e.changeType === UserProfileChangeType.Removed ? vsls.WorkspaceDisconnectedReason.Requested : undefined;
                this.workspaceUserService.notifyUserUnjoinedWorkspaceSession(e.sessionNumber, e.userProfile, disconnectedReason);
            }
        });
    }

    async registerServicesAsync(serviceNames: string[], changeType: vsls.CollectionChangeType, cancellationToken?: rpc.CancellationToken): Promise<void> {
        serviceNames.forEach(s => {
            if (changeType === vsls.CollectionChangeType.Add) {
                this.registerServiceNames.add(s);
            } else if (changeType === vsls.CollectionChangeType.Add) {
                this.registerServiceNames.delete(s);
            }
        });
        this.fireServicesChanged(serviceNames, changeType);
    }

    private notiyServicesChanged(rpcRequestContext: IRpcRequestContext, changeType: vsls.CollectionChangeType) {
        // include the local and remote registered services
        const servicesChanged = new Set([...this.workspaceServer.serviceNames, ...Array.from(this.registerServiceNames)]);

        // Note: we should exclude the 'blessed' workspace name since the existing agent has already set in his collection
        // if we don't exclude the agent will throw a missing method exception but in reality is an ambigous resolve error
        // since we could have multiple rpc services that claim the workspace interface.
        servicesChanged.delete(vsls.WorkspaceService.name);

        rpcRequestContext.connection.sendNotification('workspace.servicesChanged',
            {
                serviceNames: [...servicesChanged],
                changeType,
            } as vsls.WorkspaceServicesChangedEventArgs);
    }

    async joinWorkspaceAsync(joinInfo: vsls.WorkspaceJoinInfo, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<vsls.WorkspaceSessionInfo> {
        assertDefined(rpcRequestContext, 'rpc request expected');
        
        this.logger.info(`joinWorkspace joinInfo:${JSON.stringify(joinInfo)}`);
        const joinerProfile = await this.workspaceServer.sharedWorkspace.getWorkspaceUserProfile(
            joinInfo.joiningUserSessionToken!
        );
        joinerProfile.clientCapabilities = {
            extensionReadOnlySupport: true,
            clientReadOnlySupport: true,
        };

        // make sure we put the joined anonymous name on the join profile.
        if (joinerProfile.isAnonymous && joinInfo.anonymousUserName) {
            joinerProfile.name = joinInfo.anonymousUserName;
        }

        const sessionNumber = rpcRequestContext.session;
        const rpcConnection = rpcRequestContext.connection;
        this.workspaceServer.addUserProfile(
            joinerProfile,
            rpcRequestContext
        );

        await this.workspaceUserService.addGuestOrThrowRejectionAsync(sessionNumber, joinerProfile, joinInfo.id, rpcConnection);

        // Note: the vsls C# agent would require the update its supported service names
        // by handling the notification on the onServiceChanged event.
        this.notiyServicesChanged(rpcRequestContext, vsls.CollectionChangeType.Add);

        const workspaceInfo = this.workspaceServer.sharedWorkspace.workspaceInfo;
        return {
            sessionNumber,
            id: workspaceInfo.id,
            name: workspaceInfo.name,
            conversationId: workspaceInfo.conversationId,
            joinUri: workspaceInfo.joinLink,
            connectionMode: vsls.ConnectionMode.Relay,
            sessions: this.workspaceServer.joinedProfiles,
            accessControl: this.workspaceAccessControlService.accessControl,
        };
    }

    unjoinWorkspaceAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken, rpcRequestContext?: IRpcRequestContext): Promise<void> {
        assertDefined(rpcRequestContext, 'rpc request expected');

        this.logger.info(`unjoinWorkspace workspaceId:${workspaceId}`);
        this.notiyServicesChanged(rpcRequestContext, vsls.CollectionChangeType.Remove);

        // Note: we can't kill the ssh session on this call since it would cause the caller to never receive
        // a response. Also notice we want also that the previous notification will also goes trough hence the 0.25 secs defering
        const rpcMessageConnection = rpcRequestContext!.connection;
        defer(async () => {
            this.workspaceServer.removeUserProfile(rpcMessageConnection, UserProfileChangeType.Removed);
            try {
                await this.workspaceServer.closeSshSession(rpcMessageConnection!);
            } catch {
            }
        }, 250);

       return Promise.resolve();
    }

    getWorkspaceAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceInfo> {
        notImplemented();
    }
    listWorkspacesAsync(options: vsls.WorkspaceListOptions, cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceInfo[]> {
        notImplemented();
    }
    createPersistentWorkspaceAsync(label: string, allowAnonymmous: boolean, cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceInfo> {
        notImplemented();
    }
    deleteWorkspaceAsync(id: string, cancellationToken?: rpc.CancellationToken): Promise<boolean> {
        notImplemented();
    }
    renameWorkspaceAsync(id: string, name: string, cancellationToken?: rpc.CancellationToken): Promise<string> {
        notImplemented();
    }
    shareWorkspaceAsync(shareInfo: vsls.WorkspaceShareInfo, cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceSessionInfo> {
        notImplemented();
    }
    async createInvitationLinkAsync(invitationLinkInfo: vsls.InvitationLinkInfo, cancellationToken?: rpc.CancellationToken): Promise<string> {
        const result = await this.workspaceApi.createInvitationLink(invitationLinkInfo);
        return result.joinLink;
    }
    getInvitationLinksAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<string[]> {
        notImplemented();
    }
    unshareWorkspaceAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<void> {
        notImplemented();
    }
    beginJoinWorkspaceAsync(joinInfo: vsls.WorkspaceJoinInfo, cancellationToken?: rpc.CancellationToken): Promise<vsls.WorkspaceInfo> {
        notImplemented();
    }
    canUserShareWorkspaceAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<boolean> {
        notImplemented();
    }
    canUserHostWorkspaceAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<boolean> {
        notImplemented();
    }
    createPublicInviteLinkAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<string> {
        notImplemented();
    }
    disconnectGuestAsync(guestId: number, workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<boolean> {
        notImplemented();
    }
    unjoinOnlineEnvironmentsGuestsAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<void> {
        notImplemented();
    }
    setWorkspaceReadyForConnectionAsync(workspaceId: string, cancellationToken?: rpc.CancellationToken): Promise<void> {
        notImplemented();
    }
    updateWorkspaceOwnerAsync(workspaceId: string, currentOwnerToken: string, newOwnerToken: string, cancellationToken?: rpc.CancellationToken): Promise<vsls.UserInfo> {
        notImplemented();
    }
       
    onServicesChanged = this.onServicesChangedEmitter.event;
    onConnectionStatusChanged = this.onConnectionStatusChangedEmitter.event;
    onProgressUpdated = this.onProgressUpdatedEmitter.event;
    onUserRemoved = this.onUserRemovedEmitter.event;
    onUserBlocked = this.onUserBlockedEmitter.event;
    onWorkspaceReadyForConnection = this.onWorkspaceReadyForConnectionEmitter.event;

    private fireServicesChanged(serviceNames: string[], changeType: vsls.CollectionChangeType) {
        this.onServicesChangedEmitter.fire({
            serviceNames,
            changeType,
        });
    }

    public fireConnectionStatusChanged(connectionStatus: vsls.WorkspaceConnectionStatus, disconnectedReason?: vsls.WorkspaceDisconnectedReason) {
        this.onConnectionStatusChangedEmitter.fire({
            connectionStatus,
            disconnectedReason,
        });
    } 
}