import * as rpc from 'vscode-jsonrpc';

const contentLengthHeaderPrefix = 'Content-Length: ';
const headersSeparator = '\r\n\r\n';

export class RpcMessageWriter implements rpc.MessageWriter {
    private readonly onErrorEmitter = new rpc.Emitter<
        [Error, rpc.Message | undefined, number | undefined]
    >();
    private readonly onCloseEmitter = new rpc.Emitter<void>();

    constructor() {}

    public onSendCallback: ((data: Buffer) => Promise<void>) | undefined;

    public readonly onError = this.onErrorEmitter.event;
    public readonly onClose = this.onCloseEmitter.event;

    public write(message: rpc.Message): void {
        const messageJson = JSON.stringify(message);
        const messageData = Buffer.from(messageJson);
        const headerData = Buffer.from(
            contentLengthHeaderPrefix + messageData.length + headersSeparator
        );
        const data = Buffer.alloc(headerData.length + messageData.length);
        headerData.copy(data, 0);
        messageData.copy(data, headerData.length);

        if (this.onSendCallback) {
            this.onSendCallback(data).catch((e: Error) => {
                this.onErrorEmitter.fire([e, undefined, undefined]);
            });
        }
    }

    public dispose() {}
}
