import * as vscode from 'vscode';
import { IParticipantInfo, CallChangedType, SkypeTokenInfo, ICallInfo, CallChanged,
    DeviceType, IDevice, ISelectedDevices } from '@calling-service/ICallingService';
import { workspaceSessionInfoTracker, TelemetryEventNames, ExtensionUtil,
    sessionStateTracker, SessionState, HandledQuickPickItem, CommandContext,
    Settings, SettingKeys, TelemetryPropertyNames, localize } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { getVSLSTokenFromAuthService } from './utils';
import { TraceSource } from '@vs/vso-logging';
import { CancellationError } from '@vs/vscode-command-framework';
import { MESSAGE_SERVICE_NAME, CallingServiceCommands, CallingEventType } from '../constants';
import { Telemetry, TelemetryResult } from '@vs/vso-telemetry';
import { AudioSessionAction, AudioSessionContext } from './AudioSessionContext';
import { CallingServiceProxy } from './CallingServiceProxy';
import { AudioStatusBarController } from './AudioStatusBarController';
import { IRpcClientProxy } from '@vs/vso-rpc';
import { MessagingService } from './MessagingService';

export class CallingServiceManager {
    private audioStatusBarController: AudioStatusBarController;
    private callingServiceProxy: CallingServiceProxy;
    private isCallStarted: boolean;
    private currentTokenInfo: SkypeTokenInfo;
    private isDisposed: boolean;
    private isConnecting: boolean;
    private messagingService: MessagingService;
    private trackedCalls: Map<string, boolean>;

    constructor(
        private authCoreService: vsls.AuthenticationCoreService,
        private rpcClient: IRpcClientProxy,
        private registeredServicesCallback: () => Promise<string[]>,
        private trace: TraceSource) {
        this.callingServiceProxy = new CallingServiceProxy();

        this.audioStatusBarController = new AudioStatusBarController(this, this.trace);
        
        sessionStateTracker.onStateChanged(async (e) => {
            if (e.newState === SessionState.Joined) {
                AudioSessionContext.transition(AudioSessionAction.LiveShareSessionStarted);
            }
        });

        AudioSessionContext.transition(AudioSessionAction.InitializeDone);
    }

    private readonly newCallEventEmitter = new vscode.EventEmitter<void>();
    public readonly onNewAudioCallAvailable = this.newCallEventEmitter.event;

    private readonly muteChangedEventEmitter = new vscode.EventEmitter<IParticipantInfo | undefined>();
    public readonly onMuteChanged = this.muteChangedEventEmitter.event;

    private readonly participantsListChangedEventEmitter = new vscode.EventEmitter<void>();
    public readonly onParticipantsListChanged = this.participantsListChangedEventEmitter.event;

    private readonly participantChangedEventEmitter = new vscode.EventEmitter<IParticipantInfo>();
    public readonly onParticipantChanged = this.participantChangedEventEmitter.event;

    public async initialize(): Promise<void> {
        this.trackedCalls = new Map<string, boolean>();

        this.messagingService = new MessagingService(MESSAGE_SERVICE_NAME, this.rpcClient, this.registeredServicesCallback, this.trace);
        await this.messagingService.initialize();
        this.messagingService.onNotify(this.onNotify);

        await this.registerCommands();
        await this.callingServiceProxy.initialize((event: CallChanged) => this.onCallChanged(event));
    }

    public async commandStartOrJoinCall(): Promise<void> {
        if (this.isConnecting) {
            this.trace.warning(`Attempt to start or join a call that is already connecting.`);
            return;
        }

        this.isConnecting = true;
        const connectEvent = Telemetry.startTimedEvent(TelemetryEventNames.AUDIO_CONNECT_CALL);
        try {
            AudioSessionContext.transition(AudioSessionAction.AttemptConnectAudio);
            const sessionId = workspaceSessionInfoTracker.workspaceSessionInfo.id;
            await ExtensionUtil.runWithProgress(async () => await this.connectToCall(sessionId),
            { title: localize('calling.connectingAudio') });
            AudioSessionContext.transition(AudioSessionAction.AudioConnected);
        } catch (e) {
            if (e instanceof CancellationError) {
                this.trace.warning(`startOrJoinCall: cancellation on connect to audio: ${e.message}`);
                AudioSessionContext.transition(AudioSessionAction.AudioConnectionFailed);
                connectEvent.end(TelemetryResult.Cancel);
                return;
            }

            this.trace.error(`startOrJoinCall: Caught error while trying to connect to audio: ${e.message} ${e.stack}`);
            AudioSessionContext.transition(AudioSessionAction.AudioConnectionFailed);
            connectEvent.end(TelemetryResult.Failure, e.message);
            throw e;
        } finally {
            this.isConnecting = false;
        }

        connectEvent.end(TelemetryResult.Success);
    }

    public async promptToJoinCall() {
        const joinAudioPromptJoin = localize('calling.joinButton');
        const selectedValue = await vscode.window.showInformationMessage(localize('calling.joinInformationMessage'), joinAudioPromptJoin);
        if (selectedValue === joinAudioPromptJoin) {
            await this.commandStartOrJoinCall();
        }

        Telemetry.sendTelemetryEvent(TelemetryEventNames.JOIN_PROMPT_DISPLAYED, { [TelemetryPropertyNames.SELECTED_ACTION]: selectedValue });
    }

    public async getCallInfo(): Promise<ICallInfo> {
        if (!this.isCallStarted) {
            return;
        }

        return await this.callingServiceProxy.getCallInfo();
    }

    public checkIfCallIsAvailable() {
        this.trace.info('checkIfCallIsAvailable');
        const callInfoRequestMessage = {
            callingEventType: CallingEventType.CallInformationRequest
        };
        this.messagingService.notify(callInfoRequestMessage);
    }

    public async getSelectedDevices(): Promise<ISelectedDevices> {
        if (!this.isCallStarted) {
            return {};
        }
        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_GET_SELECTED_DEVICES);
        return await this.callingServiceProxy.getSelectedDevices();
    }

    public async getParticipants(): Promise<IParticipantInfo[]> {
        if (!this.isCallStarted) {
            return [];
        }

        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_GET_PARTICIPANTS);
        const participants = await this.callingServiceProxy.getParticipants();
        return participants || [];
    }

    public async endCall(): Promise<void> {
        if (!this.isCallStarted) {
            return;
        }
        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_END_CALL);
        await this.callingServiceProxy.endCall();
        this.isCallStarted = false;
    }

    public async enumerateDevices(): Promise<IDevice[]> {
        if (!this.isCallStarted) {
            return [];
        }
        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_ENUMERATE_DEVICES);
        return await this.callingServiceProxy.getDevices();
    }

    public async isMuted(): Promise<boolean> {
        if (!this.isCallStarted) {
            return false;
        }
        return await this.callingServiceProxy.isMuted();
    }

    public async onLiveShareSessionEnded() {
        try {
            await this.endCall();
            await this.dispose();
        } catch (e) {
            this.trace.error(`Failed to clean up call: ${e.message} ${e.stack}`);
        }
    }

    public async mute(participant?: IParticipantInfo): Promise<void> {
        if (!this.isCallStarted) {
            return;
        }

        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_MUTE);
        await this.callingServiceProxy.mute(participant);

        if (!participant) {
            await ExtensionUtil.setCommandContext(CommandContext.audioIsMuted, 'true');
            this.muteChangedEventEmitter.fire(undefined);
        }
    }

    public async unmute(participant?: IParticipantInfo): Promise<void> {
        if (!this.isCallStarted) {
            return;
        }

        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_UNMUTE);
        await this.callingServiceProxy.unmute(participant);

        if (!participant) {
            await ExtensionUtil.setCommandContext(CommandContext.audioIsMuted, 'false');
            this.muteChangedEventEmitter.fire(undefined);
        }
    }

    public async setDevice(deviceId: string, deviceType: DeviceType): Promise<void> {
        if (!this.isCallStarted) {
            return;
        }

        const selectedDevices = await this.getSelectedDevices();
        let settingsKey: string;
        switch (deviceType) {
            case 'Microphone':
                settingsKey = SettingKeys.microphoneId;
                selectedDevices.microphone = deviceId;
                break;
            case 'Speaker':
                settingsKey = SettingKeys.speakerId;
                selectedDevices.speaker = deviceId;
                break;
            default:
                return;
        }

        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_SELECT_DEVICE,  { [TelemetryPropertyNames.AUDIO_DEVICE_TYPE]: deviceType });
        await this.callingServiceProxy.selectDevices(selectedDevices);
        await Settings.save(settingsKey, deviceId);
    }

    public async dispose() {
        if (!this.isDisposed) {
            this.isDisposed = true;
            this.isCallStarted = false;
            this.currentTokenInfo = null;
        }
    }

    private async connectToCall(groupContext: string): Promise<void> {
        try {
            this.isCallStarted = false;
            const mriGroupContext = `99:${groupContext}`;

            let userName;
            const user = await this.authCoreService.getCurrentUserAsync();
            if (user) {
                userName = user.displayName || user.userName || user.emailAddress;
            }
            userName = userName || 'Unknown user';

            const skypeTokenInfo = await this.getVSLSToken();
            await this.callingServiceProxy.startOrJoinCall(mriGroupContext, userName, skypeTokenInfo);
            this.isCallStarted = true;
            await this.setUserPreferences();
        } catch (e) {
            if (!this.isDisposed) {
                // If the call hasn't been explicitly disposed
                // (ex: call canceled or Live Share session ended)
                // then log and throw the error
                this.trace.error(`Failed to connect call: ${e.message} ${e.stack}`);
                throw e;
            }

            // Otherwise, throw a cancellation error
            throw new CancellationError(e.message);
        }
    }

    private async registerCommands(): Promise<void> {
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.startOrJoinCall, async () => await this.commandStartOrJoinCall());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.endCall, async () => await this.leaveCall());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.muteSelf, async () => await this.mute());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.unmuteSelf, async () => await this.unmute());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.muteOrUnmute, async () => await this.muteOrUnmute());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.selectMicrophone, async () => await this.selectMicrophone());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.selectSpeaker, async () => await this.selectSpeaker());
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.setMicrophone, async (device) => await this.setDevice(device, 'Microphone'));
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.setSpeaker, async (device) => await this.setDevice(device, 'Speaker'));
        await ExtensionUtil.tryRegisterCommand(CallingServiceCommands.viewParticipants, async () => await this.viewParticipants());
    }

    private async muteOrUnmute(): Promise<void> {
        if (await this.isMuted()) {
            await this.unmute();
        } else {
            await this.mute();
        }
    }

    private async leaveCall(): Promise<void> {
        try {
            AudioSessionContext.transition(AudioSessionAction.AttemptDisconnectAudio);
            await ExtensionUtil.runWithProgress(async () => await this.endCall(),
                { title: localize('calling.disconnectingAudio') });
            AudioSessionContext.transition(AudioSessionAction.AudioDisconnected);
        } catch (e) {
            this.trace.error(`leaveAudio: Caught error: ${e.message} ${e.stack}`);
            AudioSessionContext.transition(AudioSessionAction.AudioConnectionFailed);
            throw e;
        }
    }

    private async viewParticipants() {
        const participants: vscode.QuickPickItem[] = (await this.callingServiceProxy.getParticipants()).map((participant) => {
            return {
                label: '',
                description: participant.displayName,
            };
        });
        return vscode.window.showQuickPick(participants, { placeHolder: localize('calling.viewParticipantsQuickPickPlaceholder') });
    }

    private async selectMicrophone() {
        const microphoneOptions = await this.buildDeviceList('Microphone');

        return this.showEnabledQuickPick(microphoneOptions, { placeHolder: localize('calling.selectMicrophoneQuickPickPlaceholder') })
            .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
    }

    private async selectSpeaker() {
        const speakerOptions = await this.buildDeviceList('Speaker');

        return this.showEnabledQuickPick(speakerOptions, { placeHolder: localize('calling.selectSpeakersQuickPickPlaceholder') })
            .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
    }

    private async buildDeviceList(deviceType: DeviceType): Promise<HandledQuickPickItem[]> {
        const allDevices = await this.enumerateDevices();
        const selectedDevices = await this.getSelectedDevices();

        const quickPick = allDevices
            .filter((device) => device.type === deviceType)
            .map((device) => {
                return {
                    command: `liveshare.callingService.setDevice.${deviceType.toLowerCase()}`,
                    commandArg: device.id,
                    label: `${this.isSelectedDevice(device, selectedDevices) ? '$(check)' : '   '} ${device.name}`,
                    enabled: () => true
                } as HandledQuickPickItem;
            });

        return quickPick;
    }

    private isSelectedDevice(device: IDevice, selectedDevices: ISelectedDevices): boolean {
        if (!device) {
            return false;
        } 

        switch (device.type) {
            case 'Camera':
                return selectedDevices.camera && (device.id === selectedDevices.camera);
            case 'Microphone':
                return selectedDevices.microphone && (device.id === selectedDevices.microphone);
            case 'Speaker':
                return selectedDevices.speaker && (device.id === selectedDevices.speaker);
            default:
                return false;
        }
    }

    private showEnabledQuickPick(items: HandledQuickPickItem[], options?: vscode.QuickPickOptions) {
        return vscode.window.showQuickPick(items.filter(item => item.enabled()), options);
    }

    private async setUserPreferences(): Promise<void> {
        const microphoneId = Settings.get<string>(SettingKeys.microphoneId);
        if (microphoneId) {
            await this.setDevice(microphoneId, 'Microphone');
        }

        const speakerId = Settings.get<string>(SettingKeys.speakerId);
        if (speakerId) {
            await this.setDevice(speakerId, 'Speaker');
        }
    }

    private async onCallChanged(event: CallChanged): Promise<void> {
        this.trace.info(`Call changed event received from calling service: ${event.changeType}`);
        switch (event.changeType) {
            case CallChangedType.callStarted:
                const callInfo = event.info as ICallInfo;
                this.sendCallStartedNotification(callInfo);
                break;
            case CallChangedType.callDisconnected:
                AudioSessionContext.transition(AudioSessionAction.AudioDisconnected);

                // When a call is disconnected check to
                // see if it is still available to give the user the
                // option to (re)join
                this.checkIfCallIsAvailable();
                break;
            case CallChangedType.participantsListChanged:
                this.participantsListChangedEventEmitter.fire();
                break;
            case CallChangedType.participantChanged:
                const participantInfo = event.info as IParticipantInfo;
                this.participantChangedEventEmitter.fire(participantInfo);
                break;
            default:
                throw new Error(`Unexpected call change type: ${event.changeType}`);
            }
    }

    private onNotify = async (message: any): Promise<void> => {
        switch (message.callingEventType) {
            case CallingEventType.CallStarted:
                if (message.callId) {
                    Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_CALL_STARTED_NOTIFICATION);
                    this.newCallEventEmitter.fire();

                    // Only prompt for new call notifications
                    if (!this.trackedCalls.has(message.callId)) {
                        this.trackedCalls.set(message.callId, true);
                        if (!await this.callingServiceProxy.getCallInfo()) {
                            await this.promptToJoinCall();
                        }
                    }
                }
                break;
            case CallingEventType.CallInformationRequest:
                if (this.isCallStarted) {
                    const callInfo = await this.getCallInfo();
                    if (callInfo && (callInfo.state === 'Connected')) {
                        Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_CALL_INFO_NOTIFICATION);
                        this.sendCallStartedNotification(callInfo);
                    }
                }
                break;
            default:
                Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_CALL_UNEXPECTED_NOTIFICATION);
                throw new Error(`Unexpected call event type: ${message.callingEventType}`);
        }
    }

    private sendCallStartedNotification(callInfo: ICallInfo) {
        // Use the callId for the groupContext.
        // The desktop extension requires that this be set.
        const callStartedMessage = {
            callingEventType: CallingEventType.CallStarted,
            groupContext: callInfo.callId,
            callId: callInfo.callId
        };
        this.messagingService.notify(callStartedMessage);
    }

    private async getVSLSToken(): Promise<SkypeTokenInfo> {
        if (this.currentTokenInfo && new Date().getTime() < this.currentTokenInfo.expiresIn - (3600 * 1000)) {
            return this.currentTokenInfo;
        }

        this.currentTokenInfo = await getVSLSTokenFromAuthService(this.trace);
        return this.currentTokenInfo;
    }
}
