import {
    ISessionStateHandler,
    SessionState,
    sessionStateTracker
} from '@vs/liveshare-core';

import { IGuestTerminalController, GuestTerminalParameters, guestTerminalControllerFactory } from './GuestTerminalController';

export class GuestTerminalHandler implements ISessionStateHandler {
    private guestController: IGuestTerminalController;

    constructor(private readonly parameters: GuestTerminalParameters) {
        // Note: in case the terminal handler is constructed during the join command
        if (sessionStateTracker.State === SessionState.JoiningInProgress) {
            this.createGuestController();
        }
    }

    public async handleSessionStateChanged(newState: SessionState, previousState: SessionState): Promise<void> {
        switch (newState) {
            case SessionState.JoiningInProgress:
                // Instantiate a guest controller.
                this.createGuestController();
                break;
            case SessionState.Joined:
                // Activate the guest terminal controller in a guest collaboration session.
                await this.guestController.activate();
                break;
            default:
                if (this.guestController && previousState === SessionState.Joined) {
                    // Disengage the guest controller when leaving a joined collaboration session.
                    await this.guestController.deactivate();
                }
                break;
        }
    }

    public async dispose(): Promise<void> {
        if (this.guestController) {
            await this.guestController.dispose();
        }
    }

    private createGuestController() {
        this.guestController = guestTerminalControllerFactory(this.parameters);
    }
}