import { TAnyFunction } from '../interfaces/TAnyFunction';

/**
 * Function to wrap any function (let say `fun`) with the wrapper that will
 * ensure that the `fun` will be called only once. The wrapper will cache
 * the first return value of the `fun` and return it immediately on any
 * subsequent calls.
 */
export const once = <
    T extends TAnyFunction,
>(
    fun: T,
): (...args: Parameters<T>) => ReturnType<T> => {
    const invocationSymbol = Symbol();
    let result: ReturnType<T> | undefined;

    const onceFunction = (...args: Parameters<T>): ReturnType<T> => {
        if ((fun as any)[invocationSymbol]) {
            return result as ReturnType<T>;
        }

        (fun as any)[invocationSymbol] = true;

        result = fun(...args);

        return result as ReturnType<T>;
    };

    return onceFunction;
};
