import * as vscode from 'vscode';
import { CancellationToken } from 'vscode';
import * as semver from 'semver';
import { TraceSource } from '@vs/vso-logging';
import { NotificationUtil } from '@vs/vscode-command-framework';
import { IProgressNotifierUtil, IProgressNotifierUtilOptions, ProgressNotifierTask } from '../abstractions/IProgressNotifier';

import { vsls } from '@vs/vsls-contracts';
import { SessionState, SessionStateChangedEventArgs } from '../SessionTypes';
import { sessionStateTracker } from '../SessionStateTracker';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { ExtensionUtil } from './ExtensionUtil';
import { IContextUtil } from './ContextUtil';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { localize } from '../localize';

/**
 * Provider that manages progress notifier in the context of a
 * command.
 */
export class ProgressNotifierUtil implements IProgressNotifierUtil {
    private static readonly statusTextGeneratorRegex = /([A-Z]?[^A-Z]*)/g;
    private static correlationIndex = 0;

    constructor(
        private contextUtil: IContextUtil,
        private workspaceService: vsls.WorkspaceService,
        private trace: TraceSource) {
    }

    public async create<T>(
        options: IProgressNotifierUtilOptions,
        commandCancellationToken: CancellationToken,
        task: ProgressNotifierTask<T>): Promise<T> {
            
        const index = ProgressNotifierUtil.correlationIndex++;

        this.trace.info(`Progress notifier opened: ${index}.`);

        const location = semver.gte(semver.coerce(vscode.version), '1.22.0')
            ? vscode.ProgressLocation.Notification
            : vscode.ProgressLocation.Window;
        
        return await NotificationUtil.withProgress(
            { title: localize('notification.ProgressNotifiers').replace('$(options.title)', options.title), cancellable: true, location } as any,
            async (progress: vscode.Progress<{ message: string }>, progressUIcancellationToken: vscode.CancellationToken) => {
                const stateCallback = (e: SessionStateChangedEventArgs) => {
                    const message = this.generateMessage(SessionState[e.newState]);
                    progress.report({ message });
                };

                const isDiagnosticLogging = Settings.get<boolean>(SettingKeys.diagnosticLogging);

                const statusCallback = (e: { newStatus: string, oldStatus: string }) => {
                    const message = this.generateMessage(e.newStatus);
                    progress.report({ message });
                };

                const stateChangedRegistration = sessionStateTracker.onStateChanged(stateCallback);
                let statusChangedRegistration: vscode.Disposable;
                if (isDiagnosticLogging) {
                    statusChangedRegistration = sessionStateTracker.onStatusChanged(statusCallback);   
                }

                const unsubscribe = () => {
                    if (stateChangedRegistration) stateChangedRegistration.dispose();
                    if (statusChangedRegistration) statusChangedRegistration.dispose();
                };

                if (progressUIcancellationToken) {
                    progressUIcancellationToken.onCancellationRequested(() => {
                        this.trace.info(`Progress notifier cancelled: ${index}.`);
                        unsubscribe();
                    });
                }

                if (commandCancellationToken) {
                    commandCancellationToken.onCancellationRequested(() => {
                        this.trace.info(`Progress notifier cancelled by command: ${index}.`);
                        unsubscribe();
                    });
                }

                this.workspaceService.onProgressUpdated(this.onWorkspaceProgressUpdated.bind(this, progress));
                const result = await task(progressUIcancellationToken);

                this.trace.info(`Progress notifier finished: ${index}.`);
                unsubscribe();

                return result;
            });
    }

    private onWorkspaceProgressUpdated(progress: vscode.Progress<{ message: string }>, e: vsls.WorkspaceProgressEventArgs) {
        switch (e.progress) {
            case vsls.WorkspaceProgress.WaitingForHost: {
                const message = ExtensionUtil.getWaitingForHostProgressUpdateString(e.progress, userAuthStateTracker.userInfo);
                progress.report({ message });
                break;
            }
            case vsls.WorkspaceProgress.OpeningRemoteSession:
            case vsls.WorkspaceProgress.JoiningRemoteSession: {
                progress.report({ message: ExtensionUtil.getProgressUpdateString(e.progress) });
                break;
            }
            default: {}
        }
    }

    private generateMessage(status: string): string {

        if (status === SessionState[SessionState.ExternallySigningIn]) {
            return `Sign in to proceed.`;
        }
        // do not show sharing in progress status as it results in `Sharing workspace: Sharing in Progress` which is redundant,
        // the `Sharing workspace` is already sufficient
        if (status === SessionState[SessionState.SharingInProgress] || status === SessionState[SessionState.JoiningInProgress]) {
            return undefined;
        }

        return status
                ? this.contextUtil.scrubPrefix(status)
                    .match(ProgressNotifierUtil.statusTextGeneratorRegex)
                    .slice(0, -1)
                    .join(' ')
                : status;
    }
}