import * as vscode from 'vscode';
import { IMap } from '../../IMap';
import { EventEmitter } from 'events';

/**
 * Tracks document positions (in VS Code coordinates) across edits.
 */
export class PositionTracker {
    private readonly coEditorSwitchedFileEventName = 'coEditorSwitchedFile';
    private readonly namedPositionsChangedEventName = 'namedPositionsChanged';
    private readonly namedPositionsChanged = new EventEmitter();
    private namedPositions: IMap<TrackedNamedPosition> = {};

    private coEditorSwitchedFileEvent: EventEmitter;
    private clientPositions: IMap<ClientPosition> = {}; // Maps client ID (session number) to the client's position

    constructor() {
        this.coEditorSwitchedFileEvent = new EventEmitter();
    }

    public dispose(): void {
        this.coEditorSwitchedFileEvent.removeAllListeners();
        this.namedPositionsChanged.removeAllListeners();
        this.namedPositions = {};
    }

    public onCoEditorSwitchedFile(handler: (sessionId: number, newFileName: string) => void): void {
        this.coEditorSwitchedFileEvent.addListener(this.coEditorSwitchedFileEventName, handler);
    }

    public onNamedPositionsChanged(handler: (positions: TrackedNamedPosition[]) => void) {
        this.namedPositionsChanged.addListener(this.namedPositionsChangedEventName, handler);
    }

    public setClientPosition(clientId: number, fileName: string, document: vscode.TextDocument, range: vscode.Range, isReversed: boolean): void {
        const previous = this.getClientPosition(clientId);
        const position = PositionTracker.createPosition(fileName, document, range, isReversed);

        this.clientPositions[clientId] = previous || {};
        this.clientPositions[clientId].documentPosition = position;
        if (previous?.notebookPosition?.documentUri.path !== document.uri.path) {
            this.clientPositions[clientId].notebookPosition = undefined;
        }

        if (PositionTracker.isDifferentPosition(previous?.documentPosition, position)) {
            this.coEditorSwitchedFileEvent.emit(this.coEditorSwitchedFileEventName, clientId, fileName);
        }
    }

    public setNotebookPosition(clientId: number, fileName: string, document: vscode.TextDocument, range: vscode.Range, isReversed: boolean, isSelection?: boolean): void {
        const previous = this.getClientPosition(clientId);
        const position = PositionTracker.createNotebookPosition(fileName, document, range );

        this.clientPositions[clientId] = previous || {};
        this.clientPositions[clientId].notebookPosition = position;
        if (previous?.documentPosition?.documentUri.path !== document.uri.path) {
            this.clientPositions[clientId].documentPosition = undefined;
        }
    }

    public setNamedPosition(name: string, fileName: string, document: vscode.TextDocument, range: vscode.Range, isReversed: boolean) {
        const previous = this.getNamedPosition(name);
        const position: TrackedNamedPosition = { name, ...PositionTracker.createPosition(fileName, document, range, isReversed) };
        this.namedPositions[name] = position;

        if (PositionTracker.isDifferentPosition(previous, position)) {
            this.namedPositionsChanged.emit(this.namedPositionsChangedEventName, [position]);
        }
    }

    private static createPosition(fileName: string, document: vscode.TextDocument, range: vscode.Range, isReversed: boolean): TrackedPosition {
        const documentUri = document.uri;
        const startOffset = document.offsetAt(range.start);
        const endOffset = document.offsetAt(range.end);
        return { fileName, documentUri, range, isReversed, startOffset, endOffset};        
    }

    private static createNotebookPosition(fileName: string, document: vscode.TextDocument, range: vscode.Range): TrackedNotebookPosition {
        const documentUri = document.uri;
        return { fileName, documentUri, range };        
    }

    private static isDifferentPosition(previous?: TrackedPosition, current?: TrackedPosition): boolean {
    
        if (previous === current) {
            return false;
        }

        return !previous || !current || 
            previous.fileName !== current.fileName || 
            previous.range.start !== current.range.start || 
            previous.range.end !== current.range.end;
    }

    public onDidChangeTextDocument(fileName: string, e: vscode.TextDocumentChangeEvent): void {
        const document = e.document;

        Object.keys(this.clientPositions).forEach((clientId) => {
            const position = this.clientPositions[clientId]?.documentPosition;

            if (!position) {
                return;
            }

            if (position.fileName === fileName) {
                let translatedPosition = position;
                e.contentChanges.forEach((change) => {
                    translatedPosition = PositionTracker.trackForSingleEdit(translatedPosition, document, change);
                });
                
                this.clientPositions[clientId] = {notebookPosition: this.clientPositions[clientId].notebookPosition, documentPosition: translatedPosition};
            }
        });

        const changedNamedPositions: TrackedNamedPosition[] = [];
        Object.keys(this.namedPositions).forEach((name) => {
            const position = this.namedPositions[name];

            if (!position) {
                return;
            }

            if (position.fileName === fileName) {
                let translatedPosition: TrackedPosition = position;
                e.contentChanges.forEach((change) => {
                    translatedPosition = PositionTracker.trackForSingleEdit(translatedPosition, document, change);
                });

                const newPosition = { name: position.name, ...translatedPosition };
                this.namedPositions[name] = newPosition;

                if (PositionTracker.isDifferentPosition(position, newPosition)) {
                    changedNamedPositions.push(newPosition);
                }
            }
        });        

        if (changedNamedPositions.length) {
            this.namedPositionsChanged.emit(this.namedPositionsChangedEventName, changedNamedPositions);
        }
    }

    public getClientPosition(clientId: number): ClientPosition | undefined {
        return this.clientPositions[clientId];
    }

    public getNamedPosition(name: string): TrackedNamedPosition | undefined {
        return this.namedPositions[name];
    }

    private static trackForSingleEdit(position: TrackedPosition, document: vscode.TextDocument, change: vscode.TextDocumentContentChangeEvent): TrackedPosition {
        const newStartOffset = PositionTracker.translateOffset(position.range.start, position.startOffset, document, change);
        const newEndOffset = PositionTracker.translateOffset(position.range.end, position.endOffset, document, change);
        const newTrackedPosition = Object.assign({}, position);
        const newStartPos = document.positionAt(newStartOffset);
        const newEndPos = document.positionAt(newEndOffset);
        const newRange = new vscode.Range(newStartPos, newEndPos);
        newTrackedPosition.startOffset = newStartOffset;
        newTrackedPosition.endOffset = newEndOffset;
        newTrackedPosition.range = newRange;
        return newTrackedPosition;
    }

    private static translateOffset(pos: vscode.Position, oldOffset: number, document: vscode.TextDocument, change: vscode.TextDocumentContentChangeEvent): number {
        if (change.range.start.isAfter(pos)) {
            // Change is completely after pos: no-op
            return oldOffset;
        }

        if (change.range.end.isBeforeOrEqual(pos)) {
            // Change is completely before or ends on pos: translate by net change length
            const netChangeLength = change.text.length - change.rangeLength;
            const newOffset = oldOffset + netChangeLength;
            return newOffset;
        }

        // Change overlaps or starts on pos: pos moves to the end of the new text
        const changeStartOffset = document.offsetAt(change.range.start);
        const changeEndOffset = changeStartOffset + change.text.length;
        return changeEndOffset;
    }
}

export interface TrackedPosition {
    fileName: string;
    range: vscode.Range;
    isReversed: boolean;
    documentUri: vscode.Uri;
    startOffset: number;
    endOffset: number;
}

export interface TrackedNotebookPosition {
    fileName: string;
    range: vscode.Range;
    documentUri: vscode.Uri;
}

export interface TrackedNamedPosition extends TrackedPosition {
    name: string;
}

export interface ClientPosition {
    documentPosition?: TrackedPosition,    
    notebookPosition?: TrackedNotebookPosition
}