'use strict';

import * as vscode from 'vscode';
import * as url from 'url';
import { PortForwardingTelemetry } from './portForwardingTelemetry';
import { TraceSource } from '@vs/vso-logging';
import { traceSource as trace, launchUrlScraper, Activatable, Disposable, NotificationUtil } from '@vs/vscode-command-framework';
import { IHostServerController } from './IHostServerController';
import {
    Server,
} from '@vs/liveshare-api-contracts';
import {
    PackageInfo,
    Permission,
    hasPermissionForExtension
} from '@vs/liveshare-api';

import {
    IDependencies,
    ISessionContext,
    TelemetryEventNames,
    TelemetryEventOrigin,
    commandBindingDecorator,
    ControllerHelper,
    ExtensionUtil,
    Settings,
    SettingKeys,
    ClipboardUtil,
    Requires
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
interface SharedServerActionPayload {
    [key: string]: any;
    port: number;
}

function isPackageInfo(arg: any): arg is PackageInfo {
    return arg !== undefined && arg.fullName !== undefined;
}

/**
 * Local server url pattern matching following urls:
 * http://localhost:3000/ - commonly used across multiple frameworks
 * https://127.0.0.1:5001/ - ASP.NET
 * http://:8080 - Beego Golang
 * http://0.0.0.0:4000 - Elixir Phoenix
 */
const LOCAL_URL_REGEX = /\b\w{2,20}:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0|:\d{2,5})[\w\-\.\~:\/\?\#[\]\@!\$&\(\)\*\+\,\;\=]*/igm;

/**
 * Internal representation of a local server.
 */
interface ServerModel {
    port: number;
    displayName?: string;
    browseUrl?: string;
    isShared?: boolean;
}

export const hostServerControllerFactory = (deps: IDependencies): IHostServerController => {
    const {
        controllerDecorator,
        telemetryMethodDecorator,
        errorNotificationMethodDecorator
    } = deps.methodDecorators();

    /**
     * Registers and handles VSCode commands controlling shared local server behavior in a shared collaboration session.
     */
    @controllerDecorator
    class HostServerController extends Activatable(Disposable(Object)) implements IHostServerController {
        private readonly trace: TraceSource;
        private readonly registrations: vscode.Disposable[] = [];
        private readonly sessionSubscriptions: vscode.Disposable[] = [];
        private readonly sessionContext: ISessionContext;
        private readonly serverSharingService: vsls.ServerSharingService;
        private readonly serverModels: Map<number, ServerModel> = new Map<number, ServerModel>();
        private dataScraper: vscode.Disposable | undefined;
        private deferredWork: Promise<any> = Promise.resolve(true);

        private static get shouldAutoShareServers() {
            return Settings.get<boolean>(SettingKeys.autoShareServers);
        }

        constructor(dependencies: IDependencies) {
            super();
            this.trace = trace.withName('HostServerController');
            this.sessionContext = dependencies.sessionContext();
            this.serverSharingService = dependencies.serverSharingService();

            if (HostServerController.shouldAutoShareServers) {
                this.deferWork(() => this.launchDataScraper());
            }

            vscode.workspace.onDidChangeConfiguration(e => {
                if (e.affectsConfiguration('liveshare.autoShareServers')) {
                    if (HostServerController.shouldAutoShareServers) {
                        if (!this.dataScraper) {
                            this.deferWork(() => this.launchDataScraper());
                        }
                    } else if (this.dataScraper) {
                        this.dataScraper.dispose();
                        this.dataScraper = undefined;
                    }
                }
            }, this.registrations);

            PortForwardingTelemetry.configure();
        }

        public async dispose(): Promise<void> {
            await this.deferredWork;
            await this.deactivate();
            this.registrations.splice(0).forEach(d => d.dispose());
            if (this.dataScraper) {
                this.dataScraper.dispose();
            }
            await super.dispose();
        }

        public async activate(): Promise<boolean> {
            if (this.isActivated) {
                return true;
            }

            this.sessionSubscriptions.push(
                this.serverSharingService.onSharingStarted((e: vsls.ServerSharingStartedEventArgs) => {
                    const server = e.server;
                    this.serverModels.set(server.sourcePort, {
                        port: server.sourcePort, displayName: server.sessionName, browseUrl: server.browseUrl, isShared: true
                    });
                    this.deferWork(() => this.checkForSharedServers());
                }),
                this.serverSharingService.onSharingStopped((e: vsls.ServerSharingStoppedEventArgs) => {
                    const serverModel = this.serverModels.get(e.server.sourcePort);
                    if (serverModel) {
                        serverModel.isShared = false;
                    }
                    this.deferWork(() => this.checkForSharedServers());
                }),
            );

            ControllerHelper.register(this, this.sessionSubscriptions);

            if (HostServerController.shouldAutoShareServers) {
                const promises = [...this.serverModels.entries()].map(entry => {
                    const [port, serverModel] = entry;
                    return this.startSharingServer(port, serverModel.displayName, serverModel.browseUrl);
                });
                this.deferWork(() => Promise.all(promises));
            }

            return await super.activate();
        }

        public async deactivate(): Promise<void> {
            await this.deferredWork;
            const removed = this.sessionSubscriptions.splice(0);
            removed.forEach(d => d.dispose());

            this.serverModels.clear();
            return super.deactivate();
        }

        private deferWork(work: () => Promise<any>) {
            this.deferredWork = this.deferredWork
                .then(work)
                .catch(reason => {
                    this.trace.error(reason.message);
                });
        }

        private async launchDataScraper() {
            if (!this.dataScraper) {
                try {
                    this.dataScraper = await launchUrlScraper((serverModel: ServerModel) => {
                        const allowedPorts = [
                            3000,
                            8080,
                            4200,
                            80,
                            5000,
                            8000,
                            5500,
                            3001,
                            8081,
                            4000,
                            9000,
                            8888,
                            443,
                            5001,
                            8082,
                            9090,
                            7071,
                        ];

                        if (!this.serverModels.has(serverModel.port)) {
                            // if this port is in the list of allowed ports
                            if (allowedPorts.includes(serverModel.port)) {
                                // add the new server model to the internal cache
                                this.serverModels.set(serverModel.port, serverModel);
                                // start sharing only when in active collaboration session
                                if (this.isActivated) {
                                    this.deferWork(() => this.startSharingServer(serverModel.port, serverModel.displayName, serverModel.browseUrl));
                                }
                            }
                        }
                        PortForwardingTelemetry.autoDetectServer(serverModel.port, serverModel.browseUrl);
                    });
                } catch (reason) {
                    this.trace.warning(reason.message);
                }
            }
        }

        private async checkForSharedServers(): Promise<void> {
            try {
                const sharedServers: vsls.SharedServer[] = await this.serverSharingService.getSharedServersAsync();
                this.sessionContext.hasServersShared = sharedServers.length > 0;
            } catch (e) {
                trace.error('Checking for shared servers failed: ' + e);
            }
        }

        @errorNotificationMethodDecorator('Sharing Server', TelemetryEventNames.SHARE_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.SHARE_SERVER, TelemetryEventNames.SHARE_SERVER_FAULT, 'ShareServer')
        @commandBindingDecorator('liveshare.shareServer')
        @commandBindingDecorator('liveshare.fileTreeExplorer.shareServer')
        @commandBindingDecorator('liveshare.activityBar.shareServer')
        private async shareServer(origin?: TelemetryEventOrigin | PackageInfo, server?: Server): Promise<void> {
            const sharedServers = await this.serverSharingService.getSharedServersAsync();
            const sharedPorts = sharedServers.map(x => x.sourcePort);

            if (isPackageInfo(origin)) {
                // Command issued by a 3rd party extension via the extensibility API
                const { port, displayName, browseUrl } = Requires.NotNullOrUndefined(server, 'server');
                Requires.Argument(!isNaN(port) && Number.isInteger(port) && port > 0 && port <= 65535, 'port', 'The port number must be an integer in range 1 - 65535');
                if (sharedPorts.includes(port)) {
                    // ignore if already shared
                    return;
                }

                let shareServerRequestAllowed: boolean;

                // If the end-user has enabled auto-shared servers, and the requesting
                // extension has permission to automatically share a server, then allow it.
                if (HostServerController.shouldAutoShareServers &&
                    hasPermissionForExtension(origin, Permission.autoShareServers)) {
                    shareServerRequestAllowed = true;
                } else {
                    // This request is coming from an unknown extension and/or the
                    // user has disabled auto-sharing servers, so request permission.
                    const friendlyOrigin = origin.displayName || origin.name;
                    const allowButton = { id: 1, title: 'Allow' };
                    const result = await NotificationUtil.showInformationMessage(
                        `${friendlyOrigin} would like to share port ${port}.`, false, {},
                        allowButton);

                    shareServerRequestAllowed = result && result.id === allowButton.id;
                }

                if (shareServerRequestAllowed) {
                    await this.serverSharingService.startSharingAsync(port, displayName, browseUrl);
                }
            } else {
                // Interactive flow triggered by a user
                const userInputValue = await NotificationUtil.showInputBox({
                    prompt: 'Enter the TCP port or server URL to share with guests.',
                    ignoreFocusOut: true,
                    validateInput: validateUserInput,
                });

                if (!userInputValue) {
                    return;
                }

                let port: number;
                let browseUrl: string;

                const urlMatches = userInputValue.match(LOCAL_URL_REGEX);
                if (urlMatches && urlMatches[0]) {
                    const localUrl = url.parse(urlMatches[0]);
                    port = parseInt(localUrl.port, 10) || 80;
                    browseUrl = url.format(localUrl);
                } else {
                    port = parseFloat(userInputValue);
                }

                const sessionName = await NotificationUtil.showInputBox({
                    value: `localhost:${port}`,
                    prompt: '[Optional] Provide a display name for the shared server.',
                    ignoreFocusOut: true,
                });

                await this.startSharingServer(port, sessionName || `localhost:${port}`, browseUrl);
                PortForwardingTelemetry.shareServer(port, origin);
            }

            function validateUserInput(value: string | number): string {
                if (!value) {
                    return null;
                }

                const port: number = (typeof value === 'number') ? value : parseFloat(value);
                if (!isNaN(port) && Number.isInteger(port)) {
                    if (port <= 0 || port > 65535) {
                        return 'The port number must be an integer in range 1 - 65535';
                    }

                    const s: vsls.SharedServer = sharedServers.find(x => x.sourcePort === port);
                    if (s) {
                        return `Port ${port} is already being shared${s.sessionName === `localhost:${s.sourcePort}` ? '' : ` as '${s.sessionName}'`}.`;
                    }

                    return null;
                }

                if (typeof value === 'string') {
                    const urlMatches = value.match(LOCAL_URL_REGEX);
                    if (urlMatches && urlMatches[0] && urlMatches[0] === value) {
                        const localUrl = url.parse(urlMatches[0]);
                        if (localUrl) {
                            return null;
                        }
                    }

                    return 'The specified value must be a valid TCP port or server URL.';
                }

                return null;
            }
        }

        private async startSharingServer(port: number, sessionName: string, browseUrl?: string): Promise<vsls.SharedServer> {
            const sharedServer = await this.serverSharingService.startSharingAsync(port, sessionName, browseUrl);
            const asSessionName = sharedServer.sessionName === `localhost:${port}` ? '' : ` as '${sharedServer.sessionName}'`;
            NotificationUtil.showInformationMessage(`Shared port ${port}${asSessionName}.`, true, { modal: false });
            return sharedServer;
        }

        @errorNotificationMethodDecorator('Unsharing Server', TelemetryEventNames.UNSHARE_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.UNSHARE_SERVER, TelemetryEventNames.UNSHARE_SERVER_FAULT, 'UnshareServer')
        @commandBindingDecorator('liveshare.unshareServer')
        private async unshareServer(origin?: TelemetryEventOrigin | PackageInfo, server?: Server): Promise<void> {
            const sharedServers = await this.serverSharingService.getSharedServersAsync();
            const getServerName = (s: vsls.SharedServer) => `localhost:${s.sourcePort}` + (s.sessionName === `localhost:${s.sourcePort}` ? '' : ` shared as '${s.sessionName}'.`);
            let sharedServer: vsls.SharedServer;

            if (isPackageInfo(origin)) {
                Requires.NotNullOrUndefined(server, 'server');
                sharedServer = sharedServers.find(x => x.sourcePort === server.port);
            } else {
                if (sharedServers.length === 0) {
                    await NotificationUtil.showInformationMessage('No ports are currently shared.', false, { modal: false });
                    return;
                }

                if (sharedServers.length === 1) {
                    sharedServer = sharedServers[0];
                } else {
                    const items: string[] = sharedServers.map(getServerName);
                    items.unshift('<All Shared Ports>');
                    const selection: string = await NotificationUtil.showQuickPick(items, { placeHolder: 'Pick the port to stop sharing.' });
                    if (!selection) {
                        return;
                    }

                    const index = items.indexOf(selection);
                    if (index < 0) {
                        return;
                    }

                    sharedServer = index > 0 ? sharedServers[index - 1] : null;
                }
            }

            if (sharedServer) {
                await this.serverSharingService.stopSharingAsync(sharedServer.sourcePort);
                PortForwardingTelemetry.unshareServer(sharedServer.sourcePort, <TelemetryEventOrigin>origin);
                await NotificationUtil.showInformationMessage(`Stopped sharing port ${sharedServer.sourcePort}.`, true, { modal: false });
            } else if (typeof sharedServer !== 'undefined') {
                for (sharedServer of sharedServers) {
                    await this.serverSharingService.stopSharingAsync(sharedServer.sourcePort);
                    PortForwardingTelemetry.unshareServer(sharedServer.sourcePort, <TelemetryEventOrigin>origin);
                }

                await NotificationUtil.showInformationMessage('Stopped sharing all ports.', false, { modal: false });
            }
        }

        @errorNotificationMethodDecorator('Unsharing Server', TelemetryEventNames.UNSHARE_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.UNSHARE_SERVER, TelemetryEventNames.UNSHARE_SERVER_FAULT, 'UnshareServer')
        @commandBindingDecorator('liveshare.fileTreeExplorer.unshareServer')
        @commandBindingDecorator('liveshare.activityBar.unshareServer')
        private async unshareServerBySourcePort(item: SharedServerActionPayload): Promise<void> {
            if (!item || (item.port == null)) {
                return;
            }

            await this.serverSharingService.stopSharingAsync(item.port);
            await NotificationUtil.showInformationMessage(`Stopped sharing port ${item.port}.`, true);
        }

        @errorNotificationMethodDecorator('Opening Server in Browser', TelemetryEventNames.BROWSE_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.BROWSE_SERVER, TelemetryEventNames.BROWSE_SERVER_FAULT, 'OpenServerInBrowser')
        @commandBindingDecorator('liveshare.fileTreeExplorer.openServerInBrowser')
        @commandBindingDecorator('liveshare.activityBar.openServerInBrowser')
        private async openSharedServerInBrowser(item: SharedServerActionPayload): Promise<void> {
            if (!item || (item.port == null)) {
                return;
            }

            const sharedServers = await this.serverSharingService.getSharedServersAsync();
            const sharedServer = sharedServers.find(x => x.sourcePort === item.port);
            if (sharedServer) {
                const browseUrl = sharedServer.browseUrl || `http://localhost:${sharedServer.sourcePort}`;
                ExtensionUtil.openBrowser(browseUrl);
            }
        }

        @errorNotificationMethodDecorator('Copying Server URL', TelemetryEventNames.COPY_URL_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.COPY_URL_SERVER, TelemetryEventNames.COPY_URL_SERVER_FAULT, 'CopyServerURL')
        @commandBindingDecorator('liveshare.fileTreeExplorer.copyServerURL')
        @commandBindingDecorator('liveshare.activityBar.copyServerURL')
        private async copySharedServerURL(item: SharedServerActionPayload): Promise<void> {
            if (!item || (item.port == null)) {
                return;
            }

            const sharedServers = await this.serverSharingService.getSharedServersAsync();
            const sharedServer = sharedServers.find(x => x.sourcePort === item.port);
            if (sharedServer) {
                const text = sharedServer.browseUrl || `http://localhost:${sharedServer.sourcePort}`;
                if (await new ClipboardUtil().copyToClipboardAsync(text)) {
                    await NotificationUtil.showInformationMessage('The server URL was copied to the clipboard.', false);
                } else {
                    await NotificationUtil.showInputBox({ value: text });
                }
            }
        }

        @errorNotificationMethodDecorator('Listing Servers', TelemetryEventNames.LIST_SERVERS_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.LIST_SERVERS, TelemetryEventNames.LIST_SERVERS_FAULT, 'listServers')
        @commandBindingDecorator('liveshare.listServers')
        private async listSharedPorts(origin?: TelemetryEventOrigin): Promise<void> {
            PortForwardingTelemetry.listSharedLocalServers(origin);

            const sharedServers = await this.serverSharingService.getSharedServersAsync();

            if (sharedServers.length === 0) {
                await NotificationUtil.showInformationMessage('No ports are currently shared.', false, { modal: false });
                return;
            }

            const items: string[] = sharedServers.map((s) => `Port ${s.sourcePort}` + (s.sessionName === `localhost:${s.sourcePort}` ? '' : ` shared as '${s.sessionName}'`));
            await NotificationUtil.showQuickPick(items, { placeHolder: 'The following ports are shared.' });
        }
    }

    return new HostServerController(deps);
};
