import * as net from 'net';

import { getPipePath } from './getPipePath';

export async function startSocketSession(socketFactory: (listener: () => void) => net.Socket): Promise<net.Socket> {
    let socket: net.Socket;
    const tcpConnect =  new Promise<void>((resolve, reject) => {
        let connected = false;
        socket = socketFactory(() => {
            resolve();
            connected = true;
        });
        
        socket.on('close', () => {
            if (!connected) {
                reject(new Error('connection closed'));
            }
        });
        socket.on('error', error => {
            if (!connected) {
                reject(error);
            }
        });
    });

    await tcpConnect;
    return socket!;
}

export function startSocketSessionOnPort(port: number): Promise<net.Socket> {
    return startSocketSession((listener) => net.createConnection(port, '127.0.0.1',listener));
}

export function startSocketSessionOnPipe(pipe: string, isRawPipe?: boolean): Promise<net.Socket> {
    return startSocketSession((listener) => net.createConnection(isRawPipe ? pipe : getPipePath(pipe),listener));
}