import { assertDefined, TIME_SECOND_MS } from '@vs/vscs-utils';
import { vsls } from '@vs/vsls-contracts';

import { IWorkspaceClient, ConnectedState } from '@vs/vso-workspace-core';
import { WorkspaceClient } from '@vs/vso-workspace-client';
import { Performance } from '@vs/vscs-performance';
import { ILogger } from '@vs/vso-logging';

import { ILiveShareConnectionOptions } from '@vs/vso-workspace-core';
import { ILiveShareConnection } from '../interfaces/ILiveShareConnection';
import { TConnectionTypes } from '../interfaces/TConnectionTypes';
import { ConnectionError } from '../errors/ConnectionError';
import { Connection } from './Connection';
import { PerformanceEventIds } from '../performance/PerformanceEventIds';
import { errorToConnectionError } from '../utils/errorToConnectionError';
import { ServiceInfo } from '@vs/vso-rpc';

/**
 * Class to connect to LiveShare Session and create basic RPC services.
 */
export class LiveShareConnection<
    TOptions extends ILiveShareConnectionOptions = ILiveShareConnectionOptions
> extends Connection implements ILiveShareConnection<TOptions> {
    constructor(
        trace: ILogger,
        protected readonly performance: Performance,
        public readonly options: TOptions
    ) {
        super(trace.createChild('liveshare'), performance);
    }

    /**
     * Get connection `id` from the connection `options`.
     */
    public getId(options: TOptions) {
        const { workspaceId } = options;

        return workspaceId;
    }

    public get type() {
        return TConnectionTypes.MainThread;
    }

    /**
     * LiveShare WorkspaceClient.
     */
    public get workspaceClient(): IWorkspaceClient {
        assertDefined(this.workspaceClientReference, 'No `WorkspaceClient` found.');

        return this.workspaceClientReference;
    }

    /**
     * Method to get RPC service proxy client.
     */
    public getRpcService<T>(rpcServiceContract: ServiceInfo<T>): T {
        return this.workspaceClient.getServiceProxy<T>(rpcServiceContract);
    }

    public dispose(reason?: string) {
        super.dispose(reason);

        this.workspaceClientReference = undefined;
        this.workspaceSessionInfoReference = undefined;

        return this;
    }

    public get workspaceSessionInfo(): vsls.WorkspaceSessionInfo | undefined {
        return this.workspaceSessionInfoReference;
    }

    /******************************************************
     * Implementation details.
     ******************************************************/

    protected workspaceClientReference?: IWorkspaceClient;
    protected workspaceSessionInfoReference?: vsls.WorkspaceSessionInfo;

    protected async createWorkspaceClient(): Promise<IWorkspaceClient> {
        const workspaceClient = new WorkspaceClient(
            this.trace.createChild('WorkspaceClient'),
            undefined,
            {
                enabled: true,
                retryTimeout: 0.25 * TIME_SECOND_MS,
                maxTimeReconnect: 10 * TIME_SECOND_MS,
            }
        );

        return workspaceClient;
    }

    protected setWorkspaceSessionInfo(workspaceSessionInfo: vsls.WorkspaceSessionInfo) {
        this.workspaceSessionInfoReference = workspaceSessionInfo;
    }

    protected async createConnection(): Promise<this> {
        try {
            this.initializeConnection();

            this.trace.info('creating workspace client', this.options);

            const workspaceClient = await this.createWorkspaceClient();

            this.addToDisposables({
                dispose: () => {
                    workspaceClient.dispose('Disposed from LiveShareConnection');
                },
            });

            const workspaceSessionInfo = await this.performance.measure(
                {
                    id: PerformanceEventIds.LiveshareJoinWorkspace,
                    name: 'join LiveShare session',
                },
                async () => {
                    return await workspaceClient.join({
                        ...this.options,
                        performance: this.performance.createGroup(
                            `${this.trace.name}:${this.options.workspaceId}`
                        ),
                        checkConnectionOptions: {
                            enabled: true,
                        },
                    });
                }
            );

            this.workspaceClientReference = workspaceClient;
            this.setWorkspaceSessionInfo(workspaceSessionInfo);

            this.trace.info(`LS session joined and authenticated`);

            await this.performance.measure(
                {
                    name: 'create workspace service',
                },
                async () => {
                    const workspaceService = workspaceClient.getServiceProxy(vsls.WorkspaceService);

                    assertDefined(workspaceService, 'WorkspaceService not set.');

                    await workspaceClient.rpcClient.onClose(() => {
                        this.onConnectionChangedHandler(
                            'disconnected',
                            new ConnectionError('RPC client closed.')
                        );
                    });

                    this.addToDisposables(
                        workspaceService.onConnectionStatusChanged(
                            (event: vsls.WorkspaceConnectionStatusChangedEventArgs) => {
                                if (
                                    event.connectionStatus ===
                                    vsls.WorkspaceConnectionStatus.Disconnected
                                ) {
                                    this.onConnectionChangedHandler(
                                        'disconnected',
                                        new ConnectionError(
                                            `Workspace service disconnected with status: "${event.disconnectedReason}".`
                                        )
                                    );
                                }
                            }
                        )
                    );
                }
            );

            this.onConnectionChangedHandler('connected');

            // hookup host connection events
            workspaceClient.onHostConnectionChanged((e) => {
                this.trace.info(`host connection changed to "${ConnectedState[e.state]}"`);

                if (e.state === ConnectedState.Reconnecting) {
                    this.initializeConnection();
                } else if (e.state === ConnectedState.Reconnected) {
                    this.onConnectionChangedHandler('connected');
                } else if (e.state === ConnectedState.Closed) {
                    this.onConnectionChangedHandler('disconnected');
                }
            });
            return this;
        } catch (e) {
            this.handleConnectionError(e);
            throw errorToConnectionError(e);
        }
    }
}
