import { TelemetryPropertyNames, TelemetryEventNames } from './TelemetryStrings';
import { ITelemetryFilter } from '@vs/vso-telemetry';
import { NotificationUtil } from '@vs/vscode-command-framework';

/** Telemetry sampling config
 * A map from telemetry event name (excluding 'vsliveshare/' prefix) to the sampling rate.
 * The sampling rate means:
 * 0 - never send the event
 * 1 - always send the event
 * Any positive number (n) - send event 1 out of n times randomly. E.g. 2 - send every other event; 10 - send every 10th event.
 *
 * To count actual occurrencies of a sampled event, use a Kusto query similar to below:
 *   extend sampleRate = iif(isempty((Measures["vsliveshare.samplerate"]), 1, toint(Measures["vsliveshare.samplerate"]))
 *   summarize totalEvents = sum(sampleRate)
 */
export interface ISamplingConfig {
    [eventName: string]: number;
}

export class SamplingFilter implements ITelemetryFilter {
    public constructor(private readonly samplingConfig: ISamplingConfig) {
    }

    public shouldSend(eventName: string, properties: { [key: string]: string; }, measures: { [key: string]: number; }): boolean {
        if (!eventName) {
            return true;
        }

        // Check if sampling is enabled for this event
        const sampleRate = this.samplingConfig[eventName];
        if (typeof sampleRate === 'number' && !isNaN(sampleRate)) {
            if (sampleRate === 0 || Math.random() * sampleRate > 1) {
                // The event is disabled (sampleRate is 0) or sampled out
                return false;
            }

            // Include into the sample - add sample rate measure
            measures[TelemetryPropertyNames.SAMPLE_RATE] = sampleRate;
        }

        return true;
    }
}

export class MissingConversationIdFilter implements ITelemetryFilter {
    public shouldSend(eventName: string, properties: { [key: string]: string; }, measures: { [key: string]: number; }): boolean {
        // tslint:disable-next-line:no-string-literal
        if (eventName === TelemetryEventNames.SHARE_WORKSPACE && properties[TelemetryPropertyNames.EVENT_RESULT] === 'Success' && !properties[TelemetryPropertyNames.CONVERSATION_ID]) {
            NotificationUtil.showErrorMessage('A share happened, but conversationId was not set. Please email mowillia@microsoft.com so she can reproduce this with your steps!');
        }
        // This filter needs to implement shouldSend, but we are not using it to filter telemetry but instead to show a notification.
        // Therefore, continue to send all telemetry that passes through this filter.
        return true;
    }
}
