import { performance } from 'performance-ponyfill';
import { Emitter } from 'vscode-jsonrpc';
import { onlyOnce } from '@vs/vscs-utils';

import {
    IPerformanceBlockSide,
    IPerformanceBlockId,
    IPerformanceBlockBase,
} from './interfaces/IPerformance';
import { IPerformanceBlock } from './interfaces/IPerformanceBlock';

import { IWaterfallNode } from './interfaces/IWaterfallNode';
import { WaterfallNode } from './WaterfallNode';
import {
    PerformanceBlocks,
    TPerformanceMeasureCallbackAsync,
    TPerformanceMeasureCallbackSync,
} from './PerformanceBlocks';

import { IPerformanceBlockIdWithMeasure } from './interfaces/IPerformanceBlockIdWithMeasure';
import { IOnAnyEventArgument } from './interfaces/IOnAnyEventArgument';

/**
 * Constructable of T.
 */
export declare type TConstructable<T> = new (...args: any[]) => T;

/**
 * Main performance measurement class. Meant do be used recusively,
 * e.g. every `createGroup` mathod call will return the instance of
 * the same class which is linked to the parent. This allows to create
 * callstack-like performance trees or waterfalls.
 */
export class Performance {
    private static groupCount = 0;
    private readonly blocks: PerformanceBlocks;
    protected readonly groups: Performance[] = [];

    private readonly onAnyEventEmitter = new Emitter<IOnAnyEventArgument>();
    public readonly onAnyEvent = this.onAnyEventEmitter.event;

    constructor(
        public readonly name: string,
        public readonly groupId: string | number,
        public readonly pathString: string = 'start'
    ) {
        this.blocks = new PerformanceBlocks(pathString);

        performance.mark(pathString);

        // set self as "main" performance initialy
        this.mainPerformanceReference = this;

        this.blocks.onAnyEvent((e) => {
            this.onAnyEventEmitter.fire(e);
        });
    }

    private mainPerformanceReference?: Performance;

    public setMainPerformance(performance: Performance) {
        this.mainPerformanceReference = performance;
    }

    public get main(): Performance {
        if (!this.mainPerformanceReference) {
            throw new Error('No main performance found.');
        }

        return this.mainPerformanceReference;
    }

    /**
     * Create the child subgroup of the current group.
     * All the performance groups must have the reference to the top-level performance
     * class, since searching for any of the group/event ids should be possible from any
     * of the performance groups.
     */
    public createGroup = (
        groupName: string,
        groupdId: string | number = Performance.groupCount++
    ) => {
        const pathString = `${this.pathString}.${groupName}.${this.groupId}`;

        const newGroup = new Performance(groupName, groupdId, pathString);

        newGroup.setMainPerformance(this.main);

        newGroup.onAnyEvent((e) => {
            this.onAnyEventEmitter.fire(e);
        });

        this.groups.push(newGroup);

        return newGroup;
    };

    /**
     * Marks `start` or `end` point of a code block that need to be measured
     * in between. see `blocks.markBlock` method note for man example.
     */
    public markBlock = (blockOptions: IPerformanceBlockSide) => {
        this.blocks.markBlock(blockOptions);

        return this;
    };

    /**
     * Marks `start` point of a code block that need to be measured
     * in between. see `blocks.markBlock` method note for man example.
     */
    public markBlockStart = (
        blockOptions: IPerformanceBlockBase,
        ignoreExistingBlock = false,
    ) => {
        try {
            this.blocks.markBlockStart(blockOptions);
        } catch (e) {
            if (!ignoreExistingBlock) {
                throw e;
            }
        }

        return this;
    };

    /**
     * Marks `end` point of a code block that need to be measured
     * in between. see `blocks.markBlock` method note for man example.
     */
    public markBlockEnd = (
        blockOptions: IPerformanceBlockBase,
        ignoreExistingBlock = false,
    ) => {
        try {
            this.blocks.markBlockEnd(blockOptions);
        } catch (e) {
            if (!ignoreExistingBlock) {
                throw e;
            }
        }

        return this;
    };

    /**
     * Convenience method for the `markBlock` method. Instead of calling
     * the `markBlock` twice, the `measure` can wrap the code block of interest
     * into an asynchronous function hence be called only once.
     */
    public measure = async <T>(
        options: IPerformanceBlockBase,
        callback: TPerformanceMeasureCallbackAsync<T>,
    ) => {
        return await this.blocks.measure(options, callback);
    };

    /**
     * Sync version of the `measure`.
     */
    public measureSync = <T>(
        options: IPerformanceBlockBase,
        callback: TPerformanceMeasureCallbackSync<T>,
    ) => {
        return this.blocks.measureSync(options, callback);
    };

    /**
     * Get waterfall of all the nested performance blocks, starting from the main
     * "start" root node that is initialized as singleton when app starts.
     */
    public getWaterfall = (): IWaterfallNode => {
        performance.measure(this.pathString, this.pathString);
        const [measure] = performance.getEntriesByName(this.pathString);

        const node = new WaterfallNode(
            this.groupId,
            this.name,
            this.pathString,
            measure,
            this.blocks.measures(),
            this.groups
        );

        return node;
    };

    /**
     * Get a measurement of a specific block by `id`.
     */
    public getBlockMeasure = (
        id: string | number,
        waterfall?: IWaterfallNode
    ,): IWaterfallNode | null => {
        waterfall = waterfall ?? this.main.getWaterfall();

        if (waterfall.id === id) {
            return waterfall;
        }

        for (let group of waterfall.groups) {
            const result = this.getBlockMeasure(id, group);
            if (result) {
                return result;
            }
        }

        return null;
    };

    public getBlock = (id: string | number): IPerformanceBlock | undefined => {
        return this.blocks.getBlock(id);
    };

    /**
     * Subscribe to `start` or `end` events of a block by `id`.
     */
    public onEvent(
        options: IPerformanceBlockId,
        callback: (options: IPerformanceBlockIdWithMeasure, block?: IWaterfallNode) => any,
    ) {
        this.blocks.onEvent(options, (opts: IPerformanceBlockIdWithMeasure) => {
            const { id, type } = opts;

            if (type === 'start') {
                callback(opts);
                return this;
            }

            const node = this.getBlockMeasure(id);
            if (!node) {
                throw new Error(`Cannot find "${id}" block.`);
            }

            callback(opts, node);
        });

        return this;
    }

    /**
     * Subscribe to `start` or `end` events of a block by `id`.
     */
    public onMeasure(
        options: IPerformanceBlockId,
        callback: (options: IPerformanceBlockIdWithMeasure, block?: IWaterfallNode) => any,
    ) {
        this.blocks.onEvent(options, (opts: IPerformanceBlockIdWithMeasure) => {
            const { id, type } = opts;

            if (type === 'start') {
                callback(opts);
                return this;
            }

            const node = this.getBlockMeasure(id);
            if (!node) {
                throw new Error(`Cannot find "${id}" block.`);
            }

            callback(opts, node);
        });

        return this;
    }

    /**
     * Get block `startTime` by block `id` or `null` if block is not found.
     */
    public getBlockStartTime = (id: string | number): number | null => {
        const block = this.main.getBlockMeasure(id);;
        if (!block) {
            return null;
        }

        const { measure } = block;
        return measure.startTime;
    };

    /**
     * Get block `endTime` by block `id` or `null` if block is not found.
     */
    public getBlockEndTime = (id: string | number): number | null => {
        const block = this.main.getBlockMeasure(id);;

        if (!block) {
            return null;
        }

        const { measure } = block;
        return measure.startTime + measure.duration;
    };

    /**
     * Get block `durationTime` by block `id` or `null` if block is not found.
     */
    public getBlockDurationTime = (id: string | number): number | null => {
        const block = this.main.getBlockMeasure(id);;

        if (!block) {
            return null;
        }

        const { measure } = block;
        return measure.duration;
    };
}

/**
 * Function to initialize the main performance singleton class, meant to be
 * called on the app startup.a
 */
export const initializePerformanceInstance = <T extends TConstructable<Performance> = TConstructable<Performance>>(
    groupdId: string,
    PerformanceClass: typeof Performance = Performance,
): InstanceType<T> => {
    const codespacePerformance = new PerformanceClass('start', groupdId);

    codespacePerformance.setMainPerformance(codespacePerformance);

    return codespacePerformance as InstanceType<T>;
};

/**
 * Get or create an instance of Performance for the group ID (default is 'extension:start').
 * Throws an error if group ID is empty or undefined, or performance has already been initialized with a different group ID.
 * 
 * @param groupId Group id, by default it is 'extension:start'
 * @returns Created or existing instance of Performance with the given group ID. 
 */
export const getOrCreatePerformance: (groupId?: string) => Performance = onlyOnce(
    (groupId: string) => initializePerformanceInstance(groupId),
    'extension:start');
