import { vsls } from '@vs/vsls-contracts';
import { settingsProviderInstance } from '@core-abstractions/SettingsProvider';
import { ISettingsProvider } from './abstractions/ISettingsProvider';
import { SettingKeys, FeatureSet } from './SettingKeys';
import * as url from 'url';

export class Settings {
    public static settingsProvider: ISettingsProvider = settingsProviderInstance;

    public static get<T>(key: string): T | undefined {
        return Settings.settingsProvider.get(key);
    }

    public static getMemento<T>(key: string): T | undefined {
        return Settings.settingsProvider.mementoConfig.get(key);
    }

    public static saveMemento(key: string, value: any): Promise<void> {
        return Settings.settingsProvider.mementoConfig.save(key, value);
    }

    public static getUri(key: string, isMemento?: boolean): url.Url | undefined {
        const value = isMemento ? Settings.getMemento<string>(key) : Settings.get<string>(key);
        if (value) {
            return parseUrl(value);
        }
    }

    public static get scheme() {
        return 'vsls';
    }

    public static get isVSLSTeamMember(): boolean {
        return !!Settings.get<string>(SettingKeys.teamStatus);
    }

    public static get isInternalFeatureSet(): boolean {
        return Settings.get<boolean>(SettingKeys.isInternal);
    }

    public static get isInsidersFeatureSet(): boolean {
        const featureSetKey = Settings.get<string>(SettingKeys.featureSet);
        return !!featureSetKey && (<any>FeatureSet)[featureSetKey] === FeatureSet.insiders;
    }

    public static get isNativeAuth(): boolean {
        return !!Settings.get<boolean>(SettingKeys.nativeAuthFlow);
    }

    public static save(key: string, value: any, global: boolean = true): Thenable<void> {
        return Settings.settingsProvider.save(key, value, global);
    }
}

/** Feature flags */
export const featureFlags: vsls.FeatureFlagStore = {
    api: false,
    localUndo: false,
    localRedo: false,
    multiRootWorkspaceVSIDE: false,
    propagateFolderEvents: false,
    agentExtension: false,
    comments: true,
    attemptReconnection: true
};

export function parseUrl(value: string): url.Url | undefined {
    try {
        return url.parse(value);
    } catch (e) {
        return undefined;
    }
}