import * as rpc from 'vscode-jsonrpc';
import { ICommandContext } from '@vs/vscode-command-framework';

import { vsls } from '@vs/vsls-contracts';
import { IAuthenticationFlow } from '../auth/IAuthenticationFlow';
import { IAuthenticationProvider } from '../auth/IAuthenticationProvider';
import { dependencies } from '../Dependencies';
import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { CommandContext } from '../CommandConstants';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { sessionStateTracker } from '../SessionStateTracker';
import { SessionAction } from '../SessionTypes';
import { TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { Settings } from '../Settings';
import { isAnonymousAuthReloadFlagValid } from '../auth/SignInReloadUtils';
import { SettingKeys } from '../SettingKeys';
import { NonBlockingError } from '../abstractions/NonBlockingError';
import { TimeTracker } from '../utils/performance';

export interface IAuthenticationDecoratorOptions {
    statusPostAuth?: SessionAction;
    authAttemptMax?: number;
    validateSessionAction?: (options: any) => boolean;
}

export function authenticationCommandDecorator(options: IAuthenticationDecoratorOptions) {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new AuthenticationCommandDecorator(
            command,
            dependencies.authenticationFlow(),
            dependencies.authenticationProvider(),
            isAnonymousAuthReloadFlagValid,
            options));
}

/**
 * When a command fails do to auth, automatically retry.
 */
export class AuthenticationCommandDecorator implements ICommandDecorator {
    private authAttemptCount: number = 0;

    constructor(
        public next: ICommand<any>,
        private authenticationFlow: IAuthenticationFlow,
        private authenticationProvider: IAuthenticationProvider,
        private isAnonymousAuthReloadFlagValidFunction: () => Promise<boolean>,
        private authDecoratorOptions: IAuthenticationDecoratorOptions) {
            this.authDecoratorOptions = {
                authAttemptMax: 1,
                ...this.authDecoratorOptions
            };
    }

    private async shouldShowAnonymousToast(options: any, context: ICommandContext): Promise<boolean> {
        const isAnonymousLoginAllowed = options.isAllowAnonymous;

        if (isAnonymousLoginAllowed && options.disableAnonymousPrompt) {
            return false;
        }

        // we want to show the sign in options for every anonymous users but not when they reload (as part of the client join or force reload).
        // hence if anonymous auth allowed, the user is anonymous and that's not a reload, ask again even if user authed as anonymous
        let isReload = context.commandText == "liveshare.join.postReload" ?
            true :
            await this.isAnonymousAuthReloadFlagValidFunction();

        const isLegitAnonymousUser = userAuthStateTracker.isCurrentUserAnonymous() && isAnonymousLoginAllowed;
        return isLegitAnonymousUser && !isReload;
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        options = {
            isNativeAuth: Settings.get<boolean>(SettingKeys.nativeAuthFlow),
            ...options
        };

        context.telemetryEvent.addProperty(TelemetryPropertyNames.DEFAULT_SIGN_IN, !!options.isDefaultSignIn);
        
        // if not default sign in, wait on the default sign-in to complete
        if (!options.isDefaultSignIn) {
            await userAuthStateTracker.defaultAuthAttemptCompleteSignal.promise;
        }

        let result: any = undefined;
        try {
            // Check if we are already authenticated
            let isAuthenticated = this.authenticationProvider.isAuthenticated();

            context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_ALLOWS_ANONYMOUS, options.isAllowAnonymous);
            context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_SHOULED_SKIP_ANONYMOUS_PROMPT, options.disableAnonymousPrompt);
            context.telemetryEvent.addMeasure(TelemetryPropertyNames.COMMAND_AUTH_RETRY_COUNT, this.authAttemptCount);
            context.telemetryEvent.addPropertyIfNotExists(TelemetryPropertyNames.COMMAND_STARTED_UNAUTHENTICATED, !isAuthenticated);
            context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_STARTED_BLOCKING_AUTH, false);

            // If we aren't already authenticated, try and load cached credentials
            if (!isAuthenticated) {
                try {
                    isAuthenticated = await TimeTracker.timeIt('attemptAuthenticationCheckFlow', async() => await this.authenticationFlow.attemptAuthenticationCheckFlow(options, context));
                } catch (e) {
                    context.trace.error(`Authentication check error: ${e}`);
                    isAuthenticated = false;
                }

                context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTO_AUTHED_RESULT, isAuthenticated);

                // if default sign in, complete the command
                if (options.isDefaultSignIn) {
                    userAuthStateTracker.completeDefaultAuthAttempt();

                    // if not authenticated, throw to prevent the sessionStateTransitionDecorator to move the login state to `success`
                    if (!isAuthenticated) {
                        throw new NonBlockingError("Authentication check returned false.");
                    }

                    return isAuthenticated;
                }
            }

            // Case 1: Deal with the case where the user has an anon account but is trying to
            //         perform an action that requires a sufficiently privileged account.
            if (!options.isAllowAnonymous && userAuthStateTracker.isCurrentUserAnonymous()) {
                isAuthenticated = false;
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTO_AUTHED_ANONYMOUSLY_BUT_ANONYMOUS_NOT_ALLOWED, true);
            }

            // If cached credentials aren't present or where but aren't sufficiently privileged,
            // attempt anonymous login if supported or failing that, perform normal login.
            const shouldShowAnonymousToast = await this.shouldShowAnonymousToast(options, context);
            if (!isAuthenticated || shouldShowAnonymousToast) {
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_DID_AUTH_FULL, !isAuthenticated);
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_STARTED_BLOCKING_AUTH, true);
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_SHOULD_SHOW_ANONYMOUS_TOAST, shouldShowAnonymousToast);

                let anonymousAuthResult;
                // If command support anonymous usage, try obtaining anonymous token from server
                if (options.isAllowAnonymous) {
                    anonymousAuthResult = await this.authenticationFlow.attemptPromptedUserAnonymousLoginFlow(options, context);
                    context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_BLOCKING_ANONYMOUS_LOGIN_FLOW_RESULT, anonymousAuthResult);
                }

                // If anonymous auth fails or not allowed, provider user with sign-in option
                if (!anonymousAuthResult) {
                    context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_BLOCKING_NON_ANONYMOUS_LOGIN_FLOW_RESULT, false);
                    await this.authenticationFlow.attemptPromptedUserLoginFlow(options, context);
                    context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_BLOCKING_NON_ANONYMOUS_LOGIN_FLOW_RESULT, true);
                }

                // If we haven't thrown before this point we are authenticated
                isAuthenticated = true;
            }
            
            const { cancellationTokenSource } = context;
            if (cancellationTokenSource && cancellationTokenSource.token.isCancellationRequested) {
                return;
            }

            ExtensionUtil.setCommandContext(CommandContext.isAnonymousUser, userAuthStateTracker.isCurrentUserAnonymous());

            // Ensure that we set the state post auth back to something that the
            // core command is happy with.
            if (this.authDecoratorOptions.statusPostAuth !== undefined && this.shouldPerformSessionAction(options)) {
                sessionStateTracker.transition(this.authDecoratorOptions.statusPostAuth);
            }

            // At this point we should be logged in (given that auth fail will throw
            // an error and be caught below) and then call next middleware, might
            // result in a AuthRequired error
            result = await this.next.invoke(options, context);
        } catch (error) {
            // Case 1: We get to the point of calling the service but the service says
            //         we aren't currently authed
            let httpException = error as rpc.ResponseError<{}>;
            if (httpException.code === vsls.ErrorCodes.UnauthorizedHttpStatusCode) {

                // Case 1.1: We have retries left and we should try going around again.
                if (this.authAttemptCount++ < this.authDecoratorOptions.authAttemptMax) {
                    context.trace.info(`AuthRetry: About to retry, attempt ${this.authAttemptCount}.`);

                    context.telemetryEvent.addProperty(TelemetryPropertyNames.SIGN_IN_RETRIES, this.authAttemptCount);

                    // Clear cache for next call around.
                    await this.authenticationProvider.clearCache();

                    // Invoke this auth middleware again with context set to clear
                    // out any stored/cache auth info.
                    result = await this.invoke(options, context);

                // Case 1.2: We have no more retries left and we are simply bubbling up
                //           auth error the agent sent us.
                } else {
                    context.trace.info('AuthRetry: No authentication fail retries left.');

                    throw error;
                }

            // Case 2: They tried signing in and the a valid user profile wasn't returned or
            //         that process threw an exception.
            // Case 3: Something else flower in the invoke chain threw an unrelated auth error.
            } else {
                throw error;
            }
        }

        return result;
    }

    private shouldPerformSessionAction(options: any): boolean {
        return !this.authDecoratorOptions.validateSessionAction || this.authDecoratorOptions.validateSessionAction(options);
    }
}
