import * as vscode from 'vscode';

import { getCellId,
        PathManager
 } from '@vs/liveshare-core';

export abstract class notebooksServiceBase {

    protected cellLanguageMap: { [uri: string]: string } = {};
    protected disposables: vscode.Disposable[] = [];
    
    public async dispose() {
        this.disposables.forEach(d => d.dispose());
        this.disposables = [];
    }

    public init() {
        this.disposables.push(vscode.workspace.onDidCloseTextDocument(e => this._onDidCloseTextDocument(e)));
        this.disposables.push(vscode.workspace.onDidOpenTextDocument(e => this._onDidOpenTextDocument(e)));
    }

    protected _onDidCloseTextDocument(e: vscode.TextDocument) {
        if (e.uri.scheme == PathManager.notebookCellScheme) {
            this.cellLanguageMap[e.uri.toString()] = e.languageId;
        }
    }

    public _onDidOpenTextDocument(e: vscode.TextDocument) {

        let cellId: string;
        const cellLanguage = this.cellLanguageMap[e.uri.toString()];
        if (e.uri.scheme === PathManager.notebookCellScheme && cellLanguage !== undefined) {
            if (cellLanguage !== e.languageId) {
                const cell = e.notebook.getCells().find(c => c.document.uri.toString() === e.uri.toString());
                if (cell) {
                    cellId = getCellId(cell);
                }
            }
        }   

        if (cellId !== undefined) {
            this.handleLanguageChange(e.notebook.uri, e.languageId, cellId);
        }
    }

    abstract handleLanguageChange(notebookUri: vscode.Uri, languageId: string, id: string):void;
}