import { vsls } from '@vs/vsls-contracts';

import { ExtensionUtil } from '@vs/liveshare-core';
export class StringUtil {

    public getErrorString(code: vsls.ErrorCodes | string): string {
        return ExtensionUtil.getErrorString(code);
    }

    public getProgressUpdateString(code: vsls.WorkspaceProgress | string): string {
        return ExtensionUtil.getProgressUpdateString(code);
    }
}
