import { TAnyFunction } from "../interfaces/TAnyFunction";

type ArrayElementTypes<T> = T extends any[] ? T[number] : never;
type FunctionWithParametersOfType<T extends TAnyFunction, A> = ArrayElementTypes<Parameters<T>> extends A ? T : never;

type ParametersOrNone<T extends TAnyFunction> = Parameters<T> | [];
type FunctionWithOptionalParameters<T extends TAnyFunction> = T & ( () => ReturnType<T> );

// Compare only arguments of primitive types
type ComparableParameter = string | number | bigint | boolean | null | undefined | symbol;

type FuncWithComparableParameters<T extends TAnyFunction> = FunctionWithParametersOfType<T, ComparableParameter>;    

/** Decorate a synchronous function to cache its result and check that it's always called with the same parameters.
 * The first call to the decorator will invoke the original function, save the parameters and the result if it succeeds. Recursion is supported.
 * The subsequent calls will check if the parameters match and return the saved result.
 * 
 * @param fun - function to decorate. Can only have parameters of primitive type (string | number | bigint | boolean | null | undefined | symbol).
 * @returns a decorating function that calls fun() the first time, caches the result, and returns it next times, comparing the parameters to the first call.
 * @throws Error if on subsequent calls the parameters differ from the first call.
*/
export function onlyOnce<T extends FuncWithComparableParameters<U>, U extends TAnyFunction = T>(fun: T): T;

/** Decorate a synchronous function to cache its result and check that it's always called with the same parameters.
 * The first call to the decorator will invoke the original function, and save the parameters and the result if it succeeds. Recursion is supported.
 * The subsequent calls will check if the parameters match and return the saved result.
 * 
 * @param fun - function to decorate. Can only have parameters of primitive type (string | number | bigint | boolean | null | undefined | symbol).
 * @param defaultParams - default parameters to use if it's called without any parameters. 
 * @returns a decorating function that calls fun() the first time, caches the result, and returns it next times, comparing the parameters to the first call.
 * @throws Error if on subsequent calls the parameters differ from the first call.
*/
export function onlyOnce<T extends FuncWithComparableParameters<U>, U extends TAnyFunction = T>(fun: T, ...defaultParams: Parameters<T>): FunctionWithOptionalParameters<T>;
export function onlyOnce<T extends FuncWithComparableParameters<U>, U extends TAnyFunction = T>(fun: T, ...defaultParams: ParametersOrNone<T>): FunctionWithOptionalParameters<T> {

    const invocationSymbol = Symbol();
    let recursionCount = 0;
    let firstParams: ParametersOrNone<T>;
    let firstResult: ReturnType<T>;

    return <FunctionWithOptionalParameters<T>> function (...params: ParametersOrNone<T>) {
        if (params.length === 0) {
            params = defaultParams;
        }

        if (!(fun as any)[invocationSymbol]) {
            recursionCount++;
            let result: ReturnType<T>;
            try {
                result = fun(...params);
                if (recursionCount > 1) {
                    return result;
                }
            } finally {
                recursionCount--;
            }

            // Set the flag after we have called the function and got the result to allow recursion for the first invocation
            (fun as any)[invocationSymbol] = true;
            firstParams = params;
            firstResult = result;
        }
        else if (!parametersEqual(firstParams, params)) {
            throw new Error(`Parameters must be the same as in the first call of ${onlyOnce.name}(${fun.name}).`);
        }

        return firstResult;
    };
};

/** Check if two parameter arrays match.
 * 
 * This check only uses === to compare the elements, so they must be of primitive type only.
 * If one array is larger than the other, the extra elements must be all undefined.
 */
function parametersEqual(a1: ComparableParameter[], a2: ComparableParameter[]): boolean {
    if (!Array.isArray(a1) || !Array.isArray(a2)) {
        return false;
    }

    if (a1 === a2) {
        return true;
    }

    const l = Math.min(a1.length, a2.length);
    for (var i = 0; i < l; i++) {
        if (a1[i] !== a2[i]) {
            return false;
        }
    }

    const a = a1.length > l ? a1 : a2;
    for (var i = l; i < a.length; i++) {
        if (a[i] !== undefined) {
            return false;
        }
    }

    return true;
}
