
import * as crypto from 'crypto';
import * as vscode from 'vscode';
import * as jwtDecode from 'jwt-decode';
import * as url from 'url';

import { IAuthStrategy, IToken } from '@vs/vscode-account';
import { IStrategyInfo } from '@vs/vscode-account/src/types/IStrategyInfo';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { LIVESHARE_EXTENSION_ID } from '../constants';
import { auth } from './Authentication';

import { Signal } from '@vs/vscs-utils';

interface ICascadeTokenPayload {
    exp: number;
}
const SECONDS_IN_MINUTE = 60;
const MINUTES_IN_HOUR = 60;
const SECONDS_IN_HOUR = MINUTES_IN_HOUR * SECONDS_IN_MINUTE;
const HOURS_IN_DAYS = 24;
const CASCDE_JWT_MIN_EXPIRATION_TIME_SECONDS = 2 * SECONDS_IN_HOUR;


export abstract class LiveShareStrategyBase implements IAuthStrategy {
    public name = 'LiveShare';
    public publicName = 'Github';

    public endpointUrl = () => {
        const uri = Settings.getUri(SettingKeys.serviceUri);
        return url.format(uri);
    }

    private authRequestIdToStrategyInfoMap = new Map<string, IStrategyInfo>();

    public minExpiration = CASCDE_JWT_MIN_EXPIRATION_TIME_SECONDS;

    private readonly onTokenUpdateEmitter = new vscode.EventEmitter<IToken>();

    public readonly onTokenUpdated = this.onTokenUpdateEmitter.event;

    public signalNewToken(token: IToken) {
        this.onTokenUpdateEmitter.fire(token);
    }

    public getRedirectUri(): Promise<vscode.Uri> {
        return auth.API.getRedirectUri(LIVESHARE_EXTENSION_ID);
    }

    public getSignInUrl() {
        const endpointUrl = this.endpointUrl();
        const signInUrl = `${endpointUrl}auth/identity/github/`;

        return signInUrl;
    }
    
    public getAccessToken = async () => {
        const nonce = crypto
                        .randomBytes(16)
                        .toString('base64')
                        .replace(/[^\w\s]/gi, '');

        const callbackUri = await this.getRedirectUri();

        const params = new URLSearchParams(callbackUri.query);
        const state = params.get('state') || nonce;
        
        const signInUrl = this.getSignInUrl();
        const baseUrl = vscode.Uri.parse(signInUrl);
        const redirectUri = decodeURIComponent(callbackUri.toString());

        const encodedQuery = new URLSearchParams([
            ['redirect', redirectUri],
            ['state', state],
            ['extensionId', state],
            ['nonce', nonce],
        ]);

        const tokenSignal = new Signal<IToken | null>();

        const strategyInfo: IStrategyInfo = {
            strategy: this,
            redirect_uri: redirectUri,
            signal: tokenSignal,
        };

        this.authRequestIdToStrategyInfoMap.set(state, strategyInfo);

        const uri = `${baseUrl}?${encodedQuery.toString()}`;
        

        await vscode.env.openExternal(vscode.Uri.parse(uri));
        return await tokenSignal.promise;
    }

    public async receiveProtocolHandlerCallback(uri: vscode.Uri) {
        const params = new URLSearchParams(uri.query);
        const nonce = params.get('extensionId');

        if (!nonce) {
            return false;
        }

        const decodedNonce = decodeURIComponent(nonce);

        const strategyInfo = this.authRequestIdToStrategyInfoMap.get(decodedNonce);
        if (!strategyInfo) {
            return false;
        }

        const error = params.get('error');
        if (error) {
            strategyInfo.signal.resolve(null);
            return true;
        }

        const userCode = params.get('userCode');
        if (!userCode) {
            strategyInfo.signal.reject(new Error('No code query param found.'));
            return true;
        }

        const token = await this.exchangeAuthorizationCode(userCode);
        strategyInfo.signal.resolve(token);

        return true;
    }

    public exchangeAuthorizationCode = async (authorizationCode: string) => {
        const resultJSON = await auth.API.fetchPost(
            `${this.endpointUrl()}auth/token/`, JSON.stringify({
                'grant_type': 'urn:ietf:params:oauth:grant-type:user_code',
                'user_code': authorizationCode
            }), {
                'Content-Type': 'application/json'
            });

        if (resultJSON.error_description) {
            throw new Error(resultJSON.error_description);
        }

        return this.parseTokenPayloadFromAccessToken(resultJSON.access_token);
    }

    public async refreshToken(refreshToken: string) {
        return this.parseTokenPayloadFromAccessToken(refreshToken);
    }

    public parseTokenPayloadFromAccessToken = (token: string): IToken | null => {
        const jwtToken = jwtDecode<ICascadeTokenPayload>(token);
        const expiresOn = jwtToken.exp * 1000;

        const expiresIn = new Date(expiresOn).getTime() - Date.now();

        if (expiresIn < (this.minExpiration * 1000)) {
            return null;
        }

        return {
            accessToken: token,
            expiresOn,
            tokenType: 'vsls',
            strategy: this
        };
    }
}