'use strict';

import * as vscode from 'vscode';
import { NotebookConstants } from '../contracts/NotebookConstants';

export function findNotebookCell(cellUri: vscode.Uri): vscode.NotebookCell {
    if (!vscode.workspace.notebookDocuments) {
        return undefined;
    }

    for (let nbd of vscode.workspace.notebookDocuments) {
        const cell = nbd.getCells()?.find(c => c.document.uri.path === cellUri.path && c.document.uri.fragment === cellUri.fragment);
        if (cell) {
            return cell;
        }
    }
    return undefined;
}

export function findNotebookCellWithCustomMetadata(notebookUri: vscode.Uri, propertyName: string, value: string): vscode.NotebookCell {
    if (!vscode.workspace.notebookDocuments) {
        return undefined;
    }

    const nbd = vscode.workspace.notebookDocuments.find(nbd => nbd.uri.toString() === notebookUri.toString());
    if (!nbd) {
        return undefined;
    }

    return nbd.getCells()?.find(c => {
        return c.metadata[propertyName] === value;
    });
}

export function findNotebookCellById(notebookUri: vscode.Uri, id: string): vscode.NotebookCell {
    return findNotebookCellWithCustomMetadata(notebookUri, NotebookConstants.cellIdPropertyName, id);
}

// TODO: add notebook cell outputs and execution summary
export function getNotebookCellData(cell: vscode.NotebookCell): vscode.NotebookCellData {
    let cellData = new vscode.NotebookCellData(cell.kind, cell.document.getText(), cell.document.languageId);
    cellData.metadata = cell.metadata;
    return cellData;
}

export function getCellId(cell: { metadata?: NotebookCellMetadata }): string {
    if (!cell?.metadata?.hasOwnProperty(NotebookConstants.cellIdPropertyName)) {
        return undefined;
    }
    return cell.metadata[NotebookConstants.cellIdPropertyName];
}

export function sortCells(cells: { index: number }[]) {
    cells.sort((a, b) => a.index - b.index);
}

export function getNotebookHash(cells: { metadata?: NotebookCellMetadata }[]) {
    // TODO to reduce size, we could hash this string
    return cells.map(c => getCellId(c)).join('');
}

export type NotebookCellMetadata = { [key: string]: any }
