import * as path from 'path';
import { fileAccess } from '@vscode-abstractions/fileAccess';
import { findFilesAsync } from '../util/findFilesAsync';

const zip = require('yazl');

const logFileExtensions = [
    '.log',
    '.blog', // Binary log files generated by the calling extension
];

export class LogZipExporter {
    public static async createLogZipFileAsync(
        zipFilePath: string,
        directoryPath: string,
    ): Promise<void> {
        const logFiles = (
            await findFilesAsync(
                directoryPath,
                directoryPath,
                (file: any) => logFileExtensions.indexOf(path.extname(file)) >= 0,
            )
        ).sort();

        const zipFile = new zip.ZipFile();
        zipFile.outputStream.pipe(fileAccess.createWriteStream(zipFilePath));
        logFiles.forEach((logFile: any) => {
            zipFile.addFile(path.join(directoryPath, logFile), logFile);
        });
        zipFile.end();
    }
}
