import { IStatusBarQuickPickItemsProvider, HandledQuickPickItem, SessionState } from '@vs/liveshare-core';
import { ExtensionContributions } from './contributions';

export class StatusbarQuickPickItemsProvider implements IStatusBarQuickPickItemsProvider {
    public getQuickPickItems(state: SessionState): HandledQuickPickItem[] {
        return ExtensionContributions.getQuickPickItems();
    }
}