import {
    IContactModel
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
function toPresenceSort(presenceStatus: contactProtocol.PresenceStatus): number {
    switch (presenceStatus) {
    case contactProtocol.PresenceStatus.Available:
        return 1;
    case contactProtocol.PresenceStatus.Away:
        return 2;
    case contactProtocol.PresenceStatus.Busy:
        return 3;
    case contactProtocol.PresenceStatus.DoNotDisturb:
        return 4;
    default:
        return 100;
    }
}

/**
 * Compare 2 contact models by first checking the status and then the display name
 * @param c1 
 * @param c2 
 */
export function  defaultCompareContacts(c1: IContactModel, c2: IContactModel) {
    const statusSort1 = toPresenceSort(c1.contact.status);
    const statusSort2 = toPresenceSort(c2.contact.status);
    if (statusSort1 > statusSort2) {
        return 1;
    } else if (statusSort1 < statusSort2) {
        return -1;
    }
 
    if (c1.contact.displayName > c2.contact.displayName) {
        return 1;
    }
 
    if (c1.contact.displayName < c2.contact.displayName) {
        return -1;
    }
 
    return 0;
 }