import { ITokenExchangeService } from './ITokenExchangeService';
import { SupportedAuthProviders as SupportedAuthProvider } from './NativeAuthProvider';
import { Settings } from '../../Settings';
import { SettingKeys } from '../../SettingKeys';
import { TraceSource } from '@vs/vso-logging';
import { default as axios } from 'axios';
import { localize } from '../../localize';

enum Endpoint {
    AuthTokenService,
    AuthTokenServiceAudience
}

export class TokenExchangeService implements ITokenExchangeService {
    private devEnvRegExp = new RegExp('.*\.dev\.liveshare\.vsengsaas\.visualstudio\.com');

    private endpointsByEnvironment: { [env: string]: { [endpoint in Endpoint]: string}} = {
        ['dev']: {
            [Endpoint.AuthTokenService]: 'https://sts.dev.core.vsengsaas.visualstudio.com/api/v1/tokens/exchange',
            [Endpoint.AuthTokenServiceAudience]: 'https://ci.dev.liveshare.vsengsaas.visualstudio.com/'
        },

        ['ppe']: {
            [Endpoint.AuthTokenService]: 'https://sts-ppe.core.vsengsaas.visualstudio.com/api/v1/tokens/exchange',
            [Endpoint.AuthTokenServiceAudience]: 'https://ppe.liveshare.vsengsaas.visualstudio.com/'
        },

        ['prod']: {
            [Endpoint.AuthTokenService]: 'https://sts.online.visualstudio.com/api/v1/tokens/exchange',
            [Endpoint.AuthTokenServiceAudience]: 'https://insiders.liveshare.vsengsaas.visualstudio.com/'
        },
    };

    private currentEndpoints: { [endpoint in Endpoint]: string};

    public constructor(
        private readonly logger: TraceSource
    ) {
        const serviceUri = Settings.get<string>(SettingKeys.serviceUri);

        let environment = undefined;

        if (!serviceUri) {
            logger.info('Service Uri is not set. Default to production');
            environment = 'prod';
        } else {
            environment = this.getEnvironment(serviceUri);
        }

        if (environment === 'unknown') {
            logger.warning(`Can not determine environment for ${serviceUri} service Uri. Default to production`);
            environment = 'prod';
        }

        this.currentEndpoints = this.endpointsByEnvironment[environment];
    }

    public async exchange(provider: SupportedAuthProvider, nativeToken: string): Promise<string> {
        const result = await axios(this.currentEndpoints[Endpoint.AuthTokenService], {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json-patch+json'
            },
            data: JSON.stringify({
                'provider': `${provider}`,
                'token': `${nativeToken}`,
                'audience': `${this.currentEndpoints[Endpoint.AuthTokenServiceAudience]}`,
                'lifetime': '25' // lifetime of a Cascade token measured in days
            }),
            proxy: false, // Disabling axios proxy support allows VS Code proxy settings to take effect.
        });

        const cascadeToken = result.data;

        if (cascadeToken.token) {
            return cascadeToken.token;
        } else {
            switch (cascadeToken.status) {
                case 401: {
                    throw new Error(localize('error.AuthTokenConversionFailed'));
                }
                default: {
                    throw new Error(localize('error.AuthTokenConversionFailedWithCode').replace('${code}', cascadeToken.status));
                }
            }
        }
    }

    private getEnvironment (env: string): 'dev' | 'ppe' | 'prod' | 'unknown' {​
        const envUrl = new URL(env.trim());

        if (this.devEnvRegExp.test(envUrl.hostname)) {
            return 'dev';
        }

        switch (envUrl.hostname) {​
            case 'ppe.liveshare.vsengsaas.visualstudio.com':
                return 'ppe';

            case 'prod.liveshare.vsengsaas.visualstudio.com':
                return 'prod';

            default:
                return 'unknown';
        }​
    }​
}