import { Uri } from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';
import { PlannedSessionTreeViewItem } from '../PlannedSessionsProvider';
import { PlannedSessionsUtils } from '../plannedSessionUtils';

import { 
    SessionAction,
    TelemetryEventNames, 
    TelemetryPropertyNames,
    workspaceSessionInfoTracker,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    authenticationCommandDecorator,
    IAuthenticationDecoratorOptions, IDependencies,
    localize, ICommand
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

export function builder(dependencies: IDependencies):  ICommand<Uri>  {
    return new RenamePlannedSessionCommand(
        dependencies.workspaceService(),
    );
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.Create
};

/**
 * Rename planned session `command` that renames a persistent session
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Rename Planned Session', TelemetryEventNames.RENAME_PLANNED_SESSION_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.RENAME_PLANNED_SESSION, TelemetryEventNames.RENAME_PLANNED_SESSION_FAULT, 'Rename Planned Session', 1)
@telemetryStatusCommandDecorator()
@authenticationCommandDecorator(authOptions)
export class RenamePlannedSessionCommand implements ICommand<Uri>  {
    constructor(
        private workspaceService: vsls.WorkspaceService) {
        }
        
        public async invoke(item: PlannedSessionTreeViewItem, context: ICommandContext): Promise<Uri> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        try {
       
            let workspaceList  = workspaceSessionInfoTracker.plannedWorkspaceList;
            let workspaceId: string;
            let name;
            let index;
            if (item.workspaceInfo === undefined || item.workspaceInfo === null) {
                let workspaceInfo =  await PlannedSessionsUtils.selectPlannedSessionItemFromCommandPaletteAsync(workspaceList);
                workspaceId = workspaceInfo.id; 
                name = await PlannedSessionsUtils.getUsernameFromInputAsync(workspaceInfo.label, cancellationToken);
                index = workspaceSessionInfoTracker.plannedWorkspaceList.indexOf(workspaceInfo);
            } else {
                workspaceId = item.workspaceInfo.id;
                name = await PlannedSessionsUtils.getUsernameFromInputAsync(item.workspaceInfo.label, cancellationToken);
                index = workspaceSessionInfoTracker.plannedWorkspaceList.indexOf(item.workspaceInfo);
            }

            if (workspaceId && name) {
                let newName = await this.workspaceService.renameWorkspaceAsync(workspaceId, name, cancellationToken);
                workspaceSessionInfoTracker.plannedWorkspaceList[index].label = newName;
                workspaceSessionInfoTracker.isPlannedSessionsChanged = true;
                context.telemetryEvent.addProperty(TelemetryPropertyNames.RENAME_PLANNED_SESSION, true);    
            }
           
        } catch (e) {
            context.trace.error(`Failed to rename Planned Session. ${e.message}`);
            throw new Error(localize('error.CannotRenamePlannedSession'));
        }
        return;
    }
}