import { DefaultSettingsProvider } from '../DefaultSettingsProvider';
import * as path from 'path';
import * as os from 'os';
import { traceSource, fileAccess } from '@vs/vscode-command-framework';
import { TraceFormat } from '@vs/vso-logging';

export const settingsProviderInstance = new DefaultSettingsProvider();

export async function readUserSettings(): Promise<{ [key: string]: any }> {
    let userSettingsFilePath = path.join(os.homedir(), '.vs-liveshare-settings.json');
    const defaultUserSettngs = {};

    // Check that the file exists
    try {
        await fileAccess.accessAsync(userSettingsFilePath);
    } catch (e) {
        traceSource.info('Did not find user settings at ' + TraceFormat.formatPath(userSettingsFilePath));
        return defaultUserSettngs
    }
    try {
        return await fileAccess.readJson(userSettingsFilePath);
    } catch (e) {
        traceSource.info('User settings are not valid JSON');
        return defaultUserSettngs;
    }
}