import { errorToObject } from './errorToObject';

/**
 * Create a stringified object that represents an error.
 */
// TODO legomushroom - test this
export const errorToString = (
    error: Error,
    isInternal = false
): string => {
    return JSON.stringify(
        errorToObject(error, isInternal),
        null,
        2,
    );
};
