import {
    Signal,
    assertDefined,
    randomString,
    timeoutPromise,
    TIME_SECOND_MS,
    withMutexByArguments,
} from '@vs/vscs-utils';
import { IWorkspaceClient } from '@vs/vso-workspace-core';
import { Performance } from '@vs/vscs-performance';
import { Event, Emitter } from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';
import { ILogger } from '@vs/vso-logging';
import { IChannel, ServiceInfo } from '@vs/vso-rpc';

import { PerformanceEventIds } from '../performance/PerformanceEventIds';
import { PerformanceGroupIds } from '../performance/PerformanceGroupIds';
import { errorToConnectionError } from '../utils/errorToConnectionError';
import { ConnectionHub } from '../connectionHub/ConnectionHub';
import { LiveShareConnection } from './LiveShareConnection';
import { ConnectionError } from '../errors/ConnectionError';
import { findSourcePort } from '../utils/findSourcePort';
import { Connection } from './Connection';

import { IRemoteVSCodeServerDescription } from '../interfaces/IRemoteVSCodeServerDescription';
import { vscodeServerHostRPCService } from '../interfaces/VSCodeServerHostRPCService';
import { IVSCodeServerHostService } from '../interfaces/IVSCodeServerHostService';
import { IVSCodeConnectionOptions } from '../interfaces/IVSCodeConnectionOptions';
import { ILiveShareConnection } from '../interfaces/ILiveShareConnection';
import { IVSCodeConnection } from '../interfaces/IVSCodeConnection';
import { withHelperDecorator } from '@vs/vscs-utils';
import { getVSCodeServerSessionName } from '../utils/getVSCodeServerSessionName';

export const DEFAULT_FORWARDING_HOST = '127.0.0.1';

/**
 * Class responsible for `vscode` connection - e.g. starting VSCode server and forwarding server
 * port. It consume the `LiveShareConnectionHub` that orchestrates the LiveShare connections.
 */
export class VSCodeConnection<TOptions extends IVSCodeConnectionOptions = IVSCodeConnectionOptions>
    extends Connection
    implements IVSCodeConnection<TOptions> {
    protected readonly onVSCodeServerStartedEmitter = new Emitter<IRemoteVSCodeServerDescription>();
    public readonly onVSCodeServerStarted: Event<IRemoteVSCodeServerDescription> = this
        .onVSCodeServerStartedEmitter.event;

    /**
     * VS Code always requests 2 channels when connecting. The channels will be pre-allocated
     * so that those connections can be setup faster.
     */
    private static readonly channelForecast = 2;
    private readonly forecastChannels: Array<Promise<IChannel | null>> = [];

    constructor(
        trace: ILogger,
        protected performance: Performance,
        public readonly options: TOptions,
        private readonly connectionHubs: [ConnectionHub<typeof LiveShareConnection>]
    ) {
        super(trace.createChild('vscode'), performance);
    }

    /**
     * Get connection `id` from the connection `options`.
     */
    public getId(options: TOptions) {
        const { workspaceId, environmentId, vsCodeQuality, vsCodeCommit } = options;

        return `${workspaceId}_${environmentId}_${vsCodeQuality}_${vsCodeCommit}`;
    }

    /**
     * Method to get LiveShare RPC service client proxy.
     */
    public getRpcService<T>(rpcServiceContract: ServiceInfo<T>): T {
        return this.workspaceClient.getServiceProxy<T>(rpcServiceContract);
    }

    /**
     * WorkspaceClient reference.
     */
    public get workspaceClient(): IWorkspaceClient {
        assertDefined(this.liveshareConnection, 'No LiveShare connection found.');

        const { workspaceClient } = this.liveshareConnection;

        assertDefined(workspaceClient, 'No WorkspaceClient found.');

        return workspaceClient;
    }

    private vscodeServerHostClientReference: IVSCodeServerHostService | null = null;

    /**
     * VSCodeServerHostService reference.
     */
    public get vscodeServerHostClient(): IVSCodeServerHostService {
        assertDefined(this.vscodeServerHostClientReference, 'No VSCodeServerHostClient defined.');

        return this.vscodeServerHostClientReference;
    }

    /**
     * ServerSharing service reference.
     */
    public get serverSharingService() {
        assertDefined(this.serverSharingServiceReference, 'No ServerSharing service found.');

        return this.serverSharingServiceReference;
    }

    /**
     * LiveShareConnection reference.
     */
    public get liveshareConnection(): ILiveShareConnection {
        assertDefined(this.liveshareConnectionReference, 'No LiveShare connection found.');

        return this.liveshareConnectionReference;
    }

    public async createConnection(): Promise<this> {
        const [liveshareConnectionHub] = this.connectionHubs;

        assertDefined(liveshareConnectionHub, 'LiveShareConnectionHub not found.');

        try {
            this.initializeConnection();

            this.trace.info('get LS connection');

            this.liveshareConnectionReference = await this.performance.measure(
                {
                    name: 'liveshare connection',
                },
                async () => {
                    return await liveshareConnectionHub.connectOnce(this.options, {
                        performance: this.performance.createGroup('liveshare connection'),
                    });
                }
            );

            this.liveshareConnectionReference.addToDisposables(this);

            this.addToDisposables(
                this.liveshareConnectionReference.onConnectionChanged((e) => {
                    const { previousStatus, status } = e;

                    this.trace.info(
                        `LiveShareConnection status changed: "${previousStatus}" -> "${status}"`
                    );

                    this.dispose('LiveShareConnection disconnected');
                }),
                this.liveshareConnectionReference.onDispose((e) => {
                    this.trace.info(`LiveShareConnection disposed`);

                    this.dispose('LiveShareConnection disposed');
                })
            );

            const { workspaceClient } = this.liveshareConnectionReference;

            // TODO legomushroom - this is redundant in the "web" connction case?
            await this.getVSCodeSharedServer(workspaceClient);

            // Start opening forecasted channels now, so they will be (almost) ready
            // by the time they are requested.
            for (let i = 0; i < VSCodeConnection.channelForecast; i++) {
                this.forecastChannels.push(this.openChannel(this.performance, false));
            }

            this.onConnectionChangedHandler('connected');

            return this;
        } catch (e) {
            this.handleConnectionError(e);
            throw errorToConnectionError(e);
        }
    }

    /******************************************************
     * Implementation details.
     ******************************************************/

    private sharedServerReference: vsls.SharedServer | null = null;
    protected liveshareConnectionReference: ILiveShareConnection | null = null;

    public get sharedServer(): vsls.SharedServer {
        assertDefined(this.sharedServerReference, 'No SharedServer found.');

        return this.sharedServerReference;
    }

    private serverSharingServiceReference: vsls.ServerSharingService | null = null;

    private async getVSCodeSharedServer(
        workspaceClient: IWorkspaceClient
    ): Promise<vsls.SharedServer> {
        const sharePerformance = this.performance.createGroup(
            'share vscode server',
            PerformanceGroupIds.VSCodeServerStartup
        );

        this.serverSharingServiceReference = workspaceClient.getServiceProxy<
            vsls.ServerSharingService
        >(vsls.ServerSharingService);

        const port = await sharePerformance.measure(
            {
                name: 'start vscode server',
                id: PerformanceEventIds.VSCodeServerStartupServerStart,
            },
            async () => {
                return await this.startVSCodeServer(workspaceClient);
            }
        );

        assertDefined(port, new ConnectionError(`VSCode Server port is "${port}"`));

        this.trace.info(`forwarding the VSCode Server port "${port}".`);

        /**
         * If the sharing of the vscode server port have stopped,
         * dispose the current connection.
         */
        this.addToDisposables(
            this.serverSharingService.onSharingStopped((e: vsls.ServerSharingStoppedEventArgs) => {
                const { server } = e;

                this.trace.verbose('serverSharingService onSharingStopped:', server);
                if (server.sourcePort !== port) {
                    return;
                }

                this.trace.info('serverSharingService closed.', server);

                this.onConnectionChangedHandler(
                    'disconnected',
                    new ConnectionError('Port closed.')
                );
            })
        );

        // TODO legomushroom - not needed?
        // /**
        //  * If the sharing of the vscode server port have changed,
        //  * dispose the current connection.
        //  */
        // this.addToDisposables(
        //     this.serverSharingService.onSharingChanged((e: vsls.ServerSharingChangedEventArgs) => {
        //         const { server } = e;
        //         const { isTCPServerConnectionEstablished } = server;

        //         this.trace.verbose('serverSharingService onSharingChanged:', server);

        //         if (server.sourcePort !== port) {
        //             return;
        //         }

        //         if (isTCPServerConnectionEstablished === false) {
        //             this.onConnectionChangedHandler(
        //                 'disconnected',
        //                 new ConnectionError('Port closed.')
        //             );
        //         }
        //     })
        // );

        this.sharedServerReference = await sharePerformance.measure(
            {
                name: 'share vscode server TCP port',
                id: PerformanceEventIds.VSCodeServerStartupServerTcpPortForwarding,
            },
            async () => {
                const { clientId } = this.options;

                return await this.serverSharingService.startSharingAsync(
                    port,
                    getVSCodeServerSessionName(clientId),
                    ''
                );
            }
        );

        this.trace.info(`VSCode Server port "${port}" forwarded.`);

        return this.sharedServerReference;
    }

    public async getSharedServers(): Promise<vsls.SharedServer[]> {
        try {
            /**
             * There is the current bug that makes RPC calls hang
             * after connection lost/reconnection. Timeout the RPC
             * call and dispose the LiveShare connection if that happens.
             */
            const sharedServers = await timeoutPromise(
                this.serverSharingService.getSharedServersAsync(),
                2 * TIME_SECOND_MS,
                new ConnectionError('Getting shared servers timed out.')
            );

            this.trace.verbose('got shared servers list', sharedServers);

            return sharedServers;
        } catch (e) {
            this.trace.error('getting shared servers failed: ', e);

            this.liveshareConnection.dispose(`disposed by vscode connection: "${e.message}"`);

            throw e;
        }
    }

    protected async startVSCodeServer(workspaceClient: IWorkspaceClient): Promise<number> {
        const { shouldReuseExistingServers = false, clientId } = this.options;

        this.trace.info('starting vscode server..', this.options);

        this.vscodeServerHostClientReference = workspaceClient.getServiceProxy(
            vscodeServerHostRPCService
        );

        /**
         * If the `shouldReuseExistingServers` flag is set,
         * get the existing vscode server.
         */
        if (shouldReuseExistingServers) {
            this.trace.info('checking if existing vscode server can be reused');

            const sharedPorts = await this.getSharedServers();

            this.trace.info('checking already running ports', sharedPorts);

            // take the last shared port
            const vscodeServerPort = sharedPorts.reverse().find((port) => {
                return port.sessionName === getVSCodeServerSessionName(clientId);
            });

            if (vscodeServerPort) {
                this.remotePortReference = vscodeServerPort.sourcePort;

                this.trace.info(`reusing already shared port ${this.remotePortReference}`);

                this.onVSCodeServerStartedEmitter.fire({
                    port: this.remotePort,
                    connectionToken: this.options.vsCodeCommit,
                });

                return this.remotePortReference;
            }
        }

        this.trace.info('vscode started, forwarding the server port');

        this.remotePortReference = await this.vscodeServerHostClient.startRemoteServerAsync({
            ...this.options,
            quality: this.options.vsCodeQuality,
        });

        this.trace.info(`the server port forwarded, port number is ${this.remotePortReference}`);

        this.trace.info('vscode server startup complete');

        this.onVSCodeServerStartedEmitter.fire({
            port: this.remotePort,
            connectionToken: this.options.vsCodeCommit,
        });

        return this.remotePort;
    }

    private remotePortReference: number | null = null;

    /**
     * The remote port that vscode server is running on.
     */
    public get remotePort(): number {
        assertDefined(this.remotePortReference, 'No remote port found.');

        return this.remotePortReference;
    }

    public async startForwardingPort(
        port: number,
        host: string = DEFAULT_FORWARDING_HOST
    ): Promise<vsls.SharedServer> {
        this.trace.info(`start sharing the port "${port}"`);

        const servers: vsls.SharedServer[] = await this.getSharedServers();

        return await this.startForwardingPortCore(servers, port, host);
    }

    public async startForwardingPortWithVisibility(
        port: number,
        isPublic: boolean,
        host: string = DEFAULT_FORWARDING_HOST
    ): Promise<vsls.SharedServer> {
        const servers: vsls.SharedServer[] = await this.getSharedServers();

        const server = await this.startForwardingPortCore(servers, port, host);

        await this.updateForwardedPortCore(server, port, isPublic);

        return server;
    }

    public async updateForwardedPortVisibility(port: number, isPublic: boolean): Promise<this> {
        this.trace.info(`updating visibility of "${port}" to "${isPublic}"`);

        const servers = await this.getSharedServers();
        const currentPort = findSourcePort(servers, port);

        assertDefined(currentPort, `No port "${port}" found.`);

        return await this.updateForwardedPortCore(currentPort, port, isPublic);
    }

    public async updateForwardedPortProtocol(port: number, isHttps: boolean): Promise<this> {
        this.trace.info(`updating protocol of "${port}" to "${isHttps}"`);

        const servers = await this.getSharedServers();
        const currentPort = findSourcePort(servers, port);

        assertDefined(currentPort, `No port "${port}" found.`);

        return await this.updateForwardedPortProtocolCore(currentPort, port, isHttps);
    }

    public async updateForwardedPortPrivacy(
        port: number,
        privacy: vsls.PrivacyEnum
    ): Promise<this> {
        this.trace.info(`updating privacy of "${port}" to "${privacy}"`);

        const servers = await this.getSharedServers();
        const currentPort = findSourcePort(servers, port);

        assertDefined(currentPort, `No port "${port}" found.`);

        return await this.updateForwardedPortPrivacyCore(currentPort, port, privacy);
    }

    public async stopForwardingPort(port: number): Promise<this> {
        const serverSharingClient = this.workspaceClient.getServiceProxy<vsls.ServerSharingService>(
            vsls.ServerSharingService
        );

        await serverSharingClient.stopSharingAsync(port);

        return this;
    }

    public async openChannel(
        performance: Performance = this.performance,
        useForecast: boolean = true
    ): Promise<IChannel | null> {
        if (useForecast) {
            const channelPromise = this.forecastChannels.shift();
            if (channelPromise) {
                return await channelPromise;
            }
        }

        const streamManager = this.getRpcService(vsls.StreamManagerService);

        const streamId = await performance.measure(
            {
                name: 'get stream Id',
                id: randomString(),
            },
            async () => {
                assertDefined(this.sharedServer, 'No SharedServer found.');

                return await streamManager.getStreamAsync(
                    this.sharedServer.streamName,
                    this.sharedServer.streamCondition
                );
            }
        );

        const channel = await performance.measure(
            {
                name: `open streaming channel "${streamId}"`,
            },
            async () => {
                return await this.workspaceClient.openStreamingChannel(streamId);
            }
        );

        return channel || null;
    }

    // TODO legomushroom - move out of the common connection class
    // [ref:0fd69cbff577529b853378fd51839fb7]
    public async sendHandshakeRequest(requestStr: string): Promise<IChannel> {
        const openedChannel = new Signal<IChannel>();
        try {
            this.trace.info('opening ssh channel');

            const channel = await this.openChannel();
            assertDefined(channel, 'Cannot open a channel.');

            const dataReceivedHandler = channel.onDataReceived((e: Buffer) => {
                // the first request on this channel is for the handshake,
                // ignore all other data messages as the consumer will set up its own listeners.
                dataReceivedHandler.dispose();

                this.trace.info(`response: \n${e.toString()}\n`);
                channel.adjustWindow(e.length);

                openedChannel.resolve(channel);
            });

            this.addToDisposables(dataReceivedHandler);

            this.trace.info(`sending the request: \n${requestStr}\n`);

            await channel.send(Buffer.from(requestStr));

            this.trace.info('🔌 connected');
        } catch (err) {
            this.trace.info('failed to send request');
            openedChannel.reject(err);
        }

        return await openedChannel.promise;
    }

    /**
     * Disconnect method is disposing the connection. Will cause the
     * `onConnectionChanged` and `onDispose` events to be fired.
     */
    public async disconnect(reason?: string): Promise<this> {
        this.trace.info(`disconnecting with reason: "${reason}"`);

        if (this.isDisconnected) {
            this.trace.info('already disconnected');
            return this;
        }

        try {
            // stop sharing the vscode server port
            if (this.remotePortReference && this.serverSharingServiceReference) {
                this.trace.info(`stop sharing vscode server port "${this.remotePortReference}"`);

                await this.serverSharingService.stopSharingAsync(this.remotePortReference);
            }

            // shut down the vscode server
            await this.vscodeServerHostClient.shutDownRemoteServerAsync();
        } catch (e) {
            this.trace.warning('error while disconnecting', e);
        } finally {
            this.remotePortReference = null;
            this.vscodeServerHostClientReference = null;
        }

        return super.disconnect(reason);
    }

    @withHelperDecorator(withMutexByArguments, {
        serializeArguments: (
            servers: vsls.SharedServer[],
            port: number,
            host: string = DEFAULT_FORWARDING_HOST
        ) => {
            return `${port}_${host}`;
        },
    })
    private async startForwardingPortCore(
        servers: vsls.SharedServer[],
        port: number,
        host: string = DEFAULT_FORWARDING_HOST
    ): Promise<vsls.SharedServer> {
        const server = findSourcePort(servers, port);
        if (server) {
            this.trace.info(`port ${port} is already forwarded.`);

            return server;
        }

        return await this.serverSharingService.startSharingAsync(port, host, '');
    }

    private async updateForwardedPortCore(
        server: vsls.SharedServer,
        port: number,
        isPublic: boolean
    ): Promise<this> {
        if (server.isPublic === isPublic) {
            this.trace.info(
                `port ${port} visibility is already ${isPublic ? 'public' : 'private'}.`
            );

            return this;
        }

        await this.serverSharingService.updateSharedServerVisibilityAsync(port, isPublic);
        this.trace.info(`port ${port} visibility updated to ${isPublic ? 'public' : 'private'}.`);

        return this;
    }

    private async updateForwardedPortProtocolCore(
        server: vsls.SharedServer,
        port: number,
        isHttps: boolean
    ): Promise<this> {
        if (server.hasTLSHandshakePassed === isHttps) {
            this.trace.info(`port ${port} protocol is already ${isHttps ? 'https' : 'http'}.`);

            return this;
        }

        await this.serverSharingService.updateSharedServerProtocolAsync(port, isHttps);
        this.trace.info(`port ${port} protocol updated to ${isHttps ? 'https' : 'http'}.`);

        return this;
    }

    private async updateForwardedPortPrivacyCore(
        server: vsls.SharedServer,
        port: number,
        privacy: vsls.PrivacyEnum
    ): Promise<this> {
        if (server.privacy === privacy) {
            this.trace.info(`port ${port} privacy is already ${privacy}.`);

            return this;
        }

        await this.serverSharingService.updateSharedServerPrivacyAsync(port, privacy);
        this.trace.info(`port ${port} privacy updated to ${privacy}.`);

        return this;
    }

    /*
     * Stop forwarding vscode server port.
     */
    public dispose(reason?: string) {
        if (this.remotePortReference == null) {
            return super.dispose(reason);
        }

        this.trace.info(`stopping remote port "${this.remotePortReference}"`);

        this.stopForwardingPort(this.remotePortReference).catch((e) => {
            this.trace.warning('failed to stop forwarding vscode server port');
        });

        return super.dispose(reason);
    }
}
