'use strict';

import { RpcServiceHelper, IDependencies } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import * as vscode from 'vscode';
import { Disposable } from 'vscode';
import { ResponseError } from 'vscode-languageclient';
import { ErrorCodes } from 'vscode-jsonrpc';
import { IHostCommentService } from './contracts';
import { commentsSupported } from './commentManager';

class ThreadInfo {
    public commentId = 0;

    constructor(public readonly thread: vsls.CommentThread) {
        if (!thread.comments || !thread.comments.length) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No comments on the comment thread parameter');
        }

        if (thread.comments.length > 1) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Too many comments on the comment thread parameter. Only one is required.');
        }

        const comment = thread.comments[0];
        if (!comment) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'The comment is undefined or missing on the comment thread parameter');
        }

        comment.parentId = -1;

        this.addComment(comment, true /* alreadyOnThread */);
    }

    public get isEmpty(): boolean {
        return this.thread.comments.length === 0;
    }

    public get lastCommentId(): number {
        return this.thread.comments[this.thread.comments.length - 1].commentId;
    }

    public addComment(comment: vsls.Comment, alreadyOnThread?: boolean) {
        if (!comment) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No comment parameter');
        }

        if (!comment.text) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No comment text.');
        }

        if (!comment.participantId) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No participant ID.');
        }

        if (!alreadyOnThread) {
            const parentId = comment.parentId;
            let index: number;
            if (parentId === -1) {
                comment.parentId = this.lastCommentId;
                index = this.thread.comments.length;
            } else {
                // Find the latest sibling if any
                index = this.thread.comments.findIndex(c => c.parentId === parentId);
                if (index >= 0) {
                    // Found a sibling. Find the last one and place this comment after it.
                    while (index < this.thread.comments.length && this.thread.comments[index].parentId === parentId) {
                        index++;
                    }
                } else {
                    // No siblings. Find the parent and place this comment right after it.
                    index = this.thread.comments.findIndex(c => c.commentId === parentId) + 1;
                    if (index === 0) {
                        throw new ResponseError(ErrorCodes.InvalidParams, 'Unknown parent comment ID');
                    }
                }

                this.thread.comments.splice(index, 0, comment);
            }
        }

        const date = new Date();
        comment.threadId = this.thread.threadId;
        comment.commentId = this.commentId++;
        comment.publishedDate = date;
        this.thread.lastUpdatedDate = date;
        this.thread.lastUpdatedSessionId = comment.lastUpdatedSessionId;

        if (!this.thread.publishedDate) {
            this.thread.publishedDate = date;
        }
    }

    public updateCommentText(commentId: number, sessionId: number, newText: string): vsls.Comment {
        if (!newText) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Missing or empty newText parameter.');
        }

        const { comment } = this.getComment(commentId);
        comment.text = newText;

        this.updateLastUpdated(comment, sessionId);
        return comment;
    }

    public deleteComment(commentId: number, sessionId: number): vsls.Comment {
        const { comment, index } = this.getComment(commentId);
        this.thread.comments.splice(index, 1);
        comment.isDeleted = true;
        this.updateLastUpdated(comment, sessionId);
        return comment;
    }

    private updateLastUpdated(comment: vsls.Comment, sessionId: number) {
        const date = new Date();
        comment.lastUpdatedSessionId = sessionId;
        comment.lastUpdatedDate = date;
        this.thread.lastUpdatedDate = date;
        this.thread.lastUpdatedSessionId = sessionId;
    }

    private getComment(commentId: number): { comment: vsls.Comment, index: number } {
        const index = this.thread.comments.findIndex(c => c.commentId === commentId);
        if (index === -1) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Unknown comment ID parameter.');
        }

        const comment = this.thread.comments[index];
        return { comment, index };
    }
}

export class HostCommentService implements IHostCommentService, vsls.CommentService {
    private readonly commentThreadChanged = new vscode.EventEmitter<vsls.CommentThreadChangedEventArgs>();
    private threadId = 1;
    private readonly threads = new Map<number, ThreadInfo>();
    private disposables: Disposable[] = [];

    constructor(public readonly dependencies: IDependencies) { }

    public async init(): Promise<void> {
        if (commentsSupported()) {
            await RpcServiceHelper.registerHostRpcService(this, vsls.CommentService, this.dependencies, this.disposables);
        }
    }

    public async dispose(): Promise<void> {
        for (const disposable of this.disposables) {
            disposable.dispose();
        }

        this.threads.clear();
        this.threadId = 1;
        this.disposables = [];
    }

    //#region IHostCommentService

    public updateThreadPosition(threadId: number, start: vsls.Position, end: vsls.Position): void {
        const { thread } = this.threads.get(threadId);
        if (!thread) {
            return;
        }

        const { threadContext } = thread;
        if (!threadContext.rightFileStart) {
            return;
        }

        threadContext.rightFileStart = start;
        threadContext.rightFileEnd = end;
    }

    //#endregion IHostCommentService

    //#region vsls.CommentService
    public async createCommentThreadAsync(commentThread: vsls.CommentThread): Promise<vsls.CommentThread> {
        if (!commentThread) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No comment thread parameter');
        }

        if (!commentThread.threadContext) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Thread context is missing on the comment thread parameter');
        }

        if (!commentThread.threadContext.filePath) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'File path is missing on the thread context of the comment thread parameter');
        }

        commentThread.threadId = this.threadId++;
        commentThread.publishedDate = new Date();
        commentThread.lastUpdatedDate = commentThread.publishedDate;
        const threadInfo = new ThreadInfo(commentThread);

        this.threads.set(commentThread.threadId, threadInfo);
        this.commentThreadChanged.fire({ newThread: commentThread });
        return commentThread;
    }

    public async createCommentAsync(comment: vsls.Comment): Promise<vsls.Comment> {
        if (!comment) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'No comment parameter');
        }

        const thread: ThreadInfo = this.getThread(comment.threadId);
        thread.addComment(comment);
        this.commentThreadChanged.fire({ changedComment: comment });
        return comment;
    }

    public async updateCommentAsync(threadId: number, commentId: number, sessionId: number, newText: string): Promise<vsls.Comment> {
        const thread: ThreadInfo = this.getThread(threadId);
        const comment = thread.updateCommentText(commentId, sessionId, newText);
        this.commentThreadChanged.fire({ changedComment: comment });
        return comment;
    }

    public async deleteCommentAsync(threadId: number, commentId: number, sessionId: number): Promise<vsls.Comment> {
        const thread: ThreadInfo = this.getThread(threadId);
        const comment: vsls.Comment = thread.deleteComment(commentId, sessionId);
        if (thread.isEmpty) {
            this.threads.delete(threadId);
        }

        this.commentThreadChanged.fire({ changedComment: comment });
        return comment;
    }

    public getAllCommentThreadsAsync(): Promise<vsls.CommentThread[]> {
        const result: vsls.CommentThread[] = [];
        for (const threadInfo of this.threads.values()) {
            result.push(threadInfo.thread);
        }

        return Promise.resolve(result);
    }

    public getCommentThreadPositionsAsync(threadIds: number[]): Promise<vsls.CommentThreadLocation[]> {
        let result = [];
        for (let id of threadIds) {
            let threadInfo = this.threads.get(id);
            if (!threadInfo) {
                continue;
            }

            let ctl = new vsls.CommentThreadLocation();
            ctl.threadId = threadInfo.thread.threadId;
            ctl.threadContext = threadInfo.thread.threadContext;

            result.push(ctl);
        }

        return Promise.resolve(result);
    }

    public updateLikeAsync(threadId: number, commentId: number, sessionId: number, participantId: string, isLike: boolean): Promise<void> {
        // No-op.
        return Promise.resolve();
    }

    public get onCommentThreadChanged(): vscode.Event<vsls.CommentThreadChangedEventArgs> {
        return this.commentThreadChanged.event;
    }

    //#endregion vsls.CommentService

    private getThread(threadId: number) {
        if (!threadId) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Comment thread ID is not defined.');
        }

        const thread: ThreadInfo = this.threads.get(threadId);
        if (!thread) {
            throw new ResponseError(ErrorCodes.InvalidParams, 'Unknown comment thread.');
        }

        return thread;
    }
}