'use strict';

import * as vscode from 'vscode';
import {
    Settings,
    SettingKeys,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

export const liveShareTaskType: string = 'vsls';

/**
 * Defines a Live Share guest-side task kind.
 */
export interface RemoteTaskDefinition extends vscode.TaskDefinition {
    /**
     * Unique ID of a host task associated with the task definition.
     */
    readonly taskUid: string;
    /**
     * The execution ID indicates the task is associated with a monitor process.
     * If no execution ID specified, this is a user triggered task.
     */
    executionId?: string | undefined;
}

/**
 * The data context shared b/w the task provider and the workspace task client.
 */
export interface TaskManagerContext extends vscode.Disposable {
   /**
     * An async method of fetching host workspace tasks (used to create regular workspace tasks).
     */
    readonly fetchTasks: () => Promise<vsls.WorkspaceTask[]>;
    /**
     * A method of fetching host task executions (used to create monitor workspace tasks).
     */
    readonly fetchTaskExecutions: () => [vsls.WorkspaceTask, vsls.TaskExecutionMoniker][];
}

let internalContext: TaskManagerContext | undefined;

/**
 * Registers the Live Share workspace task provider.
 */
export function register(): vscode.Disposable {
    const taskProvider = vscode.workspace.registerTaskProvider(
        liveShareTaskType,
        {
            provideTasks: (): Promise<vscode.Task[]> => getWorkspaceTasks(),
            resolveTask: (): vscode.Task | undefined => undefined
        });

    return taskProvider;
}

/**
 * Initializes the internal context and returns its instance.
 * @param fetchTasks The predicate to retrieve a list of all remote workspace tasks.
 * @param fetchTaskExecutions The predicate to retrieve a list of active task executions on the host.
 */
export function configure(
    fetchTasks: () => Promise<vsls.WorkspaceTask[]>,
    fetchTaskExecutions: () => [vsls.WorkspaceTask, vsls.TaskExecutionMoniker][]): TaskManagerContext {
    internalContext = {
        fetchTasks,
        fetchTaskExecutions,
        dispose: () => {
            internalContext = undefined;
        }
    };

    return internalContext;
}

async function getWorkspaceTasks(): Promise<vscode.Task[]> {
    const result: vscode.Task[] = [];

    if (!internalContext) {
        return result;
    }

    const taskExecutions = internalContext.fetchTaskExecutions();
    if (!!taskExecutions && !!taskExecutions.length) {
        // if task executions list is provided, then build monitor tasks only
        for (const [taskOnHost, taskExecution] of taskExecutions) {
            const workspaceTask = buildWorkspaceTask(taskOnHost, taskExecution);
            result.push(workspaceTask);
        }
    } else {
        // build regular workspace tasks otherwise
        const tasksOnHost = await internalContext.fetchTasks();
        for (const taskOnHost of tasksOnHost) {
            const workspaceTask = buildWorkspaceTask(taskOnHost);
            result.push(workspaceTask);
        }
    }

    return result;
}

function buildWorkspaceTask(
    taskOnHost: vsls.WorkspaceTask,
    taskExecution?: vsls.TaskExecutionMoniker): vscode.Task {

    const diagnosticLogging = Settings.get<boolean>(SettingKeys.diagnosticLogging);
    let scope: vscode.TaskScope.Global | vscode.TaskScope.Workspace | vscode.WorkspaceFolder;
    switch (taskOnHost.scope) {
        case vsls.TaskScope.WorkspaceFolder:
            // Since it's a workspace folder, we need to do some work
            // to find the actual workspace folder this should be associated with
            const workspaceIndex = parseInt(taskOnHost.owningWorkspace, 10);
            scope = vscode.workspace.workspaceFolders[workspaceIndex];
            break;

        case vsls.TaskScope.Workspace:
            scope = vscode.TaskScope.Workspace;
            break;

        case vsls.TaskScope.Global:
            scope = vscode.TaskScope.Global;
            break;

        default:
            // Default is assumed to be associated with a workspace folder.
            // Primarily this is for tasks coming from VS which inherently are
            // associated with a single workspace folder
            scope = vscode.workspace.workspaceFolders[0];
            break;

    }

    // create a workspace task to launch a task on the host
    const kind: RemoteTaskDefinition = {
        type: liveShareTaskType,
        taskUid: taskOnHost.uniqueId,
    };

    if (!!taskExecution) {
        // create a workspace task to monitor a task execution on the host
        // if it was already in progress.
        kind.executionId = taskExecution.id;
    }

    // Note: the task define this pty terminal fro the sake
    // to define a CustomExecution but in reality the remote
    // invocation will not happen here
    const writeEmitter = new vscode.EventEmitter<string>();
    const pty: vscode.Pseudoterminal = {
        onDidWrite: writeEmitter.event,
        open: () => {},
        close: () => {},
    };

    const customExecution = new vscode.CustomExecution(() => {
        return Promise.resolve(pty);
    });

    const task: vscode.Task = new vscode.Task(
        kind,
        scope,
        taskOnHost.source && taskOnHost.source !== 'Workspace' ? `${taskOnHost.source}:${taskOnHost.name}` : taskOnHost.name,
        'Shared',
        customExecution
    );
    
    switch (taskOnHost.kind) {
        case 'build':
            task.group = vscode.TaskGroup.Build;
            break;
        case 'clean':
            task.group = vscode.TaskGroup.Clean;
            break;
        case 'rebuild':
            task.group = vscode.TaskGroup.Rebuild;
            break;
        case 'test':
            task.group = vscode.TaskGroup.Test;
            break;
        default:
            break;
    }

    task.presentationOptions = {
        reveal: vscode.TaskRevealKind.Never,
        echo: diagnosticLogging,
        focus: false,
        panel: vscode.TaskPanelKind.Dedicated
    };

    task.isBackground = true;
    task.problemMatchers = ['$vsls'];

    return task;
}