import * as rpc from 'vscode-jsonrpc';
import { ILogger } from '@vs/vso-logging';

export class RpcLoggerAdapter implements rpc.Logger {
    constructor(private trace: ILogger) {}

    public error(message: string): void {
        this.trace.error(message);
    }

    public warn(message: string): void {
        this.trace.warning(message);
    }

    public info(message: string): void {
        this.trace.info(message);
    }

    public log(message: string): void {
        this.trace.verbose(message);
    }
}
