import * as vscode from 'vscode';
import { ICallingService, IParticipantInfo, CallChanged,
    CallingServiceProxyCommands, ICallInfo, SkypeTokenInfo,
    IDevice, ISelectedDevices } from '@calling-service/ICallingService';
import { ExtensionUtil } from '@vs/liveshare-core';

export class CallingServiceProxy implements ICallingService {

    public async initialize(onCallChangedCallback: Function): Promise<void> {
        await ExtensionUtil.tryRegisterCommand(CallingServiceProxyCommands.onCallChangedEvent, async (event: CallChanged) => await onCallChangedCallback(event));
    }

    public async getCallInfo(): Promise<ICallInfo> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.getCallInfo);
    }

    public async startOrJoinCall(groupContext: string, displayName: string, skypeTokenInfo: SkypeTokenInfo): Promise<void> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.startOrJoinCall, groupContext, displayName, skypeTokenInfo);
    }
    
    public async getDevices(): Promise<IDevice[]> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.getDevices);
    }

    public async getSelectedDevices(): Promise<ISelectedDevices> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.getSelectedDevices);
    }

    public async selectDevices(devices: ISelectedDevices): Promise<void> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.selectDevices, devices);
    }

    public async getParticipants(): Promise<IParticipantInfo[]> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.getParticipants);
    }

    public async endCall(): Promise<void> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.endCall);
    }

    public async isMuted(): Promise<boolean> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.isMuted);
    }

    public async mute(participantInfo?: IParticipantInfo): Promise<void> {
        return await vscode.commands.executeCommand(CallingServiceProxyCommands.mute, participantInfo);
    }

    public async unmute(participantInfo?: IParticipantInfo): Promise<void> {
       return await vscode.commands.executeCommand(CallingServiceProxyCommands.unmute, participantInfo);
    }
}