import { ICommandContext } from '@vs/vscode-command-framework';

import { dependencies } from '../Dependencies';
import { CancellationToken } from 'vscode-jsonrpc';
import { CancellationError } from '@vs/vscs-utils';
import { IProgressNotifierUtil } from '../abstractions/IProgressNotifier';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { DecoratorHelper } from '../utils/DecoratorHelper';

export function progressCommandDecorator() {
    
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new ProgressCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.progressNotifierUtil()));
}

export interface ICancelableCommand {
    onCancellationRequested(options: any, context: ICommandContext): Promise<void>;
}

/**
 * Progress `decorator` that executes progress func prior to running
 * core command.
 */
export class ProgressCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private progressNotifierUtil: IProgressNotifierUtil) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;

        const { cancellationTokenSource } = context;
        const commandCancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        result = await this.progressNotifierUtil.create(
            { title: context.commandName },
            commandCancellationToken,
            async (progressUIcancellationToken: CancellationToken) => {
                /*
                    Since we have to listen to the `progressUIcancellationToken.onCancellationRequested` and
                    throwing inside the callback will swallow the error(because at time of exception, the callback will be on the top of the call stack),
                    we need this explicit Promise `reject` to be able to bubble up the error.
                */
                return new Promise(async (resolve, reject) => {

                    const cancel = async () => {
                        const anyCommand = <any>this.command;
                        if (anyCommand.onCancellationRequested) {
                            await (<ICancelableCommand>anyCommand).onCancellationRequested(options, context);
                        }

                        reject(new CancellationError('The operation was cancelled.'));
                    };

                    if (progressUIcancellationToken) {
                        if (progressUIcancellationToken.isCancellationRequested) {
                            await cancel();
                        } else {       
                            progressUIcancellationToken.onCancellationRequested(async () => {
                                await cancel();
                            });
                        }
                    }

                    if (cancellationTokenSource && commandCancellationToken) {
                        if (commandCancellationToken.isCancellationRequested) {
                            await cancel();
                        } else {     
                            commandCancellationToken.onCancellationRequested(async () => {
                                await cancel();
                            });
                        }
                    }

                    try {
                        resolve(await this.next.invoke(options, context));
                    } catch (e) {
                        reject(e);
                    }
                });
            });

        return result;
    }
}