'use strict';

import * as vscode from 'vscode';
import { Settings } from './Settings';
import { SettingKeys } from './SettingKeys';
import { SessionState, SessionStateChangedEventArgs } from './SessionTypes';
import { sessionStateTracker } from './SessionStateTracker';
import { localize } from './localize';

const visibleStates = [SessionState.ExternallySigningIn, SessionState.Initializing, SessionState.SignedIn, SessionState.SignedOut, SessionState.SigningIn];

export function createSimpleStatusBar() {
    const shareStatusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 3);
    shareStatusBarItem.text = `$(live-share) Live Share`;
    shareStatusBarItem.command = 'liveshare.start';
    shareStatusBarItem.tooltip = localize('statusbar.StartCollaboration');

    const show = () => {
        if (Settings.get<string>(SettingKeys.showInStatusBar) === 'always') {
            shareStatusBarItem.show();
        }
    }

    show();

    sessionStateTracker.onStateChanged((e: SessionStateChangedEventArgs) => {
        if (visibleStates.indexOf(e.newState) >= 0) {
            show();
        } else {
            shareStatusBarItem.hide();
        }
    });
}
