import { TraceSource } from '@vs/vso-logging';
import { CancellationError } from "@vs/vscs-utils";
import { ICommandContext, NotificationUtil } from '@vs/vscode-command-framework';
import { sessionStateTracker } from '../SessionStateTracker';
import { SessionAction } from '../SessionTypes';
import { TelemetryEventNames, TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { auth } from './Authentication';
import { liveshareGithubStrategy } from './strategies';
import { IAuthenticationFlow } from './IAuthenticationFlow';
import { IAuthenticationProvider } from './IAuthenticationProvider';
import { AuthenticationOptions } from './AuthenticationOptions';
import { AuthenticationResultOptions } from "./AuthenticationResultOptions";
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { DEFAULT_ANONYMOUS_USER_NAME } from '../constants';
import { localize } from '../localize';
import { TelemetryEvent } from '@vs/vso-telemetry';

export class AuthenticationFlow implements IAuthenticationFlow {
    public constructor(
        private authenticationProvider: IAuthenticationProvider,
        private trace: TraceSource) {
    }

    public async attemptAuthenticationCheckFlow(options: AuthenticationOptions, context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;
        let isAuthenticated = false;
        let error: Error;

        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_CHECK_STARTING);

        try {
            isAuthenticated = await this.attemptAuthenticationCheckFlowCore(options, context);
        } catch (e) {
            error = e;
        }

        const authResultOptions: AuthenticationResultOptions = {
            successPoint: TelemetryPropertyNames.SIGNIN_CHECK_COMPLETED,
            cancelPoint: TelemetryPropertyNames.SIGNIN_CHECK_COMPLETED_CANCEL,
            errorPoint: TelemetryPropertyNames.SIGNIN_CHECK_COMPLETED_ERROR,
            neutralPoint: TelemetryPropertyNames.SIGNIN_CHECK_COMPLETED,
            telemetryEventName: TelemetryEventNames.AUTH_SILENT_CHECK,
            isAuthenticated: isAuthenticated,
            error: error,
            cancellationToken: cancellationToken,
            allowsNeutralOutcome: true,
            isNative: options.isNativeAuth
        };

        await this.processAuthResult(authResultOptions);
        return isAuthenticated;
    }

    public async attemptPromptedUserLoginFlow(options: AuthenticationOptions, context: ICommandContext): Promise<void> {
        if (options && options.shouldPromptForAuth) {
            const signInAgainItem = { title: 'Launch Sign In' };

            context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTH_PROMPT_OPENED, true);
            
            sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_PROMPT_STARTING);
            const questionResult = await NotificationUtil.showInformationMessage<any>(localize('notification.YouNeedToSignInBeforeJoin'), false, {}, signInAgainItem );
            sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_PROMPT_COMPLETED);

            context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTH_PROMPT_QUESTION_RESULT, questionResult && questionResult.title);

            const signInSelected = questionResult && (questionResult.title === signInAgainItem.title);
            if (!signInSelected) {
                throw new CancellationError('Operation cancelled @ sign in again.');
            } 
        } 

        await this.attemptLoginFlow(options, context);
    }

    public async attemptPromptedUserAnonymousLoginFlow(options: AuthenticationOptions, context: ICommandContext): Promise<boolean> {
        const { token } = context.cancellationTokenSource;

        if (token.isCancellationRequested === true) {
            context.telemetryEvent.addProperty(TelemetryPropertyNames.AUTH_CANCEL_ANONYMOUS_LOGIN_FLOW, true);
            throw new CancellationError();
        }

        const signInButton = localize('generic.SignIn');
        const anonymousButton = localize('generic.ContinueAsAnonymous');

        context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTH_PROMPT_OPENED, true);

        // Open Prompt to make sure user is happy with anon sign-in, suggest to login 
        // with an `anonymous` option
        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_PROMPT_STARTING);
        const questionResult = await NotificationUtil.showInformationMessage(localize('notification.SignIntoJoin'), false, anonymousButton, signInButton);
        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_PROMPT_COMPLETED);
        
        context.telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_AUTH_PROMPT_QUESTION_RESULT, questionResult);
 
        // If user doesn't want to anon auth, then we cancel login all together.
        if (!questionResult) {
            context.telemetryEvent.addProperty(TelemetryPropertyNames.AUTH_CANCEL_NO_ANON_AUTH, true);
            throw new CancellationError();
        }

        // If the users selects the anonymous path
        const isAnonymousSignInSelected = (questionResult === anonymousButton);
        if (isAnonymousSignInSelected) {
            // Let user pick a name that they would like, otherwise default to standard `Guest User` 
            // anonymous name
            context.telemetryEvent.addProperty(TelemetryPropertyNames.USER_OPTED_OUT_TO_AUTH_ON_JOIN, true);
            const name = await this.authenticationProvider.askForUserName();
            context.telemetryEvent.addProperty(TelemetryPropertyNames.USER_PICKED_NAME_LENGTH, name.length);
            context.telemetryEvent.addProperty(TelemetryPropertyNames.USER_PICKED_DEFAULT_NAME, name === DEFAULT_ANONYMOUS_USER_NAME);

            // Deals with the case that when a users is already signed in as anonymous, we want to
            // check every time with them as to if they want to fully sign in.
            if (userAuthStateTracker.isCurrentUserAnonymous()) {
                return true;
            } 
            
            return await this.attemptAnonymousLoginFlow(context);
        }

        return false;
    }

    private async attemptAnonymousLoginFlow(context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;

        // After returning from the `attemptLoginFlowCoreBrowser` the command might be cancelled already
        if (cancellationTokenSource && cancellationTokenSource.token.isCancellationRequested) {
            return;
        }

        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_STARTING);

        // Attempt to login using the default/stored credentials if we can.
        const isAuthenticated = await this.authenticationProvider.attemptAnonymousLoginVSCodeAccount(undefined, cancellationTokenSource.token);

        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_COMPLETED);
        if (isAuthenticated) {
            sessionStateTracker.transition(SessionAction.SignInSuccess);
        }

        return isAuthenticated;
    }

    private async attemptLoginFlow(options: AuthenticationOptions, context: ICommandContext): Promise<void> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;
        let isAuthenticated = false;
        let error: Error;

        sessionStateTracker.point(TelemetryPropertyNames.SIGNIN_STARTING);

        try {
            if (options.isNativeAuth) {
                sessionStateTracker.transition(SessionAction.AttemptSignIn);
                isAuthenticated = await this.authenticationProvider.attemptPromptedNativeLogin(context);
            } else {
                isAuthenticated = await this.attemptLoginFlowCoreBrowserVSCodeAccount(context);
            }
        } catch (e) {
            error = e;
        }

        const authResultOptions: AuthenticationResultOptions = {
            successPoint: TelemetryPropertyNames.SIGNIN_COMPLETED,
            cancelPoint: TelemetryPropertyNames.SIGNIN_COMPLETED_CANCEL,
            errorPoint: TelemetryPropertyNames.SIGNIN_COMPLETED_ERROR,
            telemetryEventName: TelemetryEventNames.AUTH_PROMPTED_SIGNIN,
            isAuthenticated: isAuthenticated,
            error: error,
            cancellationToken: cancellationToken,
            allowsNeutralOutcome: false,
            isNative: options.isNativeAuth
        };

        await this.processAuthResult(authResultOptions);
    }

    private async processAuthResult(options: AuthenticationResultOptions)
    {
        let isCanceled: boolean = false;

        try {
            // Success
            if (options.isAuthenticated) {
                sessionStateTracker.point(options.successPoint);
                sessionStateTracker.transition(SessionAction.SignInSuccess);
                return;
            }

            // Cancel
            if (options.cancellationToken?.isCancellationRequested ||
                (options.error instanceof CancellationError)) {
                sessionStateTracker.point(options.cancelPoint);
                sessionStateTracker.transition(SessionAction.SignInError);
                isCanceled = true;

                throw options.error || new CancellationError();
            }

            // Error
            if (options.error || !options.allowsNeutralOutcome) {
                sessionStateTracker.point(options.errorPoint);
                sessionStateTracker.transition(SessionAction.SignInError);
                throw options.error || new Error(localize('error.UnexpectedAuthenticationError'));
            }

            // Neutral
            sessionStateTracker.point(options.neutralPoint);
            sessionStateTracker.transition(SessionAction.SignOut);
        } finally {
            // This telemetry event is used to compare vscode account and native
            const authTelemetryEvent = new TelemetryEvent(options.telemetryEventName);
            authTelemetryEvent.addProperty(TelemetryPropertyNames.LOGIN_IS_NATIVE, options.isNative);
            authTelemetryEvent.addProperty(TelemetryPropertyNames.LOGIN_RESULT, options.isAuthenticated);
            authTelemetryEvent.addProperty(TelemetryPropertyNames.LOGIN_IS_CANCELED, isCanceled);

            authTelemetryEvent.send();
        }
    }

    private async attemptAuthenticationCheckFlowCore(options: AuthenticationOptions, context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        // Check with the auth provider what it thinks the current state is.
        let isAuthenticated = this.authenticationProvider.isAuthenticated();
        if (!isAuthenticated) {
            sessionStateTracker.transition(SessionAction.AttemptSignIn);

            if (options.isNativeAuth) {
                isAuthenticated = await this.authenticationProvider.attemptSilentNativeLogin(options, context);
            } else {
                // Attempt to login using the default/stored credentials if we can.
                isAuthenticated = await this.authenticationProvider.attemptDefaultLoginVSCodeAccount(options, cancellationToken);
            }
        }

        return isAuthenticated;
    }

    private async attemptLoginFlowCoreBrowserVSCodeAccount(context: ICommandContext): Promise<boolean> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        sessionStateTracker.transition(SessionAction.AwaitExternalSignIn);
        sessionStateTracker.point(TelemetryPropertyNames.EXTERNAL_SIGNIN_STARTING);

        const token = await auth.API.askToSignIn({
            shouldSkipQuestion: true,
            strategies:
            [
                auth.API.defaultStrategy,
                liveshareGithubStrategy
            ]
        });

        context.telemetryEvent.addProperty(TelemetryPropertyNames.EXTERNAL_SIGNIN_USER_COMPLETE_FLOW_TOKEN_SET, !!token);
        sessionStateTracker.point(TelemetryPropertyNames.EXTERNAL_SIGNIN_USER_COMPLETE_FLOW);

        if (cancellationToken.isCancellationRequested) {
            sessionStateTracker.transition(SessionAction.SignOut);
            context.telemetryEvent.addProperty(TelemetryPropertyNames.AUTH_CANCEL_NO_TOKEN_USER_CANCELLED, true);
            throw new CancellationError();
        }

        if (!token) {
            throw new CancellationError('Authentication incomplete.');
        }

        sessionStateTracker.point(TelemetryPropertyNames.EXTERNAL_SIGNIN_COMPLETE);
        sessionStateTracker.transition(SessionAction.AttemptSignIn);

        // Attempt to login with the returned user code.
        return await this.authenticationProvider.attemptLoginVSCodeAccount(token, cancellationToken);
    }
}