'use strict';
import * as semver from 'semver';
import * as vscode from 'vscode';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { WorkspaceProvider } from './WorkspaceProvider';
import { IFileSystemManager } from './IFileSystemManager';
import { IRpcServices } from '../contracts/IRpcServices';
import { ISessionContext } from '../ISessionContext';

export class FileSystemManager implements IFileSystemManager {
    private provider: WorkspaceProvider;
    private isFileSystemProviderReadOnly: boolean;
    private providerRegistration: vscode.Disposable;

    constructor(
        private readonly rpcServices: IRpcServices,
        private readonly sessionContext: ISessionContext
    ) { }

    public get workspaceProvider(): WorkspaceProvider {
        return this.provider;
    }

    public registerFileSystemProvider(isReadOnly = false): void {
        const isVersion123 = semver.gte(semver.coerce(vscode.version), '1.23.0');

        if (this.providerRegistration) {
            // There is already a file system provider registered, do not change it if
            // the read-only option has not changed or vscode doesn't support it.
            // Refresh file explorer anyway.
            if (isReadOnly === this.isFileSystemProviderReadOnly || !isVersion123) {
                return;
            }

            this.unregisterProvider();
        } else {
            // This is the first time we register the file system provider.
            // Add disposable to the extension context to dispose of it later.
            ExtensionUtil.context.subscriptions.push(this);
        }

        // version >= 1.23.0, using new API
        if (!this.provider) {
            this.provider = new WorkspaceProvider(
                this.rpcServices.workspaceService(),
                this.rpcServices.fileService,
                this.sessionContext);
        }

        this.provider.bumpGeneration();
        this.providerRegistration = vscode.workspace.registerFileSystemProvider(
            Settings.get<string>(SettingKeys.authority), this.provider, { isCaseSensitive: true, isReadonly: isReadOnly || false });

        this.isFileSystemProviderReadOnly = isReadOnly;
    }

    public disposeWorkspaceProvider() {
        if (this.provider) {
            this.provider.dispose();
            this.provider = null;
        }
    }

    public dispose() {
        this.unregisterProvider();
        this.disposeWorkspaceProvider();
    }

    private unregisterProvider() {
        if (this.providerRegistration) {
            this.providerRegistration.dispose();
            this.providerRegistration = null;
        }
    }
}