import { traceSource } from '@vs/vscode-command-framework';
import { checkDebugging } from './checkDebugging';
import { showDiagnosticErrorMessage } from './notificationUtil';
import { ExtensionTelemetry } from '../telemetry/ExtensionTelemetry';

export function assert(condition: any, message: string, telemetrySafeMessage?: string) {
    if (!condition) {
        if (checkDebugging()) {
            // When getting an assert, and we've got a debugger attached, give
            // the engineer a chance to catch it at the point it happens
            // tslint:disable-next-line:no-debugger
            debugger;
        }
        traceSource.withName('Asserts').error(`Assertion Violation: ${message}`);
        ExtensionTelemetry.ReportFailedAssertion(telemetrySafeMessage || message);
        showDiagnosticErrorMessage(`Assertion Violation: ${message}`);
    }
}