
import { CancellationToken, Event, Progress } from 'vscode';
import { DebugProtocol } from 'vscode-debugprotocol';
import { vsls } from '@vs/vsls-contracts';
import { 
    ServiceInfo,
} from '@vs/vso-rpc';

export enum ContinueReason {
    Go = <any>'go',
    StepIn = <any>'stepIn',
    StepOut = <any>'stepOut',
    StepOver = <any>'stepOver',
}

export interface DebugSessionHostService {
    continueAsync(
        reason: ContinueReason,
        threadId: number,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    handleProtocolRequestAsync(requestType: string , requestArgs: any, cancellationToken?: CancellationToken): Promise<any>;
    getCurrentStoppedEventAsync(cancellationToken?: CancellationToken): Promise<any>;
    initializeRequestAsync(initializeDebugSessionRequest: InitializeDebugSessionRequest, cancellationToken?: CancellationToken): Promise<InitializeDebugSessionResponse>;

    readonly onDebugEvent: Event<any>;
    readonly onUIDebugEvent: Event<UIDebugEventArgs>;
}

export interface StackTraceResponse {
    stackFrames: DebugProtocol.StackFrame[];
    totalFrames?: number;
}

export interface StackTraceInfo {
    key: DebugProtocol.StackFrameFormat;
    value: StackTraceResponse;
}

export interface SourceResponse {
    content: string;
    mimeType?: string;
}

export interface UIStoppedEvent {
    threads: DebugProtocol.Thread[];
    stackFrames: {[key: string]: StackTraceInfo[]};
    scopes: {[key: string]: DebugProtocol.Scope[]};
    sourceReferenceContent: {[key: string]: SourceResponse};
}

export interface UIDebugEvent {
    type: string;
}

export interface EnterRunMode extends UIDebugEvent
{
    Reason: number;
    ThreadId: number;
}

export enum MessageType {
    OutputString = 1,
    MessageBox = 2,
    ReasonException = 256,
    ReasonTracepoint = 512
}

export interface DebugMessageEvent extends UIDebugEvent
{
    messageType: MessageType;
    message: string;
}

export class UIDebugEventArgs extends vsls.EventArgs {
    body: UIDebugEvent;
}

export class InitializeDebugSessionRequest {
    includeModules: boolean;
}

export class InitializeDebugSessionResponse {
    stoppedEvent: any;
    outputEvents: DebugProtocol.OutputEvent[];
    replayEvents: DebugProtocol.Event[];
    modulesResponse: DebugProtocol.ModulesResponse;
}

export const DebugSessionHostService: ServiceInfo<DebugSessionHostService> = {
    name: '',
    methods: [ 'continue', 'handleProtocolRequest', 'getCurrentStoppedEvent', 'initializeRequest' ],
    events: [ 'debugEvent', 'uIDebugEvent' ],
};