'use strict';

import * as vscode from 'vscode';
import { Disposable, Inittable } from '../abstractions/Mixins';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '../tracing/traceSource';
import { IDataScrapingWorker, IDataScrapingManager } from './Interfaces';

interface DataScrapingJob {
    readonly kind: string;
    readonly dataScraper: IDataScrapingWorker;
    readonly terminal: vscode.Terminal;
    readonly registration: vscode.Disposable;
    dispose: () => Promise<void>;
}

type WorkerBuilder = (terminal: vscode.Terminal) => IDataScrapingWorker;

/**
 * Manages registered terminal output data scrapers.
 * Utilizes registered builders to instantiate one instance of each data scraper kind per terminal window.
 */
export class DataScrapingManager extends Inittable(Disposable(Object))
    implements IDataScrapingManager {
    private static singleton: IDataScrapingManager;
    private readonly trace: TraceSource;
    private readonly disposables: vscode.Disposable[] = [];
    private deferredWork: Promise<any> = Promise.resolve(true);
    private readonly builders: Map<string, WorkerBuilder> = new Map<string, WorkerBuilder>();
    private readonly jobs: DataScrapingJob[] = [];
    private eventEmitter?: vscode.EventEmitter<vscode.Terminal>;

    // Defer import of `vscode` package.
    private static get vscode(): typeof vscode {
        return require('vscode');
    }

    public static get Instance(): IDataScrapingManager {
        if (!DataScrapingManager.singleton) {
            DataScrapingManager.singleton = new DataScrapingManager();
        }
        return DataScrapingManager.singleton;
    }

    private constructor() {
        super();
        this.trace = traceSource.withName('DataScrapingManager');

        this.deferredWork = this.deferredWork
            .then(() => this.init())
            .catch((reason) => {
                this.trace.error(reason.message);
            });
    }

    /**
     * Event triggered when a [[DataScrapingJob]] is created for a [[vscode.Terminal]]
     * @returns the corresponding [[vscode.Terminal]] instance
     */
    public get onScrappingStarted(): vscode.Event<vscode.Terminal> {
        if (!this.eventEmitter) {
            this.eventEmitter = new DataScrapingManager.vscode.EventEmitter<vscode.Terminal>();
        }
        return this.eventEmitter.event;
    }

    public async dispose(): Promise<void> {
        await this.deferredWork;

        this.disposables.splice(0).forEach((d) => d.dispose());
        this.jobs.splice(0).forEach((d) => d.dispose());

        await super.dispose();
    }

    public async init(): Promise<void> {
        if (this.isInitialized || !DataScrapingManager.vscode.window.onDidOpenTerminal) {
            return;
        }

        DataScrapingManager.vscode.window.onDidOpenTerminal(
            this.handleTerminalCreated,
            this,
            this.disposables,
        );
        DataScrapingManager.vscode.window.onDidCloseTerminal(
            this.handleTerminalClosed,
            this,
            this.disposables,
        );

        DataScrapingManager.vscode.window.terminals.forEach(this.handleTerminalCreated, this);

        await super.init();
    }

    public async registerDataScraper(
        kind: string,
        builder: (terminal: vscode.Terminal) => IDataScrapingWorker,
    ): Promise<vscode.Disposable> {
        await this.deferredWork;

        this.builders.set(kind, builder);

        if (this.isInitialized) {
            const promises = DataScrapingManager.vscode.window.terminals.map(async (terminal) => {
                const dataScraper = builder(terminal);
                if (dataScraper) {
                    await dataScraper.init();
                    this.createJob(terminal, dataScraper, kind);
                }
            });
            await Promise.all(promises);
        }

        return new DataScrapingManager.vscode.Disposable(() => this.unregisterDataScraper(kind));
    }

    private unregisterDataScraper(kind: string) {
        this.builders.delete(kind);
        const activeJobs = this.jobs.splice(0);
        activeJobs.filter((x) => x.kind === kind).forEach((job) => job.dispose());
        this.jobs.push(...activeJobs.filter((x) => x.kind !== kind));
    }

    private async handleTerminalCreated(terminal: vscode.Terminal) {
        const promises = [...this.builders.entries()].map(async (entry) => {
            const [kind, builder] = entry;
            const dataScraper = builder(terminal);
            if (dataScraper) {
                await dataScraper.init();
                this.createJob(terminal, dataScraper, kind);
            }
        });
        this.deferredWork = this.deferredWork
            .then(() => Promise.all(promises))
            .catch((reason) => {
                this.trace.error(reason.message);
            });
    }

    private createJob(
        terminal: vscode.Terminal,
        dataScraper: IDataScrapingWorker,
        kind: string,
    ): DataScrapingJob {
        let registration: vscode.Disposable;

        if (typeof DataScrapingManager.vscode.window.onDidWriteTerminalData === 'function') {
            registration = DataScrapingManager.vscode.window.onDidWriteTerminalData((e) => {
                if (e.terminal === terminal) {
                    dataScraper.processData(e.data);
                }
            });
        } else {
            registration = terminal.onDidWriteData(dataScraper.processData, dataScraper);
        }

        const job = {
            kind,
            dataScraper,
            terminal,
            registration,
            dispose: () => {
                registration.dispose();
                return dataScraper.dispose();
            },
        };
        this.jobs.push(job);

        if (!this.eventEmitter) {
            this.eventEmitter = new DataScrapingManager.vscode.EventEmitter<vscode.Terminal>();
        }
        this.eventEmitter.fire(job.terminal);
        return job;
    }

    private handleTerminalClosed(terminal: vscode.Terminal) {
        const activeJobs = this.jobs.splice(0);
        activeJobs.filter((x) => x.terminal === terminal).forEach((job) => job.dispose());
        this.jobs.push(...activeJobs.filter((x) => x.terminal !== terminal));
    }
}

const dataScrapingManagerInstance = DataScrapingManager.Instance;
export { dataScrapingManagerInstance };
