'use strict';

import * as vscode from 'vscode';
import { ServiceInfo } from '@vs/vso-rpc';

/**
 * Augments vscode.NotebookData to include the view type that was
 * used to open the notebook, if different than the requested view type
 */
export type NotebookDataWithNotebookType = vscode.NotebookData & { usedNotebookType?: string };

export type GuestCellChanges = {
    deletes: string[];
    adds?: {
        insertAbove: string;
        cells: vscode.NotebookCellData[];
    }
}

export type HostCellChanges = {
    deletes: string[];
    adds?: {
        idx: number;
        cells: vscode.NotebookCellData[]
    }
}

export type OnDidChangeNotebookCellsArg = {
    relativePath: string;
    changes: HostCellChanges[];
    contentHash: string;
}

/**
 * Provides remote access to notebooks data. 
 */
export interface NotebooksService {
    /**
     * Returns a list of all registered notebook content providers.
     */
    getContentProvidersAsync(cancellationToken?: vscode.CancellationToken): Promise<ContentProvider[]>;
    /**
     * Get the notebook content for the given notebook opened with the given view type.
     */
    openNotebookAsync(relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<NotebookDataWithNotebookType>;
    /**
     * Event raised when the cell output changes. Event args include information to find
     * the cell whose output changed and the new output contents.
     */
    readonly onDidChangeCellOutputs: vscode.Event<CellOutputsChangeEvent>;
    /**
     * Event raised when the cell execution state changes. Event args include information to find
     * the cell whose execution state changed and the new execution state.
     */
     readonly onDidChangeCellExecutionState: vscode.Event<CellExecutionStateChangeEvent>;
    /**
     * Event raised when cell metadata changes. Event args include information to find
     * the cell whose metadata changed and the new metadata.
     */
    readonly onDidChangeCellMetadata: vscode.Event<CellMetadataChangeEvent>;
    /**
     * Event raised when cell language changes. Event args include information to find
     * the cell whose metadata changed and the new language.
     */
    readonly onDidChangeCellLanguage: vscode.Event<CellLanguageChangeEvent>;
    /**
     * Executes the specified cell.
     */
    executeCellAsync(range: { start: number, end: number }, relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<void>;
    /**
     * Executes all cells of the specified notebook.
     */
    executeNotebookAsync(relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<void>;
    /**
     * Cancels the execution of the specified cells.
     */
    cancelCellExecutionAsync(range: { start: number, end: number }, relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<void>;
    /**
     * Cancels the execution of all cells in the specified notebook.
     */
    cancelNotebookExecutionAsync(relativePath: string, notebookType: string, cancellationToken?: vscode.CancellationToken): Promise<void>;
    /**
     * Changes the language of the specified cells
     */
    changeCellLanguageAsync(cellId: string, language: string, relativePath: string, cancellationToken?: vscode.CancellationToken): Promise<void>;
     /* Changes notebook cells on the host.
     */
    applyNotebookCellChangesAsync(relativePath: string, changes: GuestCellChanges[], cancellationToken?: vscode.CancellationToken): Promise<void>;
    /**
     * Event raised by the host when their notebook cells change.
     */
    readonly onDidChangeNotebookCells: vscode.Event<OnDidChangeNotebookCellsArg>;
}

export const NotebooksService: ServiceInfo<NotebooksService> = {
    name: 'notebooksService',
    methods: ['getContentProviders', 'openNotebook', 'executeCell', 'executeNotebook', 'cancelCellExecution', 'cancelNotebookExecution', 'applyNotebookCellChanges', 'changeCellLanguage'],
    events: ['didChangeCellOutputs', 'didChangeCellMetadata', 'didChangeNotebookCells', 'didChangeCellLanguage', 'didChangeCellExecutionState'],
};

export type ContentProvider = {
    viewType: string,
    displayName: string,
    priority: 'option' | 'default',
    selector: {
        filenamePattern: string,
        excludeFileNamePattern?: string
    }[]
};

export type CellOutputsChangeEvent = {
    relativePath: string,
    cells: {
        id: string,
        outputs: vscode.NotebookCellOutput[]
    }[]
};

export type CellMetadataChangeEvent = {
    relativePath: string,
    cell: {
        id: string,
        metadata: NotebookCellMetadata
    }
};

export type CellLanguageChangeEvent = {
    relativePath: string,
    cellId: string,
    language: string
};

export type CellExecutionStateChangeEvent = {
    relativePath: string,
    cellId: string,
    executionState: number,
    executionSummary: {
        success: boolean,
        timing: {
            startTime: number, 
            endTime: number
        }
    }
};

export type NotebookCellMetadata = { [key: string]: any };
