import * as os from 'os';
import * as path from 'path';
import * as fs from 'fs';

import * as child_process from 'child_process';
import * as sudo from 'sudo-prompt';

import { OSPlatform } from './osPlatform';

export function sudoExecAgent(
    agentPath: string,
    args: string[],
    envVars?: { [key: string]: string | undefined },
    sudoWindowName?: string | undefined): Promise<child_process.ChildProcess | undefined> {
    return new Promise<child_process.ChildProcess | undefined>((resolve, reject) => {
        const sudoCallback = (error?: Error, _stdout?: string | Buffer, stderr?: string | Buffer) => {
            if (error) {
                reject(`sudo exec failed - message: ${error.message} - stack: ${error.stack}`);
            } else if (stderr) {
                reject(`sudo exec failed - stderr: ${stderr}`);
            }
            resolve(undefined);
        }
        execAgentInternal(agentPath, args, envVars, sudoWindowName, sudoCallback);
    });
}

export function execAgent(
    agentPath: string,
    args: string[],
    envVars?: { [key: string]: string | undefined }): child_process.ChildProcess {
    return execAgentInternal(agentPath, args, envVars)!;
}

function execAgentInternal(
    agentPath: string,
    args: string[],
    envVars?: { [key: string]: string | undefined },
    sudoWindowName?: string | undefined,
    sudoCallback?: (error?: Error, stdout?: string | Buffer, stderr?: string | Buffer) => void): child_process.ChildProcess | undefined {
    // Clone process.env before setting additional environment variables
    // that should be applied only to the child agent process
    const childProcessEnv = Object.assign({}, process.env);

    if (envVars) {
        Object.keys(envVars).forEach(key => childProcessEnv[key] = envVars[key]);
    }

    if (os.platform() === OSPlatform.WINDOWS) {
        // Try to use `cmd.exe`, if found in the expected place.
        // Node's child_process.exec() uses %ComSpec% by default, but when set to other shells that can cause problems.
        const cmdExePath = path.join(process.env.SystemRoot || 'C:\\WINDOWS', 'system32', 'cmd.exe');
        let shell: string;
        try {
            fs.statSync(cmdExePath);
            shell = cmdExePath;
        } catch {
            shell = process.env.ComSpec || 'cmd.exe';
        }
        const command = `start /B "" "${agentPath}" ${args.join(' ')}`;
        if (sudoWindowName) {
            sudo.exec(command, { name: sudoWindowName, env: envVars as any }, sudoCallback);
            return;
        }

        return child_process.exec(command, { env: childProcessEnv, shell, windowsHide: true });
    } else {
        const sh = `/bin/sh -c '"${agentPath}" ${args.join(' ')}' &`;
        if (sudoWindowName) {
            sudo.exec(`ELECTRON_RUN_AS_NODE=1 /bin/sh -c '"${agentPath}" ${args.join(' ')}' &`, { name: sudoWindowName, env: envVars as any }, sudoCallback);
            return;
        }
        return child_process.exec(sh, { env: childProcessEnv, windowsHide: true });
    }
}