
import { Disposable } from 'vscode';
import { vsls, contactProtocol } from '@vs/vsls-contracts';
import { IContactModel } from './IContactModel';
import { EventEmitter } from 'events';

export interface IContactServiceManager extends EventEmitter {
    readonly selfUser: IContactModel;
    readonly selfUserId: string | null;
}

export interface InviteLinkReceived {
    readonly provider: IContactServiceManager;
    readonly originator: IContactModel;
    readonly link: string;
}

export interface InviteLinkJoining {
    /**
     * Id of the guest being invited to join the session
     */
    readonly targetContactId: string;
    /**
     * Id of the host who sends the invite
     */
    readonly fromContactId: string;
}

export interface IContactManager extends EventEmitter {
    onInviteStatusChanged(handler: () => void): void;
    getInviteStatus(contactId: string): vsls.InviteContactStatus;
    fireInviteStatusChanged(targetContactId: string, fromContactId: string, status: vsls.InviteContactStatus): Promise<void>;
    registerContactProvider(serviceId: string, service: contactProtocol.ContactServiceProvider): Disposable;
    getServiceManager(serviceId: string): IContactServiceManager | undefined;

    isRecentContat(contact: IContactModel): boolean;
    isSuggestedContat(contact: IContactModel): boolean;
    
    
    readonly selfContact: IContactModel | undefined;
    readonly invitedContacts: IContactModel[];
    readonly isDoNotDisturbState: boolean;
    readonly hasSendMessageProvider: boolean;
}

export enum ContactManagerEvents {
    ProviderAdded = 'ProviderAdded',
    ContactsChanged = 'ContactsChanged',
    InviteLinkReceived = 'MessageReceived',
    SuggestedUsersUpdate = 'SuggestedUsersUpdate',
    RecentContactsUpdate = 'RecentContactsUpdate',
    InviteContactsUpdate = 'InviteContactsUpdate',
    Ready = 'Ready',
    ProviderCapabilitiesChanged = 'ProviderCapabilitiesChanged',
    SignedStateChanged = 'SignedStateChanged'
}

export enum ContactServiceEvents {
    Initialized = 'Initialized',
    SelfContactChanged = 'UsersPresenceChanged',
    AvailableUsersChanged = 'AvailableUsersChanged',
    ContactsChanged = 'ContactsChanged',
    InviteLinkReceived = 'InviteLinkReceived',
    MessageReceived = 'MessageReceived',
    ContactsChangedNotification = 'ContactsChangedNotification',
    ContactPropertyChangedNotification = 'ContactPropertyChangedNotification',
    SuggestedUsersUpdate = 'SuggestedUsersUpdate',
    CapabilitiesChanged = 'CapabilitiesChanged',
    SignedStateChanged = 'SignedStateChanged',
    AuthenticationRequired = 'AuthenticationRequired'
}