import { TelemetryEventNames, TelemetryPropertyNames } from '@vs/liveshare-core';

export class AcquisitionTelemetryEventNames {
    public static readonly ACQUIRE_DEPS = 'acquire-deps';
    public static readonly ACQUIRE_DEPS_FAULT = TelemetryEventNames.FAULT_PREFIX + 'acquire-deps-fault';
    public static readonly ACQUIRE_DEPS_PACKAGE = 'acquire-depspackage';
    public static readonly INSTALL_FAULT = TelemetryEventNames.FAULT_PREFIX + 'install-fault';
    public static readonly LOCK_FILE_FAULT = TelemetryEventNames.FAULT_PREFIX + 'lock-lockfile-fault';
    public static readonly DELETE_DEPENDENCIES_FAULT = TelemetryEventNames.FAULT_PREFIX + 'delete-dependencies-fault';
}

export class AcquisitionTelemetryPropertyNames {
    private static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'Acquisition.';

    /**
     * The stage of installation.
     */
    public static readonly INSTALLATION_STAGE = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'InstallationStage';

    /**
     * If acquisition failed, the url of package for which it failed.
     */
    public static readonly PACKAGE_URL = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'PackageUrl';

    /**
     * If acquisition failed, the url of package for which it failed.
     */
    public static readonly PACKAGE_CODE = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'PackageCode';

    /**
     * The platform of the client.
     */
    public static readonly INSTALLATION_PLATFORM = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'InstallationPlatform';

    /**
     * The architecture of the client.
     */
    public static readonly INSTALLATION_ARCH = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'InstallationArch';

    /**
     * Did it end up downloading
     */
    public static readonly DID_DOWNLOAD = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'DidDownload';

    /**
     * Whether the checksum passef
     */
    public static readonly CHECKSUM_PASS = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'ChecksumPass';

    /**
     * Indicates if dependencies were downloaded with vscode download api.
     */
    public static readonly VSCODE_DOWNLOAD = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'VscodeDownload';

    /**
     * Total number of files in the base folder pre unpack
     */
    public static readonly TOTAL_BASE_FILES_PRE_UNPACK = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalBaseFilesPreUnpack';

    /**
     * Total number of files in the base folder post unpack
     */
    public static readonly TOTAL_BASE_FILES_POST_UNPACK = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalBaseFilesPostUnpack';

    /**
     * Total number of files in the base folder pre move
     */
    public static readonly TOTAL_BASE_FILES_PRE_MOVE = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalBaseFilesPreMove';

    /**
     * Total number of files in the base folder post move
     */
    public static readonly TOTAL_BASE_FILES_POST_MOVE = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalBaseFilesPostMove';

    /**
     * Total number of files extracted
     */
    public static readonly TOTAL_FILES_EXTRACTED = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalFilesExtracted';

    /**
     * Difference in the total number of files moved
     */
    public static readonly TOTAL_FILES_MOVED_OFFSET = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'TotalFileMovedOffset';

    /**
     * Error code of the exception object - e.code
     */
    public static readonly ERROR_CODE = AcquisitionTelemetryPropertyNames.PROPERTY_PREFIX + 'ErrorCode';
}
