import debug from 'debug';

import { IConsoleLogger } from '../interfaces';

type TTraceType = 'info' | 'trace' | 'warn' | 'error';

/**
 * Console logger on top of debug package.
 */
export class DebugConsoleLogger implements IConsoleLogger {
    private readonly tracesCache: Record<string, debug.Debugger | undefined> = {};

    constructor(
        private readonly console: IConsoleLogger = globalThis.console,
    ) {}

    /**
     * Method to create an `debug` trace isntance with the specified trace level.
     * Caches the create traces for reuse to reduce GC churn.
     */
    private createTrace = (
        source: string,
        type: TTraceType,
        consoleFunction: (...args: any) => void,
    ): debug.Debugger => {
        const traceKey = `${source}:${type}`;
        const cachedTrace = this.tracesCache[traceKey];

        if (cachedTrace) {
            return cachedTrace;
        }

        const trace = debug(traceKey);
        trace.log = consoleFunction;

        this.tracesCache[traceKey] = trace;

        return trace;
    };

    public log: IConsoleLogger['log'] = (
        source: string,
        message: string,
        ...args: any[]
    ) => {
        return this.info(source, message, ...args);
    }

    public info: IConsoleLogger['info'] = (
        source: string,
        message: string,
        ...args: any[]
    ) => {
        this.createTrace(
            source,
            'info',
            this.console.info,
        )(message, ...args);
    }

    public debug: IConsoleLogger['debug'] = (
        source: string,
        message: string,
        ...args: any[]
    ) => {
        const method = (this.console.debug)
            ? this.console.debug
            : this.console.log;

        this.createTrace(
            source,
            'trace',
            method,
        )(message, ...args);
    }

    public warn: IConsoleLogger['warn'] = (
        source: string,
        message: string,
        ...args: any[]
    ) => {
        this.createTrace(
            source,
            'warn',
            this.console.warn,
        )(source, message, ...args);
    }

    public error: IConsoleLogger['error'] = (
        source: string,
        message: string,
        ...args: any[]
    ) => {
        this.createTrace(
            source,
            'error',
            this.console.error,
        )(source, message, ...args);
    }

    public static enable = (path: string) => {
        debug.enable(path);
    }
}
