import * as path from 'path-browserify';
import * as fs from 'fs';
import * as util from 'util';

import * as os from 'os';

import { TelemetryEventNames } from './telemetry/telemetryStrings';
import { LogLocations } from './logLocations';
import { Telemetry, FaultType as TelemetryFaultType } from '@vs/vso-telemetry';
import { TraceListener, TraceFormat, LogLevel } from '@vs/vso-logging';

const mkdirAsync = util.promisify(fs.mkdir);
const openAsync = util.promisify(fs.open);
const writeAsync = util.promisify(fs.write);

export class LogFileTraceListener extends TraceListener {
    private fileName: string | undefined;
    private writePromise = Promise.resolve();
    private canWriteLogs: boolean = true;

    public constructor(
        private readonly processName: string,
        private readonly logDirectory: string = LogFileTraceListener.defaultLogDirectory,
        private fileDescriptor?: number
    ) {
        super();
        this.flushEvents = () => {
            return this.writePromise;
        }
    }

    public static get defaultLogDirectory(): string {
        return LogLocations.clientLogFilePath;
    }

    public get logFileName(): string | undefined {
        return this.fileName;
    }

    /**
     * Opens the log file. Await this method before using the trace listener.
     */
    public async openAsync(): Promise<string | undefined> {
        try {
            await mkdirAsync(this.logDirectory);
        } catch (e) {}

        return await this.openLogFileAsync();
    }

    private openLogFileAsync = async (index: number = 0) => {
        // if 5th attempt - report to telemetry and forbit writing to local logs.
        if (index === 5) {
            this.canWriteLogs = false;
            Telemetry.sendFault(
                TelemetryEventNames.NAME_LOGS_FILE_FAILED,
                TelemetryFaultType.Error,
                'Name Log File Failed - Reached maximum number of attempts.',
            );
            return;
        }

        const datePrefix = new Date()
            .toISOString()
            .replace(/T/, '_')
            .replace(/:|-/g, '')
            .replace(/\..+/, '');

        // Ensure a unique file name, in case another log session started around the same time.
        const indexFileName = path.join(
            this.logDirectory,
            `${datePrefix}_${Date.now()}${index}_${this.processName}.log`,
        );

        try {
            const fileDescriptor: number = await openAsync(indexFileName, 'ax'); // Append, fail if exists

            this.fileDescriptor = fileDescriptor;
            this.fileName = indexFileName;
        } catch (err) {
            if (err.code === 'EEXIST') {
                // try the nex index
                await this.openLogFileAsync(index + 1);
            } else {
                this.canWriteLogs = false;
                Telemetry.sendFault(
                    TelemetryEventNames.OPEN_LOGS_FAILED,
                    TelemetryFaultType.Error,
                    `Name Log File Failed. ${err.message}`,
                    err,
                );
            }
        }

        return indexFileName;
    };

    public writeTo(line: string): void {
        fs.writeFileSync(this.fileDescriptor!, line + os.EOL);
    }

    protected writeEvent(source: string, logLevel: LogLevel, id: number, message: string, ...args: any[]): void {
        if (this.canWriteLogs === false) {
            return;
        }

        const line = TraceFormat.formatEvent(new Date(), source, logLevel, id, message, ...args);
        this.writePromise = this.writePromise!.then(() => {
            writeAsync(this.fileDescriptor!, line + os.EOL).catch((e: any) => {
                this.canWriteLogs = false;
                // do not reject if error, but log the event to telemetry
                Telemetry.sendFault(
                    TelemetryEventNames.WRITE_LOGS_FAILED,
                    TelemetryFaultType.Error,
                    e.message,
                    e,
                );
            });
        });
    }
}
