'use strict';

import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { createTerminalRenderer } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import * as tt from './types';
import { setTimeout } from 'timers';

import {
    Telemetry,
    FaultType
} from '@vs/vso-telemetry';

import {
    SessionState, 
    sessionStateTracker,
    TelemetryEventNames,
} from '@vs/liveshare-core';


export interface ITerminalEndpointBuffer {
    readonly isDisposed: () => boolean;
    readData(cancelationToken: vscode.CancellationToken): Promise<string | null>;
    writeData(data: string, cancelationToken: vscode.CancellationToken): Promise<void>;
}

export type terminalEndpointBufferFactoryType = (terminalInfo: vsls.TerminalInfo) => Promise<ITerminalEndpointBuffer>;

export interface JoinTerminalParameter {
    readonly terminalService: vsls.TerminalService;
    readonly terminalCache: tt.TerminalCache;
    readonly terminalEndpointBufferFactory: terminalEndpointBufferFactoryType;
    readonly trace: TraceSource; 
}

export async function createJoinedTerminal(
    thisParam: JoinTerminalParameter,
    terminalInfo: vsls.TerminalInfo,
    renderer?: vscode.TerminalRenderer): Promise<vscode.Terminal> {
    let terminalEntry = thisParam.terminalCache.getById(terminalInfo.id);
    if (!!terminalEntry) {
        terminalEntry.terminal.show();
        return terminalEntry.terminal;
    }

    const name = terminalInfo.options.name;

    if (!renderer) {
        renderer = createTerminalRenderer(name);
    }

    let terminal: vscode.Terminal;
    const eventRegistrations: vscode.Disposable[] = [];

    let resizeTimer: NodeJS.Timer = null;
    renderer.onDidChangeMaximumDimensions(d => {
        if (resizeTimer) {
            clearTimeout(resizeTimer);
        }

        // When the window is resized, it fires lots of resize events.
        // The timeout is a way to react only to the last event and reduce the churn.
        // 100ms is totally arbitrary. It seems good enough to produce just one event
        // after the resizing is done, soon enough for user to perceive it immediate.
        resizeTimer = setTimeout(async () => {
            clearTimeout(resizeTimer);
            resizeTimer = null;
            try {
                await thisParam.terminalService.resizeTerminalAsync(terminalInfo.id, d.columns, d.rows);
            } catch (e) {
                thisParam.trace.error(`Error resizing terminal ${e}`);
            }
        }, 100);
    }, undefined, eventRegistrations);

    thisParam.terminalService.onTerminalResized(e => {
        if (e.terminal.id === terminalInfo.id) {
            renderer.dimensions = { columns: e.terminal.options.cols, rows: e.terminal.options.rows };
        }
    }, undefined, eventRegistrations);

    const terminalEndpointBuffer = await thisParam.terminalEndpointBufferFactory(terminalInfo);
    terminal = await renderer.terminal;
    pipeTerminalStdio(terminalEndpointBuffer, renderer, thisParam.trace);

    terminal.show();

    const disposeTerminalWorker = async () => {
        eventRegistrations.forEach(r => r.dispose());
        if (sessionStateTracker.State === SessionState.Shared) {
            await thisParam.terminalService.stopTerminalAsync(terminalInfo.id);
        } else if (renderer) {
            try {
                await thisParam.terminalService.resizeTerminalAsync(terminalInfo.id, 0, 0);
            } catch {
                // Backward compat: old host may not understand resizing to 0 dimensions.
            }
        }
    };

    terminalEntry = thisParam.terminalCache.register(
        terminal,
        terminalInfo.id,
        true /* own */,
        {
            dispose: disposeTerminalWorker
        }
    );

    thisParam.terminalService.onTerminalStopped(
        (e: vsls.TerminalEventArgs) => {
            if (e.terminal.id === terminalInfo.id) {
                terminal.dispose();
            }
        },
        null /* this */,
        eventRegistrations
    );

    return terminal;
}

async function pipeTerminalStdio(endpointBuffer: ITerminalEndpointBuffer, renderer: vscode.TerminalRenderer, trace: TraceSource) {
    let disposables: vscode.Disposable[] = [];
    const cts = new vscode.CancellationTokenSource();
    try {
        let writeTask: Promise<void> = Promise.resolve();
        renderer.onDidAcceptInput(s => writeTask = writeTask.then(() => writeToEndpoint(s)), undefined, disposables);

        const terminal = await renderer.terminal;
        vscode.window.onDidCloseTerminal(t => { if (t === terminal) { cts.cancel(); } }, undefined, disposables);

        function writeToEndpoint(s: string): Promise<void> {
            if (!cts.token.isCancellationRequested) {
                return endpointBuffer.writeData(s, cts.token);
            }
        }

        while (!cts.token.isCancellationRequested) {
            const text = await endpointBuffer.readData(cts.token);
            if (text === null) {
                break;
            }

            renderer.write(text);
        }

        cts.cancel();
        await writeTask;
    } catch (e) {
        if (!cts.token.isCancellationRequested && !endpointBuffer.isDisposed()) {
            trace.error(`Error running shared terminal renderer ${e}`);
            renderer.write(`\r\n\x1b[31mError running shared terminal ${e}\x1b[0m`);
            Telemetry.sendFault(TelemetryEventNames.RUN_SHARED_TERMINAL_FAULT, FaultType.Error, null, e);
        }
    } finally {
        disposables.forEach(value => value.dispose());
    }
}

