import { ILogger, LogLevel } from '@vs/vso-logging';
import { HttpClient } from '@vs/vso-http-client';
import { assertDefined } from '@vs/vscs-utils';
import * as ssh from '@vs/vs-ssh';

import { SharedWorkspace } from './SharedWorkspace';
import {
    ISharedWorkspaceInfo,
    IWorkspaceConnectionInfo,
    IWorkspaceSessionInfo,
} from './IWorkspaceSessionInfo';
import { IConnectionOptions } from './IConnectionOptions';
import { vsls } from '@vs/vsls-contracts';
export class WorkspaceApi {
    private readonly baseUri: string;
    private readonly httpClient: HttpClient;

    public constructor(
        public readonly serviceUri: string,
        public readonly tokenProvider: () => string,
        private readonly logger: ILogger
    ) {
        assertDefined(serviceUri, 'service uri needs to be defined');

        let baseUri = serviceUri;
        if (!baseUri.endsWith('/')) {
            baseUri = baseUri + '/';
        }
        if (!baseUri.includes('api/v1.2')) {
            baseUri = baseUri + 'api/v1.2';
        }

        // We need to remove the trailing slash in the case it was directly
        // taken from an environment record
        this.baseUri = this.removeTrailingSlash(baseUri);

        this.httpClient = new HttpClient(logger);
    }

    public static async getWorkspaceSessionInfo(
        workspaceId: string,
        options: IConnectionOptions,
        logger: ILogger
    ): Promise<IWorkspaceSessionInfo> {
        logger.info(`getWorkspaceSessionInfo -> workspaceId:${workspaceId}`);
        const workspaceApi = new WorkspaceApi(
            options.liveShareEndpoint,
            () => options.token,
            logger
        );
        const [workspaceAccess, workspaceInfo] = await Promise.all([
            workspaceApi.getWorkspaceAccess(workspaceId),
            workspaceApi.getWorkspaceInfo(workspaceId),
        ]);
        const workspaceSessionInfo = {
            ...workspaceAccess,
            ...workspaceInfo,
        } as IWorkspaceSessionInfo;

        assertDefined(workspaceInfo, 'Cannot get LiveShare workspace info.');
        assertDefined(workspaceAccess, 'Cannot get LiveShare workspace access.');
        assertDefined(workspaceInfo.relaySas, 'No RelaySas token found.');

        return workspaceSessionInfo;
    }

    public async deleteWorkspace(workspaceId: string): Promise<void> {
        assertDefined(workspaceId, 'Cannot get Live Share workspaceId');
        workspaceId = workspaceId.toUpperCase();
        const url = `${this.baseUri}/workspace/${workspaceId}`;

        this.logger.log(LogLevel.Debug, `delete workspace -> ${url}`);

        await this.httpClient.delete(url, {
            headers: this.getRequestHeaders(),
        });
    }

    public async getWorkspaceInfo(workspaceId: string): Promise<IWorkspaceConnectionInfo> {
        assertDefined(workspaceId, 'Cannot get Live Share workspaceId');
        workspaceId = workspaceId.toUpperCase();
        const url = `${this.baseUri}/workspace/${workspaceId}`;

        this.logger.log(LogLevel.Debug, `get workspace info -> ${url}`);

        return await this.httpClient
            .get(url, {
                headers: this.getRequestHeaders(),
            })
            .value<IWorkspaceConnectionInfo>();
    }

    public async getWorkspaceAccess(workspaceId: string): Promise<IWorkspaceSessionInfo> {
        assertDefined(workspaceId, 'Cannot get Live Share workspaceId');
        workspaceId = workspaceId.toUpperCase();

        const url = `${this.baseUri}/workspace/${workspaceId}/user`;
        this.logger.log(LogLevel.Debug, `get workspace access -> ${url}`);

        return await this.httpClient
            .put(url, {
                headers: this.getRequestHeaders(),
            })
            .value<IWorkspaceSessionInfo>();
    }

    public async postWorkspaceInfo(workspaceInfo: any): Promise<ISharedWorkspaceInfo> {
        const url = `${this.baseUri}/workspace`;

        this.logger.log(LogLevel.Debug, `post workspace info -> ${url}`);

        return await this.httpClient
            .post(url, {
                headers: this.getRequestHeaders(),
                body: JSON.stringify(workspaceInfo),
            })
            .value<ISharedWorkspaceInfo>();
    }

    public async createInvitationLink(invitationLinkInfo: vsls.InvitationLinkInfo): Promise<any> {
        const url = `${this.baseUri}/workspace/${invitationLinkInfo.workspaceId}/link`;
        const response = await this.httpClient
            .put(url, {
                headers: this.getRequestHeaders(),
                body: JSON.stringify(invitationLinkInfo),
            })
            .value<any>();

        return response;
    }

    public async getWorkspaceUserProfile(
        workspaceId: string,
        userToken: string
    ): Promise<vsls.WorkspaceUserProfile> {
        assertDefined(workspaceId, 'Cannot get Live Share workspaceId');
        workspaceId = workspaceId.toUpperCase();

        const url = `${this.baseUri}/workspace/${workspaceId}/user`;
        this.logger.log(LogLevel.Debug, `get workspace user profile -> ${url}`);

        const workspaceUserProfile = await this.httpClient
            .get(url, {
                headers: {
                    ...this.getRequestHeaders(),
                    'User-Session-Token': userToken,
                },
            } as RequestInit)
            .value<vsls.WorkspaceUserProfile>();

        // The collaboration service's WorkspaceGetProfileResponse returns 'username'
        // vsls.WorkspaceUserProfile property has a different casing 'userName'
        if ((workspaceUserProfile as any)?.username) {
            workspaceUserProfile.userName = (workspaceUserProfile as any).username;
        }

        return workspaceUserProfile;
    }

    public static async createSshKeys(): Promise<[ssh.KeyPair, string]> {
        const rsa = ssh.SshAlgorithms.publicKey.rsaWithSha512!;
        const hostPrivateKey = await rsa.generateKeyPair();
        const hostPublicKey = (await hostPrivateKey!.getPublicKeyBytes(
            hostPrivateKey.keyAlgorithmName
        ))!.toString('base64');

        return [hostPrivateKey, hostPublicKey];
    }

    public async createSharedWorkspace(
        workspaceShareInfo: vsls.WorkspaceShareInfo
    ): Promise<SharedWorkspace> {
        const sshKeys = await WorkspaceApi.createSshKeys();

        const workspacePayload = {
            name: workspaceShareInfo.name,
            connectionMode: vsls.ConnectionMode.Relay,
            areAnonymousGuestsAllowed: workspaceShareInfo.areAnonymousGuestsAllowed,
            hostPublicKeys: [sshKeys[1]],
        };

        const workspaceInfo = await this.postWorkspaceInfo(workspacePayload);
        return {
            workspaceInfo,
            hostPrivateKeys: [sshKeys[0]],
            getWorkspaceUserProfile: (userToken: string) =>
                this.getWorkspaceUserProfile(workspaceInfo.id!, userToken),
        };
    }

    private getRequestHeaders = () => {
        return {
            Authorization: `Bearer ${this.tokenProvider()}`,
            'Cache-Control': 'no-cache',
            'Content-Type': 'application/json',
        };
    };

    private removeTrailingSlash(baseUri: string) {
        return baseUri.endsWith('/') ? baseUri.substr(0, baseUri.length - 1) : baseUri;
    }
}
