import * as vscode from 'vscode';
import { TreeViewItem} from './TreeViewItem';
import { ExtensionTreeDataProvider, TreeDataProviderContext } from './ExtensionTreeDataProvider';
import { ExtensionUtil } from '../utils/ExtensionUtil';

export abstract class TreeDataProviderBase implements ExtensionTreeDataProvider {
    private items: TreeViewItem[];
    protected isChildItemCacheDisabled = false;
    private readonly changeEventEmitter = new vscode.EventEmitter<TreeViewItem | undefined>();
    public readonly onDidChangeTreeData = this.changeEventEmitter.event;

    constructor(
        public id: string,
        public supportedContext: TreeDataProviderContext) {
    }

    public static getThemeIconPath(name: string): { light: string | vscode.Uri; dark: string | vscode.Uri } {
        return {
            dark: ExtensionUtil.getExtensionUri(`images/dark/${name}.svg`),
            light: ExtensionUtil.getExtensionUri(`images/light/${name}.svg`)
        };
    }

    protected refresh(element?: any) {
        this.changeEventEmitter.fire(element);
    }

    public getTreeItem(element: TreeViewItem): vscode.TreeItem | Thenable<vscode.TreeItem> {
        return element;
    }

    public async getChildren(element?: TreeViewItem): Promise<TreeViewItem[]> {
        if (element) {
            if (!this.items || this.isChildItemCacheDisabled) {
                this.items = await this.getChildrenItems(element);
            }

            return this.items;
        }
        
        const rootItem = await this.getRootItem();
        return rootItem ? [rootItem] : [];
    }

    public refreshItems() {
        this.items = undefined;
    }

    protected forceRefreshItems(): void {
        this.refreshItems();
        this.refresh();
    }

    protected abstract getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]>;
    protected abstract getRootItem(): Promise<TreeViewItem>;
}
