import { assert } from './coeditingUtils';
import { ITextChange, TextChange, compressConsecutiveTextChanges } from './textChange';
import { IOTAlgorithmBuffer, Edit } from './OTAlgorithm';
import { PrefixSumComputer } from './prefixSumComputer';
import { checkDebugging } from '../../utils/checkDebugging';
import { TextDocumentContentChangeEvent } from 'vscode';
import { TraceSource } from '@vs/vso-logging';

/**
 * A (0;0)-origin position
 */
export class CollabBufferPosition {
    constructor(
        public readonly line: number,
        public readonly character: number
    ) {
    }
}

class InternalEdit {
    constructor(
        public readonly offset: number,
        public readonly length: number,
        public readonly start: CollabBufferPosition,
        public readonly end: CollabBufferPosition,
        public readonly oldText: string,
        public readonly newText: string
    ) {
    }
}

class InternalOffsetEdit {
    constructor(
        public readonly index: number,
        public readonly offset: number,
        public readonly length: number,
        public readonly text: string
    ) {
    }
}

function insertIntoNewArray<T>(target: T[], insertIndex: number, insertArr: T[]): T[] {
    const before = target.slice(0, insertIndex);
    const after = target.slice(insertIndex);
    return before.concat(insertArr, after);
}

function isDanglingNewLine(text: string, start: CollabBufferPosition): boolean {
    return (text.length > 0) && (text.charCodeAt(0) === 10) /*\n*/ && ((start.line > 0) || (start.character > 0));
}


function adjustContentAndPositionForNewLineType(text: string, start: CollabBufferPosition, buffer: CollabBuffer): [string, CollabBufferPosition] {
    let beforePosition: CollabBufferPosition;
    let lineText: string;
    
    // We need the immediately previous character to see if it
    // was \n. That might be on the previous line.
    if (start.character === 0) {
        // We're at the start of the line, so need get the previous
        // line and adjust position to the previous lines last char
        lineText = buffer.getLineContent(start.line - 1);
        beforePosition = new CollabBufferPosition(start.line - 1, lineText.length - 1);
    } else {
        // We're somewhere else in the linem so we just need the
        // previous character in our buffer.
        lineText = buffer.getLineContent(start.line);
        beforePosition = new CollabBufferPosition(start.line, start.character - 1);
    }

    // That previous character was in fact a \r, so, we need to move
    // that start position in the buffer back one to accomodate
    // inserting our new line content.
    if (lineText.charCodeAt(beforePosition.character) === 13 /* \r */) {
        // the intent of vscode is to produce at least one new line
        // we need to preserve this intent in the case that our buffer
        // becomes \r\n which will not produce a new line
        start = beforePosition;
        text = '\r\n' + text;
    }

    return [text, start];
}

export class CollabBuffer implements IOTAlgorithmBuffer {
    /**
     * Split a string into lines, taking \r\n, \n or \r as possible line terminators.
     */
    public static convertStringToLines(source: string): string[] {
        const len = source.length;

        let result: string[] = [];
        let currentLine = 0;
        let lineStartOffset = 0;
        let prevChCode = 0;

        // Walk the source character by character, searching for end of line to
        // capture a whole line.
        for (let i = 0; i < len; i++) {
            const chCode = source.charCodeAt(i);

            if (chCode === 10 /* \n */) {
                result[currentLine++] = source.substring(lineStartOffset, i + 1);
                lineStartOffset = i + 1;
            } else if (prevChCode === 13 /* \r */) {
                result[currentLine++] = source.substring(lineStartOffset, i);
                lineStartOffset = i;
            }

            prevChCode = chCode;
        }


        // Mop up the last line if it's not terminated by a new line itself
        result[currentLine++] = source.substring(lineStartOffset, len + 1);
        if (prevChCode === 13) {
            result[currentLine++] = '';
        }

        return result;
    }

    public static convertVsCodeContentChangeToCollabChange(change: TextDocumentContentChangeEvent, buffer: CollabBuffer): [CollabBufferPosition, CollabBufferPosition, string] {
        let start = new CollabBufferPosition(change.range.start.line, change.range.start.character);
        let end = new CollabBufferPosition(change.range.end.line, change.range.end.character);
        let text = change.text;

        // In case the vs code buffer thinks \n are line endings, and we have a "dangling" \r,
        // prevent that, our (line;col)<->offset will deviate from the vs code one
        if (isDanglingNewLine(text, start)) {
            [text, start] = adjustContentAndPositionForNewLineType(text, start, buffer);
        }

        return [start, end, text];
    }

    private lines: string[];
    private lineStarts: PrefixSumComputer;

    private recording: boolean = false;
    private recordedEdits: ITextChange[] | null = null;
    private unexpandedRecordedEdits: ITextChange[] | null = null;

    private recordEditsForUndo = false;
    private recordedUndoEdits: ITextChange[] | null = null;

    constructor(initialTextBuffer: string, private readonly trace: TraceSource) {
        this.lines = CollabBuffer.convertStringToLines(initialTextBuffer);
        const lineStartValues = new Uint32Array(this.lines.length);
        
        // Maps the buffer positions into lines to know what offset the line
        // started
        this.lines.forEach((line, index) => {
            lineStartValues[index] = line.length;
        });
        
        this.lineStarts = new PrefixSumComputer(lineStartValues);
    }

    private _validatePosition(position: CollabBufferPosition): CollabBufferPosition {
        let { line, character } = position;

        // Clamp the lines to a valid range. We can't have negative lines, so
        // assume they really mean't the beginning of the buffer.
        if (line < 0) {
            line = 0;
            character = 0;
            return new CollabBufferPosition(line, character);
        }

        // If it was past or at the end, we want to bring it into the last valid
        // position in the buffer
        if (line >= this.lines.length) {
            line = this.lines.length - 1;
            character = this.lines[line].length;
            return new CollabBufferPosition(line, character);
        }

        // Constrain the character to no earlier than the beginning of the line
        let maxCharacter = this.lines[line].length;
        if (character < 0) {
            character = 0;
            return new CollabBufferPosition(line, character);
        }

        // Make sure it's not off the end of the buffer either
        if (character > maxCharacter) {
            character = maxCharacter;
            return new CollabBufferPosition(line, character);
        }

        // We were clearly within some valid range, so just return it
        return position;
    }

    /**
     * Convert (ln,ch) to a character offset from the begining of the raw string
     */
    public offsetAt(position: CollabBufferPosition): number {
        position = this._validatePosition(position);
        return this.lineStarts.getAccumulatedValue(position.line - 1) + position.character;
    }

    /**
     * Convert offset to a line & character number
     */
    public positionAt(offset: number): CollabBufferPosition {
        offset = Math.floor(offset);
        offset = Math.max(0, offset);

        const out = this.lineStarts.getIndexOf(offset);
        const lineMaxChar = this.lines[out.index].length;

        // Ensure we return a valid position
        return new CollabBufferPosition(out.index, Math.min(out.remainder, lineMaxChar));
    }

    /**
     * Get the content of the buffer.
     */
    public getContent(): string {
        return this.lines.join('');
    }

    /**
     * Get the content of a line (including EOL)
     */
    public getLineContent(line: number): string {
        assert(line < this.lines.length, 'Line content requested outside of buffer');
        return this.lines[line];
    }

    /**
     * Get the maximum legal offset for the buffer.
     */
    public getMaximumOffset(): number {
        return this.lineStarts.getAccumulatedValue(this.lines.length);
    }

    public startCapturingEditsFromUndoing(): void {
        this.recordEditsForUndo = true;
        this.recordedUndoEdits = [];
    }

    public stopCapturingEditsFromUndoing(): ITextChange[] | null {
        this.recordEditsForUndo = false;
        let backEdits = this.recordedUndoEdits;
        this.recordedUndoEdits = null;
        return backEdits;
    }

    /**
     * Begin recording changes applied to the buffer.
     * To be used in conjuction with `endRecording` to extract a single set of
     * edits that were applied to the buffer in the intervening period.
     */
    public beginRecording(): void {
        this.recording = true;
        this.recordedEdits = null;
        this.unexpandedRecordedEdits = null;
    }

    /**
     * End recording changes applied to the buffer.
     * Returns the effects of all edits applied to the buffer as a single set (i.e. merged).
     */
    public endRecording(): [ITextChange[], ITextChange[]] {
        const r = this.recordedEdits || [];
        const ur = this.unexpandedRecordedEdits || [];
        this.recordedEdits = null;
        this.unexpandedRecordedEdits = null;
        this.recording = false;
        return [r, ur];
    }

    private _convertToInternalEditWithValidation(start: CollabBufferPosition, end: CollabBufferPosition, text: string): InternalEdit {
        start = this._validatePosition(start);
        end = this._validatePosition(end);

        const startOffset = this.offsetAt(start);
        const endOffset = this.offsetAt(end);
        const oldText = this._getContentInRange(start, end);

        const edit = new InternalEdit(
            startOffset, endOffset - startOffset,
            start, end,
            oldText, text
        );

        return edit;
    }

    private _convertInternalEditsToTextChange(edits: InternalEdit[]): [ITextChange[], ITextChange[], InternalEdit[]] {
        // Handle CRLF special cases by expanding the edits around CR or LF
        const expandedEdits = this._expandCRLFEdits(edits);

        // Create changes and (ln;ch) edits
        let changes: ITextChange[] = new Array<ITextChange>(expandedEdits.length);
        let unexpandedChanges: ITextChange[] = new Array<ITextChange>(expandedEdits.length);
        let expandedDeltaOffset = 0;
        let unexpandedDeltaOffset = 0;

        for (let i = 0; i < expandedEdits.length; i++) {
            const edit = edits[i];
            const expandedEdit = expandedEdits[i];
            changes[i] = new TextChange(expandedEdit.offset, expandedEdit.oldText, expandedEdit.offset + expandedDeltaOffset, expandedEdit.newText);
            unexpandedChanges[i] = new TextChange(edit.offset, edit.oldText, edit.offset + unexpandedDeltaOffset, edit.newText);
            expandedDeltaOffset += expandedEdit.newText.length - expandedEdit.length;
            unexpandedDeltaOffset += edit.newText.length - edit.length;
        }

        return [changes, unexpandedChanges, expandedEdits];
    }

    public convertCollabufferChangeToITextChange(start: CollabBufferPosition, end: CollabBufferPosition, text: string): ITextChange {
        const edit = this._convertToInternalEditWithValidation(start, end, text);
        const [changes, unexpandedChanges, edits] = this._convertInternalEditsToTextChange([edit]);
        return changes[0];
    }

    /**
     * Apply a single (ln,ch) edit
     */
    public applyLocalEdit(start: CollabBufferPosition, end: CollabBufferPosition, text: string): void {
        const edit = this._convertToInternalEditWithValidation(start, end, text);
        this._applyInternalEdits([edit]);
    }

    /**
     * Apply N (offset,len) edits based on the current buffer state.
     */
    private _convertEditsToInternalEdits(editsToConvert: Edit[]): InternalEdit[] {
        let offsetEdits: InternalOffsetEdit[] = editsToConvert.map((edit, index) => {
            return new InternalOffsetEdit(index, edit.position, edit.length, edit.text);
        });

        // Sort edits ascending by offset and also check that:
        //  - they are within buffer bounds
        //  - they are not overlapping
        offsetEdits = CollabBuffer._sortAndValidateEdits(this.getMaximumOffset(), offsetEdits);

        // Merge adjacent (touching) edits
        offsetEdits = CollabBuffer._mergeAdjacentEdits(offsetEdits);

        const realizedEdits: InternalEdit[] = offsetEdits.map((edit) => {
            const startPosition = this.positionAt(edit.offset);
            const endPosition = this.positionAt(edit.offset + edit.length);
            const oldText = this._getContentInRange(startPosition, endPosition);

            return new InternalEdit(
                edit.offset,
                edit.length,
                startPosition,
                endPosition,
                oldText,
                edit.text
            );
        });

        return realizedEdits;
    }

    public transformEditsToTextChanges(editsToTransform: Edit[]): ITextChange[] {
        const internalEdits = this._convertEditsToInternalEdits(editsToTransform);
        const [changes, _, __] = this._convertInternalEditsToTextChange(internalEdits);
        return changes;
    }

    public applyRemoteEdits(editsToApply: Edit[]): ITextChange[] {
        const realizedEdits = this._convertEditsToInternalEdits(editsToApply);
        return this._applyInternalEdits(realizedEdits);
    }

    private static _sortAndValidateEdits(maxPosition: number, edits: InternalOffsetEdit[]): InternalOffsetEdit[] {
        if (checkDebugging()) {
            // Validate that edits are within bounds
            edits.forEach((edit) => {
                assert(edit.offset >= 0, 'invalid position');
                assert(edit.offset <= maxPosition, 'invalid position');
                assert(edit.length >= 0, 'invalid length');
                assert(edit.offset + edit.length <= maxPosition, 'invalid length');
            });
        }

        // Sort edits
        edits.sort(CollabBuffer._compareEdits);

        if (checkDebugging()) {
            // Check that there are no overlapping edits.
            edits.forEach((currentEdit, index, source) => {
                // Can't compare a previous item if there is infact no previous item
                if (index === 0) {
                    return;
                }

                const previousEdit = source[index - 1];
                if (previousEdit.offset + previousEdit.length > currentEdit.offset) {
                    assert(false, 'invalid edits: overlapping');
                }
            });
        }

        return edits;
    }

    private static _compareEdits(a: InternalOffsetEdit, b: InternalOffsetEdit): number {
        const posDelta = a.offset - b.offset;
        if (posDelta === 0) {
            return a.index - b.index;
        }
        return posDelta;
    }

    private static _mergeAdjacentEdits(edits: InternalOffsetEdit[]): InternalOffsetEdit[] {
        if (edits.length <= 1) {
            return edits;
        }

        let result: InternalOffsetEdit[] = [];
        let resultLen = 0;
        let previousEdit = edits[0];

        for (let i = 1, len = edits.length; i < len; i++) {
            const currentEdit = edits[i];

            if ((previousEdit.offset + previousEdit.length) === currentEdit.offset) {
                // Accumulate adjacent edits into one, larger edit. Note, that
                // this will keep going until it finds a break
                previousEdit = new InternalOffsetEdit(
                    previousEdit.index,
                    previousEdit.offset,
                    previousEdit.length + currentEdit.length,
                    previousEdit.text + currentEdit.text
                );

                continue;
            }

            // Non adjacent edit, start a new edit.
            result[resultLen++] = previousEdit;
            previousEdit = currentEdit;
        }

        result[resultLen++] = previousEdit;

        return result;
    }

    private _getContentInRange(start: CollabBufferPosition, end: CollabBufferPosition): string {
        // It's on the same line, we can just service from the specific line directly
        if (start.line === end.line) {
            return this.lines[start.line].substring(start.character, end.character);
        }

        let result: string[] = [];
        let resultLen = 0;
        
        // Approach this by accumulating the start &  tails as the substrings
        // and copy the "middle" wholesale (since it's just hole lines)
        result[resultLen++] = this.lines[start.line].substr(start.character);
        
        for (let i = start.line + 1; i < end.line; i++) {
            result[resultLen++] = this.lines[i];
        }

        result[resultLen++] = this.lines[end.line].substr(0, end.character);

        return result.join('');
    }

    private _expandCRLFEdits(edits: InternalEdit[]): InternalEdit[] {
        let result: InternalEdit[] = [];
        let resultLen = 0;

        for (let i = 0, len = edits.length; i < len; i++) {
            const edit = edits[i];
            let offset = edit.offset;
            let length = edit.length;
            let startPosition = edit.start;
            let endPosition = edit.end;
            let oldText = edit.oldText;
            let newText = edit.newText;

            if (offset > 0) {
                let beforePosition: CollabBufferPosition;
                let lineText: string;

                if (startPosition.character === 0) {
                    lineText = this.lines[startPosition.line - 1];
                    beforePosition = new CollabBufferPosition(startPosition.line - 1, lineText.length - 1);
                } else {
                    lineText = this.lines[startPosition.line];
                    beforePosition = new CollabBufferPosition(startPosition.line, startPosition.character - 1);
                }

                if (lineText.charCodeAt(beforePosition.character) === 13 /* \r */) {
                    // include the replacement of \r in the edit
                    offset--;
                    length++;
                    newText = '\r' + newText;
                    oldText = '\r' + oldText;
                    startPosition = beforePosition;
                }
            }

            const endLineText = this.lines[endPosition.line];
            if (endPosition.character < endLineText.length && endLineText.charCodeAt(endPosition.character) === 10 /* \n */) {
                // include the replacement of \n in the edit
                length++;
                newText = newText + '\n';
                oldText = oldText + '\n';
                endPosition = new CollabBufferPosition(endPosition.line + 1, 0);
            }

            result[resultLen++] = new InternalEdit(offset, length, startPosition, endPosition, oldText, newText);
        }

        return result;
    }

    private _applyInternalEdits(edits: InternalEdit[]): ITextChange[] {
        // Buffer contents should only ever be modified via this method
        this.trace.verbose(`CollabBuffer._applyInternalEdits ${JSON.stringify(edits.map(e => ({ start: e.start, end: e.end, length: e.length, offset: e.offset, newText: e.newText.length, oldText: e.oldText.length })))}`);

        const [changes, unexpandedChanges, expandedEdits] = this._convertInternalEditsToTextChange(edits);

        for (let i = expandedEdits.length - 1; i >= 0; i--) {
            const edit = expandedEdits[i];
            this._delete(edit.start, edit.end);
            this._insert(edit.start, edit.newText);
        }

        if (this.recording) {
            this.recordedEdits = compressConsecutiveTextChanges(this.recordedEdits || [], changes);
            this.unexpandedRecordedEdits = compressConsecutiveTextChanges(this.unexpandedRecordedEdits || [], unexpandedChanges);
        }

        if (this.recordEditsForUndo) {
            this.recordedUndoEdits = compressConsecutiveTextChanges(this.recordedUndoEdits || [], changes);
        }

        return changes;
    }

    private _setLineText(line: number, newValue: string): void {
        this.lines[line] = newValue;
        this.lineStarts.changeValue(line, newValue.length);
    }

    private _delete(start: CollabBufferPosition, end: CollabBufferPosition): void {
        if (start.line === end.line) {
            if (start.character === end.character) {
                // Nothing to delete
                return;
            }

            // Delete text on the affected line
            let lineText = this.lines[start.line];
            this._setLineText(
                start.line,
                lineText.substring(0, start.character) + lineText.substring(end.character)
            );
            return;
        }

        // Take remaining text on last line and append it to remaining text on first line
        let firstLineText = this.lines[start.line];
        let lastLineText = this.lines[end.line];
        this._setLineText(
            start.line,
            firstLineText.substring(0, start.character) + lastLineText.substring(end.character)
        );

        // Delete middle lines
        this.lines.splice(start.line + 1, end.line - start.line);
        this.lineStarts.removeValues(start.line + 1, end.line - start.line);
    }

    private _insert(position: CollabBufferPosition, insertText: string): void {

        if (insertText.length === 0) {
            // Nothing to insert
            return;
        }

        let insertLines = CollabBuffer.convertStringToLines(insertText);
        if (insertLines.length === 1) {
            // Inserting text on one line
            let lineText = this.lines[position.line];
            this._setLineText(position.line,
                lineText.substring(0, position.character)
                + insertLines[0]
                + lineText.substring(position.character)
            );
            return;
        }

        // Append overflowing text from first line to the end of text to insert
        insertLines[insertLines.length - 1] += this.lines[position.line].substring(position.character);

        // Delete overflowing text from first line and insert text on first line
        this._setLineText(
            position.line,
            this.lines[position.line].substring(0, position.character) + insertLines[0]
        );

        // Remove first element that was already handled
        insertLines.shift();

        // Insert new lines & store lengths
        let newLengths = new Uint32Array(insertLines.length);
        for (let i = 0; i < insertLines.length; i++) {
            newLengths[i] = insertLines[i].length;
        }

        this.lines = insertIntoNewArray(this.lines, position.line + 1, insertLines);
        this.lineStarts.insertValues(position.line + 1, newLengths);
    }
}