
import { assertDefined } from './asserts/assertDefined';
import { Signal } from '../components/Signal';
import { defer } from './defer';

type TAnyFun<K> = (...args: any[]) => Promise<K>;

/**
 * Utility to run an asynchronous function and reuse
 * the currently running version of it, if present.
 */
export const withCache = <K extends any, T extends TAnyFun<K> = TAnyFun<K>>(
    fn: T,
): T => {
    let runningSignal: Signal<K> | undefined;

    const res = async (
        ...args: Parameters<T>
    ): Promise<K> => {
        if (runningSignal && !runningSignal.isFulfilled) {
            return await runningSignal.promise;
        }

        runningSignal = new Signal<K>();

        /**
         * Defer function execution so we can return the signal promise
         * that will resolve to the result of the original function.
         */
        defer(async () => {
            assertDefined(
                runningSignal,
                'No running signal is defined.',
            );

            try {
                const result = await fn(...args);
                runningSignal.resolve(result);
            } catch (e) {
                runningSignal.reject(e);
            }
        }, 1);

        return await runningSignal.promise;
    };

    return res as T;
};
