import { ILogger } from '@vs/vso-logging';
import * as rpc from 'vscode-jsonrpc';

import { VscodeActivityProvider } from './VscodeActivityProvider';
import { VscodeSessionStatus } from './VscodeSessionStatus';

/**
 * This class will expose a mechanism to see if the liveshare extension
 * has had any activity work giving a timeout value.
 */
export class VscodeSessionStatusProvider extends VscodeActivityProvider {
    private readonly statusChangedEvent = new rpc.Emitter<VscodeSessionStatus>();
    private currentActivityStatus: boolean = false;
    private resetStatusTimerId: NodeJS.Timer | null = null;

    public constructor(trace: ILogger, private readonly activityTimeout: number) {
        super(trace.createChild('session-status-provider'));

        this.onActivity();
    }

    public get sessionStatus(): VscodeSessionStatus {
        return this.currentActivityStatus ? VscodeSessionStatus.Active : VscodeSessionStatus.Idle;
    }

    public get onSessionStatusChanged(): rpc.Event<VscodeSessionStatus> {
        return this.statusChangedEvent.event;
    }

    /**
     * Reset the activity status causing to report a 'true' activity status
     */
    public reset(): void {
        if (!this.currentActivityStatus) {
            this.currentActivityStatus = true;
            this.statusChangedEvent.fire(VscodeSessionStatus.Active);
        }

        if (this.resetStatusTimerId) {
            clearTimeout(this.resetStatusTimerId);
            this.resetStatusTimerId = null;
        }

        this.resetStatusTimerId = setTimeout(() => {
            this.currentActivityStatus = false;
            this.statusChangedEvent.fire(VscodeSessionStatus.Idle);
        }, this.activityTimeout);
    }

    public async onActivity(): Promise<void> {
        if (this.statusChangedEvent) {
            this.reset();
        }
    }
}
