import { Disposable, CancellationToken } from 'vscode';
import * as vscode from 'vscode';
import { EventEmitter } from 'events';
import { ContactServiceManager, SuggestedContactsModel } from './ContactServiceManager';
import { ContactModelApi } from './ContactModelApi';
import { traceSource as trace, traceSource } from '@vs/vscode-command-framework';
import { TraceSource, TraceFormat } from '@vs/vso-logging';

import { IRpcClientProxy, RpcProxy, ServiceInfo } from '@vs/vso-rpc';
import { Mutex } from '@vs/vscs-utils';
import { registerGitProvider } from './providers/GitProvider';
import { registerSelfInviteProvider } from './providers/SelfInviteProvider';

import { IPresenceStatusProvider } from './IPresenceStatusProvider';
import { IdlePresenceStatus } from './IdlePresenceStatus';
import { SessionStateStatusProvider } from './SessionStateStatusProvider';

import  {
    CommandId,
    CommandContext,
    SessionState,
    sessionStateTracker,
    SessionStateChangedEventArgs,
    workspaceSessionInfoTracker,
    ExtensionUtil,
    IRpcServices,
    SettingKeys,
    Settings,
    IContactModel,
    IContactManager,
    InviteLinkReceived,
    ContactManagerEvents,
    ContactServiceEvents,
    IDependencies,
} from '@vs/liveshare-core';

import { vsls, contactProtocol } from '@vs/vsls-contracts';

export enum PublishProperties {
    LiveshareStatus = 'liveshareStatus',
    WorkspaceName = 'workspaceName',
}

const inviteStatusChangedMessageType = 'inviteStatusChanged';
const onInviteStatusEventName = 'onInviteStatusChanged';
const preferedPresenceProviderIdKey = 'liveshare.preferedPresenceProviderId';

const isPublishWorkspaceInfoEnabled = (): boolean => {
    return Settings.get<boolean>(SettingKeys.publishWorkspaceInfo) === true;
};

class ContactManager extends EventEmitter implements IContactManager {
    private static singleton: ContactManager;
    private trace: TraceSource;

    private recentContactsPresenceRequests = new RequestPresenceContactHelper();
    private recentContacts: Array<RecentContact> = [];
    private aggregatedSuggestedUsers: Array<ContactModelApi> = [];
    private suggestedContactPresenceRequests = new RequestPresenceContactHelper();

    private suggestedUserByProvider: {[key: string]: SuggestedContactsModel} = {};

    private updateRecentContactsInProgress = new Mutex();
    private updateSuggestedContactsInProgress = new Mutex();

    private authCoreService: vsls.AuthenticationCoreService;

    private requestContactsResults = new Set<RequestContactsImpl>();
    private invitedContactsMap = new Map<string, {
        contact: IContactModel,
        status: vsls.InviteContactStatus
    }>();
    private internalEmitter: EventEmitter = new EventEmitter();
    private publishedPresenceStatus: contactProtocol.PresenceStatus;

    // the prefered presence provider
    private preferedPresenceProvider: ContactServiceManager;

    private supportMultiplePresenceProviders = false;
    // all our contact protocol providers
    public serviceProviders: Array<ContactServiceManager> = [];

    // all our presence status providers
    public presenceStatusProviders: Array<IPresenceStatusProvider> = [];

    public static get Instance(): ContactManager {
        if (!ContactManager.singleton) {
            ContactManager.singleton = new ContactManager();
        }

        return ContactManager.singleton;
    }

    public initialize(dependencies: IDependencies): Promise<void> {
        return this._initialize(
            dependencies.rpcClient(),
            dependencies.authService(),
            dependencies,
            () => {
                return Promise.resolve(Array.from(dependencies.workspaceServices().registeredServices)); 
            });
    }

    private async _initialize(
        rpcClient: IRpcClientProxy,
        authCoreService: vsls.AuthenticationCoreService,
        rpcServices: IRpcServices,
        sessionContextServicesCallback: () => Promise<string[]>): Promise<void> {
        // Create our trace source
        this.trace = traceSource.withName('Contact.Manager');

        this.authCoreService = authCoreService;
        // Note: fire the 'ready' event when the first provider is being registered
        // we may add in the future more restricted conditions
        this.once(ContactManagerEvents.ProviderAdded, () => {
            this.emit(ContactManagerEvents.Ready);
        });

        // Supported commands
        await ExtensionUtil.tryRegisterCommand(CommandId.removeInvitedContactFromFileTreeExplorer, this.removeInvitedContact, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.removeInvitedContactFromActivityBar, this.removeInvitedContact, this, /* isEditorCommand */ false);

        const contactServicePrefix = 'contactService-';

        const contactServiceSearch = async (services: string[]) => {
            const contactServices = services.filter(s => s.startsWith(contactServicePrefix));
            for (let serviceName of contactServices) {
                const serviceInfo: ServiceInfo<contactProtocol.ContactServiceProvider> = {
                    name: serviceName,
                    methods: contactProtocol.ContactServiceProvider.methods,
                    events: contactProtocol.ContactServiceProvider.events,
                };

                const proxyClient = RpcProxy.create(serviceInfo, rpcClient, trace.withName(vsls.TraceSources.ClientRpcContact));
                await this.registerAndInitializeServiceProvider(serviceName.substr(contactServicePrefix.length), proxyClient);    
            };
        };

        // when the rpc connection is completed let's look on contact service(s)
        rpcClient.ensureConnectionAsync().then(async () => {
            const services = await sessionContextServicesCallback();
            // if an rpc based user presence service is available then initialize
            contactServiceSearch(services);
        }).catch(err => {
            trace.info('Failed to get context services:' + err);
        });

        // also listen for future service addition
        rpcServices.workspaceService().onServicesChanged(e => {
            if (e.changeType === vsls.CollectionChangeType.Add) {
                contactServiceSearch(e.serviceNames);
            }
        });

        rpcServices.workspaceUserService().onWorkspaceSessionChanged(async e => {
            if ((e.changeType === vsls.WorkspaceSessionChangeType.Joined || e.changeType === vsls.WorkspaceSessionChangeType.Unjoined) && !e.userProfile.isAnonymous) {
                if (e.changeType === vsls.WorkspaceSessionChangeType.Joined) {
                    await this.addUserProfile(e.userProfile);
                }
                // attempt to cleanup our existing invited contacts
                // TODO: the matching algorithm would work if the invited contact is using the liveshare identity
                // or we found a match on the vsls.Contact.emails === UserProfile.emails (currently only 1)
                const invitedContactStatus = Array.from(this.invitedContactsMap.values()).find(c => c.contact.id === e.userProfile.id || c.contact.contact.email === e.userProfile.email);
                if (invitedContactStatus) {
                    this.setInviteStatus(invitedContactStatus.contact.id, vsls.InviteContactStatus.None);
                }
            }
        });

        let isSignedIn = false;
        const onSignedStateChanged = (newState: boolean, msg: string) => {
            isSignedIn = newState;
            this.trace.verbose(`->loadRecentCollaborators:${msg}`);
            this.loadRecentCollaborators(newState);
        };

        sessionStateTracker.onStateChanged(async (e: SessionStateChangedEventArgs) => {
            this.trace.verbose(`->onStateChanged state:${e.newState}`);

            if (e.newState === SessionState.Joined) {
                const hostUser = Object.values(workspaceSessionInfoTracker.workspaceSessionInfo.sessions).find(u => u.isHost);
                if (hostUser) {
                    await this.addUserProfile(hostUser);
                }
            } 
            
            if (e.newState === SessionState.SignedOut) {
                onSignedStateChanged(false, 'signedOut');
            } else if (e.newState >= SessionState.SignedIn && !isSignedIn) {
                onSignedStateChanged(true, 'signedIn');
                // if we are returning from a 'Shared' state we always want to cleanup our invited contacts
                if (e.newState === SessionState.SignedIn) {
                    this.invitedContactsMap.clear();
                }
            }

            // update properties
            const properties: any = {};
            properties[PublishProperties.LiveshareStatus] = e.newState;
            await this.publishProperties(properties);
        });

        this.trace.verbose(`->initialize state:${sessionStateTracker.State}`);

        // if during initialize we are already signed in
        if (sessionStateTracker.State >= SessionState.SignedIn) {
            onSignedStateChanged(true, 'initialize');
        }

        // register all the factory providers
        const registerCallback: (id: string, provider: contactProtocol.ContactServiceProvider) => void = (id, provider) => this.registerContactProvider(id, provider);
        registerGitProvider(registerCallback, this.trace);
        registerSelfInviteProvider(authCoreService, registerCallback, this.trace);

        // initial context
        await this.updateContexts();

        // Create the Idle auto presence support
        const activityTimeout = Settings.get<number>(SettingKeys.activityTimeout);
        this.registerPresenceStatusProvider(new IdlePresenceStatus(this.trace, activityTimeout));
        // Create the liveshare session status support
        this.registerPresenceStatusProvider(new SessionStateStatusProvider());
    }

    public get isPublishEnabeld() {
        // Note: we may later consider an setting ore gesture that would allow a user
        // to disable publishing their data
        return true;
    }

    public registerPresenceStatusProvider(provider: IPresenceStatusProvider): void {
        this.presenceStatusProviders.push(provider);
        provider.onStatusChanged(e => this.onPresenceStatusProviderChanged(provider, e));
    }

    private async initializeProvider(
        contactServiceManager: ContactServiceManager
    ) {
        const properties: any = {};
        properties[PublishProperties.LiveshareStatus] = sessionStateTracker.State;
        if (isPublishWorkspaceInfoEnabled()) {
            properties[PublishProperties.WorkspaceName] = vscode.workspace.name;
        }

        await contactServiceManager.initialize(this.isPublishEnabeld, {
            status: contactProtocol.PresenceStatus.Available,
            properties
        });
        
        this.updatePreferedPresenceProvider(contactServiceManager);
        if (contactServiceManager.capabilites.supportsContactPresenceRequest) {
            await this.updateAllContacts();
        }

        await this.updateContexts();     
    }

    private registerServiceProvider(
        serviceId: string, contactService: contactProtocol.ContactServiceProvider
    ): ContactServiceManager  {
        this.trace.info(`registerContactProvider-> serviceId:${serviceId}`);

        const contactServiceManager = new ContactServiceManager(serviceId, contactService, this);
        contactServiceManager.addListener(ContactServiceEvents.Initialized, () => this.fireContactsChanged());
        contactServiceManager.addListener(ContactServiceEvents.ContactsChanged, () => this.fireContactsChanged());
        contactServiceManager.addListener(ContactServiceEvents.AvailableUsersChanged, () => this.onAvailableUsersChanged());
        contactServiceManager.addListener(ContactServiceEvents.SelfContactChanged, () => this.onSelfUserChangedNotification(contactServiceManager));
        contactServiceManager.addListener(ContactServiceEvents.InviteLinkReceived, e => this.onInviteLinkReceived(contactServiceManager, <contactProtocol.InviteReceivedNotification>e));
        contactServiceManager.addListener(ContactServiceEvents.MessageReceived, e => this.onMessageReceived(<contactProtocol.MessageReceivedNotification>e));
        contactServiceManager.addListener(ContactServiceEvents.SuggestedUsersUpdate, e => this.onSuggestedUsersUpdate(contactServiceManager, <SuggestedContactsModel>e));
        contactServiceManager.addListener(ContactServiceEvents.ContactsChangedNotification, e => this.onContactsChangedNotification(contactServiceManager, <{ [key: string]: contactProtocol.ContactPropertyValueChanged[]; }>e));
        contactServiceManager.addListener(ContactServiceEvents.ContactPropertyChangedNotification, e => this.onContactPropertiesChangedNotification(<contactProtocol.ContactPropertiesChangedNotification>e));

        contactServiceManager.addListener(ContactServiceEvents.SignedStateChanged, e => this.onPresenceSignedStatusNotification(contactServiceManager));
        contactServiceManager.addListener(ContactServiceEvents.CapabilitiesChanged, e => this.onCapabilitiesChanged(contactServiceManager, e));
        contactServiceManager.addListener(ContactServiceEvents.AuthenticationRequired, e => this.onAuthenticationRequired(contactServiceManager));
        this.serviceProviders.push(contactServiceManager);
        return contactServiceManager;
    }

    public async registerAndInitializeServiceProvider(
        serviceId: string, contactService: contactProtocol.ContactServiceProvider
    ): Promise<ContactServiceManager> {
        const contactServiceManager = this.registerServiceProvider(serviceId, contactService);
        await this.initializeProvider(contactServiceManager);
        this.emit(ContactManagerEvents.ProviderAdded, contactServiceManager);
        return contactServiceManager;
    }

    public registerContactProvider(
        serviceId: string, contactService: contactProtocol.ContactServiceProvider
    ): Disposable {
        const contactServiceManager = this.registerServiceProvider(serviceId, contactService);

        this.initializeProvider(contactServiceManager).catch((reason) => {
            this.trace.error(`Failed to register contact provider:${serviceId}`, reason);
        });

        this.emit(ContactManagerEvents.ProviderAdded, contactServiceManager);

        return new Disposable(() => {
            // The returned Disposable just removes the provider from the list.
            // TODO: Implement a more complete unregistration of a contact service provider.
            const index = this.serviceProviders.indexOf(contactServiceManager);
            if (index >= 0) {
                this.serviceProviders.splice(index, 1);
            }
        });
    }

    public async dispose(): Promise<void> {
        for (let disposable of this.serviceProviders.splice(0, this.serviceProviders.length)) {
            await disposable._Dispose();
        }
    }

    public get selectedPreferedProviderId(): string {
        return Settings.getMemento<string>(preferedPresenceProviderIdKey);
    }

    public async setPreferedPresenceProvider(provider: ContactServiceManager): Promise<void> {
        // always save the prefered id into storage
        Settings.saveMemento(preferedPresenceProviderIdKey, provider.serviceId);

        if (this.preferedPresenceProvider ===  provider) {
            return;
        }

        this.preferedPresenceProvider = provider;
        this.updatePreferedProviderSelfStatus();
        this.updatePreferedProviderSignedStatus();
        await this.updateAllContacts();
    }

    public isRecentContat(contact: IContactModel): boolean {
        return this.recentContacts.findIndex(c => c.contactModel.id === contact.id) !== -1;
    }

    public isSuggestedContat(contact: IContactModel): boolean {
        return this.aggregatedSuggestedUsers.findIndex(c => c.id === contact.id) !== -1;
    }

    public getServiceManager(serviceId: string): ContactServiceManager {
        return this.serviceProviders.find(s => s.serviceId === serviceId);
    }

    public getSuggestedUsers(filter?: (contact: IContactModel) => boolean): Array<IContactModel> {
        if (filter) {
            return this.aggregatedSuggestedUsers.filter(filter);
        }

        return this.aggregatedSuggestedUsers;
    }

    public getRecentContacts(filter?: (contact: IContactModel) => boolean): Array<IContactModel> {
        const recentContactModels = this.recentContacts.map(i => i.contactModel);
        if (filter) {
            return recentContactModels.filter(filter);
        }

        return recentContactModels;
    }

    public getAllAvailableContacts(filter?: (contact: IContactModel) => boolean): Array<IContactModel> {
        const result: Array<IContactModel> = [];
        this.serviceProviders.forEach(s => {
            let contacts = s.availableUsers;
            if (filter) {
                contacts = contacts.filter(filter);
            }
            result.push(...contacts);
        });

        return result;
    }

    public get isDoNotDisturbState(): boolean {
        return this.serviceProviders.find(sp => sp.selfUser && sp.selfUser.contact.status === contactProtocol.PresenceStatus.DoNotDisturb) ? true : false;
    }

    public get selfContact() {
        return this.preferedPresenceProvider?.selfUser;
    }

    public get presenceStatus(): contactProtocol.PresenceStatus {
        if (this.preferedPresenceProvider && this.preferedPresenceProvider.selfUser) {
            return this.preferedPresenceProvider.selfUser.contact.status;
        }

        return contactProtocol.PresenceStatus.Unknown;
    }

    public async signOut(): Promise<void> {
        if (this.preferedPresenceProvider) {
            await this.preferedPresenceProvider.signOut();
        }
    }

    public async signIn(): Promise<void> {
        if (this.preferedPresenceProvider) {
            await this.preferedPresenceProvider.signIn();
        }
    }

    public async publishPresence(status: contactProtocol.PresenceStatus): Promise<void> {
        // Note: we are usign the 'Available' state as a way to auto reset the status
        if (status === contactProtocol.PresenceStatus.Available) {
            this.publishedPresenceStatus = undefined;
            this.presenceStatusProviders.forEach(p => p.reset());
            status = this.getPresenceStatusFromProviders();
        } else {
            this.publishedPresenceStatus = status;
        }

        await this.publishPresenceInternal(status, {
            allowInvites: Settings.get<string>(SettingKeys.allowInvites),
        });
    }

    public async publishProperties(properties: { [key: string]: any; }): Promise<void> {
        await this.publishPresenceInternal(contactProtocol.PresenceStatus.Unknown, properties);
    }

    public get supportedPresenceStatus(): contactProtocol.PresenceStatus[] {
        // see if the prefered presence provider
        if (this.preferedPresenceProvider &&
            this.preferedPresenceProvider.capabilites &&
            this.preferedPresenceProvider.capabilites.supportedPresenceStatus) {
            return this.preferedPresenceProvider.capabilites.supportedPresenceStatus;
        }

        return [
            contactProtocol.PresenceStatus.Available,
            contactProtocol.PresenceStatus.Busy,
            contactProtocol.PresenceStatus.DoNotDisturb,
            contactProtocol.PresenceStatus.Away
        ];
    }

    public async searchContacts(queryOptions: contactProtocol.SearchContactProperty[], maxCount?: number, cancellationToken?: CancellationToken): Promise<IContactModel[]> {
        const tasks = this.serviceProviders.filter(s => s.capabilites && s.capabilites.supportsSearchContacts).map(async s => await s.searchContactsRequest(queryOptions, maxCount, cancellationToken));
        const allResults = await Promise.all(tasks);
        return allResults.length > 0 ? allResults.reduce((a, b) => a.concat(b)) : [];
    }

    public async sendMessage(targetContactId: string, type: string, body: any, cancellationToken?: CancellationToken): Promise<boolean> {
        const sendMessgeProvider = this.getSendMessageProvider();
        if (sendMessgeProvider) {
            await sendMessgeProvider.sendMessage(targetContactId, type, body, cancellationToken);
            return true;
        }

        // no provider found
        return false;
    }

    public get signedStatus(): contactProtocol.SignedStatus {
        return this.preferedPresenceProvider ? this.preferedPresenceProvider.signedStatus : contactProtocol.SignedStatus.None;
    }

    public get hasSendMessageProvider(): boolean {
        return this.getSendMessageProvider() !== undefined;
    }

    public async removeRecentContact(contactModel: IContactModel): Promise<boolean> {
        const index = this.recentContacts.findIndex((rc) => rc.contactModel.contact.id === contactModel.contact.id);
        if (index !== -1) {
            const removed = this.recentContacts.splice(index, 1);
            await removed[0].dispose();

            await this.authCoreService.removeRecentCollaboratorAsync(contactModel.contact.id);
            await this.updateAllContacts();
            return true;
        }

        return false;
    }

    public async requestContacts(emails: string[]): Promise<RequestContacts> {
        const requestContactsResult = await this.requestContactsInternal(emails);
        this.requestContactsResults.add(requestContactsResult);
        return requestContactsResult;
    }

    public onInviteStatusChanged(handler: () => void): void {
        this.internalEmitter.addListener(onInviteStatusEventName, handler);
    }

    public get invitedContacts(): IContactModel[] {
        return Array.from(this.invitedContactsMap.values())
        .filter(i => i.status !== vsls.InviteContactStatus.None)
        .map(i => i.contact);
    }

    public isContactInvited(contactId: string): boolean {
        return this.invitedContactsMap.has(contactId);
    }

    public getInviteStatus(contactId: string): vsls.InviteContactStatus {
        if (this.invitedContactsMap.has(contactId)) {
            return this.invitedContactsMap.get(contactId).status;
        }

        return vsls.InviteContactStatus.None;
    }

    public async fireInviteStatusChanged(targetContactId: string, fromContactId: string, status: vsls.InviteContactStatus): Promise<void>  {
        this.trace.info(`fireInviteStatusChanged-> targetContactId:${TraceFormat.formatText(targetContactId)} fromContactId:${TraceFormat.formatText(fromContactId)} status:${status}`);

        await this.sendMessage(targetContactId, inviteStatusChangedMessageType, <vsls.InviteStatusNotify> {
            fromContactId,
            status
        });
    }

    public addInviteContact(invitedContact: IContactModel) {
        this.invitedContactsMap.set(invitedContact.id, {
            contact: invitedContact,
            status: vsls.InviteContactStatus.None
        });

        this.emit(ContactManagerEvents.InviteContactsUpdate);
    }

    private async onPresenceStatusProviderChanged(provider: IPresenceStatusProvider, newStatus: contactProtocol.PresenceStatus): Promise<void>  {
        this.trace.verbose(`onActivityStatusChanged-> id:${provider.id} newStatus:${newStatus} publishedPresenceStatus:${this.publishedPresenceStatus}`);
        if (!this.publishedPresenceStatus) {
            const autoStatus = this.getPresenceStatusFromProviders();
            await this.publishPresenceInternal(autoStatus, {
                allowInvites: Settings.get<string>(SettingKeys.allowInvites),
            });
        }
    }

    private getPresenceStatusFromProviders(): contactProtocol.PresenceStatus {
        const activeProvider = this.presenceStatusProviders.sort((p1, p2) => p2.priority - p1.priority).find(p => p.status !== contactProtocol.PresenceStatus.Unknown);
        return activeProvider ? activeProvider.status : contactProtocol.PresenceStatus.Available;
    }

    private async publishPresenceInternal(status: contactProtocol.PresenceStatus, properties: { [key: string]: any; }): Promise<void> {
        if (this.isPublishEnabeld) {
            const tasks = this.serviceProviders.map(async s => await s.publishPresence(status, properties));
            await Promise.all(tasks);
        }
    }

    private setInviteStatus(contactId: string, status: vsls.InviteContactStatus): void  {
        this.trace.info(`setInviteStatus-> contactId:${TraceFormat.formatText(contactId)} status:${status}`);

        if (status === vsls.InviteContactStatus.None) {
            this.invitedContactsMap.delete(contactId);
            this.emit(ContactManagerEvents.InviteContactsUpdate);
        } else if (this.invitedContactsMap.has(contactId)) {
            this.invitedContactsMap.get(contactId).status = status;
        }

        const suggestedUserChanged = this.aggregatedSuggestedUsers.find(c => c.id === contactId);
        if (suggestedUserChanged) {
            suggestedUserChanged.fireChanged('inviteStatus');
        }

        const recentUserChanged = this.recentContacts.find(c => c.contactModel.id === contactId);
        if (recentUserChanged) {
            recentUserChanged.contactModel.fireChanged('inviteStatus');
        }

        this.internalEmitter.emit(onInviteStatusEventName);
    }

    private getSendMessageProvider(): ContactServiceManager {
        return this.serviceProviders.find(s => s.capabilites && s.capabilites.supportsMessageRequest);
    }

    private removeInvitedContact(item: { options: {
        contactId: string
    }}): void {
        this.trace.info(`removeInvitedContact-> contactId:${TraceFormat.formatText(item.options.contactId)}`);
        this.setInviteStatus(item.options.contactId, vsls.InviteContactStatus.None);
    }

    private async updateContexts(): Promise<void> {
        await ExtensionUtil.setCommandContext(
            CommandContext.hasPresenceProviders,
            this.serviceProviders.findIndex(s => s.capabilites.supportsPresence) !== -1);
        await ExtensionUtil.setCommandContext(
            CommandContext.hasPublishPresenceProviders,
            this.serviceProviders.findIndex(s => s.capabilites.supportsPublishPresence) !== -1);
        await ExtensionUtil.setCommandContext(
                CommandContext.hasSearchContactsProviders,
                this.serviceProviders.findIndex(s => s.capabilites.supportsSearchContacts) !== -1);
        }

    private fireContactsChanged() {
        this.emit(ContactManagerEvents.ContactsChanged);
    }

    private updatePreferedPresenceProvider(contactServiceManager: ContactServiceManager) {
        if (contactServiceManager.capabilites.supportsContactPresenceRequest || contactServiceManager.capabilites.supportsSignedStateRequest) {
            const isSelectedPresenceProvider = this.preferedPresenceProvider && this.preferedPresenceProvider.serviceId === this.selectedPreferedProviderId;

            if (!this.preferedPresenceProvider ||
                (contactServiceManager.serviceId === this.selectedPreferedProviderId) ||
                (!isSelectedPresenceProvider && contactServiceManager.priority >=  this.preferedPresenceProvider.priority)) {
                // this our prefered provider from now on
                this.preferedPresenceProvider = contactServiceManager;
                this.updatePreferedProviderSelfStatus();
                this.updatePreferedProviderSignedStatus();
            }
        }
    }

    private onAuthenticationRequired(contactServiceManager: ContactServiceManager) {
        // Note: we receive this request about a provider that to proceed it would require the
        // the extension to be signed in. Invoking directly the 'signin' command would cause
        // undesired problems if the extension is at the same time attempting to join and so be in the
        // middle of an authentication flow.
    }

    private async onCapabilitiesChanged(contactServiceManager: ContactServiceManager, capabilitesChanged: any): Promise<void> {
        const oldCapabilities = <contactProtocol.Capabilities> capabilitesChanged.oldCapabilities;
        const newCapabilities = <contactProtocol.Capabilities> capabilitesChanged.newCapabilities;

        this.trace.info(`onCapabilitiesChanged-> serviceId:${contactServiceManager.serviceId} old:${JSON.stringify(oldCapabilities)} new:${JSON.stringify(newCapabilities)}`);

        if (oldCapabilities.supportsPresence !== newCapabilities.supportsPresence ||
            oldCapabilities.supportsContactPresenceRequest !== newCapabilities.supportsContactPresenceRequest) {
                await this.updateAllContacts();
        }

        this.updatePreferedPresenceProvider(contactServiceManager);
        await this.updateContexts();

        this.emit(ContactManagerEvents.ProviderCapabilitiesChanged, contactServiceManager);
    }

    private onInviteLinkReceived(contactServiceProvider: ContactServiceManager, params: contactProtocol.InviteReceivedNotification) {

        // always provide a safe contact id when firing this event
        if (params.fromContact && !params.fromContact.id) {
            params.fromContact.id = params.fromContactId;
        }

        if (!this.isSelfContact(params.fromContact)) {
            const allowInvites = Settings.get<string>(SettingKeys.allowInvites);
            let inviteRejected: boolean = false;
            if (allowInvites === 'none') {
                inviteRejected = true;
            } else if (allowInvites === 'contacts' || allowInvites === 'recentContacts') {
                const allowedContactIds = this.recentContacts.map(rc => rc.contactModel.id);
                if (allowInvites === 'contacts') {
                    allowedContactIds.push(...this.aggregatedSuggestedUsers.map(i => i.id));
                }

                inviteRejected = allowedContactIds.findIndex(id => id === params.fromContact.id) === -1;
            }

            if (inviteRejected) {
                this.trace.info(`invite rejected for contactId:${params.fromContact.id} allowInvites:${allowInvites}`);
                return;
            }
        }

        const evt: InviteLinkReceived = {
            provider: contactServiceProvider,
            originator: params.fromContact ? new ContactModelApi(contactServiceProvider.serviceId, params.fromContact, {}, this) : contactServiceProvider.lookupContactById(params.fromContactId),
            link: params.link
        };

        this.emit(ContactManagerEvents.InviteLinkReceived, evt);
    }

    private async onAvailableUsersChanged(): Promise<void> {
        await ExtensionUtil.setCommandContext(
            CommandContext.hasAvailableContacts,
            this.serviceProviders.findIndex(s => s.availableUsers.length > 0) !== -1);

        this.fireContactsChanged();
    }

    private onMessageReceived(params: contactProtocol.MessageReceivedNotification) {
        this.trace.info(`onMessageReceived-> type:${params.type} body:${JSON.stringify(params.body)}`);

        if (params.type === inviteStatusChangedMessageType) {
            const inviteStatusNotify = <vsls.InviteStatusNotify>params.body;
            // only make sense to change the status if the state exists
            if (this.invitedContactsMap.has(inviteStatusNotify.fromContactId)) {
                this.setInviteStatus(inviteStatusNotify.fromContactId, inviteStatusNotify.status);
            }
        }
    }

    private async onSuggestedUsersUpdate(contactServiceManager: ContactServiceManager, suggesteContactsModel: SuggestedContactsModel) {
        this.trace.info(`onSuggestedUsersUpdate-> serviceId:${contactServiceManager.serviceId} count:${suggesteContactsModel.contacts.length}`);
        this.suggestedUserByProvider[contactServiceManager.serviceId] = suggesteContactsModel;
        // Note: suggested contects being received may affect the construction of recent contacts
        // since some of the presence contacts may have come from suggestion sources
        await this.updateAllContacts();
    }

    private updatePreferedProviderSelfStatus() {
        if (this.preferedPresenceProvider && this.preferedPresenceProvider.selfUser) {
            const status = this.preferedPresenceProvider.selfUser.contact.status;
            vscode.commands.executeCommand('setContext', 'liveshare:status', status);
        }
    }

    private updatePreferedProviderSignedStatus() {
        if (this.preferedPresenceProvider) {
            vscode.commands.executeCommand('setContext', 'liveshare:presenceSignedStatus', this.preferedPresenceProvider.signedStatus);
        }
    }

    private onPresenceSignedStatusNotification(contactServiceProvider: ContactServiceManager) {

        // update prefered provider signed status
        if (this.preferedPresenceProvider  === contactServiceProvider) {
            this.updatePreferedProviderSignedStatus();
        }

        this.emit(ContactManagerEvents.SignedStateChanged, this.signedStatus);
    }

    private onSelfUserChangedNotification(contactServiceProvider: ContactServiceManager) {

        // update prefered provider status
        if (this.preferedPresenceProvider  === contactServiceProvider) {
            this.updatePreferedProviderSelfStatus();
        }

        this.fireContactsChanged();
    }

    private onContactPropertiesChangedNotification(contactPropertyChanged: contactProtocol.ContactPropertiesChangedNotification) {
        let contactModel = this.aggregatedSuggestedUsers.find(c => c.contact.id === contactPropertyChanged.contactId);         
        if (contactModel) {
            ContactServiceManager.updateContactPropertyChanges(contactModel, contactPropertyChanged.changes);
            this.emit(ContactManagerEvents.SuggestedUsersUpdate);
        }

        contactModel = this.recentContacts.map(i => i.contactModel).find(c => c.contact.id === contactPropertyChanged.contactId);         
        if (contactModel) {
            ContactServiceManager.updateContactPropertyChanges(contactModel, contactPropertyChanged.changes);
            this.emit(ContactManagerEvents.RecentContactsUpdate);
        }

        this.requestContactsResults.forEach(rc => {
            contactModel = rc.contactModels.find(c => c.contact.id === contactPropertyChanged.contactId);
            if (contactModel) {
                ContactServiceManager.updateContactPropertyChanges(contactModel, contactPropertyChanged.changes);
            }
        });    
    }

    private onContactsChangedNotification(contactServiceProvider: ContactServiceManager, changes: { [key: string]: contactProtocol.ContactPropertyValueChanged[]; }) {

        // update prefered provider status
        if (this.preferedPresenceProvider  === contactServiceProvider) {
            this.updatePreferedProviderSelfStatus();
        }

        let contactsChanged: Array<ContactModelApi> = [];

        ContactServiceManager.updateContacts(this.aggregatedSuggestedUsers, changes, contactsChanged);
        if (contactsChanged.length > 0) {
            this.emit(ContactManagerEvents.SuggestedUsersUpdate);
        }

        contactsChanged = [];
        ContactServiceManager.updateContacts(this.recentContacts.map(i => i.contactModel), changes, contactsChanged);
        if (contactsChanged.length > 0) {
            this.emit(ContactManagerEvents.RecentContactsUpdate);
        }

        this.requestContactsResults.forEach(rc => {
            contactsChanged = [];
            ContactServiceManager.updateContacts(rc.contactModels, changes, contactsChanged);
        });
    }

    private async loadRecentCollaborators(isAuthenticated: boolean): Promise<void> {

        const loadRecentCallback = async (): Promise<void> =>  { 
            await this.disposeRecentContactsInternal();
            this.recentContacts = [];
            if (isAuthenticated) {
                const currentUser = await this.authCoreService.getCurrentUserAsync();
                if (currentUser && currentUser.recentCollaborators) {
                    this.trace.verbose(`loading recent collaborators count:${currentUser.recentCollaborators.length}`);
                    await this.addRecentCollaborators(currentUser.recentCollaborators.map(rc => <contactProtocol.Contact> {
                        id: rc.id,
                        email: rc.email,
                        displayName: rc.name,
                        status: contactProtocol.PresenceStatus.Unknown
                    }));
                } else {
                    this.trace.warning('no current user retrieved from auth service');
                }
            }
            this.emit(ContactManagerEvents.RecentContactsUpdate);
        };
        this.updateRecentContactsWithProgress(loadRecentCallback);
    }

    private async updateRecentContacts(): Promise<void>  {
        this.updateRecentContactsWithProgress(() => this.updateRecentContactsInternal());
    }

    private async updateRecentContactsWithProgress(callback: () => Promise<void>): Promise<void>  {
        await this.updateRecentContactsInProgress.dispatch(callback);
    }

    private async disposeRecentContactsInternal(): Promise<contactProtocol.Contact[]>  {
        const recentContacts = this.recentContacts.map(i => {
            i.contact.status = contactProtocol.PresenceStatus.Unknown;
            return i.contact;
        });
        await Promise.all(this.recentContacts.map(rc => rc.dispose()));
        return recentContacts;
    }

    private async updateRecentContactsInternal(): Promise<void>  {
        this.trace.verbose(`->updateRecentContacts -> count:${this.recentContacts.length}`);

        const recentCollaborators = await this.disposeRecentContactsInternal();

        this.recentContacts = [];
        await this.addRecentCollaborators(recentCollaborators);

        this.trace.verbose(`<-updateRecentContacts`);
        this.emit(ContactManagerEvents.RecentContactsUpdate);
    }

    private async requestContactsInternal(emails: string[]): Promise<RequestContactsImpl> {
        const allContacts: Array<ContactModelApi> = [];
        const requestContacts = emails.map(email => {
            const contact = new contactProtocol.Contact();
            contact.id = email;
            contact.email = email;
            return contact;
        });

        const requestPresenceContactHelper = new RequestPresenceContactHelper();
        const contactIdsResolved = await this.requestContactsWithPresenceAsync(allContacts, requestContacts, requestPresenceContactHelper);
        requestContacts.forEach(c => {
            const index = allContacts.findIndex(i => i.contact.email === c.email);
            if (index === -1) {
                c.status = contactProtocol.PresenceStatus.Offline;
                allContacts.push(new ContactModelApi(null, c, {}, this));
            }
        });

        const requestContactsResult = new RequestContactsImpl(
            emails,
            allContacts,
            () => {
                this.requestContactsResults.delete(requestContactsResult);
                return requestPresenceContactHelper.clear();
            });

        return requestContactsResult;
    }

    private async updateAllContacts(): Promise<void>  {
        // Note: we allways want to start with Recent contacts since we want later
        // to exclude from our suggested contacts the duplicates
        await this.updateRecentContacts();
        await this.updateSuggestedUsers();

        // let's update any requested contacts
        for (const item of this.requestContactsResults.values()) {
            const updateResults = await this.requestContactsInternal(item.emails);
            item.update(updateResults);
        }
    }

    private async addUserProfile(userProfile: vsls.WorkspaceUserProfile): Promise<void> {
        this.trace.verbose(`addUserProfile id:${TraceFormat.formatText(userProfile.id)} name:${TraceFormat.formatText(userProfile.name)} ` +
            `email:${TraceFormat.formatEmail(userProfile.email)}`);

        const index = this.recentContacts.findIndex(i => i.contact.id === userProfile.id);
        if (index === -1) {
            const contact: contactProtocol.Contact = {
                id: userProfile.id,
                displayName: userProfile.name,
                email: userProfile.email,
                avatarUri: userProfile.avatarUri
            };

            await this.addRecentContact(contact);
            // Note: we would need to update our suggested contacts to remove potential duplicates
            await this.updateSuggestedUsers();
        } else if (index !== 0) {
            const removed = this.recentContacts.splice(index, 1);
            this.recentContacts.unshift(...removed);
        }

        this.emit(ContactManagerEvents.RecentContactsUpdate);
    }

    private async addRecentContact(contact: contactProtocol.Contact): Promise<void> {
        this.trace.verbose(`addRecentContact id:${TraceFormat.formatText(contact.id)} ` +
            `displayName:${TraceFormat.formatText(contact.displayName)} email:${TraceFormat.formatEmail(contact.email)}`);

        const allContacts: Array<ContactModelApi> = [];
        const contacts = [contact];
        const requestPresenceContactHelper = new RequestPresenceContactHelper();

        // ensure we clean the status
        contact.status = contactProtocol.PresenceStatus.Unknown;
        await this.requestContactsWithPresenceAsync(allContacts, contacts, requestPresenceContactHelper);

        // ensure no duplicates        
        this.recentContacts = this.recentContacts.filter(c => c.contact.id !== contact.id);

        this.recentContacts.push({
            contact,
            contactModel: allContacts.length > 0 ? allContacts[0] : new ContactModelApi(null, contact, {}, this),
            dispose: async () => await requestPresenceContactHelper.clear()
        });
    }

    private async addRecentCollaborators(recentContacts: contactProtocol.Contact[]): Promise<void> {
        const allContacts: Array<ContactModelApi> = [];
        await this.recentContactsPresenceRequests.clear();
        const resolvedContactIds = await this.requestContactsWithPresenceAsync(allContacts, recentContacts, this.recentContactsPresenceRequests);

        // Note: dispose is void since we use the 'clear' method of 'this.recentContactsPresenceRequests'
        const dispose = () => Promise.resolve();

        this.recentContacts.push(...recentContacts.map(c => {
            let contactModel: ContactModelApi;

            const index = resolvedContactIds.findIndex(id => id === c.id);
            if (index !== -1) {
                contactModel =  allContacts[index]; 
            } else {
                contactModel = new ContactModelApi(null, c, {}, this)
            }

            return <RecentContact> {
                contact: c,
                contactModel,
                dispose
            }
        }));
    }

    private selectPresenceProviders(capabilitiesFilter: (c: contactProtocol.Capabilities) => boolean): ContactServiceManager[] {
        let providers = this.serviceProviders.filter(s => capabilitiesFilter(s.capabilites));
        // if more than one providers is found, select the prefered provider if multiple provider is disabled
        if (providers.length > 1 &&
            !this.supportMultiplePresenceProviders &&
            this.preferedPresenceProvider) {
                providers = [this.preferedPresenceProvider];
        }

        return providers;
    }

    private async requestContactsWithPresenceAsync(
        contactModelsResolved: Array<ContactModelApi>,
        contacts: Array<contactProtocol.Contact>,
        requestPresenceContactHelper: RequestPresenceContactHelper
    ): Promise<Array<string>> {
        const contactIdsResolved: Array<string> = [];

        const providersWithPresenceSupport = this.selectPresenceProviders(c => c.supportsPresence);
        // attempt to find the contacts on the available contacts being collected
        contacts = contacts.filter(c =>
            !providersWithPresenceSupport.find(provider => {
                const matchContact = provider.findMatchContact(c);
                if (matchContact) {
                    contactIdsResolved.push(c.id);
                    contactModelsResolved.push(matchContact);
                    return true;
                }

                return false;
            }));

        const contactPresenceRequestServices = this.selectPresenceProviders(c => c.supportsContactPresenceRequest);
        for (let index = 0; index < contactPresenceRequestServices.length && contacts.length > 0; index++) {
            const contactPresenceRequestService = contactPresenceRequestServices[index];
            try {
                this.trace.verbose(`Request presence on service:${contactPresenceRequestService.serviceId} for contact ids:${contacts.map(c => TraceFormat.formatText(c.id)).concat(',')} ` +
                    `emails:${contacts.map(c => TraceFormat.formatEmail(c.email)).join(',')}`);
                const contactsWithPresence = await contactPresenceRequestService.contactsPresenceRequest(contacts);

                const contactModelValues = Object.values(contactsWithPresence);
                if (contactModelValues.length > 0) {
                    requestPresenceContactHelper.addRequest(contactPresenceRequestService, contactModelValues);
                    contactModelsResolved.push(...contactModelValues);

                    // remove the contacts being found
                    Object.keys(contactsWithPresence).forEach(contactId => {
                        this.trace.verbose(`Presence support found for id:${TraceFormat.formatText(contactId)} => id:${TraceFormat.formatText(contactsWithPresence[contactId].contact.id)} ` +
                            `email:${TraceFormat.formatEmail(contactsWithPresence[contactId].contact.email)}`);
                        contactIdsResolved.push(contactId);
                        // remove from the reamining contacts array
                        const contactIndex = contacts.findIndex(c => c.id === contactId);
                        if (contactIndex !== -1) {
                            contacts.splice(contactIndex, 1);
                        }
                    });
                }
            } catch (err) {
                    this.trace.error(`Failed to request presence for service:${contactPresenceRequestService.serviceId} `);
            }
        }

        return contactIdsResolved;
    }

    private async updateSuggestedUsers(): Promise<void>  {
        await this.updateSuggestedContactsInProgress.dispatch(() => this.updateSuggestedUsersInternal());
    }

    private isSelfContact(contact: contactProtocol.Contact): boolean {
        return this.serviceProviders.findIndex(s => {
            return s.selfUser &&
                s.capabilites.supportsInviteLink &&
                (s.selfUser.contact.id === contact.id ||
                    s.selfUser.contact.email === contact.email);
        }) >= 0;
    }

    private async updateSuggestedUsersInternal(): Promise<void> {
        this.trace.verbose('->updateSuggestedUsers');

        await this.suggestedContactPresenceRequests.clear();
        let allContacts: Array<ContactModelApi> = [];

        const suggestedUsers: { [key: string]: ContactModelApi[] } = {} 

        // Note: next block will look for exclusive payloads being requested
        const exclusiveRequests = Object.keys(this.suggestedUserByProvider).filter(serviceId =>
            this.suggestedUserByProvider[serviceId].exclusive &&
            this.suggestedUserByProvider[serviceId].contacts.length > 0)
            .sort((serviceId1, serviceId2) => {
                const priority1 = this.getServiceManager(serviceId1).priority;
                const priority2 = this.getServiceManager(serviceId2).priority;
                if (priority1 > priority2) {
                    return -1;
                } else if (priority1 < priority2) {
                    return 1;
                }

                return 0;
            });

        if (exclusiveRequests.length > 0) {
            const exclusiveServiceId = exclusiveRequests[0];
            // an 'exclusive' payload was prefered
            suggestedUsers[exclusiveServiceId] = this.suggestedUserByProvider[exclusiveServiceId].contacts;
        } else {
            // all paylods will be consumed
            Object.keys(this.suggestedUserByProvider).forEach(serviceId => suggestedUsers[serviceId] = this.suggestedUserByProvider[serviceId].contacts);
        }

        const tasks = Object.keys(suggestedUsers).map(async serviceId => {
            const contactModels = suggestedUsers[serviceId];
            this.trace.verbose(`suggest contacts from provider:${serviceId} ids:${contactModels.map(c => TraceFormat.formatText(c.contact.id)).join(',')} ` +
                `emails:${contactModels.map(c => TraceFormat.formatEmail(c.contact.email)).join(',')}`);

            const serviceManager = this.getServiceManager(serviceId);
            if (!serviceManager.capabilites.supportsPresence) {

                const contacts = contactModels.map(i => i.contact);
                const contactIdsResolved = await this.requestContactsWithPresenceAsync(allContacts, contacts, this.suggestedContactPresenceRequests);
                contactIdsResolved.forEach(contactId => {
                    const index = contactModels.findIndex(i => i.contact.id === contactId);
                    if (index !== -1) {
                        contactModels.splice(index, 1);
                    }
                });
            }

            // push remaining contacts
            allContacts.push(...contactModels);
        });
        await Promise.all(tasks);

        this.aggregatedSuggestedUsers = allContacts;
        this.trace.info(`<- updateSuggestedUsers count:${allContacts.length}`);

        this.emit(ContactManagerEvents.SuggestedUsersUpdate);
    }
}

class RequestPresenceContactHelper {
    private contactPresenceRequests: Array<ContactPresenceRequest> = [];

    public addRequest(
        serviceProvider: ContactServiceManager,
        contacts: IContactModel[]) {
        this.contactPresenceRequests.push({
            serviceProvider,
            contacts
        });
    }

    public async clear(): Promise<void> {
        let tasks = this.contactPresenceRequests.map(async req => {
            // only if the capability is supported at this moment
            if (req.serviceProvider.capabilites && req.serviceProvider.capabilites.supportsContactPresenceRequest) {
                await req.serviceProvider.contactsPresenceDispose(req.contacts.map(c => c.contact.id));
            }
        });
        try {
            await Promise.all(tasks);
        } catch {
            // we already log an error if the providers fails
        }
        this.contactPresenceRequests = [];
    }
}

interface ContactPresenceRequest {
    readonly serviceProvider: ContactServiceManager;
    readonly contacts: IContactModel[];
}

interface RecentContact {
    readonly contact: contactProtocol.Contact;
    readonly contactModel: ContactModelApi;
    readonly dispose: () => Promise<void>;
}

/**
 * Interface to expose batch request of presence
 */
export interface RequestContacts {
    readonly onContactsChanged: vscode.Event<void>;
    readonly contactModels: ContactModelApi[];
    readonly dispose: () => Promise<void>;
}

class RequestContactsImpl implements RequestContacts {
    private contactsChangedEmitter = new vscode.EventEmitter<void>();

    constructor(
        public emails: string[],
        public contactModels: ContactModelApi[],
        private disposeCallback: () => Promise<void>) {
    }

    public get onContactsChanged() { return this.contactsChangedEmitter.event; }

    public dispose(): Promise<void> {
        return this.disposeCallback();
    }

    public update(other: RequestContactsImpl): void {
        this.contactModels = other.contactModels;
        this.disposeCallback = other.disposeCallback;

        this.contactsChangedEmitter.fire();
    }
}

const contactManagerInstance = ContactManager.Instance;
export { contactManagerInstance as ContactManager };