import { Agent } from '@abstractions/agent';
import { RPCClient } from '@abstractions/rpcClient';
import { dependencies } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

export class AgentRpcClient extends RPCClient {

    public constructor(private readonly rpcConnectId?: string) {
        super(Agent.startIfNotRunning());
    }

    protected async onRpcSessionConnected(): Promise<void> {
        // bootstrap the rpc session
        // Note: we define a 5 secs delay when the rpc session is closed to allow the agent to be alive in case of reload
        // or close workspace command
        const agentSessionResponse = <vsls.AgentSessionResponse> await this.connection.sendRequest('agentSessionService.initializeSession', [
            <vsls.AgentSessionRequest> {
                reconnectId: this.rpcConnectId,
                keepAliveOnDisconnect: 5000
            }]);
        dependencies.hostSessionId.loader = () => agentSessionResponse.hostSessionNumber;
        this.trace.verbose(`finish initialize agent session with rpcConnectId:${this.rpcConnectId} hostSessionId:${agentSessionResponse.hostSessionNumber}`);

        // Next line will make sure that we complete the agent start promise in all cases
        // were this vscode instance did not start the agent process but just connect to the running pipe
        Agent.completeAgentStartIfNotRunning();
    }

}