import * as uuid from 'uuid';

import { startSocketServer, SocketServerOptions, MutliChannelRpcSocketServer, Server } from '@vs/vso-node-server';
import { WorkspaceHubService } from '@vs/vso-workspace-hub-service';
import { TLiveShareConnectionHub } from '@vs/vscs-connection-hub';
import { TraceSource } from '@vs/vso-logging';

/**
 * Start in-proc Workspace Connection RPC server and return it's pipe name.
 * This RPC server is used by sudo port-forwarder.
 */
export async function startLocalWorkspaceHubService(connectionHub: TLiveShareConnectionHub, traceSource: TraceSource): Promise<[Server, string]> {

    // Use a random pipe name to not confuse it with codespaces workspace hub.
    const pipe = `vsclsws.${uuid().replace(/-/g, '')}`; 
    const serverOptions: SocketServerOptions = {
        traceSource,
        pipe,
        socketServerFactory: (keepAliveCallback, trace) =>
            new MutliChannelRpcSocketServer(
                trace, 
                rpcServer => new WorkspaceHubService(rpcServer, connectionHub, keepAliveCallback, trace.withName('WorkspaceHubService'))
            ),
    };

    const server = await startSocketServer(serverOptions);
    return [server, pipe];
}
