import { CancellationToken } from 'vscode-jsonrpc';

import { assertDefined, isThenable } from '../utils';
import { CancellationError } from '../errors';
import { IDisposable } from '../interfaces';

type TSignalState = 'pending' | 'resolved' | 'rejected' | 'cancelled';

/**
 * An abstraction above a promise, makes it easy to `resolve`/`reject`
 * promise afterward and keeps the promise state attributes.
 */
export class Signal<T> implements IDisposable {
    private promiseReference: Promise<T>;
    private promiseResolve?: (result: T) => void;
    private promiseReject?: (error: any) => void;

    private stateReference: TSignalState = 'pending';

    constructor(
        cancellationToken?: CancellationToken
    ) {
        // tslint:disable-next-line: promise-must-complete
        this.promiseReference = new Promise((resolve, reject) => {
            this.promiseResolve = resolve;
            this.promiseReject = reject;
        });

        this.resolve = this.resolve.bind(this);
        this.reject = this.reject.bind(this);
        this.cancel = this.cancel.bind(this);

        if (!cancellationToken) {
            return;
        }

        if (cancellationToken.isCancellationRequested) {
            this.cancel();
        } else if (cancellationToken.onCancellationRequested) {
            cancellationToken.onCancellationRequested(() => {
                if (this.isFulfilled) {
                    return;
                }

                this.cancel();
            });
        }
    }

    public get isFulfilled() {
        return this.state !== 'pending';
    }

    public get state() {
        return this.stateReference;
    }

    public get isResolved() {
        return this.state === 'resolved';
    }

    public get isRejected() {
        return this.state === 'rejected';
    }

    public get isCancelled() {
        return this.state === 'cancelled';
    }

    public resolve(result: T): void {
        if (this.isFulfilled) {
            return;
        }

        this.stateReference = 'resolved';

        assertDefined(
            this.promiseResolve,
            'No `promiseResolve` function found.'
        );

        this.promiseResolve(result);
    }

    public reject(error: Error): void {
        if (this.isFulfilled) {
            return;
        }

        this.stateReference = 'rejected';

        assertDefined(
            this.promiseReject,
            'No `promiseReject` function found.'
        );

        this.promiseReject(error);
    }

    public cancel(): void {
        if (this.isFulfilled) {
            return;
        }

        this.stateReference = 'cancelled';

        assertDefined(
            this.promiseReject,
            'No `promiseReject` function found.'
        );

        this.promiseReject(new CancellationError());
    }

    public get promise(): Promise<T> {
        return this.promiseReference;
    }

    public static from<T>(value: Promise<T>): Signal<T>;
    public static from<T>(value: T): Signal<T>;
    public static from<T>(value: T | Promise<T>): Signal<T> {
        const signal = new Signal<T>();

        if (isThenable(value)) {
            value.then(signal.resolve, signal.reject);
        } else {
            signal.resolve(value);
        }

        return signal;
    }

    public dispose(): void {
        if (this.isFulfilled) {
            return;
        }

        this.cancel();
    }
}
