import { getExpService } from "./exp/ExperimentationService";
import { CommandContext } from "./CommandConstants";
import { ExtensionUtil } from "./utils/ExtensionUtil";
import { EventEmitter } from "events";
import { Settings } from "./Settings";
import { SettingKeys } from "./SettingKeys";

export class PresentationManager {
    public onPresenterUpdate: EventEmitter = new EventEmitter();

    private presenterId: number;
    public presentationMode: boolean;

    private isPresentationModeExperimentEnabled: boolean = false;

    public get currentPresenterId(): number {
        return this.presenterId;
    }

    public get isStrictFollowEnabled(): boolean {
        const alwaysFollowHost = <boolean>Settings.get(SettingKeys.alwaysFollowHost);
        // Strict follow should never be enabled when the experiment is disabled
        return this.isPresentationModeExperimentEnabled && (alwaysFollowHost || this.presentationMode);
    }

    public updatePresenterId(newPresenterId: number) {
        if (this.presenterId != newPresenterId) {
            this.presenterId = newPresenterId;
            this.onPresenterUpdate.emit('onPresenterUpdate');
        }
    }

    constructor(hostId: number, presentationMode: boolean) {
        this.presenterId = hostId;
        this.presentationMode = presentationMode;

        const expService = getExpService();
        expService?.isCachedFlightEnabled('strictFollow').then((result) => {
            this.isPresentationModeExperimentEnabled = result;
        });

        ExtensionUtil.setCommandContext(CommandContext.isPresentation, this.presentationMode);
    }
}
