import * as vscode from 'vscode';
import { contactProtocol } from '@vs/vsls-contracts';
export abstract class ProviderBase implements contactProtocol.ContactServiceProvider {
    private readonly onNotifiedEmitter = new vscode.EventEmitter<contactProtocol.NotifyContactServiceEventArgs>();

    public async requestAsync(
        type: string,
        parameters: Object,
        cancellationToken?: vscode.CancellationToken)
        : Promise<Object> {
            let result = null;

            switch (type) {
                case contactProtocol.Methods.RequestInitializeName:
                    result = await this.requestInitialize(<contactProtocol.InitializeRequest>parameters);
                    break;
            default:
                throw new Error(`type:${type} not supported`);
            }

            return result;
    }

    public get onNotified(): vscode.Event<contactProtocol.NotifyContactServiceEventArgs> {
        return this.onNotifiedEmitter.event;
    }

    protected abstract requestInitialize(request: contactProtocol.InitializeRequest): Promise<contactProtocol.InitializeResponse>;

    protected notify(type: string, body: any) {
        this.onNotifiedEmitter.fire({
            type,
            body
        });
    }

    protected notifySuggestedUsers(contacts: contactProtocol.Contact[]) {
        this.notify(contactProtocol.Methods.NotifySuggestedUsersName, <contactProtocol.ContactsNotification>{
            contacts
        });
    }

    protected notifyPresenceChanged(contactId: string, presenceStatus: contactProtocol.PresenceStatus): void {
        const presenceUpdate = new contactProtocol.ContactPresenceUpdate();
        presenceUpdate.contactId = contactId;
        presenceUpdate.status = presenceStatus;

        const presenceChangedNotification = new contactProtocol.PresenceChangedNotification();
        presenceChangedNotification.changes = [presenceUpdate];

        this.notify(contactProtocol.Methods.NotifyPresenceChangedName, presenceChangedNotification);
    }

    protected notifyContactChanged(contactId: string, changes: contactProtocol.ContactPropertyValueChanged[]): void {
        const notification: contactProtocol.ContactChangedNotification = {
            changes: {}
        };
        notification.changes[contactId] = changes;
        this.notify(contactProtocol.Methods.NotifyContactChangedName, notification);
    }

    protected notifyContactPropertiesChanged(contactId: string , changes: { [key: string]: any; }) {
        this.notify(contactProtocol.Methods.NotifyContactPropertiesChangedName, {
            contactId,
            changes
        } as contactProtocol.ContactPropertiesChangedNotification);
    }

    protected notifySignedStateChanged(signedStatus: contactProtocol.SignedStatus): void {
        this.notify(contactProtocol.Methods.NotifySignedStateChangedName, {
            state: signedStatus
        } as contactProtocol.SignedStateChangedNotification);
    }
}