import { IAgentSessionContextUpdateListener } from './abstractions/IAgentSessionContextUpdateListener';
import { IDependencies } from './IDependencies';

import { builder as ShareCommandBuilder } from './commands/ShareCommand';
import { builder as JoinSessionCommandBuilder } from './commands/JoinSessionCommand';
import { builder as JoinPostReloadCommandBuilder } from './commands/JoinPostReloadCommand';
import { builder as JoinPreReloadCommandBuilder } from './commands/JoinPreReloadCommand';
import {
    ExtensionSetupBase,
} from '@vs/liveshare-core';
import {
    registerContactCommands,
} from '@vs/liveshare-contactservice';
import {
    registerCommunicationsCommands,
} from '@vs/liveshare-communications';
import {
    ListPlannedSessionsCommandBuilder,
    CreatePlannedSessionCommandBuilder,
    DeletePlannedSessionCommandBuilder,
    RenamePlannedSessionCommandBuilder,
    CopyPlannedSessionLinkCommandBuilder,
    JoinPlannedSessionCommandBuilder,
} from '@vs/liveshare-plannedsessions';

export class ExtensionSetup extends ExtensionSetupBase {
    private agentSessionContextUpdateListener: IAgentSessionContextUpdateListener;

    constructor (
        dependencies: IDependencies
        ) {
            super(dependencies.commandRegistryProvider(), dependencies);
            this.agentSessionContextUpdateListener = dependencies.agentSessionContextUpdateListener();
    }

    protected get shareCommandBuilder() {
        return ShareCommandBuilder;
    }

    protected get joinCommandBuilder() {
        return JoinSessionCommandBuilder;
    }

    protected registerCommands(): void {
        // Setup listener to track session context updates
        this.agentSessionContextUpdateListener.subscribe();

        super.registerCommands();

        this.registerListPlannedSessionsCommand();
        this.registerCreatePlannedSessionCommand();
        this.registerDeletePlannedSessionCommand();
        this.registerRenamePlannedSessionCommand();
        this.registerCopyPlannedSessionLinkCommand();
        this.registerJoinPlannedSessionCommand();

        // All our Contact/Presence related commands
        registerContactCommands(this);
        // All Communications related commands
        registerCommunicationsCommands(this);
    }

    private registerCreatePlannedSessionCommand() {
        this.register('createPlannedSession', CreatePlannedSessionCommandBuilder);
        this.register('createPlannedSessionFromActivityBar', CreatePlannedSessionCommandBuilder);
        this.register('createPlannedSessionFromFileTreeExplorer', CreatePlannedSessionCommandBuilder);
    }

    private registerListPlannedSessionsCommand() {
        this.register('listPlannedSessions', ListPlannedSessionsCommandBuilder);
    }

    private registerDeletePlannedSessionCommand() {
        this.register('deletePlannedSession', DeletePlannedSessionCommandBuilder); 
        this.register('deletePlannedSessionFromFileTreeExplorer', DeletePlannedSessionCommandBuilder);        
    }

    private registerRenamePlannedSessionCommand() {
        this.register('renamePlannedSession', RenamePlannedSessionCommandBuilder);        
    }

    private registerCopyPlannedSessionLinkCommand() {
        this.register('copyPlannedSessionLink', CopyPlannedSessionLinkCommandBuilder);  
    }

    private registerJoinPlannedSessionCommand() {
        this.register('joinPlannedSession', JoinPlannedSessionCommandBuilder);  
    }

    protected registerJoinCommands() {
        // enable join post reload command
        const joinPostReloadCommandNames = [
            'join.postReload',
        ];

        for (let joinPostReloadCommandName of joinPostReloadCommandNames) {
            this.register(joinPostReloadCommandName, JoinPostReloadCommandBuilder, {
                isAllowAnonymous: true
            });
        }
        // enable join pre reload command
        super.registerJoinCommands();

        // enable join command
        const joinCommandNames = [
            'joinSession'
        ];

        for (let commandName of joinCommandNames) {
            this.register(commandName, JoinPreReloadCommandBuilder, {
                    isAllowAnonymous: true
                });
        }
    }

    public async dispose(): Promise<void> {
        await super.dispose();
        this.agentSessionContextUpdateListener.dispose();
    }
}

