import * as vscode from 'vscode';
import { TreeDataProviderBase, TreeDataProviderContext, TreeViewItem, localize,
    TreeViewItemOptions, ExtensionUtil, IClientAccessCheck, Lazy } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IParticipantInfo } from '@calling-service/ICallingService';
import { AudioSessionState, AudioSessionContext, AudioSessionEvents } from './AudioSessionContext';
import { CommunicationsManager } from '../CommunicationsManager';
import { CallingServiceManager } from './CallingServiceManager';
import { CallingServiceCommands } from '../constants';
import { getCollaborators } from '../utils';

export const audioViewItem = 'audio';

enum AudioItem {
    Disconnected = 'audio.disconnected',
    StartOrJoin = 'audio.startOrJoin',
    Connecting = 'audio.connecting',
    Disconnecting = 'audio.disconnecting',
    ParticipantsList = 'audio.participants',
    Participant = 'audio.participant',
    ParticipantMuted = 'audio.participant.muted',
    Self = 'audio.self',
    SelfMuted = 'audio.self.muted',
}

interface AudioSessionExplorerItemOptions extends TreeViewItemOptions {
    participantId?: number;
}

class AudioSessionExplorerItem extends TreeViewItem {
    public readonly participantId?: number;

    constructor(public readonly options: AudioSessionExplorerItemOptions) {
        super(options);
        this.participantId = options.participantId;
    }
}

export class AudioTreeDataProvider extends TreeDataProviderBase {
    private callingService: CallingServiceManager;
    private providerRegistrations: vscode.Disposable[];
    private participantsListItem: AudioSessionExplorerItem;
    private participantItems: Map<string, AudioSessionExplorerItem>;
    private selfItem: AudioSessionExplorerItem;
    private sessionState: AudioSessionState;
    private isCallAvailable: boolean = false;

    constructor(
        private authCoreService: vsls.AuthenticationCoreService,
        private clientAccessCheck: Lazy<IClientAccessCheck>) {
        super(audioViewItem, TreeDataProviderContext.SharedOrJoined);
        this.isChildItemCacheDisabled = true;
        this.initialize();
    }

    private initialize() {
        this.callingService = CommunicationsManager.callingServiceManager;
        this.participantsListItem = new AudioSessionExplorerItem({
            type: AudioItem.ParticipantsList,
            label: localize('calling.treeAudioCallParticipantsInitial'),
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            contextValue: AudioItem.ParticipantsList
        });
        this.participantItems = new Map<string, AudioSessionExplorerItem>();
        this.selfItem = new AudioSessionExplorerItem({
            type: AudioItem.Self,
            label: '',
            contextValue: AudioItem.Self
        });

        AudioSessionContext.addListener(
            AudioSessionEvents.StateChanged, async (newState: AudioSessionState) => await this.onSessionStateChanged(newState));

        this.sessionState = AudioSessionState.LiveShareWithoutAudio;

        this.callingService.onNewAudioCallAvailable(() => {
            this.isCallAvailable = true;
            this.refresh();
        });
        this.callingService.onMuteChanged(async (participant?: IParticipantInfo) => await this.onMuteChanged(participant));
        this.callingService.onParticipantsListChanged(
            async () => this.refresh(await this.updateParticipantsListItem()));
        this.callingService.onParticipantChanged((participant: any)  => this.onParticipantChanged(participant));
        this.callingService.checkIfCallIsAvailable();
    }

    protected async getChildrenItems(element: AudioSessionExplorerItem): Promise<TreeViewItem[]> {
        let label: string;
        switch (element.contextValue as AudioItem) {
            case AudioItem.Disconnected:
                switch (this.sessionState) {
                    case AudioSessionState.LiveShareWithoutAudio:
                        label = this.isCallAvailable ? localize('calling.treeJoinAudioCall') : localize('calling.treeStartAudioCall');
                        return [
                            new AudioSessionExplorerItem({
                                type: AudioItem.StartOrJoin,
                                label,
                                command: {
                                    title: label,
                                    command: CallingServiceCommands.startOrJoinCall,
                                },
                            })
                        ];
                    case AudioSessionState.AudioConnecting:
                        label = this.isCallAvailable ? localize('calling.treeJoiningAudioCall')  : localize('calling.treeStartingAudioCall');
                        return [
                            new AudioSessionExplorerItem({
                                type: AudioItem.Connecting,
                                label,
                                iconPath: TreeDataProviderBase.getThemeIconPath('loading')
                            }),
                        ];
                    default:
                        return [];
                }
            case AudioItem.ParticipantsList:
                switch (this.sessionState) {
                    case AudioSessionState.AudioDisconnecting:
                        return [
                            new AudioSessionExplorerItem({
                                type: AudioItem.Disconnecting,
                                label: localize('calling.treeEndingAudioCall'),
                                iconPath: TreeDataProviderBase.getThemeIconPath('loading')
                            }),
                        ];
                    default:
                        // reset incoming call availability
                        // check when participants are displayed
                        this.isCallAvailable = false;
                        return await this.getCallParticipants();
                }
            default:
                return [];
        }
    }

    protected async getRootItem(): Promise<AudioSessionExplorerItem> {
        let rootItem: AudioSessionExplorerItem = undefined;
        switch (this.sessionState) {
            case AudioSessionState.LiveShareWithoutAudio:
            case AudioSessionState.AudioConnecting:
                rootItem = new AudioSessionExplorerItem({
                        type: AudioItem.Disconnected,
                        label: localize('calling.treeAudioCallLabel'),
                        collapsibleState: vscode.TreeItemCollapsibleState.Expanded 
                    });
                break;
            case AudioSessionState.AudioDisconnecting:
                rootItem = new AudioSessionExplorerItem({
                        type: AudioItem.ParticipantsList,
                        label: localize('calling.treeAudioCallLabel'),
                        collapsibleState:  vscode.TreeItemCollapsibleState.Expanded,
                        contextValue: AudioItem.ParticipantsList
                    });
                break;
            case AudioSessionState.LiveShareWithAudio:
                const participants = await this.callingService.getParticipants();
                const participantCount = 1 + participants.length;
                this.participantsListItem.label = localize('calling.treeAudioCallParticipantsCount').replace('$(participantCount)', participantCount.toString());
                rootItem = this.participantsListItem;
                break;
            default:
                return;
        }
        return rootItem;
    }
    
    private async getCallParticipants(): Promise<AudioSessionExplorerItem[]> {
        const participantIds: string[] = [];
        const participants = await this.callingService.getParticipants();
        for (let participant of participants) {
            this.createOrUpdateTreeItemForParticipant(participant);
            participantIds.push(participant.id);
        }

        for (let participantId of Array.from(this.participantItems.keys())) {
            if (participantIds.indexOf(participantId) < 0) {
                this.participantItems.delete(participantId);
            }
        }

        return [this.selfItem].concat(Array.from(this.participantItems.values()));
    }

    private onParticipantChanged(participant: IParticipantInfo) {
        this.refresh(this.createOrUpdateTreeItemForParticipant(participant));
    }

    private async updateParticipantsListItem(): Promise<AudioSessionExplorerItem> {
        await this.getRootItem();
        return this.participantsListItem;
    }

    private createOrUpdateTreeItemForParticipant(participant: IParticipantInfo): AudioSessionExplorerItem {
        const isMuted = participant.isMuted;
        const isSpeaking = !isMuted && participant.isSpeaking;
        const contextValue = isMuted ? AudioItem.ParticipantMuted : AudioItem.Participant;
        const iconPath = TreeDataProviderBase.getThemeIconPath(isMuted ? 'speaker-mute' : isSpeaking ? 'speaker-sound' : 'speaker');

        let participantItem = this.participantItems.get(participant.id);
        if (!participantItem) {
            participantItem = new AudioSessionExplorerItem({
                type: contextValue,
                label: participant.displayName,
                iconPath
            });
            participantItem.id = participant.id;
            this.participantItems.set(participant.id, participantItem);
        } else {
            participantItem.label = participant.displayName;
            participantItem.contextValue = contextValue;
            participantItem.iconPath = iconPath;
        }

        return participantItem;
    }

    private async onSessionStateChanged(newState: AudioSessionState): Promise<void> {
        this.sessionState = newState;
        if (newState === AudioSessionState.LiveShareWithAudio) {
            await this.updateTreeItemForSelf();
        }
        this.refresh();
    }

    private async onMuteChanged(participant?: IParticipantInfo): Promise<void> {
        if (participant) {
            let participantItem = this.participantItems.get(participant.id);
            if (participantItem) {
                this.refresh(participantItem);
            }
        } else {
            await this.updateTreeItemForSelf();
            this.refresh();
        }
    }

    private async updateTreeItemForSelf(): Promise<void> {
        const isMuted = await this.callingService.isMuted();
        const user = await this.authCoreService.getCurrentUserAsync();
        let displayName = user ? (user.displayName || user.userName || user.emailAddress) : localize('calling.treeUnknownUser');

        // Prefer the collaboration session workspace user profile name 
        const userProfile = getCollaborators().find(u => u.id === user.id);
        if (userProfile) {
            const label = await ExtensionUtil.getAnonymousReadOnlyLabel(this.clientAccessCheck(), userProfile);
            displayName = `${userProfile.name || displayName}${label}`;
        }

        this.selfItem.label = localize('calling.treeSelfItem').replace('$(displayName)', displayName);
        this.selfItem.contextValue = isMuted ? AudioItem.SelfMuted : AudioItem.Self;
        this.selfItem.iconPath = TreeDataProviderBase.getThemeIconPath(isMuted ? 'speaker-mute' : 'speaker');
    }

    public async dispose() {
        while (this.providerRegistrations.length > 0) {
            const providerRegistration = this.providerRegistrations.pop();
            await providerRegistration.dispose();
        }
    }
}