'use strict';

import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { ClientAccessCheck } from './ClientAccessCheck';
import { IAccessControlManager, OperationRejectEvent, OperationAccessChangeEvent } from '../contracts/IAccessControlManager';
import { SessionState } from '../SessionTypes';
import { sessionStateTracker } from '../SessionStateTracker';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { ISessionContext } from '../ISessionContext';
import { IFileSystemManager } from '../file-system-provider/IFileSystemManager';
import { NotificationUtil } from '@vs/vscode-command-framework';

export class AccessControlManager extends ClientAccessCheck implements IAccessControlManager {
    private accessControl: vsls.AccessControl = {};
    private readonly operationRejected = new vscode.EventEmitter<OperationRejectEvent>();
    private readonly operationAccessChanged = new vscode.EventEmitter<OperationAccessChangeEvent>();
    private readonly disposables: vscode.Disposable[] = [];

    constructor(
        workspaceAccessControlService: vsls.WorkspaceAccessControlService,
        private accessControlService: vsls.AccessControlService,
        private readonly sessionContext: ISessionContext,
        private readonly fileSystemManager: IFileSystemManager,
        hostSessionId: number) {
        super(workspaceAccessControlService, hostSessionId);
    }

    public get isReadOnly(): boolean {
        return !!this.accessControl.isReadOnly;
    }

    public get onDidRejectOperation() {
        return this.operationRejected.event;
    }

    public get onDidChangeOperationAccess() {
        return this.operationAccessChanged.event;
    }

    public async init() {
        await super.init();

        this.accessControl = await this.accessControlService.getAccessControlAsync() || {};
        this.disposables.push(this.accessControlService.onAccessControlChanged(this.accessControlChanged, this));
        workspaceSessionInfoTracker.isReadOnly = this.isReadOnly;
        this.fileSystemManager.registerFileSystemProvider(this.isReadOnly);
        this.disposables.push(this.workspaceAccessControlService.onOperationRejected(this.workspaceAccessControlService_operationRejected, this));
        this.disposables.push(this.workspaceAccessControlService.onOperationAccessChanged(this.workspaceAccessControlService_operationAccessChanged, this));
    }

    public async dispose() {
        await super.dispose();
        this.fileSystemManager.dispose();
        await Promise.all(this.disposables.map(d => d.dispose()));
    }

    public async requestOperationAccess(operation: vsls.RestrictedOperation) {
        await this.workspaceAccessControlService.requestOperationAccessAsync(operation);
    }

    public logRejectedOperation(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess): Promise<void> {
        return Promise.resolve();
    }

    private async accessControlChanged(e: vsls.AccessControlEventArgs) {
        const oldReadOnly = this.isReadOnly;
        this.accessControl = e.accessControl || {};
        const isReadOnly = this.isReadOnly;

        if (oldReadOnly !== isReadOnly) {
            workspaceSessionInfoTracker.isReadOnly = isReadOnly;
            this.fileSystemManager.registerFileSystemProvider(isReadOnly);

            if (sessionStateTracker.State === SessionState.Joined) {
                if (sessionStateTracker.State !== SessionState.Joined) {
                    return;
                }

                const accessLevel = (workspaceSessionInfoTracker.isReadOnly)
                    ? 'read-only'
                    : 'read/write';

                NotificationUtil.showInformationMessage(`The host has given you ${accessLevel} access.`, false);
            }
        }
    }

    private async workspaceAccessControlService_operationRejected(e: vsls.RestrictedOperationAccessEventArgs) {
        const isTheSameSessionId = (this.sessionContext.coeditingClient.clientID === e.operation.sessionId);
        const isJoined = (sessionStateTracker.State === SessionState.Joined);
        const isDisabledByHost = (e.access === vsls.RestrictedOperationAccess.DisabledByHostConfiguration);
        const isCurrentUserAnonymous = userAuthStateTracker.isCurrentUserAnonymous();

        // Only request access to operations that can be enabled and that were initiated by us
        if (!e.operation
            || (!isDisabledByHost && !isCurrentUserAnonymous)
            || !isTheSameSessionId
            || !isJoined) {

            return;
        }

        const isReadOnlySession = await this.isReadOnlySession();
        this.operationRejected.fire({ operation: e.operation, isCurrentUserAnonymous, isReadOnlySession });
    }

    private workspaceAccessControlService_operationAccessChanged(e: vsls.RestrictedOperationAccessEventArgs) {
        if (!e.operation || sessionStateTracker.State !== SessionState.Joined) {
            return;
        }

        this.operationAccessChanged.fire({ operation: e.operation, access: e.access });
    }
}
