'use strict';

import * as vscode from 'vscode';
import * as git from './git';
import * as path from 'path';
import { sep } from 'path';
import { Uri, CancellationToken, Disposable } from 'vscode';
import { debounce, memoize } from '@vs/liveshare-core';
import { fileAccess, IFileSystemStats as Stats } from '@vs/vscode-command-framework';
import { IHostSourceControlProvider } from '../Contracts';

import {
    IPathManager,
    VSLS_SCHEME,
    VSLS_EXTERNAL_SCHEME
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { setInterval } from 'timers';

interface CacheRow {
    resource: vsls.SourceControlResource;
    timestamp: number;
}

const THREE_MINUTES = 1000 * 60 * 3;
const FIVE_MINUTES = 1000 * 60 * 5;
const SOURCE_CONTROL_ID = 'git';

const IMAGE_MIME_TYPES = [
    'image/png',
    'image/gif',
    'image/jpeg',
    'image/webp',
    'image/tiff',
    'image/bmp'
];

// Resource Group IDs
const MERGE_GROUP_ID = 'merge';
const INDEX_GROUP_ID = 'index';
const WORKING_TREE_GROUP_ID = 'workingTree';
const NOT_SUPPORTED_GROUP_ID = 'unsupported';

const MAX_RECENT_VERSION_COUNT = 100;

interface GitVersion {
    ref: string;
}

interface GitResourceParams extends GitVersion {
    path?: string;
    submoduleOf?: string;
}

function gitParamsFromResource(resource: vsls.SourceControlResource, pathManager: IPathManager): GitResourceParams | undefined {
    if (!resource || !resource.path) {
        return;
    }

    // tslint:disable-next-line:no-shadowed-variable
    let path = resource.path;
    switch (resource.type) {
        case vsls.SourceControlResourceType.SpecificVerision:
            break;

        case vsls.SourceControlResourceType.Workspace:
        case vsls.SourceControlResourceType.WorkspaceWithSpecificVersion:
            path = pathManager.protocolUri2CodeUriConverter(Uri.parse(`${VSLS_SCHEME}:${path}`)).fsPath;
            break;

        case vsls.SourceControlResourceType.External:
            if (path.startsWith('http:') || path.startsWith('https:')) { // tslint:disable-line:no-http-string
                // No scc params for external file
                return;
            }

            path = pathManager.protocolUri2CodeUriConverter(Uri.parse(
                path.startsWith(VSLS_SCHEME + ':') || path.startsWith(VSLS_EXTERNAL_SCHEME + ':') ? path : `${VSLS_EXTERNAL_SCHEME}:${path}`)).fsPath;

            break;

        default:
            // Not even a file or unknown type - no file path to deal with.
            return;
    }

    const result: GitResourceParams = resource.version ? JSON.parse(resource.version) : { ref: '' };
    result.path = path;
    return result;
}

function resourceFromGitParams(uri: Uri, pathManager: IPathManager, ref?: string | undefined, submoduleOf?: string | undefined): vsls.SourceControlResource | undefined {
    if (!uri) {
        return;
    }

    if (typeof ref === 'undefined' && typeof submoduleOf === 'undefined') {
        // No ref or submodule means a working directory resource or not source-controlled.
        return resourceFromUri(uri, pathManager);
    }

    if (uri.scheme !== 'file') {
        // Only files can be source-controlled.
        return;
    }

    return {
        type: vsls.SourceControlResourceType.SpecificVerision,
        path: uri.fsPath,
        version: JSON.stringify({ ref, submoduleOf }),
    };
}

function resourceFromUri(uri: Uri, pathManager: IPathManager): vsls.SourceControlResource | undefined {
    if (!uri) {
        return;
    }

    const workspaceUri = pathManager.code2protocolWorkspaceFilesOnly(uri);
    if (!workspaceUri) {
        return;
    }

    return {
        type: vsls.SourceControlResourceType.Workspace,
        path: workspaceUri.path,
    };
}

export function getChangeType(status: git.Status): vsls.SourceControlChangeType | undefined {
    switch (status) {
        case git.Status.ADDED_BY_THEM: return vsls.SourceControlChangeType.AddByThem;
        case git.Status.ADDED_BY_US: return vsls.SourceControlChangeType.AddByUs;
        case git.Status.BOTH_ADDED: return vsls.SourceControlChangeType.AddBoth;
        case git.Status.BOTH_DELETED: return vsls.SourceControlChangeType.DeleteBoth;
        case git.Status.BOTH_MODIFIED: return vsls.SourceControlChangeType.Conflict;
        case git.Status.DELETED: return vsls.SourceControlChangeType.Delete;
        case git.Status.DELETED_BY_THEM: return vsls.SourceControlChangeType.DeleteByThem;
        case git.Status.DELETED_BY_US: return vsls.SourceControlChangeType.DeleteByUs;
        case git.Status.IGNORED: return vsls.SourceControlChangeType.Ignored;
        case git.Status.INDEX_ADDED: return vsls.SourceControlChangeType.Add;
        case git.Status.INDEX_COPIED: return vsls.SourceControlChangeType.IndexCopy;
        case git.Status.INDEX_DELETED: return vsls.SourceControlChangeType.IndexDelete;
        case git.Status.INDEX_MODIFIED: return vsls.SourceControlChangeType.IndexEdit;
        case git.Status.INDEX_RENAMED: return vsls.SourceControlChangeType.Rename;
        case git.Status.MODIFIED: return vsls.SourceControlChangeType.Edit;
        case git.Status.UNTRACKED: return vsls.SourceControlChangeType.Untracked;

        default:
            return;
    }
}

function isDescendant(parent: string, descendant: string): boolean {
    if (parent === descendant) {
        return true;
    }

    if (parent.charAt(parent.length - 1) !== sep) {
        parent += sep;
    }

    // Windows is case insensitive
    if (isWindowsPath(parent)) {
        parent = parent.toLowerCase();
        descendant = descendant.toLowerCase();
    }

    return descendant.startsWith(parent);
}

function isWindowsPath(p: string): boolean {
    return /^[a-zA-Z]:\\/.test(p);
}

export class HostGitSourceControlProvider implements IHostSourceControlProvider {
    private instanceCount = 0;
    private readonly rootUriToInstanceId = new Map<string, string>();
    private readonly gitExtension: vscode.Extension<git.GitExtension>;
    private readonly sourceControlChanged = new vscode.EventEmitter<vsls.SourceControlChangedEventArgs>();
    private readonly sourceControlResourceChanged = new vscode.EventEmitter<vsls.SourceControlResourceChangedEventArgs>();
    private readonly disposables: vscode.Disposable[] = [];
    private readonly changedInstances = new Set<string>();

    // Map from repos instanceId to array of resources that have been provided by getResource().
    private readonly resourceCache = new Map<string, CacheRow[]>();
    private documentUriCacheCleanupTimer: NodeJS.Timer | undefined;
    private isDisposed = false;
    private subscribedToRepoChanges = false;

    constructor(
        private readonly fileService: vsls.FileService,
        private readonly pathManager: IPathManager) {
        this.gitExtension = vscode.extensions.getExtension<git.GitExtension>('vscode.git');
        if (this.isActive) {
            this.documentUriCacheCleanupTimer = setInterval(() => this.cleanupDocumentUriCache(), FIVE_MINUTES);
        }
    }

    @memoize private get gitApi(): git.API | undefined {
        try {
            return this.gitExtension && this.gitExtension.exports.getAPI(1);
        } catch {
            // Git is not enabled (git.enabled setting is false)
        }
    }

    public get isActive(): boolean {
        return !!(this.gitExtension && this.gitExtension.isActive && this.gitApi);
    }

    public readonly sourceControlId = SOURCE_CONTROL_ID;

    public async activate() {
        if (!this.gitExtension) {
            throw new Error('The VS Code Git extension is not enabled.');
        }

        await this.gitExtension.activate();
        if (this.isDisposed) {
            return;
        }

        this.subscribeToAllRepoChanges();
        if (!this.documentUriCacheCleanupTimer) {
            this.documentUriCacheCleanupTimer = setInterval(() => this.cleanupDocumentUriCache(), FIVE_MINUTES);
        }
    }

    public async getSourceControls(instanceId?: string | undefined, cancellationToken?: CancellationToken): Promise<vsls.SourceControlInstance[]> {
        if (!this.isActive) {
            return [];
        }

        const promises = this.gitApi.repositories
            .filter(r => !instanceId || this.isInstance(r, instanceId))
            .map(r => this.getVslsSourceControl(r));

        const result = await Promise.all(promises);
        return result.filter(s => s);
    }

    public async getRecentVersionsTillMergeVersion(mergeVersionHash: string, instanceId: string, cancellationToken?: vscode.CancellationToken): Promise<vsls.SourceControlVersion[]> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return [];
        }

        if (!repo.getGlobalConfig || !repo.getLog) {
            const version = repo.state.HEAD && this.getVersionFromCommitHash(repo.state.HEAD.commit);
            return version ? [version] : [];
        }

        const log: git.Commit[] = await repo.getLog({ maxEntries: MAX_RECENT_VERSION_COUNT });
        const index = log.findIndex(c => c.hash === mergeVersionHash);
        if (index >= 0 && index < log.length - 1) {
            log.splice(index + 1);
        }

        return log.map((c, i) => this.getVersionFromCommit(c, i)).filter(c => c);
    }

    public getRemoteVersionsNames(instanceId: string): Promise<string[]> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return Promise.resolve([]);
        }

        return Promise.resolve(repo.state.refs.map((r) => r.name));
    }

    public getCurrentVersionName(instanceId: string): Promise<string> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return Promise.resolve('');
        }

        return Promise.resolve(repo.state.HEAD.name);
    }

    public async getMergeVersion(instanceId: string, remoteVersionName: string, cancellationToken?: vscode.CancellationToken): Promise<vsls.SourceControlVersion> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return null;
        }

        const remoteRef: git.Branch = await repo.getBranch(remoteVersionName);
        const commit = await repo.getMergeBase(repo.state.HEAD.name, remoteRef.name);
        return this.getVersionFromCommitHash(commit);
    }

    public async getRecentVersions(instanceId: string, cancellationToken?: CancellationToken): Promise<vsls.SourceControlVersion[]> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return [];
        }

        if (!repo.getGlobalConfig || !repo.getLog) {
            const version = repo.state.HEAD && this.getVersionFromCommitHash(repo.state.HEAD.commit);
            return version ? [version] : [];
        }

        let userEmail = '';
        try {
            userEmail = await repo.getConfig('user.email');
        } catch {
        }

        if (!userEmail) {
            try {
                userEmail = await repo.getGlobalConfig('user.email');
            } catch {
            }
        }

        const log: git.Commit[] = await repo.getLog({ maxEntries: MAX_RECENT_VERSION_COUNT });
        const index = log.findIndex(c => c.authorEmail !== userEmail);
        if (index >= 0 && index < log.length - 1) {
            log.splice(index + 1);
        }

        return log.map((c, i) => this.getVersionFromCommit(c, i)).filter(c => c);
    }

    private getVersionFromCommit(commit: git.Commit, index: number): vsls.SourceControlVersion | undefined {
        return commit && this.getVersionFromCommitHash(commit.hash, commit.message, index);
    }

    private getVersionFromCommitHash(hash: string, message?: string | undefined, index?: number | undefined): vsls.SourceControlVersion | undefined {
        if (!hash) {
            return;
        }

        const label = message ? message.split('\n')[0] : `HEAD${index ? '~' + index : ''}`;
        const gitVersion: GitVersion = { ref: hash };
        const version = JSON.stringify(gitVersion);
        return { version, label, description: message };
    }

    public async getResource(resource: vsls.SourceControlResourceIdentifier, cancellationToken?: CancellationToken): Promise<string> {
        if (!resource || !this.isActive || this.isDisposed) {
            return '';
        }

        // Extract Git parameters from the resource
        // path - path to the file
        // ref - revision, version of the file to fetch
        // submoduleOf - if the resource is part of a submodule

        // tslint:disable-next-line:no-shadowed-variable
        let { path, ref, submoduleOf } = gitParamsFromResource(resource, this.pathManager);

        if (submoduleOf) {
            const submoduleRepo = this.getRepoContainingResource(submoduleOf);

            if (!submoduleRepo) {
                return '';
            }

            if (ref === 'index') {
                return await submoduleRepo.diffIndexWithHEAD(path);
            } else {
                return await submoduleRepo.diffWithHEAD(path);
            }
        }

        // Find the repository to get the resource from
        const repository = this.getRepoByInstanceId(resource.instanceId) || this.getRepoContainingResource(path);

        if (!repository) {
            return '';
        }

        const instanceId = this.getInstanceId(repository);

        // Save the resource type and path in the cache
        // If the repo changes, we'll be sending a notification about changed resource
        const cacheRow: CacheRow = {
            resource: { type: resource.type, path: resource.path, version: resource.version },
            timestamp: new Date().getTime()
        };
        const cache = this.resourceCache.get(instanceId);
        if (cache) {
            cache.push(cacheRow);
        } else {
            this.resourceCache.set(instanceId, [cacheRow]);
        }

        // Get the git ref
        if (ref === '~') {
            const fileUri = Uri.file(path);
            const uriString = fileUri.toString();
            const [indexStatus] = repository.state.indexChanges.filter(r => r && r.uri.toString() === uriString);
            ref = indexStatus ? '' : 'HEAD';
        } else if (/^~\d$/.test(ref)) {
            ref = `:${ref[1]}`;
        }

        // Fetch the resource from git repo
        try {
            return await repository.show(ref, path);
        } catch (err) {
            return '';
        }
    }

    public async getDiffForResource(resource: vsls.SourceControlResourceIdentifier, cancellationToken?: CancellationToken): Promise<vsls.SourceControlResourceDiff> {
        if (!resource || !resource.path || !this.isActive || this.isDisposed) {
            return null;
        }

        const instanceId = resource.instanceId;
        const groupId = resource.groupId;

        if (!instanceId || !groupId) {
            return null;
        }

        const repo: git.Repository = this.getRepoByInstanceId(instanceId);
        if (!repo) {
            return null;
        }

        let changes: git.Change[] = null;
        switch (resource.groupId) {
            case MERGE_GROUP_ID:
                changes = repo.state.mergeChanges;
                break;

            case INDEX_GROUP_ID:
                changes = repo.state.indexChanges;
                break;

            case WORKING_TREE_GROUP_ID:
                changes = repo.state.workingTreeChanges;
                break;

            default:
                return null;
        }

        const change = changes.find(c => {
            if (!c) {
                return false;
            }

            const r = resourceFromUri(c.uri, this.pathManager);
            return r && r.path === resource.path;
        });

        if (!change) {
            return null;
        }

        const resourceUri = change.uri;

        let stat: Stats | undefined;
        try {
            stat = await new Promise<Stats>((c, e) => fileAccess.lstat(resourceUri.fsPath, (err, s) => err ? e(err) : c(s)));
        } catch (err) {
            // noop
        }

        if (this.isDisposed) {
            return null;
        }

        let left: vsls.SourceControlResource;
        let right: vsls.SourceControlResource;

        if (stat && stat.isDirectory()) {
            const repository = this.getRepositoryForSubmodule(resourceUri);
            if (repository) {
                const ref = groupId === INDEX_GROUP_ID ? 'index' : 'wt';
                const submoduleOf = repository.rootUri.fsPath;
                right = resourceFromGitParams(resourceUri, this.pathManager, ref, submoduleOf);
            }
        } else {
            if (change.status !== git.Status.DELETED_BY_THEM) {
                left = await this.getLeftResource(change);
            }

            right = await this.getRightResource(change);
        }

        if (!right || this.isDisposed) {
            return null;
        }

        const changeType = getChangeType(change.status);
        const title = this.getTitle(change);
        return { left, right, title, changeType };
    }

    public async getDiffsForVersion(instanceId: string, version: string, cancellationToken?: CancellationToken): Promise<vsls.SourceControlResourceDiff[]> {
        const repo = this.getRepoByInstanceId(instanceId);
        if (!repo || !version) {
            return [];
        }

        const gitVersion: GitVersion = JSON.parse(version);
        let changes: git.Change[];
        if (repo.diffWorkingDirectoryWith) {
            changes = await repo.diffWorkingDirectoryWith(gitVersion.ref);
        } else {
            if (!repo.state.HEAD || repo.state.HEAD.commit !== gitVersion.ref) {
                return [];
            }

            // Calculate changes vs HEAD in the working directory.
            // These are staged changes and working directory changes,
            // the latter having the precedence.
            changes = [];
            const index = new Map<string, git.Change>(repo.state.indexChanges.map<[string, git.Change]>(c => [c.uri.toString(), c]));
            for (const change of repo.state.workingTreeChanges) {
                index.delete(change.uri.toString());
                changes.push(change);
            }

            changes.push(...index.values());
        }

        const diffs = changes.map(c => this.getResourceDiffFromChange(c, version)).filter(r => r);
        return await this.filterOutExternalHiddenExcludedFiles(diffs, d => (d.right || d.left).path);
    }

    public updateCommitMessages(updater: (message: string) => string) {
        if (!this.isActive || !updater) {
            return;
        }

        for (const repo of this.gitApi.repositories) {
            const message = repo.inputBox.value;
            const newMessage = updater(message);
            if (newMessage !== message) {
                repo.inputBox.value = newMessage;
            }
        }
    }

    private getResourceDiffFromChange(change: git.Change, leftVersion: string): vsls.SourceControlResourceDiff | undefined {
        if (!change) {
            return;
        }

        let left: vsls.SourceControlResource = undefined;
        if (change.status !== git.Status.INDEX_ADDED) {
            left = resourceFromUri(change.originalUri, this.pathManager);
            if (left.type !== vsls.SourceControlResourceType.Workspace) {
                return;
            }

            left.type = vsls.SourceControlResourceType.WorkspaceWithSpecificVersion;
            left.version = leftVersion;
        }

        const right = resourceFromUri(change.uri, this.pathManager);
        let changeType = getChangeType(change.status);

        let title: string = path.basename(change.uri.fsPath);
        switch (change.status) {
            case git.Status.MODIFIED:
                title += ' (Modified)';
                break;

            case git.Status.UNTRACKED:
            case git.Status.INDEX_ADDED:
                title += ' (Added)';
                changeType = vsls.SourceControlChangeType.Add;
                break;

            case git.Status.INDEX_RENAMED:
                title += ' (Renamed)';
                break;

            case git.Status.DELETED:
                title += ' (Deleted)';
                break;

            default:
                break;
        }

        return { right, changeType, left, title };
    }

    public async cleanResources(resources: vsls.SourceControlResourceIdentifier[], cancellationToken?: CancellationToken) {
        if (!this.isActive || this.isDisposed) {
            return;
        }

        const resourceByInstanceId = new Map<string, vsls.SourceControlResource[]>();
        for (const r of resources) {
            if (!r || !r.instanceId) {
                continue;
            }

            const instanceId = r.instanceId;
            const resourceList = resourceByInstanceId.get(instanceId);
            if (resourceList) {
                resourceList.push(r);
            } else {
                resourceByInstanceId.set(instanceId, [r]);
            }
        }

        for (const [instanceId, resourceList] of resourceByInstanceId) {
            const repo: git.Repository = this.getRepoByInstanceId(instanceId);
            if (!repo) {
                continue;
            }

            const paths: string[] = [];
            for (const resource of resourceList) {
                const gitParams = gitParamsFromResource(resource, this.pathManager);
                if (gitParams && gitParams.path) {
                    paths.push(gitParams.path);
                }
            }

            await repo.clean(paths);
            if (this.isDisposed) {
                return;
            }
        }
    }

    public isSourceControlled(uri: Uri): boolean {
        return !!this.getRepoContainingResource(uri);
    }

    private async getRightResource(change: git.Change): Promise<vsls.SourceControlResource | undefined> {
        if (!change) {
            return;
        }

        switch (change.status) {
            case git.Status.INDEX_MODIFIED:
            case git.Status.INDEX_ADDED:
            case git.Status.INDEX_COPIED:
            case git.Status.INDEX_RENAMED:
                return this.getResourceFromGitParams(change.uri, '');

            case git.Status.INDEX_DELETED:
            case git.Status.DELETED:
                return this.getResourceFromGitParams(change.uri, 'HEAD');

            case git.Status.DELETED_BY_US:
                return this.getResourceFromGitParams(change.uri, '~3');

            case git.Status.DELETED_BY_THEM:
                return this.getResourceFromGitParams(change.uri, '~2');

            case git.Status.MODIFIED:
            case git.Status.UNTRACKED:
            case git.Status.IGNORED:
                const repository = this.getRepoContainingResource(change.uri);

                if (!repository) {
                    return;
                }

                const uriString = change.uri.toString();
                const [indexStatus] = repository.state.indexChanges.filter(c => c.uri.toString() === uriString);

                if (indexStatus && indexStatus.renameUri) {
                    return resourceFromGitParams(indexStatus.renameUri, this.pathManager);
                }

                return resourceFromGitParams(change.uri, this.pathManager);

            case git.Status.BOTH_ADDED:
            case git.Status.BOTH_MODIFIED:
                return resourceFromGitParams(change.uri, this.pathManager);

            default:
                return;
        }
    }

    private async getLeftResource(change: git.Change): Promise<vsls.SourceControlResource | undefined> {
        if (!change) {
            return;
        }

        switch (change.status) {
            case git.Status.INDEX_MODIFIED:
            case git.Status.INDEX_RENAMED:
                return this.getResourceFromGitParams(change.originalUri, 'HEAD');

            case git.Status.MODIFIED:
                return this.getResourceFromGitParams(change.uri, '~');

            case git.Status.DELETED_BY_THEM:
                return this.getResourceFromGitParams(change.uri, '');

            default:
                return undefined;
        }
    }

    private getTitle(change: git.Change): string {
        if (!change || !change.uri) {
            return '';
        }

        const basename = path.basename(change.uri.fsPath);

        switch (change.status) {
            case git.Status.INDEX_MODIFIED:
            case git.Status.INDEX_RENAMED:
                return `${basename} (Index)`;

            case git.Status.MODIFIED:
            case git.Status.BOTH_ADDED:
            case git.Status.BOTH_MODIFIED:
                return `${basename} (Working Tree)`;

            case git.Status.DELETED_BY_US:
                return `${basename} (Theirs)`;

            case git.Status.DELETED_BY_THEM:
                return `${basename} (Ours)`;

            default:
                return '';
        }
    }

    private async getResourceFromGitParams(uri: Uri, ref: string): Promise<vsls.SourceControlResource | undefined> {
        const repository = this.getRepoContainingResource(uri);

        if (!repository) {
            return resourceFromGitParams(uri, this.pathManager, ref);
        }

        try {
            let gitRef = ref;

            if (gitRef === '~') {
                const uriString = uri.toString();
                const [indexStatus] = repository.state.indexChanges.filter(r => r.uri && r.uri.toString() === uriString);
                gitRef = indexStatus ? '' : 'HEAD';
            }

            const { size, object } = await repository.getObjectDetails(gitRef, uri.fsPath);
            const { mimetype } = await repository.detectObjectType(object);

            if (mimetype === 'text/plain') {
                return resourceFromGitParams(uri, this.pathManager, ref);
            }

            if (size > 1000000) { // 1 MB
                return {
                    type: vsls.SourceControlResourceType.External,
                    path: `data:;label:${path.basename(uri.fsPath)};description:${gitRef},`,
                };
            }

            if (IMAGE_MIME_TYPES.indexOf(mimetype) > -1) {
                const contents = await repository.buffer(gitRef, uri.fsPath);
                return {
                    type: vsls.SourceControlResourceType.External,
                    path: `data:${mimetype};label:${path.basename(uri.fsPath)};description:${gitRef};size:${size};base64,${contents.toString('base64')}`,
                };
            }

            return {
                type: vsls.SourceControlResourceType.External,
                path: `data:;label:${path.basename(uri.fsPath)};description:${gitRef},`,
            };
        } catch (err) {
            return resourceFromGitParams(uri, this.pathManager, ref);
        }
    }

    public onSourceControlChanged(listener: (e: vsls.SourceControlChangedEventArgs) => any, thisArgs?: any, disposables?: Disposable[]): Disposable {
        this.subscribeToAllRepoChanges();
        return this.sourceControlChanged.event(listener, thisArgs, disposables);
    }

    public onResourceChanged(listener: (e: vsls.SourceControlResourceChangedEventArgs) => any, thisArgs?: any, disposables?: Disposable[]): Disposable {
        this.subscribeToAllRepoChanges();
        return this.sourceControlResourceChanged.event(listener, thisArgs, disposables);
    }

    public dispose() {
        this.isDisposed = true;
        this.disposables.forEach(d => d.dispose());
        if (this.documentUriCacheCleanupTimer) {
            clearInterval(this.documentUriCacheCleanupTimer);
            this.documentUriCacheCleanupTimer = void 0;
        }
    }

    private async getVslsSourceControl(repo: git.Repository): Promise<vsls.SourceControlInstance | undefined> {
        if (!repo) {
            return;
        }

        const name = repo.rootUri ? path.basename(repo.rootUri.fsPath) || repo.rootUri.fsPath : '';

        return {
            sourceControlId: this.sourceControlId,
            instanceId: this.getInstanceId(repo),
            label: 'Git',
            name,
            resourceGroups: await this.getVslsResourceGroups(repo),
        };
    }

    private async getVslsResourceGroups(repo: git.Repository): Promise<vsls.SourceControlResourceGroup[]> {
        if (!repo) {
            return [];
        }

        // Check if git.Repository has clean() API to verify that
        // VSCode git provider has changes needed to support VSLS.
        if (!repo.clean) {
            return [{
                groupId: NOT_SUPPORTED_GROUP_ID,
                label: 'N/A. Ask host to update VSCode to get SCC in collaboration session.'
            }];
        }

        const state = repo.state;
        return [
            {
                groupId: MERGE_GROUP_ID,
                label: 'Merge Changes',
                hideWhenEmpty: true,
                supportsOpenFile: true,
                resourceStates: await this.getVslsResourceStates(state.mergeChanges)
            },
            {
                groupId: INDEX_GROUP_ID,
                label: 'Staged Changes',
                hideWhenEmpty: true,
                supportsOpenChanges: true,
                supportsOpenFile: true,
                resourceStates: await this.getVslsResourceStates(state.indexChanges)
            },
            {
                groupId: WORKING_TREE_GROUP_ID,
                label: 'Changes',
                supportsClean: true,
                supportsOpenChanges: true,
                supportsOpenFile: true,
                resourceStates: await this.getVslsResourceStates(state.workingTreeChanges)
            },
        ];
    }

    private async getVslsResourceStates(changes: git.Change[]): Promise<vsls.SourceControlResourceState[]> {
        const result = (changes || []).map(c => this.getVslsResourceState(c)).filter(r => r);

        // Remove hidden, excluded, and external files
        return await this.filterOutExternalHiddenExcludedFiles(result, r => r.current.path);
    }

    private async filterOutExternalHiddenExcludedFiles<T>(list: T[], pathGetter: (item: T) => string): Promise<T[] | undefined> {
        if (!list) {
            return;
        }

        if (!list.length) {
            return [];
        }

        const files = await this.fileService.listAsync(list.map(pathGetter), { includeExcluded: true, includeHidden: true });
        const result: T[] = [];
        for (let index = 0; index < list.length && index < files.length; index++) {
            const attributes = files[index].attributes;
            if (attributes !== vsls.FileAttributes.External &&
                attributes !== vsls.FileAttributes.Hidden &&
                attributes !== vsls.FileAttributes.Excluded) {

                result.push(list[index]);
            }
        }

        return result;
    }

    private getVslsResourceState(change: git.Change): vsls.SourceControlResourceState | undefined {
        // Only return files within the workspace
        if (!change) {
            return;
        }

        const current = resourceFromGitParams(change.uri, this.pathManager);
        if (!current) {
            return;
        }

        const changeType = getChangeType(change.status);
        const result: vsls.SourceControlResourceState = { changeType, current };
        if (change.originalUri && change.uri && change.uri.toString() !== change.originalUri.toString()) {
            result.original = resourceFromGitParams(change.originalUri, this.pathManager);
        }

        return result;
    }

    private subscribeToAllRepoChanges() {
        if (!this.subscribedToRepoChanges && this.isActive && !this.isDisposed) {
            this.gitApi.onDidOpenRepository(this.onDidOpenRepository, this, this.disposables);
            this.gitApi.onDidCloseRepository(this.onDidCloseRepository, this, this.disposables);
            this.gitApi.repositories.forEach(r => this.subscribeToRepoChanges(r));
            this.subscribedToRepoChanges = true;
        }
    }

    private subscribeToRepoChanges(repo: git.Repository) {
        repo.state.onDidChange(() => this.repoChanged(repo), this, this.disposables);
    }

    private repoChanged(repo: git.Repository) {
        this.fireSourceControlChangedEvent(repo, vsls.SourceControlChange.Updated);
        this.changedInstances.add(this.getInstanceId(repo));
        this.eventuallyFireDocumentChangeEvents();
    }

    private fireSourceControlChangedEvent(repo: git.Repository, change: vsls.SourceControlChange) {
        this.sourceControlChanged.fire({
            sourceControl: {
                sourceControlId: this.sourceControlId,
                instanceId: this.getInstanceId(repo),
            },
            change
        });
    }

    @debounce(1100)
    private eventuallyFireDocumentChangeEvents(): void {
        this.fireDocumentChangeEvents();
    }

    private async fireDocumentChangeEvents(): Promise<void> {
        for (const instanceId of this.changedInstances) {
            const cacheRows = this.resourceCache.get(instanceId);
            if (!cacheRows || !cacheRows.length) {
                continue;
            }

            this.sourceControlResourceChanged.fire({
                sourceControl: { sourceControlId: this.sourceControlId, instanceId },
                resources: cacheRows.map(r => r.resource)
            });
        }

        this.changedInstances.clear();
    }

    private onDidOpenRepository(repo: git.Repository) {
        this.subscribeToRepoChanges(repo);
        this.fireSourceControlChangedEvent(repo, vsls.SourceControlChange.Added);
    }

    private onDidCloseRepository(repo: git.Repository) {
        this.fireSourceControlChangedEvent(repo, vsls.SourceControlChange.Removed);
    }

    private getRepoByInstanceId(instanceId: string): git.Repository | undefined {
        if (!this.isActive || this.isDisposed || !instanceId) {
            return;
        }

        return this.gitApi.repositories.find(r => this.isInstance(r, instanceId));
    }

    private getInstanceId(repo: git.Repository): string | undefined {
        if (!repo || !repo.rootUri) {
            return;
        }

        const rootUri = repo.rootUri.toString();
        let result = this.rootUriToInstanceId.get(rootUri);
        if (!result) {
            this.instanceCount++;
            result = this.instanceCount.toString(10);
            this.rootUriToInstanceId.set(rootUri, result);
        }

        return result;
    }

    private isInstance(repo: git.Repository, instanceId: string): boolean {
        return repo && repo.rootUri && instanceId && this.rootUriToInstanceId.get(repo.rootUri.toString()) === instanceId;
    }

    private getRepoContainingResource(resource: string | Uri): git.Repository | undefined {
        if (!resource) {
            return;
        }

        if (typeof resource === 'string') {
            resource = Uri.file(resource);
        }

        if (resource instanceof Uri) {
            const resourcePath = resource.fsPath;

            outer:
            for (const repository of this.gitApi.repositories.sort((a, b) => a.rootUri.fsPath.length - b.rootUri.fsPath.length)) {
                const repoRoot = repository.rootUri.fsPath;
                if (!isDescendant(repoRoot, resourcePath)) {
                    continue;
                }

                for (const submodule of repository.state.submodules) {
                    const submoduleRoot = path.join(repoRoot, submodule.path);
                    if (isDescendant(submoduleRoot, resourcePath)) {
                        continue outer;
                    }
                }

                return repository;
            }
        }
    }

    private getRepositoryForSubmodule(submoduleUri: Uri): git.Repository | undefined {
        for (const repository of this.gitApi.repositories) {
            for (const submodule of repository.state.submodules) {
                const submodulePath = path.join(repository.rootUri.fsPath, submodule.path);

                if (submodulePath === submoduleUri.fsPath) {
                    return repository;
                }
            }
        }

        return undefined;
    }

    private cleanupDocumentUriCache(): void {
        const now = new Date().getTime();

        for (const [instanceId, rows] of this.resourceCache) {
            for (let index = rows.length - 1; index >= 0; index--) {
                if (now - rows[index].timestamp >= THREE_MINUTES) {
                    rows.splice(index, 1);
                }
            }

            if (!rows.length) {
                this.resourceCache.delete(instanceId);
            }
        }
    }
}
