import { LogLevel } from './interfaces/LogLevel';
import { ILogger } from './interfaces/ILogger';

/**
 * Base implementation of the ILogger interface.
 */
export abstract class LoggerBase implements ILogger {
    constructor(public readonly name: string) {
    }

    public abstract log(logLevel: LogLevel, message: string, ...args: any[]): this;

    public error(message: string, ...args: any[]): this {
        this.log(LogLevel.Error, message, ...args);

        return this;
    }

    public warning(message: string, ...args: any[]): this {
        this.log(LogLevel.Warning, message, ...args);

        return this;
    }

    public info(message: string, ...args: any[]): this {
        this.log(LogLevel.Info, message, ...args);

        return this;
    }

    public verbose(message: string, ...args: any[]): this {
        this.log(LogLevel.Debug, message, ...args);
        return this;
    }

    public abstract withName(name: string): ILogger

    public createChild(name: string): ILogger {
        return this.withName(this.name + ':' + name);
    }
}

/**
 * A logger implementation that use a callback to log the values.
 */
export class Logger extends LoggerBase {
    constructor(name: string,
        private readonly logCallback:(logLevel: LogLevel, message: string, ...args: any[]) => void) {
        super(name);
    }

    public log(logLevel: LogLevel, message: string, ...args: any[]): this {
        this.logCallback(logLevel, message, ...args);

        return this;
    }


    public withName(name: string): ILogger {
        return new Logger(name, this.logCallback);
    }
};
