import * as vscode from 'vscode';
import { AudioSessionContext, AudioSessionState, AudioSessionEvents } from './AudioSessionContext';
import { TraceSource } from '@vs/vso-logging';
import { ExtensionUtil, CommandContext, localize, HandledQuickPickItem } from '@vs/liveshare-core';
import { CallingServiceManager } from './CallingServiceManager';
import { CallingServiceCommands } from '../constants';

export class AudioStatusBarController {
    private audioConnectedStatusBarItem: vscode.StatusBarItem;
    private currentState: StatusBarState;
    private updateStatusBarPromise: Promise<void>;

    constructor(
        private callingServiceManager: CallingServiceManager,
        private trace: TraceSource
    ) {
        this.updateStatusBarPromise = Promise.resolve();

        this.audioConnectedStatusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 2);
        this.audioConnectedStatusBarItem.hide();

        this.updateStatusBar(new NoAudioState());

        AudioSessionContext.addListener(AudioSessionEvents.StateChanged, async (newState: AudioSessionState, previousState: AudioSessionState) => {
            return await this.onSessionStateChanged(newState);
        });

        this.callingServiceManager.onMuteChanged(async () => await this.onMuteChanged());
    }

    private async onMuteChanged(): Promise<void> {
        const isMuted = await this.callingServiceManager.isMuted();
        this.trace.info(`mute changed isMuted:${isMuted}`);
        this.audioConnectedStatusBarItem.text = isMuted ? '$(mute)' : '$(unmute)';
    }

    private updateStatusBar(newState: StatusBarState) {
        const previousState = this.currentState;
        this.currentState = newState;
        if (previousState) {
            previousState.dispose();
        }
        newState.updateAudioConnectedStatusBarItem(this.audioConnectedStatusBarItem);
    }

    private async onSessionStateChanged(newState: AudioSessionState): Promise<void> {
        let newStatusBarState = this.getStatusBarState(newState);
        this.updateStatusBarPromise = this.updateStatusBarPromise.then(async () => {
            this.updateStatusBar(newStatusBarState);
            await ExtensionUtil.setCommandContext(CommandContext.audioSessionState, newState.toString());
        });
    }

    private getStatusBarState(state: AudioSessionState): StatusBarState {
        switch (state) {
            case AudioSessionState.LiveShareWithAudio:
                return new LiveShareWithAudioState(this.callingServiceManager);
            default:
                return new NoAudioState();
        }
    }
}

export abstract class StatusBarState {
    protected disposed: boolean = false;
    public updateStatusBarItem(item: vscode.StatusBarItem): void {
        this.hideItem(item);
    }

    public updateAudioConnectedStatusBarItem(item: vscode.StatusBarItem) {
        this.hideItem(item);
    }

    public hideItem(item: vscode.StatusBarItem) {
        item.hide();
        item.text = undefined;
        item.command = undefined;
        item.tooltip = undefined;
    }

    protected showQuickPick(items: HandledQuickPickItem[], options?: vscode.QuickPickOptions) {
        return vscode.window.showQuickPick(items.filter(item => item.enabled()), options);
    }

    public dispose() {
        this.disposed = true;
    }
}

export class NoAudioState extends StatusBarState { }

export class LiveShareWithAudioState extends StatusBarState {
    constructor(private callingService: CallingServiceManager) {
        super();
    }

    public async updateAudioConnectedStatusBarItem(statusBarItem: vscode.StatusBarItem) {
        const commandId = CallingServiceCommands.callSettings;
        await ExtensionUtil.tryRegisterCommand(commandId,
            async() => {
                return this.showQuickPick(await this.connectedQuickPickItems(), { placeHolder: localize('calling.quickPickConnectedPlaceholder') })
                    .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
            });

        statusBarItem.text = await this.callingService.isMuted() ? '$(mute)' : '$(unmute)';
        statusBarItem.command = commandId;
        statusBarItem.show();
    }

    private async connectedQuickPickItems(): Promise<HandledQuickPickItem[]> {
        let isMuted = await this.callingService.isMuted();
        let quickPickItems = [
            {
                label: localize('calling.quickPickDisconnectLabel'),
                description: '',
                detail: localize('calling.quickPickDisconnectDetail'),
                command: CallingServiceCommands.endCall,
                enabled: () => true
            },
            {
                label: isMuted ? localize('calling.quickPickUnmuteYourselfLabel') : localize('calling.quickPickMuteYourselfLabel'),
                description: '',
                detail: isMuted ? localize('calling.quickPickUnmuteYourselfDetail') : localize('calling.quickPickMuteYourselfDetail'),
                command: CallingServiceCommands.muteOrUnmute,
                enabled: () => true
            },
            {
                label: localize('calling.quickPickViewParticipantsLabel'),
                description: '',
                detail: localize('calling.quickPickViewParticipantsDetail'),
                command: CallingServiceCommands.viewParticipants,
                enabled: () => true
            },
            {
                label: localize('calling.quickPickConfigureSpeakersLabel'),
                description: '',
                detail: localize('calling.quickPickConfigureSpeakersDetail'),
                command: CallingServiceCommands.selectSpeaker,
                enabled: () => true
            },
            {
                label: localize('calling.quickPickConfigureMicrophoneLabel'),
                description: '',
                detail: localize('calling.quickPickConfigureMicrophoneDetail'),
                command: CallingServiceCommands.selectMicrophone,
                enabled: () => true
            }
        ];

        return quickPickItems;
    }
}
