'use strict';

import * as vscode from 'vscode';
import { ICommandContext, ICommandConstructor, Constructor } from '@vs/vscode-command-framework';

import { ICommand } from './abstractions/ICommand';
import { ICommandDecoratorCallback } from './abstractions/ICommandDecorator';
import { IMethodDecorators } from './abstractions/IMethodDecorators';
import { DecoratorHelper } from './utils/DecoratorHelper';
import { errorNotificationCommandDecoratorFactory } from './decorators/errorNotificationCommandDecoratorFactory';
import { IDependencies } from './contracts/IDependencies';
import { telemetryCommandDecoratorFactory } from './decorators/TelemetryCommandDecoratorFactory';

export const methodDecoratorsFactory = (dependencies: IDependencies): IMethodDecorators => {
    /**
     * Method decorator adding an error notification command adaptor that converts exceptions into the correct
     * notification toast.
     */
    function errorNotificationMethodDecorator(
        title: string,
        telemetryFaultEventName: string,
        onError?: ICommandDecoratorCallback
    ) {
        return function (target: any, propertyKey: PropertyKey, descriptor: PropertyDescriptor) {
            return BindingHelper.bindCommandDecorator(
                (command: ICommand<any>) => errorNotificationCommandDecoratorFactory(
                    command,
                    dependencies,
                    telemetryFaultEventName,
                    title,
                    false,
                    onError
                ),
                target,
                propertyKey,
                descriptor
            );
        };
    }

    /**
     * Method decorator adding an instrumentation command adaptor that automatically sets up any
     * default telemetry and tracing.
     */
    function telemetryMethodDecorator(
        telemetryEventName: string,
        telemetryFaultEventName: string,
        telemetryTitle: string,
        telemetryEventVersion?: number,
        onError?: ICommandDecoratorCallback
    ) {
        return function (target: any, propertyKey: PropertyKey, descriptor: PropertyDescriptor) {
            return BindingHelper.bindCommandDecorator(
                (command: ICommand<any>) => telemetryCommandDecoratorFactory(command, dependencies, telemetryEventName, telemetryFaultEventName, telemetryTitle, telemetryEventVersion, onError),
                target,
                propertyKey,
                descriptor
            );
        };
    }

    // tslint:disable-next-line:variable-name
    function ControllerMixin<TBase extends Constructor>(BaseType: TBase) {
        return class extends BaseType {
            private readonly commandContextBuilder = dependencies.commandContextBuilder();
            private readonly bindingContext: BindingContext = (<any>BaseType).bindingContext;
            private readonly commandRegistrations: vscode.Disposable[] = [];

            public registerCommands(): void {
                this.bindingContext.commandBindings.forEach(binding => {
                    const commandConstructor = this.bindingContext.commandAdaptors.get(binding.methodName);
                    const registration = vscode.commands.registerCommand(
                        binding.commandName,
                        (...args: any[]) => {
                            const instance = new commandConstructor(this);
                            const commandContext = this.commandContextBuilder.build(instance, binding.commandName, BaseType.name);
                            return instance.invoke(args, commandContext);
                        },
                        this
                    );
                    this.commandRegistrations.push(registration);
                });
            }

            public unregisterCommands(): void {
                const removed = this.commandRegistrations.splice(0);
                removed.forEach(d => d.dispose());
            }
        };
    }

    /**
     * Class decorator designating a class instance to be able binding and handling VSCode commands.
     * Extends the base class with new methods to register/unregister commands as declared by command bindings.
     * @param target Target type with command bindings (controller)
     */
    function controllerDecorator(target: any) {
        return ControllerMixin(target);
    }

    return {
        errorNotificationMethodDecorator,
        telemetryMethodDecorator,
        controllerDecorator
    };
};

/**
 * Method decorator creating a command binding.
 * The controller instance will create a command adaptor class invoking the target method to handle the specified VSCode command.
 * @param commandName VSCode command name
 */
export function commandBindingDecorator(commandName: string) {
    return function (target: any, propertyKey: PropertyKey, descriptor: PropertyDescriptor) {
        BindingHelper.bindCommand(commandName, target, propertyKey, descriptor);
    };
}

interface CommandBinding {
    readonly commandName: string;
    readonly methodName: PropertyKey;
    readonly descriptor: PropertyDescriptor;
}

class BindingContext {
    public readonly commandAdaptors: Map<PropertyKey, ICommandConstructor<any>> = new Map<PropertyKey, ICommandConstructor<any>>();
    public readonly commandBindings: CommandBinding[] = [];
}

class BindingHelper {
    private static getBindingContext(controllerType: any): BindingContext {
        if (!controllerType.constructor.bindingContext) {
            controllerType.constructor.bindingContext = new BindingContext();
        }
        return controllerType.constructor.bindingContext;
    }

    public static bindCommand(
        commandName: string,
        controllerType: any,
        methodName: PropertyKey,
        descriptor: PropertyDescriptor
    ) {
        const bindingContext = BindingHelper.getBindingContext(controllerType);
        bindingContext.commandBindings.push({ commandName, methodName, descriptor });
        BindingHelper.getOrCreateCommandAdapter(bindingContext, methodName, descriptor);
    }

    private static getOrCreateCommandAdapter(
        bindingContext: BindingContext,
        methodName: PropertyKey,
        descriptor: PropertyDescriptor
    ): ICommandConstructor<any> {
        let commandAdaptor = bindingContext.commandAdaptors.get(methodName);
        if (!commandAdaptor) {
            if (typeof descriptor.value === 'function') {
                commandAdaptor = class CommandMethodAdapter implements ICommand<void> {
                    public constructor(private readonly controller: ControllerHelper) { }
                    public async invoke(options: any, context: ICommandContext): Promise<void> {
                        // unpack original command arguments array and drop the command context
                        await descriptor.value.apply(this.controller, options);
                    }
                };
            } else if (typeof descriptor.get === 'function') {
                commandAdaptor = class CommandMethodAdapter implements ICommand<void> {
                    public constructor(private readonly controller: ControllerHelper) { }
                    public async invoke(options: any, context: ICommandContext): Promise<void> {
                        // unpack original command arguments array and drop the command context
                        await descriptor.get.apply(this.controller, options);
                    }
                };
            } else {
                throw new Error('Unsupported command binding.');
            }
            bindingContext.commandAdaptors.set(methodName, commandAdaptor);
        }
        return commandAdaptor;
    }

    public static bindCommandDecorator(
        builder: (n: ICommand<any>) => ICommand<any>,
        controllerType: any,
        methodName: PropertyKey,
        descriptor: PropertyDescriptor
    ): PropertyDescriptor {
        const bindingContext = BindingHelper.getBindingContext(controllerType);
        const commandAdaptor = BindingHelper.getOrCreateCommandAdapter(bindingContext, methodName, descriptor);
        const decoratedAdaptor = DecoratorHelper.setupDecorator(builder)(commandAdaptor);
        bindingContext.commandAdaptors.set(methodName, decoratedAdaptor);

        return descriptor;
    }
}

/**
 * Helper class providing the API to manage command controllers.
 */
export class ControllerHelper {
    /**
     * Registers controller commands and returns a disposable registration object.
     * @param controller Command controller instance. The controller class should be decorated with controllerDecorator.
     * @param disposables Collection of disposable objects where the registration object will be added to.
     */
    public static register(controller: any, disposables?: vscode.Disposable[]): vscode.Disposable {
        if (!controller.registerCommands || !controller.unregisterCommands) {
            throw new Error(controller.constructor.name + ' is not a command controller.');
        }
        controller.registerCommands();
        const disposable = new vscode.Disposable(() => {
            controller.unregisterCommands();
        });
        if (disposables) {
            disposables.push(disposable);
        }
        return disposable;
    }
}
