import { LogLevel } from '../interfaces/LogLevel';
import { TraceFormat } from '../TraceFormat';
import { TraceListener } from '../TraceListener';

/**
 * A memory trace listener.
 */
export class MemoryTraceListener extends TraceListener {
    private readonly allLogs: string[] = [];
    private readonly logsByLevel = new Map<LogLevel, string[]>();
    private readonly maxLogSize: number;

    constructor(maxLogSize?: number) {
        super();
        this.maxLogSize = maxLogSize || 128;
    }

    public getLogs(logLevel?: LogLevel): string[] {
        if (logLevel) {
            const logs = this.logsByLevel.get(logLevel);
            return logs ? logs.map(i => i) : [];
        }

        return this.allLogs.map(i => i);
    }

    public writeTo(line: string): void {
        this.addLine(line);
    }

    private addLine(line: string, logLevel?: LogLevel) {
        this.allLogs.push(line);
        if (this.allLogs.length > this.maxLogSize) {
            this.allLogs.splice(0, 1);
        }

        if (logLevel) {
            const logEntries = this.logsByLevel.get(logLevel);
            if (!logEntries) {
                this.logsByLevel.set(logLevel, [line]);
            } else {
                logEntries.push(line);
                if (logEntries.length > this.maxLogSize) {
                    logEntries.splice(0, 1);
                }
            }
        }
    }

    protected writeEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void {
        const line = TraceFormat.formatEvent(new Date(), source, logLevel, id, message, ...args);
        this.addLine(line, logLevel);
    };
};
