import * as vscode from 'vscode';

import { DisposableClass } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';

import { dataScrapingManagerInstance } from '../data-scraper/dataScrapingManager';
import { VscodeActivityType } from './VscodeActivityType';

export abstract class VscodeActivityProvider extends DisposableClass {
    constructor(trace: ILogger) {
        super(trace.createChild('vscode-activity-provider'));

        // Workspace events
        this.addToDisposables(
            VscodeActivityProvider.vscode.workspace.onDidChangeTextDocument((e) => {
                this.onActivity(VscodeActivityType.changeTextDocument);
            }),
            VscodeActivityProvider.vscode.workspace.onDidOpenTextDocument((e) => {
                this.onActivity(VscodeActivityType.openTextDocument);
            }),
            VscodeActivityProvider.vscode.workspace.onDidCloseTextDocument((e) => {
                this.onActivity(VscodeActivityType.closeTextDocument);
            }),
            VscodeActivityProvider.vscode.workspace.onDidSaveTextDocument((e) => {
                this.onActivity(VscodeActivityType.saveTextDocument);
            }),
            // Debug events
            VscodeActivityProvider.vscode.debug.onDidStartDebugSession((e) => {
                this.onActivity(VscodeActivityType.startDebugSession);
            }),
            VscodeActivityProvider.vscode.debug.onDidTerminateDebugSession((e) => {
                this.onActivity(VscodeActivityType.terminateDebugSession);
            }),
            VscodeActivityProvider.vscode.debug.onDidChangeBreakpoints((e) => {
                this.onActivity(VscodeActivityType.changeBreakpoints);
            }),
            // Task events
            VscodeActivityProvider.vscode.tasks.onDidStartTask((e) => {
                this.onActivity(VscodeActivityType.startTask);
            }),
            VscodeActivityProvider.vscode.tasks.onDidEndTask((e) => {
                this.onActivity(VscodeActivityType.endTask);
            }),
            VscodeActivityProvider.vscode.tasks.onDidStartTaskProcess((e) => {
                this.onActivity(VscodeActivityType.startTaskProcess);
            }),
            VscodeActivityProvider.vscode.tasks.onDidEndTaskProcess((e) => {
                this.onActivity(VscodeActivityType.endTaskProcess);
            }),
            // Window events
            VscodeActivityProvider.vscode.window.onDidChangeActiveTextEditor((e) => {
                this.onActivity(VscodeActivityType.changeActiveTextEditor);
            }),
            VscodeActivityProvider.vscode.window.onDidOpenTerminal((e) => {
                this.onActivity(VscodeActivityType.openTerminal);
            }),
            VscodeActivityProvider.vscode.window.onDidCloseTerminal((e) => {
                this.onActivity(VscodeActivityType.closeTerminal);
            }),
        );

        // Terminal activity
        dataScrapingManagerInstance
            .registerDataScraper('vscodeEventsRegistration', () => {
                /**
                 * It is important that we don't just send self(`this`) as the
                 * terminal because the whole monitor will be disposed when
                 * the terminal data scraping worker is disposed.
                 */
                return {
                    init: this.onActivity.bind(this),
                    processData: this.onActivity.bind(this),
                    dispose() {},
                };
            })
            .then((disposable) => {
                this.addToDisposables(disposable);
            });

        // Notebook events (still in proposed API right now)
        // Cast to any to avoid compile errors until the minimum VS Code version
        // is updated to a version where the Notebooks events are guaranteed to exist
        const notebook = (VscodeActivityProvider.vscode as any).notebook;
        if (notebook) {
            try {
                if (typeof notebook.onDidOpenNotebookDocument === 'function') {
                    this.addToDisposables(
                        notebook.onDidOpenNotebookDocument(() => {
                            this.onActivity(VscodeActivityType.openNotebookDocument);
                        }),
                    );
                }
                if (typeof notebook.onDidCloseNotebookDocument === 'function') {
                    this.addToDisposables(
                        notebook.onDidCloseNotebookDocument(() => {
                            this.onActivity(VscodeActivityType.closeNotebookDocument);
                        }),
                    );
                }
                if (typeof notebook.onDidSaveNotebookDocument === 'function') {
                    this.addToDisposables(
                        notebook.onDidSaveNotebookDocument(() => {
                            this.onActivity(VscodeActivityType.saveNotebookDocument);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeVisibleNotebookEditors === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeVisibleNotebookEditors(() => {
                            this.onActivity(VscodeActivityType.changeVisibleNotebookEditors);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeNotebookEditorSelection === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeNotebookEditorSelection(() => {
                            this.onActivity(VscodeActivityType.changeNotebookEditorSelection);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeNotebookCells === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeNotebookCells(() => {
                            this.onActivity(VscodeActivityType.changeNotebookCells);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeCellOutputs === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeCellOutputs(() => {
                            this.onActivity(VscodeActivityType.changeCellOutputs);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeActiveNotebookEditor === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeActiveNotebookEditor(() => {
                            this.onActivity(VscodeActivityType.changeActiveNotebookEditor);
                        }),
                    );
                }
                if (typeof notebook.onDidChangeActiveNotebookKernel === 'function') {
                    this.addToDisposables(
                        notebook.onDidChangeActiveNotebookKernel(() => {
                            this.onActivity(VscodeActivityType.changeActiveNotebookKernel);
                        }),
                    );
                }
            } catch (err) {
                // Note: remove this later. Temporary allow debugging when proposed API is not possible.
                if (!(err instanceof Error && err.message.includes('Proposed API'))) {
                    throw err;
                }
            }
        }

        // languages events
        this.addToDisposables(
            VscodeActivityProvider.vscode.languages.registerHoverProvider('*', {
                provideHover: () => {
                    this.onActivity(VscodeActivityType.registerHoverProvider);
                    return null;
                },
            }),
        );
    }

    // Defer import of `vscode` package.
    protected static get vscode(): typeof vscode {
        return require('vscode');
    }

    public abstract onActivity(activityType?: VscodeActivityType | string): Promise<void>;
}
