interface IWorkspaceServices {
    readonly registeredServices: Set<string>;
}

/**
 * RPC variables are intentionally NOT private members of public API objects,
 * to prevent extensions from trivially using the private members to make
 * arbitrary RPC calls.
 */
export interface ExtensionContext {
    client: IRpcClientProxy;
    workspaceService: vsls.WorkspaceService;
    workspaceUserService: vsls.WorkspaceUserService;
    workspaceServices: IWorkspaceServices;
    pathManager: IPathManager;
    contactManager?: IContactManager;
    treeViews: { [viewId: string]: IExtensibleTreeView };
    authStrategies: IAuthStrategy[];
    guestChannelService?: IGuestChannelService;
    apiPromise?: Promise<void>;
}
let privateContext: ExtensionContext;

/**
 * Implementation of the root API that is used to acquire access to the
 * main Live Share API.
 *
 * An instance of this class is returned by the Live Share extension's
 * activation function.
 */
export abstract class LiveShareExtensionApiBase implements LiveShareExtension {
    protected static trace: TraceSource;
    private readonly liveShareApis: Array<LiveShare> = [];

    /**
     * Callers that request an API version outside this range will get `null`,
     * which should be treated the same as if Live Share is not installed.
     */
    public readonly supportedApiVersionRange = '>=0.3.0 <1.1.0';

    public constructor(extensionContext: ExtensionContext) {
        privateContext = extensionContext;

        if (!LiveShareExtensionApiBase.trace) {
            LiveShareExtensionApiBase.trace = traceSource.withName(vsls.TraceSources.API);
        }
    }

    public async getApi(requestedApiVersion: string, callingExtensionId?: string): Promise<LiveShare | null> {
        checkArg(requestedApiVersion, 'requestedApiVersion', 'string');

        const stackFrames = getStackFrames();

        if (privateContext.apiPromise)
        {
            await privateContext.apiPromise;
        }

        const callingPackage = await this.getCallingPackage(stackFrames, callingExtensionId);

        if (!callingPackage) {
            LiveShareExtensionApiBase.trace.warning('Live Share API request failed ' +
                'because calling package could not be detected.');
            return null;
        }

        return await this.getApiInternal(callingPackage, requestedApiVersion);
    }

    /** @deprecated */
    public getApiAsync(requestedApiVersion: string): Promise<LiveShare | null> {
        return this.getApi(requestedApiVersion);
    }

    protected abstract getCallingPackage(stackFrames: StackFrame[], callingExtensionId?: string): Promise<PackageInfo | null>;

    protected async getApiInternal(callingPackage: PackageInfo, requestedApiVersion: string): Promise<LiveShare | null> {
        const currentVersion = vscode.extensions.getExtension(extensionId).packageJSON.version;

        // Check that the extension requested a supported API version.
        if (!requestedApiVersion.endsWith('-placeholder') && !semver.satisfies(
            requestedApiVersion.split('-')[0], // Ignore any prelease tag
            this.supportedApiVersionRange)
        ) {
            // The current version is always supported. This enables dev scenarios
            // where the current version is outside the supported range defined above.
            if (!semver.eq(requestedApiVersion, currentVersion)) {
                LiveShareExtensionApiBase.trace.warning(
                    `Package ${callingPackage.fullName}@${callingPackage.version} requested` +
                    ` Live Share API version ${requestedApiVersion} that is not supported.`);
                return null;
            }
        }

        const permissions = getPermissionsForExtension(callingPackage);
        if (permissions === Permission.block) {
            LiveShareExtensionApiBase.trace.warning(`Package ${callingPackage.fullName} is blocked.`);
            return null;
        }

        const liveShareApi = this.createLiveShareApi(callingPackage, requestedApiVersion, LiveShareExtensionApiBase.trace, privateContext.authStrategies);
        this.liveShareApis.push(liveShareApi);
        return liveShareApi;
    }

    protected createLiveShareApi(callingPackage: PackageInfo, requestedApiVersion: string, trace: TraceSource, authStrategies: IAuthStrategy[]): LiveShare {
        return new LiveShareApi(callingPackage, requestedApiVersion, trace, authStrategies);
    }
}

/**
 * Main API that enables other VS Code extensions to access Live Share capabilities.
 *
 * An instance of this class is created by the extension API above.
 */
export class LiveShareApi implements LiveShare {
    public services: Services;

    private readonly sessionChangeEmitter = new vscode.EventEmitter<SessionChangeEvent>();
    private readonly currentPeers: Peer[] = [];
    private readonly peersChangeEmitter = new vscode.EventEmitter<PeersChangeEvent>();
    private readonly presenceProviderRegisteredEmitter = new vscode.EventEmitter<PresenceProviderEvent>();
    private readonly activityEmitter = new vscode.EventEmitter<Activity>();

    /** When in Host role, tracks the services that are shared via this API. */
    private readonly sharedServices: { [name: string]: SharedServiceApi } = {};

    /** When in Guest role, tracks the service proxies that are obtained via this API. */
    private readonly serviceProxies: { [name: string]: SharedServiceApi } = {};

    /** A lazy-initialized host service broker, which is cleared at every session end, and only initialized if requested while a guest in an active session. */
    private hostServiceBroker?: Lazy<Promise<IServiceBroker>>;

    public constructor(
        private readonly callingPackage: PackageInfo,
        private readonly apiVersion: string,
        private readonly trace: TraceSource,
        authStrategies: IAuthStrategy[]
    ) {
        checkArg(callingPackage, 'callingPackage', 'object');
        checkArg(apiVersion, 'apiVersion', 'string');

        // Ensure the callingPackage property cannot be modified.
        // Note the PackageInfo object is also immutable.
        Object.defineProperty(this, 'callingPackage', {
            enumerable: false,
            configurable: false,
            writable: false,
            value: this.callingPackage,
        });

        trace.info(
            `Initializing Live Share API ${apiVersion} for ` +
            `${callingPackage.fullName}@${callingPackage.version}`);
        this.sendActivatedTelemetryEvent();

        // Initialize session state.
        const sessionInfo = workspaceSessionInfoTracker.workspaceSessionInfo;
        this.session = {
            peerNumber: (sessionInfo ? sessionInfo.sessionNumber : 0),
            user: null,
            role: LiveShareApi.getSessionRole(sessionStateTracker.State),
            access: LiveShareApi.getSessionAccess(sessionStateTracker.State),
            id: (sessionInfo ? sessionInfo.id : null),
            presentationMode: workspaceSessionInfoTracker?.workspaceSessionInfo?.isPresentation ?? false
        };

        // Initialise current user info, if any.
        this.onSignedIn();

        // Register internal event handlers.
        sessionStateTracker.onStateChanged((e: SessionStateChangedEventArgs) => this.onSessionStateChanged(e.newState));
        privateContext.workspaceService.onServicesChanged((e) => this.onServicesChanged(e));
        privateContext.workspaceUserService.onWorkspaceSessionChanged((e) => this.onUserSessionChanged(e));

        Object.defineProperty(this, 'authStrategies', {
            enumerable: false,
            configurable: false,
            set: function() {},
            get: function() {
                if (!this.hasPermission(Permission.authStrategies)) {
                    return;
                }
                // check permissions
                return authStrategies;
            },
        });

        ContactManager.addListener(ContactManagerEvents.ProviderAdded, (s: ContactServiceManager) => {
            this.presenceProviderRegisteredEmitter.fire( {
                added: LiveShareApi.toPresenceProvider(s)
            });
        });

        const self = this;
        this.services = {
            get guestChannelService(): IGuestChannelService | undefined {
                if (self.session.role !== Role.Guest) {
                    return undefined;
                }

                return privateContext.guestChannelService;
            },

            async getRemoteServiceBroker(): Promise<IServiceBroker | null> {
                if (self.session.role !== Role.Guest) {
                    return null;
                }

                if (!self.hostServiceBroker) {
                    self.hostServiceBroker = lazyLoad(() => getRemoteServiceBrokerFromHost(privateContext.client, privateContext.guestChannelService, trace));
                }

                return await self.hostServiceBroker();
            },
        };

        activitySource.onActivity((a) => {
            const activity = { ...a };
            if (activity.data) {
                if (typeof activity.data.peer === 'number') {
                    activity.data.peer = this.getPeer(activity.data.peer);
                } else if (Array.isArray(activity.data.peers) && typeof activity.data.peers[0] === 'number') {
                    activity.data.peers = (activity.data.peers as number[]).map(p => this.getPeer(p));
                }
            }
            this.activityEmitter.fire(activity);
        });
    }

    public async getPeerForTextDocumentChangeEvent(e: vscode.TextDocumentChangeEvent): Promise<Peer> {
        const clientId = await SessionContext.coeditingClient?.getClientIdForTextDocumentChangeEvent(e);
        if (clientId === undefined) {
            return this.session;
        } else {
            return this.getPeer(clientId);
        }
    }

    private getPeer(peerNumber: number) {
        if (peerNumber === this.session.peerNumber) {
            return this.session;
        } else {
            return this.peers.find(peer => peer.peerNumber === peerNumber)
                || {
                    peerNumber,
                    user: undefined,
                    role: undefined,
                    access: undefined
                };
        }
    }

    public readonly session: Session;

    public get onDidChangeSession(): vscode.Event<SessionChangeEvent> {
        return this.sessionChangeEmitter.event;
    }

    public get onActivity(): vscode.Event<Activity> {
        return this.activityEmitter.event;
    }

    public get peers(): Peer[] {
        return this.currentPeers.slice(0);
    }

    public get presenceProviders(): PresenceProvider[] {
        return ContactManager.serviceProviders.map(s => LiveShareApi.toPresenceProvider(s));
    }

    private static toPresenceProvider(s: ContactServiceManager) {
        return <PresenceProvider> {
            serviceId: s.serviceId,
            capabilites: s.capabilites,
            selfContact: s.selfUser ? new ContactApi(privateContext.contactManager, s.selfUser) : null,
            provider: s.contactServiceProvider
        };
    }

    public get onDidChangePeers(): vscode.Event<PeersChangeEvent> {
        return this.peersChangeEmitter.event;
    }

    public get onPresenceProviderRegistered(): vscode.Event<PresenceProviderEvent> {
        return this.presenceProviderRegisteredEmitter.event;
    }

    public async share(options?: ShareOptions): Promise<vscode.Uri> {
        if (this.session.role === Role.Guest) {
            throw new Error('Cannot share while joined to another session.');
        } else if (this.session.role === Role.Host) {
            if (options && options.access) {
                throw new Error('Cannot change default access ' +
                    'for an already shared session.');
            }
        }

        const command = (options && options.access === Access.ReadOnly ?
            'liveshare.startReadOnly' : 'liveshare.start');
        this.sendInvokeCommandTelemetryEvent(command, options);
        return await vscode.commands.executeCommand<vscode.Uri>(command, options);
    }

    public async join(link: vscode.Uri, options?: JoinOptions): Promise<void> {
        checkArg(link, 'link', 'uri');

        if (this.session.role !== Role.None) {
            throw new Error('A session is already active.');
        }

        const command = 'liveshare.join';
        this.sendInvokeCommandTelemetryEvent(command, options);
        await vscode.commands.executeCommand(command, { ...options, link });
    }

    public async end(): Promise<void> {
        if (this.session.role === Role.Guest) {
            const command = 'liveshare.leave';
            this.sendInvokeCommandTelemetryEvent(command);
            await vscode.commands.executeCommand(command);
        } else if (this.session.role === Role.Host) {
            const command = 'liveshare.end';
            this.sendInvokeCommandTelemetryEvent(command);
            await vscode.commands.executeCommand(command);
        }
    }

    public async shareServer(server: Server): Promise<vscode.Disposable> {
        checkArg(server, 'server', 'object');

        if (this.session.role !== Role.Host) {
            throw new Error('Host collaboration session doesn\'t exist.');
        }

        const shareCommand = 'liveshare.shareServer';
        this.sendInvokeCommandTelemetryEvent(shareCommand, server);
        await vscode.commands.executeCommand(shareCommand, this.callingPackage, server);

        return new vscode.Disposable(() => {
            const unshareCommand = 'liveshare.unshareServer';
            this.sendInvokeCommandTelemetryEvent(unshareCommand, server);
            vscode.commands.executeCommand(unshareCommand, this.callingPackage, server);
        });
    }

    public async shareService(name: string): Promise<SharedService | null> {
        checkArg(name, 'name', 'string');

        const isPermitted = this.hasPermission(Permission.shareServices);
        this.sendShareServiceTelemetryEvent(name, isPermitted);

        if (!isPermitted) {
            this.trace.warning(`shareService(${name}) not permitted.`);
            return null;
        }

        name = this.callingPackage.fullName + '.' + name;
        this.trace.verbose(`shareService(${name})`);

        let sharedService = this.sharedServices[name];
        if (!sharedService) {
            const connection = await privateContext.client.ensureConnectionAsync();
            sharedService = new SharedServiceApi(name, connection, this.trace);
            this.sharedServices[name] = sharedService;

            if (this.session.role === Role.Host) {
                try {
                    await privateContext.workspaceService.registerServicesAsync(
                        [name], vsls.CollectionChangeType.Add);
                } catch (e) {
                    this.trace.error(e);
                    throw e;
                }

                sharedService._isServiceAvailable = true;
                sharedService._fireIsAvailableChange();
            }
        }

        return sharedService;
    }

    public async unshareService(name: string): Promise<void> {
        checkArg(name, 'name', 'string');

        name = this.callingPackage.fullName + '.' + name;
        this.trace.verbose(`unshareService(${name})`);

        const sharedService = this.sharedServices[name];
        if (sharedService && sharedService.isServiceAvailable) {
            try {
                await privateContext.workspaceService.registerServicesAsync(
                    [name], vsls.CollectionChangeType.Remove);
            } catch (e) {
                this.trace.error(e);
                throw e;
            }

            sharedService._isServiceAvailable = false;
            sharedService._fireIsAvailableChange();
        }

        delete this.sharedServices[name];
    }

    public async getSharedService(name: string): Promise<SharedServiceProxy | null> {
        checkArg(name, 'name', 'string');

        if (name.indexOf('.') < 0) {
            name = this.callingPackage.fullName + '.' + name;
        }

        this.trace.verbose(`getSharedService(${name})`);

        let serviceProxy = this.serviceProxies[name];
        if (!serviceProxy) {
            const connection = await privateContext.client.ensureConnectionAsync();
            serviceProxy = new SharedServiceApi(name, connection, this.trace);
            this.serviceProxies[name] = serviceProxy;

            if (this.session.role === Role.Guest &&
                privateContext.workspaceServices.registeredServices.has(name)
            ) {
                serviceProxy._isServiceAvailable = true;
            }
        }

        return serviceProxy;
    }

    public convertLocalUriToShared(localUri: vscode.Uri): vscode.Uri {
        checkArg(localUri, 'localUri', 'uri');

        if (this.session.role !== Role.Host) {
            throw new Error('Only the host role can convert shared URIs.');
        }

        const scheme = Settings.scheme;
        if (localUri.scheme === scheme) {
            throw new Error(`URI is already a ${scheme} URI: ${localUri}`);
        }

        const protocolUri = privateContext.pathManager.code2protocolWorkspaceFilesOnly(localUri);
        if (!protocolUri) {
            throw new Error(`URI was not part of a workspace: ${localUri}`);
        }

        return protocolUri;
    }

    public convertSharedUriToLocal(sharedUri: vscode.Uri): vscode.Uri {
        checkArg(sharedUri, 'sharedUri', 'uri');

        if (this.session.role !== Role.Host) {
            throw new Error('Only the host role can convert shared URIs.');
        }

        const scheme = Settings.scheme;
        if (sharedUri.scheme !== scheme) {
            throw new Error(
                `Not a ${Settings.get<string>(SettingKeys.shortName)} shared URI: ${sharedUri}`);
        }

        return privateContext.pathManager.protocolUri2CodeUriConverter(sharedUri);
    }

    public registerCommand(
        command: string,
        isEnabled?: () => boolean,
        thisArg?: any
    ): vscode.Disposable | null {
        const isPermitted = this.hasPermission(Permission.contributeCommands);
        if (!isPermitted) {
            this.trace.warning(`registerCommand(${command}) not permitted.`);
            return null;
        }

        const contributions = ExtensionContributions.getContributions(
            this.callingPackage, this.trace);
        return contributions.registerCommand(command, isEnabled, thisArg);
    }

    public registerTreeDataProvider<T>(
        viewId: View,
        treeDataProvider: vscode.TreeDataProvider<T>,
    ): vscode.Disposable | null {
        const treeView = privateContext.treeViews[viewId];
        if (!treeView) {
            return null;
        }

        return treeView.registerTreeDataProvider(treeDataProvider);
    }

    public registerContactServiceProvider(
        name: string,
        contactServiceProvider: contactProtocol.ContactServiceProvider,
    ): vscode.Disposable | null {
        this.trace.info(`Register contact service provier with name: ${name}`);

        const contactManager = privateContext.contactManager;
        if (!contactManager) {
            return null;
        }

        return contactManager.registerContactProvider(name, contactServiceProvider);
    }

    public async registerPolicyProvider(
        name: string,
        policyProvider: PolicyProvider,
    ): Promise<vscode.Disposable | null> {
        return null;
    }

    public getContacts(emails: string[]): Promise<ContactsCollection> {
        this.trace.info(`Request contacts for emails: ${emails.map(TraceFormat.formatEmail).join()}`);
        return ContactApi.getContacts(privateContext.contactManager, emails);
    }

    public postActivity(activity: Activity): void {
        activitySource.fire(activity);
    }

    private static getSessionRole(state: SessionState): Role {
        return (state === SessionState.Shared ? Role.Host :
            state === SessionState.Joined ? Role.Guest : Role.None);
    }

    private static getSessionAccess(state: SessionState): Access {
        // TODO: Read-only access
        if (state === SessionState.Shared) {
            return Access.Owner;
        }

        return (state === SessionState.Joined)
            ? Access.ReadWrite
            : Access.None;
    }

    /**
     * Callback from session context whenever state changes.
     * We only care about transitions to/from fully shared or joined states.
     */
    private async onSessionStateChanged(state: SessionState): Promise<void> {
        const newRole = LiveShareApi.getSessionRole(state);

        if (!this.session.user && (newRole !== Role.None || state === SessionState.SignedIn)) {
            this.onSignedIn();
        } else if (this.session.user && state === SessionState.SignedOut) {
            this.onSignedOut();
        }

        if (newRole === this.session.role) {
            return;
        }

        const sessionChange = <any>this.session;
        sessionChange.role = newRole;

        let peersChangeEvent: PeersChangeEvent = null;
        const changedServices: SharedServiceApi[] = [];

        if (newRole === Role.Host) {
            peersChangeEvent = await this.onShared(changedServices);
        } else if (newRole === Role.Guest) {
            peersChangeEvent = await this.onJoined(changedServices);
        } else {
            peersChangeEvent = await this.onEnded(changedServices);
            this.hostServiceBroker = undefined;
        }

        // Raise all events at the end, after all state was updated.
        this.trace.verbose(`^onDidChangeSession(${Role[newRole]})`);
        this.sessionChangeEmitter.fire({ session: this.session });

        if (peersChangeEvent) {
            this.trace.verbose(`^onDidChangePeers(${LiveShareApi.formatPeersChangeEvent(peersChangeEvent)})`);
            this.peersChangeEmitter.fire(peersChangeEvent);
        }

        for (const s of changedServices) {
            s._fireIsAvailableChange();
        }
    }

    /**
     * The user signed in. Update the current user info.
     */
    private onSignedIn(): void {
        // There is currently no public event raised for signing in.
        if (this.hasPermission(Permission.readUserProfile)) {
            (<any>this.session).user = userAuthStateTracker.userInfo && {
                displayName: userAuthStateTracker.userInfo.displayName,
                emailAddress: userAuthStateTracker.userInfo.emailAddress,
                userName: userAuthStateTracker.userInfo.userName,
                id: userAuthStateTracker.userInfo.id,
            };
        }
    }

    /**
     * The user signed out. Update the current user info.
     */
    private onSignedOut(): void {
        // There is currently no public event raised for signing out.
        (<any>this.session).user = null;
    }

    /**
     * A hosted sharing session started. Register any shared services
     * and update current session info.
     */
    private async onShared(changedServices: SharedServiceApi[]): Promise<PeersChangeEvent | null> {
        const sharedServiceNames = Object.keys(this.sharedServices);
        if (sharedServiceNames.length > 0) {
            try {
                await privateContext.workspaceService.registerServicesAsync(
                    sharedServiceNames,
                    vsls.CollectionChangeType.Add);
            } catch (e) {
                this.trace.error(e);
                // Don't throw. This is an async event-handler,
                // so the caller would not await or catch the error.
            }
            for (let s of sharedServiceNames) {
                this.sharedServices[s]._isServiceAvailable = true;
                changedServices.push(this.sharedServices[s]);
            }
        }

        // Update current session info.
        const sessionInfo = workspaceSessionInfoTracker.workspaceSessionInfo;
        const sessionChange = <any>this.session;
        sessionChange.peerNumber = sessionInfo.sessionNumber;
        sessionChange.access = LiveShareApi.getSessionAccess(SessionState.Shared);
        sessionChange.id = sessionInfo.id || null;
        this.activityEmitter.fire({
            timestamp: new Date(),
            name: `${ActivityType.session}/share`,
            data: {
                peer: this.session,
                files: vscode.workspace.workspaceFolders?.map(wf => wf.uri)
            }
        });
        return null;
    }

    /**
     * Joined a sharing session as a guest. Make service proxies available,
     * update current session info, and initialize peers.
     */
    private async onJoined(changedServices: SharedServiceApi[]): Promise<PeersChangeEvent | null> {
        for (let s of Object.keys(this.serviceProxies)) {
            if (privateContext.workspaceServices.registeredServices.has(s)) {
                const serviceProxy = this.serviceProxies[s];
                serviceProxy._isServiceAvailable = true;
                changedServices.push(serviceProxy);
            }
        }

        // Update current session info.
        const sessionInfo = workspaceSessionInfoTracker.workspaceSessionInfo;
        const sessionChange = <any>this.session;
        sessionChange.peerNumber = sessionInfo.sessionNumber;
        sessionChange.access = LiveShareApi.getSessionAccess(sessionStateTracker.State);
        sessionChange.id = sessionInfo.id || null;

        const isUserProfilePermitted = this.hasPermission(Permission.readUserProfile);

        // Initalize peers array, includuing the host and any other already-joined guests.
        if (sessionInfo.sessions && Object.keys(sessionInfo.sessions).length > 0) {
            const addedPeers: Peer[] = [];
            for (let sessionNumber of Object.keys(sessionInfo.sessions)) {
                const sessionNumberInt = parseInt(sessionNumber, 10);
                if (sessionNumberInt !== sessionInfo.sessionNumber) {
                    const profile = sessionInfo.sessions[sessionNumber];
                    const user: UserInfo | null = isUserProfilePermitted ?
                        { displayName: profile.name, emailAddress: profile.email, userName: profile.userName, id: profile.id } : null;
                    addedPeers.push({
                        peerNumber: sessionNumberInt,
                        user: user,
                        role: (profile.isHost ? Role.Host : Role.Guest),
                        access: (profile.isOwner ? Access.Owner : Access.ReadWrite),
                    });
                }
            }

            this.activityEmitter.fire({
                timestamp: new Date(),
                name: `${ActivityType.session}/join`,
                data: {
                    peers: [this.session, ...addedPeers],
                    files: vscode.workspace.workspaceFolders?.map(wf => wf.uri)
                }
            });

            if (addedPeers.length > 0) {
                this.currentPeers.push(...addedPeers);
                return { added: addedPeers, removed: [] };
            }
        }

        return null;
    }

    /**
     * The sharing session ended (or this user left). Notify shared services and service proxies,
     * and update current session and peers.
     */
    private async onEnded(changedServices: SharedServiceApi[]): Promise<PeersChangeEvent | null> {
        for (let s of Object.keys(this.serviceProxies)) {
            const service = this.serviceProxies[s];
            if (service.isServiceAvailable) {
                service._isServiceAvailable = false;
                changedServices.push(service);
            }
        }
        for (let s of Object.keys(this.sharedServices)) {
            const service = this.sharedServices[s];
            if (service.isServiceAvailable) {
                service._isServiceAvailable = false;
                changedServices.push(service);
            }
        }

        // Clear current session info.
        const sessionChange = <any>this.session;
        sessionChange.peerNumber = 0;
        sessionChange.access = LiveShareApi.getSessionAccess(sessionStateTracker.State);
        sessionChange.id = null;

        // Clear peers array.
        if (this.currentPeers.length > 0) {
            return {
                added: [],
                removed: this.currentPeers.splice(0, this.currentPeers.length),
            };
        }

        return null;
    }

    /**
     * Callback from workspace service whenever available RPC services changed.
     * We only care about prefixed services (registered via public API).
     */
    private onServicesChanged(e: vsls.WorkspaceServicesChangedEventArgs) {
        // Filter out internal service names - the ones with no package name prefix.
        const changedServiceNames = e.serviceNames
            .filter(s => s.indexOf('.') >= 0);

        if (e.changeType === vsls.CollectionChangeType.Add) {
            for (let s of changedServiceNames) {
                // If a proxy for the service exists, it's now available (if in Guest role).
                const serviceProxy = this.serviceProxies[s];
                if (serviceProxy && !serviceProxy.isServiceAvailable &&
                    this.session.role === Role.Guest) {
                    serviceProxy._isServiceAvailable = true;
                    serviceProxy._fireIsAvailableChange();
                }
            }
        } else if (e.changeType === vsls.CollectionChangeType.Remove) {
            for (let s of changedServiceNames) {
                // If a proxy for the service exists, it's now unavailable.
                const serviceProxy = this.serviceProxies[s];
                if (serviceProxy && serviceProxy.isServiceAvailable) {
                    serviceProxy._isServiceAvailable = false;
                    serviceProxy._fireIsAvailableChange();
                }
            }
        }
    }

    /**
     * Callback from workspace user service whenever participants change.
     */
    private onUserSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs) {
        if (e.sessionNumber === this.session.peerNumber) {
            // Skip notifications about myself; that's handled as part of
            // the session state change.
            return;
        }

        if (e.changeType === vsls.WorkspaceSessionChangeType.Joined) {
            const user: UserInfo | null = this.hasPermission(Permission.readUserProfile) ?
                { displayName: e.userProfile.name, emailAddress: e.userProfile.email, userName: e.userProfile.userName, id: e.userProfile.id } : null;
            const peer: Peer = {
                peerNumber: e.sessionNumber,
                user: user,
                role: Role.Guest,
                access: Access.ReadWrite,
            };
            this.currentPeers.push(peer);

            const peersChangeEvent: PeersChangeEvent = { added: [peer], removed: [] };
            this.trace.verbose(`^onDidChangePeers(${LiveShareApi.formatPeersChangeEvent(peersChangeEvent)}`);
            this.peersChangeEmitter.fire(peersChangeEvent);
            this.activityEmitter.fire({
                timestamp: new Date(),
                name: `${ActivityType.session}/guestJoin`,
                data: {
                    peer
                }
            });
        } else if (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined) {
            const i = this.currentPeers.findIndex(p => p.peerNumber === e.sessionNumber);
            if (i >= 0) {
                const peer = this.currentPeers.splice(i, 1)[0];

                const peersChangeEvent: PeersChangeEvent = { added: [], removed: [peer] };
                this.trace.verbose(`^onDidChangePeers(${LiveShareApi.formatPeersChangeEvent(peersChangeEvent)}`);
                this.peersChangeEmitter.fire(peersChangeEvent);
                this.activityEmitter.fire({
                    timestamp: new Date(),
                    name: `${ActivityType.session}/guestLeave`,
                    data: {
                        peer
                    }
                });
            }
        }
    }

    private static formatPeersChangeEvent(e: PeersChangeEvent): string {
        let s = '';
        if (e.added.length > 0) {
            s += 'added: ' + e.added.map(LiveShareApi.formatPeer).join(', ');
        }
        if (e.removed.length > 0) {
            s += (s ? '; ' : '') + 'removed: ' + e.removed.map(LiveShareApi.formatPeer).join(', ');
        }
        return s;
    }

    private static formatPeer(p: Peer) {
        const email = p.user && p.user.emailAddress;
        const s = `#${p.peerNumber} ${Role[p.role]}` + (email ? ' ' + TraceFormat.formatEmail(email) : '');
        return s;
    }

    private hasPermission(permission: Permission): boolean {
        return hasPermissionForExtension(this.callingPackage, permission);
    }

    private sendActivatedTelemetryEvent(): void {
        Telemetry.sendTelemetryEvent(TelemetryEventNames.ACTIVATE_EXTENSION_API, {
            [TelemetryPropertyNames.EXTENSION_NAME]: this.callingPackage.fullName,
            [TelemetryPropertyNames.EXTENSION_VERSION]: this.callingPackage.version,
            [TelemetryPropertyNames.EXTENSION_REQUESTED_API_VERSION]: this.apiVersion,
        });
    }

    private sendInvokeCommandTelemetryEvent(commandName: string, options?: object): void {
        Telemetry.sendTelemetryEvent(TelemetryEventNames.INVOKE_EXTENSION_COMMAND, {
            [TelemetryPropertyNames.EXTENSION_NAME]: this.callingPackage.fullName,
            [TelemetryPropertyNames.EXTENSION_VERSION]: this.callingPackage.version,
            [TelemetryPropertyNames.EXTENSION_INVOKED_COMMAND]: commandName,
        });
    }

    private sendShareServiceTelemetryEvent(serviceName: string, isPermitted: boolean): void {
        Telemetry.sendTelemetryEvent(TelemetryEventNames.SHARE_EXTENSION_SERVICE, {
            [TelemetryPropertyNames.EXTENSION_NAME]: this.callingPackage.fullName,
            [TelemetryPropertyNames.EXTENSION_VERSION]: this.callingPackage.version,
            [TelemetryPropertyNames.EXTENSION_SERVICE_NAME]: serviceName,
            [TelemetryPropertyNames.EXTENSION_SERVICE_PERMITTED]: isPermitted.toString(),
        });
    }
}
