import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import {
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator,
    localize
} from '@vs/liveshare-core';
import { ContactManager } from '../ContactManager';

export function builder(): ICommand<void> {
    return new SelectPresenceProviderCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.SELECT_PRESENCE_PROVIDER, TelemetryEventNames.SELECT_PRESENCE_PROVIDER_FAULT, 'SelectPresenceProvider', 1)
class SelectPresenceProviderCommand implements ICommand<void> {

    public async invoke(context: ICommandContext): Promise<void> {
        const providersWithPresenceSupport = ContactManager.serviceProviders.filter(sp => sp.capabilites.supportsContactPresenceRequest)
            .sort((sp1, sp2) => {
                if (sp1.priority > sp2.priority) {
                    return -1;
                } else if (sp1.priority < sp2.priority) {
                    return 1;
                }

                return 0;
            });
        if (providersWithPresenceSupport.length > 0) {
            const selectedPreferedProviderId = ContactManager.selectedPreferedProviderId;
            const items = providersWithPresenceSupport.map(sp => {
                return (sp.serviceId === selectedPreferedProviderId ? '$(check) ' : '') + sp.descriptionName;
            });
            const selection: string = await vscode.window.showQuickPick(items, { placeHolder: localize('selectPresenceProviderCommand.placeHolder') });
            if (selection) {
                const selectedProvider = providersWithPresenceSupport[items.indexOf(selection)];
                ContactManager.setPreferedPresenceProvider(selectedProvider);
            }
        }
    }
}