import * as vscode from 'vscode';

import { INotificationUtil, IQuickPickCallbacks } from '../types/INotificationUtil';

/**
 * Helper functions for working with VS Code Notifications/toasts.
 */
export class NotificationUtilClass implements INotificationUtil {
    private static singleton: NotificationUtilClass;

    public static get Instance(): NotificationUtilClass {
        if (!NotificationUtilClass.singleton) {
            NotificationUtilClass.singleton = new NotificationUtilClass();
        }
        return NotificationUtilClass.singleton;
    }

    public get notificationProgressLocation() {
        return require('vscode').ProgressLocation.Notification;
    }

    public showInformationMessage(
        message: string,
        isVerbose: boolean,
        ...items: string[]
    ): Promise<string | undefined>;
    public showInformationMessage<T extends vscode.MessageItem>(
        message: string,
        isVerbose: boolean,
        options: vscode.MessageOptions,
        ...items: T[]
    ): Promise<T | undefined>;
    public async showInformationMessage(
        message: string,
        isVerbose: boolean,
        ...items: any[]
    ): Promise<any> {
        if (!isVerbose) {
            return (await import('vscode')).window.showInformationMessage(message, ...items);
        }
    }

    public showErrorMessage(message: string, ...items: string[]): Promise<string | undefined>;
    public showErrorMessage<T extends vscode.MessageItem>(
        message: string,
        options: vscode.MessageOptions,
        ...items: T[]
    ): Promise<T | undefined>;
    public async showErrorMessage(message: string, ...items: any[]): Promise<any> {
        return (await import('vscode')).window.showErrorMessage(message, ...items);
    }

    public showWarningMessage(message: string): Promise<any>;
    public async showWarningMessage(
        message: string,
        options?: vscode.MessageOptions,
        ...items: any[]
    ): Promise<string | undefined> {
        if (options)
            return (await import('vscode')).window.showWarningMessage(message, options, ...items);
        else return (await import('vscode')).window.showWarningMessage(message, ...items);
    }

    public async showInputBox(
        options?: vscode.InputBoxOptions,
        token?: vscode.CancellationToken,
    ): Promise<string | undefined> {
        return (await import('vscode')).window.showInputBox(options, token);
    }

    public showQuickPick(
        items: string[],
        options?: vscode.QuickPickOptions,
        token?: vscode.CancellationToken,
    ): Promise<string | undefined>;
    public async showQuickPick<T extends vscode.QuickPickItem>(
        items: T[] | Thenable<T[]>,
        options?: vscode.QuickPickOptions,
        token?: vscode.CancellationToken,
    ): Promise<T | undefined>;
    public async showQuickPick<T extends vscode.QuickPickItem>(
        items: T[] | Thenable<T[]>,
        options?: vscode.QuickPickOptions,
        token?: vscode.CancellationToken,
        initialValue?: string,
        callbacks: IQuickPickCallbacks<T> = {},
    ): Promise<string | undefined> {
        // Adapt to the newer QuickPick API, which supports setting "active" (preselected) items.
        let adaptStrings = false;
        if (!Array.isArray(items)) {
            items = await items;
        } else if (Array.isArray(items) && typeof items[0] === 'string') {
            adaptStrings = true;
            items = items.map<any>((item) => <vscode.QuickPickItem>{ label: <string>(<any>item) });
        }

        let result = await new Promise<any>(async (resolve, reject) => {
            const quickPick = (await import('vscode')).window.createQuickPick<any>();
            quickPick.items = <T[]>items;
            quickPick.activeItems = (<T[]>items).filter((item) => (<any>item).picked);
            quickPick.canSelectMany = options?.canPickMany || false;
            quickPick.placeholder = options?.placeHolder || '';
            quickPick.ignoreFocusOut = options?.ignoreFocusOut || false;
            quickPick.matchOnDetail = options?.matchOnDetail || false;
            quickPick.matchOnDescription = options?.matchOnDescription || false;
            quickPick.value = initialValue;

            if (callbacks.onDidChangeValue) {
                quickPick.onDidChangeValue((value: string) => {
                    const overrides = callbacks.onDidChangeValue(value);
                    if (overrides.activeItems) {
                        quickPick.activeItems = overrides.activeItems;
                    }
                    if (overrides.selectedItems) {
                        quickPick.selectedItems = overrides.selectedItems;
                    }
                });
            }

            quickPick.onDidAccept(async () => {
                if (callbacks.onDidAccept) {
                    const shouldAccept = await callbacks.onDidAccept(
                        quickPick.selectedItems,
                        quickPick.value,
                    );
                    if (shouldAccept === false) {
                        return;
                    }
                }

                quickPick.hide();
                resolve(
                    quickPick.canSelectMany ? quickPick.selectedItems : quickPick.selectedItems[0],
                );
            });

            quickPick.onDidHide(() => {
                if (callbacks.onDidHide) {
                    callbacks.onDidHide();
                }

                resolve(null);
            });

            quickPick.show();
        });

        if (adaptStrings && result) {
            result = Array.isArray(result) ? result.map((item) => item.label) : result.label;
        }

        return result;
    }

    public async withProgress<R>(
        options: vscode.ProgressOptions,
        task: (
            progress: vscode.Progress<{ message?: string }>,
            token: vscode.CancellationToken,
        ) => Thenable<R>,
        token?: vscode.CancellationToken,
    ): Promise<R> {
        // TODO: playing with the signatures here due to version difference
        return (await import('vscode')).window.withProgress(
            options,
            task as (progress: vscode.Progress<{ message?: string }>) => Thenable<R>,
        );
    }

    public async showOpenDialog(
        options: vscode.OpenDialogOptions,
    ): Promise<vscode.Uri[] | undefined> {
        return (await import('vscode')).window.showOpenDialog(options);
    }

    public async createQuickPick(
        message: string,
        options: string[],
        defaultValue: string,
    ): Promise<string> {
        const optionsAsPickItems = options.map(
            (title) =>
                <vscode.QuickPickItem>{
                    label: title,
                },
        );

        return new Promise<string>((accept, reject) => {
            const list = require('vscode').window.createQuickPick();
            list.placeholder = message;
            list.items = optionsAsPickItems;
            list.activeItems = list.items.filter((item: vscode.QuickPickItem) => {
                return item.label === defaultValue;
            });

            list.onDidChangeValue((searchString: string) => {
                list.items = searchString
                    ? [{ label: searchString }, ...optionsAsPickItems]
                    : optionsAsPickItems;
            });

            list.onDidAccept(() => {
                list.hide();
                accept(list.selectedItems[0].label);
            });

            list.show();
        });
    }

    public createQuickPickWithRefresh<T extends vscode.QuickPickItem>(
        loadingMessage: string,
        message: string,
        onUpdatedInput?: (input: string) => Promise<T[]>,
        acceptNonMatchingInput?: (input: string) => Promise<boolean>,
    ): {
        valuePromise: Promise<T | string>;
        setItems: (items: T[]) => void;
        cancel: () => void;
    } {
        const quickPick = require('vscode').window.createQuickPick();
        const setItems = (items: T[]) => {
            quickPick.placeholder = message;
            quickPick.items = items;
            quickPick.busy = false;
        };

        const cancel = () => {
            quickPick.dispose();
        };

        return {
            setItems,
            cancel,
            valuePromise: new Promise<T | string>((resolve) => {
                quickPick.placeholder = loadingMessage;
                quickPick.items = [];
                quickPick.ignoreFocusOut = true;
                quickPick.busy = true;

                let userInput = '';
                quickPick.onDidChangeValue((input: string) => {
                    userInput = input;

                    if (onUpdatedInput) {
                        quickPick.busy = true;
                        onUpdatedInput(input).then((updatedItems) => {
                            quickPick.items = updatedItems;
                            quickPick.busy = false;
                        });
                    }
                });

                quickPick.onDidAccept(async () => {
                    quickPick.enabled = false;
                    if (quickPick.selectedItems.length < 1) {
                        const submittedInput = userInput;
                        if (
                            acceptNonMatchingInput &&
                            (await acceptNonMatchingInput(submittedInput))
                        ) {
                            resolve(submittedInput);
                            quickPick.dispose();
                        } else {
                            quickPick.enabled = true;
                            return;
                        }
                    } else {
                        resolve(quickPick.selectedItems[0]);
                        quickPick.dispose();
                    }
                });

                quickPick.show();
            }),
        };
    }

    public async showSaveDialog(
        options: vscode.SaveDialogOptions,
    ): Promise<vscode.Uri | undefined> {
        return (await import('vscode')).window.showSaveDialog(options);
    }
}

// tslint:disable-next-line: variable-name
const NotificationUtil = NotificationUtilClass.Instance;
export { NotificationUtil };
