import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { IRpcServiceHandlerInfo } from '@vs/vso-rpc';

export class SourceEventService implements vsls.SourceEventService, IRpcServiceHandlerInfo {

    private eventIds = new Map<string, number>();
    private sourceData = new Map<string, string>();
    private eventEmitter = new vscode.EventEmitter<vsls.SourceEventArgs>();

    public serviceInfo = vsls.SourceEventService;

    public async fireEventAsync(sourceId: string, jsonContent: string, cancellationToken?: vscode.CancellationToken): Promise<void> {
        let newEventId = 1;
        if (this.eventIds.has(sourceId)) {
            const eventId = this.eventIds.get(sourceId);
            newEventId = eventId + 1;
        }
        this.eventIds.set(sourceId, newEventId);

        const args: vsls.SourceEventArgs = {
            eventId: newEventId,
            sourceId: sourceId,
            jsonContent: jsonContent
        };
        this.eventEmitter.fire(args);
    }

    public setSourceDataAsync(sourceId: string, jsonContent: string, fireEvent: boolean, cancellationToken?: vscode.CancellationToken): Promise<void> {
        this.sourceData.set(sourceId, jsonContent);

        if (fireEvent) {
            return this.fireEventAsync(sourceId, jsonContent, cancellationToken);
        }

        return Promise.resolve();
    }

    public async getSourceDataAsync(sourceId: string, cancellationToken?: vscode.CancellationToken): Promise<string> {
        return this.sourceData.get(sourceId);
    }

    public onEvent: vscode.Event<vsls.SourceEventArgs> = this.eventEmitter.event;
}