import { CancellationToken, Event, Progress } from 'vscode';

/**
 * Represent an RPC Agent Session that has capabilities to reconnect to an existing RPC session
 */
export interface AgentSessionService {
    /**
     * Initialize this rpc session by adding services or reconnecting to an existing session
     * @param initializeRequest The initialize request options
     * @param cancellationToken 
     * @returns 
     */
    initializeSessionAsync(
        initializeRequest: AgentSessionRequest,
        cancellationToken?: CancellationToken)
        : Promise<AgentSessionResponse>;

    /**
     * Enable this rpc session to be later reconnected
     * @param cancellationToken 
     * @returns 
     */
    enableReconnectAsync(
        cancellationToken?: CancellationToken)
        : Promise<string>;

    /**
     * Keep the agent alive for some milliseconds to avoid the agent process to exit when rpc session are disconnected
     * and the AutoStop is enable
     * @param delay 
     * @param cancellationToken 
     * @returns 
     */
    keepAliveAsync(
        delay: number,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Force kills the agent
     * @param cancellationToken 
     * @returns 
     */
    forceKillAsync(
        cancellationToken?: CancellationToken)
        : Promise<void>;
}

export interface AuthenticationCoreService {
    /**
     * Get info of current user info and the access token
     * @param cancellationToken 
     * @returns 
     */
    getCurrentAuthenticatedUserAsync(
        cancellationToken?: CancellationToken)
        : Promise<AuthenticatedUserInfo>;

    /**
     * Gets info about the currently authenticated user, if any.
     * @returns User info, or null if the session is not authenticated.
     */
    getCurrentUserAsync(
        cancellationToken?: CancellationToken)
        : Promise<UserInfo>;

    /**
     * Removes a recent collaborator from the current profile.
     */
    removeRecentCollaboratorAsync(
        recentCollaboratorId: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Removes all recent collaborators from the current profile.
     */
    removeAllRecentCollaboratorsAsync(
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Indicate a change in the status of the current authenticate user
     */
    readonly onAuthenticationChanged: Event<AuthenticationChangedEventArgs>;
}

export interface AuthenticationService extends AuthenticationCoreService {
    /**
     * Gets a URI that can be used for interactive web login for the current environment.
     */
    getLoginUriAsync(
        cancellationToken?: CancellationToken)
        : Promise<string>;

    /**
     * Scans browser window titles for a Cascade login code.
     */
    findLoginCodeAsync(
        extensionId: string,
        cancellationToken?: CancellationToken)
        : Promise<string>;

    /**
     * Sets the authentication token for the RPC session(s).
     * @param loginTokenOrCode Token acquired from the Cascade authentication service,
     * or a short code that can be used to acquire a token.
     * @param options Login options.
     * @param userInfo User info.
     * @param cancellationToken A cancellation token.
     * @returns Information about the logged-in user, or null if the token is invalid
     * or expired.
     */
    loginAsync(
        loginTokenOrCode: AuthenticationToken,
        options: AuthenticationOptions,
        userInfo: UserInfo,
        cancellationToken?: CancellationToken)
        : Promise<UserInfo>;

    /**
     * Sets the anonymnous authentication token for the RPC session(s).
     * @returns Information about the logged-in user, or null if the token is invalid
     * or expired.
     */
    loginAsAnonymousAsync(
        options: AuthenticationOptions,
        cancellationToken?: CancellationToken)
        : Promise<UserInfo>;

    /**
     * Looks for a cached auth token matching the provided account info, and attempts to
     * sets the authentication token for the RPC session(s) with that cached token,
     * if the token is still valid.
     * @param accountInfo Details about the account used to find a
     * matching cached auth token.
     * @param options Login options.
     * @param cancellationToken A cancellation token.
     * @returns Information about the logged-in user, or null if a matching token
     * was not found or the token is invalid or expired.
     */
    loginWithCachedTokenAsync(
        accountInfo: UserAccountInfo,
        options: AuthenticationOptions,
        cancellationToken?: CancellationToken)
        : Promise<UserInfo>;

    /**
     * Using the supplied credential, conduct and attempts to sets the authentication
     * token for the RPC session(s) with that cached token, if the token is still valid.
     * @param externalAccountInfo Details about the account used to find a
     * matching cached auth token.
     * @param options Login options.
     * @param userInfo User info.
     * @param cancellationToken A cancellation token.
     * @returns Information about the logged-in user, or null if a matching token
     * was not found or the token is invalid or expired.
     */
    loginWithExternalTokenAsync(
        externalAccountInfo: UserAccountInfo,
        externalToken: AuthenticationToken,
        options: AuthenticationOptions,
        userInfo: UserInfo,
        cancellationToken?: CancellationToken)
        : Promise<UserInfo>;

    /**
     * Clears the authentication token for the RPC session(s).
     * @param options Logout options.
     * @param cancellationToken A cancellation token.
     */
    logoutAsync(
        options: AuthenticationOptions,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Gets current cached token.
     * @returns 
     */
    getCachedTokenAsync(
        cancellationToken?: CancellationToken)
        : Promise<AuthenticationToken>;
}

