/**
 * Interface for sharing local servers and named pipes.
 * It controls what local tcp ports and pipes can be forwarded to,
 * and configures `IStreamManagerService` appropriately.
 */
export interface ServerSharingService {
    /**
     * Configures a forwarding stream provider in `IStreamManagerService`
     * to start forwarding to localhost:`port` tcp socket.
     * Use the result's `StreamName` and
     * `StreamCondition` to get a stream from
     * `GetStreamAsync()`
     * which would wrap the network stream to the socket.
     * If the port is already forwarded, `sessionName` is ignored.
     * @param port Local tcp port to connect to. Not 0 or negative.
     * @param sessionName Port forwarding session name. Not null or empty.
     * @param browseUrl Browser URL if the server is a browser session or null.
     * @param cancellationToken Cancellation token
     * @returns Shared local server info, not null.
     */
    startSharingAsync(
        port: number,
        sessionName: string,
        browseUrl: string,
        cancellationToken?: CancellationToken)
        : Promise<SharedServer>;

    /**
     * Configures a forwarding stream provider in `IStreamManagerService`
     * to start forwarding to local pipe `pipeName`.
     * Use the result's `StreamName` and
     * `StreamCondition` to get a stream from
     * `GetStreamAsync()`
     * which would wrap the network stream to the pipe.
     * If the pipe is already forwarded, `sessionName` is ignored.
     * @param pipeName Local pipe name to connect to 0. Not null or empty.
     * @param sessionName Pipe forwarding session name. Not null or empty.
     * @param sendClientAccessInfoOnConnection A value indicating whether Server Sharing Service will send a ClientAccessInfo off the RPC context to the pipe when a guest connects to it.
     * @param cancellationToken Cancellation token
     * @returns Shared local pipe info, not null.
     */
    startSharingPipeAsync(
        pipeName: string,
        sessionName: string,
        sendClientAccessInfoOnConnection: boolean,
        cancellationToken?: CancellationToken)
        : Promise<SharedPipe>;

    /**
     * Stops sharing of the local tcp `port`.
     * @param port Port to stop sharing. Not 0 or negative.
     * @param cancellationToken A cancellation token.
     */
    stopSharingAsync(
        port: number,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Stops sharing of the local pipe `pipeName`.
     * @param pipeName Pipe to stop sharing. Not null or empty string.
     * @param cancellationToken A cancellation token.
     */
    stopSharingPipeAsync(
        pipeName: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Stops sharing all previousely shared browse sessions.
     */
    stopSharingBrowseSessionsAsync(
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Gets all shared local servers.
     * @param cancellationToken Cancellation token
     * @returns An array of all active shared local servers.
     */
    getSharedServersAsync(
        cancellationToken?: CancellationToken)
        : Promise<SharedServer[]>;

    /**
     * Gets all shared local pipes.
     * @param cancellationToken Cancellation token
     * @returns An array of all active shared local pipes.
     */
    getSharedPipesAsync(
        cancellationToken?: CancellationToken)
        : Promise<SharedPipe[]>;

    /**
     * Updates the session name of the shared server
     * @param port Port of the shared server to update. Not 0 or negative
     * @param newSessionName New session name.
     * @param cancellationToken Cancellation token.
     */
    updateSessionNameAsync(
        port: number,
        newSessionName: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * DEPRECATED! Use UpdateSharedServerPrivacyAsync instead.
     * Updates the port visibility.
     * @param port Port of the shared server to update. Not 0 or negative
     * @param isPublic Port visibility. True when port is public.
     * @param cancellationToken Cancellation token.
     */
    updateSharedServerVisibilityAsync(
        port: number,
        isPublic: boolean,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Updates the port protocol.
     * @param port Port of the shared server to update. Not 0 or negative
     * @param isHttps Port protocol. True when port is https and False with it is http.
     * @param cancellationToken Cancellation token.
     */
    updateSharedServerProtocolAsync(
        port: number,
        isHttps: boolean,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Updates the port privacy setting.
     * @param port Port of the shared server to update. Not 0 or negative
     * @param privacy Port privacy setting.
     * @param cancellationToken Cancellation token
     */
    updateSharedServerPrivacyAsync(
        port: number,
        privacy: PrivacyEnum,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * An event to fire when a new server is shared.
     */
    readonly onSharingStarted: Event<ServerSharingStartedEventArgs>;

    /**
     * An event to fire when a new pipe is shared.
     */
    readonly onPipeSharingStarted: Event<PipeSharingStartedEventArgs>;

    /**
     * An event to fire when browse sharing is shared.
     * It is fired any time when `StartSharingAsync()`
     * is called with `isBrowseSession` = true, even if the port is already shared.
     */
    readonly onBrowseSharingStarted: Event<ServerSharingStartedEventArgs>;

    /**
     * An event to fire when server is no longer shared.
     */
    readonly onSharingStopped: Event<ServerSharingStoppedEventArgs>;

    /**
     * An event to fire when pipe is no longer shared.
     */
    readonly onPipeSharingStopped: Event<PipeSharingStoppedEventArgs>;

    /**
     * An event to fire when shared server has changed.
     */
    readonly onSharingChanged: Event<ServerSharingChangedEventArgs>;
}

