/**
 * Provides remote access to the file system of the current workspace.
 */
export interface FileService {
    /**
     * Adds a set of external files to the collaboration session.
     * The vsls path is generated by the client-side path converter, and is simply cached here.
     * This method can be called only by the host client.
     * Dictionary maps local paths to vsls paths: e.g., {"C:/Users/Caitlin/webapp/banana" : "/~external/a1b2c3/banana"}
     */
    registerExternalFilesAsync(
        localPaths: string[],
        cancellationToken?: CancellationToken)
        : Promise<string[]>;

    listRootsAsync(
        options: FileListOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileRootInfo[]>;

    listAsync(
        paths: string[],
        options: FileListOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileInfo[]>;

    readTextAsync(
        path: string,
        options: FileReadOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileTextInfo>;

    readTextWithProgressAsync(
        paths: string[],
        options: FileReadOptions,
        progress: Progress<ReadTextResult>,
        cancellationToken?: CancellationToken)
        : Promise<FileTextInfo[]>;

    writeTextAsync(
        path: string,
        text: string,
        options: FileWriteOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileInfo>;

    createDirectoryAsync(
        path: string,
        cancellationToken?: CancellationToken)
        : Promise<FileInfo>;

    deleteAsync(
        path: string,
        options: FileDeleteOptions,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    copyAsync(
        sourcePath: string,
        targetPath: string,
        options: FileMoveOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileInfo>;

    moveAsync(
        sourcePath: string,
        targetPath: string,
        options: FileMoveOptions,
        cancellationToken?: CancellationToken)
        : Promise<FileInfo>;

    getFilesAsync(
        options: FileListOptions,
        cancellationToken?: CancellationToken)
        : Promise<string[]>;

    /**
     * Get a value indicating whether the file is excluded following these rules:
     * 1. If the file is not in any shared root, or there are no roots, the file is considered not excluded.
     * 2. If the file is inside any shared root, then it's excluded if any of the following is true:
     * 2.1. The file name matches `options`.ExcludePatterns.
     * 2.2. The file doesn't exist (or it's a directory).
     * 2.3. The file matches any exclude pattern in some .vsls.json file in its directory or any parent directory in the shared folder.
     * @param path Remote unescaped path to the file, not null.
     * @param options Optional file list options, only ExcludePatterns is used from it.
     * @param cancellationToken Cancellation token.
     * @returns Task which result indicates whether the file is excluded.
     */
    isExcludedAsync(
        path: string,
        options: FileListOptions,
        cancellationToken?: CancellationToken)
        : Promise<boolean>;

    /**
     * Find files in active roots. Doesn't do anything if there is no active roots.
     * @param query 
     * @param options 
     * @param cancellationToken 
     * @returns 
     */
    findFilesAsync(
        query: string,
        options: FileListOptions,
        cancellationToken?: CancellationToken)
        : Promise<string[]>;

    getTextSearchResultsAsync(
        options: TextSearchOptions,
        cancellationToken?: CancellationToken)
        : Promise<TextSearchResult[]>;

    getTextSearchResultsWithProgressAsync(
        options: TextSearchOptions,
        progress: Progress<TextSearchResult>,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    clearRootsAsync(
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Add a new root to the workspace.
     * @param rootDir Optional root dir. May be null.
     * @param cancellationToken Cancellation token
     */
    addRootAsync(
        rootDir: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    removeRootAsync(
        rootDir: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Replaces the root of the workspace.
     * @param rootDir Root directory.
     * @param cancellationToken Cancellation token
     */
    replaceRootAsync(
        rootDir: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    readonly onFilesChanged: Event<FilesChangedEventArgs>;

    /**
     * Event fired when a workspace root is added or removed
     */
    readonly onRootsChanged: Event<RootsChangedEventArgs>;

    /**
     * Event fired when external files are added or removed
     */
    readonly onExternalFilesChanged: Event<ExternalFilesChangedEventArgs>;
}

