/**
 * Provides access to an opaque stream that can be remoted. This service is useful when providing
 * a service that needs to communicate using its own protocol.
 */
export interface StreamManagerService {
    /**
     * Given a stream name (for eg from `WellKnownStreams`), get the id of the stream
     * @param streamName Name of the stream
     * @param condition If there are multiple streams created for a given name, get a stream for this condition
     * @param cancellationToken A cancellation token.
     * @returns Id of the stream
     */
    getStreamAsync(
        streamName: string,
        condition: string,
        cancellationToken?: CancellationToken)
        : Promise<string>;
}

/**
 * Provides read\write capabilities on a stream remoted via `IStreamManagerService`
 */
export interface StreamService {
    /**
     * Get stream traits.
     */
    getStreamTraitsAsync(
        id: string,
        cancellationToken?: CancellationToken)
        : Promise<StreamTraits>;

    /**
     * Gets stream length in bytes.
     */
    getLengthAsync(
        id: string,
        cancellationToken?: CancellationToken)
        : Promise<number>;

    /**
     * Sets stream length in bytes.
     */
    setLengthAsync(
        id: string,
        length: number,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Moves the current stream position and returns current position.
     */
    seekAsync(
        id: string,
        offset: number,
        origin: SeekOrigin,
        cancellationToken?: CancellationToken)
        : Promise<number>;

    /**
     * Reads `count` bytes from the stream.
     */
    readBytesAsync(
        id: string,
        count: number,
        cancellationToken?: CancellationToken)
        : Promise<stringBase64>;

    /**
     * Writes bytes to the stream.
     */
    writeBytesAsync(
        id: string,
        bytes: stringBase64,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Disposes the stream. Does nothing if there is no such stream or if it has been disposed of already.
     */
    disposeStreamAsync(
        id: string,
        cancellationToken?: CancellationToken)
        : Promise<void>;
}

/**
 * Represents an API for managing workspace tasks. It allows running a task on a host machine, as well as
 * managing running task status.
 */
export interface WorkspaceTaskService {
    /**
     * Retrieves a list of all tasks supported by the host.
     * @returns Collection of remote tasks
     */
    getSupportedTasksAsync(
        cancellationToken?: CancellationToken)
        : Promise<WorkspaceTask[]>;

    /**
     * Retrieves a list of all tasks currently running on the host.
     * @returns Collection of remote task IDs
     */
    getTaskExecutionsAsync(
        cancellationToken?: CancellationToken)
        : Promise<TaskExecutionMoniker[]>;

    /**
     * Sends request to a host to start given task by its IDs.
     */
    runTaskAsync(
        taskUid: string,
        cancellationToken?: CancellationToken)
        : Promise<RunTaskResult>;

    /**
     * Sends request to a host to start given task by its IDs and name of the project.
     */
    runProjectTaskAsync(
        taskUid: string,
        projectName: string,
        cancellationToken?: CancellationToken)
        : Promise<RunTaskResult>;

    /**
     * Requests default build task.
     */
    runDefaultBuildTaskAsync(
        cancellationToken?: CancellationToken)
        : Promise<RunTaskResult>;

    /**
     * Attempts to terminate a running task given its unique ID.
     */
    terminateTaskAsync(
        taskExecution: TaskExecutionMoniker,
        cancellationToken?: CancellationToken)
        : Promise<void>;

    /**
     * Raised when task task has been started.
     */
    readonly onTaskStarted: Event<TaskExecutionStatusEventArgs>;

    /**
     * Raised after the task has been terminated.
     */
    readonly onTaskTerminated: Event<TaskExecutionStatusEventArgs>;
}

