import { vsls } from '@vs/vsls-contracts';
import { assertDefined, TConstructable, Signal, raceAsync } from '@vs/vscs-utils';
import { Performance } from '@vs/vscs-performance';

import { ILiveShareConnectionOptions } from '@vs/vso-workspace-core';
import { LiveShareConnection } from './LiveShareConnection';
import { ConnectionHub } from '../connectionHub/ConnectionHub';
import { ILiveShareConnection } from '../interfaces/ILiveShareConnection';
import { ILiveShareJointConnection } from '../interfaces/ILiveShareJointConnection';
import { ILogger } from '@vs/vso-logging';

type TLiveShareConnectionHub<T extends ILiveShareConnectionOptions> = ConnectionHub<
    TConstructable<ILiveShareConnection<T>>
>;

/**
 * Class to connect to LiveShare Session through a main thread or service worker.
 */
export class LiveShareJointConnection<
    TOptions extends ILiveShareConnectionOptions = ILiveShareConnectionOptions
> extends LiveShareConnection<TOptions> implements ILiveShareJointConnection<TOptions> {
    constructor(
        trace: ILogger,
        protected readonly performance: Performance,
        public readonly options: TOptions,
        protected readonly connectionHubs: Array<TLiveShareConnectionHub<TOptions>>
    ) {
        super(trace.createChild('liveshare-joint'), performance, options);
    }

    public get type() {
        assertDefined(this.connectionReference, '');

        return this.connectionReference.type;
    }

    public get workspaceSessionInfo(): vsls.WorkspaceSessionInfo | undefined {
        if (!this.connectionReference) {
            return;
        }

        return this.connectionReference.workspaceSessionInfo;
    }

    public get connection() {
        return this.connectionReference;
    }

    /******************************************************
     * Implementation details.
     ******************************************************/

    private connectionReference: ILiveShareConnection<TOptions> | null = null;

    protected async createConnection(): Promise<this> {
        try {
            this.trace.info('creating connection');
            this.connectionSignal = new Signal();
            this.addToDisposables(this.connectionSignal);

            this.onConnectionChangedHandler('connecting');

            const connectionPromises = this.connectionHubs.map((hub, i) => {
                return hub.connectOnce(this.options, {
                    performance: this.performance.createGroup(`connection #${i}`),
                });
            });

            const connection = await raceAsync(connectionPromises);

            connection.addToDisposables(this);

            assertDefined(this.connectionSignal, 'No connection signal found.');

            this.connectionReference = connection;
            this.workspaceClientReference = connection.workspaceClient;
            this.addToDisposables(connection);

            this.addToDisposables(
                connection.onConnectionChanged(
                    this.onConnectionChangedEventEmitter.fire.bind(connection)
                )
            );

            this.onConnectionChangedHandler('connected');

            return this;
        } catch (e) {
            this.handleConnectionError(e);

            throw e;
        }
    }
}
