'use strict';

import { UriHandler, Uri, window } from 'vscode';

import { 
    TelemetryEvent,
    ITelemetryEvent
} from '@vs/vso-telemetry';

import { TelemetryPropertyNames, TelemetryEventNames } from '../telemetry/TelemetryStrings';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { SessionState } from '../SessionTypes';
import { sessionStateTracker } from '../SessionStateTracker';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { auth } from './Authentication';
import { traceSource } from '@vs/vscode-command-framework';
import { JoinCommandOptions } from '../commands/JoinCommandOptions';
import { executeNextCommand } from '../utils/commandUtils';
import { TraceFormat } from '@vs/vso-logging';

const AUTH_PROTOCOL_HANDLER_PATH = '/signin';

export const registerProtocolHandler = (telemetryEvent: ITelemetryEvent): void => {
    if (typeof window.registerUriHandler === 'function') {
        ExtensionUtil.context.subscriptions.push(window.registerUriHandler(new VSLSProtocolHandler(telemetryEvent)));
    }
};

// note that curreently does not support query arrays, e.g. `foo=1&foo=2&foo=3`
function parseQuery(queryString: string) {
    const query: { [key: string]: string; } = {};

    queryString = (queryString[0] === '?')
                    ? queryString.substr(1)
                    : queryString;

    const pairs = (queryString).split('&');
    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i].split('=');
        const name = decodeURIComponent(pair[0]);
        const value = decodeURIComponent(pair[1] || '');
        query[name] = value;
    }

    return query;
}

class VSLSProtocolHandler implements UriHandler {
    constructor(private telemetryEvent: ITelemetryEvent) {}    

    public async handleUri(uri: Uri): Promise<void> {
        const { path } = uri;
        const cleanPath = path.split('?')[0];

        traceSource.verbose(`handleUri => uri:${TraceFormat.formatText(uri.toString())}`);

        switch (cleanPath) {
            case '/join': {
                return this.join(uri);
            }
            case AUTH_PROTOCOL_HANDLER_PATH: {
                await auth.API.authCallback(uri);
                
                break;
            }
                
            default: {
                break;
            }
        }
    }

    private join(uri: Uri): void {
        const query = parseQuery(uri.query);
        const { vslsLink, correlationId } = query;

        const privacySafeUri = uri.with({ query: `workspaceId=censored&correlationId=${correlationId}` });
        this.reportInvocationToTelemetry(privacySafeUri);
        
        if (vslsLink) {
            const joinPreReloadCommandName = `${Settings.get<string>(SettingKeys.commandPrefix)}.join`;
            const link = decodeURIComponent(vslsLink);
            const newWindow = (sessionStateTracker.State === SessionState.Joined) || (sessionStateTracker.State === SessionState.Shared);

            traceSource.verbose(`VSLSProtocolHandler join => link:${link} correlationId:${correlationId}`);

            const joinPreReloadCommandOptions: JoinCommandOptions = {
                correlationId,
                link,
                newWindow
            };

            executeNextCommand(joinPreReloadCommandName, joinPreReloadCommandOptions);
            return;
        }

        throw new Error('VSCode protocol handler passed a link with unknown format.');
    }

    private reportInvocationToTelemetry(uri: Uri) {
        const telemetryEvent = new TelemetryEvent(TelemetryEventNames.INVOKE_NEWPROTOCOLHANDLER)
            .addProperty(TelemetryPropertyNames.URI, uri.toString())
            .correlateWith(this.telemetryEvent)
            .send();
    }

    public dispose(): void {}
}
