import * as vscode from 'vscode';
import { ISettingsProvider } from './ISettingsProvider';
import { defaultSettings } from './DefaultSettings';
import { SettingKeys } from '../SettingKeys';
import { RemoteConfig } from '../RemoteConfig';
import * as url from 'url';
import { ILogger } from '@vs/vso-logging';
import { readUserSettings } from '@core-abstractions/SettingsProvider';
import { IMementoConfig } from './IMementoConfig';

const privateSettings = [
    SettingKeys.commandPrefix,
    SettingKeys.serviceUri,
    SettingKeys.signalRServiceUri,
    SettingKeys.scheme,
    SettingKeys.authority,
    SettingKeys.canCollectPII,
    SettingKeys.desyncReload,
    SettingKeys.userEmail,
    SettingKeys.isInternal,
    SettingKeys.isCloudEnvironment,
    SettingKeys.name,
    SettingKeys.shortName,
    SettingKeys.abbreviation,
    SettingKeys.licenseUrl,
    SettingKeys.privacyUrl,
    SettingKeys.hasUsed,
    SettingKeys.configName,
    SettingKeys.activityTimeout,
    SettingKeys.customAccountAuthReloadFlag,
    SettingKeys.anonymousAuthReloadFlag,
    SettingKeys.nativeAuthFlow,
    SettingKeys.authenticationProvider,
    SettingKeys.useClientFileService,
    SettingKeys.remoteSettingsUri,
    SettingKeys.remoteSettingsUpdateMinutes,
    SettingKeys.runsInVSCodeDev,
];

const mementoSettings = [
    SettingKeys.anonymousUserName,
    SettingKeys.microphoneId,
    SettingKeys.speakerId,
    SettingKeys.newChatDisplayDate,
    SettingKeys.newAudioDisplayDate,
    SettingKeys.sessionCount,
    SettingKeys.dontRequestFeedback,
    SettingKeys.dontRequestAdditionalFeedback,
    SettingKeys.surveyShownDate,
    SettingKeys.firstActivationTime
];

function isPrivateKey(key: SettingKeys): boolean {
    return privateSettings.indexOf(key) >= 0;
}

function isMementoKey(key: SettingKeys): boolean {
    return mementoSettings.indexOf(key) >= 0;
}

function getInternal<T>(key: string): T | undefined {
    if (defaultSettings.hasOwnProperty(key)) {
        return defaultSettings[key] as T;
    }
}

export class DefaultSettingsProvider implements ISettingsProvider {
    private userSettings: { [key: string]: any } = {};
    private mementoConfigInstance: MementoConfig;

    async init(context: vscode.ExtensionContext, logger?: ILogger): Promise<void> {
        this.mementoConfigInstance = new MementoConfig(context);
        this.userSettings = await readUserSettings();
        const remoteSettingsUri = getInternal<string>(SettingKeys.remoteSettingsUri);
        if (remoteSettingsUri) {
            const updatePeriodInMinutes = getInternal<number>(SettingKeys.remoteSettingsUpdateMinutes);
            await RemoteConfig.init(context, url.parse(remoteSettingsUri), updatePeriodInMinutes, logger);
        }
    }
    get mementoConfig() {
        return this.mementoConfigInstance;
    }

    get ready() {
        return RemoteConfig.waitForUpdate;
    }

    get<T>(key: string): T | undefined {
        if (this.userSettings.hasOwnProperty(key)) {
            return this.userSettings[key] as T;
        }

        if (isPrivateKey(<SettingKeys>key) || isMementoKey(<SettingKeys>key)) {
            const value = getInternal<T>(key);
            if (value === undefined && isMementoKey(<SettingKeys>key)) {
                return this.mementoConfigInstance.get(key);
            }
    
            return value;
        }

        const extensionConfig = vscode.workspace.getConfiguration(getInternal<string>(SettingKeys.configName));
        const remoteDefaultValue = RemoteConfig.getDefault<T>(key);
        if (remoteDefaultValue !== undefined) {
            // Remote defaults, when set, are used as the default value instead of the
            // default value declared in the extension package. The default substitution
            // is achieved by using inspect() instead of get().
            const setting = extensionConfig.inspect<T>(key);
            if (setting) {
                if (setting.workspaceFolderValue !== undefined) {
                    return setting.workspaceFolderValue;
                } else if (setting.workspaceValue !== undefined) {
                    return setting.workspaceValue;
                } else if (setting.globalValue !== undefined) {
                    return setting.globalValue;
                }
                // setting.defaultValue is not used in this case.
            }
            return remoteDefaultValue;
        } else {        
            const configValue = extensionConfig.get<T>(key);
            return configValue;
        }
    }

    save(key: string, value: any, global: boolean): Thenable<void> {
        if (isPrivateKey(<SettingKeys>key)) {
            return defaultSettings[key] = value;
        }
    
        if (isMementoKey(<SettingKeys>key)) {
            return this.mementoConfigInstance.save(key, value);
        }

        const extensionConfig = vscode.workspace.getConfiguration(getInternal<string>(SettingKeys.configName));
        return extensionConfig.update(key, value, global);
    }
}

class MementoConfig implements IMementoConfig {
    private readonly globalState: vscode.Memento;

    constructor(context: vscode.ExtensionContext) {
        this.globalState = context.globalState;
    }

    public get<T>(key: string): T | undefined {
        return this.globalState.get<T>(key);
    }

    public async save(key: string, value: any): Promise<void> {
        await this.globalState.update(key, value);
    }
}