import { ICommandContext } from '@vs/vscode-command-framework';
import {
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { ContactManager } from '../ContactManager';
import { ContactTreeExplorerItem } from '../ContactsProviderViewlet';

export function builder(): ICommand<boolean> {
    return new RemoveRecentContactCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.REMOVE_RECENT_CONTACT, TelemetryEventNames.REMOVE_RECENT_CONTACT_FAULT, 'RemoveRecentContact', 1)
class RemoveRecentContactCommand implements ICommand<boolean> {

    public async invoke(item: ContactTreeExplorerItem, context: ICommandContext): Promise<boolean> {
        return await ContactManager.removeRecentContact(item.contactModel);
    }
}