import * as vscode from 'vscode';

import { PolicyProvider, Policy } from '@vs/liveshare-api-contracts';
import { traceSource } from '@vs/vscode-command-framework';
import { SettingKeys, defaultSettings, getExpService, ExtensionUtil } from '@vs/liveshare-core';
import { ResolutionStrategyFactory } from './policies/resolutionStrategyFactory';

class EnterpriseConfig {
    private static singleton: EnterpriseConfig;
    private ignoreConfigUpdates: boolean;
    private resolutionFactory: ResolutionStrategyFactory;
    private resolutionMap: Map<string, Policy>;
    private policyProviders: Map<string, PolicyProvider> = new Map<string, PolicyProvider>();
    private policyManagedSettings: string[] = [
        SettingKeys.allowedDomains,
        SettingKeys.allowReadWriteTerminals
    ];

    public static get Instance(): EnterpriseConfig {
        if (!EnterpriseConfig.singleton) {
            EnterpriseConfig.singleton = new EnterpriseConfig();
        }
        return EnterpriseConfig.singleton;
    }

    constructor() {
        this.resolutionMap = new Map<string, Policy>();
        this.resolutionFactory = new ResolutionStrategyFactory();
        this.ignoreConfigUpdates = false;

        vscode.workspace.onDidChangeConfiguration(event => this.configurationChangeHandler(this.ignoreConfigUpdates, event));
    }

    public async isEnabled(): Promise<boolean> {
        const expService = getExpService();
        if (expService) {
            return await expService.isCachedFlightEnabled('policies');
        }

        return false;
    }

    public get<T>(keyString: string): T | undefined {
        let policy = this.resolutionMap.get(keyString);

        if (!policy) {
            return undefined;
        }

        if (!this.policyManagedSettings.includes(policy.policySetting) && !policy.isEnforced) {
            return undefined;
        }

        return policy.value as T;
    }

    public async registerPolicyProvider(name: string, policyProvider: PolicyProvider): Promise<vscode.Disposable | null> {
        if (!await this.isEnabled()) {
            return null;
        }

        traceSource.info(`Register provier with name: ${name}`);

        if (!policyProvider) {
            return null;
        }

        this.policyProviders.set(name, policyProvider);
        this.rebuildResolutionMap();

        return new vscode.Disposable(() => {
            this.policyProviders.delete(name);
            this.rebuildResolutionMap();
        });
    }

    private configurationChangeHandler(ignoreConfigUpdates: boolean, event: vscode.ConfigurationChangeEvent) {
        if (ignoreConfigUpdates) {
            return;
        }

        let config = vscode.workspace.getConfiguration(defaultSettings.configName);

        this.resolutionMap.forEach(async entry => {
            if (!entry.isEnforced) {
                return;
            }

            let configurationName = `${defaultSettings.configName}.${entry.policySetting}`;
            if (event.affectsConfiguration(configurationName)) {
                let currentConfigurationValue = config[entry.policySetting];

                if (currentConfigurationValue !== entry.value) {
                    this.ignoreConfigUpdates = true;
                    config.update(entry.policySetting, entry.value, vscode.ConfigurationTarget.Global);
                    this.ignoreConfigUpdates = false;

                    await vscode.window.showInformationMessage(`An attempt to override a setting enforced by external extension. ` +
                    `The value of '${entry.policySetting}' has been set back to '${entry.value}'.`);
                    return;
                }
            }
        });
    }

    private rebuildResolutionMap(): void {
        this.resolutionMap.clear();

        this.policyProviders.forEach((policyProvider, key) => {

            let policies: Policy[];

            try {
                policies = policyProvider.providePolicies();
            } catch (e) {
                traceSource.error(`'${key}' policy provider failed`, e);
                return;
            }

            for (let policy of policies) {
                if (!this.resolutionMap.has(policy.policySetting)) {
                    this.resolutionMap.set(policy.policySetting, policy);
                    continue;
                }

                let existingPolicy = this.resolutionMap.get(policy.policySetting);

                if (existingPolicy === undefined) {
                    this.resolutionMap.set(policy.policySetting, policy);
                    continue;
                }

                let value = this.resolutionFactory.resolve(
                    SettingKeys[policy.policySetting],
                    existingPolicy.value,
                    policy.value
                );

                if (value === undefined) {
                    traceSource.info(`Failed to resolve policy conflict for: ${policy.policySetting}`);
                } else if (policy.value === value) {
                    this.resolutionMap.set(policy.policySetting, policy);
                }
            }
        });

        const config = vscode.workspace.getConfiguration(defaultSettings.configName);
        this.ignoreConfigUpdates = true;

        for (let entry of this.resolutionMap.values()) {
            if (this.policyManagedSettings.includes(entry.policySetting)) {
                continue;
            }
            config.update(entry.policySetting, entry.value, vscode.ConfigurationTarget.Global);
        }

        this.ignoreConfigUpdates = false;
    }
}

const entepriseConfigInstance = EnterpriseConfig.Instance;
export { entepriseConfigInstance as EnterpriseConfig };