import { CancellationTokenSource } from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { dependencies } from '../Dependencies';
import { ISessionContext } from '../ISessionContext';
import { SessionState } from '../SessionTypes';

export function cancellationDecorator() {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => {
            return new CancellationDecorator(
                DecoratorHelper.getCoreCommand(command),
                command,
                dependencies.sessionContext()
            );
        }
    );
}

/**
 * Cancellation Token decorator is responsible for setting up the cancellation token for the entire command flow and
 * cancelling a previous command cancellation token, if present.
 */
export class CancellationDecorator implements ICommandDecorator {
    private static currentCancellationTokenSource: CancellationTokenSource;
    private static sessionStateBeforeStarted: SessionState;

    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private sessionContext: ISessionContext) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any;

        // cancel the previous command if running
        this.cancelPreviousCommandIfRunning();

        // set the cancellation token to the command context
        CancellationDecorator.currentCancellationTokenSource = new CancellationTokenSource();
        context.cancellationTokenSource = CancellationDecorator.currentCancellationTokenSource;
        
        result = await this.next.invoke(options, context);

        return result;
    }

    private cancelPreviousCommandIfRunning() {
        const currentCancellationTokenSource = CancellationDecorator.currentCancellationTokenSource;
        const commandCancellationToken = currentCancellationTokenSource && currentCancellationTokenSource.token;
        if (commandCancellationToken && !commandCancellationToken.isCancellationRequested) {
            currentCancellationTokenSource.cancel();
        }
    }
}
