import * as vscode from 'vscode';
import { ShareDebugManagerBase } from './shareDebugManagerBase';
import { EventReason } from '../workspace/contract/debugEvents';
import { DebugProtocol } from 'vscode-debugprotocol';
import { TraceSource } from '@vs/vso-logging';
import * as config from '../config';
import * as net from 'net';
import * as rpc from 'vscode-jsonrpc';
import * as stream from 'stream';
import * as path from 'path';
import * as os from 'os';
import * as child_process from 'child_process';

import { IHostAdapterService } from './IHostAdapterService';
import {
    EXTENSION_ROOT_PATH,
    DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME,
    DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME } from '../constants';
import { OSPlatform } from '@vs/vso-node-utils';

import {
    Lazy,
    IClientAccessCheck,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { activitySource, ActivityType } from '@vs/activity-log';
import { setTimeout } from 'timers';
import { PackageManager } from '../packageManager';
import { IRpcClient } from '@vs/vso-rpc';

/**
 * Class to register a 'DebugConfigurationProvider' implementation and create 'IDebugAdapterTracker' trackers
 */
export class TrackDebugManager extends ShareDebugManagerBase implements vscode.DebugAdapterTrackerFactory {
    constructor(
        rpcClient: IRpcClient,
        private hostAdapterService: IHostAdapterService,
        fileService: Lazy<vsls.FileService>,
        clientAccessCheck: Lazy<IClientAccessCheck>)  {
        
        super(rpcClient, fileService, clientAccessCheck);

        this.trace.verbose('TrackDebugManager created');

        // register '*' to intercept all possible types
        vscode.debug.registerDebugAdapterTrackerFactory('*', this);
    }

    public createDebugAdapterTracker(session: vscode.DebugSession): vscode.ProviderResult<vscode.DebugAdapterTracker> {
        return new DebugAdapterTracker(this,
            this.trace,
            session,
            this.hostAdapterService.pipeName);
    }
}

/**
 * Class that implements IDebugAdapterTracker and handle the connection/launch with our debug host adapter
 */
class DebugAdapterTracker implements vscode.DebugAdapterTracker {
    private static readonly adapterBinariesPath = path.join(EXTENSION_ROOT_PATH, 'dotnet_modules');

    // Method names to send to our launch adapter
    private static readonly onFireHostDebugEventMethod = 'OnFireHostDebugEvent';
    private static readonly onFireEnterRunModeMethod = 'OnFireEnterRunMode';
    private static readonly initializeAsyncMethod = 'InitializeAsync';
    private static readonly stopAsyncMethod = 'StopAsync';
    private static readonly commandToVSCodeCommand = new Map<string, string>([
        ['continue', 'workbench.action.debug.continue'],
        ['next', 'workbench.action.debug.stepOver'],
        ['stepIn', 'workbench.action.debug.stepInto'],
        ['stepOut', 'workbench.action.debug.stepOut']
    ]);

    // Method names being request/notified by the launch adapter
    private static readonly fireEnterRunModeMethod = 'fireEnterRunMode';
    private static readonly terminateMethod = 'terminate';
    private static readonly sendRequestHostMethod = 'sendRequestHost';

    private capabilities: DebugProtocol.Capabilities;
    private rpcConnection: rpc.MessageConnection;
    private socket: net.Socket;
    private adapterProcess: child_process.ChildProcess;
    private lastStoppedEvent: DebugProtocol.StoppedEvent;
    private onDidChangeIsSharingEvt: vscode.Disposable;

    // this will keep track of the session events that will be queued during the connection awaiting
    private sessionQueueEvents: Array<{
        event: string;
        body: any;
    }>;

    constructor(
        private readonly trackDebugManager: TrackDebugManager,
        private readonly trace: TraceSource,
        private readonly session: vscode.DebugSession,
        private readonly hostPipeName: string) {

            this.trace.verbose(`DebugAdapterTracker created sessionId:${this.session.id}`);
            this.onDidChangeIsSharingEvt = trackDebugManager.onDidChangeIsSharing((isSharing) => this.onSharingStateChanged(isSharing));
    }

    private get isExtensionHost() {
        return this.session.configuration.type === 'extensionHost';
    }

    public onWillReceiveMessage(message: any): void {
        const requestMessage = <DebugProtocol.Request>message;
        switch (requestMessage.command) {
            case 'continue':
                this.fireEnterRunMode(requestMessage, EventReason.Go);
                break;
            case 'next':
            case 'stepIn':
            case 'stepOut':
                this.fireEnterRunMode(requestMessage, EventReason.Step);
                break;
            default:
                break;
        }        
}

    public onDidSendMessage?(message: any): void {
        const protocolMessage = <DebugProtocol.ProtocolMessage>message;
        if (protocolMessage.type === 'event') {
            const eventMessage = <DebugProtocol.Event>protocolMessage;
            switch (eventMessage.event) {
                case 'stopped':
                    this.lastStoppedEvent = <DebugProtocol.StoppedEvent>eventMessage;
                    break;
                default:
            }        

            if (this.rpcConnection) {
                this.notifyDebugEvent(eventMessage.event, eventMessage.body);
            } else if (this.sessionQueueEvents) {
                this.sessionQueueEvents.push({
                    event: eventMessage.event,
                    body: eventMessage.body
                });
            }
        } else if (protocolMessage.type === 'response') {
            const responseMessage = <DebugProtocol.Response>protocolMessage;
            switch (responseMessage.command) {
                case 'initialize':
                    this.capabilities = (<DebugProtocol.InitializeResponse>responseMessage).body;
                    this.trace.verbose(`initialize response with capabilities:${JSON.stringify(this.capabilities)}`);
                    if (!this.isExtensionHost) {
                        this.createDebugSession();
                    }
                    break;
                case 'attach':
                    // For extension host debugging wait for the 'attach' command
                    // to create a debug session. A 'launch' command will also be
                    // sent for extension hosts but should be ignored.
                    if (this.isExtensionHost) {
                        this.createDebugSession();
                    }                              
                    break;
                default:
            }        
        }
    }

    public onWillStopSession(): void {
        this.trace.verbose(`onWillStopSession sessionId:${this.session.id}`);
        this.stop();
    }

    private async createDebugSession(): Promise<void> { 
        this.trace.verbose(`createDebugSession sessionId:${this.session.id}`);
        if (this.trackDebugManager.isSharing) {
            await this.startSession();
        }

        const vslsDebugSession = new vsls.DebugSession();
        ShareDebugManagerBase.fillDebugSession(vslsDebugSession, this.session, this.capabilities, this.session.configuration);
        await this.trackDebugManager.addDebugSession(vslsDebugSession, true);
    }

    private async stop(): Promise<void> {
        this.onDidChangeIsSharingEvt.dispose();
        await this.trackDebugManager.removeDebugSession(this.session.id);
        if (this.trackDebugManager.isSharing) {
            await this.stopSession();
        }
    }

    private async startSession(): Promise<void> {
        this.trace.verbose(`startSession sessionId:${this.session.id}`);
        const debugServer = config.get<number>(config.Key.debugHostAdapter);
        try {
            this.sessionQueueEvents = [];
            if (debugServer) {
                await this.startSocketSession(debugServer);
            } else {
                await this.startAdapter();
            }
        }
        finally {
            this.sessionQueueEvents = undefined;
        }
    }

    private async stopSession(): Promise<void> {
        this.trace.verbose(`stopSession`);
        if (this.rpcConnection) {
            await this.rpcConnection.sendRequest(DebugAdapterTracker.stopAsyncMethod, []);

            this.rpcConnection.dispose();
            this.rpcConnection = null;
        } 

        if (this.socket) {
            this.trace.verbose(`end socket at port:${this.socket.localPort}`);
            this.socket.end();
            this.socket = null;
        }

        if (this.adapterProcess) {
            this.trace.verbose(`kill process id:${this.adapterProcess.pid}`);
            this.adapterProcess.kill();
            this.adapterProcess = null;
        }
   }

    private async onSharingStateChanged(isSharing: boolean): Promise<void> {
        this.trace.verbose(`onSharingStateChanged isSharing:${isSharing}`);
        if (isSharing) {
            this.startSession();
        } else {
            this.stopSession();
        }
    }

    private async connect(readable: stream.Readable, writable: stream.Writable): Promise<void> {
        this.trace.verbose(`rpc create connection`);
        const rpcConnection = rpc.createMessageConnection(readable, writable);

        // support sendRequestHost Method
        rpcConnection.onRequest(DebugAdapterTracker.sendRequestHostMethod, async (command: string, args: any) => {
            // First handle fireEnterRunMode requests. Execute these requests using the
            // UI so that when a guest clicks 'continue' or 'step' the host's UI goes into the
            // correct mode.
            let vscodeCommand = DebugAdapterTracker.commandToVSCodeCommand.get(command);
            if (vscodeCommand) {
                await vscode.commands.executeCommand(vscodeCommand);
                return;
            }

            // Handle all other non run mode requests
            let timer: NodeJS.Timer;
            try {
                const timeout = new Promise((resolve, reject) => {
                    timer = setTimeout(() => {
                            reject(new Error('customRequest timeout'));
                    }, 2000);
                });

                const response = await Promise.race([
                    this.session.customRequest(command, args),
                    timeout]);
                return  response;
            } catch (err) {
                this.trace.error(`send request failed err:${err}`);
                throw err;
            }
            finally {
                clearTimeout(timer);
            }
        });

        // support fireEnterRunMode Method
        // Ideally we would handle step and continue requests here. The reason provided isn't
        // specific enough though. 'step' will be passed for: 'stepOver', 'stepIn' and 'stepOut'
        // Instead handle these actions in the onRequest method above where the specific request
        // type is provided.
        rpcConnection.onNotification(DebugAdapterTracker.fireEnterRunModeMethod, (reason, threadId) => {

        });

        // support terminate method
        rpcConnection.onNotification(DebugAdapterTracker.terminateMethod, async () => {
            await this.session.customRequest('disconnect', <DebugProtocol.DisconnectArguments> {
                terminateDebuggee: true
            });
        });

        // json rpc start
        rpcConnection.listen();

        // request initializeAsync Method
        await rpcConnection.sendRequest(DebugAdapterTracker.initializeAsyncMethod, [
            this.session.id,
            this.hostPipeName,
            vscode.workspace.workspaceFolders || [this.session.workspaceFolder],
            true,
            this.session.configuration.trace ? true : false,
            this.capabilities,
            this.lastStoppedEvent]);

        this.trace.verbose(`rpc connection established`);
        this.rpcConnection = rpcConnection;
        this.sessionQueueEvents.forEach(e => this.notifyDebugEvent(e.event, e.body));
    }

    private notifyDebugEvent(event: string, body: any): void {
        this.rpcConnection.sendNotification(DebugAdapterTracker.onFireHostDebugEventMethod, [event, body]);
    }

    private fireEnterRunMode(requestMessage: DebugProtocol.Request, eventReason: EventReason): void {
        if (!requestMessage || !requestMessage.arguments) {
            return;
        }

        if (this.rpcConnection) {
            const threadId = requestMessage.arguments.threadId;
            this.rpcConnection.sendNotification(DebugAdapterTracker.onFireEnterRunModeMethod, [eventReason, threadId]);
        }
    }

    private async startSocketSession(port: number): Promise<void> {
        this.trace.verbose(`startSocketSession on port:${port}`);

        const tcpConnect =  new Promise<void>((resolve, reject) => {
            let connected = false;
            this.socket = net.createConnection(port, '127.0.0.1', () => {
                resolve(null);
                connected = true;
            });
            this.socket.on('close', () => {
                if (connected) {
                    vscode.window.showErrorMessage(`Debug adapter connection closed`);
                } else {
                    reject(new Error('connection closed'));
                }
            });
            this.socket.on('error', error => {
                if (connected) {
                    vscode.window.showErrorMessage(`Debug adapter connection error:${error}`);
                } else {
                    reject(error);
                }
            });
        });

        await tcpConnect;
        await this.connect(this.socket, this.socket);
    }

    private async startAdapter(): Promise<void> {
        const dotnetInstallPath = PackageManager.getDotnetInstallPath();
        const env = Object.assign({}, process.env);
        env[`${DOTNET_ROOT_ENVIRONMENT_VARIABLE_NAME}`] = dotnetInstallPath;
        env[`${DOTNET_ROOT_X86_ENVIRONMENT_VARIABLE_NAME}`] = dotnetInstallPath;
        const options: child_process.SpawnOptions = {
            env
        };

        let adapterPath;
        if (os.platform() === OSPlatform.WINDOWS) {
            adapterPath = path.join(DebugAdapterTracker.adapterBinariesPath, ShareDebugManagerBase.debugHostAdapterName + '.exe');
        } else {
            adapterPath = path.join(DebugAdapterTracker.adapterBinariesPath, ShareDebugManagerBase.debugHostAdapterName);
        }
        
        this.trace.verbose(`startAdapter using path:${adapterPath}, options:${options}`);
        activitySource.fire({
            timestamp: new Date(),
            name: `${ActivityType.debug}/start`
        });
        this.adapterProcess = child_process.spawn(adapterPath, ['--launchDebugSessionHostService'], options);
        if (this.adapterProcess && this.adapterProcess.pid) {
            await this.connect(this.adapterProcess.stdout, this.adapterProcess.stdin);
            this.adapterProcess.on('exit', code => {
                if (this.trackDebugManager.isActiveDebugSession(this.session.id) && code) {
                    vscode.window.showErrorMessage(`Debug adapter quit unexpectedly with code:${code}`);
                }
            });
        }
    }
}