import { dependencies } from '../Dependencies';
import { ICommand } from '../abstractions/ICommand';
import { ICommandDecoratorCallback } from '../abstractions/ICommandDecorator';
import { ErrorNotificationCommandDecorator } from './ErrorNotificationCommandDecoratorClass';
import { DecoratorHelper } from '../utils/DecoratorHelper';

export function errorNotificationCommandDecorator(
    title: string,
    telemetryFaultEventName: string,
    isModalError: boolean = false,
    onError?: ICommandDecoratorCallback,
    onNoMessageError?: ICommandDecoratorCallback) {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new ErrorNotificationCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.telemetry(),
            telemetryFaultEventName,
            title,
            isModalError,
            onError,
            onNoMessageError
        ));
}
