import { assert } from './asserts/assert';

/**
 * Function to get a random integer from a defined range.
 */
export const randomInt = (
    max: number,
    min: number = 0
): number => {
    assert(max > min, 'the `max` param should be greater than the `min`');
    assert(!isNaN(min), 'the `min` is not a number');
    assert(!isNaN(max), 'the `max` is not a number');

    const delta = max - min;
    const randomFloat = delta * Math.random();

    return Math.round(min + randomFloat);
};
