import { ServiceInfo, IRpcClient, IChannel } from '@vs/vso-rpc';
import { ConnectedState } from './ConnectedState';

import * as rpc from 'vscode-jsonrpc';

export interface HostConnectionChanged {
    readonly state: ConnectedState;
    readonly duration: number;
}

export interface WorkspaceMetricsUpdated {
    readonly bytesIn: number | undefined;
    readonly bytesOut: number | undefined;
    readonly latency: LatencyMetrics | undefined;
}

export class LatencyMetrics {
    public readonly current: number | undefined;
    public readonly average: number | undefined;
    public readonly min: number | undefined;
    public readonly max: number | undefined;

    constructor(
        latencyCurrent: number | undefined,
        latencyAvg: number | undefined,
        latencyMin: number | undefined,
        latencyMax: number | undefined
    ) {
        this.current = latencyCurrent;
        this.average = latencyAvg;
        this.min = latencyMin;
        this.max = latencyMax;
    }
}

export interface IWorkspaceConnection {
    onHostConnectionChanged: rpc.Event<HostConnectionChanged>;
    onWorkspaceMetricsUpdated: rpc.Event<WorkspaceMetricsUpdated>;

    rpcClient: IRpcClient;
    getServiceProxy<T>(serviceInfo: ServiceInfo<T>, traceName?: string): T;
    openStreamingChannel(
        streamId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<IChannel>;
    disconnect(): Promise<void>;
    dispose(reason?: string): any;
}
