'use strict';

import { Lazy } from './Lazy';
import { sessionStateTracker } from './SessionStateTracker';
import { SessionState } from './SessionTypes';

export interface StateLazyLoader<T> {
    default(): T;
    host?(): T;
    guest?(): T;
}

function isSharedState(state: SessionState) {
    return state === SessionState.SharingInProgress || state === SessionState.Shared;
}

function isJoinedState(state: SessionState) {
    return state === SessionState.JoiningInProgress || state === SessionState.Joined;
}

function isSameState(a: SessionState, b: SessionState) {
    return (isSharedState(a) && isSharedState(b)) || (isJoinedState(a) && isJoinedState(b));
}

export function stateLazyLoad<T>(loader: StateLazyLoader<T>): Lazy<T> {
    let cache: any;
    let cacheState: SessionState;

    return () => {
        if (cache && isSameState(cacheState, sessionStateTracker.State)) {
            return cache;
        }

        if (isSharedState(sessionStateTracker.State)) {
            cache = loader.host ? loader.host() : loader.default();
        } else if (isJoinedState(sessionStateTracker.State)) {
            cache = loader.guest ? loader.guest() : loader.default();
        } else {
            cache = loader.default();
        }
        cacheState = sessionStateTracker.State;
        return cache;
    };
}
