'use strict';

import * as code from 'vscode';
import * as proto from 'vscode-languageserver-protocol';
import * as c2p from 'vscode-languageclient/lib/codeConverter';
import { isString } from 'util';
import { ConverterExtension } from './ConverterExtension';

export function createConverterExtension(converter: c2p.Converter): ConverterExtension {
    function asHover(value: undefined): undefined;
    function asHover(value: null): null;
    function asHover(value: code.Hover): proto.Hover;
    function asHover(value: code.Hover | undefined | null): proto.Hover | null | undefined {
        if (value === void 0 || value === null) {
            return null;
        }
        return {
            range: converter.asRange(value.range),
            contents: value.contents.map((c, index) => asHoverContent(c, index > 0))
        };
    }

    function asHoverContent(item: code.MarkedString, prependNewLine: boolean): proto.MarkedString {
        // A code.MarkedString is a proto.MarkedString | code.MarkdownString. Handle the case where it's a MarkdownString.
        // Also, the vscode-languageclient library converts the protocol messages to code.Hover and if gets an array of markdown strings,
        // it doesn't prepend a newline between making the hover look incorrect. Fixing that up here.
        if (isMarkdownString(item)) {
            return prependNewLine ? `\n${item.value}` : item.value;
        } else if (isString(item)) {
            return prependNewLine ? `\n${item}` : item;
        } else {
            return item;
        }
    }

    function asDefinitionResult(item: code.Definition): proto.Definition;
    function asDefinitionResult(item: undefined | null): undefined;
    function asDefinitionResult(item: code.Definition | undefined | null): proto.Definition | undefined;
    function asDefinitionResult(item: code.Definition | undefined | null): proto.Definition | undefined {
        if (!item) {
            return undefined;
        }
        if (Array.isArray(item)) {
            return item.map((location) => asLocation(location));
        } else {
            return asLocation(item);
        }
    }

    function asDefinitionResultAlternate(item: undefined | null): undefined;
    function asDefinitionResultAlternate(item: code.DefinitionLink[]): proto.Definition | undefined {
        if (!item) {
            return undefined;
        }
        if (Array.isArray(item)) {
            return item.map((location: code.DefinitionLink) => {
                return proto.Location.create(converter.asUri(location.targetUri), converter.asRange(location.targetRange));
            });
        } 
    }

    function asDefinitionLinkResult(item: code.DefinitionLink[]): proto.DefinitionLink[];
    function asDefinitionLinkResult(item: undefined | null): undefined;
    function asDefinitionLinkResult(item: code.DefinitionLink[] | undefined | null): proto.DefinitionLink[] | undefined;
    function asDefinitionLinkResult(item: code.DefinitionLink[] | undefined | null): proto.DefinitionLink[] | undefined {
        if (!item) {
            return undefined;
        }
        return item.map((location) => asLocationLink(location));
    }

    function asLocation(item: code.Location): proto.Location;
    function asLocation(item: undefined | null): undefined;
    function asLocation(item: code.Location | undefined | null): proto.Location | undefined;
    function asLocation(item: code.Location | undefined | null): proto.Location | undefined {
        if (!item) {
            return undefined;
        }
        return  proto.Location.create(converter.asUri(item.uri), converter.asRange(item.range));
    }

    function asLocationLink(item: code.LocationLink): proto.LocationLink;
    function asLocationLink(item: undefined | null): undefined;
    function asLocationLink(item: code.LocationLink | undefined | null): proto.LocationLink | undefined;
    function asLocationLink(item: code.LocationLink | undefined | null): proto.LocationLink | undefined {
        if (!item) {
            return undefined;
        }

        return proto.LocationLink.create(converter.asUri(item.targetUri), converter.asRange(item.targetRange), converter.asRange(item.targetSelectionRange), converter.asRange(item.originSelectionRange));
    }

    function asReferences(values: code.Location[]): proto.Location[];
    function asReferences(values: undefined | null): proto.Location[] | undefined;
    function asReferences(values: code.Location[] | undefined | null): proto.Location[] | undefined;
    function asReferences(values: code.Location[] | undefined | null): proto.Location[] | undefined {
        if (!values) {
            return undefined;
        }
        return values.map(location => asLocation(location));
    }

    function asDocumentHighlights(values: code.DocumentHighlight[]): proto.DocumentHighlight[];
    function asDocumentHighlights(values: undefined | null): undefined;
    function asDocumentHighlights(values: code.DocumentHighlight[] | undefined | null): proto.DocumentHighlight[] | undefined;
    function asDocumentHighlights(values: code.DocumentHighlight[] | undefined | null): proto.DocumentHighlight[] | undefined {
        if (!values) {
            return undefined;
        }
        return values.map(asDocumentHighlight);
    }

    function asDocumentHighlight(item: code.DocumentHighlight): proto.DocumentHighlight {
        let result = proto.DocumentHighlight.create(converter.asRange(item.range));
        if (isNumber(item.kind)) { result.kind = asDocumentHighlightKind(item.kind); }
        return result;
    }

    function asDocumentHighlightKind(item: number): proto.DocumentHighlightKind {
        switch (item) {
            case code.DocumentHighlightKind.Text:
                return proto.DocumentHighlightKind.Text;
            case code.DocumentHighlightKind.Read:
                return proto.DocumentHighlightKind.Read;
            case code.DocumentHighlightKind.Write:
                return proto.DocumentHighlightKind.Write;
            default:
                return proto.DocumentHighlightKind.Text;
        }
    }

    function asSymbolInformations(values: code.SymbolInformation[], uri: code.Uri): proto.SymbolInformation[];
    function asSymbolInformations(values: undefined | null, uri: undefined | null): undefined;
    function asSymbolInformations(values: code.SymbolInformation[] | undefined | null, uri: code.Uri | undefined | null): proto.SymbolInformation[] | undefined;
    function asSymbolInformations(values: code.SymbolInformation[] | undefined | null, uri: code.Uri | undefined | null): proto.SymbolInformation[] | undefined {
        if (!values) {
            return undefined;
        }
        return values.map(symbol => asSymbolInformation(symbol, uri));
    }

    function asSymbolInformation(item: code.SymbolInformation, uri: code.Uri): proto.SymbolInformation {
        // VS Code broke the symbol information API around Insiders 1.25.0, and now requesting symbols returns
        // a list of vs/editor/common/modes.DocumentSymbol instead of code.SymbolInformation. Account for this case for people on newer version of VS Code.
        const range = item.location ? item.location.range : (item as any).range;
        const itemUri = item.location ? item.location.uri : uri;
        // Symbol kind is one based in the protocol and zero based in code.
        let result = proto.SymbolInformation.create(
            item.name, <any> item.kind + 1,
            converter.asRange(range),
            converter.asUri(itemUri));
        if (item.containerName) {
            result.containerName = item.containerName;
        }
        return result;
    }

    function asSignatureHelp(item: undefined | null): undefined;
    function asSignatureHelp(item: code.SignatureHelp): proto.SignatureHelp;
    function asSignatureHelp(item: code.SignatureHelp | undefined | null): proto.SignatureHelp | undefined;
    function asSignatureHelp(item: code.SignatureHelp | undefined | null): proto.SignatureHelp | undefined {
        if (!item) {
            return undefined;
        }
        let activeSignature: number;
        let activeParameter: number;
        let signatures: proto.SignatureInformation[] = [];

        if (isNumber(item.activeSignature)) {
            activeSignature = item.activeSignature;
        } else {
            // activeSignature was optional in the past
            activeSignature = 0;
        }
        if (isNumber(item.activeParameter)) {
            activeParameter = item.activeParameter;
        } else {
            // activeParameter was optional in the past
            activeParameter = 0;
        }
        if (item.signatures) { signatures = asSignatureInformations(item.signatures); }
        return {activeSignature, activeParameter, signatures};
    }

    function asSignatureInformations(items: code.SignatureInformation[]): proto.SignatureInformation[] {
        return items.map(asSignatureInformation);
    }

    function asSignatureInformation(item: code.SignatureInformation): proto.SignatureInformation {
        let result = proto.SignatureInformation.create(item.label);
        if (item.documentation) {
            // Convert all documentation to strings so they are correctly serialized
            result.documentation = (typeof item.documentation === 'string') ? item.documentation : item.documentation.value;
        }
        if (item.parameters) { result.parameters = asParameterInformations(item); }
        return result;
    }

    function asParameterInformations(signature: code.SignatureInformation): proto.ParameterInformation[] {
        return signature.parameters.map((parameter) => asParameterInformation(parameter, signature.label));
    }

    function asParameterInformation(item: code.ParameterInformation, signatureLabel: string): proto.ParameterInformation {
        let result = proto.ParameterInformation.create(item.label);
        if (item.documentation) {
            // Convert all documentation to strings so they are correctly serialized
            result.documentation = (typeof item.documentation === 'string') ? item.documentation : item.documentation.value;
        }
        // The type of item.label is string | [number, number]. Convert [number, number] to a string because the VS client doesn't know how to handle [number, number]
        if (typeof item.label !== 'string') {
            result.label = signatureLabel.substr(item.label[0], item.label[1] - item.label[0]);
        }
        return result;
    }

    function asWorkspaceEdit(item: code.WorkspaceEdit): proto.WorkspaceEdit;
    function asWorkspaceEdit(item: undefined | null): undefined;
    function asWorkspaceEdit(item: code.WorkspaceEdit | undefined | null): proto.WorkspaceEdit | undefined;
    function asWorkspaceEdit(item: code.WorkspaceEdit | undefined | null): proto.WorkspaceEdit | undefined {
        if (!item) {
            return undefined;
        }
        let changes: { [uri: string]: proto.TextEdit[] } = {};

        item.entries().forEach(c => {
            changes[converter.asUri(c['0'])] = c['1'].map(edit => converter.asTextEdit(edit));
        });

        return {changes: changes};
    }

    function asColorInformation(item: code.ColorInformation): proto.ColorInformation {
        let colorInfo: proto.ColorInformation = {
            color: item.color,
            range: converter.asRange(item.range)
        };
        return colorInfo;
    }

    function asColorPresentation(item: code.ColorPresentation): proto.ColorPresentation {
        let colorPresentation: proto.ColorPresentation = {
            label: item.label,
            textEdit: converter.asTextEdit(item.textEdit)
        };
        if (item.additionalTextEdits) {
            colorPresentation.additionalTextEdits = item.additionalTextEdits.map(edit => converter.asTextEdit(edit));
        }
        return colorPresentation;
    }

    function asCodeAction(item: code.CodeAction): proto.CodeAction {
        let codeAction: proto.CodeAction;
        let kind = item.kind ? (item.kind as any).value : undefined;
        let command = item.command;
        if (item.edit) {
            codeAction = proto.CodeAction.create(item.title, asWorkspaceEdit(item.edit), kind);
            // A CodeAction can contain both an edit and a command. If both are supplied, the edit is applied first,
            // then the command is executed.
            if (command) {
                codeAction.command = command;
            }
        } else if (command) {
            codeAction = proto.CodeAction.create(item.title, command, kind);
        } else {
            throw new Error('Invalid CodeAction - neither command nor edit.');
        }
        if (item.diagnostics) {
            codeAction.diagnostics = converter.asDiagnostics(item.diagnostics);
        }
        return codeAction;
    }

    return {
        asHover,
        asDefinitionResult,
        asDefinitionResultAlternate,
        asDefinitionLinkResult,
        asLocation,
        asLocationLink,
        asReferences,
        asDocumentHighlights,
        asSymbolInformations,
        asSignatureHelp,
        asWorkspaceEdit,
        asColorInformation,
        asColorPresentation,
        asCodeAction
    };
}

function isNumber(value: any): value is number {
    return Object.prototype.toString.call(value) === '[object Number]';
}

function isMarkdownString(item: code.MarkedString): item is code.MarkdownString {
    return (<code.MarkdownString>item).value !== undefined;
}
