import { Settings, SettingKeys, userAuthStateTracker, ShareCommandUtilities as ShareCommandUtilitiesCore } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IVsCodeShareInfo, clientFileServiceEnabled } from '../util/WorkspaceEnvironmentUtil';

export class ShareCommandUtilities {
    public static getShareInfo(): IVsCodeShareInfo {
        const shareInfo = ShareCommandUtilitiesCore.buildShareInfo();
        const clientServices: string[] = [];
        if (clientFileServiceEnabled()) {
            clientServices.push(vsls.FileService.name);
        }
        shareInfo[0].clientServices = clientServices;

        return {
            foundUnsupportedSchemes: shareInfo[1].foundUnsupportedSchemes,
            shareInfo: shareInfo[0],
        };
    }

    public static async isSignedInWithAllowedDomain(): Promise<boolean> {
        const allowedDomainsSetting = (Settings.get<string[]>(SettingKeys.allowedDomains) || []);

        if (allowedDomainsSetting.length === 0) {
            return true;
        }

        let emailDomain = userAuthStateTracker.userInfo.emailAddress?.split('@')[1];
        return allowedDomainsSetting.includes(emailDomain);
    }
}
