export function IsFileContentMessage(msg: CoauthoringMessage): boolean {
    switch (msg.messageType) {
        case vsls.MessageType.FileRelease:
        case vsls.MessageType.SaveFile:
        case vsls.MessageType.SelectionChange:
        case vsls.MessageType.TextChange:
        case vsls.MessageType.LayoutScroll:
            return true;

        // These are actually about getting to a state that you have a file open or file close
        // so they're not about manipulating the content of the file.
        case vsls.MessageType.FileOpenAcknowledge:
        case vsls.MessageType.FileOpenRequest:
        // These are obviously not file content related, since they're about joining
        case vsls.MessageType.JoinAcknowledge:
        case vsls.MessageType.JoinRequest:
        default:
            return false;
    }
}

