import { vsls } from '@vs/vsls-contracts';
import { ChatMessage, ChatMessageType, ChatParticipant } from '@vs/vsls-contracts/dist/src/contracts/VSLS';

export class ChatServiceProxy {
    constructor(
        private chatRpcService: vsls.ChatService,
        private updateWebviewCallback: (message: vsls.ChatMessage) => Promise<void>
    ) {
        this.chatRpcService.onMessageReceived((event: vsls.MessageReceivedEventArgs) => this.updateWebviewCallback(event.message));
    }

    public async getMessageHistory(): Promise<ChatMessage[]> {
        return await this.chatRpcService.getMessageHistoryAsync();
    }

    public async getParticipants(): Promise<ChatParticipant[]> {
        return await this.chatRpcService.getParticipantsAsync();
    }

    public async sendMessage(text: string) {
        const chatMessageBody = {
            timestamp: new Date(),
            text
        };

        const message: ChatMessage = {
            type: ChatMessageType.Text,
            body: chatMessageBody
        };

        await this.updateWebviewCallback(message);
        await this.chatRpcService.sendMessageAsync(message);
    }

    public async sendTyping() {
        const message: ChatMessage = {
            type: ChatMessageType.Typing
        };

        await this.chatRpcService.sendMessageAsync(message);
    }
}