
import { traceSource } from '@vs/vscode-command-framework';
import { OutputTraceListener, TraceSource } from '@vs/vso-logging';
import { Settings } from '../Settings'
import { SettingKeys } from '../SettingKeys'

export class TimeTracker {
    private static originTime: number;
    private static timings = new Map<string, number>();
    private static perfLogger: TraceSource;

    public static initialize() {
        const performanceLogging = Settings.get<boolean>(SettingKeys.performanceLogging);
        if (performanceLogging) {
            const title = 'Live Share: Performance';
            this.perfLogger = traceSource.withName(title);
            const perfOutputListener = new OutputTraceListener(title);
            this.perfLogger.addTraceListener(perfOutputListener);
            perfOutputListener.addOutputChannel(true);
        }
        TimeTracker.start('extension:start');
    }

    public static start(marker: string, prefix?: string) {
        const start = TimeTracker.getTime();
        if (!this.originTime) {
            this.originTime = start;
        }

        this.timings.set(marker, start);
        const message = prefix ? `${prefix} ${marker}` : marker;
        this.markTime(message, start);
    }

    public static stop(marker: string, prefix?: string, result?: string) {
        let start = this.timings.get(marker);
        this.timings.delete(marker);
        if (!start) {
            return;
        }

        const end = TimeTracker.getTime();
        const duration = end - start;
        const message = prefix ? `${prefix} ${marker}` : marker;
        const status =  result ? `${result} ` : '';
        this.perfLogger?.verbose(`${message}, Since start: (${end - TimeTracker.originTime}ms) Completed ${status}(${duration}ms)`);
    }

    public static markTime(marker: string, time?: number) {
        const end = time || TimeTracker.getTime();
        this.perfLogger?.verbose(`${marker} starting, Since start: (${end - TimeTracker.originTime}ms)`);
    }

    public static async timeIt(marker: string, action: () => Promise<any>): Promise<any> {
        this.start(marker);
        const result = await action();
        this.stop(marker);
        return result;
    }

    private static getTime() {
        return new Date().getTime();
    }
}