'use strict';

import * as os from 'os';
import { OSPlatform } from '@vs/vso-node-utils';

export type PlatformName = 'Linux' | 'MacOS' | 'Windows';

export function getPlatformName(): PlatformName {
    switch (os.platform()) {
        case OSPlatform.WINDOWS: return 'Windows';
        case OSPlatform.MACOS: return 'MacOS';
        case OSPlatform.LINUX: return 'Linux';
        default: return os.platform() as PlatformName;
    }
}
