import * as vscode from 'vscode';
import * as path from 'path';
import { Settings } from '../Settings';

const pathMonikerPrefix = '~';

let schemeQualifierRegExpInstance: RegExp;
function schemeQualifierRegExp(): RegExp {
    if (!schemeQualifierRegExpInstance) {
        schemeQualifierRegExpInstance = new RegExp(Settings.scheme + ':', 'g');
    }

    return schemeQualifierRegExpInstance;
}

let schemeQualifiedPathRegExpInstance: RegExp;
function schemeQualifiedPathRegExp(): RegExp {
    if (!schemeQualifiedPathRegExpInstance) {
        schemeQualifiedPathRegExpInstance = new RegExp('\"' + Settings.scheme + ':([^"]*)\"', 'g');
    }

    return schemeQualifiedPathRegExpInstance;
}
export class PathUtil {

    /**
     * Given a scheme qualified path like vsls://blah, replace the scheme with the provided replacement.
     */
    public static replaceSchemeWithPath(filePath: string, replacementPath: string): string {
        if (replacementPath.endsWith('/') || replacementPath.endsWith('\\')) {
            replacementPath = replacementPath.substr(0, replacementPath.length - 1);
        }

        return filePath.replace(schemeQualifierRegExp(), replacementPath);
    }

    public static getMonikerFromUri(uri: vscode.Uri): { moniker: string, relativePath: string } {
        if (uri.scheme !== Settings.scheme) {
            throw new Error(`Invalid scheme: '${uri.scheme}', expected: '${Settings.scheme}'`);
        }

        return PathUtil.getMonikerFromRelativePath(uri.path);
    }

    public static getMonikerFromRelativePath(rawPath: string): { moniker: string, relativePath: string } {
        const indexOfSecondSlash = rawPath.indexOf('/', 1);
        if (indexOfSecondSlash < 3 || rawPath[1] !== pathMonikerPrefix) {
            return {
                moniker: '',
                relativePath: rawPath,
            };
        }

        const monikerLength = ((indexOfSecondSlash > 1) ? indexOfSecondSlash : rawPath.length) - 2;
        const rootMoniker = rawPath.substr(2, monikerLength);
        const relativePath = rawPath.substr(2 + monikerLength);

        return {
            moniker: rootMoniker,
            relativePath: relativePath
        };
    }

    public static getRelativePathFromPrefixedPath(prefixedPath: string): string {
        const { moniker, relativePath } = PathUtil.getMonikerFromRelativePath(prefixedPath);
        if (moniker !== '0') {
            return prefixedPath;
        }

        return relativePath;
    }

    public static getPrefixedRoot(moniker: string): string {
        if (moniker === '0' || !moniker) {
            return '/';
        }

        return `/${pathMonikerPrefix}${moniker}`;
    }

    /**
     * Given a line of text with some scheme qualified paths like vsls:\\blah, replace the scheme with the provided replacement.
     */
    public static replaceSchemeWithPathInLine(line: string, replacementPath: string): string {
        // Make sure to forward slashes in paths if the owner is on a Mac.
        let normalizedLine = line.replace(schemeQualifiedPathRegExp(),
                                          (match) => PathUtil.convertToForwardSlashesIfNeeded(match, replacementPath));
        return PathUtil.replaceSchemeWithPath(normalizedLine, replacementPath);
    }

    public static replacePathWithScheme(filePath: string, rootPath: string): string {
        // Chop off a trailing slash.
        if (rootPath.endsWith('/') || rootPath.endsWith('\\')) {
            rootPath = rootPath.substr(0, rootPath.length - 1);
        }

        let ownerRootPathIgnoringSlashesRegExp = new RegExp(rootPath.replace(/[\/\\]+/g, '[\\\/\\\\]+'), 'gi');

        return filePath.replace(ownerRootPathIgnoringSlashesRegExp, Settings.scheme + ':');
    }

    /**
     * Given a path and a root, replace the root with the vsls schema.
     */
    public static replacePathWithSchemeInLine(line: string, rootPath: string): string {
        let lineWithScheme = PathUtil.replacePathWithScheme(line, rootPath);
        // Normalize the rest of the scheme qualified path to have forward slashes.
        return lineWithScheme.replace(schemeQualifiedPathRegExp(),
            (match) => match.replace(/[\/\\]+/g, '/'));
    }

    public static removeRootFromFileSystemPath(filePath: string, rootPath: string): string {
        // Chop off a trailing slash.
        if (rootPath.endsWith('/') || rootPath.endsWith('\\')) {
            rootPath = rootPath.substr(0, rootPath.length - 1);
        }

        let ownerRootPathIgnoringSlashesRegExp = new RegExp(rootPath.replace(/[\/\\]+/g, '[\\\/\\\\]+'), 'gi');
        return filePath.replace(ownerRootPathIgnoringSlashesRegExp, '');
    }

    public static convertToForwardSlashes(filePath: string): string {
        return filePath.replace(/\\\\/g, '/').replace(/\\/g, '/');
    }

    /**
     * Convert to forwardslashes, if the given rootPath is a mac-style path
     */
    private static convertToForwardSlashesIfNeeded(filePath: string, rootPath: string): string {
        if (rootPath[0] === '/') {
            return PathUtil.convertToForwardSlashes(filePath);
        }

        return filePath;
    }

    public static removeLeadingSlash(filePath: string): string {
        if (filePath.startsWith('/')) {
            return filePath.substring(1);
        }
        return filePath;
    }

    public static removeFinalSlash(filePath: string): string {
        if (filePath.endsWith('/')) {
            return filePath.substring(0, filePath.length - 1);
        }
        return filePath;
    }

    public static normalizePath(filePath: string): string {
        return this.removeFinalSlash(this.convertToForwardSlashes(filePath));
    }

    /**
     * Escape backslashes so that the path can be dropped inside a string inside a json blob.
     */
    public static EscapeBackslash(filePath: string): string {
        return filePath.replace(/\\/g, '\\\\');
    }

    /**
     * Path names are PII, so we need to remove all parts preceeding the filename.
     * Makes sure we don't accidentally scrub dates as well.
     */
    public static removePath(filePath: string, replacementString = ''): string {
        return filePath.replace(/([A-Za-z]:)?(\S*[\\\/])+\S*/gi, (match: string, drive: string, directory: string, offset: number, whole: string) => {
            if (/^\d{1,4}\/\d{1,2}\/\d{1,4}$/.test(match)) { // This is a date. No need to scrub.
                return match;
            } else {
                const driveAndDirectoryLength = (drive ? drive.length : 0) + directory.length;
                const fileName = match.substr(driveAndDirectoryLength);
                return replacementString + fileName;
            }
        });
    }

    /**
     * Given the root path of a drive (i.e. '/' on mac or 'C:\' on windows),
     * replace all the path separators with dollar.
     *
     * 'C:' -> 'C$'
     * '/'  -> '$'
     */
    public static getWorkspaceName(rootPath: string): string {
        const name = path.basename(rootPath) || rootPath;
        // TODO: refactor regex to use /[\\\/]/g
        return name.replace(/:[\\|\/]?|\\|\//g, '$');
    }

    /**
     * Obtains the file system path from the primary (e.g. 0-indexed) workspace
     *
     * If no workspace is present, returns undefined.
     */
    public static getPrimaryWorkspaceFileSystemPath(): string | undefined {
        if (!vscode.workspace.workspaceFolders
         || !vscode.workspace.workspaceFolders.length) {
            return undefined;
        }

        return vscode.workspace.workspaceFolders[0].uri.fsPath;
    }
}
