import { Uri } from 'vscode';
import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';
import { ICommand } from '@vs/vscode-command-framework/src/types/ICommand';
import { PlannedSessionTreeViewItem } from '../PlannedSessionsProvider';
import { PlannedSessionsUtils } from '../plannedSessionUtils';

import { 
    SessionAction,
    TelemetryEventNames, 
    TelemetryPropertyNames,
    workspaceSessionInfoTracker,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    authenticationCommandDecorator,
    IAuthenticationDecoratorOptions, 
    IDependencies,
    localize,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

export function builder(dependencies: IDependencies): ICommand<Uri> {
    return new DeletePlannedSessionCommand(
        dependencies.workspaceService(),
    );
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.Create
};

/**
 * Delete planned session `command` that deletes a persistent session
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Delete a Planned Session', TelemetryEventNames.DELETE_PLANNED_SESSION_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.DELETE_PLANNED_SESSION, TelemetryEventNames.DELETE_PLANNED_SESSION_FAULT, 'Delete planned session', 1)
@telemetryStatusCommandDecorator()
@authenticationCommandDecorator(authOptions)
export class DeletePlannedSessionCommand implements ICommand<Uri> {

    constructor(private workspaceService: vsls.WorkspaceService) { }

    public async invoke(item: PlannedSessionTreeViewItem, context: ICommandContext): Promise<Uri> {
        const { cancellationTokenSource } = context;
        const cancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        try {
            let workspaceId: string;
            let workspaceList  = await this.workspaceService.listWorkspacesAsync({onlyManagedWorkspaces: true}); 
            if (item.workspaceInfo === undefined || item.workspaceInfo === null) {
               let workspaceInfo =  await PlannedSessionsUtils.selectPlannedSessionItemFromCommandPaletteAsync(workspaceList, cancellationToken);
               workspaceId = workspaceInfo?.id;  
            } else  {
               workspaceId = item.workspaceInfo.id;
            }
            if (workspaceId) {
                await vscode.window.withProgress(
                    { location: vscode.ProgressLocation.Notification,
                        title: localize('progress.deletingPlannedSession') }, async () => {
                        await this.workspaceService.deleteWorkspaceAsync(workspaceId, cancellationToken);
                    });
                workspaceSessionInfoTracker.isPlannedSessionsChanged = true;
                workspaceSessionInfoTracker.plannedWorkspaceList = workspaceList;
                context.telemetryEvent.addProperty(TelemetryPropertyNames.DELETE_PLANNED_SESSION, true);
            }

        } catch (e) {
            context.trace.error(`Failed to delete Planned Session. ${e.message}`);
            throw new Error(localize('error.CannotDeletePlannedSession'));
        }
        return;
    }
}