import { CancellationToken } from 'vscode';

import { IChannel } from '@vs/vso-rpc';
import { vsls } from '@vs/vsls-contracts';
import { traceSource } from '@vs/vscode-command-framework';
import { IDependencies } from './_new_/IDependencies';
import { EventEmitter } from 'vscode';

type StreamChannelFactoryCallback = (streamMoniker: vsls.RemoteStreamMoniker) => Promise<IChannel>;

 /**
  * Return an implementation of the IChannel interface using rpc calls
  * @param dependencies 
  */
export default function(dependencies: IDependencies): StreamChannelFactoryCallback {
    return async (streamMoniker: vsls.RemoteStreamMoniker) => {
        const streamId = await dependencies.streamManagerService().getStreamAsync(streamMoniker.name, streamMoniker.condition);

        const dataReceivedEmitter = new EventEmitter<Buffer>();
        const closedEmitter = new EventEmitter<void>();
        const trace = traceSource.withName(`IChannel:${streamId}`);

        Promise.resolve().then(async () => {
            while (true) {
                const data = await dependencies.rpcClient().sendRequest<string>(trace, 'stream.readBytes', null, null, streamId, 120);
                if (!data) {
                    closedEmitter.fire();
                    break;
                }
                switch (data[0]) {
                    case ' ':
                        dataReceivedEmitter.fire(Buffer.from(data.substr(1)));
                        break;
                    case 'x':
                        const decoded = Buffer.from(data.substr(1), 'base64').toString('utf8');
                        dataReceivedEmitter.fire(Buffer.from(decoded));
                        break;
                    case 'z':
                    default:
                    // unsupported
                }
            }   
        });

        return {
            onDataReceived: dataReceivedEmitter.event,
            onClosed: closedEmitter.event,
            send: (data: Buffer, cancellation?: CancellationToken) => {
                dependencies.rpcClient().sendRequest<string>(trace, 'stream.writeBytes', null, cancellation, streamId, data);
                return Promise.resolve();
            },
            close: () => {
                return Promise.resolve();
            },
            adjustWindow: (messageLength) => {
            },
            dispose: async () => {
                await dependencies.streamService().disposeStreamAsync(streamId);
            },
        };
    };
}