import { RpcClient } from '@vs/vso-rpc';
import * as signalr_proxy from '@vs/vso-signalr-client-proxy';
import { ILogger } from '@vs/vso-logging';
import * as rpc from 'vscode-jsonrpc';
import { createSshRpcMessageStream } from '@vs/vso-signalr-ssh';
import { HubStreamUtils } from './HubStreamUtils';
import * as constants from './constants';

/**
 * rpc utils that use the signalR hub
 */
export class RpcUtils {
    /**
     * create an rpc client that connects trough a relay service proxy
     * @param relayServiceProxy the relay service proxy
     * @param hubId Hub id to connect
     * @param logger logger instance
     * @param hubDataType optional hub data type to use
     * @param selectHostParticipantCallback optional callback to select the host participant
     */
    public static createRpcClient(
        relayServiceProxy: signalr_proxy.IRelayServiceProxy,
        hubId: string,
        logger: ILogger,
        hubDataType?: string,
        selectHostParticipantCallback?: (
            relayHubProxy: signalr_proxy.IRelayHubProxy
        ) => signalr_proxy.IRelayHubParticipant
    ): RpcClient {
        selectHostParticipantCallback =
            selectHostParticipantCallback || HubStreamUtils.getHostParticipant;
        return new RpcClient(
            {
                create: async (rcpClient) => {
                    await relayServiceProxy.hubProxy.connect();
                    const relayHubProxy = await relayServiceProxy.joinHub(hubId, null, {});
                    const hostParticipantId = selectHostParticipantCallback(relayHubProxy).id;

                    const streamId = hubDataType || constants.DATA_TYPE_LIVESHARE_HUB;
                    // create a data hub proxy for request/response data channel
                    const relayDataHubProxy = signalr_proxy.SequenceRelayDataHubProxy.createForTypeAndParticipant(
                        relayHubProxy,
                        streamId,
                        hostParticipantId
                    );

                    // create a data hub proxy for the notifications
                    const notifyRelayDataHubProxy = signalr_proxy.SequenceRelayDataHubProxy.createForTypeAndParticipant(
                        relayHubProxy,
                        `${streamId}${constants.POST_FIX_NOTIFY}`,
                        hostParticipantId,
                        -1
                    );
                    notifyRelayDataHubProxy.onReceiveData((receivedData) =>
                        relayDataHubProxy.fireReceivedData(receivedData)
                    );

                    // create an rpc message stream that will handle both the request/response and the broadcast notifications
                    const rpcMessageStream = createSshRpcMessageStream(
                        relayHubProxy,
                        streamId,
                        hostParticipantId,
                        true,
                        relayDataHubProxy
                    );
                    const rpcMessageConnection = rpc.createMessageConnection(
                        rpcMessageStream.reader,
                        rpcMessageStream.writer
                    );
                    rpcMessageConnection.listen();
                    await relayHubProxy.sendData(
                        signalr_proxy.SendOption.None,
                        [hostParticipantId],
                        constants.DATA_TYPE_JOINED_READY,
                        null
                    );
                    logger.verbose(
                        `successfully joined rpc session on hubId:${hubId} host id:${hostParticipantId}`
                    );
                    return rpcMessageConnection;
                },
            },
            logger
        );
    }
}
