'use strict';
import * as vscode from 'vscode';
import { Settings } from './Settings';
import { SettingKeys, FeatureSet } from './SettingKeys';
import { TelemetryEventOrigin } from "./telemetry/TelemetryStrings";
import { HandledQuickPickItem, IStatusBarController, IStatusBarQuickPickItemsProvider } from './statusbarInterfaces';
import { READ_ONLY_LABEL } from './constants';

import { vsls } from '@vs/vsls-contracts';
import { CommandId } from './CommandConstants';
import { SessionContext } from './SessionContext';
import { SessionState, SessionStateChangedEventArgs } from './SessionTypes';
import { userAuthStateTracker } from './UserAuthStateTracker';
import { workspaceSessionInfoTracker } from './WorkspaceSessionInfoTracker';
import { sessionStateTracker } from './SessionStateTracker';
import { ICoEditing } from './coediting/ICoEditing';
import { ExtensionUtil } from './utils/ExtensionUtil';
import { localize } from './localize';

enum ShowInStatusBarOption {
    Always = 'always',
    WhileCollaborating = 'whileCollaborating',
    Never = 'never'
}

function shouldStatusBarItemBeVisible(userInitiated = false): boolean {
    switch (Settings.get<string>(SettingKeys.showInStatusBar)) {
        case ShowInStatusBarOption.WhileCollaborating:
            if (SessionContext.isCollaborating || SessionContext.isStartingCollaboration || userInitiated) {
                return true;
            } else {
                return false;
            }
        case ShowInStatusBarOption.Never:
            return userInitiated;
        case ShowInStatusBarOption.Always:
        default:
            return true;
    }
    return true;
}

const getEmojiNameSuffix = (): string => {
    const insiderSuffix = (Settings.isInsidersFeatureSet || Settings.isInternalFeatureSet)
        ? ' 🎖'
        : '';

    let authMethodSuffix = Settings.isVSLSTeamMember ? ' 🔒' : '';

    authMethodSuffix = (Settings.get<boolean>(SettingKeys.nativeAuthFlow))
        ? ' 🔐'
        : authMethodSuffix;

    return `${insiderSuffix}${authMethodSuffix}`;
};

const getNameSuffix = (): string => {
    const featureSet = (<any>FeatureSet)[Settings.get<string>(SettingKeys.featureSet)];

    // isInternal
    if (Settings.get<boolean>(SettingKeys.isInternal)) {
        return ' (Internal User)';
    }
    // Insiders features
    if (featureSet === FeatureSet.insiders) {
        return ' (Insider)';
    }

    return '';
};

/**
 * Defines the appearance and behavior of the Cascade status bar items.
 */
export class StatusBarController implements IStatusBarController {
    private userStatusBarItem: vscode.StatusBarItem;
    private collabStatusBarItem: vscode.StatusBarItem;
    private currentState: StatusBarState;
    private disposed: boolean;
    //Updates to the status bar are not awaited, so it is possible that they can happen out
    //of order. updateStatusBarPromise chains the updates to ensure this doesn't happen
    private updateStatusBarPromise: Promise<void>;

    constructor(
        private commandEnabledCallback: (commandId: string) => boolean,
        private readonly quickPickItemsProvider: IStatusBarQuickPickItemsProvider) {
        this.updateStatusBarPromise = Promise.resolve();

        this.userStatusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 4);
        this.userStatusBarItem.hide();

        this.collabStatusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 3);
        this.collabStatusBarItem.hide();

        this.updateStatusBar(new InitialState());

        SessionContext.onCoeditingClientChanged((coEditingClient) => {
            if (coEditingClient) {
                this.registerClientListeners(coEditingClient);
            }
        });

        sessionStateTracker.onStateChanged(async (e: SessionStateChangedEventArgs) => {
            return await this.onSessionStateChanged(e.newState);
        });

        workspaceSessionInfoTracker.onReadOnlyChanged(async () => {
            if (sessionStateTracker.State === SessionState.Joined || sessionStateTracker.State === SessionState.Shared) {
                await this.onSessionStateChanged(sessionStateTracker.State);
            }
        });
    }

    public refresh() {
        this.updateStatusBar(this.currentState);
    }

    private async onSessionStateChanged(newState: SessionState): Promise<void> {
        let newStatusBarState = this.getStatusBarState(newState);
        this.updateStatusBarPromise = this.updateStatusBarPromise.then(async () => {
            await this.updateStatusBar(newStatusBarState);
        });
    }

    private getStatusBarState(state: SessionState): StatusBarState {
        switch (state) {
            case SessionState.Initializing:
                return new InitialState();
            case SessionState.SigningIn:
                return new SigningInState();
            case SessionState.ExternallySigningIn:
                // same as signed out state
                return new SignedOutState();
            case SessionState.SignedIn:
                return new SignedInState(this.quickPickItemsProvider);
            case SessionState.SharingInProgress:
                if (userAuthStateTracker.IsSignedIn) {
                    return new SharingInProgressState(this.quickPickItemsProvider);
                } else {
                    return new SigningInState();
                }
            case SessionState.Shared:
                return new SharedState(this.quickPickItemsProvider);
            case SessionState.JoiningInProgress:
                if (userAuthStateTracker.IsSignedIn) {
                    return new JoiningState(this.quickPickItemsProvider);
                } else {
                    return new SigningInState();
                }
            case SessionState.Joined:
                return new JoinedState(this.commandEnabledCallback, this.quickPickItemsProvider);
            default:
            case SessionState.SignedOut:
                return new SignedOutState();
        }
    }

    /**
     * Updates the status bar.
     *
     * @param newState the new state of the status bar.
     */
    private async updateStatusBar(newState: StatusBarState): Promise<void> {
        if (!this.disposed) {
            this.currentState = newState;
            if (shouldStatusBarItemBeVisible()) {
                await newState.updateUserStatusBarItem(this.userStatusBarItem);
                await newState.updateCollabStatusBarItem(this.collabStatusBarItem);
            } else {
                this.userStatusBarItem.hide();
                this.collabStatusBarItem.hide();
            }
        }
    }

    /**
     * Registers listeners to certain co-editing events to update the status bar appropriately.
     *
     * @param client The local collaboration client object.
     */
    public registerClientListeners(client: ICoEditing): void {
        client.onCoEditorSwitchedFile(async (sessionId, newFileName) => {
            if (sessionStateTracker.State === SessionState.Joined || sessionStateTracker.State === SessionState.Shared) {
                await (this.currentState as CollaborationState).onCoEditorSwitchedFile(sessionId, newFileName, this.collabStatusBarItem);
            }
        });
        client.onCoEditorsJoined(async (joinerIds) => {
            if (sessionStateTracker.State === SessionState.Joined || sessionStateTracker.State === SessionState.Shared) {
                await (this.currentState as CollaborationState).onCoEditorsJoined(joinerIds, this.collabStatusBarItem);
            }
        });
    }

    /**
     * Triggers an update on the collaboration status item when the session changes.
     *
     * @param e The event data.
     */
    public async onWorkspaceSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs): Promise<void> {
        if (this.currentState instanceof CollaborationState && e.changeType === vsls.WorkspaceSessionChangeType.Unjoined) {
            await this.currentState.onCoEditorLeft(e.sessionNumber, this.collabStatusBarItem);
        }
    }

    /**
     * Called when the extension is unloaded.
     */
    public dispose() {
        this.updateStatusBar(new InitialState());
        this.disposed = true;
    }
}

/**
 * Base class for the status bar states.
 */
export abstract class StatusBarState {
    /**
     * Changes the look and behavior of the left hand status bar item (user status).
     * @param item  the status bar item to change.
     * @param context the status bar context.
     */
    public abstract updateUserStatusBarItem(item: vscode.StatusBarItem): void;

    /**
     * Changes the look and behavior of the right hand status bar item (collaborators status).
     * @param item  the status bar item to change.
     * @param context the status bar context.
     */
    public abstract updateCollabStatusBarItem(item: vscode.StatusBarItem): void;

    /**
     * Utility method for completely hiding a status bar item.
     * @param item the item to hide.
     */
    public hideItem(item: vscode.StatusBarItem) {
        item.hide();
        item.text = undefined;
        item.command = undefined;
        item.tooltip = undefined;
    }
}

/**
 * Defines the status bar behavior when VSCode is started. Nothing is shown in the status bar.
 * This is just the initial state, we transition to a different state as soon as extension activation is completed.
 */
export class InitialState extends StatusBarState {
    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        this.hideItem(currentUserItem);
    }

    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        this.hideItem(collaboratorsItem);
    }
}

/**
 * Defines the status bar behavior when the user is signed out.
 */
export class SignedOutState extends StatusBarState {
    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        const rootFolder = vscode.workspace.workspaceFolders && vscode.workspace.workspaceFolders[0];
        const isVSLSScheme = rootFolder && (rootFolder.uri.scheme === Settings.get<string>(SettingKeys.scheme));
        const isExternallySigningIn = (sessionStateTracker.State === SessionState.ExternallySigningIn);

        // for the share button, when in the joining from browser unauthenticated,
        // we want to show `sign in` button instead of `share`
        if (isExternallySigningIn && isVSLSScheme) {
            currentUserItem.text = `$(person) Sign in`;
            currentUserItem.command = `${Settings.get<string>(SettingKeys.commandPrefix)}.signin`;
            currentUserItem.tooltip = `Sign in to enable ${Settings.get<string>(SettingKeys.name)} collaboration.`;
            currentUserItem.show();

            return;
        }

        currentUserItem.text = `$(live-share) Live Share`;
        currentUserItem.command = `${Settings.get<string>(SettingKeys.commandPrefix)}.start`;
        currentUserItem.tooltip = `Share the workspace with ${Settings.get<string>(SettingKeys.name)}.`;
        currentUserItem.show();
    }

    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        this.hideItem(collaboratorsItem);
    }
}

/**
 * Defines the status bar behavior when the user is signing in but not yet connected.
 */
export class SigningInState extends StatusBarState {
    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        currentUserItem.hide();
    }

    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        this.hideItem(collaboratorsItem);
    }
}

/**
 * Defines the status bar behavior when the user is signed in.
 */
export class SignedInState extends StatusBarState {

    constructor(private readonly quickPickItemsProvider: IStatusBarQuickPickItemsProvider) {
        super();
    }

    public get userInfo(): vsls.UserInfo {
        return userAuthStateTracker.userInfo;
    }

    private get isCurrentUserAnonymous(): boolean {
        return userAuthStateTracker.isCurrentUserAnonymous();
    }

    private get currentUserQuickPickItems(): HandledQuickPickItem[] {
        const quickPickItems =  [
            {
                label: '$(live-share) ' + localize('statusbar.StartSession'),
                description: '',
                detail: localize('statusbar.StartSessionMessage'),
                command: 'liveshare.start',
                enabled: () => true
            },
            {
                label: '$(live-share) ' + localize('statusbar.StartReadOnly'),
                description: '',
                detail: localize('statusbar.StartReadOnlyMessage'),
                command: 'liveshare.startReadOnly',
                enabled: () => true
            },
            {
                label: '$(organization) ' + localize('statusbar.JoinSession'),
                description: '',
                detail: localize('statusbar.JoinSessionMessage'),
                command: 'liveshare.join',
                enabled: () => true
            }
        ];

        if (!Settings.get<boolean>(SettingKeys.nativeAuthFlow)) {
            quickPickItems.push(
                {
                    label: `$(sign-out) Sign Out (${this.userInfo.userName || this.userInfo.emailAddress} via ${this.userInfo.providerName})`,
                    description: '',
                    detail: `Sign out of your ${Settings.get<string>(SettingKeys.name)} account.`,
                    command: `${Settings.get<string>(SettingKeys.commandPrefix)}.signout`,
                    enabled: () => true
                }
            );
        }

        return quickPickItems;
    }

    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        const commandId = '_liveshare.showSignedInUserOptions';
        await ExtensionUtil.tryRegisterCommand('_liveshare.showSignedInUserOptions',
            () => {
                return this.showQuickPick(this.currentUserQuickPickItems, { placeHolder: localize('statusbar.SignedUserPlaceholder') })
                    .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
            });


        // show only non-anonymous users in the status bar
        if (!this.isCurrentUserAnonymous) {
            currentUserItem.text = `$(person) ${this.signedInName}${getEmojiNameSuffix()}`;
            currentUserItem.command = commandId;
            currentUserItem.tooltip = `Signed in to ${Settings.get<string>(SettingKeys.name)}${this.signedInInfo}${getNameSuffix()}`;
            currentUserItem.show();
        } else {
            currentUserItem.hide();
        }
    }

    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        collaboratorsItem.text = `$(live-share) Live Share`;
        collaboratorsItem.command = 'liveshare.start';
        collaboratorsItem.tooltip = localize('statusbar.StartCollaboration');
        collaboratorsItem.show();
    }

    /**
     * Conditionally shows quick pick items based on whether they are enabled or not.
     * Also insert items contributed by other extensions.
     */
    public showQuickPick(items: HandledQuickPickItem[], options?: vscode.QuickPickOptions) {
        const providedItems = this.quickPickItemsProvider.getQuickPickItems(sessionStateTracker.State);

        // Insert extension items just before the last item (which is signout/leave/end).
        // Make a copy before mutating the original items array.
        const insertionIndex = items.length > 1 ? items.length - 1 : 0;
        const allItems = items.slice(0);
        allItems.splice(insertionIndex, 0, ...providedItems);

        // Filter to just enabled items.
        const filteredItems = allItems.filter(item => item.enabled());

        return vscode.window.showQuickPick(filteredItems, options);
    }

    protected get signedInName(): string {
        if (!this.userInfo) {
            return '';
        }

        const { displayName = '', emailAddress, userName } = this.userInfo;

        if (displayName) {
            const firstName = displayName.replace(/ .*$/, '');
            return firstName;
        } else {
            return userName || emailAddress || 'Signed In';
        }
    }

    protected get signedInInfo(): string {
        if (this.userInfo.isAnonymous) {
            return ` as ${Settings.get<string>(SettingKeys.anonymousUserName)} (${READ_ONLY_LABEL})`;
        }

        if (this.userInfo.displayName) {
            return ' as ' + this.userInfo.displayName +
                (this.userInfo.emailAddress ? ' <' + this.userInfo.emailAddress + '>' : ' <' + this.userInfo.userName + '>') +
                ' (' + this.userInfo.providerName + ')';
        } else {
            return ' as ' + (this.userInfo.emailAddress ? this.userInfo.emailAddress : this.userInfo.userName) +
                ' (' + this.userInfo.providerName + ')';
        }
    }
}

/**
 * Defines the status bar behavior when the user has clicked 'share' but the session has not yet started.
 */
export class SharingInProgressState extends SignedInState {
    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        collaboratorsItem.hide();
    }

    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        await super.updateUserStatusBarItem(currentUserItem);

        // No commands are available in this state, apart, maybe "Cancel sharing" when we have it.
        currentUserItem.command = undefined;
    }
}

/**
 * Defines the status bar behavior when the user has clicked 'join' but has not yet joined.
 */
export class JoiningState extends SignedInState {
    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem) {
        collaboratorsItem.hide();
    }

    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        await super.updateUserStatusBarItem(currentUserItem);

        // No commands are available in this state, apart, maybe "Cancel joining" when we have it.
        currentUserItem.command = undefined;
    }
}

/**
 * Defines the behavior of the collaboration status item for both the sharer and the joiners.
 * Other status items are not handled in this class.
 */
export abstract class CollaborationState extends SignedInState {

    public async updateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem): Promise<void> {
        return this.innerUpdateCollabStatusBarItem(collaboratorsItem, /* textOnly */ false);
    }

    public async onCoEditorSwitchedFile(sessionId: number, newFileName: string, collaboratorsItem: vscode.StatusBarItem): Promise<void> {
        // If there is a single remote collaborator, we need to update the tooltip of the collaboration item. If there
        // are more than one collaborator, the quick picks menu is always re-created on the fly, so we don't have to
        // update anything.
        if (SessionContext.collaboratorManager.getCollaboratorCount() === 1) {
            return this.innerUpdateCollabStatusBarItem(collaboratorsItem, /* textOnly */ true);
        }
    }

    public async onCoEditorsJoined(joinerIds: number[], collaboratorsItem: vscode.StatusBarItem): Promise<void> {
        // If we had 1 or more collaborators, the command was already registered, so only update the text.
        const previousCount = SessionContext.collaboratorManager.getCollaboratorCount() - joinerIds.length;
        return this.innerUpdateCollabStatusBarItem(collaboratorsItem, /* textOnly */ previousCount >= 1);
    }

    public onCoEditorLeft(sessionId: number, collaboratorsItem: vscode.StatusBarItem) {
        // Debug sessions will trigger this when debugging ends. Ignore them.
        if (!SessionContext.collaboratorManager.wasCoEditor(sessionId)) {
            return;
        }

        // If we now have 0 collaborators, we need to dispose the command of the status bar item. Otherwise, we just
        // need to update the text to show the new number of collaborators.
        const textOnly = SessionContext.collaboratorManager.getCollaboratorCount() > 0;
        return this.innerUpdateCollabStatusBarItem(collaboratorsItem, textOnly);
    }

    public async innerUpdateCollabStatusBarItem(collaboratorsItem: vscode.StatusBarItem, textOnly: boolean): Promise<void> {
        // Only update our collab status if we're acutally joined, or shared
        // -- other states won't have the collaborator information.
        const state = sessionStateTracker.State;
        if ((state !== SessionState.Joined && state !== SessionState.Shared) || !shouldStatusBarItemBeVisible()) {
            return;
        }

        const collaboratorCount = SessionContext.collaboratorManager.getCollaboratorCount();
        const readonlySuffix = (state === SessionState.Shared && workspaceSessionInfoTracker.isReadOnly)
            ? ` (${READ_ONLY_LABEL})`
            : '';

        collaboratorsItem.text = `$(organization) ${collaboratorCount}${readonlySuffix}`;

        if (collaboratorCount > 0) {
            const collabIds = SessionContext.collaboratorManager.getCollaboratorSessionIds();
            if (collaboratorCount === 1) {
                const collabId = collabIds[0];
                const collabName = SessionContext.collaboratorManager.getDisplayName(collabId);
                const fileName = SessionContext.coeditingClient.lastKnownFileForClient(collabId);
                collaboratorsItem.tooltip = fileName ?
                    `Follow ${collabName} (currently editing ${fileName})` :
                    `${collabName} (not currently editing a shared document)`;
            } else {
                collaboratorsItem.tooltip = 'Follow a participant\'s cursor.';
            }

            if (!textOnly) {
                collaboratorsItem.command = CommandId.listParticipants;
            }
        } else {
            collaboratorsItem.command = null;
            collaboratorsItem.tooltip = 'There are no participants (to invite others, start by clicking on your name in the status bar)';
        }
        collaboratorsItem.show();
    }
}

/**
 * Defines the status bar behavior when the user shared their workspace.
 */
export class SharedState extends CollaborationState {
    constructor(quickPickItemsProvider: IStatusBarQuickPickItemsProvider) {
        super(quickPickItemsProvider);
    }

    private sharingQuickPickItems: HandledQuickPickItem[] = [
        {
            label: '$(clippy) ' + localize('statusbar.InviteOthers'),
            description: '',
            detail: localize('statusbar.InviteOthersMessage'),
            command: 'liveshare.collaboration.link.copy',
            enabled: () => true
        },
        {
            label: '$(megaphone) ' + localize('statusbar.FocusParticipants'),
            description: '',
            detail: localize('statusbar.FocusParticipantsMessage'),
            command: 'liveshare.focusParticipants',
            enabled: () => {
                return SessionContext.collaboratorManager.getCollaboratorCount() > 0;
            }
        },
        {
            label: '$(terminal) ' + `${workspaceSessionInfoTracker.isReadOnly ? localize('statusbar.ShareReadOnlyTerminal') : localize('statusbar.ShareTerminal')}`,
            description: '',
            detail: localize('statusbar.ShareTerminalMessage'),
            command: 'liveshare.shareTerminal',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => true
        },
        {
            label: '$(plug) ' + localize('statusbar.ShareServer'),
            description: '',
            detail: localize('statusbar.ShareServerMessage'),
            command: 'liveshare.shareServer',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => true
        },
        {
            label: '$(plug) ' + localize('statusbar.ShowSharedServers'),
            description: '',
            detail: localize('statusbar.ShowSharedServersMessage'),
            command: 'liveshare.listServers',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => SessionContext.hasServersShared
        },
        {
            label: '$(plug) ' + localize('statusbar.StopSharingServer'),
            description: '',
            detail: localize('statusbar.StopSharingServerMessage'),
            command: 'liveshare.unshareServer',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => SessionContext.hasServersShared
        },
        {
            label: '$(circle-slash) ' + localize('statusbar.StopCollaborationSession'),
            description: '',
            detail: localize('statusbar.StopCollaborationSessionMessage'),
            command: 'liveshare.end',
            enabled: () => true
        },
    ];

    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        const commandId = '_liveshare.showSharedUserOptions';
        await ExtensionUtil.tryRegisterCommand(
            commandId,
            () => {
                return this.showQuickPick(this.sharingQuickPickItems, { placeHolder: localize('statusbar.placeHolder') })
                    .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
            },
            undefined /* this */, false /* isEditorCommand */, true /* force */);

        currentUserItem.text = `$(broadcast) ${this.signedInName}${getEmojiNameSuffix()}`;
        currentUserItem.command = commandId;
        currentUserItem.tooltip = `Sharing via ${Settings.get<string>(SettingKeys.name)}${this.signedInInfo}${getNameSuffix()}`;
        currentUserItem.show();
    }
}

/**
 * Defines the status bar behavior when the guest joined the workspace.
 */
export class JoinedState extends CollaborationState {
    constructor(private commandEnabledCallback: (commandId: string) => boolean,
        quickPickItemsProvider: IStatusBarQuickPickItemsProvider) {
        super(quickPickItemsProvider);
    }

    private collaboratorQuickPickItems: HandledQuickPickItem[] = [
        {
            label: '$(person) ' + localize('generic.SignIn'),
            description: '',
            detail: localize('statusbar.SignInMessage'),
            command: 'liveshare.signInAndReload',
            enabled: () => userAuthStateTracker.isCurrentUserAnonymous()
        },
        {
            label: '$(megaphone) ' + localize('statusbar.FocusParticipants'),
            description: '',
            detail: localize('statusbar.FocusParticipantsMessage'),
            command: 'liveshare.focusParticipants',
            enabled: () => SessionContext.collaboratorManager.getCollaboratorCount() > 0
        },
        {
            label: '$(bug) ' + localize('statusbar.AttachSharedDebuggingSession'),
            description: '',
            detail: localize('statusbar.AttachSharedDebuggingSessionMessage'),
            command: 'liveshare.debug',
            enabled: () => this.commandEnabledCallback('liveshare.debug')
        },
        {
            label: '$(terminal) ' + localize('statusbar.AccessSharedTerminal'),
            description: '',
            detail: localize('statusbar.AccessSharedTerminalMessage'),
            command: 'liveshare.listTerminals',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => SessionContext.hasSharedTerminals
        },
        {
            label: '$(plug) ' + localize('statusbar.AccessSharedServer'),
            description: '',
            detail: localize('statusbar.AccessSharedServerMessage'),
            command: 'liveshare.listServers',
            commandArg: TelemetryEventOrigin.StatusBar,
            enabled: () => SessionContext.hasServersShared
        },
        {
            label: '$(circle-slash) ' + localize('statusbar.LeaveCollaborationSession'),
            description: '',
            detail: localize('statusbar.LeaveCollaborationSessionMessage'),
            command: 'liveshare.leave',
            enabled: () => true
        },
    ];

    public async updateUserStatusBarItem(currentUserItem: vscode.StatusBarItem) {
        const commandId = '_liveshare.showCollaboratorOptions';
        await ExtensionUtil.tryRegisterCommand(commandId,
            () => {
                return this.showQuickPick(this.collaboratorQuickPickItems, { placeHolder: localize('statusbar.placeHolder') })
                    .then(pick => pick && vscode.commands.executeCommand(pick.command, pick.commandArg));
            });

        const readOnlyLabel = (workspaceSessionInfoTracker.isReadOnly)
            ? ` (${READ_ONLY_LABEL})`
            : '';

        const name = this.userInfo.isAnonymous
            ? Settings.get<string>(SettingKeys.anonymousUserName)
            : this.signedInName;

        currentUserItem.text = `$(broadcast) ${name}${readOnlyLabel}${getEmojiNameSuffix()}`;
        currentUserItem.command = commandId;
        currentUserItem.tooltip = `Collaborating via ${Settings.get<string>(SettingKeys.name)}${this.signedInInfo}${getNameSuffix()}`;
        currentUserItem.show();
    }
}
