import { TimedRpcMessageUtils } from '../utils/RpcUtils';
import { ResponseErrorLiteral, Message, ResponseMessage, isResponseMessage, isRequestMessage, RequestMessage, NotificationMessage, isNotificationMessage } from 'vscode-jsonrpc/lib/messages';
import { SessionTelemetry } from './SessionTelemetry';

import {
    TelemetryEvent,
    Fault,
    FaultType
} from '@vs/vso-telemetry';
import { TelemetryPropertyNames, TelemetryEventNames } from './TelemetryStrings';
class MethodSummary {

    public numMessages = 0;
    public firstMessage = 0;
    public maxMessage = 0;
    public minMessage = 0;
    public get averageMessage(): number {
        return (this.numMessages === 0) ? 0 : (this.metricTotal / this.numMessages); 
    }
    public metricTotal = 0;

    public addMessage(metric: number) {
        if (this.numMessages === 0) {
            this.firstMessage = this.maxMessage = this.minMessage = metric;
        } else {
            this.maxMessage = Math.max(metric, this.maxMessage);
            this.minMessage = Math.min(metric, this.minMessage);
        }
        this.numMessages++;
        this.metricTotal += metric;
    }

}

class MethodTimingRequestSummary {

    public latencySummary = new MethodSummary();
    public processingSummary = new MethodSummary();
    public combinedSummary = new MethodSummary();

}

export class RpcTimingTelemetry {

    private static requestSummaries = new Map<string, MethodTimingRequestSummary>();

    public static updateTelemetry(methodName: string, latency: number, processingTime: number, combinedTime: number): void {
        if (!RpcTimingTelemetry.requestSummaries.has(methodName)) {
            RpcTimingTelemetry.requestSummaries.set(methodName, new MethodTimingRequestSummary());
        }
        const requestSummary = RpcTimingTelemetry.requestSummaries.get(methodName)!;
        requestSummary.latencySummary.addMessage(latency);
        requestSummary.processingSummary.addMessage(processingTime);
        requestSummary.combinedSummary.addMessage(combinedTime);
    }

    public static postRequestSummaries(): void {
        for (const [method, methodRequestSummary] of RpcTimingTelemetry.requestSummaries) {
            const rpcSummaryEvent = new TelemetryEvent(RpcTelemetryEventNames.SUMMARIZE_RPC_REQUEST_TIMES);
            rpcSummaryEvent.addProperty(RpcTelemetryPropertyNames.METHOD_NAME, method);
            rpcSummaryEvent.addMeasure(RpcTelemetryPropertyNames.NUMBER_OF_MESSAGES, methodRequestSummary.latencySummary.numMessages);
            rpcSummaryEvent.addProperty(RpcTelemetryPropertyNames.FIRST_MESSAGE, JSON.stringify([methodRequestSummary.latencySummary.firstMessage, methodRequestSummary.processingSummary.firstMessage, methodRequestSummary.combinedSummary.firstMessage]));
            rpcSummaryEvent.addProperty(RpcTelemetryPropertyNames.MAX_MESSAGE, JSON.stringify([methodRequestSummary.latencySummary.maxMessage, methodRequestSummary.processingSummary.maxMessage, methodRequestSummary.combinedSummary.maxMessage]));
            rpcSummaryEvent.addProperty(RpcTelemetryPropertyNames.MIN_MESSAGE, JSON.stringify([methodRequestSummary.latencySummary.minMessage, methodRequestSummary.processingSummary.minMessage, methodRequestSummary.combinedSummary.minMessage]));
            rpcSummaryEvent.addProperty(RpcTelemetryPropertyNames.AVERAGE_MESSAGE, JSON.stringify([methodRequestSummary.latencySummary.averageMessage, methodRequestSummary.processingSummary.averageMessage, methodRequestSummary.combinedSummary.averageMessage]));
            rpcSummaryEvent.send();
        }
        RpcTimingTelemetry.requestSummaries.clear();
    }

}

export class RpcSizeTelemetry {

    private static methodSummaries = new Map<string, Map<string, MethodSummary>>();

    public static updateTelemetry(methodName: string, type: string, size: number): void {
        if (!RpcSizeTelemetry.methodSummaries.has(methodName)) {
            RpcSizeTelemetry.methodSummaries.set(methodName, new Map<string, MethodSummary>());
        }
        const typeSummaries = RpcSizeTelemetry.methodSummaries.get(methodName);
        if (!typeSummaries!.has(type)) {
            typeSummaries!.set(type, new MethodSummary());
        }
        const typeSummary = typeSummaries!.get(type);
        typeSummary!.addMessage(size);
    }

    public static postMethodSummaries(): void {
        for (const [method, typeSummaries] of RpcSizeTelemetry.methodSummaries) {
            for (const [type, typeSummary] of typeSummaries) {
                const summaryEvent = new TelemetryEvent(RpcTelemetryEventNames.SUMMARIZE_RPC_METHOD_SIZES);
                summaryEvent.addProperty(RpcTelemetryPropertyNames.METHOD_NAME, method);
                summaryEvent.addProperty(RpcTelemetryPropertyNames.METHOD_TYPE, type);
                summaryEvent.addMeasure(RpcTelemetryPropertyNames.NUMBER_OF_MESSAGES, typeSummary.numMessages);
                summaryEvent.addMeasure(RpcTelemetryPropertyNames.FIRST_MESSAGE, typeSummary.firstMessage);
                summaryEvent.addMeasure(RpcTelemetryPropertyNames.MAX_MESSAGE, typeSummary.maxMessage);
                summaryEvent.addMeasure(RpcTelemetryPropertyNames.MIN_MESSAGE, typeSummary.minMessage);
                summaryEvent.addMeasure(RpcTelemetryPropertyNames.AVERAGE_MESSAGE, typeSummary.averageMessage);
                summaryEvent.send();
            }
        }
        RpcSizeTelemetry.methodSummaries.clear();
    }

}

export interface MethodNameProvider {

    serviceNames: string[];

    getMethod(msg: NotificationMessage | RequestMessage): string | undefined;

}

export class LanguageServiceRpcMethodNameProvider implements MethodNameProvider {

    public serviceNames = ['languageServerProvider-any', 'languageServerProvider-Roslyn'];

    public getMethod(msg: NotificationMessage | RequestMessage): string | undefined {
        if (msg.params && ((msg.params.length > 0 && msg.params[0].method) || (msg.params.length > 1 && msg.params[1].method))) {
            const serviceName = msg.method.split('.')[0];
            const lspMethod = msg.params[0].method
                              ? msg.params[0].method // Response
                              : msg.params[1].method; // Request
            return `${serviceName}.${lspMethod}`;
        }
        return undefined;
    }

}

class RequestMessageCacheRecord {

    public requestMessage: RequestMessage;
    public constructedTime: number;

    public constructor(requestMessage: RequestMessage) {
        this.requestMessage = requestMessage;
        this.constructedTime = (new Date()).getTime();
    }

}

class TelemetryRpcFilterBase {

    // Map from message ids to request messages
    protected requestMessages: Map<number | string, RequestMessageCacheRecord> = new Map<number | string, RequestMessageCacheRecord>();

    protected methodNameProviders = new Map<string, MethodNameProvider>();

    public constructor(...methodNameProviders: MethodNameProvider[]) {
        for (const mnp of methodNameProviders) {
            this.addMethodNameProvider(mnp);
        }
    }

    public addMethodNameProvider(provider: MethodNameProvider): void {
        for (const serviceName of provider.serviceNames) {
            this.methodNameProviders.set(serviceName, provider);
        }
    }

    protected cacheRequestMessage(msg: Message) {
        if (isRequestMessage(msg)) {
            const requestMsg = msg as RequestMessage;
            this.requestMessages.set(requestMsg.id, new RequestMessageCacheRecord(requestMsg));
        }
    }

    protected getModifiedMethodName(methodName: string, message: NotificationMessage | RequestMessage): string {
        const serviceName = methodName.split('.')[0];
        const methodNameProvider = this.methodNameProviders.get(serviceName);
        if (methodNameProvider) {
            const modifiedMethodName = methodNameProvider.getMethod(message);
            if (modifiedMethodName) {
                return modifiedMethodName;
            }
        }
        return methodName;
    }

    protected getRequestMessage(msg: ResponseMessage | number): { requestMsg: RequestMessage, methodName: string } | undefined {
        const msgId = (typeof msg === 'number')
                ? msg
                : msg.id;
        if ((msgId !== null) && (this.requestMessages.has(msgId!))) {
            const requestMsg = this.requestMessages.get(msgId!)!.requestMessage;
            this.requestMessages.delete(msgId!);
            if (requestMsg.method) {
                const methodName = this.getModifiedMethodName(requestMsg.method, requestMsg);
                return {
                    requestMsg,
                    methodName
                };
            }
        }
        return undefined;
    }

}

export class TelemetryRpcErrorFilter extends TelemetryRpcFilterBase {

    public constructor(...methodNameProviders: MethodNameProvider[]) {
        super(...methodNameProviders);
        SessionTelemetry.sessionEvent.on(SessionTelemetry.sessionEndEventName, () => {
            this.reportExpiredRequests();
            this.requestMessages.clear();
        });
    }

    public readWriteFilter(msg: Message): any {
        this.cacheRequestMessage(msg);
        this.checkForError(msg);
        this.checkForCancellation(msg);
        return msg;
    }

    private checkForError(msg: Message): void {
        if (isResponseMessage(msg)) {
            const responseMsg = msg as ResponseMessage;
            const requestMessage = this.getRequestMessage(msg);
            if (responseMsg.error) {
                const methodName = requestMessage ? requestMessage.methodName  : '';
                TelemetryRpcErrorFilter.reportRpcError(methodName, msg.error!);
            }
        }
    }

    private checkForCancellation(msg: Message): void {
        if (isNotificationMessage(msg) && msg.method === `$/cancelRequest`) {
            const requestId = (msg as NotificationMessage).params.id;
            const requestMessage = this.getRequestMessage(requestId);
            TelemetryRpcErrorFilter.reportCancelledRequest(requestMessage ? requestMessage.methodName : 'NA');
        }
    }

    private static reportRpcError(methodName: string, error: ResponseErrorLiteral<any>) {
        const rpcErrorEvent = new Fault(RpcTelemetryEventNames.RECEIVE_RPC_FAULT, FaultType.Error, error.message);
        rpcErrorEvent.addProperty(RpcTelemetryPropertyNames.METHOD_NAME, methodName);
        rpcErrorEvent.addProperty(RpcTelemetryPropertyNames.ERROR_CODE, error.code);
        rpcErrorEvent.addProperty(RpcTelemetryPropertyNames.ERROR_DATA, JSON.stringify(error.data));
        rpcErrorEvent.sendAsError([RpcTelemetryPropertyNames.ERROR_DATA]);
    }

    private static reportCancelledRequest(methodName: string) {
        const cancelEvent = new TelemetryEvent(RpcTelemetryEventNames.CANCEL_RPC_REQUEST);
        cancelEvent.addProperty(RpcTelemetryPropertyNames.METHOD_NAME, methodName);
        cancelEvent.send();
    }

    private getExpiredRequests(): Map<string, number> {
        const currentTime = (new Date()).getTime();
        const expiredRequests = new Map<string, number>();
        for (let [, record] of this.requestMessages) {
            if ((currentTime - record.constructedTime) > (60 * 1000)) {
                const methodName = this.getModifiedMethodName(record.requestMessage.method, record.requestMessage);
                const currentCount = expiredRequests.get(methodName) || 0;
                expiredRequests.set(methodName, currentCount! + 1);
            }
        }
        return expiredRequests;
    }

    private reportExpiredRequests() {
        const expiredRequests = this.getExpiredRequests();
        for (const [method, numExpiredRequests] of expiredRequests) {
            const expiredRequestsEvent = new TelemetryEvent(RpcTelemetryEventNames.EXPIRE_RPC_REQUESTS);
            expiredRequestsEvent.addProperty(RpcTelemetryPropertyNames.METHOD_NAME, method);
            expiredRequestsEvent.addMeasure(RpcTelemetryPropertyNames.NUMBER_OF_MESSAGES, numExpiredRequests);
            expiredRequestsEvent.send();
        }
    }

} 

export class TelemetryRpcFilter extends TelemetryRpcFilterBase {

    public constructor(...methodNameProviders: MethodNameProvider[]) {
        super(...methodNameProviders);
        SessionTelemetry.sessionEvent.on(SessionTelemetry.sessionEndEventName, () => {
            RpcTimingTelemetry.postRequestSummaries();
            RpcSizeTelemetry.postMethodSummaries();
        });
    }

    public writeFilter(msg: Message): Message {
        this.cacheRequestMessage(msg);
        return msg;
    }

    public readFilter(msg: Message): Message {
        if (isRequestMessage(msg) || isNotificationMessage(msg)) {
            const methodName = this.getModifiedMethodName(msg.method, msg);
            if (typeof (msg as any).size !== 'undefined') {
                RpcSizeTelemetry.updateTelemetry(methodName, isRequestMessage(msg) ? 'request' : 'notification', (msg as any).size);
            }
        } else if (isResponseMessage(msg) && (typeof msg.id !== 'undefined') && this.requestMessages.has(msg.id!)) {
            const requestMessage = this.getRequestMessage(msg);
            const methodName = requestMessage ? requestMessage.methodName : '';
            if (typeof (msg as any).size !== 'undefined') {
                RpcSizeTelemetry.updateTelemetry(methodName, 'response', (msg as any).size);
            }
            if (typeof (msg as any).times !== 'undefined') {
                RpcTimingTelemetry.updateTelemetry(methodName, TimedRpcMessageUtils.getLatency((msg as any).times), TimedRpcMessageUtils.getProcessingTime((msg as any).times), TimedRpcMessageUtils.getTotalTime((msg as any).times));
            }
        }
        return msg;
    }

}

export class RpcTelemetryEventNames {
    public static readonly SUMMARIZE_RPC_REQUEST_TIMES = 'summarize-rpcrequesttimes';
    public static readonly SUMMARIZE_RPC_METHOD_SIZES = 'summarize-rpcmethodsizes';
    public static readonly RECEIVE_RPC_FAULT = TelemetryEventNames.FAULT_PREFIX + 'receive-rpc-fault';
    public static readonly EXPIRE_RPC_REQUESTS = 'expire-rpcrequests';
    public static readonly CANCEL_RPC_REQUEST = 'cancel-rpcrequest';
}

export class RpcTelemetryPropertyNames {
    public static readonly METHOD_NAME = TelemetryPropertyNames.FEATURE_NAME + 'MethodName';
    public static readonly METHOD_TYPE = TelemetryPropertyNames.FEATURE_NAME + 'MethodType';
    public static readonly NUMBER_OF_MESSAGES = TelemetryPropertyNames.FEATURE_NAME + 'NumberOfMessages';
    public static readonly FIRST_MESSAGE = TelemetryPropertyNames.FEATURE_NAME + 'FirstMessage';
    public static readonly MAX_MESSAGE = TelemetryPropertyNames.FEATURE_NAME + 'MaxMessage';
    public static readonly MIN_MESSAGE = TelemetryPropertyNames.FEATURE_NAME + 'MinMessage';
    public static readonly AVERAGE_MESSAGE = TelemetryPropertyNames.FEATURE_NAME + 'AverageMessage';
    public static readonly ERROR_CODE = TelemetryPropertyNames.FEATURE_NAME + 'ErrorCode';
    public static readonly ERROR_DATA = TelemetryPropertyNames.FEATURE_NAME + 'ErrorData';
}