import { assert } from './assert';

import { TConstructable } from '../../interfaces/TConstructable';

type TAssertionType = <T, K extends TConstructable<any>>(val: T, classObject: K,  errorMessage: string | Error) => asserts val is InstanceType<K>;

/**
 * Assert the `val` is instance of `classObject`.
 */
export const assertInstance: TAssertionType = <T, K extends TConstructable<any>>(
    val: T,
    classObject: K,
    errorMessage: string | Error
): asserts val is InstanceType<K> => {
    return assert(
        val instanceof classObject,
        errorMessage,
    );
};
