import { CancellationTokenSource } from 'vscode-jsonrpc';
import { CancellationError } from '../errors/CancellationError';
import { IDisposable } from '../interfaces';

export const timeoutPromise = async <T>(
    promise: Promise<T>,
    timeout: number,
    error?: Error,
    promiseCancellationSource?: CancellationTokenSource,
): Promise<T> => {
    let timeoutReference: ReturnType<typeof setTimeout> | undefined;

    let ctsDisposable: IDisposable | undefined;

    const dispose = () => {
        ctsDisposable?.dispose();
        clearTimeout(timeoutReference as ReturnType<typeof setTimeout>);
    };

    const result = await Promise.race<Promise<T>>([
        /**
         * Original promise.
         */
        promise.finally(() => {
            dispose();
        }),
        /**
         * Timeout promise.
         */
        new Promise((_, reject) => {
            ctsDisposable = promiseCancellationSource?.token.onCancellationRequested(() => {
                dispose();
                reject(new CancellationError());
            });
            timeoutReference = setTimeout(() => {
                dispose();

                const rejectionError = error ?? new Error(`Promise rejected after ${timeout}ms.`);
                reject(rejectionError);
            }, timeout);
        }),
    ]);

    return result;
};
