import {
    GlobPatternTraceFilter,
    VerbosityTraceFilter,
    OutputTraceListener,
    MemoryTraceListener,
    TraceListener,
    IFilters,
    LogLevel,
    TraceFilters,
    ITraceFilter,
    LoggerSettings,
} from '@vs/vso-logging';
import { traceSource } from '../tracing/traceSource';
import { ILoggingOptions } from '../types/IVSLSCommandsAPIOptions';
import { createLogFileListener } from '@vscode-abstractions/logFile';

export class LoggingUtil {
    private outputTraceListener: OutputTraceListener;
    private memoryTraceListener: MemoryTraceListener;
    private logFileTraceListener: TraceListener | undefined;

    constructor(private displayName: string, private loggingOptions: ILoggingOptions = {}) {
        const outputChannelName = this.loggingOptions.outputChannelName || this.displayName;
        this.outputTraceListener = new OutputTraceListener(
            outputChannelName,
            this.loggingOptions.outputChannelTimestamp,
        );
        this.memoryTraceListener = new MemoryTraceListener(loggingOptions.logMaxSize);
    }

    public getLogs(logLevel?: LogLevel) {
        return this.memoryTraceListener.getLogs(logLevel);
    }

    public async initLogging() {
        traceSource.addTraceListener(this.memoryTraceListener);
        traceSource.addTraceListener(this.outputTraceListener);
        if (this.loggingOptions.diagnosticsLogging) {
            this.setDiagnosticLogging(
                this.loggingOptions.diagnosticsLogging.enable,
                this.loggingOptions.diagnosticsLogging.focus,
            );
        }

        if (this.loggingOptions.logFileEnabled) {
            this.logFileTraceListener = await createLogFileListener();
            if (this.logFileTraceListener) {
                traceSource.addTraceListener(this.logFileTraceListener);
            }
        }

        this.setLoggingFilters(
            this.loggingOptions.logLevel,
            this.loggingOptions.filters,
            this.loggingOptions.traceFilter,
        );

        if (this.loggingOptions.obfuscateProperties) {
            // copy obfuscation properties
            Object.entries(this.loggingOptions.obfuscateProperties).forEach((kvp) => {
                LoggerSettings.obfuscateProperties[kvp[0]] = kvp[1];
            });
        }
    }

    private setLoggingFilters(
        logLevel?: string,
        filters: IFilters = {},
        traceFilter?: ITraceFilter,
    ) {
        const traceFilters = new TraceFilters([
            new VerbosityTraceFilter(
                logLevel ? LogLevel[logLevel as keyof typeof LogLevel] : undefined,
            ),
            new GlobPatternTraceFilter(filters),
        ]);
        if (traceFilter) {
            traceFilters.filters.push(traceFilter);
        }

        this.outputTraceListener.filter = traceFilters;
        if (this.logFileTraceListener) {
            this.logFileTraceListener.filter = traceFilters;
        }
    }

    public async setDiagnosticLogging(enableDiagnosticsLogging: boolean = true, focus = false) {
        if (enableDiagnosticsLogging) {
            this.outputTraceListener.addOutputChannel(focus);
        } else {
            this.outputTraceListener.removeOutputChannel();
        }
    }
}
