import * as ssh from '@vs/vs-ssh';
import * as rpc from 'vscode-jsonrpc';
import { ILogger } from '@vs/vso-logging';
import { RpcClient, IRpcClient, IRpcMessageConnectionFactory } from '@vs/vso-rpc';

export interface IMultiChannelRpcClient extends IRpcClient {
    readonly rpcConnection: rpc.MessageConnection;
    readonly multiChannelStream: ssh.MultiChannelStream;
}

export async function createMultiChannelRpcClient(
    transportStream: ssh.Stream,
    logger: ILogger,
    listen: boolean = true
) {
    const multiChannelStream = new ssh.MultiChannelStream(transportStream);
    const sshChannel = await multiChannelStream.openChannel();

    const rcpClient = new MultiChannelRpcClient(multiChannelStream, sshChannel, logger);

    rcpClient.addToDisposables(multiChannelStream, {
        dispose: () => transportStream.close(),
    });
    if (listen) {
        rcpClient.rpcConnection.listen();
    }

    return rcpClient;
}

class MultiChannelRpcClient extends RpcClient implements IMultiChannelRpcClient {
    constructor(
        public readonly multiChannelStream: ssh.MultiChannelStream,
        sshChannel: ssh.SshChannel,
        logger: ILogger
    ) {
        super({} as IRpcMessageConnectionFactory, logger);
        const rpcStream = new ssh.SshRpcMessageStream(sshChannel);
        this.setConnection(this.createRpcConnection(rpcStream, logger));
    }

    public get rpcConnection() {
        return this.connection!;
    }
}
