import { initializePerformanceInstance, Performance } from '@vs/vscs-performance';
import { ILogger, TraceSource } from '@vs/vso-logging';

import { TConnectionClass } from '../../interfaces/TConnectionClass';
import { ConnectionMock } from '../connection/ConnectionMock';
import { ConnectionHubMock } from '../connectionHub/ConnectionHubMock';
import { IConnectionMock } from '../connectionHub/IConnectionMock';
// import { IConnectionMock } from '../connectionHub/IConnectionMock';
// import { IConnectionMockOptions } from '../interfaces/IConnectionMockOptions';

export const testTrace = new TraceSource('test-trace');
export const performance = initializePerformanceInstance('test:start');

export type TConnectionHubMockOptions = [
    ILogger,
    Performance,
    TConnectionClass<IConnectionMock<any>>,
    Array<ConnectionHubMock<any>> | undefined
];

interface IOptions {
    trace?: ILogger;
    childHubs?: Array<ConnectionHubMock<any>>;
}

/**
 * Mock helper to generate default `ConnectionHubMock` options.
 * Pass real trace if you want to see logs in the console.
 */
export const getConnectionHubMockOptions = (options: IOptions = {}): TConnectionHubMockOptions => {
    const { trace = testTrace, childHubs } = options;

    return [
        trace,
        performance,
        ConnectionMock as TConnectionClass<IConnectionMock<any>>,
        childHubs,
    ];
};
