import * as vscode from 'vscode';
import { JoinDebugSession } from './JoinDebugSession';
import { 
	WorkspaceServices,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { 
    ServiceInfo,
} from '@vs/vso-rpc';
import * as vslsDebug from './DebugSessionHostService';
import { TraceSource } from '@vs/vso-logging';

export class JoinDebugAdapterDescriptorFactory implements vscode.DebugAdapterDescriptorFactory {

	constructor(
		private workspaceServices:WorkspaceServices,
		private rpcFactory: <T>(serviceInfo: ServiceInfo<T>, traceName: string) => T,
		private trace: TraceSource) {
	}

	createDebugAdapterDescriptor(_session: vscode.DebugSession, _executable: vscode.DebugAdapterExecutable | undefined): vscode.ProviderResult<vscode.DebugAdapterDescriptor> {
		const debugSession = _session.configuration.debugSession as vsls.DebugSession;
		this.trace.verbose(`creating JoinDebugSession for id:${_session.id} sessionId:${debugSession.sessionId}`);

		const debugSessionHostName = `DebugSessionHostService-${debugSession.sessionId}`;

		const serviceInfo: ServiceInfo<vslsDebug.DebugSessionHostService> = {
			name: debugSessionHostName,
			methods: vslsDebug.DebugSessionHostService.methods,
			events: vslsDebug.DebugSessionHostService.events
		};

		const debugSessionHostService = this.rpcFactory(serviceInfo, serviceInfo.name);
		const joinDebugSession = new JoinDebugSession(debugSessionHostService, debugSession, this.trace.withName(`JoinDebugSession-${debugSession.sessionId}`));
		const disposable = this.workspaceServices.onServiceRemoved(srvc => {
			if (srvc === debugSessionHostName) {
				this.trace.verbose(`force terminate sessionId:${debugSession.sessionId}`);
				joinDebugSession.forceTerminate();
				disposable.dispose();
			}
		});
		
		// Note: this will only work on insiders build
		return <any> new vscode.DebugAdapterInlineImplementation(joinDebugSession);

		// // TODO@AW: we need some extension API for connecting a DA implementation with a vscode.DebugAdapterDescriptor
		// const descriptor = new vscode.DebugAdapterExecutable('dummy');
		// const a = <any>descriptor;
		// a['implementation'] = joinDebugSession;
		// return descriptor;
	}
}