import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import * as config from '../presenceConfig';

import {
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator,
    ContactManagerEvents,
    localize
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { ContactManager } from '../ContactManager';
import { ContactsProviderViewlet } from '../ContactsProviderViewlet';

export function builder(): ICommand<void> {
    return new SignInPresenceCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.SIGN_IN_PRESENCE, TelemetryEventNames.SIGN_IN_PRESENCE_FAULT, 'SignInPresence', 1)
class SignInPresenceCommand implements ICommand<void> {

    public async invoke(options: any, context: ICommandContext): Promise<void> {
        const signIn = localize('generic.SignIn');
        const pick = await vscode.window.showWarningMessage(localize('presence.signInMessage'), { modal: true }, signIn);

        if (pick !== signIn) {
            return;
        }
        
        const supportedPresenceStatus = ContactManager.supportedPresenceStatus.slice(0);
        supportedPresenceStatus.push(contactProtocol.PresenceStatus.Offline);

        const items = supportedPresenceStatus.map(s => (s === contactProtocol.PresenceStatus.Offline ? '$(check) ' : '') + ContactsProviderViewlet.toPresenceStatusName(s));
        const selection: string = await vscode.window.showQuickPick(items, { placeHolder: 'Specify your status:' });
        if (!selection || selection === items[items.length - 1] ) {
            return;
        }
    
        const onSignedStateChanged = async (status: contactProtocol.SignedStatus) => {
            if (status === contactProtocol.SignedStatus.SignedIn || status === contactProtocol.SignedStatus.SignedOut) {
                ContactManager.removeListener(ContactManagerEvents.SignedStateChanged, onSignedStateChanged);
            }
            if (status === contactProtocol.SignedStatus.SignedIn) {
                const newStatus = supportedPresenceStatus[items.indexOf(selection)];
                await ContactManager.publishPresence(<contactProtocol.PresenceStatus>newStatus);
            }
       };

        ContactManager.addListener(ContactManagerEvents.SignedStateChanged, onSignedStateChanged);
        // enable liveshare presence
        await config.setLivesharePresenceEnabled(true);
        await ContactManager.signIn();     
    }
}