import * as signalr_proxy from '@vs/vso-signalr-client-proxy';
import { ILogger } from '@vs/vso-logging';
import * as rpc from 'vscode-jsonrpc';
import * as ssh from '@vs/vs-ssh';
import { HubStream } from '@vs/vso-signalr-ssh';
import { SshRpcServerProvider } from '@vs/vso-rpc-ssh';

import { RelayHubProxyServer } from './RelayHubProxyServer';
import * as constants from './constants';
import { Signal } from '@vs/vscs-utils';

export function createRelayHubProxyServerProvider(
    relayServiceProxy: signalr_proxy.IRelayServiceProxy,
    hubId: string,
    logger: ILogger,
    hubDataType?: string
): SshRpcServerProvider {
    const onSshStreamJoinedEmitter = new rpc.Emitter<ssh.Stream>();
    const relayHubProxyServer = new RelayHubProxyServer(relayServiceProxy, hubId, logger);
    const onParticipantJoinedDisposable = relayHubProxyServer.onParticipantJoined((e) => {
        const ssStream = new HubStream(
            e.relayHubProxy,
            hubDataType || constants.DATA_TYPE_LIVESHARE_HUB,
            e.participant.id
        );
        onSshStreamJoinedEmitter.fire(ssStream);
    });

    let readySignal = new Signal<void>();

    const provider: SshRpcServerProvider = {
        name: 'signalR',
        ready: readySignal.promise,
        onRpcStreamJoined: onSshStreamJoinedEmitter.event,
        acceptConnections: (cancellationToken?: rpc.CancellationToken) =>
            relayHubProxyServer.acceptConnections(cancellationToken),
        dispose: async () => {
            onParticipantJoinedDisposable.dispose();
            onHubJoinedDisposable.dispose();
            if (relayServiceProxy.hubProxy.isConnected) {
                logger.info(`deleting hub:${hubId}`);
                try {
                    await relayServiceProxy.deleteHub(hubId);
                } catch (err) {
                    logger.error(`Failed to delete hub id:${hubId}`, err);
                }
            }
        },
    };

    const onHubJoinedDisposable = relayHubProxyServer.onHubJoined((e) => {
        if (e) {
            readySignal.resolve();
        } else {
            readySignal = new Signal<void>();
            (<any>provider).ready = readySignal.promise;
        }
    });

    return provider;
}
