import { CommandErrorCode } from './CommandErrorCode';
import { TelemetryResult } from '@vs/vso-telemetry';

export class CommandError extends Error {
    public readonly code?: CommandErrorCode;
    public readonly telemetryResult: TelemetryResult;
    public userMessage?: string;
    public isSuppressUserNotification = false;

    constructor(
        parameters: {
            message?: string;
            code?: CommandErrorCode;
            userMessage?: string;
            telemetryResult?: TelemetryResult;
        } = {},
    ) {
        super(parameters.message);
        this.code = parameters.code;
        this.userMessage = parameters.userMessage;
        this.telemetryResult = parameters.telemetryResult || TelemetryResult.Failure;
    }

    public withUserMessage(userMessage: string): CommandError {
        this.userMessage = userMessage;
        return this;
    }

    public withSuppressUserNotification(suppress: boolean) {
        this.isSuppressUserNotification = suppress;
        return this;
    }
}
