import * as vscode from 'vscode';
import { ContactCommandUtilities } from './ContactCommandUtilities';

import {
    IContactModel,
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator,
    localize
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { ContactManager } from '../ContactManager';
import { defaultCompareContacts } from '../defaultCompareContacts';
import { ContactsProviderViewlet } from '../ContactsProviderViewlet';

export function builder(): ICommand<boolean> {
    return new InviteSearchContactsCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.INVITE_SEARCH_CONTACTS, TelemetryEventNames.INVITE_SEARCH_CONTACTS_FAULT, 'InviteSearchContactsCommand', 1)
class InviteSearchContactsCommand implements ICommand<boolean> {

    public async invoke(): Promise<boolean> {

        const disposables: vscode.Disposable[] = [];
        try {
            return await new Promise<boolean>((resolve, reject) => {
                const input = vscode.window.createQuickPick<ContactItem>();
                input.placeholder = localize('searchContacts.placeholder');
                let cts: vscode.CancellationTokenSource = null;
                disposables.push(
                    input.onDidChangeValue(value => {
                        if (cts) {
                            cts.cancel();
                        }
                        if (!value) {
                            input.items = [];
                            return;
                        }
                        input.busy = true;

                        cts = new vscode.CancellationTokenSource();
                        ContactManager.searchContacts(
                            [<contactProtocol.SearchContactProperty> {
                                property: contactProtocol.ContactProperty.DisplayName,
                                expression: `^${value}`,
                                options: 1
                            }], 100, cts.token).then(results => {
                                input.items = results.sort(defaultCompareContacts).map(c => new ContactItem(c));
                                input.busy = false;
                            });
                    }),
                    input.onDidChangeSelection(items => {
                        const item = items[0];
                        if (item instanceof ContactItem) {
                            ContactCommandUtilities.inviteHelper(item.IContactModel).then(b => resolve(b));
                            input.hide();
                        }
                    }),
                    input.onDidHide(() => {
                        if (cts) {
                            cts.cancel();
                        }
                        resolve(false);
                        input.dispose();
                    })
                );
                input.show();
            });
        } finally {
            disposables.forEach(d => d.dispose());
        }
    }
}

class ContactItem implements vscode.QuickPickItem {

    public label: string;
    public description: string;

    constructor(public IContactModel: IContactModel) {
        this.label =  `${IContactModel.contact.displayName} (${ContactsProviderViewlet.getPresenceStatusName(IContactModel)})`;
        this.description = IContactModel.contact.email;
    }
}