import { Signal, timeoutPromise } from '@vs/vscs-utils';
import * as vscode from 'vscode';

/**
 * Safer function to use the vscode.workspace.updateWorkspaceFolders by ensuring when finished
 * the onDidChangeWorkspaceFolders would be completed. Another call to updateWorkspaceFolders
 * could fail if you don't wait for it to finish
 */
 export async function updateWorkspaceFolders(start: number, deleteCount: number | undefined | null, ...workspaceFoldersToAdd: { uri: vscode.Uri, name?: string }[]): Promise<boolean> {
    const workspaceChangedSignal = new Signal<void>();
    const handler = vscode.workspace.onDidChangeWorkspaceFolders((e) => {
        handler.dispose();
        workspaceChangedSignal.resolve();
    });
    if (vscode.workspace.updateWorkspaceFolders(start, deleteCount, ...workspaceFoldersToAdd)) {
        await timeoutPromise(workspaceChangedSignal.promise, 5000, new Error('Failed to update workspace folders'));
        return true;
    } else {
        handler.dispose();
        return false;
    }
}