import { SessionContext, localize } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
export function getCollaborators(): Array<vsls.WorkspaceUserProfile> {
    if (!SessionContext.collaboratorManager) {
        return [];
    }
    return Object.values(SessionContext.collaboratorManager.getCollaborators());
}

export function formatUnreadLabel(name: string, unread: number): string {
    return `${name} ${unread > 0 ? localize('chat.unreadLabel').replace('$(unread)', unread.toLocaleString()) : ''}`;
}