import * as vscode from 'vscode';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';
import { ChatViewController } from './chat/ChatViewController';
import { IRpcServices, ExtensionUtil,
    getExpService,  IClientAccessCheck, Lazy, IDependencies } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { ChatEventSource } from './chat/IChatViewController';
import { IRpcClientProxy } from '@vs/vso-rpc';

class CommunicationsManager {
    private static singleton: CommunicationsManager;
    private readonly tracePrefix = '[Communications Manager]';
    private trace: TraceSource;
    private readonly chatViewChanged = new vscode.EventEmitter<void>();

    public chatViewController: ChatViewController;
    public callingServiceManager: any;

    public static get Instance(): CommunicationsManager {
        if (!CommunicationsManager.singleton) {
            CommunicationsManager.singleton = new CommunicationsManager();
        }
        return CommunicationsManager.singleton;
    }

    public initialize(dependencies: IDependencies): Promise<void> {
        return this._initialize(
            dependencies.rpcClient(),
            dependencies.authService(),
            dependencies.accessControlManager,
            dependencies,
            () => {
                return Promise.resolve(Array.from(dependencies.workspaceServices().registeredServices)); 
            });
    }

    private async _initialize(
        rpcClient: IRpcClientProxy,
        authCoreService: vsls.AuthenticationCoreService,
        clientAccessCheck: Lazy<IClientAccessCheck>,
        rpcServices: IRpcServices,
        registeredServicesCallback: () => Promise<string[]>) {
        this.trace = traceSource.withName('Communications.Manager');

        if (await this.isChatEnabled()) {
            this.chatViewController = new ChatViewController(
                authCoreService,
                clientAccessCheck,
                rpcServices,
                this.chatViewChanged,
                this.trace
            );
        }

        if (await this.isAudioEnabled()) {
            // Only import the calling service manager from the Web context.
            // The Spool(Skype) SDK has browser dependencies that will fail otherwise.
            const { CallingServiceManager } = require('./calling/CallingServiceManager');
            this.callingServiceManager = new CallingServiceManager(authCoreService, rpcClient, registeredServicesCallback, this.trace);
            await this.callingServiceManager.initialize();
        }
    }

    public get onChatViewChanged(): vscode.Event<void> {
        return this.chatViewChanged.event;
    }

    public async isChatEnabled(shouldShowError = false): Promise<boolean> {
        return !ChatViewController.isUnsupportedChatExtensionInstalled(shouldShowError);
    }

    public async isAudioEnabled(): Promise<boolean> {
        // Always return false for the moment as the
        // calling service will not work currently on vscode.dev
        return false;
    }

    public async openSessionChat(source: ChatEventSource): Promise<void> {
        this.trace.info(`${this.tracePrefix} open session chat`);
        return await this.chatViewController.openSessionChat(source);
    }
}

const communicationsManagerInstance = CommunicationsManager.Instance;
export { communicationsManagerInstance as CommunicationsManager };