import * as vscode from 'vscode';
import { localize } from '@vs/liveshare-core';
export class ChatStatusBarItem {
    private readonly chatIcon = '$(comment-discussion)';
    protected item: vscode.StatusBarItem;
    protected disposableCommand: vscode.Disposable;
    protected unreadCount: number = 0;
    protected isVisible: boolean = false;

    constructor() {
        this.item = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left);
        const compound = `extension.liveshare.chatStatusBar`;
        this.disposableCommand = vscode.commands.registerCommand(compound, () => {
            return vscode.commands.executeCommand('liveshare.openSessionChat');
        });

        this.item.command = compound;
    }

    public updateCount(unreads: number) {
        this.unreadCount = unreads;
        this.item.text = `${this.chatIcon} ` + localize('chat.statusBarText').replace('$(unreads)', unreads.toLocaleString());
        return this.unreadCount > 0 ? this.show() : this.hide();
    }

    public show() {
        if (!this.isVisible) {
            this.item.show();
            this.isVisible = true;
        }
    }

    public hide() {
        if (this.isVisible) {
            this.item.hide();
            this.isVisible = false;
        }
    }

    public dispose() {
        this.item.dispose();
        this.disposableCommand.dispose();
    }
}
