'use strict';

import * as vscode from 'vscode';
import { Disposable, Inittable, IInittableDisposable } from '@vs/vscode-command-framework';


import { guestServerControllerFactory } from './guestServerController';
import { hostServerControllerFactory } from './hostServerController';
import { IGuestServerController } from './IGuestServerController';
import { IHostServerController } from './IHostServerController';

import {
    IDependencies,
    SessionState,
    SessionStateChangedEventArgs,
    sessionStateTracker,
} from '@vs/liveshare-core';


/** Controls shared servers behaviour and provides UX  in VSCode client */
export interface IServerManager extends IInittableDisposable { }

/**
 * Orchestrates local server controllers in shared and joined collaboration sessions.
 */
export class ServerManager extends Inittable(Disposable(Object)) implements IServerManager {
    private readonly hostController: IHostServerController;
    private guestController: IGuestServerController;
    private readonly stateChangedRegistration: vscode.Disposable;

    constructor(private readonly dependencies: IDependencies) {
        super();
        // Instantiate a host controller by default.
        // It will start monitoring current terminal output for further sharing.
        this.hostController = hostServerControllerFactory(this.dependencies);

        this.stateChangedRegistration = sessionStateTracker.onStateChanged(
            (e: SessionStateChangedEventArgs) => this.handleSessionStateChanged(e.newState, e.oldState));
    }

    public async dispose(): Promise<void> {
        this.stateChangedRegistration.dispose();

        if (this.hostController) {
            await this.hostController.dispose();
        }

        if (this.guestController) {
            await this.guestController.dispose();
        }

        await super.dispose();
    }

    private async handleSessionStateChanged(newState: SessionState, previousState: SessionState) {
        switch (newState) {
            case SessionState.Shared:
                // Activate the host controller in a shared collaboration session.
                await this.hostController.activate();
                break;
            case SessionState.JoiningInProgress:
                // The host controller is not to be used in a joined collaboration session.
                // Stop background monitoring of terminal output.
                this.hostController.dispose();
                // Instantiate a guest controller.
                this.guestController = guestServerControllerFactory(this.dependencies);
                break;
            case SessionState.Joined:
                // Activate the guest controller in a guest collaboration session.
                await this.guestController.activate();
                break;
            default:
                if (previousState === SessionState.Shared) {
                    // Disengage the host controller when leaving a shared collaboration session.
                    await this.hostController.deactivate();
                }
                if (this.guestController && previousState === SessionState.Joined) {
                    // Disengage the guest controller when leaving a joined collaboration session.
                    await this.guestController.deactivate();
                }
                break;
        }
    }
}
