import { ICommandContext } from '@vs/vscode-command-framework';

import { vsls } from '@vs/vsls-contracts';
import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator, ICommandDecoratorCallback } from '../abstractions/ICommandDecorator';
import { TelemetryUtil } from '../utils/TelemetryUtil';
import {  TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import {
    ITelemetry,
    ITimedEvent,
    TelemetryResult,
    cleanSensitiveInformation
} from '@vs/vso-telemetry';

/**
 * Instrumentation `commandHandler` that automatically sets up any
 * default telemetry and tracing for a given command.
 */
export class TelemetryCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private workspaceService: vsls.WorkspaceService,
        private telemetry: ITelemetry,
        private telemetryEventName: string,
        private telemetryFaultEventName: string,
        private telemetryTitle: string,
        private telemetryEventVersion: number,
        private readonly onError?: ICommandDecoratorCallback) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;
        let error: any = undefined;

        let telemetryEvent = this.telemetry.startTimedEvent(this.telemetryEventName);
        let telemetryResult: TelemetryResult = TelemetryResult.Success;
        let telemetryMessage: string = undefined;

        context.telemetryEvent = telemetryEvent;

        this.telemetry.setCorrelationEvent(telemetryEvent);
        telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_TEXT, context.commandText);
        telemetryEvent.addMeasure(TelemetryPropertyNames.TELEMETRY_EVENT_VERSION, this.telemetryEventVersion);

        this.addInvocationTelemetryProperties(telemetryEvent, options.telemetryProperties);

        this.workspaceService.onProgressUpdated((e) => this.onWorkspaceProgressUpdated(e, telemetryEvent));

        try {
            result = await this.next.invoke(options, context);

            telemetryEvent.addProperty(TelemetryPropertyNames.EVENT_RESULT, TelemetryResult.Success);
        } catch (e) {
            telemetryResult = TelemetryUtil.DeriveTelemetryResult(e);
            telemetryMessage = TelemetryUtil.BuildTelemetryMessage(this.telemetryTitle, telemetryResult, e.message);

            telemetryEvent.addProperty(TelemetryPropertyNames.EVENT_RESULT, telemetryResult);

            if (this.onError) {
                this.onError(e, context, options);
            }

            this.telemetry.sendFault(
                this.telemetryFaultEventName,
                TelemetryUtil.MapTelemetryResultToFaultType(telemetryResult),
                telemetryMessage,
                e);

            error = e;

            throw e;
        } finally {
            telemetryMessage = telemetryMessage || TelemetryUtil.BuildTelemetryMessage(this.telemetryTitle, TelemetryResult.Success);
            const duration = telemetryEvent.end(telemetryResult, telemetryMessage);

            context.trace.traceEvent(TelemetryUtil.MapTelemetryResultToTraceEventType(telemetryResult), 0, `Command [${context.commandName}]: ${telemetryMessage} (${duration}ms)`);

            // noting that we have logged the error. We will check this up stream
            if (error) {
                if (error.stack) {
                    context.trace.error(cleanSensitiveInformation(error.stack));
                }

                error.hasRecorded = true;
            }
        }

        return result;
    }

    private addInvocationTelemetryProperties(telemetryEvent: ITimedEvent, properties: { [key: string]: any; } = {}) {
        for (let propertyName of Object.keys(properties)) {
            telemetryEvent.addProperty(propertyName, properties[propertyName]);
        }
    }

    private onWorkspaceProgressUpdated(e: vsls.WorkspaceProgressEventArgs, telemetryEvent: ITimedEvent) {
        switch (e.progress) {
            case vsls.WorkspaceProgress.WaitingForHost: {
                telemetryEvent.markTime(TelemetryPropertyNames.START_WAITING_FOR_HOST);
                break;
            }
            case vsls.WorkspaceProgress.DoneWaitingForHost: {
                telemetryEvent.markTime(TelemetryPropertyNames.DONE_WAITING_FOR_HOST);
                break;
            }
            case vsls.WorkspaceProgress.ReconnectingToHost: {
                telemetryEvent.markTime(TelemetryPropertyNames.RECONNECTING_TO_HOST);
                break;
            }
            case vsls.WorkspaceProgress.ReconnectedToHost: {
                telemetryEvent.markTime(TelemetryPropertyNames.RECONNECTED_TO_HOST);
                break;
            }
            default: {}
        }
    }
}