import { TraceSource } from '@vs/vso-logging';

import { vsls } from '@vs/vsls-contracts';
import { ITracked } from '../CoEditing';
import { MessageFactory } from './coauthoringService';
import { TransformManager, ITransformManagerHost, ServerVersion } from './TransformManager';
import { assert, logger, colorize } from './coeditingUtils';
import { ITextChange } from './textChange';
import { EventEmitter } from 'events';
import { getTimedArray, setArray } from './timedArray';

export interface IOTAlgorithmHost {
    /**
     * The file name.
     */
    readonly fileName: string;
    /**
     * The id of the current OT host.
     */
    readonly clientID: number;
    /**
     * The trace to output to the logs.
     */
    readonly trace: TraceSource;
    /**
     * Send a message to the server.
     */
    postMessage(msg: vsls.TextChangeMessage): void;
}

export interface IOTAlgorithmBuffer {
    /**
     * Apply a list of edits that are all based on the current state of the buffer.
     * Return the changes complete with undo edits.
     */
    applyRemoteEdits(edits: Edit[]): ITextChange[];
    /**
     * Get the current max position in the buffer.
     */
    getMaximumOffset(): number;
}

export class Edit {
    constructor(
        public readonly position: number,
        public readonly length: number,
        public readonly text: string
    ) {
    }
}

export class OTAlgorithmStatus {
    public readonly unacknowledgedCount: number;
    constructor(
        public readonly serverVersion: number,
        public readonly unacknowledged: UnacknowledgedChange[]
    ) {
        this.unacknowledgedCount = unacknowledged.length;
    }
}

export class OTAlgorithmState {
    constructor(
        public readonly currentServerVersionNumber: number,
        public readonly unacknowledgedChanges: UnacknowledgedChange[],
    ) {
    }
}

export const serverVersionChangedEventName = 'serverVersionChanged';

export class OTAlgorithm {
    private readonly host: IOTAlgorithmHost;
    private readonly diagnosticTrace: boolean;

    private unacknowledgedChanges: UnacknowledgedChange[] = getTimedArray('unacknowledgedchangestime');
    private transformManager: TransformManager;

    // This event is raised any time the server version is changed -
    // either from accepting a remote change or from a local change being acknowledged. 
    public serverVersionChangedEvent: EventEmitter = new EventEmitter();

    constructor(host: IOTAlgorithmHost, diagnosticTrace: boolean) {
        this.host = host;
        this.diagnosticTrace = diagnosticTrace;

        const transformHost = new class implements ITransformManagerHost {
            public readonly trace = host.trace;
            public get fileName(): string {
                return host.fileName;
            }
        };

        this.transformManager = new TransformManager(transformHost);
    }

    public getOperationalTransformStatus(): OTAlgorithmStatus {
        return new OTAlgorithmStatus(
            this.transformManager.CurrentServerVersionNumber,
            this.unacknowledgedChanges
        );
    }

    public getCurrentHistory(): ServerVersion[] {
        return this.transformManager.CurrentHistory;
    }

    /**
     * Sets the underlying transform manager's history.
     */
    public setInitialHistory(serverVersions: ServerVersion[]): void {
        this.transformManager.setInitialHistory(serverVersions);
    }

    /**
     * Save the state of this class such that it can be restored via `loadState`.
     */
    public saveState(): OTAlgorithmState {
        let currentServerVersionNumber = this.transformManager.CurrentServerVersionNumber;
        let unacknowledgedChanges: UnacknowledgedChange[] = [];
        for (let i: number = 0; (i < this.unacknowledgedChanges.length); ++i) {
            unacknowledgedChanges.push(this.unacknowledgedChanges[i].clone());
        }

        return new OTAlgorithmState(
            currentServerVersionNumber,
            unacknowledgedChanges
        );
    }

    /**
     * Restore a previously saved state of this class.
     */
    public loadState(state: OTAlgorithmState): void {
        this.transformManager.RollbackTo(state.currentServerVersionNumber);
        setArray(this.unacknowledgedChanges, state.unacknowledgedChanges);
    }

    /**
     * Accept (react to) a local original (user made) change.
     */
    public acceptLocalChange(originalChanges: ITextChange[], unexpandedChanges: ITextChange[], trackingId?: string): void {
        if (this.diagnosticTrace) {
            logger.log(`acceptOriginalBufferChange: ${JSON.stringify(originalChanges)}`);
            logger.indent();
        }
        let changes: vsls.TextChange[] = OTAlgorithm._toTextChangeArr(unexpandedChanges);
        let message = MessageFactory.TextChangeMessage(this.host.clientID, this.host.fileName, undefined, this.transformManager.CurrentServerVersionNumber, changes);
        (message as any as ITracked).trackingId = trackingId;

        this.unacknowledgedChanges.push(new UnacknowledgedChange(message, originalChanges));
        this.host.postMessage(message);

        if (this.diagnosticTrace) {
            logger.unindent();
        }
    }

    /**
     * Accept (react to) a remote change.
     */
    public acceptRemoteChange(buffer: IOTAlgorithmBuffer, message: vsls.TextChangeMessage, eventId: number): void {
        this.host.trace.verbose('OTAlgorithm.acceptRemoteChange');
        if (this.diagnosticTrace) {
            logger.log(`acceptRemoteChange: ${JSON.stringify(message)}`);
            logger.indent();
        }

        assert(message.clientId !== this.host.clientID, 'Changes must be from a remote client');
        if (message.clientId === this.host.clientID) {
            if (this.diagnosticTrace) {
                logger.unindent();
            }

            return;
        }

        // Undo our unacknowledged changes
        if (this.diagnosticTrace) {
            logger.log(`beginning to undo unacknowledged changes.`);
            logger.indent();
        }
        
        // Apply the unacknoweldged changes in reverse order to slowly reach the
        // original state so we can apply the actual remote changes.
        for (let i: number = this.unacknowledgedChanges.length - 1; (i >= 0); --i) {
            this.host.trace.verbose('Undoing unacknowledged change so we can apply remote change');
            this._applyUndoChangeOnBuffer(buffer, this.unacknowledgedChanges[i].previousVersion);
        }

        if (this.diagnosticTrace) {
            logger.unindent();
            logger.log(`finished undo of unacknowledged changes.`);

            logger.log(`beginning to apply server message.`);
            logger.indent();
        }

        // Apply the remote change and update our knowledge of what the server's state is.
        // We must first rebase the remote change to the latest server truth.
        // Then, we can safely apply it on our buffer which matches the latest server truth (due to our undo above).
        // Finally, we will save the forward operation and update the server truth to include this remote change.
        let adjustedMessage: vsls.TextChangeMessage = this.transformManager.TransformMessageToCurrent(message);

        this.host.trace.verbose('OTAlgorithm applying remote change to buffer');
        this._applyOperationOnBuffer(buffer, adjustedMessage);
        this.transformManager.AddToServersionHistory(eventId, message, adjustedMessage);

        if (this.diagnosticTrace) {
            logger.unindent();
            logger.log(`finished applying server message.`);

            logger.log(`beginning to redo unacknowledged changes.`);
            logger.indent();
        }

        // For all our unacknowledged changes, generate a message that now correctly
        // represents the forward looking edits so when applied they result in
        // the correct state
        for (let i: number = 0; (i < this.unacknowledgedChanges.length); ++i) {
            let redoMessage: vsls.TextChangeMessage = this.unacknowledgedChanges[i].message;
            let adjustedRedoMessage: vsls.TextChangeMessage = this.transformManager.TransformMessageToCurrent(redoMessage);
            this.host.trace.verbose('Redoing unacknowledged change');
            let unacknowledgedChangeEdits: ITextChange[] = this._applyOperationOnBuffer(buffer, adjustedRedoMessage);
            this.unacknowledgedChanges[i].previousVersion = unacknowledgedChangeEdits;
            this.transformManager.AddToServersionHistory(++eventId, redoMessage, adjustedRedoMessage);
        }

        this.transformManager.RemoveUnacknowledgedChangesFromServerVersionHistory(this.unacknowledgedChanges.length);

        if (this.diagnosticTrace) {
            logger.unindent();
            logger.log(`finished redo of unacknowledged changes.`);
            logger.unindent();
        }

        this.serverVersionChangedEvent.emit(serverVersionChangedEventName);
    }

    private _applyUndoChangeOnBuffer(buffer: IOTAlgorithmBuffer, changes: ITextChange[]): void {

        let edits = new Array<Edit>(changes.length);
        for (let i = 0; (i < changes.length); ++i) {
            let c = changes[i];
            edits[i] = new Edit(c.newPosition, c.newLength, c.oldText);
        }
        buffer.applyRemoteEdits(edits);
    }

    public transformMessageToEdits(maxBufferOffset: number, message: vsls.TextChangeMessage): Edit[] {
        // TODO@Cascade: The only complication here is the extra checking of edits for invalid or overlapping edits.

        assert(message.changeServerVersion === this.transformManager.CurrentServerVersionNumber, 'Cannot apply change on buffer due to different contexts.');
        if (message.changeServerVersion !== this.transformManager.CurrentServerVersionNumber) {
            return [];
        }

        const changes = message.changes || [];
        let edits = new Array<Edit>(changes.length);

        let prevStart = -1, prevEnd = -1;
        for (let changeIndex = 0; (changeIndex < changes.length); ++changeIndex) {
            let change = changes[changeIndex];

            let start = change.start!;
            let end = change.start! + change.length!;

            // TODO@Cascade: the transformation function generates invalid and overlapping edits.
            // Here we eliminate overlapping edits
            {
                let newStart = Math.max(prevEnd, start);
                let newEnd = Math.max(prevEnd, end);
                if (newStart !== start || newEnd !== end) {
                    if (this.diagnosticTrace) {
                        logger.log(colorize.red(`warning`) + `: overlapping edits: position: ${start}, length: ${end - start} has been clamped to position: ${newStart}, length: ${newEnd - newStart}`);
                    }
                    start = newStart;
                    end = newEnd;
                }
            }

            // Here we clamp edits which are out of bounds
            {
                let newStart = Math.min(Math.max(0, start), maxBufferOffset);
                let newEnd = Math.min(Math.max(newStart, end), maxBufferOffset);
                if (newStart !== start || newEnd !== end) {
                    if (this.diagnosticTrace) {
                        logger.log(colorize.red(`warning`) + `: edit out of bounds: position: ${start}, length: ${end - start} has been clamped to position: ${newStart}, length: ${newEnd - newStart}`);
                    }
                    start = newStart;
                    end = newEnd;
                }
            }

            prevStart = start;
            prevEnd = end;

            edits[changeIndex] = new Edit(start, end - start, change.newText || '');
        }

        return edits;
    }

    private _applyOperationOnBuffer(buffer: IOTAlgorithmBuffer, message: vsls.TextChangeMessage): ITextChange[] {
        const edits = this.transformMessageToEdits(buffer.getMaximumOffset(), message);
        let editsAppliedToBuffer = buffer.applyRemoteEdits(edits);
        return editsAppliedToBuffer;
    }

    /**
     * Accept (react to) the server acknowledging a message sent by us.
     */
    public acceptTextChangeAcknowledge(message: vsls.TextChangeMessage, eventId: number): void {
        if (this.diagnosticTrace) {
            logger.log(`acceptTextChangeAcknowledge`);
            logger.indent();
        }

        try {
            assert(message.clientId === this.host.clientID, 'Changes must a change we initiated');
            if (message.clientId !== this.host.clientID) {
                return;
            }

            // Our unacknowledged change got acknowledged: delete the 1st unacknowledged change.
            let unacknowledgedChange: UnacknowledgedChange = this.unacknowledgedChanges[0];
            this.unacknowledgedChanges.splice(0, 1);

            this.transformManager.AddToServersionHistory(eventId, unacknowledgedChange.message);

            this.serverVersionChangedEvent.emit(serverVersionChangedEventName);
        } finally {
            if (this.diagnosticTrace) {
                logger.unindent();
            }
        }
    }

    public TransformMessageToCurrent(message: vsls.TextChangeMessage): vsls.TextChangeMessage {
        return this.transformManager.TransformMessageToCurrent(message);
    }

    private static _toTextChangeArr(changes: ITextChange[]): vsls.TextChange[] {
        let result: vsls.TextChange[] = new Array<vsls.TextChange>(changes.length);
        for (let i = (changes.length - 1); (i >= 0); --i) {
            let change = changes[i];
            result[i] = MessageFactory.TextChange(change.oldPosition, change.oldLength, change.newText);
        }
        return result;
    }
}

export class UnacknowledgedChange {
    public rollbackEdits: vsls.TextChange[];

    constructor(
        public readonly message: vsls.TextChangeMessage,
        // Edits required to roll back this change against the current buffer
        public previousVersion: ITextChange[]
    ) {
        this.rollbackEdits = new Array<vsls.TextChange>(previousVersion.length);
        for (let i = 0; (i < previousVersion.length); ++i) {
            let c = previousVersion[i];
            this.rollbackEdits[i] = MessageFactory.TextChange(c.newPosition, c.newLength, c.oldText);
        }
    }

    public clone(): UnacknowledgedChange {
        return new UnacknowledgedChange(this.message, this.previousVersion);
    }
}
