import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';

import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { IContactManager, InviteLinkReceived, InviteLinkJoining, ContactManagerEvents } from '../contracts/IContactManager';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { TelemetryEventNames, TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import {
    TelemetryEvent,
} from '@vs/vso-telemetry';
import { ILogger } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';

export function initInviteLinkSupport(contactManager: IContactManager) {
    contactManager.addListener(ContactManagerEvents.InviteLinkReceived, async (message: InviteLinkReceived) => {
        await handleInviteLinkReceived(contactManager, message, traceSource);
    });    
}

async function handleInviteLinkReceived(
    contactManager: IContactManager,
    e: InviteLinkReceived,
    logger?: ILogger): Promise<void> {

    // Note: we should never receive an invite if the host knows the contact is already joined or we are
    // joining or the invitation was send. To be compatible with old host versions that may still send
    // invitations or the case were there is no trivial match between a 'contact' and a liveshare 'userProfile'
    if (workspaceSessionInfoTracker.workspaceSessionInfo && workspaceSessionInfoTracker.workspaceSessionInfo.joinUri === e.link) {
        logger?.verbose(`Invite link received for uri:${e.link} but already joined`);
        return;
    }

    const fireInviteStatusChanged = async (status: vsls.InviteContactStatus) => {
        await contactManager.fireInviteStatusChanged(
            e.originator.contact.id,
            e.provider.selfUserId,
            status);
    };

    // if a self invite
    const isSelfInvite = e.originator.contact.id === e.provider.selfUserId;

    // Reject any invite when dnd state was manually set through our UI or indirectly
    // by the presence provider
    if (contactManager.isDoNotDisturbState && !isSelfInvite) {
        await fireInviteStatusChanged(vsls.InviteContactStatus.Dismissed);
        return;
    }

    // move to -> Invited
    await fireInviteStatusChanged(vsls.InviteContactStatus.Invited);

    const showInviteLinkToastAction = new TelemetryEvent(TelemetryEventNames.SHOW_LINK_INVITE_TOAST);
    showInviteLinkToastAction.send();

    const acceptButton = { id: 1, title: 'Accept'};
    let buttons = [acceptButton];

    const origContact = e.originator?.contact;
    const displayName = origContact.displayName || (<any>origContact).DisplayName  || 'Unknown User';
    const result = await vscode.window.showInformationMessage(
        `${displayName} invited you to join a collaboration session`,
        ...buttons);

    const showInviteLinkToastResult = new TelemetryEvent(TelemetryEventNames.RESPOND_TOAST);
    showInviteLinkToastResult.correlateWith(showInviteLinkToastAction);
    showInviteLinkToastResult.addProperty(TelemetryPropertyNames.TOAST_RESULT, result?.title);
    showInviteLinkToastResult.send();

    if (result && result.id === acceptButton.id) {
        // move to -> Joining
        await fireInviteStatusChanged(vsls.InviteContactStatus.Joining);

        const inviteLinkJoining: InviteLinkJoining = {
            targetContactId: e.originator.contact.id,
            fromContactId: e.provider.selfUserId
        };
        const joinOptions = {
            newWindow: false,
            link: e.link,
            inviteLinkJoining,
        };
        await vscode.commands.executeCommand(`${Settings.get<string>(SettingKeys.commandPrefix)}.join`, joinOptions);
    } else {
        // move to -> Dismissed
        await fireInviteStatusChanged(vsls.InviteContactStatus.Dismissed);
    }
}