import { fileAccess } from '@vs/vscode-command-framework';
import * as path from 'path';
import * as vscode from 'vscode';

import { LIVESHARE_WORKSPACE_TEMP_DIR, WORKSPACE_TEMP_FOLDER_NAME_PREFIX } from '../constants';

/**
 * This class is serialized to JSON and written
 * to the workspace file.
 * {"folders": [{"uri": "vsls:/"}], "settings": {}, "transient": true }
 */
export class WorkspaceDefinition {
    public folders: any[] = [];
    public settings: any = {};
    public transient: any = null; 
}

export class WorkspaceManager {
    /**
     * Creates a new workspace file in a temporary folder.
     *
     * @param workspaceFilePath Path to the workspace file.
     * @param workspaceDefinition the workspace definition (contents of the workspace file)
     */
    public static async createWorkspace(workspaceFilePath: string, workspaceDefinition: WorkspaceDefinition): Promise<string> {
        const workspaceFileContent = JSON.stringify(workspaceDefinition);

        if (await fileAccess.existsAsync(workspaceFilePath)) {
            return workspaceFilePath;
        }

        await fileAccess.writeFileAsync(workspaceFilePath, workspaceFileContent);
        
        return workspaceFilePath;
    }

    public static async createWorkspaceFromUris(uris: vscode.Uri[]): Promise<string> {
        const workspace = new WorkspaceDefinition();

        const randomString = `${Date.now()}${Math.random()}`.replace('.', '');
        let workspaceFolder = path.join(LIVESHARE_WORKSPACE_TEMP_DIR, `${WORKSPACE_TEMP_FOLDER_NAME_PREFIX}${randomString}`);

        await fileAccess.ensureDirAsync(workspaceFolder);

        for (let uri of uris) {
            workspace.folders.push({
                path: uri.path,
            });
        }

        const workspaceFilePath = path.join(workspaceFolder, `Untitled.code-workspace`);
        await WorkspaceManager.createWorkspace(workspaceFilePath, workspace);

        return workspaceFilePath;
    }

    public static async updateWorkspaceFile(workspaceDefinition: WorkspaceDefinition, workspacePath: string): Promise<void> {
        const workspaceFileContent = JSON.stringify(workspaceDefinition);
        return fileAccess.writeFileAsync(workspacePath, workspaceFileContent);
    }
}
