import * as os from 'os';
import * as path from 'path';
import * as crypto from 'crypto';

import * as vscode from 'vscode';

import { once } from '@vs/vscs-utils';

export const vscodeModule = once(() => {
    // Defer import of 'vscode' package.
    const vscodeRef = require('vscode') as typeof vscode;
    return vscodeRef;
});

export const getExtension = (extensionName: string) => {
    return vscodeModule().extensions.getExtension(extensionName);
};

export function getAppFilePath(appFilePath: string, extensionName: string): string {
    return path.join(getExtension(extensionName)!.extensionPath, appFilePath);
}

export function getAgentPipeName(appFilePath: string, prefix: string, postfix?: string): string {
    const pipeNameKey = crypto
        .createHash('md5')
        .update(appFilePath + os.userInfo().username + (postfix ? postfix : ''))
        .digest('hex');
    return `${prefix}.${pipeNameKey}`;
}
