import { VsCodeNativeAuthTokenProvider } from './VscodeNativeAuthTokenProvider';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';
import { SupportedAuthProviders } from './NativeAuthProvider';
import { Settings } from '../../Settings';
import { SettingKeys } from '../../SettingKeys';

export class GitHubAuthTokenProvider extends VsCodeNativeAuthTokenProvider {

    public constructor(logger?: TraceSource) {
        logger = logger ?? traceSource.withName(SupportedAuthProviders.GitHub);

        const scopes = Settings.get<boolean>(SettingKeys.runsInVSCodeDev) ?
            // the set of scopes we use in vscode.dev/github.dev is aligned with GitHub's builtin extensions:
            // GitHub Codespaces/Repositories/PR-s and Issues 
            ['read:user', 'user:email', 'repo'] :
            ['read:user', 'user:email'];

        super(SupportedAuthProviders.GitHub, scopes, logger);
    }
}