import { IRpcClient } from './IRpcClient';
import * as rpc from 'vscode-jsonrpc';
import { ILogger } from '@vs/vso-logging';
import { RpcConnectionClosedError } from './RpcConnectionErrors';
import { RpcClientProxyBase } from './RpcClientProxy';
import { RpcServiceHandler, IRpcMessageStream } from './RpcServiceHandler';
import { Mutex } from '@vs/vscs-utils';

export interface IRpcMessageConnectionFactory {
    create(rpcClient: RpcClient): Promise<rpc.MessageConnection>;
    dispose?(): void;
}

class RpcClientProxy extends RpcClientProxyBase {
    public constructor(private readonly rpcClient: RpcClient, logger: ILogger) {
        super(logger);
    }

    public ensureConnectionAsync(): Promise<rpc.MessageConnection> {
        return this.rpcClient.ensureConnectionAsync();
    }
}
export class RpcClient extends RpcServiceHandler implements IRpcClient {
    private readonly rpcClientProxy: RpcClientProxy;
    protected connection: rpc.MessageConnection | null = null;
    private readonly connectionFactoryMutex = new Mutex();

    public constructor(
        private readonly connectionFactory: IRpcMessageConnectionFactory,
        logger: ILogger
    ) {
        super(logger);
        this.rpcClientProxy = new RpcClientProxy(this, logger);
        if (connectionFactory.dispose) {
            this.addToDisposables(connectionFactory);
        }
    }

    public static fromRpcMessageStream(
        rpcMessageStreamCallback: () => Promise<IRpcMessageStream>,
        logger: ILogger,
        disposeCallback?: () => void
    ): RpcClient {
        return new RpcClient(
            {
                create: async (rpcClient) => {
                    const rpcMessageStream = await rpcMessageStreamCallback();
                    const rpcConnection = rpcClient.createRpcConnection(rpcMessageStream, logger);
                    rpcConnection.listen();
                    return rpcConnection;
                },
                dispose: () => {
                    if (disposeCallback) {
                        disposeCallback();
                    }
                },
            },
            logger
        );
    }

    public sendRequest<T>(
        logger: ILogger,
        serviceAndMethodName: string,
        progress: { report: (value: any) => void } | null,
        cancellationToken: rpc.CancellationToken | null,
        ...args: any[]
    ): Promise<T> {
        return this.rpcClientProxy.sendRequest(
            logger,
            serviceAndMethodName,
            progress,
            cancellationToken,
            ...args
        );
    }

    public sendNotification(
        logger: ILogger,
        serviceAndName: string,
        args: object | any[]
    ): Promise<void> {
        return this.rpcClientProxy.sendNotification(logger, serviceAndName, args);
    }

    public async onConnect(handler: () => void): Promise<void> {
        await this.ensureConnectionAsync();
        handler();
    }

    public async onClose(handler: () => void): Promise<void> {
        await this.ensureConnectionAsync();
        this.connection!.onClose(handler);
    }

    protected async ensureConnectionInternal(): Promise<void> {
        if (!this.connection) {
            await this.connectionFactoryMutex.dispatch(async () => {
                if (!this.connection) {
                    this.setConnection(await this.connectionFactory.create(this));
                }
            });
        }
    }

    public async ensureConnectionAsync(): Promise<rpc.MessageConnection> {
        await this.ensureConnectionInternal();
        return this.connection!;
    }

    protected setConnection(conection: rpc.MessageConnection | any | null): void {
        this.connection = conection as rpc.MessageConnection;
        if (conection) {
            this.attachConnection(conection);
            this.addToDisposables(conection);
        }
    }

    private attachConnection(connection: rpc.MessageConnection): void {
        connection.onClose(() => {
            this.trace.info(`RPC connection closed. disposed: "${this.isDisposed}"`);
            if (!this.isDisposed) {
                // The connection was closed unexpectedly (not due to extension deactivation).
                // Dispose with an error that causes further communication attemps to be
                // rejected with an appropriate exception.
                this.dispose(new RpcConnectionClosedError());
            }
        });

        // add generic request support
        connection.onRequest((method: string, ...params: any[]) => {
            return this.onRequest(null, connection, method, ...params);
        });

        // Add progress and generic notification support.
        connection.onNotification((method: string, ...params: any[]) => {
            this.onNotification(connection, method, ...params);
        });
    }
}
