import { IRpcServices } from './contracts/IRpcServices';
import { ServiceInfo, IRpcServiceHandler } from '@vs/vso-rpc';
import { vsls } from '@vs/vsls-contracts';
import { lazyLoad, Lazy } from './Lazy';

export class RpcServices implements IRpcServices {
    constructor(
        public readonly rpcFactory: <T>(serviceInfo: ServiceInfo<T>, traceName: string) => T,
        public readonly rpcServiceHandler: Lazy<IRpcServiceHandler>) {
    }

    public workspaceService = lazyLoad(() => this.rpcFactory(vsls.WorkspaceService, vsls.TraceSources.ClientRpcWorkspace));
    public sourceEventService = lazyLoad(() => this.rpcFactory(vsls.SourceEventService, vsls.TraceSources.ClientRpcSourceEvent));
    public workspaceAccessControlService = lazyLoad(() => this.rpcFactory(vsls.WorkspaceAccessControlService, vsls.TraceSources.ClientWorkspaceAccessControl));
    public fileService = lazyLoad(() => this.rpcFactory(vsls.FileService, vsls.TraceSources.ClientRpcFile));
    public accessControlService = lazyLoad(() => this.rpcFactory(vsls.AccessControlService, vsls.TraceSources.ClientAccessControl));
    public syncService = lazyLoad(() => this.rpcFactory(vsls.SyncService, 'SyncService'));
    public workspaceUserService = lazyLoad(() => this.rpcFactory(vsls.WorkspaceUserService, vsls.TraceSources.ClientRpcWorkspaceUser));
    public serverSharingService = lazyLoad(() => this.rpcFactory(vsls.ServerSharingService, vsls.TraceSources.ClientRpcServerSharing));
    public portForwardingService = lazyLoad(() => this.rpcFactory(vsls.PortForwardingService, vsls.TraceSources.ClientRpcPortForwarding));
    public streamManagerService = lazyLoad(() => this.rpcFactory(vsls.StreamManagerService, vsls.TraceSources.ClientRpcStreamManager));
    public streamService = lazyLoad(() => this.rpcFactory(vsls.StreamService, vsls.TraceSources.ClientRpcStream));
    public chatService = lazyLoad(() => this.rpcFactory(vsls.ChatService, vsls.TraceSources.ClientRpcChat));
    public terminalService = lazyLoad(() => this.rpcFactory(vsls.TerminalService, vsls.TraceSources.ClientRpcTerminal));
}