export enum HubProxyType {
    ContactService,
    RelayService
}

/**
 * Define a contract to a hub connection service.
 */
export interface IHubConnectionService {
    setEnabled(newState: boolean): Promise<void>;
    getOrCreateProxy<T>(type: HubProxyType): T;
}

/**
 * Define a contract for a hub connection service factory
 */
export interface IHubConnectionServiceFactory {
    getOrCreate(stamp?: string): Promise<IHubConnectionService>;
}