/**
 * Check if `val` is thenable or promiseLike.
 */
export const isThenable = <T>(val: undefined | null | T | PromiseLike<T>): val is PromiseLike<T> => {
    if (val == null) {
        return false;
    }

    if (typeof (val as PromiseLike<T>).then !== 'function') {
        return false;
    }
    return true;
};
