import { ICommandContext, NotificationUtil } from '@vs/vscode-command-framework';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator, ICommandDecoratorCallback } from '../abstractions/ICommandDecorator';
import { UserError } from '../abstractions/UserError';
import { RpcConnectionShutdownError } from '@vs/vso-rpc';
import { CancellationError } from "@vs/vscs-utils";
import { NonBlockingError } from '../abstractions/NonBlockingError';
import { ByDesignError } from '../abstractions/ByDesignErrors';
import { ExtensionUtil } from '../utils/ExtensionUtil';

import {
    FaultType,
    ITelemetry,
} from '@vs/vso-telemetry';

/**
 * Error Notification `commandHandler` that converts exceptions into the correct
 * notification toast in the client.
 */
export class ErrorNotificationCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private telemetry: ITelemetry,
        private telemetryFaultEventName: string,
        private title: string,
        private isModalError: boolean, 
        private onError?: ICommandDecoratorCallback,
        private onNoErrorMessage?: ICommandDecoratorCallback) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        const { cancellationTokenSource } = context;
        let result: any;
        
        // save the command name
        context.commandName = this.title;

        try {
            result = await this.next.invoke(options, context);
        } catch (error) {
            try {
                let message;
                if (error.code) {
                    message = ExtensionUtil.getErrorString(error.code);
                }

                if (this.onNoErrorMessage) {
                    message = await this.onNoErrorMessage(error, context, options);
                }

                if (!message) {
                    // If message is undefined, set it to exception message.
                    message = error.message;
                }

                const fullMessage = `${context.commandName}: ${message}`;
                // if `CancellationError` was throw, invalidate the cancellation token
                if (error instanceof CancellationError) {
                    
                    // cancel the command cancellation token if not cancelled yet
                    if (cancellationTokenSource && !cancellationTokenSource.token.isCancellationRequested) {
                        cancellationTokenSource.cancel();
                    }
                }

                const isCancellationOrUserError = (error instanceof UserError || error instanceof CancellationError);

                // Supress the notification if the error has the appropriate property
                // or if it's a cancellation error with no message.
                const suppressNotification = error.isSuppressUserNotification ||
                    (error instanceof CancellationError && !error.message) ||
                    (error instanceof RpcConnectionShutdownError);

                if (!suppressNotification) {
                    if (isCancellationOrUserError) {
                        NotificationUtil.showInformationMessage(fullMessage, false);
                    } else if (error instanceof ByDesignError) {
                        await NotificationUtil.showErrorMessage(fullMessage, { modal: this.isModalError });
                    } else if (!(error instanceof NonBlockingError)) {
                        await NotificationUtil.showErrorMessage(fullMessage, { modal: this.isModalError });
                    }
                }
            } catch (e) {
                // if the above block triggered an error we want to know
                error = e;
            }

            // at this this point we will know about any errors that hasn't been
            // recorded - anything thats happened up stream of `TelemetryCommandMiddleware`
            if (error && !error.hasRecorded) {
                const errorMessage = `${context.commandName}: [unhandled exception (decorator)] ${error.message}`;
                context.trace.error(errorMessage);
                this.telemetry.sendFault(
                    this.telemetryFaultEventName,
                    FaultType.Error,
                    errorMessage,
                    error);
            }
            
            if (error && this.onError) {
                await this.onError(error, context, options);
            }
        }

        return result;
    }
}