import { ICommandContext } from '@vs/vscode-command-framework';
import { ICommandRegistryProvider } from './abstractions/ICommandRegistryProvider';
import { IExtensionSetup } from './abstractions/IExtensionSetup';
import { ICommand } from './abstractions/ICommand';
import { SettingKeys } from './SettingKeys';
import { Settings } from './Settings';
import { Access } from '@vs/liveshare-api-contracts';
import { registerCommands } from './commands/registerCommands';
import { builder as UserElevationToggleCommandBuilder } from './commands/UserElevationToggleCommand';
import { builder as CreateInvitationLinkCommandBuilder } from './commands/CreateInvitationLinkCommand';
import { builder as CreateSessionCommandBuilder } from './commands/CreateSessionCommand';
import { CommandId } from './CommandConstants';

const buildCommandName = (commandName: string) => {
    const commandPrefix = `${Settings.get<string>(SettingKeys.commandPrefix)}.`;
    if (!commandName.startsWith(commandPrefix)) {
        return `${commandPrefix}${commandName}`;
    }

    return commandName;
};

interface ICommandData {
    builder: any;
    options?: {};
}

export abstract class ExtensionSetupBase implements IExtensionSetup {
    private didInit: boolean = false;
    private commandFiles: { [key: string]: ICommandData } = {};

    constructor (
        private commandRegistryProvider: ICommandRegistryProvider,
        protected dependencies: any) {
    }

    public async init(): Promise<void> {

        this.registerCommands();

        // Register commands with the client
        Object.keys(this.commandFiles).forEach((command) => {
            this.commandRegistryProvider.register(
                command,
                this.getCommandBuilder(this.commandFiles[command])
            );
        });

        this.didInit = true;
    }

    protected registerCommands(): void {
        // All 'core' commands
        registerCommands(this);

        // join commands
        this.registerJoinCommands();

        // sharing commands
        this.registerShareCommands();

        this.registerUserElevationCommand();
        this.registerCreateInvitationLinkCommand();
        this.registerCreateSessionCommand();
    }

    protected abstract get shareCommandBuilder(): any;

    protected abstract get joinCommandBuilder(): any;

    public register(commandName: string, builder: any, options?: {}): void {
        const builderDefinition: ICommandData = {
            builder,
            options
        };
        this.commandFiles[buildCommandName(commandName)] = builderDefinition;
    }

    public async dispose(): Promise<void> {
        if (!this.didInit) {
            return;
        }

        this.commandRegistryProvider.disposeAll();
    }

    private getCommandBuilder(commandData: ICommandData): () => ICommand<any> {
        return (): ICommand<any> => {
            const { builder } = commandData;
            const command: ICommand<any> = builder(this.dependencies);

            return {
                invoke: (options: any, context: ICommandContext) => {
                    return command.invoke({ ...commandData.options, ...options }, context);
                }
            };
        };
    }

    protected registerJoinCommands() {
       const joinCommandNames = [
            'join',
            'joinFromFileTreeExplorer',
            'joinFromActivityBar',
            'joinFromWelcomeContent'
        ];

        for (let joinCommandName of joinCommandNames) {
            this.register(joinCommandName, this.joinCommandBuilder, {
                isAllowAnonymous: true
            });
        }
    }

    protected registerShareCommands() {
        // enable share commands
        const shareCommandNames = [
            'start',
            'startFromFileTreeExplorer',
            'startFromActivityBar',
            'startFromWelcomeContent',
            'startFromWelcomePage'
        ];
        for (let shareCommandName of shareCommandNames) {
            this.register(shareCommandName, this.shareCommandBuilder);
        }

        // enable read-only share commands
        const shareReadOnlyCommandNames = [
            'startReadOnly',
            'startReadOnlyFromFileTreeExplorer',
            'startReadOnlyFromActivityBar',
            'startReadOnlyFromWelcomeContent'
        ];

        for (let shareReadOnlyCommandName of shareReadOnlyCommandNames) {
            this.register(shareReadOnlyCommandName, this.shareCommandBuilder, { access: Access.ReadOnly });
        }

        this.register('startPresentation', this.shareCommandBuilder, { isPresentation: true });
    }

    private registerUserElevationCommand() {
        // enable read-only share commands

        const elevateCommandNames = [
            CommandId.userElevateActivityBar,
            CommandId.userElevateFileTreeExplorer,
        ];

        const decreaseCommandNames = [
            CommandId.userDecreaseActivityBar,
            CommandId.userDecreaseFileTreeExplorer,
        ];

        for (let commandName of elevateCommandNames) {
            this.register(commandName, UserElevationToggleCommandBuilder, { isReadOnly: false });
        }

        for (let commandName of decreaseCommandNames) {
            this.register(commandName, UserElevationToggleCommandBuilder, { isReadOnly: true });
        }
    }

    private registerCreateInvitationLinkCommand() {
        this.register('createInvitationLink', CreateInvitationLinkCommandBuilder);
    }

    private registerCreateSessionCommand() {
        this.register('createSession', CreateSessionCommandBuilder);
    }
}

