import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
export class WorkspaceServices {

    private onServiceAddedEmitter = new vscode.EventEmitter<string>();
    private onServiceRemovedEmitter = new vscode.EventEmitter<string>();

    public readonly registeredServices = new Set<string>();
    public readonly onServiceAdded: vscode.Event<string> = this.onServiceAddedEmitter.event;
    public readonly onServiceRemoved: vscode.Event<string> = this.onServiceRemovedEmitter.event;

    constructor(workspaceService: vsls.WorkspaceService) {
        workspaceService.onServicesChanged((e) => {
            if (e.changeType === vsls.CollectionChangeType.Add) {
                e.serviceNames.forEach(s => {
                    this.registeredServices.add(s);
                    this.onServiceAddedEmitter.fire(s);
                });
            } else if (e.changeType === vsls.CollectionChangeType.Remove) {
                e.serviceNames.forEach(s => {
                    this.registeredServices.delete(s);
                    this.onServiceRemovedEmitter.fire(s);
                });
            }
        });
    }
}