'use strict';

import { vsls } from '@vs/vsls-contracts';
import * as vscode from 'vscode';
import { ISessionContext } from '../ISessionContext';
import { IInittableDisposable } from '../contracts/IInittableDisposable';
import { TraceSource } from '@vs/vso-logging';
import { IRpcServiceHandler, IRpcServiceHandlerInfo } from '@vs/vso-rpc';

export class HostSyncService implements IInittableDisposable, vsls.SyncService, IRpcServiceHandlerInfo {

    private disposables: vscode.Disposable[] = [];

    constructor(
        private readonly workspaceService: vsls.WorkspaceService,
        private readonly session: ISessionContext,
        private rpcServiceHandler: IRpcServiceHandler,
        private trace: TraceSource) {
    }

    public serviceInfo = vsls.SyncService;

    public async init(): Promise<void> {
        await this.workspaceService.registerServicesAsync([vsls.SyncService.name!], vsls.CollectionChangeType.Add);
        this.disposables.push(await this.rpcServiceHandler.registerRpcService(
            this, this.serviceInfo,
            ));
    }

    public async dispose(): Promise<void> {
        for (const disposable of this.disposables) {
            disposable.dispose();
        }
        this.disposables = [];
    }

    public async checkSyncAsync(filePath: string, fileHash: number, cancellationToken?: vscode.CancellationToken): Promise<boolean> {
        const result = await this.session.coeditingClient.isFileSynced(filePath, fileHash);
        return result;
    }

    public async checkSyncForVersionAsync(filePath: string, serverVersionNumber: number, fileHash: number, cancellationToken?: vscode.CancellationToken): Promise<boolean> {
        const result = await this.session.coeditingClient.isFileSyncedForVersion(filePath, undefined, serverVersionNumber, fileHash);
        return result.isSynced;
    }

    public async checkSyncForVersion2Async(filePath: string, fileVersion: number, serverVersionNumber: number, fileHash: number, cancellationToken?: vscode.CancellationToken): Promise<vsls.SyncStatus> {
        const result = await this.session.coeditingClient.isFileSyncedForVersion(filePath, fileVersion, serverVersionNumber, fileHash);
        return result;
    }

}