import * as rpc from 'vscode-jsonrpc';

import { TLiveShareConnectionHub, ConnectionError } from '@vs/vscs-connection-hub';
import { MultiChannelRpcServer } from '@vs/vso-rpc-ssh';
import { ILogger, TraceFormat } from '@vs/vso-logging';
import { IRpcRequestContext } from '@vs/vso-rpc';
import { MultiChannelStream } from '@vs/vs-ssh';
import { assertDefined } from '@vs/vscs-utils';
import { vsls } from '@vs/vsls-contracts';
import {
    ILiveShareConnectionOptions,
    IWorkspaceServiceClient,
    workspaceServiceClient,
    WorkspaceHostConnectionChanged,
    RemoteWorkspaceMetricsUpdated,
    NoHostConnectedError,
    RelayConnectionError,
    CheckConnectionOptions,
    RPC_ERR_NO_HOST_NOT_CONNECTED,
    RPC_ERR_RELAY_CONNECTIONY_SSH,
} from '@vs/vso-workspace-core';
import { IWorkspaceHubService } from './IWorkspaceHubService';
import { WorkspaceConnection } from './WorkspaceConnection';

const rpcContextExpectedMessage = 'Rpc Request context expected';

/**
 * Class to manage multiple workspace clients and allow
 * multiple rpc connections to join.
 */
export class WorkspaceHubService implements IWorkspaceServiceClient, IWorkspaceHubService {
    private readonly onHostConnectionChangedEmitter = new rpc.Emitter<
        WorkspaceHostConnectionChanged
    >();
    private readonly onWorkspaceMetricsUpdatedEmitter = new rpc.Emitter<
        RemoteWorkspaceMetricsUpdated
    >();

    private readonly workspaceConnections = new Map<string, WorkspaceConnection>();

    constructor(
        private readonly rpcServer: MultiChannelRpcServer,
        private connectionHub: TLiveShareConnectionHub,
        private keepAliveCallback: (time?: number) => void,
        private readonly logger: ILogger
    ) {
        this.rpcServer.registerRpcService<IWorkspaceServiceClient>(this, workspaceServiceClient);

        // Note: for all other request that we don't handle directly we will
        // route into the proper joined connections
        this.rpcServer.onHandleNoneRequest(async (rpcConnection, method, ...params) => {
            for (const workspaceConnection of this.workspaceConnections.values()) {
                const rpcSessionNumber = workspaceConnection.getJoinedRpcConnection(rpcConnection);
                if (rpcSessionNumber) {
                    const rpcWorkspaceConnection = await workspaceConnection.rpcWorkspaceConnection;
                    try {
                        const start = Date.now();
                        // Note: we need tp remove the injected parameter 0.
                        params.splice(0, 1);
                        const result = await rpcWorkspaceConnection.sendRequest(method, params);
                        const time = (Date.now() - start).toFixed(1);
                        this.logger.info(
                            `remote rpc request method: "${method}" result: "${TraceFormat.stringify(
                                result
                            )}" workspace: "${
                                workspaceConnection.workspaceId
                            }" rpc session #${rpcSessionNumber}
                            t:${time}`
                        );
                        return result;
                    } catch (err) {
                        this.logger.error(`failed to handle request for method:${method}`, err);
                        throw err;
                    }
                }
            }

            this.logger.warning(
                `no joined connections found to handle request for method:${method}`
            );
        });

        this.rpcServer.onRpcConnectionDisposed((rpcConnection) => {
            for (const workspaceConnection of this.workspaceConnections.values()) {
                workspaceConnection.onRpcConnectionDisposed(rpcConnection);
            }
        });
    }

    public async dispose(): Promise<void> {
        for (const workspaceConnection of this.workspaceConnections.values()) {
            workspaceConnection.disconnect();
        }

        this.workspaceConnections.clear();
        return;
    }

    public async getSessionInfoAsync(
        workspaceId: string,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<vsls.WorkspaceSessionInfo | undefined> {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        const workspaceConnection = this.workspaceConnections.get(workspaceId);
        this.logger.info(
            `-> getSessionInfo workspaceId:${workspaceId} session:${
                rpcRequestContext.session
            } found:${workspaceConnection ? 'true' : 'false'}`
        );

        if (workspaceConnection) {
            workspaceConnection.addJoinedConnection(rpcRequestContext);
            return workspaceConnection.workspaceSessionInfo;
        }

        return undefined;
    }

    public async joinAsync(
        joinConnectOptions: ILiveShareConnectionOptions,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<vsls.WorkspaceSessionInfo> {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        const workspaceId = joinConnectOptions.workspaceId;
        assertDefined(workspaceId, 'workspace id needs to be defined');

        this.logger.info(`-> join workspaceId:${workspaceId} session:${rpcRequestContext.session}`);

        try {
            const connection = await this.connectionHub.connectOnce(joinConnectOptions);
            let workspaceConnection = this.workspaceConnections.get(workspaceId);
            if (!workspaceConnection) {
                this.logger.info(`adding workspace connection for workspaceId:${workspaceId}`);

                workspaceConnection = new WorkspaceConnection(
                    workspaceId,
                    connection,
                    this,
                    this.logger.withName(`WorkspaceConnection:${workspaceId}`)
                );
                this.workspaceConnections.set(workspaceId, workspaceConnection);

                workspaceConnection.addToDisposables(
                    workspaceConnection.onDispose(() => {
                        this.workspaceConnections.delete(workspaceId);
                    })
                );
            } else {
                // the workspace connection already exists from a previous join, let's check if it is healthy
                await workspaceConnection.checkConnection(cancellationToken);
            }

            workspaceConnection.addJoinedConnection(rpcRequestContext);
            return workspaceConnection.workspaceSessionInfo;
        } catch (err) {
            if (err instanceof ConnectionError) {
                this.throwRpcError(workspaceId, err.originalError);
            } else {
                this.throwRpcError(workspaceId, err);
            }

            throw err;
        }
    }

    /**
     * Convert some well known errors into RPC error code that can be properly
     * deserialized on the client side.
     * @param workspaceId The reference workspace id.
     * @param err A
     */
    private throwRpcError(workspaceId: string, err: any) {
        if (err instanceof NoHostConnectedError) {
            throw new rpc.ResponseError(RPC_ERR_NO_HOST_NOT_CONNECTED, err.message, workspaceId);
        } else if (err instanceof RelayConnectionError) {
            throw new rpc.ResponseError(
                RPC_ERR_RELAY_CONNECTIONY_SSH,
                err.message,
                err.errorContext
            );
        }
    }

    public readonly onHostConnectionChanged = this.onHostConnectionChangedEmitter.event;

    public readonly onWorkspaceMetricsUpdated = this.onWorkspaceMetricsUpdatedEmitter.event;

    public async disconnectAsync(
        workspaceId: string,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<void> {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        this.logger.info(
            `disconnect workspaceId:${workspaceId} session:${rpcRequestContext.session}`
        );
        const workspaceConnection = this.workspaceConnections.get(workspaceId);

        assertDefined(workspaceConnection, `Workspace id:${workspaceId} not found.`);

        await workspaceConnection.disconnect(rpcRequestContext.connection);
    }

    public async openStreamingChannelAsync(
        workspaceId: string,
        streamId: string,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<void> {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        this.logger.info(
            `open stream channel workspaceId:${workspaceId} streamId:${streamId} session:${rpcRequestContext.session}`
        );

        const workspaceConnection = this.workspaceConnections.get(workspaceId);

        assertDefined(workspaceConnection, `Workspace id:${workspaceId} not found.`);

        await workspaceConnection.openStreamingChannel(
            streamId,
            rpcRequestContext.connection,
            cancellationToken
        );
    }

    public async keepAliveAsync(
        time?: number,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ) {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        this.logger.info(`keep alive time:${time} session:${rpcRequestContext.session}`);
        this.keepAliveCallback(time);
        return;
    }

    public async checkConnectionAsync(
        workspaceId: string,
        cancellationToken?: rpc.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<void> {
        assertDefined(rpcRequestContext, rpcContextExpectedMessage);

        const workspaceConnection = this.workspaceConnections.get(workspaceId);
        if (workspaceConnection) {
            await workspaceConnection.checkConnection(cancellationToken);
        } else {
            throw new Error(`workspace id:${workspaceId} not found`);
        }
    }

    public async setCheckConnectionOptionsAsync(
        workspaceId: string,
        options: CheckConnectionOptions
    ): Promise<void> {
        this.logger.info(
            `setCheckConnectionOptionsAsync workspaceId:${workspaceId} options:${JSON.stringify(
                options
            )}`
        );
        const workspaceConnection = this.workspaceConnections.get(workspaceId);
        if (workspaceConnection) {
            await workspaceConnection.workspaceClient.setCheckConnectionOptions(options);
        } else {
            throw new Error(`workspace id:${workspaceId} not found`);
        }
    }

    /**
     * Return the current multi channel stream request
     */
    public _getRequestMultiChannelStream(
        rpcConnection: rpc.MessageConnection
    ): MultiChannelStream | undefined {
        return this.rpcServer.getMultiChannelStream(rpcConnection);
    }

    public _removeWorkspaceConnection(workspaceId: string): boolean {
        return this.workspaceConnections.delete(workspaceId);
    }

    public _fireHostConnectionChanged(e: WorkspaceHostConnectionChanged) {
        this.onHostConnectionChangedEmitter.fire(e);
    }

    public _fireWorkspaceMetricsUpdated(e: RemoteWorkspaceMetricsUpdated) {
        this.onWorkspaceMetricsUpdatedEmitter.fire(e);
    }
}
