'use strict';

import * as vscode from 'vscode';
import * as uuid from 'uuid';
import { vsls } from '@vs/vsls-contracts';
import { IInittableDisposable } from '@vs/vscode-command-framework';
import { IRpcRequestContext, IRpcServiceHandler, IRpcServiceHandlerInfo, rpcMaxMessageSize } from '@vs/vso-rpc';
import { TraceSource } from '@vs/vso-logging';
import { IPathManager } from '../IPathManager';
import { Lazy } from '../Lazy';
import { IClientAccessCheck } from '../contracts/IClientAccessCheck';
import { PathManager } from '../PathManager';
import { PathUtil } from '../utils/PathUtil';
import { TextSearchService } from './TextSearchService';

function constructExternalRemotePathFromLocalPath(localPath: string) {
    localPath = vscode.Uri.parse(localPath).path;
    const fileName = localPath.substr(localPath.lastIndexOf('/') + 1);
    return `${PathManager.externalPrefix}/${uuid()}/${fileName}`;
}

function isExternalVslsPath(path: string) {
    return path.startsWith(PathManager.externalPrefix)
            && path.length > (PathManager.externalPrefix.length + 1);
}

export interface IFileService extends vsls.FileService, IInittableDisposable {}
export class FileService extends TextSearchService implements IFileService, IRpcServiceHandlerInfo {

    private disposables: vscode.Disposable[] = [];

    private readonly localPathsToVslsPaths = new Map<string, string>();
    private readonly vslsPathsToLocalPaths = new Map<string, string>();

    constructor(
        private rpcServiceHandler: IRpcServiceHandler,
        private workspaceService: vsls.WorkspaceService,
        pathManager: IPathManager,
        private clientAccessCheck: Lazy<IClientAccessCheck>,
        trace: TraceSource,
        private readonly hostSessionId?: number
    ) {
        super(pathManager, trace);
    }

    public serviceInfo = vsls.FileService;

    public contextMethods = ['registerExternalFiles', 'writeText', 'createDirectory', 'delete', 'move'];

    private getLocalUri(path: string) {
        let localUri: vscode.Uri;
        if (isExternalVslsPath(path)) {
            if (!this.vslsPathsToLocalPaths.has(path)) {
                throw new Error('External file has not been registered');
            } 
            const localPath = this.vslsPathsToLocalPaths.get(path);
            localUri = vscode.Uri.parse(localPath);
        } else {
            localUri = vscode.Uri.joinPath(vscode.workspace.workspaceFolders[0].uri, path);
        }
        return localUri;
    }

    public async init(): Promise<void> {
        await this.workspaceService.registerServicesAsync([vsls.FileService.name], vsls.CollectionChangeType.Add);

        this.disposables.push(this.rpcServiceHandler.registerRpcService(
            this,
            this.serviceInfo,
            this.contextMethods
        ));
    } 

    public async registerExternalFilesAsync(
        localPaths: string[],
        context?: any,
        cancellationToken?: vscode.CancellationToken,
        rpcRequestContext?: IRpcRequestContext
    ): Promise<string[]> {

        if (this.hostSessionId && rpcRequestContext?.session !== this.hostSessionId) {
            throw new Error('Invalid rpc request. This method is allowed only by the host session');
        } else if (this.hostSessionId === undefined && context) {
            throw new Error('Cannot register external files');
        }

        const localPathsToRegister: string[] = [];
        const vslsPathsToRegister: string[] = [];

        for (let localPath of localPaths) {
            if (!this.localPathsToVslsPaths.has(localPath)) {
                const normalizedLocalPath = PathUtil.normalizePath(localPath);
                const vslsPath = constructExternalRemotePathFromLocalPath(normalizedLocalPath);
                this.localPathsToVslsPaths.set(localPath, vslsPath);
                this.vslsPathsToLocalPaths.set(vslsPath, localPath);
                localPathsToRegister.push(normalizedLocalPath);
                vslsPathsToRegister.push(vslsPath);
            }
        }

        if (localPathsToRegister.length > 0) {
            this.onExternalFilesChangedEmitter.fire({
                changeType: vsls.CollectionChangeType.Add,
                localPaths: localPathsToRegister,
                vslsPaths: vslsPathsToRegister
            });
        }

        return localPaths.map(localPath => this.localPathsToVslsPaths.get(localPath));
    }

    public async listRootsAsync(
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileRootInfo[]> {
        const roots = [];
        if (vscode.workspace.workspaceFolders !== undefined) {
            for (const folder of vscode.workspace.workspaceFolders) {
                const root: vsls.FileRootInfo = {
                    fullPath: folder.uri.toString(),
                    path: '/',
                    friendlyName: folder.name,
                };
                roots.push(root);
            }
        }

        return roots;
    }

    public async listAsync(
        paths: string[],
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileInfo[]> {
        const fileInfos: vsls.FileInfo[] = [];

        for (const path of paths) {
            const uri = this.getLocalUri(path);

            let stat: vscode.FileStat;
            try {
                stat = await vscode.workspace.fs.stat(uri);
            } catch { }

            const childrenInfos = [];
            if (stat?.type === vscode.FileType.Directory) {
                const children = await vscode.workspace.fs.readDirectory(uri);
                for (const child of children) {
                    const childInfo: vsls.FileInfo = {
                        path: vscode.Uri.joinPath(uri, child[0]).path,
                        exists: true,
                        isDirectory: child[1] === vscode.FileType.Directory,
                    };
                    childrenInfos.push(childInfo);
                }
            }

            const fileInfo: vsls.FileInfo = {
                path: path,
                exists: stat !== undefined,
                isDirectory: stat?.type === vscode.FileType.Directory,
                hasChildren: childrenInfos.length !== 0,
                children: childrenInfos,
            };

            fileInfos.push(fileInfo);
        }

        return fileInfos;
    }

    public async readTextAsync(
        path: string,
        options: vsls.FileReadOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileTextInfo> {
        try {
            const uri = this.getLocalUri(path);
            const contents = await vscode.workspace.fs.readFile(uri);
            const fileTextInfo = { path: path, text: contents.toString() };
            return fileTextInfo;    
        } catch (err) {
            if (err?.code === 'FileNotFound') {
                return <vsls.FileTextInfo> {
                    path,
                    exists: false,
                };
            } else {
                throw err;
            }
        }
    }

    public async readTextWithProgressAsync(
        paths: string[],
        options: vsls.FileReadOptions,
        progress: vscode.Progress<vsls.ReadTextResult>,
        cancellationToken?: vscode.CancellationToken)
        : Promise<vsls.FileTextInfo[]> {

        const allFileTextInfos = await Promise.all(paths.map(p => this.readTextAsync(p, options, cancellationToken)));
        const resultTextInfos: vsls.FileTextInfo[] = [];

        let progressCount = 0;
        let contentSize = 0;
        let reportFileTextInfos: vsls.FileTextInfo[] = [];
        const reportProgress = () => {
            if (reportFileTextInfos.length > 0) {
                progress.report({
                    results: reportFileTextInfos,
                });
            }
        };

        // Note: next iteration will make sure we never exceed the max file content sie
        // we can reach since we have a known rpc limit for the packet size.
        allFileTextInfos.forEach(textInfo => {
            if (progressCount === 0) {
                resultTextInfos.push(textInfo);
            } else {
                reportFileTextInfos.push(textInfo);
            }
            
            contentSize += textInfo.text?.length ?? 0;
            if (contentSize > rpcMaxMessageSize) {
                ++progressCount;
                reportProgress();
                contentSize = 0;
                reportFileTextInfos = [];
            }
        });

        // report if neded after processing.
        reportProgress();

        return resultTextInfos;
    }

    public async writeTextAsync(
        path: string,
        text: string,
        options: vsls.FileWriteOptions,
        context: any,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileInfo> {
        if (await this.clientAccessCheck().isClientReadOnly(context)) {
            throw new Error('Read-only clients cannot create files');
        }
        const uri = this.pathManager.relativePathToLocalPath(path);
        await vscode.workspace.fs.writeFile(uri, (new TextEncoder()).encode(text));
        return {
            path
        };
    }

    public async createDirectoryAsync(
        path: string,
        context: any,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileInfo> {
        if (await this.clientAccessCheck().isClientReadOnly(context)) {
            throw new Error('Read-only clients cannot create directories');
        }
        const uri = this.pathManager.relativePathToLocalPath(path);
        await vscode.workspace.fs.createDirectory(uri);
        return {
            path
        };
    }

    public async deleteAsync(
        path: string,
        options: vsls.FileDeleteOptions,
        context: any,
        cancellationToken?: vscode.CancellationToken
    ): Promise<void> {
        if (await this.clientAccessCheck().isClientReadOnly(context)) {
            throw new Error('Read-only clients cannot delete files');
        }
        const uri = this.pathManager.relativePathToLocalPath(path);
        try {
            await vscode.workspace.fs.delete(uri, { useTrash: options.useTrash });
        } catch {
            // The delete can fail if the virtual file system does not support the useTrash option
            await vscode.workspace.fs.delete(uri);
        }
    }

    public copyAsync(
        sourcePath: string,
        targetPath: string,
        options: vsls.FileMoveOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileInfo> {
        throw new Error('Method not implemented.');
    }

    public async moveAsync(
        sourcePath: string,
        targetPath: string,
        options: vsls.FileMoveOptions,
        context: any,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.FileInfo> {
        if (await this.clientAccessCheck().isClientReadOnly(context)) {
            throw new Error('Read-only clients cannot move files');
        }
        const sourceUri = this.pathManager.relativePathToLocalPath(sourcePath);
        const targetUri = this.pathManager.relativePathToLocalPath(targetPath);
        await vscode.workspace.fs.rename(sourceUri, targetUri, { overwrite: options.overwrite });
        return {
            path: targetPath
        };
    }

    public async getFilesAsync(
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<string[]> {
        const uris = await vscode.workspace.findFiles('**/*', `{**/.git,**/.svn,**/.hg,**/CVS,**/.DS_Store,**/node_modules,**/bower_components,**/*.code-search}`);
        const relativePaths = uris.map(uri => this.pathManager.localPathToRelativePath(uri));
        return relativePaths;
    }

    public async isExcludedAsync(
        path: string,
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<boolean> {
        return false;
    }

    public async findFilesAsync(
        query: string,
        options: vsls.FileListOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<string[]> {
        return [];
    }

    public async clearRootsAsync(cancellationToken?: vscode.CancellationToken): Promise<void> {
        return;
    }

    public addRootAsync(
        rootDir: string,
        cancellationToken?: vscode.CancellationToken
    ): Promise<void> {
        throw new Error('Method not implemented.');
    }

    public removeRootAsync(
        rootDir: string,
        cancellationToken?: vscode.CancellationToken
    ): Promise<void> {
        throw new Error('Method not implemented.');
    }

    public replaceRootAsync(
        rootDir: string,
        cancellationToken?: vscode.CancellationToken
    ): Promise<void> {
        throw new Error('Method not implemented.');
    }

    private onFilesChangedEmitter = new vscode.EventEmitter<vsls.FilesChangedEventArgs>();
    public onFilesChanged: vscode.Event<vsls.FilesChangedEventArgs> = this.onFilesChangedEmitter.event;
    private onRootsChangedEmitter = new vscode.EventEmitter<vsls.RootsChangedEventArgs>();
    public onRootsChanged: vscode.Event<vsls.RootsChangedEventArgs> = this.onRootsChangedEmitter.event;
    private onExternalFilesChangedEmitter = new vscode.EventEmitter<vsls.ExternalFilesChangedEventArgs>();
    public onExternalFilesChanged: vscode.Event<vsls.ExternalFilesChangedEventArgs> = this.onExternalFilesChangedEmitter.event;

    public async dispose(): Promise<void> {
        await this.workspaceService.registerServicesAsync([vsls.FileService.name], vsls.CollectionChangeType.Remove);
        for (const disposable of this.disposables) {
            disposable.dispose();
        }
        this.disposables = [];
    }
}
