import * as nls from 'vscode-nls';
import * as vscode from 'vscode';
import * as path from 'path';
import * as url from 'url';
import { fileAccess, ICommandContext } from '@vs/vscode-command-framework';
import { localize, UserError } from '@vs/liveshare-core';

import { vsls } from '@vs/vsls-contracts';
import * as config from '../../config';
import { Key as ConfigKey } from '../../config';
import { WORKSPACE_TEMP_FOLDER_NAME_PREFIX, LIVESHARE_WORKSPACE_TEMP_DIR } from '../../constants';
import { WorkspaceDefinition, WorkspaceManager } from '../../workspace/workspaceManager';

import { IDependencies } from '../IDependencies';
import { dependencies } from '../Dependencies';
import { firstRunTrackingCommandDecorator } from '../decorators/FirstRunTrackingCommandDecorator';
import { infoPageCommandDecorator } from '../decorators/InfoPageCommandDecorator';
import { CancellationError } from '@vs/vscs-utils';
import { ExtensionUtil } from '../../extensionUtil';

import { JoinCommandUtilities } from './JoinCommandUtilities';

import {
    TelemetryEvent, 
} from '@vs/vso-telemetry';

import {
    SessionAction,
    ISessionContext,
    userAuthStateTracker,
    sessionStateTracker,
    CommandId,
    TelemetryEventNames,
    TelemetryPropertyNames,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    ICommand,
    ByDesignError,
    sessionStateTransitionsCommandDecorator,
    authenticationCommandDecorator, IAuthenticationDecoratorOptions,
    validationCommandDecorator,
    setAuthReloadFlag,
    SignInReloadMode,
    ISignInReloadInfo,
    IClipboardUtil,
    JoinCommandUtilities as JoinCommandUtilitiesCore,
    featureFlags,
    WelcomePageSource,
    JoinCommandOptions,
    Settings
} from '@vs/liveshare-core';

export function builder(deps: IDependencies): JoinPreReloadCommand {
    return new JoinPreReloadCommand(
        deps.sessionContext(),
        deps.clipboardUtil(),
        WorkspaceDefinition,
        WorkspaceManager.createWorkspace,
        deps.workspaceService(),
        deps.agentSessionService(),
        setAuthReloadFlag);
}

const askToSignIn = async (message: string, options: JoinCommandOptions | string | vscode.Uri) => {
    const notificationUtil = dependencies.notificationUtil();
    const signInItem = { title: 'Sign In' };

    const questionResult = await notificationUtil.showInformationMessage(message, false, signInItem);

    // if user picked the `sign in` button
    if (questionResult && (questionResult.title === signInItem.title)) {
        if (typeof options === 'string' || options instanceof vscode.Uri) {
            options = { link: options };
        } else if (!options) {
            options = {};
        }

        const joinCommandOptions: JoinCommandOptions = {
            ...options,
            isAllowAnonymous: false,
        };

        await vscode.commands.executeCommand(`${config.get<string>(config.Key.commandPrefix)}.join`, joinCommandOptions);
    }
};

const onError = async (error: any, context: ICommandContext, options: any) => {
    dependencies.sessionContext().notJoining();

    switch (error.code) {
        // if failed after user was rejected due to being anonymous, we ask them to sign in
        case vsls.ErrorCodes.ForbiddenHttpStatusCode: {
            await askToSignIn(`${context.commandName}: the host doesn’t allow anonymous guests. Please sign-in to proceed.`, options);
            break;
        }
        default: { }
    }
};

const validateSessionAction = (options: any): boolean => {
    // If this is a join in new window command
    // ignore state transitions as they will
    // put the parent vscode instance in an incorrect state.
    return !(options && options.newWindow);
    // The host doesn’t allow anonymous guests. Please sign-in to proceed.
};

// TODO: Save the command that we want to run when the reload happens
// TODO: Save the ID of the named pipe so we can reconnect to agent

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.AttemptJoining,
    authAttemptMax: 2,
    validateSessionAction
};

/**
 * Join `command` that triggers an updates to the current workspace so
 * that the user can join a workspace.
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Joining collaboration session', TelemetryEventNames.JOIN_FAULT, false, onError)
@firstRunTrackingCommandDecorator(ConfigKey.commandFirstRunTrackingJoin)
@telemetryCommandDecorator(TelemetryEventNames.PRE_RELOAD_WORKSPACE, TelemetryEventNames.JOIN_FAULT, 'Join', 1)
@telemetryStatusCommandDecorator()
@validationCommandDecorator()
@sessionStateTransitionsCommandDecorator(SessionAction.AttemptJoining, SessionAction.JoiningPendingReload, SessionAction.JoiningError, validateSessionAction)
@infoPageCommandDecorator(WelcomePageSource.FirstJoin)
@authenticationCommandDecorator(authOptions)
export class JoinPreReloadCommand implements ICommand<boolean> {

    constructor(
        private readonly sessionContext: ISessionContext,
        private readonly clipboardUtil: IClipboardUtil,
        private readonly workspaceDefinitionClass: typeof WorkspaceDefinition,
        private readonly createWorkspace: Function,
        private readonly workspaceService: vsls.WorkspaceService,
        private readonly agentSessionService: vsls.AgentSessionService,
        private readonly setAuthReloadFlagFunction: (signInInfo: ISignInReloadInfo, mode: SignInReloadMode) => Promise<void>
    ) {
    }

    public async invoke(
        options: JoinCommandOptions | string | vscode.Uri,
        context: ICommandContext,
    ): Promise<boolean> {
        if (typeof options === 'string' || options instanceof vscode.Uri) {
            options = { link: options };
        } else if (!options) {
            options = {};
        }

        const { telemetryEvent } = context;

        // correlate pre-reload event with initiate-session event
        const { correlationId } = options;
        telemetryEvent.correlateWithId(correlationId);

        telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_WITH_LINK, (options.link ? 'True' : 'False'));

        let workspaceInfo;
        try {
            workspaceInfo = await this.getWorkspaceInfo(options, context);
            // check if it is planned sessions
            let checkExpiration = workspaceInfo.expiresAt;
            if (workspaceInfo !== null && checkExpiration !== undefined) {
                // when guest of the persistent workspace "joins" the session we count this as "join" and send join-persistent-workpsace" event.
                telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_PLANNED_SESSION, 'true');
            }
        } catch (e) {
            if (e.code === vsls.ErrorCodes.ForbiddenHttpStatusCode) {
                e.isSuppressUserNotification = true;
            }

            throw e;
        }

        if (!workspaceInfo) {
            return false;
        }
    
        const isNewWindow = config.get<boolean>(config.Key.joinInNewWindow) || (options && options.newWindow);
        const isBrokenLiveshareWorkspaceFile = JoinCommandUtilitiesCore.isBrokenLiveshareWorkspaceFile(vscode.workspace);

        if (isBrokenLiveshareWorkspaceFile && !isNewWindow) {
            telemetryEvent.addProperty('isRestoredWorkspace', true);
            await JoinCommandUtilitiesCore.restoreLiveshareWorkspaceState(workspaceInfo.id, workspaceInfo.name);
            return true;
        }

        sessionStateTracker.point(TelemetryPropertyNames.GET_WORKSPACE_COMPLETE);

        const workspaceFolder = await this.createWorkspaceTemporaryFolder(workspaceInfo, isNewWindow);
        const workspaceFilePath = ExtensionUtil.getWorkspaceFilePath(workspaceFolder);
        // TODO: consult with Anthony about the function injection
        await this.createWorkspace(workspaceFilePath, this.createWorkspaceDefinition(workspaceInfo, workspaceFolder));
        await this.stashConfigSettings(workspaceFilePath, telemetryEvent.getCorrelationId());

        const workspaceFileUri = vscode.Uri.file(workspaceFilePath);

        // Reloads the workpace
        telemetryEvent.addProperty(TelemetryPropertyNames.JOIN_WITHOUT_RELOAD, 'False');
        // if user is anonymous, we already asked them if they want to sign
        // in and they picked a name in the anonymous case, so set the flag to not ask them again after the reload
        if (userAuthStateTracker.isCurrentUserAnonymous()) {
            const signInInfo: ISignInReloadInfo = { workspaceId: workspaceInfo.id };
            await this.setAuthReloadFlagFunction(signInInfo, SignInReloadMode.Anonymous);
        } else if (userAuthStateTracker.isCustomAccount) {
            const signInInfo: ISignInReloadInfo = { account: userAuthStateTracker.userInfo.accountId, providerName: userAuthStateTracker.userInfo.providerName };
            await this.setAuthReloadFlagFunction(signInInfo, SignInReloadMode.CustomAccount);
        }

        if (!options.newWindow) {
            // When joining in the same window, enable reconnecting to the agent session to save time.
            const reconnectId = await this.agentSessionService.enableReconnectAsync();
            Settings.saveMemento(workspaceInfo.id + '-reconnectId', reconnectId);
        }

        // save invitation link
        JoinCommandUtilitiesCore.setInviteLinkJoining(workspaceInfo.id, options, context);

        vscode.commands.executeCommand('vscode.openFolder', workspaceFileUri, isNewWindow);

        return false;
    }

    private async stashConfigSettings(workspaceFilePath: string, correlationId: string) {
        // update the config before reload
        await config.save(config.Key.joinWorkspaceLocalPath, workspaceFilePath, true, true);
        await config.save(config.Key.joinEventCorrelationId, correlationId, true, true);
        await config.save(config.Key.workspaceReloadTime, Date.now(), true);
    }

    private createWorkspaceDefinition(workspaceInfo: vsls.WorkspaceInfo, workspaceFolder: string): WorkspaceDefinition {
        const workspaceDefinition = new this.workspaceDefinitionClass();

        workspaceDefinition.folders.push({
            uri: `${config.get<string>(config.Key.scheme)}:/`,
            name: (workspaceInfo.name || 'Loading file tree...')
        });

        workspaceDefinition.transient = true;

        workspaceDefinition.settings = {
            [CommandId.joinWorkspaceIdSettingName]: workspaceInfo.id,
            [CommandId.joinWorkspaceIdFolderSettingName]: workspaceFolder,
            ['files.hotExit']: 'off'
        };

        return workspaceDefinition;
    }

    private async createWorkspaceTemporaryFolder(workspaceInfo: vsls.WorkspaceInfo, isNewWindow: boolean): Promise<string> {
        let workspaceFolder = path.join(LIVESHARE_WORKSPACE_TEMP_DIR, `${WORKSPACE_TEMP_FOLDER_NAME_PREFIX}${workspaceInfo.id}`);

        if (isNewWindow) {
            workspaceFolder += `_${Date.now()}`;
        }

        await fileAccess.ensureDirAsync(workspaceFolder);

        return workspaceFolder;
    }

    private async getWorkspaceInfo(options: JoinCommandOptions, context: ICommandContext): Promise<vsls.WorkspaceInfo | undefined> {

        let collaborationLink;
        let workspaceInfo;
        let workspaceId: string;

        if (options.link == null) {
            collaborationLink = await this.getCollaborationLink(options);
            workspaceInfo = await this.getValidWorkspaceFromLink(collaborationLink);
        } else {
            collaborationLink = options.link.toString().trim();
            workspaceId = JoinCommandUtilitiesCore.extractLiveshareWorkspaceId(collaborationLink);
            workspaceInfo = await this.workspaceService.getWorkspaceAsync(workspaceId);

            if (workspaceInfo) {
                // Use the same workspace id that is part of the join link otherwise user will not be able to connect to the workspace.
                // Join link id and workspace id will be different for invitation links
                workspaceInfo.id = workspaceId;
            }
        }

        if (!workspaceInfo) {
            throw new UserError(localize('CollaborationSessionNoLongerActive'));
        } else if (workspaceInfo.isHostConnected === false) {

            if (!featureFlags.waitForHost) {
                throw new ByDesignError(localize('HostNotPresent'));
            }

            const { telemetryEvent } = context;

            telemetryEvent.addProperty(TelemetryPropertyNames.WAIT_FOR_HOST_PROMPT, 'True');

            const isHostAvailable = await JoinCommandUtilitiesCore.showWaitingForHostProgressBar(dependencies, () => this.workspaceService.getWorkspaceAsync(workspaceId), 15, context);

            if (isHostAvailable) {
                return await this.workspaceService.getWorkspaceAsync(workspaceId);
            } else {
                // Add retry button
                const notificationUtil = dependencies.notificationUtil();

                const retryButton = {id: 1, 
                    title: localize('Join.Retry')};

                let buttons = [retryButton];

                const result = await notificationUtil.showInformationMessage(
                    ('The host is unavailable. Contact them and try joining the session again.'), true,
                    ...buttons);

                // Return if user closes the notification
                if (!result) {
                    return;
                }

                if (result.id === retryButton.id) {
                    telemetryEvent.addProperty(TelemetryPropertyNames.RETRY_JOIN, 'True');
                    await JoinCommandUtilities.invokeJoinCommand(options, context);
                    return;
                }
            }
        }
        
        return workspaceInfo;
    }

    private async getCollaborationLink(options: JoinCommandOptions): Promise<string> {
        let collaborationLink = options.link;

        if (!collaborationLink) {
            let clipboardValue = '';
            try {
                clipboardValue = await this.clipboardUtil.pasteFromClipboardAsync();
                clipboardValue = clipboardValue.trim();
            } catch (e) { }

            collaborationLink = await vscode.window.showInputBox({
                prompt: 'Enter the URL of the collaboration session to join',
                ignoreFocusOut: true,
                value: JoinCommandUtilitiesCore.extractLiveshareLink(clipboardValue)
            });

            if (!collaborationLink) {
                // The user cancelled out of the input dialog.
                throw new CancellationError('Operation cancelled @ getcollaboration session URL dialog.');
            }

            options.link = collaborationLink;
        }

        return collaborationLink.toString().trim();
    }

    private async getValidWorkspaceFromLink(collaborationLink: string): Promise<vsls.WorkspaceInfo | undefined> {
        const liveshareLink = JoinCommandUtilitiesCore.extractLiveshareLink(collaborationLink);

        if (!liveshareLink) {
            if (collaborationLink) {
                const linkLength = collaborationLink.length.toString();
                const domainName = url.parse(collaborationLink).hostname;
                const containsLiveShare = collaborationLink.indexOf('liveshare').toString();

                TelemetryEvent.create(TelemetryEventNames.PASTE_INVALIDLINK_FAULT, {
                    properties: {
                        domainName, linkLength, containsLiveShare
                    }
                }).send();
            }
            throw new Error(localize('InvalidLiveShareURL'));
        }

        const workspaceId = JoinCommandUtilitiesCore.extractLiveshareWorkspaceId(liveshareLink);

        const workspace = await this.workspaceService.getWorkspaceAsync(workspaceId);

        if (!workspace || !workspace.joinUri) {
            // No workspace or joinUri found - handle the error from the caller
            return undefined;
        }

        const { hostname: linkHostname } = url.parse(liveshareLink);
        const { hostname: workspaceHostname } = url.parse(workspace.joinUri);

        if (linkHostname !== workspaceHostname) {
            throw new Error(localize('InvalidHostname'));
        }

        return workspace;
    }
}
