import * as vscode from 'vscode';
import * as path from 'path';

import { TreeDataProviderContext } from './ExtensionTreeDataProvider';
import { TreeDataProviderBase } from './TreeDataProviderBase';
import { TreeViewItemOptions, TreeViewItem } from './TreeViewItem';
import { ISessionContext } from '../ISessionContext';
import { IContactManager } from '../contracts/IContactManager';
import { IClientAccessCheck } from '../contracts/IClientAccessCheck';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { CollaboratorChangedEventArgs } from '../SessionTypes';
import { ICoEditing } from '../coediting/ICoEditing';
import { Lazy } from '../Lazy';

import { vsls } from '@vs/vsls-contracts';
import { localize } from '../localize';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { PathManager } from '../PathManager';
import { getExpService } from '../exp/ExperimentationService';
import { TreatmentVariables } from '../exp/TreatmentVariables';
import { ViewItem } from '@vs/liveshare-api-contracts';

import { getIconPathForUser } from '@core-abstractions/participantsIconProvider';

interface ParticipantSessionExplorerItemOptions extends TreeViewItemOptions {
    sessionId: number;
    contactId?: string;
    participantId?: string;
    tooltip?: string;
    description?: string;
}

export enum AnonymousAccessLevel {
    readOnly = 'readOnly',
    readWrite = 'readWrite'
}

export class ParticipantSessionExplorerItem extends TreeViewItem {
    public readonly sessionId: number;
    public readonly participantId: string;
    constructor(public readonly options: ParticipantSessionExplorerItemOptions) {
        super(options);
        this.sessionId = options.sessionId;
        this.participantId = options.participantId;
    }
}

interface IApprovedParticipant {
    sessionId: number;
    participant: vsls.WorkspaceUserProfile;
}

function getLocalizeInviteStatus(status: vsls.InviteContactStatus): string {
    // localize the invite status
    switch (status) {
        case vsls.InviteContactStatus.Invited:
            return localize('inviteContactStatus.invited');
        case vsls.InviteContactStatus.Dismissed:
            return localize('inviteContactStatus.dismissed');
        case vsls.InviteContactStatus.Joining:
            return localize('inviteContactStatus.joining');
        default:
    }
}

export enum ParticipantsViewItem {
    Participants = 'participants',

    InvitedContact = 'contacts.invited',

    // participants
    CurrentUser = 'participants.currentuser', // (not currently shown)
    Guest = 'participants.guest',
    FollowedGuest = 'participants.guest.followed',
    Participant = 'participants.participant',
    FollowedParticipant = 'participants.participant.followed',

    GuestAnonymous = 'participants.guest.anonymous',
    FollowedGuestAnonymous = 'participants.guest.followed.anonymous',

    GuestElevated = 'participants.guest.elevated',
    FollowedGuestElevated = 'participants.guest.followed.elevated',

    GuestElevatedAnonymous = 'participants.guest.elevated.anonymous',
    FollowedGuestElevatedAnonymous = 'participants.guest.followed.elevated.anonymous',
}

const schemeToLinePostfix = new Map<string, (range:vscode.Range) => string>([
    [PathManager.notebookCellScheme, () => '']
]);



export class ParticipantsTreeDataProvider extends TreeDataProviderBase {  
    constructor(
        private sessionContext: ISessionContext,
        private clientAccessCheck: Lazy<IClientAccessCheck>,
        private contactManager: IContactManager,
        protected isSessionExplorer: boolean) {
        super(ParticipantsViewItem.Participants, TreeDataProviderContext.SharedOrJoined);

        this.sessionContext.onCollaboratorChanged((e: CollaboratorChangedEventArgs) => {
            // performance optimizations to refresh only when users count actually change
            const isUserUnjoined = e && (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined);

            if (isUserUnjoined) {
                this.forceRefreshItems();
            }
        });

        this.sessionContext.onCollaboratorsJoined(() => {
            // This event is fired whenever a user has joined the session.
            // We refresh here, instead of catching this from onCollaboratorChanged event,
            // as we need coediting to receive the JoinRequest/JoinAcknowledge messages, which will
            // setup the sessionId to compute the list of participants.
            this.forceRefreshItems();
        });

        this.sessionContext.onAccessControlChanged(() => this.forceRefreshItems());

        contactManager.onInviteStatusChanged(() => this.forceRefreshItems());
    }

    public registerCoEditing(client: ICoEditing): vscode.Disposable {
        const disposables: vscode.Disposable[] = [];

        disposables.push(client.onPin(() => this.forceRefreshItems()));
        disposables.push(client.onUnpin(() => this.forceRefreshItems()));
        disposables.push(client.onFollowed(() => this.forceRefreshItems()));
        disposables.push(client.onUnfollowed(() => this.forceRefreshItems()));
        disposables.push(client.onUpdateCoEditorPosition(() => this.forceRefreshItems()));
        return vscode.Disposable.from(...disposables);
    }

    protected getRootItem(): Promise<TreeViewItem> {
        const approvedParticipants = this.getApprovedParticipants();

        const rootItem = new TreeViewItem({
            type: ParticipantsViewItem.Participants,
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            label: `Participants (${approvedParticipants.length})`
        });

        return Promise.resolve(rootItem);
    }

    protected async getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]> {
        const result: ParticipantSessionExplorerItem[] = [];
        //this.refreshArea &= ~SessionExplorerTree.Participants;

        if (!this.sessionContext.collaboratorManager) {
            return result;
        }

        let index = 0;
        const approvedParticipants = this.getApprovedParticipants();
        for (let approvedParticipant of approvedParticipants) {
            const { sessionId, participant } = approvedParticipant;

            result.push(await this.getParticipantRow(index++, sessionId, participant));
        }

        // Next block will 'inject' the pending invited contacts as early participants
        const invitesContacts = this.contactManager.invitedContacts;
        result.push(...invitesContacts.map(c => {
            return new ParticipantSessionExplorerItem({
                sessionId: undefined,
                contactId: c.id,
                type: ParticipantsViewItem.InvitedContact,
                label: `${c.contact.displayName} (${getLocalizeInviteStatus(c.inviteStatus)})`,
                iconPath: TreeDataProviderBase.getThemeIconPath('loading'),
            });
        }));

        return (result.length === 0)
            ? this.getDefaultParticipantsActions()
            : result;
    }

    private getDefaultParticipantsActions(): TreeViewItem[] {
        return [
            new TreeViewItem({
                type: ViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: 'Invite participants...',
                command: {
                    title: 'Invite participants...',
                    command: (this.isSessionExplorer)
                        ? 'liveshare.collaboration.link.copyFromFileTreeExplorer'
                        : 'liveshare.collaboration.link.copyFromActivityBar'
                }
            })
        ];
    }

    private getApprovedParticipants(): IApprovedParticipant[] {
        const result: IApprovedParticipant[] = [];

        const participants = this.sessionContext.collaboratorManager.getCollaborators();
        const participantIds = this.sessionContext.collaboratorManager.getCollaboratorSessionIds();

        for (let profileKey of participantIds) {
            const participant: vsls.WorkspaceUserProfile = participants[profileKey];
            const sessionId: number = profileKey;
            // if not current user or online host user
            if (participant && sessionId !== this.sessionContext.coeditingClient.clientID
                && !(participant.isHost && participant.isOnlineUser)) {
                result.push({
                    sessionId,
                    participant
                });
            }
        }

        return result;
    }

    private async getParticipantRow(rowIndex: number, sessionId: number, participant: vsls.WorkspaceUserProfile) {
        const name = participant.name || participant.userName || participant.email;

        const { positionTracker } = this.sessionContext.coeditingClient;
        const _fileTrackPosition = positionTracker.getClientPosition(sessionId);

        const fileTrackPosition = _fileTrackPosition?.documentPosition || _fileTrackPosition?.notebookPosition;

        let fileNamePostFix = '';
        let tooltipPostFix = '';
        if (fileTrackPosition && fileTrackPosition.fileName) {
            const range = fileTrackPosition.range;

            let linePostfix = '';

            if (schemeToLinePostfix.has(fileTrackPosition.documentUri.scheme)) { 
                linePostfix = schemeToLinePostfix.get(fileTrackPosition.documentUri.scheme)(range);
            } else {
                linePostfix = (range && range.start) ? `:${range.start.line + 1}` : '';
            }

            fileNamePostFix = ` •  ${path.basename(fileTrackPosition.documentUri.path)}${linePostfix}`;
            tooltipPostFix = ` • ${fileTrackPosition.documentUri.path}${linePostfix}`;      
        }
        // participant icon
        const { coeditingClient } = this.sessionContext;
        const followedUsers = coeditingClient.getUsersBeingFollowed();
        const isFollowing = (followedUsers[sessionId]);
       
        const iconPath = await getIconPathForUser(rowIndex, sessionId, isFollowing);

        const userItemType = await this.getUserTreeItemType(sessionId);
        const safeUserItemType = userItemType || '';
        // we use the `startsWith` because followed users can also have the `elevated` suffix
        const isFollowedParticipant = (safeUserItemType.startsWith(ParticipantsViewItem.FollowedGuest) || safeUserItemType.startsWith(ParticipantsViewItem.FollowedParticipant));

        const commandTitle = isFollowedParticipant ? 'Unfollow Participant' : 'Follow Participant';
        const commandPrefix = isFollowedParticipant ? 'liveshare.unfollow' : 'liveshare.follow';
        const commandSuffix = (this.isSessionExplorer)
            ? `FromFileTreeExplorer`
            : `FromActivityBar`;
        const command = `${commandPrefix}${commandSuffix}`;
        let label = await ExtensionUtil.getAnonymousReadOnlyLabel(this.clientAccessCheck(), participant, sessionId);
        let description = '';


        
        if (getExpService()?.getTreatmentVariable(TreatmentVariables.VSCodeConfig, TreatmentVariables.FollowIndicators) === true) {
            const usersFollowingYou = coeditingClient.getUsersFollowingYou();
            const isFollowingYou = usersFollowingYou.get(sessionId);
            if (isFollowing && isFollowingYou) {
                fileNamePostFix =  ` • following each other`;
            } else if (isFollowing) {
                fileNamePostFix =  ` •  following`;
            } else if (isFollowingYou) {
                fileNamePostFix =  ` • following you`;
            }

            description = label;
            label = '';
        }

        const row = new ParticipantSessionExplorerItem({
            sessionId,
            participantId: participant.id,
            type: userItemType,
            label: `${name}${label} ${fileNamePostFix}`,
            tooltip: `${name}${label} ${tooltipPostFix}`,
            description: description,
            iconPath,
            command: {
                title: commandTitle,
                command,
                arguments: [{ sessionId }]
            }
        });

        return row;
    }

    public isReadWriteAnonymousEnabled(): boolean | undefined {
        return getExpService()?.getTreatmentVariable('vscode', 'readWriteAnonymous');
    }

    private async getUserTreeItemType(sessionId: number): Promise<ParticipantsViewItem> {
        const { coeditingClient } = this.sessionContext;
        const { workspaceSessionInfo } = workspaceSessionInfoTracker;
        const { sessions } = workspaceSessionInfo;
        const followedUsers = coeditingClient.getUsersBeingFollowed();
        const followedUser = followedUsers[sessionId];
        const userProfile: vsls.UserInfo = sessions[sessionId];
        const isUserElevated = await this.clientAccessCheck().isClientExplicitlyReadWrite(sessionId);

        if (userProfile.isAnonymous) {
            const getAnonymousCurrentAccessLevel = workspaceSessionInfoTracker.getAnonymousAccess(userProfile.id);
            const isAnonymousElevated = this.isReadWriteAnonymousEnabled() && getAnonymousCurrentAccessLevel === AnonymousAccessLevel.readWrite;
            return this.getUserTreeItemTypeAnonymous(sessionId, isAnonymousElevated);
        }

        if (followedUser) {
            const guestFollowedItem = (isUserElevated)
                ? ParticipantsViewItem.FollowedGuestElevated
                : ParticipantsViewItem.FollowedGuest;

            return (coeditingClient.isHost)
                ? guestFollowedItem
                : ParticipantsViewItem.FollowedParticipant;
        }

        const guestItem = (isUserElevated)
                ? ParticipantsViewItem.GuestElevated
                : ParticipantsViewItem.Guest;

        return (coeditingClient.isHost)
            ? guestItem
            : ParticipantsViewItem.Participant;
    }

    private getUserTreeItemTypeAnonymous(sessionId: number, isUserElevated: boolean) {
        const { coeditingClient } = this.sessionContext;
        const followedUsers = coeditingClient.getUsersBeingFollowed();
        const followedUser = followedUsers[sessionId];

        if (followedUser) {
            const guestFollowedItem = (isUserElevated)
                ? ParticipantsViewItem.FollowedGuestElevatedAnonymous
                : ParticipantsViewItem.FollowedGuestAnonymous;

            return (coeditingClient.isHost)
                ? guestFollowedItem
                : ParticipantsViewItem.FollowedParticipant;
        }

        const guestElevatedItem =  (isUserElevated)
        ? ParticipantsViewItem.GuestElevatedAnonymous
        : ParticipantsViewItem.GuestAnonymous; 

        return (coeditingClient.isHost)
                ? guestElevatedItem
                : ParticipantsViewItem.Participant;
    }
}