import { IWorkspaceClient } from './IWorkspaceClient';
import { timeoutPromise, TIME_SECOND_MS, CancellationError } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import { CancellationTokenSource } from 'vscode-jsonrpc';

// timeout to wait to check to check the health of a connection
const defaultCheckConnectionTimeout = 10 * TIME_SECOND_MS;
// message to log and throw if timeout is reached
export const failedtoCheckConnectionMessage = 'failed to check connection';

const checkConnectionWithTimeoutMessage = 'checkConnectionWithTimeout';

/**
 * Check a workspace client by invoking the checkConnection method with a timeout
 * @returns false if the connection check failed or timeout.
 */
export const checkConnectionWithTimeout = async (
    workspaceClient: IWorkspaceClient,
    logger?: ILogger,
    checkConnectionTimeout?: number,
    cancellationTokenSource?: CancellationTokenSource
): Promise<boolean> => {
    const start = Date.now();
    const totalTime = () => {
        return (Date.now() - start).toFixed(1);
    };

    try {
        logger?.verbose(`${checkConnectionWithTimeoutMessage} -> 'started'`);

        await timeoutPromise(
            workspaceClient.checkConnection(),
            checkConnectionTimeout ?? defaultCheckConnectionTimeout,
            undefined,
            cancellationTokenSource
        );

        logger?.verbose(`${checkConnectionWithTimeoutMessage} -> 'succeeded' t:${totalTime()}`);

        return true;
    } catch (err) {
        if (err instanceof CancellationError) {
            logger?.verbose(`${checkConnectionWithTimeoutMessage} -> 'cancelled' t:${totalTime()}`);
            return true;
        }

        logger?.error(`${checkConnectionWithTimeoutMessage} -> 'failed' t:${totalTime()}`, err);
        return false;
    }
};
