'use strict';

import * as vscode from 'vscode';
import { tasks } from 'vscode';
import { ErrorCodes, ResponseError } from 'vscode-jsonrpc';
import * as config from '../config';
import { IRpcClient, RpcProxy } from '@vs/vso-rpc';
import { traceSource, Disposable, Inittable } from '@vs/vscode-command-framework';
import { TraceSource, errorToString } from '@vs/vso-logging';
import { WorkspaceTaskTelemetry } from '@vs/liveshare-tasks';
import { RemoteServiceTelemetry } from '../telemetry/remoteServiceTelemetry';
import { IDependencies } from '../_new_/IDependencies';
import { INotificationUtil } from '../_new_/abstractions/INotificationUtil';

import {
    Telemetry,
    FaultType
} from '@vs/vso-telemetry';

import {
    ISessionContext,
    IClientAccessCheck,
    GuestIdSessionContext,
    RestrictedOperation,
    WellKnownRestrictedOperations,
    TelemetryEventNames,
    Lazy,
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
interface TaskExecutionInfo {
    readonly execution: vscode.TaskExecution;
    readonly startTime: number;
}

interface SharedTaskOutput extends vscode.Disposable {
    readonly taskOutput: vsls.TaskOutputInfo;
    readonly streamId: string;
    readonly terminal: vscode.Terminal;
}

export class WorkspaceTaskService extends Inittable(Disposable(Object)) {
    private static readonly SERVICE_NAME: string = 'workspaceTask';
    private static readonly runTaskOperation: RestrictedOperation = {
        name: WellKnownRestrictedOperations.RunTask,
        isEnabled: () => WorkspaceTaskService.guestTaskControlAllowed || { errorCode: vsls.ErrorCodes.OperationRejected, errorMessage: 'Remote task execution is not allowed.' },
    };
    private static readonly terminateTaskOperation: RestrictedOperation = { name: WellKnownRestrictedOperations.TerminateTask };
    private static taskExecutionCounter: number = 0;
    private static sessionTaskControlAllowed: boolean;

    private readonly rpcClient: IRpcClient;
    private readonly workspaceService: vsls.WorkspaceService;
    private readonly clientAccessCheck: Lazy<IClientAccessCheck>;
    private readonly workspaceAccessControlService: Lazy<vsls.WorkspaceAccessControlService>;
    private readonly notificationUtil: Lazy<INotificationUtil>;
    private readonly taskOutputService: vsls.TaskOutputService;
    private readonly streamManagerService: vsls.StreamManagerService;
    private readonly streamService: vsls.StreamService;
    private readonly trace: TraceSource;
    private readonly sessionContext: ISessionContext;

    private readonly taskOutputCache: { [name: string]: SharedTaskOutput } = {};
    private readonly subscriptions: vscode.Disposable[] = [];
    private readonly taskExecutions: [vsls.TaskExecutionMoniker, TaskExecutionInfo][] = [];
    private readonly completedExecutions: [string, number][] = [];

    private deferredInit: Promise<void> = Promise.resolve();
    private dataProcessQueue: Promise<void> = Promise.resolve();

    private static get guestTaskControlAllowed() {
        return WorkspaceTaskService.sessionTaskControlAllowed || config.get<boolean>(config.Key.allowGuestTaskControl);
    }

    constructor(dependencies: IDependencies) {
        super();
        this.rpcClient = dependencies.rpcClient();
        this.workspaceService = dependencies.workspaceService();
        this.clientAccessCheck = dependencies.clientAccessCheck;
        this.workspaceAccessControlService = dependencies.workspaceAccessControlService;
        this.notificationUtil = dependencies.notificationUtil;
        this.taskOutputService = RpcProxy.create(vsls.TaskOutputService, this.rpcClient, traceSource.withName(vsls.TraceSources.ClientRpc));
        this.streamManagerService = RpcProxy.create(vsls.StreamManagerService, this.rpcClient, traceSource.withName(vsls.TraceSources.ClientRpc));
        this.streamService = RpcProxy.create(vsls.StreamService, this.rpcClient, traceSource.withName(vsls.TraceSources.ClientRpc));
        this.trace = traceSource.withName('WorkspaceTaskService');
        this.sessionContext = dependencies.sessionContext();

        WorkspaceTaskService.sessionTaskControlAllowed = false;
    }

    public async init(): Promise<void> {
        await super.init();

        this.subscriptions.push(
            tasks.onDidStartTask(e => this.handleTaskStarted(e.execution)),
            tasks.onDidEndTask(e => this.handleTaskEnded(e.execution)),
            this.workspaceAccessControlService().onOpeationAccessRequested(e => {
                if (e.operation.name === WellKnownRestrictedOperations.RunTask) {
                    this.grantRunTaskPermission(e.operation, e.sessionId);
                }
            }),
        );

        if (vscode.window.onDidOpenTerminal) {
            this.subscriptions.push(
                vscode.window.onDidOpenTerminal(async terminal => {
                    if (terminal.name.startsWith('Task')) {
                        await this.createTaskOutput(terminal);
                    }
                })
            );
        }

        this.deferredInit = this.deferredInit.then(() => this.initializeContext()).catch(() => { });
    }

    private async initializeContext(): Promise<void> {
        this.rpcClient.addRequestMethod(
            'workspaceTask.getSupportedTasks',
            () => this.getSupportedTasks()
        );

        this.rpcClient.addRequestMethod(
            'workspaceTask.getTaskExecutions',
            () => this.getTaskExecutions()
        );

        this.rpcClient.addRequestMethodWithContext(
            'workspaceTask.runTask',
            (taskNameOrUid: string, context: any) => this.runTask(taskNameOrUid, context)
        );

        this.rpcClient.addRequestMethod(
            'workspaceTask.terminateTask',
            (taskExecution: vsls.TaskExecutionMoniker, context: any) => this.terminateTask(taskExecution, context)
        );

        await this.workspaceService.registerServicesAsync(
            ['workspaceTask'],
            vsls.CollectionChangeType.Add
        );

        for (const terminal of vscode.window.terminals.filter(x => x.name.startsWith('Task'))) {
            await this.createTaskOutput(terminal);
        }
    }

    public async dispose(): Promise<void> {
        await this.deferredInit;

        this.subscriptions.forEach(d => d.dispose());

        Object.keys(this.taskOutputCache)
            .map(x => this.taskOutputCache[x])
            .forEach(d => d.dispose());

        await this.workspaceService.registerServicesAsync(
            ['workspaceTask'],
            vsls.CollectionChangeType.Remove);

        this.rpcClient.removeRequestMethod('workspaceTask.getSupportedTasks');
        this.rpcClient.removeRequestMethod('workspaceTask.getTaskExecutions');
        this.rpcClient.removeRequestMethod('workspaceTask.runTask');
        this.rpcClient.removeRequestMethod('workspaceTask.terminateTask');

        const v0: { [kind: string]: number[] } = {};
        const executionsByKind = this.completedExecutions.reduce((ebk, entry) => ({
            ...ebk,
            [entry[0]]: [...(ebk[entry[0]] || []), entry[1]],
        }), v0);
        Object.keys(executionsByKind).forEach(taskKind => {
            WorkspaceTaskTelemetry.sendExecutionSummary(taskKind, executionsByKind[taskKind]);
        });

        await super.dispose();
    }

    private async grantRunTaskPermission(operation: vsls.RestrictedOperation, sessionId: number): Promise<void> {
        try {
            const participant = this.sessionContext.collaboratorManager.getCollaborators()[sessionId.toString(10)];
            if (!participant) {
                return;
            }

            const allow = 'Allow all guests to run tasks';
            const allowAlways = 'Always allow';
            const deny = 'Deny';
            const response = await this.notificationUtil().showInformationMessage(
                `${participant.name} requested permission to run tasks.`,
                /* isVerbose: */ false,
                { modal: false },
                allow, allowAlways, deny
                );

            if (response === allow) {
                WorkspaceTaskService.sessionTaskControlAllowed = true;
            } else if (response === allowAlways) {
                await config.save(config.Key.allowGuestTaskControl, true);
            }

            if (response === allow || response === allowAlways) {
                await this.workspaceAccessControlService().setOperationAccessAsync(
                    operation,
                    vsls.RestrictedOperationAccess.Allowed
                );
            }
        } catch (err) {
            const message = `Requesting access for '${operation ? operation.name : 'null'}' operation failed: ${err.message}`;
            this.trace.error(message);
            Telemetry.sendFault(TelemetryEventNames.REQUEST_OPERATION_ACCESS_FAULT, FaultType.NonBlockingFault, message, err);
        }
    }

    private async createTaskOutput(taskTerminal: vscode.Terminal): Promise<void> {
        const taskOutput = await this.taskOutputService.shareTaskOutputAsync(
            taskTerminal.name, { contentType: vsls.TaskOutputContentType.TextWithAnsiEscapeCodes });
        const streamMoniker = taskOutput.feed.streamMoniker;
        const streamId = await this.streamManagerService.getStreamAsync(
            streamMoniker.name, streamMoniker.condition);

        const registrations: vscode.Disposable[] = [];

        const subscribeDataListener = (event: vscode.Event<string>) => {
            event((data: string) => {
                this.dataProcessQueue = this.dataProcessQueue
                    .then(() => processData(data))
                    .catch((e) => {
                        const errorMsg = 'Rejected promise while processing terminal data';
                        this.trace.error(errorMsg);
                    });
            }, null, registrations);
        };

        if (typeof vscode.window.onDidWriteTerminalData === 'function') {
            const event: vscode.Event<string> = (listener: (e: string) => any, thisArgs?: any, disposables?: vscode.Disposable[]) => 
                vscode.window.onDidWriteTerminalData(e => {
                        if (e.terminal === taskTerminal) {
                            listener(e.data);
                        }
                    }, thisArgs, disposables);

            subscribeDataListener(event);
        } else if ('onDidWriteData' in taskTerminal) {
            subscribeDataListener(taskTerminal.onDidWriteData);
        } else if ('onData' in taskTerminal) {
            subscribeDataListener((<any>taskTerminal).onData);
        }

        const processData = async (data: string): Promise<void> => {
            const encoded = Buffer.from(data).toString('base64');
            await this.rpcClient.sendRequest<void>(this.trace, 'stream.writeBytes', null, null, streamId, 'x' + encoded);
        };

        const onDidCloseTerminal = (e: vscode.Terminal) => {
            if (e === taskTerminal) {
                disposeTaskOutput();
            }
        };

        vscode.window.onDidCloseTerminal(onDidCloseTerminal, null, registrations);

        const disposeTaskOutput = async () => {
            delete this.taskOutputCache[taskTerminal.name];
            registrations.forEach(x => x.dispose());
            await this.streamService.disposeStreamAsync(streamId);
            await this.taskOutputService.closeTaskOutputAsync(taskOutput.id);
        };

        this.taskOutputCache[taskTerminal.name] = {
            terminal: taskTerminal,
            taskOutput: taskOutput,
            streamId: streamId,
            dispose: disposeTaskOutput
        };
    }

    private async getSupportedTasks() {
        try {
            const allTasks: vscode.Task[] = await tasks.fetchTasks();
            const workspaceTasks: vsls.WorkspaceTask[] = allTasks.map(WorkspaceTaskService.getWorkspaceTask);
            return workspaceTasks;
        } catch (error) {
            RemoteServiceTelemetry.sendServiceFault(WorkspaceTaskService.SERVICE_NAME, 'getSupportedTasks', error);
            return new ResponseError(ErrorCodes.UnknownErrorCode, error.message, errorToString(error));
        }
    }

    private getTaskExecutions() {
        try {
            return Promise.resolve(this.taskExecutions.map(x => x[0]));
        } catch (error) {
            RemoteServiceTelemetry.sendServiceFault(WorkspaceTaskService.SERVICE_NAME, 'getTaskExecutions', error);
            return new ResponseError(ErrorCodes.UnknownErrorCode, error.message, errorToString(error));
        }
    }

    private async runTask(taskUidOrName: string, messageContext: GuestIdSessionContext) {
        let result: vsls.RunTaskResult = { status: vsls.RunTaskStatus.TaskNotFound };
        try {
            const allTasks = await tasks.fetchTasks();
            const taskToRun = allTasks.filter(x => x.name === taskUidOrName || WorkspaceTaskService.getTaskUid(x) === taskUidOrName)[0];
            if (taskToRun) {
                const isTaskControlAllowed = await this.clientAccessCheck().canPerformOperation(
                    messageContext, WorkspaceTaskService.runTaskOperation);
                if (!isTaskControlAllowed) {
                    const isReadOnly = await this.clientAccessCheck().isClientReadOnly(messageContext);
                    const guestSessionId = this.clientAccessCheck().getContextSessionId(messageContext);
                    const restrictedOperation: vsls.WorkspaceTaskRestrictedOperation = {
                        name: WellKnownRestrictedOperations.RunTask,
                        sessionId: guestSessionId ? parseInt(guestSessionId, 10) : undefined,
                        taskUid: taskUidOrName
                    };
                    await this.clientAccessCheck().logRejectedOperation(
                        restrictedOperation,
                        isReadOnly ? vsls.RestrictedOperationAccess.RejectedInReadOnlySession : vsls.RestrictedOperationAccess.DisabledByHostConfiguration
                    );
                    return { status: vsls.RunTaskStatus.RejectedByHost };
                }
                const execution = await tasks.executeTask(taskToRun);
                const moniker = WorkspaceTaskService.createMoniker(execution);
                this.taskExecutions.push([moniker, { execution: execution, startTime: Date.now() }]);
                result = { status: vsls.RunTaskStatus.Started, taskExecution: moniker };
            }
        } catch (error) {
            RemoteServiceTelemetry.sendServiceFault(WorkspaceTaskService.SERVICE_NAME, 'runTask', error);
            return new ResponseError(ErrorCodes.UnknownErrorCode, error.message, errorToString(error));
        }
        return result;
    }

    private async terminateTask(taskExecution: vsls.TaskExecutionMoniker, messageContext: any) {
        try {
            const entry = this.taskExecutions.find(x => x[0].id === taskExecution.id);
            if (!!entry) {
                const isTaskControlAllowed = WorkspaceTaskService.guestTaskControlAllowed
                    && await this.clientAccessCheck().canPerformOperation(messageContext, WorkspaceTaskService.terminateTaskOperation);
                if (!isTaskControlAllowed) {
                    return { status: vsls.RunTaskStatus.RejectedByHost };
                }

                const execution = entry[1].execution;
                await execution.terminate();
            }
        } catch (error) {
            RemoteServiceTelemetry.sendServiceFault(WorkspaceTaskService.SERVICE_NAME, 'terminateTask', error);
            return new ResponseError(ErrorCodes.UnknownErrorCode, error.message, errorToString(error));
        }
    }

    private async handleTaskStarted(execution: vscode.TaskExecution): Promise<void> {
        const entry = this.taskExecutions.find(x => x[1].execution === execution);
        let moniker: vsls.TaskExecutionMoniker = undefined;
        if (!!entry) {
            // task started by us programmatically
            moniker = entry[0];
        } else {
            // task started by a user
            moniker = WorkspaceTaskService.createMoniker(execution);
            this.taskExecutions.push([moniker, { execution: execution, startTime: Date.now() }]);
        }

        await this.rpcClient.sendNotification(
            this.trace,
            'workspaceTask.taskStarted',
            {
                taskExecution: moniker,
                change: vsls.TaskExecutionStatusChange.Started,
                task: WorkspaceTaskService.getWorkspaceTask(execution.task)
            }
        );
    }

    private async handleTaskEnded(execution: vscode.TaskExecution): Promise<void> {
        const index = this.taskExecutions.findIndex(x => x[1].execution === execution);
        if (index > -1) {
            const entry = this.taskExecutions[index];

            const kind = WorkspaceTaskService.getTaskKind(entry[1].execution.task) || 'Unknown';
            const elapsed = Date.now() - entry[1].startTime;
            this.completedExecutions.push([kind, elapsed]);

            await this.rpcClient.sendNotification(
                this.trace,
                'workspaceTask.taskTerminated',
                {
                    taskExecution: entry[0],
                    change: vsls.TaskExecutionStatusChange.Terminated,
                    task: WorkspaceTaskService.getWorkspaceTask(execution.task)
                }
            );

            this.taskExecutions.splice(index, 1);
        }
    }

    private static getTaskUid(task: vscode.Task): string {
        return `${task.definition.type}:${task.name}`;
    }

    private static getTaskKind(task: vscode.Task): string {
        switch (task.group) {
            case vscode.TaskGroup.Build:
                return 'build';
            case vscode.TaskGroup.Clean:
                return 'clean';
            case vscode.TaskGroup.Rebuild:
                return 'rebuild';
            case vscode.TaskGroup.Test:
                return 'test';
            default:
                return undefined;
        }
    }

    private static getWorkspaceTask(task: vscode.Task): vsls.WorkspaceTask {
        const result: vsls.WorkspaceTask = {
            uniqueId: WorkspaceTaskService.getTaskUid(task),
            name: task.name,
            source: task.source,
            kind: WorkspaceTaskService.getTaskKind(task)
        };

        switch (task.scope) {
            case vscode.TaskScope.Global:
                result.scope = vsls.TaskScope.Global;
                break;

            case vscode.TaskScope.Workspace:
                result.scope = vsls.TaskScope.Workspace;
                break;

            default:
                // Assume that since it's not an existing task scope, it must be
                // a workspace folder.
                result.scope = vsls.TaskScope.WorkspaceFolder;
                result.owningWorkspace = task.scope.index.toString();
                break;
        }

        return result;
    }

    private static createMoniker(execution: vscode.TaskExecution): vsls.TaskExecutionMoniker {
        const taskUid = WorkspaceTaskService.getTaskUid(execution.task);
        return {
            id: `${taskUid}:${++WorkspaceTaskService.taskExecutionCounter}`,
            taskUid: taskUid
        };
    }
}