import * as vscode from 'vscode';
import { RpcProxy, IRpcClient, ServiceInfo } from '@vs/vso-rpc';
import { 
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { traceSource } from '@vs/vscode-command-framework';

/**
 * Provides document contents for documents outside the shared folder cone.
 */
export class ExternalDocumentProvider implements vscode.TextDocumentContentProvider, vscode.Disposable {
    private documents: Map<string, string>;
    private documentClosedSubscription: vscode.Disposable;

    constructor(private rpcClient: IRpcClient, private prefixServiceName: string) {
        this.documents = new Map<string, string>();
        this.documentClosedSubscription = vscode.workspace.onDidCloseTextDocument(this.onTextDocumentClosed, this);
    }
        
    public async provideTextDocumentContent(uri: vscode.Uri, token: vscode.CancellationToken): Promise<string> {
        let uriString = uri.toString();
        if (this.documents.has(uriString)) {
            return this.documents.get(uriString);
        }

        const lspName = uri.fragment ? uri.fragment : 'any';
        const serviceInfo: ServiceInfo<vsls.LanguageServerProvider> = {
            name: this.prefixServiceName +  lspName,
            methods: vsls.LanguageServerProvider.methods,
            events: vsls.LanguageServerProvider.events,
        };
        const languageServerProviderClient = RpcProxy.create(serviceInfo, this.rpcClient, traceSource.withName(vsls.TraceSources.ClientLSP));

        // Use our custom liveshare/externalDocument' method
        const externalTextDocumentParams = { textDocument: { uri: uri.toString() }};
        let contents = <string>(await languageServerProviderClient.requestAsync({
                method: 'liveshare/externalDocument',
                params: externalTextDocumentParams }, null));

        if (!contents) {
            contents = '<Not supported>';
        }
        this.documents.set(uriString, contents);
        return contents;
    }

    public dispose() {
        this.documentClosedSubscription.dispose();
        this.documents.clear();
    }

    private onTextDocumentClosed(document: vscode.TextDocument): void {
        this.documents.delete(document.uri.toString());
    }
}