import { ILogger } from '@vs/vso-logging';
import { IDisposable, TIME_SECOND_MS } from '@vs/vscs-utils';
import { IWorkspaceClient } from './IWorkspaceClient';
import {
    checkConnectionWithTimeout,
    failedtoCheckConnectionMessage,
} from './checkConnectionWithTimeout';
import { CancellationTokenSource } from 'vscode-jsonrpc';

// timeout to wait on workspace metrics
const defaultTimeout = 5 * TIME_SECOND_MS;

let session = 0;

/**
 * Check if a liveshare connection is healthy by checking the connection when
 * the metrics event is not received in a period of time.
 * @returns A disposable instance if we want to stop the health check.
 */
export function checkWorkspaceClient(
    workspaceClient: IWorkspaceClient,
    logger: ILogger,
    metricsTimeout?: number,
    checkConnectionTimeout?: number,
    isCheckConnectionEnabled?: () => boolean
): IDisposable {
    metricsTimeout = metricsTimeout ?? defaultTimeout;

    logger = logger.createChild(`${++session}`);
    logger.info(`Start checking connection timeout:${metricsTimeout}`);
    let timeoutReference: number;

    const setTimeoutMetrics = () => {
        timeoutReference = setTimeout(onWorkspaceMetricsTimeout, metricsTimeout);
    };

    const clearTimeoutMetrics = () => {
        clearTimeout(timeoutReference as number | undefined);
    };

    let isChecking = false;
    const cts = new CancellationTokenSource();
    const isDisposed = () => {
        return cts.token.isCancellationRequested;
    };

    const onWorkspaceMetricsTimeout = async () => {
        if (isDisposed()) {
            return;
        }

        isChecking = true;
        if (
            (!isCheckConnectionEnabled || isCheckConnectionEnabled()) &&
            !(await checkConnectionWithTimeout(
                workspaceClient,
                logger,
                checkConnectionTimeout,
                cts
            ))
        ) {
            logger.info(`Failed check -> isDisposed:${isDisposed()}`);
            onMetricsDisposable?.dispose();
            if (!isDisposed()) {
                workspaceClient.dispose(failedtoCheckConnectionMessage);
            }
        } else {
            setTimeoutMetrics();
        }
        isChecking = false;
    };

    workspaceClient.rpcClient.onDispose(() => {
        clearTimeoutMetrics();
    });

    const onMetricsDisposable = workspaceClient.onWorkspaceMetricsUpdated((e) => {
        clearTimeoutMetrics();
        if (!isChecking) {
            setTimeoutMetrics();
        }
    });

    // kick first metrics timeout
    setTimeoutMetrics();

    return {
        dispose: () => {
            logger.info(`Stop checking connection`);
            cts.cancel();
            onMetricsDisposable?.dispose();
        },
    };
}
