import { DisposableClass, wait, defer, hashString, timeoutPromise, Signal } from '@vs/vscs-utils';

import { Emitter } from 'vscode-jsonrpc';
import { Performance } from '@vs/vscs-performance';
import { ILogger } from '@vs/vso-logging';

import { IConnectionStatusChangeArg } from '../interfaces/IConnectionStatusChangeArg';
import { HUB_CONNECTION_DEFAULT_OPTIONS, HUB_NO_RETRY_OPTIONS } from './constants';
import { IHubConnectionOptions } from '../interfaces/IHubConnectionOptions';
import { ConnectionTimeoutError } from '../errors/ConnectionTimeoutError';
import { ConnectionHubRecord } from './ConnectionHubRecord';
import { IConnection } from '../interfaces/IConnection';
import { errorToConnectionError } from '../utils/errorToConnectionError';
import { TConnectionClass } from '../interfaces/TConnectionClass';

const optionsWithDefaults = (
    connectionOptions: Partial<IHubConnectionOptions>
): IHubConnectionOptions => {
    return {
        ...HUB_CONNECTION_DEFAULT_OPTIONS,
        ...connectionOptions,
    };
};

/**
 * Orchestrator class for a `Connection`s. Gives back a LiveShare or
 * VSCode connection, either exisiting or create a new one for you.
 */
export class ConnectionHub<
    TConstructableConnection extends TConnectionClass<IConnection> = TConnectionClass<IConnection>,
    TConnection extends InstanceType<TConstructableConnection> = InstanceType<
        TConstructableConnection
    >,
    TOptions extends TConnection['options'] = TConnection['options']
> extends DisposableClass {
    /**
     * The `onConnection` callback when a connection is created.
     */
    private readonly onConnectionEmitter = new Emitter<TConnection>();
    public readonly onConnection = this.onConnectionEmitter.event;

    constructor(
        trace: ILogger,
        private performance: Performance,
        private readonly connectionClass: TConstructableConnection,
        private readonly childConnectionHubs: Array<ConnectionHub<any>> = []
    ) {
        super(trace);
    }

    public get childHubs(): Array<ConnectionHub<any> | undefined> {
        return [...this.childConnectionHubs];
    }

    /**
     * Get connection `id` by `connectionOptions`. Each connection
     * type must provide the `getId` method that identifies
     * the connection by the `connectionOptions`. Same connection
     * type with the same options must have the same resulting `id`.
     */
    public getConnectionId = (connectionOptions: TOptions) => {
        const connection = new this.connectionClass(
            this.trace,
            this.performance,
            connectionOptions
        );

        return connection.getId(connectionOptions);
    };

    /**
     * Return a possible existing connection based on the connection options.
     * The returned connection if exists would have
     */
    public getConnection(connectionOptions: TOptions): TConnection | undefined {
        const id = this.getConnectionId(connectionOptions);
        const connectionRecord = this.connections[id];
        if (connectionRecord) {
            const { connection } = connectionRecord;
            return connection;
        }
    }

    /**
     * Will give you a LiveShare
     * connection back, either exisiting or will create a new one for you.
     */
    public async connect(
        connectionOptions: TOptions,
        hubConnectionOptions: Partial<IHubConnectionOptions> = {}
    ): Promise<TConnection> {
        const { trace = this.trace } = hubConnectionOptions;

        trace.info('requested to connect', connectionOptions, hubConnectionOptions);

        try {
            const id = this.getConnectionId(connectionOptions);
            const connectionRecord = this.connections[id];

            const connectionTrace = trace.createChild(`${id}`);
            connectionTrace.info(`connection record: ${!!connectionRecord}`);

            if (!connectionRecord) {
                connectionTrace.info('creating new connection');
                return await this.createConnectionWithTimeout(
                    connectionOptions,
                    optionsWithDefaults(hubConnectionOptions)
                );
            }

            const { connection } = connectionRecord;
            if (!connection) {
                connectionTrace.info('no connection on connection record, creating');
                return await this.createConnectionWithTimeout(
                    connectionOptions,
                    optionsWithDefaults(hubConnectionOptions)
                );
            }

            if (connection.status === 'disconnected') {
                connectionTrace.info('disposed, creating');
                this.disposeConnection(id);
                return await this.createConnectionWithTimeout(
                    connectionOptions,
                    optionsWithDefaults(hubConnectionOptions)
                );
            }

            if (connection.status === 'connected') {
                connectionTrace.info('return connected');
                return connection;
            }

            const { timeout = Infinity } = hubConnectionOptions;

            connectionTrace.info(`connecting with timeout - ${timeout} ms`);
            const result = await connection.connectWithTimeout(timeout);

            return result as TConnection;
        } catch (err) {
            trace.warning('error during connection', err);

            throw errorToConnectionError(err);
        }
    }

    /**
     * Connect without retries.
     */
    public connectOnce = async (
        connectionOptions: TOptions,
        hubConnectionOptions: Partial<IHubConnectionOptions> = {}
    ): Promise<TConnection> => {
        const { trace = this.trace } = hubConnectionOptions;

        trace.info('requested to connect once', connectionOptions, hubConnectionOptions);

        return await this.connect(connectionOptions, {
            ...HUB_NO_RETRY_OPTIONS,
            ...hubConnectionOptions,
        });
    };

    /**
     * Disconnect a connection.
     */
    public async disconnect(connectionOptions: TOptions, reason?: string): Promise<boolean> {
        this.trace.info('requested disconnect', connectionOptions);
        const id = this.getConnectionId(connectionOptions);

        const retryAwaitSignal = this.retrySignals[id];
        if (retryAwaitSignal) {
            retryAwaitSignal.cancel();

            this.retrySignals[id] = undefined;
        }

        const connectionRecord = this.connections[id];
        if (!connectionRecord) {
            return false;
        }

        await connectionRecord.disconnect(reason);
        this.connections[id] = undefined;

        return true;
    }

    /******************************************************
     * Implementation details.
     ******************************************************/

    /**
     * Individual connection state changed.
     */
    private async onConnectionChanged(id: string, connectionChange: IConnectionStatusChangeArg) {
        const trace = this.trace.createChild(`onConnectionChanged:${id}`);

        const { status, previousStatus } = connectionChange;

        trace.info(`${previousStatus} -> ${status}`);

        if (status !== 'disconnected') {
            return;
        }

        // if disconnected, dispose the current connection
        const connectionRecord = this.connections[id];
        if (!connectionRecord) {
            trace.info('no connection record found');
            return;
        }

        trace.info('disposing the connection');
        this.disposeConnection(id);
        this.connections[id] = undefined;

        if (previousStatus !== 'connected') {
            return;
        }

        // if prev status was "connected" and we should also reconnect
        const { hubConnectionOptions, connectionOptions, connection } = connectionRecord;
        if (hubConnectionOptions.shouldReconnect && !connection.isDisposing) {
            trace.info('reconnecting..');

            return await this.connect(connectionOptions, hubConnectionOptions);
        }

        trace.info('not reconnecting');
    }

    protected readonly connections: Record<
        string,
        ConnectionHubRecord<TConnection, TOptions> | undefined
    > = {};

    protected readonly retrySignals: Partial<Record<string, Signal<any>>> = {};

    private disposeConnection(id: string) {
        try {
            this.trace.info(`disposing ${id} connection`);

            const connectionRecord = this.connections[id];
            if (!connectionRecord) {
                return;
            }

            connectionRecord.dispose('connection record disposed by ConnectionHub');
            this.connections[id] = undefined;
        } catch (err) {
            this.trace.warning(`error while disposing ${id} connection`, err);
        }
    }

    /**
     * If connection is not complete after specified timeout, throw the ConnectionError.
     */
    private createConnectionWithTimeout = async (
        connectionOptions: TOptions,
        hubConnectionOptions: IHubConnectionOptions
    ): Promise<TConnection> => {
        const { timeout } = hubConnectionOptions;
        if (!isFinite(timeout)) {
            this.trace.verbose(`creating connection without a timeout`);

            return await this.createConnection(connectionOptions, hubConnectionOptions);
        }

        this.trace.verbose(`creating connection with timeout of ${timeout}ms`);

        const result = await timeoutPromise(
            this.createConnection(connectionOptions, hubConnectionOptions),
            timeout,
            new ConnectionTimeoutError(`Could not establish connection in ${timeout}ms.`)
        );

        return result;
    };

    protected createConnection = async (
        connectionOptions: TOptions,
        hubConnectionOptions: IHubConnectionOptions
    ): Promise<TConnection> => {
        const {
            retries,
            retryDelay,
            performance = this.performance,
            trace = this.trace,
        } = hubConnectionOptions;

        const options = connectionOptions;
        const id = this.getConnectionId(options);

        try {
            this.trace.info('creating connection', hubConnectionOptions);

            // create new connection
            const connection = new this.connectionClass(
                trace.createChild(`connection:${id}`),
                performance.createGroup(`${trace.name}:${hashString(id)}`),
                options,
                this.childConnectionHubs
            );

            const record = new ConnectionHubRecord<TConnection, TOptions>(
                this.trace.createChild('connection-record'),
                connection as TConnection,
                connectionOptions,
                hubConnectionOptions,
                connection.onConnectionChanged(this.onConnectionChanged.bind(this, id))
            );

            this.connections[id] = record;

            const connectionResult = await connection.connect();
            this.addToDisposables(record);

            // fire the event after the connection is complete
            defer(() => {
                this.onConnectionEmitter.fire(connectionResult as TConnection);
            }, 0);

            return connectionResult as TConnection;
        } catch (e) {
            this.trace.warning(`disposing connection "${id}" due to an error`, e);

            this.disposeConnection(id);

            /**
             * If no retries left, re-throw the error.
             */
            if (retries < 1) {
                throw e;
            }

            this.trace.info(`connection failed, retrying ${retries}`);

            /**
             * If a `disconnect` is requested when we wait on `retryDelay`,
             * we must not create a new connection after the `retryDelay` is
             * finished but rather bail out immediately.
             */
            const signal = new Signal();
            this.retrySignals[id] = signal;

            await Promise.race([signal.promise, wait(retryDelay)]);

            return await this.createConnection(connectionOptions, {
                ...hubConnectionOptions,
                retries: retries - 1,
            });
        }
    };
}
