import { ICommandContext } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import { ICommand } from './abstractions/ICommand';
import { ICommandContextBuilder } from './abstractions/ICommandContextBuilder';
import { DecoratorHelper } from './utils/DecoratorHelper';

export class CommandContextBuilder implements ICommandContextBuilder {
    constructor (
        private trace: TraceSource) {
    }

    public build(command: ICommand<any>, commandText: string, traceName?: string): ICommandContext {
        return {
            trace: this.trace.withName(
                traceName || this.buildTrace(command, commandText)),
            commandText,
            commandName: ''
        };
    }

    private buildTrace(command: ICommand<any>, commandText: string): string {
        let name = '';

        command = DecoratorHelper.getCoreCommand(command);
        if (command && command.constructor && command.constructor.name) {
            name = command.constructor.name as string;
            name = name.replace('CommandDecorator', '');
        }
       
        return `Command:${name === 'Object' ? commandText : name}`;
    }
}