import * as vscode from 'vscode';

export interface TreeViewItemOptions {
    type: string;
    label: string;
    tooltip?: string;
    command?: vscode.Command;
    collapsibleState?: vscode.TreeItemCollapsibleState;
    contextValue?: string;
    iconPath?: string | vscode.Uri | { light: string | vscode.Uri; dark: string | vscode.Uri } | vscode.ThemeIcon;
    resourceUri?: vscode.Uri;
    description?: string;
}

export class TreeViewItem extends vscode.TreeItem {

    constructor(public readonly options: TreeViewItemOptions) {
        super(
            options.label,
            options.collapsibleState || vscode.TreeItemCollapsibleState.None
            );

        this.tooltip = options.tooltip;
        this.command = options.command;
        this.iconPath = options.iconPath;
        this.contextValue = options.type;
        this.resourceUri = options.resourceUri;
        this.description = options.description;
    }
}