import { ILogger } from '@vs/vso-logging';
import { RpcProxy, IRpcClient } from '@vs/vso-rpc';
import { vsls } from '@vs/vsls-contracts';

import { SudoPortForwarderServiceClient } from './SudoPortForwarderServiceClient';
import { ISudoPortForwarderService } from './interfaces/ISudoPortForwarderService';
import { DisposableClass } from '@vs/vscs-utils';

export class SudoPortforwarderClient extends DisposableClass {
    private readonly codespacePortForwarderServiceClient: ISudoPortForwarderService;

    constructor(
        trace: ILogger,
        public readonly rpcClient: IRpcClient,
    ) {
        super(trace.createChild('sudo-pf-client'));

        this.codespacePortForwarderServiceClient = RpcProxy.create<ISudoPortForwarderService>(SudoPortForwarderServiceClient, rpcClient, this.trace);
    }

    public async connect(hubPipeName: string): Promise<void>{
        const start = Date.now();
        const workspaceSessionInfo = await this.codespacePortForwarderServiceClient.connectAsync(hubPipeName);
        const time = Math.round(Date.now() - start);
        this.trace.verbose(`connect codespacePortForwarderService completed -> time:${time}`);
        return workspaceSessionInfo;
    }

    public async startPortForwarding(sharedServer: vsls.SharedServer): Promise<number|undefined> {
        const start = Date.now();
        const localPort = await this.codespacePortForwarderServiceClient.startPortForwardingAsync(sharedServer);
        const time = Math.round(Date.now() - start);
        this.trace.verbose(`start portforwarding using codespacePortForwarderService completed -> time:${time}`);
        return localPort;
    }

    public async stopPortForwarding(sharedServer: vsls.SharedServer): Promise<void> {
        const start = Date.now();
        const workspaceSessionInfo = await this.codespacePortForwarderServiceClient.stopPortForwardingAsync(sharedServer);
        const time = Math.round(Date.now() - start);
        this.trace.verbose(`stop portforwarding using codespacePortForwarderService completed -> time:${time}`);
        return workspaceSessionInfo;
    }

    public async disconnect(): Promise<void> {
        const start = Date.now();
        const workspaceSessionInfo = await this.codespacePortForwarderServiceClient.disconnectAsync();
        const time = Math.round(Date.now() - start);
        this.trace.verbose(`disconnect codespacePortForwarderService completed -> time:${time}`);
        return workspaceSessionInfo;
    }
}