import {
    ISessionStateHandler,
    SessionState
} from '@vs/liveshare-core';

import { IHostTerminalController, hostTerminalControllerFactory } from './hostTerminalController';
import { IDependencies } from '../_new_/IDependencies';

export class HostTerminalHandler implements ISessionStateHandler {
    private readonly hostController: IHostTerminalController;

    constructor(dependencies: IDependencies) {
         // Instantiate a host controller by default.
        // It will start monitoring current terminal output for further sharing.
        this.hostController = hostTerminalControllerFactory(dependencies);       
    }

    public async handleSessionStateChanged(newState: SessionState, previousState: SessionState): Promise<void> {
        switch (newState) {
            case SessionState.Shared:
                // Activate the host terminal controller in a shared collaboration session.
                await this.hostController.activate();
                break;
            case SessionState.JoiningInProgress:
                // The host controller is not to be used in a joined collaboration session.
                // Stop background monitoring of terminal output.
                this.hostController.dispose();
                break;
            default:
                if (previousState === SessionState.Shared) {
                    // Disengage the host controller when leaving a shared collaboration session.
                    await this.hostController.deactivate();
                }
                break;
        }
    }

    public async dispose(): Promise<void> {
        await this.hostController.dispose();
    }
}