type PartialProgressOptions = Partial<vscode.ProgressOptions>;
export interface UserProgressOptions extends PartialProgressOptions {
    isUserInitiated?: boolean;
    cancellationToken?: vscode.CancellationToken;
}

const defaultProgressOptions: vscode.ProgressOptions = {
    location: vscode.ProgressLocation.Window,
    title: ''
};

const userProgressOptionsDefaults: UserProgressOptions = {
    ...defaultProgressOptions,
    isUserInitiated: true,
};

export class ExtensionUtil {
    private static contextValues: { [key: string]: any } = {};
    private static extensionContext: vscode.ExtensionContext;
    private static registeredCommands: IMap<vscode.Disposable> = {};
    private static _extensionId: string;

    public static init(context: vscode.ExtensionContext, clientInfo: vsls.ClientVersionInfo, extensionId: string): void {

        ExtensionUtil.extensionContext = context;
        ExtensionUtil._extensionId = extensionId;
        traceSource.info('Extension, IDE, OS : ' + ExtensionUtil.clientInfoToString(clientInfo));
        Telemetry.addFilter(new SendOnceFilter(TelemetryEventNames.UNHANDLED_REJECTION_FAULT, [TelemetryPropertyNames.EVENT_MESSAGE]));
    }

    public static getPackage(): any | undefined {
        return ExtensionUtil.getPackageExtension(ExtensionUtil._extensionId);
    }

    public static getPackageExtension(extensionId: string): any | undefined {

        const liveshareExtension = vscode.extensions.getExtension(extensionId);
        if (liveshareExtension) {
            return liveshareExtension.packageJSON;
        }

        return undefined;
    }

    public static get extensionId(): string {
        return ExtensionUtil._extensionId;
    }

    public static get context(): vscode.ExtensionContext {
        if (!ExtensionUtil.extensionContext) {
            throw new Error('Extension context not initialized');
        }

        return ExtensionUtil.extensionContext;
    }

    /**
     * Gets a flag indicating whether modal notifications should be enabled.
     * (Modal dialogs block automated UI tests; non-modal notifications are automatiable.)
     */
    public static get enableModalNotifications(): boolean {
        return !process.env.VSLS_TEST_DISABLE_MODAL;
    }

    public static async setCommandContext(key: CommandContext, value: any): Promise<void> {
        ExtensionUtil.contextValues[key] = value;
        await vscode.commands.executeCommand('setContext', key, value);
    }

    public static getCommandContext(key: CommandContext): any {
        return ExtensionUtil.contextValues[key];
    }

    public static getErrorString(code: vsls.ErrorCodes | string): string {
        switch (code) {
            case vsls.ErrorCodes.CouldNotConnectToServer:
                return localize('error.CouldNotConnectToServer');
            case vsls.ErrorCodes.OlderThanServer:
                return localize('error.OlderThanServer').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.NewerThanServer:
                return localize('error.NewerThanServer').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.OlderThanPeer:
                return localize('error.OlderThanPeer').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.NewerThanPeer:
                return localize('error.NewerThanPeer').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.OlderThanAgent:
                return localize('error.OlderThanAgent').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.NewerThanAgent:
                return localize('error.NewerThanAgent').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.NoIPAddressesDetected:
                return localize('error.NoIPAddressesDetected');
            case vsls.ErrorCodes.NoConnectionAddresses:
                return localize('error.NoConnectionAddresses');
            case vsls.ErrorCodes.AutoConnectionFailed:
                return localize('error.AutoConnectionFailed');
            case vsls.ErrorCodes.RelayConnectionFailed:
                return localize('error.RelayConnectionFailed');
            case vsls.ErrorCodes.DirectConnectionFailed:
                return localize('error.DirectConnectionFailed');
            case vsls.ErrorCodes.SessionProtocolError:
                return localize('error.SessionProtocolError').replace('$(shortName)', Settings.get<string>(SettingKeys.shortName)!);
            case vsls.ErrorCodes.SessionAuthenticationFailed:
                return localize('error.SessionAuthenticationFailed');
            case vsls.ErrorCodes.DirectConnectionNotEnabled:
                return localize('error.DirectConnectionNotEnabled');
            case vsls.ErrorCodes.RelayConnectionNotEnabled:
                return localize('error.RelayConnectionNotEnabled');
            case vsls.ErrorCodes.CollaborationSessionUsersLimitReached:
                return localize('error.CollaborationSessionUsersLimitReached');
            case vsls.ErrorCodes.CollaborationSessionGuestRejected:
                return localize('error.CollaborationSessionGuestRejected');
            case vsls.ErrorCodes.CollaborationSessionRequestTimedOut:
                return localize('error.CollaborationSessionRequestTimedOut');
            case vsls.ErrorCodes.CollaborationSessionGuestCanceled:
                return localize('error.CollaborationSessionGuestCanceled');
            case vsls.ErrorCodes.CollaborationSessionNotFound:
                return localize('error.CollaborationSessionNotFound');
            case vsls.ErrorCodes.CollaborationSessionGuestBlocked:
                return localize('error.CollaborationSessionGuestBlocked');
            case vsls.ErrorCodes.NonSuccessHttpStatusCodeReceived:
                return localize('error.NonSuccessHttpStatusCodeReceived');
            case vsls.ErrorCodes.KeychainAccessFailed:
                return localize('error.KeychainAccessFailed');
            case vsls.ErrorCodes.RelayConnectionHostFailure:
                return localize('error.RelayConnectionHostFailure');
            case vsls.ErrorCodes.RelayConnectionGuestFailure:
                return localize('error.RelayConnectionGuestFailure');
            case vsls.ErrorCodes.RemoteLaunchNotEnabled:
                return localize('error.RemoteLaunchNotEnabled');
            case vsls.ErrorCodes.CouldNotConnectToServerAuthFailed:
                return localize('error.CouldNotConnectToServerAuthFailed');
            default:
                return '';
        }
    }

    public static getLocalizedProgressString(code: vsls.WorkspaceProgress): string {
        switch (code) {
            case vsls.WorkspaceProgress.OpeningRemoteSession:
                return localize('progress.openingRemoteSession');
            case vsls.WorkspaceProgress.JoiningRemoteSession:
                return localize('progress.joiningRemoteSession');
            case vsls.WorkspaceProgress.WaitingForHost:
                return localize('progress.waitingForHost');
            case vsls.WorkspaceProgress.ReconnectingToHost:
                return localize('progress.reconnectingToHost');
            default:
                return '';
        }
    }

    public static getProgressUpdateString(code: vsls.WorkspaceProgress | string): string {
        return ExtensionUtil.getLocalizedProgressString(code as vsls.WorkspaceProgress);
    }

    public static getWaitingForHostProgressUpdateString(code: vsls.WorkspaceProgress | string, userInfo: vsls.UserInfo) {
        if (!userInfo) {
            return;
        }

        let message = this.getLocalizedProgressString(code as vsls.WorkspaceProgress);

        if (message) {
            const anonymousUserName = Settings.get<string>(SettingKeys.anonymousUserName)!;
            const name: string = (userInfo.isAnonymous && anonymousUserName)
                ? anonymousUserName
                : userInfo.displayName || userInfo.emailAddress || 'Unknown user';

            message = message.replace('$(userName)', name);
        }

        return message;
    }

    public static getWorkspaceFilePath(workspaceFolder: string) {
        return path.join(workspaceFolder, `${Settings.get<string>(SettingKeys.name)}.code-workspace`);
    }

    //If ```progressText``` is the empty string, then no spinner is shown, hence the space
    public static async runWithProgress<T>(
        fn: (...args: any[]) => Promise<T>,
        progressOptions: UserProgressOptions = userProgressOptionsDefaults,
    ): Promise<T | undefined> {
        const options: UserProgressOptions = {
            ...userProgressOptionsDefaults,
            ...progressOptions
        };
        const { isUserInitiated, cancellationToken } = options;

        if (cancellationToken && cancellationToken.isCancellationRequested) {
            return;
        }

        if (!isUserInitiated) {
            // If the ```title``` is the empty string, then no notification is shown
            options.title = '';
        }

        return await vscode.window.withProgress(options as vscode.ProgressOptions, async (progress: vscode.Progress<{ message?: string; increment?: number }>) => {
            return new Promise<T>(async (resolve, reject) => {
                if (cancellationToken) {
                    cancellationToken.onCancellationRequested(() => {
                        resolve(null);
                    });
                }

                try {
                    resolve(await fn(progress));
                } catch (e) {
                    reject(e);
                }
            });
        });
    }

    /**
     * Attempts to lookup a custom error message for the error code, if the error has a
     * code property and a custom message is available. Then shows that message, or the
     * fallback error message property.
     */
    public static async showErrorAsync(
        error: string | { code?: vsls.ErrorCodes, message?: string },
        options: { modal?: boolean, hideReportAProblem?: boolean } = {},
        items: vscode.MessageItem[] = []
    ) {
        const message = (typeof error === 'string' ? error :
            error.code ? ExtensionUtil.getErrorString(error.code) || error.message : error.message) ||
            'Unknown error';
        const { modal, hideReportAProblem } = options;

        if (hideReportAProblem) {
            return await vscode.window.showErrorMessage(message, { modal }, ...items);
        }

        const reportAProblemItem = { title: 'Report a Problem' };
        const result = await vscode.window.showErrorMessage(message, { modal }, reportAProblemItem, ...items);

        if (result && result.title === reportAProblemItem.title) {
            this.reportIssue();
        }
        return result;
    }

    public static async reportIssue() {
        const { name, publisher } = ExtensionUtil.getPackage() as { name: string, publisher: string };
        await vscode.commands.executeCommand('vscode.openIssueReporter', `${publisher}.${name}`);
    }

    public static registerCommand<T>(command: string, callback: (...args: any[]) => Promise<T>, thisArg?: any): vscode.Disposable {
        return vscode.commands.registerCommand(
            command,
            async function (this: any, ...args: any[]) {
                try {

                    new TelemetryEvent(TelemetryEventNames.COMMAND_INITIATED)
                        .addProperty('commandName', command)
                        .send();

                    return await callback.call(this, ...args);
                } catch (e) {
                    ExtensionUtil.reportCommandError(command, e);
                }
            },
            thisArg);
    }

    public static addNewTreeViewItemAdornment(treeViewItem: TreeViewItem, settingKey: SettingKeys): TreeViewItem {
        if (!treeViewItem) {
            return undefined;
        }

        // Determine if the new icon should be displayed
        let isNew = false;
        const currentDate = new Date();
        const value = Settings.get<string>(settingKey);
        if (!value) {
            Settings.save(settingKey, currentDate);
            isNew = true;
        } else {
            const firstDisplayDate = new Date(value);
            const weekAgoDate = new Date();
            weekAgoDate.setDate(currentDate.getDate() - 7);
            isNew = firstDisplayDate > weekAgoDate;
        }

        const newIcon = '⭐';
        treeViewItem.tooltip = `${treeViewItem.label} ${isNew ? localize('treeView.newTooltip') : ''}`;
        treeViewItem.label = `${ treeViewItem.label}${isNew ? newIcon : ''}`;
        return treeViewItem;
    }

    public static registerTextEditorCommand<T>(
        command: string,
        callback: (textEditor: vscode.TextEditor, edit: vscode.TextEditorEdit, ...args: any[]) => void,
        thisArg?: any): vscode.Disposable {
        return vscode.commands.registerTextEditorCommand(
            command,
            function (this: any, textEditor: vscode.TextEditor, edit: vscode.TextEditorEdit, ...args: any[]) {
                try {
                    return callback.call(this, textEditor, edit, ...args);
                } catch (e) {
                    ExtensionUtil.reportCommandError(command, e);
                }
            },
            thisArg);
    }

    public static async tryRegisterCommand(
        command: string,
        callback: (...args: any[]) => any,
        thisArg?: any,
        isEditorCommand: boolean = false,
        force: boolean = false,
    ): Promise<vscode.Disposable | undefined> {
        let isDefined: boolean = await ExtensionUtil.isCommandDefined(command);
        let disposable: vscode.Disposable | undefined = undefined;
        if (isDefined) {
            disposable = this.registeredCommands[command];
            if (!force) {
                return disposable;
            }

            if (disposable) {
                const index = ExtensionUtil.context.subscriptions.indexOf(disposable);
                if (index >= 0) {
                    ExtensionUtil.context.subscriptions.splice(index, 1);
                }

                disposable.dispose();
            }
        }

        try {
            if (isEditorCommand) {
                disposable = ExtensionUtil.registerTextEditorCommand(command, callback, thisArg);
            } else {
                disposable = ExtensionUtil.registerCommand(command, callback, thisArg);
            }
            ExtensionUtil.registeredCommands[command] = disposable;
            ExtensionUtil.context.subscriptions.push(disposable);
        } catch (e) {
            console.error(e);
        }

        return disposable;
    }

    public static async isCommandDefined(command: string): Promise<boolean> {
        let commands = await vscode.commands.getCommands();
        return commands.indexOf(command) >= 0;
    }

    public static disposeCommand(command: string): void {
        if (this.registeredCommands[command]) {
            this.registeredCommands[command].dispose();
            delete this.registeredCommands[command];
        }
    }
    public static clientInfoToString(clientInfo: vsls.ClientVersionInfo): string {
        let s = '';
        if (!clientInfo) {
            return s;
        }
        if (clientInfo.extensionVersion) {
            if (clientInfo.extensionName) {
                s += clientInfo.extensionName;
                s += '/';
            }
            s += clientInfo.extensionVersion;
        }
        if (clientInfo.applicationVersion) {
            if (s.length > 0) {
                s += ' ';
            }
            if (clientInfo.applicationName) {
                s += clientInfo.applicationName;
                s += '/';
            }
            s += clientInfo.applicationVersion;
        }
        if (clientInfo.platformVersion) {
            if (s.length > 0) {
                s += ' ';
            }
            if (clientInfo.platformName) {
                s += clientInfo.platformName;
                s += '/';
            }
            s += clientInfo.platformVersion;
        }
        return s;
    }

    public static getExtensionVersion(extensionId: string, includePrerelease: boolean = true): string {
        let version = ExtensionUtil.getPackageExtension(extensionId).version;

        if (!includePrerelease) {
            version = version.replace(/-.*/, '');
        }

        return version;
    }

    public static reportCommandError(command: string, e: Error) {
        const message = `Unhandled error in '${command}' command: `;
        traceSource.error(message, e);
        Telemetry.sendFault(
            TelemetryEventNames.UNHANDLED_COMMAND_ERROR_FAULT,
            FaultType.Error,
            message + e.message,
            e);
        ExtensionUtil.showErrorAsync(e);
    }

    public static getGlobalStoragePath() {
        // Returns the globalStoragePath if available.
        // Otherwise returns the local extension path.
        const globalStoragePath = (ExtensionUtil.context as any).globalStoragePath;
        return globalStoragePath || ExtensionUtil.context.extensionPath;
    }

    public static openBrowser(uri: string): void {
        if (process.env.VSLS_TEST_DISABLE_BROWSE) {
            // UI tests need to set up browser windows for automation, so they can't support
            // the browser getting launched directly.
            vscode.window.showInformationMessage('[OPEN] ' + uri);
        } else {
            vscode.env.openExternal(vscode.Uri.parse(uri));
        }
    }

    public static isNode(): boolean {
        return (typeof process !== 'undefined') && (typeof (<any>process).release !== 'undefined') && ((<any>process).release.name === 'node');
    }

    public static getExtensionUri(relativePath: string): vscode.Uri {
        return getExtensionUri(relativePath, ExtensionUtil.context);
    }

    public static isReadWriteAnonymousEnabled(): boolean | undefined {
        return getExpService()?.getTreatmentVariable('vscode', 'readWriteAnonymous');
    }

    public static async getAnonymousReadOnlyLabel(clientAccessCheck: IClientAccessCheck, participant: vsls.WorkspaceUserProfile, sessionId?: number): Promise<string> {
        if (!clientAccessCheck) {
            return '';
        }

        const isReadOnly = await clientAccessCheck.isClientReadOnly(participant.id);
        const isAnonymous = participant.isAnonymous;
        let userSelection = workspaceSessionInfoTracker.getAnonymousAccess(participant.id);
        let anonymousExperimentUserSelectedReadWrite = this.isReadWriteAnonymousEnabled() && userSelection === AnonymousAccessLevel.readWrite;
        let label = '';
        let isReadOnlyLabel;
        
        // Host don't need any rw/ro label
        if (participant.isHost) {
            return label;
        }

        if (sessionId) {
            const isClientExplicitlyReadWrite = await clientAccessCheck.isClientExplicitlyReadWrite(sessionId);
            isReadOnlyLabel = isReadOnly && !isClientExplicitlyReadWrite && !isAnonymous;
        } else {
            isReadOnlyLabel = isReadOnly && !isAnonymous;
        }
        
        if (isReadOnlyLabel) {
            label = localize('guestNameViewlet.ReadOnlyLabel');
        } else if (isAnonymous) {
            if (anonymousExperimentUserSelectedReadWrite) {
                label = localize('guestNameViewlet.AnonymousReadWriteLabel');                             
            } else {
                label = localize('guestNameViewlet.ReadOnlyAndAnonymousLabel');              
            }
        }

        return label;
    }

    /**
    *  Function to set the transient setting in the workspace file. 
    */   
    public static async setTransientWorkspace(value: boolean) {
        try {
            const workspacePath = vscode.workspace.workspaceFile.fsPath;
            const workspaceFileContents = JSON.parse(new TextDecoder().decode(fileAccess.readFileSync(workspacePath)));
            workspaceFileContents.transient = value;
            fileAccess.writeFileAsync(workspacePath, JSON.stringify(workspaceFileContents));
        } catch (e) {
            assert(false, 'Setting transient workspace failed.');
        }
    }
}
