import { Emitter } from 'vscode-jsonrpc';
import * as ssh from '@vs/vs-ssh';
import { ConnectedState } from '@vs/vso-workspace-core';
import { DisposableClass } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import { SshReconnectResult } from './SshWorkspaceSessionFactory';

export interface ConnectedStateChanged {
    state: ConnectedState;
    retryCount: number;
    error?: Error;
}

export class SshWorkspaceSession extends DisposableClass {
    private readonly onConnectedStateChangedEmitter = new Emitter<ConnectedStateChanged>();

    private isReconnectingFlag: boolean = false;

    public readonly onConnectedStateChanged = this.onConnectedStateChangedEmitter.event;

    constructor(
        public readonly sshSession: ssh.SshClientSession,
        public readonly authCompletion: Promise<void>,
        logger: ILogger,
        reconnectCallback?: () => Promise<SshReconnectResult>
    ) {
        super(logger);

        this.addToDisposables(
            sshSession,
            sshSession.onDisconnected((e) => {
                if (reconnectCallback) {
                    this.isReconnectingFlag = true;
                    this.onConnectedStateChangedEmitter.fire({
                        state: ConnectedState.Reconnecting,
                        retryCount: 0,
                    });
                    reconnectCallback()
                        .then((result) => {
                            this.isReconnectingFlag = false;
                            this.onConnectedStateChangedEmitter.fire({
                                state:
                                    result.error === undefined
                                        ? ConnectedState.Reconnected
                                        : ConnectedState.Closed,
                                retryCount: result.retryCount,
                                error: result.error,
                            });
                        })
                        .catch((err) => {
                            this.isReconnectingFlag = false;
                            // ignore err
                        });
                } else {
                    this.isReconnectingFlag = false;
                    this.onConnectedStateChangedEmitter.fire({
                        state: ConnectedState.Closed,
                        retryCount: 0,
                    });
                    this.dispose('auto reconnect disabled');
                }
            })
        );
    }

    public get isReconnecting() {
        return this.isReconnectingFlag;
    }

    public async createRpcMessageStream(): Promise<ssh.SshRpcMessageStream> {
        const channelRequest = new ssh.ChannelRequestMessage();
        channelRequest.requestType = 'json-rpc';
        channelRequest.wantReply = true;

        const channel = await this.sshSession!.openChannel(null, channelRequest);
        return new ssh.SshRpcMessageStream(channel);
    }

    public async openStreamingChannel(
        streamId: string,
        cancellationToken?: ssh.CancellationToken
    ): Promise<ssh.SshChannel> {
        if (!this.sshSession) {
            throw new Error('Ssh session not initiated yet');
        }

        const channel = await this.sshSession.openChannel();
        const channelRequestType = `stream-transport-${streamId}`;
        const result = await channel.request(
            new ssh.ChannelRequestMessage(channelRequestType),
            cancellationToken
        );
        if (!result) {
            throw new Error(
                `Failed to create stream transport channel with streamId - ${streamId}`
            );
        }
        return channel;
    }
}
