import * as vscode from 'vscode';
import { StreamMessageReader, StreamMessageWriter } from 'vscode-jsonrpc';
import * as vscodeLSP from 'vscode-languageclient';
import * as p2c from 'vscode-languageclient/lib/protocolConverter';
import { InitializeRequest, InitializeResult } from 'vscode-languageserver-protocol';
import {
    Settings,
    ExtensionUtil,
    PathManager
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { traceSource } from '@vs/vscode-command-framework';
import {
    Telemetry,
    FaultType
} from '@vs/vso-telemetry';

import { LanguageServiceTelemetryEventNames } from './LanguageServiceTelemetry';
import * as commandHandler from './commandHandler';
import { ExternalDocumentProvider } from './ExternalDocumentProvider';
import { LSPClientStreamProvider } from './LSPClientStreamProvider';
import { REMOTE_COMMAND_NAME } from './lspServer';
import { RpcProxy, IRpcClient, ServiceInfo } from '@vs/vso-rpc';

const anyLspName: string = 'any';

const prefixServiceName = 'languageServerProvider-';

let universalServerCapabilities: vscodeLSP.ServerCapabilities;

/**
 * This is a LSP client to provide services for all languages. 
 */
export async function activateAsync(
    context: vscode.ExtensionContext,
    rpcClient: IRpcClient,
    workspaceServices: string[],
    exclusive?: boolean): Promise<vscode.Disposable> {

    const lspServices = workspaceServices
        .filter(s => s.startsWith(prefixServiceName))
        .map(s => s.substring(prefixServiceName.length));

    const disposables: vscode.Disposable[] = [];

    const indexOfAny = lspServices.indexOf(anyLspName);
    if (indexOfAny >= 0) {
        disposables.push(await activateLspClient(context, rpcClient, anyLspName, exclusive));
        lspServices.splice(indexOfAny, 1);
    }
    for (const lspName of lspServices) {
        disposables.push(await activateLspClient(context, rpcClient, lspName, exclusive));
    }
    // register a document provider for the external scheme
    let externalDocumentProvider = new ExternalDocumentProvider(rpcClient, prefixServiceName);
    let docProviderDisposable = vscode.workspace.registerTextDocumentContentProvider(PathManager.vslsExternalScheme, externalDocumentProvider);
    context.subscriptions.push(docProviderDisposable);

    return vscode.Disposable.from(...disposables, docProviderDisposable);
}

async function activateLspClient(context: vscode.ExtensionContext, rpcClient: IRpcClient, lspName: string, exclusive?: boolean): Promise<vscode.Disposable> {
    const disposables: vscode.Disposable[] = [];

    const addDisposable = (disposable: vscode.Disposable) => {
        context.subscriptions.push(disposable);
        disposables.push(disposable);
    };

    const serviceInfo: ServiceInfo<vsls.LanguageServerProvider> = {
        name: prefixServiceName + lspName,
        methods: vsls.LanguageServerProvider.methods,
        events: vsls.LanguageServerProvider.events,
    };
    let languageServerProviderClient = RpcProxy.create(serviceInfo, rpcClient, traceSource.withName(vsls.TraceSources.ClientLSP));

    let lspClientStreamProvider = new LSPClientStreamProvider(languageServerProviderClient, universalServerCapabilities);
    if (lspName === anyLspName) {
        const result = await languageServerProviderClient.requestAsync({ method: InitializeRequest.type.method, params: {} }, null);
        universalServerCapabilities = (result as InitializeResult).capabilities;
    }

    const metadata = await languageServerProviderClient.getMetadataAsync();
    const vslsScheme = Settings.scheme;

    let documentFilters: vscodeLSP.DocumentFilter[] = [];
    if (metadata.documentFilters) {
        documentFilters = metadata.documentFilters.map(d =>
            <vscodeLSP.DocumentFilter>{ schemes: vslsScheme, language: d.language ? d.language : undefined, pattern: d.pattern ? d.pattern : undefined });
    } else {
        documentFilters.push(<vscodeLSP.DocumentFilter>{ scheme: vslsScheme });
    }

    // define a vls schema to identify external files outside the workspace folder 
    documentFilters.push(<vscodeLSP.DocumentFilter>{ scheme: PathManager.vslsExternalScheme });

    // Note: the next call will enforce the lsp client npm package to use enabled proposed API's
    if (exclusive === undefined || exclusive) {
        documentFilters.forEach(d => (d as any).exclusive = true);
    }

    let clientOptions: vscodeLSP.LanguageClientOptions = {
        documentSelector: documentFilters,
        revealOutputChannelOn: vscodeLSP.RevealOutputChannelOn.Never,
        initializationFailedHandler: (error) => {
            lspClient.error('Server initialization failed.', error);
            Telemetry.sendFault(LanguageServiceTelemetryEventNames.LSPSERVER_INIT_FAULT, FaultType.Unknown, `Server ${lspName} initialization failed - ${error}`);
            return false;
        },
        middleware: {},
    };

    let lspClient = new vscodeLSP.LanguageClient('LiveShareGuest-' + lspName, 'Guest-' + lspName, (): Thenable<vscodeLSP.MessageTransports> => {
        return Promise.resolve<vscodeLSP.MessageTransports>({
            reader: new StreamMessageReader(lspClientStreamProvider.ReadStream),
            writer: new StreamMessageWriter(lspClientStreamProvider.WriteStream)
        });
    }, clientOptions);

    let remoteCmndName = REMOTE_COMMAND_NAME;

    let p2cConverter = p2c.createConverter();
    if (lspName === anyLspName) {
        addDisposable(lspClient.start());
        vscode.workspace.onDidOpenTextDocument(async (textDocument: vscode.TextDocument) => {
            await populateDiagnostics(lspClient, textDocument, p2cConverter);
        }, undefined, context.subscriptions);
    } else {
        remoteCmndName = remoteCmndName.concat('.', lspName);
        let started = false;
        disposables.push(vscode.workspace.onDidOpenTextDocument(async (textDocument: vscode.TextDocument) => {
            if (textDocument.languageId === lspName || documentFilters.some(d => d.language === textDocument.languageId)) {
                if (!started) {
                    started = true;
                    addDisposable(lspClient.start());
                }

                await populateDiagnostics(lspClient, textDocument, p2cConverter);
            }
            return true;
        },
            undefined,
            context.subscriptions));
    }

    let remoteCommand = ExtensionUtil.registerCommand(remoteCmndName, async (args) => {
        await commandHandler.handleLiveShareRemoteCommand(args, lspClient, p2cConverter);
    });

    addDisposable(remoteCommand);
    return vscode.Disposable.from(...disposables);
}

async function populateDiagnostics(lspClient: vscodeLSP.LanguageClient, textDocument: vscode.TextDocument, p2cConverter: p2c.Converter) {
    // Many "documents" (e.g. the output view, or the .code-workspace file), request diagnostics from the guest. Only service request for documents
    // that the host will know how to fetch diagnostics for.
    if (textDocument.uri.scheme !== Settings.scheme) {
        return;
    }
    await lspClient.onReady();
    let diagnostics = await lspClient.sendRequest<vscodeLSP.Diagnostic[]>('liveshare/diagnosticsDocument', { textDocument: { uri: textDocument.uri.toString() } });
    if (diagnostics && lspClient.diagnostics) {
        lspClient.diagnostics.set(textDocument.uri, p2cConverter.asDiagnostics(diagnostics));
    }
}
