import { Signal } from '@vs/vscs-utils';
import { TelemetryEvent } from '@vs/vso-telemetry';
import { ExtensionUtil } from './utils/ExtensionUtil';
import { TelemetryPropertyNames, TelemetryEventNames  } from './telemetry/TelemetryStrings';
import { vsls } from '@vs/vsls-contracts';
let reconnectionCompleted: Signal<void>;

export function reconnectHostCallback(isConnected: boolean, duration: number) {
    if (!isConnected) {
        reconnectionCompleted = new Signal();

        ExtensionUtil.runWithProgress(async () => { 
            await reconnectionCompleted.promise;
        },{ 
            title: ExtensionUtil.getProgressUpdateString(vsls.WorkspaceProgress.ReconnectingToHost),
        });

        const event = new TelemetryEvent(TelemetryEventNames.REPORT_AGENTPROGRESS, true);
        event.addProperty(TelemetryPropertyNames.EVENT_MESSAGE, vsls.WorkspaceProgress.ReconnectingToHost);
        event.addMeasure(TelemetryPropertyNames.PROGRESS_DURATION, duration);
        event.send();
    } else {
        reconnectionCompleted.resolve();
        const event = new TelemetryEvent(TelemetryEventNames.REPORT_AGENTPROGRESS, true);
        event.addProperty(TelemetryPropertyNames.EVENT_MESSAGE, vsls.WorkspaceProgress.ReconnectedToHost);
        event.addMeasure(TelemetryPropertyNames.PROGRESS_DURATION, duration);
        event.send();
    }
}