import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { IDependencies } from '../contracts/IDependencies';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { AnonymousAccessLevel, workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { getExpService } from '../exp/ExperimentationService';
import { IRpcServiceHandlerInfo } from '@vs/vso-rpc';

/**
 * Access control service implementation
 * 
 * Normally, vsls.AccessControlService is implemented by vsls-agent.
 * As LS web doesn't have the agent, it needs to use this AccessControlService instead.
 * When we switch desktop VSCode LS to use WorkspaceClient instead of vsls-agent, it will use this AccessControlService as well.
 */
export class AccessControlService implements vsls.AccessControlService, IRpcServiceHandlerInfo {
    private sessionNumber: number;
    private accessControl: vsls.AccessControl;

    private readonly accessControlChangedEmitter = new vscode.EventEmitter<vsls.AccessControlEventArgs>();
    public readonly onAccessControlChanged = this.accessControlChangedEmitter.event;

    public constructor(dependencies: IDependencies)
    {
        const sessionInfo = workspaceSessionInfoTracker.workspaceSessionInfo;
        if (!sessionInfo) {
            throw Error('workspaceSessionInfoTracker.workspaceSessionInfo is not set');
        }

        const isReadWriteAnonymousEnabled = getExpService()?.getTreatmentVariable('vscode', 'readWriteAnonymous');
        const isAnonymousExpUserSelectedReadOnly = isReadWriteAnonymousEnabled && getAnonymousAccessLevel() === AnonymousAccessLevel.readOnly;
        const isAnonymous = !isReadWriteAnonymousEnabled && userAuthStateTracker.userInfo?.isAnonymous;

        const workspaceAccessControl = sessionInfo.accessControl!;
        const isUserReadOnly = workspaceAccessControl.defaultAccessControl && workspaceAccessControl.defaultAccessControl.isReadOnly;
        const isReadOnly = !!(isAnonymous || isUserReadOnly || isAnonymousExpUserSelectedReadOnly);

        this.sessionNumber = sessionInfo.sessionNumber;
        this.accessControl = workspaceAccessControl.userAccessControl![sessionInfo.sessionNumber] || { isReadOnly };
        this.setAccessControl(this.accessControl);
        dependencies.workspaceAccessControlService().onAccessControlChanged(this.sessionAcs_AccessControlChanged,this);

        function getAnonymousAccessLevel() {
            const collaboratorManager = dependencies.sessionContext().collaboratorManager;
            if (!collaboratorManager) {
                return;
            }
    
            const userProfile = Object.values(collaboratorManager?.getCollaborators()).find(u => u.id === userAuthStateTracker.userInfo?.id);
            if (!userProfile) {
                return;
            }

            return workspaceSessionInfoTracker.getAnonymousAccess(userProfile.id);
        } 
    }

    public serviceInfo = vsls.AccessControlService;

    public getAccessControlAsync(): Promise<vsls.AccessControl> {
          return Promise.resolve(this.accessControl);
    }

    public setAccessControl(accessControl: vsls.AccessControl) {
        // this check (!=) is intentional
        if (accessControl.isReadOnly != this.accessControl.isReadOnly) {
            this.accessControl = accessControl;
            this.accessControlChangedEmitter.fire({accessControl});
        }
    }

    private sessionAcs_AccessControlChanged(e: vsls.WorkspaceAccessControlEventArgs) {
         const accessControl =  this.getUserAccessControl(e.accessControl);
         this.setAccessControl(accessControl);
    }

    private getUserAccessControl(workspaceAccess: vsls.WorkspaceAccessControl): vsls.AccessControl {
        const perUserAccessControl = workspaceAccess.userAccessControl![this.sessionNumber];
        return perUserAccessControl || workspaceAccess.defaultAccessControl;
    }
}