import { ICommandContext } from '@vs/vscode-command-framework';
import { CommunicationsManager } from '../CommunicationsManager';
import { TelemetryEventNames, ICommand, telemetryCommandDecorator } from '@vs/liveshare-core';
import { ChatEventSource } from '../chat/IChatViewController';

export function builder(): ICommand<void> {
    return new OpenSessionChatCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.CHAT_OPEN_SESSION, TelemetryEventNames.CHAT_OPEN_SESSION_FAULT, 'OpenSessionChat', 1)
class OpenSessionChatCommand implements ICommand<void> {
    public async invoke(item: any, context: ICommandContext): Promise<void> {
        return await CommunicationsManager.openSessionChat(ChatEventSource.command);
    }
}