import { TraceSource } from '@vs/vso-logging';
import * as rpc from 'vscode-jsonrpc';
import { MESSAGE_SERVICE_NAME, MESSAGE_SERVICE_NOTIFICATION_EVENT_NAME } from '../constants';
import { IRpcClientProxy } from '@vs/vso-rpc';

export class MessagingService {
    private isServiceAvailable: boolean;
    private connection: rpc.MessageConnection;

    constructor(
        private name: string,
        private rpcClient: IRpcClientProxy,
        private registeredServicesCallback: () => Promise<string[]>,
        private readonly trace: TraceSource) {
    }

    public async initialize(): Promise<void> {
        // Use the registered audio messaging service. This allows the web extension to
        // communicate with the standalone desktop audio extension. This can be replaced
        // with the source event service when the separate desktop audio extension is deprecated.
        this.name = `${MESSAGE_SERVICE_NAME}.${MESSAGE_SERVICE_NOTIFICATION_EVENT_NAME}`;
        this.connection = await this.rpcClient.ensureConnectionAsync();
        const registeredServices = await this.registeredServicesCallback();
        if (registeredServices?.includes(MESSAGE_SERVICE_NAME)) {
            this.isServiceAvailable = true;
        }
    }

    public onNotify(handler: (message: object) => void): void {
        this.trace.verbose(`onNotify(${this.name})`);
        this.connection.onNotification(this.name, (...argsArray: any[]) => {
            const args: any = argsArray[0];
            this.trace.verbose(`onNotify(${this.name})`);
            try {
                handler(args);
            } catch (e) {
                this.trace.warning(`Notification handler (${this.name}) failed: ` + e.message);
            }
        });
    }

    public notify(args: any): void {
        if (!this.isServiceAvailable) {
            this.trace.verbose(`notify(${this.name}) - service not available`);
            // Notifications do nothing when the service is not available.
            return;
        }
        this.trace.verbose(`notify(${this.name})`);

        try {
            this.connection.sendNotification(this.name, [args]);
        } catch (e) {
            this.trace.warning(`notify(${this.name}) failed: ` + e.message);
        }
    }
}