import { TraceSource } from '@vs/vso-logging';
import { ILogger } from '@vs/vso-logging';
import { ILiveShareConnectionMockOptions } from '../interfaces/ILiveShareConnectionMockOptions';
import { Performance } from '@vs/vscs-performance';
import { randomString } from '@vs/vscs-utils';
import { IWorkspaceSessionInfo } from '@vs/vso-workspace-core/src/IWorkspaceSessionInfo';
import { PerformanceMock } from './getConnectionMockOptions';

export const testTrace = new TraceSource(randomString());

export type TLiveShareConnectionMockOptions = [
    ILogger,
    Performance,
    ILiveShareConnectionMockOptions
];

export const getRandomLiveShareMockOptions = (): ILiveShareConnectionMockOptions => {
    const connectionInfo: IWorkspaceSessionInfo = {
        id: 'mock-connection-id',
        relayLink: 'sb://test-namespace.servicebus.windows.net/anyEndpointId',
        relaySas: 'mock-relay',
        hostPublicKeys: ['mock-host-public-key'],
        sessionToken: 'mock-session-token',
    };

    return {
        liveShareEndpoint: 'mock-liveshare-endpoint',
        workspaceId: 'mock-id',
        connectionInfo,
        token: 'mock-token',
        id: 'mock-id',
        someProp: 'mock-prop',
        numericProp: 12345,
    };
};

interface IOptions {
    trace?: ILogger;
}

/**
 * Mock helper to generate default `LiveShareConnectionMock` options.
 * Pass real trace if you want to see logs in the console.
 */
export const getLiveShareConnectionMockOptions = (
    options: IOptions = {}
): TLiveShareConnectionMockOptions => {
    const { trace = testTrace } = options;
    const performance = new PerformanceMock('test-performance', 'test-start', 'test-path-string');
    return [trace, performance, { ...getRandomLiveShareMockOptions() }];
};
