const readLastLines: (file: string, lineCount: number, encoding?: string) => Promise<string> =
    require('read-last-lines').read;

export function readLastNLinesFromFile(filePath: string, numLines: number): Promise<string> {
    return filePath ? readLastLines(filePath, numLines) : Promise.resolve('');
}
