import { SettingKeys } from '@vs/liveshare-core';
import { AnonymousGuestApprovalStrategy } from './anonymousGuestApprovalStrategy';
import { ConnectionModeStrategy } from './connectionModeStrategy';
import { PolicyResolutionStrategy } from './policyResolutionStrategy';
import { AllowedDomainsStrategy } from './allowedDomainsStrategy';
import { BooleanStrategy } from './booleanStrategy';

export interface ResolutionFactoryConfig {
    boolStrategy: PolicyResolutionStrategy<boolean>;
    inversedBoolStrategy: PolicyResolutionStrategy<boolean>;
    connectionModeStrategy: PolicyResolutionStrategy<string>;
    anonymousGuestApprovalStrategy: PolicyResolutionStrategy<string>;
    allowedDomainsStrategy: PolicyResolutionStrategy<Array<string>>;
}

export class DefaultFactoryConfig implements ResolutionFactoryConfig {
    public readonly boolStrategy: PolicyResolutionStrategy<boolean> = new BooleanStrategy();
    public readonly inversedBoolStrategy: PolicyResolutionStrategy<boolean> = new BooleanStrategy(true);
    public readonly connectionModeStrategy: PolicyResolutionStrategy<string> = new ConnectionModeStrategy();
    public readonly anonymousGuestApprovalStrategy: PolicyResolutionStrategy<string> = new AnonymousGuestApprovalStrategy();
    public readonly allowedDomainsStrategy: PolicyResolutionStrategy<Array<string>> = new AllowedDomainsStrategy();
}

export class ResolutionStrategyFactory {
    private config: ResolutionFactoryConfig;

    constructor (config?: ResolutionFactoryConfig) {
        this.config = config || new DefaultFactoryConfig();
    }

    public resolve<T>(settingKey: SettingKeys, first: T, second: T): T | undefined {
        let strategy = this.getResolutionStrategy(settingKey);

        if (!strategy) {
            return undefined;
        }

        return strategy.resolvePolicy([first, second]);
    }

    private getResolutionStrategy(settingKey: SettingKeys): PolicyResolutionStrategy<any> | undefined {
        switch (settingKey) {
            case SettingKeys.allowGuestDebugControl:
            case SettingKeys.allowGuestTaskControl:
            case SettingKeys.autoShareServers:
                return this.config.boolStrategy;

            case SettingKeys.allowReadWriteTerminals:
                return this.config.inversedBoolStrategy;

            case SettingKeys.connectionMode:
                return this.config.connectionModeStrategy;

            case SettingKeys.anonymousGuestApproval:
                return this.config.anonymousGuestApprovalStrategy;
            case SettingKeys.allowedDomains:
                return this.config.allowedDomainsStrategy;
            default:
                return undefined;
        }
    }
}
