import { ExtensionUtil } from '@vs/liveshare-core';

export interface IBrowserUtil {
    openBrowser(uri: string): void;
}

/**
 * Helper functions for working with the browser.
 */
export class BrowserUtil implements IBrowserUtil {
    public openBrowser(uri: string): void {
        // there is additional logic for UI tests inside the `ExtensionUtil.openBrowser` method
        return ExtensionUtil.openBrowser(uri);
    }
}