import {
    Telemetry,
    ITimedEvent,
    TelemetryResult,
    ITelemetry,
    TelemetryPropertyNames as OfficialTelemetryPropertyNames,
} from '@vs/vso-telemetry';

import { ICommandContext } from '../types/ICommandContext';
import { ICommandDecoratorCallback } from '../types/ICommandDecoratorCallback';
import { TelemetryUtil } from '../telemetry/TelemetryUtil';
import { TelemetryPropertyNames } from '../telemetry/telemetryStrings';
import { CommandDecoratorBase, CommandInvoke, CommandDecorator } from './CommandDecoratorBase';

export function telemetryCommandDecorator(
    telemetryEventName: string,
    telemetryFaultEventName: string,
    commandTitle: string,
    telemetryEventVersion: number = 1,
    onError?: ICommandDecoratorCallback,
): CommandDecorator {
    return new TelemetryCommandDecorator(
        Telemetry,
        telemetryEventName,
        telemetryFaultEventName,
        commandTitle,
        telemetryEventVersion,
        onError,
    ).setup();
}

/**
 * Instrumentation `commandHandler` that automatically sets up any
 * default telemetry and tracing for a given command.
 */
export class TelemetryCommandDecorator extends CommandDecoratorBase {
    constructor(
        private telemetry: ITelemetry,
        private telemetryEventName: string,
        private telemetryFaultEventName: string,
        private commandTitle: string,
        private telemetryEventVersion: number,
        private readonly onError?: ICommandDecoratorCallback,
    ) {
        super();
    }

    public async invoke<T>(
        commandInvoke: CommandInvoke<T>,
        options: any,
        context: ICommandContext,
    ): Promise<T> {
        let result: T;
        let error: any = undefined;

        let telemetryEvent = this.telemetry.startTimedEvent(this.telemetryEventName);
        let telemetryResult: TelemetryResult = TelemetryResult.Success;
        let telemetryMessage: string = '';

        context.telemetryEvent = telemetryEvent;

        this.telemetry.setCorrelationEvent(telemetryEvent);
        telemetryEvent.addProperty(TelemetryPropertyNames.COMMAND_TEXT, context.commandText);
        telemetryEvent.addMeasure(
            TelemetryPropertyNames.TELEMETRY_EVENT_VERSION,
            this.telemetryEventVersion,
        );

        this.addInvocationTelemetryProperties(telemetryEvent, options.telemetryProperties);

        try {
            result = await commandInvoke(options, context);

            telemetryEvent.addProperty(
                OfficialTelemetryPropertyNames.EVENT_RESULT,
                TelemetryResult.Success,
            );
        } catch (e) {
            telemetryResult = TelemetryUtil.DeriveTelemetryResult(e);
            telemetryMessage = TelemetryUtil.BuildTelemetryMessage(
                this.commandTitle,
                telemetryResult,
                e.message,
            );

            telemetryEvent.addProperty(
                OfficialTelemetryPropertyNames.EVENT_RESULT,
                telemetryResult,
            );

            if (this.onError) {
                this.onError(e, context, options);
            }

            this.telemetry.sendFault(
                this.telemetryFaultEventName,
                TelemetryUtil.MapTelemetryResultToFaultType(telemetryResult),
                telemetryMessage,
                e,
            );

            error = e;

            throw e;
        } finally {
            telemetryMessage =
                telemetryMessage ||
                TelemetryUtil.BuildTelemetryMessage(this.commandTitle, TelemetryResult.Success);
            const duration = telemetryEvent.end(telemetryResult, telemetryMessage);

            context.trace.traceEvent(
                TelemetryUtil.MapTelemetryResultToTraceEventType(telemetryResult),
                0,
                `Command [${context.commandName}]: ${telemetryMessage} (${duration}ms)`,
            );

            // noting that we have logged the error. We will check this up stream
            if (error) {
                error.hasRecorded = true;
            }
        }

        return result;
    }

    private addInvocationTelemetryProperties(
        telemetryEvent: ITimedEvent,
        properties: { [key: string]: any } = {},
    ) {
        for (let propertyName of Object.keys(properties)) {
            telemetryEvent.addProperty(propertyName, properties[propertyName]);
        }
    }
}
