import { LogLevel } from '@vs/vso-logging';
import { CommandError } from '../types/CommandError';
import { TelemetryResult, FaultType as TelemetryFaultType } from '@vs/vso-telemetry';
/**
 * Helper functions for sending telemetry events.
 */
export class TelemetryUtil {
    public static DeriveTelemetryResult(error: Error): TelemetryResult {
        if (error instanceof CommandError) {
            return error.telemetryResult;
        }
        return TelemetryResult.Failure;
    }

    public static DeriveTelemetryTitle(command: string, result: TelemetryResult): string {
        // TODO: Could auto convert enum to friendly string.
        let category = 'Success';
        if (result === TelemetryResult.UserFailure) {
            category = 'User Failure';
        } else if (result === TelemetryResult.Cancel) {
            category = 'Cancelled';
        } else if (result === TelemetryResult.IndeterminateFailure) {
            category = 'Indeterminate Failure';
        } else if (result === TelemetryResult.Failure) {
            category = 'Failure';
        } else if (result === TelemetryResult.NonBlockingFailure) {
            category = 'Non Blocking Failure';
        } else if (result === TelemetryResult.ByDesignFailure) {
            category = 'By Design Failure';
        }

        return `${command} ${category}`;
    }

    public static BuildTelemetryMessage(command: string, result: TelemetryResult, error?: string) {
        let errorPostfix = '';
        if (error !== undefined) {
            errorPostfix = `: ${error}`;
        }

        return `${this.DeriveTelemetryTitle(command, result)}${errorPostfix}`;
    }

    public static MapTelemetryResultToFaultType(result: TelemetryResult): TelemetryFaultType {
        // TODO: Can we unify on one enum type.
        switch (result) {
            case TelemetryResult.UserFailure:
                return TelemetryFaultType.User;
            case TelemetryResult.Cancel:
                return TelemetryFaultType.UserCancelled;
            case TelemetryResult.Failure:
                return TelemetryFaultType.Error;
            case TelemetryResult.NonBlockingFailure:
                return TelemetryFaultType.NonBlockingFault;
            case TelemetryResult.ByDesignFailure:
                return TelemetryFaultType.ByDesign;

            case TelemetryResult.IndeterminateFailure:
            default:
                return TelemetryFaultType.Unknown;
        }
    }

    public static MapTelemetryResultToTraceEventType(result: TelemetryResult): LogLevel {
        return result === TelemetryResult.Success ? LogLevel.Info : LogLevel.Error;
    }
}
