let localizeInstance = (key: string) => {
    if (defaults.hasOwnProperty(key)) {
        return defaults[key];
    }

    return key;
};

export function setLocalizeCallback(callback: (key: string) => string) {
    localizeInstance = callback;
}

export function localize(key: string): string {
    return localizeInstance(key);
}

export function localizeDate(key: Date): string {
    return key.toLocaleString();
} 
