'use strict';

import * as vscode from 'vscode';
import { Disposable } from 'vscode';

import { IHostCoauthorCommitMessageUpdater, IHostSourceControlService } from './Contracts';
import { IDependencies as ICoreDependencies, Settings, SettingKeys } from '@vs/liveshare-core';
import { IDependencies } from '../IDependencies';

import {
    ISessionContext,
    workspaceSessionInfoTracker
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
const COAUTHORED_COMMIT_MESSAGE_PREFIX = 'Co-authored-by: ';

export class HostCoauthorCommitMessageUpdater implements IHostCoauthorCommitMessageUpdater {
    private readonly sourceControl: IHostSourceControlService;
    private readonly sessionContext: ISessionContext;
    private readonly workspaceUserService: vsls.WorkspaceUserService;
    private disposables: Disposable[] = [];
    private coauthors: string[] = [];

    constructor(coreDependencies: ICoreDependencies, sourceControl: IHostSourceControlService) {
        this.sourceControl = sourceControl;
        this.sessionContext = coreDependencies.sessionContext();
        this.workspaceUserService = coreDependencies.workspaceUserService();
    }

    public async init() {
        this.workspaceUserService.onWorkspaceSessionChanged(this.onWorkspaceSessionChanged, this, this.disposables);
        vscode.workspace.onDidChangeConfiguration(e => {
            if (e.affectsConfiguration('liveshare.populateGitCoAuthors')) {
                this.updateCommitMessageIfEnabled();
            }
        }, this.disposables);
    }

    public async dispose() {
        this.disposables.forEach(d => d.dispose());
        this.disposables = [];
        this.coauthors = [];
    }

    private onWorkspaceSessionChanged({ changeType, userProfile }: vsls.WorkspaceSessionChangedEventArgs) {
        if (changeType === vsls.WorkspaceSessionChangeType.Joined) {
            this.addCoauthor(userProfile);
        }
    }

    private addCoauthor(profile?: vsls.WorkspaceUserProfile | undefined) {
        if (!profile || profile.isOwner || !profile.name || !profile.email || profile.isAnonymous) {
            return;
        }

        const coauthor = `${COAUTHORED_COMMIT_MESSAGE_PREFIX}${profile.name} <${profile.email}>`;
        if (!this.coauthors.includes(coauthor)) {
            this.coauthors.push(coauthor);
        }

        this.updateCommitMessageIfEnabled();
    }

    private updateCommitMessageIfEnabled() {
        if (Settings.get<string>(SettingKeys.populateGitCoAuthors) === 'always' && !workspaceSessionInfoTracker.isReadOnly) {
            this.sourceControl.updateCommitMessage(this.updateCoauthorsInCommitMessage.bind(this));
        }
    }

    private updateCoauthorsInCommitMessage(message: string): string {
        if (this.coauthors.length) {
            message = message || '';

            if (!message.includes(COAUTHORED_COMMIT_MESSAGE_PREFIX)) {
                message += '\n';
            }

            for (const coauthor of this.coauthors) {
                if (message.includes(coauthor)) {
                    continue;
                }

                message += '\n' + coauthor;
            }
        }

        return message;
    }
}
