import { ConnectionHub } from '@vs/vscs-connection-hub';
import { once, TConstructable } from "@vs/vscs-utils";
import { ILogger } from '@vs/vso-logging';

import { HubClientConnection } from './HubClientConnection';
import { performance } from '../performance/performance';

/**
 * "Persistent" conenction hub that maintains
 * conenction in a separate process.
 */
export const initWorkspaceHubConnectionHub = once((
    trace: ILogger,
): ConnectionHub<TConstructable<HubClientConnection>> => {
    // connection in separate process
    const remoteConnectionHub = new ConnectionHub(
        trace.createChild('sudo-pf-remote'),
        performance,
        HubClientConnection,
    );

    return remoteConnectionHub;
});
