import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { ILogger } from '@vs/vso-logging';
import { HubClient } from '@vs/vso-signalr-client';
import { ContactServiceProxy, RelayServiceProxy } from '@vs/vso-signalr-client-proxy';
import { IHubConnectionService, HubProxyType } from '@vs/liveshare-core';
import * as signalR from '@microsoft/signalr';
import * as signalRProtocol from '@microsoft/signalr-protocol-msgpack';

function createLoggerAdapter(traceSource: ILogger, logLevelSet?: signalR.LogLevel): signalR.ILogger {
    return {
        log: (logLevel: signalR.LogLevel, message: string) => {
            if (!logLevelSet || logLevel >= logLevelSet) {
                traceSource.log(logLevel + 1, message);
            }
        }
    };
}


export class HubConnectionService implements IHubConnectionService {
    private readonly connectionStateChangedEmitter = new vscode.EventEmitter<void>();
    private readonly attemptStateChangedEmitter = new vscode.EventEmitter<void>();

    public readonly onConnectionStateChanged = this.connectionStateChangedEmitter.event;
    public readonly onAttemptStateChanged = this.attemptStateChangedEmitter.event;

    private hubClientInstance: HubClient;
    private currentUserInfoInstance: vsls.AuthenticatedUserInfo;
    private enabledFlag: boolean;
    private proxies = new Map<HubProxyType, any>();
    private proxyFactories = new Map<HubProxyType, () => any>();

    private constructor(
        private authCoreService: vsls.AuthenticationCoreService,
        signalRServiceUri: string,
        private traceSource: ILogger,
        enableHttpConnectionLogging?: boolean) {

        const loggerAdapter = createLoggerAdapter(traceSource, signalR.LogLevel.Information);
        let hubBuilder = new signalR.HubConnectionBuilder().withUrl(signalRServiceUri,{
                logger: enableHttpConnectionLogging ? createLoggerAdapter(traceSource) : undefined,
                accessTokenFactory: () => this.accessToken(),
            })
            .configureLogging(loggerAdapter);
        hubBuilder = hubBuilder.withHubProtocol(new signalRProtocol.MessagePackHubProtocol());
        this.hubClientInstance = HubClient.createWithHub(hubBuilder.build(), loggerAdapter);

        this.hubClientInstance.onConnectionStateChanged(() => {
            this.traceSource.verbose(`ConnectionStateChanged isConnected:${this.isConnected}`);
            this.connectionStateChangedEmitter.fire();
            return Promise.resolve();
        });

        this.authCoreService.onAuthenticationChanged((e) => {
            const authUserInfo = new vsls.AuthenticatedUserInfo();
            authUserInfo.accessToken = e.accessToken;
            authUserInfo.userInfo = e.account;
            this.setAuthenticatedUserInfo(authUserInfo);
        });

        // define supported proxy factories
        this.proxyFactories.set(HubProxyType.ContactService, () => new ContactServiceProxy(this.hubClientInstance.hubProxy, createLoggerAdapter(traceSource.withName('ContactServiceProxy')), true));
        this.proxyFactories.set(HubProxyType.RelayService, () => new RelayServiceProxy(this.hubClientInstance.hubProxy, createLoggerAdapter(traceSource.withName('RelayServiceProxy')), true));
    }

    public static async create(
        authCoreService: vsls.AuthenticationCoreService,
        signalRServiceUri: string,
        traceSource: ILogger): Promise<HubConnectionService> {
        const hubConnectionService = new HubConnectionService(authCoreService, signalRServiceUri, traceSource);
        const authenticatedUserInfo = await authCoreService.getCurrentAuthenticatedUserAsync();
        if (authenticatedUserInfo != null) {
            hubConnectionService.setAuthenticatedUserInfo(authenticatedUserInfo);
        }

        return hubConnectionService;
    }

    public setEnabled(newState: boolean): Promise<void> {
        this.enabled = newState;
        return Promise.resolve();
    }

    public getOrCreateProxy<T>(type: HubProxyType): T {
        let instance: T;

        if (this.proxies.has(type)) {
            instance = this.proxies.get(type);
        } else {
            if (!this.proxyFactories.has(type)) {
                throw new Error(`Type:${type} not supported`);
            }

            instance = this.proxyFactories.get(type)();
            this.proxies.set(type, instance);
        }

        return instance;
    }

    public get hubClient(): HubClient {
        return this.hubClientInstance;
    }

    public get hubConnection(): signalR.HubConnection {
        return this.hubClientInstance.hubConnection;
    }

    public get enabled(): boolean {
        return this.enabledFlag;
    }

    public set enabled(enabled: boolean) {
        if (this.enabledFlag !== enabled) {
            this.enabledFlag = enabled;
            this.updateHubClientConnection();
        }
    }

    public get isConnected(): boolean {
        return this.hubClientInstance.isConnected;
    }

    public get isAttempting(): boolean {
        return this.hubClientInstance.isRunning;
    }

    public get isConnectionEnabled(): boolean {
        return this.shouldConnect(); // && !isAccessTokenExpired(AccessToken);
    }

    public get currentUserInfo(): vsls.AuthenticatedUserInfo | undefined {
        return this.currentUserInfoInstance;
    }

    private shouldConnect(): boolean {
        return this.accessToken() && this.currentUserInfoInstance.userInfo !== undefined;
    }

    private accessToken(): string | undefined {
        if (this.currentUserInfoInstance) {
            return this.currentUserInfoInstance.accessToken;
        }
    }

    private setAuthenticatedUserInfo(authenticatedUserInfo: vsls.AuthenticatedUserInfo): void {
        this.traceSource.verbose('setAuthenticatedUserInfo');

        this.currentUserInfoInstance = authenticatedUserInfo;
        this.updateHubClientConnection();
    }

    private updateHubClientConnection(): void {
        if (!this.shouldConnect() || !this.enabledFlag) {
            if (this.hubClientInstance.isRunning) {
                this.traceSource.verbose('updateHubClientConnection->StopAsync');

                this.hubClientInstance.stop();
                this.fireIsAttemptingChanged();
            }
        } else {
            if (this.enabledFlag && this.shouldConnect() && !this.hubClientInstance.isRunning) {
                this.traceSource.verbose('updateHubClientConnection->StartAsync');

                this.hubClientInstance.start();
                this.fireIsAttemptingChanged();
            }
        }
    }

    private fireIsAttemptingChanged(): void {
        this.attemptStateChangedEmitter.fire();
    }
}