import * as vscode from 'vscode';
import * as vscodeLSP from 'vscode-languageclient';
import * as CircularJson from 'circular-json';
import * as crypto from 'crypto';
import { ConverterExtension } from './ConverterExtension';
import * as p2cExt from './protocol2codeExtension';

export const REMOTE_COMMAND_NAME: string = '_liveshare.remotecommand';
export const REMOTE_CODE_LENS_NAME: string = 'liveshare.remotecodelens';
export const REMOTE_CODE_ACTION_NAME: string = 'liveshare.remotecodeaction';

// Commands that should run directly on the guest machine
const localCommands = ['vscode.open', 'editor.action.showReferences', 'merge-conflict.compare'];

/**
 * Some VSCode commands have constraints on their parameters and validate the types at runtime. 
 * For paratmers of type Uri lose their type identity when serialized to JSON and re-hydrated. 
 * So for the vscode commands where constraints are enforced, we need to handle the serialization and deserialization.
 * The list of VS Code commands with their constraints is here - https://github.com/Microsoft/vscode/blob/master/src/vs/workbench/api/node/extHostApiCommands.ts
 */
const commandConverters: { [commandName: string]: CommandConverter } = {};

export function isSafeCommand(command: string): boolean {
    return command.startsWith('vscode') || command.startsWith('editor');
}

/**
 * Wrap the given vscode command as the argument of a specific REMOTE_COMMAND_NAME for which the guest registers a handler.
 * The handler knows to either send the command back to the host or execute locally on the guest.
 */
function constructRemoteCommand(command: vscode.Command, args: any[], c2pConverter: vscodeLSP.Code2ProtocolConverter): vscodeLSP.Command {
    let remoteCommand = {
        title: command.title, 
        command: REMOTE_COMMAND_NAME,
        tooltip: command.tooltip,
        arguments: args
    };
    return c2pConverter.asCommand(remoteCommand);
}

export function hashCommand(command: vscode.Command): string {
    let commandStr: string;
    try {
        commandStr = JSON.stringify(command);
    } catch (e) {
        commandStr = CircularJson.stringify(command);
    }
    const hmac = crypto.createHmac('sha256', 'key');
    hmac.update(commandStr);
    return hmac.digest('hex');
}

function wrapCommand(remoteCommandName: string, command: vscode.Command, c2pConverter: vscodeLSP.Code2ProtocolConverter, c2pConverterExtension: ConverterExtension, args?: any[]): vscodeLSP.Command {
    if (localCommands.indexOf(command.command) >= 0) {
        const commandConverter = commandConverters[command.command];
        if (commandConverter) {
            command = commandConverter.toProtocol(command, c2pConverter, c2pConverterExtension);
        }
        return constructRemoteCommand(command, [command], c2pConverter);
    } else {
        let commandArgs = [remoteCommandName, hashCommand(command)];
        if (args) {
            commandArgs = commandArgs.concat(args);
        }
        // For reverse compatability
        const dummyCommand: vscode.Command = {
            title: 'DummyTitle',
            command: 'NotALocalCommand',
            arguments: commandArgs
        };
        return constructRemoteCommand(command, [dummyCommand], c2pConverter);
    }
}

export function wrapCodeLensCommand(command: vscode.Command, uri: vscode.Uri, c2pConverter: vscodeLSP.Code2ProtocolConverter, c2pConverterExtension: ConverterExtension): vscodeLSP.Command {
    return wrapCommand(REMOTE_CODE_LENS_NAME, command, c2pConverter, c2pConverterExtension, [c2pConverter.asUri(uri)]);
}

export function wrapCodeActionCommand(command: vscode.Command, uri: vscode.Uri, range: vscode.Range, c2pConverter: vscodeLSP.Code2ProtocolConverter, c2pConverterExtension: ConverterExtension): vscodeLSP.Command {
    return wrapCommand(REMOTE_CODE_ACTION_NAME, command, c2pConverter, c2pConverterExtension, [c2pConverter.asUri(uri), c2pConverter.asRange(range)]);
}

function executeLocalCommand(command: vscode.Command, p2cConverter: vscodeLSP.Protocol2CodeConverter) {
    const commandConverter = commandConverters[command.command];
    if (commandConverter) {
        command = commandConverter.toCode(command, p2cConverter);
    }
    let commandArgs = command.arguments || [];
    vscode.commands.executeCommand(command.command, ...commandArgs);
}

async function executeRemoteCommand(command: vscode.Command, lspClient: vscodeLSP.LanguageClient) {
    let params: vscodeLSP.ExecuteCommandParams = { // Remote command to host
        command: command.command,
        arguments: command.arguments
    };

    const commandRun = await lspClient.sendRequest(vscodeLSP.ExecuteCommandRequest.type, params);
    if (typeof commandRun === 'boolean' && !commandRun) { // Older clients may return null rather than a boolean
        let result = await vscode.window.showErrorMessage(
            'The host doesn’t allow running this command. If needed, ask them to enable it.',
            'More info');
        if (result) {
            vscode.env.openExternal(vscode.Uri.parse('https://aka.ms/vsls-security#code-commands'));
        }
    }
}

/**
 * The handler for the LiveShare remote command that knows to either run a command locally or send it to the host for execution.
 * These are commands returned for CodeActions or CodeLenses.
 */
export async function handleLiveShareRemoteCommand(args: any, lspClient: vscodeLSP.LanguageClient, p2cConverter: vscodeLSP.Protocol2CodeConverter) {
    if (args.command) { // A Command returned by VS or VS Code
        let command: vscode.Command = args;
        if (localCommands.indexOf(command.command) >= 0) { // Run command locally
            executeLocalCommand(command, p2cConverter);
        } else {
            await executeRemoteCommand(command, lspClient);
        }
    } else if (args.edit) { // A CodeAction returned by VS (VS Code doesn't wrap CodeActions in Commands)
        let workspaceEdit: vscodeLSP.WorkspaceEdit = args.edit;
        vscode.workspace.applyEdit(p2cConverter.asWorkspaceEdit(workspaceEdit));
    }
}

interface CommandConverter {
    toProtocol: (command: vscode.Command, c2p: vscodeLSP.Code2ProtocolConverter, c2pExt: ConverterExtension) => vscode.Command;
    toCode: (command: vscode.Command, p2c: vscodeLSP.Protocol2CodeConverter) => vscode.Command;
}

const openCommandConverter: CommandConverter = {
    toProtocol: (command: vscode.Command, c2p: vscodeLSP.Code2ProtocolConverter, c2pExt: ConverterExtension): vscode.Command => {
        let uri: vscode.Uri = command.arguments[0];
        command.arguments[0] = c2p.asUri(uri);
        return command;
    },
    toCode: (command: vscode.Command, p2c: vscodeLSP.Protocol2CodeConverter): vscode.Command => {
        let uri: string = command.arguments[0];
        command.arguments[0] = p2c.asUri(uri);
        return command;
    }
};

const showReferencesCommandConverter: CommandConverter = {
    toProtocol: (command: vscode.Command, c2p: vscodeLSP.Code2ProtocolConverter, c2pExt: ConverterExtension): vscode.Command => {
        let uri = command.arguments[0] as vscode.Uri;
        let position = command.arguments[1] as vscode.Position;
        let locations = command.arguments[2] as vscode.Location[];
        command.arguments[0] = c2p.asUri(uri);
        command.arguments[1] = c2p.asPosition(position);
        command.arguments[2] = locations.map(l => c2pExt.asLocation(l));
        return command;
    },
    toCode: (command: vscode.Command, p2c: vscodeLSP.Protocol2CodeConverter): vscode.Command => {
        let uri: string = command.arguments[0];
        let position = command.arguments[1] as vscodeLSP.Position;
        let locations = command.arguments[2] as vscodeLSP.Location[];
        command.arguments[0] = p2c.asUri(uri);
        command.arguments[1] = p2c.asPosition(position);
        command.arguments[2] = locations.map(l => p2cExt.asLocation(l, p2c));
        return command;
    }
};

const mergeConflictCompareCommandConverter: CommandConverter = {
    toProtocol: (command: vscode.Command, c2p: vscodeLSP.Code2ProtocolConverter, c2pExt: ConverterExtension): vscode.Command => {
        const currentRange: vscodeLSP.Range = c2p.asRange(command.arguments[0].current.content);
        const incomingRange: vscodeLSP.Range = c2p.asRange(command.arguments[0].incoming.content);
        command.arguments = [currentRange, incomingRange];
        return command;
    },
    toCode: (command: vscode.Command, p2c: vscodeLSP.Protocol2CodeConverter): vscode.Command => {
        command.arguments = [{
            current: {
                content: p2c.asRange(command.arguments[0])
            },
            incoming: {
                content: p2c.asRange(command.arguments[1])
            }
        }];
        return command;
    }
};

commandConverters['vscode.open'] = openCommandConverter;
commandConverters['editor.action.showReferences'] = showReferencesCommandConverter;
commandConverters['merge-conflict.compare'] = mergeConflictCompareCommandConverter;
