import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { IContextUtil } from '../utils/ContextUtil';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { dependencies } from '../Dependencies';
import { ISessionContext } from '../ISessionContext';
import { sessionStateTracker } from '../SessionStateTracker';
import { TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import {
    SessionState,
    SessionAction,
    SessionStateChangedEventArgs,
} from '../SessionTypes';

export function telemetryStatusCommandDecorator() {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new TelemetryStatusCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.sessionContext(),
            dependencies.contextUtil()));
}

/**
 * Adds telemetry marktimes based on session state and status updates.
 */
export class TelemetryStatusCommandDecorator implements ICommandDecorator {
    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private sessionContext: ISessionContext,
        private contextUtil: IContextUtil) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;

        const trackingStateHits: { [key: string]: number; } = {};
        const startingState = `liveshare.SessionState.${this.deriveEventName(SessionState[sessionStateTracker.State], trackingStateHits)}`;
        const trackingStateOrder: string[] = [ startingState ];
        const trackingActionHits: { [key: string]: number; } = {};
        const trackingActionOrder: string[] = [];
        const trackingStatusHits: { [key: string]: number; } = {};
        const trackingStatusOrder: string[] = [];

        const stateCallback = (e: SessionStateChangedEventArgs) => {
            context.trace.info(`SessionContext: State update from "${SessionState[e.oldState]}" (${SessionAction[e.oldAction]}) to "${SessionState[e.newState]}" (${SessionAction[e.newAction]}).`);

            const stateName = `liveshare.SessionState.${this.deriveEventName(SessionState[e.newState], trackingStateHits)}`;
            trackingStateOrder.push(stateName);
            const actionName = `liveshare.SessionAction.${this.deriveEventName(SessionAction[e.newAction], trackingActionHits)}`;
            trackingActionOrder.push(actionName);
        };
        const statusCallback = (e: { newStatus: string, oldStatus: string }) => {
            const oldStatus = this.contextUtil.scrubPrefix(e.oldStatus);
            const newStatus = this.contextUtil.scrubPrefix(e.newStatus);
            context.trace.info(`SessionContext: Status update from "${oldStatus}" to "${newStatus}".`);

            const statusName = `liveshare.SessionStatus.${this.deriveEventName(newStatus, trackingStatusHits)}`;
            context.telemetryEvent.markTime(statusName);
            trackingStatusOrder.push(statusName);
        };

        let stateChangedRegistration: vscode.Disposable;
        let statusChangedRegistration: vscode.Disposable;
        try {
            stateChangedRegistration = sessionStateTracker.onStateChanged(stateCallback);
            statusChangedRegistration = sessionStateTracker.onStatusChanged(statusCallback);

            context.telemetryEvent.addProperty(TelemetryPropertyNames.STATE_EVENT_FIRST, `liveshare.SessionState.${SessionState[sessionStateTracker.State]}`.toLowerCase());

            result = await this.next.invoke(options, context);
        } finally {
            context.telemetryEvent.addProperty(TelemetryPropertyNames.STATE_EVENT_ORDER, trackingStateOrder.length > 0 ? String(trackingStateOrder).toLowerCase() : '');
            context.telemetryEvent.addProperty(TelemetryPropertyNames.STATUS_EVENT_ORDER, trackingStatusOrder.length > 0 ? String(trackingStatusOrder).toLowerCase() : '');
            context.telemetryEvent.addProperty(TelemetryPropertyNames.STATE_EVENT_LAST, `liveshare.SessionState.${SessionState[sessionStateTracker.State]}`.toLowerCase());

            if (stateChangedRegistration) stateChangedRegistration.dispose();
            if (statusChangedRegistration) statusChangedRegistration.dispose();
        }

        return result;
    }

    private deriveEventName(name: string, tracking: { [key: string]: number; }): string {
        const occurances = (tracking[name] = tracking[name] !== undefined ? tracking[name] + 1 : 0);
        
        return (occurances > 0) ? `${name + occurances}` : name;
    }
}