import * as vscode from 'vscode';
import { Disposable, Inittable } from '@vs/vscode-command-framework';
import { sessionStateTracker } from './SessionStateTracker';
import { SessionState, SessionStateChangedEventArgs } from './SessionTypes';

export interface ISessionStateHandler {
    handleSessionStateChanged(newState: SessionState, previousState: SessionState): Promise<void>;
    dispose?: () => Promise<void>;
}

export interface ISessionStateManager {
    registerHandler(handler: ISessionStateHandler): void;
    dispose(): Promise<void>;
}

export class SessionStateManager extends Inittable(Disposable(Object)) implements ISessionStateManager {
    private readonly stateChangedRegistration: vscode.Disposable;
    private readonly handlers: ISessionStateHandler[] = [];

    constructor() {
        super();

        this.stateChangedRegistration = sessionStateTracker.onStateChanged(
            (e: SessionStateChangedEventArgs) => this.handleSessionStateChanged(e.newState, e.oldState));
    }

    public registerHandler(handler: ISessionStateHandler) {
        this.handlers.push(handler);
    }

    public async dispose() {
        this.stateChangedRegistration.dispose();

        await Promise.all(this.handlers.map(h => {
            if (h.dispose) {
                return h.dispose();
            }

            return Promise.resolve();
        }));

        await super.dispose();
    }

    private async handleSessionStateChanged(newState: SessionState, previousState: SessionState): Promise<void> {
        await Promise.all(this.handlers.map(h => h.handleSessionStateChanged(newState, previousState)));
    }
}