import * as url from 'url';
import { Signal } from '@vs/vscs-utils';
import { ExtensionUtil } from './utils/ExtensionUtil';
import { LIVESHARE_EXTENSION_ID } from './constants';
import * as semver from 'semver';
import * as vscode from 'vscode';

import { ILogger } from '@vs/vso-logging';
import { initRemoteFileSubscribe, loadFilefromCache } from '@core-abstractions/remoteFileProvider';
import { getPlatform } from '@core-abstractions/platform';

const remoteSettingsFileName = 'remoteSettings.json';

/**
 * Corresponds to the `priority` type defined in `remoteSettings-schema.json`.
 */
export const enum RemoteSettingPriority {
    default = 'default',
    override = 'override',
}

/**
 * Corresponds to the `os` type defined in `remoteSettings-schema.json`.
 */
export const enum RemoteSettingOS {
    win = 'win',
    mac = 'mac',
    linux = 'linux',
}

/**
 * Corresponds to the `conditions` type defined in `remoteSettings-schema.json`.
 */
export interface RemoteSettingConditions {
    os?: RemoteSettingOS | RemoteSettingOS[];
    extensionVersion?: string;
    ideVersion?: string;
}

/**
 * Corresponds to the `setting` type defined in `remoteSettings-schema.json`.
 */
export interface RemoteSetting {
    conditions?: RemoteSettingConditions;
    priority?: RemoteSettingPriority;
    value: any;
}

// The remote settings file is a dictionary mapping from setting names to
// either (non-conditional) single settings or (conditional) settings arrays.
type RemoteSettings = { [key: string]: RemoteSetting | RemoteSetting[] };

/**
 * Manages downloading and periodically updating settings from a file that is
 * published online. The main config module merges these remote settings with
 * locally-defined internal and user settings.
 */
class RemoteConfig {
    private static singleton: RemoteConfig;

    private settingsFileUri: url.Url | undefined;
    private extensionVersion: string | undefined;
    private settings: RemoteSettings | null = null;
    private updated = false;
    private updateSignal = new Signal<void>();

    public static get Instance(): RemoteConfig {
        if (!RemoteConfig.singleton) {
            RemoteConfig.singleton = new RemoteConfig();
        }
        return RemoteConfig.singleton;
    }

    public async init(
        context: vscode.ExtensionContext,
        settingsUri: url.Url,
        updatePeriodInMinutes?: number,
        logger?: ILogger
    ): Promise<void> {
        if (!settingsUri) {
            throw new Error('A settings URI is required.');
        }

        this.settingsFileUri = url.parse(url.resolve(settingsUri.href!, remoteSettingsFileName));
        this.settingsFileUri.path = (settingsUri.path + '/' + remoteSettingsFileName).replace('//', '/');

        this.extensionVersion = ExtensionUtil.getExtensionVersion(LIVESHARE_EXTENSION_ID, false);
        this.settings = await loadFilefromCache(this.settingsFileUri.href!);

        logger?.verbose(`Downloading remote settings from ${this.settingsFileUri.href}`);
        const disposable = await initRemoteFileSubscribe(
            context,
            this.settingsFileUri.href!,
            (result) => {
                this.loadDownloadedSettings(result);
            },
            updatePeriodInMinutes,
            logger);
        if (context) {
            context.subscriptions.push(disposable);
        }
    }

    private loadDownloadedSettings(result: RemoteSettings | null) {
        this.settings = result;
        if (!this.updated) {
            this.updated = true;

            // Notify anyone waiting for the first settings update.
            this.updateSignal.resolve();
        }
    }

    public get waitForUpdate(): Promise<void> {
        if (!this.settingsFileUri) {
            throw new Error('Not initialized.');
        }
        // The signal will be completed the first time the settings update.
        return this.updateSignal.promise;
    }

    public getDefault<T>(key: string): T | undefined {
        return this.getSettingValue<T>(key, RemoteSettingPriority.default);
    }

    public getOverride<T>(key: string): T | undefined {
        return this.getSettingValue<T>(key, RemoteSettingPriority.override);
    }

    private getSettingValue<T>(key: string, priority: RemoteSettingPriority): T | undefined {
        if (!this.settings) {
            // Settings are not loaded. This condition may be hit if some settings are requested
            // during early extension initialization. Remote settings are not available at that time.
            return undefined;
        }

        let settingArray = this.settings[key];
        if (!settingArray) {
            // No remote setting is defined for the specified key.
            return undefined;
        }

        if (!Array.isArray(settingArray)) {
            // Convert a single setting to an array to simplify following code.
            settingArray = [settingArray];
        }

        for (let setting of settingArray) {
            const settingPriority = setting.priority || RemoteSettingPriority.default;
            if (settingPriority === priority && this.evaluateConditions(setting.conditions)) {
                return setting.value;
            }
        }

        // None of the settings had requested priority and satisfied conditions.
        return undefined;
    }

    private evaluateConditions(conditions?: RemoteSettingConditions): boolean {
        if (!conditions) {
            // Settings with no conditions are always applicable.
            return true;
        }

        if (conditions.os) {
            const thisOs = getPlatform().replace('win32', 'win').replace('darwin', 'mac');
            if (!(conditions.os === thisOs || (Array.isArray(conditions.os) &&
                conditions.os.indexOf(<RemoteSettingOS>thisOs) >= 0))
            ) {
                return false;
            }
        }

        if (conditions.extensionVersion) {
            if (!semver.satisfies(this.extensionVersion!, conditions.extensionVersion)) {
                return false;
            }
        }

        if (conditions.ideVersion) {
            if (!semver.satisfies(vscode.version, conditions.ideVersion)) {
                return false;
            }
        }

        return true;
    }
}

const remoteConfigInstance = RemoteConfig.Instance;
export { remoteConfigInstance as RemoteConfig };
