'use strict';

import * as vscode from 'vscode';
import { localize } from '@vs/liveshare-core';
import { NotebooksService } from './notebooksService';

export class NotebookContentProvider implements vscode.NotebookContentProvider {

    constructor(private readonly notebookType: string, private readonly notebooksService: NotebooksService) {}

    async openNotebook(uri: vscode.Uri): Promise<vscode.NotebookData> {
        const result = await this.notebooksService.openNotebookAsync(uri.path, this.notebookType);
        if (result.usedNotebookType) {
            throw new Error(`${localize('notebooks.openWithDifferentNotebookTypeOnHost1')} ${result.usedNotebookType}. ${localize('notebooks.openWithDifferentNotebookTypeOnHost2')}`);
        }
        return result;
    }

    async saveNotebook(): Promise<void> { }
    async saveNotebookAs(): Promise<void> { }
    async backupNotebook(): Promise<vscode.NotebookDocumentBackup> { return { id: '', delete: () => { } }; }
}
