import * as vscode from 'vscode';
import { TreeDataProviderContext } from './ExtensionTreeDataProvider';
import { TreeDataProviderBase } from './TreeDataProviderBase';
import { TreeViewItemOptions, TreeViewItem } from './TreeViewItem';
import { ISessionContext} from '../ISessionContext';
import { vsls } from '@vs/vsls-contracts';
import {
    RpcErrorCodes,
} from '@vs/vso-rpc';
import {
    TraceSource,
} from '@vs/vso-logging';

interface ServerSessionExplorerItemOptions extends TreeViewItemOptions {
    port: number;
}

export class ServerSessionExplorerItem extends TreeViewItem {
    public readonly port: number;
    constructor(public readonly options: ServerSessionExplorerItemOptions) {
        super(options);
        this.port = options.port;
    }
}

export enum ServerSharingViewItem {
    Servers = 'servers',

    // servers
    LocalServer = 'servers.local',
    RemoteServer = 'servers.remote',

    // Other / unspecified item type
    Other = 'other',
}

export class ServerSharingTreeDataProvider extends TreeDataProviderBase {
    private serverSharingService: vsls.ServerSharingService;
    private portForwardingService: vsls.PortForwardingService;

    private sharedServers: vsls.SharedServer[];

    constructor(
        private sessionContext: ISessionContext,
        private isSessionExplorer: boolean,
        private trace: TraceSource) {
            super(ServerSharingViewItem.Servers, TreeDataProviderContext.SharedOrJoined)
    }

    public registerServices(
        serverSharingService: vsls.ServerSharingService,
        portForwardingService: vsls.PortForwardingService) {

        this.serverSharingService = serverSharingService;
        this.portForwardingService = portForwardingService;

        serverSharingService.onSharingChanged(() => this.forceRefreshItems());
        serverSharingService.onSharingStarted(() => this.forceRefreshItems());
        serverSharingService.onSharingStopped(() => this.forceRefreshItems());

        portForwardingService.onSharingChanged(() => this.forceRefreshItems());
        portForwardingService.onSharingStarted(() => this.forceRefreshItems());
        portForwardingService.onSharingStopped(() => this.forceRefreshItems());
    }

    public refreshItems() {
        super.refreshItems();
        this.sharedServers = undefined;
    }

    protected async getRootItem(): Promise<TreeViewItem> {
        await this.refreshSharedServers();

        return new TreeViewItem({
            type: ServerSharingViewItem.Servers,
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            label: `Shared Servers (${this.sharedServers.length})`
        });
    }

    
    protected async getChildrenItems(element: TreeViewItem): Promise<TreeViewItem[]> {
        const result: TreeViewItem[] = [];

        if (!this.serverSharingService) {
            return result;
        }

        await this.refreshSharedServers();
        for (let server of this.sharedServers) {
            result.push(await this.getServerRow(server, this.sessionContext.coeditingClient.isHost));
        }

        return (result.length === 0)
            ? this.getDefaultServersActions()
            : result;
    }

    private getDefaultServersActions() {
        if (this.sessionContext.coeditingClient.isHost) {
            return [
                new TreeViewItem({
                    type: ServerSharingViewItem.Other,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: 'Share server...',
                    command: {
                        title: 'Share server...',
                        command: (this.isSessionExplorer)
                            ? 'liveshare.fileTreeExplorer.shareServer'
                            : 'liveshare.activityBar.shareServer'
                    }
                })
            ];
        }

        return [
            new TreeViewItem({
                type: ServerSharingViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: 'No servers shared'
            })
        ];
    }

    private async refreshSharedServers(): Promise<void> {
        if (this.sharedServers) {
            return;
        }

        try {
            this.sharedServers = this.sessionContext.coeditingClient.isHost
                ? await this.serverSharingService.getSharedServersAsync()
                : await this.portForwardingService.getSharedServersAsync();        
        } catch (e) {
            // If the guest is leaving, the service may become unavailable.
            if (e.code !== RpcErrorCodes.ServiceNotAvailable) {
                this.trace.error('Could not get shared servers', e);
            }

            this.sharedServers = [];
        }      
    }

    private async getServerRow(sharedServer: vsls.SharedServer, isLocalServer: boolean) {
        const port = isLocalServer ? sharedServer.sourcePort : sharedServer.destinationPort;
        const row = new ServerSessionExplorerItem({
            port: port,
            type: (isLocalServer)
                    ? ServerSharingViewItem.LocalServer
                    : ServerSharingViewItem.RemoteServer,
            label: sharedServer.sessionName,
            iconPath: TreeDataProviderBase.getThemeIconPath('server'),
            tooltip: `${sharedServer.sessionName} (port ${port})`,
            command: {
                title: 'Open Server in Browser',
                command: (this.isSessionExplorer)
                    ? 'liveshare.fileTreeExplorer.openServerInBrowser'
                    : 'liveshare.activityBar.openServerInBrowser',
                arguments: [{ port }]
            }
        });

        return row;
    }
}