'use strict';
import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import * as tt from './types';

import { traceSource, NotificationUtil } from '@vs/vscode-command-framework';
import { TerminalControllerBase } from './TerminalControllerBase';
import { terminalEndpointBufferFactoryType, createJoinedTerminal  } from './createJoinedTerminal';

import {
    SessionContext,
    SessionState,
    IAccessControlManager,
    WellKnownRestrictedOperations,
    TelemetryEventNames,
    sessionStateTracker,
    commandBindingDecorator,
    ControllerHelper,
    Lazy,
    IDependencies,
    askToSignInAndReload,
    localize
} from '@vs/liveshare-core';

export interface IGuestTerminalController extends TerminalControllerBase {}

export interface GuestTerminalParameters {
    readonly dependencies: IDependencies;
    readonly terminalEndpointBufferFactory: terminalEndpointBufferFactoryType;
    readonly accessControlManager: Lazy<IAccessControlManager>;
}

export const guestTerminalControllerFactory = (parameters: GuestTerminalParameters) => {
    const {        
        controllerDecorator,
        telemetryMethodDecorator,
        errorNotificationMethodDecorator
    } = parameters.dependencies.methodDecorators();

    /**
     * Registers and handles VSCode commands controlling shared terminal behavior in a joined collaboration session.
     */
    @controllerDecorator
    class GuestTerminalController extends TerminalControllerBase {
        private readonly accessControlManager: Lazy<IAccessControlManager>;
        private readonly terminalsAwaitingWriteAccess = new Set<number>();
        private readonly terminalsWithRejectedWriteAccess = new Set<number>();
        private isUserAskedToSignIn: boolean = false;

        constructor(guestTerminalParameters: GuestTerminalParameters) {
            super(guestTerminalParameters.dependencies.terminalService, guestTerminalParameters.terminalEndpointBufferFactory, traceSource.withName('GuestTerminalController'));
            this.accessControlManager = guestTerminalParameters.accessControlManager;
        }

        public async activate(): Promise<boolean> {
            if (this.isActivated) {
                return true;
            }

            await super.activate();

            ControllerHelper.register(this, this.sessionSubscriptions);

            this.sessionSubscriptions.push(
                this.terminalService.onTerminalStarted(this.onHostTerminalStarted, this),
                this.terminalService.onTerminalStopped(this.onHostTerminalStopped, this),
                this.accessControlManager().onDidRejectOperation(async e => {
                    if (e.operation.name === WellKnownRestrictedOperations.WriteToSharedTerminal) {
                        const sharedTerminalOperation = <vsls.SharedTerminalRestrictedOperation>(e.operation);

                        if (e.isReadOnlySession) {
                            return;
                        }

                        if (e.isCurrentUserAnonymous) {
                            await this.terminalWriteAccessRejectedAnonymous(sharedTerminalOperation.terminalId, sharedTerminalOperation.isEscapeSequence);
                        } else {
                            await this.terminalWriteAccessRejected(sharedTerminalOperation.terminalId, sharedTerminalOperation.isEscapeSequence);
                        }
                    }
                }),
                this.accessControlManager().onDidChangeOperationAccess(async e => {
                    if (e.operation.name === WellKnownRestrictedOperations.WriteToSharedTerminal) {
                        const sharedTerminalOperation = <vsls.SharedTerminalRestrictedOperation>(e.operation);
                        await this.terminalWriteAccessChanged(sharedTerminalOperation.terminalId, e.access);
                    }
                }),
            );


            this.deferredWork = this.deferredWork
                .then(() => this.openSharedTerminalsOnJoin())
                .catch(reason => {
                    this.trace.error(reason.message);
                });
        }

        private async terminalWriteAccessRejectedAnonymous(terminalId: number, isEscapeSequence: boolean) {
            const terminal: vsls.TerminalInfo = (await this.terminalService.getRunningTerminalsAsync()).find(t => t.id === terminalId);
            if (!terminal || this.isUserAskedToSignIn) {
                return;
            }

            this.isUserAskedToSignIn = true;

            await askToSignInAndReload(localize('notification.CannotEditTheTerminal'));

            this.isUserAskedToSignIn = false;
        }

        private async terminalWriteAccessRejected(terminalId: number, isEscapeSequence: boolean) {
            if (sessionStateTracker.State !== SessionState.Joined || this.terminalsAwaitingWriteAccess.has(terminalId) || isEscapeSequence) {
                return;
            }

            this.terminalsAwaitingWriteAccess.add(terminalId);

            const terminal: vsls.TerminalInfo = (await this.terminalService.getRunningTerminalsAsync()).find(t => t.id === terminalId);
            if (!terminal) {
                this.terminalsAwaitingWriteAccess.delete(terminalId);
                return;
            }

            this.terminalsWithRejectedWriteAccess.delete(terminalId);

            const requestReadWrite = 'Request read/write access';
            const response = await vscode.window.showInformationMessage(
                'Cannot edit a read-only terminal.',
                { modal: false },
                requestReadWrite);

            if (sessionStateTracker.State !== SessionState.Joined) {
                this.terminalsAwaitingWriteAccess.delete(terminalId);
                return;
            }

            if (response === requestReadWrite) {
                await this.accessControlManager().requestOperationAccess(<any>{
                    name: WellKnownRestrictedOperations.WriteToSharedTerminal,
                    sessionId: SessionContext.coeditingClient.clientID,
                    terminalId
                });
            }
        }

        private async terminalWriteAccessChanged(terminalId: number, access: vsls.RestrictedOperationAccess) {
            if (!this.terminalsAwaitingWriteAccess.has(terminalId)) {
                return;
            }

            if (sessionStateTracker.State !== SessionState.Joined) {
                this.terminalsAwaitingWriteAccess.delete(terminalId);
                return;
            }

            const allowed = access === vsls.RestrictedOperationAccess.Allowed;
            if (!allowed && this.terminalsWithRejectedWriteAccess.has(terminalId)) {
                // We have already show a message about rejected. It must be some other participant requesting access to the terminal.
                return;
            }

            const terminal: vsls.TerminalInfo = (await this.terminalService.getRunningTerminalsAsync()).find(t => t.id === terminalId);
            if (!terminal || sessionStateTracker.State !== SessionState.Joined) {
                this.terminalsAwaitingWriteAccess.delete(terminalId);
                this.terminalsWithRejectedWriteAccess.delete(terminalId);
                return;
            }

            if (allowed) {
                this.terminalsAwaitingWriteAccess.delete(terminalId);
                this.terminalsWithRejectedWriteAccess.delete(terminalId);
            } else {
                this.terminalsWithRejectedWriteAccess.add(terminalId);
            }

            const focusTerminal = 'Focus terminal';
            const responses = allowed ? [focusTerminal] : [];
            const response = await vscode.window.showInformationMessage(
                `The host ${allowed ? 'allowed' : 'didn\'t allow'} read/write access to '${terminal.options.name}' terminal.`,
                { modal: false },
                ...responses);

            if (response === focusTerminal && sessionStateTracker.State === SessionState.Joined) {
                await this.openTerminal({ terminalId });
            }
        }

        private async openSharedTerminalsOnJoin(): Promise<void> {
            try {
                const terminals: vsls.TerminalInfo[] = await this.updateSessionContext();
                await Promise.all(
                    terminals.map(value => this.createTerminal(value))
                );
            } catch {
                SessionContext.hasSharedTerminals = false;
            }
        }

        @errorNotificationMethodDecorator('Listing Terminals', TelemetryEventNames.LIST_TERMINALS_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.LIST_TERMINALS, TelemetryEventNames.LIST_TERMINALS_FAULT, 'ListTerminals')
        @commandBindingDecorator('liveshare.listTerminals')
        private async listTerminals(): Promise<boolean> {
            const terminals: vsls.TerminalInfo[] = await this.getRunningTerminalsAsync();

            if (terminals.length === 0) {
                await vscode.window.showInformationMessage('No terminals are currently shared in the collaboration session.', { modal: false });
                return;
            }

            let index = -1;

            if (terminals.length === 1) {
                index = 0;
            } else {
                const items: string[] = terminals.map((t, i) => `${i + 1}: ${t.options.name}`);
                const selection: string = await NotificationUtil.showQuickPick(items, { placeHolder: 'Select shared terminal to open' });
                if (!selection) {
                    return;
                }

                index = items.indexOf(selection);
            }

            if (index >= 0) {
                await this.createTerminal(terminals[index]);
            }

            return true;
        }

        @errorNotificationMethodDecorator('Opening Terminal', TelemetryEventNames.OPEN_TERMINAL_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.OPEN_TERMINAL, TelemetryEventNames.OPEN_TERMINAL_FAULT, 'OpenTerminal')
        @commandBindingDecorator('liveshare.fileTreeExplorer.openTerminal')
        @commandBindingDecorator('liveshare.activityBar.openTerminal')
        private async openTerminal(terminalPayload?: tt.IViewItemTerminalPayload | undefined): Promise<boolean> {
            if (!terminalPayload) {
                return false;
            }
            
            const terminals: vsls.TerminalInfo[] = await this.terminalService.getRunningTerminalsAsync();

            for (const terminalInfo of terminals.filter(t => t.id === terminalPayload.terminalId)) {
                await this.createTerminal(terminalInfo);
                break;
            }

            return true;
        }

        private async onHostTerminalStarted(event: vsls.TerminalEventArgs): Promise<void> {
            await this.updateSessionContext();
            await this.createTerminal(event.terminal);
        }

        private async onHostTerminalStopped(): Promise<void> {
            await this.updateSessionContext();
        }

        private async updateSessionContext() {
            try {
                const terminals: vsls.TerminalInfo[] = await this.getRunningTerminalsAsync();
                SessionContext.hasSharedTerminals = terminals.length > 0;
                return terminals;
            } catch (e) {
                this.trace.error('Checking for shared terminals failed: ' + e);
            }
        }

        private async getRunningTerminalsAsync(): Promise<vsls.TerminalInfo[]> {
            try {
                return await this.terminalService.getRunningTerminalsAsync();
            } catch (e) {
                if (e.code === -32601) {
                    // Other side doesn't have terminal service
                    return [];
                }

                throw e;
            }
        }
    }

    return new GuestTerminalController(parameters) as IGuestTerminalController;
};
