export type BooleanOrError = boolean | { errorCode?: number, errorMessage?: string };

/** Interface that describes restricted operation. Restricted operation is disabled in read-only session by default. */
export interface RestrictedOperation {
    /** Required operation name for telemetry purposes. Should be one of WellKnownRestrictedOperation constants. */
    name: string;

    /** Optional value indicating whether the operation is enabled in a read-only session. The default is not enabled. */
    enabledInReadOnlySession?: boolean;

    /** Indicate operation is rstricted to owners only. */
    ownerOnly?: boolean;

    /** Optional function that can check if the operation is enabled on the host, and return either true, false, or error. */
    isEnabled?(): BooleanOrError;
}

/** Names of restricted operations. */
export enum WellKnownRestrictedOperations {
    Edit = 'Edit',
    FileAccess = 'FileAccess',
    CodeAction = 'CodeAction',
    RunTask = 'RunTask',
    TerminateTask = 'TerminateTask',
    LaunchDebug = 'LaunchDebug',
    DebugContinue = 'DebugContinue',
    DebugSetVariable = 'DebugSetVariable',
    DebugEvaluate = 'DebugEvaluate',
    WriteToSharedTerminal = 'WriteToSharedTerminal',
    CleanSourceControlResource = 'CleanSourceControlResource',
    ExecuteNotebookCell = 'ExecuteNotebookCell',
}

/** Reason why a restricted operation can be rejected. */
export enum RestrictedOperationRejectionReason {
    RejectedInReadOnlySession = 'RejectedInReadOnlySession',
    RejectedForNotOwner = 'RejectedForNotOwner',
    DisabledByHost = 'DisabledByHost',
}
