import * as vscode from 'vscode';
import { ITextSearchManager } from './ITextSearchManager';
import { IRpcClient } from '@vs/vso-rpc';
import {
    IPathManager,
    TextSearchService,
} from '@vs/liveshare-core';
import { TraceSource } from '@vs/vso-logging';
import { vsls } from '@vs/vsls-contracts';

export class TextSearchManager implements ITextSearchManager {
    private textSearchService: TextSearchService;

    constructor(
        private readonly rpcClient: IRpcClient,
        pathManager: IPathManager
    ) {
        this.textSearchService = new TextSearchService(pathManager, new TraceSource('textSearch'));
    }

    public async init(): Promise<void> {
        this.rpcClient.addRequestMethod(vsls.TextSearchService.name + '.getTextSearchResults', 
            async (options: vsls.TextSearchOptions, token?: vscode.CancellationToken) => {
            return this.textSearchService.getTextSearchResultsAsync(options, token);
        });
        this.rpcClient.addRequestMethodWithProgress(vsls.TextSearchService.name + '.getTextSearchResultsWithProgress', 
            async (options: vsls.TextSearchOptions, progress: vscode.Progress<vsls.TextSearchResult>, token?: vscode.CancellationToken) => {
            return this.textSearchService.getTextSearchResultsWithProgressAsync(options, progress, token);
        });
    }

    public dispose(): Promise<void> {
        return Promise.resolve();
    }
}