import { traceSource } from '../tracing/traceSource';

import { ICommand } from '../types/ICommand';
import { ICommandContext } from '../types/ICommandContext';
import { ICommandContextBuilder } from '../types/ICommandContextBuilder';

export class CommandContextBuilderClass implements ICommandContextBuilder {
    constructor() {}

    public build(command: ICommand<any>, commandText: string): ICommandContext {
        return {
            trace: traceSource.withName(this.buildTrace(command)),
            commandText,
            commandName: '',
        };
    }

    private buildTrace(command: ICommand<any>): string {
        let name = '';

        if (command && command.constructor && command.constructor.name) {
            name = command.constructor.name as string;
            name = name.replace('CommandDecorator', '');
        }
        return `Command:${name}`;
    }
}

// tslint:disable-next-line: variable-name
export const CommandContextBuilder = new CommandContextBuilderClass();
