import { EventEmitter } from 'events';
import { SessionContext } from '../SessionContext';
import { SettingKeys } from '../SettingKeys';

import {
    Telemetry,
    cleanSensitiveInformation,
    TelemetryEvent,
    TelemetryResult,
    ITimedEvent,
    TimedEvent
} from '@vs/vso-telemetry';

import { TelemetryPropertyNames, TelemetryEventNames } from './TelemetryStrings';

export class SessionTelemetry {

    // represents the entirety of a session from its start to its end
    private static sessionTimedEvent: ITimedEvent;

    private static activeTimeRecorder: ActiveTimeRecorder;

    public static readonly sessionEvent: EventEmitter = new EventEmitter();
    public static readonly sessionEndEventName = 'sessionEnd';

    private static collaborateBlockEvent: TimedEvent;

    public static startSession(isHost: boolean, configurationSettings: any): void {
        this.activeTimeRecorder = new ActiveTimeRecorder(
            () => {
                this.collaborateBlockEvent = new TimedEvent(TelemetryEventNames.COLLABORATE_BLOCK, false, true);
            },
            (duration: number) => {
                this.collaborateBlockEvent.addMeasure(TelemetryPropertyNames.ACTIVE_COLLABORATION_DURATION, duration);
                this.collaborateBlockEvent.end(TelemetryResult.Success);
            }
        );
        SessionTelemetry.sessionTimedEvent = Telemetry.startTimedEvent(TelemetryEventNames.SESSION);
        Telemetry.addContextProperty(TelemetryPropertyNames.IS_HOST, isHost);
        SessionTelemetry.reportSettings(configurationSettings);
    }

    public static endSession(guestsByIDE: any, distinctGuestsByIDE: any): void {
        this.activeTimeRecorder.stop();
        SessionTelemetry.sessionEvent.emit(SessionTelemetry.sessionEndEventName);
        SessionTelemetry.sessionTimedEvent.addProperty(TelemetryPropertyNames.GUESTS_BY_IDE, JSON.stringify(guestsByIDE));
        SessionTelemetry.sessionTimedEvent.addProperty(TelemetryPropertyNames.DISTINCT_GUESTS_BY_IDE, JSON.stringify(distinctGuestsByIDE));
        SessionTelemetry.sessionTimedEvent.addMeasure(TelemetryPropertyNames.ACTIVE_COLLABORATION_DURATION, this.activeTimeRecorder.activeDuration);
        SessionTelemetry.sessionTimedEvent.addMeasure(TelemetryPropertyNames.ACTIVE_COLLABORATION_BLOCKS, this.activeTimeRecorder.activeBlocks);
        SessionTelemetry.sessionTimedEvent.end(TelemetryResult.Success);
        Telemetry.removeContextProperty(TelemetryPropertyNames.CONVERSATION_ID);
        Telemetry.removeContextProperty(TelemetryPropertyNames.IS_HOST);
        Telemetry.removeContextProperty(TelemetryPropertyNames.SESSION_ID);

    }

    public static reportSettings(configurationSettings: any): void {
        const cleanedConfigurationSettings = Object.assign({}, configurationSettings);
        //clean sensitive account  info
        cleanedConfigurationSettings[SettingKeys.account] = cleanSensitiveInformation(configurationSettings[SettingKeys.account]);
        // clean sensitive accountProvider info
        cleanedConfigurationSettings[SettingKeys.accountProvider] = cleanSensitiveInformation(configurationSettings[SettingKeys.accountProvider]);
        const reportSettingsTelemetryEvent = new TelemetryEvent(TelemetryEventNames.REPORT_SETTINGS);
        reportSettingsTelemetryEvent.addProperty(TelemetryPropertyNames.SETTING_VALUES, JSON.stringify(cleanedConfigurationSettings));
        reportSettingsTelemetryEvent.send();
    }

    public static recordActivity() {
        if (SessionContext.hasCollaborators) {
            this.activeTimeRecorder?.recordActivity();
        }
    }

}

export class ActiveTimeRecorder {

    private duration = 0;
    private blocks = 0;
    private firstActivity = 0;
    private lastActivity = 0;
    private newBlock = true;

    private idleTimer: NodeJS.Timeout;

    public constructor(
        private readonly onBlockStart: () => void,
        private readonly onBlockEnd: (duration: number) => void,
        private readonly idleTime = FIVE_MINUTES
    ) { }

    private endActiveBlock() {
        if (this.newBlock) {
            return;
        }

        const blockDuration = this.lastActivity - this.firstActivity;
        this.duration += blockDuration;
        this.blocks++;
        this.newBlock = true;
        this.onBlockEnd(blockDuration);
    }

    public recordActivity() {
        clearTimeout(this.idleTimer);

        const currentTime = (new Date()).getTime();
        if (this.newBlock) {
            this.newBlock = false;
            this.firstActivity = currentTime;
            this.onBlockStart();
        }

        this.lastActivity = currentTime;
        this.idleTimer = setTimeout(() => this.endActiveBlock(), this.idleTime);
    }

    public stop() {
        this.endActiveBlock();
    }

    public get activeDuration() { return this.duration; }

    public get activeBlocks() { return this.blocks; }

}

const FIVE_MINUTES = 5 * 60 * 1000;
