import { FaultType, Telemetry } from '@vs/vso-telemetry';
import { IInittableDisposable } from './contracts/IInittableDisposable';
import { Lazy } from './Lazy';
import { sessionStateTracker } from './SessionStateTracker';

export interface IInittableDisposableManager {
    instance: IInittableDisposable;
    status?: string;
    children?: IInittableDisposableManager[];
}
export function createInittableDisposable(initCallback: () => Promise<void>): IInittableDisposable {
    const innitableDisposable = {
        isInited: false,
        init: async () => {
            await initCallback();
            innitableDisposable.isInited = true;
        },
        dispose: () => Promise.resolve()
    };

    return innitableDisposable;
}

export function lazyInittable(lazy: Lazy<IInittableDisposable>): IInittableDisposable;
export function lazyInittable(lazy: Lazy<{}>): IInittableDisposable;
export function lazyInittable(lazy: Lazy<any>): IInittableDisposable {
    return {
        isInited: false,
        init: async () => {
            const initable = <IInittableDisposable><any>lazy();
            if (typeof initable.init === 'function') {
                await initable.init();
            }
        },
        dispose: async () => Promise.resolve(),
    };
}

export async function initDisposableManager(managers: IInittableDisposableManager[], throwIfFail?: boolean): Promise<void> {
    await Promise.all(
        managers.map(async ({ instance, children, status }) => {
            try {
                await instance.init();
            } catch (e) {
                Telemetry.sendFault('init-manager-fault', FaultType.Error, '', e);
                if (throwIfFail === undefined || throwIfFail) {
                    throw e;
                }
            }
            
            if (children) {
                await initDisposableManager(children, throwIfFail);
            }

            if (status) {
                sessionStateTracker.point(status);
            }
        }));
}