import * as vscode from 'vscode';
import uuid = require('uuid');

import { vsls } from '@vs/vsls-contracts';
import { IWorkspaceSessionInfoTracker } from './IWorkspaceSessionInfoTracker';
import {
    Telemetry, TelemetryEvent
} from '@vs/vso-telemetry';

import { TelemetryEventNames, TelemetryPropertyNames } from './telemetry/TelemetryStrings';
import { localize } from './localize';
import { ExtensionUtil } from './utils/ExtensionUtil';
import { CommandContext } from './CommandConstants';

export enum AnonymousAccessLevel {
    readOnly = 'readOnly',
    readWrite = 'readWrite'
}

class WorkspaceSessionInfoTracker implements IWorkspaceSessionInfoTracker {
    private _workspaceSessionInfo: vsls.WorkspaceSessionInfo | null = null;
    public plannedWorkspaceList: vsls.WorkspaceInfo[] | null = null;
    private isReadOnlyPrivate: boolean = false;
    private isPlannedSessionsChangedPrivate: boolean = false;
    private anonymousAccessMap = new Map<string, string>(); 
    private anonymousUserId: any;

    private readonly readOnlyChangedEmitter = new vscode.EventEmitter<boolean>();
    public readonly onReadOnlyChanged = this.readOnlyChangedEmitter.event;
    
    private readonly plannedSessionsChangedEmitter = new vscode.EventEmitter<boolean>();
    public readonly onPlannedSessionsChanged = this.plannedSessionsChangedEmitter.event;

    private readonly anonymousAccessLevelChangedInSessionEmitter = new vscode.EventEmitter<void>();
    public readonly onAccessLevelChangedInSession = this.anonymousAccessLevelChangedInSessionEmitter.event;

    public get workspaceSessionInfo() {
        return this._workspaceSessionInfo;
    }

    public set workspaceSessionInfo(info: vsls.WorkspaceSessionInfo | null) {
        this._workspaceSessionInfo = info;
        if (this._workspaceSessionInfo?.id && ExtensionUtil.getCommandContext(CommandContext.isWeb)) {
            this._workspaceSessionInfo.joinUri = `https://vscode.dev/liveshare/${this._workspaceSessionInfo.id}`;
        }
        if (info?.conversationId) {
            Telemetry.addContextProperty(TelemetryPropertyNames.CONVERSATION_ID, info.conversationId);
            Telemetry.addContextProperty(TelemetryPropertyNames.SESSION_ID, uuid());
        }
    }

    public get isReadOnly(): boolean {
        return this.isReadOnlyPrivate;
    }

    public set isReadOnly(isReadOnly: boolean) {
        const previousReadOnly = workspaceSessionInfoTracker.isReadOnly;
        if (isReadOnly !== previousReadOnly) {
            if (isReadOnly) {
                Telemetry.addContextProperty(TelemetryPropertyNames.IS_READONLY_SESSION, true /* value */, false /* isPII */);
            } else {
                Telemetry.removeContextProperty(TelemetryPropertyNames.IS_READONLY_SESSION);
            }

            workspaceSessionInfoTracker.isReadOnlyPrivate = isReadOnly;
            this.readOnlyChangedEmitter.fire(isReadOnly);
        }
    }

    public get isPlannedSessionsChanged(): boolean {
        return this.isPlannedSessionsChangedPrivate;
    }

    public set isPlannedSessionsChanged(isPlannedSessionChanged: boolean) {
        const previousPlannedSession = workspaceSessionInfoTracker.isPlannedSessionsChanged;
        if (isPlannedSessionChanged !== previousPlannedSession) {

            workspaceSessionInfoTracker.isPlannedSessionsChangedPrivate = isPlannedSessionChanged;
            this.plannedSessionsChangedEmitter.fire(isPlannedSessionChanged);
        }
        workspaceSessionInfoTracker.isPlannedSessionsChangedPrivate = false;
    }

    // Here we are setting anonymous guest access level before they join the session. (either via toast notification or via "anonymous guest join" setting)
    public async setAnonymousAccess(userProfileId: any, userSelection: string) {
        const respondAnonymousJoinRequestEvent = new TelemetryEvent(TelemetryEventNames.RESPOND_ANONYMOUS_JOIN_REQUEST);
        switch (userSelection) {
            case localize('notification.AcceptReadOnly'):
            case localize('notification.Accept'):
            case localize('notification.AlwaysAcceptAnonymous'): // This is the case where "anonymous guest approval" setting is set to "always accept" which is read only by default.
                this.anonymousAccessMap.set(userProfileId, AnonymousAccessLevel.readOnly);
                respondAnonymousJoinRequestEvent.addProperty(TelemetryPropertyNames.READONLY, true);
                respondAnonymousJoinRequestEvent.addProperty(TelemetryPropertyNames.ACCEPTED, true);
                break;
            case localize('notification.AcceptReadWrite'):
                this.anonymousAccessMap.set(userProfileId, AnonymousAccessLevel.readWrite);
                respondAnonymousJoinRequestEvent.addProperty(TelemetryPropertyNames.READONLY, false);
                respondAnonymousJoinRequestEvent.addProperty(TelemetryPropertyNames.ACCEPTED, true);
                break;
            case localize('notification.Reject'):
                respondAnonymousJoinRequestEvent.addProperty(TelemetryPropertyNames.ACCEPTED, false);
                break;
            default:
                break;
        }
        respondAnonymousJoinRequestEvent.send();
    }

    // Here we are updating anonymous users' access level after they join the session.
    public async updateAnonymousAccess(options: any, isReadOnly: boolean) {
        const updateAnonymousGuestAccessLevelEvent = new TelemetryEvent(TelemetryEventNames.UPDATE_ANONYMOUS_GUEST_ACCESS_LEVEL);
        const participantId  = options.participantId;
        const sessionId = options.sessionId;
        if (isReadOnly) {
            this.anonymousAccessMap.set(participantId, AnonymousAccessLevel.readOnly);
            this.anonymousAccessLevelChangedInSessionEmitter.fire();
            this.anonymousUserId = sessionId;
            updateAnonymousGuestAccessLevelEvent.addProperty(TelemetryPropertyNames.IS_ANONYMOUS_ELEVATED, false);
        } else {
            this.anonymousAccessMap.set(participantId, AnonymousAccessLevel.readWrite);
            this.anonymousAccessLevelChangedInSessionEmitter.fire();
            this.anonymousUserId = sessionId;
            updateAnonymousGuestAccessLevelEvent.addProperty(TelemetryPropertyNames.IS_ANONYMOUS_ELEVATED, true);
        }
        updateAnonymousGuestAccessLevelEvent.send();
    }

    public getAnonymousAccess(userProfileId: any): string {
        return this.anonymousAccessMap.get(userProfileId);
    }

    public getAnonymousAccessMapHasTheProfile(userProfile: any): boolean {
        const id  = userProfile.participantId;
        return this.anonymousAccessMap.has(id);
    }

    public clearAnonymousAccessMap() {
        this.anonymousAccessMap.clear();
    }

    public getAccessLevelChangedUserID() {
        return this.anonymousUserId;
    }
}

export const workspaceSessionInfoTracker = new WorkspaceSessionInfoTracker();
