import * as vscode from 'vscode';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { showWelcomePage, WelcomePageSource } from '../welcomePage/welcomePageUtil';
import { ClipboardUtil } from '../utils/ClipboardUtil';
import { IWorkspaceAccessControlManager } from '../contracts/IWorkspaceAccessControlManager';

export async function showInvitationLink(
    workspaceAccessControlManager: IWorkspaceAccessControlManager,
    link?: string,
    manualCopy?: boolean,
    showReadonly?: boolean): Promise<void> {
    if (!link || link === workspaceSessionInfoTracker.workspaceSessionInfo.joinUri) {
        const currentLink = workspaceSessionInfoTracker.workspaceSessionInfo.joinUri;

        if (manualCopy) {
            // Auto-copying to clipboard didn't work. Allow manual copy from an input box.
            await vscode.window.showInputBox({
                prompt: 'Copy Live Share invitation link',
                value: currentLink,
                ignoreFocusOut: true,
            });
            return;
        }

        const copied = await new ClipboardUtil().copyToClipboardAsync(currentLink);
        const moreInfoButton =  { id: 1, title: 'More info' };
        const copyButton = { id: 2, title: (copied ? 'Copy again' : 'Copy link') };
        let buttons: any[] = [moreInfoButton, copyButton];

        const toggleReadOnlyButton = { id: 3, title: workspaceSessionInfoTracker.isReadOnly ? 'Make read/write' : 'Make read-only' };

        if (showReadonly !== false) {
            buttons.splice(0, 0, toggleReadOnlyButton);
        }

        const result = await vscode.window.showInformationMessage(
            (copied ? 'Invitation link copied to clipboard! Send it to anyone you trust ' :
                'Session shared! Click "Copy link" to get an invitation link ') +
            'or click "More info" to learn about secure sharing.', true,
            ...buttons);
        if (result && result.id === copyButton.id) {
            // Prevent this button from dismissing the notification.
            await showInvitationLink(workspaceAccessControlManager, currentLink, !copied, showReadonly);
        } else if (result && result.id === moreInfoButton.id) {
            await showWelcomePage(WelcomePageSource.Sharing);
        } else if (result && result.id === toggleReadOnlyButton.id) {
            await workspaceAccessControlManager.setReadOnly(!workspaceSessionInfoTracker.isReadOnly);
        }
    } else {
        await vscode.window.showErrorMessage(
            'This invite link has expired. Share again to generate a new link.');
    }
}