import { EventEmitter } from 'events';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';
import { Telemetry } from '@vs/vso-telemetry';
import { TelemetryEventNames, TelemetryPropertyNames } from '@vs/liveshare-core';

export enum AudioSessionState {
    AudioConnecting = 'AudioConnecting',
    AudioDisconnecting = 'AudioDisconnecting',
    Initializing = 'Initializing',
    LiveShareWithoutAudio = 'LiveShareWithoutAudio',
    LiveShareWithAudio = 'LiveShareWithAudio',
    NoLiveShare = 'NoLiveShare'
}

export enum AudioSessionAction {
    InitializeDone,
    LiveShareSessionStarted,
    LiveShareSessionEnded,
    AttemptConnectAudio,
    AttemptDisconnectAudio,
    AudioConnected,
    AudioDisconnected,
    AudioConnectionFailed,
}

type StateMachine = { [key: string]: { [key: number]: AudioSessionState } };
export const sessionMachine: StateMachine = {
    [AudioSessionState.Initializing]: {
        [AudioSessionAction.InitializeDone]: AudioSessionState.NoLiveShare,
    },
    [AudioSessionState.NoLiveShare]: {
        [AudioSessionAction.LiveShareSessionStarted]: AudioSessionState.LiveShareWithoutAudio
    },
    [AudioSessionState.LiveShareWithoutAudio]: {
        [AudioSessionAction.AttemptConnectAudio]: AudioSessionState.AudioConnecting,
        [AudioSessionAction.AudioConnected]: AudioSessionState.LiveShareWithAudio,
        [AudioSessionAction.LiveShareSessionEnded]: AudioSessionState.NoLiveShare,
    },
    [AudioSessionState.AudioConnecting]: {
        [AudioSessionAction.AudioConnected]: AudioSessionState.LiveShareWithAudio,
        [AudioSessionAction.AudioDisconnected]: AudioSessionState.LiveShareWithoutAudio,
        [AudioSessionAction.AudioConnectionFailed]: AudioSessionState.LiveShareWithoutAudio,
        [AudioSessionAction.LiveShareSessionEnded]: AudioSessionState.NoLiveShare,
    },
    [AudioSessionState.AudioDisconnecting]: {
        [AudioSessionAction.AudioDisconnected]: AudioSessionState.LiveShareWithoutAudio,
        [AudioSessionAction.AudioConnectionFailed]: AudioSessionState.LiveShareWithoutAudio,
        [AudioSessionAction.LiveShareSessionEnded]: AudioSessionState.NoLiveShare,
    },
    [AudioSessionState.LiveShareWithAudio]: {
        [AudioSessionAction.AttemptDisconnectAudio]: AudioSessionState.AudioDisconnecting,
        [AudioSessionAction.AudioDisconnected]: AudioSessionState.LiveShareWithoutAudio,
        [AudioSessionAction.LiveShareSessionEnded]: AudioSessionState.NoLiveShare,
    }
};

export enum AudioSessionEvents {
    StateChanged = 'StateChanged'
}

class AudioSessionContext extends EventEmitter {
    private static singleton: AudioSessionContext;
    private trace: TraceSource;
    private currentState: AudioSessionState = AudioSessionState.Initializing; // initial state

    public static get Instance(): AudioSessionContext {
        if (!AudioSessionContext.singleton) {
            AudioSessionContext.singleton = new AudioSessionContext();
        }
        return AudioSessionContext.singleton;
    }

    constructor() {
        super();
        this.trace = traceSource.withName('Calling.AudioSessionContext');
    }

    public get State(): AudioSessionState {
        return AudioSessionContext.Instance.currentState;
    }

    public transition(action: AudioSessionAction): AudioSessionState {
        const currentStateConfig = sessionMachine[this.State];
        this.trace.verbose(`Current state: ${this.State}, Action: ${AudioSessionAction[action]}`);
        if (currentStateConfig) {
            const nextState = currentStateConfig[action];

            if (nextState !== undefined) {
                AudioSessionContext.Instance.setState(nextState);
                return AudioSessionContext.Instance.State;
            }

            Telemetry.sendTelemetryEvent(TelemetryEventNames.AUDIO_INVALID_SESSION_TRANSITION,
                { [TelemetryPropertyNames.AUDIO_SESSION_STATE]: this.State.toString(),
                  [TelemetryPropertyNames.AUDIO_SESSION_ACTION]: action.toString() });
            this.trace.warning(`No transition exists for state: ${this.State}, action: ${AudioSessionAction[action]}`);
            return undefined;
        }

        this.trace.warning(`No config for the given state exists in the machine: action ${AudioSessionAction[action]}`);
        return undefined;
    }

    private setState(newState: AudioSessionState) {
        const previousState = AudioSessionContext.Instance.currentState;
        if (previousState === newState) return;
        AudioSessionContext.Instance.currentState = newState;
        AudioSessionContext.Instance.emit(AudioSessionEvents.StateChanged, newState, previousState);
    }
}

const sessionContextInstance = AudioSessionContext.Instance;
export { sessionContextInstance as AudioSessionContext };