import { vsls } from '@vs/vsls-contracts';
import { IWorkspaceConnection } from '@vs/vso-workspace-core';
import { IDependencies } from '@vs/liveshare-core';
import { GuestTerminalParameters } from './GuestTerminalController';
import { GuestTerminalHandler } from './GuestTerminalHandler';
import { createTerminalEndpointBufferFactory } from './terminalEndpointBufferFactory';

export function registerGuestTerminalHandler(dependencies: IDependencies, workspaceConnection: IWorkspaceConnection) {

    // Guest terminal handler
    const guestTerminalParameters: GuestTerminalParameters = {
        dependencies,
        terminalEndpointBufferFactory: createTerminalEndpointBufferFactory(dependencies, workspaceConnection),
        accessControlManager: dependencies.accessControlManager,
    };

    dependencies.sessionStateManager().registerHandler(new GuestTerminalHandler(guestTerminalParameters));
}