import { 
    TelemetryEvent
} from '@vs/vso-telemetry';
import { 
    TelemetryEventNames,
    TelemetryPropertyNames
} from '@vs/liveshare-core';

export class LanguageServiceTelemetryEventNames {
    public static readonly LSPSERVER_INIT_FAULT = TelemetryEventNames.FAULT_PREFIX + 'init-lspserver-fault';
    public static readonly SUMMARIZE_LSREQUESTS = 'summarize-lsrequests';
    public static readonly GET_DIAGNOSTICS_FAULT = TelemetryEventNames.FAULT_PREFIX + 'get-diagnostics-fault';
    public static readonly RESET_LANGUAGE_SERVICES = 'reset-languageservices';
    public static readonly SHOW_OPPORTUNISTIC_CODE_LENS = 'show-opportunisticcodelens';
    public static readonly INVOKE_OPPORTUNISTIC_CODE_LENS = 'invoke-opportunisticcodelens';
}

export class LanuageServiceTelemetryPropertyNames {
    public static readonly SERVICED_REQUESTS = TelemetryPropertyNames.FEATURE_NAME + 'ServicedRequests';
    public static readonly REJECTED_REQUESTS = TelemetryPropertyNames.FEATURE_NAME + 'RejectedRequests';
    public static readonly UNACKNOWLEDGED_HOST_CHANGES_REJECTS = TelemetryPropertyNames.FEATURE_NAME + 'UnacknowledgedHostChangesRejects';
    public static readonly REJECTED_REQUESTS_DETAILS = TelemetryPropertyNames.FEATURE_NAME + 'RejectedRequestsDetails';
}

export function summarizeLsRequests(servicedRequests: number, rejectedReqests: number, unacknowledgedHostChangesRejects: number, rejectedRequestsDetails: { [method: string]: number }) {
    let summaryEvent = new TelemetryEvent(LanguageServiceTelemetryEventNames.SUMMARIZE_LSREQUESTS);
    summaryEvent.addMeasure(LanuageServiceTelemetryPropertyNames.SERVICED_REQUESTS, servicedRequests);
    summaryEvent.addMeasure(LanuageServiceTelemetryPropertyNames.REJECTED_REQUESTS, rejectedReqests);
    summaryEvent.addMeasure(LanuageServiceTelemetryPropertyNames.UNACKNOWLEDGED_HOST_CHANGES_REJECTS, unacknowledgedHostChangesRejects);
    summaryEvent.addProperty(LanuageServiceTelemetryPropertyNames.REJECTED_REQUESTS_DETAILS, JSON.stringify(rejectedRequestsDetails));
    summaryEvent.send();
}