import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { getAllRootFileSystemPaths, SettingKeys, Settings } from '@vs/liveshare-core';

/**
 * Helper functions for working with VS Code workspaces.
 */
export interface IVsCodeShareInfo {
    foundUnsupportedSchemes: boolean;
    shareInfo: vsls.WorkspaceShareInfo;
}

export function clientFileServiceEnabled() {
    return getAllRootFileSystemPaths().isVirtualWorkspace || Settings.get<boolean>(SettingKeys.useClientFileService);
}

export function isWebviewSupported(): boolean {
    const window: any = vscode.window;
    return (typeof window.createWebviewPanel) === 'function';
}
