import * as os from 'os';
import { OSPlatform } from './osPlatform';

export function getPlatformProperty(): string {
    switch (os.platform()) {
        case OSPlatform.WINDOWS:
            return 'windows';

        case OSPlatform.MACOS:
            return 'osx';

        case OSPlatform.LINUX:
        default:
            return 'linux';
    }
}