import * as vscode from 'vscode';
import { ICommandContext, traceSource as trace } from '@vs/vscode-command-framework';
import { GitHubAuthTokenProvider } from './GitHubAuthTokenProvider';
import { MicrosoftAuthTokenProvider } from './MicrosoftAuthTokenProvider';
import { VsCodeNativeAuthTokenProvider } from './VscodeNativeAuthTokenProvider';

export enum SupportedAuthProviders {
    GitHub = 'github',
    Microsoft = 'microsoft'
}

export class NativeAuthProvider {
    private readonly registeredTokenProviders: Map<SupportedAuthProviders, VsCodeNativeAuthTokenProvider> = new Map<SupportedAuthProviders, VsCodeNativeAuthTokenProvider>();

    private readonly onSignOutEmitter = new vscode.EventEmitter<void>();
    public readonly onSignOut = this.onSignOutEmitter.event;

    constructor() {
        this.registeredTokenProviders.set(SupportedAuthProviders.GitHub, new GitHubAuthTokenProvider());
        this.registeredTokenProviders.set(SupportedAuthProviders.Microsoft, new MicrosoftAuthTokenProvider());

        this.registeredTokenProviders.forEach((provider) => {
            provider.onSignOut(this.handleOnDidSignOut.bind(this));
        });
    }

    public async getCachedTokenOrLogin(providerName: SupportedAuthProviders, context: ICommandContext): Promise<string | null> {
        let token = await this.getCachedToken(providerName);

        if (token) {
            return token;
        }

        let provider = this.registeredTokenProviders.get(providerName);

        if (!provider) {
            trace.verbose(`Attempting to log in with not supported auth provider - ${providerName}`);
            return null;
        }

        if (await provider.signIn(context)) {
            return await provider.getAccessToken();
        }

        trace.verbose(`Attempt to login with ${providerName} failed`);
        return null;
    }

    public async getCachedToken(providerName: SupportedAuthProviders): Promise<string | null> {

        let provider = this.registeredTokenProviders.get(providerName);

        if (!provider) {
            trace.verbose(`Attempting to get a cached auth token from not supported auth provider - ${providerName}`);
            return null;
        }

        return await provider.getAccessToken();
    }

    public resetAccessTokenCache(providerName: SupportedAuthProviders): void {
        let provider = this.registeredTokenProviders.get(providerName);

        if (!provider) {
            trace.verbose(`Attempting to reset a cached auth token of unsupported auth provider - ${providerName}`);
            return null;
        }

        provider.resetCascadeToken();
    }

    private handleOnDidSignOut() {
        this.onSignOutEmitter.fire();
    }
}