import { ITraceFilter } from './interfaces/ITraceFilter';
import { LogLevel } from './interfaces/LogLevel';

export class TraceFilters implements ITraceFilter {
    public constructor(public readonly filters: ITraceFilter[] = []) {        
    }

    public shouldTrace(source: string, logLevel: LogLevel, id: number): boolean {
        return this.filters.every(t => t.shouldTrace(source, logLevel, id));
    }
}