import * as url from 'url';
import { SettingKeys, Settings, workspaceSessionInfoTracker, joinWithLocalConnectionHub, createLocalWorkspaceClient } from '@vs/liveshare-core';
import { IDependencies } from '../../_new_/IDependencies';
import { getJoiningWorkspaceId } from '../../_new_/util/activateUtils';
import * as config from '../../config';
import { traceSource } from '@vs/vscode-command-framework';
import { once } from '@vs/vscs-utils';
import { LiveShareConnection, TConnectionTypes } from '@vs/vscs-connection-hub';
import { IWorkspaceClient } from '@vs/vso-workspace-core';

/**
 * Return the singleton local workspace client.
 */
export const getLocalWorkspaceClient = once(() => {
    return createLocalWorkspaceClient(traceSource.withName('WorkspaceClient'));
});

/**
 * Our singleton liveshare connection class
 */
class SingletonLocalClientConnection extends LiveShareConnection {
    public get type() {
        return TConnectionTypes.WorkspaceHub;
    }

    protected async createWorkspaceClient(): Promise<IWorkspaceClient> {
        return getLocalWorkspaceClient();
    }
}

/**
 * Join the workspace from a vscode reload using the workspace clinet library and the connection hub
 */
export async function joinWorkspaceClientFactory(dependencies: IDependencies) {

    const workspaceId: string | undefined = getJoiningWorkspaceId();
    if (!workspaceId) {
        throw new Error('JoinedWorkspaceConnection is unavailable in a non-guest session.');
    }

    const token = await dependencies.authenticationProvider().waitForAuthenticatedUserToken();
    const liveShareEndpoint = url.format(Settings.getUri(SettingKeys.serviceUri));
    const clientCapabilities = config.getClientCapabilties();
    const anonymousUserName = config.get<string>(config.Key.anonymousUserName);

    const liveShareConnection = await joinWithLocalConnectionHub(traceSource, {
        workspaceId,
        liveShareEndpoint,
        token,
        workspaceJoinInfo: {
            anonymousUserName
        }, 
        clientCapabilities
    }, SingletonLocalClientConnection);
    
    const workspaceSessionInfo = liveShareConnection.workspaceSessionInfo!;
    workspaceSessionInfoTracker.workspaceSessionInfo = workspaceSessionInfo;
    const hostSession = Object.entries(workspaceSessionInfo.sessions!).find(([key, value]) => !!value.isHost);
    dependencies.hostSessionId.loader = () => Number(hostSession![0]);
    return liveShareConnection.workspaceClient.rpcClient;
}