import { vsls } from '@vs/vsls-contracts';
import { Stream } from '@vs/vs-ssh';
import { ConnectionMode, IWorkspaceConnectionInfo} from '@vs/vso-workspace-core';

import { assert, promiseAny, toCamelCase } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import { SshHelpers } from '@vs/vso-workspace-client';
import { ByDesignError } from '../abstractions/ByDesignErrors';
import { SettingKeys } from '../SettingKeys';
import { Settings } from '../Settings';
import { IHubConnectionServiceFactory, HubProxyType } from '../contracts/IHubConnectionService';
import { openDirectConnection } from '@core-abstractions/openDirectConnection';
import {
    IRelayServiceProxy
} from '@vs/vso-signalr-client-proxy';
import {
    HubStreamUtils,
} from '@vs/vso-rpc-signalr';

/**
 * The possible hub stamps we could have.
 */
const hubStamps = [
    'usw2',
    'use',
    'euw',
    'asse',
];

/**
 * Setting to enable/disable tracing the hub data.
 */
const traceHubDataSetting = 'traceHubData';
/**
 * Setting to enable/disable the use of cross region when connection to signalR hubs.
 */
const hubCrossRegionEnabledSetting = 'hubCrossRegionEnabled';

/**
 * Connect and open a stream to to Live Share workspace.
 * 
 * @param workspaceConnectionInfo Workspace connection info as obtained from the shared workspace.
 * @param logger tracer
 * @returns Stream connected to the workspace.
 */
export async function openWorkspaceConnection(
    workspaceConnectionInfo: IWorkspaceConnectionInfo,
    logger: ILogger,
    hubConnectionServiceFactory?: IHubConnectionServiceFactory): Promise<Stream> {

    const workspaceConnectionMode = () => {
        if (typeof workspaceConnectionInfo.connectionMode === 'number') {
            return ConnectionMode[workspaceConnectionInfo.connectionMode];
        }

        if (typeof workspaceConnectionInfo.connectionMode === 'string') {
            return <ConnectionMode>toCamelCase(<string>workspaceConnectionInfo.connectionMode);
        }
    }
    

    // Determine if the connection mode is compatible and set the appropriate mode.
    let connectionMode = Settings.get<ConnectionMode>(SettingKeys.connectionMode);
    const workspaceMode = workspaceConnectionMode() || ConnectionMode.Auto;
    if (workspaceMode !== connectionMode) {
        if (connectionMode === ConnectionMode.Auto) {
            connectionMode = workspaceMode;
        } else if (
            connectionMode === ConnectionMode.Direct &&
            workspaceMode === ConnectionMode.Relay
        ) {
            throw new ByDesignError(
                'The host does not allow direct connections. Switch to \"Auto\" or \"Relay\" mode and retry.', 
                vsls.ErrorCodes.DirectConnectionNotEnabled
            );
        } else if (
            connectionMode === ConnectionMode.Relay &&
            workspaceMode === ConnectionMode.Direct
        ) {
            throw new ByDesignError(
                'Unable to connect since the host does not allow relayed connections. Switch to \"Auto\" or \"Direct\" mode and retry.',
                vsls.ErrorCodes.RelayConnectionNotEnabled
            );
        }
    }

    if (connectionMode === ConnectionMode.Local || (connectionMode === ConnectionMode.SignalR && !hubConnectionServiceFactory)) {
        throw new Error(`Unsupported workspace connection mode '${connectionMode}'.`);
    }

    // Check if there is enough information to establish the connection.
    const hasConnectLinks = workspaceConnectionInfo.connectLinks && workspaceConnectionInfo.connectLinks.length;
    if (connectionMode === ConnectionMode.Auto && !workspaceConnectionInfo.relayLink && !hasConnectLinks && !hubConnectionServiceFactory) {
        throw new Error('Workspace does not have relay or direct connection info.');
    }

    if (connectionMode === ConnectionMode.Direct && !hasConnectLinks) {
        throw new Error('Workspace does not have direct connection info.');
    }

    const streamPromises: Promise<[Stream, ConnectionMode] | undefined>[] = [];
    if ((connectionMode === ConnectionMode.Auto || connectionMode === ConnectionMode.Relay) && workspaceConnectionInfo.relayLink) {
        streamPromises.push(openAzureRelayStream(workspaceConnectionInfo, logger));
    }

    if ((connectionMode === ConnectionMode.Auto || connectionMode === ConnectionMode.Relay || connectionMode === ConnectionMode.SignalR) && hubConnectionServiceFactory) {
        streamPromises.push(openHubSshStream(hubConnectionServiceFactory, workspaceConnectionInfo, logger));
    }

    if ((connectionMode === ConnectionMode.Auto || connectionMode === ConnectionMode.Direct) && hasConnectLinks) {
        streamPromises.push(
            ...workspaceConnectionInfo.connectLinks!.map((connectLink) =>
                openDirectConnection(connectLink, logger)
            )
        );
    }

    assert(streamPromises.length > 0, 'Cannot connect to workspace. Workspace does not have sufficient connection info.');

    let result: [Stream, ConnectionMode] | undefined;
    try {
        result = await promiseAny(streamPromises);
        if (!result) {
            throw new Error('Cannot connect to workspace. Workspace does not have sufficient connection info.');
        }
    
        logger.verbose(`Successfully connected using connection mode: ${result[1]}`);
        return result[0];
    }
    finally {
        streamPromises.forEach((p) =>
            p.then(
                (s) => {
                    if (s && s !== result) {
                        s[0].dispose();
                    }
                },
                () => {} // Ignore the rejection
            )
        );
    }
}

const openHubSshStream = async (hubConnectionServiceFactory: IHubConnectionServiceFactory, workspaceInfo: IWorkspaceConnectionInfo, logger: ILogger) : Promise<[Stream, ConnectionMode]> => {
    const hubStamp = Settings.get<boolean>(hubCrossRegionEnabledSetting) ?
        undefined
        : workspaceInfo.relayLink ? getStampFromUri(workspaceInfo.relayLink) : undefined;

    const hubConnectionService = await hubConnectionServiceFactory.getOrCreate(hubStamp);
    await hubConnectionService.setEnabled(true);
    const relayServiceProxy = hubConnectionService.getOrCreateProxy<IRelayServiceProxy>(HubProxyType.RelayService);
    
    // Note: in case you want log the hub data packtes use the following setting key.
    if (Settings.get<boolean>(traceHubDataSetting)) {
        relayServiceProxy.traceHubData = true;
    }

    const sshStream = await HubStreamUtils.createClientStream(relayServiceProxy, workspaceInfo.id, undefined, undefined, logger);
    return [sshStream, ConnectionMode.SignalR];
};

const openAzureRelayStream = async (workspaceInfo: IWorkspaceConnectionInfo, logger: ILogger) : Promise<[Stream, ConnectionMode]> => {
    const sshStream = await SshHelpers.openConnection(workspaceInfo, logger);
    return [sshStream, ConnectionMode.Relay];
}

/**
 * Attempt to extract the stamp name from a Uri
 */
function getStampFromUri(uri: string): string | undefined {
    for (let stamp of hubStamps) {
        if (uri.indexOf(stamp) !== -1) {
            return stamp;
        }
    }
}