import { DebugProtocol } from 'vscode-debugprotocol';
import * as vslsDebug from './DebugSessionHostService';


export class DebugUtil {
    public static getStackTrace(
        _args: DebugProtocol.StackTraceArguments, 
        stoppedEvent: vslsDebug.UIStoppedEvent,
        _request?: DebugProtocol.Request): 
        vslsDebug.StackTraceResponse
    {
        let bodyResponse: vslsDebug.StackTraceResponse = undefined;
        const threadIdStr = _args.threadId.toString();
        if (stoppedEvent.stackFrames.hasOwnProperty(threadIdStr)) {
            const stackTraceInfos = stoppedEvent.stackFrames[threadIdStr];
            let posStart = (_args.startFrame ? _args.startFrame : 0);
            let posEnd = posStart + (_args.levels ? _args.levels : 0);

            const verifyRange = (str: vslsDebug.StackTraceResponse): boolean => {
                if (!_args.levels) {
                    // no range specified
                    posEnd = str.totalFrames;
                    return true;
                }
                if (str.totalFrames) {
                    posStart = Math.min(posStart, str.totalFrames);
                    posEnd = Math.min(posEnd, str.totalFrames);
                }
                
                const count = str.stackFrames.length;
                return (posStart <= count) && (posEnd <= count);
            };

            const stackTraceResponse = stackTraceInfos.find(si => {
                return ((!_args.format && Object.keys(si.key).length === 0) ||
                    (_args.format && JSON.stringify(_args.format) === JSON.stringify(si.key))) &&
                    verifyRange(si.value);
            });

            if (stackTraceResponse) {
                bodyResponse = {
                    stackFrames: stackTraceResponse.value.stackFrames.slice(posStart, posEnd),
                    totalFrames: posEnd - posStart
                }
            }
        }

        return bodyResponse;
    }
}