import { ILogger } from '@vs/vso-logging';
import { IRpcClientProxy } from './IRpcClient';
import { RpcProxy } from './RpcProxy';
import { ServiceInfo } from './ServiceInfo';

export class RpcProxyCache {
    private readonly proxyMap = new Map<string, RpcProxy>();

    constructor(private readonly clientProxy: IRpcClientProxy, private readonly logger: ILogger) {}

    public getOrCreate<T>(serviceInfo: ServiceInfo<T>, traceName?: string) {
        let proxy = this.proxyMap.get(serviceInfo.name!) as T & RpcProxy;
        if (!proxy) {
            this.logger.info(`Creating proxy for ${serviceInfo.name} service`);
            proxy = RpcProxy.create<T>(
                serviceInfo,
                this.clientProxy,
                traceName ? this.logger.withName(traceName) : this.logger
            ) as T & RpcProxy;
            this.proxyMap.set(serviceInfo.name!, proxy);
        }
        return proxy;
    }
}
