import * as path from 'path';
import { fileAccess, loadJSON } from '@vs/vscode-command-framework';

import { EXTENSION_ROOT_PATH } from '../constants';

/**
 * Function to check if the folder is LiveShare extension directory.
 * @param pathComponents 
 *      - @source - the path to the folder.
 *      - @name - folder name.
 * @returns Whether the folder is the LiveShare extension directory.
 */
const isLiveShareExtensionDirectory = (pathComponents: { source: string; name: string }): boolean => {
    const { source, name } = pathComponents;
    const folderPath = path.join(source, name);
    const packageInfo = loadJSON(path.resolve(EXTENSION_ROOT_PATH, './package.json'));

    const isDirectory = fileAccess.lstatSync(folderPath).isDirectory();

    if (isDirectory) {
        return new RegExp(`^${packageInfo.publisher}\\.${packageInfo.name}-[0-9]`).test(name);
    }

    return false;
};

/**
 * Function to get all liveshare directory names form the VSCode extensions directory.
 * @param source Path to the extensions directory.
 */
const getLiveShareExtensionDirectories = async (source: string) => {
    return (await fileAccess.readdirAsync(source))
            .map((name) => { return { source, name }; })
            .filter(isLiveShareExtensionDirectory);
};

/**
 * Function to check whether the current extension is the only LiveShare extension in the VSCode extensions folder.
 * @returns Whether the current extension is the only LiveShare extension in the VSCode extensions folder.
 */
export const isExtensionBeingUpdated = async (): Promise<boolean> => {
    try {
        const vscodeExtensionsRoot = path.join(EXTENSION_ROOT_PATH, '../');
        const directories = await getLiveShareExtensionDirectories(vscodeExtensionsRoot);

        return (directories.length > 1);
    } catch (e) {
        return false;
    }
};