import * as vscode from 'vscode';
import { Telemetry } from '@vs/vso-telemetry';
import { TelemetryPropertyNames } from '../telemetry/telemetryStrings';
interface IInitializedABTest {
    currentGroup: string;
}

interface IABExperimentsMementoRecord {
    // the map of tests that the current client was evaluated for
    evaluatedTests: {
        [key: string]: boolean;
    };

    // the map of tests that the current client is part of
    currentTests: {
        [key: string]: IInitializedABTest;
    };
}

interface IABTestGroup {
    name: Readonly<string>;
    probability: Readonly<number>;
}

export interface IABTest {
    name: Readonly<string>;
    groups: Readonly<IABTestGroup[]>;
    shouldAllowConcurrentExperiments?: Readonly<boolean>; // default: `false`
    shouldStartOnFirstRunOnly?: Readonly<boolean>; // default: `true`, if set to `false` will
}

const abTestDefaults: Partial<IABTest> = {
    shouldAllowConcurrentExperiments: false,
};

const AB_TESTS_SETTING_KEY = 'vscode-vsls-commands-ab-tests';

interface IEnabledTestsSettings {
    [key: string]: boolean;
}

interface IABTesterOptions {
    abTests: IABTest[];
    enabledTests: IEnabledTestsSettings;
    settingsStorage?: vscode.Memento;
    isFirstInitialization?: boolean;
}

export class ABTester {
    private options: IABTesterOptions | undefined;
    private settingsStorage: vscode.Memento;
    private isFirstInitialization: boolean;

    constructor(storage: vscode.Memento, isFirstInitialization: boolean) {
        this.settingsStorage = storage;
        this.isFirstInitialization = isFirstInitialization;
    }

    /**
     * Method to initialize the singleton.
     */
    public async initialize(options: IABTesterOptions) {
        this.options = options;
        const { settingsStorage, abTests, isFirstInitialization } = options;

        // update settings storage  object if was passed
        this.settingsStorage = settingsStorage || this.settingsStorage!;
        this.isFirstInitialization =
            isFirstInitialization != null ? isFirstInitialization : this.isFirstInitialization;

        // make sure there is the AB test config record on construction
        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        if (!currentConfig) {
            const initConfig: IABExperimentsMementoRecord = {
                currentTests: {},
                evaluatedTests: {},
            };
            await this.settingsStorage.update(AB_TESTS_SETTING_KEY, initConfig);
        }

        for (let i = 0; i < abTests.length; i++) {
            // add defaults
            abTests[i] = {
                ...abTestDefaults,
                ...abTests[i],
            };
        }

        await this.initializeTests();
        await this.addTelemetry();
    }

    private async addTelemetry() {
        // Adds AB test related properties to every telemetry event
        const abExperiment = await this.isPartOfAnyExperiment();
        Telemetry.addContextProperty(TelemetryPropertyNames.CURRENT_AB_EXPERIMENT, abExperiment);
        Telemetry.addContextProperty(
            TelemetryPropertyNames.COUNT_OF_CONCURRENT_AB_EXPERIMENTS,
            await this.getCountOfCurrentExperiments(),
        );
        Telemetry.addContextProperty(
            TelemetryPropertyNames.CURRENT_AB_EXPERIMENT_GROUP,
            await this.isPartOfExperiment(abExperiment),
        );
    }

    private async initializeTests() {
        for (let abTest of this.options!.abTests) {
            if ((await this.isPartOfAnyExperiment()) && !abTest.shouldAllowConcurrentExperiments) {
                continue;
            }

            await this.initializeTest(abTest);
        }
    }

    private cleanUpOldTest(abTest: IABTest) {
        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        // if remote setting for the test is not set,
        // and we have the test record, delete it
        if (currentConfig.evaluatedTests[abTest.name]) {
            delete currentConfig.evaluatedTests[abTest.name];
        }

        if (currentConfig.currentTests[abTest.name]) {
            delete currentConfig.currentTests[abTest.name];
        }

        this.settingsStorage.update(AB_TESTS_SETTING_KEY, currentConfig);
    }

    private async initializeTest(abTest: IABTest) {
        const { enabledTests } = this.options!;

        const remoteEnableTestSetting = enabledTests[abTest.name];

        if (!remoteEnableTestSetting) {
            this.cleanUpOldTest(abTest);
        }

        // if the test should be run
        if (abTest.shouldStartOnFirstRunOnly && !this.isFirstInitialization) {
            return;
        }

        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        const isPartOfAnyExperiment = !(await this.isPartOfAnyExperiment());
        const isEvaluatedAlready = !currentConfig.evaluatedTests[abTest.name];
        if (isPartOfAnyExperiment && isEvaluatedAlready && remoteEnableTestSetting) {
            const currentGroup = this.initializeGroupForTest(abTest, currentConfig);
            // if selected for any of the experimental groups
            if (currentGroup) {
                currentConfig.currentTests[abTest.name] = { currentGroup };
            }

            this.settingsStorage.update(AB_TESTS_SETTING_KEY, currentConfig);
        }
    }

    private initializeGroupForTest(
        abTest: IABTest,
        currentConfig: IABExperimentsMementoRecord,
    ): string | undefined {
        const randomNumber = Math.random();

        let currentLowerBound = 0;
        for (let group of abTest.groups) {
            let currentUpperBound = currentLowerBound + group.probability;

            if (randomNumber > currentLowerBound && randomNumber <= currentUpperBound) {
                return;
            }

            currentLowerBound = currentUpperBound;
        }

        currentConfig.evaluatedTests[abTest.name] = true;
    }

    /**
     * Method to check if the current client if part of a particular experiment.
     */
    public async isPartOfExperiment(name: string | null): Promise<string | null> {
        if (!name) {
            return null;
        }

        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        const experimentRecord = currentConfig.currentTests[name];

        return experimentRecord ? experimentRecord.currentGroup : null;
    }

    /**
     * Method to check if the current client is part of any experiment.
     */
    public async isPartOfAnyExperiment(): Promise<string | null> {
        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        const currentTests = Object.keys(currentConfig.currentTests);

        return currentTests[0] || null;
    }

    /**
     * Method to get how many concurrent experiemnts the client is a part of.
     */
    public async getCountOfCurrentExperiments(): Promise<number> {
        const currentConfig = this.settingsStorage.get(
            AB_TESTS_SETTING_KEY,
        ) as IABExperimentsMementoRecord;
        const currentTests = Object.keys(currentConfig.currentTests);

        return currentTests.length;
    }
}
