import { ServiceInfo } from '@vs/vso-rpc';
import * as rpc from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';
import { HostConnectionChanged, WorkspaceMetricsUpdated } from './IWorkspaceConnection';
import { CheckConnectionOptions } from './IWorkspaceClient';
import { ILiveShareConnectionOptions } from './ILiveShareConnectionOptions';

export interface WorkspaceHostConnectionChanged extends HostConnectionChanged {
    workspaceId: string;
}

export interface RemoteWorkspaceMetricsUpdated extends WorkspaceMetricsUpdated {
    workspaceId: string;
}
export interface IWorkspaceServiceClient {
    readonly onHostConnectionChanged: rpc.Event<WorkspaceHostConnectionChanged>;
    readonly onWorkspaceMetricsUpdated: rpc.Event<RemoteWorkspaceMetricsUpdated>;

    getSessionInfoAsync(
        workspaceId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<vsls.WorkspaceSessionInfo | undefined>;
    joinAsync(joinConnectOptions: ILiveShareConnectionOptions): Promise<vsls.WorkspaceSessionInfo>;
    disconnectAsync(workspaceId: string): Promise<void>;
    openStreamingChannelAsync(
        workspaceId: string,
        streamId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<void>;
    keepAliveAsync(time?: number): Promise<void>;
    checkConnectionAsync(
        workspaceId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<void>;
    setCheckConnectionOptionsAsync(
        workspaceId: string,
        options: CheckConnectionOptions
    ): Promise<void>;
}

export const workspaceServiceClient: ServiceInfo<IWorkspaceServiceClient> = {
    name: 'workspaceServiceClient',
    methods: [
        'getSessionInfo',
        'join',
        'disconnect',
        'openStreamingChannel',
        'keepAlive',
        'checkConnection',
        'setCheckConnectionOptions',
    ],
    events: ['hostConnectionChanged', 'workspaceMetricsUpdated'],
};
