import { ExtensionSetupBase } from '@vs/liveshare-core';
import { builder as OpenSessionChatCommandBuilder } from './OpenSessionChatCommand';
import { StartOrJoinCallCommandBuilder } from './StartOrJoinCallCommandBuilder';

export const registerCommands = (extensionSetup: ExtensionSetupBase): void => {
    // chat commands
    extensionSetup.register('openSessionChat', OpenSessionChatCommandBuilder);

    // audio commands
    extensionSetup.register('startOrJoinCall', StartOrJoinCallCommandBuilder);
};