import {
    Event,
    EventEmitter,
    Disposable
} from 'vscode';

import {
    Contact,
    ContactsCollection,
    InviteContactOptions
} from '@vs/liveshare-api-contracts';
import { 
    ContactManager,
    ContactCommandUtilities
} from '@vs/liveshare-contactservice';
import { IContactModel, IContactManager } from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
export class ContactApi implements Contact {
    private onDidChangePropertyEmitter = new EventEmitter<string[]>();
    private onDidChangePropertyDisposable: Disposable;
    private contactModel: IContactModel;

    public constructor(private readonly contactManager: IContactManager, contactModel: IContactModel) {
        this.attachContactModel(contactModel);
    }

    public get onDidChange(): Event<string[]> { return this.onDidChangePropertyEmitter.event; }

    public get id(): string { return this.contact.id; }
    public get email(): string { return this.contact.email; }
    public get displayName(): string { return this.contact.displayName; }
    public get status(): string { return this.contact.status.toString(); }
    public get avatarUri(): string { return this.contact.avatarUri; }
    public get isRecentContact(): boolean { return this.contactManager.isRecentContat(this.contactModel); }
    public get isSuggestedContact(): boolean { return this.contactManager.isSuggestedContat(this.contactModel); }
    public get allowInvites(): string { return this.contactModel.properties['allowInvites']; }
    
    private get contact(): contactProtocol.Contact { return this.contactModel.contact; }

    public invite(options?: InviteContactOptions): Promise<boolean> {
        if (options && options.useEmail) {
            return ContactCommandUtilities.inviteByEmail(this.email, this.displayName);
        }

        return ContactCommandUtilities.inviteHelper(this.contactModel);
    }

    private attachContactModel(contactModel: IContactModel) {
        if (this.onDidChangePropertyDisposable) {
            this.onDidChangePropertyDisposable.dispose();
            this.onDidChangePropertyDisposable = null;
        }

        this.contactModel = contactModel;
        this.onDidChangePropertyDisposable = contactModel.onDidChangeProperty((properties) => {
            this.onDidChangePropertyEmitter.fire(properties);
        });
    }

    public static async getContacts(contactManager: IContactManager, emails: string[]): Promise<ContactsCollection> {
        const contacts: { [email: string]: ContactApi} = {};
        const result = await ContactManager.requestContacts(emails);

        result.contactModels.forEach(c => {
            contacts[c.contact.email] = new ContactApi(contactManager, c);
        });

        const disposable = result.onContactsChanged(() => {
            result.contactModels.forEach(c => {
                const contactApi = contacts[c.contact.email];
                if (contactApi) {
                    contactApi.attachContactModel(c);
                    contactApi.onDidChangePropertyEmitter.fire([]);
                }
            });
        });

        return {
            contacts,
            dispose: () => {
                disposable.dispose();
                return result.dispose();
            }
        };
    }
}