import {
    TelemetryEvent,
} from '@vs/vso-telemetry';

import {
    TelemetryEventNames,
    TelemetryPropertyNames
} from '@vs/liveshare-core';

export class WorkspaceTaskTelemetry {
    public static readonly FEATURE_PREFIX = 'WorkspaceTask/';
    public static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'WorkspaceTask.';

    public static sendExecutionSummary(taskKind: string, executionTimes: number[]): void {
        let summaryEvent = new TelemetryEvent(EventNames.EXECUTE_SHARED_TASK);
        summaryEvent.addProperty(PropertyNames.TASK_KIND, taskKind);
        summaryEvent.addMeasure(PropertyNames.TOTAL_COUNT, executionTimes.length);
        summaryEvent.addMeasure(PropertyNames.MAX_TIME, Math.max(...executionTimes));
        summaryEvent.addMeasure(PropertyNames.MIN_TIME, Math.min(...executionTimes));
        summaryEvent.addMeasure(PropertyNames.AVERAGE_TIME, executionTimes.reduce((p, c) => p + c, 0) / executionTimes.length);
        summaryEvent.send();
    }
}

class EventNames {
    public static readonly EXECUTE_SHARED_TASK = 'execute-task';
    public static readonly TASK_EXECUTION_ERROR = TelemetryEventNames.FAULT_PREFIX + 'execute-task-error';
}

class PropertyNames {
    public static readonly TASK_KIND = TelemetryPropertyNames.FEATURE_NAME + 'TaskKind';
    public static readonly TOTAL_COUNT = TelemetryPropertyNames.FEATURE_NAME + 'TotalCount';
    public static readonly MAX_TIME = TelemetryPropertyNames.FEATURE_NAME + 'MaxTime';
    public static readonly MIN_TIME = TelemetryPropertyNames.FEATURE_NAME + 'MinTime';
    public static readonly AVERAGE_TIME = TelemetryPropertyNames.FEATURE_NAME + 'AverageTime';
}