import * as vscode from 'vscode';
import { contactProtocol, vsls } from '@vs/vsls-contracts';
import { TraceSource } from '@vs/vso-logging';
import { ProviderBase } from '@vs/liveshare-contactservice';
import { HubConnectionService } from '../HubConnectionService';
import { ContactServiceProxy, IContactReference } from '@vs/vso-signalr-client-proxy';
import { userAuthStateTracker, HubProxyType } from '@vs/liveshare-core';
const inviteLinkType = 'inviteLink';

interface InviteLink {
    readonly Link: string;
    readonly Contact: contactProtocol.Contact;
}

enum Properties {
    email = 'email',
    displayName = 'name',
    status = 'status',
    avatarUri = 'avatarUri',
    contactId = 'contactId',
    idReserved = '_Id',
}

const reservedProeprties = [
    Properties.email,
    Properties.displayName,
    Properties.status,
    Properties.avatarUri,
];

const isReservedProperty = (name: string): boolean => reservedProeprties.find(p => name === p) !== undefined;
const presenceValues = [
    contactProtocol.PresenceStatus.Unknown,
    contactProtocol.PresenceStatus.Available,
    contactProtocol.PresenceStatus.Busy,
    contactProtocol.PresenceStatus.DoNotDisturb,
    contactProtocol.PresenceStatus.Away,
    contactProtocol.PresenceStatus.Invisible,
    contactProtocol.PresenceStatus.Offline,
];

export class PresenceServiceProvider extends ProviderBase {
    private readonly contactServiceProxy: ContactServiceProxy;
    private signInRequested: boolean;
    private publishPresence: contactProtocol.PublishPresenceRequest;
    private enablePublish?: boolean;
    private currentSubscriptions = new Map<string, ContactSubscription>();

    public constructor(private hubConnectionService: HubConnectionService, private traceSource: TraceSource) {
        super();

        this.contactServiceProxy = hubConnectionService.getOrCreateProxy<ContactServiceProxy>(HubProxyType.ContactService);
        this.contactServiceProxy.onUpdateProperties((contact, properties, targetConnectionId) => this.onUpdateProperties(contact, properties, targetConnectionId));
        this.contactServiceProxy.onMessageReceived((targetContact, fromContact, messageType, body) => this.onMessageReceived(targetContact, fromContact, messageType, body));

        hubConnectionService.onAttemptStateChanged(() => this.onAttemptStateChanged());
        hubConnectionService.onConnectionStateChanged(() => this.onConnectionStateChanged());
    }

    public async requestAsync(
        type: string,
        parameters: Object,
        cancellationToken?: vscode.CancellationToken)
        : Promise<Object> {
            if (type === contactProtocol.Methods.RequestInitializeName) {
                return super.requestAsync(type, parameters, cancellationToken);
            }
            let result = null;

            switch (type) {
                case contactProtocol.Methods.RequestSendMessageName:
                    await this.requestSendMessage(<contactProtocol.SendMessageRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestInviteName:
                    await this.requestInvite(<contactProtocol.InviteRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestPublishPresenceName:
                    await this.requestPublishPresence(<contactProtocol.PublishPresenceRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestContactPresenceName:
                    result = await this.requestContactPresence(<contactProtocol.ContactPresenceRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestContactPresenceDisposeName:
                    await this.requestContactPresenceDispose(<contactProtocol.ContactPresenceDisposeRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestSignInName:
                    await this.requestSignIn(<contactProtocol.SignInRequest>parameters);
                    break;
                case contactProtocol.Methods.RequestSignOutName:
                    await this.requestSignOut();
                    break;
            default:
                throw new Error(`type:${type} not supported`);
            }

            return result;
    }

    protected async requestInitialize(request: contactProtocol.InitializeRequest): Promise<contactProtocol.InitializeResponse> {
        this.enablePublish = request.enablePublish;
        this.publishPresence = request.publishPresence;

        let selfContact: contactProtocol.Contact = null;
        if (this.isServiceConnected) {
            selfContact = PresenceServiceProvider.userInfoToContact(this.userInfo);
        }

        const response = new contactProtocol.InitializeResponse();
        response.description = 'Live Share';
        response.capabilities = PresenceServiceProvider.createCapabilites(this.capabilitiesEnabled);
        response.selfContact = selfContact;
        response.signedState = this.isServiceConnected ? contactProtocol.SignedStatus.SignedIn : this.isAttempting ? contactProtocol.SignedStatus.SigningIn : contactProtocol.SignedStatus.SignedOut;
        response.providerPriority = 0; // the lowest possible provider

        return response;
    }

    private get capabilitiesEnabled() {
        return this.isServiceConnected && this.isAuthorizedUser;
    }

    private get isAuthorizedUser() {
        return !userAuthStateTracker.isCurrentUserAnonymous();
    }

    private async requestSendMessage(request: contactProtocol.SendMessageRequest): Promise<void> {
        await this.contactServiceProxy.sendMessage({
           id: request.targetContactId,
        }, request.type, request.body);
    }

    private async requestInvite(request: contactProtocol.InviteRequest): Promise<void> {
        const body: InviteLink = {
            Link: request.link,
            Contact: {
                id: this.userInfo.id,
                email: this.userInfo.emailAddress,
                displayName: this.userInfo.displayName
            } as contactProtocol.Contact
        };
        await this.contactServiceProxy.sendMessage({
            id:  request.targetContactId,
         }, inviteLinkType, body);
    }

    private async requestPublishPresence(request: contactProtocol.PublishPresenceRequest): Promise<void> {
        if (this.isPublishEnabled) {
            this.publishPresence = request;
            const publishProperties = {};

            if (request.status !== contactProtocol.PresenceStatus.Unknown) {
                // @ts-ignore
                publishProperties[Properties.status] = request.status;
            }

            if (request.properties) {
                Object.assign(publishProperties, request.properties);
            }

            if (this.capabilitiesEnabled) {
                await this.contactServiceProxy.publishProperties(publishProperties);
            }
        }
    }

    private async requestContactPresence(request: contactProtocol.ContactPresenceRequest): Promise<contactProtocol.ContactPresenceResponse> {
        const contactsResponse: contactProtocol.ContactResponse[] = [];
        const targetContactProperties: ContactRequest[] = [];

        // when adding an empty request
        const addEmptyRequestContact = (requestContact: contactProtocol.Contact) => {
            contactsResponse.push({
                contactId: requestContact.id,
                contact: requestContact
            });
        };

        const isLiveshareUserProfileId = (id: string): boolean => id && id.length >= 36;

        request.contacts.forEach(requestContact => {
            if (isLiveshareUserProfileId(requestContact.id)) {
                if (this.currentSubscriptions.has(requestContact.id)) {
                    const contactSubscription = this.currentSubscriptions.get(requestContact.id);
                    contactSubscription.addSubscriptionCount();
                    contactsResponse.push(PresenceServiceProvider.createContactResponse(requestContact, contactSubscription));
                } else {
                    // the passed contact id is a valid user profile that can be used directly without any match needed
                    const props = {};
                    // @ts-ignore
                    props[Properties.idReserved] = requestContact.id;

                    targetContactProperties.push({
                        contact: requestContact,
                        properties: props
                    });
                }
            } else if (requestContact.email && requestContact.email.length > 0) {
                const contactSubscription = this.findContactSunscriptionByEmail(requestContact.email);
                if (!contactSubscription) {
                    // this will enforce a match to happen on the service
                    const props = {};
                    // @ts-ignore
                    props[Properties.email] = requestContact.email;
                    targetContactProperties.push({
                        contact: requestContact,
                        properties: props
                    });
                } else {
                    // we already have an existing subscription with the same email
                    contactSubscription.addSubscriptionCount();
                    contactsResponse.push(PresenceServiceProvider.createContactResponse(requestContact, contactSubscription));
                }
            } else {
                addEmptyRequestContact(requestContact);
            }
        });

        if (targetContactProperties.length > 0) {
            const resultSubscriptions = await this.contactServiceProxy.requestSubcriptions(
                targetContactProperties.map(i => i.properties),
                ['*'],
                true);
            for (let index = 0; index < resultSubscriptions.length; ++index) {
                const requestContact = targetContactProperties[index].contact;
                const publishedProperties = resultSubscriptions[index];

                if (publishedProperties) {
                    const contactSubscription = new ContactSubscription();
                    contactSubscription.id = tryGetProperty(publishedProperties, Properties.idReserved);
                    contactSubscription.email = tryGetProperty(publishedProperties, Properties.email);
                    contactSubscription.displayName = tryGetProperty(publishedProperties, Properties.displayName);
                    contactSubscription.avatarUri = tryGetProperty(publishedProperties, Properties.avatarUri);

                    const status = tryGetProperty(publishedProperties, Properties.status);
                    if (status) {
                        contactSubscription.status = PresenceServiceProvider.toPresenceStatus(status);
                    } else {
                        contactSubscription.status = contactProtocol.PresenceStatus.Unknown;
                    }

                    // populate non-reserved properties
                    Array.from(Object.keys(publishedProperties)).forEach(k => {
                        if (!isReservedProperty(k)) {
                            contactSubscription.properties[k] = publishedProperties[k];
                        }
                    });

                    contactsResponse.push(PresenceServiceProvider.createContactResponse(requestContact, contactSubscription));
                    this.currentSubscriptions.set(contactSubscription.id, contactSubscription);
                } else {
                    addEmptyRequestContact(requestContact);
                }
            }
        }

        return {
            contacts: contactsResponse
        };
    }

    private async requestContactPresenceDispose(request: contactProtocol.ContactPresenceDisposeRequest): Promise<void> {
        // Note: it is possible that we get a request to dispose a set of contacts request but we just get disconnected
        // This addtional check would prevent lot of log errors beign generated
        if (!this.isServiceConnected) {
            return;
        }

        const userInfoId = this.userInfoId;
        const contactIds = request.contactIds.filter(c => c !== userInfoId);
        if (contactIds.length > 0) {
            const removeSubscriptionContactIds: string[] = [];
            contactIds.forEach(contactId => {
                if (this.currentSubscriptions.has(contactId) && this.currentSubscriptions.get(contactId).removeSubscriptionCount()) {
                    removeSubscriptionContactIds.push(contactId);
                    this.traceSource.verbose(`Remove subscription for contact Id:${contactId}`);
                    this.currentSubscriptions.delete(contactId);
                }
            });

            if (removeSubscriptionContactIds.length > 0) {
                const targetContacts = removeSubscriptionContactIds.map(contactId => {
                    return {
                        id: contactId,
                    } as IContactReference;
                });

                await this.contactServiceProxy.removeSubscription(targetContacts);
            }
        }
    }

    private async requestSignIn(signInRequest: contactProtocol.SignInRequest) {
        this.traceSource.verbose('reguestSignIn');

        this.signInRequested = true;
        this.hubConnectionService.enabled = true;
        if (this.hubConnectionService.isConnected) {
            await this.signIn();
        } else if (!this.hubConnectionService.isConnectionEnabled) {
            // we want to connect but auth is not yet ready
            this.notify(contactProtocol.Methods.NotifyAuthenticationRequiredName, <contactProtocol.AuthenticationRequiredNotification> {
                // we may pass more data related
            });
        }
    }

    private async requestSignOut() {
        this.traceSource.verbose('reguestSignOut');

        this.signInRequested = false;
        await this.contactServiceProxy.unregisterSelfContact();
        this.signOut();
        this.notifySignedOut();
    }

    private onUpdateProperties(contact: IContactReference, properties: { [key: string]: any; }, targetConnectionId: string) {
        this.traceSource.verbose(`onUpdateProperties -> contact Id:${contact.id}`);

        const nonReservedProperties = Array.from(Object.keys(properties)).filter(p => !isReservedProperty(p));
        // update contact subscription cache if needed
        if (this.currentSubscriptions.has(contact.id)) {
            const contactSubscription = this.currentSubscriptions.get(contact.id);

            let value: any;
            value = tryGetProperty(properties, Properties.email);
            if (value) {
                contactSubscription.email = value;
            }
            value = tryGetProperty(properties, Properties.displayName);
            if (value) {
                contactSubscription.displayName = value;
            }
            value = tryGetProperty(properties, Properties.avatarUri);
            if (value) {
                contactSubscription.avatarUri = value;
            }

            value = tryGetProperty(properties, Properties.status);
            if (value) {
                contactSubscription.status = value;
            }

            // non-reserved proeprties
            nonReservedProperties.forEach(p => contactSubscription.properties[p] = properties[p]);
        }

        if (properties.hasOwnProperty(Properties.status)) {
            this.notifyPresenceChanged(contact.id, PresenceServiceProvider.toPresenceStatus(properties[Properties.status]));
        }

        const otherChangedProperties = Array.from(Object.keys(properties)).filter(p => p !== Properties.status && isReservedProperty(p)).map(p => {
            return {
                property: PresenceServiceProvider.toContactProperty(p),
                value: properties[p]
            } as contactProtocol.ContactPropertyValueChanged;
        });

        if (otherChangedProperties.length > 0) {
            this.notifyContactChanged(contact.id, otherChangedProperties);
        }

        if (nonReservedProperties.length > 0) {
            const changes = {};
            // @ts-ignore
            nonReservedProperties.forEach(p => changes[p] = properties[p]);
            this.notifyContactPropertiesChanged(contact.id, changes);
        }
    }

    private onMessageReceived(targetContact: IContactReference, fromContact: IContactReference, messageType: string, body: any) {
        if (messageType === inviteLinkType) {
            const inviteLink = body as InviteLink;
            const inviteReceivedNotification = new contactProtocol.InviteReceivedNotification();
            inviteReceivedNotification.fromContactId = fromContact.id;
            inviteReceivedNotification.link = inviteLink.Link;
            inviteReceivedNotification.fromContact = inviteLink.Contact;

            this.notify(contactProtocol.Methods.NotifyInviteReceivedName, inviteReceivedNotification);
        } else {
            const messageReceivedNotification = new contactProtocol.MessageReceivedNotification();
            messageReceivedNotification.fromContactId = fromContact.id;
            messageReceivedNotification.body = body;
            messageReceivedNotification.type = messageType;

            this.notify(contactProtocol.Methods.NotifyMessageReceivedName, messageReceivedNotification);
        }
    }

    private async publishUserInfo(userInfo: vsls.UserInfo): Promise<void> {
        this.traceSource.verbose(`publishUserInfo -> id:${userInfo.id} email:${userInfo.emailAddress}`);

        let publishInfo = {};
        // @ts-ignore
        publishInfo[Properties.email] = userInfo.emailAddress;
        // @ts-ignore
        publishInfo[Properties.displayName] = userInfo.displayName;
        // @ts-ignore
        publishInfo[Properties.status] = contactProtocol.PresenceStatus.Available;
        // @ts-ignore
        publishInfo[Properties.avatarUri] = userInfo.avatarUri;

        if (this.publishPresence) {
            // @ts-ignore
            publishInfo[Properties.status] = this.publishPresence.status;
            if (this.publishPresence.properties) {
                Object.assign(publishInfo, this.publishPresence.properties);
            }
        }

        if (!this.isPublishEnabled) {
            publishInfo = {};
        }

        const registrationInfo = await this.contactServiceProxy.registerSelfContact(userInfo.id, publishInfo);
        // Self to protocol notification
        this.notify(contactProtocol.Methods.NotifySelfContactName, <contactProtocol.SelfContactNotification> {
            contact: PresenceServiceProvider.userInfoToContact(userInfo),
            registrationInfo,
        } );
    }

    private get userInfo(): vsls.UserInfo | undefined {
        const currentUserInfo = this.hubConnectionService.currentUserInfo;
        if (currentUserInfo) {
            return currentUserInfo.userInfo;
        }
    }

    private get userInfoId(): string | undefined {
        const userInfo = this.userInfo;
        if (userInfo) {
            return userInfo.id;
        }
    }

    private get isServiceConnected(): boolean {
        return this.hubConnectionService.isConnected;
    }

    private get isAttempting(): boolean {
        return this.hubConnectionService.isAttempting;
    }

    private get isPublishEnabled(): boolean {
        return !this.enablePublish || this.enablePublish === true;
    }

    private findContactSunscriptionByEmail(email: string): ContactSubscription | undefined {
        return Array.from(this.currentSubscriptions.values()).find(c => c.email === email);
    }

    private notifyCurrentCapabilites(enabled?: boolean) {
        this.notify(
            contactProtocol.Methods.NotifyCapabilitiesUpdateName, PresenceServiceProvider.createCapabilites(enabled === undefined ? this.capabilitiesEnabled : enabled));
    }

    private onAttemptStateChanged() {
        if (this.isAttempting) {
            if (this.signInRequested) {
                this.notifySigningIn();
            }
        } else {
            this.notifySignedOut();
        }
    }

    private notifySigningIn() {
        this.notifySignedStateChanged(contactProtocol.SignedStatus.SigningIn);
    }

    private notifySignedIn() {
        this.notifySignedStateChanged(contactProtocol.SignedStatus.SignedIn);
    }

    private notifySignedOut() {
        this.notifySignedStateChanged(contactProtocol.SignedStatus.SignedOut);
    }

    private async onConnectionStateChanged(): Promise<void> {
        if (this.hubConnectionService.isConnected) {
            if (this.signInRequested) {
                await this.signIn();
            }
        } else {
            this.signOut();
            this.notifySignedStateChanged(this.isAttempting && this.signInRequested ? contactProtocol.SignedStatus.SigningIn : contactProtocol.SignedStatus.SignedOut);
        }
    }

    private async signIn(): Promise<void> {
        if (this.isAuthorizedUser) {
            await this.publishUserInfo(this.userInfo);
        }
        this.notifyCurrentCapabilites();
        this.notifySignedIn();

    }

    private signOut() {
        this.currentSubscriptions.clear();
        this.notifyCurrentCapabilites(false);
        this.notifyPresenceChanged(this.userInfoId, contactProtocol.PresenceStatus.Offline);
    }

    private static toContactProperty(propertyName: string): contactProtocol.ContactProperty {
        switch (propertyName) {
            case Properties.email:
                return contactProtocol.ContactProperty.Email;
            case Properties.displayName:
                return contactProtocol.ContactProperty.DisplayName;
            case Properties.status:
                return contactProtocol.ContactProperty.Status;
            case Properties.avatarUri:
                return contactProtocol.ContactProperty.AvatarUri;
            default:
                throw new Error('Invaild property');
        }
    }

    private static createCapabilites(enabled: boolean): contactProtocol.Capabilities {
        const capabilities = new contactProtocol.Capabilities();

        capabilities.supportsDispose = enabled,
        capabilities.supportsPresence = enabled,
        capabilities.supportsPublishPresence = enabled,
        capabilities.supportsInviteLink = enabled,
        capabilities.supportsSelfContact = enabled,
        capabilities.supportsContactPresenceRequest = enabled,
        // Note: the presence service does support some sort of search but without a context scope
        // it will be disabled and considered for future review
        //SupportsSearchContacts = enabled,
        capabilities.supportsMessageRequest = enabled,
        capabilities.supportedPresenceStatus = [
            contactProtocol.PresenceStatus.Available,
            contactProtocol.PresenceStatus.DoNotDisturb,
            contactProtocol.PresenceStatus.Away,
        ],
        capabilities.supportsSignedStateRequest = true;

        return capabilities;
    }

    private static userInfoToContact(userInfo: vsls.UserInfo): contactProtocol.Contact {
        const contact = new contactProtocol.Contact();

        contact.id = userInfo.id,
        contact.email = userInfo.emailAddress,
        contact.displayName = userInfo.displayName,
        contact.status = contactProtocol.PresenceStatus.Available,
        contact.avatarUri = userInfo.avatarUri;
        return contact;
    }

    private static createContactResponse(requestContact: contactProtocol.Contact, contactSubscription: ContactSubscription ): contactProtocol.ContactResponse {
        return {
            contactId: requestContact.id,
            contact: {
                id: contactSubscription.id,
                email: requestContact.email ? requestContact.email : contactSubscription.email,
                displayName: requestContact.displayName ? requestContact.displayName : contactSubscription.displayName,
                avatarUri: requestContact.avatarUri ? requestContact.avatarUri : contactSubscription.avatarUri,
                status: contactSubscription.status
            },
            properties: contactSubscription.properties
        };
    }

    private static toPresenceStatus(statusValue: any): contactProtocol.PresenceStatus {
        if (Number.isInteger(statusValue)) {
            return presenceValues[statusValue];
        }

        return statusValue as contactProtocol.PresenceStatus;
    }
}

class ContactSubscription extends contactProtocol.Contact {
    private counter: number = 1;

    constructor() {
        super();
        this.properties = {};
    }

    public properties: any;

    public addSubscriptionCount(): void {
        ++this.counter;
    }

    public removeSubscriptionCount(): boolean {
        --this.counter;
        return this.counter === 0;
    }
}

function tryGetProperty(o: any, name: string) {
    if (o.hasOwnProperty(name)) {
        return o[name];
    }
}

interface ContactRequest {
    contact: contactProtocol.Contact;
    properties: any;
}