import { ICommandContext } from '@vs/vscode-command-framework';
import { dependencies } from '../Dependencies';
import { CancellationError } from "@vs/vscs-utils";
import { ErrorCodes as VSCodeRpcErrorCodes } from 'vscode-jsonrpc';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { sessionStateTracker } from '../SessionStateTracker';
import { ISessionContext } from '../ISessionContext';
import { SessionAction } from '../SessionTypes';

export function sessionStateTransitionsCommandDecorator(
    statusStart?: SessionAction,
    statusComplete?: SessionAction,
    statusCompleteError?: SessionAction,
    validateSessionAction?: (options: any) => boolean) {
    return DecoratorHelper.setupDecorator(
        (command: ICommand<any>) => new SessionStateTransitionsCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command,
            dependencies.sessionContext(),
            validateSessionAction,
            statusStart,
            statusComplete,
            statusCompleteError));
}

/**
 * SessionContext Transition `commandHandler` that automatically transitions the
 * `start`, `completeError` and `complete` states for the command.
 */
export class SessionStateTransitionsCommandDecorator implements ICommandDecorator {
    // Tracks the number of command invocations in flight.
    private static count = 0;

    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>,
        private sessionContext: ISessionContext,
        private validateSessionAction?: (options: any) => boolean,
        private statusStart?: SessionAction,
        private statusComplete?: SessionAction,
        private statusCompleteError?: SessionAction) {
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;
        SessionStateTransitionsCommandDecorator.count++;

        try {
            if (this.statusStart !== undefined && this.shouldPerformSessionAction(options)) {
                sessionStateTracker.transition(this.statusStart);
            }

            result = await this.next.invoke(options, context);

            if (this.statusComplete !== undefined && this.shouldPerformSessionAction(options)) {
                sessionStateTracker.transition(this.statusComplete);
            }
        } catch (error) {
            // Only transition state on cancel if there are no other commands in flight.
            // The final command invoked will transition the state machine to the correct state.
            // Ex: the user can double-click the 'Start Collaboration Session' button from the activity
            // bar. The second click will cancel the first 'Share' command while the second 'Share' command
            // is still in flight. If the state is transitioned on the first cancel (AttemptSharing -> SignedIn)
            // then when the second 'Share' completes it will attempt to transition from SignedIn -> Shared.
            // Since there is no SharingSuccess action transition from the SignedIn state (only AttemptSharing -> Shared)
            // it will leave the user in an incorrect state.
            const isCancel = (error instanceof CancellationError) ||
                (error.code === VSCodeRpcErrorCodes.RequestCancelled);
            const isCancelWithoutTransition = (SessionStateTransitionsCommandDecorator.count !== 1) && isCancel;
            if (isCancelWithoutTransition) {
                // Return without state transition. Don't throw the cancellation error as
                // we don't want to show a cancellation notification to the user.
                return;
            }

            if (this.shouldPerformSessionAction(options)) {
                sessionStateTracker.transition(this.statusCompleteError);
            }
            throw error;
        } finally {
            SessionStateTransitionsCommandDecorator.count--;
        }

        return result;
    }

    private shouldPerformSessionAction(options: any): boolean {
        return !this.validateSessionAction || this.validateSessionAction(options);
    }
}