import { PolicyResolutionStrategy } from './policyResolutionStrategy';

export class BooleanStrategy implements PolicyResolutionStrategy<boolean> {
    private inverted: boolean;
    public readonly default: boolean;

    constructor(inverted: boolean = false) {
        this.inverted = inverted;
        this.default = inverted;
    }

    public resolvePolicy(policyValues: boolean[]): boolean {
        if (!policyValues || policyValues.length === 0)
            return this.default;

        let result = policyValues.reduce((p, c) => p && c);
        return this.inverted ? !result : result;
    }
}
