import { RpcMessageWriter, notifyEventProviderType } from '@vs/vso-rpc';
import * as signalr_proxy from '@vs/vso-signalr-client-proxy';
import * as rpc from 'vscode-jsonrpc';

import { RelayHubProxyServer } from './RelayHubProxyServer';
import * as constants from './constants';

/** create notify event provider from a relay hub proxy server */
export function createRelayHubEventNotifier(
    relayHubProxyServer: RelayHubProxyServer,
    hubStreamType?: string
): notifyEventProviderType {
    let nextNotifySequence = 0;
    const typeHubData = hubStreamType || constants.DATA_TYPE_LIVESHARE_HUB;

    const rpcMessageWriter = new RpcMessageWriter();
    relayHubProxyServer.onHubJoined((e) => {
        if (e) {
            rpcMessageWriter.onSendCallback = async (data) => {
                await e.sendData(
                    signalr_proxy.SendOption.None,
                    null,
                    `${typeHubData}${constants.POST_FIX_NOTIFY}`,
                    data,
                    signalr_proxy.RelayHubMessageProperties.createMessageSequence(
                        ++nextNotifySequence
                    )
                );
            };
        } else {
            nextNotifySequence = 0;
            rpcMessageWriter.onSendCallback = null;
        }
    });

    const notifyAllMessageConnection = rpc.createMessageConnection(
        {} as rpc.MessageReader,
        rpcMessageWriter
    );

    return (serviceAndMethod: string, event: any) =>
        notifyAllMessageConnection.sendNotification(serviceAndMethod, event);
}
