import { Hasher, sha256 } from 'js-sha256';

export class Privacy {
    private static privacyKey: string;

    public static setKey(privacyKeyBase64: string) {
        Privacy.privacyKey = privacyKeyBase64;
    }

    public static getShortHash(
        value: string,
        length: number = 8,
        unkeyed: boolean = false
    ): string {
        return this.getHash(value, unkeyed).substr(0, length);
    }

    public static getHash(
        value: string,
        unkeyed: boolean = false
    ): string {
        if (!value) {
            return '<null>';
        }
        
        let hasher: Hasher;
        
        if (unkeyed) {
            hasher = sha256.create();          
        } else {
            if (!Privacy.privacyKey ) {
                return '<redacted>';
            }
                   
            hasher = sha256.hmac.create(Privacy.privacyKey);
        }
        
        return hasher
            .update(value)
            .hex();
    }

    /** Get sha256 hash of UTF8 encoded value. Undefined or null value is treated as empty string. */
    public static getSha256Hash(value: string, maxLength?: number): string {
        const result = sha256.create().update(new TextEncoder().encode(value || '')).toString();
        return typeof maxLength === 'number' && maxLength > 0 && result.length > maxLength ? result.substr(0, maxLength): result;
    }
};
