import { ExtensionSetupBase } from '@vs/liveshare-core';

import { builder as InviteContactCommandBuilder } from './InviteContactCommand';
import { builder as InviteContactByEmailCommandBuilder } from './InviteContactByEmailCommand';
import { builder as InviteNoContactByEmailCommandBuilder } from './InviteNoContactByEmailCommand';
import { builder as RemoveRecentContactCommandBuilder } from './RemoveRecentContactCommand';
import { builder as InviteAvailableContactsCommandBuilder } from './InviteAvailableContactsCommand';
import { builder as SelectPresenceProviderCommandBuilder } from './SelectPresenceProviderCommand';
import { builder as InviteSearchContactsContactsCommandBuilder } from './InviteSearchContactsCommand';
import { builder as ChangeSelfPresenceCommandBuilder } from './ChangeSelfPresenceCommand';
import { builder as ChangeSelfPresenceStatusCommandBuilder } from './ChangeSelfPresenceStatusCommand';
import { builder as SignInPresenceCommandBuilder } from './SignInPresenceCommand';
import { builder as SignOutPresenceCommandBuilder } from './SignOutPresenceCommand';

export const registerCommands = (extensionSetup: ExtensionSetupBase): void => {
    extensionSetup.register('inviteUserJoin', InviteContactCommandBuilder);
    extensionSetup.register('inviteUserJoinByEmail', InviteContactByEmailCommandBuilder);
    extensionSetup.register('inviteNoUserJoinByEmail', InviteNoContactByEmailCommandBuilder);
    extensionSetup.register('removeRecentContact', RemoveRecentContactCommandBuilder);
    extensionSetup.register('inviteAvailableContacts', InviteAvailableContactsCommandBuilder);
    extensionSetup.register('selectPresenceProvider', SelectPresenceProviderCommandBuilder);
    extensionSetup.register('inviteSearchContacts', InviteSearchContactsContactsCommandBuilder);

    extensionSetup.register('changeSelfPresenceFromAvailable', ChangeSelfPresenceCommandBuilder);
    extensionSetup.register('changeSelfPresenceFromAway', ChangeSelfPresenceCommandBuilder);
    extensionSetup.register('changeSelfPresenceFromBusy', ChangeSelfPresenceCommandBuilder);
    extensionSetup.register('changeSelfPresenceFromDoNotDisturb', ChangeSelfPresenceCommandBuilder);

    extensionSetup.register('signInPresence', SignInPresenceCommandBuilder);
    extensionSetup.register('signOutPresence', SignOutPresenceCommandBuilder);

    extensionSetup.register('changePresenceAvailable', ChangeSelfPresenceStatusCommandBuilder);
    extensionSetup.register('changePresenceBusy', ChangeSelfPresenceStatusCommandBuilder);
    extensionSetup.register('changePresenceDoNotDisturb', ChangeSelfPresenceStatusCommandBuilder);
    extensionSetup.register('changePresenceAway', ChangeSelfPresenceStatusCommandBuilder);
    extensionSetup.register('changePresenceInvisible', ChangeSelfPresenceStatusCommandBuilder);
};