import * as vscode from 'vscode';

import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '../tracing/traceSource';

import { ICommand } from '../types/ICommand';
import { ICommandRegistryProvider } from '../types/ICommandRegistryProvider';
import { CommandContextBuilder } from './CommandContextBuilder';
import { TelemetryEventNames } from '../telemetry/telemetryStrings';
import { Telemetry, FaultType as TelemetryFaultType } from '@vs/vso-telemetry';

/**
 * Provider that ensures we register and execute commands safely
 * within VS Code.
 */
export class CommandRegistryProvider implements ICommandRegistryProvider {
    private readonly disposables: { [key: string]: vscode.Disposable } = {};
    private readonly trace: TraceSource = traceSource.withName('CommandRegistry');

    // tslint:disable-next-line: variable-name
    public register(commandText: string, CommandClass: any, commandOptions: any = {}): void {
        const commandInstance = new CommandClass() as ICommand<boolean>;

        // Defer import of 'vscode' package.
        const registerCommand: typeof vscode.commands.registerCommand = require('vscode').commands
            .registerCommand;
        this.disposables[commandText] = registerCommand(commandText, async (options: any = {}) => {
            try {
                const context = CommandContextBuilder.build(commandInstance, commandText);
                const invocationOptions = { ...commandOptions, ...options };

                return await commandInstance.invoke(invocationOptions, context);
            } catch (error) {
                if (error && !error.hasRecorded) {
                    const errorMessage = `Unhandled exception (command): ${error.message}`;
                    this.trace.error(errorMessage);
                    Telemetry.sendFault(
                        TelemetryEventNames.UNHANDLED_COMMAND_ERROR_FAULT,
                        TelemetryFaultType.Error,
                        errorMessage,
                        error,
                    );
                }
            }
        });
    }

    public dispose(commandString: string): void {
        const disposable = this.disposables[commandString];
        if (disposable && disposable.dispose) {
            disposable.dispose();
        }
    }

    public disposeAll(): void {
        for (const key in this.disposables) {
            if (key) {
                this.dispose(key);
            }
        }
    }
}

export const commandRegistry = new CommandRegistryProvider();
