import * as vscode from 'vscode';

import { LogLevel } from "../interfaces/LogLevel";
import { TraceFormat } from "../TraceFormat";
import { TraceListener } from "../TraceListener";


export class OutputTraceListener extends TraceListener {
    private channel: vscode.OutputChannel | null = null;
    public channelName: string;

    public constructor(outputChannelName: string, private readonly includeTimestamp?: boolean) {
        super();
        this.channelName = outputChannelName;
    }

    public writeTo(line: string): void {
        if (this.channel != null) {
            this.channel.appendLine(line);
        }
    }

    protected writeEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void {
        const line = TraceFormat.formatEvent(this.includeTimestamp ? new Date() : null, source, logLevel, id, message, ...args);
        this.writeTo(line);
    }

    public addOutputChannel(focus: boolean): void {
        if (this.channel != null) {
            return;
        }

        // Defer import of 'vscode' package.
        const vscodeModule = require('vscode') as typeof vscode;

        this.channel = vscodeModule.window.createOutputChannel(this.channelName);
        if (focus) {
            // Keep OutputChannel in focus
            this.channel.show(true);
        }
    }

    public removeOutputChannel(): void {
        if (this.channel == null) {
            return;
        }
        this.channel.clear();
        this.channel.dispose();
        this.channel = null;
    }
};
