import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { Uri } from 'vscode';
import { LiveShareCommandBase } from './LiveShareCommandBase';
import { IDependencies } from '../contracts/IDependencies';
import { ICommandContext } from '@vs/vscode-command-framework';
import { telemetryCommandDecorator } from '../decorators/TelemetryCommandDecorator';
import { telemetryStatusCommandDecorator } from '../decorators/TelemetryStatusCommandDecorator';
import { errorNotificationCommandDecorator } from '../decorators/ErrorNotificationCommandDecorator';
import { cancellationDecorator } from '../decorators/CancellationDecorator';
import { authenticationCommandDecorator, IAuthenticationDecoratorOptions } from '../decorators/AuthenticationCommandDecorator';
import { TelemetryPropertyNames, TelemetryEventNames } from '../telemetry/TelemetryStrings';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { SessionAction } from '../SessionTypes';
import { showReusableLink } from '../utils/showReusableLink';
import { IWorkspaceAccessControlManager } from '../contracts/IWorkspaceAccessControlManager';
import { localize } from '../localize';

export function builder(dependencies: IDependencies): CreateSessionCommand {
    return new CreateSessionCommand(
        dependencies.workspaceService(),
        dependencies.workspaceAccessControlManager(),
    );
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.Create
};

/**
 * Create session `command` that creates a persistent session
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Creating a Reusable Session link', TelemetryEventNames.CREATE_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.CREATE_WORKSPACE, TelemetryEventNames.CREATE_FAULT, 'Create', 1)
@telemetryStatusCommandDecorator()
@authenticationCommandDecorator(authOptions)
export class CreateSessionCommand extends LiveShareCommandBase {

    constructor(
        private readonly workspaceService: vsls.WorkspaceService,
        private readonly workspaceAccessControlManager: IWorkspaceAccessControlManager,
    ) {
        super();
    }

    public async invoke(options: any, context: ICommandContext): Promise<Uri> {
        const { cancellationTokenSource } = context;
      
        try {
            let workspaceSessionInfo;

            await vscode.window.withProgress(
                { location: vscode.ProgressLocation.Notification,
                    title: localize('CreateLinkProgress') }, async () => {
                    workspaceSessionInfo = await this.workspaceService.createPersistentWorkspaceAsync(null, true, cancellationTokenSource && cancellationTokenSource.token);
                });

            workspaceSessionInfoTracker.workspaceSessionInfo = workspaceSessionInfo;
            await showReusableLink(this.workspaceAccessControlManager, workspaceSessionInfo, context);

            context.telemetryEvent.addProperty(TelemetryPropertyNames.CREATE_WORKSPACE, true);
        } catch (e) {
            context.trace.error(`Failed to create a Reusable Session link. ${e}`);
            throw new Error(localize('CannotCreatePersistentSession'));
        }
        return;
    }
}
