import * as sb from '@microsoft/servicehub-framework';
import CT from 'cancellationtoken';
import { IGuestChannelService } from '@vs/liveshare-api-contracts';
import { Settings, workspaceSessionInfoTracker } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { IRpcClientProxy, ServiceInfo, RpcProxy } from '@vs/vso-rpc';
import { ILogger } from '@vs/vso-logging';
import * as vscode from 'vscode';

const LIVESHARE_CHANNEL_NAME = 'IServiceBroker-3';
const PROTOCOL_VERSION = '3.0';

/**
 * Initializes a service broker from a shared pipe
 * @param rpcClient The IRpcClientPRoxy instance to use when setting up an RPC connection.
 * @param guestChannelService The channel service to use in requesting a stream
 * @param trace The logger to use.
 * @param cancellationToken The cancellation token.
 * @returns An instance of RemoteServiceBroker, or `undefined` if the connection could not be established.
 */
export async function getRemoteServiceBrokerFromHost(rpcClientProxy: IRpcClientProxy, guestChannelService: IGuestChannelService, trace: ILogger, cancellationToken?: vscode.CancellationToken): Promise<sb.IServiceBroker | null> {
    if (!Settings.isInsidersFeatureSet) {
        return null;
    }

    const isNexusClient = false; // Nexus connections aren't a thing in VS Code.
    let isOwner = false;
    if (workspaceSessionInfoTracker?.workspaceSessionInfo?.sessions) {
        for (const sessionNumber in workspaceSessionInfoTracker.workspaceSessionInfo.sessions) {
            if (workspaceSessionInfoTracker.workspaceSessionInfo.sessions.hasOwnProperty(sessionNumber)) {
                const sessionNumberInt = parseInt(sessionNumber, 10);
                if (workspaceSessionInfoTracker.workspaceSessionInfo.sessionNumber === sessionNumberInt) {
                    isOwner = workspaceSessionInfoTracker.workspaceSessionInfo.sessions[sessionNumberInt].isOwner;
                    break;
                }
            }
        }
    }

    const serviceSource =
        isNexusClient ? ServiceSource.NexusServer :
            isOwner ? ServiceSource.TrustedServer : ServiceSource.UntrustedServer;

    const serviceProxy = RpcProxy.create(SERVICE_BROKER_RPC_HANDSHAKE_SERVICE, rpcClientProxy, trace.withName(vsls.TraceSources.RemoteServiceBroker));
    const clientToHostData: ClientToHostHandshake = { protocolVersion: PROTOCOL_VERSION, availableServices: [] };
    const hostToClientData = await serviceProxy.checkCompatibilityAsync(clientToHostData, cancellationToken);
    if (!hostToClientData) {
        trace.warning('The host is not sharing its remote service broker.');
        return null;
    }

    if (!hostToClientData.protocolVersion) {
        trace.error('The host did not disclose its protocol version.');
        return null;
    }

    const remoteVersionComponents = hostToClientData.protocolVersion.split('.');
    const localVersionComponents = PROTOCOL_VERSION.split('.');
    if (remoteVersionComponents[0] !== localVersionComponents[0]) {
        trace.error(`Incompatible service broker on host. Local version ${PROTOCOL_VERSION}, remote version ${hostToClientData.protocolVersion}.`);
        return null;
    }

    trace.info('Service broker on host is active and compatible. Connecting...');

    const channel = await guestChannelService.connectToChannel(LIVESHARE_CHANNEL_NAME, cancellationToken);
    if (!channel) {
        return null;
    }

    let ctRegistration: vscode.Disposable | undefined;
    try {
        const cts = CT.create();
        ctRegistration = cancellationToken?.onCancellationRequested(e => cts.cancel(e));
        const remoteServiceBroker = await sb.RemoteServiceBroker.connectToMultiplexingDuplex(channel, { protocolMajorVersion: 2 }, cts.token);

        remoteServiceBroker.defaultClientCulture = vscode.env.language;
        remoteServiceBroker.defaultClientUICulture = vscode.env.language;

        return remoteServiceBroker;
    } catch (err) {
        channel.end(err);
        throw err;
    } finally {
        ctRegistration?.dispose();
    }
}

const SERVICE_BROKER_RPC_HANDSHAKE_SERVICE: ServiceInfo<IServiceBrokerRpcHandshake> = {
    name: 'ServiceBrokerHost',
    methods: ['checkCompatibility'],
    events: [],
};

interface IServiceBrokerRpcHandshake {
    /**
     * Exchanges data between Live Share guest and host to establish compatibility.
     * @param data Data from the client.
     * @param cancellationToken A cancellation token.
     * @returns Data from the server, or null if the server has disabled brokered service integration.
     */
    checkCompatibilityAsync(data: ClientToHostHandshake, cancellationToken?: vscode.CancellationToken): Promise<HostToClientHandshake | undefined>;
}

/**
 * Names the various sources for brokered services.
 */
enum ServiceSource {
    /**
     * The services are proffered from within this process.
     */
    SameProcess,
    /**
     * The services are proffered by local (and trusted) sources, outside this process.
     */
    OtherProcessOnSameMachine,
    /**
     * The services are proffered by a remote server (e.g. Live Share host) that is under the control of the same user account as the local one (the guest who is joining the session).
     */
    TrustedServer,
    /**
     * The services are proffered by a remote server (e.g. Live Share host) that is NOT under the control of the same user account as the local one (the guest who is joining the session).
     */
    UntrustedServer,
    /**
     * The services are proffered by a remote server that is under the control of the same user account as the local one
     */
    NexusServer,
    /**
     * The services are proffered by a remote <em>client</em> under the control of the same user account as the local one.
     */
    NexusClient,
}

interface ClientToHostHandshake {
    /**
     * The protocol version used.
     */
    protocolVersion?: string;

    /**
     * Data about the services available.
     */
    availableServices?: sb.ServiceMoniker[];
}

interface HostToClientHandshake {
    /**
     * The protocol version used.
     */
    protocolVersion?: string;

    /**
     * Data about the services available.
     */
    availableServices?: sb.ServiceMoniker[];

    /**
     * Version information about the host.
     */
    versionInformation?: { visualStudioVersion?: string, liveShareVersion?: string };
}
