import * as vscode from 'vscode';
import { IDependencies } from "../contracts/IDependencies";
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { ClipboardUtil } from '../utils/ClipboardUtil';
import { sessionStateTracker } from '../SessionStateTracker';
import { SessionState } from '../SessionTypes';
import { vsls } from '@vs/vsls-contracts';
import { traceSource } from '@vs/vscode-command-framework';
import { SettingKeys } from '../SettingKeys';
import { Settings } from '../Settings';
import { CommandContext } from '../CommandConstants';
import { showWelcomePage, WelcomePageSource } from '../welcomePage/welcomePageUtil';
interface ParticipantActionPayload {
    [key: string]: any;
    sessionId: number;
};

export class Commands {
    constructor(private readonly coreDependencies: IDependencies) {
    }

    public initialize() {
        this.register(ExtensionUtil.context);
        this.initializeEvents();
        if (Settings.get<boolean>(SettingKeys.diagnosticLogging)) {
            ExtensionUtil.setCommandContext(CommandContext.logsEnabled, true);
        } else {
            ExtensionUtil.setCommandContext(CommandContext.logsEnabled, false);
        }
    }

    protected get workspaceUserService() {
        return this.coreDependencies.workspaceUserService();
    }

    protected get sessionContext() {
        return this.coreDependencies.sessionContext();
    }

    protected get statusBarController() {
        return this.coreDependencies.statusBarController();
    }

    protected get workspaceAccessControlManager() {
        return this.coreDependencies.workspaceAccessControlManager();
    }

    protected register(context: vscode.ExtensionContext): void {
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.collaboration.link.copy', this.copyCollaborationLinkCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.collaboration.link.copyFromFileTreeExplorer', this.copyCollaborationLinkCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.collaboration.link.copyFromActivityBar', this.copyCollaborationLinkCommandHandler, this));  
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.removeParticipant', this.removeUserCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.removeParticipantFromFileTreeExplorer', this.removeUserCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.removeParticipantFromActivityBar', this.removeUserCommandHandler, this));

        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.blockParticipant', this.blockUserCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.blockParticipantFromFileTreeExplorer', this.blockUserCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.blockParticipantFromActivityBar', this.blockUserCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.help', () => showWelcomePage(WelcomePageSource.Help)));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.openInVSCode', this.openInVSCodeCommandHandler, this));
        context.subscriptions.push(ExtensionUtil.registerCommand('liveshare.openInVS', this.openInVSCommandHandler, this));
    }
  
    protected initializeEvents() {
        this.workspaceUserService.onWorkspaceSessionChanged(this.onWorkspaceSessionChanged, this);
    }

    private async onWorkspaceSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs): Promise<void> {
        try {
            // Notify listeners of the session changing, *before* we go through the accept/reject flow
            // to ensure that the various internal states for displaying information have the latest
            // info. A primary example of this is that in the Notify mode, we shouldn't wait to notify
            // others that someone has joined -- this means all the user info etc is correct.
            // In the approval mode, this doesn't cause issues, because the collaborator interactions
            // are driven by the by co-editing counts, not just the simple join message.
    
            // Note: CollaboratorManager needs to be updated first because the status bar queries it to know the updated
            // list of co-editors.
            if (this.sessionContext.collaboratorManager) {
                this.sessionContext.collaboratorManager.onWorkspaceSessionChanged(e);
            }
    
            if (this.statusBarController) {
                this.statusBarController.onWorkspaceSessionChanged(e);
            }
    
            if (this.sessionContext.coeditingClient) {
                this.sessionContext.coeditingClient.onWorkspaceSessionChanged(e);
            }
    
            if (sessionStateTracker.State === SessionState.Shared) {
                await this.workspaceAccessControlManager.onWorkspaceSessionChanged(e);
            }
        } catch (e) {
            traceSource.error('onWorkspaceSessionChanged error', e);
        }
    }

    private getWorkspaceSessionInfo = (): vsls.WorkspaceSessionInfo | undefined => {
        const sessionContext = this.coreDependencies.sessionContext();

        if (!sessionContext) {
            return undefined;
        }

        return workspaceSessionInfoTracker.workspaceSessionInfo;
    }

    private async copyCollaborationLinkCommandHandler() {
        const workspaceSessionInfo = this.getWorkspaceSessionInfo();
        if (!workspaceSessionInfo) {
            return;
        }

        const currentLink = workspaceSessionInfo.joinUri;
        const copied = await new ClipboardUtil().copyToClipboardAsync(currentLink);
        if (copied) {
            await vscode.window.showInformationMessage('Invite link copied to clipboard! Send it to anyone you trust.');
        } else {
            await vscode.window.showInputBox({
                prompt: 'Copy Live Share invitation link',
                value: currentLink,
                ignoreFocusOut: true,
            });
        }
    }

    private removeUserCommandHandler = async (item: ParticipantActionPayload) => {
        if (!item || (item.sessionId === undefined)) {
            return;
        }

        const { sessionId } = item;
        if (!sessionId || sessionId < 1) {
            return;
        }

        await this.workspaceUserService.removeUserAsync(sessionId, vsls.WorkspaceDisconnectedReason.UserRemoved);
    }

    private blockUserCommandHandler = async (item: ParticipantActionPayload) => {
        if (!item || (item.sessionId === undefined)) {
            return;
        }

        const { sessionId } = item;
        if (!sessionId || sessionId < 1) {
            return;
        }

        await this.workspaceUserService.removeUserAsync(sessionId, vsls.WorkspaceDisconnectedReason.UserBlocked);
    }

    private openInVSCodeCommandHandler = () => {
        const workspaceSessionInfo = this.getWorkspaceSessionInfo();
        if (!workspaceSessionInfo) {
            return;
        }

        vscode.env.openExternal(vscode.Uri.parse(`vscode://ms-vsliveshare.vsliveshare/join?vslsLink=${encodeURI(workspaceSessionInfo.joinUri)}`));
        return Promise.resolve();
    };

    private openInVSCommandHandler = () => {
        const workspaceSessionInfo = this.getWorkspaceSessionInfo();
        if (!workspaceSessionInfo) {
            return;
        }

        vscode.env.openExternal(vscode.Uri.parse(`vsls:?action=join&workspaceId=${workspaceSessionInfo.id}`));
        return Promise.resolve();
    };

}
