import { VSCODE_SERVER_PORT_NAME } from '../constants';

/**
 * Function to construct vscode server session name.
 */
export const getVSCodeServerSessionName = (clientId?: string): string => {
    if (!clientId) {
        return VSCODE_SERVER_PORT_NAME;
    }

    return `${VSCODE_SERVER_PORT_NAME}_${clientId}`;
};
