import { checkDebugging } from '../../utils/checkDebugging';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';

import { CoauthoringTelemetry } from '../../telemetry/CoauthoringTelemetry';
import { vsls } from '@vs/vsls-contracts';
import { showDiagnosticErrorMessage } from '../../utils/notificationUtil';

export function assert(condition: boolean, message: string, telemetrySafeMessage?: string, fileName?: string) {
    if (!condition) {
        if (checkDebugging()) {
            // When getting an assert, and we've got a debugger attached, give
            // the engineer a chance to catch it at the point it happens
            // tslint:disable-next-line:no-debugger
            debugger;
        }
        traceSource.withName(vsls.TraceSources.ClientCoEditing).error(`Assertion Violation: ${message}`);
        CoauthoringTelemetry.ReportFailedAssertion(telemetrySafeMessage || message, fileName);
        showDiagnosticErrorMessage(`Coediting Assertion Violation: ${message}`);
    }
}

function makeColorizeFunc(startEscape: string): (str: string) => string {
    return (str: string): string => {
        return startEscape + str + '\x1b[0m';
    };
}

export namespace colorize {
    export const black = makeColorizeFunc('\x1b[30m');
    export const red = makeColorizeFunc('\x1b[31m');
    export const green = makeColorizeFunc('\x1b[32m');
    export const yellow = makeColorizeFunc('\x1b[33m');
    export const blue = makeColorizeFunc('\x1b[34m');
    export const magenta = makeColorizeFunc('\x1b[35m');
    export const cyan = makeColorizeFunc('\x1b[36m');
    export const white = makeColorizeFunc('\x1b[37m');
}

export class LoggerImpl {

    private indentValue = 0;

    public indent(): void {
        this.indentValue++;
    }

    public reset(): void {
        this.indentValue = 0;
    }

    public unindent(): void {
        this.indentValue--;
    }

    public logTrace(trace: TraceSource, ...str: string[]): void {
        this.logInternal(trace.verbose.bind(trace), ...str);
    }

    public log(...str: string[]): void {
        this.logInternal(console.log, ...str);
    }

    private logInternal(logFunc: (msg: string) => void, ...str: string[]): void {
        let result = '';
        for (let i = 0; i < this.indentValue; i++) {
            result += '|   ';
        }
        logFunc(result + str.join(''));
    }
}

export const logger = new LoggerImpl();
