import * as lockFile from 'lockfile';
import { ILogger, TraceFormat } from '@vs/vso-logging';

export async function lockAgent(path: string, lockSuccessCallback:() => Promise<void>, logger: ILogger) {

    const lockOptions: lockFile.Options = {
        stale: 60 * 1000, // 1 min
        retries: 60,
        retryWait: 1000,
    };

    const pathLock = path + '.lock';

    // Check if the file is already locked
    const isLocked = await new Promise((resolve) => {
        lockFile.check(pathLock, lockOptions, (err, locked) => resolve(!!locked));
    });

    if (isLocked) {
        logger.verbose('Agent is being started by another vscode instance. Waiting for completion...');
    }

    logger.verbose(`Agent lock on:${TraceFormat.formatPath(pathLock)}`);
    // Acquire a new lock
    await new Promise((resolve, reject) =>
        lockFile.lock(pathLock, lockOptions, (err) => {
            if (err) {
                logger.error('Failed to lock the agent');
                reject(err);
            } else {
                resolve(true);
            }
        }));

    try {
        if (!isLocked) {
            await lockSuccessCallback();
             logger.verbose(`Finished agent startup...`);
        }
    } finally {
        // No need to wait for unlocking to finish
        lockFile.unlock(pathLock, () => {
            logger.verbose(`Agent unlocked`);
        });
    }
}