let editorIds = new WeakMap();

function getEditorId(editor: vscode.TextEditor | vscode.NotebookEditor): string {
    // In order to "break" follow through user actions, we must be able to accurately identify and compare text editors when they move across viewcolumns.
    // Editors are unique and can be used for identification. 
    if (!editorIds.has(editor)) {
        editorIds.set(editor, uuid());
    }
    return editorIds.get(editor);
}

// This is a helper implementation of undoing the buffer until it reaches desired
// buffer content. Of note, this is based on the assumption that the remote edits
// are actually creating a 'undo stop' in the Code undo stack. A the time of
// authoring, this was true -- by observation & code inspection.
// Also, of note, that if the window looses focus, and there is no focused
// editor when this happens, nothing changes, and we'll keep calling the undo
// command. There is no indication that is did or didn't perform an operation,
// so this is very much a hope that something happens.
// Additionally, of note, VS Code's undo implementation is pretty much fire-and
// -forget; it does it irrespective of anything to undo.
function repeatCommandUntilContentMatches(command: string, checkpoint: string, doc: vscode.TextDocument, trace: TraceSource, onComplete?: () => void,): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        const docVersionBeforeCommand = doc.version;
        vscode.commands.executeCommand(`default:${command}`).then(() => {
            let documentContent = doc.getText();
            let docVersionAfterCommand = doc.version;
            // If content doesn't match, clearly got more to go. However if the
            // document version didn't change, nothing really got undo, so there
            // is no point in continuing.
            if (documentContent !== checkpoint && (docVersionBeforeCommand !== docVersionAfterCommand)) {
                setImmediate(() => {
                    repeatCommandUntilContentMatches(command, checkpoint, doc, trace, onComplete || resolve);
                });
                return;
            }

            if (docVersionBeforeCommand === docVersionAfterCommand) {
                trace.verbose('Undo: Performing undo didn\'t actually make changes');
            }

            if (onComplete) {
                onComplete();
            } else {
                resolve();
            }
        });
    });
}

const droppedMessageTimeout = 5000; // 5s

function checkForDroppedMessage(expectedId: number, actualId: number, droppedIds: Set<number>, idType: string) {
    droppedIds.delete(actualId);
    if (actualId !== expectedId) {
        droppedIds.add(expectedId);
        setTimeout(() => {
            if (droppedIds.has(expectedId)) {
                droppedIds.delete(expectedId);
                CoauthoringTelemetry.ReportDroppedMessage(expectedId, actualId, idType, true);
            }
        }, droppedMessageTimeout);
        CoauthoringTelemetry.ReportDroppedMessage(expectedId, actualId, idType, false);
        showDiagnosticErrorMessage(`Dropped coediting message. Expected ID: ${expectedId}. Actual ID: ${actualId}. ID Type: ${idType}.`);
    }
}

async function asyncThrowableWithRetry<T>(fn: () => Thenable<T>, retries = 3): Promise<T> {
    for (let i = 0; i < retries - 1; i++) {
        try {
            const result = await fn();
            return result;
        } catch { }
    }
    return fn();
}

