    private onDidChangeVisibleRanges() {
        const visibleRanges: vsls.EditorVisibleRanges[] = [];
        for (let editor of vscode.window.visibleTextEditors) {
            const relativePath = this.pathManager.localPathToRelativePath(editor.document.uri);
            const fileClient = this.getSharedFileClient(relativePath);
            if (fileClient) {
                visibleRanges.push({ editorId: getEditorId(editor), fileVersion: fileClient.version, ...fileClient.getEditorVisibleRanges(editor.visibleRanges) });
            } else { // File could be just opened
                visibleRanges.push({ editorId: getEditorId(editor), fileVersion: -1, fileName: relativePath });
            }

        }
        const visibleRangesChangeMsg = MessageFactory.VisibleRangesChangeMessage(this.clientID, visibleRanges);
        this.postMessage(visibleRangesChangeMsg);
    }

    private _addPinnedInfoForEditor(editor: vscode.TextEditor | vscode.NotebookEditor, editors: IMap<EditorColumnInformation>, pinToClientId: number = -1): void {
        const id = getEditorId(editor);
        const previousData = this.currentVisibleEditors[id];
        let pinnedClient = (previousData) ? previousData.pinnedClient : -1;

        // If we were supplied a client that we're explicitly pinning this editor to
        // then override whatever else we've found with that client.
        if (pinToClientId > -1) {
            pinnedClient = pinToClientId;
        }

        const newEditorInfo: EditorColumnInformation = {
            pinnedClient: pinnedClient,
            column: editor.viewColumn || 1, // Notebook editors do not have an assigned viewColumn
            id: id,
        };

        editors[getEditorId(editor)] = newEditorInfo;
    }

    private getEditorInfoForClient(clientId: number): EditorColumnInformation | null {
        let matchingEditorInfo: EditorColumnInformation | null = null;
        Object.keys(this.currentVisibleEditors).some((key) => {
            const editorInfo = this.currentVisibleEditors[key];
            if (editorInfo.pinnedClient !== clientId) {
                return false;
            }

            matchingEditorInfo = editorInfo;
            return true;
        });

        return matchingEditorInfo;
    }

    private getColumnForPinnedClient(clientId: number): vscode.ViewColumn | undefined {
        const editorInfo = this.getEditorInfoForClient(clientId);
        if (editorInfo == null) {
            return vscode.ViewColumn.Active;
        }

        return editorInfo.column;
    }

    public getClientIdIfEditorIsPinned(editor: vscode.TextEditor): number {
        if (!editor) {
            return -1;
        }

        const editorId = getEditorId(editor);
        const columnInformation = this.currentVisibleEditors[editorId];
        if (!columnInformation) {
            return -1;
        }

        return columnInformation.pinnedClient;
    }

    private captureVisibleEditorInformation(editors: (vscode.TextEditor | vscode.NotebookEditor)[]): void {
        // Calculate new editors information -- this can just be the list of currently
        // visible documents
        let newVisibleEditors: IMap<EditorColumnInformation> = {};
        editors.forEach((editor) => this._addPinnedInfoForEditor(editor, newVisibleEditors));
        this.currentVisibleEditors = newVisibleEditors;

        this.updatePinIconFromActiveEditor();
    }

    public getClientVisibleRanges(clientId: number) {
        return this.clientVisibileRanges[clientId];
    }

    private async onDidOpenTextDocument(e: vscode.TextDocument): Promise<void> {
        const filename = this.pathManager.localPathToRelativePath(e.uri);
        this.coEditingTrace.verbose(`onDidOpenTextDocument ${formatPath(filename)}`);

        if (e.isUntitled && this.isHost) {
            this.postUntitledFileOpenedMessageToOtherParticipants(filename);
        }
    }

    private async onDidCloseTextDocument(e: vscode.TextDocument): Promise<void> {
        let filename = this.pathManager.localPathToRelativePath(e.uri);
        this.coEditingTrace.verbose(`onDidCloseTextDocument ${formatPath(filename)}`);
        let sharedClient = this.getSharedFileClient(filename);
        if (!sharedClient) {
            // We don't know about this file, so we're not going to do anything
            return;
        }

        // The document definitely closed, so the undo state is lost. So always
        // clear it, even if it were a rename.
        sharedClient.clearUndoStateDueToDocumentClosing();

        let newName = this.getNewNameFromRename(sharedClient.fileName);
        // First check to see if it's in the rename list, and what its new name is
        if (newName) {
            this.renameSharedFileClient(sharedClient, newName);
            return;
        }

        if (e.isUntitled && this.isHost) {
            this.postUntitledFileClosedMessageToOtherParticipants(filename);
            const localPath = this.pathManager.getFromVslsPathsToLocalPaths(filename);
            if (localPath) {
                this.pathManager.deleteFromLocalPathsToVslsPaths(localPath);
                this.pathManager.deleteFromVslsPathsToLocalPaths(filename);
            }
        }

        // For guests, we've already handled the delete in the file service
        // handler. Additionally, if the file still exists here, we don't want
        // to clean it up, since it could come back.
        if (this.isGuest || (await fileAccess.existsAsync(e.fileName))) {
            return;
        }
    }

    private getNewNameFromRename(filename: string): string | null {
        const rename = this.pendingRenames.filter((renameInformation) => renameInformation.oldName === filename)[0];
        if (!rename) {
            return null;
        }

        // Now we've got a rename, we need to remove it from the list
        const pendingItemIndex = this.pendingRenames.indexOf(rename);
        this.pendingRenames.splice(pendingItemIndex, 1);

        return rename.newName;
    }

    private saveDocument(e: vscode.NotebookDocument | vscode.TextDocument, postSave: (fileName: string) => void): void {
        if (!e) {
            return;
        }

        const fileName = this.pathManager.localPathToRelativePath(e.uri);
        if (!fileName) {
            return;
        }

        if (this.fileSaveRequestsPaused) {
            return;
        }

        this.vsCodeEventTrace.info(`onDidSaveDocument (${formatPath(fileName)})`);

        if (this.isHost) {
            const sharedFile = this.getSharedFileClient(fileName);
            if (sharedFile) {
                sharedFile.takeSnapshot();
                sharedFile.updateDirtyState(e.isDirty);
            }
        }

        const lowercaseFileName = fileName.toLowerCase();
        if (this.savingFiles[lowercaseFileName]) {
            // This save was initiated by a saveFile message
            delete this.savingFiles[lowercaseFileName];
            return;
        }

        this.vsCodeEventTrace.info(`onDidSaveDocument (${formatPath(fileName)})`);
        postSave(fileName);

        if (this.activeFileName && this.activeFileName.startsWith(this.untitledPrefix) && this.isHost) {
            new TelemetryEvent(CoauthoringTelemetryEvents.SAVE_UNTITLED_FILE).send();
        }
    }

    private _onDidSaveNotebookDocument(e: vscode.NotebookDocument): void {
        this.saveDocument(e, (fileName) => this.postNotebookSaveMessageToOtherParticipants(fileName));
    }

