    private updateNametagVisibilitySetting = () => {
        // Update nameTagVisibility value
        const nameTagSetting = Settings.get<string>(SettingKeys.nameTagVisibility);
        const nameTagSettingValue = (<any>NameTagVisibility)[nameTagSetting || ''];
        this.nameTagVisibility = nameTagSettingValue || NameTagVisibility.Activity;
        // Update decorators
        Object.keys(this.clientDecoratorManagers).forEach((clientId) => {
            if (!this.clientDecoratorManagers[clientId]) {
                return;
            }
            this.clientDecoratorManagers[clientId].nameTagVisibility = this.nameTagVisibility;
            this.clientDecoratorManagers[clientId].updateDecorators();
        });
    }

