import * as vscode from 'vscode';

import { ICommand } from '../abstractions/ICommand';
import { ICommandContext } from '@vs/vscode-command-framework';
import { IDependencies } from '../contracts/IDependencies';
import { sessionStateTracker } from '../SessionStateTracker';
import { SessionState } from '../SessionTypes';
import { userAuthStateTracker } from '../UserAuthStateTracker';
import { ExtensionUtil } from '../utils/ExtensionUtil';

export function builder(dependencies: IDependencies): SignOutCommand {
    return new SignOutCommand(dependencies);
}

class SignOutCommand implements ICommand<void> {
    public constructor(private dependencies: IDependencies) {

    }
    public async invoke(options: any, context: ICommandContext): Promise<void> {
        if (sessionStateTracker.State === SessionState.Joined || sessionStateTracker.State === SessionState.Shared) {
            return;
        }

        if (!userAuthStateTracker.IsSignedIn) {
            await vscode.window.showInformationMessage('Not signed in.');
            return;
        }

        if (this.dependencies.sessionContext().isStartingCollaboration) {
            await ExtensionUtil.showErrorAsync('Cannot sign out while collaboration is starting.');
            return;
        }

        return ExtensionUtil.runWithProgress(
            () => this.dependencies.authenticationProvider().signOut(),
            { title: 'Signing Out' });
    }
}