
import * as vscode from 'vscode';
import { EventEmitter } from 'events';

import { vsls } from '@vs/vsls-contracts';
import { CoauthoringMessage } from './common/coauthoringService';
import { PositionTracker } from './client/positionTracker';
import { PresentationManager } from '../PresentationManager';

export type UpdateCoEditorPositionEventArgs = {
    clientId: number,
    fileName: string,
    document: vscode.TextDocument,
    range: vscode.Range,
    isReversed: boolean,
    kind?: vscode.TextEditorSelectionChangeKind
}

export enum UpdateCoEditorVisibleRangesReason {
    SCROLL,
    EDITORS
}

export type UpdateCoEditorVisibleRangesEventArgs = {
    clientId: number;
    reason: UpdateCoEditorVisibleRangesReason;
    fileName?: string;
    editorId?: string;
}

export interface IClientFileData {}

export interface ICoEditingCore {
    clientID: number;
    openUntitledFiles: Map<string, vscode.FileStat>;
    uriToFileName(uri: vscode.Uri): string;
    performFileOpenHandshake(fileName: string, receivedContent: string): Promise<string | boolean>;
}

export interface EditorVisibleRanges {
    fileName: string;
    editorId: string;
    visibleRanges: vscode.Range[];
}
export type ClientVisibleRanges = EditorVisibleRanges[];

export enum ApplyEditResult {
    SUCCESSFUL,
    FAILED,
    MODIFIED
}

export interface ICoEditing extends ICoEditingCore {
    onPinEvent: EventEmitter;
    onUnpinEvent: EventEmitter;
    onFollowedEvent: EventEmitter;
    onUnfollowedEvent: EventEmitter;
    onUpdateCoEditorPositionEvent: EventEmitter;
    onUpdateCoEditorVisibleRangesEvent: EventEmitter;

    positionTracker: PositionTracker;
    initialPinIdToOwner: number;

    presentationManager: PresentationManager;

    isHost: boolean;
    isReadOnlyGuest: boolean;

    resetLanguageServicesDataStructures: () => void;
    currentServerVersion: number;

    currentHighestLocalTextChange: number;
    textChangeHistory: vsls.TextChangeMessage[];
    hasUnacknowledgedTextChanges: boolean;

    removeOldUnacknowledgedTextChanges: () => void;
    postMessage: (message: CoauthoringMessage) => void;
    dispose: () => void;

    getClientIdForTextDocumentChangeEvent: (e: vscode.TextDocumentChangeEvent) => Promise<number | undefined>;

    getClientIdIfEditorIsPinned: (editor: vscode.TextEditor) => number;

    postSaveMessageToOtherParticipants: (fileName: string) => void;
    postUntitledFileOpenedMessageToOtherParticipants: (fileName: string) => void;
    postUntitledFileClosedMessageToOtherParticipants: (fileName: string) => void;
    pauseProcessingFileSaveRequests: () => void;
    resumeProcessingFileSaveRequests: () => void;

    updateCoEditorPosition: (message: vsls.SelectionChangeMessage) => Promise<void>;
    updateCoEditorScrollPosition: (message: vsls.LayoutScrollMessage) => void;
    getClientVisibleRanges: (clientId: number) => ClientVisibleRanges;
    jumpTo: (clientId: number, viewColumn?: vscode.ViewColumn, explicit?: boolean) => void;
    pin: (editor: vscode.TextEditor, userId: number, split?: boolean) => void;
    getUsersBeingFollowed: () => { [key: string]: boolean; };
    getUsersFollowingYou: () => Map<number, boolean>;
    unpinByEditor: (editor: vscode.TextEditor, options?: { explicit?: boolean }) => void;
    unpinByClient: (clientId: number, options?: { explicit?: boolean }) => void;
    lastKnownFileForClient: (clientId: number) => string | undefined;
    onCoEditorSwitchedFile: (handler: (sessionId: number, newFileName: string) => void) => void;
    onCoEditorsJoined: (handler: (joinerIds: number[]) => void) => void;
    onPin: (handler: (followedId: number) => void) => vscode.Disposable;
    onUnpin: (handler: (unollowedId: number) => void) => vscode.Disposable;
    onFollowed: (handler: () => void) => vscode.Disposable;
    onUnfollowed: (handler: () => void) => vscode.Disposable;
    onUpdateCoEditorPosition: (handler: (args: UpdateCoEditorPositionEventArgs) => void) => vscode.Disposable;
    onUpdateCoEditorVisibleRanges(handler: (args: UpdateCoEditorVisibleRangesEventArgs) => void): void;
    onWorkspaceSessionChanged: (e: vsls.WorkspaceSessionChangedEventArgs) => Promise<void>;
    performUserInitiatedUndo: (args: any) => Promise<void>;
    performUserInitiatedRedo: (args: any) => Promise<void>;
    isFileSynced: (filePath: string, fileHash: number) => Promise<boolean>;
    isFileSyncedForVersion: (filePath: string, fileVersion: number | undefined, serverVersionNumber: number, fileHash: number) => Promise<vsls.SyncStatus>;
    createSharedFileClient(fileName: string, initialContent: string, dirty: boolean, clientVersion?: number, languageId?: string, replace?: boolean, sendFileOpenMessage?: boolean): IClientFileData;
}
