import * as vscode from 'vscode';
import { terminalEndpointBufferFactoryType, ITerminalEndpointBuffer } from './createJoinedTerminal';
import { IChannel } from '@vs/vso-rpc';
import { IWorkspaceConnection } from '@vs/vso-workspace-core';

import { IRpcServices } from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { CancellationToken } from 'vscode-jsonrpc';
import { BaseStream } from '@vs/vs-ssh';

export function createTerminalEndpointBufferFactory(rpcServices: IRpcServices, workspaceConnection: IWorkspaceConnection): terminalEndpointBufferFactoryType {

    const factory = async (terminalInfo: vsls.TerminalInfo) => {
        const streamId = await rpcServices.streamManagerService().getStreamAsync(terminalInfo.streamName, terminalInfo.streamCondition);
        const streamingChannel = await workspaceConnection.openStreamingChannel(streamId);

        const streamChannel = new StreamChannel(streamingChannel);
        let isClosed = false;
        streamingChannel.onClosed(() => {
            isClosed = true;
        });

        const endpointBuffer: ITerminalEndpointBuffer = {
            isDisposed: () => isClosed,
            readData: async (cancelationToken: vscode.CancellationToken) => {
                const dataRead = await streamChannel.read(1024, cancelationToken);
                return dataRead ? dataRead.toString() : null;
            },
            writeData: async (data: string, cancelationToken: vscode.CancellationToken) => {
                const buf = Buffer.from(data, 'utf8');
                await streamingChannel.send(buf, cancelationToken);
            }
        };

        return endpointBuffer;
    };

    return factory;
}

class StreamChannel extends BaseStream {
    constructor(streamingChannel: IChannel) {
        super();
        streamingChannel.onDataReceived((e) => {
            this.onData(e);
        });
    }
    write(data: Buffer, cancellation?: CancellationToken | undefined): Promise<void> {
        throw new Error("Method not implemented.");
    }
    close(error?: Error | undefined, cancellation?: CancellationToken | undefined): Promise<void> {
        throw new Error("Method not implemented.");
    } 
}