import { cleanupPII } from './cleanupPII';
import { BaseError } from '../errors';

import { IErrorProperties } from '../interfaces';

/**
 * Create a plain object that represents an error.
 * Can be used to send the error to telemetry or
 * log it to the console.
 */
// TODO legomushroom - test this
export const errorToObject = (
    error: Error,
    isInternal = true,
): IErrorProperties => {
    const vscsError = error as BaseError;

    const {
        errorCode = -1,
        errorType = 'GenericError',
        message = '<no message>',
        originalErrorType = '<no original type>',
    } = vscsError;

    const stack = (isInternal)
        ? vscsError.stack
        : cleanupPII(vscsError.stack);

    return {
        errorMessage: message,
        originalErrorType,
        errorCode,
        errorType,
        stack,
    };
};
