// TODO legomushroom - cleanup?
export function propertiesToJSON(o: any) {
    if (o) {
        return JSON.stringify(o, Object.getOwnPropertyNames(o));
    }
}

export function propertiesToString(o: any) {
    return `type:${o?.constructor?.name} props:${propertiesToJSON(o)}`;
}
