import { ICommandContext } from '@vs/vscode-command-framework';
import { ContactCommandUtilities } from './ContactCommandUtilities';
import { ContactTreeExplorerItem } from '../ContactsProviderViewlet';
import { 
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
export function builder(): ICommand<boolean> {
    return new InviteNoContactByEmailCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.INVITE_NO_CONTACT_BY_EMAIL, TelemetryEventNames.INVITE_NO_CONTACT_BY_EMAIL_FAULT, 'InviteNoContactByEmail', 1)
class InviteNoContactByEmailCommand implements ICommand<boolean> {

    public async invoke(item: ContactTreeExplorerItem, context: ICommandContext): Promise<boolean> {
        return ContactCommandUtilities.inviteByEmail('','');
    }
}