import * as path from 'path';
import * as os from 'os';
import * as vscode from 'vscode';
import { fileAccess, OSPlatform } from '@vs/vso-node-utils';
import { vsls } from '@vs/vsls-contracts';
import { Disposable, IInittableDisposable, Inittable, NotificationUtil } from '@vs/vscode-command-framework';
import { LocalPortForwarder, SudoPortforwarderClient } from '@vs/port-forwarder';
import {  workspaceSessionInfoTracker, IRpcServices, dependencies as coreDependencies, constants } from '@vs/liveshare-core';
import { Privacy, ILogger } from '@vs/vso-logging';
import { createSudoPortForwardingHubClient } from '@vs/vso-workspace-client-vscode';
import { IPortFowardingServiceDependencies } from '../../IPortFowardingServiceDependencies';
import { IRpcServiceHandlerInfo } from '@vs/vso-rpc';

export function workspaceHubPortFowardingServiceFactory(dependencies: IPortFowardingServiceDependencies, logger: ILogger): vsls.PortForwardingService & IInittableDisposable & IRpcServiceHandlerInfo {
    return new WorkspaceHubPortFowardingService(dependencies, coreDependencies, logger);
}

class WorkspaceHubPortFowardingService extends Inittable(Disposable(Object)) implements vsls.PortForwardingService, IInittableDisposable, IRpcServiceHandlerInfo {
    private readonly sharingStarted = new vscode.EventEmitter<vsls.ServerSharingStartedEventArgs>();
    private readonly pipeSharingStarted = new vscode.EventEmitter<vsls.PipeSharingStartedEventArgs>();
    private readonly browseSharingStarted = new vscode.EventEmitter<vsls.ServerSharingStartedEventArgs>();
    private readonly sharingStopped = new vscode.EventEmitter<vsls.ServerSharingStoppedEventArgs>();
    private readonly pipeSharingStopped = new vscode.EventEmitter<vsls.PipeSharingStoppedEventArgs>();
    private readonly sharingChanged = new vscode.EventEmitter<vsls.ServerSharingChangedEventArgs>();

    private readonly disposeCts = new vscode.CancellationTokenSource();
    private readonly disposables: vscode.Disposable[] = [this.disposeCts];
    private readonly serverDisposables = new Map<number, vscode.Disposable>();
    private alwaysUseFreePort = false;
    private servers = new Map<number, vsls.SharedServer>();
    private pipes: vsls.SharedPipe[] = [];
    private disableSudoPortForwarder?: boolean;
    private sudoPortforwarderClient?: SudoPortforwarderClient;

    constructor (
        private readonly dependencies: IPortFowardingServiceDependencies,
        private readonly rpcServices: IRpcServices,
        private readonly logger: ILogger) {
        super();
        this.service.onSharingStarted(this.serverSharingStarted, this, this.disposables);
        this.service.onBrowseSharingStarted(this.serverBrowseSharingStarted, this, this.disposables);
        this.service.onSharingChanged(this.serverSharingChanged, this, this.disposables);
        this.service.onSharingStopped(this.serverSharingStopped, this, this.disposables);
        this.service.onPipeSharingStarted(this.serverPipeSharingStarted, this, this.disposables);
        this.service.onPipeSharingStopped(this.serverPipeSharingStopped, this, this.disposables);
    }

    private get service() { return this.rpcServices.serverSharingService(); }

    public serviceInfo = vsls.PortForwardingService;
    
    public getSharedServersAsync() { return Promise.resolve(Array.from(this.servers.values())); }
    public getSharedPipesAsync() { return Promise.resolve(this.pipes); }
    public getLastAccessTimeAsync() { return Promise.resolve(0); }

    public setDestinationPortAsync(sourcePort: number, destinationPort: number, ): Promise<vsls.SharedServer> { throw Error('Not implemented'); }

    public get onSharingStarted() { return this.sharingStarted.event; }
    public get onPipeSharingStarted() { return this.pipeSharingStarted.event; }
    public get onBrowseSharingStarted() { return this.browseSharingStarted.event; }
    public get onSharingStopped() { return this.sharingStopped.event; }
    public get onPipeSharingStopped() { return this.pipeSharingStopped.event; }
    public get onSharingChanged() { return this.sharingChanged.event; }

    protected serverSharingStarted({ server }: vsls.ServerSharingStartedEventArgs) { this.startForwarding(server); }
    protected serverBrowseSharingStarted({ server }: vsls.ServerSharingStartedEventArgs) { this.startBrowseSharing(server); }
    protected serverSharingStopped({ server }: vsls.ServerSharingStoppedEventArgs) { this.stopForwarding(server, true); }
    protected serverSharingChanged({ server: { sourcePort, sessionName, isTCPServerConnectionEstablished, hasTLSHandshakePassed, isPublic }}: vsls.ServerSharingChangedEventArgs) {
        const server = this.servers.get(sourcePort);
        if (server && (
            sessionName !== server.sessionName || 
            isTCPServerConnectionEstablished !== server.isTCPServerConnectionEstablished || 
            hasTLSHandshakePassed !== server.hasTLSHandshakePassed ||
            isPublic !== server.isPublic)) {

            this.sharingChanged.fire({ server });
        }
    }

    protected serverPipeSharingStarted({ pipe }: vsls.PipeSharingStartedEventArgs) { this.startPipeForwarding(pipe); }
    protected serverPipeSharingStopped({ pipe }: vsls.PipeSharingStoppedEventArgs) { this.stopPipeForwarding(pipe); }

    public async init() {
        if (!this.isInitialized) {
            await super.init();
            let servers: vsls.SharedServer[] = [];
            try {
                servers = await this.service.getSharedServersAsync(this.disposeCts.token);
            } catch (e) {
                // could be a web browsing hosting that does not yet support server sharing
                this.logger.error(`Failed to get remote servers`, e);
            }

            // If we can get shared servers from the server sharing RPC service, it means that workspaceSessionInfoTracker.workspaceSessionInfo is populated.
            this.alwaysUseFreePort = await WorkspaceHubPortFowardingService.isWorkspaceTracked(workspaceSessionInfoTracker.workspaceSessionInfo);

            if (servers) {
                servers.forEach(s => this.startForwarding(s, true /* fire sharing event */, true /* start browse sharing */ ));
            }

            try {
                const pipes = await this.service.getSharedPipesAsync(this.disposeCts.token);
                if (pipes) {
                    pipes.forEach(p => this.startPipeForwarding(p));
                }
            } catch {
                // Legacy host, doesn't support sharing pipes
            }
        }
    }

    private static async isWorkspaceTracked({ id, conversationId }: {id?: string, conversationId?: string}) {
        // Check if this workspace is shared on the same machine by looking for the track file in a specific location.
        // Workspace service on the host creates this file when the workspace is shared. See GetTrackFilePath() in src\Agent\SharedWorkspace.cs
        if (id && conversationId) {
            try {
                const workspaceTrackFilePath = path.join(os.tmpdir(), 'VSLS-WS', Privacy.getSha256Hash(`${id}\n${conversationId}`, 20));
                return await fileAccess.existsAsync(workspaceTrackFilePath);
            } catch {
                // Ignore file access errors and treat as if the workspace track file doesn't exist.
            }
        }
        
        return false;
    }

    public async dispose() {
        if (!this.isDisposed) {
            this.disposeCts.cancel();
            this.disposables.splice(0).forEach(d => d.dispose());
            this.serverDisposables.forEach(s => s.dispose());
            this.serverDisposables.clear();
            if (this.sudoPortforwarderClient) {
                await this.sudoPortforwarderClient.disconnect();
            }

            await super.dispose();
        }
    }    

    private async startForwarding(s: vsls.SharedServer, fireSharingStartedEvent = true, startBrowseSharing = false) {
        if (this.isDisposed || !s) {
        }

        const { sourcePort } = s;
        if (this.servers.has(sourcePort) || this.serverDisposables.has(sourcePort)) {
            return;
        }

        let destinationPort: number;
        if (os.platform() !== OSPlatform.WINDOWS && !this.alwaysUseFreePort && sourcePort < 1024 && !this.disableSudoPortForwarder) {

            // Elevation is required
            destinationPort = await this.startSudoPortForwarder(s);
            if (this.isDisposed) {
                return;
            }
        }

        if (!destinationPort) {
            destinationPort = await this.startLocalPortForwarder(s);
            if (!destinationPort) {
                return;
            }
        }

        const server: vsls.SharedServer = { ...s, destinationPort };
        this.servers.set(sourcePort, server);
        if (fireSharingStartedEvent) {
            this.sharingStarted.fire({ server });
        }

        if (startBrowseSharing && s.browseUrl) {
            this.startBrowseSharing(server);
        }
    }

    private async startSudoPortForwarder(s: vsls.SharedServer): Promise<number|undefined> {
        try {
            if (!this.sudoPortforwarderClient) {
                const workspaceId = this.dependencies.workspaceId;
                if (!workspaceId || this.isDisposed) {
                    return;
                }

                const hubPipeName = await this.dependencies.hubPipeName;
                if (!hubPipeName || this.isDisposed) {
                    return;
                }

                if (!this.sudoPortforwarderClient) {
                    const userChoice = await NotificationUtil.showInformationMessage(
                        `Live Share host is sharing a server at port ${s.sourcePort}. How do you want to map it?`,
                        false,
                        'Random free port', `System port ${s.sourcePort} (elevation required)`);

                    if (this.isDisposed) {
                        return;
                    }

                    if (userChoice === 'Random free port') {
                        this.disableSudoPortForwarder = true;
                        return;
                    }
        
                    const pfClient = await createSudoPortForwardingHubClient(
                        constants.LIVESHARE_EXTENSION_ID,
                        workspaceId,
                        this.logger.createChild('PortForwardingHubClient'),
                        {
                            sudoWindowName: 'Live Share Port Forwarder',
                            timeoutMs: 2 * 60 * 1000,
                            failFast: true,
                        }
                    );

                    if (this.isDisposed) {
                        return;
                    }

                    await pfClient.connect(hubPipeName);

                    if (!this.sudoPortforwarderClient && !this.isDisposed) {
                        this.sudoPortforwarderClient = pfClient;
                    } else {
                        pfClient.disconnect();
                        if (this.isDisposed) {
                            return;
                        }
                    }
                }
            }

            const localPort = await this.sudoPortforwarderClient.startPortForwarding(s);
            if (localPort && !this.isDisposed) {
                this.serverDisposables.set(s.sourcePort, { dispose: () => this.sudoPortforwarderClient.stopPortForwarding(s)});
                return localPort;
            }
        } catch (e) {
            this.logger.error(`Error starting sudo port forwarder: ${e}`);
            this.disableSudoPortForwarder = true;            
        }
    }

    private async startLocalPortForwarder(s: vsls.SharedServer) {
        const { sourcePort } = s;
        const trace = this.logger.withName(`liveshare-tunnel${sourcePort}`);
        const localServer = new LocalPortForwarder(
            trace, 
            s,
            (await this.dependencies.workspaceConnectionPromise),
            this.rpcServices.streamManagerService(),
            this.alwaysUseFreePort ? 0 : sourcePort);

        this.serverDisposables.set(sourcePort, localServer);
        try {
            await localServer.start(1 /* channel forecast */);
        } catch (e) {
            trace.error(`Error starting local port forwarder for port ${sourcePort}: ${e.message || e}`);
            this.serverDisposables.delete(sourcePort);
        }

        if (this.isDisposed || !this.serverDisposables.has(sourcePort)) {
            localServer.dispose();
            return;
        }

        return localServer.localPort;
    }

    private stopForwarding({ sourcePort }: vsls.SharedServer, fireSharingStoppedEvent: boolean) {
        if (this.isDisposed || !sourcePort) {
            return;
        }

        const disposable = this.serverDisposables.get(sourcePort);
        if (disposable) {
            disposable.dispose();
            this.serverDisposables.delete(sourcePort);
        }

        const server = this.servers.get(sourcePort);
        if (server) {
            this.servers.delete(sourcePort);
            if (fireSharingStoppedEvent) {
                this.sharingStopped.fire({ server });
            }
        }
    }

    private startBrowseSharing(server: vsls.SharedServer) {
        // guestServerController implements this.
    }

    private startPipeForwarding(pipe: vsls.SharedPipe) {
    }

    private stopPipeForwarding(pipe: vsls.SharedPipe) {
    }    
}

