import * as rpc from 'vscode-jsonrpc';

import { IRpcMessageStream, RpcServer } from '@vs/vso-rpc';
import { ILogger } from '@vs/vso-logging';
import { vsls } from '@vs/vsls-contracts';
import { LocalPortForwarder } from './LocalPortForwarder';
import { SudoPortForwarderServiceClient } from './SudoPortForwarderServiceClient';
import { ISudoPortForwarderService } from './interfaces/ISudoPortForwarderService';
import { assertDefined, DisposableClass, TConstructable } from '@vs/vscs-utils';

import { ConnectionHub } from '@vs/vscs-connection-hub';
import { HubClientConnection } from './connection/HubClientConnection';

export class SudoPortForwarderService extends DisposableClass implements ISudoPortForwarderService {
    private readonly rpcServer: RpcServer;
    private sudoLocalPortForwarders: Map<number, LocalPortForwarder> = new Map();

    private hubPipeName: string | null = null;

    constructor(
        trace: ILogger,
        private readonly workspaceId: string,
        private readonly connectionHub: ConnectionHub<TConstructable<HubClientConnection>>,
    ) {

        super(trace.createChild('sudo-pf-service'));

        this.rpcServer = new RpcServer(trace.createChild('RpcServer'));
        this.rpcServer.registerRpcService<ISudoPortForwarderService>(
            this,
            SudoPortForwarderServiceClient
        );

        this.addToDisposables(this.rpcServer);
        this.rpcServer.addToDisposables(this);
    }

    public acceptStream(rpcMessageStream: IRpcMessageStream): rpc.MessageConnection {
        const rpcConnection = this.rpcServer.acceptRpcMessageStream(rpcMessageStream)[0];
        rpcConnection.onClose(() => {
            this.disconnectAsync();
        });

        return rpcConnection;
    }

    public async connectAsync(hubPipeName: string) {
        try {
            this.hubPipeName = hubPipeName;

            const start = Date.now();
            this.trace.info(`connectAsync: Connecting now.. pipename ${hubPipeName}`);

            const connection = await this.connectionHub.connect({
                hubPipeName,
                workspaceId: this.workspaceId,
                liveShareEndpoint: '',
                token: '',
            });

            connection.workspaceClient.rpcClient.onClose(() => {
                this.sudoLocalPortForwarders.forEach(async (portForwarder) => {
                    await portForwarder.stop();
                });
                this.sudoLocalPortForwarders = new Map();
            });

            const time = (Date.now() - start).toFixed(1);
            this.trace.verbose(`connectAsync: connected -> total time:${time}`);
        } catch (err) {
            this.trace.error('connectAsync: Error connecting', err);
            throw err;
        }
    }

    async startPortForwardingAsync(sharedServer: vsls.SharedServer): Promise<number|undefined> {
        try {
            this.trace.verbose(`startPortForwardingAsync`);

            const start = Date.now();

            assertDefined(
                this.hubPipeName,
                'No hub pipe name set, please call `connectAsync` first.',
            );

            const connection = await this.connectionHub.connect({
                hubPipeName: this.hubPipeName,
                workspaceId: this.workspaceId,
                liveShareEndpoint: '',
                token: '',
            });

            const streamManagerClient = connection.workspaceClient.getServiceProxy<
                vsls.StreamManagerService
            >(vsls.StreamManagerService);

            const portForwarder = new LocalPortForwarder(
                this.trace,
                sharedServer,
                connection.workspaceClient,
                streamManagerClient,
                sharedServer.sourcePort,
                [], // don't rebind to random port on `EACCESS` and `EADDRINUSE` errors
            );
            this.sudoLocalPortForwarders.set(sharedServer.sourcePort, portForwarder);
            await portForwarder.start();

            const time = (Date.now() - start).toFixed(1);
            this.trace.verbose(`startPortForwardingAsync: forwarded port -> total time:${time}`);
            return portForwarder.localPort;
        } catch (err) {
            this.trace.error('startPortForwardingAsync: Error forwarding port', err);
            throw err;
        }
    }

    async stopPortForwardingAsync(sharedServer: vsls.SharedServer): Promise<void> {
        try {
            const portForwarder = this.sudoLocalPortForwarders.get(sharedServer.sourcePort);
            if (!portForwarder) {
                this.trace.error(
                    `stopPortForwardingAsync: Trying to stop port forwarder (for port ${sharedServer.sourcePort}) which is not already forwarded`
                );
                return;
            }
            await portForwarder.stop();
            this.sudoLocalPortForwarders.delete(sharedServer.sourcePort);
            this.trace.verbose('stopPortForwardingAsync: stopped forwarded port');
        } catch (err) {
            this.trace.error('stopPortForwardingAsync: Error stopping forwarded port', err);
            throw err;
        }
    }

    async disconnectAsync(): Promise<void> {
        if (!this.hubPipeName) {
            this.trace.info('not connected');
            return;
        }

        const connection = await this.connectionHub.getConnection({
            hubPipeName: this.hubPipeName,
            workspaceId: this.workspaceId,
            liveShareEndpoint: '',
            token: '',
        });

        await connection?.workspaceClient?.disconnect();
    }
}

