'use strict';
import * as semver from 'semver';
import * as vscode from 'vscode';
import { Progress, Uri, CancellationToken } from 'vscode';
import { traceSource } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import { SearchServiceTelemetryEventNames, FileSearchTelemetry, TextSearchTelemetry } from './telemetry/SearchServiceTelemetry';
import { ErrorCodes } from 'vscode-jsonrpc';
import { IInternalFileSearchProvider } from 'vscode-cached-file-search-provider';
import { IDependencies } from './contracts/IDependencies';
import { Signal } from '@vs/vscs-utils';
import {
    Telemetry,
    FaultType
} from '@vs/vso-telemetry';

import { vsls } from '@vs/vsls-contracts';
import { PathUtil } from './utils/PathUtil';
import { IPathManager } from './IPathManager';
import { localize } from './localize';

export class SearchProvider implements IInternalFileSearchProvider, vscode.FileIndexProvider, vscode.TextSearchProvider {
    private fileservice: vsls.FileService;
    private readonly trace: TraceSource;
    private fileListMap: Map<string, Promise<string[]>>;
    private fileSearchOptionsMap: Map<string, vscode.FileSearchOptions>;
    private readonly pathManager: IPathManager;

    public constructor(dependencies: IDependencies) {
        this.fileservice = dependencies.fileService();
        this.fileSearchOptionsMap = new Map<string, vscode.FileSearchOptions>();
        this.fileListMap = new Map<string, Promise<string[]>>();
        this.fileservice.onFilesChanged((e: vsls.FilesChangedEventArgs) =>
            this.onFilesChanged(e));
        this.trace = traceSource.withName(vsls.TraceSources.AgentFile);
        this.pathManager = dependencies.pathManager();
    }

    private async onFilesChanged(e: vsls.FilesChangedEventArgs): Promise<void> {
        for (let change of e.changes) {
            await this.updateList(change);
        }
    }

    private async updateList(change: vsls.FileChange): Promise<void> {
        if (!change.fullPath) {
            return;
        }
        const { moniker } = PathUtil.getMonikerFromRelativePath(change.fullPath);
        const changePath = PathUtil.getRelativePathFromPrefixedPath(change.fullPath);
        
        const root = PathUtil.getPrefixedRoot(moniker);
        let filePaths = await this.getCachedList(root);        
        if (!filePaths) {
            filePaths = [];
        }

        switch (change.changeType) {
            case vsls.FileChangeType.Deleted:
                let index = filePaths ? filePaths.indexOf(changePath) : -1 ;
                if (index === -1) {
                    break;
                }

                filePaths.splice(index, 1);
                break;
            case vsls.FileChangeType.Added:
                // if we haven't done a search for this root, we
                // won't have options or anything to update.
                const options = this.fileSearchOptionsMap.get(root);
                if (!options) {
                    break;
                }

                //check if file is excluded
                let fileOptions: vsls.FileListOptions = {
                    excludePatterns: options.excludes,
                    enableMultipleRoots: true
                };
                if (!(await this.fileservice.isExcludedAsync(changePath, fileOptions))) {
                    filePaths.push(changePath);
                }
                break;
            default:
                break;
        }

        this.fileListMap.set(root, Promise.resolve(filePaths));
    }

    private async getFiles(options: vscode.FileSearchOptions, token: CancellationToken): Promise<string[]> {
        try {
            const includeList = [options.folder.path];

            const fileOptions: vsls.FileListOptions = {
                excludePatterns: options.excludes,
                enableMultipleRoots: true,
                includePatterns: includeList
            };

            const filePaths = await this.fileservice.getFilesAsync(fileOptions, token);
            FileSearchTelemetry.sendFindFileDiagnostics(filePaths.length, !!options.useIgnoreFiles);
            return filePaths;
        } catch (e) {
            this.trace.error(e);
            Telemetry.sendFault(SearchServiceTelemetryEventNames.FIND_FILE_FAULT, FaultType.Error, 'Failed to get files from host', e);
        }
    }

    private getCachedList(root: string): Promise<string[] | undefined> {
        const fileListPromise = this.fileListMap.get(root);
        if (fileListPromise) {
            return fileListPromise;
        }
    }

    private async getFileResults(options: vscode.FileSearchOptions, token: any): Promise<string[] | undefined> {
        const root = options.folder.path;
        let fileList: string[];

        const fileListPromise = this.fileListMap.get(root);
        if (fileListPromise) {
            fileList = await fileListPromise;
        }

        if (!fileList || !this.fileSearchOptionsMap.has(root)) {
            const signal = new Signal<string[]>();
            try {
                this.fileListMap.set(root, signal.promise);
                fileList = await this.getFiles(options, token);
                signal.resolve(fileList);
            } catch(error) {
                this.fileListMap.delete(root);
                signal.reject(error);
                throw error;
            }

            this.fileSearchOptionsMap.set(root, options);
        }

        return fileList;
    }

    public async provideFileSearchResults(options: vscode.FileSearchOptions, progress: vscode.Progress<string>, token: any): Promise<void> {
        const fileList = await this.getFileResults(options, token);
        if (fileList) {
            fileList.forEach(f => progress.report(f));
        }
    }

    public async provideFileIndex(options: vscode.FileSearchOptions, token: CancellationToken): Promise<vscode.Uri[]> {
        const fileList = await this.getFileResults(options, token);
        if (fileList) {
            const vslsUris = fileList.map(relativePath => {
                return this.pathManager.relativePathToLocalPath(relativePath);
            });
            return vslsUris;
        }
        return [];
    }

    //current 1.29.0+, result.ranges not null
    public toVsCodeTextSearchResult1(result: vsls.TextSearchResult): vscode.TextSearchMatch {
        let vslsUri = this.pathManager.relativePathToLocalPath(result.path);
        return {
            uri: vslsUri,
            ranges: result.ranges ? result.ranges.map(r => new vscode.Range(r.line, r.column, r.endLine, r.endColumn)) : [],
            preview: {
                text: result.text,
                matches: result.previewRanges ? result.previewRanges.map(r => new vscode.Range(r.line, r.column, r.endLine, r.endColumn)) : []
            }
        };        
    }

    //current 1.29.0+, result.ranges null
    //i.e., if host is sending old-style result
    public toVsCodeTextSearchResult2(result: vsls.TextSearchResult): vscode.TextSearchMatch {
        let vslsUri = this.pathManager.relativePathToLocalPath(result.path);
        return {
            uri: vslsUri,
            ranges: [new vscode.Range(result.line, result.column, result.line, result.column + result.length)],
            preview: {
                text: result.text,
                matches: [new vscode.Range(0, result.column, 0, result.column + result.length)]
            }
        };       
    }

    //older 1.26.0+
    public toVsCodeTextSearchResult3(result: vsls.TextSearchResult): vscode.OldTextSearchMatch {
        let vslsUri = this.pathManager.relativePathToLocalPath(result.path);
        return {
            uri: vslsUri,
            range: new vscode.Range(result.line, result.column, result.line, result.column + result.length),
            preview: {
                text: result.text,
                match: new vscode.Range(0, result.column, 0, result.column + result.length)
            }
        };
    }

    public toVslsTextSearchOptions(query: vscode.TextSearchQuery, options: vscode.TextSearchOptions): vsls.TextSearchOptions {
        return {
            pattern: query.pattern,
            isRegex: query.isRegExp,
            isCaseSensitive: query.isCaseSensitive,
            isWordMatch: query.isWordMatch,
            includeHiddenFiles: options.useIgnoreFiles,
            encoding: options.encoding,
            fileIncludes: options.includes,
            fileExcludes: options.excludes
        };
    }

    public async provideTextSearchResults(
        query: vscode.TextSearchQuery, options: vscode.TextSearchOptions, progress: Progress<vscode.TextSearchResult>, token: CancellationToken): 
        Promise<vscode.TextSearchComplete> {
        let vslsOptions = this.toVslsTextSearchOptions(query, options);
        const searchServiceTelemetry = new TextSearchTelemetry();
        searchServiceTelemetry.startTextSearch();
        let results: vsls.TextSearchResult[] = [];
        let receivedResult = false;
        let counter = 0;
        let hitResultsLimit = false;
        let hostIsNotOld = false;

        let vslsProgress: Progress<vsls.TextSearchResult> = {
            report: (v: any) => { 
                if (!receivedResult) {
                    receivedResult = true;
                    searchServiceTelemetry.saveFirstResultTime();
                }
                try {
                    if (semver.gte(vscode.version, '1.29.0')) {
                        if (v.ranges && v.previewRanges) { // both or neither must be null
                            hostIsNotOld = true;
                            progress.report(this.toVsCodeTextSearchResult1(v));
                        } else {
                            if (!hostIsNotOld) {
                                progress.report(this.toVsCodeTextSearchResult2(v));
                            }
                        }
                    } else if (semver.gte(vscode.version, '1.26.0')) {
                        progress.report(this.toVsCodeTextSearchResult3(v));
                    }
                    counter++; 
                } catch (e) {
                }
                if (v.hitResultsLimit === true) {
                    hitResultsLimit = true;
                }
            }
        };
        try {
            try {
                await this.fileservice.getTextSearchResultsWithProgressAsync(vslsOptions, vslsProgress, token);
                searchServiceTelemetry.saveTextSearchResults(counter);
            } catch (e) {
                if (e.code === ErrorCodes.MethodNotFound) {
                    results = await this.fileservice.getTextSearchResultsAsync(vslsOptions, token);
                    if (semver.gte(vscode.version, '1.29.0')) {
                        results.forEach(result => {
                            progress.report(this.toVsCodeTextSearchResult1(result));
                        });
                    } else if (semver.gte(vscode.version, '1.26.0')) {
                        results.forEach(result => {
                            progress.report(this.toVsCodeTextSearchResult3(result));
                        });
                    }
                }
                if (results.length > 0 && results[results.length - 1].hitResultsLimit) {
                    hitResultsLimit = true;
                }
                searchServiceTelemetry.saveTextSearchResults(results.length);
            }
        } catch (e) {
            // Do nothing; host doesn't have latest extension
            return {limitHit: hitResultsLimit};
        }
        searchServiceTelemetry.send();
        if (semver.gte(vscode.version, '1.28.0')) {
            return {limitHit: hitResultsLimit};
        } else {
            if (hitResultsLimit) {
                vscode.window.showInformationMessage(localize('info.SearchResultsLimited'));
            }
            return {limitHit: hitResultsLimit};             
        }
    }
}