import { ITelemetryFilter } from './ITelemetryFilter';
import { TelemetryPropertyNames } from './TelemetryStrings';

// This filter ensures that only one telemetry event with the given
// event name and set of properties is ever sent. This is useful in
// situations where the same event can be sent many times; e.g. exceptions.
export class SendOnceFilter implements ITelemetryFilter {

    private sentEventsProperties: { [key: string]: string; }[] = [];

    constructor(private readonly eventName: string, private readonly distinctProperties: string[] = []) {}

    public shouldSend(eventName: string, properties: { [key: string]: string; }, measures: { [key: string]: number; }): boolean {
        if (eventName === this.eventName) {
            for (const sentProperties of this.sentEventsProperties) {
                if (this.propertySubsetsEqual(properties, sentProperties)) {
                    return false;
                }
            }
            this.sentEventsProperties.push(this.createPropertySubset(properties));
        }
        return true;
    }

    public reset(): void {
        this.sentEventsProperties = [];
    }

    private createPropertySubset(properties: { [key: string]: string; }): { [key: string]: string; } {
        const propertySubset: { [key: string]: string; } = {};
        for (const p of this.distinctProperties) {
            propertySubset[p] = properties[p];
        }
        return propertySubset;
    }

    private propertySubsetsEqual(properties1: { [key: string]: string; }, properties2: { [key: string]: string; }): boolean {
        for (const p of this.distinctProperties) {
            if (properties1[p] !== properties2[p]) {
                return false;
            }
        }
        return true;
    }

}

/** Telemetry sampling config
 * A map from telemetry event name (excluding 'vsliveshare/' prefix) to the sampling rate.
 * The sampling rate means:
 * 0 - never send the event
 * 1 - always send the event
 * Any positive number (n) - send event 1 out of n times randomly. E.g. 2 - send every other event; 10 - send every 10th event.
 *
 * To count actual occurrencies of a sampled event, use a Kusto query similar to below:
 *   extend sampleRate = iif(isempty((Measures["vsliveshare.samplerate"]), 1, toint(Measures["vsliveshare.samplerate"]))
 *   summarize totalEvents = sum(sampleRate)
 */
export interface ISamplingConfig {
    [eventName: string]: number;
}

export class SamplingFilter implements ITelemetryFilter {
    public constructor(private readonly samplingConfig: ISamplingConfig) {
    }

    public shouldSend(eventName: string, properties: { [key: string]: string; }, measures: { [key: string]: number; }): boolean {
        if (!eventName) {
            return true;
        }

        // Check if sampling is enabled for this event
        const sampleRate = this.samplingConfig[eventName];
        if (typeof sampleRate === 'number' && !isNaN(sampleRate)) {
            if (sampleRate === 0 || Math.random() * sampleRate > 1) {
                // The event is disabled (sampleRate is 0) or sampled out
                return false;
            }

            // Include into the sample - add sample rate measure
            measures[TelemetryPropertyNames.SAMPLE_RATE] = sampleRate;
        }

        return true;
    }
}
