import * as stream from 'stream';
import { InitializeRequest, InitializeParams, InitializeResult, ServerCapabilities } from 'vscode-languageserver-protocol';
import { StreamMessageReader, StreamMessageWriter, Logger, MessageConnection, createMessageConnection, RequestMessage, NotificationMessage, CancellationToken } from 'vscode-jsonrpc';
import { RpcErrorCodes, RpcProxy } from '@vs/vso-rpc';
import { TraceSource } from '@vs/vso-logging';

import { 
    SessionContext,
 } from '@vs/liveshare-core';
 import { vsls } from '@vs/vsls-contracts';
 import { traceSource } from '@vs/vscode-command-framework';
/**
 * This class provides readable and writable streams that can be connected to a LSP client and on the side performs requests via LiveShare 
 */
export class LSPClientStreamProvider {
    private readonly trace: TraceSource;
    private readonly readStream: stream.Readable;
    private readonly readStreamWriter: stream.Writable;
    private readonly writeStream: stream.Writable;
    private readonly writeStreamReader: stream.Readable;
    
    constructor(private languageServerProviderClient: vsls.LanguageServerProvider, universalServerCapabilities: ServerCapabilities = null) {
        this.trace = traceSource.withName(vsls.TraceSources.ClientLSP);
        
        // Set up read and write streams that we hand out the LSP client. Connect them to a reader and writer using which we can pipe messages in.
        this.readStream = new stream.Readable({read: () => {}});
        this.readStreamWriter = new stream.Writable({write: (chunk, encoding, callback) => {
            this.readStream.push(chunk, encoding);
            callback();
        }});
        this.writeStreamReader = new stream.Readable({read: () => {}});
        this.writeStream = new stream.Writable({write: (chunk, encoding, callback) => {
            this.writeStreamReader.push(chunk, encoding);
            callback();
        }});

        let logger: Logger = {
            info: this.trace.info,
            warn: this.trace.warning,
            error: this.trace.error,
            log: this.trace.verbose
        };

        // Setup a rpc connection to the stream readers so that we can decode the messages to a RPC message object that we can send
        // to the host side.
        let connection = createMessageConnection(new StreamMessageReader(this.writeStreamReader), new StreamMessageWriter(this.readStreamWriter), logger);

        connection.onRequest(async (method: string, params: any[], token: CancellationToken) => {
            let coeditingInformation: vsls.CoeditingInformation = { highestLocalTextChange: SessionContext.coeditingClient.currentHighestLocalTextChange,
                                                                    serverVersion: SessionContext.coeditingClient.currentServerVersion,
                                                                    clientId: SessionContext.coeditingClient.clientID };
            LSPClientStreamProvider.modifyRequestParams(method, params);
            let result: any;
            try {
                result = await languageServerProviderClient.requestAsync({method, params}, coeditingInformation, token);
            } catch (e) {
                if (e.code === RpcErrorCodes.RequestCancelled) {
                    // TODO the vscode-jsonrpc library will report this as an internal server error. According to the spec, it's preferred
                    // that we report it as a cancellation error - https://microsoft.github.io/language-server-protocol/specification#cancelRequest
                }
                throw e;
            }

            switch (method) {
                case InitializeRequest.type.method:
                    const initializeResult = result as InitializeResult;
                    if (universalServerCapabilities && initializeResult.capabilities) {
                        LSPClientStreamProvider.modifyServerCapabilities(initializeResult, universalServerCapabilities);
                    }
                    break;
                default:
                    break;
            }
            return result;
        });

        connection.onNotification((method: string, params: any[], token: CancellationToken) => {
            return RpcProxy.notifyAsync(languageServerProviderClient, 'notify', <vsls.LspMessage>{
                method,
                params
            });
        });

        languageServerProviderClient.onNotified((notificationEventArgs) =>  {
            const notificationMessage = notificationEventArgs.body;
            connection.sendNotification(notificationMessage.method, notificationMessage.params);
        });
        connection.listen();
    }

    private static modifyRequestParams(method: string, params: any) {
        // The initialize request sent from VS Code doesn't conform to the LSP; it contains an empty
        // value for an enum type, which will break the VS client. Bug on VS Code: https://github.com/microsoft/vscode/issues/73791
        if (method === InitializeRequest.type.method) {
            const initializeParams = params as InitializeParams;
            if (initializeParams.capabilities && initializeParams.capabilities.textDocument && initializeParams.capabilities.textDocument.codeAction
                        && initializeParams.capabilities.textDocument.codeAction.codeActionLiteralSupport
                        && initializeParams.capabilities.textDocument.codeAction.codeActionLiteralSupport.codeActionKind
                        && initializeParams.capabilities.textDocument.codeAction.codeActionLiteralSupport.codeActionKind.valueSet) {
                const valueSet = initializeParams.capabilities.textDocument.codeAction.codeActionLiteralSupport.codeActionKind.valueSet;
                const emptyIdx = valueSet.indexOf('');
                if (emptyIdx >= 0) {
                    valueSet.splice(emptyIdx, 1);
                }
            }
        }
    }

    // We should modify the Server capabilities and set false the capabilities we can manage with the Universal server.
    private static modifyServerCapabilities(initializeResult: InitializeResult, universalServerCapabilities: ServerCapabilities) {
        initializeResult.capabilities.codeActionProvider = !universalServerCapabilities.codeActionProvider && initializeResult.capabilities.codeActionProvider;
        initializeResult.capabilities.colorProvider = !universalServerCapabilities.colorProvider && initializeResult.capabilities.colorProvider;
        initializeResult.capabilities.declarationProvider = !universalServerCapabilities.declarationProvider && initializeResult.capabilities.declarationProvider;
        initializeResult.capabilities.definitionProvider = !universalServerCapabilities.definitionProvider && initializeResult.capabilities.definitionProvider;
        initializeResult.capabilities.documentFormattingProvider = !universalServerCapabilities.documentFormattingProvider && initializeResult.capabilities.documentFormattingProvider;
        initializeResult.capabilities.documentHighlightProvider = !universalServerCapabilities.documentHighlightProvider && initializeResult.capabilities.documentHighlightProvider;
        initializeResult.capabilities.documentRangeFormattingProvider = !universalServerCapabilities.documentRangeFormattingProvider && initializeResult.capabilities.documentRangeFormattingProvider;
        initializeResult.capabilities.documentSymbolProvider = !universalServerCapabilities.documentSymbolProvider && initializeResult.capabilities.documentSymbolProvider;
        initializeResult.capabilities.foldingRangeProvider = !universalServerCapabilities.foldingRangeProvider && initializeResult.capabilities.foldingRangeProvider;
        initializeResult.capabilities.hoverProvider = !universalServerCapabilities.hoverProvider && initializeResult.capabilities.hoverProvider;
        initializeResult.capabilities.implementationProvider = !universalServerCapabilities.implementationProvider && initializeResult.capabilities.implementationProvider;
        initializeResult.capabilities.referencesProvider = !universalServerCapabilities.referencesProvider && initializeResult.capabilities.referencesProvider;
        initializeResult.capabilities.renameProvider = !universalServerCapabilities.renameProvider && initializeResult.capabilities.renameProvider;
        initializeResult.capabilities.typeDefinitionProvider = !universalServerCapabilities.typeDefinitionProvider && initializeResult.capabilities.typeDefinitionProvider;
        initializeResult.capabilities.workspaceSymbolProvider = !universalServerCapabilities.workspaceSymbolProvider && initializeResult.capabilities.workspaceSymbolProvider;
    }

    public get ReadStream(): stream.Readable {
        return this.readStream;
    }

    public get WriteStream(): stream.Writable {
        return this.writeStream;
    }
}