import * as vscode from 'vscode';

import { traceSource } from '@vs/vscode-command-framework';
import { AgentRpcClient } from '../../workspace/AgentRpcClient';
import { joinWorkspaceClientFactory, getLocalWorkspaceClient } from './joinWorkspaceClientFactory';
import { IRpcClient, RpcClient, ServiceInfo } from '@vs/vso-rpc';
import { IDependencies } from '../../_new_/IDependencies';
import { isJoinActivated } from '../../_new_/util/activateUtils';
import { CommandId, Settings } from '@vs/liveshare-core';

export function getWorkspaceClientProxy<T>(serviceInfo: ServiceInfo<T>, traceName: string) {
    return getLocalWorkspaceClient().getServiceProxy(serviceInfo, traceName);
}

export function rpcClientFactory(dependencies: IDependencies): IRpcClient {
    if (isJoinActivated()) {
        // Note: if joinining we dont need the agent client, our rpc connection
        // will come from the workspace client library.
        return new RpcClient({
            create: async () => {
                const rpcClient = await joinWorkspaceClientFactory(dependencies);
                const rpcMessageConnection = await rpcClient.ensureConnectionAsync();
                return rpcMessageConnection;
            }
        }, traceSource.withName('RpcClient'));
    }

    const settings = vscode.workspace.getConfiguration();
    const workspaceId = settings.get(CommandId.joinWorkspaceIdSettingName);
    let rpcConnectId: string = null;
    if (workspaceId) {
        const keyReconnectionId = workspaceId.toString() + '-reconnectId';
        rpcConnectId = Settings.getMemento<string>(keyReconnectionId);
        if (rpcConnectId) {
            Settings.saveMemento(keyReconnectionId, null);
        }
    }

    return new AgentRpcClient(rpcConnectId);
}
