import * as rpc from 'vscode-jsonrpc';

import { ILogger } from '@vs/vso-logging';
import { DisposableClass } from '@vs/vscs-utils';
import { IChannel, IRpcRequestContext } from '@vs/vso-rpc';
import { ConnectedState, ILiveShareConnectionOptions } from '@vs/vso-workspace-core';
import { ILiveShareConnection } from '@vs/vscs-connection-hub';
import { IWorkspaceHubService } from './IWorkspaceHubService';
import { wait, assertDefined, timeoutPromise } from '@vs/vscs-utils';
import * as ssh from '@vs/vs-ssh';

/* tslint:disable:no-floating-promises */

// amount of time to keep alive a worskpace join after the last rpc disconnect
const keepAliveTime = 45000;

// timeout to wait to check to check the health of a connection
const checkConnectionTimeout = 3000;

/**
 * Class to manage a workspace remote connection.
 */
export class WorkspaceConnection extends DisposableClass {
    private readonly joinedConnections = new Map<rpc.MessageConnection, number>();
    private readonly streamChannels = new Map<string, IChannel>();

    constructor(
        public readonly workspaceId: string,
        private readonly connection: ILiveShareConnection<ILiveShareConnectionOptions>,
        private readonly workspaceHubService: IWorkspaceHubService,
        private readonly logger: ILogger
    ) {
        super(logger.createChild(`workspace-connection:${workspaceId}`));

        connection.addToDisposables(this);

        // hookup notifications
        this.workspaceClient.rpcClient
            .ensureConnectionAsync()
            .then((rpcConnection) => {
                rpcConnection.onNotification((method: string, ...params: any[]) => {
                    this.logger.verbose(`joined sendNotification method:${method}`);
                    for (const joinedRpcConnection of this.joinedConnections.keys()) {
                        joinedRpcConnection.sendNotification(method, params);
                    }
                });
            })
            .catch((reason) => {
                logger.error('Failed to hookup notifications', reason);
            });

        // hookup events
        this.addToDisposables(
            this.workspaceClient.onHostConnectionChanged((e) => {
                this.trace.verbose(`host connection changed to "${ConnectedState[e.state]}"`);

                // fire to all connected rpc sessions.
                this.workspaceHubService._fireHostConnectionChanged({
                    workspaceId,
                    state: e.state,
                    duration: e.duration,
                });
            })
        );

        this.addToDisposables(
            this.workspaceClient.onWorkspaceMetricsUpdated((e) => {
                // fire to all connected rpc sessions.
                this.workspaceHubService._fireWorkspaceMetricsUpdated({
                    workspaceId,
                    bytesIn: e.bytesIn,
                    bytesOut: e.bytesOut,
                    latency: e.latency,
                });
            }),
            connection.onConnectionChanged((e) => {
                if (e.status === 'disconnected') {
                    this.handleDisconnected('connection disconnected');
                }
            })
        );
    }

    public get workspaceClient() {
        assertDefined(this.connection.workspaceClient, 'workspace client undefined');
        return this.connection.workspaceClient;
    }

    public get workspaceSessionInfo() {
        assertDefined(this.connection.workspaceSessionInfo, 'workspace session undefined');
        return this.connection.workspaceSessionInfo;
    }

    /**
     * Return the rpc workspace client connection.
     */
    public get rpcWorkspaceConnection() {
        return this.workspaceClient.rpcClient.ensureConnectionAsync();
    }

    /**
     * Return the rpc session rpc session number associated with an rpc connection.
     * @param rpcConnection the rpc connection to find.
     */
    public getJoinedRpcConnection(rpcConnection: rpc.MessageConnection): number | undefined {
        return this.joinedConnections.get(rpcConnection);
    }

    public async openStreamingChannel(
        streamId: string,
        rpcConnection: rpc.MessageConnection,
        cancellationToken?: rpc.CancellationToken
    ): Promise<void> {
        let remoteChannel = this.streamChannels.get(streamId);
        if (!remoteChannel) {
            // open the remote stream channel
            try {
                const start = Date.now();
                remoteChannel = await this.workspaceClient.openStreamingChannel(
                    streamId,
                    cancellationToken
                );

                const time = (Date.now() - start).toFixed(1);
                this.logger.info(
                    `openStreamingChannel streamId:${streamId} completed in t:${time}`
                );
            } catch (err) {
                this.logger.error(`Failed to open remote stream: ${streamId}`, err);
                // Note: we still think is better to accpet channel sicne the client is expecting to macth
                // an openChannel method call that otherwise will never be rejected or completed
                await this.acceptChannel(rpcConnection);
                // we still want the client to reject this service call, keep in mind the client create
                // and await for 2 promises, we are making the second one (service call) to fail.
                throw err;
            }

            this.streamChannels.set(streamId, remoteChannel);
            this.logger.verbose(`added streamId:${streamId}`);
        }

        // now accept the channel initiated by the local rpc client
        const acceptSshChannel = await this.acceptChannel(rpcConnection);
        // forward
        this.forwardRemoteChannel(remoteChannel, acceptSshChannel);
    }

    /**
     * Add an rpc connection to the joined set.
     * @param rpcRequestContext the rpc request context.
     */
    public addJoinedConnection(rpcRequestContext: IRpcRequestContext) {
        // add this to the joined connections
        this.logger.info(`join -> adding rpc connection session:${rpcRequestContext.session}`);
        this.joinedConnections.set(rpcRequestContext.connection, rpcRequestContext.session);
    }

    /**
     * Force disconnect by unjoining from the workspace and remove from the hub service
     * @param rpcConnection The rpc connection that route the call
     */
    public disconnect(rpcConnection?: rpc.MessageConnection) {
        const reason = 'disconnect';

        this.logger.info(reason);

        if (rpcConnection) {
            this.joinedConnections.delete(rpcConnection);
        }

        // dispose all hookup events first
        this.dispose(reason);

        // dispose the connection.
        this.connection.disconnect();

        // remove myself from the hub service
        this.removeFromHubService(reason);

        // remove joind rpc connections
        this.disposeJoinedRpcConnections(reason);
    }

    /**
     * Handle an rpc connection disposed
     * @param rpcConnection The rpc connection that got disposed
     */
    public onRpcConnectionDisposed(rpcConnection: rpc.MessageConnection) {
        const noRpcJoined = () => this.joinedConnections.size === 0;

        // delete if belong to an existing joined workspace
        if (this.joinedConnections.has(rpcConnection)) {
            this.logger.info(
                `remove rpc connection rpc session:${this.joinedConnections.get(rpcConnection)}`
            );
            this.joinedConnections.delete(rpcConnection);

            if (noRpcJoined()) {
                wait(keepAliveTime).then(() => {
                    if (noRpcJoined() && !this.isDisposed) {
                        this.logger.info(`disconnect due to no rpc joined`);
                        try {
                            this.disconnect();
                        } catch (err) {
                            this.logger.error(`failed to disconnect workspace`, err);
                        }
                    }
                });
            }
        }
    }

    public async checkConnection(cancellationToken?: rpc.CancellationToken) {
        try {
            this.logger.info('check connection');
            await timeoutPromise(
                this.workspaceClient.checkConnection(cancellationToken),
                checkConnectionTimeout,
                new Error('Failed to check connection')
            );
        } catch (err) {
            this.logger.error('failed to check connection', err);
            const reason = 'check connection failed';
            // remove from the hub service
            this.removeFromHubService(reason);
            // next statement will cause the connection to be dropped
            this.workspaceClient.dispose(reason);
            throw err;
        }
    }

    private handleDisconnected(reason: string) {
        // remove from the hub service
        this.removeFromHubService(reason);
        // Note: this will force all joined rpc sessions to be closed.
        this.disposeJoinedRpcConnections(reason);
        // dispose self
        this.dispose(reason);
    }

    /**
     * Forward a remote channel into a ssh channel
     * @param remoteChannel The remote channel to tunnel
     * @param acceptSshChannel the accepted ssh channel
     */
    private forwardRemoteChannel(remoteChannel: IChannel, acceptSshChannel: ssh.SshChannel) {
        remoteChannel.onDataReceived((data) => {
            data = Buffer.from(data);

            acceptSshChannel.send(data).then(
                () => {
                    remoteChannel.adjustWindow(data.length);
                },
                (e) => {
                    this.logger.error('Error sending channel data: ' + e.message, e);
                }
            );
        });
        acceptSshChannel.onDataReceived((data) => {
            data = Buffer.from(data);

            remoteChannel.send(data).then(
                () => {
                    acceptSshChannel.adjustWindow(data.length);
                },
                (e) => {
                    this.logger.error('Error sending channel data: ' + e.message, e);
                }
            );
        });
        remoteChannel.onClosed((e) => {
            acceptSshChannel.close();
        });
        acceptSshChannel.onClosed((e) => {
            remoteChannel.close();
        });
    }

    /**
     * Accepts a client ssh channel from out multi channel stream
     * @param rpcConnection The rpc connection
     * @returns a ssh channel promise
     */
    private acceptChannel(rpcConnection: rpc.MessageConnection): Promise<ssh.SshChannel> {
        return this.workspaceHubService
            ._getRequestMultiChannelStream(rpcConnection)!
            .acceptChannel();
    }

    /**
     * Dispose all the joined rpc connections
     */
    private disposeJoinedRpcConnections(reason: string): void {
        if (this.joinedConnections.size === 0) {
            return;
        }

        this.logger.info(`disposeJoinedRpcConnections reason:${reason}`);

        const joinedRpcConnections = Array.from(this.joinedConnections.keys());
        this.joinedConnections.clear();

        // Close all the joined connections
        for (const joinedRpcConnection of joinedRpcConnections) {
            joinedRpcConnection.dispose();
        }
    }

    /**
     * Remove the instance from the hub service map.
     */
    private removeFromHubService(reason: string) {
        if (this.workspaceHubService._removeWorkspaceConnection(this.workspaceId)) {
            this.logger.info(`removed from the hub service reason:${reason}`);
        }
    }
}
