import { VsCodeNativeAuthTokenProvider } from './VscodeNativeAuthTokenProvider';
import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';
import { MicrosoftAuthenticationSession } from 'vscode'
import { SupportedAuthProviders } from './NativeAuthProvider';
import * as jwtDecode from 'jwt-decode';

interface IIdentityTokenPayload {
    altsecid: string;
    puid: string;
}

/*
 * Please refer to the following doc for description of Microsoft token scopes:
 * https://docs.microsoft.com/en-us/azure/active-directory/develop/v2-permissions-and-consent
 *
 * The API GUID is one of two authorized audiences for Cascade tokens. Refer to this file for more details:
 * https://devdiv.visualstudio.com/OnlineServices/_git/vssaas-sdk?path=%2Fsrc%2FCommon%2FIdentity%2FAuthenticationConstants.cs&version=GBmaster&line=47&lineEnd=48&lineStartColumn=1&lineEndColumn=1&lineStyle=plain
 */

const visualStudioServicesApiAppId = '9bd5ab7f-4031-4045-ace9-6bebbad202f6';
const scopes = ['email', 'openid', 'offline_access', `${visualStudioServicesApiAppId}/all`];

export class MicrosoftAuthTokenProvider extends VsCodeNativeAuthTokenProvider {

    public constructor(logger?: TraceSource) {
        logger = logger ?? traceSource.withName(SupportedAuthProviders.Microsoft);

        super(SupportedAuthProviders.Microsoft, scopes, logger);
    }

    public async getAccessToken(): Promise<string | undefined> {
        if (this.cascadeTokenIsValid ()) {
            return this.cascadeToken;
        }

        /* This call will refresh tokens in sessions stored
         * by microsoft-authentication provider extension in VSCode.
         *
         * By making the call we will avoid exchanging stale acceess/id tokens
         */
        await this.tryLoadSession(false);

        const microsoftSession = this.session as MicrosoftAuthenticationSession;

        if (!microsoftSession) {
            return undefined;
        }

        let nativeToken = undefined;

        if (microsoftSession.idToken) {
            const jwtToken = jwtDecode<IIdentityTokenPayload>(microsoftSession.idToken);
            nativeToken = (!jwtToken.altsecid && !jwtToken.puid) ? microsoftSession.accessToken : microsoftSession.idToken;
        } else {
            nativeToken = microsoftSession.accessToken;
        }

        if (!nativeToken) {
            return undefined;
        }

        this.cascadeToken = await this.tokenExchangeService.exchange(this.providerId, nativeToken);
        return this.cascadeToken;
    }
}