/** Participant property to indicate a 'host' participant */
export const PARTICIPANT_PROPERTY_IS_HOST = 'isHost';

/** Host flags property */
export const PARTICIPANT_PROPERTY_HOST_FLAGS = 'hostFlags';

/** data type send when an rpc session has just joined */
export const DATA_TYPE_JOINED_READY = 'joined-ready';

/** data type send when the host acknowledge the joining ready message */
export const DATA_TYPE_JOINED_READY_ACK = 'joined-ready.ack';

/** the default liveshare hub type */
export const DATA_TYPE_LIVESHARE_HUB = 'ms-liveshare-hub';

/** Postfix to append when notifying multiple participants */
export const POST_FIX_NOTIFY = '-notify';

/** The Host flags options */
export enum HostFlags {
    /** Will send join ready ack */
    JoinReadAck = 1,
}
