import { IDependencies, TelemetryEventNames, TelemetryPropertyNames } from '@vs/liveshare-core';
import { isSignalRServiceEnabled, isLivesharePresenceEnabled } from '@vs/liveshare-contactservice';
import { vsls } from '@vs/vsls-contracts';
import { ILogger } from '@vs/vso-logging';
import { TelemetryEvent } from '@vs/vso-telemetry';
import * as config from './config';

/**
 * init the rpc hub connection service when used trough an rpc channel.
 */
export function initRpcHubConnectionService(dependencies: IDependencies, trace: ILogger) {

    // Initialize our Hub Connection service
    if (isSignalRServiceEnabled()) {
        trace.info(`Hub connection is being enabled...`);
        const hubConnectionService = dependencies.rpcFactory(vsls.HubConnectionService, 'Hub.Connection');

        let authenticating: boolean = false;
        hubConnectionService.onHubConnectionAttempted(async (e) => {
            if (e.error === vsls.HubConnectionError.TokenExpired && !authenticating) {
                let tokenExpiredEvent = new TelemetryEvent(TelemetryEventNames.TOKEN_EXPIRED);
                try {
                    trace.info(`Refreshing auth token for presence service.`);
                    authenticating = true;

                    const authProvider = dependencies.authenticationProvider();
                    const options = { isAllowAnonymous: false };
                    const nativeAuthFlow = config.get<boolean>(config.Key.nativeAuthFlow);

                    const authenticated = nativeAuthFlow ?
                        await authProvider.attemptSilentNativeLogin(options) :
                        await authProvider.attemptDefaultLoginVSCodeAccount(options);

                    if (!authenticated) {
                        trace.error(`Unable to refresh auth token for presence service.`);
                        if (e.errorDetails) {
                            tokenExpiredEvent.addProperty(TelemetryPropertyNames.TOKEN_EXPIRED_DAYS, e.errorDetails.expiredDays);
                        }
                        await authProvider.signOut();
                    } else {
                        tokenExpiredEvent = null;
                    }
                } catch (error) {
                    trace.error(`Exception when refreshing auth token for presensece service: ` + error);
                    tokenExpiredEvent.addProperty(`Exception:`, error);
                } finally {
                    authenticating = false;
                    if (tokenExpiredEvent) {
                        tokenExpiredEvent.send();
                    }
                }
            }
        });
    }
}