import * as vscode from 'vscode';
import { IChannel } from '@vs/vso-rpc';
import { Disposable } from 'vscode-jsonrpc';

export class StreamChannelTerminal implements vscode.Pseudoterminal {
    private readonly onDidWriteEmitter = new vscode.EventEmitter<string>();
    private isOpened: boolean;
    private readonly initBuffers: Buffer[] = [];
    private disposable: Disposable;
    private streamChannel: IChannel;
    private isReadonly: boolean;

    public onDidWrite = this.onDidWriteEmitter.event;

    constructor(streamChannel?: IChannel, isReadonly?: boolean) {
        if (streamChannel) {
            this.attach(streamChannel, isReadonly);
        }
    }

    public attach(streamChannel: IChannel, isReadonly: boolean) {
        this.streamChannel = streamChannel;
        this.isReadonly = isReadonly;
        this.disposable = streamChannel.onDataReceived(e => this.fireDidWrite(e));
    }

    public open(initialDimensions: vscode.TerminalDimensions | undefined): void {
        this.isOpened = true;
        this.initBuffers.forEach(b => this.fireDidWrite(b));
        this.initBuffers.length = 0;
    }

    public close(): void { 
        if (this.disposable) {
            this.disposable.dispose();
        }     
    }

    public handleInput(data: string): void {
        if (this.isReadonly) {
            return;
        }
        
        this.streamChannel.send(Buffer.from(data));
    }

    public fireDidWrite(buffer: Buffer): void {
        if (this.isOpened) {
            const s = buffer.toString();
            this.onDidWriteEmitter.fire(s);
        } else {
            this.initBuffers.push(buffer);
        }
    }
}