import * as vscode from 'vscode';
import { ShareOptions } from '@vs/liveshare-api-contracts';
import { ICommandContext } from '@vs/vscode-command-framework';
import { ClipboardUtil } from './ClipboardUtil';
import { showInvitationLink } from './showInvitationLink';
import { TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { IWorkspaceAccessControlManager } from '../contracts/IWorkspaceAccessControlManager';
import { vsls } from '@vs/vsls-contracts';

import { localize } from '../localize';

export async function showReusableLink(
    workspaceAccessControlManager: IWorkspaceAccessControlManager,
    workspaceInfo: vsls.WorkspaceInfo,
    context: ICommandContext,
    manualCopy?: boolean): Promise<void> {
        const link = workspaceInfo.joinUri.toString();
        const workspaceId = workspaceInfo.id;

        const copied = await new ClipboardUtil().copyToClipboardAsync(link);

        const moreInfoButton =  { id: 1, 
            title: localize('generic.MoreInfo')};
        const copyButton = { id: 2, 
            title: (copied ? 
            localize('generic.CopyAgain') : localize('generic.CopyLink'))};
        const shareButton = {id: 3, 
            title: localize('generic.StartSharing')};

        let buttons: any[] = [moreInfoButton, copyButton, shareButton];

        const result = await vscode.window.showInformationMessage(
            (copied ? localize('notification.ReusableInvitationLinkCopied') : localize('notification.ReusableInvitationLinkCreated')), true,
            ...buttons);

        if (!result) {
            return;
        }

        switch (result.id) {
            case copyButton.id:
                context.telemetryEvent.addProperty(TelemetryPropertyNames.COPYLINK_FROM_CREATE_WORKSPACE, true);
                await showInvitationLink(workspaceAccessControlManager, link, !copied, false);
                break;
            case moreInfoButton.id:
                context.telemetryEvent.addProperty(TelemetryPropertyNames.MOREINFO_FROM_CREATE_WORKSPACE, true);
                vscode.commands.executeCommand('vscode.open', vscode.Uri.parse('https://aka.ms/vsls-reusable'));
                break;
            case shareButton.id:
                const command = 'liveshare.start';
                context.telemetryEvent.addProperty(TelemetryPropertyNames.SHARE_FROM_CREATE_WORKSPACE, true);
                await vscode.commands.executeCommand<vscode.Uri>(command, <ShareOptions> {
                    sessionId: workspaceId});
                break;
            default: {}
        }
}