import * as vscode from 'vscode';
import { EventEmitter } from 'events';
import { ContactModelApi } from './ContactModelApi';
import { traceSource } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';
import {
    IContactModel,
    IContactManager,
    IContactServiceManager,
    ContactServiceEvents
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';

export interface SuggestedContactsModel {
    contacts: ContactModelApi[];
    exclusive?: boolean;
}

const maxSuggestedContacts = 50;

export class ContactServiceManager extends EventEmitter implements IContactServiceManager {
 
    private readonly trace: TraceSource;
    // tslint:disable
    private _selfUser: ContactModelApi = null;
    private _capabilites: contactProtocol.Capabilities = {};
    private _availableUsers: ContactModelApi[] = [];
    private _suggestedUsers: ContactModelApi[] = [];
    private _descriptionName: string;
    private _providerPriority: number;
    // tslint:enable

    private initialized: boolean;
    private signedState: contactProtocol.SignedStatus = contactProtocol.SignedStatus.None;

    private queueEmitEvents: Array<{
        readonly event: string;
        readonly parameter: any;
    }> = [];

    constructor(
        public readonly serviceId: string,
        public readonly contactServiceProvider: contactProtocol.ContactServiceProvider,
        private contactManager: IContactManager) {
        super();

        // Create our trace source
        this.trace = traceSource.withName('Contact.Service');
    }

    private async request(command: string, parameters: any, cancellationToken?: vscode.CancellationToken): Promise<any> {
        this.trace.verbose(`Request '${command}' serviceId:${this.serviceId}`);           
        try {
            const result = await this.contactServiceProvider.requestAsync(command, parameters, cancellationToken);
            return result;
        } catch (err) {
            this.trace.error(`Request '${command}' failed with error:${err} serviceId:${this.serviceId}`);           
            throw err;
        }
    }

    public async initialize(enablePublish: boolean, publishPresence: contactProtocol.PublishPresenceRequest): Promise<void> {
        this.trace.verbose(`_Initialize:${this.serviceId}`);

        // start receiving events
        this.contactServiceProvider.onNotified(e => this.onNotified(e.type, e.body));

        // request 'Initialize'
        const response = <contactProtocol.InitializeResponse> await this.request(contactProtocol.Methods.RequestInitializeName,
            <contactProtocol.InitializeRequest> {
                clientID: 'vscode',
                workspaceFolders: <any>vscode.workspace.workspaceFolders,
                enablePublish: enablePublish,
                publishPresence: publishPresence
            });

        this._descriptionName = response.description;
        this._capabilites = response.capabilities;
        this._providerPriority = response.providerPriority;
        if (response.selfContact) {
            this.setSelfUser({
                contact: response.selfContact,
            });
        }

        if (response.signedState) {
            this.signedState = response.signedState;
        }

        this.initialized = true;
        if (this.queueEmitEvents.length > 0) {
            this.trace.info(`flush events-> serviceId:${this.serviceId} count:${this.queueEmitEvents.length}`);         
            this.queueEmitEvents.forEach(ev => this.emit(ev.event, ev.parameter));
            this.queueEmitEvents = [];
        }

        this.emit(ContactServiceEvents.Initialized);
    }

    public async signIn(): Promise<void> {
        if (this._capabilites && this._capabilites.supportsSignedStateRequest) {
            await this.request(contactProtocol.Methods.RequestSignInName, {});
        }
    }

    public async signOut(): Promise<void> {
        if (this._capabilites && this._capabilites.supportsSignedStateRequest) {
            await this.request(contactProtocol.Methods.RequestSignOutName, {});
        }
    }

    public async _Dispose(): Promise<void> {
        if (this._capabilites && this._capabilites.supportsDispose) {
            await this.request(contactProtocol.Methods.RequestDisposeName, {});
        }
    }

    public async publishPresence(status: contactProtocol.PresenceStatus, properties: { [key: string]: any; }): Promise<void> {
        if (this._capabilites && this._capabilites.supportsPublishPresence) {
            await this.request(contactProtocol.Methods.RequestPublishPresenceName, <contactProtocol.PublishPresenceRequest> {
                status,
                properties
            });
        }
    }

    public async sendInviteLink(targetContactId: string, link: string): Promise<void> {
        if (this._capabilites && this._capabilites.supportsInviteLink) {
            await this.request(contactProtocol.Methods.RequestInviteName, <contactProtocol.InviteRequest> {
                targetContactId,
                link
            });
        }
    }

    public async contactsPresenceRequest(contacts: contactProtocol.Contact[]): Promise< {[key: string]: ContactModelApi }> {
        if (this._capabilites && !this._capabilites.supportsContactPresenceRequest) {
            // return empty result since the provider does not support it.
            return {               
            };
        }

        const contactsResult = <contactProtocol.ContactPresenceResponse>await this.request(contactProtocol.Methods.RequestContactPresenceName, <contactProtocol.ContactPresenceRequest> {
            contacts
        });

        const result: {[key: string]: ContactModelApi } = {};
        contactsResult.contacts.forEach(r => result[r.contactId] = new ContactModelApi(
            this.serviceId,
            r.contact,
            r.properties ? r.properties : {},
            this.contactManager));

        return result;
    }

    public async contactsPresenceDispose(contactIds: string[]): Promise<void> {
        await this.request(contactProtocol.Methods.RequestContactPresenceDisposeName, <contactProtocol.ContactPresenceDisposeRequest> {
            contactIds
        });
    }

    public async searchContactsRequest(queryOptions: contactProtocol.SearchContactProperty[], maxCount?: number, cancellationToken?: vscode.CancellationToken): Promise<ContactModelApi[]> {
        const searchContactsResponse = <contactProtocol.SearchContactsResponse>await this.request(contactProtocol.Methods.RequestSearchContactsName, <contactProtocol.SearchContactsRequest> {
            queryOptions,
            maxCount
        }, cancellationToken);

        return searchContactsResponse.results.map(item => new ContactModelApi(
            this.serviceId,
             item,
             {},
             this.contactManager));
    }

    public async sendMessage(targetContactId: string, type: string, body: any, cancellationToken?: vscode.CancellationToken): Promise<void> {
        const request = <contactProtocol.SendMessageRequest> {
            targetContactId,
            type,
            body
        };
        await this.request(contactProtocol.Methods.RequestSendMessageName, request, cancellationToken);
    }

    public get capabilites(): contactProtocol.Capabilities {
        return this._capabilites;
    }

    public get descriptionName(): string {
        return this._descriptionName;
    }   

    public get priority(): number {
        if (this._providerPriority !== undefined) {
            return this._providerPriority;
        }

        // return a default priority
        return 100;
    }

    public get selfUser(): ContactModelApi {
        return this._selfUser;
    }
   
    public get selfUserId(): string {
        return this._selfUser ? this._selfUser.contact.id : null;
    }

    public get signedStatus(): contactProtocol.SignedStatus {
        return this.signedState;
    }

    public get availableUsers(): Array<ContactModelApi> {
        return this._availableUsers;
    }

    public lookupContactById(id: string): ContactModelApi {
        return this.availableUsers.concat(this._suggestedUsers).find(c => c.contact.id === id);
    }

    public findMatchContact(contact: contactProtocol.Contact): ContactModelApi {
        return ContactServiceManager.findMatchContact(this.availableUsers.concat(this._suggestedUsers), contact);
    }

    public static isOffline(contactModel: IContactModel): boolean {
        return contactModel.contact.status === contactProtocol.PresenceStatus.Unknown ||
        contactModel.contact.status === contactProtocol.PresenceStatus.Offline;
    }

    private emitEvent(event: string, parameter?: any) {
        if (this.initialized) {
            this.emit(event, parameter);
        } else {
            this.queueEmitEvents.push({
                event,
                parameter
            });
        }
    }

    private setSelfUser(selfContactParams: contactProtocol.SelfContactNotification): void {
        this._selfUser =  new ContactModelApi(
            this.serviceId,
            selfContactParams.contact,
            selfContactParams.registrationInfo ?? {},
            this.contactManager);
    }

    private onNotified(name: string, params: any): void {
        this.trace.verbose(`onNotified-> serviceId:${this.serviceId} name:${name}`);

        switch (name) {
        case contactProtocol.Methods.NotifySelfContactName:
            this.setSelfUser(<contactProtocol.SelfContactNotification>params);
            this.emitEvent(ContactServiceEvents.SelfContactChanged);
            break;
        case contactProtocol.Methods.NotifyAvailableUsersName:
            const availableUsersParams = <contactProtocol.ContactsNotification>params;
            this._availableUsers = this.toContactModels(availableUsersParams);
            
            this.emitEvent(ContactServiceEvents.AvailableUsersChanged);
            break;
        case contactProtocol.Methods.NotifyAvailableUsersAddedName:
            const availableUsersAddedParams = <contactProtocol.ContactsNotification>params;
            this._availableUsers.push(...this.toContactModels(availableUsersAddedParams));            
            this.emitEvent(ContactServiceEvents.AvailableUsersChanged);
            break;
        case contactProtocol.Methods.NotifyAvailableUsersRemovedName:
            const availableUsersRemovedParams = <contactProtocol.ContactsNotification>params;
            this.emitEvent(ContactServiceEvents.AvailableUsersChanged);
            break;
        case contactProtocol.Methods.NotifyPresenceChangedName:
            const presenceChangedParams = <contactProtocol.PresenceChangedNotification>params;

            const contactsPresenceChanged: Array<ContactModelApi> = [];
            presenceChangedParams.changes.forEach(ci => this.updatePresenceStatus(ci, contactsPresenceChanged));

            if (contactsPresenceChanged.length > 0) {
                this.emitEvent(ContactServiceEvents.ContactsChanged, contactsPresenceChanged);
            }

            const changes: { [key: string]: contactProtocol.ContactPropertyValueChanged[]; } = {};
            presenceChangedParams.changes.forEach(ci => {
                    changes[ci.contactId] = [<contactProtocol.ContactPropertyValueChanged>{
                        property: contactProtocol.ContactProperty.Status,
                        value: ci.status
                    }];
            });
    
            this.emitEvent(ContactServiceEvents.ContactsChangedNotification, changes);
            break;
        case contactProtocol.Methods.NotifyContactChangedName:

            const contactChangedParams = <contactProtocol.ContactChangedNotification>params;
            const contactNotifyChanged: Array<ContactModelApi> = [];         
            const contactModels = this.selfUser ? [this.selfUser].concat(this.availableUsers) : this.availableUsers;

            ContactServiceManager.updateContacts(contactModels, contactChangedParams.changes, contactNotifyChanged);
            if (contactNotifyChanged.length > 0) {
                this.emitEvent(ContactServiceEvents.ContactsChanged, contactNotifyChanged);
            }
            this.emitEvent(ContactServiceEvents.ContactsChangedNotification, contactChangedParams.changes);
            break;
        case contactProtocol.Methods.NotifyContactPropertiesChangedName:
            const contactPropertiesChangedParams = <contactProtocol.ContactPropertiesChangedNotification>params;
            this.emitEvent(ContactServiceEvents.ContactPropertyChangedNotification, contactPropertiesChangedParams);
            break;
        case contactProtocol.Methods.NotifyInviteReceivedName:
            const inviteLinkReceivedParams = <contactProtocol.InviteReceivedNotification>params;
            this.emitEvent(ContactServiceEvents.InviteLinkReceived, inviteLinkReceivedParams);
            break; 
        case contactProtocol.Methods.NotifyMessageReceivedName:
            const messageReceivedParams = <contactProtocol.MessageReceivedNotification>params;
            this.emitEvent(ContactServiceEvents.MessageReceived, messageReceivedParams);
            break;
        case contactProtocol.Methods.NotifySuggestedUsersName:
            const suggestedContactsNotification = <contactProtocol.SuggestedContactsNotification>params;
            this._suggestedUsers = this.toContactModels(suggestedContactsNotification, maxSuggestedContacts);
            this.emitEvent(ContactServiceEvents.SuggestedUsersUpdate, <SuggestedContactsModel> {
                    contacts: this._suggestedUsers,
                    exclusive: suggestedContactsNotification.exclusive,
            });
            break; 
        case contactProtocol.Methods.NotifyCapabilitiesUpdateName:
            const oldCapabilities = this._capabilites;
            const newCapabilities = <contactProtocol.Capabilities>params;
           
            this._capabilites = newCapabilities;
            this.emitEvent(ContactServiceEvents.CapabilitiesChanged, {
                oldCapabilities,
                newCapabilities
            });

            // update self contact
            if (! newCapabilities.supportsSelfContact && this._selfUser) {
                this._selfUser = null;
                this.emitEvent(ContactServiceEvents.SelfContactChanged);
            }

            break;
        case contactProtocol.Methods.NotifySignedStateChangedName:
            const signedStateNotification = <contactProtocol.SignedStateChangedNotification>params;
            this.signedState = signedStateNotification.state;
            this.emitEvent(ContactServiceEvents.SignedStateChanged, this.signedState);
            break;
        case contactProtocol.Methods.NotifyAuthenticationRequiredName:
            this.emitEvent(ContactServiceEvents.AuthenticationRequired);
            break;
        default:
        }
    }

    public static updatePresenceStatus(
        contacts: Array<ContactModelApi>,
        presenceChanges: contactProtocol.ContactPresenceUpdate[],
        contactsChanged?: Array<ContactModelApi>) {
        
        const changes: { [key: string]: contactProtocol.ContactPropertyValueChanged[]; } = {};
        presenceChanges.forEach(ci => {
                changes[ci.contactId] = [<contactProtocol.ContactPropertyValueChanged>{
                    property: contactProtocol.ContactProperty.Status,
                    value: ci.status
                }];
        });

        ContactServiceManager.updateContacts(contacts, changes, contactsChanged);
    }

    public static updateContacts(
        contactModels: Array<ContactModelApi>,
        changes: { [key: string]: contactProtocol.ContactPropertyValueChanged[]; },
        contactsChanged?: Array<ContactModelApi>) {

        Object.keys(changes).forEach(contactId => {
            const contactModel = contactModels.find(c => c.contact.id === contactId);         
            if (contactModel) {
                const contactChanged = ContactServiceManager.updateContactChanges(contactModel, changes[contactId]);
                if (contactChanged && contactsChanged) {
                    contactsChanged.push(contactModel);
                }
            }
        });
    }

    public static updateContactPropertyChanges(
        contactModel: ContactModelApi,
        changedProperties: { [key: string]: any; }): void {

        const properties = Object.keys(changedProperties);
        properties.forEach(propertyName => {
            contactModel.properties[propertyName] = changedProperties[propertyName];
        });

        contactModel.fireChanged(...properties);
    }

    private static updateContactChanges(
        contactModel: ContactModelApi,
        changes: contactProtocol.ContactPropertyValueChanged[]): boolean {

        const contact = contactModel.contact;
        const properties: string[] = [];

        changes.forEach(change => {
            // ignore null or undefined properties being received
            if (change.value) {
                switch (change.property) {
                    case contactProtocol.ContactProperty.Status:
                        if (contact.status !== change.value) {
                            contact.status = change.value;
                            properties.push('status');
                        }
                        break;
                    case contactProtocol.ContactProperty.Email:
                        if (contact.email !== change.value) {
                            contact.email = change.value;
                            properties.push('email');
                        }
                        break;
                    case contactProtocol.ContactProperty.AvatarUri:
                        if (contact.avatarUri !== change.value) {
                            contact.avatarUri = change.value;
                            properties.push('avatarUri');
                        }
                        break;
                    case contactProtocol.ContactProperty.DisplayName:
                        if (contact.displayName !== change.value) {
                            contact.displayName = change.value;
                            properties.push('displayName');
                        }
                        break;
                    default:
                }
            }
        });

        if (properties.length > 0) {
            contactModel.fireChanged(...properties);
        }

        return properties.length > 0;
    }

    private updatePresenceStatus(contactPresenceUpdate: contactProtocol.ContactPresenceUpdate, contactsChanged?: Array<ContactModelApi>) {
        const contactModels = this._selfUser && this._selfUser.contact.id === contactPresenceUpdate.contactId ? [this._selfUser] : this.availableUsers;
        ContactServiceManager.updatePresenceStatus(contactModels, [contactPresenceUpdate], contactsChanged);
    }

    private toContactModels(contactsResult: contactProtocol.ContactsNotification, maxCount?: number): Array<ContactModelApi> {
        let contacts = contactsResult.contacts;
        if (maxCount && contacts.length > maxCount) {
            contacts = contacts.slice(0, maxCount);
        }

        return contacts.map(contact => {
            if (!contact.status) {
                contact.status = contactProtocol.PresenceStatus.Unknown;
            }
            return new ContactModelApi(this.serviceId, contact, {}, this.contactManager);
        });
    }

    private static findMatchContact(contacts: ContactModelApi[], contact: contactProtocol.Contact): ContactModelApi {
        return contacts.find(c => contact.id === c.contact.id || contact.email === c.contact.id);
    }
}