import * as vscode from 'vscode';

import { Settings } from '../Settings'
import { SettingKeys } from '../SettingKeys'
import { CommandId } from '../CommandConstants';

export enum SignInReloadMode {
    Anonymous,
    CustomAccount,
}

export interface ISignInReloadInfo {
    time?: number;
    workspaceId?: string;
    account?: string;
    providerName?: string;
}

export async function setAuthReloadFlag(flag: ISignInReloadInfo, mode: SignInReloadMode) {
    if (mode === SignInReloadMode.Anonymous) {
        flag.time = Date.now();
        await setAnonymousAuthReloadFlag(flag);
    } else if (mode === SignInReloadMode.CustomAccount) {
        await setCustomAccountAuthReloadFlag(flag);
    } 
}

export async function resetAuthReloadFlag(mode: SignInReloadMode) {
    if (mode === SignInReloadMode.Anonymous) {
        await resetAnonymousAuthReloadFlag();
    } else if (mode === SignInReloadMode.CustomAccount) {
        await resetCustomAccountAuthReloadFlag();
    }
}

async function setAnonymousAuthReloadFlag(flag: ISignInReloadInfo) {
    await Settings.save(SettingKeys.anonymousAuthReloadFlag, flag);
}

async function resetAnonymousAuthReloadFlag() {
    await Settings.save(SettingKeys.anonymousAuthReloadFlag, null);
}

export async function isAnonymousAuthReloadFlagValid() {
    const settings = vscode.workspace.getConfiguration();
    const workspaceId: string = settings.get(CommandId.joinWorkspaceIdSettingName);
    const flag = Settings.get<ISignInReloadInfo>(SettingKeys.anonymousAuthReloadFlag);

    if (!flag || !flag.time || !flag.workspaceId || !workspaceId) {
        return false;
    }
    
    // if an old record - return false
    if ((Date.now() - flag.time) >= (60 * 1000)) {
        await resetAnonymousAuthReloadFlag();
        return false;
    }

    if (flag.workspaceId.toLowerCase() !== workspaceId.toLowerCase()) {
        return false;
    }

    return true;
}

async function setCustomAccountAuthReloadFlag(flag: ISignInReloadInfo) {
    await Settings.save(SettingKeys.customAccountAuthReloadFlag, flag);
}

async function resetCustomAccountAuthReloadFlag() {
    await Settings.save(SettingKeys.customAccountAuthReloadFlag, null);
}