import * as vscode from 'vscode';
import * as gravatar from 'gravatar-api';
import WebviewContainer from './WebViewContainer';
import { ChatStatusBarItem } from './ChatStatusBarItem';
import { VSLS_CHAT_WINDOW } from '../constants';
import { TraceSource } from '@vs/vso-logging';
import { Telemetry, FaultType } from '@vs/vso-telemetry';
import { SessionState, sessionStateTracker,
    workspaceSessionInfoTracker, localize, IRpcServices,
    ExtensionUtil, IClientAccessCheck, Lazy, TelemetryEventNames,
    TelemetryPropertyNames, SessionContext, CollaboratorChangedEventArgs } from '@vs/liveshare-core';
import { contactProtocol, vsls } from '@vs/vsls-contracts';
import { Messages, ChatWindow, Users, ChatEventSource, UIMessage, ExtensionMessage,
    WindowType, WindowMessages, WindowMessagesWithUndefined, Message,
    MessageType, CommandType, IChatWindowInfo } from './IChatViewController';
import { CommunicationsTelemetryEventNames, CommunicationsTelemetryPropertyNames } from '../CommunicationsTelemetry';
import { NotificationUtil } from '@vs/vscode-command-framework';
import { CommunicationsManager } from '../CommunicationsManager';
import { ChatServiceProxy } from './ChatServiceProxy';
import { ChatMessage, ChatMessageType } from '@vs/vsls-contracts/dist/src/contracts/VSLS';

export class ChatViewController {
    private readonly tracePrefix = '[Chat View Controller]';
    private messages: Messages = {};
    private chatWindow: ChatWindow;
    private users: Users = {};
    private currentUser: contactProtocol.Contact;
    private webview: WebviewContainer;
    private isUIReady: Boolean = false; // Vuejs loaded
    private pendingMessage: UIMessage;
    private typingTimers: { [key: string]: NodeJS.Timer } = {};
    private chatStatusBarItem: ChatStatusBarItem;
    private readonly chatViewChanged: vscode.EventEmitter<void>;
    private readonly unreadWindowCounts: { [key: string]: number } = {};
    private chatServiceProxy: ChatServiceProxy;

    constructor(
        private authCoreService: vsls.AuthenticationCoreService,
        private clientAccessCheck: Lazy<IClientAccessCheck>,
        private rpcServices: IRpcServices,
        chatViewChanged: vscode.EventEmitter<void>,
        private trace: TraceSource) {

        this.authCoreService.onAuthenticationChanged(async (e) => {
            await this.updateUser(e.account?.id);
        });

        workspaceSessionInfoTracker.onReadOnlyChanged(async () => {
            await this.updateUser();
        });

        sessionStateTracker.onStateChanged(async (e) => {
            switch (e.newState) {
                case SessionState.Shared: {
                    await this.initialize();
                    await this.chatServiceProxy.sendMessage(localize('chat.sessionStarted'));
                    break;
                }
                case SessionState.Joined: {
                    await this.initialize();

                    const messageHistory = await this.chatServiceProxy.getMessageHistory();
                    messageHistory.forEach(async (message) => {
                        await this.onMessageReceived({message});
                    });

                    await this.chatServiceProxy.sendMessage(localize('chat.sessionJoined'));
                    break;
                }
                default:
                    break;
            }
        });

        SessionContext.onCollaboratorChanged(async (e: CollaboratorChangedEventArgs) => {
            const isUserUnjoined = e && (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined);
            if (isUserUnjoined) {
                const message: vsls.ChatMessage = {
                    type: ChatMessageType.Text,
                    fromId: e.sessionNumber.toString(),
                    body: { 
                        text: localize('chat.sessionLeft'),
                        timestamp: new Date()
                    }
                };
                await this.onMessageReceived({message});
            }
        });

        this.rpcServices.workspaceService().onConnectionStatusChanged(async e => {
            if (e.disconnectedReason === vsls.WorkspaceDisconnectedReason.SessionEnded && sessionStateTracker.State === SessionState.Shared) {
                await this.chatServiceProxy.sendMessage(localize('chat.sessionEnded'));
            }
        });

        this.chatViewChanged = chatViewChanged;
        this.chatStatusBarItem = new ChatStatusBarItem();
    }

    public async initialize() {
        this.trace.info(`${this.tracePrefix} initialize`);

        this.users = {};
        await this.createChatWindow();
        this.chatServiceProxy = new ChatServiceProxy(this.rpcServices.chatService(), async(message: ChatMessage) => {
            return await this.onMessageReceived({message}); 
        });
        await this.updateUser();
        this.clearMessages();
    }

    private async onMessageReceived(event: vsls.MessageReceivedEventArgs) {
        let { type, fromId, body } = event.message;
        this.trace.info(`${this.tracePrefix} notify. type:${type}, from:${fromId}`);

        const currentUserId = workspaceSessionInfoTracker?.workspaceSessionInfo?.sessionNumber.toString();
        if (!currentUserId || (currentUserId === fromId)) {
            return;
        }

        // OnMessageReceived callback was called by the current user
        if (typeof fromId === 'undefined') {
            fromId = currentUserId;
        }

        if (!this.users[fromId]) {
            await this.prepareContactForDisplay(fromId);
        }

        switch (type) {
            case ChatMessageType.Text:
                const { text, timestamp } = body;
                Telemetry.sendTelemetryEvent(TelemetryEventNames.CHAT_NOTIFY, { [TelemetryPropertyNames.CHAT_NOTIFY_TYPE]: ChatMessageType.Text.toString() });

                const timestampDate = (typeof timestamp === 'string') ? new Date(timestamp) : timestamp;
                const utcTimestamp = (timestampDate.getTime() / 1000).toString();
                let newMessages: WindowMessages = {};
                newMessages[utcTimestamp] = this.toWebviewMessage(text, utcTimestamp, fromId);
                await this.updateMessages(newMessages);
                break;
            case ChatMessageType.Typing:
                await this.updateWebview(fromId);
                
                const key = `${fromId}`;
                if (this.typingTimers[key]) {
                    clearTimeout(this.typingTimers[key] as NodeJS.Timer);
                    this.typingTimers[key] = undefined;
                }
    
                const newTimer = setTimeout(async() => {
                    // This removes typing status --> this timeout should be larger than
                    // the time period between typing events sent from the wire + the time
                    // it takes to transfer them over the wire.
                    await this.updateWebview();
                }, 500);
    
                this.typingTimers[key] = newTimer;
                break;
            default:
                const err = `Unsupported chat message type: ${type}`;
                Telemetry.sendFault(TelemetryEventNames.CHAT_FAULT,
                    FaultType.Error,
                    err);
                throw new Error(err);
        }
    }

    public async openSessionChat(source: ChatEventSource): Promise<void> {
        this.trace.info(`${this.tracePrefix} open session chat: ${VSLS_CHAT_WINDOW.id}`);
        Telemetry.sendTelemetryEvent(CommunicationsTelemetryEventNames.OPEN_CHAT_WINDOW, { [CommunicationsTelemetryPropertyNames.CHAT_EVENT_SOURCE]: source });

        await vscode.commands.executeCommand('workbench.action.focusLastEditorGroup');

        this.loadUi();
        await this.updateWebview();
        await this.updateChatUI();
    }

    public chatWindowInfo(): IChatWindowInfo {
        return {
            contact: VSLS_CHAT_WINDOW,
            unread: this.getUnreadCount()
        };
    }

    public static isUnsupportedChatExtensionInstalled(shouldShowError: boolean): boolean {
        // Ensure that if the legacy chat extension is installed it
        // is a version that works with integrated chat
        const extensions = vscode.extensions.all;
        const chatExtension = extensions.find(ext => ext.id === 'karigari.chat');
        if (!chatExtension) {
            // chat extension isn't installed
             return false;
        }

        const unsupportedVersion = [0, 33]; // 0.33.0
        const installedVersion = chatExtension.packageJSON.version;
        if (installedVersion) {
            const parts = installedVersion.split('.');
            if (parts?.length > 1) {
                const majorVersion = parseInt(parts[0], 10);
                const minorVersion = parseInt(parts[1], 10);
                const isValidInstalledVersion =
                    (majorVersion > unsupportedVersion[0]) ||
                    (minorVersion > unsupportedVersion[1]);
                if (isValidInstalledVersion) {
                    // Valid extension is installed
                    return false;
                }

                if (shouldShowError) {
                    // do not await as the error message should not block extension activation
                    NotificationUtil.showErrorMessage(localize('chat.legacyExtensionUnsupported'));
                }
            }
        }

        // unsupported chat extension
        return true;
    }

    public static getCurrentUserId(): string| undefined {
        const clientId = SessionContext.coeditingClient?.clientID;
        return (typeof clientId === 'number') ?
            SessionContext.collaboratorManager.getUserId(clientId) : undefined;
    }

    private async sendToExtension(message: ExtensionMessage) {
        const { type, body } = message;
        this.trace.info(`${this.tracePrefix} Sending to extension (${type})`);

        switch (type) {
            case MessageType.ready:
                this.isUIReady = true;
                if (this.pendingMessage) {
                    await this.sendToUI(this.pendingMessage);
                }
                break;
            case MessageType.command:
                await this.handleCommand(body);
                break;
            case MessageType.focus:
                await this.onFocus();
                break;
            case MessageType.text:
                await this.chatServiceProxy.sendMessage(body);
                break;
            case MessageType.typing:
                await this.chatServiceProxy.sendTyping();
                break;
            default:
                break;
        }
    }

    private async handleCommand(text: string) {
        const command = text.toLowerCase().trim();
        switch (command) {
            case CommandType.clear:
                Telemetry.sendTelemetryEvent(TelemetryEventNames.CHAT_COMMAND_INVOKED, { [TelemetryPropertyNames.CHAT_COMMAND]: CommandType.clear });
                this.clearMessages();
                break;
            case CommandType.end:
                Telemetry.sendTelemetryEvent(TelemetryEventNames.CHAT_COMMAND_INVOKED, { [TelemetryPropertyNames.CHAT_COMMAND]: CommandType.end });
                if (sessionStateTracker.State === SessionState.Shared) {
                    // If this is the host end the collaboration session
                    await vscode.commands.executeCommand<vscode.Uri>('liveshare.end');
                } else if (sessionStateTracker.State === SessionState.Joined) {
                    // If this is the guest leave the collaboration session
                    await vscode.commands.executeCommand<vscode.Uri>('liveshare.leave');
                }
                break;
            default:
                Telemetry.sendTelemetryEvent(TelemetryEventNames.CHAT_COMMAND_INVOKED, { [TelemetryPropertyNames.CHAT_COMMAND]: 'unknown' });
                // treat the command as a regular text message
                await this.chatServiceProxy.sendMessage(text);
                break;
        }
    }

    private async clearMessages() {
        const existingMessages = this.messages[VSLS_CHAT_WINDOW.id] || {};
        const deletedMessages: any = {};
        Object.keys(existingMessages).forEach((ts: string) => {
            deletedMessages[ts] = undefined;
        });

        await this.updateMessages(deletedMessages);
    }

    private loadUi() {
        if (this.webview) {
            this.webview.reveal();
            return;
        }

        this.webview = new WebviewContainer(
            () => {
                this.webview = undefined;
                this.isUIReady = false;
            },
        );
        this.webview.setMessageHandler(async(message: ExtensionMessage) => await this.sendToExtension(message));
    }

    private async sendToUI(uiMessage: UIMessage): Promise<void> {
        if (!this.isUIReady) {
            this.pendingMessage = uiMessage;
        } else {
            const { messages } = uiMessage;
            const size = Object.keys(messages).length;
            this.trace.info(`${this.tracePrefix} Sending to webview: ${size} messages`);

            if (this.webview) {
                this.webview.update(uiMessage);
                this.pendingMessage = undefined;
                if (this.webview.isVisible()) {
                    await this.updateReadMarker();
                }
            }
        }
    }

    private async updateUser(userId?: string) {
        if (!workspaceSessionInfoTracker?.workspaceSessionInfo?.sessions) {
            return;
        }

        // current user
        if (!userId) {
            const id = workspaceSessionInfoTracker.workspaceSessionInfo.sessionNumber.toString();
            this.currentUser = await this.prepareContactForDisplay(id);
            return;
        }

        for (const sessionNumber in workspaceSessionInfoTracker.workspaceSessionInfo.sessions) {
            if (workspaceSessionInfoTracker.workspaceSessionInfo.sessions[sessionNumber].id === userId) {
                await this.prepareContactForDisplay(sessionNumber);
                break;
            }
        }
    }

    private async onFocus() {
        await this.updateReadMarker();
        await this.updateChatUI();
    }

    private getUnreadCount(): number {
        const { readTimestamp } = this.chatWindow;
        const currentUserInfo = this.currentUser;
        if (!currentUserInfo) {
            // Can be undefined during async update on vsls chat
            return 0;
        }

        const messages = this.messages[VSLS_CHAT_WINDOW.id] || {};
        const unreadMessages = Object.keys(messages).filter(ts => {
            const isDifferentUser = messages[ts].userId !== currentUserInfo.id;
            const isNewTimestamp = !!readTimestamp ? +ts > +readTimestamp : false;
            return isDifferentUser && isNewTimestamp;
        });

        return unreadMessages.length;
    }

    private updateStatusBarItem() {
        const unreads = this.getUnreadCount();
        this.chatStatusBarItem.updateCount(unreads);
    }

    private async updateChatUI() {
        const isChatEnabled = await CommunicationsManager.isChatEnabled();
        if (!isChatEnabled) {
            return;
        }
        const unreadAfter = this.getUnreadCount();
        // Only update the chat UI if the
        // message unread count has changed
        if (this.unreadWindowCounts[VSLS_CHAT_WINDOW.id] !== unreadAfter) {
            this.unreadWindowCounts[VSLS_CHAT_WINDOW.id] = unreadAfter;
            this.updateStatusBarItem();
            this.chatViewChanged.fire();
        }
    }

    private async updateReadMarker(): Promise<void> {
        const lastTs = this.getLastTimestamp();

        if (this.chatWindow && lastTs) {
            const { readTimestamp } = this.chatWindow;
            const hasNewerMsgs = !!readTimestamp ? +readTimestamp < +lastTs : true;

            if (hasNewerMsgs) {
                const incremented = (+lastTs + 1).toString();
                const updatedWindow = this.markChatWindow(incremented);

                if (!!updatedWindow) {
                    this.chatWindow = updatedWindow;
                }
            }
        }
    }

    private markChatWindow(ts: string): ChatWindow {
        return {
            ...this.chatWindow,
            readTimestamp: ts,
            unreadCount: 0
        };
    }

    private getLastTimestamp(): string | undefined {
        const windowMessages = this.messages[VSLS_CHAT_WINDOW.id] || {};
        const timestamps = Object.keys(windowMessages).map(tsString => +tsString);

        if (timestamps.length > 0) {
            return Math.max(...timestamps).toString();
        }
    }

    private async prepareContactForDisplay(id: string): Promise<contactProtocol.Contact> {
        if (sessionStateTracker.State !== SessionState.Joined &&
            sessionStateTracker.State !== SessionState.Shared) {
            return;
        }

        // Search the list of session participants
        let participant = (await this.chatServiceProxy.getParticipants()).find(u => u.id === id);
        if (!participant) {
            return;
        }

        const userProfile = workspaceSessionInfoTracker?.workspaceSessionInfo?.sessions[id];
        const email = (!participant.email || participant.email === 'anonymous') ? `anonymous${id}` : participant.email;
        const avatarUri = userProfile?.avatarUri || this.defaultAvatar(email);
        const label = userProfile ? await ExtensionUtil.getAnonymousReadOnlyLabel(this.clientAccessCheck(), userProfile) : '';
        const contact: contactProtocol.Contact = {
            id,
            displayName: `${participant.name}${label}`,
            avatarUri: avatarUri,
            email
        };

        this.users[id] = contact;

        return contact;
    }

    private defaultAvatar(email: string) {
        return gravatar.imageUrl({
            email: email,
            parameters: { size: '200', d: 'retro' },
            secure: true
        });
    }

    private async updateWebview(typingUserId?: string) {
        if (this.currentUser && this.chatWindow) {
            const users = this.users;
            const windowMessages = this.messages[VSLS_CHAT_WINDOW.id] || {};
            let typingUser: contactProtocol.Contact | undefined;

            if (typingUserId) {
                typingUser = users[typingUserId];
            }

            const { fontFamily, fontSize } = vscode.workspace.getConfiguration('editor');
            let statusText = ``;

            if (typingUser) {
                statusText = localize('chat.typingStatus').replace('$(username)', typingUser.displayName);
            }

            let uiMessage: UIMessage = {
                fontFamily,
                fontSize,
                provider: '',
                messages: windowMessages,
                users,
                currentUser: this.currentUser,
                window: this.chatWindow,
                statusText
            };

            await this.sendToUI(uiMessage);
        }
    }

    private async createChatWindow(): Promise<ChatWindow> {
        let window = this.chatWindow;
        if (!window) {
            // We are saving a slightly old readTimestamp, so that the unread
            // notification can be triggered correctly. As the IM windows can be created
            // at the same time as the message is received, we don't want to simply do a now()
            const oneMinuteAgo = +new Date() / 1000.0 - 60;
            window = {
                id: VSLS_CHAT_WINDOW.id,
                name: VSLS_CHAT_WINDOW.displayName,
                type: WindowType.im,
                isDisabled: false,
                readTimestamp: oneMinuteAgo.toString(),
                unreadCount: 0
            };

            this.chatWindow = window;
        }
        return window;
    }

    private async updateMessages(messages: WindowMessagesWithUndefined): Promise<void> {
        const existingMessages = this.messages[VSLS_CHAT_WINDOW.id] || {};
        const deletedTimestamps = Object.keys(messages).filter(ts => typeof messages[ts] === 'undefined');

        const newMessages: WindowMessages = {};
        Object.keys(existingMessages).forEach(ts => {
            const isDeleted = deletedTimestamps.indexOf(ts) >= 0;
            if (!isDeleted) {
                newMessages[ts] = existingMessages[ts];
            }
        });
        Object.keys(messages).forEach(ts => {
            const message = messages[ts];
            if (!!message) {
                newMessages[ts] = message;
            }
        });
        this.messages[VSLS_CHAT_WINDOW.id] = newMessages;

        // Remove undefined, after message deleted
        Object.keys(this.messages[VSLS_CHAT_WINDOW.id]).forEach(key => {
            if (typeof this.messages[VSLS_CHAT_WINDOW.id][key] === 'undefined') {
                delete this.messages[VSLS_CHAT_WINDOW.id][key];
            }
        });

        await this.updateWebview();

        this.updateChatUI();
    }

    private toWebviewMessage(text: string, timestamp: string, id: string): Message {
        return { text, timestamp, content: undefined, reactions: [], replies: {}, userId: id };
    }
}
