import * as vscode from 'vscode';
import * as uuid from 'uuid';

const stripJsonComments = require('strip-json-comments');

import { ResponseError } from 'vscode-jsonrpc';
import {
    IInittableDisposable,
    Settings,
    SettingKeys,
    IFileSystemManager,
    IPathManager,
    RestrictedOperation,
    WellKnownRestrictedOperations,
    IClientAccessCheck,
    ExtensionUtil,
    ISessionContext,
    TelemetryEventNames,
    TelemetryPropertyNames,
    PathUtil,
    IWorkspaceProvider,
    IWorkspaceFileSystemProvider,
    sessionStateTracker,
    SessionState
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { 
    Telemetry,
    TelemetryResult
} from '@vs/vso-telemetry';

import { 
    TraceSource
} from '@vs/vso-logging';
import {
    RpcErrorCodes
} from '@vs/vso-rpc';

import { activitySource, ActivityType } from '@vs/activity-log';

import { DebugAdapterCustomRequest, DebugType } from './debugConstants';
export enum JoinDebugSessionOption {
    Automatic = 'Automatic',
    Manual = 'Manual',
    Prompt = 'Prompt'
}

export class JoinDebugManager implements IWorkspaceProvider, IInittableDisposable, vscode.DebugConfigurationProvider {
    private static readonly vscodePath = '/.vscode';
    private static readonly vscodeLaunchPath = `${JoinDebugManager.vscodePath}/launch.json`;
    protected readonly joinUniqueId: string;
    protected activeJoinedDebugSessions: Map<string, vscode.DebugSession> = new Map();
    protected sharedDebugSessions: vsls.DebugSession[] = [];
    protected delayedStartDebugSessions: vsls.DebugSession[] = [];
    private rawLaunchConfigurationData: string | object;
    private unmodifiedLaunchConfigurations: Map<string, vscode.DebugConfiguration[]> = new Map();
    private static readonly launchDebugOperation: RestrictedOperation = {
        name: WellKnownRestrictedOperations.LaunchDebug
    };

    protected eventRegistrations: vscode.Disposable[] = [];
    constructor(
        private debuggerHostService: vsls.DebuggerHostService,
        private sessionContext: ISessionContext,
        private fileSystemManager: IFileSystemManager,
        private pathManager: IPathManager,
        private clientAccessCheck: IClientAccessCheck,
        protected trace: TraceSource) {

        // initialize unique join id
        this.joinUniqueId = uuid();

    }

    public isInited: boolean;

    public async init(): Promise<void> {
        // start listening to debugger events
        this.debuggerHostService.onDebugSessionChanged(this.onDebugSessionChanged, this, this.eventRegistrations);
        this.debuggerHostService.onLaunchConfigurationsChanged(this.onLaunchConfigurationsChanged, this, this.eventRegistrations);
        
        // register '*' to intercept all possible types
        vscode.debug.registerDebugConfigurationProvider('*', this);

        vscode.debug.onDidStartDebugSession(this.onDidStartDebugSession, this, this.eventRegistrations);
        vscode.debug.onDidTerminateDebugSession(this.onDidTerminateDebugSession, this, this.eventRegistrations);
       
        const initDebuggingTelemetryEvent = Telemetry.startTimedEvent(TelemetryEventNames.INITIALIZE_DEBUGGING, true);
        try {
            this.sharedDebugSessions = await this.debuggerHostService.getCurrentDebugSessionsAsync();
        } catch (e) {
            if (e.code === RpcErrorCodes.ServiceNotAvailable) {
                this.sharedDebugSessions = [];
            } else {
                throw e;
            }
        }
        initDebuggingTelemetryEvent.addMeasure(TelemetryPropertyNames.NUM_DEBUGGING_PROCESSES, this.sharedDebugSessions ? this.sharedDebugSessions.length : 0);
        if (this.sharedDebugSessions && this.sharedDebugSessions.length > 0) {
            const launchDebugSessions = this.sharedDebugSessions.slice(0);
            const launchAll = () => {
                const sessionLaunches = launchDebugSessions.map(item => {
                    // check if the debug session is still valid
                    if (this.isDebugSessionValid(item)) {
                        return this.joinDebugSession(item);
                    }

                    return null;
                });

                return Promise.all(sessionLaunches);
            };

            initDebuggingTelemetryEvent.addProperty(TelemetryPropertyNames.DEBUG_PROMPT, (this.joinDebugSessionOptionValue === JoinDebugSessionOption.Prompt).toString());
            if (this.joinDebugSessionOptionValue === JoinDebugSessionOption.Automatic) {
                // do not await join debug session in this scenario (see joinDebugSession for details)
                launchAll();
            } else if (this.joinDebugSessionOptionValue === JoinDebugSessionOption.Prompt) {
                const result = await vscode.window.showInformationMessage('The host is already in a collaborative debugging session that you can join', { title: 'Join session now' });
                if (result) {
                    // do not await join debug session in this scenario (see joinDebugSession for details)
                    launchAll();
                }
            }
        }

        // retrieve all remote launch configurations
        try {
            this.setLaunchConfigurations(await this.debuggerHostService.getLaunchConfigurationsAsync() as any);
        } catch (e) {
            if (e.code === RpcErrorCodes.MethodNotFound || e.code === RpcErrorCodes.ServiceNotAvailable) {
                this.setLaunchConfigurations(null);
            } else {
                throw e;
            }
        }

        const workspaceProvider = this.fileSystemManager.workspaceProvider;
        if (workspaceProvider) {
            workspaceProvider.registerWorkspaceProvider(this);
            // Note: since we just joined a remote session we want vscode to update
            // the launch configurations that are available
            this.fireLaunchConfigurationsChanged(workspaceProvider);
        }

        initDebuggingTelemetryEvent.end(TelemetryResult.Success);
        this.isInited = true;
    }

    public dispose(): Promise<void> {
        this.eventRegistrations.forEach((r) => r.dispose());
        return Promise.resolve();
    }

    public async resolveDebugConfiguration(folder: vscode.WorkspaceFolder | undefined, debugConfiguration: vscode.DebugConfiguration, token?: vscode.CancellationToken): Promise<vscode.DebugConfiguration> {
        // Note: vscode will sometimes call 'resolveDebugConfiguration' twice on a single call to 'vscode.debug.startDebugging'.
        // This causes our property injection to run twice with the side effect of blocking our serialization on the
        // adapter execute provider implementation
        if (debugConfiguration.type === DebugType.join && debugConfiguration.joinUniqueId) {
            return debugConfiguration;
        }

        if (debugConfiguration.type !== DebugType.join) {
            if (DebugType.share === debugConfiguration.type) {
                debugConfiguration = debugConfiguration.adapterProxy.configuration;
            }

            return await this.launchRemoteDebugConfiguration(folder, debugConfiguration);
        }

        // Note: if no debugSession object is found mean the launch is being initiated by a 'restart' action
        // and so we would need to locate the shared debug session that should exists (otherwise we can't proceed)
        if (!debugConfiguration.debugSession) {
            // Terminated debug sessions get removed from the list of sharedDebugSessions in onDidTerminateDebugSession
            // There is no guarantee that this will happen before the call to resolveDebugConfiguration in the restart scenario.
            // Thus, if a targetDebugSession is found also check if the debugConfiguration has a launchUniqueId. When this is present this
            // is a guest `Restart` from a guest initiated debug session. In this scenario we always want to launch the remote debug configuration.
            const targetDebugSession = this.sharedDebugSessions.find(ds => {
                const name = (ds.configurationProperties && ds.configurationProperties.name) ? ds.configurationProperties.name : ds.name;
                return name === debugConfiguration.name;
            });
            if (!targetDebugSession ||
                (targetDebugSession.configurationProperties && targetDebugSession.configurationProperties.launchUniqueId)) {
                // this restart may have been initiated by our session and so implies the shared debug session was terminated
                return await this.launchRemoteDebugConfiguration(folder, debugConfiguration);
            }

            debugConfiguration = this.toDebugConfiguration(targetDebugSession);
        }

        debugConfiguration.joinUniqueId = this.joinUniqueId;
        await this.setupDebugConfiguration(debugConfiguration);
        return debugConfiguration;
    }

    /*
    Return the available debug sessions that can be started by looking on the shared debug sessions
    and filter the already joined sessions
    */
   public getAvailableDebugSessions(): vsls.DebugSession[] {
        return this.sharedDebugSessions.filter(i => {
            return !this.activeJoinedDebugSessions.has(i.sessionId);
        });
    }

    public async joinDebugSession(debugSession: vsls.DebugSession): Promise<void> {
        const folders = vscode.workspace.workspaceFolders;
        activitySource.fire({
            timestamp: new Date(),
            name: `${ActivityType.debug}/join`,
        });
        let options: vscode.DebugSessionOptions = undefined
        const parentId = debugSession?.configurationProperties?.__parentId;
        if (parentId) {
            const parentSession = this.activeJoinedDebugSessions.get(parentId);
            if (parentSession) {
                options = {
                    parentSession: parentSession,
                    compact: true
                };
            } else {
                this.delayedStartDebugSessions.push(debugSession);
                return;
            }
        }
        await vscode.debug.startDebugging(folders ? folders[0] : undefined, this.toDebugConfiguration(debugSession), options);
    }

    public async onReadFile(fileTextInfo: vsls.FileTextInfo): Promise<void> {
        const { moniker } = PathUtil.getMonikerFromRelativePath(fileTextInfo.path);

        // The reason we're injecting contents of the  .vscode/launch.json file
        // is to ensure that when connected to VS, we have information to work
        // with that allows us to start a debugger session. Since VS Projects all
        // it's debug information through tasks or debugger info in the _primary_
        // root, we don't need to do anything if this this isn't the primary root:
        // The default file system information represents the truth.
        //
        // Note, it's not possible to just rely on _not_injecting the file in
        // read directory or stat calls, since there are times that VS Code
        // directly tries to read the file.
        if (moniker !== '0' && moniker) {
            return;
        }


        // If the file exists, we don't have anything to return, or it's not a file we care about
        // let the request pass through unmodified, since it's reporting accurate
        // information already.
        if (!this.isLaunchConfigurationsExists() || fileTextInfo.path !== JoinDebugManager.vscodeLaunchPath) {
            return;
        }

        // for the existance of this file
        fileTextInfo.exists = true;
        const isLaunchText = typeof this.rawLaunchConfigurationData === 'string';
        fileTextInfo.text = isLaunchText ? this.rawLaunchConfigurationData.toString() : JSON.stringify(this.rawLaunchConfigurationData, null, 4);

        // if launch configurations is not a raw text we don't want co-editing to start, hence the 'hidden' attribute
        fileTextInfo.attributes = isLaunchText ? undefined : vsls.FileAttributes.Hidden;
    }

    public async onReadDirectory(fileInfos: vsls.FileInfo[]): Promise<void> {
        if (fileInfos.length < 1 || !this.isLaunchConfigurationsExists()) {
            return;
        }

        const fileInfoItem = fileInfos[0];
        const { moniker } = PathUtil.getMonikerFromRelativePath(fileInfoItem.path);

        // The reason we're injecting the .vscode folder & the .vscode/launch.json
        // file is to ensure that when connected to VS, we have information to work
        // with that allows us to start a debugger session. Since VS Projects all
        // it's debug information through tasks or debugger info in the _primary_
        // root, we don't need to do anything if this this isn't the primary root:
        // The default file system information represents the truth.
        if (moniker !== '0' && moniker) {
            return;
        }

        // Ensure that there is always '.vscode' directory presended to the
        // guest, even if one doesn't exist. We do this by inserting one into
        // the list of of directories
        if (fileInfoItem.path === '/' && !fileInfoItem.children.some((fi) => fi.path === JoinDebugManager.vscodePath)) {
            fileInfoItem.children.push(
                <vsls.FileInfo> {
                    path: JoinDebugManager.vscodePath,
                    isDirectory: true,
                    hasChildren: true
                });
            return;
        }

        // When the '.vscode' directory is being read to ensure that there is
        // a launch.json file available, even if there isn't one physically present
        if ((fileInfoItem.path !== JoinDebugManager.vscodePath)
            || (fileInfoItem.children && fileInfoItem.children.find((fi) => fi.path === JoinDebugManager.vscodeLaunchPath))) {
            return;
        }

        // no launch.json exists on host but we still want to return one
        fileInfoItem.exists = true;
        fileInfoItem.isDirectory = true;
        const launchFileInfo: vsls.FileInfo = {
            path: JoinDebugManager.vscodeLaunchPath,
            isDirectory: false,
            hasChildren: false
        };

        if (!fileInfoItem.children) {
            fileInfoItem.children = [];
        }

        fileInfoItem.children.push(launchFileInfo);
        return;
    }

    public async onStat(fileInfos: vsls.FileInfo[]): Promise<void> {
        const fileInfoItem = fileInfos[0];
        // File exists, then theres nothing for us to do, or if we have no
        // configuration to lie about.
        if ((!fileInfoItem || fileInfoItem.exists) || !this.isLaunchConfigurationsExists()) {
            return;
        }

        const { moniker } = PathUtil.getMonikerFromRelativePath(fileInfoItem.path);

        // The reason we're injecting contents of the  .vscode/launch.json file
        // is to ensure that when connected to VS, we have information to work
        // with that allows us to start a debugger session. Since VS Projects all
        // it's debug information through tasks or debugger info in the _primary_
        // root, we don't need to do anything if this this isn't the primary root:
        // The default file system information represents the truth.
        //
        // Note, it's not possible to just rely on _not_injecting the file in
        // read directory calls, since there are times that VS Code directly
        // tries to stat the file.
        if ((moniker !== '0' && moniker)
         || (fileInfoItem.path !== JoinDebugManager.vscodePath && fileInfoItem.path !== JoinDebugManager.vscodeLaunchPath)) {
            return;
        }

        fileInfoItem.exists = true;
        fileInfoItem.mtime = new Date(0);
        fileInfoItem.isDirectory = (fileInfoItem.path === JoinDebugManager.vscodePath);

        return;
    }

    public canAttach() {
        return this.getAvailableDebugSessions().length > 0;
    }

    public async attach(): Promise<void> {
        if (sessionStateTracker.State !== SessionState.Joined) {
            throw new Error('Not currently in a collaboration session.');
        }

        let debugSessions = this.getAvailableDebugSessions();
        if (debugSessions.length === 0) {
            await vscode.window.showInformationMessage('No debug session available to join');
            return;
        }

        if (debugSessions.length === 1) {
            await ExtensionUtil.runWithProgress(
                () => this.joinDebugSession(debugSessions[0]),
                { title: 'Joining Debug Session...' });
        } else {
            let items: any = [];
            debugSessions.forEach((d) => {
                items.push({
                    label: d.name
                });
            });
            let selection = (await vscode.window.showQuickPick(items, { placeHolder: 'Select the debug session' })) as any;
            if (selection) {
                let debugSession = debugSessions.filter(item => item.name === selection.label)[0];
                await ExtensionUtil.runWithProgress(
                    () => this.joinDebugSession(debugSession),
                    { title: 'Joining Debug Session...' });
            }
        }
    }

    protected setupDebugConfiguration(debugConfiguration: vscode.DebugConfiguration): Promise<void> {
        return Promise.resolve();
    }

    protected async launchRemoteDebugConfiguration(workspaceFolder: vscode.WorkspaceFolder, debugConfiguration: vscode.DebugConfiguration): Promise<vscode.DebugConfiguration> {
        // Verify if not in read-only mode
        const sessionId = this.sessionContext.coeditingClient.clientID;
        await this.clientAccessCheck.verifyCanPerformOperation(sessionId, JoinDebugManager.launchDebugOperation);

        // find the original 'raw' debug configuration without any 'injection' from a provider
        const configurationForRoot = this.unmodifiedLaunchConfigurations.get(workspaceFolder ? workspaceFolder.index.toString() : '0');
        // We haven't had any configurations yet, so lets just inform VS Code that
        // we don't have anything to offer, and let it fall back to generating
        // launch.json. This can happen sometimes, depending on state (e.g. nodejs
        // app that supports automatic debugging)
        if (!configurationForRoot) {
            return null;
        }

        let rawDebugConfiguration = configurationForRoot.find(lc => lc.name === debugConfiguration.name);

        if (rawDebugConfiguration) {
            const remoteDebugConfiguration: any = {};
            Object.assign(remoteDebugConfiguration, rawDebugConfiguration);

            // inject launch unique id to allow terminate on disconnect
            remoteDebugConfiguration.launchUniqueId = this.joinUniqueId;

            // inject noDebug property from the requested configuration
            if (debugConfiguration.noDebug) {
                remoteDebugConfiguration.noDebug = true;
            }

            if (workspaceFolder) {
                remoteDebugConfiguration.__workspaceIndex = workspaceFolder.index;
            }

            // invoke remote launch using the RPC service
            try {
                await this.debuggerHostService.launchDebugSessionAsync(remoteDebugConfiguration);
            } catch (error) {
                if (error instanceof ResponseError && error.code === vsls.ErrorCodes.RemoteLaunchNotEnabled) {
                    await vscode.window.showInformationMessage(ExtensionUtil.getErrorString(vsls.ErrorCodes.RemoteLaunchNotEnabled));
                } else {
                    throw error;
                }
            }

            // Return `undefined` to abort the remote launch and prevent launch.json from appearing
            return undefined;
        }

        return null;
    }

    private async onDidStartDebugSession(eventData: vscode.DebugSession): Promise<void> {
        if (eventData.type === DebugType.join) {
            this.trace.info(`Starting joined debug session:${eventData.id} name:${eventData.name}`);

            // store the shared debug session id and the vsCode debug session
            let response = await eventData.customRequest(DebugAdapterCustomRequest.debugSessionId);
            let sharedDebugSessionId = response.Id;
            this.activeJoinedDebugSessions.set(sharedDebugSessionId, eventData);

            // Note: if we just receive the event on our joined debug session, it could
            // happen that the shared debug session is already finished
            let sessionIsActive = true;
            if (!this.sharedDebugSessions.find( (d) => d.sessionId === sharedDebugSessionId)) {
                this.trace.verbose(`Terminate ${eventData.id} due to removed shared debug session id:${sharedDebugSessionId}`);
                eventData.customRequest(DebugAdapterCustomRequest.forceTerminate);
                sessionIsActive = false;
            }

            this.delayedStartDebugSessions = this.delayedStartDebugSessions.filter(session => {
                if (session.configurationProperties.__parentId == sharedDebugSessionId) {
                    if(sessionIsActive){
                        this.joinDebugSession(session);
                    }
                    return false;
                }
                return true;
            });
        }
    }

    private onDidTerminateDebugSession(eventData: vscode.DebugSession) {
        if (eventData.type === DebugType.join) {
            this.trace.info(`Terminate joined debug session:${eventData.id}`);
            for (let [key, value] of this.activeJoinedDebugSessions) {
                if (value.id === eventData.id) {
                    this.activeJoinedDebugSessions.delete(key);
                    this.sharedDebugSessions.forEach(session => {
                        if (session.configurationProperties.__parentId == key) {
                            const child = this.activeJoinedDebugSessions.get(session.sessionId);
                            child.customRequest(DebugAdapterCustomRequest.forceTerminate);
                        }
                    });

                    // Note: next code will attempt to remove the shared debug session if it was launched by us
                    // and has just been terminated. This will help the code that detect a restart scenario when
                    // resolving debug configurations
                    const indexSharedSession = this.sharedDebugSessions.findIndex(ds =>
                        ds.configurationProperties && ds.sessionId === key &&  ds.configurationProperties.launchUniqueId === this.joinUniqueId);
                    if (indexSharedSession >= 0) {
                        this.sharedDebugSessions.splice(indexSharedSession);
                    }

                    break;
                }
            }
        }
    }

    private get joinDebugSessionOptionValue(): JoinDebugSessionOption {
        const joinDebugSessionOptionSetting = Settings.get<string>(SettingKeys.joinDebugSessionOption)
        return (<any>JoinDebugSessionOption)[joinDebugSessionOptionSetting];
    }

    protected toDebugConfiguration(debugSession: vsls.DebugSession): vscode.DebugConfiguration {
        const isLaunch = debugSession.configurationProperties &&
            debugSession.configurationProperties.launchUniqueId === this.joinUniqueId;
        const noDebug = debugSession.configurationProperties &&
            debugSession.configurationProperties.noDebug;
        return {
            type: DebugType.join,
            request: isLaunch ? 'launch' : 'attach',
            name: debugSession.name,
            noDebug: noDebug,
            debugSession: debugSession,
            debugServer: Settings.get<number>('debugAdapter'),
            enableMultipleRoots: true
        };
    }

    private async onDebugSessionChanged(eventData: vsls.DebugSessionChangedEventArgs): Promise<void> {
        if (eventData.changeType === vsls.DebugSessionChangeType.Add) {
            this.trace.info(`Host debug session started:${eventData.debugSession.sessionId}`);
            this.sharedDebugSessions.push(eventData.debugSession);
            if (this.joinDebugSessionOptionValue === JoinDebugSessionOption.Automatic) {
                await this.joinDebugSession(eventData.debugSession);
            } else if (this.joinDebugSessionOptionValue === JoinDebugSessionOption.Prompt) {
                const result = await vscode.window.showInformationMessage(
                    `The host has started a collaborative debugging session ('${eventData.debugSession.name}') that you can join`, { title: 'Join session now' });
                if (result) {
                    if (this.isDebugSessionValid(eventData.debugSession)) {
                        await this.joinDebugSession(eventData.debugSession);
                    }
                }
            }
       } else if (eventData.changeType === vsls.DebugSessionChangeType.Remove) {
            const debugSessionId = eventData.debugSession.sessionId;
            this.trace.info(`Host debug session removed:${debugSessionId}`);
            // track the shared debugged sessions
            const index = this.sharedDebugSessions.findIndex( (d) => d.sessionId === debugSessionId);
            if (index >= 0) {
                this.sharedDebugSessions.splice(index, 1);
            }

            // if we have a joined debug session make sure we terminate it
            if (this.activeJoinedDebugSessions.has(eventData.debugSession.sessionId)) {
                this.trace.verbose(`Attempt to terminate joined debug session:${eventData.debugSession.sessionId}`);
                await this.activeJoinedDebugSessions.get(eventData.debugSession.sessionId).customRequest('forceTerminate');
            }
       }
    }

    private isDebugSessionValid(debugSession: vsls.DebugSession): boolean {
        return this.sharedDebugSessions.find( (d) => d.sessionId === debugSession.sessionId) !== undefined;
    }

        /**
     * Sets the actual launch configurations from the 'raw' information provided
     * by the host. We want to hold onto this information, rather than take the
     * info that comes when resolve/launching so that any properties that have
     * been injected by _local_ adapters/extensions aren't pushed to the host.
     * 
     * Additionally, rather than look up the "name" and hope things are OK, there
     * are times we want to inject information on the host via the guest. NoDebug
     * is a good example of something we want to add.
     * 
     * So, we store the raw configs for us to pass along when we _actually_ begin
     * the debugging session.
     */
    private setLaunchConfigurations(rawLaunchConfiguration: string | object) {
        this.unmodifiedLaunchConfigurations = new Map();
        this.rawLaunchConfigurationData = rawLaunchConfiguration;
        
        if (!rawLaunchConfiguration) {
            return;
        }

        let launchContentObject: any = rawLaunchConfiguration;
        if (typeof rawLaunchConfiguration === 'string') {
            try {
                // Use jsonc so we handle comments in launch configurations
                launchContentObject = JSON.parse(stripJsonComments(<string>rawLaunchConfiguration));
            } catch {
                return;
            }
        }

        this.unmodifiedLaunchConfigurations.set('0', launchContentObject.configurations instanceof Array ? launchContentObject.configurations : []);

        if (!launchContentObject.configurationsByRoot) {
            return;
        }

        // It was multiroot, so extract the per-root configurations
        const configurationsByRoot: { [key: string]: any } = launchContentObject.configurationsByRoot;
        const rootkeys = Object.keys(configurationsByRoot);
        for (let key of rootkeys) {
            const root = configurationsByRoot[key];
            if (!root || !(root.configurations instanceof Array)) {
                continue;
            }

            this.unmodifiedLaunchConfigurations.set(key, root.configurations);
        }
    }

    private isLaunchConfigurationsExists(): boolean {
        return this.rawLaunchConfigurationData != null;
    }

    private onLaunchConfigurationsChanged(eventData: vsls.LaunchConfigurationChangedEventArgs): void {
        // update launch configurations
        this.setLaunchConfigurations(eventData.launchConfigurations);

        const workspaceProvider = this.fileSystemManager.workspaceProvider;
        if (workspaceProvider) {
            this.fireLaunchConfigurationsChanged(workspaceProvider);
        }
    }

    private fireLaunchConfigurationsChanged(workspaceProvider: IWorkspaceFileSystemProvider) {
        // fire file system event in case debugger want to refresh the combo box options
        const launchFileChanged = {
            type: vscode.FileChangeType.Changed,
            uri: this.pathManager.relativePathToLocalPath(JoinDebugManager.vscodeLaunchPath)
        } as vscode.FileChangeEvent;
        workspaceProvider.fireFilesChanged([launchFileChanged]);
    }
}