import * as vscode from 'vscode';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';

import { NotificationUtil } from '@vs/vscode-command-framework';
import { ExtensionUtil } from './ExtensionUtil';

export async function askToSignInAndReload(
    question: string,
    dontShowAgainName?: string) {
    const MEMENTO_NAME = dontShowAgainName;

    if (MEMENTO_NAME) {
        const isRequestedToNotShowAnymore = ExtensionUtil.context.globalState.get<boolean>(MEMENTO_NAME);
        if (isRequestedToNotShowAnymore) {
            return;
        }
    }

    const signInAgainItem = 'Sign In';
    const dontShowAgain = 'Don\'t show again';
    const items = [signInAgainItem];

    if (MEMENTO_NAME) {
        items.push(dontShowAgain);
    }

    const questionResult = await NotificationUtil.showInformationMessage(question, false, ...items);

    if (questionResult === signInAgainItem) {
        await vscode.commands.executeCommand(`${Settings.get<string>(SettingKeys.commandPrefix)}.signInAndReload`);
    }

    if (questionResult === dontShowAgain) {
        if (ExtensionUtil.context) {
            await ExtensionUtil.context.globalState.update(MEMENTO_NAME!, true);
        }
    }
}