import * as rpc from 'vscode-jsonrpc';
import { DisposableClass, createDisposable, IDisposable } from '@vs/vscs-utils';
import { WorkspaceMetricsUpdated, HostConnectionChanged } from './IWorkspaceConnection';
import { IWorkspaceClient, CheckConnectionOptions } from './IWorkspaceClient';
import { checkWorkspaceClient } from './checkWorkspaceClient';
import { RpcClient, ServiceInfo, IRpcClient, IChannel, RpcProxyCache } from '@vs/vso-rpc';

import { ILogger } from '@vs/vso-logging';
import { WorkspaceSessionInfo } from '@vs/vsls-contracts/src/contracts/VSLS';
import { IJoinConnectOptions } from './IJoinConnectOptions';

/**
 * A base class to implement the IWorkspaceClient interface contract.
 */
export abstract class WorkspaceClientBase extends DisposableClass implements IWorkspaceClient {
    protected readonly onHostConnectionChangedEmitter = new rpc.Emitter<HostConnectionChanged>();
    public readonly onHostConnectionChanged = this.onHostConnectionChangedEmitter.event;

    protected readonly onWorkspaceMetricsUpdatedEmitter = new rpc.Emitter<
        WorkspaceMetricsUpdated
    >();
    public readonly onWorkspaceMetricsUpdated = this.onWorkspaceMetricsUpdatedEmitter.event;

    private readonly rpcProxyCache: RpcProxyCache;
    private checkConnectionDisposable: IDisposable | undefined;

    constructor(protected rcpClientInstance: RpcClient, logger: ILogger) {
        super(logger);
        this.rpcProxyCache = new RpcProxyCache(this.rcpClientInstance, logger);
        this.addToDisposables(
            createDisposable(() => {
                this.stopCheckConnection('disposed');
            })
        );
    }

    public abstract join(joinConnectOptions: IJoinConnectOptions): Promise<WorkspaceSessionInfo>;

    public abstract checkConnection(cancellationToken?: rpc.CancellationToken): Promise<void>;

    public abstract openStreamingChannel(
        streamId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<IChannel>;

    public abstract disconnect(): Promise<void>;

    public get rpcClient(): IRpcClient {
        return this.rcpClientInstance;
    }

    public getServiceProxy<T>(serviceInfo: ServiceInfo<T>, traceName?: string): T {
        return this.rpcProxyCache.getOrCreate(serviceInfo, traceName);
    }

    public setCheckConnectionOptions(options: CheckConnectionOptions): Promise<void> {
        if (options.enabled && this.checkConnectionDisposable === undefined && !this.isDisposed) {
            this.ensureIsJoined();
            this.checkConnectionDisposable = checkWorkspaceClient(
                this,
                this.trace,
                options.metricsTimeout,
                options.checkConnectionTimeout,
                () => this.canCheckConnection()
            );
        } else if (!options.enabled) {
            this.stopCheckConnection('connection options');
        }

        return Promise.resolve();
    }

    protected ensureIsJoined(): void {}

    protected canCheckConnection(): boolean {
        return true;
    }

    private stopCheckConnection(reason: string) {
        this.trace.info(`stopCheckConnection reason:'${reason}'`);
        if (this.checkConnectionDisposable !== undefined) {
            this.checkConnectionDisposable.dispose();
            this.checkConnectionDisposable = undefined;
        }
    }
}
