import { ICommandContext } from '@vs/vscode-command-framework';

import { sessionStateTransitionsCommandDecorator } from '../decorators/SessionStateTransitionsCommandDecorator';
import { authenticationCommandDecorator, IAuthenticationDecoratorOptions } from '../decorators/AuthenticationCommandDecorator';
import { validationCommandDecorator } from '../decorators/ValidationCommandDecorator';
import { errorNotificationCommandDecorator } from '../decorators/ErrorNotificationCommandDecorator';
import { telemetryCommandDecorator } from '../decorators/TelemetryCommandDecorator';
import { telemetryStatusCommandDecorator } from '../decorators/TelemetryStatusCommandDecorator';
import { cancellationDecorator } from '../decorators/CancellationDecorator';
import { ICommand } from '../abstractions/ICommand';
import { SessionAction } from '../SessionTypes';
import { TelemetryEventNames } from '../telemetry/TelemetryStrings';

export function builder(): SignInCommand {
    return new SignInCommand();
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.AttemptSignIn,
    authAttemptMax: 1
};

/**
 * Sign-in `command` for authentication purposes.
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Signing in', TelemetryEventNames.SIGN_IN_FAULT_EXPLICIT)
@telemetryCommandDecorator(TelemetryEventNames.SIGN_IN_EXPLICIT, TelemetryEventNames.SIGN_IN_FAULT_EXPLICIT, 'ExplicitSignIn')
@telemetryStatusCommandDecorator()
@validationCommandDecorator()
@sessionStateTransitionsCommandDecorator(SessionAction.AttemptSignIn, SessionAction.SignInSuccess, SessionAction.SignInError)
@authenticationCommandDecorator(authOptions)
export class SignInCommand implements ICommand<boolean> {
    public async invoke(options: any, context: ICommandContext): Promise<boolean> {
        // the body is empty since this is a `SignIn` command that is responsibble for authentication only,
        // and the authentication happends in the `authenticationCommandDecorator` above
        return false;
    }
}
