import * as vscode from 'vscode';
import { 
    CommandId,
    getExpService,
    Lazy, 
    lazyLoad,
    TreatmentVariables, 
} from '@vs/liveshare-core';
import { traceSource } from '@vs/vscode-command-framework';
import { once } from '@vs/vscs-utils';

/** Get workspace id for the joining guest, or undefined if it's not a guest session. */
export const getJoiningWorkspaceId = lazyLoad(() => 
    vscode.workspace.getConfiguration().get<string>(CommandId.joinWorkspaceIdSettingName));

/**
 * Return true if the workspace client join is enabled
 */
export const isWorkspaceClientJoin = once(() => {
    const isEnabled = !!getExpService()?.getTreatmentVariable(TreatmentVariables.VSCodeConfig, 'workspace-client-join');
    if (isEnabled) {
        traceSource.info('Experiment on workspace client join enabled');
    }
    
    return isEnabled;
});


/** Get a value indicating if this is a guest session.
 *  Guest session is a VSC session where vscode.workspace.getConfiguration().get<string>(CommandId.joinWorkspaceIdSettingName) is defined. 
 */
export function isJoinActivated(): boolean {
    return isWorkspaceClientJoin() && !!getJoiningWorkspaceId();
}

export function onlyNonJoinedLazyLoad<T>(loader: () => T): Lazy<T> {
    return twoWayLazyLoad(undefined, loader);
}

function twoWayLazyLoad<T>(joinLoader: (() => T) | undefined | Error, nonJoinLoader: (() => T) | undefined | Error): Lazy<T> {
    return lazyLoad<T>(() => {
        if (isJoinActivated()) {
            if (joinLoader === undefined) {
                throw Error('This service is not available in a guest session');
            }

            if (typeof joinLoader === 'function') {
                return joinLoader();
            }

            throw joinLoader;

        } else {
            if (nonJoinLoader == null) {
                throw Error('This service is available only in a guest session');
            }

            if (typeof nonJoinLoader === 'function') {
                return nonJoinLoader();
            }

            throw nonJoinLoader;
        }
    });
}