import * as nls from 'vscode-nls';
import * as vscode from 'vscode';
import * as path from 'path';

enum ContactViewItem {
    // contacts
    SuggestedContacts = 'contacts.suggested',
    AvailableContacts = 'contacts.available',
    ContactsProvider = 'contacts.provider',
    SelfContact = 'contacts.selfContact',
    Contact = 'contacts.contact',
    ContactInvited = 'contacts.contact.invited',
    ContactOffline = 'contacts.contact.offline',
    RecentContact = 'contacts.recentContact',
    RecentContactOffline = 'contacts.recentContact.offline',
    RecentContactInvited = 'contacts.recentContact.invited',
    NoContact = 'contacts.noContact',
    RecentContacts = 'contacts.RecentContacts',
    NoSuggestedContacts = 'contacts.NoSuggestedUsers',
    NoRecentContacts = 'contacts.NoRecentContacts',
    InvitedContact = 'contacts.invited',
}

import { ContactManager, PublishProperties } from './ContactManager';
import { ContactServiceManager } from './ContactServiceManager';
import { defaultCompareContacts } from './defaultCompareContacts';

import {
    ISessionContext,
    SessionState,
    CollaboratorChangedEventArgs,
    TreeViewItem,
    TreeViewItemOptions,
    localize,
    IContactModel,
    ExtensionUtil,
    ContactManagerEvents,
} from '@vs/liveshare-core';
import { vsls, contactProtocol } from '@vs/vsls-contracts';
export class ContactsProviderViewlet implements vscode.TreeDataProvider<TreeViewItem> {
    private changeEventEmitter = new vscode.EventEmitter<TreeViewItem | undefined>();
    public readonly onDidChangeTreeData = this.changeEventEmitter.event;

    private joinedUserProfiles = new Map<string, vsls.WorkspaceUserProfile>();

    constructor(
        private sessionContext: ISessionContext) {
        ContactManager.addListener(ContactManagerEvents.ContactsChanged, this.refresh);
        ContactManager.addListener(ContactManagerEvents.SuggestedUsersUpdate, this.refresh);
        ContactManager.addListener(ContactManagerEvents.RecentContactsUpdate, this.refresh);
        ContactManager.addListener(ContactManagerEvents.InviteContactsUpdate, this.refresh);
        this.sessionContext.onCollaboratorChanged(e => this.onCollaboratorChanged(e));
    }

    public refresh = (): void => {
        this.changeEventEmitter.fire(undefined);
    }

    public getTreeItem(element: TreeViewItem): vscode.TreeItem { return element; }

    public async getChildren(element?: ContactServiceExplorerItem): Promise<TreeViewItem[]> {
        if (element) {
            return await this.getElementChildren(element);
        }

        return await this.getDefaultRootChildren();
    }

    private async getElementChildren(element: TreeViewItem): Promise<TreeViewItem[]> {
        switch (element.contextValue) {
            case ContactViewItem.SuggestedContacts:
                return this.getSuggestedUsersChildren();
            case ContactViewItem.RecentContacts:
                return this.getRecentContactsChildren();
            case ContactViewItem.ContactsProvider:
                return this.getContactServiceChildren((<ContactServiceExplorerItem>element).contactServiceManager);
            case ContactViewItem.AvailableContacts:
                return this.getAvailableContactsChildren((<ContactServiceExplorerItem>element).contactServiceManager);
            case ContactViewItem.NoRecentContacts:
            case ContactViewItem.NoSuggestedContacts:
                return [
                    new TreeViewItem({
                        type: ContactViewItem.NoContact,
                        label: 'Invite participants...',
                        command: {
                            title: 'Invite participants...',
                            command: 'liveshare.inviteNoUserJoinByEmail'
                        }        
                    })
                ];
            default:
                return [];
        }
    }

    private createContactTreeExplorerItem(contactServiceManager: ContactServiceManager, contactModel: IContactModel, treeItemType: ContactViewItem) {
        const status = ContactsProviderViewlet.getPresenceStatusName(contactModel);
        let tooltip = `${contactModel.contact.displayName} - ${status} (${contactModel.contact.email})`;

        const addPropertyText = (property: string, shouldDisplay: (value: any) => boolean, format: (value: any) => void ) => {
            const value = contactModel.properties[property];
            if (value && shouldDisplay(value)) {
                format(value);
            }
        };

        addPropertyText(PublishProperties.LiveshareStatus, v => {
            const state: SessionState = v;
            return state === SessionState.Joined || state === SessionState.Shared;
        }, v => {
            const inLiveshareSessionMsg = localize('extension.liveshare.InLiveShareSession');
            tooltip = `${contactModel.contact.displayName} - ${inLiveshareSessionMsg} (${contactModel.contact.email})`;
        });

        addPropertyText(PublishProperties.WorkspaceName, v => v !== '', v => tooltip += `\nWorkspace: ${v}`);
        const treeItem = new ContactTreeExplorerItem(
            contactModel,
            contactServiceManager, {
            type: treeItemType,
            label: `${contactModel.contact.displayName}`,
            tooltip,
            iconPath: this.getPresenceIconUri(contactModel)
        });

        return treeItem;
    }

    private getContactModelChildren(contactModels: Array<IContactModel>, viewItemSelector: (contactModel: IContactModel) => ContactViewItem): ContactTreeExplorerItem[] {
        const items = contactModels.sort(defaultCompareContacts);

        return items.map(c => {
            const contactServiceManager = ContactManager.getServiceManager(c.serviceId);
            return this.createContactTreeExplorerItem(contactServiceManager, c, viewItemSelector(c));
       });
    }

    private onCollaboratorChanged(e: CollaboratorChangedEventArgs) {
        if (e.changeType === vsls.WorkspaceSessionChangeType.Joined) {
            this.joinedUserProfiles.set(e.userProfile.id, e.userProfile);
        } else if (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined || e.changeType === vsls.WorkspaceSessionChangeType.Canceled) {
            this.joinedUserProfiles.delete(e.userProfile.id);
        }

        this.refresh();
   }

    private getSuggestedUsersChildren(): ContactTreeExplorerItem[] {
        return this.getContactModelChildren(ContactManager.getSuggestedUsers(), (c) =>
            this.isContactCollaborator(c) || ContactManager.isContactInvited(c.id) ?
            ContactViewItem.ContactInvited : // suggested 'invited' contact
            ContactsProviderViewlet.isContactOffline(c) ? ContactViewItem.ContactOffline : ContactViewItem.Contact);
    }

    private getRecentContactsChildren(): ContactTreeExplorerItem[] {
        return this.getContactModelChildren(ContactManager.getRecentContacts(), (c) =>
            this.isContactCollaborator(c) || ContactManager.isContactInvited(c.id) ?
            ContactViewItem.RecentContactInvited : // recent 'invited' contact
            ContactsProviderViewlet.isContactOffline(c) ? ContactViewItem.RecentContactOffline : ContactViewItem.RecentContact);
    }

    private getAvailableContactsChildren(contactServiceManager: ContactServiceManager): ContactTreeExplorerItem[] {
        return ContactsProviderViewlet.getContactsWithPresence(contactServiceManager.availableUsers).map((u) => this.createContactTreeExplorerItem(contactServiceManager, u, ContactViewItem.Contact));
    }

    private getCollaborators(): Array<vsls.WorkspaceUserProfile> {
        return Object.values(this.sessionContext.collaboratorManager.getCollaborators());
    }

    private isContactCollaborator(contactModel: IContactModel): boolean {
        if (!this.sessionContext.collaboratorManager) {
            return false;
        }

        const collaboratorsUserProfiles = this.getCollaborators().filter(u => !u.isOwner)
                                .concat(Array.from(this.joinedUserProfiles.values()));
        const matchCollaboratorProfile = collaboratorsUserProfiles.find(userProfile => 
            userProfile.id === contactModel.id ||
            userProfile.email === contactModel.contact.email);
        return matchCollaboratorProfile !== undefined;
    }

    private getContactServiceChildren(contactServiceManager: ContactServiceManager) {

        let items = [];
        if (contactServiceManager.capabilites.supportsAvailableContacts) {
            const availableUsersItem = new ContactServiceExplorerItem(
                contactServiceManager, {
                type: ContactViewItem.AvailableContacts,
                collapsibleState: vscode.TreeItemCollapsibleState.Collapsed,
                label: `Available contacts (${ ContactsProviderViewlet.getContactsWithPresence(contactServiceManager.availableUsers).length })`,
            });
            items.push(availableUsersItem);
        }

        const selfUser = contactServiceManager.selfUser;
  
        if (selfUser) {
            const selfUserItem = new ContactTreeExplorerItem(
                selfUser,
                contactServiceManager, {
                type: ContactViewItem.SelfContact,
                label: `${selfUser.contact.displayName} - ${ContactsProviderViewlet.getPresenceStatusName(selfUser)}`,
                iconPath: this.getPresenceIconUri(selfUser)
            });
            items.unshift(selfUserItem);
        }

        return items;
    }

    private async getDefaultRootChildren() {
        const items: TreeViewItem[] = [];
        const suggestedUsers = ContactManager.getSuggestedUsers();
        const recentContacts = ContactManager.getRecentContacts();

        const hasRecentContacts = recentContacts.length > 0;

        const recentContactsItem = new TreeViewItem({
            type: hasRecentContacts ? ContactViewItem.RecentContacts : ContactViewItem.NoRecentContacts,
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            label: `Recent contacts (${ recentContacts.length })`
        });
        items.push(recentContactsItem);

        const hasSuggestedContacts = suggestedUsers.length > 0;
        const suggestedUsersItem = new TreeViewItem({
            type: hasSuggestedContacts ? ContactViewItem.SuggestedContacts : ContactViewItem.NoSuggestedContacts,
            collapsibleState: vscode.TreeItemCollapsibleState.Expanded,
            label: `Suggested contacts (${ suggestedUsers.length })`
        });
        items.push(suggestedUsersItem);

        return items;
    }

    private static getPresenceIcon(contactModel: IContactModel): string {
        switch (contactModel.contact.status) {
            case contactProtocol.PresenceStatus.Available:
                return 'available.svg';
            case contactProtocol.PresenceStatus.DoNotDisturb:
                return 'dnd.svg';
            case contactProtocol.PresenceStatus.Away:
                return 'away.svg';
            case contactProtocol.PresenceStatus.Busy:
                return 'busy.svg';
            default:
                return 'invisible.svg';
        }
    }

    private getPresenceIconUri(contactModel: IContactModel): string | vscode.Uri {
        return ExtensionUtil.getExtensionUri(path.join('images', 'presence', ContactsProviderViewlet.getPresenceIcon(contactModel)));
    }

    private static getContactsWithPresence(contacts: Array<IContactModel>): Array<IContactModel> {
        return contacts.filter(c => c.contact.status !== contactProtocol.PresenceStatus.Offline);
    }

    public static getPresenceStatusName(contactModel: IContactModel): string {
        return ContactsProviderViewlet.toPresenceStatusName(contactModel.contact.status);
    }

    public static toPresenceStatusName(presenceStatus: contactProtocol.PresenceStatus): string {
        switch (presenceStatus) {
            case contactProtocol.PresenceStatus.Available:
                return 'Available';
            case contactProtocol.PresenceStatus.DoNotDisturb:
            return 'Do not disturb';
            case contactProtocol.PresenceStatus.Away:
                return 'Away';
            case contactProtocol.PresenceStatus.Busy:
                return 'Busy';
            case contactProtocol.PresenceStatus.Offline:
            default:
                return 'Offline';
        }
    }

    public static isContactOffline(contactModel: IContactModel): boolean {
        const presenceStatus = contactModel.contact.status;
        return  presenceStatus === undefined ||
            presenceStatus === contactProtocol.PresenceStatus.Offline ||
            presenceStatus === contactProtocol.PresenceStatus.Unknown;
    }
}

export class ContactServiceExplorerItem extends TreeViewItem  {
    constructor(public contactServiceManager: ContactServiceManager, options: TreeViewItemOptions) {
        super(options);
    }
}

export class ContactTreeExplorerItem extends ContactServiceExplorerItem  {
    constructor(
        public contactModel: IContactModel,
        contactServiceManager: ContactServiceManager, options: TreeViewItemOptions) {
        super(contactServiceManager, options);
    }
}
