import { ICommandContext } from '@vs/vscode-command-framework';

import { ICommand } from '../abstractions/ICommand';
import { IDependencies } from '../contracts/IDependencies';
import { IWorkspaceAccessControlManager } from '../contracts/IWorkspaceAccessControlManager';
import { ParticipantSessionExplorerItem } from '../treeViews/ParticipantsTreeDataProvider';
import { telemetryCommandDecorator } from '../decorators/TelemetryCommandDecorator';
import { errorNotificationCommandDecorator } from '../decorators/ErrorNotificationCommandDecorator';
import { TelemetryEventNames } from '../telemetry/TelemetryStrings';

import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';

export function builder(dependencies: IDependencies): ICommand<void> {
    return new UserElevationToggleCommand(
        dependencies.workspaceAccessControlManager(),
    );
}

export interface IUserElevationToggleCommandOptions {
    isReadOnly: boolean;
    sessionId: number;
    item: ParticipantSessionExplorerItem;
}

@errorNotificationCommandDecorator('Changing user permissions', TelemetryEventNames.USER_ELEVATION_TOGGLE_COMMAND_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.USER_ELEVATION_TOGGLE_COMMAND, TelemetryEventNames.USER_ELEVATION_TOGGLE_COMMAND_FAULT, 'Toggle user read/write access', 1)
class UserElevationToggleCommand {
    constructor(private workspaceAccessControlManager: IWorkspaceAccessControlManager) { }

    public async invoke(options: IUserElevationToggleCommandOptions, context: ICommandContext): Promise<void> {
        if (!options || typeof options.sessionId !== 'number' || isNaN(options.sessionId)) {
            return;
        }

        const anonymousProfile = workspaceSessionInfoTracker.getAnonymousAccessMapHasTheProfile(options);
        if (anonymousProfile) {
            await workspaceSessionInfoTracker.updateAnonymousAccess(options, options.isReadOnly);
        }
        await this.workspaceAccessControlManager.setUserReadOnly(options.isReadOnly, options.sessionId);
    }
}