'use strict';

import { TraceSource } from '@vs/vso-logging';
import { HostGitSourceControlProvider } from './git/hostGitSourceControlProvider';
import { CancellationToken, Disposable } from 'vscode';
import { IHostSourceControlService, IHostSourceControlProvider } from './Contracts';

import { IDependencies as ICoreDependencies, Lazy } from '@vs/liveshare-core';
import { IRpcServiceHandler } from '@vs/vso-rpc';

import {
    IPathManager,
    ISessionContext,
    IClientAccessCheck,
    WellKnownRestrictedOperations,
    VSLS_SCHEME,
    VSLS_EXTERNAL_SCHEME
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
const cleanOperation: vsls.RestrictedOperation = { name: WellKnownRestrictedOperations.CodeAction };

export class HostSourceControlService implements IHostSourceControlService {
    private readonly providers = new Map<string, IHostSourceControlProvider>();
    private isActive: boolean;
    private disposables: Disposable[] = [];
    private readonly rpcServiceHandler: IRpcServiceHandler;
    private readonly workspaceService: vsls.WorkspaceService;
    private readonly clientAccessCheck: Lazy<IClientAccessCheck>;
    private readonly fileService: Lazy<vsls.FileService>;
    private readonly session: ISessionContext;
    private readonly trace: TraceSource;
    private readonly pathManager: IPathManager;

    public constructor(coreDependencies: ICoreDependencies, clientAccessCheck: Lazy<IClientAccessCheck>) {
        this.rpcServiceHandler = coreDependencies.rpcServiceHandler();
        this.workspaceService = coreDependencies.workspaceService();
        this.clientAccessCheck = clientAccessCheck;
        this.fileService = coreDependencies.fileService;
        this.session = coreDependencies.sessionContext();
        this.trace = coreDependencies.trace().withName('SourceControl');
        this.pathManager = coreDependencies.pathManager();
    }

    public async init() {
        if (this.isActive) {
            return;
        }

        this.isActive = true;
        this.addProvider(new HostGitSourceControlProvider(this.fileService(), this.pathManager));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getAllSourceControls`,
            token => this.getSourceControls(null, null, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getSourceControls`,
            (sourceControlId, token) => this.getSourceControls(sourceControlId, null, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getSourceControl`,
            (sourceControl, token) => this.getSourceControl(sourceControl, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getRecentVersions`,
            (sourceControl, token) => this.getRecentVersions(sourceControl, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getRecentVersionsTillMergeVersion`,
            (sourceControl, token) => this.getRecentVersionsTillMergeVersion(sourceControl, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getCurrentVersionName`,
            (sourceControl, token) => this.getCurrentVersionName(sourceControl, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getRemoteVersionsNames`,
            (sourceControl, token) => this.getRemoteVersionsNames(sourceControl, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getMergeVersion`,
            (sourceControl, branch, token) => this.getMergeVersion(sourceControl, branch, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getDiffsForVersion`,
            (sourceControl, version, token) => this.getDiffsForVersion(sourceControl, version, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getDiffForResource`,
            (resource, token) => this.getDiffForResource(resource, token));

        this.rpcServiceHandler.addRequestMethod(
            `${vsls.SourceControlService.name}.getResource`,
            (resource, token) => this.getResource(resource, token));

        this.rpcServiceHandler.addRequestMethodWithContext(
            `${vsls.SourceControlService.name}.cleanResources`,
            (resources, context, token) => this.cleanResources(resources, context, token));

        await this.workspaceService.registerServicesAsync([`${vsls.SourceControlService.name}`], vsls.CollectionChangeType.Add);
    }

    public async dispose() {
        await this.close();
    }

    public async close() {
        if (!this.isActive) {
            return;
        }

        this.isActive = false;

        if (this.session.isStartingCollaboration || this.session.isCollaborating) {
            try {
                await this.workspaceService.registerServicesAsync(
                    [`${vsls.SourceControlService.name}`],
                    vsls.CollectionChangeType.Remove
                );
            } catch {
                // The session has ended already and we couldn't unregister the service.
                // Ignore this and carry on.
            }
        }

        this.disposables.forEach(d => d.dispose());
        this.providers.forEach(p => p.dispose());
        this.providers.clear();
    }

    public addProvider(provider: IHostSourceControlProvider) {
        if (!provider) {
            throw new Error('provider is not defined');
        }

        if (!this.isActive || this.providers.has(provider.sourceControlId)) {
            return;
        }

        this.providers.set(provider.sourceControlId, provider);

        const providerActivated = () => {
            if (this.isActive) {
                provider.onResourceChanged(this.resourceChanged, this, this.disposables);
                provider.onSourceControlChanged(this.sourceControlChanged, this, this.disposables);
                this.sourceControlChanged({ change: vsls.SourceControlChange.Added, sourceControl: { sourceControlId: provider.sourceControlId, instanceId: null } });
            }
        };

        if (provider.isActive) {
            providerActivated();
        } else {
            provider.activate().then(
                providerActivated,
                err => {
                    this.providers.delete(provider.sourceControlId);
                    this.providerActivationFailed(provider, err);
                });
        }
    }

    public updateCommitMessage(updater: (message: string) => string) {
        if (!updater || !this.isActive) {
            return;
        }

        for (const provider of this.providers.values()) {
            provider.updateCommitMessages(updater);
        }
    }

    private sourceControlChanged(e: vsls.SourceControlChangedEventArgs) {
        if (this.isActive) {
            this.rpcServiceHandler.sendNotification(this.trace, `${vsls.SourceControlService.name}.sourceControlChanged`, e);
        }
    }

    private resourceChanged(e: vsls.SourceControlResourceChangedEventArgs) {
        if (this.isActive) {
            this.rpcServiceHandler.sendNotification(this.trace, `${vsls.SourceControlService.name}.resourceChanged`, e);
        }
    }

    private providerActivationFailed(provider: IHostSourceControlProvider, err: any) {
        this.trace.error(`'${provider.sourceControlId}' host source control provider activation failed: ${err ? err.message || err : 'no reason provided'}`);
    }

    private async getSourceControl(sourceControl: vsls.SourceControlIdentifier, cancellationToken?: CancellationToken): Promise<vsls.SourceControlInstance> {
        const { sourceControlId, instanceId } = sourceControl;
        const [result] = await this.getSourceControls(sourceControlId, instanceId, cancellationToken);
        return result || null;
    }

    private async getSourceControls(sourceControlId?: string | undefined, instanceId?: string | undefined, cancellationToken?: CancellationToken): Promise<vsls.SourceControlInstance[]> {
        if (!this.isActive) {
            return [];
        }

        const promises: Promise<vsls.SourceControlInstance[]>[] = [];
        this.providers.forEach(p => p.isActive && (!sourceControlId || p.sourceControlId === sourceControlId) && promises.push(p.getSourceControls(instanceId, cancellationToken)));

        const results = await Promise.all(promises);
        return this.isActive ? [].concat(...results) : [];
    }

    private async getRecentVersions(sourceControl: vsls.SourceControlIdentifier, cancellationToken?: CancellationToken): Promise<vsls.SourceControlVersion[]> {
        if (!sourceControl || !this.isActive) {
            return [];
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? await provider.getRecentVersions(instanceId, cancellationToken) : [];
    }

    private async getRecentVersionsTillMergeVersion(mergeVersionHash: string, sourceControl: vsls.SourceControlIdentifier, cancellationToken?: CancellationToken): Promise<vsls.SourceControlVersion[]> {
        if (!sourceControl || !this.isActive) {
            return [];
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? await provider.getRecentVersionsTillMergeVersion(mergeVersionHash, instanceId, cancellationToken) : [];
    }

    private async getMergeVersion(sourceControl: vsls.SourceControlIdentifier, remoteVersionName: string, cancellationToken?: CancellationToken): Promise<vsls.SourceControlVersion> {
        if (!sourceControl || !this.isActive) {
            return null;
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? await provider.getMergeVersion(instanceId, remoteVersionName, cancellationToken) : null;
    }

    private getRemoteVersionsNames(sourceControl: vsls.SourceControlIdentifier, cancellationToken?: CancellationToken): Promise<string[]> {
        if (!sourceControl || !this.isActive) {
            return Promise.resolve([]);
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? Promise.resolve(provider.getRemoteVersionsNames(instanceId)) : Promise.resolve([]);
    }

    private getCurrentVersionName(sourceControl: vsls.SourceControlIdentifier, cancellationToken?: CancellationToken): Promise<string> {
        if (!sourceControl || !this.isActive) {
            return Promise.resolve('');
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? Promise.resolve(provider.getCurrentVersionName(instanceId)) : Promise.resolve('');
    }

    private async getDiffsForVersion(sourceControl: vsls.SourceControlIdentifier, version: string, cancellationToken?: CancellationToken): Promise<vsls.SourceControlResourceDiff[]> {
        if (!sourceControl || !this.isActive) {
            return [];
        }

        const { sourceControlId, instanceId } = sourceControl;
        const provider = this.providers.get(sourceControlId);
        return provider ? await provider.getDiffsForVersion(instanceId, version, cancellationToken) : [];
    }

    private async getDiffForResource(resource: vsls.SourceControlResourceIdentifier, cancellationToken?: CancellationToken): Promise<vsls.SourceControlResourceDiff> {
        if (!resource || !this.isActive) {
            return null;
        }

        const provider = this.providers.get(resource.sourceControlId);
        return provider ? await provider.getDiffForResource(resource, cancellationToken) : null;
    }

    private async getResource(resource: vsls.SourceControlResourceIdentifier, cancellationToken?: CancellationToken): Promise<string> {
        if (!resource || !this.isActive) {
            return '';
        }

        let provider: IHostSourceControlProvider;

        const sourceControlId = resource.sourceControlId;
        if (sourceControlId) {
            provider = this.providers.get(sourceControlId);
        } else {
            let scheme: string;
            switch (resource.type) {
                case vsls.SourceControlResourceType.Workspace:
                case vsls.SourceControlResourceType.WorkspaceWithSpecificVersion:
                    scheme = VSLS_SCHEME;
                    break;

                case vsls.SourceControlResourceType.External:
                    scheme = VSLS_EXTERNAL_SCHEME;
                    break;

                default:
            }

            if (scheme) {
                const uri = this.pathManager.protocol2CodeUriConverter(scheme + ':' + resource.path);
                for (const p of this.providers.values()) {
                    if (p.isSourceControlled(uri)) {
                        provider = p;
                        break;
                    }
                }
            }
        }

        if (!provider) {
            return '';
        }

        return await provider.getResource(resource, cancellationToken);
    }

    private async cleanResources(resources: vsls.SourceControlResourceIdentifier[], context: any, cancellationToken?: CancellationToken): Promise<void> {
        if (!resources || !resources.length || !this.isActive) {
            return;
        }

        if (this.clientAccessCheck &&
            !await this.clientAccessCheck().canPerformOperation(context, cleanOperation)) {
            return undefined;
        }


        const resourcesByScc = new Map<string, vsls.SourceControlResourceIdentifier[]>();
        for (const resource of resources) {
            const { sourceControlId } = resource;
            const list = resourcesByScc.get(sourceControlId);
            if (list) {
                list.push(resource);
            } else if (this.providers.has(sourceControlId)) {
                resourcesByScc.set(sourceControlId, [resource]);
            }
        }

        const promises: Promise<void>[] = [];
        for (const [sourceControlId, list] of resourcesByScc) {
            promises.push(this.providers.get(sourceControlId).cleanResources(list, cancellationToken));
        }

        await Promise.all(promises);
    }
}
