import * as vscode from 'vscode';
import { traceSource, dataScrapingManagerInstance } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';

// NOTE: Old system dependencies
import { ShareDebugManager as ShareDebugManagerClass } from '../debugger/shareDebugManager';
import { TrackDebugManager as TrackDebugManagerClass } from '../debugger/trackDebugManager';
import { JoinDebugManager as JoinDebugManagerClass } from '../debugger/joinDebugManager';
import { RpcProxy } from '@vs/vso-rpc';

// NOTE: New system dependencies
import { StringUtil } from './util/StringUtil';
import { NotificationUtil } from './util/NotificationUtil';
import { BrowserUtil } from './util/BrowserUtil';
import { ConfigUtil } from './util/ConfigUtil';
import { WorkspacePromptsUtil } from './util/WorkspacePromptsUtil';
import { WorkspaceFirewallUtil } from './util/WorkspaceFirewallUtil';
import { ShareDebugManager } from './managers/ShareDebugManager';
import { LspServerManager } from './managers/LspServerManager';
import WorkspaceTaskManager from './managers/WorkspaceTaskManager';
import { CoEditingHostManager, CoEditingGuestManager } from './managers/CoEditingManager';
import { BreakpointManager } from './managers/BreakpointManager';
import { ShareBreakpointManager } from './managers/ShareBreakpointManager';
import { JoinBreakpointManager } from './managers/JoinBreakpointManager';
import { GuestTrackerManager } from './managers/GuestTrackerManager';
import { AgentSessionContextUpdateListener } from './providers/AgentSessionContextUpdateListener';
import { TextSearchManager } from './managers/TextSearchManager';
import { SearchProviderManager } from './managers/SearchProviderManager';
import { AdditionalRootsManager } from './managers/AdditionalRootsManager';
import { WorkspaceTaskClientManager } from './managers/WorkspaceTaskClientManager';
import { IDependencies } from './IDependencies';
import { AuthenticationProvider } from '@abstractions/AuthenticationProvider';
import { rpcClientFactory, getWorkspaceClientProxy } from '@abstractions/rpcClientFactory';
import { GuestChannelService } from '../GuestChannelService';

import {
    reviewsDependencies,
    HostSourceControlService,
    HostCoauthorCommitMessageUpdater
} from '@vs/liveshare-reviews';

import { NotebooksService, HostNotebooksService, GuestNotebooksService } from '@vs/liveshare-notebooks';

import {
    sessionStateTracker,
    SessionState,
    lazyLoad,
    lazyLoadNotImplemented,
    HostSyncService,
    IClientAccessCheck,
    dependencies as coreDependencies,
    Dependencies,
    ClipboardUtil,
    FileService,
    stateLazyLoad,
    setLazyLoadMutable,
    Lazy,
    IAuthenticationProviderBase,
    AccessControlService,
    AuthenticationProviderBase,
    lazyLoadMutable
} from '@vs/liveshare-core';
import { RpcServices } from './RpcServices';
import { vsls } from '@vs/vsls-contracts';

import { ServerManager } from '@vs/liveshare-servers';
import { clientFileServiceEnabled } from './util/WorkspaceEnvironmentUtil';
import { isJoinActivated, onlyNonJoinedLazyLoad } from './util/activateUtils';

function toTraceSource(name: string): TraceSource {
    return traceSource.withName(name);
}

function initDependencies(): IDependencies {
    const context: IDependencies = {
        ...coreDependencies,
        ...reviewsDependencies,
        rpcClient: setLazyLoadMutable(coreDependencies.rpcClient, () => rpcClientFactory(context)),
        agentSessionService: lazyLoad(() => RpcProxy.create(vsls.AgentSessionService, context.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpcAgentSession))),
        authService: lazyLoadMutable(() => {
            if (!isJoinActivated()) {
                return RpcProxy.create(vsls.AuthenticationService, context.rpcClient(), traceSource.withName(vsls.TraceSources.ClientRpcAuth));
            }
            return coreDependencies.authService();
        }),
        authenticationProvider: setLazyLoadMutable(coreDependencies.authenticationProvider, () => getAuthenticationProvider(context)),
        firewallService: lazyLoad(() => RpcProxy.create(vsls.FirewallService, context.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpc))),
        hostFileService: lazyLoad(() => new FileService(context.rpcServiceHandler(), context.workspaceService(), context.pathManager(), context.clientAccessCheck, toTraceSource(vsls.TraceSources.ClientRpcFile))),
        sessionContextService: lazyLoad(() => RpcProxy.create(vsls.SessionContextService, context.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpcSessionContext))),
        stringUtil: lazyLoad(() => new StringUtil()),
        notificationUtil: lazyLoad(() => new NotificationUtil()),
        clipboardUtil: lazyLoad(() => new ClipboardUtil()),
        browserUtil: lazyLoad(() => new BrowserUtil()),
        configUtil: lazyLoad(() => new ConfigUtil()),
        workspacePromptsUtil: lazyLoad(() => new WorkspacePromptsUtil(context.notificationUtil(), context.browserUtil())),
        workspaceFirewallUtil: lazyLoad(() => new WorkspaceFirewallUtil(context.firewallService(), context.workspacePromptsUtil(), context.configUtil())),
        shareDebugManager: lazyLoad(() => {
            //For backwards compat: Falls back to ShareDebugManager if registerDebugAdapterTrackerFactory isn't available
            const debugManagerBase = vscode.debug.registerDebugAdapterTrackerFactory ?
                new TrackDebugManagerClass(context.rpcClient(), context.hostAdapterService(), context.fileService, context.clientAccessCheck) :
                new ShareDebugManagerClass(context.rpcClient(), context.hostAdapterService(), context.fileService, context.clientAccessCheck);
            return new ShareDebugManager(debugManagerBase);
        }),
        workspaceTaskManager: lazyLoad(() => new WorkspaceTaskManager(context)),
        lspServerManager: lazyLoad(() => new LspServerManager(context.workspaceService(), context.pathManager(), context.clientAccessCheck, context.sessionContext(), context.rpcServiceHandler())),
        coEditingHostManager: lazyLoad(() => new CoEditingHostManager(context)),
        coEditingGuestManager: lazyLoad(() => new CoEditingGuestManager(context)),
        breakpointManager: lazyLoad(() => new BreakpointManager(context.pathManager(), context.sourceEventService())),
        shareBreakpointManager: lazyLoad(() => new ShareBreakpointManager(context.breakpointManager())),
        joinBreakpointManager: lazyLoad(() => new JoinBreakpointManager(context.breakpointManager())),
        guestTrackerManager: lazyLoad(() => new GuestTrackerManager(context.sessionContext(), context.telemetry(), context.notificationUtil(), context.browserUtil(), traceSource)),
        textSearchManager: lazyLoad(() => new TextSearchManager(context.rpcClient(), context.pathManager())),
        agentSessionContextUpdateListener: lazyLoad(() => new AgentSessionContextUpdateListener(context.sessionContextService(), context.sessionContext(), traceSource)),
        debuggerHostService: lazyLoad(() => RpcProxy.create(vsls.DebuggerHostService, context.rpcClient(), toTraceSource(vsls.TraceSources.DebugHost))),
        clientAccessCheck: lazyLoad(() => getClientAccessCheck(context)),
        telemetryService: getTelemetryServiceLazy(getContext),
        chatService: lazyLoad(() => RpcProxy.create(vsls.ChatService, context.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpcChat))),
        searchProviderManager: lazyLoad(() => { return new SearchProviderManager(context); }),
        additionalRootsManager: lazyLoad(() => { return new AdditionalRootsManager(context); }),
        joinDebugManager: lazyLoad(() => {
            const joinDebugmanagerInstance = new JoinDebugManagerClass(
                context.rpcClient(),
                context.hostAdapterService(),
                context.debuggerHostService(),
                context.sessionContext(),
                context.fileSystemManager(),
                context.pathManager(),
                context.accessControlManager(),
                context.trace().withName('JoinDebugManager'));
            return joinDebugmanagerInstance;
        }),
        workspaceTaskClientManager: lazyLoad(() => new WorkspaceTaskClientManager(context)),
        hostSourceControlService: lazyLoad(() => new HostSourceControlService(coreDependencies, context.clientAccessCheck)),
        hostAdapterService: lazyLoadNotImplemented,
        rpcServiceHandler: lazyLoad(() => context.rpcClient()),
        serverManager: lazyLoad(() => new ServerManager(context)),
        dataScrapingManager: lazyLoad(() => dataScrapingManagerInstance),
        hostCoauthorCommitMessageUpdater: lazyLoad(() => new HostCoauthorCommitMessageUpdater(coreDependencies, context.hostSourceControlService())),
        hostSyncService: lazyLoad(() => new HostSyncService(context.workspaceService(), context.sessionContext(), context.rpcClient(), traceSource)),
        guestChannelService: lazyLoad(() => new GuestChannelService(context.portForwardingService)),
        hostNotebooksService: lazyLoad(() => new HostNotebooksService(coreDependencies, context.clientAccessCheck)),
        guestNotebooksService: lazyLoad(() => new GuestNotebooksService(coreDependencies, RpcProxy.create(NotebooksService, context.rpcClient(), toTraceSource('Notebooks')))),
        portForwardingService: lazyLoadMutable(() => {
            if (isJoinActivated()) {
                throw new Error('Port forward service needs to be defined');
            }

            return coreDependencies.portForwardingService();
        }),
    };
    
    function getContext() { return context; }
    return context;
}

export let dependencies = initDependencies();

/** Get factory for the telemetry service */
function getTelemetryServiceLazy(context: Lazy<IDependencies>): Lazy<vsls.TelemetryService> {
    return onlyNonJoinedLazyLoad(() => {
        return RpcProxy.create(vsls.TelemetryService, context().rpcClient(), traceSource.withName(vsls.TraceSources.ClientRpc));
    });
}

/** Get factory for the authentication provider */
function getAuthenticationProvider(context: IDependencies): IAuthenticationProviderBase {
    return isJoinActivated() ? 
        new AuthenticationProviderBase(context.authService(), true /* native auth is enabled */) : 
        new AuthenticationProvider(context.authService());
}

const fileService: Lazy<vsls.FileService> = stateLazyLoad({
    default: () => { throw new Error('Should not use file service outside of a session'); },
    guest: () => RpcProxy.create(vsls.FileService, dependencies.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpcFile)),
    host: () => clientFileServiceEnabled() ? dependencies.hostFileService() : RpcProxy.create(vsls.FileService, dependencies.rpcClient(), toTraceSource(vsls.TraceSources.ClientRpcFile))
});

const syncService: Lazy<vsls.SyncService> = lazyLoad(() =>
    sessionStateTracker.State === SessionState.Shared || sessionStateTracker.State === SessionState.SharingInProgress ?
        dependencies.hostSyncService() : RpcProxy.create(vsls.SyncService, dependencies.rpcClient(), toTraceSource('SyncService')));

// define core dependencies rpc services
Dependencies.rpcServices = new RpcServices(
    (serviceInfo, traceName) => {
        if (isJoinActivated()) {
            if (serviceInfo.name === vsls.AccessControlService.name) {
                return <any> new AccessControlService(dependencies);
            }
            
            return getWorkspaceClientProxy(serviceInfo, traceName);
        }

        return RpcProxy.create(
            serviceInfo,
            dependencies.rpcClient(),
            traceSource.withName(traceName));
    },
    dependencies.rpcServiceHandler,
    fileService,
    syncService
);

function getClientAccessCheck(deps: IDependencies): IClientAccessCheck {
    const state: SessionState = sessionStateTracker.State;
    switch (state) {
        case SessionState.SharingInProgress:
        case SessionState.Shared:
            return deps.workspaceAccessControlManager();

        case SessionState.JoiningInProgress:
        case SessionState.Joined:
            return deps.accessControlManager();

        default:
            throw new Error(`IClientAccessCheck is not available in session state '${state}'.`);
    }
}
