'use strict';

import * as vscode from 'vscode';
import {
    IAuthStrategy,
    PolicyProvider 
} from '@vs/liveshare-api-contracts';

import {
    PackageInfo,
    StackFrame,
    ExtensionContext,
    LiveShareApi as LiveShareApiBase,
    LiveShareExtensionApi as LiveShareExtensionApiBase,
} from '@vs/liveshare-api';

import { TraceSource } from '@vs/vso-logging';
import * as ec from './../enterpriseConfig';

export class LiveShareExtensionApi extends LiveShareExtensionApiBase {

    public constructor(extensionContext: ExtensionContext) {
        super(extensionContext);
    }

    protected createLiveShareApi(callingPackage: PackageInfo, requestedApiVersion: string, trace: TraceSource, authStrategies: IAuthStrategy[]) {
        return new LiveShareApi(callingPackage, requestedApiVersion, trace, authStrategies);
    }
}

/**
 * Main API that enables other VS Code extensions to access Live Share capabilities.
 *
 * An instance of this class is created by the extension API above.
 */
export class LiveShareApi extends LiveShareApiBase {
    public constructor(
        callingPackage: PackageInfo,
        apiVersion: string,
        trace: TraceSource,
        authStrategies: IAuthStrategy[]
    ) {
        super(callingPackage, apiVersion, trace, authStrategies);
    }

    public async registerPolicyProvider(
        name: string,
        policyProvider: PolicyProvider,
    ): Promise<vscode.Disposable | null> {
        return await ec.EnterpriseConfig.registerPolicyProvider(name, policyProvider);
    }
}
