import { Telemetry, TelemetryEvent, ITimedEvent } from '@vs/vso-telemetry';
import { TelemetryPropertyNames }  from './TelemetryStrings';

export class FileSearchTelemetry {
    public static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'Search.';

    public static sendFindFileDiagnostics(fileCount: number, useIgnoreFiles: boolean): void {
        const summaryEvent = new TelemetryEvent(SearchServiceTelemetryEventNames.FIND_FILE);
        summaryEvent.addMeasure(SearchServiceTelemetryPropertyNames.FILE_COUNT, fileCount);
        summaryEvent.addProperty(SearchServiceTelemetryPropertyNames.USE_IGNORE_FILES, useIgnoreFiles);
        summaryEvent.send();
    }
}
export class TextSearchTelemetry {
    public static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'Search.';
    public textSearchEvent!: ITimedEvent;

    public startTextSearch() {
        this.textSearchEvent = Telemetry.startTimedEvent(SearchServiceTelemetryEventNames.TEXT_SEARCH);
    }

    public saveFirstResultTime() {
        this.textSearchEvent.markTime(SearchServiceTelemetryPropertyNames.FIRST_RESULT_TIME);
    }

    public saveTextSearchResults(resultsCount: number) {
        this.textSearchEvent.addMeasure(SearchServiceTelemetryPropertyNames.RESULTS_COUNT, resultsCount);
        this.textSearchEvent.markTime(SearchServiceTelemetryPropertyNames.RESULTS_RECEIVED_TIME);
    }

    public send(): void {
        this.textSearchEvent.send();
    }
}

export class SearchServiceTelemetryEventNames {
    public static readonly FIND_FILE_FAULT = 'find-file-fault';
    public static readonly FIND_FILE = 'find-file';
    public static readonly TEXT_SEARCH = 'find-text';
}

class SearchServiceTelemetryPropertyNames {
    public static readonly FILE_COUNT = FileSearchTelemetry.PROPERTY_PREFIX + 'FileCount';
    public static readonly USE_IGNORE_FILES = FileSearchTelemetry.PROPERTY_PREFIX + 'UseIgnoreFiles';
    public static readonly RESULTS_RECEIVED_TIME = TextSearchTelemetry.PROPERTY_PREFIX + 'ResultsReceivedTime';
    public static readonly RESULTS_COUNT = TextSearchTelemetry.PROPERTY_PREFIX + 'ResultsCount';
    public static readonly FIRST_RESULT_TIME = TextSearchTelemetry.PROPERTY_PREFIX + 'FirstResultTime';
}