import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { SettingKeys } from '../SettingKeys';
import { Settings } from '../Settings';
import { IPathManager } from '../IPathManager';
import { TraceSource } from '@vs/vso-logging';

export class TextSearchService implements vsls.TextSearchService {
    constructor(
        protected readonly pathManager: IPathManager,
        private trace: TraceSource
    ) { }

    public async getTextSearchResultsAsync(
        options: vsls.TextSearchOptions,
        cancellationToken?: vscode.CancellationToken
    ): Promise<vsls.TextSearchResult[]> {
        return [];
    }

    public async getTextSearchResultsWithProgressAsync(
        options: vsls.TextSearchOptions,
        progress: vscode.Progress<vsls.TextSearchResult>,
        cancellationToken?: vscode.CancellationToken
    ): Promise<void> {
        let vscodeQuery = toVscodeQuery(options);
        let vscodeOptions = toVscodeOptions(options);
        let counter = 0;
        let excludedCounter = 0;
        let searchCancellationSource = new vscode.CancellationTokenSource();   
        let textSearchResultsLimit = Settings.get<number>(SettingKeys.textSearchResultsLimit) || 10000;
        let textSearchPreviewLimit = Settings.get<number>(SettingKeys.textSearchPreviewLimit) || 200;
        
        if (vscode.workspace.findTextInFiles) {
            try {
                await vscode.workspace.findTextInFiles(
                    vscodeQuery, 
                    vscodeOptions,
                    ((result) => {
                        if (counter > textSearchResultsLimit) {
                            return;
                        }
                        let vslsResults = this.toVslsResults(result);
                        for (let i = 0; i < vslsResults.length; ++i) {
                            let vslsResult = vslsResults[i];
                            if (vslsResult.path) { 
                                counter++;
                                if (counter === textSearchResultsLimit) {
                                    vslsResult.hitResultsLimit = true;
                                }
                                if (vslsResult.text.length > textSearchPreviewLimit) {
                                    let text = vslsResult.text;
                                    const offset = 100;
                                    //Note: vslsResult.text is only displayed in Visual Studio, where search trims preview strings to 100 chars before the search term. This pattern is followed here.
                                    if (vslsResult.column < offset) {
                                        text = vslsResult.text.substr(0, textSearchPreviewLimit);
                                    } else {
                                        text = vslsResult.text.substr(vslsResult.column - offset, (vslsResult.column - offset) + textSearchPreviewLimit);
                                    }
                                    vslsResult.text = text;
                                }
                                progress.report(vslsResult);
                            } else {
                                excludedCounter++;
                            }
                        }
                    }),
                    searchCancellationSource.token);
                this.trace.info(`Results returned: ${counter}, results excluded: ${excludedCounter}`);
            } catch (e) {
                this.trace.error(`Problem obtaining search results on host side: ${e.message}`);
            }
        }
    }

    private toVslsResults(result: vscode.TextSearchResult): vsls.TextSearchResult[] {
        let relativePath = this.pathManager.localPathToRelativePath(result.uri);
        return toVersionedVslsResults(result, relativePath);
    }
}

export const toVscodeQuery = (options: vsls.TextSearchOptions): vscode.TextSearchQuery => {
    return {
        pattern: options.pattern || '',
        isRegExp: options.isRegex || false,
        isCaseSensitive: options.isCaseSensitive || false,
        isWordMatch: options.isWordMatch
    };
};

export const toVscodeOptions = (options: vsls.TextSearchOptions): vscode.FindTextInFilesOptions => {
    return {
        include: options.fileIncludes && options.fileIncludes.length > 0 ? `{${options.fileIncludes.join(',')}}` : '',
        exclude: options.fileExcludes && options.fileExcludes.length > 0 ? `{${options.fileExcludes.join(',')}}` : '',
        encoding: options.encoding,
        useIgnoreFiles: options.includeHiddenFiles,
        maxResults: Settings.get<number>(SettingKeys.textSearchResultsLimit) || 10000
    };
};

export const toVersionedVslsResults = (result: vscode.TextSearchResult, relativePath: string): vsls.TextSearchResult[] => {
    // Need this for hosts on version 1.29 and below
    if ((<vscode.OldTextSearchMatch>result).range) {
        let oldTypedResult = <vscode.OldTextSearchMatch>result;
        return [{
            path: relativePath,
            text: oldTypedResult.preview.text,
            line: oldTypedResult.range.start.line,
            column: oldTypedResult.range.start.character,
            length: (oldTypedResult.range.end.character - oldTypedResult.range.start.character)
        }];
    }

    let newTypedResult = <vscode.TextSearchMatch>result;
    if (Array.isArray(newTypedResult.ranges)) { //implies that previewRanges is array as well
        let ranges = (<vscode.Range[]>newTypedResult.ranges);
        let previewRanges = (<vscode.Range[]>newTypedResult.preview.matches);
        let vslsResults = new Array<vsls.TextSearchResult>();

        // first item: ranges is populated, line/column/length are dupes -> no effect
        let vslsRanges: vsls.TextSearchResultRange[] = ranges.map(r => {
            return {
                line: r.start.line,
                column: r.start.character,
                endLine: r.end.line,
                endColumn: r.end.character
            };
        });
        let vslsPreviewRanges: vsls.TextSearchResultRange[] = previewRanges.map(r => {
            return {
                line: r.start.line,
                column: r.start.character,
                endLine: r.end.line,
                endColumn: r.end.character
            };
        });
        let vslsResult = {
            path: relativePath,
            text: newTypedResult.preview.text,
            line: ranges[0].start.line, // we know length of ranges is at least 1
            column: ranges[0].start.character,  
            length: (ranges[0].end.character - ranges[0].start.character), // this will be wrong for multiline, but it's ok bc deprecated
            ranges: vslsRanges,
            previewRanges: vslsPreviewRanges
        };
        vslsResults.push(vslsResult);

        // other items: ranges is null, line/column/length are populated
        for (let i = 1; i < ranges.length; ++i) {
            let r = ranges[i];
            vslsResults.push({
                path: relativePath,
                text: newTypedResult.preview.text,
                line: r.start.line,
                column: r.start.character,
                length: (r.end.character - r.start.character) // wrong for multiline
            });
        }
        return vslsResults;
    } else {
        let range = <vscode.Range><unknown>newTypedResult.ranges;
        let previewRange = <vscode.Range><unknown>newTypedResult.preview.matches;
        let vslsRanges = [{
            line: range.start.line,
            column: range.start.character,
            endLine: range.end.line,
            endColumn: range.end.character
        }];
        let vslsPreviewRanges = [{
            line: previewRange.start.line,
            column: previewRange.start.character,
            endLine: previewRange.end.line,
            endColumn: previewRange.end.character
        }];
        return [{
            path: relativePath,
            text: newTypedResult.preview.text,
            line: range.start.line,
            column: range.start.character,
            length: (range.end.character - range.start.character),
            ranges: vslsRanges,
            previewRanges: vslsPreviewRanges
        }];
    }
};