import * as vscode from 'vscode';
import { IPresenceStatusProvider } from './IPresenceStatusProvider';

import {
    sessionStateTracker,
    SessionState,
    SessionStateChangedEventArgs
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
/**
 * This class will expose a mechanism to set the status to 'Do not Disturb' when a liveshare session
 * is active by joining or sharing
 */
export class SessionStateStatusProvider implements IPresenceStatusProvider {
    private readonly statusChangedEvent = new vscode.EventEmitter<contactProtocol.PresenceStatus>();
    private lastStatus: contactProtocol.PresenceStatus;

    public constructor() {
        this.lastStatus = this.status;
        sessionStateTracker.onStateChanged(async (e: SessionStateChangedEventArgs) => {
            if (this.status !== this.lastStatus) {
                this.lastStatus = this.status;
                this.statusChangedEvent.fire(this.status);
            }
        });
    }

    public get id(): string {
        return 'liveshare-State';
    }

    public get status(): contactProtocol.PresenceStatus {
        return sessionStateTracker.State === SessionState.Joined ||
                sessionStateTracker.State === SessionState.Shared
                ? contactProtocol.PresenceStatus.DoNotDisturb : contactProtocol.PresenceStatus.Unknown;
    }

    public get priority(): number {
        return 50; 
    }

    public get onStatusChanged(): vscode.Event<contactProtocol.PresenceStatus> {
        return this.statusChangedEvent.event;
    }

    public reset(): void {
    }
}
