import { LogLevel } from './interfaces/LogLevel';
import { ITraceFilter } from './interfaces/ITraceFilter';
import { TraceFormat } from './TraceFormat';

/**
 * Base class for a listener for events from a TraceSource.
 */
export abstract class TraceListener {
    public filter: ITraceFilter | null = null;

    public traceEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void {
        if (!this.filter || this.filter.shouldTrace(source, logLevel, id)) {
            this.writeEvent(source, logLevel, id, message, ...args);
        }
    }

    public writeLine(source: string, line: string, includeTimestamp?: boolean): void {
        if (includeTimestamp) {
            line = `[${TraceFormat.formatDate(new Date())} ${source}] ${line}`
        }

        this.writeTo(line);
    }

    public abstract writeTo(line: string): void;

    public flushEvents?: () => Promise<void>;

    protected abstract writeEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void;
}
