import { Event, EventEmitter } from 'vscode';
import {
    IContactModel,
    IContactManager
} from '@vs/liveshare-core';
import { vsls, contactProtocol } from '@vs/vsls-contracts';
export class ContactModelApi implements IContactModel {
    private onDidChangePropertyEmitter = new EventEmitter<string[]>();

    constructor(
        public readonly serviceId: string,
        public readonly contact: contactProtocol.Contact,
        public readonly properties: { [key: string]: any; },
        private contactManager: IContactManager
    ) {  
    }

    public get inviteStatus(): vsls.InviteContactStatus { return this.contactManager.getInviteStatus(this.id); }

    public get id() {
        return this.contact.id;
    }

    public fireChanged(...properties: string[]) {
        this.onDidChangePropertyEmitter.fire(properties);
    }

    public get onDidChangeProperty(): Event<string[]> { return this.onDidChangePropertyEmitter.event; }
}