import * as rpc from 'vscode-jsonrpc';
import { ILogger, Logger } from '@vs/vso-logging';
import {
    IJoinConnectOptions,
    IWorkspaceClient,
    HostConnectionChanged,
    WorkspaceMetricsUpdated,
    IWorkspaceServiceClient,
    workspaceServiceClient,
    NoHostConnectedError,
    RelayConnectionError,
    RPC_ERR_NO_HOST_NOT_CONNECTED,
    RPC_ERR_RELAY_CONNECTIONY_SSH,
    ILiveShareConnectionOptions,
    ConnectedState,
    CheckConnectionOptions,
} from '@vs/vso-workspace-core';
import { RpcProxy, ServiceInfo, IRpcClient, IChannel, RpcProxyCache } from '@vs/vso-rpc';
import { IMultiChannelRpcClient, createMultiChannelRpcClient } from '@vs/vso-rpc-ssh';
import { Stream } from '@vs/vs-ssh';
import { DisposableClass, assertDefined, errorToObject } from '@vs/vscs-utils';
import { vsls } from '@vs/vsls-contracts';

const workspaceNotJoined = 'workspace not joined';

export class WorkspaceHubClient extends DisposableClass implements IWorkspaceClient {
    private readonly onHostConnectionChangedEmitter = new rpc.Emitter<HostConnectionChanged>();
    private readonly onWorkspaceMetricsUpdatedEmitter = new rpc.Emitter<WorkspaceMetricsUpdated>();
    private readonly rpcProxyCache: RpcProxyCache;

    private readonly workspaceServiceClient: IWorkspaceServiceClient;
    private joinedWorkspaceId?: string;

    private constructor(
        private readonly multiChannelRpcClient: IMultiChannelRpcClient,
        logger: ILogger
    ) {
        super(logger);

        const fireHostConnectionChanged = (e: HostConnectionChanged) => {
            this.onHostConnectionChangedEmitter.fire(e);
        };

        let fireHostClosed = false;
        const fireHostConnectionClosed = (reason: string, e?: HostConnectionChanged) => {
            if (!fireHostClosed) {
                logger.info(`firing host connection closed -> reason:${reason}`);
                fireHostClosed = true;
                fireHostConnectionChanged(
                    e ?? {
                        state: ConnectedState.Closed,
                        duration: 0,
                    }
                );

                this.disconnect().catch((error) => {
                    logger.info(
                        `error while disconnecting workspace hub client`,
                        errorToObject(error)
                    );
                });

                this.dispose('host connection closed');
            }
        };

        multiChannelRpcClient.rpcConnection.onDispose(() => {
            // fire host closed if needed.
            fireHostConnectionClosed('onDisposed');

            // Note: if the rpc is being closed it is for 2 reasons, one of them is that we dispose this
            // instance or we are being closed because of the remote connection is dropped.
            if (!this.isDisposed) {
                logger.warning('Rpc connection was disposed from our hub service');
            }
        });

        const proxyLogger = logger.createChild('rpc');
        this.workspaceServiceClient = RpcProxy.create<IWorkspaceServiceClient>(
            workspaceServiceClient,
            this.rpcClient,
            new Logger(logger.name, (logLevel, message, ...args) => {
                // remove rpc verbose messages we know about
                if (
                    message.startsWith('> workspaceServiceClient.workspaceMetricsUpdated') ||
                    message.includes('workspaceServiceClient.checkConnection()')
                ) {
                    return;
                }

                proxyLogger.log(logLevel, message, ...args);
            })
        );
        // Route event from the hub
        this.workspaceServiceClient.onHostConnectionChanged((e) => {
            if (e.workspaceId === this.joinedWorkspaceId) {
                if (e.state === ConnectedState.Closed) {
                    fireHostConnectionClosed('onHostConnectionChanged', e);
                } else {
                    fireHostConnectionChanged(e);
                }
            }
        });
        this.workspaceServiceClient.onWorkspaceMetricsUpdated((e) => {
            if (e.workspaceId === this.joinedWorkspaceId) {
                this.onWorkspaceMetricsUpdatedEmitter.fire(e);
            }
        });

        this.addToDisposables(
            {
                dispose: () => fireHostConnectionClosed('disposed'),
            },
            multiChannelRpcClient
        );

        this.rpcProxyCache = new RpcProxyCache(this.multiChannelRpcClient, logger);
    }

    public static async create(
        transportStream: Stream,
        logger: ILogger
    ): Promise<WorkspaceHubClient> {
        const multiChannelRpcClient = await createMultiChannelRpcClient(transportStream, logger);
        return new WorkspaceHubClient(multiChannelRpcClient, logger);
    }

    public readonly onHostConnectionChanged = this.onHostConnectionChangedEmitter.event;

    public readonly onWorkspaceMetricsUpdated = this.onWorkspaceMetricsUpdatedEmitter.event;

    public get rpcClient(): IRpcClient {
        return this.multiChannelRpcClient;
    }

    public getServiceProxy<T>(serviceInfo: ServiceInfo<T>): T {
        return this.rpcProxyCache.getOrCreate(serviceInfo);
    }

    public async join(joinConnectOptions: IJoinConnectOptions): Promise<vsls.WorkspaceSessionInfo> {
        const start = Date.now();

        const workspaceId = joinConnectOptions.workspaceId;
        let workspaceSessionInfo: vsls.WorkspaceSessionInfo | undefined;

        // if seesion factory defined it may be worth to retrieve the session info on the hub service.
        if (joinConnectOptions.sessionInfoFactory) {
            workspaceSessionInfo = await this.workspaceServiceClient.getSessionInfoAsync(
                workspaceId
            );
        }

        if (!workspaceSessionInfo) {
            try {
                const liveshareConnectOptions: ILiveShareConnectionOptions = {
                    ...joinConnectOptions,
                };
                // Note: remove any properties that should not be serialize trough JSON
                ['performance', 'sessionInfoFactory'].forEach(
                    // @ts-ignore
                    (key) => delete liveshareConnectOptions[key]
                );

                // delete any mock keys
                Object.keys(liveshareConnectOptions)
                    .filter((k) => k.startsWith('mock'))
                    // @ts-ignore
                    .forEach((k) => delete liveshareConnectOptions[k]);

                if (joinConnectOptions.sessionInfoFactory) {
                    liveshareConnectOptions.connectionInfo = await joinConnectOptions.sessionInfoFactory(
                        workspaceId
                    );
                }

                workspaceSessionInfo = await this.workspaceServiceClient.joinAsync(
                    liveshareConnectOptions
                );
            } catch (err) {
                if (err instanceof rpc.ResponseError) {
                    if (err.code === RPC_ERR_NO_HOST_NOT_CONNECTED) {
                        throw new NoHostConnectedError(err.data);
                    } else if (err.code === RPC_ERR_RELAY_CONNECTIONY_SSH) {
                        throw new RelayConnectionError(err.message, err.data);
                    }
                }

                throw err;
            }
        }

        this.joinedWorkspaceId = workspaceId;
        const time = (Date.now() - start).toFixed(1);
        this.trace.info(
            `join completed -> time:${time} session:${workspaceSessionInfo.sessionNumber} conversation:${workspaceSessionInfo.conversationId}`
        );
        return workspaceSessionInfo;
    }

    public async openStreamingChannel(
        streamId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<IChannel> {
        assertDefined(this.joinedWorkspaceId, 'Workspace not joined.');

        // open the channel and then open a remote stream channel on the hub and wait
        const [sshChannel] = await Promise.all([
            this.multiChannelRpcClient.multiChannelStream.openChannel(),
            this.workspaceServiceClient.openStreamingChannelAsync(
                this.joinedWorkspaceId,
                streamId,
                cancellationToken ?? rpc.CancellationToken.None
            ),
        ]);

        return sshChannel;
    }

    public async disconnect(): Promise<void> {
        assertDefined(this.joinedWorkspaceId, workspaceNotJoined);
        await this.workspaceServiceClient.disconnectAsync(this.joinedWorkspaceId!);

        this.dispose();
    }

    public keepAlive(time?: number): Promise<void> {
        return this.workspaceServiceClient.keepAliveAsync(time);
    }

    public async checkConnection(cancellationToken?: rpc.CancellationToken) {
        assertDefined(this.joinedWorkspaceId, workspaceNotJoined);

        await this.workspaceServiceClient.checkConnectionAsync(
            this.joinedWorkspaceId,
            cancellationToken
        );
    }

    public async setCheckConnectionOptions(options: CheckConnectionOptions): Promise<void> {
        assertDefined(this.joinedWorkspaceId, workspaceNotJoined);
        await this.workspaceServiceClient.setCheckConnectionOptionsAsync(
            this.joinedWorkspaceId,
            options
        );
    }
}
