import * as rpc from 'vscode-jsonrpc';
import { vsls } from '@vs/vsls-contracts';
import { notImplemented } from '@vs/vscs-utils';
import { IRpcServiceHandlerInfo } from '@vs/vso-rpc';

class GuestSession {

    private blocked = false
    private removed = false;
    private rejected = false;

    constructor(
        public readonly rpcSession: rpc.MessageConnection,
        public readonly userProfile: vsls.WorkspaceUserProfile,
        public readonly joinId: string,
        public readonly resolveRequestPromise: (result: GuestJoinResult) => void,
        public readonly rejectRequestPromise: (reason?: any) => void
    ) { }

    public block() {
        this.blocked = true;
    }

    public remove() {
        this.removed = true;
    }

    public reject() {
        this.rejected = true;
    }

    public get isBlocked(): boolean {
        return this.blocked;
    }

    public get isRemoved(): boolean {
        return this.removed;
    }

    public get isRejected(): boolean {
        return this.rejected;
    }

}

enum GuestJoinResult {
    SUCCESS,
    REJECTED,
    CANCELLED
}

/**
 * Base class for WorkspaceUserService implementation.
 */
export class WorkspaceUserService implements vsls.WorkspaceUserService, IRpcServiceHandlerInfo {
    protected onWorkspaceSessionChangedEmitter = new rpc.Emitter<vsls.WorkspaceSessionChangedEventArgs>();

    public serviceInfo = vsls.WorkspaceUserService;

    readonly onWorkspaceSessionChanged = this.onWorkspaceSessionChangedEmitter.event;

    protected readonly guestSessions = new Map<number, GuestSession>();

    public constructor(private disconnect: (connection: rpc.MessageConnection) => void) {}

    public fireWorkspaceSessionChanged(
        changeType: vsls.WorkspaceSessionChangeType,
        sessionNumber: number,
        userProfile: vsls.WorkspaceUserProfile,
        applicationName = 'VS Code',
        disconnectedReason?: vsls.WorkspaceDisconnectedReason) {

        this.onWorkspaceSessionChangedEmitter.fire({
            changeType,
            sessionNumber,
            userProfile,
            applicationName,
            disconnectedReason
        });
    }

    acceptOrRejectGuestAsync(
        sessionNumber: number,
        acceptance: vsls.GuestAcceptance,
        cancellationToken?: rpc.CancellationToken)
        : Promise<void> {
        const guestSession = this.guestSessions.get(sessionNumber);
        if (guestSession) {
            if (!acceptance.accept && typeof acceptance.errorCode === 'number' && acceptance.errorCode !== 0) {
                guestSession.rejectRequestPromise(new rpc.ResponseError(acceptance.errorCode, acceptance.message));
            }
            guestSession.resolveRequestPromise(acceptance.accept ? GuestJoinResult.SUCCESS : GuestJoinResult.REJECTED);
        }
        return Promise.resolve();
    }

    autoAcceptGuestsAsync(
        acceptance: vsls.GuestAcceptance,
        cancellationToken?: rpc.CancellationToken)
        : Promise<void> {
        notImplemented();
    }

    removeUserAsync(
        sessionNumber: number,
        disconnectionReason: vsls.WorkspaceDisconnectedReason,
        cancellationToken?: rpc.CancellationToken)
        : Promise<void> {
        const guestSession = this.guestSessions.get(sessionNumber);
        if (!guestSession) {
            return;
        }

        if (disconnectionReason == vsls.WorkspaceDisconnectedReason.SessionEnded) {
            const args: vsls.WorkspaceConnectionStatusChangedEventArgs = {
                connectionStatus: vsls.WorkspaceConnectionStatus.Disconnected,
                disconnectedReason: vsls.WorkspaceDisconnectedReason.SessionEnded
            };
            guestSession.rpcSession.sendNotification(`${vsls.WorkspaceService.name}.connectionStatusChanged`, args);
        } else if (disconnectionReason == vsls.WorkspaceDisconnectedReason.UserBlocked) {
            guestSession.block();
            guestSession.rpcSession.sendNotification(`${vsls.WorkspaceService.name}.userBlocked`);
        } else {
            guestSession.remove();
            guestSession.rpcSession.sendNotification(`${vsls.WorkspaceService.name}.userRemoved`);
        }

        // Disconnect after a timeout because the above Workspace Service notifications need to be delivered
        // before the disconnect. These notifications set flags which are checked in the disconnect handler
        // and are used to display an appropriate message to the guest about why the disconnect happened.
        // TODO wait for an acknowledgement from the guest that they received the Workspace Service notifications
        // before disconnecting, probably by converting the notifications into a request that tells
        // the guest to remove themselves from the session. If no acknowledgement is received in a short time,
        // force the disconnect (which may result in an inappropriate error message).
        setTimeout(() => this.disconnect(guestSession.rpcSession), 1000);
    }

    removeAllInteractiveUsersAsync(
        cancellationToken?: rpc.CancellationToken)
        : Promise<void> {
        notImplemented();
    }

    fireProgressUpdatedToGuestAsync(
        progress: vsls.WorkspaceProgress,
        sessionNumber: number,
        cancellationToken?: rpc.CancellationToken)
        : Promise<void> {
        const guestSession = this.guestSessions.get(sessionNumber);
        if (guestSession) {
            const args: vsls.WorkspaceProgressEventArgs = {
                progress,
                duration: 0
            };
            guestSession.rpcSession.sendNotification(`${vsls.WorkspaceService.name}.progressUpdated`, args);
        }
        return Promise.resolve();
    }

    getCountOfGuestsWithSameAccountAsync(
        name: string,
        email: string,
        cancellationToken?: rpc.CancellationToken)
        : Promise<number> {
        notImplemented();
    }

    createGuestDisplayNameAsync(
        userProfile: vsls.WorkspaceUserProfile,
        cancellationToken?: rpc.CancellationToken)
        : Promise<string> {
        notImplemented();
    }

    getCachedGuestDisplayNameAsync(
        sessionNumber: number,
        cancellationToken?: rpc.CancellationToken)
        : Promise<string> {
        notImplemented();
    }

    getGuestUserProfileAsync(
        userToken: string,
        cancellationToken?: rpc.CancellationToken)
        : Promise<vsls.WorkspaceUserProfile> {
        notImplemented();
    }

    getCountOfInteractiveGuestsAsync(
        cancellationToken?: rpc.CancellationToken)
        : Promise<number> {
        notImplemented();
    }

    public notifyUserUnjoinedWorkspaceSession(sessionNumber: number, userProfile: vsls.WorkspaceUserProfile, disconnectedReason: vsls.WorkspaceDisconnectedReason) {
        if (this.guestSessions.has(sessionNumber)) {
            this.fireWorkspaceSessionChanged(
                vsls.WorkspaceSessionChangeType.Unjoined,
                sessionNumber,
                userProfile,
                '',
                disconnectedReason);
        }
    }

    public async addGuestOrThrowRejectionAsync(sessionNumber: number, userProfile: vsls.WorkspaceUserProfile, joinId: string, connection: rpc.MessageConnection) {
        let resolveRequestPromise: (result: GuestJoinResult) => void;
        let rejectRequestPromise: (reason?: any) => void;
        const requestPromise = new Promise<GuestJoinResult>((resolve, reject) => { resolveRequestPromise = resolve; rejectRequestPromise = reject; });
        const guestSession = new GuestSession(connection, userProfile, joinId, resolveRequestPromise, rejectRequestPromise);
        this.guestSessions.set(sessionNumber, guestSession);

        this.throwIfUserIsBlocked(userProfile, joinId);

        this.fireWorkspaceSessionChanged(vsls.WorkspaceSessionChangeType.Requested, sessionNumber, userProfile);

        let result: GuestJoinResult;
        try {
            result = await requestPromise;
        } catch (e) {
            this.cancelGuestJoin(sessionNumber, userProfile);
            throw e;
        }

        if (result === GuestJoinResult.REJECTED) {
            guestSession.reject();
            throw new rpc.ResponseError(vsls.ErrorCodes.CollaborationSessionGuestRejected, 'Rejected by host');
        } else if (result === GuestJoinResult.CANCELLED) {
            this.cancelGuestJoin(sessionNumber, userProfile);
            throw new rpc.ResponseError(vsls.ErrorCodes.CollaborationSessionGuestCanceled, 'Join request canceled');
        } else if (result === GuestJoinResult.SUCCESS) {
            this.fireWorkspaceSessionChanged(vsls.WorkspaceSessionChangeType.Joined, sessionNumber, userProfile);
        }
    }

    private cancelGuestJoin(sessionNumber: number, userProfile: vsls.WorkspaceUserProfile) {
        this.fireWorkspaceSessionChanged(vsls.WorkspaceSessionChangeType.Canceled, sessionNumber, userProfile);
        this.guestSessions.delete(sessionNumber);
    }

    private throwIfUserIsBlocked(userProfile: vsls.WorkspaceUserProfile, joinId: string) {
        for (let guestSession of this.guestSessions.values()) {
            if (isSameUser(userProfile, joinId, guestSession)
                && (guestSession.isBlocked || guestSession.isRejected)) {
                throw new rpc.ResponseError(vsls.ErrorCodes.CollaborationSessionGuestBlocked, 'Already blocked by host');
            }
        }
    }

}

function isSameUser(userProfile: vsls.WorkspaceUserProfile, joinId: string, guestSession: GuestSession) {
    if (userProfile.isAnonymous) {
        return (userProfile.id === guestSession.userProfile.id)
            && (joinId == guestSession.joinId);
    }

    return (userProfile.name == guestSession.userProfile.name)
        && (userProfile.email == guestSession.userProfile.email)
        && (joinId == guestSession.joinId);
}
