import { ILogger } from "@vs/vso-logging";

export interface IDisposableLike {
    dispose: (reason?: string) => any;
}

export function createDisposable(callback: (reason?: string) => any, logger: ILogger): IDisposableLike {
    return {
        dispose: (reason?: string) => {
            logger?.verbose(`Disposing reason:${reason}`);
            return callback(reason);
        }
    };
}

export function createDisposablesAll(logger?: ILogger, ...disposables:IDisposableLike[]): IDisposableLike {
    return {
        dispose: (reason?: string) => {    
            logger?.verbose(`createDisposablesAll->dispose reason:${reason}`);       
            return Promise.all(disposables.map(d => d.dispose(reason)));
        }
    };
}

export function createDisposablesSeries(logger?: ILogger, ...disposables:IDisposableLike[]): IDisposableLike {
    return {
        dispose: async (reason?: string) => {           
            logger?.verbose(`createDisposablesSeries->dispose reason:${reason}`);       
            for (let d of disposables) {
                try {
                    await d.dispose(reason);
                } catch(err) {
                    logger?.error(`Failed to dispose`, err);
                }              
            }
        }
    };
}