import * as minimatch from 'minimatch';

import { ITraceFilter, LogLevel } from './interfaces';
import { VSLSError } from './utils/errorToString';
declare type TLogLevel = keyof typeof LogLevel;
export interface IFilters {
    [key: string]: string;
}

export class GlobPatternTraceFilter implements ITraceFilter {
    private readonly traceSourceVerbosityCache: Map<string, number> = new Map();

    constructor(
        private globToVerbosity: IFilters,
    ) {
    }

    private getTraceVerbosity(source: string): number {
        let traceVerbosity = this.traceSourceVerbosityCache.get(source);
        // If we don't have a cached verbosity for this source, find the verbosity and cache it
        if (typeof traceVerbosity === 'undefined') {
            traceVerbosity = 0;
            if (this.globToVerbosity) {
                for (let traceGlob in this.globToVerbosity) {
                    if (minimatch(source, traceGlob)) {
                        traceVerbosity =
                        LogLevel[this.globToVerbosity[traceGlob] as TLogLevel];
                    }
                }
            }
            this.traceSourceVerbosityCache.set(source, traceVerbosity);
        }
        return traceVerbosity;
    }

    public shouldTrace(source: string, logLevel: LogLevel, id: number): boolean {
        return this.getTraceVerbosity(source) <= logLevel;
    }
}

if (typeof Error.prepareStackTrace === 'function' ) {
    // Save the stack frames as a property on all errors before preparing the stack trace string.
    const originalPrepareStackTrace = Error.prepareStackTrace;
    Error.prepareStackTrace = function prepareVslsStack(e: VSLSError, s: NodeJS.CallSite[]) {
        e.vslsStack = s;
        return originalPrepareStackTrace(e, s);
    };
};
