import { vsls } from '@vs/vsls-contracts';
import { Settings, featureFlags } from '../Settings';
import { SettingKeys } from '../SettingKeys';

import {
    Telemetry,
    TelemetryEvent,
    Fault,
    FaultType,
    ITelemetryEvent
} from '@vs/vso-telemetry';

import { TelemetryPropertyNames, TelemetryEventNames } from './TelemetryStrings';

type TelemetryEventPayload = { [key: string]: any; } | undefined | null;

export class ExtensionTelemetry {

    private static singleton: ExtensionTelemetry;

    // For transition events
    private static transitionSeq = 0;
    private static lastTransitionTime = (new Date()).getTime();

    public static sendShareFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.SHARE_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendJoinFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.JOIN_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendSignInFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.SIGN_IN_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendActivateExtensionFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.ACTIVATE_EXTENSION_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendDeactivateExtensionFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.DEACTIVATE_EXTENSION_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendActivateAgentAsyncFault(type: FaultType, details?: string, exception?: any, correlatedEvent?: ITelemetryEvent) {
        Telemetry.sendFault(TelemetryEventNames.ACTIVATE_AGENTASYNC_FAULT, type, details, exception, correlatedEvent);
    }

    public static sendTransition(currentState: string, nextState: string, fromAction: string): void {
        let currentTime = (new Date()).getTime();
        let timeSinceLastTransition = currentTime - this.lastTransitionTime;
        this.lastTransitionTime = currentTime;

        let transitionTelemetryEvent = new TelemetryEvent(TelemetryEventNames.TRANSITION);
        transitionTelemetryEvent.addProperty(TelemetryPropertyNames.CURRENT_STATE, currentState);
        transitionTelemetryEvent.addProperty(TelemetryPropertyNames.NEXT_STATE, nextState);
        transitionTelemetryEvent.addProperty(TelemetryPropertyNames.TRANSITION_ACTION, fromAction);
        transitionTelemetryEvent.addMeasure(TelemetryPropertyNames.TRANSITION_SEQUENCE, this.transitionSeq++);
        transitionTelemetryEvent.addMeasure(TelemetryPropertyNames.TIME_SINCE_LAST_TRANSITION, timeSinceLastTransition);
        transitionTelemetryEvent.send();
    }

    public static reportChangedSetting(): void {
        (new TelemetryEvent(TelemetryEventNames.CHANGE_SETTING)).send();
    }

    public static versionCheckFail(platformName: string, platformVersion: string, versionInfoServicePack?: number): void {
        let versionCheckFailFault = new Fault(TelemetryEventNames.VERSION_CHECK_FAIL, FaultType.User, 'Version check failed.');
        versionCheckFailFault.addProperty(TelemetryPropertyNames.VERSION_PLATFORMNAME, platformName);
        versionCheckFailFault.addProperty(TelemetryPropertyNames.VERSION_PLATFORMVERSION, platformVersion);
        versionCheckFailFault.addProperty(TelemetryPropertyNames.VERSION_PLATFORMVERSION_SERVICEPACK, String(versionInfoServicePack));
        versionCheckFailFault.send();
    }

    public static ReportFailedAssertion(message: string): void {
        (new Fault(TelemetryEventNames.ASSERT_FAULT, FaultType.Error, message, new Error('Assertion Failed'))).send();
    }

    public static async setUserInfo(userInfo: vsls.UserInfo) {
        if (!(userInfo && userInfo.emailAddress)) {
            return;
        }
        if (userInfo.emailAddress !== Settings.get<string>(SettingKeys.userEmail)) {
            await Settings.save(SettingKeys.userEmail, userInfo.emailAddress);
        }
        if (userInfo.emailAddress.endsWith('microsoft.com') && !Settings.get<boolean>(SettingKeys.isInternal)) {
            await Settings.save(SettingKeys.isInternal, true);
            Telemetry.addContextProperty(TelemetryPropertyNames.IS_INTERNAL, 'true');
        }
    }

    public static setServiceEndpoint(serviceEndpoint: string): void {
        Telemetry.addContextProperty(TelemetryPropertyNames.SERVICE_ENDPOINT, serviceEndpoint);
    }

    public static setSettingsContextProperties(): void {
        Telemetry.addContextProperty(TelemetryPropertyNames.IS_INTERNAL, Settings.get<boolean>(SettingKeys.isInternal) ? 'true' : 'false');
        Telemetry.addContextProperty(TelemetryPropertyNames.IS_CLOUD_ENVIRONMENT, Settings.get<boolean>(SettingKeys.isCloudEnvironment) ? 'true' : 'false');
        Telemetry.addContextProperty(TelemetryPropertyNames.USER_TEAM_STATUS, Settings.get<string>(SettingKeys.teamStatus));
        Telemetry.addContextProperty(TelemetryPropertyNames.CONNECTION_MODE, Settings.get<string>(SettingKeys.connectionMode));
        Telemetry.addContextProperty(TelemetryPropertyNames.FEATURE_FLAGS, JSON.stringify(featureFlags));
    }

    public static genericOperation(eventName: string, result: any, payload?: TelemetryEventPayload) {
        const genericOperationEvent = new TelemetryEvent(eventName);
        genericOperationEvent.addProperty(TelemetryPropertyNames.EVENT_RESULT, this.capitalizeFirstChar(result));
        this.setPayloadAndSend(genericOperationEvent, payload);
    }

    public static sendFault(eventName: string, details?: string, payload?: TelemetryEventPayload, type?: FaultType) {
        const fault = new Fault(eventName, type || FaultType.Error, details);
        this.setPayloadAndSend(fault, payload);
    }

    private static setPayloadAndSend(telemetryEvent: TelemetryEvent, payload?: TelemetryEventPayload) {
        if (payload) {
            for (let key in payload) {
                if (payload.hasOwnProperty(key)) {
                    const value = payload[key] === undefined
                        || payload[key] === null ? undefined : payload[key].toString();
    
                    telemetryEvent.addProperty(
                        TelemetryPropertyNames.FEATURE_NAME + this.capitalizeFirstChar(key),
                        value);
                }
            }
        }

        Telemetry.correlate(telemetryEvent);
        telemetryEvent.send();
    }

    private static capitalizeFirstChar(content: string): string {
        return content.charAt(0).toUpperCase() + content.slice(1);
    }
}