'use strict';

import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import Semaphore from 'semaphore-async-await';

import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';

import { ExtensionUtil } from '../utils/ExtensionUtil';
import { SessionContext } from '../SessionContext';
import { SessionState } from '../SessionTypes';

import { BooleanOrError } from './RestrictedOperation';
import { ClientAccessCheck } from './ClientAccessCheck';
import { NotificationUtil } from '@vs/vscode-command-framework';
import { IWorkspaceAccessControlManager } from '../contracts/IWorkspaceAccessControlManager';
import { sessionStateTracker } from '../SessionStateTracker';
import { workspaceSessionInfoTracker } from '../WorkspaceSessionInfoTracker';
import { localize } from '../localize';
import { IRpcServices } from '../contracts/IRpcServices';
import { getExpService } from '../exp/ExperimentationService';

export enum AnonymousAccessLevel {
    readOnly = 'readOnly',
    readWrite = 'readWrite'
}

export class WorkspaceAccessControlManager extends ClientAccessCheck implements IWorkspaceAccessControlManager {
    private readonly workspaceUserService: vsls.WorkspaceUserService;
    private readonly guestNameSemaphore = new Semaphore(1);
    private readonly guestNameCounts = new Map<string, number>();

    constructor(dependencies: IRpcServices,
                hostSessionId: number) {
        super(dependencies.workspaceAccessControlService(), hostSessionId);
        this.workspaceUserService = dependencies.workspaceUserService();
    }

    public get isReadOnly(): boolean {
        return false; // Host is never read-only.
    }

    public endCollaboration() {
        this.guestNameCounts.clear();
        super.endCollaboration();
        workspaceSessionInfoTracker.clearAnonymousAccessMap();
    }

    public async setReadOnly(isReadOnly: boolean) {
        let workspaceAccessControl: vsls.WorkspaceAccessControl = await this.workspaceAccessControlService.getAccessControlAsync() || {};
        workspaceAccessControl.defaultAccessControl = workspaceAccessControl.defaultAccessControl || {};
        if (!!workspaceAccessControl.defaultAccessControl.isReadOnly !== isReadOnly) {
            if (SessionContext.hasCollaborators) {
                await vscode.window.showErrorMessage(
                    'Cannot change read-only status of the collaboration session when there are participants joined.',
                    { 
                        modal: ExtensionUtil.enableModalNotifications
                    });
                return;
            }

            workspaceAccessControl.defaultAccessControl.isReadOnly = isReadOnly;

            // Set session context here sooner, don't wait for the event to set it up.
            workspaceSessionInfoTracker.isReadOnly = isReadOnly;
            await this.workspaceAccessControlService.setAccessControlAsync(workspaceAccessControl);
        }
    }

    private async getUserAccessControlBySessionId(sessionId: number) {
        await this.ensureWorkspaceAccessControl();
        const usersAccesControl = this.workspaceAccessControl.userAccessControl;

        return usersAccesControl[sessionId];
    }

    public async setUserReadOnly(isReadOnly: boolean, sessionId: number) {
        const workspaceAccessControl: vsls.WorkspaceAccessControl = await this.workspaceAccessControlService.getAccessControlAsync() || {};
        workspaceAccessControl.defaultAccessControl = workspaceAccessControl.defaultAccessControl || {};

        const usersAccesControl = workspaceAccessControl.userAccessControl;
        const currentUserAcessControl = usersAccesControl[sessionId];

        const currentIsReadOnly = currentUserAcessControl && currentUserAcessControl.isReadOnly;

        if (currentIsReadOnly !== isReadOnly) {
            usersAccesControl[sessionId] = {
                ...currentUserAcessControl,
                isReadOnly
            };

            await this.workspaceAccessControlService.setAccessControlAsync(workspaceAccessControl);
        }
    }

    public async setOperationAccess(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess) {
        await this.workspaceAccessControlService.setOperationAccessAsync(operation, access);
    }

    private async setUserAccessControl(sessionNumber: number, userProfile: vsls.WorkspaceUserProfile) {
        const anonymousGuestApprovalRequiredSetting = (Settings.get<string>(SettingKeys.anonymousGuestApproval) || '').toLowerCase();
        const isAutoAcceptAnonymous = (anonymousGuestApprovalRequiredSetting === 'accept');
        const isAnonymousAcceptedAsReadOnly = workspaceSessionInfoTracker.getAnonymousAccess(userProfile.id) === AnonymousAccessLevel.readOnly;
        if (userProfile.isAnonymous) {
            if (!this.isReadWriteAnonymousEnabled() ||
            (this.isReadWriteAnonymousEnabled() && (isAnonymousAcceptedAsReadOnly || isAutoAcceptAnonymous))) {
                await this.setUserReadOnly(true, sessionNumber);
                if (isAutoAcceptAnonymous && this.isReadWriteAnonymousEnabled()) {
                    await workspaceSessionInfoTracker.setAnonymousAccess(userProfile.id, localize('notification.AlwaysAcceptAnonymous'));
                }
            }
        } else {
            await this.copyPreviousAccessControl(userProfile, sessionNumber);
        }
    }

    private async copyAccessControl(fromSessionId: number, toSessionId: number) {
        const workspaceAccessControl: vsls.WorkspaceAccessControl = this.workspaceAccessControl;
        const usersAccesControl = workspaceAccessControl.userAccessControl;

        const fromAccessControl = usersAccesControl[fromSessionId];
        const toAccessControl = usersAccesControl[toSessionId];

        if (!fromAccessControl) {
            return;
        }

        usersAccesControl[toSessionId] = {
            ...toAccessControl,
            ...fromAccessControl,
            // explicitelly convert the `isReadOnly` to `boolean` because  if it previously was set to `false`,
            // services will return the property as `undefined`(false is default) and sending property as undefined
            // back to services will not take effect
            isReadOnly: !!fromAccessControl.isReadOnly
        };

        await this.workspaceAccessControlService.setAccessControlAsync(workspaceAccessControl);
    }

    private async copyPreviousAccessControl(userProfile: vsls.WorkspaceUserProfile, currentUserSessionId: number) {
        // if user was previously in the session, get their `sessionId`
        const sessionId = SessionContext.getLatestPreviousSessionId(userProfile.id);
        if (sessionId) {
            // get associated `accessControl` with the last sessionId the user had
            const userAccessControl = await this.getUserAccessControlBySessionId(sessionId);
            // if present, create new `accessControl` for the user
            if (userAccessControl) {
                await this.copyAccessControl(sessionId, currentUserSessionId);
            }
        }
    }

    public async logRejectedOperation(operation: vsls.RestrictedOperation, access: vsls.RestrictedOperationAccess) {
        await this.workspaceAccessControlService.rejectOperationAsync(operation, access);
    }

    public async onWorkspaceSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs) {
        if (e.changeType === vsls.WorkspaceSessionChangeType.Requested && sessionStateTracker.State === SessionState.Shared) {
            const { sessionNumber, userProfile } = e;
            const approval = await this.approveGuest(sessionNumber, e);
            if (typeof approval === 'boolean') {
                // if user approved, set their `accessControl`
                if (approval) {
                    await this.setUserAccessControl(sessionNumber, userProfile);
                }
                await this.workspaceUserService.acceptOrRejectGuestAsync(sessionNumber, { accept: approval });
            } else {
                await this.workspaceUserService.acceptOrRejectGuestAsync(
                    sessionNumber,
                    {
                        accept: false,
                        errorCode: approval.errorCode || vsls.ErrorCodes.CollaborationSessionGuestRejectedWithSpecificReason,
                        message: approval.errorMessage
                    });
            }
        }

        if (e.changeType === vsls.WorkspaceSessionChangeType.Unjoined && sessionStateTracker.State === SessionState.Shared) {
            await this.showGuestLeftNotification(e);
        }
    }

    private async approveGuest(sessionNumber: number, e: vsls.WorkspaceSessionChangedEventArgs): Promise<BooleanOrError> {
        const { userProfile } = e;
        const guestCapabilities = userProfile.clientCapabilities || {};
        const isGuestSupportsReadonly = (!guestCapabilities.extensionReadOnlySupport || !guestCapabilities.clientReadOnlySupport);
        const isAnonymousGuest = userProfile.isAnonymous;

        if ((workspaceSessionInfoTracker.isReadOnly || isAnonymousGuest) && isGuestSupportsReadonly) {
            // In read-only mode reject guests who do not support it.
            if (!guestCapabilities.extensionReadOnlySupport && !guestCapabilities.clientReadOnlySupport) {
                return { errorMessage: 'Your VS Live Share extension does not support read-only collaboration session. Please update the extension.' };
            }

            if (!guestCapabilities.clientReadOnlySupport) {
                const vsAppName = (e.applicationName === 'VisualStudio')
                    ? 'Visual Studio'
                    : undefined;

                const vsCodeAppName = (e.applicationName === 'VSCode')
                    ? 'VS Code'
                    : undefined;

                const appName = vsAppName || vsCodeAppName;

                return { errorMessage: `Your ${appName || 'client'} does not support read-only collaboration session. Please update ${appName || 'the client'}.` };
            }

            return { errorMessage: 'Read-only support is disabled. To join a read-only collaboration session, please enable the read-only support feature.' };
        }

        const anonymousGuestApprovalRequiredSetting = (Settings.get<string>(SettingKeys.anonymousGuestApproval) || '').toLowerCase();
        // if host does not allow anonymous guests and the guest is `anonymous`, reject them
        const isAutoRejectAnonymous = (anonymousGuestApprovalRequiredSetting === 'reject');
        if (isAutoRejectAnonymous && isAnonymousGuest) {
            return {
                errorCode: vsls.ErrorCodes.ForbiddenHttpStatusCode,
                errorMessage: localize('The host does not allow anonymous guests. Please sign in.')
            };
        }

        const allowedDomainsSetting = (Settings.get<string[]>(SettingKeys.allowedDomains) || []);

        if (allowedDomainsSetting && allowedDomainsSetting.length !== 0) {
            let emailDomain = userProfile?.email?.split('@')[1];
            if (!allowedDomainsSetting.includes(emailDomain)) {
                return {
                    errorCode: vsls.ErrorCodes.ForbiddenHttpStatusCode,
                    errorMessage: `The host has restricted you from joining the collaboration session.`
                };
            }
        }

        const guestDisplayName = this.buildGuestName(await this.getGuestDisplayName(userProfile), isAnonymousGuest, userProfile, true);
        const isApproveByAnonymous = (anonymousGuestApprovalRequiredSetting === 'prompt') && isAnonymousGuest;
        const isGuestApprovalRequired = Settings.get(SettingKeys.guestApprovalRequired);
        // if Guest Approval is required and read- write experiment is enabled, signed in users should see non-experiment toast with only "Accept and "Reject" options 
        const isSignedInGuestInExperiment = this.isReadWriteAnonymousEnabled() && !isAnonymousGuest;
        if (isGuestApprovalRequired || isApproveByAnonymous) {
            // If read-write anonymous experiment is not enabled 
            // Or if it is a read-only session 
            // Or if guest  signed in and experiment is enabled ->  do not change the flow. Use non-experiment toast
            if (!this.isReadWriteAnonymousEnabled() || workspaceSessionInfoTracker.isReadOnly || isSignedInGuestInExperiment) {
                return await this.waitForHostToAcceptGuest(sessionNumber, guestDisplayName, isAnonymousGuest, userProfile);
            } else if (this.isReadWriteAnonymousEnabled() && isAnonymousGuest) {
                return await this.waitForHostToAcceptGuestForReadWriteAnonymousExperiment(sessionNumber, guestDisplayName, isAnonymousGuest, userProfile);
            }
        }

        // Do not await on the notification to allow guest to join right away
        // The host can later kick them off
        this.showJoinNotification(guestDisplayName);

        return true;
    }

    private buildGuestName(guestDisplayName: string, isAnonymousGuest: boolean, userProfile: vsls.WorkspaceUserProfile, isNameBuiltForGuestJoinToast: boolean) {
        const isReadOnly = workspaceSessionInfoTracker.isReadOnly;
        const isHostAllowedAnonyUserToBeRW = workspaceSessionInfoTracker.getAnonymousAccess(userProfile.id) === AnonymousAccessLevel.readWrite;

        if (isReadOnly && !isAnonymousGuest) {
            guestDisplayName +=  localize('guestNameToast.ReadOnlyLabel');
        } else if (isAnonymousGuest) {
            if (this.isReadWriteAnonymousEnabled() &&  isNameBuiltForGuestJoinToast) {
                // Here we are building name for Guest Join Toast.
                // We don't know whether the Anonymous guest will be R/W or R/O yet.
                // Host will decide by clicking the button in the toast. So, just indicating guest is anonymous.         
                guestDisplayName += localize('guestNameToast.AnonymousLabel');
            } else if (this.isReadWriteAnonymousEnabled() && isHostAllowedAnonyUserToBeRW ) {
                guestDisplayName += localize('guestNameToast.AnonymousReadWriteLabel');
            } else {
                guestDisplayName += localize('guestNameToast.ReadOnlyAndAnonymousLabel'); 
            }             
        }

        return  guestDisplayName;
    }
 
    private async waitForHostToAcceptGuest(sessionNumber: number, guestDisplayName: string, isAnonymousGuest: boolean, userProfile: vsls.WorkspaceUserProfile): Promise<boolean> {
        const anonymousGuestApprovalRequiredSetting = (Settings.get<string>(SettingKeys.anonymousGuestApproval) || '').toLowerCase();
        const isAnonymousAccepted = (anonymousGuestApprovalRequiredSetting === 'accept');
        await this.workspaceUserService.fireProgressUpdatedToGuestAsync(vsls.WorkspaceProgress.WaitingForHost, sessionNumber);

        const message = `${guestDisplayName}` + localize('notification.AcceptRejectGuest');

        const ACCEPT = localize('notification.Accept');
        const REJECT = localize('notification.Reject');
        const ALWAYS_ACCEPT_ANONS = localize('notification.AlwaysAcceptAnonymous');

        const buttons = [ACCEPT, REJECT];

        if (isAnonymousGuest && !isAnonymousAccepted) {
            buttons.push(ALWAYS_ACCEPT_ANONS);
        }

        const selection = await vscode.window.showInformationMessage(
            message, ...buttons);

        if (this.isReadWriteAnonymousEnabled() && isAnonymousGuest) {
            await workspaceSessionInfoTracker.setAnonymousAccess(userProfile.id, selection);
        }

        if (selection === ALWAYS_ACCEPT_ANONS) {
            await Settings.save(SettingKeys.anonymousGuestApproval, 'accept');
        }

        await this.workspaceUserService.fireProgressUpdatedToGuestAsync(
            vsls.WorkspaceProgress.DoneWaitingForHost, sessionNumber);

        return (selection === ACCEPT) || (selection === ALWAYS_ACCEPT_ANONS);
    }

    private async waitForHostToAcceptGuestForReadWriteAnonymousExperiment(sessionNumber: number, guestDisplayName: string, isAnonymousGuest: boolean, userProfile: vsls.WorkspaceUserProfile): Promise<boolean> {

        await this.workspaceUserService.fireProgressUpdatedToGuestAsync(vsls.WorkspaceProgress.WaitingForHost, sessionNumber); 
        const message = `${guestDisplayName} ` + localize('notification.AcceptRejectGuest');

        const ACCEPT_READ_ONLY = localize('notification.AcceptReadOnly');
        const ACCEPT_READ_WRITE = localize('notification.AcceptReadWrite');
        const REJECT = localize('notification.Reject');
        const buttons = [ACCEPT_READ_ONLY, ACCEPT_READ_WRITE, REJECT];

        const selection = await vscode.window.showInformationMessage(
            message, ...buttons);

        await this.workspaceUserService.fireProgressUpdatedToGuestAsync(
            vsls.WorkspaceProgress.DoneWaitingForHost, sessionNumber);
        await workspaceSessionInfoTracker.setAnonymousAccess(userProfile.id, selection);

        return (selection === ACCEPT_READ_ONLY) || (selection === ACCEPT_READ_WRITE);
    }

    public isReadWriteAnonymousEnabled(): boolean | undefined {
        return getExpService()?.getTreatmentVariable('vscode', 'readWriteAnonymous');
    }

    private async showJoinNotification(guestDisplayName: string) {
        let message = `${guestDisplayName}` + localize('notification.InformGuestJoined');
        const showVerboseNotifications = !!Settings.get<boolean>(SettingKeys.showVerboseNotifications);
        await NotificationUtil.showInformationMessage(message, !showVerboseNotifications);
    }


    private async showGuestLeftNotification(e: vsls.WorkspaceSessionChangedEventArgs) {
        let nameAndUsername = this.getNameAndUsername(e.userProfile);
        nameAndUsername = this.buildGuestName(nameAndUsername, e.userProfile.isAnonymous, e.userProfile, false);
        switch (e.disconnectedReason) {
            case vsls.WorkspaceDisconnectedReason.NetworkDisconnected: {
                    let message = `${nameAndUsername}` + localize('notification.GuestDisconnected');
                    await vscode.window.showInformationMessage(message);
                    break;
                }
            case vsls.WorkspaceDisconnectedReason.Requested: {
                    let message = `${nameAndUsername}` + localize('notification.GuestLeft');
                    const showVerboseNotifications = !!Settings.get<boolean>(SettingKeys.showVerboseNotifications);
                    await NotificationUtil.showInformationMessage(message, !showVerboseNotifications);
                    break;
                }
            case vsls.WorkspaceDisconnectedReason.UserRemoved:
            case vsls.WorkspaceDisconnectedReason.UserBlocked:
            default:
                break;
        }
    }

    private async getGuestDisplayName(userProfile: vsls.WorkspaceUserProfile): Promise<string> {
        let nameAndUsername = this.getNameAndUsername(userProfile);

        await this.guestNameSemaphore.acquire();
        try {
            if (this.guestNameCounts.has(nameAndUsername)) {
                let newCount = this.guestNameCounts
                    .set(nameAndUsername, this.guestNameCounts.get(nameAndUsername) + 1)
                    .get(nameAndUsername);
                return `${nameAndUsername} (${newCount})`;
            } else {
                this.guestNameCounts.set(nameAndUsername, 0);
                return nameAndUsername;
            }
        } finally {
            this.guestNameSemaphore.release();
        }
    }

    private getNameAndUsername(userProfile: vsls.WorkspaceUserProfile): string {
        let username = userProfile.userName;
        let name = userProfile.name;

        if (!name) {
            return username;
        }

        if (userProfile.isAnonymous) {
            return name;
        }

        if (name === username) {
            return username;
        }

        const suffix = username ? ` (${username})` : '';
        return `${name}${suffix}`;
    }

    protected onWorkspaceAccessControlChanged(e: vsls.WorkspaceAccessControlEventArgs) {
        super.onWorkspaceAccessControlChanged(e);
        workspaceSessionInfoTracker.isReadOnly = this.workspaceAccessControl.defaultAccessControl.isReadOnly;
        SessionContext.onWorkspaceAccessControlChanged(e);
    }

    protected async initWorkspaceAccessControl() {
        await super.initWorkspaceAccessControl();
    }
}