import * as rpc from 'vscode-jsonrpc';
import * as ssh from '@vs/vs-ssh';
import { ILogger } from '@vs/vso-logging';
import { Signal, Mutex, assertDefined, assert } from '@vs/vscs-utils';
import { RpcProxy, RpcClient, ServiceInfo, IChannel } from '@vs/vso-rpc';
import {
    IJoinConnectOptions,
    IWorkspaceSessionInfo,
    ConnectedState,
    LatencyMetrics,
    WorkspaceApi,
    NoHostConnectedError,
    TelemetryEventNames,
    TelemetryPropertyNames,
    WorkspaceClientBase,
} from '@vs/vso-workspace-core';
import { vsls } from '@vs/vsls-contracts';
import { SshWorkspaceSessionFactory, SshReconnectOptions } from './SshWorkspaceSessionFactory';
import { SshWorkspaceSession, ConnectedStateChanged } from './SshWorkspaceSession';
import { streamFactoryType } from './streamFactoryType';
import { Performance, IPerformanceBlockBase } from '@vs/vscs-performance';
import {
    TelemetryEvent,
    TelemetryPropertyNames as CoreTelemetryPropertyNames,
} from '@vs/vso-telemetry';

type RpcProxyFor<T> = T & RpcProxy;

type RpcMethodMessage = rpc.NotificationMessage | rpc.RequestMessage;
export class WorkspaceClient extends WorkspaceClientBase {
    private checkConnectionMutex = new Mutex();
    private rpcConnected = new Signal<rpc.MessageConnection>();

    protected workspaceSessionInfo?: vsls.WorkspaceSessionInfo;
    protected sshWorkspaceSession?: SshWorkspaceSession;

    constructor(
        logger: ILogger,
        public readonly socketStreamFactory?: streamFactoryType,
        public readonly sshReconnectOptions?: SshReconnectOptions
    ) {
        super(
            new RpcClient(
                {
                    create: (rpcClient) => this.rpcConnected.promise,
                },
                logger
            ),
            logger
        );
    }

    public async join(joinConnectOptions: IJoinConnectOptions): Promise<vsls.WorkspaceSessionInfo> {
        const performance: Performance =
            joinConnectOptions.performance ??
            ({
                measure: <T>(
                    options: IPerformanceBlockBase,
                    callback: (...args: any[]) => Promise<T>
                ) => {
                    return callback();
                },
            } as Performance);

        assertDefined(
            joinConnectOptions.connectionInfo ||
                joinConnectOptions.sessionInfoFactory ||
                joinConnectOptions.liveShareEndpoint.length !== 0,
            'join connect options expected'
        );

        const sessionInfo = await this.getSessionInfo(joinConnectOptions, performance);

        // throw if host not connected
        if (sessionInfo.isHostConnected === false) {
            throw new NoHostConnectedError(joinConnectOptions.workspaceId);
        }

        // create the workspace session
        this.sshWorkspaceSession = await this.createWorkspaceSession(performance, sessionInfo);

        performance
            .measure(
                {
                    id: 'ssh-auth-completion',
                    name: 'Ssh auth completion',
                },
                () => this.sshWorkspaceSession!.authCompletion
            )
            .catch((err) => {
                this.trace.error('auth failed');
            });

        this.addToDisposables(this.sshWorkspaceSession);

        const sshSession = this.sshWorkspaceSession.sshSession;
        // hookup metrics events
        const fireMetricsUpdated = (
            bytesIn: number | undefined,
            bytesOut: number | undefined,
            latency: LatencyMetrics | undefined
        ) => {
            this.onWorkspaceMetricsUpdatedEmitter.fire({
                bytesIn,
                bytesOut,
                latency,
            });
        };

        sshSession?.metrics.onMessageReceived(() => {
            fireMetricsUpdated(sshSession.metrics.bytesReceived, undefined, undefined);
        });
        sshSession?.metrics.onMessageSent(() => {
            fireMetricsUpdated(undefined, sshSession.metrics.bytesSent, undefined);
        });
        sshSession?.metrics.onLatencyUpdated(() => {
            const latency = new LatencyMetrics(
                sshSession.metrics.latencyCurrentMs,
                sshSession.metrics.latencyAverageMs,
                sshSession.metrics.latencyMinMs,
                sshSession.metrics.latencyMaxMs
            );
            fireMetricsUpdated(undefined, undefined, latency);
        });

        this.trace.info(`join started`);
        const { clientVersionInfo, workspaceJoinInfo, clientCapabilities } = joinConnectOptions;
        const joinPromise = performance.measure(
            {
                id: 'join-internal',
                name: 'Joining the workspace',
            },
            () =>
                this.joinInternal(
                    sessionInfo,
                    clientVersionInfo ?? {},
                    workspaceJoinInfo,
                    clientCapabilities
                )
        );
        await Promise.all([this.sshWorkspaceSession.authCompletion, joinPromise]);

        this.onWorkspaceSessionConnectionChange(joinConnectOptions);

        // if check connection options is enabled.
        if (joinConnectOptions.checkConnectionOptions) {
            await this.setCheckConnectionOptions(joinConnectOptions.checkConnectionOptions);
        }

        return this.workspaceSessionInfo!;
    }

    protected ensureIsJoined(): void {
        assertDefined(this.sshWorkspaceSession, 'Ssh session not initiated yet');
    }

    protected canCheckConnection(): boolean {
        return this.sshWorkspaceSession?.isReconnecting === false;
    }

    protected async createWorkspaceSession(
        performance: Performance,
        sessionInfo: IWorkspaceSessionInfo
    ): Promise<SshWorkspaceSession> {
        return await performance.measure(
            {
                id: 'createSshWorkspaceSession',
                name: 'Creating the ssh workspace session',
            },
            () =>
                SshWorkspaceSessionFactory.createSshWorkspaceSession(
                    sessionInfo,
                    this.trace,
                    this.socketStreamFactory,
                    this.sshReconnectOptions
                )
        );
    }

    protected onWorkspaceSessionConnectionChange(joinConnectOptions: IJoinConnectOptions) {
        // wire up reconnection
        const sendReconnectEvent = (elapsed: number, result: ConnectedStateChanged) => {
            const reconnectEvent = new TelemetryEvent(TelemetryEventNames.WORKSPACE_RECONNECT);
            const telemetryProperties = joinConnectOptions.telemetryProperties;
            if (telemetryProperties) {
                Object.keys(telemetryProperties).forEach((key) =>
                    reconnectEvent.addProperty(key, telemetryProperties[key])
                );
            }

            reconnectEvent.addProperty(
                CoreTelemetryPropertyNames.FEATURE_NAME +
                    TelemetryPropertyNames.RECONNECT_SUCCEEDED,
                result.error === undefined ? true : false
            );
            reconnectEvent.addProperty(
                CoreTelemetryPropertyNames.FEATURE_NAME + TelemetryPropertyNames.RECONNECT_ELAPSED,
                elapsed
            );
            reconnectEvent.addProperty(
                CoreTelemetryPropertyNames.FEATURE_NAME +
                    TelemetryPropertyNames.RECONNECT_RETRY_COUNT,
                result.retryCount
            );

            if (result.error !== undefined) {
                if (result.error instanceof ssh.SshReconnectError) {
                    const reason: ssh.SshReconnectFailureReason =
                        result.error.reason ?? ssh.SshReconnectFailureReason.unknownClientFailure;
                    reconnectEvent.addProperty(
                        CoreTelemetryPropertyNames.FEATURE_NAME +
                            TelemetryPropertyNames.RECONNECT_ERROR_REASON,
                        reason
                    );
                }
                reconnectEvent.addProperty(
                    CoreTelemetryPropertyNames.FEATURE_NAME +
                        TelemetryPropertyNames.RECONNECT_ERROR_MESSAGE,
                    result.error.message
                );
            }

            reconnectEvent.send();
        };

        let start: number | undefined;
        this.sshWorkspaceSession?.onConnectedStateChanged((e) => {
            const elapsed = start ? Date.now() - start : 0;
            if (e.state === ConnectedState.Reconnecting) {
                start = Date.now();
            } else if (e.state === ConnectedState.Reconnected) {
                if (start) {
                    sendReconnectEvent(elapsed, e);
                }

                start = undefined;
            } else if (e.state === ConnectedState.Closed) {
                if (start) {
                    sendReconnectEvent(elapsed, e);
                }

                start = undefined;
            }

            this.onHostConnectionChangedEmitter.fire({
                state: e.state,
                duration: elapsed,
            });
        });

        this.trace.info(`join completed`);
    }

    public async disconnect(): Promise<void> {
        if (this.workspaceSessionInfo) {
            const sessionInfo = this.workspaceSessionInfo;
            this.workspaceSessionInfo = undefined;
            this.trace.info(`unjoing`);
            await this.getServiceProxy(vsls.WorkspaceService).unjoinWorkspaceAsync(sessionInfo.id!);
            this.dispose('disconnect');
        }
    }

    protected async getSessionInfo(
        joinConnectOptions: IJoinConnectOptions,
        performance: Performance
    ) {
        if (joinConnectOptions.connectionInfo) {
            return joinConnectOptions.connectionInfo;
        } else if (joinConnectOptions.sessionInfoFactory) {
            return await joinConnectOptions.sessionInfoFactory(joinConnectOptions.workspaceId);
        } else {
            return await performance.measure(
                {
                    id: 'workspaceApi-getWorkspaceSessionInfo',
                    name: 'get workspace session info from liveshare',
                },
                () =>
                    WorkspaceApi.getWorkspaceSessionInfo(
                        joinConnectOptions.workspaceId,
                        joinConnectOptions,
                        this.trace.createChild('WorkspaceApi')
                    )
            );
        }
    }

    protected async joinInternal(
        sessionInfo: IWorkspaceSessionInfo,
        clientVersionInfo: vsls.ClientVersionInfo,
        workspaceJoinInfo?: vsls.WorkspaceJoinInfo,
        clientCapabilities?: vsls.ClientCapabilities
    ): Promise<void> {
        const rpcStream = await this.sshWorkspaceSession!.createRpcMessageStream();

        // Note: we want to wrap the 'raw' ssh rpc reader stream
        const joinMessages: RpcMethodMessage[] = [];

        const listen = rpcStream.reader.listen.bind(rpcStream.reader);
        let dataCallback: rpc.DataCallback | undefined;
        const listenWrapper = (callback: rpc.DataCallback) => {
            dataCallback = callback;
            listen((data) => {
                if (!this.rpcConnected.isFulfilled && data.hasOwnProperty('method')) {
                    joinMessages.push(data as RpcMethodMessage);
                }

                callback(data);
            });
        };
        // inject the listen wrapper
        rpcStream.reader.listen = listenWrapper;

        const rpcConnection = this.rcpClientInstance.createRpcConnection(rpcStream, this.trace);
        rpcConnection.listen();

        const configClient: vsls.ConfigurationService = this.getServiceProxyWithConnection(
            rpcConnection,
            vsls.ConfigurationService
        );
        const hostVersionInfo = await configClient.exchangeVersionsAsync({}, clientVersionInfo);
        this.trace.info('Host version: ' + JSON.stringify(hostVersionInfo));

        if (!clientCapabilities) {
            clientCapabilities = new vsls.ClientCapabilities();
            clientCapabilities.isNonInteractive = false;
        }

        // default workspace join info
        let joinInfo: vsls.WorkspaceJoinInfo = {
            id: sessionInfo.id,
            connectionMode: vsls.ConnectionMode.Local, // Note "local" connection mode is correct when talking to remote service.
            joiningUserSessionToken: sessionInfo.sessionToken,
            clientCapabilities,
        };

        if (workspaceJoinInfo) {
            joinInfo = { ...joinInfo, ...workspaceJoinInfo };
        }

        const workspaceService: vsls.WorkspaceService = this.getServiceProxyWithConnection(
            rpcConnection,
            {
                name: vsls.WorkspaceService.name,
                methods: vsls.WorkspaceService.methods,
                voidMethods: vsls.WorkspaceService.voidMethods,
                events: [],
            }
        );

        this.workspaceSessionInfo = await workspaceService.joinWorkspaceAsync(joinInfo);

        // complete rpc connections
        this.rpcConnected.resolve(rpcConnection);

        // flush rpc messages that would happen during the join
        joinMessages.forEach((m) => {
            dataCallback!(m);
        });

        this.trace.info(
            `joinWorkspace -> session:${this.workspaceSessionInfo.sessionNumber} conversation:${this.workspaceSessionInfo.conversationId} join messages count:${joinMessages.length}`
        );
    }

    private getServiceProxyWithConnection<T>(
        rpcConnection: rpc.MessageConnection,
        serviceInfo: ServiceInfo<T>
    ): RpcProxyFor<T> {
        return RpcProxy.createWithConnection<T>(
            serviceInfo,
            rpcConnection,
            this.trace
        ) as RpcProxyFor<T>;
    }

    public async openStreamingChannel(
        streamId: string,
        cancellationToken?: rpc.CancellationToken
    ): Promise<IChannel> {
        assertDefined(this.sshWorkspaceSession, 'Ssh session not initiated yet');

        this.trace.info(`openStreamingChannel -> streamId:${streamId}`);
        const sshChannel = await this.sshWorkspaceSession.openStreamingChannel(
            streamId,
            cancellationToken
        );
        return sshChannel;
    }

    public async checkConnection(cancellationToken?: rpc.CancellationToken) {
        assertDefined(this.sshWorkspaceSession, 'Ssh session not initiated yet');

        this.trace.verbose('checking ssh connection');

        const sshSession = this.sshWorkspaceSession.sshSession;
        assert(!sshSession.isClosed, 'ssh session is closed');

        // Note: by sending a simple request to the ssh server session we want to guarantee a packet
        // was properly send and received no matter we know it won't be handled by the server logic.
        const request = new ssh.SessionRequestMessage('ping-check-connection', true);
        await this.checkConnectionMutex.dispatch(() =>
            sshSession.request(request, cancellationToken)
        );
    }
}
