import * as process from 'process';
import * as rpc from 'vscode-jsonrpc';

import { SudoPortforwarderClient } from '@vs/port-forwarder';
import { RpcClient } from '@vs/vso-rpc';
import { ILogger } from '@vs/vso-logging';
import { startSocketSessionOnPipe, lockAgent, sudoExecAgent } from '@vs/vso-node-utils';
import { ChildProcess } from 'child_process';
import { wait, Mutex } from '@vs/vscs-utils';

import { hubPortForwardingAppFile } from './hubConstants';
import { getAppFilePath, getAgentPipeName } from './connections';

const MAX_RETRIES = 5;
const WAIT_FIRST_TRY_MS = 10000;
const WAIT_NEXT_TRY_MS = 1000;

const sudoPortCreateMutex = new Mutex();

function getHubAppFilePath(extensionName: string) {
    return getAppFilePath(hubPortForwardingAppFile, extensionName);
}

/**
 * Launch the hub workspace as an agent
 * @param pipeName the desired pipe name
 */
function launchSudoPortForwardingHub(
    extensionName: string,
    workspaceId: string,
    pipeName: string,
    sudoWindowName?: string
): Promise<ChildProcess | undefined> {
    const hubAppFilePath = getHubAppFilePath(extensionName);

    // Note: we will use the same elctron app that runs the extension as our node host runtime.
    return sudoExecAgent(
        process.execPath,
        [
            hubAppFilePath,
            '--workspaceId',
            workspaceId,
            '--pipe',
            pipeName,
            '--keepAliveTime',
            '60000',
            '--autoExit',
            '--noLogConsole',
        ],
        {
            ELECTRON_RUN_AS_NODE: '1',
        },
        sudoWindowName || 'Codespaces Port Forwarder'
    );
}

export interface ISudoPortForwardingClientOptions {
    readonly sudoWindowName?: string;
    readonly timeoutMs?: number;
    readonly failFast?: boolean;
}

export function createSudoPortForwardingHubClient(
    extensionName: string,
    workspaceId: string,
    logger: ILogger,
    options?: ISudoPortForwardingClientOptions
): Promise<SudoPortforwarderClient> {
    const hubAppFilePath = getHubAppFilePath(extensionName);
    const { sudoWindowName, timeoutMs, failFast } = options || {};

    // Note: since we are invoking a 'sudo' type process we would be asked for credentials and so
    // we want this next code to be gated trough the local mutex.
    return sudoPortCreateMutex.dispatch<SudoPortforwarderClient>(async () => {
        const pipeName = getAgentPipeName(hubAppFilePath, 'pf', workspaceId);
        const startTime = new Date().getTime();
        let retry = 0;
        let launchError;
        while (true) {
            try {
                const socket = await startSocketSessionOnPipe(pipeName);
                const rpcHubConnection = rpc.createMessageConnection(socket, socket);
                rpcHubConnection.listen();

                const rpcClient = new RpcClient(
                    {
                        create: async (rpcClientLocal) => {
                            return Promise.resolve(rpcHubConnection);
                        },
                    },
                    logger
                );
                return new SudoPortforwarderClient(logger, rpcClient);
            } catch (err) {
                ++retry;
                const elapsedMs = new Date().getTime() - startTime;
                if (retry === 1) {
                    try {
                        await lockAgent(
                            hubAppFilePath,
                            () => {
                                launchSudoPortForwardingHub(
                                    extensionName,
                                    workspaceId,
                                    pipeName,
                                    sudoWindowName
                                ).catch((reason) => {
                                    logger.error(reason);
                                    if (failFast) {
                                        launchError =
                                            reason ||
                                            new Error('Failed to launch sudo port forwarding hub');
                                    }
                                });
                                return Promise.resolve();
                            },
                            logger
                        );
                    } catch (error) {
                        logger.error(`Failed to start sudo process`, error);
                    }
                    await wait(WAIT_FIRST_TRY_MS);
                } else if (
                    (typeof timeoutMs !== 'number' && retry === MAX_RETRIES) ||
                    (typeof timeoutMs === 'number' && elapsedMs > timeoutMs)
                ) {
                    logger.error(`Failed to connect to the hub workspace process`, err);
                    throw err;
                } else if (launchError) {
                    throw launchError;
                } else {
                    logger.verbose(`Attempting connection:${retry} failed`);
                    await wait(WAIT_NEXT_TRY_MS);
                }
            }
        }
    });
}
