import * as vscode from 'vscode';
import { PackageInfo } from './contracts/packageInfo';
import { extensionId } from '@vs/liveshare-api-contracts';
import { Settings, SettingKeys, featureFlags } from '@vs/liveshare-core';
/**
 * Keep these extensions in the lexical scope to prevent external extensions from overriding them.
 */

const privatePermissions = new Set<Permission>([
    Permission.authStrategies
]);
// prevent prototype modifications to affect the `Set`
Object.defineProperty(privatePermissions, 'has', {
  configurable: false,
  enumerable: false,
  writable: false,
  value: Set.prototype.has.bind(privatePermissions) 
});

export const enum Permission {
    readUserProfile = 'readUserProfile',
    shareServices = 'shareServices',
    contributeCommands = 'contributeCommands',
    autoShareServers = 'autoShareServers',
    authStrategies = 'authStrategies',

    // Special token that indicates all permissions are granted.
    all = '*',
    // Special token that indicates all permissions, including private ones are granted.
    allPrivate = '**',
    // Special token that indicates the extension should be entirely
    // blocked from using the API.
    block = '-',
}

export const getPermissionsForExtension = (extension: PackageInfo): string | string[] | null => {
    const allExtensionPermissions = Settings.get<any>(SettingKeys.extensionPermissions);
    if (!allExtensionPermissions) {
        return null;
    }

    // Look up permissions for the specific extension or all extensions by the publisher.
    const permissions = allExtensionPermissions[extension.fullName] ||
        allExtensionPermissions[`${extension.publisher}.*`];
    return permissions;
};

const isOnPermissionsList = (permission: Permission, permissions: string | string[] | null = []): boolean => {
    if (permissions === null) {
        permissions = [];
    }
    // if that's the private permission, only the `**` will count as "all",
    // while that's the non-private one, we can count both `**` and `*` as "all"
    const isAllPermissions = privatePermissions.has(permission)
        ? permissions.indexOf(Permission.allPrivate) >= 0
        : (permissions.indexOf(Permission.all) >= 0) || permissions.indexOf(Permission.allPrivate) >= 0;
    
    return Array.isArray(permissions) && ((permissions.indexOf(permission) >= 0) || isAllPermissions);
};

export const hasPermissionForExtension = (extension: PackageInfo, permission: Permission): boolean => {
    const vslsPublisher = vscode.extensions.getExtension(extensionId).packageJSON.publisher;

    if (extension.publisher === vslsPublisher) {
        // Extensions from the same publisher always have full permissions.
        return true;
    }

    if (featureFlags.api) {
        // Enable temporarily bypassing restrictions by setting the feature flag.
        return true;
    }

    // Check if permissions have been granted to this extension in settings.
    const permissions = getPermissionsForExtension(extension);
    
    // if the permission is all private, since it also includes all, return `true`
    if (permissions === Permission.allPrivate) {
        return true;
    }
    // if permission is marked as `private`, check if it is on the permissions list
    if (privatePermissions.has(permission)) {
        return isOnPermissionsList(permission, permissions);
    }
    // not a private permission, check if it is `all`
    if (permissions === Permission.all) {
        return true;
    }
    
    // otherwise check if the permision is on the list
    return isOnPermissionsList(permission, permissions);
};
