import * as net from 'net';
import * as rpc from "vscode-jsonrpc";
import { TraceSource } from "@vs/vso-logging";
import { MultiChannelRpcServer } from "@vs/vso-rpc-ssh";
import { NodeStream } from '@vs/vs-ssh';
import { SocketServer  } from './serverUtils';

export class MutliChannelRpcSocketServer<T extends { dispose?: () => void|Promise<void> }> implements SocketServer {
    private readonly rpcServer: MultiChannelRpcServer;
    private readonly server: T;

    constructor(trace: TraceSource, serverFactory: (rpcServer: MultiChannelRpcServer) => T) {
        this.rpcServer = new MultiChannelRpcServer(trace.withName('RpcServer'));
        this.server = serverFactory(this.rpcServer);
    }

    public async accept(socket: net.Socket): Promise<rpc.MessageConnection> {
        const transportStream = new NodeStream(socket);
        const [messageConnectInfo] = await this.rpcServer.acceptStream(transportStream);
        return messageConnectInfo;        
    }

    public async dispose(): Promise<void> {
        if (this.server && typeof this.server.dispose === 'function') {
            await Promise.resolve(this.server.dispose());
        }
    }
}
