import { contactProtocol } from '@vs/vsls-contracts';
export const enum ChatEventSource {
    command = 'command_palette',
    contacts = 'contacts_panel',
    started = 'started',
    statusBar = 'status_bar',
}

export const enum ChatType {
    directMessage = 'directMessage',
    session = 'session',
}

export interface IChatWindowInfo {
    contact: contactProtocol.Contact;
    unread: number;
}

// The following is ported from: https://github.com/vsls-contrib/chat
// Used for communication between the ChatViewController and the webview (WebViewContainer)
export enum MessageType {
    text = 'text',
    typing = 'typing',
    thread_reply = 'thread_reply',
    command = 'command',
    link = 'link',
    focus = 'is_focused',
    ready = 'is_ready',
    fetch_replies = 'fetch_replies'
}

export enum CommandType {
    clear = '/clear',
    share = '/share',
    end = '/end'
}

export const enum WindowType {
    im = 'im'
}

export interface Users {
    [id: string]: contactProtocol.Contact;
}

export interface ChatWindow {
    id: string;
    name: string;
    type: WindowType;
    readTimestamp: string | undefined;
    unreadCount: number;
    isDisabled: boolean;
    infoMessage?: string;
    categoryName?: string;
    contactMetadata?: IContactMetadata;
}

export interface IContactMetadata {
    id: string;
    email: string;
}

export interface WindowLabel {
    window: ChatWindow;
    unread: number;
    label: string;
}

export interface ExtensionMessage {
    type: MessageType;
    body: string;
}

export interface UIMessage {
    fontFamily: string;
    fontSize: string;
    provider: string;
    messages: WindowMessages;
    users: Users;
    window: ChatWindow;
    currentUser: contactProtocol.Contact;
    statusText: string;
}

export interface UIMessageDateGroup {
    groups: UIMessageGroup[];
    date: string;
}

export interface UIMessageGroup {
    messages: Message[];
    userId: string;
    user: contactProtocol.Contact;
    minTimestamp: string;
    key: string;
}

export interface Message {
    timestamp: string;
    userId: string;
    text: string;
    isEdited?: Boolean;
    attachment?: MessageAttachment;
    content: MessageContent | undefined;
    reactions: MessageReaction[];
    replies: MessageReplies;
}

export interface MessageAttachment {
    name: string;
    permalink: string;
}

export interface MessageContent {
    author: string;
    authorIcon?: string;
    pretext: string;
    title: string;
    titleLink: string;
    text: string;
    footer: string;
    borderColor?: string;
}

export interface MessageReaction {
    name: string;
    count: number;
    userIds: string[];
}

export interface MessageReply {
    userId: string;
    timestamp: string;
    text?: string;
    attachment?: MessageAttachment;
}

export interface MessageReplies {
    [timestamp: string]: MessageReply;
}

export interface WindowMessages {
    [timestamp: string]: Message;
}

export interface Messages {
    [windowId: string]: WindowMessages;
}

export interface WindowMessagesWithUndefined {
    [timestamp: string]: Message | undefined;
}
