import * as vscode from 'vscode';

import { IInittableDisposable } from '../contracts/IInittableDisposable';
import {
    Telemetry,
    FaultType,
} from '@vs/vso-telemetry';

import { ISessionContext } from '../ISessionContext';
import { TelemetryEventNames } from '../telemetry/TelemetryStrings';
import { ExtensionUtil } from '../utils/ExtensionUtil';
import { CommandId } from '../CommandConstants';
import { assert } from './common/coeditingUtils';
import { MessageFactory } from '../coediting/common/coauthoringService';
import { Settings } from '../Settings';
import { SettingKeys } from '../SettingKeys';
import { NotificationUtil } from '@vs/vscode-command-framework';
import { ParticipantSessionExplorerItem } from '../treeViews/ParticipantsTreeDataProvider';

function unPinAndFollowToTheSide(clientId: number, sessionContext: ISessionContext) {
    sessionContext.coeditingClient.unpinByClient(clientId, {explicit: true});
    sessionContext.coeditingClient.pin(null, clientId, true);
}

/**
 * Quick pick item that targets a co-editor.
 */
export interface CoEditorQuickPick extends vscode.QuickPickItem {
    targetSessionId: number;
}

export class CoEditingCommands implements IInittableDisposable {
    public constructor(private sessionContext: ISessionContext) { }

    public async init(): Promise<void> {
        await ExtensionUtil.tryRegisterCommand(CommandId.pin, this.pinWithParticipantPrompt, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.followToTheSide, this.followToTheSide, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.followToTheSideActivityBar, this.followToTheSideSpecificUser, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.followToTheSideTreeExplorer, this.followToTheSideSpecificUser, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.pinFromFileTreeExplorer, this.followSpecificUser, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.pinFromActivityBar, this.followSpecificUser, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.listParticipants, this.listParticipants, this, /* isEditorCommand */ false);

        await ExtensionUtil.tryRegisterCommand(CommandId.focusParticipantActivityBar, this.focusParticipant, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.focusParticipantFileTreeExplorer, this.focusParticipant, this, /* isEditorCommand */ false);

        await ExtensionUtil.tryRegisterCommand(CommandId.unpin, this.unpinEditorCommandHandler, this, /* isEditorCommand */ true);
        await ExtensionUtil.tryRegisterCommand(CommandId.unpinFromFileTreeExplorer, this.unpinClientCommandHandler, this, /* isEditorCommand */ false);
        await ExtensionUtil.tryRegisterCommand(CommandId.unpinFromActivityBar, this.unpinClientCommandHandler, this, /* isEditorCommand */ false);

        await ExtensionUtil.tryRegisterCommand('liveshare.changePresenter', this.changePresenter, this, /* isEditorCommand */ false);
    }

    public async dispose(): Promise<void> {
        ExtensionUtil.disposeCommand(CommandId.pin);
        ExtensionUtil.disposeCommand(CommandId.pinFromFileTreeExplorer);
        ExtensionUtil.disposeCommand(CommandId.pinFromActivityBar);
        ExtensionUtil.disposeCommand(CommandId.unpin);
        ExtensionUtil.disposeCommand(CommandId.unpinFromFileTreeExplorer);
        ExtensionUtil.disposeCommand(CommandId.unpinFromActivityBar);
    }

    private async followToTheSide() {
        if (!this.getCollaboratorsIfWeHaveSome()) {
            return;
        }

        if (!vscode.window.activeTextEditor) {
            return this.pinWithParticipantPrompt(false);
        }

        let clientId = this.sessionContext.coeditingClient.getClientIdIfEditorIsPinned(vscode.window.activeTextEditor);
        if (clientId === -1) {
            clientId = await this.promptForParticipantsToFollow(false);
        }

        if (clientId === -1) {
            return;
        }

        unPinAndFollowToTheSide(clientId, this.sessionContext);
    }

    private followToTheSideSpecificUser(user: { sessionId: number }) {
        unPinAndFollowToTheSide(user?.sessionId, this.sessionContext);
    }

    private async followSpecificUser(user: { sessionId: number } | undefined) {
        if (typeof user === 'undefined') {
            // User should not be undefined, log a fault. As a backup allow the user
            // to select the participant to follow from the quickpick dropdown.
            let types = '';
            const args = [].slice.call(arguments);
            args.forEach((arg) => types += ` ${arg === null ? null : typeof arg}`);
            Telemetry.sendFault(TelemetryEventNames.FOLLOW_USER_FAILURE, FaultType.Error, `User is undefined. Args length: ${args.length}. Args types: ${types}`);
            await this.pinWithParticipantPrompt(true /*alwaysShowParticipants*/);
            return;
        }

        await this.sessionContext.coeditingClient.pin(null,user.sessionId);
    }

    private async changePresenter(newPresenterId?: number) {
        const targetId = newPresenterId ? newPresenterId : await this.promptForParticipantToPresent();

        if (targetId < 0) {
            return;
        }

        this.sessionContext.coeditingClient.presentationManager.updatePresenterId(targetId);

        return;
    }

    private async pinWithParticipantPrompt(arg: any) {
        const coEditors = this.getCollaboratorsIfWeHaveSome();

        if (!coEditors) {
            return;
        }

        // This specific command is hooked up to the editor directly, and can
        // be called with a parameter. In the second case it's a bool -- easy!
        // But in the first case it's a URI. We don't do anything with URI's so
        // its not useful. Lets do a typecheck to make sure we handle this
        // correctly
        let alwaysShowParticipants: boolean = false;
        if (typeof arg === 'boolean') {
            alwaysShowParticipants = arg;
        }

        let targetClient = coEditors[0]; // Default to first participant
        if (coEditors.length > 1 || alwaysShowParticipants) {
            // if we have only 1 editor, theres no point in prompting. However,
            // there are times we use the list to inform people who is in the session
            // not just pin.
            targetClient = await this.promptForParticipantsToFollow(alwaysShowParticipants);
        }

        if (targetClient === -1) {
            return;
        }

        await this.sessionContext.coeditingClient.pin(null, targetClient);
    }

    private async promptForParticipantToPresent(): Promise<number> {
        const allParticipants = [this.sessionContext.coeditingClient.clientID].concat(
            this.sessionContext.collaboratorManager.getCollaboratorSessionIds()
        );

        const placeHolder = "Select a new presenter or press 'Escape' to cancel.";
        const allChoices = allParticipants.map(
            (participantId): CoEditorQuickPick => {
                let displayName = this.sessionContext.collaboratorManager.getDisplayName(
                    participantId
                );
                if (this.sessionContext.coeditingClient.presentationManager.currentPresenterId == participantId) {
                    displayName = `${displayName} (Current Presenter)`;
                }

                return {
                    description: displayName,
                    label: '$(person)',
                    targetSessionId: participantId,
                };
            }
        );

        const selectedChoice = await vscode.window.showQuickPick(allChoices, { placeHolder });
        if (!selectedChoice) {
            return -1;
        }

        return selectedChoice.targetSessionId;
    }

    private async promptForParticipantsToFollow(alwaysShowParticipants: boolean): Promise<number> {
        const coEditors = this.getCollaboratorsIfWeHaveSome();
        if (!coEditors) {
            return -1;
        }

        const placeHolder = alwaysShowParticipants
            ? coEditors.length + ' participant location(s) listed below. Select one to follow or press \'Escape\' when done.'
            : 'Select a participant to follow';
        const picks = coEditors.map((sessionId): CoEditorQuickPick => {
            const displayName = this.sessionContext.collaboratorManager.getDisplayName(sessionId);
            const lastKnownFile = this.sessionContext.coeditingClient.lastKnownFileForClient(sessionId);

            return {
                description: displayName,
                detail: lastKnownFile ? `Currently editing ${lastKnownFile}` : 'Not currently editing a shared document',
                label: '$(file-symlink-file)',
                targetSessionId: sessionId
            };
        });

        const pick = await vscode.window.showQuickPick(picks, { placeHolder });
        if (!pick) {
            return -1;
        }

        return pick.targetSessionId;
    }

    private async unpinClientCommandHandler(user: { sessionId: number }) {
        if (typeof user === 'undefined') { 
            const { coeditingClient } = this.sessionContext;
            const followedUsers = coeditingClient.getUsersBeingFollowed();
            const targetId = (Object.keys(followedUsers)[0]);

            assert(Object.keys(followedUsers).length <= 1, "User is following more than one person.");
            assert(Object.keys(followedUsers).length >= 1, "User is following less than one person.");

            if (targetId == undefined) {
                // Log a fault if the user parameter is undefined and we cannot get the followed user from the session context
                Telemetry.sendFault(TelemetryEventNames.UNFOLLOW_USER_FAILURE, FaultType.Error, `User parameter is undefined. Cannot find followed user from getUsersBeingFollowed(): ${followedUsers}.`);
                return;
            }

            this.sessionContext.coeditingClient?.unpinByClient(Number(targetId), {explicit: true});
            
            return;
        }
        this.sessionContext.coeditingClient?.unpinByClient(user.sessionId, {explicit: true});
    }
    
    private async unpinEditorCommandHandler(textEditor: vscode.TextEditor, edit: vscode.TextEdit, args: any[]) {
        this.sessionContext.coeditingClient?.unpinByEditor(textEditor, {explicit: true});
    }

    private getCollaboratorsIfWeHaveSome(): number[] {
        if (!this.sessionContext.coeditingClient || !this.sessionContext.collaboratorManager) {
            return;
        }

        const coEditors = this.sessionContext.collaboratorManager.getCollaboratorSessionIds();
        const coEditorCount = coEditors.length;

        if (coEditorCount < 1) {
            return;
        }

        return coEditors;
    }

    private async listParticipants(): Promise<void> {
        await this.pinWithParticipantPrompt(true);
    }

    private async focusParticipant(user: { sessionId: number }) {
        Telemetry.sendTelemetryEvent(TelemetryEventNames.FOCUS_PARTICIPANT);

        this.sessionContext.coeditingClient.postMessage(MessageFactory.SummonMessage(this.sessionContext.coeditingClient.clientID, user.sessionId));
        const showVerboseNotifications = !!Settings.get<boolean>(SettingKeys.showVerboseNotifications);
        await NotificationUtil.showInformationMessage('Focus request sent.', showVerboseNotifications);
    }

}
