import { IWorkspaceConnectionInfo } from './IWorkspaceSessionInfo';

/**
 * Error when a workspace has no host connected, hence no join could happen.
 */
export class NoHostConnectedError extends Error {
    constructor(public readonly workspaceId: string) {
        super(`Host not connected to workspace:${workspaceId}`);
    }
}

/**
 * Type of relay connection error types.
 */
export enum RelayErrorType {
    ConnectionError = 1,
    SasInvalid = 2,
    EndpointNotFound = 3,
    ListenerOffline = 4,
    ServerError = 5,
}

/**
 * Error used when a connection to an Azure relay failed.
 */
export class RelayConnectionError extends Error {
    constructor(
        message: string,
        public readonly errorContext: {
            errorType: RelayErrorType;
            workspaceConnectionInfo: IWorkspaceConnectionInfo;
        }
    ) {
        super(message);
    }
}
