import * as vscode from 'vscode';
import { CancellationToken } from 'vscode';

import { ICommandContext } from '@vs/vscode-command-framework';
import { IDependencies } from '../contracts/IDependencies';
import { vsls } from '@vs/vsls-contracts';
import { TelemetryPropertyNames } from '../telemetry/TelemetryStrings';
import { traceSource as trace } from '@vs/vscode-command-framework';
import { localize } from '../localize';
import { Settings } from '../Settings';
import { CancellationError, wait } from '@vs/vscs-utils';
import { getExpService } from '../exp/ExperimentationService';
import { ContactManagerEvents, IContactManager, InviteLinkJoining } from '../contracts/IContactManager';
import { JoinCommandOptions } from './JoinCommandOptions';
import { updateWorkspaceFolders } from '../utils/workspaceUtils';

/**
 * Settings that are used during LiveShare collab sessions, to set on the workspace file.
 */
const baseWorkspaceSettings: { [key: string]: any; } = {
    // Don't show extension recommendations to guests, since
    // we're trying to avoid them having to install them
    'extensions.ignoreRecommendations': true,

    // Always detect the indentation from the file, as a best-guess for
    // ensuring existing code formatting rule is followed. True is the default
    // in vscode, this is to ensure that others turning it off, get it back on
    'editor.detectIndentation': true,

    // Since formatting policy is driven entirely by the host, make sure that 
    // the decision of when to format is also driven by the host.
    'editor.formatOnSave': false,

    // Don't persist our state if closed, so they get a blank IDE rather than
    // trying to reconnect to a session days later
    'files.hotExit': 'off',

    // Make sure the guest isn't sending periodic save requests. The host will
    // have their settings apply, but the guest won't be randomly saving files.
    // However, the human guest can still press save.
    'files.autoSave': 'off',

    // Disable the guest from automatically updating code contents as typing
    // happens. These settings, if set on the host, will still be applied. This
    // ensures that the guests don't have conflicting settings
    'files.trimTrailingWhitespace': false,
    'files.insertFinalNewline': false,
    'files.trimFinalNewlines': false,

    // disable task auto-detect for built-in providers
    'typescript.tsc.autoDetect': 'off',
    'jake.autoDetect': 'off',
    'grunt.autoDetect': 'off',
    'gulp.autoDetect': 'off',
    'npm.autoDetect': 'off',

    // This setting allows guests to set breakpoints in any file within the workspace they
    // are joining, without requiring them to install the respective language extensions.
    'debug.allowBreakpointsEverywhere': true,

    // This setting ensures that the guests build-in HTML auto-closing logic
    // doesn't run, since it will already run on the host-side
    'html.autoClosingTags': false,
};

function ensureWorkspaceName(workspaceSessionInfo: vsls.WorkspaceSessionInfo, rootUri?: vscode.Uri): Promise<boolean> {
    if (!vscode.workspace.workspaceFolders) {
        return;
    }

    if (!workspaceSessionInfo ||
        (vscode.workspace.workspaceFolders.length > 0 && vscode.workspace.workspaceFolders[0].name === workspaceSessionInfo.name)) {
        return;
    }

    if (vscode.workspace.workspaceFolders.length <= 0 && !rootUri) {
        if (getExpService()?.getTreatmentVariable('vscode', 'joinFailureUriOfUndefined')) {
            return;
        }
    }

    if (rootUri) {
        return updateWorkspaceFolders(0, vscode.workspace.workspaceFolders.length, {
            uri: rootUri,
            name: workspaceSessionInfo.name || localize('emptyWorkspace.liveShareWorkspace')
        });
    }
}



export class JoinCommandUtilities {
    private static vslsLinkRegex = new RegExp(`${Settings.scheme}:\?.*join.*workspaceId=([0-9A-Z-]+)`, 'i');
    private static readonly joinLinkRegex = /([a-z|\-]+\.)+liveshare.*\/join(\/)?\?([0-9a-z]{36})/im;
    private static readonly joinLinkEncodedRegex = /([^\dF][a-z|\-]+\.)+liveshare.*\%2Fjoin(\%2F)?\%3F([0-9a-z]{36})/im;
    private static readonly vscodeDevJoinLinkRegex = /vscode.dev\/liveshare\/([0-9a-z]{36})/im;

    public static async finishInviteLinkJoining(contactManager: IContactManager, workspaceId: string): Promise<void> {      
        const inviteLinkJoining = JoinCommandUtilities.getInviteLinkJoining(workspaceId);
        if (!inviteLinkJoining) {
            return;
        }
        // transition -> None
        const finishInviteWorkflow = () => contactManager.fireInviteStatusChanged(
            inviteLinkJoining.targetContactId,
            inviteLinkJoining.fromContactId,
            vsls.InviteContactStatus.None);

        // If no sent message provider it could be related with signed in is in progress
        if (!contactManager.hasSendMessageProvider) {
            new Promise((resolve) => {
                contactManager.once(ContactManagerEvents.ProviderCapabilitiesChanged, () => {
                    if (contactManager.hasSendMessageProvider) {
                        resolve(null);
                    }
                });
            }).then(finishInviteWorkflow);
        } else {
            await finishInviteWorkflow();
        }
    }

    public static extractLiveshareWorkspaceId(joinCollaborationLink: string = '') {
        const { linkMatch, linkEncodedMatch, vscodeDevLinkMatch, cascadeMatch } = JoinCommandUtilities.getLiveshareLinkMatch(joinCollaborationLink);

        if (linkMatch) {
            return linkMatch[3];
        }

        if (linkEncodedMatch) {
            return linkEncodedMatch[3];
        }

        if (vscodeDevLinkMatch) {
            return vscodeDevLinkMatch[1];
        }

        if (cascadeMatch) {
            return cascadeMatch[1];
        }
    }

    public static extractLiveshareLink(joinCollaborationLink: string = '') {
        const {
            linkMatch,
            linkEncodedMatch,
            vscodeDevLinkMatch,
            cascadeMatch
        } = JoinCommandUtilities.getLiveshareLinkMatch(joinCollaborationLink);

        if (linkMatch) {
            return `https://${linkMatch[0]}`;
        }

        if (linkEncodedMatch) {
            return `https://${decodeURIComponent(linkEncodedMatch[0])}`;
        }

        if (vscodeDevLinkMatch) {
            return `https://${vscodeDevLinkMatch[0]}`;
        }

        if (cascadeMatch) {
            return cascadeMatch[0];
        }
    }

    public static async applyGuestSettingsToWorkspace(configurationTarget?: vscode.ConfigurationTarget | boolean): Promise<void> {
        const settings = vscode.workspace.getConfiguration();
        for (const settingName of Object.keys(baseWorkspaceSettings)) {
            try {
                const oldValue = settings.get(settingName);
                const newValue = baseWorkspaceSettings[settingName];
                if (newValue !== oldValue) {
                    trace.verbose(`settingName:${settingName} old:${oldValue} new:${newValue}`)
                    await settings.update(settingName, newValue, configurationTarget ? configurationTarget : vscode.ConfigurationTarget.Workspace);
                }
            } catch (e) {
                trace.info(`[applying guest workspace settings]: Failed to set the "${settingName}" setting on the workspace.`);
            }
        }
    }

    public static getBaseWorkspaceSettings(): { [key: string]: any; } {
        return Object.assign({}, baseWorkspaceSettings);
    }

    public static async showInformationMessage(
        message: string,
        isVerbose: boolean,
        ...items: any[]
    ): Promise<any> {
        if (!isVerbose) {
            return (await import('vscode')).window.showInformationMessage(message, ...items);
        }
    }

    public static async showWaitingForHostProgressBar(
        dependencies: IDependencies,
        workspaceInfoFactory: () => Promise<vsls.WorkspaceInfo>,
        timeoutInMins: number,
        context: ICommandContext): Promise<boolean> {
        let isCancelled = false;
        const { cancellationTokenSource, telemetryEvent } = context;
        const commandCancellationToken = cancellationTokenSource && cancellationTokenSource.token;

        return await dependencies.progressNotifierUtil().create(
            { title: 'Waiting for the host to start the session...' },
            commandCancellationToken,
            async (progressUIcancellationToken: CancellationToken) => {
                return new Promise(async (resolve, reject) => {

                    const cancel = () => {
                        isCancelled = true;
                        telemetryEvent.addProperty(TelemetryPropertyNames.RETRY_JOIN, 'True');
                        reject(new CancellationError(`The operation was cancelled.`));
                    };

                    if (progressUIcancellationToken) {
                        if (progressUIcancellationToken.isCancellationRequested) {
                            cancel();
                        } else {
                            progressUIcancellationToken.onCancellationRequested(async () => {
                                cancel();
                            });
                        }
                    }

                    try {
                        const endTime = new Date();
                        endTime.setMinutes(endTime.getMinutes() + timeoutInMins);
                        let workspaceInfo;

                        while (new Date() < endTime && !isCancelled) {
                            await wait(1000);
                            workspaceInfo = await workspaceInfoFactory();

                            if (!workspaceInfo) {
                                resolve(false);
                            }
                            if (workspaceInfo.isHostConnected === true) {
                                resolve(true);
                            }
                        }
                        resolve(false);
                    } catch (e) {
                        reject(e);
                    }
                });
            });
    }

    public static addAdditionalRootsFromFileServiceToWorkspace(fileService: vsls.FileService, workspaceSessionInfo: vsls.WorkspaceSessionInfo) {
        const vslsUriFactory = (rootInfo: vsls.FileRootInfo) => vscode.Uri.parse(`${Settings.scheme}:${rootInfo.path}`);

        fileService.listRootsAsync({ enableMultipleRoots: true }).then(async (roots: vsls.FileRootInfo[]) => {
            try {
                const rootUri = vscode.workspace.workspaceFolders && vscode.workspace.workspaceFolders.length > 0 ? vscode.workspace.workspaceFolders[0].uri : vslsUriFactory(roots[0]);
                await ensureWorkspaceName(workspaceSessionInfo, rootUri);

                if (roots.length < 2) {
                    return;
                }

                // Convert the paths into URIs. Note we will skip the first root since this will be updated through
                // ensureWorkspaceName function
                const workspaceFolders: { uri: vscode.Uri; name: string }[] = roots.slice(1).map((root, index) => {
                    return {
                        uri: vslsUriFactory(root),
                        name: root.friendlyName || `Workspace ${index + 1}`,
                    };
                });

                // now the non-primary workspace folders
                const didAddFolders = await updateWorkspaceFolders(1, 0, ...workspaceFolders);
                if (!didAddFolders) {
                    throw new Error('Unable to add non-primary workspace folders');
                }
            } catch (err) {
                trace.error(`Failed to update workspace folders`, err);
            }
        });
    }

    /**
     * Function to restore LiveShare workspace without a reload.
     * @param workspaceid Workspace id string.
     * @param workspaceName Worksapce name string, if present.
     * @returns void
     */
    public static async restoreLiveshareWorkspaceState(workspaceid: string, workspaceName: string = 'Loading file tree...') {
        const settings = vscode.workspace.getConfiguration();

        await settings.update('vsliveshare.join.reload.workspaceId', workspaceid, vscode.ConfigurationTarget.Workspace);
        await JoinCommandUtilities.applyGuestSettingsToWorkspace();

        let primaryWorkspaceRoot = `${Settings.scheme}:/`;

        const didAddFolder = await updateWorkspaceFolders(0, null, {
            uri: vscode.Uri.parse(primaryWorkspaceRoot),
            name: workspaceName
        });

        return;
    }

    
    /**
     * Check if the workspace name is what Live Share uses for VSCode workspace on the guest.
     * @param workspace VSCode workspace
     * @returns true if the workspace has the name expected for Live Share guest's VSC workspace.
     */
     public static isLiveshareWorkspaceName(workspace: typeof vscode.workspace): boolean {
        return workspace?.name === 'Visual Studio Live Share (Workspace)';
    }

    /**
     * Check if a workspace is a Live Share guest workspace and get the workspace file path.
     * @param workspace VSCode workspace to check.
     * @returns Workspace file path if it's a valid Live Share guest's VSC workspace; Otherwise, undefined.
     */
    public static async getLiveShareWorkspaceFile(workspace: typeof vscode.workspace): Promise<string|undefined> {
        if (JoinCommandUtilities.isLiveshareWorkspaceName(workspace)) {
            const workspaceFile = workspace.workspaceFile;
            if (workspaceFile && workspaceFile.scheme === 'file') {
                return workspaceFile.fsPath;
            }
        }
    }

    /**
     * Function to check if the VSCode instance loaded in context of LiveShare workspace that does not have folders.
     * @param workspace VSCode workspace to check on.
     * @returns boolean Whether the workspace is LiveShare workspace with no folders.
     */
    public static isBrokenLiveshareWorkspaceFile(workspace: typeof vscode.workspace): boolean {
        return JoinCommandUtilities.isLiveshareWorkspaceName(workspace) && JoinCommandUtilities.isEmptyWorkspace(workspace);
    }

    public static isEmptyWorkspace(workspace: typeof vscode.workspace): boolean {
        return !workspace.workspaceFolders || (workspace.workspaceFolders.length === 0);
    }

    public static async setInviteLinkJoining(workspaceId: string, options: JoinCommandOptions, context: ICommandContext): Promise<void> {
        // Note: a simple way to persist the next relaod is using the memento by using the workspace Uri
        // and then use the invite link later on the post load command
        if (options.inviteLinkJoining) {
            // coming from an invite link
            context.telemetryEvent?.addProperty(TelemetryPropertyNames.JOIN_FROM_INVITE_LINK, 'True');

            // since the next execute command will force a reload let's store what we want to when the join command finished
            await Settings.saveMemento(workspaceId, options.inviteLinkJoining);
        }
    }

    public static getInviteLinkJoining(workspaceId: string): InviteLinkJoining | undefined {
        const inviteLinkJoining = Settings.getMemento<InviteLinkJoining>(workspaceId);
        if (inviteLinkJoining) {
            // remove from the memento
            Settings.saveMemento(workspaceId, null);
        }
    
        return inviteLinkJoining;
    }

    private static getLiveshareLinkMatch(joinCollaborationLink: string = '') {
        return {
            linkMatch: joinCollaborationLink.match(this.joinLinkRegex),
            linkEncodedMatch: joinCollaborationLink.match(this.joinLinkEncodedRegex),
            vscodeDevLinkMatch: joinCollaborationLink.match(this.vscodeDevJoinLinkRegex),
            cascadeMatch: joinCollaborationLink.match(this.vslsLinkRegex)
        };
    }
}
