import * as rpc from 'vscode-jsonrpc';
import { EventEmitter } from 'events';
import { IRpcMessageStream } from './RpcServiceHandler';

/**
 * Create a duplex rpc stream loopback to connect to rpc connections on the same process.
 * @returns the pair of rpc message streams.
 */
export function createDuplexRpcMessageStreams(): [IRpcMessageStream, IRpcMessageStream] {
    const readableStream1 = new DuplexReadableStream();
    const writableStream1 = new DuplexWritableStream(readableStream1);
    const readableStream2 = new DuplexReadableStream();
    const writableStream2 = new DuplexWritableStream(readableStream2);

    const messageReader1 = new rpc.StreamMessageReader(readableStream1 as NodeJS.ReadStream);
    const messageWriter1 = new rpc.StreamMessageWriter(
        (<any>writableStream1) as NodeJS.WritableStream
    );

    const messageReader2 = new rpc.StreamMessageReader(readableStream2 as NodeJS.ReadStream);
    const messageWriter2 = new rpc.StreamMessageWriter(
        (<any>writableStream2) as NodeJS.WritableStream
    );

    return [
        {
            reader: messageReader1,
            writer: messageWriter2,
        },
        {
            reader: messageReader2,
            writer: messageWriter1,
        },
    ];
}

class DuplexReadableStream extends EventEmitter {}

class DuplexWritableStream extends EventEmitter {
    constructor(private readableStream: DuplexReadableStream) {
        super();
    }

    public write(str: string, encoding?: string, cb?: (err?: Error | null) => void): boolean {
        this.readableStream.emit('data', str);
        return true;
    }
}
