'use strict';

import { ICommandContext } from '@vs/vscode-command-framework';
import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { DecoratorHelper } from '../utils/DecoratorHelper';

export function singleInvocationCommandDecorator(commandId: string) {
    return DecoratorHelper.setupDecorator((command: ICommand<any>) => new SingleInvocationCommandDecorator(commandId, command));
}

interface CommandInvocations {
    numInvocations: number;
    maxInvocations: number;
}

const defaultCommandInvocations: CommandInvocations = {
    numInvocations: 0,
    maxInvocations: 1
};

export class SingleInvocationCommandDecorator implements ICommandDecorator {

    private static commandInvocations: { [commandId: string]: CommandInvocations } = {};
    
    constructor(private commandId: string, public next: ICommand<any>) {
        if (!SingleInvocationCommandDecorator.commandInvocations[commandId]) {
            SingleInvocationCommandDecorator.commandInvocations[commandId] = { ...defaultCommandInvocations };
        }
    }

    get numInvocations(): number {
        return SingleInvocationCommandDecorator.commandInvocations[this.commandId].numInvocations;
    }

    set numInvocations(numInvocations: number) {
        SingleInvocationCommandDecorator.commandInvocations[this.commandId].numInvocations = numInvocations;
    }
    
    get maxInvocations(): number {
        return SingleInvocationCommandDecorator.commandInvocations[this.commandId].maxInvocations;
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        if (this.numInvocations >= this.maxInvocations) {
            return;
        }
        this.numInvocations++;
        try {
            return await this.next.invoke(options, context);
        } catch (e) {
            throw e;
        } finally {
            this.numInvocations--;
        }
    }

}
