import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { IRpcRequestContext, IRpcServiceHandlerInfo } from '@vs/vso-rpc';
import { IDependencies, workspaceSessionInfoTracker } from '@vs/liveshare-core';

const maxChatHistoryCount = 200;

export class ChatService implements vsls.ChatService, IRpcServiceHandlerInfo, vscode.Disposable {
    private readonly eventEmitter = new vscode.EventEmitter<vsls.MessageReceivedEventArgs>();
    private readonly messageHistory: Array<vsls.ChatMessage> = [];
    private readonly participants = new Map<number, vsls.ChatParticipant>();
    private disposables: vscode.Disposable[] = [];

    public constructor(dependencies: IDependencies)
    {
        this.disposables.push(dependencies.workspaceUserService().onWorkspaceSessionChanged((e) => this.onUserSessionChanged(e)));

        // Add host participant info
        const sessionInfo = workspaceSessionInfoTracker.workspaceSessionInfo;
        if (!sessionInfo) {
            throw Error('workspaceSessionInfoTracker.workspaceSessionInfo is not set');
        }
        const userProfile = sessionInfo.sessions[sessionInfo.sessionNumber];
        this.addOrUpdateParticipant(userProfile, sessionInfo.sessionNumber);
    }

    public serviceInfo = vsls.ChatService;

    public onMessageReceived: vscode.Event<vsls.MessageReceivedEventArgs> = this.eventEmitter.event;

    public async getMessageHistoryAsync(): Promise<vsls.ChatMessage[]> {
        return this.messageHistory;
    }

    public async getParticipantsAsync(): Promise<vsls.ChatParticipant[]> {
        return Array.from(this.participants.values())
    };

    public async sendMessageAsync(message: vsls.ChatMessage, cancellationToken?: vscode.CancellationToken,  rpcRequestContext?: IRpcRequestContext): Promise<void> {
        message.fromId = rpcRequestContext.session.toString();
        if (message.type === vsls.ChatMessageType.Text) {
            if (this.messageHistory.length === maxChatHistoryCount) {
                this.messageHistory.shift();
            }

            this.messageHistory.push(message);
        }

        this.eventEmitter.fire({message});
    }

    public dispose() {
        for (const disposable of this.disposables) {
            disposable.dispose();
        }
        this.disposables = [];
    }

    public async disposeAsync(): Promise<void> {
        this.dispose();
    }

    private onUserSessionChanged(e: vsls.WorkspaceSessionChangedEventArgs) {
        this.addOrUpdateParticipant(e.userProfile, e.sessionNumber);
    }

    private addOrUpdateParticipant(userProfile: vsls.WorkspaceUserProfile, sessionNumber: number) {
        const participant: vsls.ChatParticipant = {
            name: userProfile.name || userProfile.userName,
            email: userProfile.email,
            id: sessionNumber.toString()
        };

        this.participants.set(sessionNumber, participant);
    }
}