import { IHubProxy } from '@vs/vso-signalr-client-proxy';
import { CancellationToken } from 'vscode-jsonrpc';
import { Signal } from '@vs/vscs-utils';

export class HubProxyUtils {
    public static async waitForConnection(
        hubProxy: IHubProxy,
        cancellationToken?: CancellationToken
    ): Promise<void> {
        if (!hubProxy.isConnected) {
            const connected = new Signal<boolean>(cancellationToken);
            const disposable = hubProxy.onConnectionStateChanged(() => {
                if (hubProxy.isConnected) {
                    connected.resolve(true);
                }

                return Promise.resolve();
            });

            await connected.promise;
            disposable.dispose();
        }
    }
}
