import * as vscode from 'vscode';
import * as git from '../../typings/git';
import { TraceSource } from '@vs/vso-logging';
import { ProviderBase } from './ProviderBase';
import { contactProtocol } from '@vs/vsls-contracts';
export function registerGitProvider(registerCallback: (id: string, provider: contactProtocol.ContactServiceProvider) => void, trace: TraceSource)  {

    try {
        const gitExtension = vscode.extensions.getExtension<git.GitExtension>('vscode.git');
        if (gitExtension) {
            const api = gitExtension.exports.getAPI(1);
            const gitProvider = new GitProvider(api);
            registerCallback('git', gitProvider);
        }
    } catch (err) {
        trace.error(`Failed to register Git provider error:${err}`);
    }
}

/**
 * GIT provider implementation on the context service protocol defined by vs live share
 */
class GitProvider extends ProviderBase {
    private readonly gitPrivate: any;

    constructor(private readonly api: git.API) {
        super();
        const gitPrivate = (<any>api)._model.git;
        const keyExec = 'exec';
        if (typeof gitPrivate[keyExec] === 'function') {
            this.gitPrivate = gitPrivate;
        } else {
            throw new Error('Missing Git exec function');
        }
    }

    protected async requestInitialize(request: contactProtocol.InitializeRequest): Promise<contactProtocol.InitializeResponse> {

        // Note: we depend on the private 'exec' fucntion to retrieve author commit info
        // otherwise we will be a silent provider that does notify any suggested contact
        if (this.gitPrivate) {
            const repos = this.api.repositories;

            if (repos.length > 0) {
                this.notifyRepoSuggestedUsers(repos[0]);
            } else {
                this.api.onDidOpenRepository( async e => {
                    this.notifyRepoSuggestedUsers(e);
                }); 
            }
        }

        return {
            description: 'Git',
            capabilities: {
                supportsDispose: false,
                supportsInviteLink: false,
                supportsPresence: false,
                supportsContactPresenceRequest: false,
                supportsPublishPresence: false
            }
        }; 
    }

    private async notifyRepoSuggestedUsers(repo: git.Repository) {
        this.getAuthors(repo).then((result) => {
            this.notifySuggestedUsers(
                result.map(a => <contactProtocol.Contact> {
                    id: a.email,
                    displayName: a.author,
                    email: a.email
                }));
        });
    }

    /**
     * Return the authors email from the commits on the current HEAD branch of a git repo
     * @param repo
     */
    private async getAuthors(repo: git.Repository): Promise<AuthorInfo[]> {
        const MAX_COMMITS = 75;
        const MAX_AUTHORS = 10;
        const MAX_DAYS = 30;

        const now = new Date();
        const authorsSet = new Set<string>();
        const authors: AuthorInfo[] = [];

        const selfEmail = (await this.gitExec(repo, ['config', '--global', 'user.email'])).trim();
        const selfName = (await this.gitExec(repo, ['config', '--global', 'user.name'])).trim();

        let commitCounter = 0;
        await repo.status();
        if (repo.state && repo.state.HEAD) {
            const processCommit = async (commitId: string) => {
                if (!commitId || commitCounter > MAX_COMMITS || authorsSet.size > MAX_AUTHORS) {
                    return;
                }

                const authorInfo = await this.getAuthorInfo(repo, commitId);
                if (authorInfo.timestamp) {
                    const diffTime = Math.abs(now.getTime() - authorInfo.timestamp.getTime());
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    if (diffDays > MAX_DAYS) {
                        return;
                    }
                }

                if (authorInfo.email !== selfEmail &&
                    authorInfo.author !== selfName &&
                    authorInfo.email && !authorsSet.has(authorInfo.email) &&
                    !authorInfo.email.includes('@users.noreply.github.com')) {
                    authorsSet.add(authorInfo.email);
                    authors.push(authorInfo);
                }
                
                ++commitCounter;
                const { parents } = await repo.getCommit(commitId);
                if (parents.length > 0) {
                    await Promise.all(parents.map(cid => { return processCommit(cid); }));
                }
            };

            await processCommit(repo.state.HEAD.commit);
        }
        return authors;
    }

    private async getAuthorInfo(repo: git.Repository, commitId: string): Promise<AuthorInfo> {

        const result = await this.gitExec(repo, ['show', '-s', '--format=%an <%ae> [%ai]', commitId]);
    
        const author = result.substr(0, result.indexOf('<')).trim();
        let email = undefined; 

        const emailMatches = result.match(/\<(.*?)\>/);
        if (emailMatches) {
            email = emailMatches[1];
        }

        let timestamp: Date = undefined;
        const timestampMatches = result.match(/\[(.*?)\]/);
        if (timestampMatches && timestampMatches.length === 2) {
            timestamp = new Date(timestampMatches[1]);
        }

        return {
            email,
            author,
            timestamp
        };
    }

    /**
     * Since Git vscode extension does not provide access to the author commit, this method
     * will use the private Git instance and use the 'exec' function
     * @param repo 
     * @param args 
     */
    private async gitExec(repo: git.Repository, args: string[]): Promise<string> {
        const resultPromise = <Promise<any>>this.gitPrivate.exec(repo.rootUri.fsPath, args);
        try {
            const result = await resultPromise;
            return result.stdout;
        } catch (err) {
            console.error(`gitExec:err:${err}`);
            throw err;
        }
    }

}

interface AuthorInfo {
    email: string;
    author: string;
    timestamp?: Date;
}