import { mocks as performanceMocks, Performance } from '@vs/vscs-performance';
import { randomInt, randomString } from '@vs/vscs-utils';
import { ILogger, TraceSource } from '@vs/vso-logging';

// import { mocks } from '../../../src';

export const { PerformanceMock } = performanceMocks;

type TOptions = [ILogger, Performance, any];

/**
 * Mock helper to a random `IConnectionMockOptions`.
 */
export const getRandomConnectionMockOptions = () => {
    return {
        id: randomString(),
        someProp: randomString(),
        numericProp: randomInt(100),
    };
};

export const testTrace = new TraceSource('test-trace');
const performance = new PerformanceMock('test-performance', 'test-start');

interface IOptions {
    trace?: ILogger;
}

/**
 * Mock helper to generate default `ConnectionMock` options.
 * Pass real trace if you want to see logs in the console.
 */
export const getConnectionMockOptions = (options: IOptions = {}): TOptions => {
    const { trace = testTrace } = options;

    return [
        trace,
        performance,
        {
            ...getRandomConnectionMockOptions(),
        },
    ];
};
