'use strict';

import * as vscode from 'vscode';

import { vsls } from '@vs/vsls-contracts';
import {
    getNotebookCellData,
    ICoEditing,
    IPathManager,
    getCellId,
    Settings,
    SettingKeys,
    Lazy
} from '@vs/liveshare-core';
import { GuestCellChanges, HostCellChanges } from './notebooksService';
import { CellManager } from './cellManager';

export class HostCellManager extends CellManager {

    private initPromise: Promise<void>;
    private neighborOnDelete = new Map<string, string | undefined>();
    private changeQueue: Promise<HostCellChanges[]> = Promise.resolve([]);

    constructor (notebookDocument: vscode.NotebookDocument, private readonly pathManager: IPathManager, private readonly fileService: Lazy<vsls.FileService>, private readonly coediting: ICoEditing) {
        super(notebookDocument);
        this.init();
    }

    // Ensure all cells have an id and file client
    public async init() {
        if (!this.initPromise) {
            this.initPromise = new Promise(async (resolve, reject) => {
                if (Settings.get(SettingKeys.shareExternalFiles) &&
                    !vscode.workspace.getWorkspaceFolder(this.notebookDocument.uri)) {
                    await this.fileService().registerExternalFilesAsync([this.notebookDocument.uri.toString()]);
                }
                for (let cell of this.notebookDocument.getCells()) {
                    // TODO consider doing this in parallel (but be careful that all the VS Code edits are applied as one, otherwise some will fail)
                    await this.addIdToCell(cell);
                    const fileName = this.pathManager.localPathToRelativePath(cell.document.uri);
                    this.coediting.createSharedFileClient(fileName, cell.document.getText(), false, undefined, undefined, undefined, true);
                }
                resolve();
            });
        }
        return this.initPromise;
    }

    public async onDidChangeNotebookCells(changeEvent: vscode.NotebookCellsChangeEvent): Promise<HostCellChanges[]> {
        this.changeQueue = this.changeQueue.then(async () => {
            const changes = [];
            for (let change of changeEvent.changes) {
                const neighborIdx = change.start - 1;
                const neighborId = getCellId(this.notebookDocument.getCells().find(c => c.index === neighborIdx));
                const deletes = change.deletedItems.map(cell => {
                    const cellId = getCellId(cell);
                    this.neighborOnDelete.set(cellId, neighborId);
                    return cellId;
                });

                const addedCells = [];
                for (let cell of change.items) {
                    if (!this.isRemoteChange(cell)) {
                        await this.addIdToCell(cell);
                    }
                    const fileName = this.pathManager.localPathToRelativePath(cell.document.uri);
                    this.coediting.createSharedFileClient(fileName, cell.document.getText(), false);
                    addedCells.push(getNotebookCellData(cell));
                }

                const adds = addedCells.length > 0
                                ? {
                                    idx: change.start,
                                    cells: addedCells
                                }
                                : undefined;

                changes.push({
                    deletes,
                    adds
                });
            }
            return changes;
        });
        return this.changeQueue;
    }

    public async applyChanges(changes: GuestCellChanges[]) {
        for (let change of changes) {
            for (let id of change.deletes) {
                const deletedCell = this.notebookDocument.getCells().find(c => getCellId(c) === id);
                await this.deleteCell(deletedCell);
            }

            if (change.adds) {
                let insertAboveId = change.adds.insertAbove;
                while (insertAboveId && this.neighborOnDelete.has(insertAboveId)) {
                    insertAboveId = this.neighborOnDelete.get(insertAboveId);
                }
                const start = insertAboveId ? this.notebookDocument.getCells().find(c => getCellId(c) === insertAboveId).index + 1 : 0;
                await this.addCells(start, change.adds.cells);
            }
        }
    }

}
