import { ITelemetryFilter } from '@vs/vso-telemetry';
import { TraceSource } from '@vs/vso-logging';
import { LogFileTraceListener } from '../logFileTraceListener';

// This filter logs all sent telemetry events to a file.
export class LogFilter implements ITelemetryFilter {
    private readonly trace: TraceSource = new TraceSource('Telemetry');

    public async init() {
        const logFileTraceListener = new LogFileTraceListener('VSCodeTelemetry');
        await logFileTraceListener.openAsync();
        this.trace.addTraceListener(logFileTraceListener);
    }

    public shouldSend(
        eventName: string,
        properties: { [key: string]: string },
        measures: { [key: string]: number },
    ): boolean {
        const telemetryEvent = {
            eventName,
            properties,
            measures,
        };
        this.trace.info(JSON.stringify(telemetryEvent, null, 2));
        return true;
    }
}
