'use strict';

import {  IRpcClient } from '@vs/vso-rpc';
import * as lspClient from './lspClient';

import { 
    SessionContext,
    SessionState,
    ExtensionUtil,
    WorkspaceServices,
    sessionStateTracker
} from '@vs/liveshare-core';

export function lspClientActivator(workspaceServices: WorkspaceServices, rpcClient: IRpcClient, exclusive?: boolean) {

    let clientLspLanguageServicesActivated = false;

    SessionContext.onCollaboratorsJoined(async () => {
        if (!clientLspLanguageServicesActivated && 
            [SessionState.JoiningInProgress, SessionState.Joined].indexOf(sessionStateTracker.State) >= 0) {

            await lspClient.activateAsync(ExtensionUtil.context, rpcClient, [...workspaceServices.registeredServices], exclusive);
            clientLspLanguageServicesActivated = true;
        }
    });
}

