import * as vscode from 'vscode';

import { Mutex } from "@vs/vscs-utils";

/**
 * A mutex to serialize the invocation of a vscode command.
 */
const commandMutex = new Mutex();

/**
 * Execute a vscode command but serializing the execution if some other invocation has been made before
 * @param command The name of the command to execute
 * @param rest Arguments of the vscode command
 * @returns Result of the serialized vscode command.
 */
export async function executeNextCommand<T>(command: string, ...rest: any[]): Promise<T | undefined> {
    const result = await commandMutex.dispatch(async () => {
        const result = await vscode.commands.executeCommand<T>(command, ...rest);
        return result;
    });
    return result;  
}

