import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import * as config from '../presenceConfig';

import { 
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { ContactManager } from '../ContactManager';
import { ContactsProviderViewlet } from '../ContactsProviderViewlet';

export function builder(): ICommand<void> {
    return new ChangeSelfPresenceCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.CHANGE_SELF_PRESENCE, TelemetryEventNames.CHANGE_SELF_PRESENCE_FAULT, 'ChangeSelfPresence', 1)
class ChangeSelfPresenceCommand implements ICommand<void> {

    public async invoke(options: any, context: ICommandContext): Promise<void> {
        const presenceStatus = ContactManager.presenceStatus;
        const supportedPresenceStatus = ContactManager.supportedPresenceStatus.slice(0);

        const isSignedIn = ContactManager.signedStatus === contactProtocol.SignedStatus.SignedIn;

        if (isSignedIn && supportedPresenceStatus.findIndex(s => s === contactProtocol.PresenceStatus.Offline) === -1) {
            supportedPresenceStatus.push(contactProtocol.PresenceStatus.Offline);
        }

        const items = supportedPresenceStatus.map(s => (presenceStatus === s ? '$(check) ' : '') + ContactsProviderViewlet.toPresenceStatusName(s));
        const selection: string = await vscode.window.showQuickPick(items, { placeHolder: 'Specify your status:' });
        if (!selection) {
            return;
        }

        let newStatus = supportedPresenceStatus[items.indexOf(selection)];
        if (isSignedIn && newStatus === contactProtocol.PresenceStatus.Offline) {
            // disable liveshare presence
            await config.setLivesharePresenceEnabled(false);
            await ContactManager.signOut();
        } else {
            await ContactManager.publishPresence(<contactProtocol.PresenceStatus>newStatus);
        }
    }
}