import * as rpc from 'vscode-jsonrpc';
import { CancellationToken, Progress } from 'vscode';
import { ILogger } from '@vs/vso-logging';
import { CallbackContainer, IDisposable, DisposableClass } from '@vs/vscs-utils';
import { RpcRequestsWithContext, WrappedMessageReader, WrappedMessageWriter } from './RpcUtils';
import { RpcLoggerAdapter } from './RpcLoggerAdapter';
import {
    IRpcServiceHandlerBase,
    IRpcServiceHandler,
    HandleNoneRequestCallback,
    HandleNoneNotificationCallback,
} from './IRpcServiceHandler';
import { createMethodNotFoundResponse, getEventPropertyName } from './RpcUtils';
import { ServiceInfo } from './ServiceInfo';

interface StarNotificationEntry {
    cookie: number;
    notificationHandler: rpc.GenericNotificationHandler;
}

export interface IRpcMessageStream {
    reader: rpc.MessageReader;
    writer: rpc.MessageWriter;
}

export const methodProgress = '$/progress';

const RESTRICTED_HANDLERS_FIELD = '$RestrictedHandlers$';

/**
 * Base class to handle common tasks related with handling rpc request and notifications.
 */
export class RpcServiceHandlerBase extends DisposableClass implements IRpcServiceHandlerBase {
    private readonly rpcRequestsWithContext = new RpcRequestsWithContext();
    private rpcReadFilters: Array<(msg: rpc.Message) => rpc.Message> = [
        this.rpcRequestsWithContext.readFilter,
    ];
    private rpcWriteFilters: Array<(msg: rpc.Message) => rpc.Message> = [];
    private progressHandlers = new Map<number, { report: (value: any, id: number) => void }>();
    private readonly requests = new Map<string, rpc.GenericRequestHandler<any, any>>();
    private readonly requestsWithProgress = new Set<string>();
    private readonly notifications = new Map<string, StarNotificationEntry[]>();
    private notificationsCookies = 0;
    private handleNoneRequestCallbacks = new CallbackContainer<HandleNoneRequestCallback>();
    private handleNoneNotificationCallbacks = new CallbackContainer<
        HandleNoneNotificationCallback
    >();

    public constructor(logger: ILogger) {
        super(logger);
        this.addProgressFilters();
    }

    public get serviceNames(): string[] {
        const serviceNames = new Set<string>();
        const addServices = (keys: IterableIterator<string>) => {
            for (const key of keys) {
                serviceNames.add(key.split('.')[0]);
            }
        };
        addServices(this.requests.keys());
        addServices(this.notifications.keys());
        return Array.from(serviceNames);
    }

    public clear() {
        this.requests.clear();
        this.requestsWithProgress.clear();
        this.notifications.clear();
        this.handleNoneRequestCallbacks.clear();
        this.handleNoneNotificationCallbacks.clear();
    }

    public onHandleNoneRequest(callback: HandleNoneRequestCallback): IDisposable {
        return this.handleNoneRequestCallbacks.add(callback);
    }

    public onHandleNoneNotification(callback: HandleNoneNotificationCallback): IDisposable {
        return this.handleNoneNotificationCallbacks.add(callback);
    }

    public createRpcConnection(rpcMessageStream: IRpcMessageStream, logger: ILogger) {
        const rpcConnection = rpc.createMessageConnection(
            this.createFilteredMessageReader(rpcMessageStream.reader),
            this.createFilteredMessageWriter(rpcMessageStream.writer),
            new RpcLoggerAdapter(logger)
        );
        return rpcConnection;
    }

    public addReadFilter(filter: (msg: rpc.Message) => rpc.Message): rpc.Disposable {
        return addRpcFilter(this.rpcReadFilters, filter);
    }

    public addWriteFilter(filter: (msg: rpc.Message) => rpc.Message): rpc.Disposable {
        return addRpcFilter(this.rpcWriteFilters, filter);
    }

    public addRequestMethod(
        method: string,
        requestHandler: rpc.GenericRequestHandler<any, any>
    ): void {
        this.requests.set(method, requestHandler);
    }

    public addRequestMethodWithContext(
        method: string,
        requestHandler: rpc.GenericRequestHandler<any, any>
    ) {
        this.addRequestMethod(method, requestHandler);
        this.rpcRequestsWithContext.add(method);
    }

    public addRequestMethodWithProgress(
        method: string,
        requestHandler: rpc.GenericRequestHandler<any, any>
    ): void {
        this.addRequestMethod(method, requestHandler);
        this.requestsWithProgress.add(method);
    }

    public removeRequestMethod(method: string): void {
        this.requests.delete(method);
        this.requestsWithProgress.delete(method);
    }

    public addNotificationHandler(
        method: string,
        notificationHandler: rpc.GenericNotificationHandler
    ) {
        let entrys = this.notifications.get(method);
        if (!entrys) {
            entrys = [];
            this.notifications.set(method, entrys);
        }

        const entry: StarNotificationEntry = {
            cookie: ++this.notificationsCookies,
            notificationHandler,
        };
        entrys.push(entry);
        return entry.cookie;
    }

    public removeNotificationHandler(
        method: string,
        cookie: number
    ): rpc.GenericNotificationHandler | undefined {
        const entrys = this.notifications.get(method);
        if (entrys) {
            const indexEntry = entrys.findIndex((i) => i.cookie === cookie);
            if (indexEntry !== -1) {
                return entrys.splice(indexEntry, 1)[0].notificationHandler;
            }
        }

        return undefined;
    }

    public onRequest(
        requestHandlerInvoke:
            | ((requestHandler: rpc.GenericRequestHandler<any, any>, ...params: any[]) => any)
            | null,
        rpcConnection: rpc.MessageConnection,
        method: string,
        ...params: any[]
    ) {
        const requestHandler = this.requests.get(method);
        if (!requestHandler) {
            for (const callback of this.handleNoneRequestCallbacks.items) {
                const result = callback(rpcConnection, method, ...params);
                if (result !== undefined) {
                    return result;
                }
            }

            return Promise.resolve(createMethodNotFoundResponse(method));
        }

        // The request ID was inserted into the args by the read filter. (It's not used here.)
        const [requestId] = params.splice(0, 1);

        if (this.requestsWithProgress.has(method)) {
            const progress: Progress<any> = {
                report: (value: any) => {
                    rpcConnection.sendNotification(methodProgress, { id: requestId, value });
                },
            };
            // Insert progress into args just before the last (cancellation) arg.
            params.splice(params.length - 1, 0, progress);
        }

        if (requestHandlerInvoke) {
            return requestHandlerInvoke(requestHandler, ...params);
        }
        return requestHandler(...params);
    }

    public onNotification(rpcConnection: rpc.MessageConnection, method: string, ...params: any[]) {
        if (method === methodProgress && typeof params[0] === 'object') {
            // Note: the progress notification is being handled on the rpc read filter
            // and its better to no op.
            return;
        } else if (this.notifications.has(method)) {
            this.notifications.get(method)!.forEach((item) => {
                item.notificationHandler(...params);
            });
        } else {
            for (const callback of this.handleNoneNotificationCallbacks.items) {
                callback(rpcConnection, method, ...params);
            }
        }
    }

    public createFilteredMessageReader(reader: rpc.MessageReader): rpc.MessageReader {
        return new WrappedMessageReader(reader, (msg: rpc.Message) =>
            RpcServiceHandlerBase.filterMessage(msg, this.rpcReadFilters)
        );
    }

    public createFilteredMessageWriter(writer: rpc.MessageWriter): rpc.MessageWriter {
        return new WrappedMessageWriter(writer, (msg: rpc.Message) =>
            RpcServiceHandlerBase.filterMessage(msg, this.rpcWriteFilters)
        );
    }

    private static filterMessage(
        msg: rpc.Message,
        filters: Array<(msg: rpc.Message) => rpc.Message>
    ): rpc.Message {
        for (const filter of filters) {
            msg = filter(msg);
        }

        return msg;
    }

    private addProgressFilters(): void {
        this.rpcReadFilters.push((msg: rpc.Message) => {
            const msgObj = msg as any;
            const requestId = msgObj.id;
            if (typeof requestId !== 'undefined') {
                if (Array.isArray(msgObj.params)) {
                    // This is an incoming request message.
                    // Insert the request ID into the params in case it is needed for progress.
                    msgObj.params.splice(0, 0, requestId);
                } else if (
                    typeof msgObj.result !== 'undefined' ||
                    typeof msgObj.error !== 'undefined'
                ) {
                    // This is an incoming response message.
                    // Unregister any progress handler for the response's request ID.
                    this.progressHandlers.delete(requestId);
                }
            } else if (msgObj.method === methodProgress) {
                let progressArgs: { id: number; value: any } = msgObj.params;
                if (progressArgs.id === undefined) {
                    progressArgs = msgObj.params[0];
                }

                const progress = this.progressHandlers.get(progressArgs.id);
                if (progress) {
                    progress.report(progressArgs.value, progressArgs.id);
                }
            }
            return msg;
        });
        this.rpcWriteFilters.push((msg: rpc.Message) => {
            const msgObj = msg as any;
            const requestId = msgObj.id;
            const params = msgObj.params;
            if (
                typeof requestId !== 'undefined' &&
                params &&
                params.progress &&
                typeof params.progress.report === 'function'
            ) {
                // An outgoing message has a progress handler attached to the params.
                // Register the progress handler for the request ID.
                this.progressHandlers.set(msgObj.id, msgObj.params.progress);

                // Unregister the progress handler when the request is cancelled.
                const cancellation: CancellationToken = params.progress.cancellation;
                if (cancellation) {
                    cancellation.onCancellationRequested(() => {
                        this.progressHandlers.delete(requestId);
                    });
                }

                delete params.progress;
            }
            return msg;
        });
    }
}

export abstract class RpcServiceHandler extends RpcServiceHandlerBase
    implements IRpcServiceHandler {
    public abstract sendNotification(
        logger: ILogger,
        serviceAndName: string,
        args: object | any[]
    ): Promise<void>;

    /**
     * Registers an RPC service and returns a disposable registration object.
     * @param service Service instance. The class should implement the service interface.
     * @param serviceInfo Service metadata.
     * @param trace Trace source.
     * @param disposables Collection of disposable objects where the registration object will be added to.
     */
    public registerRpcService<TService>(
        service: TService,
        serviceInfo: ServiceInfo<TService>,
        contextMethods?: string[] | undefined,
        strict?: boolean
    ): rpc.Disposable {
        if (!service) {
            throw new Error('service argument is missing or undefined');
        }

        if (!serviceInfo) {
            throw new Error('serviceInfo argument is missing or undefined');
        }

        if (
            contextMethods &&
            contextMethods.filter((method) => serviceInfo.methods.indexOf(method) < 0).length > 0
        ) {
            throw new Error('invalid context method');
        }

        const serviceName = serviceInfo.name;
        if (!serviceName) {
            throw new Error('serviceInfo.serviceName is empty or undefined');
        }

        let isServiceActive = true;
        const addedRequestMethods = new Set<string>();
        const addedNotificationMethods = new Map<string, number>();
        let eventDisposables: rpc.Disposable[] = [];

        const result: rpc.Disposable = {
            dispose: () => {
                isServiceActive = false;
                for (const d of eventDisposables) {
                    d.dispose();
                }

                eventDisposables = [];

                for (const handlerName of addedRequestMethods) {
                    this.removeRequestMethod(handlerName);
                }

                addedRequestMethods.clear();

                for (const [handlerName, cookie] of addedNotificationMethods) {
                    this.removeNotificationHandler(handlerName, cookie);
                }
                addedNotificationMethods.clear();
            },
        };

        const restrictedHandlers: Map<string, Function> = (service as any)[
            RESTRICTED_HANDLERS_FIELD
        ];
        try {
            for (const method of serviceInfo.methods) {
                const handlerName = `${serviceName}.${method}`;
                const restrictedHandler = restrictedHandlers && restrictedHandlers.get(method);
                if (restrictedHandler) {
                    this.addRequestMethodWithContext(handlerName, (...args: any[]) =>
                        restrictedHandler.apply(service, args)
                    );
                    addedRequestMethods.add(handlerName);
                    continue;
                }

                const impl: Function =
                    (service as any)[method] || (service as any)[method + 'Async'];
                if (typeof impl !== 'function') {
                    if (strict || strict === undefined) {
                        throw new Error(
                            `Object ${serviceInfo.name} does not implement method '${method}' of service '${serviceName}'.`
                        );
                    } else {
                        continue;
                    }
                }

                if (contextMethods && contextMethods.indexOf(method) >= 0) {
                    this.addRequestMethodWithContext(handlerName, (...args: any[]) =>
                        impl.apply(service, args)
                    );
                } else {
                    this.addRequestMethod(handlerName, (...args: any[]) =>
                        impl.apply(service, args)
                    );
                }

                addedRequestMethods.add(handlerName);
            }

            if (serviceInfo.voidMethods) {
                for (const method of serviceInfo.voidMethods) {
                    const handlerName = `${serviceName}.${method}`;
                    if (restrictedHandlers && restrictedHandlers.get(method)) {
                        throw new Error(
                            `Restricted operation check is not supported yet for notification methods. Object ${serviceInfo.name} restricts notification '${method}' of service '${serviceName}'.`
                        );
                    }

                    const impl: Function = (this as any)[method] || (service as any)[method];
                    if (typeof impl !== 'function') {
                        if (strict) {
                            throw new Error(
                                `Object ${serviceInfo.name} does not implement notification '${method}' of service '${serviceName}'.`
                            );
                        } else {
                            continue;
                        }
                    }

                    const cookie = this.addNotificationHandler(handlerName, (...args: any[]) =>
                        impl.apply(service, args)
                    );
                    addedNotificationMethods.set(handlerName, cookie);
                }
            }

            if (serviceInfo.events) {
                for (const eventName of serviceInfo.events) {
                    if (!eventName) {
                        continue;
                    }

                    const propertyName = getEventPropertyName(eventName);
                    const event: rpc.Event<any> = (service as any)[propertyName];
                    if (typeof event === 'function') {
                        event((e) => {
                            if (isServiceActive) {
                                this.sendNotification(
                                    this.trace,
                                    `${serviceName}.${eventName}`,
                                    e
                                ).catch((err) =>
                                    this.trace.error(
                                        `Failed to send notification:${serviceName}.${eventName}`,
                                        err
                                    )
                                );
                            }
                        }, eventDisposables);
                    }
                }
            }
        } catch (err) {
            result.dispose();
            throw err;
        }

        return result;
    }
}

/**
 * helper function to add an rpc filter and be able to remove it.
 */
function addRpcFilter(
    filters: Array<(msg: rpc.Message) => rpc.Message>,
    filter: (msg: rpc.Message) => rpc.Message
): rpc.Disposable {
    filters.push(filter);
    return {
        dispose: () => {
            const index = filters.indexOf(filter);
            if (index !== -1) {
                filters.splice(index, 1);
            }
        },
    };
}
