'use strict';

import * as vscode from 'vscode';
import { ITelemetryFilter } from '@vs/vso-telemetry';
import { IDisposable } from '../abstractions/Mixins';

export class OptOutTelemetryFilter implements ITelemetryFilter, IDisposable {
    private enableTelemetry = true;
    private readonly configListener: vscode.Disposable;

    constructor() {
        this.updateUserOptIn();
        this.configListener = OptOutTelemetryFilter.vscode.workspace.onDidChangeConfiguration(() =>
            this.updateUserOptIn(),
        );
    }

    public shouldSend(
        eventName: string,
        properties: { [key: string]: string },
        measures: { [key: string]: number },
    ) {
        return this.enableTelemetry;
    }

    private updateUserOptIn(): void {
        const config = OptOutTelemetryFilter.vscode.workspace.getConfiguration('telemetry');
        this.enableTelemetry = config.get<boolean>('enableTelemetry', true);
    }

    public dispose() {
        return this.configListener.dispose();
    }

    // Defer import of `vscode` package.
    private static get vscode(): typeof vscode {
        return require('vscode');
    }
}
