import * as vscode from 'vscode';
import { Url } from 'url';
import { traceSource } from '@vs/vscode-command-framework';

import { TreeViewItem,
    TreeViewItemOptions,
    sessionStateTracker,
    workspaceSessionInfoTracker,
    SessionStateChangedEventArgs,
    SessionState ,
    ExtensionUtil as ExtensionUtilCore,
    CommandContext,
    TelemetryEventNames,
    TelemetryPropertyNames,
    localize,
    userAuthStateTracker} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
import { Telemetry, TelemetryEvent } from '@vs/vso-telemetry';
import { localizeDate } from '@vs/liveshare-core/dist/src/localize';

interface PlannedSessionExplorerItemOptions extends TreeViewItemOptions {
    workspaceInfos: vsls.WorkspaceInfo;
}

enum PlannedSessionItemType {
    plannedSession = 'plannedSession',
    other = 'other'
}

export class PlannedSessionTreeViewItem extends TreeViewItem {
    public readonly workspaceInfo: vsls.WorkspaceInfo;
    public readonly itemLink: string | Url;
    public type: PlannedSessionItemType;
    constructor(public readonly options: PlannedSessionExplorerItemOptions) {
        super(options);
        this.workspaceInfo = options.workspaceInfos;
    }
}

export class PlannedSessionsProvider implements vscode.TreeDataProvider<TreeViewItem> {
    private changeEventEmitter = new vscode.EventEmitter<TreeViewItem | undefined>();
    public readonly onDidChangeTreeData = this.changeEventEmitter.event;
    private plannedSessionsList: vsls.WorkspaceInfo[];

    constructor() {
        workspaceSessionInfoTracker.onPlannedSessionsChanged(this.onPlannedSessionChanged);
        sessionStateTracker.onStateChanged(this.onStateChanged);
        ExtensionUtilCore.setCommandContext(CommandContext.isPlannedSessionsReady, false);
    }

    private  onStateChanged = (e: SessionStateChangedEventArgs) => {
        if (e.newState === SessionState.SignedIn) {
           ExtensionUtilCore.setCommandContext(CommandContext.isPlannedSessionsReady, true);
           traceSource.info(`"Planned sessions are enabled, state: ` + SessionState[e.newState]);
           Telemetry.sendTelemetryEvent(TelemetryEventNames.SHOW_PLANNED_SESSIONS);
        } else {
           ExtensionUtilCore.setCommandContext(CommandContext.isPlannedSessionsReady, false);
           traceSource.info(`"Planned sessions are disabled, state: ` + SessionState[e.newState]);
        }

        this.refresh();
    }

    private onPlannedSessionChanged = (e: vsls.EventArgs) => {
        this.refresh();
    }

    public refresh = (): void => {
        this.changeEventEmitter.fire(undefined);
    }

    public getTreeItem = (element: TreeViewItem) => element;

    public async getChildren(element?: TreeViewItem): Promise<TreeViewItem[]> {
        return await this.getDefaultRootChildren();
    }

    private async getDefaultRootChildren() {
        let result: TreeViewItem[] = [];
        let state = sessionStateTracker.State;
        const localizedLabel = localize('plannedSessions.NewLabel');
        const localizedTooltip = localize('plannedSessions.CreateaPlannedSessionTooltip');
        if (state === SessionState.SignedOut
            || state === SessionState.Initializing
            || state === SessionState.Joined
            || state === SessionState.JoiningInProgress
            || state === SessionState.SharingInProgress
            || state === SessionState.Shared
            || userAuthStateTracker.isCurrentUserAnonymous()) {
            return result ;
        } else {
            traceSource.info(`"Planned sessions are ready, listing workspaces`);
            await vscode.commands.executeCommand('liveshare.listPlannedSessions');
            this.plannedSessionsList  = workspaceSessionInfoTracker?.plannedWorkspaceList;

            if (this.plannedSessionsList !== undefined && this.plannedSessionsList?.length !== 0) {
                for (let plannedSession of this.plannedSessionsList) {
                    result.push(await this.getPlannedSessionRow(plannedSession));
                }
            }

            if (result.length === 0) {
                result.push(new TreeViewItem({
                type: PlannedSessionItemType.other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: localizedLabel,
                tooltip: localizedTooltip,
                command: {
                    title: 'Create Planned Session',
                    command: 'liveshare.createPlannedSessionFromFileTreeExplorer',
                }}));
            } else {
                const plannedSessionsListIsNotEmptyEvent  = new TelemetryEvent(TelemetryEventNames.PLANNED_SESSIONS_LIST_IS_NOT_EMPTY);
                plannedSessionsListIsNotEmptyEvent.addProperty(TelemetryPropertyNames.PLANNED_SESSIONS_LIST_SIZE, result.length);
                plannedSessionsListIsNotEmptyEvent.send();
            }
        }

        return result;
    }

    private async getPlannedSessionRow(plannedSession: vsls.WorkspaceInfo) {
        const localizedExpiredTooltip = localize('plannedSessions.expiresatTooltip');
        const name = localize('Name: ');
        const date: Date = new Date(plannedSession.expiresAt);
        const localizedDate = localizeDate(date);
        const row = new PlannedSessionTreeViewItem ({
            label: `${plannedSession.label}`,
            workspaceInfos: plannedSession,
            type: PlannedSessionItemType.plannedSession,
            tooltip: name + `${plannedSession.label}` + '\r\n\n' + localizedExpiredTooltip + localizedDate
        });
        return row;
    }
}