import { assertDefined } from '../asserts/assertDefined';
import { assert } from '../asserts/assert';

import { IDisposableClass } from '../../interfaces/IDisposableClass';
import { TAsyncFunction } from '../../interfaces/TAsyncFunction';
import { TAnyFunction } from '../../interfaces/TAnyFunction';

type TAnyHelper = (...args: any[]) => TAnyFunction;

/**
 * Factory function to construct a helper with
 * specific execution context.
 */
 const contextMap = new Map<any, Map<Function, Function>>();

const getHelper = <T>(
    method: TAnyFunction,
    helper: TAnyFunction,
    options: T,
    context: any,
) => {
    /**
     * The overriden method should be associated with both
     * class instance and the class method, hence we are
     * using 2 maps here.
     */
    const existingHelpers = contextMap.get(context);
    if (existingHelpers) {
       const existingHelper = existingHelpers.get(method);

       if (existingHelper) {
           return existingHelper;
       }
    } else {
        contextMap.set(context, new Map());
    }

    const newHelper = helper(method.bind(context), options);
    const helpers = contextMap.get(context);

    assertDefined(
        helpers,
        'No helpers found.',
    );

    helpers.set(method, newHelper);

    return newHelper;
};

/**
 * Generic decorator to wrap a method with a helper.
 */
export function withHelperDecorator<
    TProp extends TAsyncFunction,
    TTarget extends IDisposableClass,
    THelper extends (...args: any[]) => TAnyHelper,
    THelperOptions extends Parameters<THelper>[1],
>(
    helper: THelper,
    options?: THelperOptions,
) {
    return function (
        target: TTarget,
        propertyName: string,
        propertyDesciptor: TypedPropertyDescriptor<TProp>,
    ): TypedPropertyDescriptor<TProp> {
        const { value: method } = propertyDesciptor;

        assert(
            method instanceof Function,
            'This decorator works only on methods',
        );

        assertDefined(
            method,
            `The method "${propertyName}" is not defined.`,
        );

        // must be `function` to not loose `this` context
        propertyDesciptor.value = async function (this: any, ...args: any[]) {
            const wrappedMethod = getHelper(method, helper, options, this);

            return await wrappedMethod.call(this, ...args);
        } as any;

        return propertyDesciptor;
    };
};
