import {
    Telemetry,
    ITimedEvent,
    TelemetryResult,
    TelemetryPropertyNames
} from '@vs/vso-telemetry';

import { CollaboratorChangedEventArgs } from '../SessionTypes';

export class CollaboratorsTelemetry {

    public static activeEvent: ITimedEvent;
    public static listenerAdded: boolean;

    public static endSession() {
        if (this.activeEvent) {
            this.activeEvent.end(TelemetryResult.Success);
        }
    }

    public static resetActiveEvent(hasCollaborators: boolean): void {
        this.activeEvent = Telemetry.startTimedEvent(SessionTelemetryEventNames.HAS_COLLABORATORS_CHANGED);
        this.activeEvent.addProperty(SessionTelemetryPropertyNames.HAS_COLLABORATORS, hasCollaborators);
    }

    public static sendChangeCollaboratorsEvent(eventArgs: CollaboratorChangedEventArgs): void {
        Telemetry.sendTelemetryEvent(
            SessionTelemetryEventNames.COLLABORATORS_CHANGED,
            {
                [SessionTelemetryPropertyNames.HAS_COLLABORATORS]: eventArgs.hasCollaborators.toString(),
                [SessionTelemetryPropertyNames.COLLABORATOR_SESSION_HASH]: eventArgs.collaboratorSessionHash.toString(),
                [SessionTelemetryPropertyNames.PREVIOUSLY_JOINED]: eventArgs.previouslyJoined.toString(),
                [SessionTelemetryPropertyNames.IS_HOST]: eventArgs.isHost.toString(),
                [SessionTelemetryPropertyNames.CHANGE_TYPE]: eventArgs.changeType.toString(),
                [SessionTelemetryPropertyNames.APPLICATION_NAME]: eventArgs.applicationName,
                [SessionTelemetryPropertyNames.DISCONNECTED_REASON]: eventArgs.disconnectedReason && eventArgs.disconnectedReason.toString() || ''
            });
    }
}

class SessionTelemetryEventNames {
    public static readonly HAS_COLLABORATORS_CHANGED = 'change-hascollaborators';
    public static readonly COLLABORATORS_CHANGED = 'change-collaborators';
}

class SessionTelemetryPropertyNames {
    public static readonly HAS_COLLABORATORS = TelemetryPropertyNames.FEATURE_NAME + 'HasCollaborators';
    public static readonly COLLABORATOR_SESSION_HASH = TelemetryPropertyNames.FEATURE_NAME + 'CollaboratorSessionHash';
    public static readonly PREVIOUSLY_JOINED = TelemetryPropertyNames.FEATURE_NAME + 'PreviouslyJoined';
    public static readonly IS_HOST = TelemetryPropertyNames.FEATURE_NAME + 'IsHost';
    public static readonly CHANGE_TYPE = TelemetryPropertyNames.FEATURE_NAME + 'ChangeType';
    public static readonly APPLICATION_NAME = TelemetryPropertyNames.FEATURE_NAME + 'ApplicationName';
    public static readonly DISCONNECTED_REASON = TelemetryPropertyNames.FEATURE_NAME + 'DisconnectedReason';
}