import { TAnyFunction } from '../interfaces/TAnyFunction';

interface IThrottleOptions {
    interval: number;
};

/**
 * Function that throttles a function invocation to
 * at most one per every `interval` milliseconds.
 */
export function throttle<T extends TAnyFunction>(
    fn: T,
    options: IThrottleOptions,
): (...args: Parameters<T>) => ReturnType<T> | undefined {
    let lockInterval: ReturnType<typeof setTimeout> | undefined;

    // wrap the original function
    return function throttledFunction(this: any, ...args: Parameters<T>): ReturnType<T> | undefined {
        /**
         * If still locked, return immediatelly.
         */
        if (lockInterval) {
            return;
        }

        /**
         * If not locked, invoke the original function and
         * lock so no invocation
         */
        const { interval } = options;
        lockInterval = setTimeout(() => {
            if (lockInterval) {
                clearInterval(lockInterval);
                lockInterval = undefined;
            }
        }, interval);

        /**
         * Run the original function and return the result.
         */
        return fn.call(this, ...args);
    };
};
