import { PromiseCompletionSource } from '@vs/vs-ssh';
import * as vscode from 'vscode';
import { TraceSource } from '@vs/vso-logging';
import {
    AuthenticationProviderInformation,
    AuthenticationSessionsChangeEvent,
} from 'vscode';
import { ExtensionUtil } from '../../utils/ExtensionUtil';
import { SupportedAuthProviders } from './NativeAuthProvider';
import { ITokenExchangeService } from './ITokenExchangeService';
import { TokenExchangeService } from './TokenExchangeService';
import { CommandId } from 'src/CommandConstants';
import { Settings } from '../../Settings';
import { SettingKeys } from '../../SettingKeys';
import { userAuthStateTracker } from '../../UserAuthStateTracker';
import * as jwtDecode from 'jwt-decode';
import { ICommandContext } from '@vs/vscode-command-framework';
import { cleanSensitiveInformation, TelemetryEvent } from '@vs/vso-telemetry';
import { TelemetryEventNames, TelemetryPropertyNames } from '../../telemetry/TelemetryStrings';

interface ICascadeTokenPayload {
    aud: string;
    exp: number;
    oid: string;
    idp: string;
    tid: string;
    name: string;
    email: string;
    preferredUsername: string;
    jti: string;
    iat: number;
    nbf: number;
}


export abstract class VsCodeNativeAuthTokenProvider {
    protected session: vscode.AuthenticationSession | undefined;

    private loginPromise: PromiseCompletionSource<boolean> | undefined;
    private signInIsInProgress: boolean;
    private readonly onSignOutEmitter = new vscode.EventEmitter<void>();
    private readonly hoursBufferCascade = 2; // that number comes from AuthenticationTokenValidator class in the agent

    protected cascadeToken: string;

    public readonly onSignOut = this.onSignOutEmitter.event;

    protected constructor(
        protected readonly providerId: SupportedAuthProviders,
        private readonly scopes: string[],
        private readonly logger: TraceSource,
        protected tokenExchangeService?: ITokenExchangeService
    ) {
        this.scopes = this.scopes.sort();
        this.tokenExchangeService = tokenExchangeService || new TokenExchangeService(logger);
        vscode.authentication.onDidChangeSessions(this.handleOnDidChangeSessions.bind(this));
    }

    private async handleOnDidChangeSessions(event: AuthenticationSessionsChangeEvent ) {
        if (!event) {
            return;
        }

        if (!event.provider) {
            return;
        }

        if (event.provider.id !== this.providerId) {
            return;
        }

        const sessionIsDefined = this.session !== undefined;
        const result = await this.tryLoadSession(false);

        if(sessionIsDefined && result === false) {
            // session has been removed
            await this.signOut();
        } if(!sessionIsDefined && result == true && !this.signInIsInProgress) {
            // session has been added
            await vscode.commands.executeCommand(userAuthStateTracker.isCurrentUserAnonymous() ?
                `${Settings.get<string>(SettingKeys.commandPrefix)}.signInAndReload` :
                CommandId.signIn
            );
        }
    }

    protected async tryLoadSession(login: boolean, context?: ICommandContext): Promise<boolean> {
        let error: Error;
        let telemetryResult: string;

        try {
            const currentProviderKey = Settings.get<string>(SettingKeys.authenticationProvider);
            const currentProvider = (<any>SupportedAuthProviders)[currentProviderKey];

            if (currentProvider && currentProvider !== this.providerId && !login) {
                return false;
            }

            this.logger.verbose(`Attempting to load session - login = ${login}`);

            const session = await vscode.authentication.getSession(this.providerId, this.scopes, {
                createIfNone: login,
            });

            if (session) {
                this.logger.verbose('Successfully loaded session');
                this.session = session;
                telemetryResult = 'Success';

                return true;
            } else {
                this.logger.warning('Failed to load session');
            }
        } catch (err) {
            this.logger.warning(`Failed to load session: ${err.message}`);

            error = err as Error;
            if ((error.message === 'User did not consent to login.' ||
                error.message === 'Unauthorized' ||
                err === 'Cancelled' ||
                err === 'access_denied') && login) {
                await this.cancelSignIn();

                telemetryResult = 'Cancel';

                if (context) {
                    const { cancellationTokenSource } = context;
                    cancellationTokenSource?.cancel();
                }
            } else {
                telemetryResult = 'Failure';
            }
        } finally {
            if (login) {
                const loadSessionEvent = new TelemetryEvent(TelemetryEventNames.TRY_LOAD_SESSION);
                loadSessionEvent.addProperty(TelemetryPropertyNames.EVENT_RESULT, telemetryResult);

                if (error && error.stack) {
                    loadSessionEvent.addProperty(TelemetryPropertyNames.VSCODE_ERROR_CALL_STACK, cleanSensitiveInformation(error.stack));
                }

                if (context && context.telemetryEvent) {
                    loadSessionEvent.correlateWith(context.telemetryEvent);
                }

                loadSessionEvent.send();
            }
        }

        return false;
    }

    public isSignedIn(): boolean {
        return this.session !== undefined;
    }

    public async signIn(context: ICommandContext): Promise<boolean> {
        this.signInIsInProgress = true;
        try {
            if (this.isSignedIn()) {
                this.logger.verbose(`Already signed in`);
                return true;
            }

            if (this.loginPromise) {
                return await this.loginPromise.promise;
            }

            this.loginPromise = new PromiseCompletionSource();

            try {
                await this.tryLoadSession(true, context);
            } catch (err) {
                this.logger.error(`Failed to sign in: ${err.message}`);
                this.loginPromise?.reject(err);
            }

            // Check for the token instead of `isSignedIn` as we may need to piggyback off keytar here
            const token = await this.getAccessToken();
            if (token) {
                if (this.session) {
                    this.logger.info(`Successfully signed in`);
                } else {
                    this.logger.info(`Successfully signed in from a cached credential`);
                }

                this.loginPromise?.resolve(true);
                return true;
            }

            this.logger.error(`Failed to sign in: no token available`);
            this.loginPromise?.resolve(false);
            return false;
        } finally {
            this.loginPromise = undefined;
            this.signInIsInProgress = false;
        }
    }

    public signOut(): Promise<void> {
        this.loginPromise?.reject(new Error('Logged Out'));
        this.loginPromise = undefined;

        this.resetCascadeToken();

        this.session = undefined;
        this.onSignOutEmitter.fire();
        this.logger.info(`Successfully signed out`);

        return Promise.resolve();
    }

    public resetCascadeToken(): void {
        this.cascadeToken = undefined;
    }

    private cancelSignIn(): Promise<void> {
        this.loginPromise?.reject(new Error('Sign in cancelled'));
        this.loginPromise = undefined;
        return Promise.resolve();
    }

    /*
     * Gets the credential from the native auth platform which is not a Cascade token.
     * Then exchanges a native token to a Cascade token.
     */
    public async getAccessToken(): Promise<string | undefined> {
        if (this.cascadeTokenIsValid ()) {
            return this.cascadeToken;
        }

        if (!this.isSignedIn()) {
            await this.tryLoadSession(false);
        }

        const nativeAccessToken = this.session?.accessToken;

        if (!nativeAccessToken) {
            return undefined;
        }

        this.cascadeToken = await this.tokenExchangeService.exchange(this.providerId, nativeAccessToken);
        return this.cascadeToken;
    }

    protected cascadeTokenIsValid(): boolean {
        if (!this.cascadeToken) {
            return false;
        }

        try {
            const jwtToken = jwtDecode<ICascadeTokenPayload>(this.cascadeToken);

            if (!jwtToken) {
                this.logger.info(`Can't decode Cascade token`);
                return false;
            }

            /*
             * Current date/time + two hours. This logic mimics token
             * validation checkin the Agent (AuthenticationTokenValidator class)
             */
            var expirationDate = new Date();
            expirationDate.setHours(expirationDate.getHours() + this.hoursBufferCascade);
            if (jwtToken.exp * 1000 < expirationDate.getTime())
            {
                this.logger.info(`Cascade token will expire in less than two hours`);
                return false;
            }

            return true;
        } catch(err) {
            this.logger.error(`Failed to validate cascade token: ${err.message}`);
            return false;
        }
    }
}