import {
    IRelayServiceProxy,
    IRelayHubProxy,
    IRelayHubParticipant,
    SendOption,
    HubMethodOption,
} from '@vs/vso-signalr-client-proxy';
import { HubStream } from '@vs/vso-signalr-ssh';
import { Stream } from '@vs/vs-ssh';
import { ILogger } from '@vs/vso-logging';
import * as constants from './constants';
import { Signal, timeoutPromise } from '@vs/vscs-utils';

export class HubStreamUtils {
    public static async createClientStream(
        relayServiceProxy: IRelayServiceProxy,
        hubId: string,
        streamId?: string,
        selectHostParticipantCallback?: (relayHubProxy: IRelayHubProxy) => IRelayHubParticipant,
        logger?: ILogger
    ): Promise<Stream> {
        selectHostParticipantCallback =
            selectHostParticipantCallback || HubStreamUtils.getHostParticipant;
        await relayServiceProxy.hubProxy.connect();
        const relayHubProxy = await relayServiceProxy.joinHub(hubId, null, {});
        const hostParticipant = selectHostParticipantCallback(relayHubProxy);

        logger?.verbose(
            `hub:${hubId} joined host:${hostParticipant.id} self:${
                relayHubProxy.selfParticipant.id
            } participants:${JSON.stringify(relayHubProxy.participants)} on service:${
                relayHubProxy.serviceId
            } stamp:${relayHubProxy.stamp}`
        );
        const stream = new HubStream(
            relayHubProxy,
            streamId || constants.DATA_TYPE_LIVESHARE_HUB,
            hostParticipant.id
        );

        const initTime = new Date().getTime();
        const ackReceived = new Signal<void>();

        const onReceiveAckDisposable = relayHubProxy.onReceiveData(async (e) => {
            if (
                e.type === constants.DATA_TYPE_JOINED_READY_ACK &&
                e.fromParticipant.id === hostParticipant.id
            ) {
                logger?.verbose(`Ack received after:${new Date().getTime() - initTime} ms`);
                ackReceived.resolve();
            }

            return;
        });

        // Note: ensure we await for the server response before returning the stream by using the 'Invoke' option.
        await relayHubProxy.sendData(
            SendOption.None,
            [hostParticipant.id],
            constants.DATA_TYPE_JOINED_READY,
            null,
            undefined,
            HubMethodOption.Invoke
        );

        if (
            hostParticipant.properties.hasOwnProperty(constants.PARTICIPANT_PROPERTY_HOST_FLAGS) &&
            hostParticipant.properties[constants.PARTICIPANT_PROPERTY_HOST_FLAGS] &
                constants.HostFlags.JoinReadAck
        ) {
            logger?.verbose(
                `Host join ready completed after:${new Date().getTime() - initTime} ms`
            );
            // await for the ack back from host participant
            await timeoutPromise(
                ackReceived.promise,
                30000,
                new Error('Host acknowledge not received to initiate the hub stream')
            );
        }

        onReceiveAckDisposable.dispose();
        return stream;
    }

    public static getHostParticipant(relayHubProxy: IRelayHubProxy): IRelayHubParticipant {
        return HubStreamUtils.getHostParticipantByProperty(
            relayHubProxy,
            constants.PARTICIPANT_PROPERTY_IS_HOST
        );
    }

    public static getHostParticipantByProperty(
        relayHubProxy: IRelayHubProxy,
        propertyName: string
    ): IRelayHubParticipant {
        const hostParticipants = relayHubProxy.participants.filter(
            (p) => p.properties && p.properties.hasOwnProperty(propertyName)
        );
        if (hostParticipants.length !== 1) {
            throw new Error(
                hostParticipants.length > 1
                    ? 'Multiple host participants'
                    : 'No host participant found'
            );
        }

        return hostParticipants[0];
    }
}
