import * as net from 'net';
import { vsls } from '@vs/vsls-contracts';
import * as getPort from 'get-port';
import { ILocalPortForwarder } from './contracts/ILocalPortForwarder';
import { ILogger } from '@vs/vso-logging';
import { ConnectedState, IWorkspaceConnection } from '@vs/vso-workspace-core';
import { IChannel } from '@vs/vso-rpc';
import { assert, createDisposable, DisposableClass, errorToObject, Signal } from '@vs/vscs-utils';

const MessageWorkspaceClientClosed = 'Workspace client was closed.';
const DEFAULT_SERVER_ADDRESS = '127.0.0.1';

enum ErrorCodes {
    AlreadyInUse = 'EADDRINUSE',
    NoAccess = 'EACCES',
};

/**
 * Accepts incoming TCP connections on a local port and forwards them to a
 * shared server on the remote host.
 */
export class LocalPortForwarder extends DisposableClass implements ILocalPortForwarder {
    private readonly server: net.Server;

    private readonly connections: net.Socket[] = [];
    private readonly channels: IChannel[] = [];
    private readonly forecastChannels: Promise<IChannel>[] = [];

    private readonly stoppingSignal = new Signal<void>();
    private isClosed = false;

    public get localPort(): number {
        return this.localPortRef;
    }

    public constructor(
        trace: ILogger,
        public readonly sharedServer: vsls.SharedServer,
        private readonly workspaceConnection: IWorkspaceConnection,
        private readonly streamManagerClient: vsls.StreamManagerService,
        private localPortRef: number,
        private readonly rebindToRandomPortOnErrors: ReadonlyArray<ErrorCodes> = [
            ErrorCodes.AlreadyInUse,
            ErrorCodes.NoAccess,
        ],
    ) {
        super(
            trace.createChild(`local-port-forwarder[${sharedServer.sourcePort}]`),
        );

        this.trace.info('rebindToRandomPortOnErrors: ', JSON.stringify(rebindToRandomPortOnErrors));

        this.server = new net.Server(this.onConnection.bind(this));

        this.addToDisposables(
            workspaceConnection.onHostConnectionChanged(e => {
                if (e.state === ConnectedState.Closed) {
                    this.trace.info(MessageWorkspaceClientClosed);
                    this.isClosed = true;

                    this.dispose('workspace connection closed');
                }
            }),
            this.onDispose(() => {
                this.stop()
                    .catch((err) => {
                        this.trace.error('Failed to stop local server.', err);
                    });
            }),
        );
    }

    /**
     * Start listening for incoming connections.
     */
    public async start(channelForecast: number = 0): Promise<void> {
        try {
            this.trace.info(`start with "${channelForecast}" channels`);

            this.trace.info(
                `start: sourcePort=${this.sharedServer.sourcePort} localPort=${this.localPortRef} host=${this.sharedServer.sessionName}`,
            );
            await this.listen();

            this.trace.info('server started');
        } catch (error) {
            this.trace.info('error while starting: ', JSON.stringify(errorToObject(error)));

            /**
             * If error code is not on the list - rethrow the error,
             * if error code is in the list, bind to a random port.
             */
            assert(
                this.rebindToRandomPortOnErrors.includes(error.code),
                error,
            );

            this.trace.info('rebinding to a random port');

            // Try again, this time with a RANDOM port number.
            this.localPortRef = await getPort.default();
            await this.listen();
            this.trace.info(
                `start (failed): sourcePort=${this.sharedServer.sourcePort} localPort=${this.localPortRef} host=${this.sharedServer.sessionName}`,
            );
        }

        // Start opening the forecasted number of channels, so they will
        // will be available more quickly when requested.
        for (let i = 0; i < channelForecast; i++) {
            this.forecastChannels.push(this.openChannel());
        }
    }

    public stop() {
        this.trace.info('stopping');

        if (!this.server.listening) {
            return Promise.resolve();
        }

        for (const channel of this.channels) {
            channel.close()?.catch((err) => this.trace.error(`failed to close channel`, err));
        }

        this.trace.verbose(
            `stop: stopping local server port=${this.localPortRef} connections=${this.connections.length}`,
        );

        this.server.close((err) => {
            if (err) {
                this.trace.error(`stop: failed to stop local server port=${this.localPortRef}`, err);

                this.stoppingSignal.reject(err);
                return;
            }

            this.trace.verbose(`stop: stopped local server port=${this.localPortRef}`, err);
            this.stoppingSignal.resolve();
        });

        for (const conn of this.connections) {
            conn.destroy();
        }

        return this.stoppingSignal.promise;
    }

    private async listen(): Promise<void> {
        return await new Promise((resolve, reject) => {
            // Listen on the IPv4 loopback interface, because connections are only expected
            // from local clients.
            this.server.once('listening', () => {
                this.trace.info(`listening on local port=${this.localPortRef}`);
                resolve();
            });
            this.server.once('error', (e) => {
                this.trace.error(`failed to listen on local port=${this.localPortRef}`, e);
                reject(e);
            });

            this.trace.info(`start listen to port: "${DEFAULT_SERVER_ADDRESS}:${this.localPortRef}"`);
            this.server.listen(this.localPortRef, DEFAULT_SERVER_ADDRESS);
        });
    }

    /**
     * Accept incoming connections from VS Code and forward them to the shared server.
     */
    private async onConnection(socket: net.Socket): Promise<void> {
        this.connections.push(socket);
        try {
            // Wait for a forecasted channel if available, otherwise wait for a new channel.
            const channel = await (this.forecastChannels.shift() ?? this.openChannel());

            this.addToDisposables(
                createDisposable(() => {
                    channel.close();
                    socket.end();
                }),
                channel,
            );

            this.channels.push(channel);

            // Normally these are SSH channels, which have a `channelId` property, but it's not required.
            const channelId = (<any>channel).channelId ?? '?';
            this.trace.info(`Forwarding connection on channel #${channelId}.`);

            // Forward data between the socket and the SSH channel.
            socket.on('data', (data) => {
                // console.log(ssh.formatBuffer(data, ` sending`));

                // Block further data events while sending.
                socket.pause();

                channel.send(data).then(
                    () => {
                        socket.resume();
                    },
                    (e) => {
                        this.trace.error('Error sending channel data: ' + e.message, e);
                    },
                );
            });
            channel.onDataReceived((data) => {
                // Make a copy of the data before passing it to the async socket.write()
                // because the current buffer may get re-used after this callback returns.
                data = Buffer.from(data);

                // console.log(ssh.formatBuffer(data, ` receiving`));
                socket.write(data, () => {
                    // Notify the channel that the data has been consumed and more data may be sent.
                    channel.adjustWindow(data.length);
                });
            });

            // Propagate close events both directions.
            socket.on('close', () => {
                const i = this.connections.indexOf(socket);
                if (i >= 0) {
                    this.connections.splice(i, 1);
                }

                channel
                    .close()
                    ?.catch((e) => this.trace.error('Channel close failed with error', e));
            });
            socket.on('error', (e) => {
                const i = this.connections.indexOf(socket);
                if (i >= 0) {
                    this.connections.splice(i, 1);
                }

                channel
                    .close(e)
                    ?.catch((err) => this.trace.error('Channel close failed with error', err));
            });
            channel.onClosed((e) => {
                if (e.error || e.errorMessage) {
                    const errorMsg = `Port-forward channel #${channelId} closed with error: ${
                        e.error && e.error.message ? e.error.message : e.errorMessage
                    }`;
                    this.trace.error(errorMsg);
                } else {
                    this.trace.info(`Port-forward channel #${channelId} closed.`)
                }
                socket.end();
            });
        } catch (e) {
            this.trace.error(
                'Failed to forward incoming connection to remote server: ' + e.message,
                e,
            );
            socket.end();
        }
    }

    /**
     * Open a new SSH channel that is remotely connected to the shared server.
     */
    private async openChannel(): Promise<IChannel> {
        assert(!this.isClosed, MessageWorkspaceClientClosed);

        const streamId = await this.streamManagerClient.getStreamAsync(
            this.sharedServer.streamName,
            this.sharedServer.streamCondition,
        );

        return await this.workspaceConnection.openStreamingChannel(streamId);
    }
}
