import { env as vscodeEnv } from 'vscode';
import { clipboard } from '@core-abstractions/clipboard';


// The VS Code clipboard API supports headless, but is
// not available in all verisons. Determine if it can be used.
/* tslint:disable-next-line:no-string-literal */
const vscodeClipboard = (<any>vscodeEnv)['clipboard'];
const vscodeClipboardExists = (typeof vscodeClipboard !== 'undefined');

export interface IClipboardUtil {
    pasteFromClipboardAsync(): Promise<string>;
    copyToClipboardAsync(value: string): Promise<boolean>;
}

/**
 * Helper functions for working with the clipboard.
 */
export class ClipboardUtil implements IClipboardUtil {
    public async pasteFromClipboardAsync(): Promise<string> {
        try {
            if (vscodeClipboardExists) {
                return await vscodeClipboard.readText();
            } else {
                return await clipboard.readAsync();
            }
        } catch (e) {
            // Clipboardy can fail in certain environments, such as Linux/WSL
            // when dependencies are missing, or Windows with anti-malware restrictions.
            return '';
        }
    }

    public async copyToClipboardAsync(value: string): Promise<boolean> {
        try {
            if (vscodeClipboardExists) {
                await vscodeClipboard.writeText(value);
            } else {
                await clipboard.writeAsync(value);
            }
            return true;
        } catch (e) {
            // Clipboardy can fail in certain environments, such as Linux/WSL
            // when dependencies are missing, or Windows with anti-malware restrictions. 
            return false;
        }
    }
}