'use strict';

import * as vscode from 'vscode';

import Semaphore from 'semaphore-async-await';
import { PortForwardingTelemetry } from './portForwardingTelemetry';
import { traceSource as trace, Activatable, Disposable } from '@vs/vscode-command-framework';
import { TraceSource } from '@vs/vso-logging';

import { NotificationUtil } from '@vs/vscode-command-framework';
import { IGuestServerController } from './IGuestServerController';
import {
    IDependencies,
    ISessionContext,
    TelemetryEventNames,
    TelemetryEventOrigin,
    commandBindingDecorator,
    ControllerHelper,
    ExtensionUtil,
    Settings,
    SettingKeys,
    ClipboardUtil,
    localize,
    Lazy
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

import { portForwardingService } from './abstractions/portForwardingService';

interface SharedServerActionPayload {
    [key: string]: any;
    port: number;
}

enum BrowseBehavior {
    Ignore,
    Open,
}

export const guestServerControllerFactory = (deps: IDependencies): IGuestServerController => {

    const {
        controllerDecorator,
        errorNotificationMethodDecorator,
        telemetryMethodDecorator
    } = deps.methodDecorators();

    /**
     * Registers and handles VSCode commands controlling shared local server behavior in a joined collaboration session.
     */
    @controllerDecorator
    class GuestServerController extends Activatable(Disposable(Object)) implements IGuestServerController {
        private readonly sessionSubscriptions: vscode.Disposable[] = [];
        private readonly sessionContext: ISessionContext;
        private readonly lazyPortForwardingService: Lazy<vsls.PortForwardingService>;
        private readonly trace: TraceSource;
        private readonly browseSourcePorts = new Set<number>();
        private readonly browsePromptSemaphore = new Semaphore(1);
        private browseBehavior?: BrowseBehavior;

        public get canBrowse() {
            return Settings.get<boolean>(SettingKeys.openSharedServers) &&
                this.browseBehavior !== BrowseBehavior.Ignore &&
                this.isActivated;
        }

        constructor(dependencies: IDependencies) {
            super();
            this.sessionContext = dependencies.sessionContext();
            this.lazyPortForwardingService = dependencies.portForwardingService;
            this.trace = dependencies.trace().withName('GuestServerController');
        }

        private get portForwardingService() {
            return this.lazyPortForwardingService();
        }

        public async dispose(): Promise<void> {
            await this.deactivate();
            await super.dispose();
        }

        public async activate(): Promise<boolean> {
            if (this.isActivated) {
                return true;
            }

            this.isActivated = true;
            this.sessionSubscriptions.push(
                this.portForwardingService.onSharingStarted(this.sharingStarted),
                this.portForwardingService.onSharingStopped(this.sharingStopped),
                this.portForwardingService.onBrowseSharingStarted(this.browseSharingStarted),
            );

            ControllerHelper.register(this, this.sessionSubscriptions);

            this.checkForSharedServers(true);

            return await super.activate();
        }

        public deactivate(): Promise<void> {
            const removed = this.sessionSubscriptions.splice(0);
            removed.forEach(d => d.dispose());
            return super.deactivate();
        }

        private sharingStarted = () => this.checkForSharedServers();

        private sharingStopped = ({ server: { sourcePort } }: vsls.ServerSharingStoppedEventArgs) => {
            this.browseSourcePorts.delete(sourcePort);
            this.checkForSharedServers();
        }

        private checkForSharedServers = async (startBrowse?: boolean): Promise<void> => {
            try {
                console.log('checking for servers' + this.portForwardingService);
                const sharedServers: vsls.SharedServer[] = await this.portForwardingService.getSharedServersAsync();
                console.log('found servers ' + sharedServers.length);
                this.sessionContext.hasServersShared = sharedServers.length > 0 && this.isActivated;
                if (startBrowse && this.canBrowse) {
                    sharedServers.forEach(this.startBrowser);
                }
            } catch (e) {
                trace.error('Checking for shared servers failed: ' + e);
            }
        }

        private browseSharingStarted = (e: vsls.ServerSharingStartedEventArgs) => this.startBrowser(e && e.server);

        private async getBrowseUrl(sharedServer: vsls.SharedServer): Promise<string> {
            let localUri = sharedServer.browseUrl || `http://localhost:${sharedServer.destinationPort}`;

            const isFunction = (thing: unknown): thing is Function => {
                return (typeof thing === 'function');
            };

            // In the browser this will get mapped to a url to the portforwarding service instead of localhost by calling asExternalUri.
            if (isFunction(vscode.env.asExternalUri)) {
                localUri = (await vscode.env.asExternalUri(vscode.Uri.parse(localUri))).toString();
            }

            return localUri;
        }

        private startBrowser = async ({ browseUrl, sourcePort, sessionName }: vsls.SharedServer) => {
            if (!browseUrl || !this.canBrowse || this.browseSourcePorts.has(sourcePort)) {
                return;
            }

            this.browseSourcePorts.add(sourcePort);

            await this.browsePromptSemaphore.acquire();
            try {
                // The server may have been unshared, or session has ended while we waited
                if (!this.browseSourcePorts.has(sourcePort) || !this.canBrowse) {
                    return;
                }

                if (this.browseBehavior === BrowseBehavior.Open) {
                    ExtensionUtil.openBrowser(browseUrl);
                    return;
                }

                const message = localize('guestServerController-promtHostSharedServer').replace('$(sessionName)', sessionName);
                const yes = localize('guestServerController-yes');
                const no = localize('guestServerController-no');

                const response = await NotificationUtil.showInformationMessage(message, false, yes, no);
                switch (response) {
                    case no:
                        this.browseBehavior = BrowseBehavior.Ignore;
                        break;

                    case yes:
                        this.browseBehavior = BrowseBehavior.Open;
                        if (!this.browseSourcePorts.has(sourcePort)) {
                            const serverUnsharedMessage = localize('guestServerController-serverUnshared').replace('$(sessionName)', sessionName);
                            await NotificationUtil.showWarningMessage(serverUnsharedMessage);
                        } else if (this.isActivated) {
                            ExtensionUtil.openBrowser(browseUrl);
                        }

                        break;

                    default:
                }
            } catch (err) {
                this.trace.error(`Error starting browser for ${sessionName}: ${err.message}`);
            } finally {
                this.browsePromptSemaphore.release();
            }
        }

        @errorNotificationMethodDecorator('Opening Server in Browser', TelemetryEventNames.BROWSE_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.BROWSE_SERVER, TelemetryEventNames.BROWSE_SERVER_FAULT, 'OpenServerInBrowser')
        @commandBindingDecorator('liveshare.fileTreeExplorer.openServerInBrowser')
        @commandBindingDecorator('liveshare.activityBar.openServerInBrowser')
        private async openServerInBrowser(item: SharedServerActionPayload): Promise<void> {
            if (!item || (item.port == null)) {
                return;
            }

            const sharedServers = await this.portForwardingService.getSharedServersAsync();
            const sharedServer = sharedServers.find(x => x.destinationPort === item.port);
            if (sharedServer) {
                const browseUrl = await this.getBrowseUrl(sharedServer);
                ExtensionUtil.openBrowser(browseUrl);
            }
        }

        @errorNotificationMethodDecorator('Copying Server URL', TelemetryEventNames.COPY_URL_SERVER_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.COPY_URL_SERVER, TelemetryEventNames.COPY_URL_SERVER_FAULT, 'CopyServerURL')
        @commandBindingDecorator('liveshare.fileTreeExplorer.copyServerURL')
        @commandBindingDecorator('liveshare.activityBar.copyServerURL')
        private async copyServerURL(item: SharedServerActionPayload): Promise<void> {
            if (!item || (item.port == null)) {
                return;
            }

            const sharedServers = await this.portForwardingService.getSharedServersAsync();
            const sharedServer = sharedServers.find(x => x.destinationPort === item.port);
            if (sharedServer) {
                const text = await this.getBrowseUrl(sharedServer);
                if (await new ClipboardUtil().copyToClipboardAsync(text)) {
                    await NotificationUtil.showInformationMessage('The server URL was copied to the clipboard.', false);
                } else {
                    await NotificationUtil.showInputBox({ value: text });
                }
            }
        }

        @errorNotificationMethodDecorator('Listing Servers', TelemetryEventNames.LIST_SERVERS_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.LIST_SERVERS, TelemetryEventNames.LIST_SERVERS_FAULT, 'ListServers')
        @commandBindingDecorator('liveshare.listServers')
        private async listForwardedPorts(origin?: TelemetryEventOrigin): Promise<void> {
            PortForwardingTelemetry.listSharedLocalServers(origin);

            const sharedServers = await this.portForwardingService.getSharedServersAsync();

            if (sharedServers.length === 0) {
                await NotificationUtil.showInformationMessage('No ports are currently shared.', false, { modal: false });
                return;
            }

            let index = -1;

            if (sharedServers.length === 1) {
                index = 0;
            } else {
                const items: string[] = sharedServers.map((s) => s.sessionName === `localhost:${s.destinationPort}` ? s.sessionName : `${s.sessionName} mapped to localhost:${s.destinationPort}`);
                const selection: string = await NotificationUtil.showQuickPick(items, { placeHolder: 'Select the port to copy to the clipboard.' });
                if (!selection) {
                    return;
                }

                index = items.indexOf(selection);
            }

            if (index >= 0) {
                const sharedServer: vsls.SharedServer = sharedServers[index];
                const text = await this.getBrowseUrl(sharedServer);
                const clipboard = new ClipboardUtil();
                if (await clipboard.copyToClipboardAsync(text)) {
                    const result = await NotificationUtil.showInformationMessage(
                        'The server URL was copied to the clipboard.', false, {}, { title: 'Copy again' });
                    if (result) {
                        await clipboard.copyToClipboardAsync(text);
                    }
                } else {
                    await NotificationUtil.showInputBox({ value: text });
                }
            }
        }
    }

    return new GuestServerController(deps);
};
