import { SaveSnapshot } from '../client/vscodeBufferManager';

export class SyncManager {

    private snapshots = new Map<number, number>();
    private snapshotsQueue: number[] = [];
    private pendingSyncChecks = new Map<number, { hashCode: number, resolve: (isSynced: boolean) => void, result: Promise<boolean> }>();

    public recordSnapshot(snapshot: SaveSnapshot) {
        if (this.pendingSyncChecks.has(snapshot.serverVersionNumber)) {
            const pendingCheck = this.pendingSyncChecks.get(snapshot.serverVersionNumber);
            pendingCheck.resolve(snapshot.hasUnacknowledgedChanges ? true : snapshot.hashCode === pendingCheck.hashCode);
            this.pendingSyncChecks.delete(snapshot.serverVersionNumber);
        }

        this.snapshots.set(snapshot.serverVersionNumber, snapshot.hasUnacknowledgedChanges ? undefined : snapshot.hashCode);
        this.snapshotsQueue.push(snapshot.serverVersionNumber);
        this.trimBlessedStates();
    }

    private trimBlessedStates() {
        const trimCount = 10000;
        if (this.snapshotsQueue.length < (2*trimCount)) {
            return;
        }
        
        for (let i = 0; i < trimCount; i++) {
            this.snapshots.delete(this.snapshotsQueue[i]);
        }
        this.snapshotsQueue.splice(0, trimCount);
    }

    public isFileSyncedForVersion(serverVersionNumber: number, fileHash: number): Promise<boolean> {
        if (this.snapshots.has(serverVersionNumber)) {
            const hostHash = this.snapshots.get(serverVersionNumber);
            return Promise.resolve(hostHash === undefined ? true : hostHash === fileHash);
        }

        if (this.pendingSyncChecks.has(serverVersionNumber)) {
            return this.pendingSyncChecks.get(serverVersionNumber).result;
        }

        let syncPromiseResolve: (isSynced: boolean) => void;
        const syncPromise = new Promise<boolean>((resolve, reject) => {
            syncPromiseResolve = resolve;
        });
        this.pendingSyncChecks.set(serverVersionNumber, { hashCode: fileHash, resolve: syncPromiseResolve, result: syncPromise });
        return syncPromise;
    }

}
