import { DisposableClass } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import { Disposable } from 'vscode-jsonrpc';

import { IHubConnectionOptions } from '../interfaces/IHubConnectionOptions';
import { IConnection } from '../interfaces/IConnection';

/**
 * Record of a connection inside a ConnectionHub.
 */
export class ConnectionHubRecord<T extends IConnection<any>, K> extends DisposableClass {
    constructor(
        trace: ILogger,
        private connectionArg: T,
        private connectionOptionsArg: K,
        private hubConnectionOptionsArg: IHubConnectionOptions,
        private eventHandlerArg: Disposable
    ) {
        super(trace);

        this.addToDisposables(eventHandlerArg, connectionArg);
    }

    public get connection() {
        return this.connectionArg;
    }

    public get connectionOptions() {
        return this.connectionOptionsArg;
    }

    public get hubConnectionOptions() {
        return this.hubConnectionOptionsArg;
    }

    public get eventHandler() {
        return this.eventHandlerArg;
    }

    public async disconnect(reason?: string) {
        await this.connection.disconnect(reason);

        return super.dispose(reason);
    }
}
