import * as vscode from 'vscode';

import { IMap } from '../IMap';
import { IPathManager } from '../IPathManager';
import { PathManager } from '../PathManager';
import { EventEmitter } from 'events';

export interface DiffViewInformation {
    leftFile: vscode.Uri;
    rightFile: vscode.Uri;
}

export class DiffView extends EventEmitter implements vscode.Disposable {

    private readonly onDiffViewOpenEventName = 'onDiffViewOpen';
    private readonly onDiffViewClosedEventName = 'onDiffViewClosed';
    private readonly onNewGitDocumentEventName = 'onNewGitDocument';

    private currentVisibleDiffViews: IMap<DiffViewInformation[]> = {};
    private readonly pathManager: IPathManager;

    public constructor(pathManager: IPathManager) {
        super();
        this.pathManager = pathManager;
    }

    public saveDiffViewInformation(clientId: number, leftFileUri: vscode.Uri, rightFileUri: vscode.Uri): void {
        if (leftFileUri && rightFileUri) {
            let diffViewInfo: DiffViewInformation = {
                leftFile: leftFileUri,
                rightFile: rightFileUri
            };

            let clientInfoArray = this.currentVisibleDiffViews[clientId];
            if (!clientInfoArray) {
                clientInfoArray = [];
                this.currentVisibleDiffViews[clientId] = clientInfoArray;
            }

            clientInfoArray.push(diffViewInfo);
        }
    }

    public findDiffViewInformation(clientId: number, uriToFind: vscode.Uri): DiffViewInformation {
        let clientInfoArray = this.currentVisibleDiffViews[clientId];

        if (clientInfoArray) {
            return clientInfoArray.find(diffInfo =>
                uriToFind.toString() === diffInfo.leftFile.toString() ||
                uriToFind.toString() === diffInfo.rightFile.toString());
        }

        return null;
    }

    public removeDiffViewInformation(clientId: number, leftFileUri: vscode.Uri, rightFileUri: vscode.Uri): void {
        let clientInfoArray = this.currentVisibleDiffViews[clientId];

        if (clientInfoArray) {
            clientInfoArray = clientInfoArray.filter(diffInfo =>
                leftFileUri.toString() !== diffInfo.leftFile.toString() ||
                rightFileUri.toString() !== diffInfo.rightFile.toString());
            this.currentVisibleDiffViews[clientId] = clientInfoArray;
        }
    }

    private notifyDiffViewsClosed(clientId: number, visibleEditors: vscode.TextEditor[]) {
        let diffViewsForClient = this.currentVisibleDiffViews[clientId];
        if (diffViewsForClient) {
            diffViewsForClient = diffViewsForClient.filter(diffView => {
                // check if the editors for the diff view are still visible
                let correspondingEditors = visibleEditors.filter(
                    editor =>
                        editor.viewColumn === undefined &&
                        (diffView.leftFile.toString() === editor.document?.uri?.toString() ||
                            diffView.rightFile.toString() === editor.document?.uri?.toString())
                );
                // if both of them are not visible, the diff view is hidden or closed
                if (correspondingEditors.length >= 2) {
                    return true; // diff view still open
                } else {
                    // notify others that the diff view has been closed
                    let leftFileRelativePath = this.pathManager.localPathToRelativePath(diffView.leftFile);
                    let rightFileRelativePath = this.pathManager.localPathToRelativePath(diffView.rightFile);
                    this.emit(this.onDiffViewClosedEventName, leftFileRelativePath, rightFileRelativePath);
                    return false;
                }
            });

            this.currentVisibleDiffViews[clientId] = diffViewsForClient;
        }
    }

    private onHostEditorsChanged(visibleEditors: vscode.TextEditor[], clientId: number) {
        let fileAndSourceControlEditors = visibleEditors
            .filter(editor => editor.viewColumn === undefined
                && [PathManager.fileScheme, PathManager.gitScheme].includes(editor?.document?.uri?.scheme));

        // host can have (file <--> git) and (git <--> git) diffs
        if (fileAndSourceControlEditors.length >= 2) {
            for (var i = 0; i < fileAndSourceControlEditors.length; i++) {
                for (var j = i + 1; j < fileAndSourceControlEditors.length; j++) {
                    var leftEditor = fileAndSourceControlEditors[i];
                    var rightEditor = fileAndSourceControlEditors[j];
                    if (leftEditor.document.uri.fsPath === rightEditor.document.uri.fsPath) {
                        let leftFileRelativePath = this.pathManager.localPathToRelativePath(leftEditor.document.uri);
                        let rightFileRelativePath = this.pathManager.localPathToRelativePath(rightEditor.document.uri);
                        if (leftFileRelativePath && rightFileRelativePath) {
                            this.saveDiffViewInformation(clientId, leftEditor.document.uri, rightEditor.document.uri);
                            this.emit(this.onDiffViewOpenEventName, leftFileRelativePath, rightFileRelativePath);
                        }
                    }
                }
            }
        }
    }

    private onGuestEditorsChanged(visibleEditors: vscode.TextEditor[], clientId: number) {
        let fileAndSourceControlEditors = visibleEditors
            .filter(editor => editor.viewColumn === undefined
                && [PathManager.vslsSccScheme, PathManager.rawScheme].includes(editor?.document?.uri?.scheme));

        // guest can have (vsls <--> vsls-scc) and (vsls-scc <--> vsls-scc) diffs
        if (fileAndSourceControlEditors.length >= 2) {
            for (var i = 0; i < fileAndSourceControlEditors.length; i++) {
                for (var j = i + 1; j < fileAndSourceControlEditors.length; j++) {

                    var leftEditorUri = fileAndSourceControlEditors[i].document.uri;
                    var rigthEditorUri = fileAndSourceControlEditors[j].document.uri;

                    var leftUriFilePath = this.getRawUriFromGuestEditorUri(leftEditorUri);
                    var rightUriFilePath = this.getRawUriFromGuestEditorUri(rigthEditorUri);

                    if (leftUriFilePath.toString() === rightUriFilePath.toString()) {
                        let leftFileRelativePath = this.pathManager.localPathToRelativePath(leftEditorUri);
                        let rightFileRelativePath = this.pathManager.localPathToRelativePath(rigthEditorUri);
                        this.saveDiffViewInformation(clientId, leftEditorUri, rigthEditorUri);
                        this.emit(this.onDiffViewOpenEventName, leftFileRelativePath, rightFileRelativePath);
                    }
                }
            }
        }
    }

    private initGuestGitDocuments(visibleEditors: vscode.TextEditor[]) {
        let guestSourceControlEditors = visibleEditors.filter((editor) => {
            return editor?.document?.uri?.scheme === PathManager.vslsSccScheme;
        });

        guestSourceControlEditors.forEach(guestGitEditor => {
            // create the sharedFileClient for every new git editor
            this.emit(this.onNewGitDocumentEventName, guestGitEditor.document);
        });
    }

    public onEditorsChanged(visibleEditors: vscode.TextEditor[], isHost: boolean, clientId: number) {
        // check for diff views
        if (visibleEditors.length >= 2) {
            if (isHost) {
                this.onHostEditorsChanged(visibleEditors, clientId);
            } else {
                this.onGuestEditorsChanged(visibleEditors, clientId);
                this.initGuestGitDocuments(visibleEditors);
            }
        }

        // notify any diffs that are not visible anymore
        this.notifyDiffViewsClosed(clientId, visibleEditors);
    }

    /**
     * Subscribe to open diff view events.
     */
    public onDidOpenDiffView(handler: (leftFile: string, rightFile: string) => void) {
        this.addListener(this.onDiffViewOpenEventName, handler);
    }

    /**
     * Subscribe to close diff view events.
     */
    public onDidCloseDiffView(handler: (leftFile: string, rightFile: string) => void) {
        this.addListener(this.onDiffViewClosedEventName, handler);
    }

    /**
     * Subscribe to new git editor events.
     */
    public onDidOpenNewGitDocument(handler: (document: vscode.TextDocument) => void) {
        this.addListener(this.onNewGitDocumentEventName, handler);
    }

    /**
     * Clean up.
     */
    public dispose(): Promise<void> {
        this.removeAllListeners();
        return Promise.resolve();
    }

    /**
     * Gets a vsls URI from a guest URI, which might be vsls or vsls-scc.
     */
    private getRawUriFromGuestEditorUri(editorUri: vscode.Uri): vscode.Uri {
        // vsls: URI is saved in the resourceUri property of vsls-scc: URI query
        return (editorUri.scheme === PathManager.vslsSccScheme) ?
            this.pathManager.resourceUriFromLiveShareSourceControlUri(editorUri) :
            editorUri;
    }
}