'use strict';

import * as vscode from 'vscode';
import * as path from 'path';

import { Uri, Disposable, CancellationToken } from 'vscode';

import { IGuestSourceControlManager } from './Contracts';
import { IDependencies } from '../IDependencies';
import {
    IDependencies as ICoreDependencies,
    ExtensionUtil,
    TelemetryEventNames,
    ControllerHelper,
    commandBindingDecorator,
    VSLS_SCHEME,
    VSLS_EXTERNAL_SCHEME,
    KNOWN_SCHEMES,
    SccUriQuery,
    UriParams
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';
/** VSCode source control provider ID */
const SCC_PROVIDER_ID = 'vsls-scc';

/** Source control command prefix in package.json */
const COMMAND_PREFIX = 'liveshare.scc.';

/** Scheme for URIs that are handled by the VSLS source control provider */
const SCC_SCHEME = 'vsls-scc';

/** Repository count command context */
const REPO_COUNT_COMMAND_CONTEXT = 'vslsSccOpenRepositoryCount';

function getUri(params: UriParams): Uri | undefined {
    if (!params) {
        return;
    }

    const { resource, sccId, groupId } = params;

    if (!resource || !resource.path) {
        return;
    }

    // tslint:disable-next-line:no-shadowed-variable
    const path = resource.path;

    if (resource.type === vsls.SourceControlResourceType.SpecificVerision ||
        resource.type === vsls.SourceControlResourceType.WorkspaceWithSpecificVersion) {

        const query: SccUriQuery = { path };

        if (resource.type === vsls.SourceControlResourceType.WorkspaceWithSpecificVersion) {
            query.isWorkspace = true;
        }

        if (resource.version) {
            query.version = resource.version;
        }

        if (sccId) {
            query.sccId = sccId;
        }

        if (groupId) {
            query.groupId = groupId;
        }

        if (params.resourceUri) {
            query.resourceUri = params.resourceUri.toString();
        }

        return Uri.parse(`${SCC_SCHEME}://`).with({
            query: JSON.stringify(query),
            path: path
        });
    }

    if (KNOWN_SCHEMES.find(s => path.startsWith(s + ':'))) {
        return Uri.parse(path);
    }

    if (path.startsWith('file:')) {
        return Uri.parse(path).with({ scheme: VSLS_EXTERNAL_SCHEME });
    }

    let scheme: string;
    let uriPath = resource.path;

    switch (resource.type) {
        case vsls.SourceControlResourceType.Workspace:
            scheme = VSLS_SCHEME;
            if (uriPath) {
                uriPath = uriPath.replace(/\\/g, '/');
                if (!uriPath.startsWith('/')) {
                    uriPath = '/' + uriPath;
                }
            } else {
                uriPath = '/';
            }

            break;

        case vsls.SourceControlResourceType.External:
            scheme = VSLS_EXTERNAL_SCHEME;
            break;

        default:
            return;
    }

    return Uri.parse(`${scheme}:${uriPath}`);
}

function isDecorationEnabled() {
    return vscode.workspace.getConfiguration('git').get<boolean>('decorations.enabled', true);
}

// Group capabilties. These should match to checks in package.json
const GROUP_SUPPORTS_CLEAN = 'clean_';
const GROUP_SUPPORTS_OPEN_FILE = 'openFile_';
const GROUP_SUPPORTS_OPEN_CHANGES = 'openChanges_';

function getVSCodeGroupId(group: vsls.SourceControlResourceGroup): string | undefined {
    if (!group || !group.groupId) {
        return;
    }

    let result = '';

    if (group.supportsClean) {
        result += GROUP_SUPPORTS_CLEAN;
    }

    if (group.supportsOpenChanges) {
        result += GROUP_SUPPORTS_OPEN_CHANGES;
    }

    if (group.supportsOpenFile) {
        result += GROUP_SUPPORTS_OPEN_FILE;
    }

    // Escape _ in group id with ~_ to simplify regular expressions checking for group capabilties in package.json
    return result + group.groupId.replace('~', '~~').replace('_', '~_');
}

class SccRegistration implements vscode.DecorationProvider, vscode.QuickDiffProvider, Disposable {
    private static registrationCount = 0;
    private static readonly registrations = new Map<number, SccRegistration>();

    private readonly id: number;
    private readonly decorationsChanged = new vscode.EventEmitter<Uri[]>();
    private disposables: Disposable[] = [];
    private decorations = new Map<string, vscode.DecorationData>();
    public readonly groups = new Map<string, vscode.SourceControlResourceGroup>();
    public readonly instanceId: string;
    public readonly scc: vscode.SourceControl;
    public readonly sourceControlId: string;

    constructor(sourceControl: vsls.SourceControlInstance) {
        this.id = ++SccRegistration.registrationCount;
        SccRegistration.registrations.set(this.id, this);

        this.instanceId = sourceControl.instanceId;
        this.sourceControlId = sourceControl.sourceControlId;

        const rootUri = sourceControl.name ? Uri.file(`/${sourceControl.name}`) : undefined;
        this.scc = vscode.scm.createSourceControl(SCC_PROVIDER_ID, sourceControl.label, rootUri);
        this.scc.inputBox.visible = false;
        this.scc.quickDiffProvider = this;
        if (sourceControl.resourceGroups) {
            sourceControl.resourceGroups.forEach(g => this.createResourceGroup(g));
        }

        this.updateDecorations(false /* fireChangeEvent */);
        if (vscode.window.registerDecorationProvider) {
            this.disposables.push(vscode.window.registerDecorationProvider(this));
        }
    }

    /** vscode.DecorationProvider.onDidChangeDecorations */
    public readonly onDidChangeDecorations: vscode.Event<undefined | Uri | Uri[]> = this.decorationsChanged.event;

    /** vscode.DecorationProvider.provideDecoration */
    public provideDecoration(uri: Uri, token: CancellationToken): vscode.DecorationData | undefined {
        return this.decorations.get(uri.toString());
    }

    /** vscode.QuickDiffProvider.provideOriginalResource implementation */
    public provideOriginalResource(uri: Uri): Uri | undefined {
        const resource = SccRegistration.getResourceIdentity(uri);
        if (!resource || resource.type !== vsls.SourceControlResourceType.Workspace) {
            return;
        }

        resource.type = vsls.SourceControlResourceType.WorkspaceWithSpecificVersion;

        return this.getUri({ resource });
    }

    public dispose() {
        this.disposables.forEach(d => d.dispose());
        this.disposables = [];
        this.scc.dispose();
        SccRegistration.registrations.delete(this.id);
    }

    public update(sourceControl: vsls.SourceControlInstance) {
        const useIcons = !isDecorationEnabled();
        const vslsGroups = sourceControl.resourceGroups || [];
        this.groups.forEach(g => !vslsGroups.find(rg => getVSCodeGroupId(rg) === g.id) && this.groups.delete(g.id) && g.dispose());
        vslsGroups.forEach(vslsGroup => {
            const group = this.groups.get(getVSCodeGroupId(vslsGroup));
            if (group) {
                group.resourceStates = vslsGroup.resourceStates.map(s => new SccResourceState(this, vslsGroup.groupId, s, useIcons, vslsGroup.supportsClean, vslsGroup.supportsOpenChanges));
            } else {
                this.createResourceGroup(vslsGroup);
            }
        });

        this.updateDecorations(true /* fireChangeEvent */);
    }

    public getUri(params: UriParams): Uri | undefined {
        return getUri({ sccId: this.id, ...params });
    }

    public static getResourceIdentity(uri: Uri): vsls.SourceControlResourceIdentifier | undefined {
        if (!uri) {
            return;
        }

        switch (uri.scheme) {
            case VSLS_SCHEME:
                return {
                    path: uri.path,
                    type: vsls.SourceControlResourceType.Workspace,
                };

            case VSLS_EXTERNAL_SCHEME:
                return {
                    path: uri.path,
                    type: vsls.SourceControlResourceType.External,
                };

            case SCC_SCHEME:
                const query: SccUriQuery = JSON.parse(uri.query);
                if (!query || !query.path) {
                    return;
                }

                const type = query.isWorkspace ?
                    vsls.SourceControlResourceType.WorkspaceWithSpecificVersion : vsls.SourceControlResourceType.SpecificVerision;

                const result: vsls.SourceControlResourceIdentifier = {
                    path: query.path,
                    type,
                };

                if (query.version) {
                    result.version = query.version;
                }

                const registration = SccRegistration.registrations.get(query.sccId);
                if (registration) {
                    result.sourceControlId = registration.sourceControlId;
                    result.instanceId = registration.instanceId;
                }

                if (query.groupId) {
                    result.groupId = query.groupId;
                }

                return result;

            default:
        }
    }

    public getSccResources(uri: Uri | undefined): SccResourceState[] {
        uri = uri ? uri : (vscode.window.activeTextEditor && vscode.window.activeTextEditor.document.uri);
        if (!uri) {
            return [];
        }

        let uriStr: string;
        if (uri.scheme === SCC_SCHEME) {
            const query: SccUriQuery = JSON.parse(uri.query);
            if (!query || !query.resourceUri) {
                return [];
            }

            uriStr = query.resourceUri;
        } else {
            uriStr = uri.toString();
        }

        const result: SccResourceState[] = [];
        for (const [, group] of this.groups) {
            for (const resource of group.resourceStates) {
                if (resource.resourceUri.toString() === uriStr) {
                    result.push(<SccResourceState>resource);
                }
            }
        }

        return result;
    }

    private updateDecorations(fireChangeEvent: boolean) {
        if (!vscode.window.registerDecorationProvider) {
            return;
        }

        const newDecorations = new Map<string, vscode.DecorationData>();

        this.groups.forEach(group =>
            group.resourceStates.forEach(state => {
                const sccState = <SccResourceState><any>state;
                const decoration = sccState.resourceDecoration;
                if (decoration && sccState.original) {
                    newDecorations.set(sccState.original.toString(), decoration);
                }
            }));

        const uris = new Set([...this.decorations.keys()].concat([...newDecorations.keys()]));
        this.decorations = newDecorations;

        if (fireChangeEvent) {
            this.decorationsChanged.fire([...uris.values()].map(uri => Uri.parse(uri)));
        }
    }

    private createResourceGroup(vslsGroup: vsls.SourceControlResourceGroup) {
        if (!vslsGroup) {
            return;
        }

        const group = this.scc.createResourceGroup(getVSCodeGroupId(vslsGroup), vslsGroup.label);
        if (vslsGroup.hideWhenEmpty) {
            group.hideWhenEmpty = true;
        }

        const useIcons = !isDecorationEnabled();
        group.resourceStates = vslsGroup.resourceStates.map(s => new SccResourceState(this, vslsGroup.groupId, s, useIcons, vslsGroup.supportsClean, vslsGroup.supportsOpenChanges)).filter(s => s.resourceUri);
        this.groups.set(group.id, group);
    }
}

const imagesRoot = 'images';

class SccResourceState implements vscode.SourceControlResourceState {
    public readonly current: vsls.SourceControlResource;
    public readonly resourceUri: Uri | undefined;
    public readonly original: Uri | undefined;
    public readonly changeType?: vsls.SourceControlChangeType | undefined;

    constructor(
        private readonly sccRegistration: SccRegistration,
        public readonly groupId: string,
        resourceState: vsls.SourceControlResourceState,
        private readonly useIcons: boolean,
        public readonly supportsClean?: boolean | undefined,
        public readonly supportsOpenChanges?: boolean | undefined) {

        this.current = resourceState.current;
        this.changeType = resourceState.changeType;
        this.resourceUri = sccRegistration.getUri({ resource: resourceState.current, groupId });
        this.original = sccRegistration.getUri({ resource: resourceState.original, groupId }) || this.resourceUri;
    }

    public get instanceId(): string { return this.sccRegistration.instanceId; }
    public get sourceControlId(): string { return this.sccRegistration.sourceControlId; }
    public readonly command: vscode.Command = {
        command: COMMAND_PREFIX + 'openChange',
        title: 'Open',
        arguments: [this]
    };

    public get ResourceIdentity(): vsls.SourceControlResourceIdentifier {
        return {
            sourceControlId: this.sourceControlId,
            instanceId: this.instanceId,
            groupId: this.groupId,
            path: this.current.path,
            version: this.current.version,
            type: this.current.type,
        };
    }

    public get decorations(): vscode.SourceControlResourceDecorations {
        const tooltip = this.tooltip;
        const strikeThrough = this.strikeThrough;
        const letter = this.letter;
        const color = this.color;
        const light = this.useIcons ? { iconPath: this.getIconPath('light') } : undefined;
        const dark = this.useIcons ? { iconPath: this.getIconPath('dark') } : undefined;

        return { strikeThrough, faded: false, tooltip, light, dark, letter, color, source: 'vsls-scc.resource' };
    }

    public get resourceDecoration(): vscode.DecorationData | undefined {
        if (!this.changeType || this.changeType === vsls.SourceControlChangeType.Delete ||
            this.changeType === vsls.SourceControlChangeType.IndexDelete) {
            return;
        }

        const title = this.tooltip;
        const letter = this.letter;
        const color = this.color;
        const priority = this.priority;
        return { bubble: true, source: 'git.resource', title, letter, color, priority };
    }

    public getUri(params: UriParams): Uri {
        return this.sccRegistration.getUri({ groupId: this.groupId, resourceUri: this.resourceUri, ...params });
    }

    private getIconPath(theme: string): string | Uri | undefined {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.IndexEdit:
            case vsls.SourceControlChangeType.Edit:
                return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-modified.svg`);

            case vsls.SourceControlChangeType.Add:
                return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-added.svg`);

            case vsls.SourceControlChangeType.IndexDelete:
            case vsls.SourceControlChangeType.Delete:
                return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-deleted.svg`);

            case vsls.SourceControlChangeType.Rename: return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-renamed.svg`);
            case vsls.SourceControlChangeType.IndexCopy: return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-copied.svg`);
            case vsls.SourceControlChangeType.Untracked: return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-untracked.svg`);
            case vsls.SourceControlChangeType.Ignored: return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-ignored.svg`);

            case vsls.SourceControlChangeType.DeleteBoth:
            case vsls.SourceControlChangeType.AddByUs:
            case vsls.SourceControlChangeType.DeleteByThem:
            case vsls.SourceControlChangeType.AddByThem:
            case vsls.SourceControlChangeType.DeleteByUs:
            case vsls.SourceControlChangeType.AddBoth:
            case vsls.SourceControlChangeType.Conflict:
                return ExtensionUtil.getExtensionUri(`${imagesRoot}/${theme}/status-conflict.svg`);

            default:
        }
    }

    private get priority(): number {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.IndexEdit:
            case vsls.SourceControlChangeType.Edit:
                return 2;
            case vsls.SourceControlChangeType.Ignored:
                return 3;
            case vsls.SourceControlChangeType.IndexCopy:
            case vsls.SourceControlChangeType.DeleteBoth:
            case vsls.SourceControlChangeType.AddByUs:
            case vsls.SourceControlChangeType.DeleteByThem:
            case vsls.SourceControlChangeType.AddByThem:
            case vsls.SourceControlChangeType.DeleteByUs:
            case vsls.SourceControlChangeType.AddBoth:
            case vsls.SourceControlChangeType.Conflict:
                return 4;
            default:
                return 1;
        }
    }

    private get tooltip(): string {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.IndexEdit: return 'Index Modified';
            case vsls.SourceControlChangeType.Edit: return 'Modified';
            case vsls.SourceControlChangeType.Add: return 'Index Added';
            case vsls.SourceControlChangeType.IndexDelete: return 'Index Deleted';
            case vsls.SourceControlChangeType.Delete: return 'Deleted';
            case vsls.SourceControlChangeType.Rename: return 'Index Renamed';
            case vsls.SourceControlChangeType.IndexCopy: return 'Index Copied';
            case vsls.SourceControlChangeType.Untracked: return 'Untracked';
            case vsls.SourceControlChangeType.Ignored: return 'Ignored';
            case vsls.SourceControlChangeType.DeleteBoth: return 'Both Deleted';
            case vsls.SourceControlChangeType.AddByUs: return 'Added By Us';
            case vsls.SourceControlChangeType.DeleteByThem: return 'Deleted By Them';
            case vsls.SourceControlChangeType.AddByThem: return 'Added By Them';
            case vsls.SourceControlChangeType.DeleteByUs: return 'Deleted By Us';
            case vsls.SourceControlChangeType.AddBoth: return 'Both Added';
            case vsls.SourceControlChangeType.Conflict: return 'Both Modified';
            default: return '';
        }
    }

    private get letter(): string | undefined {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.IndexEdit:
            case vsls.SourceControlChangeType.Edit:
                return 'M';
            case vsls.SourceControlChangeType.Add:
                return 'A';
            case vsls.SourceControlChangeType.IndexDelete:
            case vsls.SourceControlChangeType.Delete:
                return 'D';
            case vsls.SourceControlChangeType.Rename:
                return 'R';
            case vsls.SourceControlChangeType.Untracked:
                return 'U';
            case vsls.SourceControlChangeType.Ignored:
                return 'I';
            case vsls.SourceControlChangeType.DeleteByThem:
                return 'D';
            case vsls.SourceControlChangeType.DeleteByUs:
                return 'D';
            case vsls.SourceControlChangeType.IndexCopy:
            case vsls.SourceControlChangeType.DeleteBoth:
            case vsls.SourceControlChangeType.AddByUs:
            case vsls.SourceControlChangeType.AddByThem:
            case vsls.SourceControlChangeType.AddBoth:
            case vsls.SourceControlChangeType.Conflict:
                return 'C';
            default:
                return undefined;
        }
    }

    private get color(): vscode.ThemeColor | undefined {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.IndexEdit:
            case vsls.SourceControlChangeType.Edit:
                return new vscode.ThemeColor('gitDecoration.modifiedResourceForeground');
            case vsls.SourceControlChangeType.IndexDelete:
            case vsls.SourceControlChangeType.Delete:
                return new vscode.ThemeColor('gitDecoration.deletedResourceForeground');
            case vsls.SourceControlChangeType.Add:
                return new vscode.ThemeColor('gitDecoration.addedResourceForeground');
            case vsls.SourceControlChangeType.Rename:
            case vsls.SourceControlChangeType.Untracked:
                return new vscode.ThemeColor('gitDecoration.untrackedResourceForeground');
            case vsls.SourceControlChangeType.Ignored:
                return new vscode.ThemeColor('gitDecoration.ignoredResourceForeground');
            case vsls.SourceControlChangeType.IndexCopy:
            case vsls.SourceControlChangeType.DeleteBoth:
            case vsls.SourceControlChangeType.AddByUs:
            case vsls.SourceControlChangeType.DeleteByThem:
            case vsls.SourceControlChangeType.AddByThem:
            case vsls.SourceControlChangeType.DeleteByUs:
            case vsls.SourceControlChangeType.AddBoth:
            case vsls.SourceControlChangeType.Conflict:
                return new vscode.ThemeColor('gitDecoration.conflictingResourceForeground');
            default:
                return undefined;
        }
    }

    private get strikeThrough(): boolean {
        switch (this.changeType) {
            case vsls.SourceControlChangeType.Delete:
            case vsls.SourceControlChangeType.DeleteBoth:
            case vsls.SourceControlChangeType.DeleteByThem:
            case vsls.SourceControlChangeType.DeleteByUs:
            case vsls.SourceControlChangeType.IndexDelete:
                return true;
            default:
                return false;
        }
    }
}

export const guestSourceControlManagerFactory = (coreDependencies: ICoreDependencies, dependencies: IDependencies) => {
    const {
        controllerDecorator,
        errorNotificationMethodDecorator,
        telemetryMethodDecorator
    } = coreDependencies.methodDecorators();

    @controllerDecorator
    class GuestSourceControlManager implements IGuestSourceControlManager, vscode.TextDocumentContentProvider {
        private sccRegistrations: SccRegistration[] = [];
        private disposables: Disposable[] = [];
        private isActive = false;

        constructor(private readonly service: vsls.SourceControlService) { }

        public async init() {
            if (this.isActive) {
                return;
            }

            this.isActive = true;
            this.disposables.push(
                vscode.workspace.registerTextDocumentContentProvider(SCC_SCHEME, this),
            );

            ControllerHelper.register(this, this.disposables);

            await this.addSourceControls();

            if (!this.isActive) {
                return;
            }

            this.service.onSourceControlChanged(this.sourceControlChanged, this, this.disposables);
        }

        public async dispose() {
            if (!this.isActive) {
                return;
            }

            this.isActive = false;
            this.disposeSourceControls();

            this.disposables.forEach(d => d.dispose());
            this.disposables = [];
        }

        /** vscode.TextDocumentContentProvider.onDidChange */
        public onDidChange?: vscode.Event<Uri>;

        /** vscode.TextDocumentContentProvider.provideTextDocumentContent */
        public async provideTextDocumentContent(uri: Uri, cancellationToken: CancellationToken): Promise<string> {
            const resource = SccRegistration.getResourceIdentity(uri);
            if (!resource) {
                return '';
            }

            return await this.service.getResourceAsync(resource, cancellationToken);
        }

        private sourceControlChanged(e: vsls.SourceControlChangedEventArgs) {
            if (!e || !this.isActive) {
                return;
            }

            const sourceControl = e.sourceControl;
            if (!sourceControl) {
                return;
            }

            const sccId = sourceControl.sourceControlId;
            const instanceId = sourceControl.instanceId;

            if (instanceId) {
                switch (e.change) {
                    case vsls.SourceControlChange.Added:
                        this.addSourceControls(sccId, instanceId);
                        break;

                    case vsls.SourceControlChange.Removed:
                        this.disposeSourceControls(sccId, instanceId);
                        break;

                    case vsls.SourceControlChange.Updated:
                        this.updateSourceControl(sccId, instanceId);
                        break;

                    default:
                    // Unknown vsls.SourceControlChange
                }
            } else {
                this.disposeSourceControls(sccId);
                if (e.change !== vsls.SourceControlChange.Removed) {
                    this.addSourceControls(sccId);
                }
            }
        }

        private disposeSourceControls(sourceControlId?: string | undefined, instanceId?: string | undefined) {
            if (sourceControlId) {
                for (let index = this.sccRegistrations.length - 1; index >= 0; index++) {
                    if (this.sccRegistrations[index].sourceControlId === sourceControlId &&
                        (!instanceId || this.sccRegistrations[index].instanceId === instanceId)) {
                        const [regitration] = this.sccRegistrations.splice(index, 1);
                        regitration.dispose();
                    }
                }
            } else {
                this.sccRegistrations.forEach(r => r.dispose());
                this.sccRegistrations = [];
            }

            this.updateSourceControlCountContext(this.sccRegistrations.length);
        }

        private async addSourceControls(sourceControlId?: string | undefined, instanceId?: string | undefined) {
            try {
                const sourceControls = !sourceControlId ? await this.service.getAllSourceControlsAsync() :
                    instanceId ? [await this.service.getSourceControlAsync({ sourceControlId: sourceControlId, instanceId })] :
                        await this.service.getSourceControlsAsync(sourceControlId);

                if (!this.isActive) {
                    return;
                }

                sourceControls.forEach(s => this.sccRegistrations.push(new SccRegistration(s)));
                this.updateSourceControlCountContext(this.sccRegistrations.length);
            } catch {
                // Session closed or no source control for the given scc id.
                // Just ignore that.            
            }
        }

        private async updateSourceControl(sourceControlId: string, instanceId: string) {
            const registration = this.sccRegistrations.find(r => r.sourceControlId === sourceControlId && r.instanceId === instanceId);
            if (!registration) {
                await this.addSourceControls(sourceControlId, instanceId);
                return;
            }

            try {
                const sourceControl = await this.service.getSourceControlAsync({ sourceControlId, instanceId });
                if (!this.isActive) {
                    return;
                }

                if (!sourceControl) {
                    this.disposeSourceControls(sourceControlId, instanceId);
                } else {
                    registration.update(sourceControl);
                }
            } catch {
                // Session closed or no source control for the given scc id.
                // Remove the source control.
                if (!this.isActive) {
                    this.disposeSourceControls(sourceControlId, instanceId);
                }
            }
        }

        @errorNotificationMethodDecorator('Opening source-controlled resource', TelemetryEventNames.OPEN_SCC_RESOURCE_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.OPEN_SCC_RESOURCE, TelemetryEventNames.OPEN_SCC_RESOURCE_FAULT, 'GuestSourceControlManager.openFile')
        @commandBindingDecorator('liveshare.scc.openFile')
        @commandBindingDecorator('liveshare.scc.openFile2')
        public async openFile(arg?: SccResourceState | Uri, ...resources: SccResourceState[]) {
            const preserveFocus = arg instanceof SccResourceState;

            let uris: Uri[] | undefined;

            if (!arg) {
                // If the command is invoked from command palette or key binding, no argument is given.
                // Get the uri for the active document then.
                uris = this.getSccResources().map(r => r.resourceUri);
            } else if (arg instanceof Uri) {
                // If the command is invoked from the editor, the arg is the URI of the document.
                switch (arg.scheme) {
                    case VSLS_SCHEME:
                    case VSLS_EXTERNAL_SCHEME:
                        uris = [arg];
                        break;

                    case SCC_SCHEME:
                        const query: SccUriQuery = JSON.parse(arg.query);
                        if (query.resourceUri) {
                            uris = [Uri.parse(query.resourceUri)];
                        }

                        break;

                    default:
                }
            } else {
                // The command is invoked from Source Control viewlet, the arg is resource state.
                const resource = arg;
                if (!(resource instanceof SccResourceState)) {
                    return;
                }

                if (resource) {
                    uris = [resource, ...resources]
                        .filter(r => r.changeType !== vsls.SourceControlChangeType.Delete && r.changeType !== vsls.SourceControlChangeType.IndexDelete)
                        .map(r => r.resourceUri);
                }
            }

            if (!uris || !uris.length) {
                return;
            }

            const activeTextEditor = vscode.window.activeTextEditor;
            for (const uri of uris) {
                const opts: vscode.TextDocumentShowOptions = {
                    preserveFocus,
                    preview: false,
                    viewColumn: vscode.ViewColumn.Active
                };

                const document = await vscode.workspace.openTextDocument(uri);

                if (activeTextEditor && activeTextEditor.document.uri.toString() === uri.toString()) {
                    // preserve not only selection but also visible range
                    opts.selection = activeTextEditor.selection;
                    const previousVisibleRanges = activeTextEditor.visibleRanges;
                    const editor = await vscode.window.showTextDocument(document, opts);
                    editor.revealRange(previousVisibleRanges[0]);
                } else {
                    await vscode.window.showTextDocument(document, opts);
                }
            }
        }

        @errorNotificationMethodDecorator('Opening source-controlled changes', TelemetryEventNames.OPEN_SCC_CHANGE_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.OPEN_SCC_CHANGE, TelemetryEventNames.OPEN_SCC_CHANGE_FAULT, 'GuestSourceControlManager.openChanges')
        @commandBindingDecorator('liveshare.scc.openChange')
        public async openChanges(arg?: SccResourceState | Uri, ...resourceStates: SccResourceState[]) {
            const preserveFocus = arg instanceof SccResourceState;
            const preserveSelection = arg instanceof Uri || !arg;
            let resources: SccResourceState[] = [];

            if (!arg) {
                // The command is invoked from the command palette or key binding.
                // Target the resources from the active editor.
                resources = this.getSccResources();
            } else if (arg instanceof Uri) {
                // The command is invoked from the editor.
                resources = this.getSccResources(arg);
            } else if (arg instanceof SccResourceState) {
                // The command is invoked from source control viewlet.
                resources = [...resourceStates, arg];
            }

            resources = resources.filter(r => r.supportsOpenChanges);
            const preview = resources.length === 1 ? undefined : false;
            for (const resource of resources) {
                await this.openChange(resource, preview, preserveFocus, preserveSelection);
            }
        }

        private async openChange(resource: SccResourceState, preview: boolean | undefined, preserveFocus?: boolean, preserveSelection?: boolean) {
            if (!resource) {
                return;
            }

            const diff = await this.service.getDiffForResourceAsync(resource.ResourceIdentity);
            if (!diff) {
                return;
            }

            const right = resource.getUri({ resource: diff.right });
            const left = resource.getUri({ resource: diff.left });

            const opts: vscode.TextDocumentShowOptions = {
                preserveFocus,
                preview,
                viewColumn: vscode.ViewColumn.Active
            };

            const activeTextEditor = vscode.window.activeTextEditor;

            // Check if active text editor has same path as other editor.
            const singleFile = right || left;
            if (preserveSelection && activeTextEditor && activeTextEditor.document.uri.toString() === singleFile.toString()) {
                opts.selection = activeTextEditor.selection;
            }

            if (left && right) {
                await vscode.commands.executeCommand('vscode.diff', left, right, diff.title, opts);
            } else { 
                await vscode.commands.executeCommand('vscode.open', singleFile, opts, diff.title);
            }
        }

        private updateSourceControlCountContext(repoCount: number) {
            vscode.commands.executeCommand('setContext', REPO_COUNT_COMMAND_CONTEXT, `${repoCount}`);
        }

        @errorNotificationMethodDecorator('Discarding source-controlled changes', TelemetryEventNames.DISCARD_SCC_CHANGE_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.DISCARD_SCC_CHANGE, TelemetryEventNames.DISCARD_SCC_CHANGE_FAULT, 'GuestSourceControlManager.clean')
        @commandBindingDecorator('liveshare.scc.clean')
        public async clean(...scmResources: SccResourceState[]) {
            scmResources = scmResources.filter(s => !!s && s.supportsClean);
            if (!scmResources.length || !this.isActive) {
                return;
            }

            const untrackedCount = scmResources.reduce((s, r) => s + (r.changeType === vsls.SourceControlChangeType.Untracked ? 1 : 0), 0);
            let message: string;
            let yes = 'Discard Changes';

            if (scmResources.length === 1) {
                if (untrackedCount > 0) {
                    message = `Are you sure you want to DELETE ${path.basename(scmResources[0].resourceUri.fsPath)}?`;
                    yes = 'Delete file';
                } else {
                    if (scmResources[0].changeType === vsls.SourceControlChangeType.Delete) {
                        yes = 'Restore file';
                        message = `Are you sure you want to restore ${path.basename(scmResources[0].resourceUri.fsPath)}?`;
                    } else {
                        message = `Are you sure you want to discard changes in ${path.basename(scmResources[0].resourceUri.fsPath)}?`;
                    }
                }
            } else {
                if (scmResources.every(resource => resource.changeType === vsls.SourceControlChangeType.Delete)) {
                    yes = 'Restore files';
                    message = `Are you sure you want to restore ${scmResources.length} files?`;
                } else {
                    message = `Are you sure you want to discard changes in ${scmResources.length} files?`;
                }

                if (untrackedCount > 0) {
                    message = `${message}\n\nThis will DELETE ${untrackedCount} untracked files!`;
                }
            }

            const pick = await vscode.window.showWarningMessage(message, { modal: true }, yes);

            if (pick !== yes) {
                return;
            }

            await this.service.cleanResourcesAsync(scmResources.map(r => r.ResourceIdentity));
        }

        @errorNotificationMethodDecorator('Discarding all source-controlled changes', TelemetryEventNames.DISCARD_ALL_SCC_CHANGES_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.DISCARD_ALL_SCC_CHANGES, TelemetryEventNames.DISCARD_ALL_SCC_CHANGES_FAULT, 'GuestSourceControlManager.cleanAll')
        @commandBindingDecorator('liveshare.scc.cleanAll')
        public async cleanAll(arg: vscode.SourceControlResourceGroup) {
            if (arg && arg.resourceStates) {
                await this.clean(...<SccResourceState[]>arg.resourceStates);
            }
        }

        private getSccResources(uri?: Uri | undefined): SccResourceState[] {
            const result: SccResourceState[] = [];
            return result.concat(...this.sccRegistrations.map(r => r.getSccResources(uri)));
        }


        @errorNotificationMethodDecorator('Revert change', TelemetryEventNames.REVERT_SCC_CHANGE_FAULT)
        @telemetryMethodDecorator(TelemetryEventNames.REVERT_SCC_CHANGE, TelemetryEventNames.REVERT_SCC_CHANGE_FAULT, 'GuestSourceControlManager.revertChange')
        @commandBindingDecorator('liveshare.scc.revertChange')
        public async revertChange(uri: Uri, changes: vscode.LineChange[], index: number) {
            if (!uri) {
                return;
            }

            const textEditor = vscode.window.visibleTextEditors.find(e => e.document.uri.toString() === uri.toString());
            if (!textEditor) {
                return;
            }

            const diff = changes[index];
            const isInsertion = diff.originalEndLineNumber === 0;
            const isDeletion = diff.modifiedEndLineNumber === 0;

            let baselineText = undefined;

            if (!isInsertion) {
                // Get the vsls-scc: URI for the baseline document
                const resource = SccRegistration.getResourceIdentity(uri);
                if (!resource || resource.type !== vsls.SourceControlResourceType.Workspace) {
                    return;
                }
                resource.type = vsls.SourceControlResourceType.WorkspaceWithSpecificVersion;
                const uriParams: UriParams = { resource };
                const originalUri = this.sccRegistrations.length === 1 ? this.sccRegistrations[0].getUri(uriParams) : getUri(uriParams);
                if (!originalUri) {
                    return;
                }

                const originalDocument = await vscode.workspace.openTextDocument(originalUri);
                baselineText = originalDocument.getText(new vscode.Range(diff.originalStartLineNumber - 1, 0, diff.originalEndLineNumber, 0));
            }

            const selectionsBeforeRevert = textEditor.selections;
            const visibleRangesBeforeRevert = textEditor.visibleRanges;

            const modifiedRange = !isDeletion && new vscode.Range(diff.modifiedStartLineNumber - 1, 0, diff.modifiedEndLineNumber, 0);
            const edit = new vscode.WorkspaceEdit();
            if (isInsertion) {
                edit.delete(uri, modifiedRange);
            } else if (isDeletion) {
                edit.insert(uri, new vscode.Position(diff.modifiedStartLineNumber, 0), baselineText);
            } else {
                edit.replace(uri, modifiedRange, baselineText);
            }

            vscode.workspace.applyEdit(edit);

            await textEditor.document.save();

            textEditor.selections = selectionsBeforeRevert;
            textEditor.revealRange(visibleRangesBeforeRevert[0]);
        }
    }

    return <any>new GuestSourceControlManager(dependencies.sourceControlService());
};
