import { TraceSource } from '@vs/vso-logging';
import { traceSource } from '@vs/vscode-command-framework';
import {
    Telemetry, ITelemetry,
} from '@vs/vso-telemetry';
import { ISessionContext } from './ISessionContext';
import { IDependencies } from './contracts/IDependencies';
import { IRpcServices } from './contracts/IRpcServices';
import { SessionContext } from './SessionContext';
import { PathManager } from './PathManager';
import { ContextUtil } from './utils/ContextUtil';
import { ProgressNotifierUtil } from './utils/ProgressNotifierUtil';
import { lazyLoad, delayedLoadMutable, lazyLoadMutable } from './Lazy';
import { CommandContextBuilder } from './CommandContextBuilder';
import { CommandRegistryProvider } from './CommandRegistryProvider';
import { AuthenticationFlow } from './auth/AuthenticationFlow';
import { FileSystemManager } from './file-system-provider/FileSystemManager';
import { CoEditingCommands } from './coediting/CoEditingCommands';
import { SessionStateManager } from './SessionStateManager';
import { methodDecoratorsFactory } from './CommandBinding';
import { IAccessControlManager } from './contracts/IAccessControlManager';
import { AccessControlManager } from './accessControl/AccessControlManager';
import { WorkspaceAccessControlManager } from './accessControl/WorkspaceAccessControlManager';
import { AuthenticationProviderService } from './auth/nativeAuth/AuthenticationProviderService';
import { WorkspaceServices } from './WorkspaceServices';

export class Dependencies {
    public static rpcServices: IRpcServices;
}

function getRpcServices(): IRpcServices {
    if (!Dependencies.rpcServices) {
        throw new Error('rpcServices not defined');
    }

    return Dependencies.rpcServices;
}

export const dependencies = (function (sessionContext: ISessionContext, trace: TraceSource, telemetry: ITelemetry): IDependencies {
    const context: IDependencies = {
        rpcClient: delayedLoadMutable('rpcClient'),
        rpcFactory: (serviceInfo, traceName) => getRpcServices().rpcFactory(serviceInfo, traceName),
        sessionContext: () => sessionContext,
        trace: () => trace,
        telemetry: () => telemetry,
        contextUtil: lazyLoad(() => new ContextUtil()),

        workspaceService: lazyLoad(() => getRpcServices().workspaceService()),
        accessControlService: lazyLoad(() => getRpcServices().accessControlService()),
        workspaceAccessControlService: lazyLoad(() => getRpcServices().workspaceAccessControlService()),
        fileService: lazyLoad(() => getRpcServices().fileService()),
        streamManagerService: lazyLoad(() => getRpcServices().streamManagerService()),
        streamService: lazyLoad(() => getRpcServices().streamService()),
        chatService: lazyLoad(() => getRpcServices().chatService()),
        terminalService: lazyLoad(() => getRpcServices().terminalService()),
        rpcServiceHandler: () => getRpcServices().rpcServiceHandler(),
        fileSystemManager: lazyLoad(() => new FileSystemManager(context, context.sessionContext())),
        coEditingCommands: lazyLoad(() => new CoEditingCommands(context.sessionContext())),
        pathManager: lazyLoad(() => {
            return new PathManager(false, context.fileService);
        }),
        sourceEventService: lazyLoad(() => getRpcServices().sourceEventService()),
        workspaceUserService: lazyLoad(() => getRpcServices().workspaceUserService()),
        syncService: lazyLoad(() => getRpcServices().syncService()),
        serverSharingService: lazyLoad(() => getRpcServices().serverSharingService()),
        portForwardingService: lazyLoad(() => getRpcServices().portForwardingService()),

        commandContextBuilder: lazyLoad(() => new CommandContextBuilder(traceSource)),
        commandRegistryProvider: lazyLoad(() => new CommandRegistryProvider(context.commandContextBuilder(), Telemetry, traceSource.withName('CommandRegistry'))),
        progressNotifierUtil: lazyLoad(() => new ProgressNotifierUtil(context.contextUtil(), context.workspaceService(), traceSource.withName('Progress'))),
        authenticationFlow: lazyLoad(() => {
            const instance = new AuthenticationFlow(context.authenticationProvider(), traceSource.withName('AuthenticationFlow'));
            return instance;
        }),
        authenticationProvider: delayedLoadMutable('authenticationProvider'),
        sessionStateManager: lazyLoad(() => new SessionStateManager()),
        methodDecorators: lazyLoad(() => methodDecoratorsFactory(context)),
        authService: lazyLoadMutable(() => new AuthenticationProviderService(traceSource.withName('AuthenticationProviderService'))),
        workspaceServices: lazyLoad(() => new WorkspaceServices(context.workspaceService())),
        accessControlManager: lazyLoad<IAccessControlManager>(() => new AccessControlManager(
            context.workspaceAccessControlService(),
            context.accessControlService(),
            context.sessionContext(),
            context.fileSystemManager(),
            context.hostSessionId())),
        hostSessionId: delayedLoadMutable('hostSessionId'),
        workspaceAccessControlManager: lazyLoad(() => new WorkspaceAccessControlManager(context, context.hostSessionId())),
        statusBarController: delayedLoadMutable('statusBarController'),
    };
    return context;
})(SessionContext, traceSource, Telemetry);

