import * as vscode from 'vscode';
import { IMap } from '../../IMap';
import * as colorString from 'color-string';
import { PositionTracker } from './positionTracker';
import { PathManager } from '../../PathManager';

type CssRules = IMap<string | number>;

export enum NameTagVisibility {
    Never = 'Never',
    Activity = 'Activity',
    Always = 'Always'
}

export abstract class TextEditorDecoratorBase {
    protected decoration?: vscode.TextEditorDecorationType;
    protected color: DecoratorColor;
    protected backgroundCssColor: string;
    protected textCssColor: string;

    constructor(color: DecoratorColor) {
        this.color = color;
        this.backgroundCssColor = DecoratorUtils.toCssColor(this.color.backgroundColor);
        this.textCssColor = DecoratorUtils.toCssColor(this.color.textColor);
    }

    public dispose(): void {
        if (this.decoration) {
            this.decoration.dispose();
        }
    }

    public render(renderInEditors: (vscode.TextEditor | vscode.NotebookEditor)[], cursorPos: vscode.Position, selectionRange: vscode.Range, lineCount?: number): void {
        if (this.decoration) {
            this.decoration.dispose();
            this.decoration = undefined;
        }

        if (!renderInEditors || !renderInEditors.length || !cursorPos || !selectionRange) {
            return;
        }

        this._createDecorationStyle(cursorPos, selectionRange, lineCount);
        this._renderCore(renderInEditors, cursorPos, selectionRange);
    }

    protected abstract _renderCore(renderInEditors: (vscode.TextEditor | vscode.NotebookEditor)[], cursorPos: vscode.Position, selectionRange: vscode.Range): void;
    protected abstract _createDecorationStyle(cursorPos: vscode.Position, selectionRange: vscode.Range, lineCount?: number): void;
}

export class CursorDecorator extends TextEditorDecoratorBase {
    private displayName: string;

    constructor(color: DecoratorColor, displayName: string) {
        super(color);
        this.displayName = displayName;
    }

    protected _renderCore(renderInEditors: vscode.TextEditor[], cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        if (!this.decoration) {
            return;
        }

        const decoratorRange = new vscode.Range(cursorPos, cursorPos);
        const renderOptions: vscode.DecorationOptions = {
            range: decoratorRange
        };

        if (selectionRange.isEmpty) {
            // TODO: When https://github.com/Microsoft/vscode/issues/37401 is fixed, we will also need to add a check
            // for the nameTagVisibility. If it is set to Always, then this hover message should not be shown
            // (because the name tag will already be shown).
            renderOptions.hoverMessage = this.displayName;
        }

        renderInEditors.forEach((editor) => {
            editor.setDecorations(this.decoration!, [renderOptions]);
        });
    }

    protected _createDecorationStyle(cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        const leftMarginValue = cursorPos.character === 0 ? '0.17' : '0.25';
        const cursorCssRules: CssRules = {
            position: 'absolute',
            display: 'inline-block',
            top: `0`,
            'font-size': '200%',
            'font-weight': 'bold',
            'z-index': 1
        };
        const stringifiedNameTagCss = DecoratorUtils.stringifyCssProperties(cursorCssRules);
        const decorationOptions: vscode.DecorationRenderOptions = {
            rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
            before: {
                contentText: 'ᛙ',
                margin: `0px 0px 0px -${leftMarginValue}ch`,
                color: this.backgroundCssColor,
                textDecoration: `none; ${stringifiedNameTagCss}`
            }
        };

        this.decoration = vscode.window.createTextEditorDecorationType(decorationOptions);
    }
}

export class NameTagDecorator extends TextEditorDecoratorBase {
    private displayName: string;

    constructor(color: DecoratorColor, displayName: string) {
        super(color);
        this.displayName = displayName;
    }

    public updateDisplayName(name: string) {
        this.displayName = name;
    }

    protected _renderCore(renderInEditors: vscode.TextEditor[], cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        if (!this.decoration) {
            return;
        }

        const decoratorRange = new vscode.Range(cursorPos, cursorPos);

        renderInEditors.forEach((editor) => {
            editor.setDecorations(this.decoration!, [decoratorRange]);
        });
    }

    protected _createDecorationStyle(cursorPos: vscode.Position, selectionRange: vscode.Range, lineCount?: number): void {
        let showAbove = true;

        // Name tag goes below if cursor is on 1st line or if there is a multiline, non-reversed selection.
        if (cursorPos.line === 0 || selectionRange && !selectionRange.isEmpty && !selectionRange.isSingleLine && selectionRange.end.isEqual(cursorPos)) {
            
            //if we pass in lineCount, show above if we are on the first line and there is only one line
            if (lineCount && cursorPos.line === 0 && lineCount === 1) {
                showAbove = true;
            } else {
                showAbove = false;
            }
        }

        const topValue = showAbove ? -1 : 1;
        const nameTagCssRules: CssRules = {
            position: 'absolute',
            top: `${topValue}rem`,
            'border-radius': '0.15rem',
            padding: '0px 0.5ch',
            display: 'inline-block',
            'pointer-events': 'none',
            color: this.textCssColor,
            'font-size': '0.7rem',
            'z-index': 1,
            'font-weight': 'bold'
        };
        const stringifiedNameTagCss = DecoratorUtils.stringifyCssProperties(nameTagCssRules);
        const decorationOptions: vscode.DecorationRenderOptions = {
            backgroundColor: this.backgroundCssColor,
            rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
            textDecoration: 'none; position: relative; z-index: 1;',
            after: {
                contentText: this.displayName,
                backgroundColor: this.backgroundCssColor,
                textDecoration: `none; ${stringifiedNameTagCss}`
            }
        };

        this.decoration = vscode.window.createTextEditorDecorationType(decorationOptions);
    }
}

export class RulerDecorator extends TextEditorDecoratorBase {
    constructor(color: DecoratorColor) {
        super(color.withBackgroundAlpha(0.6));
    }

    protected _renderCore(renderInEditors: vscode.TextEditor[], cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        if (!this.decoration) {
            return;
        }

        const decoratorRange = new vscode.Range(cursorPos, cursorPos);

        renderInEditors.forEach((editor) => {
            editor.setDecorations(this.decoration!, [decoratorRange]);
        });
    }

    protected _createDecorationStyle(cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        this.decoration = vscode.window.createTextEditorDecorationType({
            overviewRulerLane: vscode.OverviewRulerLane.Full,
            overviewRulerColor: this.backgroundCssColor
        });
    }
}

export class SelectionDecorator extends TextEditorDecoratorBase {
    private displayName: string;

    constructor(color: DecoratorColor, displayName: string) {
        super(color.withBackgroundAlpha(0.35));
        this.displayName = displayName;
    }

    protected _renderCore(renderInEditors: vscode.TextEditor[], cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        if (selectionRange.isEmpty) {
            return;
        }

        const renderOptions: vscode.DecorationOptions = {
            range: selectionRange,
            hoverMessage: this.displayName
        };

        renderInEditors.forEach((editor) => {
            editor.setDecorations(this.decoration!, [renderOptions]);
        });
    }

    protected _createDecorationStyle(cursorPos: vscode.Position, selectionRange: vscode.Range): void {
        this.decoration = vscode.window.createTextEditorDecorationType({
            backgroundColor: this.backgroundCssColor,
            borderRadius: '0.1rem'
        });
    }
}

export class ClientDecoratorManager {
    private clientId: number;
    private clientDisplayName: string;
    private clientColor: DecoratorColor;
    public nameTagVisibility: NameTagVisibility;
    private nameTagVisibilityTimer?: ReturnType<typeof setTimeout>;
    private positionTracker: PositionTracker;

    private selectionDecorator: SelectionDecorator;
    private cursorDecorator: CursorDecorator;
    private nameTagDecorator: NameTagDecorator;
    private rulerDecorator: RulerDecorator;

    constructor(clientId: number, clientDisplayName: string, nameTagVisibility: NameTagVisibility, positionTracker: PositionTracker) {
        this.clientId = clientId;
        this.clientDisplayName = clientDisplayName;
        this.clientColor = SharedColors.requestColor(clientId);
        this.nameTagVisibility = nameTagVisibility;
        this.positionTracker = positionTracker;

        this.selectionDecorator = new SelectionDecorator(this.clientColor, this.clientDisplayName);
        this.cursorDecorator = new CursorDecorator(this.clientColor, this.clientDisplayName);
        this.nameTagDecorator = new NameTagDecorator(this.clientColor, this.clientDisplayName);
        this.rulerDecorator = new RulerDecorator(this.clientColor);
    }

    public dispose(): void {
        if (this.nameTagVisibilityTimer) {
            clearTimeout(this.nameTagVisibilityTimer);
        }
        this.disposeDecorators();
    }

    public updateNameTag(name: string) {
        this.nameTagDecorator.updateDisplayName(name);
    }

    public updateDecorators(): void {
        const _lastTrackedPosition = this.positionTracker.getClientPosition(this.clientId);
        const renderInEditors: (vscode.TextEditor | vscode.NotebookEditor)[] = [];

        const lastTrackedPosition = _lastTrackedPosition?.documentPosition || _lastTrackedPosition?.notebookPosition;

        let lineCount;
        if (lastTrackedPosition) {
            vscode.window.visibleTextEditors.forEach((editor) => {
                if (editor.document.uri.toString() === lastTrackedPosition.documentUri.toString()) {
                    if (editor.document.uri.scheme.startsWith(PathManager.notebookCellScheme)) {
                        lineCount = editor.document.lineCount;
                    }
                    renderInEditors.push(editor);
                }
            });
            try {
                vscode.window.visibleNotebookEditors.forEach((editor) => {
                    if (editor.document.uri.toString() === lastTrackedPosition.documentUri.toString()) {
                        renderInEditors.push(editor);
                    }
                });
            } catch { /* Proposed APIs */ }
        }

        if (!renderInEditors.length) {
            // This client is not in a currently visible editor (splitview tab).
            this.disposeDecorators();
            return;
        }

        const selectionRange = lastTrackedPosition!.range;
        const cursorPosition = _lastTrackedPosition.documentPosition?.isReversed ? selectionRange.start : selectionRange.end;
        this.selectionDecorator.render(renderInEditors, cursorPosition, selectionRange);
        this.rulerDecorator.render(renderInEditors, cursorPosition, selectionRange);

        switch (this.nameTagVisibility) {
            case NameTagVisibility.Always:
                this.cursorDecorator.render(renderInEditors, cursorPosition, selectionRange);
                this.nameTagDecorator.render(renderInEditors, cursorPosition, selectionRange, lineCount);
                break;
            case NameTagVisibility.Never:
                this.cursorDecorator.render(renderInEditors, cursorPosition, selectionRange);
                if (this.nameTagDecorator) {
                    this.nameTagDecorator.dispose();
                }
                break;
            case NameTagVisibility.Activity:
            default:
                if (this.nameTagVisibilityTimer) {
                    clearTimeout(this.nameTagVisibilityTimer);
                }

                this.cursorDecorator.render(renderInEditors, cursorPosition, selectionRange);
                this.nameTagDecorator.render(renderInEditors, cursorPosition, selectionRange, lineCount);
                this.nameTagVisibilityTimer = setTimeout(() => {
                    this.nameTagDecorator.dispose();
                }, 1500);
                break;
        }
    }

    private disposeDecorators(): void {
        this.selectionDecorator.dispose();
        this.cursorDecorator.dispose();
        this.nameTagDecorator.dispose();
        this.rulerDecorator.dispose();
    }
}

class DecoratorColor {
    public readonly backgroundColor: vscode.Color;
    public readonly textColor: vscode.Color;

    constructor(backgroundColor: vscode.Color, textColor: vscode.Color) {
        this.backgroundColor = backgroundColor;
        this.textColor = textColor;
    }

    /**
     * Returns a new DecoratorColor instance based on this one, with the alpha channel set to the given value for the background.
     * @param alpha The desired transparency, from 0 (transparent) to 1 (opaque)
     */
    public withBackgroundAlpha(alpha: number): DecoratorColor {
        // Clamp alpha between 0 and 1
        alpha = Math.max(0, alpha);
        alpha = Math.min(1, alpha);
        const newBgColor = new vscode.Color(this.backgroundColor.red, this.backgroundColor.green, this.backgroundColor.blue, alpha);
        return new DecoratorColor(newBgColor, this.textColor);
    }
}

export class SharedColors {
    private static allColors: DecoratorColor[];

    public static requestColor(clientId: number): DecoratorColor {
        SharedColors._initcolors();

        return SharedColors.allColors[clientId % SharedColors.allColors.length];
    }

    private static _initcolors(): void {
        if (SharedColors.allColors) {
            return;
        }

        // Colors are used in order. Earlier in the array means they will be used first.
        const defaultColors = [
            // Yellow
            ['rgba(0, 0, 0, 1)', 'rgba(255, 185, 0, 1)'],
            // Green
            ['rgba(255, 255, 255, 1)', 'rgba(16, 124, 16, 1)'],
            // Magenta
            ['rgba(255, 255, 255, 1)', 'rgba(180, 0, 158, 1)'],
            // Light green
            ['rgba(0, 0, 0, 1)', 'rgba(186, 216, 10, 1)'],
            // Light orange
            ['rgba(0, 0, 0, 1)', 'rgba(255, 140, 0, 1)'],
            // Light magenta
            ['rgba(255, 255, 255, 1)', 'rgba(227, 0, 140, 1)'],
            // Purple
            ['rgba(255, 255, 255, 1)', 'rgba(92, 45, 145, 1)'],
            // Light teal
            ['rgba(0, 0, 0, 1)', 'rgba(0, 178, 148, 1)'],
            // Light yellow
            ['rgba(0, 0, 0, 1)', 'rgba(255, 241, 0, 1)'],
            // Light purple
            ['rgba(0, 0, 0, 1)', 'rgba(180, 160, 255, 1)']
        ];

        const colorCustomizations = vscode.workspace.getConfiguration('workbench.colorCustomizations');
        let cursorForegroundBackgroundColors: ([string, string])[] = (colorCustomizations && colorCustomizations['cascade.cursorForegroundBackgroundColors']);

        if (cursorForegroundBackgroundColors && Array.isArray(cursorForegroundBackgroundColors)) {
            SharedColors.allColors = SharedColors.parseColors(cursorForegroundBackgroundColors);
        }

        if (!SharedColors.allColors || !SharedColors.allColors.length) {
            SharedColors.allColors = SharedColors.parseColors(<([string, string])[]>defaultColors);
        }
    }

    private static parseColors(colorStringPairs: ([string, string])[]): DecoratorColor[] {
        const parsedColors = colorStringPairs
            .map((colorPair) => {
                if (colorPair && colorPair.length === 2) {
                    const foregroundColor = DecoratorUtils.toVSCodeColor(colorPair[0]);
                    const backgroundColor = DecoratorUtils.toVSCodeColor(colorPair[1]);
                    if (foregroundColor && backgroundColor) {
                        return new DecoratorColor(backgroundColor, foregroundColor);
                    }
                }
            })
            .filter((color) => !!color)
            .reverse() as DecoratorColor[];
        return parsedColors;
    }
}

export class DecoratorUtils {
    public static stringifyCssProperties(rules: CssRules): string {
        return Object.keys(rules)
            .map((rule) => {
                return `${rule}: ${rules[rule]};`;
            })
            .join(' ');
    }

    public static toCssColor(color: vscode.Color): string {
        const r = Math.round(color.red * 255);
        const g = Math.round(color.green * 255);
        const b = Math.round(color.blue * 255);
        return `rgba(${r}, ${g}, ${b}, ${color.alpha})`;
    }

    public static toVSCodeColor(color: string): vscode.Color | null {
        const parsedColor = colorString.get.rgb(color);
        if (parsedColor) {
            const [r, g, b, a] = parsedColor;
            return new vscode.Color(r / 255, g / 255, b / 255, a);
        } else {
            // colorString couldn't parse the color out of that string.
            return null;
        }
    }

    public static isSamePosition(p1: vscode.Position, p2: vscode.Position): boolean {
        if (p1 === null || p2 === null) {
            return false;
        }
        return p1.isEqual(p2);
    }

    public static isSameRange(r1: vscode.Range, r2: vscode.Range): boolean {
        if (r1 === null || r2 === null) {
            return false;
        }
        return r1.isEqual(r2);
    }
}
