import * as dateformat from 'dateformat';
import * as path from 'path';

import { Privacy } from './Privacy';
import { LoggerSettings } from './LoggerSettings';
import { LogLevel } from "./interfaces/LogLevel";
import { LogValueType } from "./interfaces/LogValueType";
import { errorToString } from './utils';

const renderObjectToString = (object: any) => {
    if (typeof object === undefined) {
        return '<undefined>';
    }

    if (typeof object === null) {
        return '<null>';
    }

    if (typeof object === 'string') {
        return `"${object}"`;
    }

    if (typeof object === 'number') {
        return `#${object}`;
    }

    if (typeof object === 'boolean') {
        return `${object}`;
    }

    if (object instanceof Symbol) {
        return object.toString();
    }

    if (object instanceof Error) {
        return errorToString(object);
    }

    try {
        return TraceFormat.stringify(object);
    } catch {
        try {
            return object.toString();
        } catch (e) {
            return '<unknown type>';
        }
    }
};


export class TraceFormat {
    private static readonly maxMessageLength: number = 5120;

    public static formatDate(time: Date, mask?: string) {
        return dateformat(time, mask || 'yyyy-mm-dd HH:MM:ss.l ', /*utc*/ true);
    }

    public static formatEvent(
        time: Date | null,
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): string {
        let eventTypeChar;
        switch (logLevel) {
            case LogLevel.Critical:
                eventTypeChar = 'C';
                break;
            case LogLevel.Error:
                eventTypeChar = 'E';
                break;
            case LogLevel.Warning:
                eventTypeChar = 'W';
                break;
            case LogLevel.Info:
                eventTypeChar = 'I';
                break;
            case LogLevel.Debug:
                eventTypeChar = 'V';
                break;

            default:
                eventTypeChar = '?';
                break;
        }

        const dateString = time === null ? '' : TraceFormat.formatDate(time);

        if (message.length > TraceFormat.maxMessageLength) {
            message = message.substr(0, TraceFormat.maxMessageLength) + '...';
        }

        let line;
        if (id !== 0) {
            line = `[${dateString}${source} ${eventTypeChar}] (${id}) ${message}`;
        } else {
            line = `[${dateString}${source} ${eventTypeChar}] ${message}`;
        }

        const renderedObjects = args
            .map(renderObjectToString)
            .map((str, i) => {
                return `> object #${i}: ${str}`;
            });

        line += renderedObjects.join('\n');

        return line;
    }

    public static parseEventId(formattedMessage: string): number {
        let m = formattedMessage.match(/\] \(([0-9]+)\)/);
        return m ? parseInt(m[1], 10) : 0;
    }

    public static formatPath(value: string): string {
        if (!value) {
            return '<null>';
        } else if (LoggerSettings.disableObfuscation) {
            return value;
        }

        // Obfuscate the directory and file names, but preserve the extension
        // and whether it's an absolute or relative path.
        const directoryHash = Privacy.getShortHash(path.dirname(value));
        const extension = path.extname(value);
        const fileHash = Privacy.getShortHash(path.basename(value, extension));
        const slashIndex = value.replace('\\', '/').indexOf('/');

        if (slashIndex === 2 && value[1] === ':') {
            // Windows style absolute path
            return `<?:${value[2]}${directoryHash}${value[2]}${fileHash}${extension}>`;
        } else if (slashIndex === 0) {
            // Unix style absolute path
            return `<${value[0]}${directoryHash}${value[0]}${fileHash}${extension}>`;
        } else if (slashIndex > 0) {
            // Relative path
            return `<${directoryHash}${value[slashIndex]}${fileHash}${extension}>`;
        } else {
            // Simple file name
            return `<${fileHash}${extension}>`;
        }
    }

    public static formatEmail(value: string): string {
        if (!value) {
            return '<null>';
        } else if (LoggerSettings.disableObfuscation) {
            return value;
        }

        const emailHash = Privacy.getShortHash(value);
        return `<${emailHash.substr(0, 4)}@${emailHash.substr(4)}>`;
    }

    public static formatText(value: string): string {
        if (!value) {
            return '<null>';
        } else if (LoggerSettings.disableObfuscation) {
            return value;
        }

        const valueHash = Privacy.getShortHash(value);
        return `<${value.length}:${valueHash}>`;
    }

    public static stringify(value: any) {
        if (LoggerSettings.disableObfuscation) {
            return JSON.stringify(value, null, 2);
        }

        return JSON.stringify(value, (key, value) => {
            if (value instanceof Error) {
                return errorToString(value);
            }

            const logValueType = LoggerSettings.obfuscateProperties[key];
            if (logValueType) {
                switch (logValueType) {
                    case LogValueType.Text:
                        return TraceFormat.formatText(value);
                    case LogValueType.Email:
                        return TraceFormat.formatEmail(value);
                    case LogValueType.Path:
                        return TraceFormat.formatPath(value);
                }
            }

            return value;
        }, 2);
    }
}
