import * as vscode from 'vscode';
import { getExtensionContext } from './ExtentionContext';

export function getExtensionUri(
    relativePath: string,
    extensionContext?: vscode.ExtensionContext,
): vscode.Uri {
    const vscodeModule = require('vscode') as typeof vscode;

    extensionContext = extensionContext || getExtensionContext();
    return vscodeModule.Uri.joinPath(extensionContext.extensionUri, relativePath);
}
