import * as vscode from 'vscode';
import * as nls from 'vscode-nls';

import { Access, ShareOptions, ViewItem } from '@vs/liveshare-api-contracts';
import { ExtensionTreeDataProvider, TreeDataProviderContext } from './ExtensionTreeDataProvider';
import { getLabelAndLinkTreeViewItems } from './getLabelAndLinkTreeViewItems';
import { TreeViewItem } from './TreeViewItem';
import { localize } from '../localize';

export class CollabActionTreeDataProvider implements ExtensionTreeDataProvider {  
    constructor(private isInFileTreeExplorer: boolean) {
    }

    public get supportedContext() {
        return TreeDataProviderContext.NotSharedOrJoined;
    }

    public getTreeItem(element: TreeViewItem): vscode.TreeItem | Thenable<vscode.TreeItem> {
        return element;
    }

    public async getChildren(element?: TreeViewItem): Promise<TreeViewItem[]> {

        const sharecommand = (this.isInFileTreeExplorer)
                ? 'liveshare.startFromFileTreeExplorer'
                : 'liveshare.startFromActivityBar';
        const joinCommand = (this.isInFileTreeExplorer)
                ? 'liveshare.joinFromFileTreeExplorer'
                : 'liveshare.joinFromActivityBar';
        const startSessionLabel = localize('startCollaborationSession');
        let result = [
            new TreeViewItem({
                type: ViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: localize('joinCollaborationSession'),
                command: {
                    title: 'Join collaboration session...',
                    command: joinCommand
                }
            }),
            new TreeViewItem({
                type: ViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: startSessionLabel ,
                command: {
                    title: startSessionLabel,
                    command: sharecommand
                }
            })
        ];

        const shareOptions: ShareOptions = { access: Access.ReadOnly };

        const shareReadOnlyCommand = (this.isInFileTreeExplorer)
            ? 'liveshare.startReadOnlyFromFileTreeExplorer'
            : 'liveshare.startReadOnlyFromActivityBar';

        result.push(
            new TreeViewItem({
                type: ViewItem.Other,
                collapsibleState: vscode.TreeItemCollapsibleState.None,
                label: localize('startReadOnlyCollaborationSession'),
                command: {
                    title: 'Start read-only collaboration session..',
                    command: shareReadOnlyCommand,
                    arguments: [shareOptions]
                }
            }));

        const sessionExplorerLinksAndLabels = await getLabelAndLinkTreeViewItems('SessionExplorer');
        result.push(...sessionExplorerLinksAndLabels);

        return Promise.resolve(result);
    }
}