import { Uri } from 'vscode';
import * as vscode from 'vscode';
import { DEFAULT_PLANNED_SESSION_LABEL } from '../constants';
import { ICommandContext } from '@vs/vscode-command-framework';
import { PlannedSessionsUtils } from '../plannedSessionUtils';

import { 
    SessionAction,
    TelemetryEventNames, 
    TelemetryPropertyNames,
    workspaceSessionInfoTracker,
    errorNotificationCommandDecorator,
    telemetryCommandDecorator,
    telemetryStatusCommandDecorator,
    cancellationDecorator,
    authenticationCommandDecorator,
    IAuthenticationDecoratorOptions, IDependencies,
    localize, ICommand
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

export function builder(dependencies: IDependencies):  ICommand<Uri>  {
    return new CreatePlannedSessionCommand(
        dependencies.workspaceService(),
    );
}

const authOptions: IAuthenticationDecoratorOptions = {
    statusPostAuth: SessionAction.Create
};

/**
 * Create planned session `command` that creates a persistent session
 */
@cancellationDecorator()
@errorNotificationCommandDecorator('Creating a Planned Session link', TelemetryEventNames.CREATE_PLANNED_SESSION_FAULT)
@telemetryCommandDecorator(TelemetryEventNames.CREATE_PLANNED_SESSION, TelemetryEventNames.CREATE_PLANNED_SESSION_FAULT, 'Create Planned Session', 1)
@telemetryStatusCommandDecorator()
@authenticationCommandDecorator(authOptions)
export class CreatePlannedSessionCommand implements ICommand<Uri>  {
    
    constructor(private workspaceService: vsls.WorkspaceService) {}

    public async invoke(options: any, context: ICommandContext): Promise<Uri> {
        const { cancellationTokenSource } = context;

        try {      
            let name = await PlannedSessionsUtils.getUsernameFromInputAsync(DEFAULT_PLANNED_SESSION_LABEL, cancellationTokenSource.token);
            if (name) {
            await vscode.window.withProgress(
                { location: vscode.ProgressLocation.Notification,
                    title: localize('progress.creatingPlannedSession') }, async () => {
                    await this.workspaceService.createPersistentWorkspaceAsync(name, true, cancellationTokenSource && cancellationTokenSource.token);
                });

            let workspaceList  = await this.workspaceService.listWorkspacesAsync({onlyManagedWorkspaces: true}); 
            workspaceSessionInfoTracker.isPlannedSessionsChanged = true;
            workspaceSessionInfoTracker.plannedWorkspaceList  = workspaceList;
            context.telemetryEvent.addProperty(TelemetryPropertyNames.CREATE_PLANNED_SESSION, true);
            }
        } catch (e) {
            context.trace.error(`Failed to create a Planned Session link. ${e}`);
            throw new Error(localize('error.CannotCreatePlannedSession'));
        }
        return;
    }
}