import * as net from 'net';

import { ILiveShareConnectionOptions, IWorkspaceClient } from '@vs/vso-workspace-core';
import { errorToObject, once, withHelperDecorator, withRetries } from '@vs/vscs-utils';
import { LiveShareConnection, TConnectionTypes } from '@vs/vscs-connection-hub';
import { WorkspaceHubClient } from '@vs/vso-workspace-client-hub';
import { startSocketSessionOnPipe } from '@vs/vso-node-utils';
import { NodeStream } from '@vs/vs-ssh';

let hubClientSession = 0;

const MAX_RETRIES = 20;
const WAIT_TIME_MS = 1000;

export interface IHubClientConnectionOptions extends ILiveShareConnectionOptions {
    hubPipeName: string;
};

/**
 * A hub client connection to use the hub-agent to create
 * liveshare connections thru the separate process.
 */
export class HubClientConnection extends LiveShareConnection<IHubClientConnectionOptions> {
    private socket: net.Socket | null = null;

    public get type() {
        return TConnectionTypes.WorkspaceHub;
    }

    /**
     * Create the WorkspaceClient that is capable of connecting thru the "remote" WorkspaceHub.
     */
    protected async createWorkspaceClient(): Promise<IWorkspaceClient> {
        const { hubPipeName } = this.options;

        const socket = await this.startSocketSessionForHubWorkspace(hubPipeName);
        return await WorkspaceHubClient.create(
            new NodeStream(socket),
            this.trace.createChild(`workspace-hub-client:${++hubClientSession}`),
        );
    }

    /**
     * Connect to the WorkspaceHub socket.
     */
    @withHelperDecorator(once)
    private async startSocketSessionForHubWorkspace(
        hubPipeName: string,
    ): Promise<net.Socket> {
        return await withRetries(async (retriesLeft) => {
            const retry = MAX_RETRIES - retriesLeft;

            this.trace
                .verbose(`trying to connect to the TCP socket, retries left: "${retriesLeft}" (retry: "${retry}")`);

            const pipeName = retry === 0 ? hubPipeName : `${hubPipeName}-${retry}`;
            this.socket = await startSocketSessionOnPipe(pipeName);

            this.socket.on('close', this.dispose.bind(this, 'TCP socket closed.'));
            this.socket.on('end', this.dispose.bind(this, 'TCP socket ended'));

            return this.socket;
        }, {
            retries: MAX_RETRIES,
            retryDelay: WAIT_TIME_MS,
        });
    }
    
    /**
     * Make sure we disconnect from the WorkspaceHub and close
     * the socket on dispose.
     */
    public dispose(reason?: string): this {
        if (this.isDisposed) {
            return this;
        }

        // disconnect WorkspaceClient
        this.workspaceClientReference
            ?.disconnect()
            .catch((error) => {
                this.trace.verbose('error while disconnecting workspace client: ', errorToObject(error))
            })
            .finally(() => {
                this.workspaceClientReference?.dispose(reason);

                this.workspaceClientReference = undefined;
                this.workspaceSessionInfoReference = undefined;
            });

        // close the socket
        this.socket?.destroy();

        return this;
    }
};
