import * as ssh from '@vs/vs-ssh';
import { CancellationToken } from 'vscode-jsonrpc';

export function createDuplexStreams(): [ssh.Stream, ssh.Stream] {
    return DuplexStream.createStreams();
}

class DuplexStream extends ssh.BaseStream {
    private other!: DuplexStream;

    public static createStreams(): [ssh.Stream, ssh.Stream] {
        const stream1 = new DuplexStream();
        const stream2 = new DuplexStream();
        stream1.other = stream2;
        stream2.other = stream1;
        return [stream1, stream2];
    }

    private constructor() {
        super();
    }

    public async write(data: Buffer, cancellation?: CancellationToken): Promise<void> {
        if (!data) throw new TypeError('Data is required.');
        this.other.onData(Buffer.from(data));
        return;
    }

    public async close(error?: Error, cancellation?: CancellationToken): Promise<void> {
        if (!error) {
            this.dispose();
            this.other.onEnd();
            this.other.dispose();
        } else {
            this.onError(error);
            this.dispose();
            this.other.onError(error);
            this.other.dispose();
        }
        return;
    }

    public dispose(): void {
        super.dispose();

        if (!this.other.isDisposed) {
            this.other.onError(new Error('Stream disposed.'));
            this.other.dispose();
        }
    }
}
