import * as https from 'https';
import * as uuid from 'uuid';
import { TraceSource } from '@vs/vso-logging';
import { SkypeTokenInfo } from '@calling-service/ICallingService';
import { AUTH_TOKEN_TENANT_ID } from '../constants';

export class DeferredPromise<T>  {
    private deferredReject: any;
    private deferredResolve: any;

    public promise: Promise<T>;

    constructor() {
        let deferredResolve: (value?: T | PromiseLike<T>) => void;
        let deferredReject: (reason?: any) => void;
        this.promise = new Promise<T>((resolve, reject) => {
            deferredResolve = resolve;
            deferredReject = reject;
        });

        this.deferredReject = deferredReject;
        this.deferredResolve = deferredResolve;
    }

    public resolve(data?: any) {
        this.deferredResolve(data);
    }

    public reject(error: any) {
        this.deferredReject(error);
    }
}

export async function getVSLSTokenFromAuthService(trace: TraceSource): Promise<SkypeTokenInfo> {
    const options = {
        hostname: 'authsvc-server.teams.microsoft.com',
        port: 443,
        path: '/v1.0/authz/visitor',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'x-ms-request-id': uuid(),
            'x-ms-client-type': 'ms-vsliveshare.vsliveshare'
        }
    };

    const data = JSON.stringify({
        'tenantId': AUTH_TOKEN_TENANT_ID
    });

    let skypeTokenInfo: SkypeTokenInfo;
    const skypeTokenReady = new DeferredPromise();
    let result = '';
    const req = https.request(options, (res: any) => {
        if (res.statusCode !== 200) {
            skypeTokenReady.reject(`Expected 200 status code to get SkypeToken. status code: ${res.statusCode}`);
            return;
        }

        res.setEncoding('utf8');
        res.on('data', (d: string) => {
            result += d;
        });
        res.on('end', function () {
            const response = JSON.parse(result);
            skypeTokenInfo = response.tokens;
            skypeTokenReady.resolve();
        });
    });

    req.on('error', (error) => {
        skypeTokenReady.reject(`HTTPS request failed for SkypeToken: ${error.message}`);
    });
    req.write(data);
    req.end();

    await skypeTokenReady.promise.catch((e) => {
        throw new Error(e);
    });

    if (!skypeTokenInfo) {
        throw new Error('Error retrieving SkypeToken');
    }
    skypeTokenInfo.skypeId = getSkypeId(skypeTokenInfo.skypeToken);
    return skypeTokenInfo;
}

function getSkypeId(token: string) {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const decoded = JSON.parse(Buffer.from(base64, 'base64').toString('ascii'));
        if (!decoded.skypeid) {
            throw new Error('skypeid claim not found');
        }
        return decoded.skypeid;
    } catch (e) {
        throw new Error(`Cannot retrieve skypeid from token: ${e.message}`);
    }
}