import * as vscode from 'vscode';
import { DEFAULT_PLANNED_SESSION_LABEL } from './constants';
import { env as vscodeEnv, CancellationToken } from 'vscode';
import {  NotificationUtil, CancellationError} from '@vs/vscode-command-framework';

import { 
    localize
} from '@vs/liveshare-core';
import { vsls } from '@vs/vsls-contracts';

// export const clipboard = new NodeClipboard();
// The VS Code clipboard API supports headless, but is
// not available in all verisons. Determine if it can be used.
/* tslint:disable-next-line:no-string-literal */
const vscodeClipboard = (<any>vscodeEnv)['clipboard'];
const vscodeClipboardExists = typeof vscodeClipboard !== 'undefined';

export class PlannedSessionsUtils {

    constructor() {
    }

    public static async getUsernameFromInputAsync(label: string,  cancellationToken?: CancellationToken): Promise<string | undefined>  {
        const previousLabel = label;
        const findNamePromise = new Promise<string | undefined>(async (resolve, reject) => {

        if (cancellationToken) {
            cancellationToken.onCancellationRequested(() => {
                return resolve(undefined);
            });
        }
    
        let name = await NotificationUtil.showInputBox({
            prompt: localize('plannedSessions.Name'),
            ignoreFocusOut: true,
            value: previousLabel || DEFAULT_PLANNED_SESSION_LABEL
        }, cancellationToken);

        // check for empty string
        while ( name === '') {
            name = await NotificationUtil.showInputBox({
                prompt: localize('plannedSessions.NameCannotBeEmpty'),
                ignoreFocusOut: true,
                value: previousLabel || DEFAULT_PLANNED_SESSION_LABEL
            }, cancellationToken);
        }

        // check for alpha numeric
        const regEx = /^[a-z0-9 ]+$/i;
        while (!regEx.test(name)) {
            name = await NotificationUtil.showInputBox({
                prompt: localize('plannedSessions.NameIsInvalid'),
                ignoreFocusOut: true,
                value: previousLabel || DEFAULT_PLANNED_SESSION_LABEL
            }, cancellationToken);
        }

        const trimmedName = (name || '').trim();
        
        if (trimmedName) {
            return resolve(trimmedName.slice(0, 50));
        } else {
            return resolve(undefined);
        }
    });
        return findNamePromise;
    }
 
    public static async copyToClipboardAsync(value: string): Promise<boolean> {

        try {
            if (vscodeClipboardExists) {
                await vscodeClipboard.writeText(value);
            } else {
                await vscodeClipboard.writeAsync(value);
            }
            return true;
        } catch (e) {
            // Clipboard can fail in certain environments, such as Linux/WSL
            // when dependencies are missing, or Windows with anti-malware restrictions.
            return false;
        }
    }

    public static async selectPlannedSessionItemFromCommandPaletteAsync(workspaceList: vsls.WorkspaceInfo[], cancellationToken?: CancellationToken): Promise<vsls.WorkspaceInfo | undefined> {
        const findNamePromise = new Promise<vsls.WorkspaceInfo | undefined>(async (resolve, reject) => {
            if (cancellationToken) {
                cancellationToken.onCancellationRequested(() => {
                    return resolve(undefined);
                });
            }
            const quickpickItems: vscode.QuickPickItem[] = workspaceList.map(workspaceInfo => {
            return {
                label: workspaceInfo.label,
            };
        });
            const finalList = quickpickItems;
            const selected = await vscode.window.showQuickPick(finalList, {
            placeHolder: localize('plannedSessions.quickPickSelectWindow'),
            matchOnDetail: true,
            matchOnDescription: true
        }, cancellationToken);

            if (!!selected) {
            const selectedWindowLabel = workspaceList.find(
                x => x.label === selected.label
            );

            if (!!selectedWindowLabel) {
                return resolve(selectedWindowLabel);
            }
        }
        
        });
        return findNamePromise;
    }
}