import { ConnectionHub, ILiveShareConnection, LiveShareConnection, TConnectionTypes } from '@vs/vscs-connection-hub';
import { ILiveShareConnectionOptions, IWorkspaceClient } from '@vs/vso-workspace-core';
import { WorkspaceClient } from "@vs/vso-workspace-client";
import { TimeTracker } from "../utils/performance";
import { openWorkspaceConnection } from "./openWorkspaceConnection";
import { dependencies } from "../Dependencies";
import { once, TConstructable } from '@vs/vscs-utils';
import { ILogger } from '@vs/vso-logging';
import { getOrCreatePerformance } from '@vs/vscs-performance';
import { traceSource } from '@vs/vscode-command-framework';

/**
 * A hub client connection to use the hub-agent to create liveshare connections.
 */
 class LocalClientConnection extends LiveShareConnection {
    public get type() {
        return TConnectionTypes.WorkspaceHub;
    }

    protected async createWorkspaceClient(): Promise<IWorkspaceClient> {
        return createLocalWorkspaceClient(this.trace);
    }
};

export function createLocalWorkspaceClient(logger: ILogger) {
    const workspaceClient = new WorkspaceClient(
        logger,
        async (workspaceInfo, logger) => {
            const sshStream = await TimeTracker.timeIt('openStream', () => openWorkspaceConnection(workspaceInfo, logger, dependencies.hubConnectionServiceFactory));
            return sshStream;
        }, {
            enabled: true,
            retryTimeout: 250,
            maxTimeReconnect: 10000,                
        });

    return workspaceClient;    
}

type ConstructableLiveShareConnection = TConstructable<ILiveShareConnection>;

export const initLocalConnectionHub = once((
    trace?: ILogger,
    connectionClass?: ConstructableLiveShareConnection
): ConnectionHub<ConstructableLiveShareConnection> => {
    // connection in local process
    const connectionHub = new ConnectionHub(
        (trace || traceSource).createChild('localConnectionHub'),
        getOrCreatePerformance().createGroup('LocalConnectionHub'),
        connectionClass || LocalClientConnection,
    );

    return connectionHub;
});

export const joinWithLocalConnectionHub = (trace: ILogger, options: ILiveShareConnectionOptions, connectionClass?: ConstructableLiveShareConnection) => {
    return initLocalConnectionHub(trace, connectionClass).connectOnce(options);   
}