import { ICommandContext } from '@vs/vscode-command-framework';
import { TimeTracker } from '../utils/performance';

import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';

/**
 * Instrumentation other pieces of middleware.
 */
export class MetaProfilingCommandDecorator implements ICommandDecorator {
    private readonly friendlyName: string;

    constructor(
        private command: ICommand<any>,
        public next: ICommand<any>) {
        this.friendlyName = (this.next && this.next.constructor && this.next.constructor.name).replace('CommandDecorator', '');
    }

    public async invoke(options: any, context: ICommandContext): Promise<any> {
        let result: any = undefined;
        let hasError = false;

        TimeTracker.start(this.friendlyName, 'Decorator:');
        context.trace.info(`Decorator: ${this.friendlyName} Starting`);

        try {
            result = await this.next.invoke(options, context);
        } catch (e) {
            hasError = true;
            throw e;
        } finally {
            const errorText = hasError ? 'Failed' : 'Success';
            TimeTracker.stop(this.friendlyName, 'Decorator:', errorText);
            context.trace.info(`Decorator: ${this.friendlyName} Completed ${errorText}`);
        }

        return result;
    }
}