import { Telemetry, TelemetryEvent, SendOnceFilter } from '@vs/vso-telemetry';
import { TelemetryPropertyNames, TelemetryEventOrigin } from '@vs/liveshare-core';

export class PortForwardingTelemetry {
    public static readonly FEATURE_PREFIX = 'portforwarding/';
    public static readonly PROPERTY_PREFIX = TelemetryPropertyNames.FEATURE_NAME + 'portforwarding.';

    public static listSharedLocalServers(origin?: TelemetryEventOrigin): void {
        PortForwardingTelemetry.sendEvent(Event.LIST_SHARED_LOCAL_SERVERS, origin);
    }

    public static shareServer(sourcePort: number, origin?: TelemetryEventOrigin): void {
        PortForwardingTelemetry.sendEvent(Event.SHARE_SERVER, origin, sourcePort);
    }

    public static unshareServer(sourcePort: number, origin?: TelemetryEventOrigin): void {
        PortForwardingTelemetry.sendEvent(Event.UNSHARE_SERVER, origin, sourcePort);
    }

    private static sendEvent(eventName: string, origin?: TelemetryEventOrigin, sourcePort?: number): void {
        const event = new TelemetryEvent(eventName);
        if (sourcePort) {
            event.addProperty(Property.SOURCE_PORT, sourcePort.toString());
        }

        event.send();
    }

    private static configured = false;

    public static configure() {
        if (!PortForwardingTelemetry.configured) {
            PortForwardingTelemetry.configured = true;
            Telemetry.addFilter(new SendOnceFilter(Event.AUTO_DETECT_SERVER, [Property.SOURCE_PORT]));
        }
    }

    public static autoDetectServer(sourcePort: number, serverUrl: string): void {
        const event = new TelemetryEvent(Event.AUTO_DETECT_SERVER);
        event.addProperty(Property.SOURCE_PORT, sourcePort.toString());
        event.send();
    }
}

class Event {
    /// <summary>
    /// User lists shared local servers.
    /// </summary>
    public static readonly LIST_SHARED_LOCAL_SERVERS = PortForwardingTelemetry.FEATURE_PREFIX + 'list-shareLocalServers';

    /// <summary>
    /// User shares a local server.
    /// </summary>
    public static readonly SHARE_SERVER = PortForwardingTelemetry.FEATURE_PREFIX + 'share-server';

    /// <summary>
    /// User unshares a local server.
    /// </summary>
    public static readonly UNSHARE_SERVER = PortForwardingTelemetry.FEATURE_PREFIX + 'unshare-server';

    /// <summary>
    /// Server url is detected by a data scraper (or some other method)
    /// </summary>
    public static readonly AUTO_DETECT_SERVER = PortForwardingTelemetry.FEATURE_PREFIX + 'auto-detect-server';
}

class Property {
    /// <summary>
    /// Task or operation origin.
    /// </summary>
    public static readonly ORIGIN = PortForwardingTelemetry.PROPERTY_PREFIX + 'Origin';

    /// <summary>
    /// Local port being forwarded from
    /// </summary>
    public static readonly SOURCE_PORT = PortForwardingTelemetry.PROPERTY_PREFIX + 'SourcePort';

    /// <summary>
    /// Local server url
    /// </summary>
    public static readonly SERVER_URL = PortForwardingTelemetry.PROPERTY_PREFIX + 'ServerUrl';
}
