import { vsls } from '@vs/vsls-contracts';
import { assert, assertDefined } from '@vs/vscs-utils';

import { LiveShareConnection } from './LiveShareConnection';

export class CodespaceConnection extends LiveShareConnection {
    protected setWorkspaceSessionInfo(workspaceSessionInfo: vsls.WorkspaceSessionInfo) {
        this.trace.verbose(`setWorkspaceSessionInfo`, workspaceSessionInfo);

        const { ownerId, sessionNumber, sessions } = workspaceSessionInfo;

        assertDefined(ownerId, 'No owner id defined.');

        this.trace.info(`ownerId: "${ownerId}"`);

        assert(!ownerId.startsWith('vm_'), 'Session host is not updated to the user, retrying...');

        assertDefined(sessions, 'Workspace sessions not defined.');

        const session = sessions[sessionNumber];
        assertDefined(session, `Session #${sessionNumber} not defined.`);
        assert(session.isOwner, 'Session does not have owner permissions');

        super.setWorkspaceSessionInfo(workspaceSessionInfo);
    }
}
