import { ICommand } from '../abstractions/ICommand';
import { ICommandDecorator } from '../abstractions/ICommandDecorator';
import { ICommandConstructor } from '@vs/vscode-command-framework';
import { MetaProfilingCommandDecorator } from '../decorators/MetaProfilingCommandDecorator';

export class DecoratorHelper {
    public static getCoreCommand(command: ICommand<any>): ICommand<any> {
        const decorator = command as ICommandDecorator;
        if (decorator.next) {
            return DecoratorHelper.getCoreCommand(decorator.next);
        }
        return decorator;
    }

    public static setupDecorator(builder: (n: ICommand<any>) => ICommand<any>) {
        // TODO: Could have a switch here to bypass profiling at in prod if we wanted
        return DecoratorHelper.setupDecoratorInner(
            (command: ICommand<any>) => DecoratorHelper.buildMetaProfilingCommandDecorator(builder(command))
        );
    }

    private static setupDecoratorInner(builder: (n: ICommand<any>) => ICommand<any>) {
        return (original: ICommandConstructor<any>) => {
            const f: any = function (this: any, ...args: any[]) {
                const next = original.name === 'f'
                    // A double cast here is required to make TypeScript happy. Is there a better way to code this?
                    ? <ICommand<any>><unknown>original.apply(this, args)
                    : DecoratorHelper.buildMetaProfilingCommandDecorator(new original(...args));
                return builder(next);
            };
            f.prototype = original.prototype;
            return f;
        };
    }

    private static buildMetaProfilingCommandDecorator(command: ICommand<any>): ICommand<any> {
        return new MetaProfilingCommandDecorator(
            DecoratorHelper.getCoreCommand(command),
            command);
    }
}