'use strict';
import * as vscode from 'vscode';
import { vsls } from '@vs/vsls-contracts';
import { ResponseError } from 'vscode-jsonrpc';
import { RestrictedOperation, RestrictedOperationRejectionReason, BooleanOrError } from './RestrictedOperation';
import { IClientAccessCheck, GuestIdSessionContext } from '../contracts/IClientAccessCheck';

import {
    TelemetryEvent
} from '@vs/vso-telemetry';

import { TelemetryEventNames, TelemetryPropertyNames } from '../telemetry/TelemetryStrings';

export abstract class ClientAccessCheck implements IClientAccessCheck {
    private accessControlChangedEvent: vscode.Disposable;
    protected workspaceAccessControl: vsls.WorkspaceAccessControl;

    constructor(
        protected readonly workspaceAccessControlService: vsls.WorkspaceAccessControlService,
        private hostSessionId: number) {
    }

    public abstract get isReadOnly(): boolean;

    public getContextSessionId(context: GuestIdSessionContext): string | undefined {
        if (context && typeof context === 'object') {
            context = typeof context.GuestSessionId !== 'undefined' ? context.GuestSessionId :
                typeof context.context === 'object' ? context.context.GuestSessionId :
                undefined;
        }

        if (typeof context === 'number') {
            context = context.toString();
        }

        if (typeof context === 'string') {
            return context;
        }
    }

    private isHostSession(sessionId: string): boolean {
        return this.hostSessionId.toString() === sessionId;
    }

    private isHostSessionContext(context: GuestIdSessionContext): boolean {
        return this.isHostSession(this.getContextSessionId(context));
    }

    public async isReadOnlySession(): Promise<boolean> {
        await this.ensureWorkspaceAccessControl();

        const {
            defaultAccessControl = {}
        } = this.workspaceAccessControl;

        return !!defaultAccessControl.isReadOnly;
    }

    public async isClientExplicitlyReadWrite(context: GuestIdSessionContext): Promise<boolean> {
        const sessionId = this.getContextSessionId(context);
        
        if (this.isHostSession(sessionId) || !sessionId) {
            // Host session is never read-only.
            return false;
        }

        await this.ensureWorkspaceAccessControl();

        const {
            defaultAccessControl = {},
            userAccessControl = {}
        } = this.workspaceAccessControl;

        const userSpecificAccessControl = userAccessControl[sessionId];

        if (!userSpecificAccessControl) {
            return false;
        }
        
        // if the workspace is writable but user is readonly
        return (defaultAccessControl.isReadOnly && (!userSpecificAccessControl.isReadOnly));
    }

    public async isClientReadOnly(context: GuestIdSessionContext): Promise<boolean> {
        const sessionId = this.getContextSessionId(context);

        if (this.isHostSession(sessionId) || !sessionId) {
            // Host session is never read-only.
            return false;
        }

        await this.ensureWorkspaceAccessControl();

        const accessControl = this.workspaceAccessControl.userAccessControl[sessionId] || this.workspaceAccessControl.defaultAccessControl || {};
        return !!accessControl.isReadOnly;
    }

    public async canPerformOperation(context: GuestIdSessionContext, operation: RestrictedOperation): Promise<boolean> {
        if (!operation) {
            return true;
        }

        if (operation.ownerOnly && !this.isHostSessionContext(context)) {
            this.sendRejectedOperationTelemetry(operation, RestrictedOperationRejectionReason.RejectedForNotOwner);
            return false;
        }

        if (!operation.enabledInReadOnlySession && await this.isClientReadOnly(context)) {
            this.sendRejectedOperationTelemetry(operation, RestrictedOperationRejectionReason.RejectedInReadOnlySession);
            return false;
        }

        if (operation.isEnabled && operation.isEnabled() !== true) {
            this.sendRejectedOperationTelemetry(operation, RestrictedOperationRejectionReason.DisabledByHost);
            return false;
        }

        return true;
    }

    public async verifyCanPerformOperation(context: GuestIdSessionContext, operation: RestrictedOperation) {
        if (await this.canPerformOperation(context, operation)) {
            return;
        }

        if (operation.ownerOnly && !this.isHostSessionContext(context)) {
            throw new ResponseError(
                vsls.ErrorCodes.OperationRejectedForNotOwner,
                'This operation is not allowed for non owners.');
        }

        if (!operation.enabledInReadOnlySession && await this.isClientReadOnly(context)) {
            throw new ResponseError(
                vsls.ErrorCodes.OperationRejectedInReadOnlySession,
                'This operation is not allowed in read-only collaboration session.');
        }

        if (operation.isEnabled) {
            const error: BooleanOrError = operation.isEnabled();
            if (error && typeof error === 'object') {
                throw new ResponseError(error.errorCode, error.errorMessage);
            }
        }

        throw new ResponseError(vsls.ErrorCodes.OperationRejected, 'Insufficient access rights to perform this operation.');
    }

    public abstract logRejectedOperation(operation: RestrictedOperation, access: vsls.RestrictedOperationAccess): Promise<void>;

    public async init(): Promise<void> {
        await this.initWorkspaceAccessControl();
    }

    public async dispose() {
        this.endCollaboration();
    }

    public endCollaboration() {
        if (this.accessControlChangedEvent) {
            this.accessControlChangedEvent.dispose();
            this.accessControlChangedEvent = undefined;
        }

        this.workspaceAccessControl = undefined;
    }

    protected onWorkspaceAccessControlChanged(e: vsls.WorkspaceAccessControlEventArgs) {
        this.workspaceAccessControl = e.accessControl || {};
        this.workspaceAccessControl.defaultAccessControl = this.workspaceAccessControl.defaultAccessControl || {};
    }

    protected async initWorkspaceAccessControl() {
        try {
            this.workspaceAccessControl = await this.workspaceAccessControlService.getAccessControlAsync() || {};
            this.accessControlChangedEvent = this.workspaceAccessControlService.onAccessControlChanged(this.onWorkspaceAccessControlChanged, this);
        } catch {
            // Legacy host - no workspace access control service
            this.workspaceAccessControl = {
                userAccessControl: {
                }
            };
        }
    }

    /**
     * Ensure the workspace access control is initialized from the remote rpc service.
     */
    protected async ensureWorkspaceAccessControl() {
        if (!this.workspaceAccessControl) {
            await this.initWorkspaceAccessControl();
        }
    }

    private sendRejectedOperationTelemetry(operation: RestrictedOperation, reason: RestrictedOperationRejectionReason) {
        new TelemetryEvent(TelemetryEventNames.REJECT_RESTRICTED_OPERATION)
        .addProperty(TelemetryPropertyNames.OPERATION_NAME, operation.name)
        .addProperty(TelemetryPropertyNames.REJECTION_REASON, reason)
        .send();
    }
}