'use strict';

import { getCellId, localize, NotebookConstants, IPathManager, workspaceSessionInfoTracker } from '@vs/liveshare-core';
import * as vscode from 'vscode';
import { NotebooksService } from './notebooksService';

type ExecutionTaskAndCell = {
    task:  vscode.NotebookCellExecution,
    cell: vscode.NotebookCell
}

export class NotebookController {

    private runningExecutionTasks: Map<string, ExecutionTaskAndCell> = new Map<string, ExecutionTaskAndCell>();
    public label = "Live Share Controller";
    public id = 'LiveShare-Controller';
    public notebookType = '*';
    public description = 'Visual Studio Live Share Controller';
    public detail = localize('notebooks.kernelDetail');
    public controller: vscode.NotebookController;
    public executeHandler = (cells: vscode.NotebookCell[], notebook: vscode.NotebookDocument, controller: vscode.NotebookController) => this.controllerHandler(cells, notebook, controller);

    public constructor (private pathManager: IPathManager, private service: NotebooksService) {}
    
    public createNotebookController(): vscode.NotebookController {

        this.controller = vscode.notebooks?.createNotebookController(
            this.id,
            this.notebookType,
            this.label,
            this.executeHandler
        );

        for (let document of vscode.workspace.notebookDocuments) {
            this.controller.updateNotebookAffinity(document, vscode.NotebookControllerAffinity.Preferred);
        }
        return this.controller;
    }

    public async controllerHandler(cells: vscode.NotebookCell[], notebook: vscode.NotebookDocument, controller: vscode.NotebookController) {

        if (workspaceSessionInfoTracker.isReadOnly) {
            vscode.window.showInformationMessage(localize('notebooks.executeCellsReadOnly'));
            return;
        }

        // Each cell run in a group has its own execution task
        for (var cell of cells) {
            this.startExecutionTask(cell, this.pathManager.localPathToRelativePath(cell.notebook.uri));
        }
        
        if (cells.length !== notebook.cellCount) {
            this.service.executeCellAsync({ start: cells[0].index, end: cells[cells.length - 1].index + 1 }, 
                this.pathManager.localPathToRelativePath(notebook.uri),
                notebook.notebookType.substring(NotebookConstants.mirrorNotebookTypePrefix.length)
            );
        } else { 
            this.service.executeNotebookAsync(this.pathManager.localPathToRelativePath(notebook.uri), notebook.notebookType.substring(NotebookConstants.mirrorNotebookTypePrefix.length));
        }
    }

    public _onDidCancelExecution(e: { range: number, path: string,type: string}) {
        this.service.cancelCellExecutionAsync({ start: e.range, end: e.range + 1 }, e.path, e.type);
    }

    public startExecutionTask(cell: vscode.NotebookCell, path: string) {
        const executionTask = this.controller.createNotebookCellExecution(cell);
        executionTask.token.onCancellationRequested(() => this._onDidCancelExecution ({
            range: cell.index,
            path: path,
            type: cell.notebook.notebookType
        }));
        executionTask.start();
        this.runningExecutionTasks.set(getCellId(cell), { task: executionTask, cell: cell });
    }

    /* When a cell execution object is created, the cell enters the {NotebookCellExecutionState.Pending `Pending`} state.
	 * When {@link NotebookCellExecution.start `start(...)`} is called on the execution task, it enters the {NotebookCellExecutionState.Executing `Executing`} state. When
	 * {NotebookCellExecution.end `end(...)`} is called, it enters the {NotebookCellExecutionState.Idle `Idle`} state.
     */
    public updateExecutionState(cell: vscode.NotebookCell, path: string, state: number, successful?: boolean) {
        
        let executionTask = this.getExecutionTask(getCellId(cell));

        if (executionTask && state == vscode.NotebookCellExecutionState.Executing) {
            return;
        }

        if (!executionTask && state == vscode.NotebookCellExecutionState.Executing) { // host has initiated an execution
            this.startExecutionTask(cell, path);
        }
        if (state === vscode.NotebookCellExecutionState.Executing) {
            try {
                executionTask.start();
            } catch (e) { /* cannot start a cell twice */ }
        } else if (state === vscode.NotebookCellExecutionState.Idle) { //cell is done executing
            let success = successful;
            if (success === undefined) {
                success = false;
            }
            try {
                executionTask.end(success); 
            } catch (e) { /* cannot end a task twice */ }
            this.runningExecutionTasks.delete(getCellId(cell));
       }
       
    }

    public getExecutionTask(cellId: string): vscode.NotebookCellExecution {
        const task = this.runningExecutionTasks.get(cellId)?.task;
        return task;
    }

    public getExecutionCell(cellId: string): vscode.NotebookCell {
        const cell = this.runningExecutionTasks.get(cellId)?.cell;
        return cell;
    }

    public updateOutput(cell: vscode.NotebookCell, outputs: vscode.NotebookCellOutput[]) {
        
        // Create a new execution task because tasks are single-use, we cannot reuse the task from updating execution state
        try {

            let executionTask = this.getExecutionTask(getCellId(cell));
            const useExistingTask = !!executionTask;
            if (!useExistingTask) {
                executionTask = this.controller.createNotebookCellExecution(cell);
                executionTask.start();
            }

            let outputItems: any = [];
            let success = true;

            if (outputs.length === 0) {
                outputItems.push(new vscode.NotebookCellOutputItem(new Uint8Array(), 'text/html'));
            } else {
                for (var item of outputs[0].items) {
                    const array = Object.values(item.data);

                    let uint = new Uint8Array();
                    if (typeof array[1] === "object") {
                        uint = Uint8Array.from(array[1]);
                    }

                    outputItems.push(new vscode.NotebookCellOutputItem(uint, item.mime));

                    if (item.mime === NotebookConstants.notebookErrorMimeType || item.mime === NotebookConstants.notebookStandardErrorMimeType) {
                        success = false;
                    }
                }
            }
            
            executionTask.replaceOutput(new vscode.NotebookCellOutput(outputItems));

            if (!useExistingTask) { // If we used an existing task, an execution state change will end the task later
                executionTask.end(success);
            }

        } catch (e) { /* Cannot create two execution tasks per cell */ }
    }

    public handleExecutionRequests(grantedAccess: boolean) {
        
        if (grantedAccess) {
            for (let task of this.runningExecutionTasks.keys()) {
                const cell = this.runningExecutionTasks.get(task).cell;
                this.service.executeCellAsync({ start: cell.index, end: cell.index + 1 }, 
                    this.pathManager.localPathToRelativePath(cell.notebook.uri),
                    cell.notebook.notebookType.substring(NotebookConstants.mirrorNotebookTypePrefix.length)
                );
            } 
            return;
        }

        for (let task of this.runningExecutionTasks.keys()) {
            try { 
                const execTask = this.runningExecutionTasks.get(task);
                execTask.task.end(false);
                this.runningExecutionTasks.delete(getCellId(execTask.cell));
            } catch (e) { /* Can't end a task twice */ }
        }
    }

    dispose(): void {
        this.controller.dispose();
    }
    
}
