import { ICommandContext } from '@vs/vscode-command-framework';
import {
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { ContactManager } from '../ContactManager';

export function builder(): ICommand<void> {
    return new SignOutPresenceCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.SIGN_OUT_PRESENCE, TelemetryEventNames.SIGN_OUT_PRESENCE_FAULT, 'SignOutPresence', 1)
class SignOutPresenceCommand implements ICommand<void> {

    public async invoke(options: any, context: ICommandContext): Promise<void> {
        await ContactManager.signOut();
    }
}