'use strict';

/**
 * Error raised by argument validation methods.
 */
export class ArgumentError extends Error {
    constructor(message: string, public readonly argumentName: string) {
        super(message);
    }
}

/**
 * Collection of utility methods validating a parameter value.
 */
export class Requires {
    /**
     * Validates the given condition is true. Throws ArgumentError when it's false.
     * @param condition Condition to validate.
     * @param argumentName Name of the argument associated with the condition.
     * @param message Error message
     */
    public static Argument(condition: boolean, argumentName: string, message: string) {
        if (!condition) {
            throw new ArgumentError(message, argumentName);
        }
    }

    /**
     * Validates the given argument value is not null or undefined.
     * @param value Argument value to validate.
     * @param argumentName Name of the argument.
     */
    public static NotNullOrUndefined<T extends {}>(value: T, argumentName: string): T {
        if (!value) {
            throw new ArgumentError('Parameter ' + argumentName + ' is required', argumentName);
        }
        return value;
    }
}