import { AssertionError } from '../../errors';


type TAssertNever = (value: never, errorMesssage: string | Error) => never;

/**
 * Assert to cover the cases that should never happen.
 */
// TODO legomushroom - test this
export const assertNever: TAssertNever = (
    value: never,
    errorMessage: string | Error,
): never => {
    const error = (typeof errorMessage === 'string')
        ? new AssertionError(errorMessage)
        : errorMessage;

    throw error;
};
