import { wait } from '@vs/vscs-utils';

import { ConnectionHub } from '../../connectionHub/ConnectionHub';
import { ConnectionHubRecord } from '../../connectionHub/ConnectionHubRecord';
import { TConnectionClass } from '../../interfaces/TConnectionClass';
import { TVSCodeConnectionMock } from '../connection/VSCodeConnectionMock';
import { IConnectionMock } from './IConnectionMock';

type TConnectionMock = IConnectionMock | TVSCodeConnectionMock;

export class ConnectionHubMock<
    TConstructableConnection extends TConnectionClass<TConnectionMock> = TConnectionClass<
        TConnectionMock
    >,
    TConnection extends InstanceType<TConstructableConnection> = InstanceType<
        TConstructableConnection
    >,
    TOptions extends TConnection['options'] = TConnection['options']
> extends ConnectionHub<TConstructableConnection, TConnection, TOptions> {
    /**
     * Expose the method to calculate the connection id.
     */
    public getConnectionIdMock(options: TOptions): string {
        return this.getConnectionId(options);
    }

    /**
     * Get `ConnectionMock` instantse by `ConnectionMockOptions`.
     */
    public getConnectionMock(options: TOptions): TConnection | undefined {
        const id = this.getConnectionId(options);

        const record = this.connections[id];

        return record ? (record.connection as TConnection) : undefined;
    }

    /**
     * Get `ConnectionMock` record instantse by `ConnectionMockOptions`.
     */
    public getConnectionRecordMock(
        options: TOptions
    ): ConnectionHubRecord<TConnection, TOptions> | undefined {
        const id = this.getConnectionId(options);

        const record = this.connections[id];

        return record as ConnectionHubRecord<TConnection, TOptions> | undefined;
    }

    /**
     * Mock the failure for the `this.createConnection` method.
     */
    public mockCreateConnectionFail = (error: Error, delay = 1) => {
        this.createConnection = async () => {
            await wait(delay);

            throw error;
        };
    };
}
