import { IConsoleLogger } from '../interfaces';
import { LogLevel } from '../interfaces/LogLevel';
import { DebugConsoleLogger } from '../loggers';
import { ConsoleTraceListener } from './ConsoleTraceListener';

/**
 * A trace listener using the `console`.
 */
export class BrowserConsoleTraceListener extends ConsoleTraceListener {
    constructor(
        consoleReference: IConsoleLogger = new DebugConsoleLogger(),
    ) {
        super(consoleReference);
    }

    protected writeEvent(
        source: string,
        logLevel: LogLevel,
        id: number,
        message: string,
        ...args: any[]
    ): void {
        switch (logLevel) {
            case LogLevel.Critical:
            case LogLevel.Error: {
                return this.consoleReference.error(source, message, ...args);
            }

            case LogLevel.Warning: {
                return this.consoleReference.warn(source, message, ...args);
            }

            case LogLevel.Debug: {
                return (this.consoleReference.debug)
                    ? this.consoleReference.debug(source, message, ...args)
                    : this.consoleReference.info(source, message, ...args);
            }

            default: {
                return this.consoleReference.info(source, message, ...args);
            }
        }
    };
};
