import * as vscode from 'vscode';
import { TreeViewItem } from './TreeViewItem';
import { SettingKeys } from '../SettingKeys';
import { Settings } from '../Settings';
import { CommandId } from '../CommandConstants';
import { ViewItem } from '@vs/liveshare-api-contracts';
interface LabelAndLink {
    label: string;
    link: string;
    location: string;
}

export async function getLabelAndLinkTreeViewItems (location: string): Promise<TreeViewItem[]> {
    const labelAndLinks =  Settings.get<LabelAndLink[]>(SettingKeys.remoteLabelAndLinks) || [];
    const treeViewItems: TreeViewItem[] = [];
    // Only show these to users that have at least 5 sessions
    if ((Settings.isInsidersFeatureSet || Settings.isInternalFeatureSet) && Settings.get<number>(SettingKeys.sessionCount) >= 5) { 
        labelAndLinks.filter(x => x.location === location).forEach((x) => {
            treeViewItems.push(
                new TreeViewItem({
                    type: ViewItem.Other,
                    collapsibleState: vscode.TreeItemCollapsibleState.None,
                    label: x.label,
                    command: {
                        title: x.label,
                        command: CommandId.openLink,
                        arguments: [x.link]
                    }
                })
            );
        
        }); 
    }

    return treeViewItems;
}