import * as vscode from 'vscode';
import { ICommandContext } from '@vs/vscode-command-framework';

import { 
    TelemetryEventNames,
    ICommand,
    telemetryCommandDecorator
} from '@vs/liveshare-core';
import { contactProtocol } from '@vs/vsls-contracts';
import { defaultCompareContacts } from '../defaultCompareContacts';
import { ContactManager } from '../ContactManager';
import { ContactsProviderViewlet, ContactTreeExplorerItem } from '../ContactsProviderViewlet';
import { ContactCommandUtilities } from './ContactCommandUtilities';

export function builder(): ICommand<boolean> {
    return new InviteAvailableContactsCommand();
}

@telemetryCommandDecorator(TelemetryEventNames.INVITE_AVAILABLE_CONTACTS, TelemetryEventNames.INVITE_AVAILABLE_CONTACTS_FAULT, 'InviteAvailableContacts', 1)
class InviteAvailableContactsCommand implements ICommand<boolean> {

    public async invoke(item: ContactTreeExplorerItem, context: ICommandContext): Promise<boolean> {
        const availableContacts = ContactManager.getAllAvailableContacts(c => c.contact.status !== contactProtocol.PresenceStatus.Unknown && c.contact.status !== contactProtocol.PresenceStatus.Offline)
        .sort(defaultCompareContacts);

        const items: string[] = availableContacts.map(c => `${c.contact.displayName ? c.contact.displayName : c.contact.id} (${ContactsProviderViewlet.getPresenceStatusName(c)})`);
        const selection: string = await vscode.window.showQuickPick(items, { placeHolder: 'Select a contact to invite:' });
        if (!selection) {
            return;
        }

        const selectedContact = availableContacts[items.indexOf(selection)];
        return await ContactCommandUtilities.inviteHelper(selectedContact);
    }
}