'use strict';

import * as vscode from 'vscode';
import * as semver from 'semver';

export function createTerminalRenderer(name: string): vscode.TerminalRenderer | null {
    // Defer import of 'vscode' package.
    const vscodeModule = require('vscode') as typeof vscode;
    if (semver.gte(semver.coerce(vscodeModule.version)!, '1.37.0')) {
        return new TerminalVirtualProcessAdaptor(name);
    }

    if (vscodeModule.window.createTerminalRenderer) {
        return vscodeModule.window.createTerminalRenderer(name);
    }

    return null;
}

class TerminalVirtualProcessAdaptor implements vscode.TerminalRenderer {
    private readonly acceptInputEmitter: vscode.EventEmitter<string>;
    private readonly changeMaximumDimensionsEmitter: vscode.EventEmitter<vscode.TerminalDimensions>;
    private readonly writeEmitter: vscode.EventEmitter<string>;
    private readonly overrideDimensionsEmitter: vscode.EventEmitter<vscode.TerminalDimensions>;

    private terminalDimensions?: vscode.TerminalDimensions;
    private terminalMaximumDimensions?: vscode.TerminalDimensions;
    private isStarted?: boolean;
    private isOverrideDimensionsFired?: boolean;
    private writeBuffer?: string;

    public constructor(public readonly name: string) {
        // Defer import of 'vscode' package.
        const vscodeModule = require('vscode') as typeof vscode;

        this.acceptInputEmitter = new vscodeModule.EventEmitter<string>();
        this.changeMaximumDimensionsEmitter = new vscodeModule.EventEmitter<
            vscode.TerminalDimensions
        >();
        this.writeEmitter = new vscodeModule.EventEmitter<string>();
        this.overrideDimensionsEmitter = new vscodeModule.EventEmitter<vscode.TerminalDimensions>();

        this.terminal = vscodeModule.window.createTerminal({
            name,
            pty: {
                onDidWrite: this.writeEmitter.event,
                onDidOverrideDimensions: this.overrideDimensionsEmitter.event,
                handleInput: (data: string) => this.acceptInputEmitter.fire(data),
                setDimensions: (dimensions: vscode.TerminalDimensions) =>
                    this.setPtyDimensions(dimensions),
                open: (initialDimensions: vscode.TerminalDimensions) =>
                    this.openPty(initialDimensions),
                close: () => {},
            },
        });
    }

    //#region vscode.TerminalRenderer

    public get dimensions(): vscode.TerminalDimensions {
        return this.terminalDimensions!;
    }

    public set dimensions(value: vscode.TerminalDimensions) {
        if (!value) {
            return;
        }

        if (
            !this.terminalDimensions ||
            this.terminalDimensions.columns !== value.columns ||
            this.terminalDimensions.rows !== value.rows
        ) {
            this.terminalDimensions = value;
            if (this.isStarted) {
                this.isOverrideDimensionsFired = true;
                this.overrideDimensionsEmitter.fire(value);
            }
        }
    }

    public get maximumDimensions(): vscode.TerminalDimensions {
        return this.terminalMaximumDimensions!;
    }

    public readonly terminal: vscode.Terminal;

    public write(text: string): void {
        if (this.isStarted) {
            this.writeEmitter.fire(text);
        } else {
            this.writeBuffer = (this.writeBuffer || '') + text;
        }
    }

    public get onDidAcceptInput(): vscode.Event<string> {
        return this.acceptInputEmitter.event;
    }

    public get onDidChangeMaximumDimensions(): vscode.Event<vscode.TerminalDimensions> {
        return this.changeMaximumDimensionsEmitter.event;
    }

    //#endregion

    private setPtyDimensions(dimensions: vscode.TerminalDimensions): void {
        if (!dimensions) {
            return;
        }

        if (this.terminalDimensions) {
            this.terminalDimensions = {
                columns: Math.min(this.terminalDimensions.columns, dimensions.columns),
                rows: Math.min(this.terminalDimensions.rows, dimensions.rows),
            };
        } else {
            this.terminalDimensions = dimensions;
        }

        this.terminalMaximumDimensions = dimensions;
        this.changeMaximumDimensionsEmitter.fire(dimensions);

        if (
            this.terminalDimensions.columns !== dimensions.columns ||
            this.terminalDimensions.rows !== dimensions.rows
        ) {
            if (!this.isOverrideDimensionsFired) {
                this.isOverrideDimensionsFired = true;
                this.overrideDimensionsEmitter.fire(this.terminalDimensions);
            }
        }
    }

    private openPty(initialDimensions?: vscode.TerminalDimensions): void {
        this.isStarted = true;

        this.setPtyDimensions(initialDimensions!);

        if (this.writeBuffer) {
            this.writeEmitter.fire(this.writeBuffer);
            this.writeBuffer = undefined;
        }
    }
}
