import { ICommand } from '../abstractions/ICommand';
import { ICommandDecoratorCallback } from '../abstractions/ICommandDecorator';
import { TelemetryCommandDecorator } from './TelemetryCommandDecoratorClass';
import { DecoratorHelper } from '../utils/DecoratorHelper';
import { IDependencies } from '../contracts/IDependencies';

export const telemetryCommandDecoratorFactory = (command: ICommand<any>, dependencies: IDependencies, telemetryEventName: string, telemetryFaultEventName: string, telemetryTitle: string, telemetryEventVersion: number, onError?: ICommandDecoratorCallback) => {
    return new TelemetryCommandDecorator(
        DecoratorHelper.getCoreCommand(command),
        command,
        dependencies.workspaceService(),
        dependencies.telemetry(),
        telemetryEventName,
        telemetryFaultEventName,
        telemetryTitle,
        telemetryEventVersion || 1,
        onError
    );
};
