import { assertDefined } from '../asserts/assertDefined';
import { withRetries } from '../withRetries';
import { assert } from '../asserts/assert';

import { IWithRetriesOptions } from '../../interfaces/IWithRetriesOptions';
import { IDisposableClass } from '../../interfaces/IDisposableClass';
import { TAsyncFunction } from '../../interfaces/TAsyncFunction';

/**
 * Method decorator, analog of the `withRetries` util.
 */
// TODO legomushroom - test this
export const withRetriesDecorator = <
    TProp extends TAsyncFunction,
    TTarget extends IDisposableClass,
>(
    options: Partial<IWithRetriesOptions> = {},
) => {
    return (
        target: TTarget,
        propertyName: string,
        propertyDesciptor: TypedPropertyDescriptor<TProp>,
    ): TypedPropertyDescriptor<TProp> => {
        const { value: method } = propertyDesciptor;

        assert(
            method instanceof Function,
            'This decorator works only on methods',
        );

        assertDefined(
            method,
            `The method "${propertyName}" is not defined.`,
        );

        // must be `function` to not loose `this` context
        const result = async function(
            this: TTarget,
            ...args: Parameters<TProp>
        ): Promise<ReturnType<TProp>> {
            return await withRetries(
                async (retry: number) => {
                    return await method.call(this, ...args, retry);
                },
                options,
            );
        };

        propertyDesciptor.value = result as any;

        return propertyDesciptor;
    };
};
